INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(1, 1, 1, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'bismi llāhi r-raḥmāni r-raḥīmi', 'Rahmân ve Rahîm olan Allah''ın adıyla.'),
(1, 2, 1, 1, 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'alḥamdu lillāhi rabbilʿālamīn', 'Hamd, âlemlerin Rabbi Allah''a mahsustur.'),
(1, 3, 1, 1, 'ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'ar-raḥmāni ar-raḥīmi', 'O, Rahmân, Rahîm''dir.'),
(1, 4, 1, 1, 'مَٰلِكِ يَوْمِ ٱلدِّينِ', 'mālik yawm ad-dīn', 'Sahip ve Hakim O, o günün.'),
(1, 5, 1, 1, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'iyyāke naʿbudu wa-iyyāke nastaʿīnu', 'Ancak Sana kulluk ederiz ve ancak Senden yardım dileriz.'),
(1, 6, 1, 1, 'ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 'ihdinā aṣ-ṣirāṭa al-mustaqīm', 'Bizi doğru yola ilet.'),
(1, 7, 1, 1, 'صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ', 'ṣirāṭa l-ladhīna anʿamta ʿalayhim ghayri l-maghḍūbi ʿalayhim walā ḍ-ḍāllīn', 'Kendilerine lütuf ve ihsan buyurduğun kimselerin yoluna. Gazaba uğramışların ve sapmışların yoluna değil.'),
(2, 1, 1, 2, 'الٓمٓ', 'ʾelife, lāme, mīme', 'Elif, Lâm, Mîm.'),
(2, 2, 1, 2, 'ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ', 'dhālika l-kitābu lā rayba fīhi hudan lil-muttaqīn', 'Bu, şüphe olmayan kitaptır. Müttakiler için bir hidayettir.'),
(2, 3, 1, 2, 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'alladhīna yuʾminūna bil-ghaybi wa yuqīmūna ṣ-ṣalāta wa mimmā razaqnāhum yunfiqūna', 'Onlar, gayba inanırlar, namazı dosdoğru kılarlar ve kendilerine verdiğimiz rızıktan yerli yerince harcarlar.'),
(2, 4, 1, 2, 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 'wa-lladhīna yuʾminūna bimā ʾunžila ʾilayka wamā ʾunžila min qablika wa-bi-l-ʾākhirati hum yūqinūna', 'Onlar, sana indirilene ve senden önce indirilene inanırlar; ahirete de kesin olarak inanırlar.'),
(2, 5, 1, 2, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'ʾulāʾika ʿalā hudan mir rabbihim wa-ʾulāʾika humu l-mufliḥūn', 'İşte onlar, Rab''leri tarafından (gelen) bir hidayet üzeredirler ve işte onlar, kurtuluşa erenlerdir.'),
(2, 6, 1, 3, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 'ʾinna lladhīna kafarū sawāʾun ʿalayhim ʾam lam tundhirhum lā yuʾminūn', 'Şüphesiz ki kâfir olanlar için, onları (azap ile) korkutsan da korkutmasan da birdir; inanmazlar.'),
(2, 7, 1, 3, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'khatama allahu ''ala qulubihim wa ''ala sam''ihim wa ''ala absarihim ghishawatun wa lahum ''adhabun ''adhimun', 'Allah onların kalplerini ve kulaklarını mühürlemiştir. Gözlerinde de bir perdelilik vardır. Ve onlar için büyük bir azap vardır.'),
(2, 8, 1, 3, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْءَاخِرِ وَمَا هُم بِمُؤْمِنِينَ', 'wa min an-nāsi man yaqūlu āmannā bi-llāhi wa bi-l-yawmi l-ʾākhiri wa mā hum bi-muʾminīna', 'İnsanlardan kimi de der ki: "Allah''a ve ahiret gününe inandık." Oysa inanmış değillerdir.'),
(2, 9, 1, 3, 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'yukhādiʿūna Allāha wa-lladhīna āmanū wa mā yakhdaʿūna illā anfusahum wa mā yashʿurūna', 'Onlar Allah''ı ve iman edenleri aldatmaya çalışırlar. Oysa onlar ancak kendilerini aldatırlar, ama farkında değillerdir.'),
(2, 10, 1, 3, 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', 'fī qulūbihim maraḍun fazādahumu ʾllāhu maraḍan wa lahum ʿadhābun ʾalīmun bimā kānū yakdhibūna', 'Onların kalplerinde bir hastalık vardır. Allah da onların hastalığını artırmıştır. Söylemekte oldukları yalanlar yüzünden onlara elem dolu bir azap vardır.'),
(2, 11, 1, 3, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', 'wa-ʾidhā qīla lahum lā tufsidū fī l-ʾarḍi qālū ʾinnamā naḥnu muṣliḥūna', 'Onlara, "Yeryüzünde bozgunculuk yapmayın" dendiği zaman, "Biz ancak ıslah edicileriz" derler.'),
(2, 12, 1, 3, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ', 'ʾalā ʾinnahum humu l-mufsidūna wa-lākin lā yašʿurūna', 'Onlar, bozguncuların ta kendileridir, ama anlamazlar.'),
(2, 13, 1, 3, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', 'wa-ʾidhā qīla lahum ʾāminū kamā ʾāmana n-nāsu qālū ʾanūʾminu kamā ʾāmana s-sufahāʾu ʾalā ʾinnahum humu s-sufahāʾu wa-lākin lā yaʿlamūna', 'Onlara, "İnsanların iman ettiği gibi siz de iman edin" dendiğinde, "Biz de, aklı kıtların (veya aptalların) iman ettiği gibi mi iman edeceğiz?" derler. İyi bilin ki, asıl aklı kıtlar kendileridir, ama bunu bilmezler.'),
(2, 14, 1, 3, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', 'wa ʾiḏā laqū ʾallaḏīna ʾāmanū qālū ʾāmannā wa ʾiḏā ḫalaw ʾilā šayāṭīnihim qālū ʾinnā maʿakum ʾinnamā naḥnu mustahziʾūn', 'Onlar, iman edenlerle karşılaştıklarında: "İman ettik" derler. Kendi şeytanlarıyla baş başa kaldıklarında ise: "Biz sizinle beraberiz, biz onlarla alay edenleriz" derler.'),
(2, 15, 1, 3, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'allāhu yastahziʾu bihim wa yamudduhum fī ṭuġyānihim yaʿmahūn', 'Allah onlarla alay eder ve onları kendi azgınlıkları içinde şaşkına çevirir.'),
(2, 16, 1, 3, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', 'ʾūlāʾika lladhīna ʾshtaraū ḍ-ḍalālata bi-l-hudā famā rabiḥat tijāratuhum wamā kānū muh''tadina', 'İşte onlar, hidayeti dalâletle satın alanlardır. Lâkin bu alışverişleri onlara kâr sağlamadığı gibi, doğru yolu da bulamamışlardır.'),
(2, 17, 1, 4, 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَٰتٍ لَّا يُبْصِرُونَ', 'mathaluhum kamathali allathee istawqada naran falammā adāʾat mā ḥawlahū tḥahaba allāhu binūrihim watarakahum fī thulumātin lā yubṣirūn', 'Onların durumu, bir ateş yakan kimsenin durumu gibidir. Ateş çevresini aydınlattığı zaman, Allah onların aydınlığını giderdi ve onları karanlıkta bıraktı. Artık göremezler.'),
(2, 18, 1, 4, 'صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ', 'ṣummun bukmun ʿumyun fa-hum lā yarjiʿūn', 'Onlar, sağır, dilsiz ve kördürler; artık (hakka) dönmezler.'),
(2, 19, 1, 4, 'أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَٰفِرِينَ', 'aw kaṣayyibin min as-samāʾi fīhi ẓulumātun wa-raʿdun wa-barqun yajʿalūna aṣābiʿahum fī ʾāḏānihim mina ṣ-ṣawāʿiqi ḥaḏara l-mawti wa-llāhu muḥīṭun bi-l-kāfirīn', 'Yahut (onların durumu) gökten sağanak halinde inen, içinde karanlıklar, gök gürültüsü ve şimşek bulunan bir sağanak gibidir. Ölüm korkusuyla parmaklarını kulaklarına tıkarlar. Allah kâfirleri çepeçevre kuşatmıştır.'),
(2, 20, 1, 4, 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَٰرِهِمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'Yakādu l-barqu yakhṭafu abṣārahum Kullamā aḍāʾa lahum mashaw fīhi Wa iḏā aẓlama ʿalayhim qāmū Wa law šāʾa ḷḷāhu laḏahaba bisamʿihim wa abṣārihim Inna ḷḷāha ʿalā kulli šayʾin qadīrun', 'Gözleri (görüşlerini) kapıp alacak gibi oluyordu. Ne zaman kendilerine ışık verdi, onunla yürüdüler ve üzerlerine karanlık çökünce durakaldılar. Allah dileseydi, işitme ve görme duyularını elbette giderirdi. Şüphesiz Allah, her şeye hakkıyla gücü yetendir.'),
(2, 21, 1, 4, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'yā ayyuhā n-nāsu ʿbudū rabbakum alladhī khalaqakum wa-lladhīna min qablikum laʿallakum tattaqūn', 'Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize kulluk edin ki, (O''nun azabından) korunasınız.'),
(2, 22, 1, 4, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ', 'alladhī jaʿala lakumu l-arḍa firāshan wa-s-samāʾa banāʾan wa-anzala mina s-samāʾi māʾan fa-akhraja bihi min ath-thamarāti rizqan lakum falā tajʿalū lillāhi andādan wa-antum taʿlamūn', 'O (Allah) ki, yeri sizin için bir döşek, göğü de bir tavan yaptı. Gökten su indirip onunla size çeşitli meyveler (ürünler) çıkardı. Artık siz de (bunları) bile bile Allah’a denk ve ortaklar koşmayın.'),
(2, 23, 1, 4, 'وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'wa-ʾin kuntum fī raybin mimmā nazzalnā ʿalā ʿabdinā fa-ʾtū bisūratin min mithlihī wa-dʿū shuhadāʾakum min dūni ʾllāhi ʾin kuntum ṣādiqīn', 'Eğer kulumuza indirdiğimiz şeyden herhangi bir şüpheda iseniz, haydi onun benzeri bir sure getirin ve eğer doğru sözlüler iseniz, Allah''tan başka şahitlerinizi çağırın.'),
(2, 24, 1, 4, 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ أُعِدَّتْ لِلْكَٰفِرِينَ', 'fa-in lam tafʿalū wa-lan tafʿalū fa-ttaqū an-nāra allatī waqūdūhā an-nāsu wa-l-ḥijāratu uʿiddat lil-kāfirīn', 'Eğer (bu dediklerimizi) yapamazsanız -ki asla yapamayacaksınız- o takdirde, yakıtı insanlar ve taşlar olan, inkârcılar için hazırlanmış ateşten korunun.'),
(2, 25, 1, 5, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَٰلِدُونَ', 'wa bashshiri alladhīna āmanū wa ʿamilū aṣ-ṣāliḥāti anna lahum jannātin tajrī min taḥtihā al-anhāru kullamā ruziqū minhā min thamaratin rizqan qālū hādhā alladhī ruziqnā min qablu wa ūtū bihi mutashābihan wa lahum fīhā azwājun muṭahharatun wa hum fīhā khālidūna', 'İman edip salih amel işleyenlere, kendileri için hazırlanan, altlarından ırmaklar akan cennetlerin olduğunu müjdele. Onlara orada (cennet meyvelerinden) bir rızık verildiğinde, "Daha önce dünyada iken bize verilen rızık budur" derler. Hem (bu meyveler) birbirine benzer şekilde sunulmuştur. Onlar için orada tertemiz eşler de vardır. Ve onlar orada ebedî kalacaklardır.'),
(2, 26, 1, 5, 'إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', 'İnna Allāha lā yestaḥyī an yaḍriba maṯalan mā baʿūḍatan famā fawqahā Faʾammā allaḏīna āmanū fayaʿlamūna annahu al-ḥaqqu min rabbihim Waʾammā allaḏīna kafarū fayaqūlūna māḏā arāda Allāhu bihāḏā maṯalan Yuḍillu bihī kaṯīran wayahdī bihī kaṯīran Wamā yuḍillu bihī illā al-fāsiqīna', 'Şüphesiz Allah, bir sivrisineği, hatta ondan daha üstün bir şeyi misal vermekten çekinmez. İman edenlere gelince, onlar bunun Rablerinden gelen bir hakikat olduğunu bilirler. Kâfirler ise, “Allah bu misalle ne demek istedi?” derler. Allah onunla birçoklarını saptırır, birçoklarını da doğru yola iletir. Onunla ancak fasıkları saptırır.'),
(2, 27, 1, 5, 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'alladhīna yanquḍūna ʿahda allāhi mim baʿdi mīthāqihī wayaqṭaʿūna mā amara allāhu bihi an yūṣala wayufsidūna fī l-arḍi ulāʾika humu l-khāsirūn', 'Onlar, Allah''ın ahdini pekiştirildikten sonra bozarlar, Allah''ın birleştirmesini emrettiği şeyi keserler ve yeryüzünde fesat çıkarırlar. İşte onlar ziyana uğrayanların ta kendileridir.'),
(2, 28, 1, 5, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'kayfa takfurūna bi-llāhi wa kuntum amwātan fa-aḥyākum thumma yumītukum thumma yuḥyīkum thumma ilayhi turjaʿūna', 'Siz Allâh''a nasıl küfredersiniz? Hâlbuki sizler ölü idiniz, O sizi diriltti; sonra sizi yine öldürecek, sonra sizi yine diriltecektir. Nihâyet O''na döndürüleceksiniz.'),
(2, 29, 1, 5, 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'huwa lladhī khalaqa lakum mā fī l-arḍi jamīʿan thumma stawā ilā s-samāʾi fa-sawwāhunna sabʿa samāwātin wa-huwa bikulli shayʾin ʿalīmun', 'Yeryüzündeki her şeyi sizin için yaratan O''dur. Sonra göğe yönelip onu yedi kat gök olarak düzenledi. O, her şeyi bilendir.'),
(2, 30, 1, 6, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', 'wa-ʾiḏ qāla rabbuka lil-malāʾikati ʾinnī jāʿilun fī l-ʾarḍi ḫalīfatan qālū ʾatajʿalu fīhā man yufsidu fīhā wa-yasfiku d-dimāʾa wa-naḥnu nusabbiḥu bi-ḥamdika wa-nuqaddisu laka qāla ʾinnī ʾaʿlamu mā lā taʿlamūna', 'Hani Rabbin meleklere, "Ben yeryüzünde bir halife yaratacağım" demişti. Onlar, "Biz seni överek tesbih eder ve takdis ederken, yeryüzünde bozgunculuk yapacak, orada kan dökecek kimseyi mi yaratacaksın?" dediler. Allah, "Sizin bilmediğinizi ben bilirim" dedi.'),
(2, 31, 1, 6, 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ', 'wa ʿallama ʾādama l-ʾasmāʾa kullahā thumma ʿaraḍahum ʿalā l-malāʾikati faqāla ʾanbiʾūnī bi-ʾasmāʾi hāʾulāʾi ʾin kuntum ṣādiqīna', 'Ve Âdem''e isimlerin hepsini öğretti. Sonra onları meleklere gösterip: ''Eğer (sözünüzde) doğru iseniz, bana şunların isimlerini bildirin'' dedi.'),
(2, 32, 1, 6, 'قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'qālū subḥānaka lā ʿilma lanā ʾillā mā ʿallamtana ʾinnaka ʾanta l-ʿalīmu l-ḥakīm', 'Onlar şöyle dediler: "Seni tenzih ederiz! Senin bize öğrettiğinden başka bilgimiz yoktur. Şüphesiz sen, her şeyi bilen, hikmet sahibi olansın."'),
(2, 33, 1, 6, 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', 'qāla yā ʾādamu ʾanbiʾhum bi-ʾasmāʾihim falammā ʾanbaʾahum bi-ʾasmāʾihim qāla ʾalam ʾaqul lakum ʾinnī ʾaʿlamu ġayba s-samāwāti wal-ʾarḍi wa-ʾaʿlamu mā tubdūna wa-mā kuntum taktūmūna', 'Âdem, onların isimlerini bildirdi. Kendilerine onların isimlerini bildirdiği zaman, Allah şöyle dedi: "Size, göklerin ve yerin gaybini bildiğimi ve sizin açıkladığınız şeyleri ve gizlemekte olduğunuz şeyleri bildiğimi söylememiş miydim?"'),
(2, 34, 1, 6, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 'wa-ʾiḏ qulnā lil-malāʾikati sǧudū li-ʾādama fa-sǧadū ʾillā ʾiblīsa ʾabā wa-stakbara wa-kāna mina l-kāfirīn', 'Hani meleklere, ''Adem''e secde edin'' demiştik. İblis''in dışında hepsi secde etmişti. İblis ise kaçınmış ve kibirlenmişti. Böylece kâfirlerden olmuştu.'),
(2, 35, 1, 6, 'وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 'wa-qulnā yā-ʾādamu s-kun ʾanta wa-zawjukā l-jannata wa-kulā min-hā raghadan ḥaythu shiʾtumā wa-lā taqrabā hādhihi sh-shajarata fa-takūnā mina ẓ-ẓālimīn', 'Ve dedik ki: "Ey Âdem! Sen ve eşin cennete yerleşin ve ikiniz de ondan, istediğiniz yerden bol bol yiyin. Ancak ş şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz."'),
(2, 36, 1, 6, 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'faʾazallahumā ash-shayṭānu ʿanhā faʾakhrajahumā mimmā kānā fīhi waqulnā ihbiṭū baʿḍukum libaʿḍin ʿaduwwun walakum fī al-ʾarḍi mustaqarrun wamatāʿun ʾilā ḥīnin', 'Derken şeytan onları(n ayağını kaydırıp) oradan çıkardı ve biz de: "Birbirinize düşman olarak inin! Sizin için yeryüzünde bir müddete kadar bir yerleşim ve bir geçim (vasıtası) vardır" dedik.'),
(2, 37, 1, 6, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍ فَتَابَ عَلَيْهِ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'fa-talaqqā ʾādamu min rabbihī kalimātin fa-tāba ʿalayhi ʾinnahu huwa t-tawwābu r-raḥīmu', 'Derken Âdem, Rabbinden birtakım kelimeler aldı da ona tövbesini kabul etti. Şüphesiz O, tevbeleri kabul edendir, merhametlidir.'),
(2, 38, 1, 7, 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'qulnā hbiṭū minhā jamīʿan faʾimmā yaʾtiyannakum minnī hudan faman tabiʿa hudāya falā khawfun ʿalayhim walā hum yaḥzanūn', 'Hep birlikte (cennetten) inin! Size benden bir hidayet geldiğinde, kim benim hidayetime uyarsa, onlara korku yoktur ve onlar mahzun da olmayacaklardır.'),
(2, 39, 1, 7, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'wa-lladhīna kafarū wa-kadhdhabū bi-ʾāyātinā ʾulāʾika ʾaṣḥābu n-nāri hum fīhā khālidūna', 'İnkâr edip âyetlerimizi yalanlayanlara gelince, işte onlar cehennem ehlidir. Onlar orada ebedî kalacaklardır.'),
(2, 40, 1, 7, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', 'yā banī ʾisrāʾīl uḏkurū niʿmatīya llatī ʾanʿamtu ʿalaykum wa ʾawfū biʿahdī ʾufi biʿahdikum wa ʾiyyāya fa-rhabūn', 'Ey İsrailoğulları! Size verdiğim nimetlerimi hatırlayın ve bana verdiğiniz sözü (iman ve itaatle) yerine getirin ki ben de size verdiğim sözü (mükâfatı) yerine getireyim. Ve yalnız benden korkun.'),
(2, 41, 1, 7, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', 'wa ʾāminū bimā ʾanzaltu muṣaddiqan limā maʿakum walā takūnū ʾawwala kāfirin bihi walā tashtarū bi-ʾāyātī thamanan qalīlan wa ʾiyyāya fattqūn', 'Benim indirdiğime, yanınızda olanı doğrulayıcı olarak inanın ve onu ilk inkâr edenler olmayın. Benim âyetlerimi az bir değere satmayın ve yalnızca Benden korkun.'),
(2, 42, 1, 7, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 'wa la talbisū al-ḥaqqa bil-bāṭili wa taktumu al-ḥaqqa wa antum taʿlamūna', 'Hakkı batıla karıştırmayın ve hakkı bile bile gizlemeyin.'),
(2, 43, 1, 7, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', 'wa aqīmū ṣ-ṣalāta wa ātū z-zakāta war-kaʿū maʿa r-rākiʿīn', 'Namazı dosdoğru kılın, zekâtı verin ve rükû edenlerle birlikte rükû edin.'),
(2, 44, 1, 7, 'أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ أَفَلَا تَعْقِلُونَ', 'ʾataʾmurūna n-nāsa bil-birri wa tansawna ʾanfusakum wa ʾantum tatlūna l-kitāba ʾaflā taʿqilūna', 'Siz insanlara iyiliği emreder de kendi nefislerinizi unutur musunuz? Oysa siz Kitab''ı okuyorsunuz. Hiç aklınızı kullanmıyor musunuz?'),
(2, 45, 1, 7, 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ', 'wa-staʿīnū bi-ṣ-ṣabri wa-ṣ-ṣalāti wa-innahā la-kabīratun ʾillā ʿalā l-khāshiʿīna', 'Bir de sabırla ve namazla yardım isteyin. Şüphesiz o, iki rekâtı huşû ile kılacak olanlar dışında, elbette zor (ağır)dır.'),
(2, 46, 1, 7, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', 'alladhīna yaẓunnūna ʾannahum mulāqū rabbihim wa-ʾannahum ʾilayhi rājiʿūna', 'Onlar, Rablerine kavuşacaklarını ve O''na döneceklerini umanlardır.'),
(2, 47, 1, 7, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 'yā banī ʾisrāʾīl uḏkurū niʿmetiye ʾelle-ti ʾanʿamtu ʿalaykum wa ʾannī faḍḍaltukum ʿalā l-ʿālamīn', 'Ey İsrailoğulları! Size verdiğim nimetimi ve sizi (diğer) alemlere üstün kıldığımı hatırlayın.'),
(2, 48, 1, 7, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', 'wa-ttaqū yawman lā tajzī nafsun ʿan nafsin shayʾan wa-lā yuqbalu minhā shafāʿatun wa-lā yuʾkhadhu minhā ʿadlun wa-lā hum yunṣarūna', 'Ve öyle bir günden sakının ki, o gün kimse kimsenin yerine bir şey ödeyemez, ondan hiçbir şefaat kabul edilmez, ondan hiçbir fidye alınmaz ve onlara yardım edilmez.'),
(2, 49, 1, 8, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'wa-idh najjaynākum min āl-i firʿawna yasūmūnakum sūʾa l-ʿadhābi yudhabbiḥūna abnāʾakum wa-yastaḥyūna nisāʾakum wa-fī dhālikum balāʾun min rabbikum ʿaẓīmun', 'Hani sizleri, Firavun ailesinden kurtarmıştık. Onlar sizleri kötü azaba uğratıyorlar, erkek çocuklarınızı kesiyorlar, kadınlarınızı ise sağ bırakıyorlardı. İşte bunlarda, Rabbinizden büyük bir imtihan vardı.'),
(2, 50, 1, 8, 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', 'wa-ʾiḏ farqanā bikumu l-baḥra fa-ʾanjaynākum wa-ʾaġraqnā ʾāla firʿawna wa-ʾantum tanẓurūn', 'Hani, (bir zamanlar) denizi sizin için yarmış, sizi kurtarmış ve Firavun''un halkını da siz bakıp dururken boğmuştuk.'),
(2, 51, 1, 8, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 'wa-ʾiḏ wāʿadnā mūsā ʾarbaʿīna laylatan ṯumma ʾittaḵaḏtum al-ʿijla min baʿdihi wa-ʾantum ẓālimūn', 'Hani Mûsâ ile kırk gece (vâde)leşmiştik de, ondan (sonra) zulmedici kimseler olarak buzağıyı (tanrı edinmişti)niz.'),
(2, 52, 1, 8, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 'thumma ʿafavnā ʿankum mim baʿdi dhālika laʿallakum tashkurūn', 'Sonra bunun ardından sizi affettik ki şükredesiniz.'),
(2, 53, 1, 8, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', 'wa-ʾiḏ ʾātaynā Mūsā l-kitāba wa-l-furqāna laʿallakum tahtadūn', 'Hani bir zamanlar Mûsâ''ya Kitab''ı ve (hak ile bâtılı) ayıran Furkan''ı vermiştik ki, doğru yolu bulasınız diye.'),
(2, 54, 1, 8, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'wa ʾiḏ qāla mūsā li-qawmihī yā-qawmi ʾinnakum ẓalamtum ʾanfusakum bi-ttikhāḏikum al-ʿijla fa-tūbū ʾilā bāriʾikum fa-qtalū ʾanfusakum ḏālikum ḫayrun lakum ʿinda bāriʾikum fa-tāba ʿalaykum ʾinnahu huwa at-tawwābu ar-raḥīmu', 'Hani Mûsâ da kavmine şöyle demişti: "Ey kavmim! Şüphesiz siz, buzağıyı (tanrı edinmekle) kendinize zulmettiniz. Bu yüzden, yaratıcınıza tevbe edin, nefislerinizi öldürün. Bu, yaratıcınız katında sizin için daha hayırlıdır." Sonra Allah sizin tevbenizi kabul etti. Şüphesiz O, tevbeleri kabul edendir, çok merhamet edendir.'),
(2, 55, 1, 8, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', 'wa-ʾiḏ ḳultum yā mūsā lan nuʾmina laka ḥattā narā llāha ǧahratan fa-ʾaḵaḏatkum aṣ-ṣāʿiqatu wa-ʾantum tanẓurūna', 'Hani siz: "Ey Musa! Biz Allah''ı apaçık görmedikçe sana inanmayız" demiştiniz de, bakmakta olduğunuz halde sizi yıldırım çarpmıştı.'),
(2, 56, 1, 8, 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'thumma baʿathnākum min baʿdi mawtimkum laʿallakum tashkurūn', 'Sonra, şükretmeniz için, ölümünüzden sonra sizi tekrar dirilttik.'),
(2, 57, 1, 8, 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'waẓallalnā ʿalaykumu l-ghamāma wa ʾanzalnā ʿalaykumu l-manna wa-s-salwā kulū min ṭayyibāti mā razaqnākum wa mā ẓalamūnā wa lākin kānū ʾanfusahum yaẓlimūn', 'Ve üzerinize bulutları gölge yaptık ve size kudret helvası ile bıldırcın indirdik. (Ve buyurduk ki:) ''Size rızık olarak verdiklerimizin temiz olanlarından yiyin.'' (Onlar emrimize karşı gelmekle) bize zulmetmediler, fakat kendilerine zulmettiler.'),
(2, 58, 1, 9, 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', 'wa-idh qulnā dkhulū hādhihi l-qaryata fakulū minhā ḥaythu shiʾtum raghadan wa-dkhulū l-bāba sujaddan wa-qūlū ḥiṭṭatun naghfir lakum khaṭāyākum wa-sanazīdu l-muḥsinīna', 'Hani, demiştik ki: ''Bu şehre girin, orada dilediğiniz yerden bol bol yiyin. Kapıdan secde ederek girin ve ''Hıtta'' deyin ki, günahlarınızı bağışlayalım. İyilik edenlerin sevabını da artıracağız.'''),
(2, 59, 1, 9, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'fe beddelelleźîne zalemû kavlen gayralleźî qîle lehum fe enzelnâ ''alelleźîne zalemû riczen mines-semâ''i bimâ kânû yefsuqûn', 'Ancak onlardan zalim olanlar, kendilerine söylenenden başka bir söz ile değiştirdiler. Bu yüzden, fasıklık yapmalarından dolayı, zalimlerin üzerine gökten bir azap indirdik.'),
(2, 60, 1, 9, 'وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'wa-ʾiḏi-stsqā mūsā li-qawmihī fa-qulnā-ḍrib bi-ʿaṣāka l-ḥajara fa-nfaǧarat minhu ʾiṯnatā ʿašrata ʿaynan qad ʿalima kullu ʾunāsin mašrabehum kulū wa-šrabū min rizqi llāhi wa-lā taʿṯaw fī l-ʾarḍi mufsidīn', 'Hani Mûsâ da, kavmi için su dilemişti. Biz de ona: "Asânı taşa vur!" demiştik. Bunun üzerine taştan on iki pınar fışkırmış, her kabile kendi su alacağı yeri bilmişti. Allah''ın rızkından yiyin, için. Yeryüzünde bozgunculuk yaparak fesat çıkarmayın.'),
(2, 61, 1, 9, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'wa-ʾiḏ ḳultum yā-mūsā lan naṣbira ʿalā ṭaʿāmin wāḥidin fa-dʿu lanā rabbaka yukhriju lanā mimmā tunbitu l-ʾarḍu min baḳlihā wa-ḳiṯṯāʾihā wa-fūmihā wa-ʿadasihā wa-baṣalihā ḳāla ʾatastabdilūna l-laḏī huwa ʾadnā bil-laḏī huwa ḫayrun uhbiṭū miṣran fa-ʾinna lakum mā saʾaltum wa-ḍuribat ʿalayhimu ẓ-ẓilatu wal-maskanatu wa-bāʾū bi-ġaḍabin mina l-lāhi ḏālika bi-ʾannahum kānū yakfurūna bi-ʾāyāti l-lāhi wa-yaqtulūna n-nabiyyīna bi-ġayri l-ḥaqqi ḏālika bimā ʿaṣaw wa-kānū yaʿtadūna', 'Hani siz, "Ey Musa! Biz tek çeşit yemeğe asla sabredemeyiz. O halde, bizim için Rabbine dua et de toprağın bitirdiklerinden; sebzelerinden, hıyarından, sarımsağından, mercimeğinden, soğanından bize çıkarsın" demiştiniz. Musa da, "(Bunu) daha iyi olanla mı değiştirmek istiyorsunuz? Öyleyse (bir şehre) inin, şüphesiz istediğiniz (her şey) orada sizin içindir" demişti. Onların üzerine horlanma ve yoksulluk damgası vuruldu. Allah''tan bir gazaba uğradılar. Bu, onların Allah''ın âyetlerini inkâr etmeleri ve peygamberleri haksız yere öldürmeleri yüzündendi. Bu, isyan etmeleri ve haddi aşmaları yüzündendi.'),
(2, 62, 1, 10, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ʾinna lladhīna ʾāmanū wa-lladhīna hādū wa-n-naṣārā wa-ṣ-ṣābiʾīna man ʾāmana bi-llāhi wa-l-yawmi l-ʾākhiri wa-ʿamila ṣāliḥan fa-lahum ʾajruhum ʿinda rabbihim wa-lā khawfun ʿalayhim wa-lā hum yaḥzanūna', 'Şüphesiz iman edenler, Yahudiler, Hristiyanlar ve Sabiîlerden kim Allah''a ve ahiret gününe inanıp salih amel işlerse, Rableri katında onlara mükâfatları vardır. Onlar için korku yoktur ve onlar mahzun da olmayacaklardır.'),
(2, 63, 1, 10, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'wa-idh akhadhna mithāqakum wa-rafaʿnā fawqakumu ṭ-ṭūra khudhū mā ātaynākum bi-quwwatin wa-dhkurū mā fīhi laʿallakum tattaqūna', 'Hani sizden mîsak (kesin söz) almış ve üstünüze Tûr dağını kaldırmıştık. (Ve demiştik ki:) "Size verdiğimize kuvvetle sarılın ve içinde olanları hatırlayın ki, takvâya eresiniz."'),
(2, 64, 1, 10, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ', 'thumma tawallaytum min baʿdi dhālika falawlā faḍlu Allāhi ʿalaykum wa-raḥmatuhu lakuntum mina l-khāsirīn', 'Sonra bunun ardından yüz çevirdiniz. Eğer üzerinizde Allah''ın lütuf ve merhameti olmasaydı, elbette hüsrana uğrayanlardan olurdunuz.'),
(2, 65, 1, 10, 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 'Ve lekad ''alimtumullezîne''tedev minkum fîs-sebti Fekulnâ lehum kûnû kıradeten hâsi''în', 'Andolsun, içinizden Cumartesi (yasağı) konusunda haddi aşanları bildiniz. Biz de onlara: "Aşağılık maymunlar olun!" dedik.'),
(2, 66, 1, 10, 'فَجَعَلْنَٰهَا نَكَٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'fa jaʿalnāhā nakālan limā bayna yadayhā wa mā khalfahā wa mawʿiẓatan lil-muttaqīn', 'Böylece, hem önlerindekine hem de arkalarındakine bir ibret ve takva sahipleri için de bir öğüt kıldık.'),
(2, 67, 1, 10, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ', 'wa-ʾiḏ qāla mūsā li-qawmihi ʾinna-llāha yaʾmurukum ʾan taḏbaḥū baqaratan qālū ʾa-tattaḵiḏunā huzuʾan qāla ʾaʿūḏu bi-llāhi ʾan ʾakūna mina-l-jāhilīn', 'Hani Mûsâ, kavmine demişti ki: "Allah, bir sığır kesmenizi emrediyor." Onlar: "Bizi alay konusu mu ediniyorsun?" dediler. Mûsâ: "Cahillerden olmaktan Allah''a sığınırım" dedi.'),
(2, 68, 1, 10, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', 'qālū ʾdʿu lanā rabbaka yubayyin lanā mā hiya qāla ʾinnahuu yaqūlu ʾinnahā baqaratun lā fāriḍun walā bikrun ʿawānun bayna dhālika fāʿalū mā tuʾmarūn', 'Dediler ki: ''Bizim için Rabbine dua et de bize onun ne olduğunu açıklasın.'' (Musa) ''Şüphesiz O, ''Onun ne yaşlı ne de bakir, ikisinin ortası bir sığır olmasını buyuruyor'' dedi. ''Haydi emrolunduğunuz şeyi yapın.'''),
(2, 69, 1, 10, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', 'qālū udʿu lanā rabbaka yubayyin lanā mā lawnuhā qāla ʾinnahuۥ yaqūlu ʾinnahā baqaratun ṣafrāʾu fāqiʿun lawnuhā tasurru ʾn-nāẓirīn', 'Dediler ki: ''Bizim için Rabbine dua et de onun rengini bize açıklasın.'' (Musa) dedi ki: ''Şüphesiz O, ''Onun rengi, bakanların hoşuna giden parlak sarı bir sığır olmalı'' diyor.'''),
(2, 70, 1, 11, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', 'qālū udʿu lanā rabbaka yubayyin lanā mā hiya inna l-baqara tatashābaha ʿalaynā wa-innā in shāʾa llāhu la-muhtadūna', 'Dediler ki: ''Rabbine dua et de bize onun ne olduğunu açıklasın. Çünkü bize (bu) dana (çasının rengi) şüpheli geldi. Ve biz, Allah dilerse, doğru yolu bulacağız.'''),
(2, 71, 1, 11, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', 'qāla ʾinnahu yqūlu ʾinnahā baqaratun lā ḏalūlun tuʾṯīru l-ʾarḍa walā tasqī l-ḥarṯa musallamatun lā šiyata fīhā qālū l-ʾāna jiʾta bil-ḥaqqi faḏabaḥūhā wamā kādū yafʿalūn', 'Musa şöyle dedi: "Doğrusu o, toprağı sürmeyen ve ekinleri sulamayan, kusursuz, alacası olmayan bir sığırdır." Dediler ki: "İşte şimdi gerçeği getirdin." Bunun üzerine onu kestiler, az kalsın yapmayacaklardı.'),
(2, 72, 1, 11, 'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', 'wa-ʾidh qataltum nafsan fa-ddāraʾtum fīhā wa-llāhu mukhricum mā kuntum taktumūn', 'Hani bir cana kıymıştınız da, onun (katili) hakkında birbirinizle atışmıştınız. Oysa Allah, gizlemekte olduğunuzu açığa çıkarıcıdır.'),
(2, 73, 1, 11, 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'faqulnā ḍribūhu bibaʿḍihā kadhālika yuḥyī ٱllāhu l-mawtā wa yurīkum ʾāyātihi laʿallakum taʿqilūn', 'Bunun üzerine: ''Onun bir parçasıyla ona vurun'' dedik. İşte Allah ölüleri böyle diriltir ve akledesiniz diye size ayetlerini gösterir.'),
(2, 74, 1, 11, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'thumma qasat qulūbukum mim baʿdi dhālika fahiya kalḥijārati aw ashadd qaswatan wa-inna minal ḥijārati lamā yatafajjaru minhu l-anhāru wa-inna minhā lamā yashaqqaqu fa-yakhruju minhu l-māʾu wa-inna minhā lamā yahbiṭu min khashyati llāhi wa-mā llāhu bighāfilin ʿammā taʿmalūna', 'Sonra bütün bunlardan sonra kalpleriniz yine katılaştı; öyle ki, taş gibi, hatta daha katı. Çünkü taşlardan öylesi vardır ki, içinden ırmaklar fışkırır. Öylesi de vardır ki, çatlar da suyunu çıkarır. Bir de taşlardan öylesi vardır ki, Allah korkusuyla aşağıya yuvarlanır. Allah ise yaptıklarınızdan gafil değildir.'),
(2, 75, 1, 11, 'أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', 'ʾafataṭmaʿūna ʾan yuʾminū lakum waqad kāna farīqun minhum yasmaʿūna kalāma ʾllāhi ṯumma yuḥarrifūnahū mim baʿdi mā ʿaqalūhu wahum yaʿlamūna', 'Onların size inanacağını umuyor musunuz? Oysa onlardan bir grup, Allah''ın kelamını işitir, sonra da onu anladıkları halde bile bile tahrif ederlerdi.'),
(2, 76, 1, 11, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ أَفَلَا تَعْقِلُونَ', 'wa-idhā laqū alladhīna āmanū qālū āmannā wa-idhā khalā baʿḍuhum ilā baʿḍin qālū atuḥaddithūnahum bimā fataḥa allāhu ʿalaykum liyuḥājjūkum bihi ʿinda rabbikum ʾaflā taʿqilūn', 'Onlar, iman edenlerle karşılaştıklarında: "İman ettik" derler. Kendi şeytanlarıyla baş başa kaldıklarında ise: "Şüphesiz biz sizinle beraberiz, biz onlarla alay ediyoruz (sadece)" derler.'),
(2, 77, 1, 12, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'ʾawallā yaʿlamūn ʾanna ʾallāha yaʿlamu mā yusirrun wamā yuʿlinūn', 'Onlar, Allah''ın, gizlediklerini de açıkladıklarını da bildiğini bilmiyorlar mı?'),
(2, 78, 1, 12, 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', 'wa-minhum ummiyyūna lā yaʿlamūna l-kitāba illā amāniyya wa-in hum illā yaẓunnūna', 'Onlardan bir de ümmiler vardır ki, Kitab’ı (Tevrat’ı) okuyup yazmayı bilmezler. Onlar sadece birtakım kuruntulara sahiptirler ve sadece zannederler.'),
(2, 79, 1, 12, 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', 'fa-waylun lilladhīna yaktubūna l-kitāba bi-aydīhim thumma yaqūlūna hādhā min ʿindi llāhi li-yashtarū bihi thamanan qalīlan fa-waylun lahum mimmā katabat aydīhim wa-waylun lahum mimmā yaksibūna', 'Nihayet kendi elleriyle kitap yazıp sonra da onu biraz değer elde etmek için "Bu Allah katındandır" diyenlerin vay haline! Kendi elleriyle yazdıkları yüzünden vay onların haline! Ve yine kendi kazandıkları yüzünden vay onların haline!'),
(2, 80, 1, 12, 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'wa qālū lan tamassanā an-nāru illā ayyāman maʿdūdah qul ʾattakhaḏtum ʿinda Allāhi ʿahdan fa-lan yuhlīfa Allāhu ʿahdahū ʾam taqūlūna ʿalā Allāhi mā lā taʿlamūn', 'Onlar: "Bize sayılı günlerden başka asla ateş dokunmayacaktır" dediler. De ki: "Siz Allah katından bir ahid mi aldınız? Eğer öyleyse, Allah ahdini asla bozmaz. Yoksa Allah''a karşı bilmediğiniz şeyleri mi söylüyorsunuz?"'),
(2, 81, 1, 12, 'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'balā man kasaba sayyiʾatan waʾaḥāṭat bihi ḫaṭīʾatuhu faʾulāʾika ʾaṣḥābu n-nār hum fīhā ḫālidūn', 'Hayır! Kim bir kötülük kazanır ve onu günahları kuşatırsa, işte onlar ateşin halkıdır; onlar orada ebedî kalırlar.'),
(2, 82, 1, 12, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti ʾulāʾika ʾaṣḥābu l-jannati hum fīhā khālidūna', 'İman edip salih amel işleyenler var ya, işte onlar cennet ehlidirler. Onlar orada ebedî kalırlar.'),
(2, 83, 1, 12, 'وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', 'wa-ʾiḏ ʾaḵaḏnā mīṯāqa banī ʾisrāʾīla lā taʿbudūna ʾillā ʾallāha wa-bi-l-wālidayni ʾiḥsānan wa-ḏī l-qurbā wa-l-yatāmā wa-l-masākīni wa-qūlū li-n-nāsi ḥusnan wa-ʾaqīmū ṣ-ṣalāta wa-ʾātū z-zakāta ṯumma tawallaytum ʾillā qalīlan mimm-kum wa-ʾantum muʿriḍūna', 'Hani, İsrailoğullarından şöylece mîsâk (söz) almıştık: Allah''tan başkasına kulluk etmeyeceksiniz. Anne-babaya, yakın akrabaya, yetimlere, yoksullara iyilik edeceksiniz. İnsanlara güzel söz söyleyeceksiniz. Namazı dosdoğru kılacaksınız, zekâtı vereceksiniz. Ama sizden azı müstesnâ, (sözlerinizde) döndünüz ve siz yüz çevirenler oldunuz.'),
(2, 84, 1, 13, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', 'wa-ʾiḏ ʾaḵaḏnā mīṯāqa-kum lā tasfikūna dimāʾa-kum wa-lā tuḵrijūna ʾanfusa-kum min diyāri-kum ṯumma ʾaqrartum wa-ʾantum tašhadūn', 'Hani sizden, birbirinizin kanlarını dökmeyeceğinize, birbirinizi yurtlarınızdan çıkarmayacağınıza dair kesin söz almıştık. Sonra siz de ikrar etmiştiniz ve buna şahit olmuşsunuzdur.'),
(2, 85, 1, 13, 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'thumma antum hāʾulāʾi taqtulūna anfusakum wa tukhrijūna farīqan minkum min diyārihim taẓāharūna ʿalayhim bil-ithmi wal-ʿudwāni wa in yaʾtūkum usārā tufādūhum wa huwa muḥarramun ʿalaykum ikhrājuhum a fa-tuʾminūna bi-baʿḍi l-kitābi wa takfurūna bi-baʿḍin fa mā jazāʾu man yafʿalu dhālika minkum illā khizyun fī l-ḥayāti d-dunyā wa yawma l-qiyāmati yuraddūna ilā ashaddi l-ʿadhābi wa mā ʾallāhu bi-ghāfilin ʿammā taʿmalūna', 'Sonra siz, yine sizler birbirinizi öldüren ve içinizden bir kısmını yurtlarından süren kimselersiniz. Onlara karşı günah ve düşmanlıkta birbirinize yardım ediyorsunuz. Eğer onlar size esir olarak gelselerdi, fidye verip kurtaracaktınız. Halbuki onları (sürgün etmek) size haram kılınmıştı. Kitabın bir kısmına inanıp da bir kısmını inkâr mı ediyorsunuz? Sizden böyle yapanların dünya hayatındaki cezası, ancak rezil olmaktır. Kıyamet gününde ise azabın en şiddetlisine atılırlar. Allah, yaptıklarınızdan gafil değildir.'),
(2, 86, 1, 13, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْءَاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', 'ʾūlāʾika lladhīna ʾshtirawū l-ḥayāta d-dunyā bi-l-ʾākhirati falā yukhaffafu ʿanhumu l-ʿadhābu walā hum yunṣarūna', 'İşte onlar, ahireti verip dünya hayatını satın alanlardır. Onların azabı hafifletilmez ve onlara yardım da edilmez.'),
(2, 87, 1, 13, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ', 've leḳad āteynā mūsā el-kitābe ve ḳaffeynā mim baʿdihī bi-er-rusuli ve āteynā ʿīsā ebne meryeme el-beyyināti ve eyyednāhu bi-rūḥi el-ḳudusi e fe-kullamā jāʾekum rasūlun bimā lā tehvā en-fusukumu is-tekbertum fe-ferīḳan keẕẕebtum ve ferīḳan taḳtulūne', 'Andolsun ki Musa''ya Kitab''ı verdik ve ondan sonra ardı ardına peygamberler gönderdik. Meryem oğlu İsa''ya da apaçık deliller verdik ve onu Ruhu''l-Kudüs ile destekledik. Ne zaman size nefislerinizin hoşlanmadığı bir şeyle bir peygamber gelse büyüklük tasladınız. Kimini yalanladınız, kimini de öldürüyorsunuz.'),
(2, 88, 1, 13, 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ', 'wa qālū qulūbunā ġulfun bal laʿanahumu ʾllāhu bikufrihim fa qalīlan mā yuʾminūn', 'Ve dediler ki: Kalplerimiz perdelidir. Hayır, küfretmeleri yüzünden Allah onları lanetlemiştir. Bu yüzden çok az inanırlar.'),
(2, 89, 1, 14, 'وَلَمَّا جَآءَهُمْ كِتَٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ', 'wa lammā jāʾahum kitābun min ʿindi llāhi muṣaddiqun limā maʿahum wa kānū min qablu yastaftiḥūna ʿalā lladhīna kafarū fa lammā jāʾahum mā ʿarafū kafarū bihi fa laʿnatu llāhi ʿalā l-kāfirīn', 'Onlara, yanlarındakini doğrulayan Allah katından bir kitap gelince -oysa daha önce kendileri o kitapla kâfirler üzerine zafer kazanmak istiyorlardı- bildikleri (hak) onlara gelince onu inkâr ettiler. Allah''ın lâneti kâfirleredir.'),
(2, 90, 1, 14, 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'biʾsamā ʾštaraw bihi ʾnfusahum ʾan yakfurū bimā ʾnzala ʾllāhu bagyan ʾan yunazzila ʾllāhu min faḍlihi ʿalā man yashāʾu min ʿibādihi fabāʾū bigaḍabin ʿalā gaḍab walilkāfirīna ʿaḏābun muhīnun', 'Allah''ın indirdiğini inkâr etmek suretiyle, karşılığında kendilerini sattıkları şey ne kötüdür! Kendilerine indirilene inanmayıp, Allah''ın lütfundan dilediğine, kullarından dilediğine indirmesine haset ederek inkâr etmeleri yüzünden hem bir gazap üstüne gazap biriktirdiler. Kâfirler için de alçaltıcı bir azap vardır.'),
(2, 91, 1, 14, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', 'wa-ʾidhā qīla lahum ʾāminū bimā ʾanzala ʾllāhu qālū nuʾminu bimā ʾunzilla ʿalaynā wa-yakfurūna bimā warāʾahu wa-huwa l-ḥaqqu muṣaddiqan limā maʿahum qul fa-lima taqtulūna ʾanbiyāʾa ʾllāhi min qablu ʾin kuntum muʾminīn', 'Onlara, "Allah''ın indirdiğine inanın" dendiği zaman, "Biz sadece bize indirilene inanırız" derler ve ondan başkasını inkâr ederler. Oysa o, yanlarındakini doğrulayan bir hak olarak gelmiştir. De ki: "Eğer inanmış idiyseniz, daha önce Allah''ın peygamberlerini niçin öldürdünüz?"'),
(2, 92, 1, 14, 'وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 'Ve lekad câekum Mûsâ bilbeyyinâti summettehaztumul ıcle min ba''dihî Ve entum zâlimûn(zâlimûne)', 'Andolsun ki Musa size apaçık delillerle gelmişti de, ardından siz buzağıyı (ilah) edinmiştiniz. Sizler zalimlersiniz.'),
(2, 93, 1, 14, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'wa-ʾiḏ ʾaḵaḏnā mīṯāqakum wa-rafaʿnā fawqakumu ṭ-ṭūra ḵuḏū mā ʾātaynākum bi-quwwatin wa-smaʿū qālū samiʿnā wa-ʿaṣaynā wa-ʾušribū fī qulūbihimu l-ʿijla bi-kufrihim qul biʾsamā yaʾmurukum bihi ʾīmānukum ʾin kuntum muʾminīn', 'Hani sizden kesin söz almış ve Tûr dağını üzerinize kaldırmıştık. "Size verdiğimizi kuvvetle tutun ve dinleyin!" demiştik. "Dinledik ve isyan ettik" demişlerdi. Onların küfürleri yüzünden kalplerine buzağı sevgisi içirilmişti. De ki: "İnanıyorsanız, imanınız size ne kötü şey emrediyor!"'),
(2, 94, 1, 15, 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْءَاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'qul in kānat lakumu d-dāru l-ʾākhiratu ʿinda llāhi khāliṣatan min dūni n-nāsi fatamannaw al-mawta in kuntum ṣādiqīn', 'De ki: "Allah katında (ebedî) yurt, başka insanlar değil de, yalnız size ait ise, haydi dürüstseniz ölümü temenni edin!"'),
(2, 95, 1, 15, 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'wa lan yatamannawhu abadan bimā qaddamat aydīhim wallāhu ʿalīmun biẓ-ẓālimīn', 'Onlar, daha önce kendi elleriyle yaptıkları yüzünden ölümü asla temenni etmezler. Allah zalimleri çok iyi bilendir.'),
(2, 96, 1, 15, 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'wa-latadjidannahum aḥraṣa n-nāsi ʿalā ḥayātin wa-mina lladīna ashrakū yawaddu aḥaduhum law yuʿammara alfa sanatin wa-mā huwa bi-muzḥziḥihi mina l-ʿadhābi an yuʿammara wa-llāhu baṣīrun bimā yaʿmalūna', 'Onları, hayata karşı insanların en düşkünü olarak bulursun. Hatta müşriklerden bile (daha düşkündürler). Onlardan her biri, bin yıl yaşamayı arzu eder. Oysa uzun yaşamak onu azaptan kurtaracak değildir. Allah, onların yapmakta olduklarını hakkıyla görmektedir.'),
(2, 97, 1, 15, 'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'qul man kāna ʿaduwwan li-jibrīla fa-ʾinnahuu nazzalahuu ʿalā qalbika bi-ʾidhnillāhi muṣaddiqan limā bayna yadayhi wa-hudan wa-bushrā lil-muʾminīn', 'De ki: Kim Cebrail''e düşman ise, şunu bilmelidir ki, o, Allah''ın izniyle Kur''an''ı senin kalbine indirmiştir; bu, önündekileri doğrulayan, müminlere bir hidayet ve müjdeleyici bir kitaptır.'),
(2, 98, 1, 15, 'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَٰفِرِينَ', 'man kāna ʿaduwwan lillāhi wa-malāʾikatihi wa-rusulihi wa-jibrīla wa-mīkāla fa-inna ʾllāha ʿaduwwun lill-kāfirīn', 'Kim Allah''a, meleklerine, peygamberlerine, Cebrail''e ve Mikail''e düşman olursa, bilsin ki Allah da inkârcı kâfirlerin düşmanıdır.'),
(2, 99, 1, 15, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ', 'Ve lekad enzelnâ ileyke âyâtin beyyinâtin Ve mâ yekfuru bihâ illâl fâsikûn(fâsikûne)', 'Andolsun ki sana apaçık ayetler indirdik. Onları ancak fasıklar inkar eder.'),
(2, 100, 1, 15, 'أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', 'ʾa-wa-kullamā ʿāhadū ʿahdan nabadahu fariqun minhum bal ʾaktharuhum lā yuʾminūn', 'Onlar ne zaman bir ahidle anlaştılar, içlerinden bir topluluk onu bozmadı mı? Hatta onların çoğu iman etmez.'),
(2, 101, 1, 15, 'وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', 'wa lammā jāʾahum rasūlun min ʿindi llāhi muṣaddiqun limā maʿahum nabadha farīqun mina lladhīna ʾūtū l-kitāba kitāba llāhi warāʾa ẓuhūrihim kaʾannahum lā yaʿlamūn', 'Allah katından kendilerine gelen, yanlarındakini doğrulayan bir elçi gelince, Kitap verilenlerden bir grup, sanki hiçbir şey bilmiyorlarmış gibi Allah''ın kitabını arkalarına attılar.'),
(2, 102, 1, 16, 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُوا۟ يَعْلَمُونَ', 'wa-ttabaʿū mā tatlū ash-shayāṭīnu ʿalā mulki Sulaymāna wa-mā kafara Sulaymānu wa-lākinna ash-shayāṭīna kafarū yuʿallimūna an-nāsa as-siḥra wa-mā unzila ʿalā al-malakayni bi-Bābila Hārūta wa-Mārūta wa-mā yuʿallimāni min aḥadin ḥattā yaqūlā innamā naḥnu fitnatun fa-lā takfur fa-yataʿallamūna minhumā mā yufarriqūna bihi bayna al-marʾi wa-zawjihi wa-mā hum bi-ḍārrīna bihi min aḥadin illā bi-idhni Allāhi wa-yataʿallamūna mā yaḍurruhum wa-lā yanfaʿuhum wa-laqad ʿalimū li-mani istarāhu mā lahu fī al-ʾākhirati min khalāqin wa-la-biʾsa mā sharaw bihi anfusahum law kānū yaʿlamūna', 'Ve Süleyman''ın mülkü (saltanatı) aleyhine şeytanların okuyup uydurduğu şeye uydular. Süleyman kâfir olmadı, lâkin şeytanlar kâfir oldular. Onlar, Bâbil''deki iki meleğe: Hârut ile Mârut''a indirilmiş olanı (sihri) öğretiyorlardı. Halbuki o ikisi: Biz ancak bir fitneyiz, sen kâfir olma! demedikçe hiç kimseye (sihri) öğretmezlerdi. Derken onlardan (o iki melekten) kişi ile zevcesini arasını ayıracak şeyleri öğreniyorlardı. Allah''ın izni olmadıkça onlarla kimseye zarar verecek değillerdi. Ve gerçekten onlar, kendilerine zarar verecek ve fayda vermeyecek şeyi öğreniyorlardı. Ve andolsun ki, onu (sihri) satın alan kimsenin âhirette hiçbir nasibi olmadığını bildiler. Velev ki, nefislerini neye sattıklarını bilselerdi, gerçekten ne kötü bir şeydi o!'),
(2, 103, 1, 16, 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ لَّوْ كَانُوا۟ يَعْلَمُونَ', 'wa-law annahum āmanū wa-ttaqaw la-mathūbatun min ʿindi-llāhi khayrun law kānū yaʿlamūn', 'Onlar iman edip de takva sahibi olsalardı, Allah katından bir sevap elbette daha hayırlı olurdu. Keşke bilmiş olsalardı.'),
(2, 104, 1, 16, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', 'yā ayyuhā alladhīna āmānū lā taqūlū rāʿinā wa qūlū unẓurnā wa s-maʿū wa lil-kāfirīna ʿadhābun alīmun', 'Ey iman edenler! Râinâ demeyin, unzurnâ deyin ve dinleyin. Kâfirler için de elem dolu bir azap vardır.'),
(2, 105, 1, 16, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'mā yawaddu l-ladhīna kafarū min ahli l-kitābi wa-lā l-mushrikīna an yunazzala ʿalaykum min khayrin min rabbikum wa-llāhu yakhtaṣṣu bi-raḥmatihī man yashāʾu wa-llāhu dhū l-faḍli l-ʿaẓīmi', 'Kitap ehlinden inkâr edenler ile Allah''a ortak koşanler, Rabbinizden size hiçbir iyilik indirilmesini istemezler. Allah ise dilediğini rahmetine tahsis eder. Allah, büyük fazl sahibidir.'),
(2, 106, 1, 17, 'مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'mā nansakh min āyatin aw nūnsihā naʾti bi-khayrin minhā aw mithlihā alam taʿlam anna ʾllāha ʿalā kulli shayʾin qadīr', 'Hangi ayeti yürürlükten kaldırır veya unutturursak, yerine daha hayırlısını veya benzerini getiririz. Allah''ın her şeye gücü yeter olduğunu bilmez misin?'),
(2, 107, 1, 17, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'elem taʿlem enne-llāhe lehu mulku-s-semāwāti ve-l-ʾarḍi ve mā lekum min dūni-llāhi min veliyyin ve lā naṣīrin', 'Göklerin ve yerin mülkü (hükümranlığı) Allah''a ait değil midir? Ve sizin için Allah''tan başka ne bir dost ne de bir yardımcı vardır.'),
(2, 108, 1, 17, 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'am turīdūna an tas''alū rasūlakum kamā su''ila Mūsā min qablu wa man yatabaddalil-kufra bil-īmāni faqad ḍalla sawā''as-sabīli', 'Yoksa peygamberinize daha önce Musa''ya sorulduğu gibi soru sormak mı istiyorsunuz? Kim imanı küfre değişirse, şüphesiz dosdoğru yoldan sapmış olur.'),
(2, 109, 1, 17, 'وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wadda kathīrun min ahli l-kitābi law yaruddūnakum min baʿdi īmānikum kuffāran ḥasadan min ʿindi anfushim min baʿdi mā tabayyana lahumu l-ḥaqqu faʿfū wa-ṣfaḥū ḥattā yaʾtiya llāhu bi-amrihī ʾinna llāha ʿalā kulli shayʾin qadīrun', 'Kitap ehlinden birçoğu, kendilerine hakikat apaçık belli olduktan sonra bile, içlerindeki hasetten dolayı sizi, imanınızdan sonra tekrar kâfirliğe döndürmeyi arzu ederler. Affedin ve hoş görün, Allah kendi emri gelinceye kadar (böyle yapın). Şüphesiz Allah her şeye hakkıyla gücü yetendir.'),
(2, 110, 1, 17, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'wa aqīmū aṣ-ṣalāta wa ātū az-zakāta wa mā tuqaddimū li-anfusikum min khayrin tajidūhu ʿinda Allāhi ʾinna Allāha bimā taʿmalūna baṣīrun', 'Namazı dosdoğru kılın, zekâtı verin. Kendiniz için önceden ne hayır işlemiş olursanız, onu Allah katında hazır bulursunuz. Şüphesiz Allah, yaptıklarınızı hakkıyla görendir.'),
(2, 111, 1, 17, 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'wa qālū lan yadkhula l-jannata illā man kāna hūdan aw naṣārā tilka amāniyyuhum qul hātū burhānakum in kuntum ṣādiqīn', 'Ve dediler ki: "Yahudi veya Hristiyan olmayan cennete giremez." Bunlar onların kendi kuruntularıdır. De ki: "Eğer doğru sözlüler iseniz, delilinizi getirin."'),
(2, 112, 1, 17, 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'balā man aslama wajhahu li-llāhi wa-huwa muḥsinun fa-lahū ʾajruhu ʿinda rabbihi wa-lā khawfun ʿalayhim wa-lā hum yaḥzanūna', 'Hayır! Kim yüzünü Allah''a döndürür ve iyilik yaparsa, onun mükâfatı Rabbinin katındadır. Onlara korku yoktur ve onlar mahzun da olmayacaklardır.'),
(2, 113, 1, 18, 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'waqālati l-yahūdu laysati n-naṣārā ʿalā shayʾin waqālati n-naṣārā laysati l-yahūdu ʿalā shayʾin wa hum yatlūna l-kitāb kadhālika qāla l-ladhīna lā yaʿlamūna mithla qawlihim fa-llāhu yaḥkumu baynahum yawma l-qiyāmati fīmā kānū fīhi yakhtalifūn', 'Yahudiler: "Hristiyanlar bir şey (doğru yol) üzere değillerdir" dediler. Hristiyanlar da: "Yahudiler bir şey üzere değillerdir" dediler. Halbuki hepsi Kitabı okuyorlar. (Bu şekilde) bilmeyenler de onların sözlerine benzer şeyler söylediler. Artık Allah, kıyamet günü, aralarında ayrılığa düştükleri şeyde hükmedecektir.'),
(2, 114, 1, 18, 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌ', 'Ve men aẓlamu mimmen menea mesācidallāhi en yużkera fīhā ismuhū ve sea fī ḫarābihā Ulāʾike mā kāne lehum en yedḫulūhā illā ḫāʾifīn Lehum fīd-dunyā ḫizyun Ve lehum fīl-ʾāḫirati ʿaẕābun ʿaẓīmun', 'Allah''ın mescitlerinde O''nun adının anılmasını engelleyen ve onların (mescitlerin) imarını/yıkılmasını önlemeye çalışan kimseden daha zalim kim olabilir? Bunlar, ancak korkarak girebilirler. Onlar için dünyada bir rezillik, ahirette ise büyük bir azap vardır.'),
(2, 115, 1, 18, 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ', 'wa lil-lāhi l-mashriqu wa l-maghribu fa-aynamā tuwallū fa-thamma wajhu l-lāhi ʾinna l-lāha wāsiʿun ʿalīmun', 'Doğu da batı da Allah''ındır. Nereye dönerseniz Allah''ın yönü orasıdır. Şüphesiz Allah, Vâsi''dir (rahmeti ve ilmi her şeyi kuşatandır), Alîm''dir (her şeyi bilendir).'),
(2, 116, 1, 18, 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', 'wa qālū t-takhadha l-lāhu waladan subḥānahū bal lahū mā fī s-samāwāti wa l-arḍi kullun lahū qānitūna', 'Dediler ki: "Allah çocuk edindi." Haşa! O, müstağnidir. Göklerde ve yerde ne varsa hepsi O''nundur. Hepsi O''na boyun eğmektedir.'),
(2, 117, 1, 18, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'Bedîʿu es-semâvâti ve el-ʾarḍi ve iżâ qaḍâ ʾemran feʾinnemâ yaqûlu lehû kun feyekûnu', 'O, göklerin ve yerin yaratıcısıdır. Bir işe hükmettiği zaman ona sadece “Ol!” der, o da hemen oluverir.'),
(2, 118, 1, 18, 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَٰبَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا ٱلْءَايَٰتِ لِقَوْمٍ يُوقِنُونَ', 'waqāla alladhīna lā yaʿlamūna lawlā yukallimunā allāhu aw taʾtīnā ʾāyatun kadhālika qāla alladhīna min qablihim mithla qawlihim tashābaha qulūbuhum qad bayyanā al-ʾāyāti liqawmin yūqinūna', 'Bilmezler, "Allah bize konuşmaz veya bize bir ayet gelmez mi?" dedi. Onlardan öncekiler de tıpkı onların dediği gibi dediler. Kalpleri birbirine benzedi. Biz, kesin bilgi edinecek bir topluluğa ayetleri (açıkça) beyan ettik.'),
(2, 119, 1, 18, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ', 'ʾinnā ʾarsalnāka bil-ḥaqqi bashīran wa nadhīran wa lā tus''alu ʿan ʾaṣḥābil-jaḥīmi', 'Şüphesiz biz seni hak ile, müjdeleyici ve uyarıcı olarak gönderdik. Ve sen, çılgın ateşin yoldaşlarından sorulmayacaksın.'),
(2, 120, 1, 19, 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'wa lan tarḍā ʿanka l-yahūdu wa lā n-naṣārā ḥattā tattabiʿa milatahum qul inna hudā llāhi huwa l-hudā wa laʾini ttabaʿta ahwāʾahum baʿda lladhī jāʾaka mina l-ʿilmi mā laka mina llāhi min waliyyin wa lā naṣīrin', 'Yahudiler de Hristiyanlar da, sen onların dinlerine uymadıkça asla senden razı olmazlar. De ki: "Allah''ın yolu, asıl doğru yol budur." Eğer sana gelen bu ilimden sonra onların arzu ve keyflerine uyarsan, bil ki Allah''tan sana ne bir dost ne de bir yardımcı vardır.'),
(2, 121, 1, 19, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'alladhīna ātaynāhumu l-kitāba yatlūnahu ḥaqqa tilāwatihi ulāʾika yuʾminūna bihi wa-man yakfuri bihi fa-ulāʾika humu l-khāsirūna', 'Kendilerine verdiğimiz Kitap''ı, onu hakkiyle okuyanlar (ona gereği gibi iman edenler) var ya, işte onlar buna inanırlar. Onu inkâr edenlere gelince, işte onlar ziyana uğrayanlardır.'),
(2, 122, 1, 19, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 'yā banī ʾisrāʾīl uḏkurū niʿmatiya llatī ʾanʿamtu ʿalaykum wa ʾannī faḍḍaltukum ʿalā l-ʿālamīn', 'Ey İsrailoğulları! Size verdiğim nimetimi ve sizi (diğer) âlemlere üstün kıldığımı hatırlayın.'),
(2, 123, 1, 19, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَٰعَةٌ وَلَا هُمْ يُنصَرُونَ', 'wa-ttaqū yawman lā tajzī nafsun ʿan nafsin shayʾan wa-lā yuqbalu minhā ʿadlun wa-lā tanfaʿuhā shafāʿatun wa-lā hum yunṣarūn', 'Ve öyle bir günden sakının ki, o gün kimse kimsenin yerine bir şey ödeyemez, kimseden fidye kabul edilmez ve kimseye şefaat fayda vermez ve onlara yardım edilmez.'),
(2, 124, 1, 19, 'وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِۦمَ رَبُّهُۥ بِكَلِمَٰتٍ فَأَتَمَّهُنَّ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِن ذُرِّيَّتِى قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ', 'wa-ʾiḏi-btalā ʾibrāhīma rabbuhu bi-kalimātin fa-ʾatammanna qāla ʾinnī jāʿiluka li-n-nāsi ʾimāman qāla wa-min ḏurriyyatī qāla lā yanālu ʿahdī ẓ-ẓālimīn', 'Hani Rabbi İbrahim''i birtakım kelimelerle denemiş, o da onları tamama erdirmişti. (Allah) şöyle buyurmuştu: "Ben seni insanlara önder yapacağım." İbrahim, "Ya soyumdan da (önderler yap, yâ Rab!)" demişti. Allah, "Zalimler benim ahdime (peygamberlik ve imamet gibi makamlara) nail olamaz." buyurmuştu.'),
(2, 125, 1, 19, 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِۦمَ مُصَلًّى وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'wa-ʾidh jaʿalnā l-bayta mathābatall lin-nāsi wa-ʾamnan wa-ttakhidhū min maqāmi ʾibrāhīma muṣallan wa-ʿahidnā ʾilā ʾibrāhīma wa-ʾismāʿīla ʾan ṭahhirā baytiya li-ṭ-ṭāʾifīna wa-l-ʿākifīna wa-r-rukkāʿi s-sujūd', 'Hani biz Beyt''i (Kabe''yi) insanlara bir ziyaret ve güvenlik mahalli kılmıştık. (Ve yine demiştik ki:) İbrahim''in makamından bir namaz yeri edinin. İbrahim ve İsmail''e de: Tavaf edenler, (orada) itikâfa girenler ve rükû edenler, secde edenler için evimi temizlemelerini emretmiştik.'),
(2, 126, 1, 19, 'وَإِذْ قَالَ إِبْرَٰهِۦمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ وَبِئْسَ ٱلْمَصِيرُ', 'wa-ʾiḏ qāla ʾibrāhīmu rabbi-ǧʿal hāḏā baladan ʾāminan wa-rzuq ʾahla-hū mina ṯ-ṯamarāti man ʾāmana min-hum bi-llāhi wa-l-yawmi l-ʾāḫiri qāla wa-man kafara fa-ʾumattiʿu-hū qalīlan ṯumma ʾaḍ-ṭarru-hū ʾilā ʿaḏābi n-nāri wa-biʾsa l-maṣīru', 'Hani İbrahim: "Rabbim! Burayı güvenli bir şehir yap, halkından Allah''a ve ahiret gününe iman edenleri rızıklandır." demişti. Allah: "Kim inkâr ederse, onu az bir süre geçindireceğim, sonra onu ateşin azabına mecbur kılacağım. Ne kötü bir dönüş yeri!" dedi.'),
(2, 127, 1, 20, 'وَإِذْ يَرْفَعُ إِبْرَٰهِۦمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa-ʾidh yarfaʿu ʾibrāhīmu l-qawāʿida mina l-bayti wa-ʾismāʿīlu rabbanā taqabbal minnā ʾinnaka ʾanta s-samīʿu l-ʿalīmu', 'İbrâhim, evinin duvarlarını (temellerini) İsmâil ile birlikte yükseltirken: "Rabbimiz! Bizden (bu hizmetimizi) kabul buyur. Şüphesiz sen, her şeyi işiten, her şeyi bilen-sin!" demişti.'),
(2, 128, 1, 20, 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'Rabbana wajʿalnā muslimayni laka Wamin dhurriyyatinā ummatan muslimatan laka Waʾarinā manāsikanā Wa tub ʿalaynā ʾInnaka ʾanta at-Tawwābu ar-Raḥīm', 'Ey Rabbimiz! Bizi sana tam teslim olmuş kimseler yap ve soyumuzdan da sana tam teslim olmuş bir ümmet (oluştur). Bize ibadet yollarımızı göster, tevbelerimizi kabul et. Şüphesiz tevbeleri kabul eden, merhamet eden sensin.'),
(2, 129, 1, 20, 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'Rabbana wa-bʿath fīhim rasūlan minhum yatlū ʿalayhim āyātika wa-yuʿallimuhumu l-kitāba wa-l-ḥikmata wa-yuzakkīhim innaka anta l-ʿazīzu l-ḥakīmu', 'Ey Rabbimiz! Onların içinden kendilerine senin ayetlerini okuyacak, onlara Kitabı ve hikmeti öğretecek ve onları arıtacak bir peygamber gönder. Şüphesiz sen, mutlak güç sahibi, hüküm ve hikmet sahibi olan sensin.'),
(2, 130, 1, 20, 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِۦمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'wa man yarghabu ʿan millati ibrāhīma illā man safiha nafsahū wa laqadi ṣṭafaynāhu fī d-dunyā wa innahū fī l-ʾākhirati lamina ṣ-ṣāliḥīn', 'İbrahim''in dininden, kendi nefsini aşağılayan kimselerden başka kim yüz çevirir? Andolsun ki biz onu dünyada seçtik; şüphesiz o, ahirette de salihlerdendir.'),
(2, 131, 1, 20, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ', 'iḏ qāla lahu ʾrabbuhu ʾaslim qāla ʾaslamtu lirabbi l-ʿālamīn', 'Rabbi ona: "Teslim ol!" dedi. O da: "Ben, âlemlerin Rabbine teslim oldum!" dedi.'),
(2, 132, 1, 20, 'وَوَصَّىٰ بِهَآ إِبْرَٰهِۦمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 'wa waṣṣā bihā ʾIbrāhīmu banīhi wa Yaʿqūbu yā banīyya ʾinna Llāha ʾiṣṭafā lakumu d-dīna falā tamūtunna ʾillā wa ʾantum muslimūna', 'Bunu İbrahim de kendi oğullarına vasiyet etti, Ya''kub da: "Ey oğullarım! Şüphesiz Allah size bu dini seçti. O halde sadece Müslümanlar olarak can verin!" dedi.'),
(2, 133, 1, 20, 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'am kuntum shuhadāʾa idh ḥaḍara Yaʿqūba l-mawtu idh qāla libanīhi mā taʿbudūna min baʿdī qālū naʿbudu ilāhaka wa-ilāha ʾābāʾika ʾIbrāhīma wa-ʾIsmāʿīla wa-ʾIsḥāqa ʾilāhan wāḥidan wa-naḥnu lahu muslimūna', 'Yoksa Yakub''a ölüm geldiği zaman siz şahitler miydiniz? O, oğullarına: "Benden sonra kime kulluk edeceksiniz?" dediği zaman, onlar: "Senin ilahına ve ataların İbrahim, İsmail ve İshak''ın ilahı olan tek bir ilaha kulluk edeceğiz. Ve bizler O''na teslim olmuşlarız" demişlerdi.'),
(2, 134, 1, 20, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 'tilka ummatun qad khalat laha ma kasar wa lakum ma kasaritum wa la tus''aluna ''amma kanu ya''malun', 'Onlar, gelip geçmiş bir ümmetti. Onların kazandığı kendilerine, sizin kazandığınız size aittir. Siz onların yapmakta olduklarından sorumlu değilsiniz.'),
(2, 135, 1, 21, 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ قُلْ بَلْ مِلَّةَ إِبْرَٰهِۦمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'wa qālū kūnū hūdan aw naṣārā tahtadū qul bal milleta ibrāhīma ḥanīfan wa mā kāna mina l-mušrikīn', 'Yahudiler: "Yahudi olun veya Hristiyanlar: "Hristiyan olun ki doğru yolu bulun" dediler. De ki: "Hayır, biz Hanif olarak İbrahim''in dinine uyarız; o ortak koşanlardan değildi."'),
(2, 136, 1, 21, 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'qūlū ʾāmannā bi-llāhi wa mā ʾunzilla ʾilayna wa mā ʾunzilla ʾilā ʾibrāhīma wa-ʾismāʿīla wa-ʾisḥāqa wa-yaʿqūba wa-l-ʾasbāṭi wa mā ʾūtiya mūsā wa-ʿīsā wa mā ʾūtiya n-nabiyyūna min rabbihim lā nufarriqu bayna ʾaḥadin minhum wa naḥnu lahuū muslimūna', 'De ki: "Allah''a, bize indirilene, İbrahim''e, İsmail''e, İshak''a, Yakub''a ve torunlarına indirilene, Musa''ya ve İsa''ya verilenlerle diğer peygamberlere Rableri tarafından verilene iman ettik. Onlardan hiçbirini ayırmayız ve biz O''na teslim olmuşlarız."'),
(2, 137, 1, 21, 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ فَسَيَكْفِيكَهُمُ ٱللَّهُ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'faʾin ʾāmanū bimithli mā ʾāmantum bihi faqadi ʾhtadaw waʾin tawallaw faʾinnamā hum fī šiqāqin fasayakfīkahumu ʾllāhu wahuwa ʾs-samīʿu ʾl-ʿalīmu', 'Eğer onlar da sizin inandığınız gibi inanırlarsa, doğru yolu bulmuş olurlar. Eğer yüz çevirirlerse, o zaman onlar derin bir ayrılık içindedirler. Onlara karşı Allah sana yetecektir. O, işiten ve bilendir.'),
(2, 138, 1, 21, 'صِبْغَةَ ٱللَّهِ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً وَنَحْنُ لَهُۥ عَٰبِدُونَ', 'ṣibġata llāh wa man aḥsanu mina llāhi ṣibġatan wa naḥnu lahū ʿābidūn', 'Allah''ın boyasıyla boyanın. Kim Allah''tan daha güzel boya verebilir? Biz ancak O''na kulluk ederiz.'),
(2, 139, 1, 21, 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', 'Qul ʾatuḥājjūnanā fī ʾallāhi wa huwa rabbunā wa rabbukum Wa lanā ʾaʿmālunā wa lakum ʾaʿmālukum Wa naḥnu lahu mukhliṣūna', 'De ki: "Aramızda Allah hakkında deliller mi ileri sürüyorsunuz? Oysa O, hem bizim hem de sizin Rabbinizdir. Bizim yaptıklarımız bize, sizin yaptıklarınız size aittir. Biz ise O''na samimiyetle bağlıyız."'),
(2, 140, 1, 21, 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'am taqūlūna inna ibrāhīma wa-ismāʿīla wa-isḥāqa wa-yaʿqūba wa-al-asbāṭa kānū hūdan aw naṣārā qul aʾantum aʿlamu am allāh wa-man aẓlamu mimman katama shahādatan ʿindahu min allāh wa-mā allāhu bi-ghāfilin ʿammā taʿmalūn', 'Yoksa siz, "İbrahim, İsmail, İshak, Yakub ve torunları Yahudi veya Hıristiyan idiler" mi diyeceksiniz? De ki: "Siz mi daha iyi bilirsiniz, yoksa Allah mı?" Allah tarafından (gelen hakikati) bilip de, onu (bile bile) gizleyenden daha zalim kim olabilir? Allah yaptıklarınızdan gafil değildir.'),
(2, 141, 1, 21, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 'tilka ummatun qad khalat laha ma kasar wa lakum ma kasar wa la tus''aluna ''amma kanu ya''malun', 'Onlar gelip geçmiş bir ümmetti; kazandıkları kendilerinedir, kazandığınız da sizedir. Siz onların yapmakta olduklarından sorumlu değilsiniz.'),
(2, 142, 2, 22, 'سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'sayaqūlu s-sufahāʾu mina n-nāsi mā wallāhum ʿan qiblatihimu llatī kānū ʿalayhā qul lillāhi l-mašriqu wa-l-maġribu yahdī man yašāʾu ʾilā ṣirāṭin mustaqīmin', 'İnsanlardan bir kısım beyinsizler, kendilerini (önceden) üzerinde bulundukları kıbleden çeviren sebep neydi, diyecekler. De ki: "Doğu da batı da Allah''ındır. O, dilediğini doğru yola iletir."'),
(2, 143, 2, 22, 'وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', 'wa kadhalika ja''alnākum ummatan wasaṭan litakūnū shuhadā''a ''alā an-nāsi wa yakūna ar-rasūlu ''alaykum shahīdan wa mā ja''alnā al-qibleta allatī kunta ''alayhā illā lina''lama man yattabi''u ar-rasūla mimman yanqalibu ''alā ''aqibayhi wa in kānat lakabīratan illā ''alā alladhīna hadā Allāhu wa mā kāna Allāhu liyudī''a īmānakum inna Allāha bi-n-nāsi lara''ūfun raḥīmun', 'İşte böylece sizi, insanlara şahitlik etmeniz ve elçinin de size şahitlik etmesi için hakkaniyetli bir ümmet kıldık. Ve biz, (daha önce) üzerinde bulunduğun Kâbe''yi ancak, Peygamber''e uyanlarla, topukları üzerinde geri dönenleri birbirinden ayırmak için bir imtihan (kıble) kıldık. Bu (kıble değişikliği) ise, Allah''ın hidayete erdirdiği kimseler dışında, herkese elbette ağır gelmişti. Allah, sizin imanınızı asla zayi edecek değildir. Şüphesiz Allah, insanlara karşı çok şefkatli, çok merhametlidir.'),
(2, 144, 2, 22, 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'qad narā taqalluba wajhika fī s-samāʾi falanuwalliyannaka qiblatan tarḍāhā fawalli wajhaka shaṭra l-masjidi l-ḥarāmi wa ḥaythu mā kuntum fawallū wujūhakum shaṭrahu wa inna lladhīna ūtū l-kitāba layaʿlamūna annahu l-ḥaqqu min rabbihim wa mā llāhu bighāfilin ʿammā yaʿmalūna', 'Yüzünün (sana gelen vahyi bekleyerek) göğe doğru yönelip durduğunu görmekteyiz. Elbette seni memnun edeceğin bir kıbleye döndüreceğiz. Hemen şimdi yüzünü Mescid-i Haram''a doğru çevir! Nerede bulunursanız bulunun, yüzlerinizi o yöne çevirin. Kendilerine kitap verilenler, bunun Rablerinden (gelen) bir gerçek olduğunu elbette bilirler. Allah yaptıklarınızdan gafil değildir.'),
(2, 145, 2, 22, 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ إِنَّكَ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'Ve leʾin eteyte ellezîne ûtû el-kitâbe bi-kulli âyetin mâ tebiʿû kıbleteke Ve mâ ente bi-tâbiʿin kıbletehum Ve mâ baʿduhum bi-tâbiʿin kıblete baʿdin Ve leʾini ittebaʿte ehvâʾehum min baʿdi mâ câʾeke mine el-ʿilmi inneke iżen le-mine ez-zâlimîne', 'Andolsun ki, sen Kitap verilenlere her türlü delili getirsen de, onlar senin kıblene uymazlar. Sen de onların kıblesine uyacak değilsin. Onların bazıları da diğer bazılarının kıblesine uymaz. Andolsun ki, sana ilim geldikten sonra onların heveslerine uyarsan, o zaman sen mutlaka zalimlerden olursun.'),
(2, 146, 2, 23, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', 'Alladhīna ātaynāhumu l-kitāba yaʿrifūnahu kamā yaʿrifūna abnāʾahum Wa-inna farīqan minhum layaktumūna l-ḥaqqa wa-hum yaʿlamūn', 'Kendilerine kitap verdiğimiz kimseler, onu (Muhammed''i), kendi oğullarını tanıdıkları gibi tanırlar. Yine de onlardan bir grup, bildikleri halde gerçeği gizlerler.'),
(2, 147, 2, 23, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'al-ḥaqqu min rabbika falā takūnan na mina al-mumtarīna', 'Hak, Rabbindendir; artık şüpheye düşenlerden olma!'),
(2, 148, 2, 23, 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wa likullin wijhatun huwa muwallīhā fastabiqū l-khayrāt aynamā takūnū yaʾti bikumu l-lāhu jamīʿan ʾinna l-lāha ʿalā kulli shayʾin qadīr', 'Herkesin yöneldiği bir yönü vardır. Öyleyse hayırlarda yarışın. Nerede olursanız olun, Allah hepinizi bir araya getirecektir. Şüphesiz Allah, her şeye hakkıyla gücü yetendir.'),
(2, 149, 2, 23, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'wa-min ḥaythu kharajta fa-walli wajhaka shaṭra l-masjidi l-ḥarāmi wa-ʾinnahu la-l-ḥaqqu min rabbika wa-mā llāhu bi-ghāfilin ʿammā taʿmalūna', 'Nereden çıkarsan çık, yüzünü Mescid-i Haram tarafına çevir. Şüphesiz bu Rabbinden gelen bir gerçektir. Allah yaptıklarınızdan gafil değildir.'),
(2, 150, 2, 23, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', 'wa-min ḥaythu kharajta fawalli wajhaka shaṭra l-masjidi l-ḥarāmi wa-ḥaythu mā kuntum fawallū wujūhakum shaṭrahu li-allā yakūna li-n-nāsi ʿalaykum ḥujjatun illā l-ladhīna ẓalamū minhum falā takhshawhum wa-khshawni wa-li-utimma niʿmatī ʿalaykum wa-laʿallakum tahtadūna', 'Nerede olursan ol, yüzünü Mescid-i Haram tarafına çevir. Nerede olursanız olun, yüzlerinizi onun tarafına çevirin. Tâ ki, -onlardan zulmedenler hariç- insanlar için size karşı bir delil kalmasın. (Onlardan) Bana haşyet etmeyin, Bana haşyet edin. Size olan ni''metimi tamamlamak ve sizin doğru yolu bulmanız için (böyle emrettim).'),
(2, 151, 2, 23, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'kamā arsalnā fīkum rasūlan minkum yatlū ʿalaykum ʾāyātinā wa yuzakkīkum wa yuʿallimukum al-kitāba wa al-ḥikmata wa yuʿallimukum mā lam takūnū taʿlamūn', 'Nitekim size kendi içinizden, âyetlerimizi size okuyan, sizi (mânevî kirlerden) temizleyen, Kitap ve hikmeti öğreten ve bilmediğiniz şeyleri öğreten bir elçi göndermiş bulunuyoruz.'),
(2, 152, 2, 23, 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', 'fa-dhkurūnī ʾadhkurkum wa-shkurū lī wa-lā takfurūn', 'O halde beni zikredin ki ben de sizi zikredeyim. Bana şükredin ve bana nankörlük etmeyin.'),
(2, 153, 2, 23, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 'yā ayyuhā alladhīna āmānū istaʿīnū biṣ-ṣabri waṣ-ṣalāti ʾinna Allāha maʿa ṣ-ṣābirīna', 'Ey iman edenler! Sabırla ve namazla yardım isteyin. Şüphesiz Allah, sabredenlerle beraberdir.'),
(2, 154, 2, 24, 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ بَلْ أَحْيَآءٌ وَلَٰكِن لَّا تَشْعُرُونَ', 'wa-lā taqūlū liman yuqtalu fī sabīli Allāhi amwātun bal aḥyāʾun wa-lākin lā tashʿurūna', 'Allah yolunda öldürülenlere «ölüler» demeyin. Hayır, onlar diridirler. Fakat siz sezamazsınız.'),
(2, 155, 2, 24, 'وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ وَبَشِّرِ ٱلصَّٰبِرِينَ', 'Ve le neblüvenneküm bi şey''in minel havfi vel cûı ve naksın minel emvâli vel enfüsi ves semerât Ve beşşiri es sâbirîn', 'Andolsun ki sizi biraz korku ve açlıkla, mallardan, canlardan ve ürünlerden eksiltmekle imtihan edeceğiz. Sabredenleri müjdele.'),
(2, 156, 2, 24, 'ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', 'alladhīna idhā aṣābathum muṣībatun qālū innā lillāhi wa-innā ilayhi rājiʿūna', 'Onlar, başlarına bir musibet geldiğinde, "Biz Allah''a aidiz ve biz O''na döneceğiz" diyenlerdir.'),
(2, 157, 2, 24, 'أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', 'ʾūlāʾika ʿalayhim ṣalawātun mir rabbihim wa-raḥmah wa-ʾūlāʾika humu l-muhtadūn', 'İşte Rab''lerinden bağışlamalar ve rahmet de bunlardır. Ve işte doğru yolu bulanlar bunlardır.'),
(2, 158, 2, 24, 'إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 'ʾinna ṣ-ṣafā wa-l-marwata min shaʿāʾiri llāhi fa-man ḥajja l-bayta ʾawi ʿtamara fa-lā junāḥa ʿalayhi ʾan yaṭṭawwafa bihimā wa-man taṭawwaʿa khayran fa-ʾinna llāha shākirun ʿalīmun', 'Şüphesiz Safa ile Merve, Allah''ın nişanelerindendir. Her kim Beyt''i (Kâbe''yi) hac veya umre niyetiyle ziyaret ederse, onun ikisi arasında tavaf etmesinde bir sakınca yoktur. Her kim de gönlünden koparak hayır işlerse, şüphesiz Allah şükrün karşılığını veren, her şeyi bilendir.'),
(2, 159, 2, 24, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ', 'ʾinna lladhīna yaktumūna mā ʾanzalnā mina l-bayyināti wal-hudā min baʿdi mā bayyannāhu li-nnāsi fī l-kitābi ʾulāʾika yalʿanuhumu l-lāhu wa yalʿanuhumu l-lāʿinūna', 'Şüphesiz ki âyetlerimizden ve doğru yolu gösteren açık delillerimizden indirdikten sonra, Kitap''ta insanlara bunları açıkladıktan sonra gizleyenler var ya; işte onlara hem Allah lânet eder, hem de bütün lânet ediciler lânet eder.'),
(2, 160, 2, 24, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', 'illa alladhīna tābū waʾaṣlaḥū wa bayyanū fa ʾulāʾika ʾatūbu ʿalayhim wa ʾanā at-tawwābu ar-raḥīmu', 'Ancak tövbe edenler, durumlarını düzeltenler ve gerçeği açıkça ortaya koyanlar (bu hükmün dışındadır). İşte ben onların tövbelerini kabul ederim. Ben de tövbeleri kabul edenim, merhamet ve ihsanı bol olanım.'),
(2, 161, 2, 24, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'ʾinna lladhīna kafarū wamātū wahum kuffārun ʾulāʾika ʿalayhim laʿnatu l-lāhi wal-malāʾikati wannaāsi ʾajmaʿīn', 'Şüphesiz inkâr edenler ve kâfir olarak ölenler; işte Allah''ın, meleklerin ve bütün insanların laneti onların üzerinedir.'),
(2, 162, 2, 24, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'khālidīna fīhā lā yukhaffafu ʿanhumu l-ʿadhābu walā hum yunẓarūn', 'Onlar orada ebedî kalırlar. Kendilerinden azap hafifletilmez ve onlara mühlet verilmez.'),
(2, 163, 2, 24, 'وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 'wa ʾilāhukum ʾilāhun wāḥidun lā ʾilāha ʾillā huwa ʾr-raḥmānu ʾr-raḥīmu', 'Sizin ilahınız tek bir ilahtır. O''ndan başka ilah yoktur. O, Rahmân''dır, Rahîm''dir.'),
(2, 164, 2, 25, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَءَايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'inna fī khalqi s-samāwāti wa-l-arḍi wa-khtilāfi l-layli wa-n-nahāri wa-l-fulki llatī tajrī fī l-baḥri bimā yanfaʿu n-nāsa wa mā anzala llāhu mina s-samāʾi min māʾin fa-aḥyā bihi l-arḍa baʿda mawtihā wa baththa fīhā min kulli dābbatin wa taṣrīfi r-riyāḥi wa-s-saḥābi l-musakhkhari bayna s-samāʾi wa-l-arḍi laʾāyātin li-qawmin yaʿqilūna', 'Şüphesiz göklerin ve yerin yaratılışında, gece ile gündüzün art arda gelişinde, insanlara fayda veren şeylerle denizde akıp giden gemilerde, Allah''ın gökten indirip de onunla yeryüzünü ölümünden sonra dirilttiği suda, yine orada her canlıdan türetip yaydığı (hayvanlarda), gökle yer arasında düzenleyip durduğu rüzgarlarda ve (gök ile yer) arasında céu''a tabi olmuş bulutlarda, aklını kullanan bir topluluk için (Allah''ın) birliğini gösteren deliller vardır.'),
(2, 165, 2, 25, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', 'Ve minen-nāsi men yetteḫiẕu min dûnillâhi endâden yuḥibbûnehum keḥubbillâh velleẕîne âmenû eşeddü ḥubben lillâh Ve lev yeralleẕîne żalemû iẕ yeravnel-ʿaẕâbe ennel-ḳuvvete lillâhi cemîʿan ve ennallâhe şedîdül-ʿaẕâb', 'İnsanlardan öyleleri vardır ki, Allah''tan başka eşler edinirler, onları Allah''ı sever gibi severler. İman edenlerin Allah''a olan sevgisi ise daha şiddetlidir. Zulmedenler azabı gördükleri zaman, bütün kuvvetin Allah''a ait olduğunu ve Allah''ın azabının şiddetli olduğunu bir bilselerdi!'),
(2, 166, 2, 25, 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', 'idh tabarraʾa alladhīna ʾuttubiʿū min alladhīna ʾttabaʿū wa raʾawu l-ʿadhāba wa taqaṭṭaʿat bihimu l-ʾasbābu', 'Hani, kendilerine uyulanlar, kendilerine uyanlardan uzaklaşmışlardı ve azabı görmüşlerdi de bütün bağlar kopmuştu.'),
(2, 167, 2, 25, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', 'waqāla alladhīna ittabaʿū law anna lanā karratan fanatabarraʾa minhum kamā tabarraʾū minnā kadhālika yurīhimu ʾallāhu ʾaʿmālahum ḥasarātin ʿalayhim wamā hum bik͟hārijīna mina n-nār', 'Uyanlar şöyle derler: Ah, bir daha dünyaya dönme imkanımız olsaydı da, şimdi biz de onlardan uzaklaştığımız gibi onlardan uzaklaşsaydık! İşte böylece Allah onlara yaptıklarını, üzerlerinde derin bir pişmanlık olarak gösterecektir. Onlar ateşten çıkacak da değillerdir.'),
(2, 168, 2, 25, 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'yā ayyuhā n-nāsu kulū mimmā fī l-arḍi ḥalālan ṭayyibā wa lā tattabiʿū khuṭuwāti sh-shayṭāni ʾinnahuū lakum ʿadūwun mubīnun', 'Ey insanlar! Yeryüzündeki şeylerin helal ve temiz olanlarından yiyin. Şeytanın adımlarını izlemeyin. Çünkü o, sizin için apaçık bir düşmandır.'),
(2, 169, 2, 25, 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'ʾinnemā yaʾmurukum bis-sūʾi wal-faḥshāʾi wa ʾan taqūlū ʿalā ʾllāhi mā lā taʿlamūn', 'O size ancak kötülüğü, fenalığı ve Allah hakkında bilmediğiniz şeyleri söylemenizi emreder.'),
(2, 170, 2, 26, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', 'wa-ʾidhā qīla lahumu-ttabiʿū mā ʾanzala ʾllāhu qālū bal nattabiʿu mā ʾalfaynā ʿalayhi ʾābāʾanā ʾa-wa-law kāna ʾābāʾuhum lā yaʿqilūna šayʾan wa-lā yahtadūna', 'Onlara: "Allah''ın indirdiğine uyun!" denildiği zaman, "Hayır, biz atalarımızı üzerinde bulduğumuz yola uyarız" derler. Ataları hiç akıl etmiyor ve doğru yolu bulamıyor idilerse de mi?'),
(2, 171, 2, 26, 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ', 'wa-mathalu allatheena kafaroo kamathali allathee yanʿiqu bimā lā yasmaʿu illā duʿāʾan wa-nidāʾan ṣummum bukmum ʿumyun fahum lā yaʿqiloon', 'İnkâr edenlerin durumu, sadece çağırma ve bağırmayı duyan (anlamayan) bir sürünün başında bağıran kimsenin durumu gibidir. Onlar sağır, dilsiz ve kördürler. Bu yüzden akıl erdiremezler.'),
(2, 172, 2, 26, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'yā ʾayyuhā l-ladhīna ʾāmanū kulū min ṭayyibāti mā razaqnākum wa-shkurū li-llāhi ʾin kuntum ʾiyyāhu taʿbudūna', 'Ey iman edenler! Size verdiğimiz rızıkların temiz olanlarından yiyin. Eğer siz (yalnızca) O''na kulluk ediyorsanız, Allah''a şükredin.'),
(2, 173, 2, 26, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'innamā ḥarrama ʿalaykumu l-maytata wa-d-dama wa-laḥma l-khinzīri wa mā uhilla bihi li-ghayri llāh fa-mani ḍṭurra ghayra bāghin wa lā ʿādin fa-lā ithma ʿalayh inna llāha ghafūrun raḥīm', 'O, size sadece leşi, kanı, domuz etini ve Allah''tan başkası adına kesileni haram kılmıştır. Başkaldıran ve sınırı aşan kimse olmamak üzere, kim zorlanırsa, günaha girmez. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir.'),
(2, 174, 2, 26, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ʾinna lladhīna yaktumūna mā ʾanzala l-lāhu mina l-kitābi wa-yashtarūna bihi thamanan qalīlan ʾulāʾika mā yaʾkulūna fī buṭūnihim ʾillā n-nāra wa-lā yukallimuhumu l-lāhu yawma l-qiyāmati wa-lā yuzakkīhim wa-lahum ʿadhābun ʾalīmun', 'Şüphesiz Allah''ın indirdiği Kitap''tan (bir şeyi) gizleyip onu az bir karşılığa satanlar, işte onlar, karınlarına yalnızca ateş doldururlar. Allah, kıyamet günü onlarla konuşmaz, onları günahlarından arındırmaz. Onlar için acı veren bir azap vardır.'),
(2, 175, 2, 26, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', 'ʾūlāʾika lladhīna shtarawu ḍ-ḍalālata bi-l-hudā wa-l-ʿadhāba bi-l-maghfirah famā ʾaṣbarahum ʿalā n-nār', 'İşte bunlar, hidayeti sapıklıkla, bağışlamayı azapla satın almış kimselerdir. Ateşe karşı onların bu sabrı ne kadar da garip!'),
(2, 176, 2, 26, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ', 'dhālika biʾanna ʾallāha nazzala l-kitāba bil-ḥaqqi waʾinna lladhīna ʾikhtalafū fī l-kitābi lafī shiqāqin baʿīdin', 'İşte bu, Allah''ın Kitab''ı hak olarak indirmesinden dolayıdır. Şüphesiz Kitap hakkında anlaşmazlığa düşenler, (gerçekten) uzak bir ayrılık içindedirler.'),
(2, 177, 2, 27, 'لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّۦنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'laysa l-birra an tuwallū wujūhakum qibala l-mashriqi wa-l-maghribi wa-lākinna l-birra man āmana bi-llāhi wa-l-yawmi l-ʾākhiri wa-l-malāʾikati wa-l-kitābi wa-n-nabiyyīna wa-ātā l-māla ʿalā ḥubbihi dhawī l-qurbā wa-l-yatāmā wa-l-masākīna wa-bna s-sabīli wa-s-sāʾilīna wa-fī r-riqābi wa-ʾaqāma ṣ-ṣalāta wa-ātā z-zakāta wa-l-mūfūna bi-ʿahdihim ʾidhā ʿāhadū wa-ṣ-ṣābirīna fī l-baʾsāʾi wa-ḍ-ḍarrāʾi wa-ḥīna l-baʾsi ʾulāʾika l-ladhīna ṣadaqū wa-ʾulāʾika humu l-muttaqūna', 'Yüzlerinizi doğuya veya batıya çevirmeniz iyilik (özü) değildir. Ancak iyilik, Allah''a, ahiret gününe, meleklere, kitaba ve peygamberlere iman eden; mala olan sevgisine rağmen, yakınlara, yetimlere, yoksullara, yolda kalmışlara, dilencilere ve boyunları (köleleri) çözmeye (harcayan); namazı kılan ve zekatı veren; anlaştıkları zaman sözlerini yerine getirenler; sıkıntı, hastalık ve savaş zamanlarında sabredenlerdir. İşte bunlar, doğru olanlardır ve işte bunlar, takva sahipleridir.'),
(2, 178, 2, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', 'yā ayyuhā llaḏīna āmanū kutiba ʿalaykumu l-qiṣāṣu fī l-qatla l-ḥurru bi-l-ḥurri wa-l-ʿabdu bi-l-ʿabdi wa-l-unṯā bi-l-unṯā faman ʿufiya lahu min axīhi šayʾun fāttibāʿun bi-l-maʿrūfi wa-adāʾun ilayhi bi-iḥsānin ḏālika taḫfīfun min rabbikum wa-raḥmatun famani-ʿtadā baʿda ḏālika falahu ʿaḏābun alīmun', 'Ey iman edenler! Öldürme (konusunda) kısas size farz kılındı. Hür kimse hür kimseye, köle kimse köle kimseye ve dişi kimse dişi kimseye (kısas olunur). Ancak kimin, kardeşi tarafından affedilmesi (bağışlanması) ile bir şey (kan bedeli) kabul edilirse, artık örfe uymak ve ona (hak sahibine) güzellikle (kan bedelini) ödemek gerekir. Bu, Rabbinizden (gelen) bir hafifletme ve bir rahmettir. Kim bunun ardından saldırıya geçerse, onun için elem dolu bir azap vardır.'),
(2, 179, 2, 27, 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ', 'wa lakum fī l-qiṣāṣi ḥayātun yā ʾulī l-ʾalbābi laʿallakum tattaqūna', 'Ey akıl sahipleri! Kasasta sizin için bir hayat vardır. Umulur ki, (bu hükümle) korunursunuz.'),
(2, 180, 2, 27, 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', 'kutiba ʿalaykum iḏā ḥaḍara aḥadakumul-mawt in taraka ḫayranil-waṣiyyatu lil-wālidayni wal-aqrabīn bil-maʿrūf ḥaqqan ʿalal-muttaqīn', 'Ey iman edenler! Birinize ölüm geldiği zaman, vasiyet etmek size farz kılındı. Anne baba ve yakın akrabalar için örfe uygun bir vasiyet; bu, Allah''tan korkanlar üzerine bir borçtur.'),
(2, 181, 2, 27, 'فَمَنۢ بَدَّلَهُۥ بَعْدَمَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'fe-men beddelehū baʿda mā samiʿahū fe-ʾinnamā ʾithmuhū ʿalā ʾlladhīna yubaddilūnahū ʾinna ʾllāha samīʿun ʿalīmun', 'Onu işittikten sonra kim onu değiştirirse, şüphesiz onun günahı onu değiştirenlerin üzerine olur. Şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir.'),
(2, 182, 2, 28, 'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'fe-men khāfa min mūsın janafān aw ithman fa-aṣlaḥa baynahum falā ithma ʿalayhi ʾinna llāha ghafūrun raḥīmun', 'Her kim, vasiyet edenin bir hataya düşmesinden veya günaha girmesinden korkar da tarafları uzlaştırırsa, onun üzerine hiçbir vebal yoktur. Şüphesiz Allah, Gafûr''dur, Rahîm''dir.'),
(2, 183, 2, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'yā ayyuhā alladhīna āmanū kutiba ʿalaykumu ṣ-ṣiyāmu kamā kutiba ʿalā alladhīna min qablikum laʿallakum tattaqūna', 'Ey iman edenler! Oruç, sizden öncekilere farz kılındığı gibi, size de farz kılındı. Umulur ki korunursunuz.'),
(2, 184, 2, 28, 'أَيَّامًا مَّعْدُودَٰتٍ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'Ayyāman maʿdūdātin Faman kāna minkum marīḍan aw ʿalā safarin Faʿiddatun min ayyāmin ukhar Waʿalā alladhīna yuṭīqūnahū fidyatun ṭaʿāmu miskīnin Faman taṭawwaʿa khayran fahuwa khayrun lahū Wa an taṣūmū khayrun lakum in kuntum taʿlamūn', 'Sayılı günlerdedir. Sizden kim hasta olur veya yolculukta bulunursa, tutamadığı günler sayısınca başka günlerde tutsun. Ona dayanabilenler (ancak) bir yoksul doyumu kadar fidye vermekle yükümlüdür. Kim gönülden hayır işlerse, bu kendisi için daha iyidir. Oruç tutmanız -eğer bilirseniz- sizin için daha hayırlıdır.'),
(2, 185, 2, 28, 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Şehru Ramadâne-lleżî unzile fîhi-lkur''ânu huden linnâsi ve beyyinâtin mine-lhudâ ve-lfurḳân(i) Femen şehide minkumu-şşehra felyeṣumh(u) Vemen kâne merîḍan ev ‘alâ seferin fe‘iddetun min eyyâmin uḫar(a) Yurîdu-llâhu bikumu-lyusra velâ yurîdu bikumu-l‘usr(a) Velitukmilû-l‘idde(te) Velitukebbirû-llâhe ‘alâ mâ hedâkum Vele‘allekum teşkurûn(e)', 'Ramazan ayı ki onda Kur''an, insanlara hidayet rehberi ve doğru yolu gösteren apaçık deliller ve (hak ile batılı ayıran) Furkan olarak indirilmiştir. Öyleyse sizden kim bu aya yetişirse onu oruçlu geçirsin. Kim de hasta olur veya yolculukta bulunursa, tutamadığı günler sayısınca başka günlerde tutsun. Allah sizin için kolaylık ister, zorluk istemez. Sayıyı tamamlamanız, sizi doğru yola iletmesine karşılık Allah''ı yüceltmeniz ve şükretmeniz içindir.'),
(2, 186, 2, 28, 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', 'wa ʾiḏā saʾalaka ʿibādī ʿannī faʾinnī qarībun ʾujību daʿwata ʾd-dāʿi ʾiḏā daʿānī falyastajībū lī walyaʾmīnū bī laʿallahum yarsudūn', 'Kullarım sana benden (herhangi bir şeyi) sorduklarında, (onlara de ki:) Ben (onlara çok) yakınım. Bana dua ettiği zaman, dua edenin duasına icabet ederim. Artık benim çağrıma uymaları ve bana inanmaları gereklidir. İşte onlar, doğruya erebilirler.'),
(2, 187, 2, 29, 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', 'uḥilla lakum laylata ṣ-ṣiyāmi r-rafathu ilā nisāʾikum hunna libāsun lakum wa-antum libāsun lahunna ʿalima -llāhu annakum kuntum takhtānūna anfusakum fatāba ʿalaykum wa-ʿafā ʿankum fa-l-āna bāshirūhunna wa-btaghū mā kataba -llāhu lakum wa-kulū wa-shrū ḥattā yatabayyana lakumu l-khayṭu l-ʾabyuḍu mina l-khayṭi l-ʾaswadi mina l-fajri thumma ʾatimmū ṣ-ṣiyāma ilā l-layli wa-lā tubāshirūhunna wa-antum ʿākifūna fī l-masājidi tilka ḥudūdu -llāhi fa-lā taqrabūhā kadhālika yubayyinu -llāhu ʾāyātihi li-n-nāsi laʿallahum yattaqūna', 'Oruç gecesinde kadınlarınıza yaklaşmak size helal kılındı. Onlar size birer elbise, siz de onlara birer elbisesiniz. Allah, sizin nefislerinize hıyanet etmekte olduğunuzu bildi de tövbenizi kabul edip sizi affetti. Artık onlarla birleşin ve Allah''ın sizin için yazdığını isteyin. Tan yeri ağarıncaya kadar siz yiyin için. Sonra da orucu geceye kadar tamamlayın. Mescidlerde itikâfta bulunduğunuz zamanlarda ise kadınlarınızla birleşmeyin. Bunlar Allah''ın sınırlarıdır, onlara yaklaşmayın. İşte Allah, insanlara âyetlerini böyle açıklar; tâ ki kendileri sakınsınlar.'),
(2, 188, 2, 29, 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', 'wa-lā taʾkulū ʾamwālakum baynakum bi-l-bāṭili wa-tudlū bihā ʾilā al-ḥukkāmi li-taʾkulū farīqan min ʾamwāli an-nāsi bi-l-ʾithmi wa-ʾantum taʿlamūna', 'Mallarınızı aranızda batıl yollarla yemeyin. İnsanların mallarından bir kısmını günah yoluyla yemeniz için, onları hâkimlere (rüşvet olarak) vermeyin. Siz de biliyorsunuz.'),
(2, 189, 2, 29, 'يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'yas''alūnaka ''ani l-ʾahillati qul hiya mawāqītu li-nnāsi wa-l-ḥajji wa-laysa l-birru bi-ʾan taʾtū l-buyūta min ẓuhūrihā wa-lākinna l-birra mani-ttqā wa-ʾtū l-buyūta min ʾabwābihā wa-ttaqū l-lāha laʿallakum tufliḥūna', 'Sana hilali sorarlar. De ki: "O, insanlar ve hac için vakittir (ölçüsüdür). İyilik, evlere arkalarından gelmeniz değildir. Lakin iyilik, Allah''tan korkup fenalıktan sakınandır. Evlere kapılarından gelin. Allah''tan korkun ki kurtuluşa eresiniz."'),
(2, 190, 2, 29, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'wa qātilū fī sabīli llāhi lladhīna yuqātilūnakum wa lā taʿtadū ʾinna llāha lā yuḥibbu l-muʿtadīn', 'Allah yolunda, size karşı savaşanlarla savaşın ve haddi aşmayın. Şüphesiz Allah haddi aşanları sevmez.'),
(2, 191, 2, 30, 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'waqtulūhum ḥaythu thaqiftumūhum waʾakhrijūhum min ḥaythu ʾakhrajūkum wa-lfitnatu ʾashaddu mina l-qatl walā tuqātilūhum ʿinda l-masjidi l-ḥarāmi ḥattā yuqātilūkum fīhi faʾin qātalūkum fa-qtulūhum kadhālika jazāʾu l-kāfirīn', 'Onları bulduğunuz yerde öldürün ve sizi çıkardıkları yerden siz de onları çıkarın. Fitne, öldürmeden daha kötüdür. Onlarla Mescid-i Haram yanında, onlar sizinle orada savaşmadıkça savaşmayın. Eğer sizinle orada savaşırsa, artık onları öldürün. İşte kafirlerin cezası budur.'),
(2, 192, 2, 30, 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'fa-ʾini-ntahaw fa-ʾinna-llāha ġafūrun raḥīm', 'Eğer vazgeçerlerse, şüphesiz Allah Gafur''dur, Rahîm''dir.'),
(2, 193, 2, 30, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', 'wa qātilūhum ḥattā lā takūna fitnah wa yakūna d-dīnu lillāh fa-ʾin intahaw falā ʿudwāna ʾillā ʿalā ẓ-ẓālimīn', 'Onlarla, fitne ortadan kalkıncaya ve din tamamen Allah''ın oluncaya kadar savaşın. Eğer vazgeçerlerse, bilin ki Allah onların yaptıklarını hakkıyla görmektedir.'),
(2, 194, 2, 30, 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'ash-shahru l-ḥarāmu bish-shahri l-ḥarāmi wa-l-ḥurumātu qiṣāṣun fa-mani-ʿtadā ʿalaykum fa-ʿtadū ʿalayhi bi-mithli mā-ʿtadā ʿalaykum wa-ttaqū Allāha wa-ʿlamū anna Allāha maʿa l-muttaqīna', 'Haram ay, haram aya karşılıktır. Diğer kutsal şeylere karşılık da kısastır. O halde kim size tecavüz ederse, size tecavüz ettiği kadar ona tecavüz edin. Allah''tan korkun ve Allah''ın, Allah''a karşı gelmekten sakınanlarla beraber olduğunu bilin.'),
(2, 195, 2, 30, 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ وَأَحْسِنُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 'wa-anfiqū fī sabīli llāhi wa-lā tulqū bi-aydīkum ilā t-tahlukati wa-aḥsinū ʾinna llāha yuḥibbu l-muḥsinīna', 'Allah yolunda harcayın ve (yaptıklarınızla) kendi kendinizi tehlikeye atmayın. Bir de iyilik edin. Şüphesiz Allah iyilik edenleri sever.'),
(2, 196, 2, 30, 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'wa-atimmū l-ḥajja wa-l-ʿumrata li-llāh fa-in uḥṣirtum fa-mā staysaṟa mina l-hadyi wa-lā taḥliqū ruʾūsakum ḥattā yabluḡa l-hadyu maḥillahu fa-man kāna minkum marīḍan aw bihi ʾaḏan min raʾsihi fa-fidyatun min ṣiyāmin ʾaw ṣadaqatin ʾaw nusukin fa-iḏā ʾamintum fa-man tamattaʿa bi-l-ʿumra-ti ʾilā l-ḥajji fa-mā staysaṟa mina l-hadyi fa-man lam yajid fa-ṣiyāmu ṯalāṯati ʾayyāmin fī l-ḥajji wa-sabʿatin iḏā rajaʿtum tilka ʿašaratu-n kāmilatun ḏālika li-man lam yakun ʾahluhu ḥāḍirī l-masjidi l-ḥarāmi wa-ttaqū l-lāha wa-ʿlamū ʾanna l-lāha šadīdu l-ʿiqābi', 'Haccı ve umreyi Allah için tamamlayın. Eğer (düşman tarafından) kuşatılırsanız, artık size (kurban olarak) ne kolay gelirse (onu gönderin). Kurbanlarınız yerlerine ulaşıncaya kadar başlarınızı tıraş etmeyin. Sizden her kim hasta olursa veya başından bir rahatsızlığı bulunursa, fidye olarak oruç tutması, sadaka vermesi veya kurban kesmesi gerekir. Güvenliğe kavuşursanız, hac günlerine kadar umre ile faydalanmak isteyen kimse, kolayına gelen bir kurban keser. Kurban bulamayan kimse ise, hac günlerinde üç gün, döndüğünüzde yedi gün olmak üzere (toplam) on gün oruç tutar. Bu, ailesi Mescid-i Haram civarında bulunmayanlar içindir. Allah''a karşı gelmekten sakının ve Allah''ın azabının çetin olduğunu bilin.'),
(2, 197, 2, 31, 'ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَٰتٌ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ', 'al-ḥajju ʾašhurun maʿlūmātun fa-man faraḍa fīhinna al-ḥajja fa-lā rafata wa-lā fusūqa wa-lā jidāla fī al-ḥajji wa-mā tafʿalū min ḫayrin yaʿlamhu ʾallāhu wa-tazawwadū fa-ʾinna ḫayra az-zādi at-taqwā wa-ttaqūnī yā ʾūlī al-ʾalbābi', 'Hac, bilinen aylardır. Kim bu aylarda hac yapmaya niyet ederse, (ihramda iken) cinsel ilişki, günaha sapma ve çekişme yoktur. Ne yaparsanız Allah onu bilir. (Ahiret için) azık edinin. Şüphesiz azığın en iyisi takva (Allah''a karşı gelmekten sakınma)dır. Ey akıl sahipleri! Bana karşı gelmekten sakının.'),
(2, 198, 2, 31, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', 'laysa ʿalaykum junāḥun an tabtaghū faḍlan min rabbikum faʾiḏā ʾafaḍtum min ʿarafātin faḏkurū ʾllāha ʿinda l-mašʿari l-ḥarāmi waḏkurūhu kamā hadākum waʾin kuntum min qablihī lamina ḍ-ḍāʾillīn', 'Rabbinizden bir fazl (rızık) istemenizde size bir günah yoktur. Arafat''tan (sel gibi) indiğinizde Allah''ı Meş''ar-i Haram''da zikredin. O sizi nasıl hidayete erdirdiyse siz de O''nu öyle zikredin. Gerçekten siz, daha önce sapmışlardan idiniz.'),
(2, 199, 2, 31, 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'thumma afīḍū min ḥaythu afāḍa n-nāsu wāstagfirū llāha ʾinna llāha ghafūrun raḥīmun', 'Sonra insanların (döküldüğü gibi) dökülün ve Allah''tan mağfiret dileyin. Şüphesiz Allah, Gafur''dur, Rahim''dir.'),
(2, 200, 2, 31, 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍ', 'fa-iḏā qaḍaytum manāsikakum fa-ḏkurū llāha ka-ḏikrikum ābāʾakum aw ašadda ḏikran fa-mina n-nāsi man yaqūlu rabbanā ātinā fī d-dunyā wa-mā lahu fī l-ʾāḫirati min ḫalāqin', 'Nihayet hac ibadetinizi bitirdiğinizde, (kendi aranızda) atalarınızı andığınız gibi, hatta ondan daha kuvvetli bir anma ile Allah''ı anın. İnsanlardan öylesi vardır ki: "Rabbimiz! Bize dünyada (verebileceğini) ver" der. Böylelerinin ahirette hiçbir nasibi yoktur.'),
(2, 201, 2, 31, 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْءَاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ', 'wa-minhum man yaqūlu rabbanā ātina fī d-dunyā ḥasanatan wa-fī l-ʾākhirati ḥasanatan wa-qinā ʿadhāba n-nār', 'Onlardan öylesi de vardır ki: "Rabbimiz! Bize dünyada da iyilik ver, ahirette de iyilik ver ve bizi ateş azabından koru" der.'),
(2, 202, 2, 31, 'أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'ʾūlāʾika lahum naṣībun mimmā kasabū wa-llāhu sarīʿu l-ḥisābi', 'İşte onların kazandıklarından nasipleri vardır. Allah, hesabı çabuk görendir.'),
(2, 203, 2, 32, 'وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ ٱتَّقَىٰ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', 'wa-dhkurū llāha fī ʾayyāmin maʿdūdātin fa-man taʿajjala fī yawmayni falā ʾithma ʿalayhi wa-man taʾakhkhara falā ʾithma ʿalayhi li-mani ʾttaqā wa-ttaqū llāha wa-ʿlamū ʾannakum ʾilayhi tuḥsharūna', 'Allah''ı sayılı günler boyunca anın. Kim iki günde (Mina''dan) acele ederse ona günah yoktur. Kim de geri kalırsa ona da günah yoktur; bu, Allah''tan korkup sakınanlar içindir. Allah''tan korkup sakının ve bilin ki O''na toplanacaksınız.'),
(2, 204, 2, 32, 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', 'wa min an-nāsi man yuʿjibuka qawluhū fī al-ḥayāti ad-dunyā wa yushhidu Allāha ʿalā mā fī qalbihī wa huwa aladdu al-khiṣām', 'İnsanlardan öylesi vardır ki, dünya hayatına dair (söylediği) sözleri senin hoşuna gider. Hatta o, kalbindekine şahit tutar. Halbuki o, (hakkı) bırakmayan azılı bir düşmandır.'),
(2, 205, 2, 32, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', 'wa ʾiḏā tawallā saʿā fī l-ʾarḍi li-yufsida fīhā wa yuhlika l-ḥarṯa wa n-nasla wa-llāhu lā yuḥibbu l-fasāda', 'Onlar, yüz çevirip (o) yerde bozgunculuk çıkarmaya, ekinleri ve nesilleri helak etmeye çalışırlar. Allah ise bozgunculuğu sevmez.'),
(2, 206, 2, 32, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ فَحَسْبُهُۥ جَهَنَّمُ وَلَبِئْسَ ٱلْمِهَادُ', 'wa ʾiḏā qīla lahu ʾttaqi ʾllāha ʾaḵaḏathu l-ʿizztu bil-ʾiṯmi faḥasbuhu ǧahannamu walabiʾsa l-mihādu', 'Ne zaman ona: “Allah’tan kork!” dense, günahı onu alır götürür. Cehennem de onun için yeter! Ne kötü bir varış yeridir orası!'),
(2, 207, 2, 32, 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'wa min an-nāsi man yashrī nafsahu ibtiġāʾa marḍāti llāh wa llāhu raʾūfun bil-ʿibād', 'İnsanlardan öylesi de vardır ki, Allah''ın rızasını kazanmak amacıyla kendini (canını) feda eder. Allah da kullarına çok şefkatlidir.'),
(2, 208, 2, 32, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'yā ayyuhā alladhīna āmanū udkhulū fī s-silmi kāffatan wa lā tattabiʿū khuṭuwāti sh-shayṭāni innahuu lakum ʿaduwwun mubīnun', 'Ey iman edenler! Hep birlikte barışa (teslimiyete) girin ve şeytanın adımlarını izlemeyin. Şüphesiz o, sizin için apaçık bir düşmandır.'),
(2, 209, 2, 32, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'fa-in zalaltum min baʿdi mā jāʾatkum al-bayyinātu fa-ʿlamū anna Allāha ʿazīzun ḥakīmun', 'Artık size açık deliller geldikten sonra kiminից sapacak olursa, bilin ki Allah azizdir, hikmet sahibidir.'),
(2, 210, 2, 32, 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'hal naẓurūna illā an yaʾtiyahumu ʾllāhu fī ẓulalin mina l-ġamāmi wa-l-malāʾikatu wa-quḍiya l-ʾamru wa-ʾilā ʾllāhi turjaʿu l-ʾumūru', 'Onlar, Allah''ın kendilerine gölgeler halinde meleklerle birlikte gelmesini ve işin bitirilmesini mi bekliyorlar? Bütün işler Allah''a döndürülür.'),
(2, 211, 2, 33, 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'sal banī isrāʾīla kam ātaynāhum min āyatin bayyinatin wa man yubaddil niʿmata allāhi mim baʿdi mā jāʾathu faʾinna allāha shadīdu l-ʿiqābi', 'İsrailoğullarına sor: Onlara nice açık ayetler verdik. Kim Allah''ın nimetini, kendisine geldikten sonra değiştirirse, şüphesiz Allah''ın azabı şiddetlidir.'),
(2, 212, 2, 33, 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'Zuyyina lilladhīna kafarū al-ḥayātu ad-dunyā Wa yaskharūna minalladhīna āmanū Walladhīna ittaqaw fawqahum yawma al-qiyāmah Wallāhu yarzuqu man yashāʾu bighayri ḥisāb', 'Dünya hayatı, inkar edenlere çekici kılındı. Onlar, iman edenlerden kimileriyle alay ederler. Oysa, kendilerini koruyanlar (takva sahipleri) kıyamet günü onlardan daha üstündür. Allah, dilediği kimseleri hesapsız rızıklandırır.'),
(2, 213, 2, 33, 'كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّۦنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'kāna n-nāsu ummatan wāḥidatan fa-baʿatha llāhu n-nabiyyīna mubashshirīna wa-mundhirīna wa-anzala maʿahumu l-kitāba bi-l-ḥaqqi li-yaḥkuma bayna n-nāsi fīmā ʾikhtalafū fīhi wa-mā ʾikhtalafa fīhi ʾillā l-ladhīna ʾūtūhu min baʿdi mā jāʾathumu l-bayyinātu baghyan baynahum fa-hadā llāhu lladhīna ʾāmanū li-mā ʾikhtalafū fīhi mina l-ḥaqqi bi-ʾidhnihi wa-llāhu yahdī man yashāʾu ʾilā ṣirāṭin mustaqīmin', 'İnsanlar (başlangıçta) tek bir ümmet idi. Allah, müjdeleyici ve uyarıcı olarak peygamberler gönderdi. İnsanlar arasındaki anlaşmazlıklar konusunda hak ile hükmetsinler diye onlarla birlikte hak kitabını indirdi. Kendilerine apaçık deliller geldikten sonra, aralarındaki kıskançlık ve azgınlık yüzünden ayrılığa düşenler, ancak o (kitap) verilenlerdir. Allah, iman edenleri, hakkında ayrılığa düştükleri gerçeğe kendi izniyle ulaştırdı. Allah, dilediğini dosdoğru yola iletir.'),
(2, 214, 2, 33, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ', 'am ḥasibtum an tadkhulū l-jannata wa-lammā yaʾtikum mathalu l-ladhīna khalaw min qablikum massathumu l-baʾsāʾu wa-ḍ-ḍarrāʾu wa-zulzilū ḥattā yaqūla r-rasūlu wa-l-ladhīna āmanū maʿahu matā naṣru llāhi ʾalā ʾinna naṣra llāhi qarībun', 'Yoksa sizden öncekilerin başına gelenler gelmeden cennete gireceğinizi mi sandınız? Onlar öyle şiddetli mihnetlere ve sıkıntılara uğradılar ve öyle sarsıldılar ki, sonunda Resûl ve onunla birlikte iman edenler: ''Allah''ın yardımı ne zaman?'' dediler. Dikkat edin, şüphesiz Allah''ın yardımı pek yakındır.'),
(2, 215, 2, 33, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'yas''alūnaka mādhā yunfiqūn qul mā anfaqtum min khayrin falilwālidayni wal''aqrabīna walyatāmā walmasākīni wabni s-sabīl wamā tafʿalū min khayrin fa''inna Llāha bihi ʿalīm', 'Sana, neyi nafaka olarak vereceklerini sorarlar. De ki: ''Hayır olarak her ne verirseniz, ana-babaya, akrabaya, yetimlere, yoksullara ve yolcuya verin. Hayır olarak ne yaparsanız, şüphesiz Allah onu bilir.'''),
(2, 216, 2, 34, 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'kutiba ʿalaykumu l-qitālu wa-huwa kurhun lakum wa-ʿasā an takrahū shayʾan wa-huwa khayrun lakum wa-ʿasā an tuḥibbū shayʾan wa-huwa sharrun lakum wa-llāhu yaʿlamu wa-antum lā taʿlamūn', 'Üzerinize savaş farz kılındı. Savaş, sizin için bir hoşnutsuzluktur. Oysa sizin için hayırlı olabilecek bir şeyi hoş görmeyebilirsiniz. Sizin için şerli olabilecek bir şeyi de hoş görebilirsiniz. Allah bilir, siz bilmezsiniz.'),
(2, 217, 2, 34, 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'yas''alūnaka ''ani sh-shahri l-ḥarāmi qitālin fīhi qul qitālun fīhi kabīrun wa ṣaddun ''an sabīli llāhi wa kufrun bihi wa l-masjidi l-ḥarāmi wa ''ikhrāju ''ahlihi minhu ''akbaru ''inda llāhi wa l-fitnatu ''akbaru mina l-qatli wa lā yazālūna yuqātilūnakum ḥattā yaruddūkum ''an dīnikum ''ini staṭā''ū wa man yartadid minkum ''an dīnihi fa-yamut wa huwa kāfirun fa-''ulā''ika ḥabiṭat ''a''māluhum fī d-dunyā wa l-''ākhirati wa ''ulā''ika ''aṣḥābu n-nāri hum fīhā khālidūna', 'Sana haram olan ayda savaşmayı soruyorlar. De ki: "Haram olan ayda savaşmak büyük bir günahtır. Allah yolundan alıkoymak, O''nu inkâr etmek, Mescid-i Haram''ı (ziyaretten) alıkoymak ve halkını oradan çıkarmak ise Allah katında daha büyüktür. Fitne çıkarmak, adam öldürmekten daha büyüktür." Onlar, güç yetirirlerse sizi dininizden döndürünceye kadar sizinle savaşmaya devam ederler. Sizden kim dininden döner ve kâfir olarak ölürse, onların bütün amelleri dünyada da ahirette de boşa gitmiş demektir. İşte onlar cehennem ehlidirler ve orada ebedî kalacaklardır.'),
(2, 218, 2, 34, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'ʾinna lladhīna ʾāmanū wal-ladhīna hājarū wa-jāhadū fī sabīli l-lāhi ʾulāʾika yarjūna raḥmata l-lāhi wal-lāhu ghafūrun raḥīmun', 'Şüphesiz iman edenler, hicret edenler ve Allah yolunda cihad edenler var ya, işte bunlar Allah''ın rahmetini umarlar. Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(2, 219, 2, 34, 'يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'yas''alūnaka ''ani l-khamri wa-l-maysiri qul fīhimā ithmun kabīrun wa-manāfi''u li-nnāsi wa-ithmuhumā akbaru min naf''ihimā wa-yas''alūnaka mādhā yunfiqūna quli l-''afwa kadhālika yubayyinu l-Allāhu lakumu l-āyāti la''allakum tatafakkarūna', 'Sana içkiyi ve kumarı soruyorlar. De ki: "Onlarda hem büyük bir günah, hem de insanlar için (bazı) faydalar vardır. Ancak günahları, faydalarından daha büyüktür." Ve sana, neyi infak edeceklerini soruyorlar. De ki: "(İhtiyaçtan) artanı." İşte Allah, düşünüp anayasınız diye size âyetleri böyle açıklar.'),
(2, 220, 2, 35, 'فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'fī d-dunyā wa-l-ʾākhirati wa yasʾalūnaka ʿani l-yatāmā qul iṣlāḥun lahum khayrun wa in tukhāliṭūhum fa-ʾikhwānukum wa-llāhu yaʿlamu l-mufsida mina l-muṣliḥi wa law shāʾa llāhu la-ʾaʿnatakum ʾinna llāha ʿazīzun ḥakīmun', 'Dünya ve ahiret hakkında sana yetimler hakkında soru sorarlar. De ki: "Onlar için ıslah (iyilik) etmek hayırlıdır. Eğer onlarla (malı) karıştırırsanız, artık onlar sizin kardeşlerinizdir. Allah, fesat çıkaranı ıslah edenden ayırır. Ve eğer Allah dileseydi, sizi de helâk ederdi. Şüphesiz Allah, Azîz''dir, Hakîm''dir."'),
(2, 221, 2, 35, 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'wa lā tankiḥū al-mushrikāti ḥattā yuʾminna wa laʾamatun muʾminatun khayrun min mushrikatin walaw aʿjabatkum wa lā tunkiḥū al-mushrikīna ḥattā yuʾminū wa laʿabdun muʾminun khayrun min mushrikin walaw aʿjabakum ʾulāʾika yadʿūna ʾilā an-nār wallāhu yadʿū ʾilā al-jannati wal-maghfirati biʾidhnihi wa yubayyinu ʾāyātihi li-nnāsi laʿallahum yataḏakkarūn', 'İman etmedikçe müşrik kadınlarla evlenmeyin. İman eden bir cariye, hoşunuza gitseler bile müşrik bir kadından daha hayırlıdır. Müşrik erkeklerle de iman etmedikçe evlenmeyin. İman eden bir köle, hoşunuza gitseler bile müşrik bir erkekten daha hayırlıdır. Onlar ateşe davet ederler, Allah ise izniyle cennete ve bağışlanmaya davet eder. O, insanlara âyetlerini açıklar ki, öğüt alıp düşünebilsinler.'),
(2, 222, 2, 35, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 'wa yas''alūnaka ʿani l-maḥīḍi qul huwa ʾaḏan fa-ʿtazilū an-nisāʾa fī l-maḥīḍi wa lā taqrabūhunna ḥattā yaṭhur''na fa-ʾiḏā taṭahhar''na fa-ʾtūhunna min ḥayṯu ʾamarākumu ʾllāhu ʾinna ʾllāha yuḥibbu t-tawwābīna wa yuḥibbu l-mutaṭahhirīna', 'Sana kadınların ay hali (hayız) hakkında soru sorarlar. De ki: ''O, bir rahatsızlıktır (ezâ). Bu sebeple kadınlardan ay hali süresince ayrılın ve temizlenmedikçe onlara yaklaşmayın. Temizlendiklerinde ise Allah''ın size emrettiği yerden onlara yaklaşın. Şüphesiz Allah, tevbe edenleri ve temizlenenleri sever.'''),
(2, 223, 2, 35, 'نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ وَقَدِّمُوا۟ لِأَنفُسِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'nisāʾukum ḥarṯun lakum faʾtū ḥarṯakum ʾannā šiʾtum waqaddimū liʾanfusikum wattaqū ʾllāha waʿlamū ʾannakum mulāqūhu wa-bašširi l-muʾminīn', 'Kadınlarınız sizin için bir tarladır. O halde tarlanıza dilediğiniz gibi varın. Kendiniz için (geleceğe yönelik) hazırlık yapın. Allah''tan korkup sakının ve O''na kavuşacağınızı bilin. Mü''minleri müjdele.'),
(2, 224, 2, 35, 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'wa-lā tajʿalū ʾllāha ʿurḍatan li-ʾaymānikum ʾan tabarrū wa-tattaqū wa-tuṣliḥū bayna ʾn-nāsi wa-ʾllāhu samīʿun ʿalīmun', 'Allah''ı, iyilik yapmanız, Allah''tan korkmanız ve insanlar arasını düzeltmeniz (konusunda) yeminlerinize bir engel tutmayın. Şüphesiz Allah, hakkıyla işitendir, bilendir.'),
(2, 225, 2, 36, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ وَٱللَّهُ غَفُورٌ حَلِيمٌ', 'La yu''ākhidhukumullāhu bil-laghwi fī aymānikum Wa lākin yu''ākhidhukum bimā kasabat qulūbukum Wallāhu ghafūrun ḥalīm', 'Allah sizi, yeminlerinizdeki (kasıtsız) boş sözlerinizden dolayı sorumlu tutmaz; fakat kalplerinizin kazandığından dolayı sizi sorumlu tutar. Allah çok bağışlayıcı, çok sabırlıdır.'),
(2, 226, 2, 36, 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'lilladhīna yuʾlūna min nisāʾihim tarabbuṣu ʾarbaʿati ʾashhurin fa-in fāʾū fa-inna Llāha ghafūrun raḥīmun', 'Kadınlarından kasemle uzaklaşanlar için dört ay bekleme süresi vardır. Eğer bu sürede (eşlerine) dönüp barışırlarsa, şüphesiz Allah çok bağışlayıcı, çok merhamet edicidir.'),
(2, 227, 2, 36, 'وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'wa ʾin ʿazamū ṭ-ṭalāqa fa ʾinna Llāha samīʿun ʿalīmun', 'Eğer (boşanmaya) azmederlerse, şüphesiz Allah hakkıyla işitendir, bilendir.'),
(2, 228, 2, 36, 'وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًا وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'wa-l-muṭallaqātu yatarabbaṣna bi-ʾanfusihinna thalāthata qurūʾin wa-lā yaḥillu lahunna ʾan yaktumna mā khalaqa ʾallāhu fī ʾarḥāmihinna ʾin kunna yuʾminna bi-llāhi wa-l-yawmi l-ʾākhiri wa-buʿūlatuhunna ʾaḥaqqu bi-raddihinna fī dhālika ʾin ʾarādū ʾiṣlāḥan wa-lahunna mithlu lladhī ʿalayhinna bi-l-maʿrūfi wa-li-r-rijāli ʿalayhinna darajatun wa-llāhu ʿazīzun ḥakīmun', 'Boşanmış kadınlar, üç kur'' (hayız veya temizlik müddeti) beklerler. Onların, Allah''ın rahimlerinde yarattığını gizlemeleri kendilerine helâl olmaz. Eğer Allah''a ve ahiret gününe inanuyorlarsa. Kocaları, bu süre içinde barış (veya barışma) isteğiyle onları geri almağa daha çok hak sahibidirler. Kadınların, hakkaniyete uygun olarak erkekler üzerindeki hakları gibi, erkeklerin de kadınlar üzerine hakları vardır. Ancak erkeklerin kadınlar üzerine bir derece (üstünlüğü) vardır. Allah Azîz''dir, Hakîm''dir.'),
(2, 229, 2, 36, 'ٱلطَّلَٰقُ مَرَّتَانِ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'aṭ-ṭalāqu marratān fa-imsākun bi-maʿrūfin aw tasrīḥun bi-iḥsānin wa-lā yaḥillu lakum an taʾkhudhū mim-mā ātaytumūhunna shayʾan illā an yakhāfā allā yuqīmā ḥudūda Allāhi fa-in khiftum allā yuqīmā ḥudūda Allāhi fa-lā junāḥa ʿalayhimā fīmā iftadat bihi tilka ḥudūdu Allāhi fa-lā taʿtadūhā wa-man yataʿadda ḥudūda Allāhi fa-ʾulāʾika humu ẓ-ẓālimūn', 'Boşanma iki defadır. Ardından ya iyilikle tutmak ya da güzellikle salıvermek vardır. Kadınlara verdiğiniz mehirlerden bir şey almanız size helal değildir. Ancak ikisinin de Allah''ın sınırlarını gözetemeyecekleri korkusuna kapılmaları durumu müstesnadır. Eğer ikisinin de Allah''ın sınırlarını gözetemeyecekleri korkusuna kapılacağınızdan endişe ederseniz, o zaman kadının (boşanmak için) ödediği fidye konusunda ikisine de bir günah yoktur. Bunlar Allah''ın sınırlarıdır, onlara tecavüz etmeyin. Kim Allah''ın sınırlarını aşarsa, işte onlar zalimlerdir.'),
(2, 230, 2, 36, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', 'fa-in ṭallaqahā falā taḥillu lahu min baʿdu ḥattā tankiḥa zawjan ġayrahu fa-in ṭallaqahā falā junāḥa ʿalayhimā an yatarājʿā in ẓannā an yuqīmā ḥudūda ʾllāh wa-tilka ḥudūdu ʾllāhi yubayyinuhā li-qawmin yaʿlamūn', 'Böylece eğer o (kadını) boşarsa, ondan sonra artık o kadın, kendisinden başka bir (erkekle) evleninceye kadar kendisine helal olmaz. Eğer o (ikinci koca da) onu boşarsa, Allah''ın sınırlarını (hukukunu) ayakta tutabileceklerini zannederlerse, o zaman (ilk karı-koca) birbirlerine dönmelerinde kendilerine bir günah yoktur. İşte bunlar Allah''ın sınırlarıdır; bilen bir topluluk için bunları açıklar.'),
(2, 231, 2, 37, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًا وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'wa ʾiḏā ṭallaqtumu n-nisāʾa fabalaḡna ʾajalَهُنَّ fa-ʾamsikūhunna bimaʿrūfin ʾaw sarriḥūhunna bimaʿrūfin walā tumsikūhunna ḍirāran litaʿtadū waman yafʿal ḏālika faqad ẓalama nafsahū walā tattahiḏū ʾāyāti llāhi huzuwan wa-ḏkurū niʿmata llāhi ʿalaykum wamā ʾanzala ʿalaykum mina l-kitābi wal-ḥikmati yaʿiẓukum bihī wattaqū llāha wa-ʿlamū ʾanna llāha bikulli šayʾin ʿalīmun', 'Boşadığınız kadınların iddet süreleri sona ermeden onlara dönmeniz veya onları bilerek nikâhınızda tutmanız caiz değildir. Onları, haklarına tecavüz etmek amacıyla zarar vermek için tutmayınız. Kim böyle yaparsa, gerçekten kendine zulmetmiş olur. Allah''ın âyetlerini alaya almayınız. Allah''ın size verdiği nimetleri ve indirdiği Kitap ve hikmeti hatırlayınız ki onlarla size öğüt versin. Allah''tan korkup sakının ve Allah''ın her şeyi bildiğini iyi biliniz.'),
(2, 232, 2, 37, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'wa ʾiḏā ṭallaqtumu n-nisāʾa fabalaḡna ʾajalَهُنَّ falā taʿḍulūhunna ʾan yankiḥna ʾazwājahunna ʾiḏā tarāḍaw baynahum bil-maʿrūfi ḏālika yūʿaẓu bihi man kāna minkum yuʾminu billāhi wal-yawmi l-ʾāḵiri ḏāliskum ʾazkā lakum wa ʾaṭharu wallāhu yaʿlamu wa ʾantum lā taʿlamūna', 'Siz kadınları boşadığınızda ve iddet sürelerini doldurduklarında, birbirleriyle anlaşarak yeniden evlenmelerini engellemeyin. Bu, içinizden Allah''a ve ahiret gününe inanan kimselere verilen öğüttür. Bu sizin için daha hayırlı ve daha temizdir. Allah bilir, siz bilmezsiniz.'),
(2, 233, 2, 37, 'وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'wa-l-wālidātu yurḍiʿna ʾawlādahunna ḥawlayni kāmilayni liman ʾarāda ʾan yutimma r-raḍāʿata wa-ʿalā l-mawlūdi lahu rizquhunna wa-kiswatuhunna bi-l-maʿrūfi lā tukallafu nafṣun ʾillā wusʿahā lā tuḍārra wālidatun bi-waladihā wa-lā mawlūdun lahu bi-waladihī wa-ʿalā l-wāriṯi miṯlu ḏālika fa-ʾin ʾarādā fiṣālan ʿan tarāḍin minhumā wa-tašāwurin fa-lā junāḥa ʿalayhimā wa-ʾin ʾaradtum ʾan tastarḍiʿū ʾawlādakum fa-lā junāḥa ʿalaykum ʾiḏā sallamtum mā ʾātaytum bi-l-maʿrūfi wa-ttaqū ʾllāha wa-ʿlamū ʾanna ʾllāha bi-mā taʿmalūna baṣīrun', 'Anneler, çocuklarını tam iki yıl emzirirler. Bu, emzirmeyi tamamlamak isteyenler içindir. Annelerin yiyecek ve giyecek masrafları, örfe uygun olarak babaya aittir. Hiçbir kimse, gücünün yeteceği kadarından fazla yüklenmez. Ne anne, ne de baba, çocuğu yüzünden zarara uğratılmamalıdır. Mirasçı da aynı şekilde sorumludur. Eğer ana-baba, karşılıklı anlaşarak ve danışarak sütten ayırmak isterlerse, ikisine de bir günah yoktur. Eğer çocuklarınızı (başka bir süt anneye) emzirtmek isterseniz, vereceğiniz şeyi örfe uygun olarak teslim ettiğiniz takdirde size de bir günah yoktur. Allah''tan korkun ve Allah''ın, yaptıklarınızı gördüğünü bilin.'),
(2, 234, 2, 38, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'wa-alladhīna yutawaffawna minkum wa-yadharūna azwājan yatarabbaṣna bi-anfusihinna arbaʿata ashruin wa-ʿashran fa-idhā balaghna ajalahunna fa-lā junāḥa ʿalaykum fīmā faʿalna fī anfusihinna bi-al-maʿrūfi wa-allāhu bimā taʿmalūna khabīrun', 'İçinizden ölenler ve geride eşler bırakanlar, eşleri kendileri için dört ay on gün bekleme süresi geçirirler. Sürelerini doldurduklarında, kendi haklarında örfe uygun olarak ne yaparlarsa size bir günah yoktur. Allah, yaptıklarınızdan haberdardır.'),
(2, 235, 2, 38, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', 'wa lā junāḥa ʿalaykum fīmā ʿarraḍtum bihi min khiṭbati n-nisāʾi aw aknantum fī ʾanfusikum ʿalima ʾllāhu ʾannakum satadhkurūnahu wa lākin lā tuwāʿidūhunna sirran ʾillā ʾan taqūlū qawlan maʿrūfan wa lā taʿzimū ʿuqdata n-nikāḥi ḥattā yablugha l-kitābu ʾajalahu wa ʿlamū ʾanna ʾllāha yaʿlamu mā fī ʾanfusikum fa-ḥdhahūruhu wa ʿlamū ʾanna ʾllāha ghafūrun ḥalīmun', 'Onları kadınlara (evlenme teklifiyle) dokundurduğunuz veya içlerinizde gizlediğiniz hususta size bir vebal yoktur. Allah sizin onları anacağınızı bilmektedir. Ancak, onlarla gizli bir vaatte bulunmayın; ancak maruf (uygun) bir söz söylemeniz müstesnadır. Ve nikah akdine azmetmeyin, ta ki kitap (olan süre) eceli gelinceye kadar. Ve Allah''ın, nefislerinizde olanı bildiğini biliniz ve O''ndan sakının. Ve Allah''ın Gafur (çok bağışlayıcı) ve Halim (çok yumuşak huylu) olduğunu biliniz.'),
(2, 236, 2, 38, 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُحْسِنِينَ', 'lā junāḥa ʿalaykum in ṭallaqtumu n-nisāʾa mā lam tamsasūhunna aw tafriḍū lahunna farīḍatan wa-mattiʿūhunna ʿalā l-mūsiʿi qadaruhū wa-ʿalā l-muqtari qadaruhū matāʿan bi-l-maʿrūfi ḥaqqan ʿalā l-muḥsinīn', 'Onları (kadınları) kendilerine dokunmadan veya bir mehir belirlemeden boşadığınız takdirde, üzerinize bir günah yoktur. Ancak onları (boşandıkları takdirde) yararlandırın. Varlıklı olan kendi imkanına göre, darda kalan da kendi imkanına göre, uygun bir şekilde yararlandırması, iyilik edenler üzerine bir borçtur.'),
(2, 237, 2, 38, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'wa-ʾin ṭallaqtumūhunna min qabli ʾan tamassūhunna wa-qad faraḍtum lahunna farīḍatan fa-niṣfu mā faraḍtum ʾillā ʾan yaʿfūna ʾaw yaʿfuwa l-ladhī bi-yadihi ʿuqdatu n-nikāḥi wa-ʾan taʿfū ʾaqrabu li-t-taqwā wa-lā tansawu l-faḍla baynakum ʾinna llāha bimā taʿmalūna baṣīrun', 'Eğer onları, kendilerine dokunmadan önce boşamış olursanız ve onlar için bir mehir belirlemişseniz, o zaman (ödenmesi gereken) yarısı sizin üzerinizedir. Ancak kadınların affetmesi veya nikah akdini elinde tutan kişinin (kocanın) affetmesi başka. Sizin affetmeniz takvaya daha yakındır. Aranızdaki fazlı (üstünlüğü/iyiliği) unutmayın. Şüphesiz Allah, yaptıklarınızı hakkıyla bilendir.'),
(2, 238, 2, 39, 'حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ', 'ḥāfiẓū ʿalā ṣ-ṣalawāt wa-ṣ-ṣalāti l-wusṭā wa-qūmū li-llāhi qānitīn', 'Namazlara ve orta namaza (ikindi namazına) riayet edin ve Allah için boyun eğerek (saygıyla) kalkın.'),
(2, 239, 2, 39, 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'fa-in khiftum fa-rijālan aw rukbānan fa-idhā amintum fa-dhkurū Allāha kamā ''allamakum mā lam takūnū ta''lamūn', 'Eğer (düşman korkusuyla) tehlikeye düşerseniz, yaya veya binekli olarak (namaz kılın). Güvene girince, bilmediğiniz şeyleri Allah size öğrettiği şekilde Allah''ı zikredin (namaz kılın).'),
(2, 240, 2, 39, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'wa-lladhīna yutawaffawna minkum wa-yadharūna azwājan waṣiyyatan li-azwājihim matāʿan ilā l-ḥawli ghayra ikhrājin fa-in kharajna falā junāḥa ʿalaykum fī mā faʿalna fī ʾanfusihinna min maʿrūfin wa-llāhu ʿazīzun ḥakīmun', 'İçinizden ölenler ve geride eşler bırakanlar, eşleri için bir yıla kadar (evlenmeden) yararlanma vasiyetinde bulunsunlar. Eğer kendiliğinden çıkarlarsa, haklarında örfe uygun olarak yaptıkları şeyden dolayı size bir günah yoktur. Allah Azîz''dir, Hakîm''dir.'),
(2, 241, 2, 39, 'وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', 'wa lilmuṭallaqāti matāʿun bilmaʿrūfi ḥaqqan ʿalā l-muttaqīn', 'Boşanmış kadınlar için de örfe uygun bir müt''a (fayda sağlama) vardır. Bu, Allah''a karşı sorumluluk bilinciyle yaşayanlar üzerine düşen bir borçtur.'),
(2, 242, 2, 39, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'kadhalika yubayyinu allahu lakum ayatihi la''allakum ta''qilun', 'Allah, umulur ki akledesiniz diye ayetlerini size böyle açıklar.'),
(2, 243, 2, 39, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'a-lem te-ra i-la-l-le-zi-ne ha-ra-ju- min di-ya-ri-him ve hum u-lu-fun ha-ze-ra-l-mevt fe-qa-le le-hu-mul-la-hu mu-tu sum-me ah-ya-hum in-ne-l-la-he le-zu fad-lin a-le-n-na-s ve la-kin-ne ak-the-ra-n-na-si la yash-ku-run', 'Ölümden kaçınmak için yurtlarından çıkan ve binlerce kişi olan kimseleri görmedin mi? Allah onlara, ''Ölün!'' dedi. Sonra onlara (tekrar) can verdi. Şüphesiz Allah, insanlara karşı lütuf sahibidir. Fakat insanların çoğu şükretmez.'),
(2, 244, 2, 39, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'wa qātilū fī sabīli llāh wa ʿlamū anna llāha samīʿun ʿalīm', 'Allah yolunda savaşın ve bilin ki Allah, hakkıyla işitendir, bilendir.'),
(2, 245, 2, 39, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', 'man dā alladhī yuqriḍu llāha qarḍan ḥasanan fayuḍāʿifuhu lahū ʾaḍʿāfan kathīrah wa llāhu yaqbiḍu wa yabsṭu wa ʾilayhi turjaʿūn', 'Kimdir o ki Allah''a güzel bir borç verecek de O da bunu kendisine kat kat ödeyecektir? Allah darlığa da, bolluğa da imkan verir ve siz O''na döndürüleceksiniz.'),
(2, 246, 2, 40, 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'alam tara ilā l-malai min banī isrāʾīla min baʿdi mūsā iż qālū li-nabiyyin lahumu-bʿaṯ lanā malikan nuqātil fī sabīli-llāh qāla hal ʿasaytum in kutiba ʿalaykumu l-qitālu allā tuqātilū qālū wa-mā lanā allā nuqātila fī sabīli-llāhi wa-qad uḫrijnā min diyārinā wa-abnāʾinā fa-lammā kutiba ʿalayhimu l-qitālu tawallaw illā qalīlan minhum wa-llāhu ʿalīmun bi-ẓ-ẓālimīn', 'Musa''dan sonra İsrailoğulları''ndan ileri gelenleri görmedin mi ki, peygamberlerine, ''Bize bir komutan ata da Allah yolunda savaşalım'' demişlerdi. Peygamber, ''Ya üzerinize savaş farz kılınır da savaşmazsanız?'' dedi. ''Allah yolunda ve yurtlarımızdan, çocuklarımızdan çıkarılmışken savaşmayalım mı?'' dediler. Savaş kendilerine farz kılınınca, içlerinden azı müstesna, hepsi yüz çevirdiler. Allah zalimleri bilir.'),
(2, 247, 2, 40, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'waqāla lahum nabiyyuuhum innallāha qad baʿatha lakum ṭālūta malikā qālū annā yakūnu lahul-mulku ʿalaynā wa naḥnu aḥaqqu bil-mulki minhu wa lam yuʾta saʿatan minal-māl qāla innallāha ṣṭafāhu ʿalaykum wa zādahuu basṭatan fīl-ʿilmi wal-jism wallāhu yuʾtī mulkahuu man yashāʾu wallāhu wāsiʿun ʿalīm', 'Onlara peygamberleri dedi ki: "Şüphesiz Allah size Talut''u melik (hükümdar) olarak göndermiştir." Dediler ki: "O bize nasıl melik olur? Mülk (hükümdarlık) bize ondan daha çok layıktır. Ona maldan da bolca verilmemiştir." (Peygamberleri) dedi ki: "Doğrusu Allah onu size seçti ve onun bilgisini ve beden yapısını (gücünü) bolca artırdı. Allah mülkünü dilediğine verir. Allah, Vâsi''dir (rahmet ve ihsanı bol), Alîm''dir (her şeyi bilen)."'),
(2, 248, 2, 40, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ إِنَّ فِى ذَٰلِكَ لَءَايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'waqāla lahum nabiyyu-hum inna ʾāyata mulkihi ʾan yaʾtiyaku-mu ʾat-tābūtu fīhi sakīnatun mir rabbikum wabaqiyyatun mimmā taraka ʾālu mūsā waʾālu hārūna taḥmilu-hu ʾal-malāʾikatu ʾinna fī dhālika laʾāyatan lakum ʾin kuntum muʾminīn', 'Onlara peygamberleri şöyle dedi: "Onun (Tâlût''un) hükümdarlığının alâmeti, size içinde Rabbinizden bir sekînet (huzur ve sükûn), Mûsâ ailesinden ve Hârûn ailesinden kalmış bir kalıntı bulunan ve meleklerin taşıdığı bir sandığın gelmesidir. Eğer inanmış kimseler iseniz, bunda sizin için muhakkak bir alâmet (delil) vardır."'),
(2, 249, 2, 41, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 'falamma faṣala ṭālūtu bil-junūdi qāla inna -llāha mubtalīkum binaharin faman shariba minhu falaysa minnī waman lam yaṭʿamhu fa-innahu minnī illā mani-ghtarafa ghurfatan bi-yadihi fa-sharibū minhu illā qalīlan minhum falamma jāwazahu huwa wal-ladhīna āmanū maʿahu qālū lā ṭāqata lanā l-yawma bi-jālūta wa-junūdihi qāla l-ladhīna yaẓunnūna annahum mulāqū -llāhi kam min fiʾatin qalīlatin ghalabat fiʾatan kathīratan bi-idhni -llāhi wal-lāhu maʿa ṣ-ṣābirīn', 'Talut, ordularıyla birlikte (savaşa) çıktığında dedi ki: "Şüphesiz Allah sizi bir ırmakla imtihan edecek. Kim ondan içerse benden değildir. Kim de tadına bakmazsa, avucuyla bir avuç alan müstesna, o bendendir." Onlardan pek azı hariç hepsi ondan içti. Talut ve onunla birlikte iman edenler ırmağı geçtiğinde, (diğerleri) "Bugün bizim Calut ve ordularına karşı gücümüz yok" dediler. Allah''a kavuşacaklarını umanlar ise şöyle dediler: "Nice az topluluklar, Allah''ın izniyle nice çok topluluklara galip gelmiştir. Allah sabredenlerle beraberdir."'),
(2, 250, 2, 41, 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'wa lammā barazū li-jālūta wa junūdihi qālū rabbana ʾafrig ʿalaynā ṣabran wa thabbit ʾaqdāmanā wanṣurnā ʿalā l-qawmi l-kāfirīn', 'Onlar, Calut ve ordusuyla karşılaştıklarında şöyle dediler: "Rabbimiz! Üzerimize sabır yağdır, ayaklarımızı sabit tut ve kâfirler topluluğuna karşı bize yardım et!"'),
(2, 251, 2, 41, 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ', 'fa-hazamūhum bi-iḏni llāhi wa-qatala Dāwūdu Ǧālūta wa-ʾātāhu llāhu l-mulka wa-l-ḥikmata wa-ʿallamahū mimmā yašāʾu wa-lawlā dafʿu llāhi n-nāsa baʿḍahum bi-baʿḍin la-fasadati l-ʾarḍu wa-lākinna llāha ḏū faḍlin ʿalā l-ʿālamīna', 'Allah''ın izniyle onları bozguna uğrattılar. (Ve) Allah, Davud''a mülk ve hikmet verdi ve ona dilediğinden öğretti. Eğer Allah''ın insanları birbirleriyle savması olmasaydı, yeryüzesi mutlaka fesada uğrardı. Fakat Allah, âlemlere karşı fazl sahibidir.'),
(2, 252, 2, 41, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'tilka ʾāyātu llāhi natlūhā ʿalayka bil-ḥaqqi wa ʾinnaka lamina l-mursilīna', 'Bunlar, sana hak olarak okuduğumuz Allah''ın ayetleridir. Ve şüphesiz sen gönderilenlerdensin.'),
(2, 253, 3, 42, 'تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 'tilka r-rusulu faḍḍalnā baʿḍahum ʿalā baʿḍin minhum man kallama ḷḷāhu wa rafaʿa baʿḍahum darajātin wa ātaynā ʿīsa bna maryama l-bayyināti wa ayyadnāhu bi-rūḥi l-qudusi wa law shāʾa ḷḷāhu mā qtatala lladhīna min baʿdihim min baʿdi mā jāʾathumu l-bayyinātu wa lākini kh-talaftū fa minhum man āmāna wa minhum man kafara wa law shāʾa ḷḷāhu mā qtataltū wa lākina ḷḷāha yafʿalu mā yurīdu', 'İşte bu peygamberler; biz onların bir kısmını bir kısmına üstün kıldık. Onlardan Allah ile konuşanlar ve derecelerle yükselttiğimiz kimseler vardır. Biz Meryem’in oğlu İsa’ya apaçık deliller verdik ve onu Rûhulkudüs ile destekledik. Eğer Allah dileseydi, kendilerine apaçık deliller geldikten sonra birbirlerini öldürmezlerdi. Fakat ayrılığa düştüler. Onlardan kimi iman etti, kimi de inkar etti. Eğer Allah dileseydi birbirlerini öldürmezlerdi. Ama Allah dilediğini yapandır.'),
(2, 254, 3, 42, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَٰعَةٌ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', 'yā ayyuhā lladhīna āmānū anfiqū mimmā razaqnākum min qabli an yaʾtiya yawmun lā bayʿun fīhi wa lā khullatun wa lā shafāʿatun wa lkāfirūna humu ẓẓālimūna', 'Ey iman edenler! Sizleri rızıklandırdığımız şeylerden (infak edip) harcayın. Ta ki (o gün gelmeden) alış-verişin, dostluğun ve şefaatin olmayacağı bir gün gelinceye dek. Kafirler ise zalimlerdir.'),
(2, 255, 3, 42, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'Allāhu lā ilāhe illā huve’l-ḥayyu’l-kayyūmu Lā te’huẕuhu senetun velā nevmun Lehu mā fi’s-semāvāti vemā fi’l-arḍi Men ẕe’lleẕī yeşfeʿu ʿindehu illā bi-iẕnihi Yaʿlemu mā beyne eydīhim vemā ḫalfahum Velā yuḥīṭūne bişey’in min ʿilmihi illā bimā şā’e Vesiʿa kürsiyyu’hu’s-semāvāti ve’l-arḍa Velā ye’ūduhu ḥifẕuhumā Ve huve’l-ʿaliyyu’l-ʿaẓīmu', 'Allah, O''ndan başka hiçbir ilah yoktur. O, daima diridir, ebedî olarak var olandır. O''nu ne bir uyuklama tutabilir ne de bir uyku. Göklerde ve yerde ne varsa hepsi O''nundur. O''nun izni olmadan O''nun katında kim şefaat edebilir? O, kullarının önlerinde ve arkalarında ne varsa hepsini bilir. Onlar ise O''nun dilediği kadarından başka ilminden hiçbir şey kavrayamazlar. O''nun kürsisi, gökleri ve yeri içine alacak kadar geniştir. Onları korumak kendisine bir ağırlık vermez. O, çok yücedir, çok büyüktür.'),
(2, 256, 3, 42, 'لَآ إِكْرَاهَ فِى ٱلدِّينِ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'lā ʾikrāha fī d-dīn qad tabayyana r-rušdu mina l-ġayy fa-man yakfur bi-ṭ-ṭāġūti wa-yuʾmin billāh fa-qadi stamsaka bi-l-ʿurwati l-wuṯqā lā nfiṣāma lahā wa-llāhu samīʿun ʿalīm', 'Dinde zorlama yoktur. Artık doğruluk, eğrilikten (açıkça) ayrılmıştır. Kim tağutu reddedip Allah''a inanırsa, muhakkak ki kopması imkânsız (sağlam) bir kulpa tutunmuştur. Allah, (her şeyi) işitendir, bilendir.'),
(2, 257, 3, 43, 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'Allāhu waliyyu alladhīna ʾāmanū yukhrijuhum mina ẓ-ẓulumāti ʾilā n-nūr Wa-lladhīna kafarū ʾawliyāʾuhumu ṭ-ṭāghūtu yukhrijūnahum mina n-nūri ʾilā ẓ-ẓulumāt ʾŪlāʾika ʾaṣḥābu n-nāri hum fīhā khālidūn', 'Allah, iman edenlerin velisidir (dostudur); onları karanlıklardan aydınlığa çıkarır. İnkâr edenlere gelince, onların velileri (dostları) ise Tağut''tur. Onları aydınlıktan karanlıklara çıkarırlar. İşte bunlar cehennem ehlidir. Onlar orada ebedî kalacaklardır.'),
(2, 258, 3, 43, 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِۦمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِۦمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ قَالَ إِبْرَٰهِۦمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'ʾalam tara ʾilā lladhī ḥājja ʾibrāhīma fī rabbihī ʾan ʾātāhu l-llāhu l-mulka ʾidh qāla ʾibrāhīmu rabbiyya lladhī yuḥyī wa-yumītu qāla ʾanā ʾuḥyī wa-ʾumītu qāla ʾibrāhīmu fa-ʾinna l-llāha yaʾtī bi-sh-shamsi mina l-mashriqi fa-ʾti bihā mina l-maghribi fa-buheta lladhī kafara wa-l-llāhu lā yahdī l-qawma ẓ-ẓālimīna', 'Kendisine Allah mülk verdi diye Rabbi hakkında (kendi kendine) tartışmaya giren kimseyi görmedin mi? Hani İbrahim: "Benim Rabbim hem diriltir hem de öldürür" deyince, o: "Ben de diriltir ve öldürürüm" demişti. İbrahim: "Allah güneşi doğudan getirmektedir, haydi sen de onu batıdan getir!" deyince, kâfir olan o kimse şaşıp kalmıştı. Allah, zâlimler topluluğunu doğru yola eriştirmez.'),
(2, 259, 3, 43, 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'aw kalladhī marra ʿalā qaryatin wa hiya khawiyatun ʿalā ʿurūshihā qāla annā yuḥyī hādhihi ʾallāhu baʿda mawtihā fa ʾamātahu ʾallāhu miʾata ʿāmin thumma baʿathahū qāla kam labithta qāla labithtu yawman ʾaw baʿḍa yawmin qāla bal labithta miʾata ʿāmin fa nẓur ʾilā ṭaʿāmika wa sharābika lam yatasannah wa nẓur ʾilā ḥimārika wa li najʿalaka ʾāyatan lilnāsi wa nẓur ʾilā l-ʿiẓāmi kayfa nunshizuhā thumma naksūhā laḥman fa lammā tabayyana lahū qāla ʾaʿlamu ʾanna ʾallāha ʿalā kulli shayʾin qadīrun', 'Yahut yanından geçmekte olduğu bir kasaba (hakkında): "Allah, bu kasabeyi ölümünden sonra nasıl diriltecek?" diyen kimse gibi (olduğunu düşün). Bunun üzerine Allah, o kimseyi yüz sene öldürdü, sonra onu diriltti. "Ne kadar kaldın?" dedi. "Bir gün yahut bir günden daha az bir zaman kaldım" dedi. Allah, "Hayır, yüz sene kaldın. Yiyeceğine ve içeceğine bak, hiç bozulmamış. Bir de eşeğine bak. (Bütün bunları) sana insanlara bir delil kılmak için (yaptık). Şimdi sen, o kemiklere bak, onları nasıl birleştiriyor, sonra onlara nasıl et giydiriyoruz." Bu, kendisine (olayın) iyice belli olunca, "Biliyorum, şüphesiz Allah her şeye gücü yetendir" dedi.'),
(2, 260, 3, 44, 'وَإِذْ قَالَ إِبْرَٰهِۦمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ قَالَ أَوَلَمْ تُؤْمِن قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'wa-ʾidh qāla ʾibrāhīmu rabbi ʾarinī kayfa tuḥyī l-mawtā qāla ʾa-wa-lam tuʾmin qāla balā wa-lākin li-yaṭmaʾinna qalbī qāla fa-khudh ʾarbaʿatan min aṭ-ṭayri fa-ṣurhunna ʾilayka thumma ʾjʿal ʿalā kulli jabalin minhunna juzʾan thumma dʿuhunna yaʾtīna-ka saʿyan wa-ʿlam ʾanna llāha ʿazīzun ḥakīmun', 'Hani İbrahim, "Rabbim! Ölüleri nasıl dirilttiğini bana göster," demişti. Allah, "İnanmıyor musun?" buyurunca, "Evet, inanıyorum, ama kalbimin tatmin olması için," dedi. "Öyleyse dört çeşit kuş yakala da onları kendine alıştır. Sonra onları (parçalayıp) her bir dağın üzerine birer parça bırak. Daha sonra da onları (kendiliğine) çağır. Sana koşarak geleceklerdir. Bil ki, Allah aziz ve hakîm''dir."'),
(2, 261, 3, 44, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'Mathalu allatheena yunfiqoona amwalahum fee sabeeli Allahi kamathali habbatin anbatat sab''a sanabila fee kulli sunbulatin mi''atu habbah Wa Allahu yudha''ifu liman yashaa'' Wa Allahu wasi''un ''aleem', 'Allah yolunda mallarını harcayanların durumu, her bir tohûmundan yedi başak bitiren ve her bir başakta yüz tane bulunan bir tohuma benzer. Allah dilediğine kat kat verir. Allah, lütfu geniş olan, her şeyi bilen''dir.'),
(2, 262, 3, 44, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'alladhīna yunfiqūna ʾamwālahum fī sabīli llāhi thumma lā yutbiʿūna mā ʾanfaqū mannan walā ʾadhan lahum ʾajruhum ʿinda rabbihim walā khawfun ʿalayhim walā hum yaḥzanon', 'Onlar ki mallarını Allah yolunda harcarlar, sonra da harcadıklarının peşinden (başa) kakma ve gönül yaralama gelmez. Onların Rableri katında mükâfatları vardır. Onlar için ne korku vardır ne de onlar hüzne kapılacaklardır.'),
(2, 263, 3, 44, 'قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى وَٱللَّهُ غَنِىٌّ حَلِيمٌ', 'qawlun maʿrūfun wa-maghfiratun khayrun min ṣadaqatin yatbaʿuhā ʾadhan wa-llāhu ghaniyyun ḥalīmun', 'Güzel söz ve bağışlama, peşinden incitme gelen bir sadakadan daha hayırlıdır. Allah zengindir, halimdir.'),
(2, 264, 3, 44, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'yā ayyuhā alladhīna āmanū lā tubṭilū ṣadaqātikum bil-manni wal-adhā kalladhī yunfiqu māluhū riʾāʾa an-nāsi walā yuʾminu billāhi wal-yawmi al-ʾākhiri famaṯaluhū kamaṯali ṣafwānin ʿalayhi turābun faʾaṣābahū wābilun fatarakahū ṣaldan lā yaqdirūna ʿalā shayʾin mimmā kasarū wallāhu lā yahdī al-qawma al-kāfirīna', 'Ey iman edenler! Sadakalarınızı, malını gösteriş için harcayan ve Allah’a ve ahiret gününe inanmayan kimse gibi, başa kakmak ve eziyet etmek suretiyle boşa çıkarmayın. Böyle kimsenin durumu, üzerinde biraz toprak bulunan ve üzerine sağanak yağmış da onu cilalı, pürüzsüz bir halde bırakmış olan bir kayanın durumu gibidir. Onlar, kazandıklarından hiçbir şeye sahip olamazlar. Allah kâfirler topluluğunu doğru yola eriştirmez.'),
(2, 265, 3, 45, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'wa-mathalu alladhīna yunfiqūna amwālahumu ibitighāʾa marḍāti Allāhi wa-tathbītan min anfusihim kamathali jannatin birabwatin aṣābahā wābilun fa-ātat ukulahā ḍiʿfayni fa-in lam yuṣibha wābilun fa-ṭallun wa-Allāhu bimā taʿmalūna baṣīrun', 'Allah''ın rızasını kazanmak ve kendi nefislerinde bir iman yerleştirmek için mallarını hayra sarf edenlerin durumu, bir tepenin üzerinde bulunan ve bol yağmur alan, bu yüzden de yemişlerini iki kat veren bir bahçenin durumu gibidir. Bol yağmur almasa bile, çiseleme (hafif yağmur) yeterlidir. Allah yaptıklarınızı görmektedir.'),
(2, 266, 3, 45, 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'ʾayawaddu ʾaḥadukum ʾan takūna lahu jannatun min nakhīlin wa-ʾaʿnābin tajrī min taḥtihā l-ʾanhāru lahu fīhā min kulli ʾth-thamarāti wa-ʾaṣābahu l-kibaru wa-lahu dhurriyyatun ḍuʿafāʾu fa-ʾaṣābahā ʿiṣārun fīhi nārun fa-ḥtaraqat kadhālika yubayyinullāhu lakumu l-ʾāyāti laʿallakum tatafakkarūna', 'Sizden biriniz, altından ırmaklar akan, içinde her çeşit meyvelerden bulunan hurma ve üzüm bağlarına sahip olmayı ister mi? Kendisi de yaşlı ve zayıf evlatlar bırakmışken, bağlarına ateşli bir kasırga isabet edip de yanıp kül olmasını ister mi? İşte Allah, düşünüp anlayasınız diye size ayetleri böyle açıklar.'),
(2, 267, 3, 45, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'yāʾayyuhā llaḏīna ʾāmanū ʾanfiqū min ṭayyibāti mā kasabtum wa-mimmā ʾaḵraǧnā lakum mina l-ʾarḍi wa-lā tayammmamū l-ḵabīṯa minhu tunfiqūna wa-lastum bi-ʾāḵiḏīhi ʾillā ʾan ṯuġmiḍū fīhi wa-ʿlamū ʾanna llāha ġaniyyun ḥamīd', 'Ey iman edenler! Kazandıklarınızın iyi olanlarından ve sizin için yerden çıkardığımız şeylerden (ürünlerden) harcayın. Kendinizin göz yummadan alamayacağınız bayağı şeyleri, hayır diye harcamaya kalkışmayın. Bilin ki Allah zengindir, her zaman övgüye layıktır.'),
(2, 268, 3, 45, 'ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'ash-shayṭānu yaʿidukum al-faqr wa yaʾmurukum bil-faḥshāʾ wallāhu yaʿidukum maghfiratan minhu wa faḍlan wallāhu wāsiʿun ʿalīm', 'Şeytan sizi fakirlikle korkutur ve size çirkin (utanmazlık) şeyleri emreder. Allah ise sizden mağfiret ve bol lütuf vaad etmektedir. Allah her şeyi kuşatan, her şeyi bilen''dir.'),
(2, 269, 3, 45, 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'yuʾtī l-ḥikmata man yašāʾu wa-man yuʾta l-ḥikmata fa-qad ūtīya ḵayran kaṯīran wa-mā yaḏḏakkaru ʾillā ʾulū l-ʾalbābi', 'Dilediğine hikmet verir. Kime hikmet verilirse, şüphesiz ona çok hayır verilmiş demektir. Bunu ancak akıl sahipleri düşünüp anlar.'),
(2, 270, 3, 46, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'wa mā ʾanfaqtum min nafaqatin ʾaw naḎartum min naḎrin fa-ʾinna ʾallāha yaʿlamuhū wa mā liẓ-ẓālimīna min ʾanṣārin', 'Her ne kadar nafaka harcarsanız veya adak adarsanız, şüphesiz Allah onu bilir. Zalimler için hiçbir yardımcı yoktur.'),
(2, 271, 3, 46, 'إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'in tubdū aṣ-ṣadaqāti fa niʿimmā hiya wa in tukhfūhā wa tuʾtūhā al-fuqaraʾa fa huwa khayrun lakum wa yukaffiru ʿankum min sayyiʾātikum wa-llāhu bimā taʿmalūna khabīr', 'Sadakaları açıkça verirseniz ne güzel! Fakat onları gizleyerek fakirlere verirseniz, bu sizin için daha hayırlıdır ve günahlarınızın bir kısmını örter. Allah yaptıklarınızdan haberdardır.'),
(2, 272, 3, 46, 'لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'laysa ʿalayka hudāhum walākinna Allāha yahdī man yašāʾu wamā tunfiqū min ḫayrin faliʾanfusikum wamā tunfiqūna ʾillā ʾibtiġāʾa wajhi Allāhi wamā tunfiqū min ḫayrin yuwaffa ʾilaykum waʾantum lā tuẓlamūna', 'Onları hidayete erdirmek sana düşmez. Allah dilediğini hidayete erdirir. Hayır olarak ne harcarsanız kendi iyiliğiniz içindir. Allah''ın vechini (rızasını) isteyerekten başka türlü harcamayın. Hayır olarak ne harcarsanız eksiksiz size ödenir ve siz asla haksızlığa uğramazsınız.'),
(2, 273, 3, 46, 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'lil-fuqarāʾi lladhīna uḥṣirū fī sabīli llāhi lā yastaṭīʿūna ḍarban fī l-arḍi yaḥsabuhumu l-jāhilu ʾaghnīyāʾa mina t-taʿaffufi taʿrifuhum bisīmāhum lā yasʾalūna n-nāsa ilḥāfan wa mā tunfiqū min khayrin fa-ʾinna llāha bihi ʿalīmun', 'O mallar, Allah yolunda (hizmet ve) alıkonulmuş, yeryüzünde (bir yere) gitmeye güç yetiremeyen yoksullar içindir. Onları (halden anlamayan) cahil kimse, iffetlerinden (veya istemekten çekinmelerinden) dolayı zengin sanır. Sen onları yüzlerinden tanırsın. İnsanlardan (hiçbir şey) isteyerek yüzsuyu dökmezler. Hayır olarak ne harcarsanız, şüphesiz Allah onu bilir.'),
(2, 274, 3, 46, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'alladhīna yunfiqūna amwālahum billayli wannahāri sirran waʿalāniyatan falahum ajruhum ʿinda rabbihim walā khawfun ʿalayhim walā hum yaḥzanūna', 'Mallarını gece ve gündüz, gizlice ve açıktan harcayanlar var ya, onların mükâfatları Rableri katındadır. Onlara korku yoktur ve onlar mahzun da olmayacaklardır.'),
(2, 275, 3, 47, 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'alladhīna yaʾkulūna r-ribā lā yaqūmūna ʾillā kamā yaqūmu lladhī yatakhabbaṭuhu sh-shayṭānu mina l-masse dhālika biʾannahum qālū ʾinnamā l-bayʿu mithlu r-ribā wa-aḥalla llāhu l-bayʿa wa-ḥarrāma r-ribā fa-man jāʾahū mawʿiẓatun min rabbihī fa-ntahā fa-lahū mā salafa wa-ʾamruhu ʾilā llāhi wa-man ʿāda fa-ʾulāʾika ʾaṣḥābu n-nāri hum fīhā khālidūna', 'Faiz yiyenler, (kabirlerinden) ancak şeytanın çarptığı kimsenin (akıl hastasının) kalktığı gibi kalkarlar. Bu, onların: "Alım satım da tıpkı faiz gibidir" demelerinden dolayıdır. Oysa Allah, alım satımı helâl, faizi ise haram kılmıştır. Bundan sonra kim kendisine Rabbinden bir öğüt gelip de faizden vazgeçerse, artık geçmişte aldıkları kendisinedir; durumu da Allah''a aittir. Kim de faize dönerse, işte onlar cehennemliktirler; orada ebedî kalırlar.'),
(2, 276, 3, 47, 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', 'yamḥaqu llāhu r-ribā wa yuribī ṣ-ṣadaqāti wa llāhu lā yuḥibbu kulla kaffārin ʾathīmin', 'Allah faizi mahveder, sadakaları bereketlendirir. Allah, günahkâr hiçbir kâfiri sevmez.'),
(2, 277, 3, 47, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ʾinna lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti wa ʾaqāmū ṣ-ṣalāta wa ʾātū z-zakāta lahum ʾajruhum ʿinda rabbihim wa lā khawfun ʿalayhim wa lā hum yaḥzanūna', 'Şüphesiz iman edip salih amel işleyenler, namazı dosdoğru kılan ve zekâtı verenler var ya, onlar için Rableri katında ecirleri vardır. Onlar için korku yoktur ve onlar mahzun da olmayacaklardır.'),
(2, 278, 3, 47, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 'yā ayyuhā alladhīna āmānū ittaqū allāha wa dhārū mā baqiya mina ar-ribā in kuntum muʾminīna', 'Ey iman edenler! Eğer inanmışsanız, Allah''tan korkun ve faizin geri kalanını bırakın.'),
(2, 279, 3, 47, 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', 'fa-in lam tafʿalū fa-ʾadhenū bi-ḥarbin mina ʾllāhi wa-rasūlihī wa-in tubtum fa-lakum ruʾūsu ʾamwālikum lā taẓlimūna wa-lā tuẓlamūna', 'Eğer (borçlarınızı) yapmazsanız, Allah ve Resûlü tarafından bir savaş ilân edildiğini bilin. Eğer tevbe ederseniz, sermayeleriniz sizindir. Ne zulmedersiniz ne de zulme uğrarsınız.'),
(2, 280, 3, 47, 'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'wa-ʾin kāna ḏū ʿusratin fa-naẓiratun ʾilā maysaratin wa-ʾan taṣaddaqū ḫayrun lakum ʾin kuntum taʿlamūn', 'Borçlu darlık içinde ise, ona eli rahatlayıncaya kadar bir süre tanıyın. Eğer borcu bağışlamanız sizin için daha hayırlıdır, eğer bilirseniz.'),
(2, 281, 3, 47, 'وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'wa-ttaqū yawman turjaʿūna fīhi ʾilā ʾllāhi thumma tuwaffā kullu nafsin mā kasabat wa-hum lā yuẓlamūna', 'Ve öyle bir günden sakının ki, o günde Allah''a döndürüleceksiniz. Sonra her nefis kazandığı şeyin karşılığını tam olarak alacak ve onlara haksızlık edilmeyecektir.'),
(2, 282, 3, 48, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَيُعَلِّمُكُمُ ٱللَّهُ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'Yā ʾayyuhā alladhīna ʾāmanū idhā tadāyantum bidainin ilā ʾajalin musamman faktubūhu walyaktub bainakum kātibun bilʿadli walā yaʾba kātibun an yaktuba kamā ʿallamahu Allāhu falyaktub walyumlili alladhī ʿalaihi alḥaqqu walyattaqi Allāha rabbahu walā yabkhas minhu shaiʾan faʾin kāna alladhī ʿalaihi alḥaqqu safīhan aw ḍaʿīfan aw lā yastaṭīʿu an yumilla huwa falyumlil waliyyuhu bilʿadli wastashhidū shahīdaini min rijālikum faʾin lam yakūnā rajulaini farajulun wa-imraʾatāni mimman tarḍawna mina ash-shuhadāʾi an taḍilla iḥdāhumā fatudhakkira iḥdāhumā al-ukhrā walā yaʾba ash-shuhadāʾu idhā mā duʿū walā tasʾamū an taktūbūhu ṣaghīran aw kabīran ilā ʾajalihi dhālikum aqsaṭu ʿinda Allāhi waʾaqwamu lilshshahādati waʾadnā allā tartābū illā an takūna tijāratan ḥāḍiratan tudīrūnahā bainakum falaisa ʿalaikum junāḥun allā taktūbūhā waʾashhidū idhā tabāyaʿtum walā yuḍārra kātibun walā shahīdun waʾin tafʿalū faʾinnahu fusūqun bikum wattaqū Allāha wayuʿallimukumu Allāhu waAllāhu bikulli shaiʾin ʿalīmun', 'Ey iman edenler! Belirli bir süreye kadar birbirinize borçlandığınız zaman onu yazın. Aranızda bir kâtip adaletle yazsın. Hiçbir kâtip, Allah''ın kendisine öğrettiği gibi yazmaktan çekinmesin, yazsın. Üzerinde hak olan (borçlu) da yazdırsın ve Rabbi olan Allah''tan korksun da borcundan hiçbir şeyi eksiltmesin. Eğer üzerinde hak olan (borçlu) akılca zayıf veya güçsüz ya da kendisi yazdıramayacak durumda ise, velisi adaletle yazdırsın. Erkeklerinizden iki şahit tutun. Eğer iki erkek bulunamazsa, razı olacağınız şahitlerden bir erkek ve iki kadın (şahitlik etsin). Böylece kadınlardan biri şaşırırsa, diğeri ona hatırlatsın. Şahitler çağrıldıkları zaman (şahitlikten) kaçınmasınlar. Borcu az olsun çok olsun, süresine kadar yazmaktan üşenmeyin. Bu, Allah katında daha adil, şahitlik için daha sağlam ve şüpheye düşmemeniz için daha uygun bir yoldur. Ancak aranızda elden ele dönen peşin bir ticaret olursa, onu yazmamanızda size bir günah yoktur. Alışveriş yaptığınız zaman da şahit tutun. Ne kâtip ne de şahit zarar görmesin. Eğer zarar verirseniz, şüphesiz bu sizin için bir fâsıklıktır. Allah''tan korkun. Allah size öğretiyor. Allah her şeyi hakkıyla bilendir.'),
(2, 283, 3, 49, 'وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَٰنٌ مَّقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', 'wa-in kuntum ʿalā safarin wa-lam tajidū kātiban fa-rahānun maqbūḍah fa-in amina baʿḍukum baʿḍan fa-l-yuʾaddi alladhī ʾutumina amānatahū wa-l-yattaqi Allāha rabbahū wa-lā taktumu ash-shahādah wa-man yaktumhā fa-innahu ʾāthimun qalbuhū wa-Allāhu bimā taʿmalūna ʿalīm', 'Eğer yolculuk halinde olur da bir katip bulamazsanız, o zaman (borçlu) rehin alsın. Eğer birbirinize güvenirseniz, kendisine güvenilen kimse emanetini ödesin ve Rabb''i olan Allah''tan korksun. Şahitliği gizlemeyin. Kim onu gizlerse, şüphesiz onun kalbi günahkârdır. Allah yaptıklarınızı bilendir.'),
(2, 284, 3, 49, 'لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'lillāhi mā fī s-samāwāti wa mā fī l-arḍi wa in tubdū mā fī ʾanfusikum ʾaw tukhfūhu yuḥāsubkum bihi l-lāhu fa-yaghfiru liman yashāʾu wa yuʿaḏḏibu man yashāʾu wa-llāhu ʿalā kulli shayʾin qadīrun', 'Göklerde ve yerde ne varsa hepsi Allah''ındır. İçinizdekini açığa vursanız da, gizleseniz de Allah sizi (onunla) hesaba çeker. Sonra dilediğini bağışlar, dilediğine de azap eder. Allah her şeye hakkıyla kadirdir.'),
(2, 285, 3, 49, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'āmana r-rasūlu bimā unzila ilayhi min rabbihī wa-l-muʾminūn kullun āmana bi-llāhi wa-malāʾikatihī wa-kutubihī wa-rusulihī lā nufarriqu bayna ʾaḥadin min rusulihī wa-qālū samiʿnā wa-ʾaṭaʿnā ġufrānaka rabbanā wa-ʾilayka l-maṣīr', 'Peygamber, Rabbinden ona indirilene iman etti, mü''minler de. Hepsi Allah''a, meleklerine, kitaplarına ve peygamberlerine iman ettiler. "O''nun peygamberlerinden hiçbirini ayırmayız" dediler ve "İşittik, itaat ettik. Ey Rabbimiz! Senden bağışlama dileriz. Sonunda dönüş yalnız sanadır" dediler.'),
(2, 286, 3, 49, 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'lā yukallifu ʾllāhu nafsan ʾillā wusʿahā lahā mā kasabat wa ʿalayhā mā ʾktasabat rabbanā lā tuʾākhidhnā ʾin nasīnā ʾaw ʾakhṭaʾnā rabbanā walā taḥmil ʿalaynā ʾiṣran kamā ḥamaltahū ʿalā ʾlladhīna min qablinā rabbanā walā tuḥammilnā mā lā ṭāqata lanā bihī wa-ʿfu ʿannā wa-ghfir lanā warḥamnā ʾanta mawlānā fa-nṣurnā ʿalā ʾl-qawmi ʾl-kāfirīn', 'Allah kimseyi gücünün yetmediğinden sorumlu tutmaz. Herkesin kazandığı iyilik kendi lehine, kötülük de kendi aleyhinedir. Rabbimiz! Unutacak veya hata yapacak olursak bizi sorumlu tutma. Rabbimiz! Bize, bizden öncekilere yüklediğin gibi ağır bir yük yükleme. Rabbimiz! Bize gücümüzün yetmediği şeyleri yükleme! Bizi bağışla, kusurlarımızı ört ve bize merhamet et! Sen bizim Mevlâmızsın. Kâfirler topluluğuna karşı bize yardım et!'),
(3, 1, 3, 50, 'الٓمٓ', 'ʾalif-lām-mīm', 'Elif, Lâm, Mim.'),
(3, 2, 3, 50, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', 'Allāhu lā ilāha illā huve''l-ḥayyu''l-kayyūm(u)', 'Allah, O''ndan başka ilah yoktur; O, daima diridir, her şeyin varlığı O''na bağlı ve dayalıdır.'),
(3, 3, 3, 50, 'نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'nazzala ʿalayka l-kitāba bil-ḥaqqi muṣaddiqan limā bayna yadayhi wa-anzala t-tawrāta wal-ʾinjīla', 'O, sana Kitab''ı hak olarak indirdi; bu, ondan önce indirilenleri doğrulayıcıdır. Daha önce de Tevrat''ı ve İncil''i indirmişti.'),
(3, 4, 3, 50, 'مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'min qablu hudan linnāsi wa anzala l-furqāna inna lladhīna kafarū bi-āyāti llāhi lahum ʿadhābun shadīdun wa llāhu ʿazīzun dhū intiqāmin', 'Bundan önce insanlara bir yol gösterici olarak ve (hak ile batılı) ayıran (hükümleri) indirmiştir. Şüphesiz Allah''ın ayetlerini inkâr edenler için çetin bir azap vardır. Allah, mutlak güç sahibi ve intikam sahibidir.'),
(3, 5, 3, 50, 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'ʾinna ʾallāha lā yakhfā ʿalayhi shayʾun fī l-ʾarḍi walā fī s-samāʾi', 'Şüphesiz Allah, yerde ve gökte hiçbir şeyden gizli değildir.'),
(3, 6, 3, 50, 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'huwa lladhī yuṣawwirukum fī l-arḥāmi kayfa yashāʾu lā ilāha illā huwa l-ʿazīzu l-ḥakīmu', 'O, sizi rahimlerde dilediği gibi şekillendirendir. O’ndan başka ilah yoktur; O, mutlak güç sahibidir, hüküm ve hikmet sahibidir.'),
(3, 7, 3, 50, 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'huwa alladhī ʾanzala ʿalayka l-kitāba minhu ʾāyātun muḥkamātun hunna ʾummu l-kitābi wa ʾukharu mutashābihātun fa ʾammā alladhīna fī qulūbihim zayghun fa yattabiʿūna mā tashābaha minhu ʾibtiġāʾa l-fitnati wa ʾibtiġāʾa taʾwīlihī wa mā yaʿlamu taʾwīlahū ʾillā ʾallāhu wa r-rāsiḫūna fī l-ʿilmi yaqūlūna ʾāmannā bihi kullun min ʿindi rabbinā wa mā yadhdhakkaru ʾillā ʾūlū l-ʾalbābi', 'O, sana Kitab''ı indiren O''dur. Onun bir kısmı, ''Kitab''ın anası'' (temel esasları) olan muhkem (anlamı açık) ayetlerdir. Diğerleri ise müteşabih (tevil götürür) ayetlerdir. Kalplerinde eğrilik olanlar, fitne çıkarmak ve onu (kendi arzularına göre) tevil etmek için müteşabih olanlarına uyarlar. Oysa onun tevilini ancak Allah ve ilimde derinleşmiş olanlar bilir. ''Ona inandık, hepsi Rabbimizdendir'' derler. (Bu inceliği) ancak akıl sahipleri düşünüp anlar.'),
(3, 8, 3, 50, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'Rabbanā lā tużiġ qulūbanā baʿda iẓ hadaytanā Wehab lanā min ladunka raḥmah Innaka anta l-Wahhāb', 'Rabbimiz! Bizi doğru yola ilettikten sonra kalplerimizi eğriltme. Bize tarafından bir rahmet ihsan et. Şüphesiz sen, çok bahşedensin.'),
(3, 9, 3, 50, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'Rabbena inneke cami''u an-nasi li-yawmin la rayba fihi Innallaha la yuhlifu al-mi''ad', 'Ey Rabbimiz! Şüphesiz Sen, toplanılmasında şüphe olmayan bir günde insanları bir araya getireceksin. Şüphesiz Allah va''dinden dönmez.'),
(3, 10, 3, 51, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', 'ʾinna alladhīna kafarū lan tughniya ʿanhum ʾamwāluhum walā ʾawlāduhum mina Allāhi shayʾan wa ʾulāʾika hum waqūdu an-nār', 'Şüphesiz inkâr edenlerin malları ve evlatları, kendilerini Allah''tan (gelecek) hiçbir şeye karşı asla bî-gâne yapamaz. Onlar cehennemin odunlarıdır.'),
(3, 11, 3, 51, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'kad''aabi aali fir''awna wa-llazeena min qablihim kaz''zaboo bi-aayaatinaa fa-a''khazehumu l-laahu bi-zunoo''bihim wa-l-laahu shadeedu l-''iqaab', 'Onların durumu, tıpkı Firavun ailesinin ve onlardan öncekilerin durumu gibidir. Ayetlerimizi yalanladılar da Allah onları günahları yüzünden yakalayıverdi. Allah''ın azabı çetindir.'),
(3, 12, 3, 51, 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ وَبِئْسَ ٱلْمِهَادُ', 'qul lilladhīna kafarū satughlabūna wa tuḥsharūna ilā jahannama wa biʾsa l-mihādu', 'De ki: "İnkâr edenlere: Siz yenilgiye uğrayacaksınız ve cehenneme toplanacaksınız. Ne kötü bir varış yeridir!"'),
(3, 13, 3, 51, 'قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا فِئَةٌ تُقَٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'qad kāna lakum ʾāyāh fī fiʾatayni ltaqatā fiʾah tuqātilu fī sabīli llāh wa ʾuḵrā kāfirah yarawnahum miṯlayhim raʾya l-ʿayni wa llāhu yuʾayyidu binaṣrihī man yašāʾu ʾinna fī dhālika laʿibrah liʾūlī l-ʾabṣāri', 'Gerçek şu ki, iki topluluğun karşılaştığı (Bedir''de) sizin için bir ibret vardır. Biri Allah yolunda savaşanlar, diğeri ise kâfirlerdi. Onlar (müminler) ise, gözle gördükleri kadar kendilerinin iki katı kadar (düşman) görüyorlardı. Allah, dilediğini yardımıyla destekler. Şüphesiz bunda basiret sahipleri için bir ibret vardır.'),
(3, 14, 3, 51, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَٰمِ وَٱلْحَرْثِ ذَٰلِكَ مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', 'zuyyina lil-nāsi ḥubbu l-shahawāti mina l-nisāʾi wa-l-banīna wa-l-qanāṭīri l-muqanṭarati mina l-dhahabi wa-l-fiḍḍati wa-l-khayli l-musawwamati wa-l-anʿāmi wa-l-ḥarthi dhālika matāʿu l-ḥayāti l-dunyā wa-llāhu ʿindahu ḥusnu l-maʾābi', 'Kadınlar, oğullar, yığın yığın biriktirilmiş altın ve gümüş, salma atlar, (ve) çiftlik hayvanları ve ekinler gibi şehvet düşkünlüğünün çekici gelmesi insanlara süslendi. Bunlar, dünya hayatının geçici bir metaıdır. Allah''ın yanında ise O''nun katında güzel bir dönüş yeri vardır.'),
(3, 15, 3, 51, 'قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 'Qul aʾunabbiʾukum bi-khayrin min dhālikum Lilladhīna-ttaqaw ʿinda Rabbihim jannātun tajrī min taḥtihā-l-anhāru khālidīna fīhā Wa-azwājun muṭahharatun Wa-riḍwānun mina-llāhi Wa-llāhu baṣīrun bi-l-ʿibād', 'De ki: "Size bundan daha hayırlısını bildireyim mi? Takva sahipleri için Rablerinin katında, altlarından ırmaklar akan, içinde ebedi kalacakları, tertemiz zevceler ve Allah''ın rızası vardır. Allah kulları hakkıyla görmektedir."'),
(3, 16, 3, 52, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', 'alladhīna yaqūlūna rabbana ʾinnanā ʾāmannā fāghfir lanā dhunūbanā waqina ʿadhāba n-nār', 'Onlar: ''Rabbimiz! İman ettik, onun için günahlarımızı bağışla ve bizi ateş azabından koru'' diyenlerdir.'),
(3, 17, 3, 52, 'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلْقَٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', 'aṣ-ṣābirīna waṣ-ṣādiqīna wal-qānitīna wal-munfiqīna wal-mustaġfirīna bil-ʾasḥār', 'Onlar, sabredenler, doğru söyleyenler, itaat edenler, harcayanlar ve seher vakitlerinde bağışlanma dileyenlerdir.'),
(3, 18, 3, 52, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'shahida allahu annahu la ilaha illa huwa wa al-mala''ikatu wa ulu al-''ilmi qa''iman bil-qisti la ilaha illa huwa al-''azizu al-hakimu', 'Allah, melekler ve ilim sahipleri, adaletle şahitlik ederek, O''ndan başka ilah olmadığına delalet ettiler. O, mutlak güç sahibi, hüküm ve hikmet sahibidir.'),
(3, 19, 3, 52, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'ʾinna d-dīna ʿinda llāhi l-ʾislāmu wa mā ʾxtalafa lladhīna ʾūtū l-kitāba ʾillā min baʿdi mā jāʾahumu l-ʿilmu baghyan baynahum wa man yakfur bi-ʾāyāti llāhi fa-ʾinna llāha sarīʿu l-ḥisābi', 'Şüphesiz Allah katında din, İslâm''dır. Kitap verilenler, kendilerine ilim geldikten sonra, aralarındaki kıskançlık yüzünden ayrılığa düştüler. Kim Allah''ın âyetlerini inkâr ederse, bilsin ki Allah, hesabı çabuk görendir.'),
(3, 20, 3, 52, 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْأُمِّيِّۦنَ ءَأَسْلَمْتُمْ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 'fa-in ḥājjūka faqul aslamtu wajhiya lillāhi wa mani-ttabaʿani wa qul lilladhīna ūtū l-kitāba wal-ummiyyīna ʾaslamtum fa-in ʾaslamū faqadi-htadaw wa-in tawallaw fa-innamā ʿalayka l-balāghu wallāhu baṣīrun bil-ʿibādi', 'Eğer sana karşı tartışmaya girerlerse, de ki: "Ben yüzümü Allah''a teslim ettim ve bana uyanlar da." Ve kitap verilenlere ve ümmîlere de ki: "Siz de İslam''a girin." Eğer İslam''a girerlerse doğru yolu bulmuş olurlar. Eğer yüz çevirirlerse, bil ki sana düşen sadece tebliğdir. Allah kullarını hakkıyla görmektedir.'),
(3, 21, 3, 52, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'ʾinna llaḏīna yakfurūna bi-ʾāyāti l-lāhi wa-yaqtulūna n-nabiyyiyna bi-ġayri ḥaqqin wa-yaqtulūna llaḏīna ʾamurūna bil-qisṭi mina n-nāsi fa-bašširhum bi-ʿaḏābin ʾalīmin', 'Şüphesiz Allah''ın ayetlerini inkâr edenler, peygamberleri haksız yere öldürenler ve insanlardan adaleti emredenleri öldürenler var ya, onlara elem dolu bir azabı müjdele.'),
(3, 22, 3, 52, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'ʾūlāʾika lladhīna ḥabiṭat ʾaʿmāluhum fī d-dunyā wa-l-ʾākhirati wa-mā lahum min nāṣirīna', 'İşte onlar, dünyada ve ahirette amelleri boşa giden kimselerdir. Onların hiçbir yardımcıları da yoktur.'),
(3, 23, 3, 53, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ', 'ʾalam tara ʾilā alladhīna ʾūtū naṣīban min al-kitābi yudʿawna ʾilā kitābi allāhi liyaḥkuma baynahum thumma yatawallā farīqun minhum wa hum muʿriḍūna', 'Kitaptan kendilerine bir pay verilenleri görmedin mi? Aralarında hükmetmesi için Allah''ın Kitabı''na çağrılıyorlar da sonra içlerinden bir grup yüz çeviriyor ve onlar dönüp gidiyorlar.'),
(3, 24, 3, 53, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', 'dhālika bi-ʾannahum qālū lan tamassana ʾn-nāru ʾillā ʾayyāman maʿdūdātin wa-gharrhum fī dīnihim mā kānū yaftarūna', 'Bu, onların: ''Sayılı birkaç gün dışında bize asla ateş dokunmayacaktır'' demelerinden ve uydurmakta oldukları şeyler yüzünden dinleri konusunda kendilerini aldatmalarından ötürüdür.'),
(3, 25, 3, 53, 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'fakayfa iḏā ǧamaʿnāhum liyawmin lā rayba fīhi wawuffiyat kullu nafsin mā kasabat wahum lā yuẓlamūn', 'Peki, kendisinde şüphe olmayan o gün kendilerini topladığımızda ve her nefis kazandığını eksiksiz aldığında ve onlara haksızlık edilmediğinde durumları nasıl olacak?'),
(3, 26, 3, 53, 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'qulillāhumma mālika l-mulki tuʾtī l-mulka man tašāʾu wa tanziʿu l-mulka mimman tašāʾu wa tuʿizzu man tašāʾu wa tuḏillu man tašāʾu biyadika l-ḫayru ʾinnaka ʿalā kulli šayʾin qadīrun', 'De ki: "Ey Allahım! Mülkün sahibi sensin. Sen mülkü dilediğine verir, dilediğinden de çeker alırsın. Dilediğini aziz eder, dilediğini de zelil edersin. Bütün hayır (iyilik ve güzellikler) senin elindedir. Şüphesiz sen her şeye hakkıyla kadirsin."'),
(3, 27, 3, 53, 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ', 'tūliju l-layla fī n-nahāri wa tūliju n-nahāra fī l-layli wa tukhriju l-ḥayya mina l-mayyiti wa tukhriju l-mayyita mina l-ḥayyi wa tarzuqu man tashāʾu bi-ghayri ḥisābin', 'Geceyi gündüze sokarsın, gündüzü de geceye sokarsın. Ölüden diri çıkarırsın, diriden de ölü çıkarırsın. Ve dilediğini hesapsız rızıklandırırsın.'),
(3, 28, 3, 53, 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'lā yattakhidhi l-muʾminūna l-kāfirīna ʾawliyāʾa min dūni l-muʾminīn wa man yafʿal dhālika falaysa mina llāhi fī shayʾin ʾillā ʾan tattaqū minhum tuqātan wa yuḥadhdhirukumu llāhu nafsahū wa ʾilā llāhi l-maṣīr', 'Mü''minler, mü''minleri bırakıp kâfirleri dost edinmesinler. Kim böyle yaparsa, artık Allah''tan bir şey (yardım, dostluk) kalmamış olur. Ancak onlardan (kâfirlerden) korunmak için böyle yapmanız müstesnadır. Allah, sizi kendisinden sakındırır. Dönüş Allah''adır.'),
(3, 29, 3, 53, 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'qul in tukhfū mā fī ṣudūrikum aw tubdūhu yaʿlamhu ʾallāhu wa yaʿlamu mā fī s-samāwāti wa mā fī l-ʾarḍi wa ʾallāhu ʿalā kulli shayʾin qadīrun', 'De ki: "Gönüllerinizdekini gizleseniz de, açıklasanız da Allah onu bilir. O, göklerde olanı da, yerde olanı da bilir. Allah her şeye hakkıyla kadirdir."'),
(3, 30, 3, 54, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'Yawma tajidu kullu nafsin ma ''amilat min khayrin muhdaran Wa ma ''amilat min soo''in Tawaddu law anna baynaha wa baynahu amadan ba''eedan Wa yuhadhirukumu Allahu nafsahu Wallahu ra''oofun bil-''ibad', 'O gün her nefis, ne hayır ne de şer işlemişse hepsini hazır bulur. Ve onlar, keşke kendisiyle onun arasında uzak bir mesafe olsaydı, isterler. Allah sizi Kendisinden korkmaya davet eder. Allah kullarına çok şefkatlidir.'),
(3, 31, 3, 54, 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'Qul in kuntum tuḥibbūna Allāha fattabiʿūnī yuḥbibkumullāhu wa yaghfir lakum dhunūbakum Wa-Allāhu ghafūrun raḥīm', 'De ki: Eğer Allah''ı seviyorsanız bana uyun; Allah da sizi sevsin ve günahlarınızı bağışlasın. Allah çok bağışlayıcı, çok merhamet edicidir.'),
(3, 32, 3, 54, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 'Qul aṭīʿū Allāha wa-r-rasūla Fa-in tawallaw Fa-inna Allāha lā yuḥibbu l-kāfirīn', 'De ki: Allah''a ve Peygamber''e itaat edin. Eğer yüz çevirirseniz, bilin ki Allah kâfirleri sevmez.'),
(3, 33, 3, 54, 'إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ', 'ʾinna-llāha-ṣṭafā ʾādama wa-nūḥan wa-ʾāla ʾibrāhīma wa-ʾāla ʿimrāna ʿalā-l-ʿālamīn', 'Şüphesiz Allah, Âdem''i, Nuh''u, İbrahim ailesini ve İmran ailesini (diğer) alemlere üstün kıldı.'),
(3, 34, 3, 54, 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'dhurriyyatan ba''duha mim ba''din wallahu sami''un ''alim', 'Onlar, birbirinin soyundan gelen bir zürriyettir. Allah, her şeyi işiten, her şeyi bilen demektir.'),
(3, 35, 3, 54, 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'iḏ qālat i mraʾatu ʿimrāna rabbī innī naḏartu laka mā fī baṭnī muḥarraran fataqabbal minnī innaka anta s-samīʿu l-ʿalīmu', 'Hani İmran''ın karısı demişti ki: "Rabbim! Karnımdakini azatlı bir kul olarak sana adadım. Adağımı kabul buyur. Şüphesiz sen, hakkıyla bilen, kemaliyle duyan sensin."'),
(3, 36, 3, 54, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'fe-lem-mā wa-ḍaʿat-hā qa-lat rab-bi in-nī wa-ḍaʿ-tu-hā un-thā wa-l-lā-hu aʿ-la-mu bi-mā wa-ḍaʿat wa-lay-sa al-ththa-ka-ru ka-l-un-thā wa in-nī sam-may-tu-hā Mar-yam wa in-nī uʿī-thu-hā bi-ka wa-thu-riy-ya-ta-hā min al-shay-ṭā-ni al-ra-jīm', 'Onu doğurunca, şöyle dedi: Rabbim! Ben onu kız olarak doğurdum. Allah ise onun ne doğurduğunu daha iyi bilir. Erkek, kız gibi değildir. Ben ona Meryem adını verdim. Ve ben, onu ve soyunu o recîm (kovulmuş) şeytandan senin hıfzına/korumana/sığınmasına emanet ediyorum.'),
(3, 37, 3, 54, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'Fetakabbelahā rabbuhā bikabūlin ḥasanin Ve enbet''ehā nebātan ḥasanan Ve keffelehā Zekeriyyā Kullamā dakhala ʿalayhā Zekeriyyā l-miḥrāba wajada ʿindahā rizqan Qāla yā Maryamu annā laki hādhā Qālat huwa min ʿindi Llāhi ʾInna Llāha yarzuqu man yashāʾu bi-ghayri ḥisābin', 'Böylece Rabbi onu güzel bir kabulle kabul etti ve onu güzel bir şekilde yetiştirdi. Zekeriya''yı da onunla O ilgilendi. Zekeriya ne zaman onun yanına, mîraba girdiyse, onun yanında bir yiyecek buldu. "Ey Meryem! Bu senin için nereden geldi?" dedi. Meryem de: "O, Allah tarafındandır. Şüphesiz Allah, dilediği kimseyi hesapsız rızıklandırır" dedi.'),
(3, 38, 3, 55, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 'hunālika daʿā zakariyyā rabbahū qāla rabbī hab lī min ladunka dhurriyyatan ṭayyibatan ʾinnaka samīʿu d-duʿāʾi', 'İşte orada Zekeriya Rabbine dua etti: "Rabbim! Bana tarafından temiz bir soy ver. Şüphesiz Sen duayı hakkıyla işitensin."'),
(3, 39, 3, 55, 'فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّٰلِحِينَ', 'fanādathu al-malāʾikatu wa-huwa qāʾimun yuṣallī fī al-miḥrābi anna Allāha yubashshiruka bi-Yaḥyā muṣaddiqan bi-kalimatin mina Allāhi wa-sayyidan wa-ḥaṣūran wa-nabiyyan mina al-ṣāliḥīna', 'Derken melekler ona, mabedde namaz kılarken şöyle seslendi: Allah sana, Allah''tan bir kelimeyi doğrulayan, aynı zamanda efendi, iffetli ve salihlerden bir peygamber olan Yahya''yı müjdeler.'),
(3, 40, 3, 55, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', 'qāla rabbi annā yakūnu lī ġulāmun waqad balaganī al-kibaru wamraʾatī ʿāqirun qāla kaḏālika ʾallāhu yafʿalu mā yašāʾu', 'Dedi ki: "Rabbim! Bana yaşlılık gelmişken ve karım da kısır iken benim nasıl çocuğum olabilir? Allah dilediğini yapar."'),
(3, 41, 3, 55, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًا وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'qāla rabbi-jʿal lī ʾāyatan qāla ʾāyatuka ʾallā tukallima n-nāsa thalāthata ʾayyāmin ʾillā ramzan wa-dhkur rabbaka kathīran wa-sabbih bi-l-ʿashiyyi wa-l-ʾibkāri', 'O dedi ki: Rabbim! Bana bir alâmet (işaret) ver. Allah buyurdu ki: Senin alâmetin, insanlarla üç gün, (dili tutulmuş gibi) konuşamaman olacak. Ancak işaretle (ima ile) konuşabileceksin. Rabbini çok zikret ve akşam-sabah tesbih et.'),
(3, 42, 3, 55, 'وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ', 'wa-idh qālat-i l-malāʾikatu yā-maryamu ʾinna-llāha-ṣṭafāki wa-ṭahharaki wa-ṣṭafāki ʿalā nisāʾi l-ʿālamīna', 'Hani melekler şöyle demişti: "Ey Meryem! Allah seni seçti, seni tertemiz yarattı ve seni dünya kadınlarının üstüne seçti."'),
(3, 43, 3, 55, 'يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', 'yā maryamu ʾqnutī lirabbiki wasjudī warkʿī maʿa r-rākiʿīn', 'Ey Meryem! Rabbine itaat et, secde et ve rüku edenlerle birlikte rüku''a var.'),
(3, 44, 3, 55, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', 'dhālika min anbāʾi l-ghaybi nūḥīhi ilayka wa mā kunta ladayhim idh yulqūna aqlāmahum ayyuhum yakfulu Maryama wa mā kunta ladayhim idh yakhtaṣimūn', 'İşte bunlar, sana vahyettiğimiz gayb (gizli) haberlerindendir. Onlar, kalemlerini atıp da hangisinin Meryem''i himayesine alacağı hususunda kur''a çekerlerken sen yanlarında değildin. Onlar çekişirlerken de yanlarında değildin.'),
(3, 45, 3, 55, 'إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', 'idh qālati l-malāʾikatu yāmaryamu ʾinna llāha yubashshiruki bikalimatin minhu ʾismuhu l-masīḥu ʿīsā bnu maryama wajīhan fī d-dunyā wa-l-ʾākhirati wa-mina l-muqarrabīna', 'Hani melekler şöyle demişti: ''Ey Meryem! Allah seni, kendisi tarafından bir kelime ile müjdeliyor. Adı Meryem oğlu İsa''dır. Kendisi dünyada ve ahirette itibarlı ve (Allah''a) yakın olanlardandır.'''),
(3, 46, 3, 56, 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّٰلِحِينَ', 'wayukallimu n-nāsa fī l-mahdi wa kahlā wa mina ṣ-ṣāliḥīna', 'İnsanlarla beşikte iken de, yetişkinken de konuşacaktır. Ve salihlerden olacaktır.'),
(3, 47, 3, 56, 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'qālat rabbi annā yakūnu lī waladun wa-lam yamsasnī basharun qāla kadhālikillāhu yakhluqu mā yashāʾu idhā qaḍā ʾamran fa-innamā yaqūlu lahū kun fa-yakūnu', '“Rabbim! Bana bir beşer dokunmamışken benim çocuğum nasıl olabilir?” dedi. Allah, “İşte böyledir; Allah dilediğini yaratır. Bir şeye hükmettiği zaman, ona sadece ‘Ol!’ der, o da oluverir.” buyurdu.'),
(3, 48, 3, 56, 'وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'wa yuʿallimuhu l-kitāba wa-l-ḥikmata wa-t-tawrāta wa-l-injīla', 'Ve ona Kitab''ı, hikmeti, Tevrat''ı ve İncil''i öğretecektir.'),
(3, 49, 3, 56, 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ إِنَّ فِى ذَٰلِكَ لَءَايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'wa rasūlan ilā banī isrāʾīla annī qad jiʾtukum bi-āyatin min rabbikum annī ʾakhluqu lakum mina ṭ-ṭīni ka-hayʾati ṭ-ṭayri fa-ʾanfukhu fīhi fa-yakūnu ṭayran bi-ʾidhni llāhi wa ʾubriʾu l-ʾakmaha wa l-ʾabraṣa wa ʾuḥyī l-mawtā bi-ʾidhni llāhi wa ʾunabbiʾukum bimā taʾkulūna wa mā taddakhirūna fī buyūtikum ʾinna fī dhālika la-ʾāyatan lakum ʾin kuntum muʾminīna', 'Ve İsrailoğullarına da (şöyle diyen) bir resul (göndereceğim): ''Şüphesiz ben, Rabbimden (gelen) bir ayetle size geldim. Ben size çamurdan kuş örneği yapar, ona üflerim ve Allah''ın izniyle o kuş olur. Yine Allah''ın izniyle anadan doğma körleri ve abraş hastalarını iyileştirir, ölüleri diriltirim. Evlerinizde yediklerinizi ve biriktirdiklerinizi de size haber veririm. Elbette bunlarda, eğer inanmış kimselerseniz sizin için bir ayet (delil) vardır.'''),
(3, 50, 3, 56, 'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'wa muṣaddiqan limā bayna yadayya mina t-tawrāti wa liʾuḥilla lakum baʿḍa l-ladhī ḥurrimʿalaykum wa jiʾtukum biʾāyatin min rabbikum fattaqū l-lāha wa ʾaṭīʿūn', 'Ve önümdeki Tevrat''ı tasdik edici ve size haram kılınan bazı şeyleri helal etmek için (geldim) ve size Rabb''inizden bir ayet getirdim. Artık Allah''tan korkun ve bana itaat edin.'),
(3, 51, 3, 56, 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'ʾinna Allāha rabbī wa rabbukum fa-ʿbudūhu hādhā ṣirāṭun mustaqīm', 'Şüphesiz Allah benim de Rabbim, sizin de Rabbinizdir. O halde yalnız O''na kulluk edin. İşte dosdoğru yol budur.'),
(3, 52, 3, 56, 'فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', 'fe-lemmā ʾaḥassa ʿīsā min-humu l-kufra qāla man ʾanṣārī ʾilā llāhi qāla l-ḥawāriyyūna naḥnu ʾanṣāru llāhi ʾāmannā bi-llāhi wa-šhad bi-ʾannanā muslimūna', 'İsa onların küfrünü sezince, "Allah yolunda bana yardımcı olacak kimdir?" dedi. Havariler, "Allah yolunda yardımcılar biziz! Allah''a iman ettik. Şahit ol ki biz Müslümanlarız!" dediler.'),
(3, 53, 3, 57, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 'Rabbanā āmannā bimā anzalta Wattabaʿnā ar-rasūla Faktubnā maʿa ash-shāhidīn', 'Rabbimiz! İndirdiğin (mesaj)a inandık ve Resûl''e uyduk. Artık bizi (hakikate) şahitlik edenlerle birlikte yaz.'),
(3, 54, 3, 57, 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'wa makarū wa makara Allāhu wa Allāhu khayru l-mākirīn', 'Onlar tuzak kurdular. Allah da onlara tuzak kurdu. Allah tuzak kuranların en iyisidir.'),
(3, 55, 3, 57, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'idh qala allahu ya ''isa inni mutawaffika wa rafi''uka ilayya wa mutahhiruka minal ladhina kafaroo wa ja''ilul ladhina ittaba''ooka fawqal ladhina kafaroo ila yawmil qiyamah thumma ilayya marji''ukum fa ahkumu baynakum fima kuntum feehi takhtalifoon', 'Hani Allah, "Ey İsa! Ben senin ecelini dolduracak, seni nezdime yüceltecek, seni inkârcılardan temizleyecek ve sana uyanları kıyamete kadar küfredenlerin üstüne çıkaracak olanım. Sonra dönüşünüz yalnız banadır. Ayrılığa düştüğünüz hususlarda aranızda ben hükmedeceğim" dedi.'),
(3, 56, 3, 57, 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'faʾammā alladhīna kafarū faʾuʿadhdhibuhum ʿadhāban shadīdan fī d-dunyā wa-l-ʾākhirati wa mā lahum min nāṣirīn', 'İnkâr edenlere gelince, onları dünyada da ahirette de şiddetli bir azapla cezalandıracağım. Onların hiçbir yardımcıları da yoktur.'),
(3, 57, 3, 57, 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'waʾammā alladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti fayuwaffīhim ʾujūrahum wa-llāhu lā yuḥibbu ẓ-ẓālimīna', 'İman edip salih amel işleyenlere gelince, Allah onların ecirlerini eksiksiz ödeyecektir. Allah zalimleri sevmez.'),
(3, 58, 3, 57, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْءَايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', 'dhālika natlūhu ʿalayka mina l-ʾāyāti wa-dh-dhikri l-ḥakīm', 'Bu, sana okuduğumuz ayetlerden ve hikmet dolu zikirden (Kur''an''dan) ibarettir.'),
(3, 59, 3, 57, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', 'İnne mesele ‘Îsâ ‘indallâhi kemeseli Âdeme ḫaleḳahû min turâbin śümme ḳâle lehû kün feyekûnü', 'Şüphesiz Allah katında İsa''nın durumu, Âdem''in durumu gibidir. Onu topraktan yarattı, sonra ona "Ol!" dedi, o da hemen oluverdi.'),
(3, 60, 3, 57, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', 'al-ḥaqqu min rabbika felā takun mina al-mumtarīn', 'Hak, Rabbindendir. Şüphe edenlerden olma.'),
(3, 61, 3, 57, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ', 'fe men ḥājjake fīhi mim baʿdi mā jāʾake minel-ʿilm(i) fe qul teʿālev(ā) nedʿu abnāʾanā ve abnāʾakum ve nisāʾanā ve nisāʾakum ve enfusana ve enfusakum summe nebtehil fe necʿal laʿneta Llāhi ʿalel-kāżibīn(e)', 'Sana gelen ilimden sonra, onun hakkında seninle tartışmaya girenlere de ki: "Gelin, biz de sizin oğullarınızı, siz de sizin oğullarınızı, biz de sizin kadınlarınızı, siz de sizin kadınlarınızı, biz de sizin kendilerimizi (canlarımızı) ve siz de sizin kendilerinizi (canlarınızı) çağıralım. Sonra da karşılıklı lanetleşelim de Allah''ın yalancılar üzerine lanetini dileyelim."'),
(3, 62, 3, 58, 'إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'inna hāḏā lahuwa l-qaṣaṣu l-ḥaqqu wa mā min ʾilāhin ʾillā llāhu wa ʾinna llāha lahuwa l-ʿazīzu l-ḥakīmu', 'Şüphesiz ki bu, (sana anlatılan) dosdoğru kıssadır. Allah''tan başka hiçbir ilah yoktur. Ve şüphesiz Allah, mutlak güç sahibi, hüküm ve hikmet sahibidir.'),
(3, 63, 3, 58, 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', 'faʾin tawallaw faʾinna ʾallāha ʿalīmun bi-l-mufsidīn', 'Eğer yüz çevirirlerse, şüphesiz Allah bozguncuları bilendir.'),
(3, 64, 3, 58, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', 'qul yā ahla l-kitābi taʿālav ʾilā kalimatin sawāʾin baynanā wa-baynakum ʾallā naʿbuda ʾillā llāha wa-lā nušrika bihi šayʾan wa-lā yattahiḏa baʿḍunā baʿḍan ʾarhāban min dūni llāhi fa-ʾin tawallaw fa-qūlū ʾašhadū bi-ʾannā muslimūna', 'De ki: "Ey kitap ehli! Gelin, sizinle bizim aramızda müsavi (eşit) bir kelimeye (toplanalım): Allah''tan başkasına tapmayalım, O''na hiçbir şeyi ortak koşmayalım ve Allah''ı bırakıp da birbirimizi Rabler edinmeyelim." Eğer yine yüz çevirirlerse, o zaman deyin ki: "Bizim Müslüman olduğumuza şahit olun."'),
(3, 65, 3, 58, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ أَفَلَا تَعْقِلُونَ', 'yā ʾahla l-kitābi lima tuḥājjūna fī ʾibrāhīma wa mā ʾunzilati t-tawrātu wa l-ʾinjīlu ʾillā min baʿdihi ʾafalā taʿqilūna', 'Ey Kitap Ehli! İbrahim hakkında ne diye tartışıyorsunuz? Tevrat da İncil de ancak ondan sonra indirilmiştir. Akıl erdirmiyor musunuz?'),
(3, 66, 3, 58, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'hā antum hāʾulāʾi ḥājacartum fīmā lakum bihi ʿilmun falima tuḥājjūna fīmā laysa lakum bihi ʿilmun wallāhu yaʿlamu wa antum lā taʿlamūna', 'İşte siz, az çok bilgili olduğunuz konularda böyle tartıştınız. Peki ya hiç bilginiz olmayan konularda niçin tartışıyorsunuz? Oysa Allah bilir, siz bilmezsiniz.'),
(3, 67, 3, 58, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'mā kāna ibrāhīmu yahūdiyyan walā naṣrāniyyan walākin kāna ḥanīfan musli̇man wamā kāna mina l-mušrikīn', 'İbrahim ne Yahudi idi, ne de Hristiyan; fakat o, Allah''a yönelmiş dosdoğru bir Müslüman idi ve müşriklerden değildi.'),
(3, 68, 3, 58, 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', 'inna awlā an-nāsi bi-ibrāhīma la-llaḏīna ittabaʿūhu wa-hāḏā an-nabiyyu wa-llaḏīna āmanū wa-llāhu walīyyu al-muʾminīna', 'İnsanların İbrahim''e en yakın olanları, ona uyanlar, şu peygamber ve ona iman edenlerdir. Allah müminlerin dostudur.'),
(3, 69, 3, 58, 'وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'waddat ṭāʾifatun min ʾahli l-kitābi law yuḍillūnakum wa mā yuḍillūna ʾillā ʾanfusahum wa mā yashʿurūn', 'Kitap ehlinden bir zümre, sizi saptırmak ister. Halbuki onlar ancak kendilerini saptırırlar ve bunun farkında değillerdir.'),
(3, 70, 3, 58, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', 'yā ʾahla l-kitābi lima takfurūna bi-ʾāyāti llāhi wa-ʾantum tašhadūn', 'Ey Kitap Ehli! Siz de şahit olup dururken, niçin Allah''ın âyetlerini inkâr ediyorsunuz?'),
(3, 71, 3, 59, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 'yā ʾahla l-kitābi lima talbisūna l-ḥaqqa bi-l-bāṭili wa-taktumūna l-ḥaqqa wa-ʾantum taʿlamūna', 'Ey Kitap Ehli! Hakkı batılla karıştırıyor ve bile bile hakkı gizliyorsunuz.'),
(3, 72, 3, 59, 'وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', 'wa qālat ṭāʾifatun min ʾahli l-kitābi ʾāminū bi-lladhī ʾunzila ʿalā lladhīna ʾāmanū wajha n-nahāri wa-kfurū ʾākhirahu laʿallahum yarjiʿūna', 'Kitap ehlinden bir grup: "Gündüzün başında inananlara inanın, sonunda inkâr edin!" dediler.'),
(3, 73, 3, 59, 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'wa lā tuʾminū ʾillā liman tabiʿa dīnakum qul ʾinna l-hudā hudā llāhi ʾan yuʾtā ʾaḥadun mithla mā ʾūtītum ʾaw yuḥājjūkum ʿinda rabbikum qul ʾinna l-faḍla biyadi llāhi yuʾtīhi man yashāʾu wa llāhu wāsiʿun ʿalīmun', 'Sizin dininize uyanlardan başkasını tasdik etmeyin. De ki: "Doğru yol, Allah''ın doğru yoludur. Size verilmiş olanın bir benzerinin bir başkasına verilmesi veya Rabbinizin huzurunda sizinle tartışmaları (ihtimali) söz konusu olamaz." De ki: "Şüphesiz fazl Allah''ın elindedir, onu dilediğine verir. Allah, Vâsi''dir, Alîm''dir."'),
(3, 74, 3, 59, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'yakhtaṣṣu biraḥmatihī man yashāʾu wa-llāhu ḏū l-faḍli l-ʿaẓīmi', 'Dilediğini kendi rahmetine seçer. Allah, büyük fazl sahibidir.'),
(3, 75, 3, 59, 'وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّۦنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'wa-min ahli l-kitābi man in taʾmanhu bi-qinṭārin yuʾaddīhi ʾilayka wa-minhum man in taʾmanhu bi-dīnārin lā yuʾaddīhi ʾilayka ʾillā mā dumta ʿalayhi qāʾiman dhālika bi-ʾannahum qālū laysa ʿalaynā fī l-ʾummiyyīna sabīlun wa-yaqūlūna ʿalā llāhi l-kaḏiba wa-hum yaʿlamūna', 'Kitap ehlinden öylesi vardır ki, eğer ona bir yük altın emanet bıraksan, sen onu geri vermesini isteyinceye kadar onu sana öder. Yine onlardan öylesi de vardır ki, eğer ona bir dinar emanet bıraksan, sen tepesine dikilmedikçe onu sana ödemez. Bu böyledir, çünkü onlar: "Biz Arap olmayanlar (Ümmîler) hususunda bize bir yol yoktur" derler. Ve onlar, bile bile Allah''a karşı yalan söylerler.'),
(3, 76, 3, 59, 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'balā man ʾawfā bi-ʿahdihi wa-ttaqā fa-ʾinna ʾallāha yuḥibbu l-muttaqīn', 'Hayır! Kim ahdine vefa gösterir ve Allah''tan korkarsa, şüphesiz Allah da takva sahiplerini sever.'),
(3, 77, 3, 59, 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْءَاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ʾinna lladhīna yashtarūna biʿahdi llāhi wa-ʾaymānihim thamanan qalīlan ʾulāʾika lā khalāqa lahum fī l-ʾākhirati wa-lā yukallimuhumu llāhu wa-lā yanẓuru ʾilayhim yawma l-qiyāmati wa-lā yuzakkīhim wa-lahum ʿadhābun ʾalīmun', 'Allah''ın ahdini ve kendi yeminlerini az bir karşılığa değişenler var ya, işte onların ahirette bir nasibi yoktur. Kıyamet günü Allah onlarla konuşmaz, onları (rahmetiyle) bakmaz ve onları tertemiz kılmaz. Onlar için elem dolu bir azap vardır.'),
(3, 78, 3, 60, 'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'wa-ʾinna minhum lafarīqan yalwūna ʾalsinatahum bil-kitābi litaḥsabūhu minal-kitābi wa-mā huwa minal-kitābi wa-yaqūlūna huwa min ʿindi-llāhi wa-mā huwa min ʿindi-llāhi wa-yaqūlūna ʿalā-llāhi l-kaḏiba wa-hum yaʿlamūna', 'Onlardan öylesine bir topluluk vardır ki, dillerini Kitap''la öyle eğerler ki, siz onu Kitap''tan sanırsınız. Oysa o Kitap''tan değildir. Ve "O, Allah katındandır" derler. Oysa o, Allah katından değildir. Ve Allah''a karşı yalan söylerler; halbuki onlar bilirler.'),
(3, 79, 3, 60, 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّۦنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', 'mā kāna li-basharin an yuʾtiyahū ʾllāhu l-kitāba wa-l-ḥukma wa-n-nubūwata thumma yaqūla li-n-nāsi kūnū ʿibādan l-lī min dūni ʾllāhi wa-lākin kūnū rabbāniyyīna bimā kuntum tuʿallimūna l-kitāba wa-bimā kuntum tadrusūna', 'Allah''ın kendisine kitap, hikmet ve peygamberlik verdiği hiçbir insana, ondan sonra insanlara şöyle demesi yakışmaz: "Allah''ı bırakıp bana kullar olun!" Fakat (o şöyle demeli): "Öğrettiğiniz kitaplara ve onu okuyup anladığınıza göre, halis kullarım olun!"'),
(3, 80, 3, 60, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّۦنَ أَرْبَابًا أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', 'wa-lā yaʾmurakum an tattakhidhū al-malāʾikata wa-n-nabiyyīna ʾarbābā ʾayaʾmurukum bi-l-kufri baʿda ʾidh ʾantum muslimūn', 'O, size melekleri ve peygamberleri rabler edinin diye emretmez. Siz Müslüman olduktan sonra O size küfrü mü emredecek?'),
(3, 81, 3, 60, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّۦنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى قَالُوٓا۟ أَقْرَرْنَا قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', 'wa-ʾiḏ ʾaḵaḏa llāhu mīṯāqa n-nabiyyi-na lamā ʾātaytukum min kitābin wa-ḥikmatin ṯumma jāʾakum rasūlun muṣaddiqun limā maʿakum l-tuʾminunna bihi wa-l-tanṣurūnnahu qāla ʾaʾaqrartum wa-ʾaḵaḏtum ʿalā ḏālikum ʾiṣrī qālū ʾaqrarnā qāla fa-šhadū wa-ʾanā maʿakum mina š-šāhidīn', 'Hani Allah, peygamberlerden, "Size Kitap ve hikmet verdim. Sonra size de sizin yanınızdaki (gerçeği) doğrulayan bir elçi gelince, ona mutlaka inanacak ve yardım edeceksiniz" diye ahid (misak) almıştı. (Onlara) "Bunu ikrar ettiniz ve bu ağır (ahdimi) üzerinize aldınız mı?" demişti. (Onlar) "İkrar ettik" demişlerdi. (Allah) "Öyleyse şahit olun, ben de sizinle beraber şahit olanlardanım" buyurmuştu.'),
(3, 82, 3, 60, 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'fe-men tevellā baʿde dhālika fa-ʾulāʾike humu l-fāsiqūn', 'Artık kim bundan sonra dönerse, işte onlar fasiktirlar.'),
(3, 83, 3, 60, 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ', 'ʾafaghayra dīni ʾllāhi yبغhūna walʾa-hū ʾaslama man fī s-samāwāti wal-ʾarḍi ṭawʿan wa-karhan wa-ʾilayhi yurjaʿūna', 'Allah''ın dininden başkasını mı arıyorlar? Oysa göklerde ve yerde kim varsa isteyerek veya istemeyerek O''na teslim olmuştur ve O''na döndürüleceklerdir.'),
(3, 84, 3, 61, 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'qul ʾāmannā bi-llāhi wa mā ʾunżila ʿalaynā wa mā ʾunżila ʿalā ʾibrāhīma wa-ʾismāʿīla wa-ʾisḥāqa wa-yaʿqūba wa-l-ʾasbāṭi wa mā ʾūtiya mūsā wa-ʿīsā wa-n-nabiyyūna min rabbihim lā nufarriqu bayna ʾaḥadin minhum wa naḥnu lahuū muslimūna', 'De ki: "Allah''a, bize indirilene, İbrahim''e, İsmail''e, İshak''a, Ya''kub''a ve torunlarına indirilene, Musa''ya ve İsa''ya verilenler ile diğer peygamberlere Rableri tarafından verilene iman ettik. Onlardan hiçbirini ayırmayız ve biz O''na teslim olmuşlarız."'),
(3, 85, 3, 61, 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 've men yebtaği ġayra l-islāmi dīnā fe-len yuḳbele minhu ve hüve fī l-ʾāḫirati mine l-ḫāsirīn', 'Kim İslam''dan başka bir din ararsa, ondan asla kabul edilmez. Ve o, ahirette de husrana uğrayanlardandır.'),
(3, 86, 3, 61, 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'kayfa yahdī allāhu qawman kafarū baʿda īmānihim wašahidū anna ar-rasūla ḥaqqun wa jāʾahumu al-bayyinātu wa allāhu lā yahdī al-qawma aẓ-ẓālimīna', 'Allah, imanlarından sonra kâfir olmuş, peygamberin hak olduğuna şahitlik etmiş ve kendilerine apaçık deliller gelmiş bir toplumu nasıl doğru yola iletir? Allah zalim toplumu doğru yola iletmez.'),
(3, 87, 3, 61, 'أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'ʾulāʾika jazāʾuhum ʾanna ʿalayhim laʿnata ʾllāhi wa-l-malāʾikati wa-n-nāsi ʾajmaʿīn', 'İşte bunların cezası, Allah''ın, meleklerin ve bütün insanların lanetinin üzerlerine olmasıdır.'),
(3, 88, 3, 61, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 'khālidīna fīhā lā yukhaffafu ʿanhumu l-ʿadhābu walā hum yunẓarūn', 'Onlar orada ebedî kalırlar. Kendilerinden azap hafifletilmez ve onlara mühlet verilmez.'),
(3, 89, 3, 61, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'illa alladhīna tābū min baʿdi dhālika waʾaṣlaḥū faʾinna allāha ghafūrun raḥīmun', 'Ancak bundan sonra tevbe eden ve ıslah olanlar başka. Şüphesiz Allah, çok bağışlayıcıdır, çok merhametlidir.'),
(3, 90, 3, 61, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', 'ʾinna lladhīna kafarū baʿda ʾīmānihim thumma zdādū kufran lan tuqbala tawbatuhum wa ʾulāʾika humu ḍ-ḍāllūna', 'İmanlarından sonra inkâra sapan, sonra da inkârlarını artırarak küfürlerini çoğaltanların tevbeleri asla kabul edilmez. İşte onlar, (haktan) sapmışların ta kendileridir.'),
(3, 91, 3, 61, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'ʾinna lladhīna kafarū wamātū wahum kuffārun falan yuqbala min ʾaḥadihim milʾu l-ʾarḍi dhahaban walawiftadā bihī ʾulāʾika lahum ʿadhābun ʾalīmun wamā lahum min nāṣirīna', 'Şüphesiz inkâr edenler ve kâfir olarak ölenler var ya, onların hiçbirinden, (kurtulmalık olarak) yeri dolduracak kadar altın bile olsa kabul edilmez. İşte onlar için acı veren bir azap vardır ve kendileri için hiçbir yardımcı da yoktur.'),
(3, 92, 3, 62, 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 'lan tanālū al-birra ḥattā tunfiqū mimmā tuḥibbūn wa mā tunfiqū min shayʾin fa-inna Allāha bihi ʿalīm', 'Sevdiğiniz şeylerden (Allah yolunda) harcayıncaya kadar iyiliğe asla erişemezsiniz. Her ne harcarsanız Allah onu bilir.'),
(3, 93, 4, 62, 'كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ', 'kullu ṭ-ṭaʿāmi kāna ḥillan li-banī ʾisrāʾīla ʾillā mā ḥarrāma ʾisrāʾīlu ʿalā nafsihi min qabli ʾan tunazzala t-tawrātu qul faʾtū bi-t-tawrāti fa-tlūhā ʾin kuntum ṣādiqīna', 'İsrailoğullarına bütün yiyecekler helal idi; ancak İsrail''in (Yakup''un) kendi nefsine haram kıldığı müstesna. De ki: ''Eğer doğru sözlü iseniz Tevrat''ı getirin ve okuyun.'''),
(3, 94, 4, 62, 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'fe meniftarā ʿalā llāhi l-kaḏiba mim baʿdi ḏālika fa-ʾulāʾika humu ẓ-ẓālimūn', 'Bundan sonra kim Allah''a yalan isnad ederse, işte onlar zalimlerdir.'),
(3, 95, 4, 62, 'قُلْ صَدَقَ ٱللَّهُ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'qul ṣadaqa -llāh fāttabiʿū milleta ʾibrāhīma ḥanīfā wa mā kāna mina -lmušrikīn', 'De ki: "Allah doğru söylemiştir. Öyleyse hakka yönelen İbrahim''in dinine uyun. O, ortak koşanlardan değildi."'),
(3, 96, 4, 62, 'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَٰلَمِينَ', 'ʾinna ʾawwala baytin wuḍiʿa lil-nāsi la-llaḏī bibakkata mubārakan wa-hudan lil-ʿālamīn', 'Şüphesiz, insanlar için kurulan ilk ev (mâbed), Mekke''de, alemlere bir bereket ve hidayet kaynağı olarak (inşa edilen) Ka''be''dir.'),
(3, 97, 4, 62, 'فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌ مَّقَامُ إِبْرَٰهِيمَ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 'fīhi ʾāyātun bayyinātun maqāmu ʾibrāhīm wa man dakhala-hu kāna ʾāminan wa li-llāhi ʿalā an-nāsi ḥijju al-bayti mani istṭāʿa ʾilayhi sabīlan wa man kafara fa-ʾinna llāha ġaniyyun ʿani al-ʿālamīn', 'Onda apaçık ayetler, İbrahim''in makamı vardır. Oraya giren güven içinde olur. Yolu gücü yeten herkesin o evi haccetmesi Allah''ın insanlar üzerindeki hakkıdır. Kim inkâr ederse, şüphesiz Allah âlemlerden müstağnidir.'),
(3, 98, 4, 62, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', 'Qul yā ahla l-kitābi Lima takfurūna bi-āyāti llāhi Wa-llāhu shahīdun ʿalā mā taʿmalūna', 'De ki: "Ey Kitap Ehli! Allah''ın ayetlerine neden küfrediyorsunuz? Oysa Allah yaptıklarınızı görüp durmaktadır."'),
(3, 99, 4, 62, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'Qul yā ʾahla l-kitābi Lima taṣuddūna ʿan sabīli llāhi man ʾāmana Tabġūnahā ʿiwajan Wa ʾantum shuhadāʾu Wa mā llāhu bighāfilin ʿammā taʿmalūna', 'De ki: "Ey Kitap Ehli! Niçin Allah''ın yolundan, iman edenleri çeviriyorsunuz? Oysa siz de (onların haklılığına) şahitlersiniz. Allah yaptıklarınızdan gafil değildir."'),
(3, 100, 4, 62, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ', 'yā ayyuhā lladhīna āmanū in tuṭīʿū farīqan mina lladhīna ūtū l-kitāba yaruddūkum baʿda īmānikum kāfirīna', 'Ey iman edenler! Eğer Kitap verilenlerden bir gruba uyarsanız, sizi imanınızdan sonra kâfir yaparlar.'),
(3, 101, 4, 63, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa kayfa takfurūna wa antum tutlā ʿalaykum āyātu llāhi wa fīkum rasūluhu wa man yaʿtaṣim bi llāhi faqad hudīya ilā ṣirāṭin mustaqīm', 'Allah''ın ayetleri size okunup dururken ve aranızda O''nun Resûlü de bulunurken nasıl küfredebilirsiniz? Kim Allah''a sımsıkı sarılırsa, şüphesiz ki o, doğru bir yola iletilmiştir.'),
(3, 102, 4, 63, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 'yā ayyuhā alladhīna āmānū ittaqū allāha ḥaqqa tuqātihī walā tamūtunna illā wa-antum muslimūn', 'Ey iman edenler! Allah''tan, O''na yaraşır şekilde korkun ve ancak Müslümanlar olarak can verin.'),
(3, 103, 4, 63, 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', 'wa-ʿtaṣimū bi-ḥabli ʾllāhi jamīʿan wa-lā tafarraqu wa-ʾdhkurū niʿmata ʾllāhi ʿalaykum ʾidh kuntum ʾaʿdāʾan fa-ʾallafa bayna qulūbikum fa-ʾaṣbaḥtum bi-niʿmatihī ʾikhwānan wa-kuntum ʿalā shafā ḥufratin mina n-nāri fa-ʾanqadhakum minhā kadhālika yubayyinullāhu lakum ʾāyātihi laʿallakum tahtadūn', 'Hep birlikte Allah''ın ipine sarılın, bölünüp ayrılmayın. Allah''ın size olan nimetini hatırlayın; hani siz birbirinize düşmandınız da O, kalplerinizi birleştirmişti ve O''nun nimetiyle kardeşler olmuştunuz. Bir ateş çukurunun kenarında iken sizi oradan kurtarmıştı. İşte Allah, doğru yolu bulasınız diye size ayetlerini böyle açıklar.'),
(3, 104, 4, 63, 'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'wa-latkun minkum ummatun yad''ūna ilā l-khayri wa-ya''murūna bi-l-ma''rūfi wa-yanhawna ''ani l-munkari wa-ulā''ika humu l-mufliḥūna', 'Sizden, hayra çağıran, iyiliği emreden ve kötülükten alıkoyan bir ümmet bulunsun. İşte bunlar kurtuluşa erenlerdir.'),
(3, 105, 4, 63, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ', 'wa lā takūnū ka-lladhīna tafarraqū wa-khtalafū min baʿdi mā jāʾahumu l-bayyinātu wa ʾulāʾika lahum ʿadhābun ʿaẓīmun', 'Siz de, kendilerine apaçık deliller geldikten sonra ayrılığa düşen ve (gerçeği) tartışanlar gibi olmayın. İşte onlar için büyük bir azap vardır.'),
(3, 106, 4, 63, 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'yawma tabyaḍḍu wujūhun wa taswadu wujūhun fa-ammā alladhīna uswaddat wujūhuhum a-kafartum baʿda īmānikum fa-dhūqū al-ʿadhāba bimā kuntum takfurūn', 'O gün birtakım yüzler ağarır, birtakım yüzler kararır. Yüzleri kararanlara: "Siz iman ettikten sonra kâfir mi oldunuz? Öyleyse tattığınız küfür yüzünden azabı tadın!" denilir.'),
(3, 107, 4, 63, 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ', 'waʾammā allaḏīna ibyaḍḍat wujūhuhum fafī raḥmati llāhi hum fīhā ḫālidūn', 'Yüzleri ak olanlara gelince; işte onlar Allah''ın rahmetindedirler; orada ebedî kalırlar.'),
(3, 108, 4, 63, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَٰلَمِينَ', 'tilka ʾāyātu llāhi natlūhā ʿalayka bil-ḥaqqi wa mā llāhu yurīdu ẓulman lil-ʿālamīn', 'Bunlar, sana dosdoğru okuduğumuz Allah''ın ayetleridir. Allah, âlemler için zulüm dilemez.'),
(3, 109, 4, 64, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'wa lil-lāhi mā fī s-samāwāti wa mā fī l-ʾarḍi wa ʾilā llāhi turjaʿu l-ʾumūru', 'Göklerde ne var, yerde ne varsa hepsi Allah''ındır. Bütün işler de sonunda Allah''a döner.'),
(3, 110, 4, 64, 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًا لَّهُم مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ', 'kuntum khayra ummatin ukhrijat lilnnāsi taʾmurūna bil-maʿrūfi wa-tanhawna ʿani l-munkari wa-tuʾminūna billāhi wa-law āmana ahlu l-kitābi lakāna khayran lahum minhumu l-muʾminūna wa-aktharuhumu l-fāsiqūna', 'Siz, insanlar için çıkarılmış en hayırlı ümmetsiniz; iyiliği emreder, kötülükten vazgeçirir ve Allah''a inanırsınız. Kitap ehli de inanmış olsaydı, kendileri için elbette daha hayırlı olurdu. Onlardan iman edenler de var, fakat çoğu yoldan çıkmışlardır.'),
(3, 111, 4, 64, 'لَن يَضُرُّوكُمْ إِلَّآ أَذًى وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', 'lan yaḍurrukum illā ḏan wa-in yuqātilūkum yewallūkumul-adbār ṯumma lā yunṣarūn', 'Onlar size ancak eziyet verebilirler. Eğer sizinle savaşa çıkarlarsa, gerisin geri dönerler. Sonra onlara yardım edilmez.'),
(3, 112, 4, 64, 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'ḍuribat ʿalayhimu ẓ-ẓilalatu ayna mā thuqifū illā biḥablin mina llāhi waḥablin mina n-nāsi wa bāʾū biġaḍabin mina llāhi wa ḍuribat ʿalayhimu l-maskanatu dhālika bi ʾannahum kānū yakfurūna bi ʾāyāti llāhi wa yaqtulūna l- ʾanbiyāʾa biġayri ḥaqqin dhālika bimā ʿaṣaw wa kānū yaʿtadūna', 'Onlar, nerede bulunsalar, Allah''ın ipine ve insanların ipine (sığınmadıkça) üzerlerine zillet (aşağılık) damgası vurulmuştur. Allah''tan bir gazaba uğradılar ve üzerlerine de miskinlik (aşağılık) damgası vuruldu. Bu, onların Allah''ın âyetlerini inkâr etmeleri ve peygamberleri haksız yere öldürmeleri yüzündendi. Bu da onların isyan etmiş olmaları ve haddi aşmış olmalarındandır.'),
(3, 113, 4, 64, 'لَيْسُوا۟ سَوَآءً مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', 'laysū sawāʾan min ʾahli l-kitābi ʾummatun qāʾimatun yatlūna ʾāyāti llāhi ʾānāʾa l-layli wa-hum yasjudūna', 'Kitap Ehli''nin hepsi bir değildir; gece vaktinde Allah''ın ayetlerini okuyup secdeye kapanan dosdoğru bir topluluk da vardır.'),
(3, 114, 4, 64, 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', 'yuʾminūna bi-llāhi wa-l-yawmi l-ʾākhiri wa-yaʾmurūna bi-l-maʿrūfi wa-yanhawna ʿani l-munkari wa-yusāriʿūna fī l-khayrāti wa-ʾulāʾika mina ṣ-ṣāliḥīna', 'Onlar Allah''a, ahiret gününe inanırlar, iyiliği emrederler, kötülükten vazgeçirirler ve hayırlara koşuşurlar. İşte bunlar iyi kimselerdendir.'),
(3, 115, 4, 64, 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 'Ve mā yafʿalū min khayrin falan yukfarūhu Veʾllāhu ʿalīmun bil-muttaqīn', 'Her ne hayır işlerseniz, bilin ki Allah onu bilir. Ve Allah takva sahiplerini bilir.'),
(3, 116, 4, 65, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'ʾinna llaḏīna kafarū lan tuġniya ʿanhum ʾamwāluhum walā ʾawlāduhum mina llaāhi šayʾan wa ʾulāʾika ʾaṣḥābu n-nāri hum fīhā ḫālidūna', 'Şüphesiz inkâr edenlerin ne malları ne de evlatları, kendilerini Allah''tan (kurtaracak) hiçbir şeye yaramaz. Onlar cehennem ehlidirler; orada ebedî kalırlar.'),
(3, 117, 4, 65, 'مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', 'Mathalu mā yunfiqūna fī hādhihi al-ḥayāti ad-dunyā kamathali rīḥin fīhā ṣirrun aṣābat ḥarth qawmin ẓalamū anfusahum fa-ahlakathu Wa mā ẓalamahumu Allāhu wa lākin anfusahum yaẓlimūn', 'Onların bu dünya hayatında yapmakta oldukları harcamaların durumu, içinde dondurucu bir soğuk bulunan ve kendi kendilerine zulmetmiş bir kavmin ekinlerine isabet edip de onu mahveden bir rüzgârın durumu gibidir. Allah onlara zulmetmedi; fakat onlar kendi kendilerine zulmediyorlar.'),
(3, 118, 4, 65, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ إِن كُنتُمْ تَعْقِلُونَ', 'yāʾayyuhā llaḏīna ʾāmanū lā tattahẖiḏū biṭānetan min dūnikum lā yaʾlūnakum habālā waddū mā ʿanittum qad badati l-baġḍāʾu min ʾafwāhihim wamā tuḥfī ṣudūruhum ʾakbaru qad bayyannā lakumu l-ʾāyāti ʾin kuntum taʿqilūna', 'Ey iman edenler! Sizden olmayanları sırdaş edinmeyin. Onlar size fenalık etmekten asla geri durmazlar. Hep sıkıntıya düşmenizi isterler. Düşmanlıkları ağızlarından (açıkça) belli olmuştur. Kalplerinde gizledikleri ise daha büyüktür. Eğer akıl erdirecek olursanız, size ayetleri açıkladık.'),
(3, 119, 4, 65, 'هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ قُلْ مُوتُوا۟ بِغَيْظِكُمْ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'hā''antum ʾulāʾi tuḥibbūnahum walā yuḥibbūnakum watūʾminūna bilkitābi kullihī waʾiḏā laqūkum qālū ʾāmannā waʾiḏā ḵalaw ʿaḍḍū ʿalaykumu l-ʾanāmila mina l-ḡayẓi qul mūtū biḡayẓikum ʾinna ḷḷāha ʿalīmun biḏāti ṣ-ṣudūri', 'Siz öyle kimselersiniz ki onları seversiniz, halbuki onlar size buğz ederler. Siz, bütün kitaplara inanmışsınızdır. Onlar sizinle karşılaştıkları zaman: "İman ettik" derler. Baş başa kaldıkları zaman da, size karşı besledikleri kin ve hiddetten dolayı parmak uçlarını ısırırlar. De ki: "Öfkenizle geberin! Şüphesiz Allah, göğüslerin özünü bilendir."'),
(3, 120, 4, 65, 'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ', 'in temseskum hasenetun tesu''hum ve in tusibkum seyyi''etun yefrahu biha ve in tasbiru ve tetteku la yadurrukum keyduhum şey''en innallaha bima ya''melune muhitun', 'Eğer size bir iyilik dokunursa bu onları tasalandırır, eğer başınıza bir kötülük gelirse buna sevinirler. Eğer siz sabreder ve sakınırsanız, onların hileli düzenleri size hiçbir zarar vermez. Şüphesiz Allah, onların yapmakta olduklarını kuşatmaktadır.'),
(3, 121, 4, 65, 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'wa-ʾidh ghadawta min ʾahlika tubawwiʾu l-muʾminīna maqāʿida lil-qitāli wa-llāhu samīʿun ʿalīmun', 'Hani sen ailenden ayrılıp (Uhud''a doğru) müminleri savaş düzenine yerleştiriyordun. Allah işitendir, bilendir.'),
(3, 122, 4, 66, 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'idh hammaṭ ṭāʾifatāni minkum an tafshalā wa-llāhu waliyyuhumā wa-ʿalā llāhi falyatawakkali l-muʾminūn', 'Sizden iki topluluğun bozguna uğramaya yüz tuttuğu zamanı hatırlayın. Allah onların yardımcısıydı. İşte bu yüzden müminler yalnız Allah''a güvenmelidir.'),
(3, 123, 4, 66, 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', 'Ve lekad nasarakumu(A)llâhu bibedrin ve entum ezille(tun) Fettekû(A)llâhe le’allekum teşkurûn', 'Andolsun ki Allah size Bedir''de yardım etmişti, oysa siz zayıf ve az idiniz. Öyleyse Allah''tan korkup sakının ki şükredesiniz.'),
(3, 124, 4, 66, 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ', 'iḏ taqūlu lil-muʾminīn ʾalan yakfiyakum ʾan yumididakum rabbukum bi-ṯalāṯati ʾālāfin mina l-malāʾikati munzalīn', 'Hani o zaman mü''minlere şöyle diyordun: "Rabbinizin, size üç bin melekle yardım indirmesi size yetmez mi?"'),
(3, 125, 4, 66, 'بَلَىٰٓ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ', 'balā in taṣbirū wa tattaqū wa yaʾtūkum min fawrihim hāḏā yumdidkum rabbukum bi-ḫamsati ʾālāfin mina l-malāʾikati musawwimīn', 'Evet! Eğer sabrederseniz, takva sahibi olursanız ve onlar (düşmanlarınız) hemen üzerinize gelirlerse, Rabbiniz size, nişanlı/damgalı beş bin melek ile yardım edecektir.'),
(3, 126, 4, 66, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'wa mā jaʿalahu ʾllāhu ʾillā bushṛā lakum wa litaṭmaʾinna qulūbukum bihi wa mā n-naṣru ʾillā min ʿindi ʾllāhi l-ʿazīzi l-ḥakīm', 'Allah, bunu ancak size bir müjde kılmak ve kalplerinizin onunla yatışmasını sağlamak için yaptı. Zafer, yalnızca mutlak güç sahibi, hüküm ve hikmet sahibi Allah''tandır.'),
(3, 127, 4, 66, 'لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', 'liyaqṭaʿa ṭarafan mmina lladhīna kafarū aw yakbitahum fayanqalibū khāʾibīn', 'Onları kesip biçmek için ya da onları kahredip umduklarına nail olmadan dönmelerini sağlamak için...'),
(3, 128, 4, 66, 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ', 'laysa laka mina l-amri shayʾun aw yatūba ʿalayhim aw yuʿaḏḏibahum fa-ʾinnahum ẓālimūn', 'Onların işinden sana hiçbir şey (yoktur); O, onların tevbesini kabul etsin veya onlara azap etsin, çünkü onlar zalimlerdir.'),
(3, 129, 4, 66, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'wa lil-lāhi mā fī s-samāwāti wa mā fī l-arḍi yaghfiru liman yashāʾu wa yuʿadhdhibu man yashāʾu wa-llāhu ghafūrun raḥīmun', 'Göklerde ne var, yerde ne varsa hepsi Allah''ındır. O, dilediğini bağışlar, dilediğine azap eder. Allah, çok bağışlayandır, çok merhamet edendir.'),
(3, 130, 4, 66, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًا مُّضَٰعَفَةً وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'yā ayyuhā lladhīna āmānū lā taʾkulū r-ribā ʾaḍʿāfan muḍāʿafatan wa-ttaqū llāha laʿallakum tufliḥūn', 'Ey iman edenler! Kat kat artırılmış olarak faiz yemeyin. Allah''tan korkun ki kurtuluşa eresiniz.'),
(3, 131, 4, 66, 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ', 'wa-ttaqū an-nāra allatī ʾuʿiddat lil-kāfirīn', 'Kâfirler için hazırlanmış olan ateşten sakının.'),
(3, 132, 4, 66, 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'wa ʾaṭīʿū ʾllāha wa-r-rasūla laʿallakum turḥamūna', 'Allah''a ve Peygamber''e itaat edin ki merhamet olunasınız.'),
(3, 133, 4, 67, 'وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 'wa-sāriʿū ʾilā maghfiratin min rabbikum wa-jannatin ʿarḍuhā s-samāwātu wa-l-ʾarḍu ʾuʿiddat lil-muttaqīn', 'Ve Rabbinizden bir mağfirete ve genişliği gökler ve yer kadar olan, takva sahipleri için hazırlanmış bir cennete doğru yarışın.'),
(3, 134, 4, 67, 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'alladhīna yunfiqūna fī as-sarrāʾi wa-ḍ-ḍarrāʾi wa-l-kāẓimīna l-ghayẓa wa-l-ʿāfīna ʿani n-nāsi wa-llāhu yuḥibbu l-muḥsinīna', 'Onlar, bollukta da darlıkta da Allah için harcayanlar, öfkelerini yutanlar ve insanları affedenlerdir. Allah iyilik edenleri sever.'),
(3, 135, 4, 67, 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', 'wa-lladhīna idhā faʿalū fāḥishatan aw ẓalamū anfusahum dhakarū llāha fastagfarū lidhunūbihim wa-man yaghfiru dh-dhunūba illā llāhu wa-lam yuṣirrū ʿalā mā faʿalū wa-hum yaʿlamūna', 'Onlar, bir kötülük yaptıkları veya kendilerine zulmettikleri zaman Allah''ı anarlar, günahlarının bağışlanmasını dilerler. Allah''tan başka günahları kim bağışlayabilir? Ve onlar, yaptıklarında ısrar etmezler; biliyorlar.'),
(3, 136, 4, 67, 'أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'ʾulāʾika jazāʾuhum maghfiratun min rabbihim wa-jannātun tajrī min taḥtihā l-ʾanhāru khālidīna fīhā wa-niʿma ajru l-ʿāmilīna', 'İşte onların mükafatı, Rableri katında bağışlanma ve altlarından ırmaklar akan, içinde ebedi kalacakları cennetlerdir. (Salih) amellerde bulunanların mükafatı ne güzeldir!'),
(3, 137, 4, 67, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'qad ḵalat min qabl kum sunanun fasīrū fī l-arḍi fa nẓurū kayfa kāna ʿāqibatu l-mukaḏḏibīn', 'Sizden önce nice devirler gelip geçti. Bu yüzden yeryüzünde dolaşın da (peygamberleri) yalanlayanların sonunun nasıl olduğuna bir bakın.'),
(3, 138, 4, 67, 'هَٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ', 'hādhā bayānun linnāsi wa hudan wa mawʿiẓatun lilmuttaqīn', 'Bu, insanlara bir açıklama, Allah''a karşı gelmekten sakınanlara bir hidayet ve bir öğüttür.'),
(3, 139, 4, 67, 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', 'wa-lā tahinū wa-lā taḥzanū wa-antum al-aʿlawna ʾin kuntum muʾminīna', 'Gevşeklik göstermeyin, üzüntüye kapılmayın. Eğer inanmışsanız, üstün olan sizlersiniz.'),
(3, 140, 4, 67, 'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'in yamsaskum qarḥun faqad massa l-qawma qarḥun mithluhū wa-tilka l-ayyāmu nudāwiluhā bayna n-nāsi wa-liyaʿlama llāhu lladhīna ʾāmanū wa-yattakhidha minkum shuhadāʾa wa-llāhu lā yuḥibbu ẓ-ẓālimīna', 'Eğer size bir yara dokunursa, o topluma da benzer bir yara dokunmuştur. İşte bu günleri biz insanlar arasında evirir çeviririz; böylece Allah, inanmış olanları bilip ortaya çıkarsın ve sizin için de şahitler edinsin. Allah zalimleri sevmez.'),
(3, 141, 4, 68, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ', 'wa-liyumahhiṣa allāhu alladhīna ʾāmanū wa-yamḥaqa l-kāfirīna', 'Allah, iman edenleri ayırmak ve kafirleri mahvetmek için (böyle yapmıştır).'),
(3, 142, 4, 68, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ', 'am ḥasibtum an tadkhulū l-jannata wa-lammā yaʿlam i l-lāhu l-ladhīna jāhadū minkum wa-yaʿlama ṣ-ṣābirīn', 'Yoksa siz, içinizden cihad edenleri ve sabredenleri Allah bilmeden cennete gireceğinizi mi sandınız?'),
(3, 143, 4, 68, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', 'Ve lekad kuntum temennevne el-mevte min kabli en telkavhu Fe kad raeytumuhu ve entum tenzurune', 'Andolsun ki siz, ölümle karşılaşmadan önce onu temenni ediyordunuz. İşte onu gördünüz, siz bakıp dururken.'),
(3, 144, 4, 68, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ', 've mâ muḥammedun illâ rasûlun ḳad ḫalet min ḳablihi ʾr-rusûlu ʾafaʾin mâte ʾaw ḳutila nḳalebtum ʿalā ʾaʿḳâbikum ve men yanḳalib ʿalā ʿaḳibeyhi felen yaḍurra ʾllāhe şeyen ve seyeğzî ʾllāhu ʾş-şâkirîn', 'Muhammed, ancak bir peygamberdir. Ondan önce de nice peygamberler gelip geçmiştir. Eğer o, ölürse veya öldürülürse, siz ökçelerinizin üzerine (geriye) dönecek misiniz? Kim (geriye) dönerse, Allah''a hiçbir zarar vermeyecektir. Allah şükredenleri mükâfatlandıracaktır.'),
(3, 145, 4, 68, 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًا مُّؤَجَّلًا وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْءَاخِرَةِ نُؤْتِهِۦ مِنْهَا وَسَنَجْزِى ٱلشَّٰكِرِينَ', 'wa mā kāna li-nafsin an tamūta illā bi-ʾiḏni llāhi kitāban muʾajjalan wa man yurid ṯawāba d-dunyā nuʾtihī minhā wa man yurid ṯawāba l-ʾāḫirati nuʾtihī minhā wa sa-najzā š-šākirīn', 'Hiçbir nefis, Allah''ın izni olmadan ölmez. (Ölüm) belirli bir süreye bağlanmıştır. Kim dünya (nimet ve sevabını) isterse, ona ondan veririz. Kim de ahiret (sevabını) isterse, ona ondan veririz. Şükredenleri de mükâfatlandıracağız.'),
(3, 146, 4, 68, 'وَكَأَيِّن مِّن نَّبِىٍّ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', 'wa kaʾayyin min nabiyyin qātala maʿahu rābiyyūna kathīrun famā wahanū limā ʾaṣābahum fī sabīli llāhi wa mā ḍaʿufū wa mā istakānū wa llāhu yuḥibbu ṣ-ṣābirīn', 'Nice peygamberler de oldu ki, onlarla birlikte birçok Allah dostu savaşmış, böylece Allah yolunda başlarına gelenlerden ötürü gevşememişler, zaafiyet göstermemişler ve boyun eğmemişlerdi. Allah sabredenleri sever.'),
(3, 147, 4, 68, 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'wa mā kāna qawlahum illā an qālū rabbanā ʾighfir lanā dhunūbanā wa ʾisrāfanā fī ʾamrinā wa thabbit ʾaqdāmanā wa nṣurnā ʿalā l-qawmi l-kāfirīn', 'Onların sözleri, "Rabbimiz! Günahlarımızı ve işimizdeki aşırılıklarımızı bağışla! Ayaklarımızı sabit tut ve kâfirler topluluğuna karşı bize yardım et!" demekten başka bir şey değildi.'),
(3, 148, 4, 68, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْءَاخِرَةِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'faʾātāhumu ʾllāhu thawāba ʾddunyā waḥusna thawābi ʾlʾākhirah waʾllāhu yuḥibbu ʾlmuḥsinīn', 'Bunun üzerine Allah onlara dünya nimetini ve ahiret sevabının güzelliğini verdi. Allah iyilik edenleri sever.'),
(3, 149, 4, 69, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'yā ayyuhā alladhīna āmanū in tuṭīʿū alladhīna kafarū yaruddūkum ʿalā aʿqābikum fatanqalibū khāsirīn', 'Ey iman edenler! Eğer kâfirlere itaat ederseniz, sizi topuklarınızın üzerine gerisin geri çevirirler ve böylece ziyana uğrayanlardan olursunuz.'),
(3, 150, 4, 69, 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ', 'balillāhu mawlākum wahuwa khayrun-nāṣirīn', 'Hayır, sizin Mevlânız Allah''tır. O, yardımcıların en iyisidir.'),
(3, 151, 4, 69, 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَأْوَىٰهُمُ ٱلنَّارُ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ', 'sanulḳī fī ḳulūbi l-leẕīne kafarū r-ruʿbe bimā ʾašrakū bi-llāhi mā lem yunezzil bihi sulṭānen ve meʾvāhumu n-nāru ve biʾse meŝvā ẓ-ẓālimīn', 'Onları, Allah''a hakkında hiçbir delil indirmediği şeyleri O''na ortak koşmalarından dolayı, kalplerine korku salacağız. Varacakları yer de cehennemdir. Zalimlerin varacağı yer ne kötüdür!'),
(3, 152, 4, 69, 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْءَاخِرَةَ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ وَلَقَدْ عَفَا عَنكُمْ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', 'Ve lekad sadakakumullâhu va’dehû İz tehussûnehum biʾiznihî Hattâ izâ feşiltum ve tenâza’tum fîl emri ve ‘asaytum min ba’di mâ erâkum mâ tuhıbbûne Minkum men yurîdud dunyâ ve minkum men yurîdul âhırah Summe sarafakum ‘anhum liyebteliyekum Ve lekad ‘afâ ‘ankum Vallâhu zû fadlin ‘alel mu’minîn', 'Andolsun ki Allah size verdiği sözü tuttu. Hani siz O''nun izniyle onları biçiyordunuz. Nihayet siz gevşediğiniz, iş hakkında çekiştiğiniz ve sevdiğiniz şeyi (zaferi) size gösterdikten sonra isyan ettiğiniz zaman, kiminiz dünyayı istiyordu, kiminiz de ahireti istiyordu. Sonra sizi denemek için onlardan yüz çevirtti. Andolsun ki sizi affetti. Allah müminlere karşı lütuf sahibidir.'),
(3, 153, 4, 69, 'إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'idh tuṣʿidūna walā talwūna ʿalā ʾaḥadin war-rasūlu yadʿūkum fī ʾuḫrāykum faʾaṯābakum ġamman biġammin likaylā taḥzanū ʿalā mā fātakum walā mā ʾaṣābakum wallāhu ḫabīrum bimā taʿmalūna', 'Hani siz yokuş yukarı tırmanıyor, hiç kimseye dönüp bakmıyordunuz ve Peygamber de ensenizde size sesleniyordu. Bunun üzerine Allah, size (bu) üzüntüye karşılık bir üzüntü verdi ki, elden çıkan şeye ve başınıza gelene üzülmeyesiniz. Allah yaptıklarınızdan haberi olanıdır.'),
(3, 154, 4, 70, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَٰهُنَا قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'Tchumma anzele ''alaykum mim ba''di l-ghammi amanatan nu''āsan yaghshā ṭā''ifatan minkum wa ṭā''ifatun qad ahammathum anfusuhum yaẓunnūna bi-llāhi ghayra l-ḥaqqi ẓanna l-jāhiliyyati yaqūlūna hal lanā mina l-amri min shay''in Qul inna l-amra kullahū li-llāhi yukhfūna fī anfusihim mā lā yubdūna laka yaqūlūna law kāna lanā mina l-amri shay''un mā qutilnā hāhunā Qul law kuntum fī buyūtukum la-baraza lladhīna kutiba ''alayhimu l-qatlu ilā maḍāji''ihim wa li-yabtaliya l-llāhu mā fī ṣudūrikum wa li-yumahḥiṣa mā fī qulūbikum wa-llāhu ''alīmun bi-dhāti ṣ-ṣudūri', 'Sonra o gamdan sonra üzerinize bir güven (bir emniyet) indirdi. Sizin bir kısmınızı bürüyen bir uyuklama idi ve bir kısmı da kendi canlarının derdine düşmüşlerdi; Allah hakkında, cahiliyet düşünüşü gibi, haksız düşüncelere kapılıyorlardı. "Bu işten bize bir şey var mı?" diyorlardı. De ki: "Bütün iş Allah''ındır." Onlar, sana açıklamadıkları bir şeyi kendi içlerinde gizliyorlar. "Eğer işten bize bir şey olsaydı, burada öldürülmezdik" diyorlar. De ki: "Siz evlerinizde bile olsaydınız, üzerine ölüm yazılmış olanlar, mutlaka çıktıkları mezarlarına doğru çıkarlardı. Ve bu, Allah''ın sizin kalblerinizde olanı denemesi ve kalblerinizde olanı temizlemesi içindir. Ve Allah, göğüslerde olanı bilir."'),
(3, 155, 4, 70, 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', 'ʾinna llaḏīna tawallaw min kum yawma ltaqā l-jamʿāni ʾinnamā stazallahumu š-šayṭānu bi-baʿḍi mā kasabū wa-laqad ʿafā llāhu ʿanhum ʾinna llāha ġafūrun ḥalīmun', 'Şüphesiz içinizden o iki topluluğun (savaş meydanında) karşılaştığı gün sırtını dönenler, ancak kazandıklarının bir kısmıyla şeytan onları telkin etmiş olmasından dolayı olmuştur. Andolsun ki Allah onları affetmiştir. Şüphesiz Allah çok bağışlayıcı, halimdir.'),
(3, 156, 4, 70, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'yā ʾayyuhā llaḏīna ʾāmanū lā takūnū ka llaḏīna kafarū wa qālū li ʾiḫwānihim iḏā ḍarabū fī l-ʾarḍi ʾaw kānū ġuzzan law kānū ʿindanā mā mātū wa mā qutilū li yaǧʿala llāhu ḏālika ḥasratan fī qulūbihim wa llāhu yuḥyī wa yumītu wa llāhu bimā taʿmalūna baṣīrun', 'Ey iman edenler! Siz, yeryüzünde (bir yere) giden veya savaşta olan (din) kardeşleriniz için, ''Bizim yanımızda olsaydı ölmez ve öldürülmezdi'' diyen kâfirler gibi olmayın. Allah, bunu onların kalplerine bir tasa olarak yerleştirmek için (böyle yaptı). Allah yaşatır ve öldürür. Allah yaptıklarınızı hakkıyla görmektedir.'),
(3, 157, 4, 70, 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'Ve leʾin kutiltum fī sebīlillāhi ev muttum lemeġfiratun minallāhi ve raḥmetun ḫayrun mimmā yecmeʿūn', 'Andolsun, eğer Allah yolunda öldürülür veya ölürseniz, Allah''tan bir bağışlama ve rahmet, onların topladıklarından daha hayırlıdır.'),
(3, 158, 4, 71, 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', 'Ve leʾin muttum ev kutiltum leʾilallâhi tuhşerûn', 'Andolsun, ölseniz de öldürülseniz de mutlaka Allah''ın huzurunda toplanacaksınız.'),
(3, 159, 4, 71, 'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 'fabimā raḥmatin mina llāhi lin-ta lahum wa-law kunta faẓẓan ghalīẓa l-qalbi la-nfaḍḍū min ḥawlik fa-ʿfu ʿanhum wa-staghfir lahum wa-shāwirhum fī l-amri fa-iḏā ʿazamta fa-tawakkal ʿalā llāhi inna llāha yuḥibbu l-mutawakkilīn', 'Allah''tan bir rahmet olmasaydı, sen onlara karşı yumuşak davranamazdın. Eğer kaba ve katı yürekli olsaydın, hiç şüphesiz etrafından dağılırlardı. Artık onları affet, bağışlanmaları için dua et ve onlarla iş konusunda onlara danış. Bir de azmettiğinde Allah''a tevekkül et. Şüphesiz Allah, tevekkül edenleri sever.'),
(3, 160, 4, 71, 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'in yansurkumullahu fela galibe lekum ve in yakhdhulkum femen zellezi yansurukum mim ba''dihi ve alallahi felyetevekkeli-lmu''minun', 'Eğer Allah size yardım ederse, sizi yenecek yoktur. Eğer sizi yardımsız bırakırsa, O''ndan başka kim size yardım edebilir? Artık müminler yalnız Allah''a güvenip dayansınlar.'),
(3, 161, 4, 71, 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'wa mā kāna linabiyyin an yagulla wa man yaglul yaʾti bimā ghalla yawma l-qiyāmati thumma tuwaffā kullu nafsin mā kasabat wa hum lā yuẓlamūna', 'Hiçbir peygamber için emanete hıyanet etmek olamaz. Kim hıyanet ederse, kıyamet günü hıyanet ettiği şeyle gelir. Sonra herkese kazandığı eksiksiz ödenir. Onlar zulme uğratılmazlar.'),
(3, 162, 4, 71, 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'afamani-ttabaʿa riḍwāna-llāhi kaman bāʾa bisakhaṭin mina-llāhi wa-maʾwāhu jahanam wa-biʾsa-l-maṣīr', 'Allah''ın rızasına uyan kimse, Allah''tan bir gazabla dönen ve barınağı cehennem olan kimse gibi olur mu? Ne kötü bir dönüş yeridir!'),
(3, 163, 4, 71, 'هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'hum darajātun ʿinda llāhi wa llāhu baṣīrun bimā yaʿmalūn', 'Onlar, Allah katında dereceler (mertebeler) sahibidirler. Allah, onların yapmakta olduklarını hakkıyla görmektedir.'),
(3, 164, 4, 71, 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'leqad menna Allāhu ʿalā l-muʾminīna idh baʿatha fīhim rasūlan min anfusihim yatlu ʿalayhim āyātihī wayuzakkīhim wayuʿallimuhumu l-kitāba wal-ḥikmata wa-in kānū min qablu lafī ḍalālin mubīnin', 'Andolsun ki Allah, müminlere kendi içlerinden, onlara ayetlerini okuyan, onları arındıran, onlara Kitab''ı ve hikmeti öğreten bir peygamber göndermekle büyük bir lütufta bulunmuştur. Oysa onlar daha önce apaçık bir sapıklık içindeydiler.'),
(3, 165, 4, 71, 'أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'Awalammā aṣābatkum muṣībatu Qad aṣabtum mithlayhā Qultum annā hādhā Qul huwa min ʿindi anfusikum ʾInna Llāha ʿalā kulli shayʾin qadīr', 'Başınıza gelen bir musibet (Uhud''da iki misli kadarını) tattırmışken, nasıl olur da "Bu nereden geldi?" dersiniz? De ki: "O, sizin kendi (hatalarınızdan) dolayınızdandır." Şüphesiz Allah, her şeye hakkıyla gücü yetendir.'),
(3, 166, 4, 72, 'وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', 've mā aṣābakum yawma ltaqā l-jamʿāni fa-bi-ʾidhnillāhi wa-liyaʿlama l-muʾminīna', 'İki topluluğun karşılaştığı gün başınıza gelen (musibet), Allah''ın izniyle olmuştur ve Allah, iman edenleri ortaya çıkarmak (bilmek) içindir.'),
(3, 167, 4, 72, 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَٰكُمْ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', 'wa liyaclama alladhīna nāfaqū wa qīla lahum taʿālaw qātilū fī sabīli llāhi awi dfaʿū qālū law naclamu qitālan lattabaʿnākum hum lilkufri yawmaʾidhin aqrabu minhum lilʾīmāni yaqūlūna biʾafwāhihim mā laysa fī qulūbihim wa llāhu ʾaʿlamu bimā yaktumūna', 'Hem münafıkların bildiği, hem de onlara: "Gelin, Allah yolunda çarpışın veya savunun!" denildiği zaman: "Biz savaşmayı bilseydik elbette size tâbi olurduk." diyenlerin (halini de bilsin). Onlar o gün inanmaktan çok kâfirliğe yakındılar. Ağızlarıyla, kalplerinde olmayanı söylüyorlardı. Allah onların gizlediklerini daha iyi bilir.'),
(3, 168, 4, 72, 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'alladhīna qālū li-ikhwānihim waqaʿadū law aṭāʿūnā mā qutilū qul fadraʾū ʿan anfusikumu l-mawta in kuntum ṣādiqīna', 'Onlar ki, kendi kardeşlerine şöyle dediler ve kendileri de oturup kaldılar: "Eğer bize itaat etselerdi öldürülmezlerdi." De ki: "Eğer doğru sözlüler iseniz, haydi bakalım, ölümün kendinizi sizden uzaklaştırmasını becerebilir misiniz?"'),
(3, 169, 4, 72, 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 'wa-lā taḥsabanna alladhīna qutilū fī sabīli allāhi amwātan bal aḥyāʾun ʿinda rabbihim yurzqūna', 'Sakın Allah yolunda öldürülenleri ölüler sanma! Hayır, onlar diridirler; Rableri katında rızıklanırlar.'),
(3, 170, 4, 72, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'farḥīna bimā ʾātāhumu ʾllāhu min faḍlihī wayastabşirūna bi-llaḏīna lam yalḥaqū bihim min ḵalfihim ʾallā ḵawfun ʿalayhim walā hum yaḥzanūna', 'Allah''ın lütfundan onlara verdikleriyle sevinirler ve henüz kendilerine katılmamış olan (henüz dünyaya gelmemiş veya savaşta bulunmamış) kimseler için de, kendilerine hiçbir korku olmadığını ve üzülmeyeceklerini müjdelemek isterler.'),
(3, 171, 4, 72, 'يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', 'yastabshirūna biniʿmatin mina llāhi wa-faḍlin wa-anna llāha lā yuḍīʿu ajra l-muʾminīna', 'Allah''tan bir nimet ve fazl ile sevinirler ve Allah''ın, müminlerin mükâfatını zayi etmeyeceği (Onları mükafatlandıracağı) hususunda (da sevinirler).'),
(3, 172, 4, 72, 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', 'alladhīna istajābū lillāhi war-rasūli mim baʿdi mā aṣābahumu l-qarḥu lilladhīna aḥsanū minhum wa-ttaqaw ajrun ʿaẓīmun', 'Yaraları aldıktan sonra Allah''a ve Peygamber''e icabet edenler, onlardan iyilik yapanlar ve sakınanlar için büyük bir ecir vardır.'),
(3, 173, 4, 72, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 'alladhīna qāla lahumu n-nāsu inna n-nāsa qad jamaʿū lakum fa-khshawhum fazādahum īmānan wa qālū ḥasbunā llāhu wa niʿma l-wakīlu', 'Onlar, halkın kendilerine, ''İnsanlar size karşı toplandı, hemen onlardan korkun!'' demeleri üzerine imanları artan ve ''Allah bize yeter, O ne güzel vekildir!'' diyenlerdir.'),
(3, 174, 4, 73, 'فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', 'fa-nqalabū bi-niʿmatin mina llāhi wa-faḍlin lam yamsashum sūʾun wa-ttabaʿū riḍwāna llāhi wa-llāhu ḏū faḍlin ʿaẓīmin', 'Böylece Allah''tan bir nimet ve bol ihsanla döndüler; kendilerine hiçbir fenalık dokunmadı ve Allah''ın rızasına uydular. Allah, büyük fazl sahibidir.'),
(3, 175, 4, 73, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', 'ʾinnemā dhālikumu ʾš-šayṭānu yuḫawwifu ʾawliyāʾahu falā taḫāfūhum waḫāfūni ʾin kuntum muʾminīn', 'Şüphesiz o şeytan, kendi dostlarını (size) korkutur. Artık onlardan korkmayın, eğer mü''minlerseniz Benden korkun.'),
(3, 176, 4, 73, 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْءَاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'wa lā yaḥzunnuka alladhīna yusāriʿūna fī al-kufri innahum lan yaḍurrū Allāha shayʾan yurīdu Allāhu allā yajʿala lahum ḥaẓẓan fī al-ʾākhirati wa lahum ʿadhābun ʿaẓīmun', 'O küfürde (hızla) koşanlar seni üzmesin. Şüphesiz onlar Allah''a hiçbir zarar veremezler. Allah onlara ahirette hiçbir pay vermemek istiyor. Onlar için büyük bir azap da vardır.'),
(3, 177, 4, 73, 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ', 'inna alladhīna ishtirawu l-kufra bi-l-īmāni lan yaḍurrū Allāha shayʾan wa lahum ʿadhābun alīmun', 'Şüphesiz ki iman karşılığında küfrü satın alanlar, Allah''a hiçbir zarar veremezler. Onlar için elem dolu bir azap vardır.'),
(3, 178, 4, 73, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا وَلَهُمْ عَذَابٌ مُّهِينٌ', 'wa lā yaḥsabanna alladhīna kafarū anna mā numlī lahum khayrun li-anfusihim innamā numlī lahum li-yazdādū ithman wa lahum ʿadhābun muhīnun', 'Sakın, inkâr edenler, kendilerine mühlet vermemizin kendileri için hayırlı olduğunu sanmasınlar. Biz onlara ancak günahlarını artırmaları için mühlet veriyoruz. Onlar için alçaltıcı bir azap vardır.'),
(3, 179, 4, 73, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ', 'mā kāna llāhu liyaḏara l-muʾminīna ʿalā mā ʾantum ʿalayhi ḥattā yumīza l-xabīṯa mina ṭ-ṭayyibi wa mā kāna llāhu liyuṭliʿakum ʿalā l-ġaybi wa lākinna llāha yajtabī min rusulihī man yašāʾu fa-ʾāminū bi-llāhi wa rusulihī wa ʾin tuʾminū wa tattaqū fa-lakum ʾajrun ʿaẓīmun', 'Allah, inanmış olanları sizin bulunduğunuz hal üzere bırakacak değildir; sonunda pis olanı temizden ayıracaktır. Allah, sizi gayba muttali kılacak da değildir. Fakat Allah, elçilerinden dilediğini seçer. Bu itibarla Allah''a ve elçilerine iman edin. Eğer inanır ve sakınırsanız, sizin için büyük bir ecir vardır.'),
(3, 180, 4, 73, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم بَلْ هُوَ شَرٌّ لَّهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'Ve lâ yahsabennellezîne yebḫalûne bimâ âtâhumullâhu min faḍlihi huve hayran lehum Bel huve şerrun lehum Seyuṭavveḳûne mâ baḫilû bihî yevmel-ḳiyâmeh Ve lillâhi mîrâṡus-semâvâti vel-arḍ Vallâhu bimâ ta''melûne ḫabîr', 'Allah''ın kendilerine lütfundan verdiği şeylerde cimrilik edenler, bunun kendileri için hayırlı olduğunu sanmasınlar. Aksine bu, onlar için şerdir. Cimrilik ettikleri şey, kıyamet günü boyunlarına dolanacaktır. Göklerin ve yerin mirası Allah''ındır. Allah, yaptıklarınızdan hakkıyla haberdardır.'),
(3, 181, 4, 74, 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'leḳad semiʿa-llâhu ḳavle-lleẕîne ḳâlû inne-llâhe feḳîrun venaḥnu agniyâʾ senektübü mâ ḳâlû veḳatlehumu-lʾenbiyâʾe bigayri ḥaḳḳ venaḳûlü ẕûḳû ʿaẕâbe-lḥarîḳ', 'Andolsun ki Allah, “Allah fakirdir, biz ise zenginiz” diyenlerin sözünü işitmiştir. Onların söylediklerini ve haksız yere peygamberleri öldürmelerini yazacağız ve onlara: “Yakıcı azabı tadın!” diyeceğiz.'),
(3, 182, 4, 74, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', 'dhālika bimā qaddamat aydīkum wa anna Llāha laysa biẓallāmin lil-ʿabīd', 'İşte bu, sizin ellerinizle önden gönderdiğiniz (amellerin) yüzündendir ve Allah kullara asla zulmedici değildir.'),
(3, 183, 4, 74, 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ', 'alladhīna qālū inna allāha ʿahida ilaynā allā nuʾmina lirashūlin ḥattā yaʾtiyanā biqurbānin taʾkuluhu al-nāru qul qad jāʾakum rusulun min qablī bil-bayyināti wa-billadhī qultum fa-lima qataltumūhum in kuntum ṣādiqīna', 'Onlar, "Allah bize, ateşin yiyeceği bir kurban getirmedikçe hiçbir peygambere inanmamamızı emretti" diyenlerdir. De ki: "Benden önce nice peygamberler size açık delillerle ve istediğiniz şeyle (kurbanla) geldi. Eğer doğru sözlüler iseniz, onlara niçin öldürdünüz?"'),
(3, 184, 4, 74, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ', 'fa-ʾin kaḏḏabūka fa-qad kuḏḏiba rusulun min qablika jāʾū bi-l-bayyināti wa-z-zuburi wa-l-kitābi l-munīri', 'Eğer seni yalanlarlarsa, bil ki onlardan önceki nice peygamberler de yalanlanmıştır. Onlar, apaçık deliller, sahifeler ve aydınlatıcı kitaplarla gelmişlerdi.'),
(3, 185, 4, 74, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 'kullu nafsin dhāʾiqatu l-mawti wa-innamā tuwaffawna ʾujūra-kum yawma l-qiyāmati fa-man zuḥziḥa ʿani n-nāri wa-ʾudkhila l-jannata fa-qad fāza wa-mā l-ḥayātu d-dunyā ʾillā matāʿu l-ghurūri', 'Her nefis ölümü tadacaktır. Ve muhakkak ki, ecirleriniz (karşılıklarınız) kıyamet günü tastamam verilecektir. Kim ateşten uzaklaştırılır ve cennete konulursa, artık o kimse kurtulmuştur. Dünya hayatı ise aldatma (gurur) metaından başka bir şey değildir.'),
(3, 186, 4, 74, 'لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 'latublawunna fī amwālikum wa anfusikum walatasmanna mina alladhīna ūtū alkitaāba min qablikum wamina alladhīna ashrakū adhan kathīran wa in taṣbirū wa tattaqū faʾinna dhālika min ʿazmi alʾumūri', 'Andolsun ki mallarınız ve canlarınız konusunda imtihan edileceksiniz. Sizden önce kitap verilenlerden ve müşriklerden birçok incitici söz işiteceksiniz. Eğer sabreder ve sakınırsanız, şüphesiz bu, azmedilmesi gereken işlerdendir.'),
(3, 187, 4, 75, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا فَبِئْسَ مَا يَشْتَرُونَ', 'wa-ʾiḏ ʾaḵaḏa ʾllāhu mīṯāqa ʾllḏīna ʾūtū l-kitāb latubayyinunnahū li-n-nās wa-lā taktumūnahū fanabaḏūhu warāʾa ẓuhūrihim wa-ʾštaraū bihi ṯamanāan qalīlā fabiʾsa mā yaštarūn', 'Hani Allah, kendilerine kitap verilenlerden, "Onu mutlaka insanlara açıklayacaksınız ve onu gizlemeyeceksiniz" diye söz almıştı. Ama onlar bu ahdi, hem de az bir değere sattılar. Yaptıkları bu alışveriş ne kadar kötüdür!'),
(3, 188, 4, 75, 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'lā taḥsabanna alladhīna yafraḥūna bimā ataw wa yuḥibbūna an yuḥmadū bimā lam yafʿalū falā taḥsabannahum bimafāzatin mina l-ʿadhābi wa lahum ʿadhābun alīmun', 'Yaptıklarından dolayı sevinenleri ve yapmadıkları şeyler yüzünden övülmekten hoşlananları sakın güvende sanma! Onlar için elem dolu bir azap vardır.'),
(3, 189, 4, 75, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wa lil-lāhi mulku s-samāwāti wa l-ʾarḍi wa llāhu ʿalā kulli šayʾin qadīrun', 'Göklerin ve yerin mülkiyeti/hükümranlığı Allah''a aittir. Allah her şeye hakkıyla gücü yetendir.'),
(3, 190, 4, 75, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَءَايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ', 'inna fī khalqi s-samāwāti wa-l-arḍi wa-khtilāfi l-layli wa-n-nahāri la-āyātin li-ulī l-albāb', 'Şüphesiz göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelişinde, akıl sahipleri için (Allah''ın birliğini gösteren) deliller vardır.'),
(3, 191, 4, 75, 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'alladhīna yadhkurūna llāha qiyāman waquʿūdan waʿalā junūbihim wayatafakkarūna fī khalqi s-samāwāti wa-l-arḍi rabbanā mā khalaqta hādhā bāṭilan subḥānaka faqina ʿadhāba n-nāri', 'Onlar, ayaktayken, otururken ve yanları üzerine yatarken Allah''ı anarlar. Göklerin ve yerin yaratılışı hakkında derin derin düşünürler. Ve şöyle derler: ''Rabbimiz! Sen bunları boşuna yaratmadın. Seni tenzih ederiz. Bizi ateş azabından koru.'''),
(3, 192, 4, 75, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'Rabbanā inna man tudkhili an-nāra faqad akhzaytahū Wa mā liẓ-ẓālimīna min anṣārin', 'Ey Rabbimiz! Şüphesiz Sen kimi ateşe sokarsan, onu gerçekten rezil etmiş olursun. Zalimlerin hiçbir yardımcıları yoktur.'),
(3, 193, 4, 75, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', 'Rabbena innana sami''na munadiyan yunadi lil-imani an aminu birabbikum fe amanna Rabbena fagfir lena zunubana ve kaffir ''anna sayyiatina ve tawaffana ma''al-abrari', 'Ey Rabbimiz! Biz, ''Rabbinize iman edin'' diye çağıran bir davetçi işittik de hemen iman ettik. Rabbimiz! Günahlarımızı bize bağışla, kötülüklerimizi senden ört (git-dir) ve bizim canlarımızı iyilerle birlikte al!'),
(3, 194, 4, 75, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', 'Rabbanā wa ātina mā waʿadtanā ʿalā rusulika Wa lā tukhzinā yawma l-qiyāmati Innaka lā tukhliqu l-mīʿāda', 'Ey Rabbimiz! Ve bize peygamberlerin vasıtasıyla vaadettiğini ver ve kıyamet gününde bizi rezil etme. Şüphesiz ki Sen vaadine muhalif hareket etmezsin.'),
(3, 195, 4, 76, 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّنۢ بَعْضٍ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', 'fastajāba lahum rabbuhum annī lā uḍīʿu ʿamala ʿāmilim minkum min dhakarin aw unthā baʿḍukum min baʿḍin falladhīna hājarū wa-ukhrijū min diyārihim wa-ūdhū fī sabīlī waqātalū waqutilū la-ukaffiranna ʿanhum sayyiʾātihim wa-la-udkhilannahum jannātin tajrī min taḥtihā l-anhāru thawāban min ʿindi llāhi wa-llāhu ʿindahu ḥusnu ṯṯawābi', 'Böylece Rableri onlara şöyle cevap verdi: "Şüphesiz Ben, sizden erkek veya kadın, hiçbir çalışanın amelini zâyi etmeyeceğim. Hep birbirinizdensiniz. Hicret edenler, yurtlarından çıkarılanlar, Benim yolumda işkenceye uğrayanlar, savaşan ve öldürülenler yok mu, Ben de onların kötülüklerini elbette örteceğim ve onları, altlarından ırmaklar akan cennetlere sokacağım. Bu, Allah katından bir sevaptır. Allah''ın katında ise en güzel sevap vardır."'),
(3, 196, 4, 76, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ', 'lā yaghurrannaka taqalubul-ladhīna kafarū fīl-bilād', 'Sakın, kâfirlerin şehirlerde (serbestçe) dolaşmaları seni aldatmasın.'),
(3, 197, 4, 76, 'مَتَٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', 'matāʿun qalīlun thumma maʾwāhum jahannamu wa biʾsa l-mihādu', 'Bunlar, az bir faydalanmadır. Sonra varacakları yer cehennemdir. Ne kötü bir yataktır!'),
(3, 198, 4, 76, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ', 'lākin alladhīna ittaqaw rabbahum lahum jannātun tajrī min taḥtihā al-anhāru khālidīna fīhā nuzulan min ʿindi allāh wa mā ʿinda allāhi khayrun lil-ʾabrār', 'Ancak Rablerinden korkanlar için, altlarından ırmaklar akan, içinde ebedî kalacakları cennetler vardır. Bu, Allah katından bir ikramdır. Allah katındaki ise iyi kimseler için daha hayırlıdır.'),
(3, 199, 4, 76, 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'wa-inna min ahl-i l-kitābi laman yuʾminu bi-llāhi wa-mā ʾunzila ʾilaykum wa-mā ʾunzila ʾilayhim khāshiʿīna li-llāhi lā yashtarūna bi-ʾāyāti llāhi thamanan qalīlan ʾulāʾika lahum ʾajruhum ʿinda rabbihim ʾinna llāha sarīʿu l-ḥisābi', 'Kitap ehlinden, Allah''a, size indirilene ve kendilerine indirilene inanıp Allah''a derin bir saygı ile boyun eğenler vardır. Allah''ın ayetlerini az bir değere satmazlar. İşte onların Rableri katında mükafatları vardır. Şüphesiz Allah, hesabını çabuk görendir.'),
(3, 200, 4, 76, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 'Yā ayyuhā alladhīna āmanū iṣbirū waṣābirū warābiṭū wattaqū Allāha laʿallakum tufliḥūn', 'Ey iman edenler! Sabredin, sabır yarışında bulunun, cihat için hazırlıklı olun ve Allah''a karşı gelmekten sakının ki kurtuluşa eresiniz.'),
(4, 1, 4, 77, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا', 'yā ayyuhā n-nāsu ttaqū rabbakum alladhī khalaqakum min nafsin wāḥidatin wa khalaqa minhā zawjahā wa baththa minhumā rijālan kathīran wa nisāʾan wa ttaqū llāha alladhī tasāʾalūna bihi wal arḥāma inna llāha kāna ʿalaykum raqīban', 'Ey insanlar! Sizi topraktan yaratan ve sonra ondan eşini meydana getiren, ikisinden de birçok erkek ve kadın (insanlar) yayan Rabbinizden korkun. Kendi üzerinden ve (akraba) rahimler(i) üzerine yemin ettiğiniz Allah’tan korkun. Şüphesiz Allah, sizin üzerinizde gözetleyicidir.'),
(4, 2, 4, 77, 'وَءَاتُوا۟ ٱلْيَتَٰمَىٰٓ أَمْوَٰلَهُمْ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ إِنَّهُۥ كَانَ حُوبًا كَبِيرًا', 'wa ʾātū l-yetāmā ʾamwālahum wa lā tetebeddelū l-khabītha biṭ-ṭayyibi wa lā taʾkulū ʾamwālahum ʾilā ʾamwālikum ʾinnahu kāna ḥūban kabīran', 'Yetimlere mallarını verin. (Onların) iyi mallarını kendi kötü mallarınızla değişmeyin. Onların mallarını kendi mallarınıza katıp (yiyerek) almayın. Çünkü bu, büyük bir günah olur.'),
(4, 3, 4, 77, 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', 'wa-in khiftum allā tuqsiṭū fī l-yatāmā fa-inkihū mā ṭāba lakum mina n-nisāʾi mathnā wa-thulātha wa-rubāʿa fa-in khiftum allā taʿdilū fa-wāḥidatan aw mā malakat aymānukum dhālika adnā allā taʿūlū', 'Eğer yetim kızlar hakkında adaletsizlik etmekten korkarsanız, o halde hoşunuza giden (meşru) kadınlardan iki, üç veya dört tanesiyle evlenin. Eğer adaletsizlik etmekten korkarsanız, o halde bir (eş) ile ya da sahip olduğunuz (cariyeler) ile (yetinin). Bu, adaletsizlik yapmamaya daha yakındır.'),
(4, 4, 4, 77, 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحْلَةً فَإِن طِبْنَ لَكُمْ عَن شَىْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيٓـًٔا مَّرِيٓـًٔا', 'wa ʾātū an-nisāʾa ṣadaqātihinna niḥlatan fa ʾin ṭibna lakum ʿan šayʾin minhu nafsan fa kulūhu hanīʾan marīʾan', 'Kadınlara mehirlerini gönül rızasıyla verin. Eğer onların mehirlerin kendiliğinden bir kısmını size bağışlamaları durumunda, onu afiyetle, helal olarak yiyin.'),
(4, 5, 4, 77, 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَٰمًا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'wa lā tuʾtū s-sufahāʾa ʾamwālakumu llatī jaʿala ʾllāhu lakum qiyāman wāʾrzuqūhum fīhā wa-ksūhum wa qūlū lahum qawlan maʿrūfan', 'Allah''ın size geçim kaynağı yaptığı mallarınızı aklı ermezlere vermeyin; onları o mallardan yedirin, giydirin ve onlara güzel söz söyleyin.'),
(4, 6, 4, 77, 'وَٱبْتَلُوا۟ ٱلْيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ وَلَا تَأْكُلُوهَآ إِسْرَافًا وَبِدَارًا أَن يَكْبَرُوا۟ وَمَن كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَن كَانَ فَقِيرًا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', 'wa-btalū l-yetāmā ḥattā ʾidhā balaghū n-nikāḥa fa-ʾin ʾānastum minhum rushdan fa-d-faʿū ʾilayhim ʾamwālahum wa-lā taʾkulūhā ʾisrāfan wa-bidāran ʾan yakbarū wa-man kāna ghaniyyan fa-l-yastaʿfif wa-man kāna faqīran fa-l-yaʾkul bi-l-maʿrūfi fa-ʾidhā dafaʿtum ʾilayhim ʾamwālahum fa-ʾashhidū ʿalayhim wa-kafā bi-llāhi ḥasībā', 'Yetimleri nikah çağına gelinceye kadar imtihan edin. Onlarda reşid olduklarını görürseniz, onlara mallarını verin. Büyüyecekler diye israf ederek ve çarçabuk tüketerek yemeyin. Kim zenginse, (yetim malından) uzak dursun. Kim de fakir ise, maruf (uygun) bir şekilde yesin. Onlara mallarını verdiğinizde, şahit bulundurun. Hesap sorucu olarak Allah yeter.'),
(4, 7, 4, 78, 'لِّلرِّجَالِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًا مَّفْرُوضًا', 'lirricâli nasîbun mimmâ terake l-vâlidâni ve-l-akrabûn Ve lin-nisâi nasîbun mimmâ terake l-vâlidâni ve-l-akrabûn Mimmâ qalle minhu ev kesur Nasîben mefrûdâ', 'Ana baba ve en yakın akrabaların bıraktıklarından erkeklere bir pay vardır. Yine ana baba ve en yakın akrabaların bıraktıklarından kadınlara da bir pay vardır. Bu pay, az olsun çok olsun farz kılınmış bir hak olarak (belirlenmiştir).')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(4, 8, 4, 78, 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'wa-idhā ḥaḍara l-qismata ʾulū l-qurbā wa-l-yatāmā wa-l-masākīn fa-rzuqūhum minhu wa-qūlū lahum qawlan maʿrūfan', 'Miras taksim edildiği zaman, (orada) akrabalar, yetimler ve miskinler de hazır bulunursa, onlara da mallarından bir şeyler verin ve onlara güzel söz söyleyin.'),
(4, 9, 4, 78, 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًا سَدِيدًا', 'wa-l-yakhsha alladhīna law tarakū min khalfihim dhurriyyatan ḍiʿāfan khāfū ʿalayhim fa-l-yattaqū allāha wa-l-yaqūlū qawlan sadīdan', 'Arkalarında zayıf bir nesil bırakacakları zaman, onlar hakkında (yetimler hakkında olduğu gibi) endişe duyacak olanlar, (onlar da Allah''tan) korkup doğru söz söylesinler.'),
(4, 10, 4, 78, 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا', 'ʾinna lladhīna yaʾkulūna ʾamwāla l-yatāmā ẓulman ʾinnamā yaʾkulūna fī buṭūnihim nāran wa-sayaslawna saʿīran', 'Yetimlerin mallarını haksız yere yiyenler, şüphesiz ki karınlarına yalnızca ateş yiyorlar ve onlar çılgın bir ateşe atılacaklardır.'),
(4, 11, 4, 78, 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَٰدِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِى بِهَآ أَوْ دَيْنٍ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا فَرِيضَةً مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'yūṣīkumullāhu fī awlādikum lilddhakari mithlu ḥaẓẓi l-unthayayn fa-in kunna nisāʾan fawqa ithnatayni falahunna thuluthā mā taraka wa-in kānat wāḥidatan falahā n-niṣfu wa-li-abawayhi likulli wāḥidin minhumā s-sudusu mimmā taraka in kāna lahuū waladun fa-in lam yakun lahuū waladun wa-warithahu ābawāhu fali-ummihi th-thuluthu fa-in kāna lahuū ikhwatun fali-ummihi s-sudusu min baʿdi waṣiyyatin yūṣī bihā aw daynin ābāʾukum wa-abnāʾukum lā tadrūna ayyuhum aqrabu lakum nafʿan farīḍatan mina llāhi inna llāha kāna ʿalīman ḥakīman', 'Allah, çocuklarınız hakkında size (şöyle) tavsiye eder: Erkeğe, iki dişinin payı kadar hisse vardır. Eğer ikiden fazla kadın olup hepsi ikiden fazla iseler, onlara bıraktığı malın üçte ikisi verilir. Eğer tek ise, yarısı verilir. Ölenin çocuğu varsa, ana babasından her birine bıraktığı malın altıda biri düşer. Eğer çocuğu yok da, mirasçıları sadece ana babası ise, anasına üçte bir düşer. (Ölenin) çocuğu varsa, altıda biri ananındır. (Bu paylaştırma, yapılmış) bir vasiyetten veya borçtan sonradır. Atalarınızdan ve evlatlarınızdan hangisinin size fayda bakımından daha yakın olduğunu siz bilemezsiniz. Bunlar Allah tarafından (farz) bildirilmiştir. Şüphesiz Allah, (her şeyi) bilen, hikmet sahibi olandır.'),
(4, 12, 4, 79, 'وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ وَصِيَّةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَلِيمٌ', 'wa lakum niṣfu mā taraka azwājukum il lam yakul lahunna waladun fa in kāna lahunna waladun falakumul rubuʿu mimmā tarakna min baʿdi waṣiyyatin yūṣīna bihā aw dayn wa lahunnal rubuʿu mimmā taraktum il lam yakul lakum waladun fa in kāna lakum waladun falahunnuth thumunu mimmā taraktum min baʿdi waṣiyyatin tūṣūna bihā aw dayn wa in kāna rajulun yūraṯu kalālatan aw imraʾatun wa lahū akhun aw ukhtun falikullin wāḥidin minhuma s-sudusu fa in kānū akṯara min ḏālika fahum shurakāʾu fī th-ṯuluṯi min baʿdi waṣiyyatin yūṣā bihā aw daynin ġayra muḍārrin waṣiyyatan mina llāhi wa llāhu ʿalīmun ḥalīmun', 'Eşlerinizin çocuğu olmazsa, bıraktıklarının yarısı sizindir. Eğer eşlerinizin çocuğu olursa, bıraktıklarının dörtte biri sizindir. (Bu paylar) yaptıkları vasiyetten veya borçtan (sonra verilir). Sizin çocuğunuz olmazsa, bıraktığınızın dörtte biri eşlerinizindir. Eğer sizin çocuğunuz olursa, bıraktığınızın sekizde biri eşlerinizindir. (Bu paylar) yaptığınız vasiyetten veya borçtan (sonra verilir). Eğer bir erkek veya kadın, ana-babası ve çocuğu olmayan biri (kelale) miras bırakırsa ve miras bırakanın bir erkek veya kız kardeşi varsa, o zaman onlardan her birine altıda bir düşer. Eğer bundan daha çok iseler, (mirasın) üçte birine ortak olurlar. (Bu paylar) kimseye zarar vermeden yapılacak vasiyetten veya borçtan (sonra verilir). (Bunlar) Allah''dan birer fariza (hüküm)dir. Allah, her şeyi bilen, halimdir.'),
(4, 13, 4, 79, 'تِلْكَ حُدُودُ ٱللَّهِ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'tilka ḥudūdu llāh wa man yuṭiʿi llāha wa rasūlahū yudkhilhu jannātin tajrī min taḥtihā l-anhāru khālidīna fīhā wa ḏālika l-fawzu l-ʿaẓīm', 'Bunlar Allah''ın sınırlarıdır. Kim Allah''a ve Resûlü''ne itaat ederse, Allah onu, içinde ebedî kalacakları, zemininden ırmaklar akan cennetlere sokar. İşte bu büyük kurtuluştur.'),
(4, 14, 4, 79, 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ', 've men yaʿṣi llāha wa rasūlahū wa yataʿaddā ḥudūdahū yudkhilhu nāran khālidan fīhā wa lahū ʿaḏābun muhīn', 'Kim Allah’a ve Resûlü’ne isyan eder ve O’nun sınırlarını aşarsa, Allah onu ateşe sokar; orada ebedî kalır. Ve onun için hor düşürücü bir azap vardır.'),
(4, 15, 4, 80, 'وَٱلَّٰتِى يَأْتِينَ ٱلْفَٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًا', 'wal-lātī yaʾtīna l-fāḥishata min nisāʾikum fastashhidū ʿalayhinna ʾarbaʿatan minkum fa-ʾin shahidū fa-ʾamsikūhunna fī l-buyūti ḥattā yatawaffāhunna l-mawtu ʾaw yajʿala llāhu lahunna sabīlā', 'Kadınlarınızdan zina edenlere karşı içinizden dört şahit getirin. Eğer şahitlik ederlerse, o kadınları ölüm alıp götünceye veya Allah onlara bir yol açıncaya kadar evlerde tutun.'),
(4, 16, 4, 80, 'وَٱلَّذَانِ يَأْتِيَٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ إِنَّ ٱللَّهَ كَانَ تَوَّابًا رَّحِيمًا', 'wa-lladhāni yaʾtiyānihā minkum fa-ʾadhūhumā fa-in tābā wa-ʾaṣlaḥā fa-ʾaʿriḍū ʿanhumā ʾinna llāha kāna tawwāban raḥīmā', 'Sizden her ikisi (kadın veya erkek) bu fiili (livata) işleyecek olurlarsa, onlara eziyet edin (cezalandırın). Eğer tevbe eder ve ıslah olurlarsa, artık onlardan yüz çevirin. Şüphesiz Allah, tevbeleri kabul edendir, rahmet edendir.'),
(4, 17, 4, 80, 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ فَأُو۟لَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'innamā t-tawbetu ʿalā llāhi l-ladhīna yaʿmalūna s-sūʾa bi-jahālatin thumma yatūbūna min qarībin fa-ʾulāʾika yatūbu llāhu ʿalayhim wa-kāna llāhu ʿalīman ḥakīman', 'Allah katında (makbul) tövbe, ancak bilmeden kötülük yapıp sonra hemen tövbe edenlerin tövbesidir. İşte Allah, bunların tövbelerini kabul eder. Allah, her şeyi bilen, hikmet sahibi olandır.'),
(4, 18, 4, 80, 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', 'wa laysati t-tawbadtu lilladhīna yaʿmalūna s-sayyiʾāti ḥattā ʾidhā ḥaḍara ʾaḥadahumu l-mawtu qāla ʾinnī tubtu l-ʾāna wa lā lladhīna yamūtūna wa hum kuffārun ʾulāʾika ʾaʿtadnā lahum ʿadhāban ʾalīman', 'Ancak, kötülükleriして, nihayet kendilerinden birine ölüm gelip çatınca: "Şimdi ben tevbe ettim" diyenler ve kâfir olarak ölenler için tevbe yoktur. Bunlar için elem dolu bir azap hazırlamışızdır.'),
(4, 19, 4, 80, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًا وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًا كَثِيرًا', 'yā ʾayyuhā llaḏīna ʾāmanū lā yaḥillu lakum ʾan tarithū n-nisāʾa karhan wa lā taʿḍulūhunna li-taḏhabū bi-baʿḍi mā ʾātaytumūhunna ʾillā ʾan yaʾtīna bi-fāḥišatin mubayyinah wa ʿāširūhunna bi-l-maʿrūf fa-ʾin karihtumūhunna fa-ʿasā ʾan takrahū šayʾan wa yajʿala llāhu fīhi ḵayran kaṯīran', 'Ey iman edenler! Kadınlara tasallut etmeniz helal değildir. Apaçık bir hayasızlık yapmadıkları sürece, onlara verdiğinizin bir kısmını alıp götürmeniz için onları sıkıştırmayın. Onlarla iyi geçinin. Eğer onlardan hoşlanmazsanız, hoşlanmadığınız bir şeyde Allah çok hayır yaratabilir.'),
(4, 20, 4, 81, 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا أَتَأْخُذُونَهُۥ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'wa-in aradtum-u istibdaala zawgin makaana zawgin wa-aataytum ihdaahunna qinṭaaran fa-laa taakhudhuu min-hu shay''an ataakhudhuunahuu buhtaanan wa-ithman mubiinan', 'Eğer (boşadığınız eşinizle evlenmekten vazgeçip) başka bir eş almak ister ve onlardan birine yüklerle (mal) vermiş olsanız bile, ondan hiçbir şeyi geri almayın. Onu, bir iftira ve apaçık bir günah olarak mı alacaksınız?'),
(4, 21, 4, 81, 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَٰقًا غَلِيظًا', 'wa kayfa taʾkhudhūnahū wa qad ʾafḍā baʿḍukum ʾilā baʿḍin wa ʾakhadhna minkum mīthāqan ghalīẓan', 'Nasıl olur da onu (geri) alırsınız? Oysa siz birbirinizle (zahirde) birleşmiş ve onlardan (kadınlardan) kesin bir söz (misak) almışsınızdır.'),
(4, 22, 4, 81, 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ إِنَّهُۥ كَانَ فَٰحِشَةً وَمَقْتًا وَسَآءَ سَبِيلًا', 'wa-lā tankiḥū mā nakaḥa ʾābāʾukum mina n-nisāʾi ʾillā mā qad salafa ʾinnahu kāna fāḥiṣatan wa-maqtan wa-sāʾa sabīlā', 'Babalarınızın evlenmiş olduğu kadınlarla evlenmeyin. Ancak geçmişte olanlar hariç. Şüphesiz bu, hayâsızlık, sevimsiz bir şey ve çok kötü bir yoldur.'),
(4, 23, 4, 81, 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'ḥurrimat ʿalaykum ummahātukum wa-banātukum wa-akhawātukum wa-ʿammātukum wa-khālātukum wa-banātu l-ʾakhi wa-banātu l-ʾukhti wa-ummahātukumū llatī ʾarḍaʿnakum wa-akhawātukum mina r-raḍāʿati wa-ummahātu nisāʾikum wa-rabāʾibukumū llatī fī ḥujūrikum min nisāʾikumū llatī dakhaltum bihinna fa-ʾin lam takūnū dakhaltum bihinna fa-lā junāḥa ʿalaykum wa-ḥalāʾilu ʾabnāʾikumu lladhīna min ʾaṣlābikum wa-ʾan tajmaʿū bayna l-ʾukhtayni ʾillā mā qad salafa ʾinna llāha kāna ghafūran raḥīmā', 'Size anneleriniz, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, erkek kardeşlerinizin kızları, kız kardeşlerinizin kızları, kendi süt anneleriniz, süt (anne) kardeşleriniz, hanımlarınızın anneleri, kendileriyle zifafa girdiğiniz hanımlarınızdan olup (kucağınızda) bulunan üvey kızlarınız -eğer onlarla zifafa girmemiş olsanız- size (onlarla evlenmekte) bir günah yoktur; kendi sulbünüzden olan oğullarınızın hanımları ve iki kız kardeşi birden almak -geçmişte olanlar müstesna- size haram kılındı. Şüphesiz Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(4, 24, 5, 82, 'وَٱلْمُحْصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَٰنُكُمْ كِتَٰبَ ٱللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'wa-l-muḥṣanātu mina n-nisāʾi ʾillā mā malakat ʾaymānukum kitāba ʾllāhi ʿalaykum wa-ʾuḥilla lakum mā warāʾa ḏālikum ʾan tabtaḡū bi-ʾamwālikum muḥṣinīna ḡayra musāfiḥīna famā stamtacṭum bihi min-hunna fa-ʾātūhunna ʾujūrahunna farīḍatan wa-lā junāḥa ʿalaykum fīmā tarāḍaytum bihi min baʿdi l-farīḍati ʾinna ʾllāha kāna ʿalīman ḥakīman', 'Namuslu kadınlar da (size helaldir), ancak sahip olduğunuz cariyeler müstesna. Bunlar Allah''ın üzerinize farz kıldığı hükümlerdir. Bunların dışındaki kadınlarla iffetli olarak, zinâkâr olmaksızın, mallarınızla evlenmek istemeniz size helal kılındı. Onlardan faydalandığınız takdirde, kendilerine mehirlerini bir hak olarak verin. Hakkında bir anlaşmaya vardıktan sonra (mehir konusunda) kendi aranızda bir şey yapmanızda size bir günah yoktur. Şüphesiz Allah, her şeyi bilen, hikmet sahibi olandır.'),
(4, 25, 5, 82, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَٰتِ ٱلْمُؤْمِنَٰتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلْمُؤْمِنَٰتِ وَٱللَّهُ أَعْلَمُ بِإِيمَٰنِكُم بَعْضُكُم مِّنۢ بَعْضٍ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتٍ وَلَا مُتَّخِذَٰتِ أَخْدَانٍ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَٰحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَٰتِ مِنَ ٱلْعَذَابِ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ وَأَن تَصْبِرُوا۟ خَيْرٌ لَّكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'wa man lam yastaṭiʿ minkum ṭawlan an yankiḥa l-muḥṣanāti l-muʾmināti fa-min mā malakat aymānukum min fatayātikumu l-muʾmināti wa-llāhu aʿlamu bi-ʾīmānikum baʿḍukum min baʿḍin fa-nkīḥūhunna bi-ʾiḏni ʾahlihinna wa-ʾātūhunna ʾujūrahunna bil-maʿrūfi muḥṣanātin ġayra musāfiḥātin wa-lā muttachiḏāti ʾaḫdānin fa-iḏā ʾuḥṣinna fa-ʾin ʾatayna bi-fāḥišatin fa-ʿalayhinna niṣfu mā ʿalā l-muḥṣanāti mina l-ʿaḏābi ḏālika li-man kašiya l-ʿanata minkum wa-ʾan taṣbirū ḫayrun lakum wa-llāhu ġafūrun raḥīmun', 'İçinizden özgür mümin kadınlarla evlenmeye gücü yetmeyen kimse, sahip olduğunuz (cariyelerden) mümin genç kızlarınızdan (birini nikahlasın). Allah sizin imanınızı daha iyi bilir. Hepiniz birbirinizdensiniz. Irzlarını iffetle korumaya çalışan, zinada bulunmayan ve gizli dost tutmayan (cariyelerle) evlenmek istediğiniz takdirde, velilerinin izniyle onlarla evlenin. Mehirlerini örfe uygun olarak verin. Onlar, (evlenip) iffetli kalmak isteyenler ve gizli dost tutmayanlar olsunlar. Evlendikten sonra fuhuş yaparlarsa, onlara özgür kadınlar için (öngörülen) azabın yarısı uygulanır. Bu, içinizden günaha düşmekten korkanlar içindir. Sabretmeniz ise sizin için daha hayırlıdır. Allah, çok bağışlayandır, çok merhametlıdır.'),
(4, 26, 5, 82, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'yurīdu ʾallāhu liyubayyi-na lakum wayahdiya-kum sunana ʾalladhīna min qablakum wayatūba ʿalaykum wa-ʾallāhu ʿalīmun ḥakīmun', 'Allah, size açıklamak, sizden öncekilerin yollarını göstermek ve tevbenizi kabul etmek istiyor. Allah, bilendir, hikmet sahibidir.'),
(4, 27, 5, 83, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًا', 'wa-llāhu yurīdu an yatūba ʿalaykum wa-yurīdu llaḏīna yattabiʿūna sh-shahawāti an tamīlū maylan ʿaẓīman', 'Allah, size tevbe kapısını açmak istiyor. Nefislerine uymak isteyenler ise sizin eğilip sapmanızı istiyorlar.'),
(4, 28, 5, 83, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًا', 'yurīdu ʾallāhu ʾan yukhaffifa ʿankum wa ḫuliqa l-ʾinsānu ḍaʿīfan', 'Allah, yükünüzü hafifletmek ister; zira insan zayıf yaratılmıştır.'),
(4, 29, 5, 83, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍ مِّنكُمْ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًا', 'yā ayyuhā l-ladhīna āmanū lā taʾkulū amwālakum baynakum bil-bāṭili illā an takūna tijāratan ʿan tarāḍin minkum wa lā taqtulū anfusakum ʾinna llāha kāna bikum raḥīmā', 'Ey iman edenler! Mallarınızı aranızda batıl yollarla yemeyin. Ancak karşılıklı rıza ile olursa başka. Kendinizi öldürmeyin. Şüphesiz Allah, size karşı çok merhametlidir.'),
(4, 30, 5, 83, 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 've men yefʿal ḏālika ʿudwānan waẓulman fa-sawfa nuṣlīhi nāran wa-kāna ḏālika ʿalā llāhi yasīran', 'Kim bunları (bu yasakları) aşarak haksızlık ve zulüm yaparsa, onu ateşe atacağız. Bu ise Allah için çok kolaydır.'),
(4, 31, 5, 83, 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا', 'in tectenibū kabāʾira mā tunhawna ʿanhu nukaffir ʿankum sayyiʾātikum wa nudkhilukum mudkhalan karīman', 'Eğer siz, yasak olunduğunuz büyük günahlardan kaçınırsanız, sizin küçük günahlarınızı örteriz ve sizi şerefli bir yere (cennete) sokarız.'),
(4, 32, 5, 83, 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ لِّلرِّجَالِ نَصِيبٌ مِّمَّا ٱكْتَسَبُوا۟ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا ٱكْتَسَبْنَ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', 'wa lā tatamannaw mā faḍḍala llāhu bihiۦ baʿḍakum ʿalā ʿaḍin lir-rijāli naṣībun mimmā iktasabū wa lin-nisāʾi naṣībun mimmā iktasabna wa-sʾalū llāha min faḍlihī ʾinna llāha kāna bikulli shaiʾin ʿalīman', 'Allah''ın sizi birbirinize üstün kıldığı şeyleri temenni etmeyin. Erkekler kazandıklarından bir paya, kadınlar da kazandıklarından bir paya sahiptir. Allah''tan O''nun fazlından isteyin. Şüphesiz Allah her şeyi hakkıyla bilendir.'),
(4, 33, 5, 83, 'وَلِكُلٍّ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', 'wa likullin jaʿalnā mawālīya mimmā taraka l-wālidāni wa-l-aqrabūna wa-lladhīna ʿaqadat aymānukum fa-ātūhum naṣībahum ʾinna llāha kāna ʿalā kulli shayʾin shahīdan', 'Herkes için ana-baba ve akrabaların bıraktıklarından (mirasçı olarak) hak sahipleri kıldık. Bir de yeminlerinizle akidde bulunduklarınız var. Onlara da hisselerini verin. Şüphesiz Allah her şeye şahittir.'),
(4, 34, 5, 84, 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٌ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ وَٱلَّٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا', 'ar-ricālu qawwāmūna ʿalā n-nisāʾi bimā faḍḍala llāhu baʿḍahum ʿalā bāʿḍin wa bimāʾ anfaqū min amwālihim faṣ-ṣāliḥātu qānitātun ḥāfiẓātun lil-ġaybi bimā ḥafiẓa llāhu wallātī taḫāfūna nushūzahunna faʿiẓūhunna wahjurūhunna fī l-maḍājiʿi waḍribūhunna faʾin aṭaʿnakum falā tabġū ʿalayhinna sabīlan ʾinna llāha kāna ʿaliyyān kabīran', 'Erkekler, kadınlar üzerine gözetici ve koruyucudurlar. Çünkü Allah, onların bir kısmını diğerleri üzerine üstün kılmıştır ve yine (erkekler) kendi mallarından harcamaktadırlar. Bu sebeple iyi kadınlar, itaatkârdırlar; Allah''ın korumasına (ve gözetimine) karşılık, kendileri de gizli olanı (namuslarını, eşlerinin haklarını) korurlar. Serkeşlik etmelerinden (itaatsizliklerinden) endişe ettiğiniz kadınlara gelince; (önce) onları öğütleyin, (yine yola gelmezlerse) onları yataklarda yalnız bırakın, (bunlarla da yola gelmezlerse) onları (hafifçe) dövün. Eğer size itaat ederlerse, artık onlara karşı başka bir yol aramayın. Şüphesiz Allah, yücedir, büyüktür.'),
(4, 35, 5, 84, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًا مِّنْ أَهْلِهِۦ وَحَكَمًا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَٰحًا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًا', 'wa-in khiftum shiqāqa baynahumā fa-ibʿathū ḥakaman min ahlihī wa-ḥakaman min ahlihā in yurīdā iṣlāḥan yuwaffiqillāhu baynahumā ʾinna Allāha kāna ʿalīman khabīran', 'Eğer karı-koca arasına anlaşmazlık gireceğinden korkarsanız, o takdirde erkeğin ailesinden bir hakem, kadının ailesinden de bir hakem gönderin. Bunlar (hakemler) barıştırmak isterlerse, Allah aralarını bulur. Şüphesiz Allah, bilendir, haberdar olandır.'),
(4, 36, 5, 84, 'وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا', 'wa-ʿbudū ʾllāha wa-lā tušrikū bihi šayʾan wa-bi-l-wālidayni ʾiḥsānan wa-bi-ḏī l-qurbā wa-l-yatāmā wa-l-masākīn wa-l-jāri ḏī l-qurbā wa-l-jāri l-junubi wa-ṣ-ṣāḥibi bi-l-jambi wa-bni s-sabīli wa-mā malakat ʾaymānukum ʾinna ʾllāha lā yuḥibbu man kāna muḫtālan faḫūrā', 'Allah''a kulluk edin ve O''na hiçbir şeyi ortak koşmayın. Anne babaya, akrabalara, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolda kalmışa ve sahip olduğunuz (köle ve cariyeler) şeylere iyilik edin. Şüphesiz Allah, kibirlenen ve övünen kimseleri sevmez.'),
(4, 37, 5, 84, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'alladhīna yabkhalūn wa yaʾmurūna n-nāsa bil-bukhl wa yaktumūna mā ʾātāhumu l-lāhu min faḍlihī wa ʾaʿtadnā lil-kāfirīna ʿadhāban muhīnan', 'Onlar ki cimrilik ederler ve insanlara da cimriliği emrederler. Allah''ın kendilerine fazlından verdiğini gizlerler. Biz de kâfirler için alçaltıcı bir azap hazırlamışızdır.'),
(4, 38, 5, 85, 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًا فَسَآءَ قَرِينًا', 'wa-lladhīna yunfiqūna amwālahum riʾāʾa n-nāsi wa-lā yuʾminūna bi-llāhi wa-lā bi-l-yawmi l-ʾākhiri wa-man yakuni sh-shayṭānu lahu qorīnā fa-sāʾa qorīnā', 'Ve onlar ki, mallarını insanlara gösteriş için harcarlar ve Allah''a da âhiret gününe de inanmazlar. Ve kimin şeytanı arkadaşı olursa, o ne kötü bir arkadaştır!'),
(4, 39, 5, 85, 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', 've mâdhâ ʿalayhim lev ʾāmanû billâhi vel-yawmi l-ʾākhiri ve ʾanfaqû mimmâ rezeqahumu llâhu ve kâna llâhu bihim ʿalîmen', 'Onlar Allah''a ve ahiret gününe inanıp da Allah''ın kendilerine verdiği rızıktan (hayra) harcasalardı, Allah onlara ne diye azap ederdi ki? Allah onların her halini bilmektedir.'),
(4, 40, 5, 85, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا', 'ʾinna llāha lā yaẓlimu miṯqāla ḏarratin wa-ʾin taku ḥasatan yuḍāʿifhā wa-yuʾti min ladunhu ʾajran ʿaẓīman', 'Şüphesiz Allah, zerre kadar haksızlık etmez. Eğer iyilik olursa, onu kat kat artırır ve kendi tarafından büyük bir mükâfat verir.'),
(4, 41, 5, 85, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًا', 'fakayfa iḏā jiʾnā min kulli ummetin bišahīd wa jiʾnā bika ʿalā hāʾulāʾi šahīdā', 'Her ümmetten bir şahit getirdiğimiz ve seni de bunlara bir şahit olarak getirdiğimiz zaman halleri nice olur?'),
(4, 42, 5, 85, 'يَوْمَئِذٍ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا', 'yawmaʾiḏin yawaddu ʾallaḏīna kafarū waʿaṣawu ʾr-rasūla law tusawwā bihimu ʾl-ʾarḍu walā yaktumūna ʾllāha ḥadīṯan', 'O gün, inkâr edenler ve Peygamber''e isyan edenler, toprağa karışıvermiş olmayı temenni ederler. Allah''tan da hiçbir söz gizleyemezler.'),
(4, 43, 5, 85, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', 'yāʾayyuhā llaḏīna ʾāmanū lā taqrabū ṣ-ṣalāta waʾantum sukārā ḥattā taʿlamū mā taqūlūna walā junuban ʾillā ʿābirī sabīlin ḥattā taġtasilū waʾin kuntum maṛḍā ʾaw ʿalā safarin ʾaw jāʾa ʾaḥadun minkum mina l-ġāʾiṭi ʾaw lāmastumū n-nisāʾa falam tajidū māʾan fatayammamū ṣaʿīdan ṭayyiban famsaḥū biwujūhikum waʾaydīkum ʾinna -llāha kāna ʿafuwwan ġafūrā', 'Ey iman edenler! Sarhoşken, ne dediğinizi bilinceye kadar ve cünüpken –yolcu olanlar müstesna– gusül edinceye kadar namaza yaklaşmayın. Eğer hasta olur veya yolculukta bulunursanız, yahut biriniz tuvaletten gelirse ya da kadınlara dokunursanız ve bu durumlarda su bulamazsanız, o zaman temiz bir toprağa yönelip onunla yüzlerinizi ve ellerinizi meshedin. Şüphesiz Allah affedici, bağışlayıcıdır.'),
(4, 44, 5, 85, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يَشْتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', 'ʾalam tara ʾilā alladhīna ʾūtū naṣīban mina l-kitābi yashtarūna ḍ-ḍalālata wa yurīdūna ʾan taḍillū s-sabīla', 'Kendilerine Kitap''tan bir nasip verilmiş olanları görmedin mi? Onlar (doğruyu bırakıp) sapkınlığı satın alıyorlar ve sizin de yoldan sapmanızı istiyorlar.'),
(4, 45, 5, 86, 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا', 'wa-llāhu ʾaʿlamu bi-ʾaʿdāʾikum wa-kafā bi-llāhi walīyan wa-kafā bi-llāhi naṣīran', 'Allah düşmanlarınızı daha iyi bilir. Ve Allah, velî (dost ve yardımcı) olarak yeter, Allah, yardımcı olarak yeter.'),
(4, 46, 5, 86, 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', 'minna-lladhīna hādū yuḥarrifūna-lkalima ʿan mawāḍiʿihi wa-yaqūlūna samiʿnā wa-ʿaṣaynā wa-smeʿ ghayra musmaʿin wa-rāʿinā layyan bi-alsinatihim wa-ṭaʿnan fī-d-dīni wa-law annahum qālū samiʿnā wa-aṭaʿnā wa-smeʿ wa-nẓurna la-kāna khayran lahum wa-aqwama wa-lākin laʿanahumu-llāhu bi-kufrim fa-lā yuʾminūna illā qalīlan', 'Yahudilerden öylesi vardır ki, kelimeleri yerlerinden kaydırırlar. "Dinledik ve karşı geldik", "Dinle, dinletilmeyesin" ve "Râinâ" derler; dillerini eğip bükerek ve dine bir ta''n (kusur) olarak. Eğer onlar "Dinledik ve itaat ettik", "Dinle ve bize bak" deselerdi, kendileri için daha hayırlı ve daha doğru olurdu. Fakat Allah, küfürleri yüzünden onları lanetlemiştir. Bu yüzden pek azı iman eder.'),
(4, 47, 5, 86, 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ٱلسَّبْتِ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', 'yā ayyuhā l-ladhīna ūtū l-kitāba āmīnū bimā nazzalnā muṣaddiqan limā maʿakum min qabli an naṭmisa wujūhan fa-naruddahā ʿalā ādabārihā aw nalʿanuhum kamā laʿannā aṣḥāba s-sabti wa-kāna amru l-lāhi mafʿūlā', 'Ey Kitap verilenler! Yüzlerini (tanınmaz hale getirip) geriye çevirmeden veya Sebt Ashabını lanetlediğimiz gibi onları da lanetlemeden önce, yanınızdakini (Tevrat''ı) doğrulayıcı olarak indirdiğimiz (Kur''an''a) iman edin. Allah''ın emri (yerine) getirilmiş bir şeydir.'),
(4, 48, 5, 86, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', 'ʾinna-llāha lā yagfiru ʾan yušraka bihi wa-yagfiru mā dūna ḏālika li-man yašāʾu wa-man yušriki bi-llāhi fa-qadi-ftará ʾiṯman ʿaẓīman', 'Şüphesiz Allah, kendisine ortak koşulmasını affetmez. Bunun altındaki (günahları) ise dilediği kimse için affeder. Kim Allah''a ortak koşarsa, gerçekten büyük bir günah uydurmuş olur.'),
(4, 49, 5, 86, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', 'ʾelem tere ʾilā l-ladhīne yuzekkūne ʾenfüsehum bal-illāhu yuzekkī men yešāʾu welā yuẓlamūne fetīlā', 'Kendilerini temize çıkaranları görmedin mi? Hayır, Allah dilediğini temize çıkarır ve onlar, bir (kıl kadar) bile haksızlığa uğramazlar.'),
(4, 50, 5, 86, 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَكَفَىٰ بِهِۦٓ إِثْمًا مُّبِينًا', 'unẓur kayfa yaftarūna ʿalā Allāhi l-kaẓiba wa kafā bihi ʾithman mubīnan', 'Bak, Allah''a karşı nasıl yalan uyduruyorlar! Apaçık günah olarak bu yeter.'),
(4, 51, 5, 86, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', 'Elem tera ila-llezine utu nasiban mine-l-kitab Yu''minune bi-l-cibti ve-t-tagut Ve yequlune li-llezine keferu ha''ula''i ahda mine-llezine amenu sebila', 'Kendilerine kitaptan bir nasip verilmiş olanları görmedin mi? Onlar, Cibt''e ve Tağut''a inanırlar ve kâfirler için: "Bunlar, iman edenlerden daha doğru yoldadır" derler.'),
(4, 52, 5, 87, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', 'Ulâike-lleẕîne le’anehumu-llâh(u) Vemen yel’ani-llâhu Felen tecide lehu nasîrâ(n)', 'İşte onlar, Allah''ın lanetlediği kimselerdir. Allah kimi lanetlerse, artık sen ona hiçbir yardımcı bulamazsın.'),
(4, 53, 5, 87, 'أَمْ لَهُمْ نَصِيبٌ مِّنَ ٱلْمُلْكِ فَإِذًا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', 'ʾam lahum naṣībun mina l-mulki fa-ʾiḏan lā yuʾtūna n-nāsa naqīran', 'Yoksa mülkten onların bir nasibi mi var? (Öyle olsaydı) İnsanlara bir zerre bile vermezlerdi.'),
(4, 54, 5, 87, 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكًا عَظِيمًا', 'am yaḥsudūna n-nāsa ʿalā mā ʾātāhumu llāhu min faḍlihī fəqad ʾātaynā ʾāla ʾibrāhīma l-kitāba wa-l-ḥikmata wa ʾātaynāhum mulkan ʿaẓīman', 'Yoksa insanlar, Allah''ın kendilerine fazlından verdikleri (nimetler) yüzünden onlara haset mi ediyorlar? Oysa İbrahim ailesine de kitap ve hikmet verdik ve onlara büyük bir mülk de verdik.'),
(4, 55, 5, 87, 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', 'Fe minhum men āmena bihi Ve minhum men ṣadda ʿanhu Ve kefā bi-Jahannama saʿīrā', 'İçlerinden ona iman edenler de var, ondan yüz çeviren de. Çılgın alevli cehennem yeter!'),
(4, 56, 5, 87, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًا', 'inna alladhīna kafarū bi-ʾāyātinā sawfa nuṣlīhim nāran kullamā naḍijat julūduhum baddalnāhum julūdan ġayrahā li-yaḏūqū al-ʿaḏāb inna Allāha kāna ʿazīzan ḥakīmā', 'Şüphesiz âyetlerimizi inkâr edenleri biz ateşe atacağız. Onlar yandıkça, azabı tatmaları için derilerini yenileyeceğiz. Şüphesiz Allah, azîz ve hakîm''dir.'),
(4, 57, 5, 87, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا لَّهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti sanudkhiluhum jannātin tajrī min taḥtihā l-ʾanhāru khālidīna fīhā ʾabadan lahum fīhā ʾazwājun muṭahharatun wa-nudkhiluhum ẓillan ẓalīlan', 'İman edip salih amel işleyenleri ise, içlerinde ebediyen kalacakları, altlarından ırmaklar akan cennetlere sokacağız. Orada onlar için tertemiz eşler vardır. Ve onları, (güneşin yakıcılığından uzak) ferah ve sürekli bir gölgeye daldıracağız.'),
(4, 58, 5, 87, 'إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًا', 'ʾinna ʾallāha yaʾmurukum ʾan tuʾaddū ʾl-ʾamānāti ʾilā ʾahlihā wa-ʾiḏā ḥakamtum bayna ʾn-nāsi ʾan taḥkumū bil-ʿadli ʾinna ʾallāha niʿimmā yaʿiẓukum bihi ʾinna ʾallāha kāna samīʿan baṣīran', 'Şüphesiz Allah, emanetleri mutlaka sahiplerine ödemenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emreder. Şüphesiz Allah''ın, onunla size öğütlemesi ne güzel! Şüphesiz Allah, hakkıyla işitendir, hakkıyla görendir.'),
(4, 59, 5, 87, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', 'yā ayyuhā alladhīna ʾāmanū ʾaṭīʿū allāha wa ʾaṭīʿū ar-rasūla wa ʾūlī al-ʾamri minkum fa-ʾin tanāzaʿtum fī shayin fa-rudduhū ʾilā allāhi wa-r-rasūli ʾin kuntum tuʾminūna bi-llāhi wa-l-yawmi al-ʾākhiri dhālika khayrun wa-ʾaḥsanu taʾwīlan', 'Ey iman edenler! Allah''a itaat edin, Peygamber''e itaat edin ve içinizden olan emir sahiplerine de itaat edin. Eğer herhangi bir hususta anlaşmazlığa düşerseniz, -eğer gerçekten Allah''a ve ahiret gününe inanuyorsanız- onu Allah''a ve Peygamber''e arz edin. Bu, hem hayırlı hem de netice bakımından en güzeldir.'),
(4, 60, 5, 88, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَٰنُ أَن يُضِلَّهُمْ ضَلَٰلًۢا بَعِيدًا', 'elem tera ile-lleżîne yezʿumûne ennehum âmenû bimâ unzile ileyke vemâ unzile min ḱablik yurîdûne en yeteḥâkemû ile-ṭ-ṭâġût ve kad umirû en yekfurû bihî ve yurîdu-ş-şeyṭânu en yuḍillehum ḍalâlen ḱaʿîdâ', 'Kendilerine indirilene ve senden önce indirilene iman ettiklerini sananları görmedin mi? Onlar, tağuta (hakkın dışındaki ilahlara) muhakeme olmak istiyorlar. Oysa onu (tağutu) tanımamakla emrolunmuşlardır. Şeytan da onları (hak yoldan) uzak bir sapıklığa saptırmak istiyor.'),
(4, 61, 5, 88, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًا', 'wa-ʾidhā qīla lahum taʿālaw ʾilā mā ʾanzala ʾllāhu wa-ʾilā r-rasūli raʾayta l-munāfiqīna yaṣudhdhūna ʿanka ṣudūdan', 'Onlara: "Allah’ın indirdiğine ve Peygamber’e gelin!" dendiğinde, o münafıkların senden nasıl yüz çevirdiklerini görürsün.'),
(4, 62, 5, 88, 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَٰنًا وَتَوْفِيقًا', 'fakayfa iḏā aṣābathum muṣībatum bimā qaddamat aydīhim ṯumma jāʾūka yaḥlifūna billāhi in aradnā illā iḥsānan wat-tawfīqā', 'Elleriyle yaptıkları yüzünden başlarına bir musibet geldiğinde halleri nice olur da, sonra sana gelip: "Biz sadece iyilik etmek ve uzlaştırmak istedik" diye Allah''a yemin ederler.'),
(4, 63, 5, 88, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًا', 'ʾulāʾika lladhīna yaʿlamu llāhu mā fī qulūbihim faʾaʿriḍ ʿanhum waʿiẓhum wa qul lahum fī ʾanfusihim qawlan balīghan', 'İşte onlar, Allah''ın kalplerindekini bildiği kimselerdir. Artık sen onlara aldırma, onlara öğüt ver ve onlara kendi nefisleri hakkında (tesir edecek) söz söyle.'),
(4, 64, 5, 88, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًا رَّحِيمًا', 'Ve mā arsalnā min resūlin illā liyutāʿa bi-iḏni llāh Ve lev ennehum iḏ ẓalamū ʾenfezahum jāʾūke fastaġfarū llāhe ve-staġfere lehumu r-resūlu Le-veجدū llāhe tevvāben raḥīmā', 'Biz hiçbir resul göndermedik ki, Allah''ın izniyle itaat edilmedikçe (bırakalım). Onlar, kendilerine zulmettikleri zaman sana gelip Allah''tan bağışlanma dileselerdi ve resul de onlar için bağışlanma dileseydi, elbette Allah''ı tevbeleri kabul eden, esirgeyen olarak bulurlardı.'),
(4, 65, 5, 88, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا', 'falā wa rabbika lā yuʾminūn ḥattā yuḥakkimūka fīmā shajara baynahum thumma lā yajidū fī ʾanfusihim ḥarajan mimmā qaḍayta wa yusallimū taslīman', 'Hayır! Rabbine yemin ederim ki, onlar aralarındaki anlaşmazlıklarda seni hakem tâyin edip verdiğin hükümden içlerinde hiçbir sıkıntı duymayarak tam bir teslimiyetle teslim olmadıkça iman etmiş olmazlar.'),
(4, 66, 5, 89, 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا', 'wa-law annā katabnā ʿalayhim ani-qtulū anfusakum awi-khrujū min diyārikum mā faʿalūhu illā qalīlun minhum wa-law annahum faʿalū mā yūʿaẓūna bihi lakāna khayran lahum wa-ashadda tathbītan', 'Eğer onlara, "Kendinizi öldürün" veya "Yurtlarınızdan çıkın" diye yazmış olsaydık, onlardan pek az kimse hariç, bunu yapmazlardı. Halbuki kendilerine verilen öğütleri yapsalardı, bu onlar için daha hayırlı ve (imanlarını) daha çok pekiştirici olurdu.'),
(4, 67, 5, 89, 'وَإِذًا لَّءَاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا', 'wa-idhan la-aataynāhum min ladunnā ajran ʿaẓīman', 'Ve o takdirde onlara tarafımızdan büyük bir ecir verirdik.'),
(4, 68, 5, 89, 'وَلَهَدَيْنَٰهُمْ صِرَٰطًا مُّسْتَقِيمًا', 'wa lahadaynāhum ṣirāṭan mustaqīman', 'Ve onları dosdoğru yola iletirdik.'),
(4, 69, 5, 89, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَ وَحَسُنَ أُو۟لَٰٓئِكَ رَفِيقًا', 'Ve men yuṭiʿi l-lāhe wa-r-rasūla fa-ʾulāʾike maʿa l-ladhīna ʾanʿama l-lāhu ʿalayhim mina n-nabiyyīna wa-ṣ-ṣiddīqīna wa-sh-shuhadāʾi wa-ṣ-ṣāliḥīna Wa ḥasuna ʾulāʾika rafīqan', 'Kim Allah''a ve Resûl''e itaat ederse, işte onlar Allah''ın kendilerine ni''met verdiği peygamberler, sıddîklar, şehidler ve salihlerle beraberdir. Ve onlar ne güzel arkadaştır!'),
(4, 70, 5, 89, 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ وَكَفَىٰ بِٱللَّهِ عَلِيمًا', 'dhālika l-faḍlu mina llāhi wa kafā bi llāhi ʿalīmā', 'Bu, Allah''tan bir fazl''dır. Ve Allah, her şeyi bilen olarak yeter.'),
(4, 71, 5, 89, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًا', 'yā ayyuhā l-ladhīna āmanū khudhū ḥidhra-kum fa-nfirū thubātin awi-nfirū jamīʿan', 'Ey iman edenler! Tedbirinizi alın da (düşman üzerine) küçük birlikler hâlinde yahut topyekûn seferber olun.'),
(4, 72, 5, 89, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَٰبَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا', 'wa-inna minkum la-man la-yubatti''anna fa-in asābatkum musībatu qāla qad an''ama -llāhu ''alayya idh lam akun ma''ahum shahīdan', 'Ve içinizden, gerçekten öyleleri vardır ki, yavaşlık eder. Size bir musibet isabet ederse, "Allah bana lütfetmişti, onlarla birlikte şahit olmadım" der.'),
(4, 73, 5, 89, 'وَلَئِنْ أَصَٰبَكُمْ فَضْلٌ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌ يَٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا', 'Ve leʾin ʾaṣābakum faḍlun mina Allāhi leyaqūlanna kaʾan lam takun baynakum wa baynahū mawaddatun yā laytanī kuntu maʿahum faʾafūza fawzan ʿaẓīman', 'Andolsun ki, eğer size Allah''tan bir lütuf erişirse, sanki sizinle onun arasında hiçbir sevgi bağı yokmuş gibi, "Keşke ben de onlarla beraber olsaydım da büyük bir başarıya ulaşsaydım!" der.'),
(4, 74, 5, 89, 'فَلْيُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْءَاخِرَةِ وَمَن يُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', 'fa-l-yuqātil fī sabīli-llāhi-lladhīna yashrūna-l-ḥayāta-d-dunyā bi-l-ʾākhirah wa-man yuqātil fī sabīli-llāhi fa-yuqtal aw yaghlib fa-sawfa nuʾtīhi ʾajran ʿaẓīman', 'Öyleyse, dünya hayatını ahiret karşılığında satanlar, Allah yolunda savaşsınlar. Kim Allah yolunda savaşır da öldürülür veya galip gelirse, ona büyük bir ecir vereceğiz.'),
(4, 75, 5, 90, 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', 'Ve mâ lekum lâ tukâtilûne fî sebîlillâhi vel mustad''afîne miner ricâli ven nisâi vel vildâni ellezîne yekûlûne rabbenaâ ehrignâ min hâzihil karyetil zâlimi ehluhâ Vec''al lenâ min ledunke veliyyen Vec''al lenâ min ledunke nasîran', 'Allah yolunda ve "Rabbimiz! Bizleri halkı zalim olan bu şehirden çıkar, bize katından bir veli (koruyucu) gönder, bize katından bir yardımcı yolla!" diyen zayıf düşürülmüş erkekler, kadınlar ve çocukların (kurtarılması) uğrunda sizin ne sebebiniz var da savaşmıyorsunuz?'),
(4, 76, 5, 90, 'ٱلَّذِينَ ءَامَنُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ كَفَرُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَٰنِ إِنَّ كَيْدَ ٱلشَّيْطَٰنِ كَانَ ضَعِيفًا', 'alladhīna ʾāmanū yuqātilūna fī sabīli llāhi wa-lladhīna kafarū yuqātilūna fī sabīli ṭ-ṭāgūti fa-qātilū ʾawliyāʾa sh-shayṭāni ʾinna kayda sh-shayṭāni kāna ḍaʿīfā', 'İman edenler Allah yolunda savaşırlar. Küfredenler ise azgınların (tağutun) yolunda savaşırlar. O halde şeytanın dostlarıyla savaşın! Şüphesiz şeytanın hilesi zayıftır.'),
(4, 77, 5, 90, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةً وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ قُلْ مَتَٰعُ ٱلدُّنْيَا قَلِيلٌ وَٱلْءَاخِرَةُ خَيْرٌ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', 'ʾalam tara ʾilā alladhīna qīla lahum kuffū ʾaydiyakum wa-ʾaqīmū ʾaṣ-ṣalāta wa-ʾātū ʾaz-zakāta falammā kutiba ʿalayhimu l-qitālu ʾidhā farīqun minhum yakhshawna n-nāsa kakhasyati llāhi ʾaw ʾashadda khashyatan wa-qālū rabbanā lima katabta ʿalaynā l-qitāla lawlā ʾakhkhartanā ʾilā ʾajalin qarībin qul matāʿu d-dunyā qalīlun wa-l-ʾākhiratu khayrun limani ʾttaqā wa-lā tuẓlamūna fatīlan', 'Kendilerine, ''Elinizi (savaştan) çekin, namazı dosdoğru kılın ve zekâtı verin'' denilen kimseleri görmedin mi? Üzerlerine savaş farz kılınınca, hemen onlardan bir grup insanlardan Allah korkar gibi, hatta daha şiddetli bir korkuyla korktular ve şöyle dediler: ''Rabbimiz! Bize neden savaş farz kıldın? Bizi yakın bir zamana kadar erteleseydin ya!'' De ki: ''Dünya metaı azdır. Kim takva sahibi olursa, ahiret daha hayırlıdır. Ve size kıl kadar haksızlık edilmez.'''),
(4, 78, 5, 90, 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍ مُّشَيَّدَةٍ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ قُلْ كُلٌّ مِّنْ عِندِ ٱللَّهِ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا', 'ʾAynamā takūnū yudrikukumul-mawtu Wa law kuntum fī burūjim-mušayyadah Wa ʾin tuṣibhum ḥasanatun yaqūlū hāḏihi min ʿindillāh Wa ʾin tuṣibhum sayyiʾatun yaqūlū hāḏihi min ʿindik Qul kullun min ʿindillāh Famā li hāʾulāʾil-qawmi lā yakādūna yafqahūna ḥadīṯā', 'Nerede olursanız olun ölüm size ulaşır. Sizi sağlam kaleler içinde bulunduğunuz zaman bile (yakalar). Onlara bir iyilik gelince: "Bu, Allah''tandır" derler. Bir de kötülük gelince: "Bu, senden (Muhammed''den) ötürüdür" derler. De ki: "Hepsi Allah''tandır." Bu topluluğa ne oluyor ki, sözü anlamaya yaklaşmıyorlar?'),
(4, 79, 5, 90, 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولًا وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'mā aṣābaki min ḥasanation famina-llāh wa mā aṣābaki min sayyiʾation famin nafsik wa arsalnāka li-n-nāsi rasūlan wa kafā bi-llāhi shahīdan', 'Sana iyilikten her ne gelirse, Allah''tandır. Kötülükten her ne gelirse, o da kendindendir. Seni insanlara bir peygamber olarak gönderdik. Şahit olarak Allah yeter.'),
(4, 80, 5, 91, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا', 'man yuṭiʿi r-rasūla faqad aṭāʿa llāha wa man tawallā famā ʾarsalnāka ʿalayhim ḥafīẓan', 'Kim Resûl''e itaat ederse, Allah''a itaat etmiş olur. Kim de yüz çevirirse, (bil ki) biz seni onlara bir koruyucu olarak göndermedik.'),
(4, 81, 5, 91, 'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'wa-yaqūlūna ṭāʿatun fa-ʾidhā barazū min ʿindika bayyata ṭāʾifatun minhum ghayra alladhī taqūlu wa-llāhu yaktubu mā yubaywitūna fa-ʾaʿriḍ ʿanhum wa-tawakkal ʿalā llāhi wa-kafā bi-llāhi wakīlan', 'Onlar: "İtaat ettik" derler. Fakat senden ayrılıp yanlarından çıktıklarında, onlardan bir grup, geceleyin senin söylemediğin bir şeyi kurar. Allah onların kurduklarını yazıyor. Sen onlara aldırma ve Allah''a tevekkül et. Vekil olarak Allah yeter.'),
(4, 82, 5, 91, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَٰفًا كَثِيرًا', 'ʾafalā yatadabbarūna l-qurʾāna walaw kāna min ʿindi ġayri l-lāhi lawajadū fīhi ʾiḫtilāfan kaṯīran', 'Onlar Kur''an''ı düşünmüyorlar mı? Eğer o, Allah''tan başkasından gelmiş olsaydı, şüphesiz içinde pek çok çelişki bulurlardı.'),
(4, 83, 5, 91, 'وَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًا', 'wa-idhā jāʾahum ʾamrun min al-ʾamni ʾawi al-khawfi ʾadhāʿū bihi wa-law raddūhu ʾilā ar-rasūli wa-ʾilā ʾūlī al-ʾamri minhum la-ʿalimahu alladhīna yastanbiṭūnahu minhum wa-lawlā faḍlu Allāhi ʿalaykum wa-raḥmatuhu lattabaʿtum u-sh-shayṭāna ʾillā qalīlan', 'Onlara güvenlik veya korku ile ilgili bir iş geldiğinde, hemen onu yayarlar. Oysa eğer onu peygambere ve kendi içlerinden emir sahiplerine götürselerdi, onlardan onu anlayanlar onun ne olduğunu anlarlardı. Eğer üzerinizde Allah''ın lütuf ve merhameti olmasaydı, içinizden pek azınız müstesna, şeytana uymuş olurdunuz.'),
(4, 84, 5, 91, 'فَقَٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ وَحَرِّضِ ٱلْمُؤْمِنِينَ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا', 'faqātil fī sabīli llāh lā tukallafu illā nafsak wa ḥarriḍi l-muʾminīn ʿasā llāhu an yakuffa baʾsa lladhīna kafarū wa llāhu ʾashaddu baʾsan wa ʾashaddu tankīlā', 'Artık Allah yolunda savaş; sen ancak kendi nefsinden sorumlusun. Mü''minleri de teşvik et. Umulur ki Allah, kâfirlerin gücünü kırar. Allah''ın gücü daha çetin ve cezası daha şiddetlidir.'),
(4, 85, 5, 91, 'مَّن يَشْفَعْ شَفَٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا', 'man yashfaʿ shafāʿatan ḥasanatan yakun lahū naṣībun minhā wa man yashfaʿ shafāʿatan sayyiʾatan yakun lahū kiflun minhā wa kāna -llāhu ʿalā kulli shayʾin muqītan', 'Kim güzel bir aracılık yaparsa, ondan kendisine bir pay vardır. Kim de kötü bir aracılık yaparsa, ondan da kendisine bir pay vardır. Allah her şeye hakkıyla kâdirdir.'),
(4, 86, 5, 91, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', 'wa-idhā ḥuyyītum bitaḥiyyatin faḥayyū bi-aḥsana minhā aw ruddūhā ʾinna ʾllāha kāna ʿalā kulli shayʾin ḥasībā', 'Siz bir selâmla selâmlandığınız zaman, ondan daha iyisiyle selâmlayın veya aynıyla karşılık verin. Şüphesiz Allah, her şeyin hesabını hakkıyla bilendir.'),
(4, 87, 5, 92, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا', 'Allāhu lā ilāha illā huw leyecmeʿannekum ilā yawmi l-qiyāmah lā rayba fīh wa man aṣdaqu mina llāhi ḥadīthā', 'Allah, O''ndan başka ilah yoktur. Sizi, şüphe yok, kıyamet gününde elbette toplayacaktır. Allah''dan daha doğru sözlü kim vardır?'),
(4, 88, 5, 92, 'فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', 'famā lakum fī l-munāfiqīna fiʾatayn wa-llāhu arkusahum bimā kasabū aturīdūna an tahdū man aḍalla llāhu wa-man yuḍlili llāhu falan tajida lahū sabīlā', 'Münafıklar konusunda ne oluyor size de iki gruba ayrılmışsınız? Oysa Allah, onların kazandıkları yüzünden (küfürlerine devam etmeleri sebebiyle) onları altüst etmiş (hak yola dönmelerini engellemiş)tir. Allah''ın saptırdığını mı doğru yola getirmek istiyorsunuz? Allah''ın saptırdığı kimse için asla bir yol bulamazsınız.'),
(4, 89, 5, 92, 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا', 'waddū law takfurūna kamā kafarū fatakūnūna sawāʾan falā tattakhidhū minhum awliyāʾa ḥattā yuhājirū fī sabīli ʾllāhi faʾin tawallaw fakhudhūhum waqtulūhum ḥaythu wajadtumūhum walā tattakhidhū minhum waliyyan walā naṣīran', 'Onlar, kendileri küfrettikleri gibi sizin de küfretmenizi ve böylece sizinle bir olmanızı istiyorlar. Allah yolunda hicret edinceye kadar onlardan dostlar edinmeyin. Eğer yüz çevirirlerse, onları yakalayın ve her nerede bulursanız öldürün. Onlardan ne bir dost edinin ne de bir yardımcı.'),
(4, 90, 5, 92, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَٰتِلُوكُمْ أَوْ يُقَٰتِلُوا۟ قَوْمَهُمْ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا', 'illa alladhīna yaṣilūna ilā qawmin baynakum wa-baynahum mīthāqun aw jāʾūkum ḥaṣirat ṣudūruhum an yuqātilūkum aw yuqātilū qawmahum wa-law shāʾa allāhu la-sallaṭahum ʿalaykum falaqātalūkum fa-ʾini iʿtazalūkum falam yuqātilūkum wa-ʾalqaw ʾilaykumu s-salama fa-mā jaʿala allāhu lakum ʿalayhim sabīlan', 'Ancak sizinle aralarında antlaşma bulunan bir kavme ulaşanlar veya size gelip de ya sizinle savaşmak ya da kendi kavimleriyle savaşmak hususunda göğüsleri daralmış olanlar müstesnadır. Eğer Allah dileseydi, onları sizin üzerinize musallat kılardı da sizinle savaşırlardı. Eğer sizden uzaklaşıp da sizinle savaşmadılar ve size barış teklif ettilerse, Allah size onların aleyhine bir yol vermemiştir.'),
(4, 91, 5, 92, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأُو۟لَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰنًا مُّبِينًا', 'sataciduuna aahariyyna yuriiduuna an ya''manuukum wa ya''manuu qawmahum kulla maa rudduu ilaa l-fitneti urkisuu fiihaa fa-in lam ya''taziluukum wa yulquu ilaykumu s-salama wa yakuffuu aydiyahum fa-khudhuuhum wa-qtuluuhum haythu thaqiftumuuhum wa-ulaa''ikum ja''alnaa lakum ''alayhim sulthaanan mubiinaa', 'Onları, hem sizden emin olmak hem de kendi kavimlerinden emin olmak isteyen başka kimseler de bulacaksınız. Ne zaman fitneye (huzursuzluğa ve fesada) çağrılsalar, ona hemen atılırlar. Eğer sizden uzak durmazlarsa, sizinle barış yapmaya yanaşmazlarsa ve ellerini (savaştan) çekmezlerse, onları yakalayıp bulduğunuz yerde öldürün. İşte bunlara karşı size apaçık bir yetki (ve delil) verdik.'),
(4, 92, 5, 93, 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 've-mā kāne li-muʾmin-in ʾen yaqtule muʾmin-an ʾillā khaṭaʾā ve-men qatele muʾmin-an khaṭaʾā fe-taḥrīru raqabet-in muʾminetin ve-diyyetun musellemetun ʾilā ʾahlihī ʾillā ʾen yaṣṣaddeqū fe-ʾin kāne min qawmin ʿaduvvin lekum ve-huve muʾminun fe-taḥrīru raqabet-in muʾminetin ve-ʾin kāne min qawmin-in beynakum ve-beynehum mīthāqun fe-diyyetun musellemetun ʾilā ʾahlihī ve-taḥrīru raqabet-in muʾminetin fe-men lem yecid fe-ṣiyāmu şehreyni mutetābiʿeyni tawbetan mine-llāhi ve-kāne-llāhu ʿalīman ḥakīmā', 'Mü''min, mü''mini öldüremez; ancak yanlışlıkla (öldürebilir). Yanlışlıkla bir mü''mini öldüren kimse, mü''min bir köle azat etmeli ve (öldürülenin) ailesine (diyet olarak) teslim edilecek bir bedel vermelidir. Ancak (aile) bunu sadaka olarak bağışlarlarsa, (bu durumda) sizden (ödemeniz gereken) bu bedel kalkar. Eğer (öldürülen) size düşman bir topluluktan olup da kendisi mü''min ise, (o zaman) mü''min bir köle azat etmek gerekir. Eğer (öldürülen) sizinle aralarında antlaşma bulunan bir topluluktan ise, (o zaman) ailesine teslim edilecek bir bedel ve mü''min bir köle azat etmek gerekir. Bunları bulamayan kimse, Allah''tan bir tevbe olmak üzere peş peşe iki ay oruç tutmalıdır. Allah, her şeyi bilen, hikmet sahibi olandır.'),
(4, 93, 5, 93, 'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا', 'wa-man yaqtul muʾminan mutaʿammidan fa-jazāʾuhu jahanam khālidan fīhā wa-ghaḍiba ʾllāhu ʿalayhi wa-laʿanahu wa-ʾaʿadda lahu ʿadhāban ʿaẓīman', 'Kim bir mümini kasden öldürürse, cezası içinde ebedî kalacağı cehennemdir. Allah ona gazab etmiştir, onu lânetlemiştir ve ona büyük bir azap hazırlamıştır.'),
(4, 94, 5, 93, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'yā ayyuhā alladhīna āmanū idhā ḍarabtum fī sabīli llāhi fatabayyanū wa lā taqūlū liman alqā ilaykumu s-salāma lasta muʾminan tabtaghūna ʿaraḍa l-ḥayāti d-dunyā fa ʿinda llāhi maghānimu kathīrah kadhālika kuntum min qablu fa manna llāhu ʿalaykum fatabayyanū inna llāha kāna bimā taʿmalūna khabīran', 'Ey iman edenler! Allah yolunda (savaşa) çıktığınız zaman, iyice araştırın ve size selam verene, dünya hayatının geçici menfaatleri peşinde koşarak, “Sen mümin değilsin” demeyin. Halbuki Allah katında pek çok ganimetler vardır. Daha önce siz de böyle idiniz de Allah size lütufta bulundu. Onun için iyice araştırın. Şüphesiz Allah yaptıklarınızdan haberdardır.'),
(4, 95, 5, 94, 'لَّا يَسْتَوِى ٱلْقَٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَٰعِدِينَ دَرَجَةً وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَفَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ عَلَى ٱلْقَٰعِدِينَ أَجْرًا عَظِيمًا', 'lā yastawī l-qāʿidūna mina l-muʾminīna ġayru ʾūlī ḍ-ḍarari wa-l-muǧāhidūna fī sabīli llāhi bi-ʾamwālihim wa-ʾanfusihim faḍḍala llāhu l-muǧāhidīna bi-ʾamwālihim wa-ʾanfusihim ʿalā l-qāʿidīna darajatan wa-kullan waʿada llāhu l-ḥusnā wa-faḍḍala llāhu l-muǧāhidīna ʿalā l-qāʿidīna ʾajran ʿaẓīman', 'Müminlerden (savaşa katılmayıp) oturanlar, özür sahibi olanlar dışında, mallarıyla ve canlarıyla Allah yolunda cihad edenlerle bir olmazlar. Mallarıyla ve canlarıyla cihad edenleri, oturanların derecesinden Allah üstün kılmıştır. Her birine Allah en güzel olanı vaad etmiştir. Allah, mallarıyla ve canlarıyla cihad edenleri, oturanların üstüne büyük bir ecirle üstün kılmıştır.'),
(4, 96, 5, 94, 'دَرَجَٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'darajātin minhu wa maghfiratan wa raḥmah wa kāna Allāhu ghafūran raḥīmā', 'Onlardan dereceler, bağışlama ve rahmettir. Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(4, 97, 5, 94, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا فَأُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَسَآءَتْ مَصِيرًا', 'ʾinna lladhīna tawaffāhumu l-malāʾikatu ẓālimī ʾanfusihim qālū fīma kuntum qālū kunnā mustaḍʿafīna fī l-ʾarḍi qālū ʾalam takun ʾarḍu llāhi wāsiʿatan fatuhājirū fīhā fa-ʾulāʾika maʾwāhumu jahannamu wa-sāʾat maṣīrā', 'Canlarına zulmetmiş olan kimseleri melekler vefatırdıkları zaman, (onlara şöyle) derler: «Ne hal üzere idiniz?» (Onlar da) «Biz yeryüzünde darda kalan kimselerdik» derler. (Melekler) «Allah''ın arzı geniş değil miydi ki, orada hicret etseydiniz?» derler. İşte bunların yurdu cehennemdir. Orası ne kötü bir dönüş yeridir!'),
(4, 98, 5, 94, 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا', 'illa al-mustaḍʿafīna mina ar-ricāli wa-n-nisāʾi wa-l-wildāni lā yastaṭīʿūna ḥīlatan wa lā yahtadūna sabīlā', 'Ancak çaresiz kalan, (hicret için) hiçbir çare bulamayan ve hiçbir yol bulamayan erkekler, kadınlar ve çocuklardan başka.'),
(4, 99, 5, 94, 'فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا', 'faʾūlāʾika ʿasā ʾllāhu ʾan yaʿfuwa ʿanhum wa kāna ʾllāhu ʿafuwwan ġafūrā', 'İşte bunlardır Allah''ın kendilerinden affetmesi umulanlar. Allah, affedicidir, bağışlayıcıdır.'),
(4, 100, 5, 94, 'وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'Ve men yuhâcir fî sebîlillâhi yecid fil-ardi murâgaman kesîran ve se''ah Ve men yahruc min beytihî muhâciran ilallâhi ve resûlihî Summe yudrikhul-mevtu fe kad veka''a ecruhu ''alallâh Ve kânallâhu gafûran rahîmâ', 'Kim Allah yolunda hicret ederse, yeryüzünde (barınacak) çok yer ve genişlik bulur. Kim de evinden Allah''a ve Resûlü''ne hicret ederek çıkar da sonra kendisini ölüm yakalarsa, artık onun mükâfatı Allah''a düşmüştür. Allah, çok bağışlayıcıdır, çok merhamet edicidir.'),
(4, 101, 5, 94, 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ إِنَّ ٱلْكَٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا', 'wa ʾiḏā ḍarabtum fī l-ʾarḍi falaysa ʿalaykum junāḥun ʾan taqṣurū mina ṣ-ṣalāti ʾin ḫiftum ʾan yaftinakumu l-laḏīna kafarū ʾinna l-kāfirīna kānū lakum ʿaduwwan mubīnan', 'Yeryüzünde sefer halindeyken namazı kısaltmanızda size bir günah yoktur. Eğer kâfirlerin sizi fitneye düşürmelerinden endişe ederseniz. Şüphesiz kâfirler sizin için apaçık düşmandırlar.'),
(4, 102, 5, 95, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ وَخُذُوا۟ حِذْرَكُمْ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'wa-idhā kunta fīhim fa-aqamta lahumu ṣ-ṣalāta fal-taqom ṭāʾifatun minhum maʿaka wal-yaʾkhudhū ʾasliḥatahum fa-idhā sajadū falyakūnū min warāʾikum wal-taʾti ṭāʾifatun ʾukhrā lam yuṣallū falyuṣallū maʿaka wal-yaʾkhudhū ḥidhrahum wa-ʾasliḥatahum wadda l-ladhīna kafarū law taghfulūna ʿan ʾasliḥatikum wa-ʾamtiʿatikum fa-yamīlūna ʿalaykum maylatan wāḥidatan wa-lā junāḥa ʿalaykum in kāna bikum ʾadhan min maṭarin ʾaw kuntum marḍā ʾan taḍaʿū ʾasliḥatakum wa-khudhū ḥidhrakum ʾinna-llāha ʾaʿadda lil-kāfirīna ʿadhāban muhīnan', 'Sen içlerinde olup da onlara namaz kıldırdığın zaman, onlardan bir grup seninle birlikte (namaza) dursun ve silahlarını yanlarına alsınlar. Secdeyi tamamladıklarında, (düşman tarafına) arkanıza geçsinler. Henüz namaz kılmamış olan diğer grup gelsin, seninle birlikte namaz kılsınlar ve ihtiyatlı olsunlar, silahlarını yanlarına alsınlar. Küfre sapanlar, sizin silahlarınızdan ve eşyalarınızdan gafil olmanızı isterler ki size tek bir seferde (baskın) yapabilsinler. Eğer yağmurdan dolayı size eziyet varsa veya siz hasta iseniz, silahlarınızı bırakmanızda size bir günah yoktur. İhtiyatlı olun! Şüphesiz Allah, kâfirler için alçaltıcı bir azap hazırlamıştır.'),
(4, 103, 5, 95, 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًا مَّوْقُوتًا', 'faʾiḏā qaḍaytumū ṣ-ṣalāta faḏkurū llāha qiyāman waquʿūdan wa ʿalā junūbikum faʾiḏā ṭmaʾnنتum faʾaqīmū ṣ-ṣalāta ʾinna ṣ-ṣalāta kānat ʿalā l-muʾminīna kitāban mawqūtā', 'Namazı kıldınız mı, Allah''ı ayaktayken, otururken ve yanlarınız üzereyken (her halinizde) zikredin. Huzura kavuştuğunuzda namazı (tam olarak) kılın. Çünkü namaz, müminler üzerine vakti (belirlenmiş) bir farz olmuştur.'),
(4, 104, 5, 95, 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'wa lā tahinū fī-btiġāʾi l-qawmi in takūnū taʾlamūna fa-ʾinnahum yaʾlamūna kamā taʾlamūna wa tarjūna mina-llāhi mā lā yarjūna wa kāna-llāhu ʿalīman ḥakīmā', 'Düşman topluluğuna karşı gevşeklik göstermeyin. Eğer siz acı çekiyorsanız, bilin ki onlar da sizin acı çektiğiniz gibi acı çekmektedirler. Siz Allah''tan onların ummadığı ümitlerini umarsınız. Allah her şeyi bilen, hikmet sahibi olandır.'),
(4, 105, 5, 95, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا', 'ʾinna ʾanzalnā ʾilayka l-kitāba bil-ḥaqqi litaḥkuma bayna n-nāsi bimā ʾarāka ʾllāhu wa lā takun lil-khāʾinīna khaṣīmā', 'Şüphesiz biz sana o kitabı hak ile indirdik ki, Allah''ın sana gösterdiği şekilde insanlar arasında hükmedesin. Sakın hainlerin savunucusu olma.'),
(4, 106, 5, 96, 'وَٱسْتَغْفِرِ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'wa-staghfiri llāha ʾinna llāha kāna ghafūran raḥīmā', 'Allah''tan bağışlanma dile. Şüphesiz Allah, çok bağışlayıcıdır, çok merhametlidir.'),
(4, 107, 5, 96, 'وَلَا تُجَٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا', 'walā tujādil ʿani lladhīna yakh''tānūna anfusahum ʾinna l-lāha lā yuḥibbu man kāna khawwānan ʾathīmā', 'Kendilerine ihanet edenleri savunma. Şüphesiz Allah, hain ve günahkâr olan kimseyi sevmez.'),
(4, 108, 5, 96, 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', 'yastakhfūna mina n-nāsi wa lā yastakhfūna mina llāhi wa huwa maʿahum iḏ yubayyi-tūna mā lā yarḍā mina l-qawli wa kāna llāhu bimā yaʿmalūna muḥīṭan', 'Onlar, insanlardan gizlenirler de Allah''tan gizlenmezler. Halbuki O, razı olmayacağı sözleri (geceleri) planladıkları zaman, kendileriyle beraberdir. Allah onların yapmakta olduklarını kuşatıcıdır.'),
(4, 109, 5, 96, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا', 'Hā antum hāʾulāʾi jādaltum ʿanhum fī l-ḥayāti d-dunyā Fa-man yujādilu ʾllāha ʿanhum yawma l-qiyāmati ʾAm man yakūnu ʿalayhim wakīlā', 'İşte sizler, dünya hayatında onlardan yana tartışanlarsınız. Kıyamet gününde onlardan Allah''a karşı kim tartışacak? Ya da kim onlara vekil olabilir?'),
(4, 110, 5, 96, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا', 'wa man yaʿmal sūʾan aw yaẓlim nafsahū thumma yastaghfir Allāh yajid Allāh ghafūran raḥīmā', 'Kim bir kötülük yapar veya nefsine zulmeder de sonra Allah''tan bağışlanma dilerse, Allah''ı çok bağışlayıcı, çok merhamet edici olarak bulur.'),
(4, 111, 5, 96, 'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 've-men yeksib iŝmen fe-innemā yeksibuhu ʿalā nefsihī ve-kāne Llāhu ʿalīmen ḥakīmen', 'Kim bir günah kazanırsa, onu kendi aleyhine kazanmış olur. Allah, her şeyi bilen, hikmet sahibidir.'),
(4, 112, 5, 96, 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'wa man yaksib ḫaṭīʾatan aw iṯman ṯumma yarmi bihī barīʾan faqaidi ḥtamala buhtānan wa iṯman mubīnan', 'Kim bir hata veya günah kazanır da sonra onu bir suçsuzun üzerine atarsa, gerçekten büyük bir iftira ve apaçık bir günah yüklenmiş olur.'),
(4, 113, 5, 96, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَضُرُّونَكَ مِن شَىْءٍ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا', 'wa lawlā faḍlu llāhi ʿalayka wa raḥmatuhū lahammat ṭāʾifatun minhum an yuḍillūk(a) wa mā yuḍillūna illā anfusahum wa mā yaḍurrunāka min shaiʾ(in) wa anzala llāhu ʿalayka l-kitāba wa l-ḥikmah(ta) wa ʿallamaka mā lam takun taʿlam(u) wa kāna faḍlu llāhi ʿalayka ʿaẓīmā(n)', 'Eğer sana Allah''ın lütfu ve rahmeti olmasaydı, onlardan bir grup seni saptırmaya kesin karar vermişti. Oysa onlar ancak kendilerini saptırırlar ve sana hiçbir zarar veremezler. Allah sana Kitabı ve Hikmeti indirdi ve sana bilmediğin şeyleri öğretti. Ve Allah''ın sana olan lütfu çok büyüktür.'),
(4, 114, 5, 97, 'لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَٰحٍۭ بَيْنَ ٱلنَّاسِ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', 'lā khayra fī kathīrin min najwāhum illā man amara biṣadaqatin aw maʿrūfin aw iṣlāḥin bayna n-nāsi wa man yafʿal dhālika ibtigāʾa marḍāti llāhi fa-sawfa nuʾtīhi ajran ʿaẓīman', 'Onların gizli konuşmalarının çoğunda hayır yoktur; ancak sadaka vermeyi, iyilik yapmayı veya insanlar arasında barış sağlamayı emredenler müstesnadır. Kim bunları Allah''ın rızasını kazanmak için yaparsa, ona büyük bir ecir vereceğiz.'),
(4, 115, 5, 97, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', 've men yuşâkıkı-rrasûle mim ba''di mâ tebeyyene lehu-lhudâ ve yettebi'' ğayra sebîli-lmu''minîn nuvellihi mâ tevellyâ ve nuṣlihi cehennem ve sâ''et maṣîrâ', 'Kim kendisine hidayet (doğru yol) belli olduktan sonra Peygamber''e karşı çıkar, müminlerin yolundan başkasına uyarsa, onu yöneldiği şeyde bırakırız ve onu cehenneme sokarız. Orası ne kötü bir varış yeridir!'),
(4, 116, 5, 97, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 'ʾinna-llāha lā yagfiru ʾan yušraka bihi wa-yagfiru mā dūna dhālika li-man yašāʾu wa-man yušriki bi-llāhi fa-qad ḍalla ḍalālan baʿīdan', 'Şüphesiz Allah, Kendisine ortak koşulmasını affetmez. Bunun altındaki (günahları) ise dilediği kimse için affeder. Kim Allah''a ortak koşarsa, şüphesiz uzak bir sapıklığa sapmış olur.'),
(4, 117, 5, 97, 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَٰنًا مَّرِيدًا', 'in yadʿūna min dūnihi ʾillā ʾināṯan wa-in yadʿūna ʾillā šayṭānan marīdā', 'Onlar, O''ndan başka sadece dişilere taparlar ve onlar azgın bir şeytandan başkasına tapmazlar.'),
(4, 118, 5, 97, 'لَّعَنَهُ ٱللَّهُ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا', 'laʿanahu ʾallāhu waqāla laʾʾattakhidhanan min ʿibādika naṣīban mafrūḍan', 'Allah onu lanetlemiştir. Ve (o şeytan) dedi ki: ''Onların (insanların) içinden belirli bir pay alacağım.'''),
(4, 119, 5, 97, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَءَامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَٰمِ وَلَءَامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ وَمَن يَتَّخِذِ ٱلشَّيْطَٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا', 'wa laʾuḍillannahum wa laʾumanniyannahum wa laʾāmurannahum falayubattikunna ʾādhāna l-ʾanʿāmi wa laʾāmurannahum falayughayyirunna khalqa llāhi wa man yattakhidhi sh-shayṭāna waliyyan min dūni llāhi faqad khasira khusrānan mubīnan', 'Ve onları mutlaka saptıracağım, onlara mutlaka boş kuruntular vereceğim ve onlara mutlaka emredeceğim de hayvanların kulaklarını yaracaklar ve onlara mutlaka emredeceğim de Allah''ın yarattığı (dini) değiştirecekler. Kim Allah''ı bırakıp da şeytanı dost edinirse, şüphesiz o, apaçık bir ziyana uğramıştır.'),
(4, 120, 5, 97, 'يَعِدُهُمْ وَيُمَنِّيهِمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'yaʿiduhum wa yumannīhim wa mā yaʿiduhumu sh-shayṭānu illā ghurūran', 'Onlara va''deder ve onları umutlandırır. Şeytan onlara sadece aldatma va''deder.'),
(4, 121, 5, 97, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا', 'ʾulāʾika maʾwāhumu jahannamu walā yajidūna ʿanhā maḥīṣan', 'İşte onların varacakları yer cehennemdir ve oradan bir kurtuluş yolu bulamayacaklardır.'),
(4, 122, 5, 98, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا وَعْدَ ٱللَّهِ حَقًّا وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti sanudkhiluhum jannātin tajrī min taḥtihā l-ʾanhāru khālidīna fīhā ʾabadan waʿda llāhi ḥaqqan wa-man ʾaṣdaqu mina llāhi qīlan', 'İman edip salih amel işleyenleri ise, içinde ebediyen kalacakları, altlarından ırmaklar akan cennetlere sokacağız. Allah, bu, O''nun hak vaadidir. Allah''tan daha doğru sözlü kim olabilir?'),
(4, 123, 5, 98, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَٰبِ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'laysa bi-ʾamāniyyikum walā ʾamānī ʾahli l-kitābi man yaʿmal sūʾan yujza bihi walā yajid lahu min dūni llāhi waliyyan walā naṣīrā', 'Ne sizin kuruntularınızla ne de Ehl-i kitabın kuruntularıyla (bu işler olmaz). Kim kötülük yaparsa onunla cezalandırılır. Ve kendisi için Allah''tan başka bir dost ve yardımcı bulamaz.'),
(4, 124, 5, 98, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا', 've men yaʿmal min aṣ-ṣāliḥāti min dhakarin ʾaw ʾunthā wa-huwa muʾminun fa-ʾulāʾika yadkhulūna l-jannata wa-lā yuẓlamūna naqīran', 'Erkek veya kadın, her kim de mümin olarak salih ameller işlerse, işte onlar cennete girecekler ve zerre kadar haksızlığa uğramayacaklardır.'),
(4, 125, 5, 98, 'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا', 'vemen ʾaḥsanu dīnan mimmen ʾaslama wajhahū lillāhi wahuwa muḥsinun wāttabaʿa milleta ʾibrāhīma ḥanīfan wāttakhaḏa ʾallāhu ʾibrāhīma ḵalīlan', 'Kim, iyilik yaparak kendini Allah''a veren ve İbrahim''in, hanîf olan dinine tâbi'' olan kimse kadar güzel dinli olabilir? Allah, İbrahim''i dost edinmiştir.'),
(4, 126, 5, 98, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا', 'wa lil-lāhi mā fī s-samāwāti wa mā fī l-arḍi wa kāna l-lāhu bikulli shayʾin muḥīṭan', 'Göklerde ne var, yerde ne varsa hepsi Allah''ındır. Allah her şeyi kuşatıcıdır.'),
(4, 127, 5, 98, 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَٰبِ فِى يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَٰمَىٰ بِٱلْقِسْطِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا', 'wa yastaftūnaka fī n-nisāʾi quli llāhu yuftīkum fīhinna wa mā yutlā ʿalaykum fī l-kitābi fī yatāmā n-nisāʾi l-latī lā tuʾtūhunna mā kutiba lahunna wa targhabūna an tankiḥūhunna wa l-mustaḍʿafīna mina l-wildāni wa an taqūmū lil-yatāmā bi l-qisṭi wa mā tafʿalū min khayrin fa-inna llāha kāna bihi ʿalīman', 'Sana kadınlar hakkında fetva soruyorlar. De ki: "Allah, onlarla ilgili size fetva veriyor ve size okunan (ayetlerde) yetim kadınlara verilmeyen ve nikahlanmak istediğiniz (kadınlar) ile, himayenizdeki zayıf çocuklar ile ilgili (hükümler) ve yetimlere adaletle davranmanız (konusundaki hükümler) de (bildiriliyor). Ne hayır işlerseniz şüphesiz Allah onu bilir."'),
(4, 128, 5, 99, 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَٱلصُّلْحُ خَيْرٌ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'wa-ini-mraʾatun ḵāfat min-baʿlihā nušūzan aw-iʿrāḍan fa-lā junāḥa ʿalayhimā an-yuṣliḥā baynahumā ṣulḥan wa-ṣ-ṣulḥu ḵayrun wa-uḥḍirati l-ʾanfusu š-šuḥḥa wa-in tuḥsinū wa-tattaqū fa-ʾinna llāha kāna bimā taʿmalūna ḵabīran', 'Eğer bir kadın, kocasının huysuzluğundan (yüz çevirmesinden) veya ilgisizliğinden endişe ederse, kendi aralarında anlaşmalarıyla bir sorun olmaz. Anlaşma daha hayırlıdır. Nefisler kıskançlığa hazır kılınmıştır. Eğer iyi davranır ve Allah’tan sakınırsanız, şüphesiz Allah yaptıklarınızdan haberdardır.'),
(4, 129, 5, 99, 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'wa-lan tastaṭīʿū an taʿdilū bayna n-nisāʾi wa-law ḥaraṣtum fa-lā tamīlū kulla l-mayli fa-taḏarūhā ka-l-muʿallaqati wa-in tuṣliḥū wa-tattaqū fa-inna ʾllāha kāna ġafūran raḥīmā', 'Kadınlar arasında (adaleti) asla tam olarak sağlayamazsınız. Bir tarafa büsbütün eğilerek diğerini askıdaymış gibi bırakmayın. Eğer arayı düzeltir ve Allah’tan korkarsanız, şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir.'),
(4, 130, 5, 99, 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا', 'wa-ʾin yatafarraqā yuġni ʾllāhu kullah min saʿatihī wa-kāna ʾllāhu wāsiʿan ḥakīmā', 'Eğer (karı-koca) ayrılırlarsa, Allah her birini kendi lütfundan zenginleştirir. Allah her şeyi kuşatan hikmet sahibidir.'),
(4, 131, 5, 99, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا', 'wa-lillāhi mā fī s-samāwāti wa-mā fī l-arḍi wa-laqad waṣṣaynā lladhīna ūtū l-kitāba min qablikum wa-iyyākum ani ttaqū llāha wa-in takfurū fa-inna lillāhi mā fī s-samāwāti wa-mā fī l-arḍi wa-kāna llāhu ghaniyyan ḥamīdā', 'Göklerde ne var, yerde ne varsa hepsi Allah''ındır. Andolsun ki, sizden önce kendilerine kitap verilen kimselere ve size, Allah''tan korkun diye emrettik. Eğer inkâr ederseniz, bilin ki göklerde ne var, yerde ne varsa hepsi Allah''ındır. Allah zengin ve övgüye lâyıktır.'),
(4, 132, 5, 99, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'wa lillāhi mā fī s-samāwāti wa mā fī l-arḍi wa kafā bi-llāhi wakīlan', 'Göklerde ve yerde ne varsa hepsi Allah''ındır. Vekil olarak Allah yeter.'),
(4, 133, 5, 99, 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا', 'in yeşeʾ yuzhibkum ayyuhā n-nāsu wa yaʾti bi-ʾākhirīn wa kāna l-lāhu ʿalā dhālika qadīrā', 'Eğer dilerse, ey insanlar, sizi giderip yerinize başkalarını getirebilir. Allah buna hakkıyla kadirdir.'),
(4, 134, 5, 99, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا', 'man kāna yurīdu thawāba d-dunyā fa-ʿinda Llāhi thawābu d-dunyā wa-l-ʾākhirah wa-kāna Llāhu samīʿan baṣīran', 'Kim dünya sevabını isterse, bilsin ki dünya ve ahiret sevabı Allah katındadır. Allah, işiten ve görendir.'),
(4, 135, 5, 100, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'yā ayyuhā alladhīna āmanū kūnū qawwāmīna bilqisṭi shuhadāʾa lillāhi walaw ʿalā anfusikum awi l-wālidayni wal-aqrabīna in yakun ghaniyyan aw faqīran fallāhu awlā bihimā falā tattabiʿū al-hawā an taʿdilū wa in talwū aw tuʿriḍū faʾinna allāha kāna bimā taʿmalūna khabīran', 'Ey iman edenler! Adaleti ayakta tutan, kendiniz, ana-babanız ve yakınlarınız aleyhine de olsa, Allah için şahitlik eden kimseler olun. Zengin de olsa, fakir de olsa, Allah onlardan daha yakındır. Nefsinize uyup da adaletten sapmayın. Eğer (hakikati) çarpıtırsanız veya (ondan) yüz çevirirseniz, şüphesiz Allah yaptıklarınızdan haberdar olandır.'),
(4, 136, 5, 100, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْءَاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 'yā ayyuhā alladhīna āmanū āminū bi-llāhi wa-rasūlihi wa-l-kitābi alladhī nazzala ʿalā rasūlihi wa-l-kitābi alladhī anzala min qablu wa-man yakfur bi-llāhi wa-malāʾikatihi wa-kutubihi wa-rusulihi wa-l-yawmi l-ʾākhiri fa-qad ḍalla ḍalālan baʿīdan', 'Ey iman edenler! Allah''a, Resûlüne, Resûlüne indirdiği kitaba ve daha önce indirdiği kitaba iman edin. Kim Allah''ı, meleklerini, kitaplarını, resullerini ve ahiret gününü inkâr ederse, şüphesiz derin bir sapıklığa düşmüştür.'),
(4, 137, 5, 100, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', 'ʾinna l-ladhīna ʾāmanū thumma kafarū thumma ʾāmanū thumma kafarū thumma ʾazdādū kufran lam yakuni l-lāhu li-yaghfira lahum wa-lā li-yahdiyahum sabīlan', 'İman edip sonra kâfir olanlar, sonra iman edip sonra kâfir olanlar, sonra da küfürde artanlar... Allah onları bağışlayacak değildir; onları (doğru) yola iletecek de değildir.'),
(4, 138, 5, 100, 'بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', 'bashshiri l-munāfiqīna bi-ʾanna lahum ʿadhāban ʾalīmā', 'Münafıklara, kendileri için elem dolu bir azap olduğunu müjdele!'),
(4, 139, 5, 100, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا', 'alladhīna yattakhidhūna l-kāfirīna awliyāʾa min dūni l-muʾminīn ʾayabtaghūna ʿindahumu l-ʿizzata faʾinna l-ʿizzata lillāhi jamīʿan', 'Onlar, mü''minleri bırakıp kâfirleri dost edinenlerdir. Onların yanında izzet (güç ve şeref) mi arıyorlar? Bilsinler ki izzetin tamamı Allah''ındır.'),
(4, 140, 5, 100, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ إِنَّكُمْ إِذًا مِّثْلُهُمْ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَٰفِقِينَ وَٱلْكَٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', 've kad nezzele ʿaleykum fî-lkitâbi en iżâ semiʿtum âyâti-llâhi yukferu bihâ ve yustehzeu bihâ felâ takʿudû meʿahum hattâ yeḫûdû fî ḥadîŝin ġayrihî innekum iżen miŝluhum inne-llâhe câmiʿu-lmunâfiḳîne velkâfirîne fî cehenneme cemîʿâ', 'Oysa O (Allah), Kitap''ta size şunu indirmiştir: Allah''ın ayetlerinin inkâr edildiğini ve onlarla alay edildiğini işittiğiniz zaman, onlar başka bir söze geçinceye kadar onlarla oturmayın. Aksi takdirde siz de onlar gibi olursunuz. Şüphesiz Allah, münafıkların ve kâfirlerin hepsini cehennemde bir araya getirecektir.'),
(4, 141, 5, 101, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', 'alladhīna yatarabbaṣūna bikum fa-in kāna lakum fatḥun minallāhi qālū ʾalam nakun maʿakum wa-in kāna lil-kāfirīna naṣībun qālū ʾalam nastaḥwiḏ ʿalaykum wa-namnaʿkum min al-muʾminīn fallāhu yaḥkumu baynakum yawma l-qiyāmah wa-lan yajʿala ʾallāhu lil-kāfirīna ʿalā l-muʾminīna sabīlā', 'Onlar, sizin başınıza ne geleceğini gözetlerler. Eğer Allah''tan size bir zafer gelirse, "Sizinle beraber değil miydik?" derler. Eğer kâfirlere bir pay düşerse, (onlara dönüp) "Biz size üstün gelip sizi müminlerden koruyamadık mı?" derler. Allah, kıyamet gününde sizin aranızda hükmedecektir. Allah, müminlerin aleyhine kâfirlere asla bir yol vermeyecektir.'),
(4, 142, 5, 101, 'إِنَّ ٱلْمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا', 'ʾinna l-munāfiqīna yukhādiʿūna ʾllāha wa-huwa khādiʿuhum wa-ʾidhā qāmū ʾilā ṣ-ṣalāti qāmū kusālā yurāʾūna n-nāsa wa-lā yadhkurūna ʾllāha ʾillā qalīlā', 'Şüphesiz münafıklar Allah''ı aldatmaya çalışırlar. Halbuki Allah onların bu tuzaklarını başlarına çevirecektir. Onlar, namaza kalktıkları zaman isteksizce kalkarlar, insanlara gösteriş yaparlar ve Allah''ı ancak çok az zikrederler.'),
(4, 143, 5, 101, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', 'muḏaḏḻibīna bayna ḏālika lā ilā hāʾulāʾi wa lā ilā hāʾulāʾi wa man yuḍlili ḷḷāhu falan taǧida lahu sabīlā', 'Onlar bununla (imanla küfür) arasında bocalayanlardır; ne onlara (müminlere) bağlıdırlar ne de ötekilere (kâfirlere). Allah''ın (dilediğini) saptırdığına ise asla bir yol bulamazsın.'),
(4, 144, 5, 101, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًا مُّبِينًا', 'yā ayyuhā alladhīna āmanū lā tattakhidhū al-kāfirīna awliyāʾa min dūni al-muʾminīna aturīdūna an tajʿalū lillāhi ʿalaykum sulṭānan mubīnan', 'Ey iman edenler! Mü''minleri bırakıp kâfirleri dost edinmeyin. Kendi aleyhinize Allah''a apaçık bir delil mi vermek istiyorsunuz?'),
(4, 145, 5, 101, 'إِنَّ ٱلْمُنَٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', 'ʾinna l-munāfiqīna fī d-darki l-ʾasfali mina n-nāri wa-lan tajida lahum naṣīrā', 'Şüphesiz münafıklar (cehennemin) en alt tabakasındadır. Onlar için bir yardımcı da bulamazsın.'),
(4, 146, 5, 101, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا', 'illa-lladhīna tābū wa-aṣlaḥū wa-ʿtaṣamū bi-llāhi wa-akhlaṣū dīnahum li-llāhi fa-ʾulāʾika maʿa-l-muʾminīna wa-sawfa yuʾti-llāhu-l-muʾminīna ʾajran ʿaẓīmā', 'Ancak tevbe edenler, durumlarını düzeltenler, Allah''a sımsıkı sarılanlar ve dinlerini Allah için samimi olarak (yapmaya) gayret edenler (bu hükmün dışındadır). İşte bunlar müminlerle beraberdir. Allah müminlere büyük bir mükâfat verecektir.'),
(4, 147, 5, 101, 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا', 'mā yafʿalu ʾllāhu biʿaḏābikum in šakartum wa-ʾāmantum wa-kāna ʾllāhu šākiran ʿalīman', 'Eğer şükreder ve iman ederseniz, Allah size azap etmekten ne diyecek? Allah şükredenleri mükâfatlandıran, her şeyi bilen, (yapılan iyilikleri) bilendir.'),
(4, 148, 6, 102, 'لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', 'lā yuḥibbu ʾllāhu l-jahra bi-ssūʾi mina l-qawli ʾillā man ẓulima wa-kāna ʾllāhu samīʿan ʿalīman', 'Allah, zulme uğrayanlar hariç, kimsenin (kötülük ve) çirkin sözle<bos> açıkça söylenmesini sevmez. Allah hakkıyla işitendir, hakkıyla bilendir.'),
(4, 149, 6, 102, 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا', 'in tubdū khayran aw tukhfūhu aw taʿfū ʿan sūʾin faʾinna ʾallāha kāna ʿafuwwan qadīran', 'Eğer hayrı açıklar veya gizlerseniz ya da kötülükten dolayı affederseniz, bilin ki Allah da çok affedici, güç yetirendir.'),
(4, 150, 6, 102, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', 'ʾinna lladhīna yakfurūna bi-llāhi wa rusulihī wa yurīdūna ʾan yufarriqū bayna l-lāhi wa rusulihī wa yaqūlūna nuʾminu bi-baʿḍin wa nakfuru bi-baʿḍin wa yurīdūna ʾan yattakhidhū bayna dhālika sabīlā', 'Şüphesiz ki Allah''ı ve peygamberlerini inkâr edenler ve Allah ile peygamberlerinin arasını ayırmak isteyip, "Biz bazısına inanır, bazısını inkâr ederiz" diyenler ve bunlar (imanla küfür) arasında bir yol tutmak isteyenler var ya,'),
(4, 151, 6, 102, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ حَقًّا وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'ʾūlāʾika humu l-kāfirūna ḥaqqan wa-ʾaʿtadnā lil-kāfirīna ʿaḏāban muhīnan', 'İşte kâfirlerin ta kendileri bunlardır. Biz de kâfirler için rezil edici bir azap hazırlamışızdır.'),
(4, 152, 6, 102, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'wa-lladhīna ʾāmanū bi-llāhi wa-rusulihi wa-lam yufarriqū bayna ʾaḥadin minhum ʾulāʾika sawfa yuʾtīhim ʾujūrahum wa-kāna llāhu ghafūran raḥīman', 'Allah''a ve peygamberlerine iman edenler ve onlardan hiçbirini ayırmayanlar (hepsine inananlar) var ya, işte onlara Allah ecirlerini verecektir. Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(4, 153, 6, 102, 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰبًا مِّنَ ٱلسَّمَآءِ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ بِظُلْمِهِمْ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ وَءَاتَيْنَا مُوسَىٰ سُلْطَٰنًا مُّبِينًا', 'yas''aluka ahlul-kitābi an tunazzila ''alayhim kitāban minas-samā''i faqad sa''alū mūsā akbara min dhālika faqālū arinā Allāha jahratan fa''akhadhat-humuṣ-ṣā''iqatu biẓulmihim thumma-ttakhadhūl-''ijla mim ba''di mā jā''at-humul-bayyinātu fawa''afaynā ''an dhālika wa''ātainā mūsā sulṭānan mubīnā', 'Kitap ehli senden, kendilerine gökten bir kitap indirmeni istiyorlar. Nitekim Mûsâ''dan da bundan daha büyüğünü istemişler, "Bize Allah''ı açıkça göster" demişlerdi. Bunun üzerine zulümleri yüzünden onları yıldırım çarpmıştı. Ardından kendilerine apaçık deliller gelmişken, buzağıyı (tanrı edinmişlerdi). Biz bunu da affettik. Mûsâ''ya da apaçık bir delil (hükümranlık) verdik.'),
(4, 154, 6, 102, 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', 'wa rafaʿnā fawqahumu ṭ-ṭūra bimīthāqihim wa qulnā lahumu dkhulū l-bāba sujjadan wa qulnā lahum lā taʿdaw fī s-sabti wa ʾakhadhnā minhum mīthāqan ghalīẓan', 'Onların üzerlerine Tûr dağını da, verdikleri ahid dolayısıyla kaldırmıştık. Ve onlara: "Kapıdan secde ederek girin!" demiştik. Ve yine onlara: "Cumartesi günü haddi aşmayın!" demiştik. Ve onlardan ağır bir ahid de almıştık.'),
(4, 155, 6, 103, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', 'fabimā naqḍihim mīthāqahum wa kufrihim bi ʾāyāti llāhi wa qatluhumu l-ʾanbiyāʾa bi ghayri ḥaqqin wa qawlihim qulūbunā ghulfun bal ṭabaʿa llāhu ʿalayhā bi kufrihim falā yuʾminūna ʾillā qalīlan', 'Bunun üzerine, ahitlerini bozmaları, Allah''ın ayetlerini inkâr etmeleri, peygamberleri haksız yere öldürmeleri ve "kalplerimiz perdelidir" demeleri yüzünden (onlar lanetlendi). Hayır! Allah, inkârları yüzünden onların kalplerini mühürlemiştir. Bu yüzden pek azı iman eder.'),
(4, 156, 6, 103, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰنًا عَظِيمًا', 'wa bikufrihim wa qawlihim ʿalā Maryama buhtānan ʿaẓīmā', 'Ve küfre sapmaları ve Meryem''e büyük bir bühtanda bulunmaları yüzünden.'),
(4, 157, 6, 103, 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ وَمَا قَتَلُوهُ يَقِينًۢا', 'wa qawlihim innā qatalnā l-masīḥa ʿīsā bna maryama rasūla llāh wa mā qatalūhu wa mā ṣalabūhu wa lākin shubbiha lahum wa inna lladhīna ikhtalafū fīhi lafī shakkim minh mā lahum bihi min ʿilmin illā ttibāʿa ẓ-ẓann wa mā qatalūhu yaqīnan', 'Ve "Doğrusu biz, Allah''ın elçisi Meryem oğlu Mesih İsa''yı öldürdük" demeleri yüzünden (onları lanetledik). Oysa onu öldürmediler ve onu asmadılar. Fakat onlara (onun gibi) benzetildi. Ve onun hakkında anlaşmazlığa düşenler, ondan yana tam bir kuşku içindedirler. Bu hususta zanna uymaktan başka hiçbir bilgileri yoktur. Onu kesin olarak öldürmediler.'),
(4, 158, 6, 103, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'bal rafaʿahu ʾallāhu ʾilayhi wa-kāna ʾallāhu ʿazīzan ḥakīman', 'Hayır, Allah onu kendisine yükseltmiştir. Allah aziz, hakîm olandır.'),
(4, 159, 6, 103, 'وَإِن مِّنْ أَهْلِ ٱلْكِتَٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ وَيَوْمَ ٱلْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا', 'wa-ʾin min ʾahli l-kitābi ʾillā layuʾminanna bihi qabla mawtihi wa-yawma l-qiyāmati yakūnu ʿalayhim šahīdan', 'Kitap ehlinden, kendisi ölmeden önce ona (İsa''ya) inanmayacak hiç kimse yoktur. Kıyamet gününde de o, onların aleyhine şahit olacaktır.'),
(4, 160, 6, 103, 'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا', 'fa-bi-ẓulmin mina-lladhīna hādū ḥarramnā ʿalayhim ṭayyibātin uḥillat lahum wa-bi-ṣaddihim ʿan sabīli-llāhi kathīran', 'Yahudi olanların zulmü yüzünden ve Allah''ın yolundan çokça alıkoymaları sebebiyle kendilerine helâl kılınan temiz şeyleri onlara haram kıldık.'),
(4, 161, 6, 103, 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَأَعْتَدْنَا لِلْكَٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا', 'wa-ʾakhdhihimu r-ribā wa-qad nuhū ʿanhu wa-ʾaklihim ʾamwāla n-nāsi bil-bāṭil wa-ʾaʿtadnā lil-kāfirīna minhum ʿadhāban ʾalīman', 'Ve onların, kendileri yasaklandığı halde ribâyı (faizi) almaları ve insanların mallarını haksızlıkla yemeleri yüzünden. Ve onlardan kâfir olanlara (veya kâfir oldukları için) elîm (acı veren) bir azap hazırladık.'),
(4, 162, 6, 103, 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ أُو۟لَٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', 'lākin ar-rāsiḫūna fī l-ʿilmi minhum wa-l-muʾminūna yuʾminūna bimā unzila ilayka wa-mā unzila min qablika wa-l-muqimīna ṣ-ṣalāta wa-l-muʾtūna z-zakāta wa-l-muʾminūna bi-llāhi wa-l-yawmi l-ʾāḫiri ʾulāʾika sa-nuʾtīhim ʾajran ʿaẓīman', 'Ancak ilimde derinleşmiş olanlar, onlardan iman edenler, sana indirilene ve senden önce indirilene iman ederler. Namazı kılanlar, zekâtı verenler, Allah''a ve ahiret gününe inananlar; işte bunlara büyük bir ecir vereceğiz.'),
(4, 163, 6, 104, 'إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّۦنَ مِنۢ بَعْدِهِۦ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', 'ʾinnā ʾawḥaynā ʾilayka kamā ʾawḥaynā ʾilā nūḥin wa-n-nabiyyīna min baʿdihī wa-ʾawḥaynā ʾilā ʾibrāhīma wa-ʾismāʿīla wa-ʾisḥāqa wa-yaʿqūba wa-l-ʾasbāṭi wa-ʿīsā wa-ʾayyūba wa-yūnusa wa-hārūna wa-sulaymāna wa-ʾā tīnā dāwūda zabūrā', 'Şüphesiz ki Biz, Nuh''a ve ondan sonraki peygamberlere vahyettiğimiz gibi sana da vahyettik. Ve (yine) İbrahim''e, İsmail''e, İshak''a, Yakub''a ve torunlarına, İsa''ya, Eyyub''a, Yunus''a, Harun''a ve Süleyman''a vahyettik. Ve Davud''a da Zebur''u verdik.'),
(4, 164, 6, 104, 'وَرُسُلًا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا', 'wa rusulan qad qaṣaṣnāhum ʿalayka min qablu wa rusulan lam naqṣuṣhum ʿalayka wa kallama -llāhu Mūsā taklīmā', 'Hem daha önce kendilerine hikâye ettiğimiz (anlattığımız) peygamberleri de (göndermiştik) ve kendilerine hikâye etmediğimiz (anlatmadığımız) peygamberleri de (göndermiştik). Ve Allah, Mûsâ ile doğrudan konuştu.'),
(4, 165, 6, 104, 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'rusulan mubashshireena wa munthireena li''alla yakuna lilnnasi ''ala Allahi hujjatum ba''da arrusuli wa kana Allahu ''azeezan hakeema', 'Onları, elçilerinden sonra insanların Allah''a karşı bir bahaneleri olmasın diye müjdeleyici ve uyarıcı olarak gönderdik. Allah, mutlak güç sahibi, hüküm ve hikmet sahibidir.'),
(4, 166, 6, 104, 'لَّٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ أَنزَلَهُۥ بِعِلْمِهِۦ وَٱلْمَلَٰٓئِكَةُ يَشْهَدُونَ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'lākinna Allāha yashhadu bimā anzala ilayka anzalahū biʿilmihī wa-l-malāʾikatu yashhadūn wa kafā bi-llāhi shahīdan', 'Ancak Allah sana indirdiğiyle şahitlik eder. Melekler de şahitlik eder. Şahit olarak Allah yeter.'),
(4, 167, 6, 104, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَٰلًۢا بَعِيدًا', 'ʾinna lladhīna kafarū wa ṣaddū ʿan sabīli llāhi qad ḍallū ḍalālan baʿīdan', 'Şüphesiz inkâr edenler ve Allah''ın yolundan alıkoyanlar, gerçekten (haktan) uzak bir sapıklığa sapmışlardır.'),
(4, 168, 6, 104, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', 'ʾinna lladhīna kafarū waẓalamū lam yakuni l-llāhu liyaġfira lahum walā liyehdiya hum ṭarīqan', 'Şüphesiz inkâr edenleri ve zulmedenleri Allah bağışlayacak değildir ve onlara (doğru) bir yol göstermiş de değildir.'),
(4, 169, 6, 104, 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'illa tarīqa jahannama ḫālidīne fīhā abedan ve kāne dhālika ʿalā llāhi yasīran', 'Ancak cehennem yolunu, orada ebediyen kalıcılar olarak (giderler). Bu ise Allah için pek kolaydır.'),
(4, 170, 6, 104, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'yā ʾayyuhā n-nāsu qad jāʾakumur-rasūlu bil-ḥaqqi min rabbikum fa-ʾāminū ḵayran lakum wa-ʾin takfurū fa-ʾinna lillāhi mā fī s-samāwāti wal-ʾarḍi wa-kāna llāhu ʿalīman ḥakīman', 'Ey insanlar! Rabbinizden size hak (Kur''an) geldi. Artık ona iman edin. Bu sizin için daha hayırlıdır. Eğer inkâr ederseniz, bilin ki göklerde ve yerde ne varsa hepsi Allah''ındır. Allah, her şeyi bilen, hikmet sahibi olandır.'),
(4, 171, 6, 105, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ٱنتَهُوا۟ خَيْرًا لَّكُمْ إِنَّمَا ٱللَّهُ إِلَٰهٌ وَٰحِدٌ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'Yā ʾahla l-kitābi lā taglū fī dīnikum walā taqūlū ʿalā l-lahi ʾillā l-ḥaqqa ʾinnamā l-masīḥu ʿīsā bnu maryama rasūlu l-lahi wakalimatuhu ʾalqāhā ʾilā maryama warūḥun minhu faʾāminū bi l-lahi warusulihi walā taqūlū ṯalāṯatun intahuw khayran lakum ʾinnamā l-lahu ʾilāhun wāḥidun subḥānahu ʾan yakūna lahu waladun lahu mā fī s-samāwāti wamā fī l-ʾarḍi wakafā bi l-lahi wakīlan', 'Ey Kitap Ehli! Dininizde aşırı gitmeyin ve Allah hakkında haktan başkasını söylemeyin. Meryem oğlu Mesih İsa, ancak Allah''ın Resûlü ve Meryem''e ulaştırdığı kelimesi ve O''ndan bir ruhtur. Öyleyse Allah''a ve resûllerine iman edin. “Üçtür” demeyin; vazgeçin, bu sizin için daha hayırlıdır. Şüphesiz Allah, ancak tek bir ilahtır. O''nun bir çocuğu olmaktan münezzehtir. Göklerde ve yerde ne varsa O''nundur. Vekil olarak Allah yeter.'),
(4, 172, 6, 105, 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَٰٓئِكَةُ ٱلْمُقَرَّبُونَ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا', 'lan yastanḳifa l-masīḥu ʾen yekūne ʿabdan li-llāh wa-lā l-malāʾiketu l-muḳarrebūn wa-men yastanḳif ʿan ʿibādatihi wa-yestekbir fa-sa-yaḥshuruhum ʾileyhi ǧamīʿan', 'Mesih, Allah''ın kulu olmaktan asla çekinmez. Mukarreb (Allah''a yakın) melekler de çekinmez. O''na kulluktan çekinip büyüklük taslayanlara gelince, (Allah) hepsini kendi nezdine toplayacaktır.'),
(4, 173, 6, 105, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'feʾemmā alladhīna āmanū waʿamilū al-ṣṣāliḥāti fayūwaffīhim ujūrahum wayazīduhum min faḍlihī waʾammā alladhīna istankafū waistakbarū fayuʿadhdhibuhum ʿadhāban alīman walā yajidūna lahum min dūni Allāhi waliyyan walā naṣīran', 'İman edip salih ameller işleyenlere gelince, Allah onların mükâfatlarını eksiksiz verecek ve lütfundan onlara daha da artıracaktır. Ama kibirlenip büyüklük taslayanlara gelince, onlara elem verici bir azapla azap edecek ve kendileri için Allah''tan başka ne bir dost ne de bir yardımcı bulamayacaklardır.'),
(4, 174, 6, 105, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا', 'yā ayyuhā an-nāsu qad jāʾakum burhānu min rabbikum wa anzalnā ilaykum nūran mubīnan', 'Ey insanlar! Rabbinizden size bir delil geldi. Ve size apaçık bir nur indirdik.'),
(4, 175, 6, 105, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا', 'fa-ammā alladhīna ʾāmanū bi-llāhi wa-ʿtaṣamū bihi fa-sayudkhiluhum fī raḥmatin minhu wa-faḍlin wa-yahdīhim ʾilayhi ṣirāṭan mustaqīman', 'Allah''a iman edip O''na sımsıkı sarılanlara gelince, işte onlara Allah kendi tarafından bir rahmet ve bir lütuf ihsan edecek ve onları kendisine giden dosdoğru bir yola iletecektir.'),
(4, 176, 6, 106, 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'yestiftūneke ḳuli ʾllāhu yuftīkum fī ʾl-kelāleti ʾini ʾmruʾun ʾheleke leyse lehū veladun velehū ʾuḫtun felehā niṣfu mā tereke vehuve yerisuhā ʾin lem yekun lehā veladun feʾin kānetā ʾiṯneteyni felehumā ʾeṯ-ṯulutāni mimmā tereke veʾin kānū ʾiḫveten ricālan ve nisāʾan feleẕ-ẕekeri miṯlu ḥaẓẓi ʾel-ʾunṯeyeyn yubeyyinu ʾllāhu lekum ʾen taḍillū veʾllāhu bikulli šeyʾin ʿalīmun', 'Sana fetva sorarlar. De ki: Allah, "kelâle" hakkında size fetva veriyor: Çocuğu olmayan ve biraderi bulunan kimse ölürse, geride bıraktığı maldan biraderi için bırakılan malın yarısı vardır. Eğer (kadın) çocuğu olmazsa, (erkek) biraderi ona vâris olur. Eğer (ölünün) iki kız kardeşi varsa, bıraktığı malın üçte ikisi onlarındır. Eğer hem erkek hem de kadın kardeşler bulunursa, erkek için iki dişi kadar hisse vardır. Şaşırmamanız için Allah size (hükümleri) açıklıyor. Allah her şeyi bilir.'),
(5, 1, 6, 106, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', 'yā ʾayyuhā lladhīna ʾāmanū ʾawfū bil-ʿuqūd uḥillat lakum bahīmatu l-ʾanʿām ʾillā mā yutlā ʿalaykum ghayra muḥillī ṣ-ṣaydi wa-ʾantum ḥurum ʾinna llāha yaḥkumu mā yurīd', 'Ey iman edenler! Akitleri yerine getirin. Size (haram oldukları) size okunacak olanlar dışında, en''am (hayvanlar) helal kılındı. İhramda iken avlanmayı helal saymayın. Şüphesiz Allah dilediği hükmü verir.'),
(5, 2, 6, 106, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'yā ayyuhā alladhīna āmanū lā tuḥillū shaʿāʾira allāhi walā ash-shahra al-ḥarāma walā al-hadyā walā al-qalāʾida walā ʾāmmīna al-bayta al-ḥarāma yabtaghūna faḍlan min rabbihim wa riḍwānan wa idhā ḥalaltum fa-ṣṭādū walā yajrimannakum shanaʾanu qawmin an ṣaddukum ʿani al-masjidi al-ḥarāmi an taʿtadū wa taʿāwanū ʿalā al-birri wa-t-taqwā walā taʿāwanū ʿalā al-ithmi wal-ʿudwāni w-ttaqū allāha inna allāha shadīdu al-ʿiqābi', 'Ey iman edenler! Allah''ın (dini) nişanelerine, haram olan aya, kurban edilmek için (Mekke''ye) gönderilen hediyelere ve (onları süslemek için) boyunlarına takdıkları çelenge saygısızlık etmeyin. Rab''lerinden bol nimet ve rıza isteyerek Beyt-i Harem''e (Kâbe''ye) yönelmiş kimselere de (dokunmayın). Ancak, hacdan çıkıp ihramdan çıktığınız zaman avlanabilirsiniz. Sizi Mescid-i Haram''dan alıkoydukları için bir topluma karşı düşmanlık beslemeniz, haddi aşmanıza sebep olmasın. İyilik ve takva hususunda birbirinizle yardımlaşın. Günah ve düşmanlık hususunda yardımlaşmayın. Allah''tan korkun. Şüphesiz Allah''ın azabı şiddetlidir.'),
(5, 3, 6, 107, 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَٰمِ ذَٰلِكُمْ فِسْقٌ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَٰمَ دِينًا فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ḥurrimat ʿalaykumu l-maytatu wa-d-damu wa-laḥmu l-khinzīri wa mā uhilla li-ghayri llāhi bihi wa-l-munkhaniqatu wa-l-mawqūzatu wa-l-mutaraddiyatu wa-n-naṭīḥatu wa mā akala s-sabuʿu illā mā dhakkaytum wa mā dhubiḥa ʿalā n-nuṣubi wa an tastaqsimū bi-l-azlāmi dhālikum fisqun al-yawma yaʾisa lladhīna kafarū min dīnikum falā takhshawhum wa-khshawni al-yawma akmaltu lakum dīnakum wa atmamtu ʿalaykum niʿmatī wa raḍītu lakumu l-islāma dīnan fa-mani ḍṭurra fī makhmaṣatin ghayra mutajānifin li-ithmin fa-inna llāha ghafūrun raḥīmun', 'Size leş, kan, domuz eti, Allah''tan başkası adına kesilenler, boğulmuş, (vurulup) öldürülmüş, düşerek ölmüş, boynuzlanmış ve yırtıcı hayvanın yediği (hariç) hayvanlar haram kılındı. Ancak yetişip kestikleriniz müstesna. Bir de dikili taşlar (putlar) üzerinde (boğazlanan) hayvanlar ve fal oklarıyla kısmet aramanız da (haramdır). Bunlar yoldan çıkmaktır. Bugün kâfirler dininize karşı (artık) ümitsizliğe düşmüşlerdir. Onlardan korkmayın, benden korkun. Bugün sizin için dininizi kemale erdirdim, üzerinize olan nimetimi tamamladım ve din olarak size İslam''ı seçtim. Kim zorda kalır da günaha meylederek olmamak şartıyla (haramdan) yemeye mecbur olursa, (bilsin ki) şüphesiz Allah çok bağışlayıcı, çok merhamet edicidir.'),
(5, 4, 6, 107, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'yas''alūnakə māḏā ʾuḥilla lahum qul ʾuḥilla lakumu ṭ-ṭayyibātu wa mā ʿallamtum mina l-jawāriḥi mukallibīna tuʿallimūnahunna mimmā ʿallamakumu ʾllāhu fakulū mimmā ʾamsakna ʿalaykum wa-ḏkurū ʾsma ʾllāhi ʿalayhi wa-ttaqū ʾllāha ʾinna ʾllāha sarīʿu l-ḥisābi', 'Sana, kendilerine nelerin helâl kılındığını soruyorlar. De ki: "Size temiz ve iyi şeyler helâl kılındı. Allah''ın size öğrettiğinden öğreterek, avcılığa alıştırıp yetiştirdiğiniz (eğittiğiniz) hayvanların sizin için tuttuklarını yiyin. Onu tutarken üzerine Allah''ın adını anın. Allah''tan korkun. Şüphesiz Allah, hesabı çabuk görendir."'),
(5, 5, 6, 107, 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ وَٱلْمُحْصَنَٰتُ مِنَ ٱلْمُؤْمِنَٰتِ وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ وَمَن يَكْفُرْ بِٱلْإِيمَٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 'alyawma uḥilla lakumu ṭ-ṭayyibātu wa ṭaʿāmu lladhīna ūtū l-kitāba ḥillun lakum wa ṭaʿāmu kum ḥillun lahum wa l-muḥṣanātu mina l-muʾmināti wa l-muḥṣanātu mina lladhīna ūtū l-kitāba min qablikum idhā ātaytumūhunna ujūrahunna muḥṣinīna ghayra musāfiḥīna wa lā muttakhidhī ʾakhedānin wa man yakfur bil-ʾīmāni faqad ḥabiṭa ʿamaluhu wa huwa fī l-ʾākhirati mina l-khāsirīna', 'Bugün size temiz ve hoş şeyler helal kılındı. Kendilerine kitap verilenlerin yiyecekleri size helal olduğu gibi, sizin yiyecekleriniz de onlara helaldir. Ve imanlı kadınlardan ve sizden önce kendilerine kitap verilenlerden iffetli kadınlar da, kendilerine mehirlerini verdiğiniz takdirde, onları nikahınız altına almanız size helaldir; onları zinaya (açık ve gizli ilişkiler kurmaya) ve gayrimeşru ilişkilere sürüklenmiş kimseler olarak değil, iffetli kimseler olarak (alın). Kim imanla küfre saparsa, şüphesiz onun ameli boşa gitmiştir ve o, ahirette de hüsrana uğrayanlardandır.'),
(5, 6, 6, 108, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'yā ayyuhā l-ladhīna āmanū idhā qumtum ilā ṣ-ṣalāti fāghsilū wujūhakum wa-aydiyakum ilā l-marāfiqi wamsahū bi-ruʾūsikum wa-arjulakum ilā l-kaʿbayni wa-in kuntum junuban fa-ṭṭahharū wa-in kuntum marḍā aw ʿalā safarin aw jāʾa aḥadun minkum mina l-ghāʾiṭi aw lāmastumu n-nisāʾa fa-lam tajidū māʾan fa-tayammamū ṣaʿīdan ṭayyiban fa-msaḥū bi-wujūhikum wa-aydīkum minhu mā yurīdu l-lāhu li-yajʿala ʿalaykum min ḥaraji wa-lākin yurīdu li-yuṭahhirakum wa-li-yutimma niʿmatahū ʿalaykum laʿallakum tashkurūna', 'Ey iman edenler! Namaza kalkacağınız zaman yüzlerinizi, dirseklere kadar ellerinizi yıkayın. Başlarınızı meshedin, dizlere kadar ayaklarınızı yıkayın. Eğer cünüp iseniz iyice yıkanın. Eğer hasta veya yolculuk halinde iseniz, yahut biriniz abdest bozmaktan gelmişse, yahut kadınlara dokunmuşsanız da su bulamamışsanız, temiz bir toprağa teyemmüm edin. Onu yüzlerinize ve ellerinize sürün. Allah size güçlük çıkarmak istemez, fakat O sizi tertemiz etmek ve üzerinizdeki nimetini tamamlamak ister; umulur ki şükredersiniz.'),
(5, 7, 6, 108, 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'wa-dhkurū niʿmata Allāhi ʿalaykum wa-mīthāqahu alladhī wāthaqakum bihi idh qultum samiʿnā wa-aṭaʿnā wa-ttaqū Allāh inna Allāha ʿalīmun bi-dhāti ṣ-ṣudūr', 'Allah''ın size olan nimetini ve ''İşittik ve itaat ettik'' dediğinizde sizi bununla teyit ettiği ahdini hatırlayın. Allah''a karşı takva sahibi olun. Şüphesiz Allah, göğüslerde olanı hakkıyla bilendir.'),
(5, 8, 6, 108, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'yā ʾayyuhā lladhīna ʾāmanū kūnū qawwāmīna lillāhi shuhadāʾa bilqisṭi walā yajrimannakum shanaʾānu qawmin ʿalā ʾallā taʿdilū iʿdilū huwa ʾaqrabu littaqwā wattaqū l-lāha ʾinna l-lāha khabīrum bimā taʿmalūna', 'Ey iman edenler! Allah için hakkı ayakta tutan, adaletle şahitlik eden kimseler olun. Bir topluluğa duyduğunuz kin, sizi adaletsizliğe sevketmesin. Adalet yapın; bu, takvaya daha yakındır. Allah''tan korkun; şüphesiz Allah yaptıklarınızdan haberdardır.'),
(5, 9, 6, 108, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', 'waʿada ʾallāhu lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti lahum maghfiratun wa ʾajrun ʿaẓīmun', 'Allah, inanıp salih amel işleyenlere, kendileri için bir mağfiret ve büyük bir ecir (mükafat) vaad etmiştir.'),
(5, 10, 6, 109, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'wa-lladhīna kafarū wa-kadhdhabū bi-ʾāyātinā ʾulāʾika ʾaṣḥābu l-jaḥīmi', 'İnkâr edip âyetlerimizi yalanlayanlar ise işte onlar cehennem ehlidir.'),
(5, 11, 6, 109, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'yā ayyuhā alladhīna ʾāmanū udhkurū niʿmata allāhi ʿalaykum idh hamma qawmun ʾan yabsutū ʾilaykum ʾaydiyahum fakaffa ʾaydiyahum ʿankum wa-ttaqū allāha wa-ʿalā allāhi fa-l-yatawakkali l-muʾminūn', 'Ey iman edenler! Allah''ın size olan nimetini hatırlayın. Hani bir kavim size el uzatmak (size saldırmak) istemişti de O, onların ellerini sizden çekmişti. Allah''tan korkun ve müminler yalnız Allah''a güvenip dayansınlar.'),
(5, 12, 6, 109, 'وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 've lekad eḣaẕa-llâhu mîŝâḳa benî isrâʾîl ve be`aŝnâ minhumu-ŝney `aşera naḳîbâ ve ḳâle-llâhu innî me`akum leʾin eḳamtumu-ṣṣalâte ve âteytumu-zzekâte ve âmentum birusulî ve `azzertumûhum ve aḳraḍtumu-llâhe ḳarḍan ḥasenâ leʾukeffiranne `ankum seyyiʾâtikum ve leʾudḣilennekum cennâtin tecrî min taḥtihâ-lʾenhâr femen kefera ba`de ẕâlike minkum feḳad ḍalle sevâʾe-ssebîl', 'Andolsun ki Allah, İsrailoğulları''ndan sağlam söz almıştı. Onlardan on iki nakîb (başkan) göndermiştik. Ve Allah şöyle demişti: "Şüphesiz ben sizinle beraberim. Eğer namazı kılar, zekâtı verir, peygamberlerime inanır, onlara yardım eder ve Allah''a güzel bir borç verirseniz, elbette sizin günahlarınızı örterim ve sizi altından ırmaklar akan cennetlere koyarım. Artık sizden kim bundan sonra inkâr ederse, şüphesiz doğru yoldan sapmış olur."'),
(5, 13, 6, 109, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةً يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 'fabimā naqḍihim mīthāqahum laʿannāhum wa-jaʿalnā qulūbahum qāsiyatan yuḥarrifūna l-kalima ʿan mawāḍiʿihi wa-nasū ḥaẓẓan mimmā dhukkirū bihi wa-lā tazālu taṭṭaliʿu ʿalā khāʾinatin minhum illā qalīlan minhum fa-ʿfu ʿanhum wa-ṣfaḥ ʾinna llāha yuḥibbu l-muḥsinīn', 'Onların ahidlerini bozmaları yüzünden kendilerine lanet ettik ve kalplerini katılaştırdık. Onlar kelimeleri (onların) yerlerinden kaydırırlar ve kendilerine hatırlatılan şeylerin çoğunu unuttular. İçlerinden pek azı hariç, onlardan sürekli bir hainlik görersin. Yine de onları affet ve onlardan yüz çevir. Şüphesiz Allah, iyilik edenleri sever.'),
(5, 14, 6, 110, 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', 'wa-minna alladhīna qālū ʾinnā naṣārā ʾakhadhnā mīthāqahum fanasiū ḥaẓẓan mimmā dhukkirū bihi fa-ʾaghraynā baynahumu l-ʿadāwata wa-l-baghḍāʾa ʾilā yawmi l-qiyāmah wa-sawfa yunabbiʾuhumu llāhu bimā kānū yaṣnaʿūn', 'Kendilerine "Biz Hristiyanız" diyenlerden de misaklarını almıştık. Ama onlar kendilerine hatırlatılan şeylerin çoğunu unuttular. Bu yüzden kıyamete kadar aralarına düşmanlık ve kin saldık. Allah onlara neler yaptıklarını bildirecektir.'),
(5, 15, 6, 110, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَٰبٌ مُّبِينٌ', 'yā ʾahla l-kitābi qad jāʾakum rasūlunā yubayyinu lakum kaṯīran mimmā kuntum tuḫfūna mina l-kitābi wa-yaʿfū ʿan kaṯīrin qad jāʾakum mina llāhi nūr wa-kitābun mubīnun', 'Ey Kitap Ehli! Size Kitap''tan gizlediğinizin çoğunu açıklayan ve çoğundan da vazgeçen peygamberimiz gelmiştir. Size Allah''tan bir nur ve apaçık bir kitap gelmiştir.'),
(5, 16, 6, 110, 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'yahdī bihi ʾllāhu man ʾttabaʿa riḍwānahū subula ʾssalāmi wayukhrijuhum mina ẓẓulumāti ʾilā ʾnnūri biʾʾidhnihī wayahdīhim ʾilā ṣirāṭin mmustaqīmin', 'Allah, rızasına uyanları selamet yollarına iletir ve onları izniyle karanlıklardan aydınlığa çıkarıp kendisini dosdoğru yola iletir.'),
(5, 17, 6, 110, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا يَخْلُقُ مَا يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'leḳad kefera-lleẕîne ḳâlû inne-llâhe huve-lmesîḥu-bnu meryem ḳul femen yemliku mine-llâhi şey''en in erâde en yühlike-lmesîḥa-bne meryeme veümmehû vemen fi-l''arḍi cemî''â velillâhi mülkü-ssemâvâti vel''arḍi vemâ beynehümâ yaḫluḳu mâ yeşâ'' vellâhü ''alâ külli şey''in ḳadîr', 'Andolsun ki, "Allah, Meryem oğlu Mesih''tir" diyenler kâfir olmuşlardır. De ki: "Eğer Allah, Meryem oğlu Mesih''i, annesini ve yeryüzündeki herkesi helak etmek istese, O''na karşı kim bir şeye sahip olabilir?" Göklerin, yerin ve ikisi arasındakilerin hükümranlığı Allah''ındır. O, dilediğini yaratır. Allah her şeye kadirdir.'),
(5, 18, 6, 111, 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَٰرَىٰ نَحْنُ أَبْنَٰٓؤُا۟ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَإِلَيْهِ ٱلْمَصِيرُ', 'wa qālati l-yahūdu wa-n-naṣārā naḥnu abnāʾu llāhi wa-aḥibbāʾuhu qul fa-lima yuʿaḏḏibukum bi-ḏunūbikum bal antum bašarun mimman ḵalaqa yaḡfiru liman yašāʾu wa yuʿaḏḏibu man yašāʾu wa li-llāhi mulku s-samāwāti wa-l-ʾarḍi wa mā baynahumā wa ʾilayhi l-maṣīru', 'Yahudiler ve Hristiyanlar: "Biz Allah''ın oğulları ve sevgilileriyiz" dediler. De ki: "Öyleyse dediğinizin doğru olduğuna ne deliliniz var? O sizi günahlarınızdan dolayı niçin cezalandırsın? Hayır, siz de O''nun yarattığı insanlar gibisiniz. O, dilediğini affeder ve dilediğini azaplandırır. Göklerin, yerin ve ikisi arasında bulunan her şeyin mülkiyeti Allah''ındır. Dönüş de yalnız O''nadır."'),
(5, 19, 6, 111, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'yā ʾahla l-kitābi qad jāʾakum rasūlunā yubayyinu lakum ʿalā fatratin mina r-rusuli ʾan taqūlū mā jāʾanā min bāshīrin walā nadhīrin falaqad jāʾakum bāshīrun wanadhīrun wa-llāhu ʿalā kulli shayin qadīrun', 'Ey Kitap Ehli! Peygamberlerin (tebliğden) bir süre kesintiye uğradığı bir dönemde, size (gerçeği) açıklayan elçimiz gelmiştir. "Bize müjdeleyici de, uyarıcı da gelmedi" demeyesiniz diye. İşte size müjdeleyici de, uyarıcı da gelmiştir. Allah her şeye kadirdir.'),
(5, 20, 6, 111, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', 'wa-ʾidh qāla mūsā li-qawmihi yā-qawmi ʾdh-kurū niʿmata-llāhi ʿalaykum ʾidh jaʿala fīkum ʾanbiyāʾa wa-jaʿalakum mulūkan wa-ʾātākum mā lam yuʾti ʾaḥadan mina-l-ʿālamīn', 'Hani Mûsâ, kavmine demişti ki: "Ey kavmim! Allah''ın size olan nimetini hatırlayın. Hani O, içinizden peygamberler çıkardı ve sizi hükümdarlar yaptı; size âlemlerden hiç kimseye vermediğini verdi."'),
(5, 21, 6, 111, 'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'yā qawmi ʾdkhulū l-ʾarḍa l-muqaddasata llatī kataba l-lāhu lakum walā tartaddū ʿalā ʾadbārikum fatanqalibū khāsirīn', 'Ey kavmim! Allah''ın size yazdığı (takdir ettiği) mukaddes toprağa girin ve sakın gerisin geriye dönmeyin ki, ziyana uğrayanlardan olmayasınız.'),
(5, 22, 6, 111, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', 'qālū yā Mūsā ʾinna fīhā qawman jabbārīn wa ʾinnā lan nadkhulahā ḥattā yakhrujū minhā fa-ʾin yakhrujū minhā fa-ʾinnā dākhilūn', 'Dediler ki: "Ey Musa! Orada zorba bir kavim var. Onlar oradan çıkmadıkça biz oraya asla giremeyiz. Eğer oradan çıkarlarsa, biz de gireriz."'),
(5, 23, 6, 111, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 'qāla rajulāni mina lladhīna yakhāfūna anʿama l-lāhu ʿalayhimā udkhulū ʿalayhimu l-bāba fa-idhā dakhaltumūhu fa-innakum ghālibūna wa ʿalā l-lāhi fa-tawakkalū in kuntum muʾminīna', 'Korkup çekinenlerden, Allah''ın kendilerine lütfettiği iki adam şöyle dedi: "Onların üzerine şehir kapısından girin. Eğer oradan girerseniz, şüphesiz siz galip gelenlersiniz. Eğer inanmışsanız, sadece Allah''a güvenin."'),
(5, 24, 6, 112, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', 'qālū yā Mūsā ʾinnā lan nadkhulahā ʾabadan mā dāmū fīhā fāḏhab ʾanta wa Rabbuka faqātilā ʾinnā hāhunā qāʿidūn', 'Dediler ki: "Ey Musa! Onlar orada bulundukları sürece biz asla oraya giremeyiz. Haydi sen ve Rabbin gidin savaşın! Biz burada oturacağız."'),
(5, 25, 6, 112, 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'qāla rabbi innī lā amliku illā nafsī wa-ʾaḫī fa-furuq baynanā wa-bayna l-qawmi l-fāsiqīn', 'Dedi ki: "Rabbim! Ben kendimden ve kardeşimden başkasına malik olamıyorum. Artık bizimle fasık olan topluluk arasına (kesin) bir ayrılık koy.'),
(5, 26, 6, 112, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِى ٱلْأَرْضِ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'qāla fa-ʾinnahā muḥarramatun ʿalayhim ʾarbaʿīna sanatan yatīhūna fī l-ʾarḍi falā taʾsa ʿalā l-qawmi l-fāsiqīna', 'Allah şöyle buyurdu: "O halde, bu topraklar onlara kırk yıl haramdır. Bu süre içinde yeryüzünde şaşkın bir halde dolaşacaklar. Artık sen bu fasık topluma üzülme."'),
(5, 27, 6, 112, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْءَاخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', 'wa-tlu ʿalayhim nabaʾa ʾibnay ʾādama bi-l-ḥaqqi ʾidh qarrabā qurbānan fa-tuqubbila min ʾaḥadihimā wa-lam yutaqabbal mina l-ʾākhari qāla la-ʾaqtulannaka qāla ʾinnamā yataqabbalu llāhu mina l-muttaqīna', 'Onlara, Âdem''in iki oğlunun haberini gerçeğe uygun olarak anlat: Hani ikisi birer kurban sunmuşlardı da, birinden kabul edilmiş, diğerinden kabul edilmemişti. Kurbanı kabul edilmeyen, ''Seni mutlaka öldüreceğim!'' dedi. Diğeri, ''Allah ancak takva sahiplerinden kabul eder'' dedi.'),
(5, 28, 6, 112, 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'Leʾin besaṭte ileyye yedeke litaqtulenî mâ enâ bibâsiṭin yedî ileyke liʾaqtuleke innî ehâfu Allâhe Rabbe-l''âlemîn', 'Andolsun ki sen beni öldürmek için elini bana uzatsan da ben seni öldürmek için elimi sana uzatacak değilim. Çünkü ben âlemlerin Rabbi olan Allah''tan korkarım.'),
(5, 29, 6, 112, 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَٰبِ ٱلنَّارِ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 'innī urīdu an tabūʾa bi-ithmī wa-ithmik fa-takūna min aṣḥābi an-nār wa-dhālika jazāʾu aẓ-ẓālimīn', 'Şüphesiz ben, benim günahımla senin günahını da yüklenerek (cehennemde) dönmeni istiyorum ki böylece ateş halkından olasın. Zalimlerin cezası işte budur.'),
(5, 30, 6, 112, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَٰسِرِينَ', 'faṭawwaʿat la-hū nafs-uhū qatl-a akhī-hi fa-qatala-hū fa-aṣbaḥa min-al-khāsirīn', 'Nefsi, kardeşini öldürmeye onu sürükledi, böylece onu öldürdü ve böylece hüsrana uğrayanlardan oldu.'),
(5, 31, 6, 112, 'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ قَالَ يَٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى فَأَصْبَحَ مِنَ ٱلنَّٰدِمِينَ', 'fa baʿatha llāhu ġurāban yabbaḥu fī l-arḍi li yuriyahu kayfa yuwārī sawʾata ʾaxīhi qāla yā waylatā ʾaʿajaztu ʾan ʾakūna miṯla hāḏā l-ġurābi fa ʾuwāriya sawʾata ʾaxī fa ʾaṣbaḥa mina n-nādimīn', 'Bunun üzerine Allah, yeri eşeleyip duran bir karga gönderdi. Kardeşinin cesedini nasıl örtüp gizleyeceğini ona göstermiş oldu. "Vay halime!" dedi, "Şu karga gibi olamadım da kardeşimin cesedini örtemedim!" Böylece pişmanlık duyanlardan oldu.'),
(5, 32, 6, 113, 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', 'min ajli dhālika katabnā ʿalā banī isrāʾīla annahū man qatala nafsan bighayri nafsin aw fasādin fī l-arḍi fakʾaṉṉamā qatala n-nāsa jamīʿan wa-man aḥyāhā fakʾaṉṉamā aḥyā n-nāsa jamīʿan wa-laqad jāʾathum rusulunā bi-l-bayyināti thumma inna kathīran minhum baʿda dhālika fī l-arḍi la-musrifūna', 'İşte bu yüzden, İsrailoğulları''na şöyle yazmıştık: Kim bir cana karşılık olmaksızın veya yeryüzünde bir bozgunculuk çıkarmak yüzünden olmaksızın bir cana kıyarsa, bütün insanları öldürmüş gibi olur. Kim de bir can bağışlarsa, bütün insanları bağışlamış gibi olur. Andolsun ki onlara peygamberlerimiz apaçık delillerle gelmişti. Ama onlardan birçoğu bütün bunlardan sonra yeryüzünde israfçıdır.'),
(5, 33, 6, 113, 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌ', 'innamā jazāʾu alladhīna yuḥāribūna allāha warasūlahū wayasʿawna fī l-arḍi fasādan an yuqattalū aw yuṣallabū aw tuqaṭṭaʿa aydīhim wa-arjulumum min khilāfin aw yunfaw mina l-arḍi dhālika lahum khizyun fī d-dunyā wa-lahum fī l-ʾākhirati ʿadhābun ʿaẓīmun', 'Allah''a ve Resûlü''ne karşı savaşanların ve yeryüzünde fesat çıkarmaya çalışanların cezası, ancak öldürülmeleri veya asılmaları ya da ellerinin ve ayaklarının çapraz olarak kesilmesi ya da yeryüzünden sürülmeleridir. Bu, dünyadaki onların onurunu kırmaktır. Ahirette ise onlara büyük bir azap vardır.'),
(5, 34, 6, 113, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'illa alladhīna tābū min qabli an taqdirū ʿalayhim faʿlamū anna Allāha ghafūrun raḥīmun', 'Ancak, siz onları yakalamadan önce tevbe edenler müstesna. Bilin ki Allah, çok bağışlayandır, çok merhamet edendir.'),
(5, 35, 6, 113, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', 'yā ayyuhā alladhīna āmanū ittaqū allāh wa-btaghū ilayhi al-wasīlah wa-jāhidū fī sabīlihī laʿallakum tufliḥūn', 'Ey iman edenler! Allah''a karşı gelmekten sakının ve O''na (yaklaşmaya vesile) arayın. O''nun yolunda cihad edin ki kurtuluşa eresiniz.'),
(5, 36, 6, 113, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ʾinna lladhīna kafarū law ʾanna lahum mā fī l-ʾarḍi jamīʿan wa mithlahū maʿahū li yaftadū bihi min ʿadhābi yawmi l-qiyāmati mā tuqubbila minhum wa lahum ʿadhābun ʾalīmun', 'Şüphesiz inkâr edenler, yeryüzündeki her şeye ve hatta bunun bir katına daha sahip olsalar da, kıyamet gününün azabından kurtulmak için hepsini fidye olarak verseler, yine de onlardan kabul edilmez. Onlar için acı veren bir azap vardır.'),
(5, 37, 6, 114, 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُّقِيمٌ', 'yurīdūna an yakhrujū mina n-nāri wa mā hum bi-khārijīna minhā wa lahum ʿadhābun muqīmun', 'Ateşten çıkmak isterler, oysa ondan çıkacak değillerdir. Ve onların sürekli bir azabı vardır.'),
(5, 38, 6, 114, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًا مِّنَ ٱللَّهِ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'wa-s-sāriqu wa-s-sāriqatu fa-qṭaʿū ʾaydiyahumā jazāʾam bimā kasabā nakālam mina ʾllāhi wa-llāhu ʿazīzun ḥakīmun', 'Erkek hırsızla kadın hırsızın, kazandıklarına bir karşılık ve Allah''tan birer ibret olmak üzere ellerini kesin. Allah Azîz''dir, Hakîm''dir.'),
(5, 39, 6, 114, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'fe men tābe mim baʿdi ẓulmihī wa aṣlaḥa fe inne Allāhe yetūbu ʿalayhi inne Allāhe ġafūrun raḥīmun', 'Kim zulmünden sonra tevbe eder ve durumunu düzeltirse, şüphesiz Allah onun tevbesini kabul eder. Çünkü Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(5, 40, 6, 114, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'elem taʿlem enne-llāhe lehu mulku-s-semāwāti ve-l-ʾarḍi yuʿaḏḏibu men yešāʾu wa-yagfiru limen yešāʾu ve-llāhu ʿalā kulli šayʾin qadīrun', 'Göklerin ve yerin mülkiyetinin Allah''a ait olduğunu ve Allah''ın dilediğini azaplandıracağını, dilediğini de bağışlayacağını bilmedin mi? Allah her şeye hakkıyla gücü yetendir.'),
(5, 41, 6, 114, 'يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ وَمِنَ ٱلَّذِينَ هَادُوا۟ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌ', 'yā ayyuhā r-rasūlu lā yaḥzunnka l-ladhīna yusāriʿūna fī l-kufri mina l-ladhīna qālū ʾāmannā bi-ʾafwāhihim wa-lam tuʾmin qulūbuhum wa-mina l-ladhīna hādū sammāʿūna lil-kadhibi sammāʿūna li-qawmin ʾākhirīna lam yaʾtūka yuḥarrifūna l-kalima min baʿdi mawāḍiʿihi yaqūlūna ʾin ʾūtītum hādhā fa-khudhūhu wa-ʾin lam tuʾtūhu fa-ḥdhārū wa-man yuridī l-lāhu fitnatahuu fa-lan tamlika lahuu mina l-lāhi shayʾan ʾulāʾika l-ladhīna lam yuridī l-lāhu ʾan yuṭahhira qulūbahum lahum fī d-dunyā khizyun wa-lahum fī l-ʾākhirati ʿadhābun ʿaẓīmun', 'Ey Resûl! Ağızlarıyla "inandık" diyen, ama kalpleri inanmamış olan kimselerle, Yahudilerden olup yalana kulak veren, sana gelmeyen başka bir kavim için koşuşanlar seni üzmesin. Onlar kelimeleri yerlerinden kaydırırlar. "Eğer size bu verilirse alın, ama verilmezse sakının" derler. Allah kimin azdırılmasına hükmederse, sen onun için Allah''tan hiçbir şey yapamazsın. İşte onların kalblerini Allah''ın temizlemesini dilemediği kimselerdir. Onlar için dünyada bir perişanlık, ahirette ise büyük bir azap vardır.'),
(5, 42, 6, 115, 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'sammāʿūna lil-kadhibi akālūna lis-suḥti fa-in jāʾūka fa-ḥkum baynahum aw aʿriḍ ʿanhum wa-in tuʿriḍ ʿanhum fa-lan yaḍurrūka shayʾan wa-in ḥakamta fa-ḥkum baynahum bil-qisṭi ʾinna ʾllāha yuḥibbu l-muqsiṭīna', 'Onlar yalana kulak veren, haramı durmadan/durmaksızın yiyenlerdir. Eğer sana gelirlerse, ister aralarında hükmet, ister onlardan yüz çevir. Eğer onlardan yüz çevirirsen, sana hiçbir zarar veremezler. Eğer hükmedersen, aralarında adaletle hükmet. Şüphesiz Allah, adil davrananları sever.'),
(5, 43, 6, 115, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'wa kayfa yuḥakkimūnak wa ʿindahumu t-tawrātu fīhā ḥukmu llāhi thumma yatawallawna min baʿdi dhālika wa mā ʾulāʾika bil-muʾminīna', 'Onların yanında Tevrat varken, nasıl seni hakem tayin ederler? Hem Tevrat''ta Allah''ın hükmü de varken! Sonra da bunun ardından yüz çevirirler. İşte onlar inanmış kimseler değillerdir.'),
(5, 44, 6, 115, 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ', 'ʾinnā ʾanzalnā t-tawrāta fīhā hudan wa-nūr yaḥkumu bihā n-nabiyyūna l-ladhīna ʾaslamū li-l-ladhīna hādū wa-r-rabbāniyyūna wa-l-ʾaḥbāru bimā stuhfiẓū min kitābi llāhi wa-kānū ʿalayhi shuhadāʾa falā takhshawu n-nāsa wa-khshawni wa-lā tashtarū bi-ʾāyātī thamanan qalīlan wa-man lam yaḥkum bimā ʾanzala llāhu fa-ʾulāʾika humu l-kāfirūna', 'Şüphesiz Tevrat''ı, içinde bir hidayet ve bir nur olarak biz indirdik. Kendilerini Allah''a teslim etmiş olan peygamberler, Yahudiler hakkında onunla hükmederlerdi; (yine) Allah''a adanmış alimler ve (dini derinlemesine bilen) hahamlar da, Allah''ın kitabından muhafaza etmekle görevlendirildikleri şeylerle ve onun üzerine şahit olmalarıyla (hükmederlerdi). (Ey Yahudiler!) İnsanlardan korkmayın, benden korkun. Benim âyetlerimi az bir karşılığa satmayın. Kim Allah''ın indirdiği ile hükmetmezse, işte onlar kâfirlerdir.'),
(5, 45, 6, 115, 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'wa katabnā ʿalayhim fīhā anna n-nafsa bi-n-nafsi wa-l-ʿayna bi-l-ʿayni wa-l-anfa bi-l-anfi wa-l-udhunna bi-l-udhunni wa-s-sinna bi-s-sinni wa-l-jurūḥa qiṣāṣun fa-man taṣaddaqa bihi fa-huwa kaffāratun lahū wa man lam yaḥkum bimā anzalallāhu fa-ʾulāʾika humu ẓ-ẓālimūn', 'Onlara o devirde şöyle yazmıştık: Cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralara da kısas (misilleme) vardır. Kim bunu sadaka olarak bağışlarsa, bu kendisi için bir kefaret olur. Allah''ın indirdiğiyle hükmetmeyenler ise zalimlerin ta kendileridir.'),
(5, 46, 6, 116, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'wa qaffaynā ʿalā āthārihim biʿīsā ibni maryama muṣaddiqan limā bayna yadayhi mina t-tawrāti wa ātaynāhu l-injīla fīhi hudan wa nūr wa muṣaddiqan limā bayna yadayhi mina t-tawrāti wa hudan wa mawʿiẓatan lil-muttaqīna', 'Onların peşinden, önündeki Tevrat''tan tasdik edici olarak Meryem oğlu İsa''yı gönderdik ve ona, içinde hidayet ve nur bulunan, önündeki Tevrat''tan tasdik edici ve takva sahipleri için bir hidayet ve öğüt olan İncil''i verdik.'),
(5, 47, 6, 116, 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'wa-l-yaḥkum ahlu l-ʾinjīli bimā ʾanzala ʾllāhu fīhi wa-man lam yaḥkum bimā ʾanzala ʾllāhu fa-ʾulāʾika humu l-fāsiqūna', 'Onların, Allah''ın indirdiğiyle hükmetmeleri gerekir. Kim Allah''ın indirdiğiyle hükmetmezse, işte onlar fasıkların ta kendileridir.'),
(5, 48, 6, 116, 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَٰبِ وَمُهَيْمِنًا عَلَيْهِ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'waʾanzalnā ʾilayka l-kitāba bil-ḥaqqi muṣaddiqan limā bayna yadayhi mina l-kitābi wa-muhayminan ʿalayhi fa-ḥkum baynahum bimā ʾanzala ʾllāhu wa-lā tattabiʿ ʾahwāʾahum ʿammā jāʾaka mina l-ḥaqqi likullin jaʿalnā minkum shirʿatan wa-minhājan wa-law shāʾa ʾllāhu la-jaʿalakum ʾummatan wāḥidatan wa-lākin li-yabluwakum fī mā ʾātākum fa-stabiqū l-khayrāt ʾilā ʾllāhi marjiʿukum jamīʿan fa-yunabbiʾukum bimā kuntum fīhi takhtalifūna', 'Sana da, kendinden önceki kitapları tasdik eden ve onları denetleyip koruyan Kitab''ı hak olarak indirdik. Artık onların mallarını Allah''ın indirdiğiyle yönet; sana gelen hakkı bırakıp da onların keyiflerine uyma. Sizden her biriniz için bir şeriat ve bir yol belirledik. Eğer Allah dileseydi, sizi tek bir ümmet yapardı. Fakat size verdiğiyle sizi imtihan etmek istedi. Öyleyse iyiliklere koşuşun. Hepinizin dönüşü Allah''adır. O zaman, üzerinde ayrılığa düştüğünüz şeyleri size haber verecektir.'),
(5, 49, 6, 116, 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', 'wa-ani ḥkum baynahum bimā anzala ʾllāhu wa-lā tattabiʿ ahwāʾahum wa-ḥḏarhum an yaftinūka ʿan baʿḍi mā anzala ʾllāhu ʾilayka fa-ʾin tawallaw fa-ʿlam ʾannemā yurīdu ʾllāhu ʾan yuṣībahum bi-baʿḍi ḏunūbihim wa-ʾinna kaṯīran mina n-nāsi la-fāsiqūna', 'Onların aralarında Allah''ın indirdiği ile hükmet. Onların heveslerine uyma. Allah''ın sana indirdiği (hükümlerin) bir kısmından seni saptırmalarından sakın. Eğer (bu hükümlerden) yüz çevirirlerse, bil ki Allah onları bazı günahları yüzünden musibete uğratmak istemektedir. Şüphesiz ki insanların çoğu yoldan çıkmışlardır.'),
(5, 50, 6, 116, 'أَفَحُكْمَ ٱلْجَٰهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ', 'ʾafahukma l-jāhiliyyati yبغūna wa man ʾaḥsanu mina llāhi ḥukman li-qawmin yūqinūna', 'Yoksa cahiliye devrinin hükmünü mü arıyorlar? İyice bilen bir topluluk için Allah''tan daha iyi hüküm verecek kim vardır?'),
(5, 51, 6, 117, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوْلِيَآءَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'yā ayyuhā lladhīna āmānū lā tattakhidhū l-yahūda wā n-naṣārā awliyāʾa baʿḍuhum awliyāʾu baʿḍin waman yatawallahum minkum faʾinnahuu minhum ʾinna llāha lā yahdī l-qawma ẓ-ẓālimīna', 'Ey iman edenler! Yahudileri ve Hristiyanları dost edinmeyin. Onlar birbirlerinin dostudurlar. Sizden kim onları dost edinirse, şüphesiz o onlardan olur. Şüphesiz Allah, zalimler topluluğunu doğru yola iletmez.'),
(5, 52, 6, 117, 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ', 'fa-tarā alladhīna fī qulūbihim maraḍun yusāriʿūna fīhim yaqūlūna nakhshā an tuṣībanā dāʾirah fa-ʿasā allāhu an yaʾtiya bi-l-fatḥi aw amrin min ʿindihi fa-yuṣbiḥū ʿalā mā asarrū fī anfusihim nādimīn', 'Kalplerinde hastalık olanları, "Bağımıza bir felaket gelmesinden korkuyoruz" diyerek (onların) arasında koşuşup dururlarken görürsün. Umulur ki Allah bir fetih ihsan eder veya kendi katından bir emir getirir de, böylece gizledikleri şeyden dolayı pişman olurlar.'),
(5, 53, 6, 117, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ إِنَّهُمْ لَمَعَكُمْ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ', 'wa-yaqūlu alladhīna ʾāmanū ʾahāʾulāʾi alladhīna ʾaqsamū bi-llāhi jahda ʾaymānihim ʾinnahum lamaʿakum ḥabiṭat ʾaʿmāluhum fa-ʾaṣbaḥū khāsirīna', 'İman edenler şöyle derler: "Rableri katında bu sayılanlar, Allah''a yemin ederek O''nunla beraber olanlar bunlardır." dediler. Onların bütün yaptıkları boşa gitmiş ve böylece hüsrana uğramışlardır.'),
(5, 54, 6, 117, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَٰفِرِينَ يُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'yā ayyuhā alladhīna āmanū man yartadda minkum ʿan dīnihi fasawfa yaʾtī allāhu biqawmin yuḥibbuhum wa yuḥibbūnahu adhil latin ʿalā l-muʾminīna ʾaʿizzatin ʿalā l-kāfirīna yujāhidūna fī sabīli allāhi walā yakhāfūna lawmata lāʾimin dhālika faḍlu allāhi yuʾtīhi man yashāʾu wallāhu wāsiʿun ʿalīmun', 'Ey iman edenler! Sizden kim dininden dönerse (bilsin ki) Allah onların yerine, kendilerinin sevdiği ve kendilerini seven, müminlere karşı alçak gönüllü, kâfirlere karşı kibirli (ve güçlü) bir topluluk getirir. Allah yolunda cihad ederler ve hiçbir kınayıcının kınamasından da çekinmezler. Bu, Allah''ın lütfudur, onu dilediğine verir. Allah, lütfu geniş olan, her şeyi bilen''dir.'),
(5, 55, 6, 117, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', 'ʾinnemā walīyukumu ʾllāhu wa-rasūluhu wa-llaḏīna ʾāmanū llaḏīna yuqīmūna ṣ-ṣalāta wa-yuʾtūna z-zakāta wa-hum rākiʿūn', 'Sizin veliniz ancak Allah, O''nun Resûlü ve iman edenlerdir; o iman edenler ki, namazı kılarlar, zekâtı verirler ve rükû edicidirler.'),
(5, 56, 6, 117, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَٰلِبُونَ', 've men yetevellellāhe ve resūlehu vellezîne âmenû fe inne hizballāhi humul ğālibûn', 'Kim Allah''ı, Peygamberini ve iman edenleri dost edinirse, bilsin ki Allah''tan yana olanlar üstün olanlardır.'),
(5, 57, 6, 117, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 'yā ayyuhā alladhīna āmānū lā tattakhidhū alladhīna ittakhadhū dīnakum huzūan wa laʿiban mina alladhīna ūtū al-kitāba min qablikum wa al-kuffāra awliyāʾa wa-ttaqū Allāha in kuntum muʾminīna', 'Ey iman edenler! Sizden önce kendilerine kitap verilenlerden kimileri, dininizi alay ve eğlence (konusu) edindiler. Eğer inanmışsanız, Allah’tan korkup (O’na) itaatten ayrılmayın.'),
(5, 58, 6, 118, 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', 'wa ʾiḏā nādaytum ʾilā ṣ-ṣalāti ittāḵaḏūhā huzuwan wa laʿiban ḏālika bi-ʾannahum qawmun lā yaʿqilūna', 'Namaz için çağırdığınızda onu alay ve eğlence konusu edinirler. Bu, onların aklını kullanmayan bir topluluk olmalarındandır.'),
(5, 59, 6, 118, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ', 'qul yā ʾahla l-kitābi hal tanqimūna minnā ʾillā ʾan ʾāmannā bi-llāhi wa mā ʾunzilla ʾilaynā wa mā ʾunzilla min qablu wa ʾanna ʾaktharakum fāsiqūna', 'De ki: "Ey kitap ehli! Sırf Allah''a, bize indirilene ve daha önce indirilene iman etmemizden başka neyimizden dolayı bize buğzediyorsunuz? Oysa onların çoğu yoldan çıkmışlardır."'),
(5, 60, 6, 118, 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', 'Qul hal unabbi''ukum bi-sharriñ min dhālika mathūbatan ʿinda Allāh man laʿanahu Allāhu wa-ghaḍiba ʿalayhi wa-jaʿala minhumu l-qiradata wa-l-khanāzīra wa-ʿabada ṭ-ṭāghūt ʾulā''ika sharruñ makānan wa-ʾaḍallu ʿan sawā''i s-sabīl', 'De ki: "Allah katında, (insan ve cinlerden) kendilerine gazap ettiği, lanet ettiği, içlerinden maymunlar ve domuzlar kıldığı ve tağuta tapanlar olarak bulundurduğu kimselerden daha kötü bir karşılık görecekleri konusunda sizi bilgilendireyim mi? İşte bunlar, konumca daha kötü ve dosdoğru yoldan daha çok sapmış olanlardır."'),
(5, 61, 6, 118, 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', 'wa-idhā jāʾūkum qālū ʾāmannā wa-qad dakhalū bi-l-kufri wa-hum qad kharajū bihi wa-llāhu ʾaʿlamu bi-mā kānū yaktumūn', 'Onlar size geldiklerinde, "İnandık" derler. Oysa onlar küfürle girmişler ve yine onunla çıkmışlardır. Allah, onların gizlemekte olduklarını daha iyi bilendir.'),
(5, 62, 6, 118, 'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', 'wa tarā kathīran minhum yusāriʿūna fī l-ithmi wa-l-ʿudwāni wa-aklihimu s-suḥta la-biʾsa mā kānū yaʿmalūna', 'Onlardan çoğunun günaha ve düşmanlığa koştuğunu ve haram yediklerini görürsün. Yaptıkları ne kötüdür!'),
(5, 63, 6, 118, 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', 'lawlā yan-hāhumu r-rabbāniyyūna wal-ʾaḥbāru ʿan qawlihimu l-ʾithma wa-ʾaklihimu s-suḥta la-biʾsa mā kānū yaṣnaʿūna', 'Rabbânîler ve ahbârlar (dini liderler ve bilginler) onları, günah söylemelerinden ve haram yiyip tüketmelerinden men etmeli değil miydiler? Yapmakta oldukları şey ne kötüdür!'),
(5, 64, 6, 118, 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 'wa qālati l-yahūdu yadu l-lāhi maghlūlah ghullat aydīhim wa luʿinū bimā qālū bal yadahū mabsuṭatāni yunfiqu kayfa yashāʾu wa layazīdanna kathīran minhum mā unzila ilayka min rabbika ṭughyānan wa kufran wa alqaynā baynahumu l-ʿadāwata wa l-baghḍāʾa ilā yawmi l-qiyāmah kullamā awqadū nāran lil-ḥarbi aṭfaʾahā l-lāhu wa yasʿawna fī l-arḍi fasādan wa l-lāhu lā yuḥibbu l-mufsidīn', 'Yahudiler: "Allah''ın eli sıkıdır (bağlıdır)" dediler. Kendi elleri bağlandı ve dedikleri yüzünden lanetlendiler. Hayır! Allah''ın iki eli de açıktır, dilediği gibi harcar. Andolsun ki Rabbinden sana indirilen (Kur''an), onlardan çoğunun azgınlığını ve küfrünü artıracaktır. Biz de onların arasına Kıyamet gününe kadar sürecek düşmanlık ve kin saldık. Ne zaman savaş için bir ateş yaktılarsa Allah onu söndürmüştür. Onlar yeryüzünde bozgunculuk yapmaya koşarlar. Allah ise bozguncuları sevmez.'),
(5, 65, 6, 119, 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ٱلنَّعِيمِ', 'wa-law anna ahla l-kitābi āmānū wa-ttaqaw la-kaffarnā ʿanhum sayyiʾātihim wa-la-adkhalnāhum jannāti n-naʿīmi', 'Eğer Kitap Ehli iman edip (Allah''a karşı gelmekten) sakınsalardı, elbette onların kötülüklerini örter ve onları nimeti bol cennetlere sokardık.'),
(5, 66, 6, 119, 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', 'Wa law annahum aqāmū at-Tawrāta wal-Injīla wa mā unzila ilayhim min Rabbihim La''akalū min fawqihim wa min taḥti arjulihim Minhum ummatun muqtaṣidah Wa kathīrun minhum sā''a mā yaʿmalūn', 'Eğer onlar Tevrat''ı, İncil''i ve kendilerine Rableri tarafından indirileni (Kur''an''ı) ayakta tutsalardı, elbette hem üstlerinden hem de ayaklarının altından (sayısız rızıklar) yiyeceklerdi. Onlardan bir kısmı doğru yoldadır, ancak onlardan çoğunun yaptıkları ne kötüdür!'),
(5, 67, 6, 119, 'يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'yā ayyuhā r-rasūlu balliġ mā unzila ilayka min rabbika wa in lam tafʿal famā balleġta risālatahū wa llāhu yaʿṣimuka mina n-nāsi inna llāha lā yahdī l-qawma l-kāfirīna', 'Ey Resûl! Rabbinden sana indirileni tebliğ et. Eğer bunu yapmazsan, O''nun risaletini tebliğ etmemiş olursun. Allah seni insanlardan koruyacaktır. Şüphesiz Allah, kâfirler topluluğunu doğru yola eriştirmez.'),
(5, 68, 6, 119, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'Qul yā ahla l-kitābi lastum ʿalā shayʾin ḥattā tuqīmū t-tawrāta wa-l-injīla wa mā unzila ilaykum min rabbikum Wa layazīdanna kathīran minhum mā unzila ilayka min rabbika ṭughyānan wa kufran Falā taʾsa ʿalā l-qawmi l-kāfirīn', 'De ki: "Ey Kitap Ehli! Tevrat''ı, İncil''i ve Rabbinizden size indirileni (tam olarak) uygulamadıkça hiçbir şey (dininiz) üzere değilsiniz." Andolsun ki, sana Rabb''inden indirilen (Kur''an) onların çoğuna azgınlık ve küfür olarak mutlaka artıracaktır. Artık o kâfirler topluluğu için üzülme!'),
(5, 69, 6, 119, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَعَمِلَ صَٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ʾinna alladhīna ʾāmanū wa-alladhīna hādū wa-aṣ-ṣābiʾūna wa-an-naṣārā man ʾāmana bi-llāhi wa-l-yawmi l-ʾākhiri wa-ʿamila ṣāliḥan fa-lā khawfun ʿalayhim wa-lā hum yaḥzanūna', 'Şüphesiz iman edenler, Yahudiler, Sabiîler ve Hristiyanlardan kim Allah''a ve ahiret gününe inanıp salih amel işlerse, onlara korku yoktur ve onlar mahzun da olmayacaklardır.'),
(5, 70, 6, 119, 'لَقَدْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ', 'laqad ʾakhadhnā mīthāqa banī ʾisrāʾīla wa ʾarsalnā ʾilayhim rusulan kullamā jāʾahum rasūlun bimā lā tahwā ʾanfusuhum farīqan kadhdhabū wa farīqan yaqtulūna', 'And لقد (andolsun ki) biz Benî İsrâîl''den mîsak (ahd) almıştık ve onlara resûller göndermiştik. Kendilerine resûl, nefislerinin hoşlanmadığı bir şeyle geldiği zaman, bir kısmını yalanladılar ve bir kısmını da öldürüyorlar.'),
(5, 71, 6, 120, 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'waḥasibū ʾallā takūna fitnah fāʿamū waṣammū thumma tāba ʾallāhu ʿalayhim thumma ʿamū waṣammū kaṯīrum minhum ʾallāhu baṣīrum bimā yaʿmalūn', 'Onlar için bir fitne (imtihan) olmayacağını sandılar, bu yüzden kör oldular ve sağır kesildiler. Sonra Allah onların tevbesini kabul etti. Ama onlardan birçoğu yine kör oldu ve sağır kesildi. Allah onların yapmakta olduklarını hakkıyla görmektedir.'),
(5, 72, 6, 120, 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'leḳad kefera-lleẕîne ḳālû inne-llâhe huve-lmesîḥu-bnu meryem veḳâle-lmesîḥu yâ benî isrâʾîle-ʿbudû-llâhe rabbî verabbekum innehu men yuşrik billâhi feḳad ḥarrame-llâhu ʿaleyhi-lcennete vemeʾvâhu-nnâr vemâ liżżâlimîne min enṣâr', 'Andolsun ki, "Allah, Meryem oğlu Mesih''tir" diyenler kâfir olmuşlardır. Oysa Mesih şöyle demişti: "Ey İsrailoğulları! Benim de Rabbim, sizin de Rabbiniz olan Allah''a kulluk edin." Şüphesiz kim Allah''a ortak koşarsa, Allah ona cenneti haram kılar ve onun varacağı yer ateştir. Zalimler için hiçbir yardımcı da yoktur.'),
(5, 73, 6, 120, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٍ وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌ وَٰحِدٌ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', 'leḳad kefera-lleẕîne ḳālû inne-llâhe ŝâliŝu ŝelâŝetin vemâ min ilâhin illâ ilâhün vâḥidün vein lem yentehû ‘ammâ yeḳūlûne leyemessenne-lleẕîne keferû minhüm ‘aẕâbün elîmün', 'Andolsun ki, "Allah üçten üçüncüsüdür" diyenler kâfir olmuşlardır. Oysa tek bir İlah''tan başka hiçbir ilah yoktur. Eğer söylediklerinden vazgeçmezlerse, onlardan inkâr edenlere mutlaka elem verici bir azap dokunacaktır.'),
(5, 74, 6, 120, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'ʾafalā yatūbūna ʾilā llāhi wayastagfirūnahu wa llāhu ghafūrun raḥīmun', 'Allah''a tövbe edip O''ndan bağışlanma dilemiyorlar mı? Allah çok bağışlayandır, çok merhamet edendir.'),
(5, 75, 6, 120, 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْءَايَٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', 'mā l-masīḥu bnu maryama illā rasūlun qad ḵalath min qablihi r-rusulu wa-ummuhu ṣiddīqatun kānā yaʾkulāni ṭ-ṭaʿāma unẓur kayfa nubayyinuhumul-ʾāyāti thumma nẓur ʾannā yuʾfakūna', 'Meryem''in oğlu Mesih, yalnızca bir elçidir. Kendisinden önce de nice elçiler gelip geçmiştir. Annesi de dosdoğru bir kadındı. Onların ikisi de (diğer insanlar gibi) yemek yerlerdi. Onlara ayetleri nasıl açıkladığımızı gör; sonra da nasıl (gerçekten) çevrildiklerini gör!'),
(5, 76, 6, 120, 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'Qul a-taʿbudūna min dūni llāhi mā lā yamliku lakum ḍarraw wa-lā nafʿan Wa-llāhu huwa s-samīʿu l-ʿalīm', 'De ki: Allah''ı bırakıp da size ne bir zarar ne de bir fayda sağlayamayacak olan şeylere mi tapıyorsunuz? Halbuki Allah, her şeyi duyan, her şeyi bilendir.'),
(5, 77, 6, 121, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', 'qul yā ʾahla l-kitābi lā taghlū fī dīnikum ghayra l-ḥaqqi wa lā tattabiʿū ʾahwāʾa qawmin qad ḍallū min qablu wa ʾaḍallū kathīran wa ḍallū ʿan sawāʾi s-sabīli', 'De ki: "Ey Kitap Ehli! Dininizde haksız yere aşırı gitmeyin ve daha önce sapmış, birçoklarını da saptırmış ve doğru yoldan sapmış bir topluluğun heveslerine uymayın."'),
(5, 78, 6, 121, 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'luʿina alladhīna kafarū min banī isrāʾīla ʿalā lisāni dāwūda wa ʿīsā bni maryama dhālika bimā ʿaṣaw wa kānū yaʿtadūn', 'İsrailoğullarından küfredenler, Davud''un ve Meryem''in oğlu İsa''nın diliyle lanetlendi. Bu, isyan etmeleri ve haddi aşmaları nedeniyledir.'),
(5, 79, 6, 121, 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', 'kānū lā yatanāhawna ʿan munkarin faʿalūhu labiʾsa mā kānū yafʿalūn', 'Onlar, işledikleri münkerden (kötülükten) birbirlerini vazgeçirmezlerdi. Yapmakta oldukları şey ne kötüdür!'),
(5, 80, 6, 121, 'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَٰلِدُونَ', 'tarā kathīran minhum yatawallawna alladhīna kafarū labiʾsa mā qaddamat lahum anfusuhum an sakhiṭa allāhu ʿalayhim wafī l-ʿadhābi hum khālidūna', 'Onlardan çoğunun, inkâr edenlere dostluk ettiklerini görürsün. Allah''ın kendilerine gazap ettiği şey ne kötüdür! Ve onlar azapta ebedî kalacaklardır.'),
(5, 81, 6, 121, 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًا مِّنْهُمْ فَٰسِقُونَ', 'wa law kānū yuʾminūna bi-llāhi wa-n-nabiyyi wa mā ʾunzila ʾilayhi mā-ttakhadhūhum ʾawliyāʾa wa-lākinna kathīran minhum fāsiqūna', 'Onlar Allah''a, Peygamber''e ve ona indirilene inanmış olsalardı, onları (o kâfirleri) veli edinmezlerdi. Fakat onlardan çoğu yoldan çıkmışlardır.'),
(5, 82, 7, 121, 'لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', 'Letecidenne eşeddennâsi adâveten lilleẕîne âmenûl yehûde velleẕîne eşrakû Ve letecidenne akrabehum meveddeten lilleẕîne âmenûlleẕîne kâlû innâ nasârâ Ẕâlike bi-enne minhum kissîsîne ve ruhbânâ Ve ennehum lâ yestekbirûn', 'İman edenlere düşmanlıkta insanların en şiddetlisi olarak Yahudileri ve müşrikleri bulacaksın. İman edenlere sevgi bakımından en yakınlarını ise, “Biz Hristiyanız” diyenleri bulacaksın. Bu, onların içinde ruhbanlar ve rahipler bulunmasından ve onların büyüklük taslamamalarındandır.'),
(5, 83, 7, 122, 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 'wa-idhā samiʿū mā unzila ilā r-rasūli tarā ʾaʿyunahum tafīḍu mina d-damʿi mimmā ʿarafū min al-ḥaqqi yaqūlūna rabbanā ʾāmannā fa-ktubnā maʿa š-šāhidīna', 'Resule indirileni duyduklarında, hakkı tanımalarından dolayı gözlerinin dolduğunu görürsün. "Rabbimiz! İman ettik. Bizleri şahitlerle birlikte yaz. " derler.'),
(5, 84, 7, 122, 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّٰلِحِينَ', 've mā lenā lā nuʾminu bi-llāhi ve mā jāʾanā mine l-ḥaqqi ve naṭmaʿu ʾen yudkhilenā rabbunā meʿa l-qawmi ṣ-ṣāliḥīn', 'Allah''a ve bize gelen hakka inanmamamız için bize ne oluyor? Rabbimizin bizi salih kimselerle birlikte cennete koymasını umuyoruz.'),
(5, 85, 7, 122, 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 'faʾaṯābahumu ʾallāhu bimā qālū jannātin tajrī min taḥtihā ʾalʾanhāru khālidīna fīhā waḏālika jazāʾu ʾalmuḥsinīna', 'Allah da onlara, söyledikleri sözler sebebiyle, altlarından ırmaklar akan, içinde ebedi kalacakları cennetler mükâfatını verdi. İşte bu, iyilik edenlerin mükâfatıdır.'),
(5, 86, 7, 122, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'wa-lladhīna kafarū wa-kadhdhabū bi-ʾāyātinā ʾulāʾika ʾaṣḥābu l-jaḥīmi', 'İnkâr edip âyetlerimizi yalanlayanlar ise, işte onlar cehennem ehlidir.'),
(5, 87, 7, 122, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'yā ayyuhā lladhīna āmanū lā tuḥarrimū ṭayyibāti mā aḥalla llāhu lakum walā taʿtadū ʾinna llāha lā yuḥibbu lmuʿtadīna', 'Ey iman edenler! Allah''ın size helal kıldığı şeyleri haram kılmayın ve haddi aşmayın. Şüphesiz Allah haddi aşanları sevmez.'),
(5, 88, 7, 122, 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 'wa-kulū mimmā razaqakumullāhu ḥalālan ṭayyibā wa-ttaqūllāha alladhī antum bihi muʾminūn', 'Allah''ın size verdiği helal ve temiz rızıkdan yiyin. Ve kendisine iman ettiğiniz Allah''tan korkun.'),
(5, 89, 7, 122, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمْ إِذَا حَلَفْتُمْ وَٱحْفَظُوٓا۟ أَيْمَٰنَكُمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', 'lā yuʾākhidhukumullāhu bil-laghwi fī ʾaymānikum wa-lākin yuʾākhidhukum bimā ʿaqqadtumul-ʾaymāna fa-kafāratuhū ʾiṭʿāmu ʿašarati masākīna min ʾawsaṭi mā tuṭʿimūna ʾahlīkum ʾaw kiswatuhum ʾaw taḥrīru raqabatin fa-man lam yajid fa-ṣiyāmu ṯalāṯati ʾayyāmin ḏālika kafāratu ʾaymānikum ʾiḏā ḥalaftum wa-ḥfaẓō ʾaymānakum kaḏālika yubayyinullāhu lakum ʾāyātihi laʿallakum taškūrun', 'Allah sizi yeminlerinizdeki (hatalarınızdan dolayı) sorumlu tutmaz, ancak kalplerinizle akdettiğiniz (kasem ettiğiniz) yeminlerden dolayı sizi sorumlu tutar. Bunun kefareti, ailelerinize yedirdiğinizin orta hallisinden on miskini doyurmak veya onlara giyim sağlamak yahut bir köle azat etmektir. Kim (bunları) bulamazsa, onun kefareti üç gün oruç tutmaktır. İşte yeminlerinizden döndüğünüz zaman kefareti budur. Yeminlerinize riayet edin. İşte Allah size ayetlerini böyle açıklar, umulur ki şükredersiniz.'),
(5, 90, 7, 123, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 'yā ayyuhā lladhīna āmānū innamā l-khamru wa-l-maysiru wa-l-ʾanṣābu wa-l-ʾazlāmu rijsun min ʿamali sh-shayṭāni fājtinibūhu laʿallakum tufliḥūna', 'Ey iman edenler! Şarap, kumar, dikili taşlar ve fal okları ancak şeytan işi birer pisliktir. Bunlardan kaçının ki kurtuluşa eresiniz.'),
(5, 91, 7, 123, 'إِنَّمَا يُرِيدُ ٱلشَّيْطَٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ فَهَلْ أَنتُم مُّنتَهُونَ', 'innamā yurīdu sh-shayṭānu an yūqiʿa baynakumu l-ʿadāwata wa-l-baghḍāʾa fī l-khamri wa-l-maysiri wa yaṣudakum ʿan dhikri llāhi wa ʿani ṣ-ṣalāti fa hal antum muntahūn', 'Şüphesiz şeytan, içki ve kumarla aranıza düşmanlık ve kin sokmak, sizi Allah''ı anmaktan ve namazdan alıkoymak ister. Artık bunlardan vazgeçiyor musunuz?'),
(5, 92, 7, 123, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'wa ʾaṭīʿū ʾllāha wa ʾaṭīʿū r-rasūla wa ḥḏarū fa ʾin tawallaytum fa ʿlamū ʾa nnāmā ʿalā rasūlinā l-balāġu l-mubīnu', 'Allah''a itaat edin, Peygamber''e itaat edin ve (emirlerimize aykırı hareket etmekten) sakının. Eğer yüz çevirirseniz, bilin ki Peygamberimizin görevi apaçık tebliğden başka bir şey değildir.'),
(5, 93, 7, 123, 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 'laysa ʿalā alladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti junāḥun fīmā ṭaʿimū ʾidhā mā ttaqaw wa ʾāmanū wa ʿamilū ṣ-ṣāliḥāti thumma ttaqaw wa ʾāmanū thumma ttaqaw wa ʾaḥsanū wa-llāhu yuḥibbu l-muḥsinīna', 'İman edip salih amel işleyenler hakkında, (haram olduğu) bildirildikten sonra (helal olan şeylerden) tattıkları takdirde, -eğer takva sahibi olup imanlarını sürdürürler ve salih amel işlemeye devam ederlerse- daha önce tattıklarından dolayı bir günah yoktur. Allah, iyilik edenleri sever.'),
(5, 94, 7, 123, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', 'yā ʾayyuhā llaḏīna ʾāmanū layabluwannakumu llāhu bišayʾim mina ṣ-ṣaydi tanāluhu ʾaydīkum wa rimāḥukum li yaʿlama llāhu man yaḫāfuhu bil-ġaybi faman iʿtadā baʿda ḏālika falahū ʿaḏābun ʾalīmun', 'Ey iman edenler! Allah, sizin ellerinizin ve mızraklarınızın (kolayca) erişebileceği bir av ile sizi mutlaka imtihan edecektir. Kim bundan sonra haddi aşarsa, onun için elem dolu bir azap vardır.'),
(5, 95, 7, 123, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّٰرَةٌ طَعَامُ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ عَفَا ٱللَّهُ عَمَّا سَلَفَ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'yā ʾayyuhā lladhīna ʾāmanū lā taqtulū ṣ-ṣayda wa ʾantum ḥurumun wa man qatalahu min-kum mutaʿammidan fa-jazāʾun mithlu mā qatala mina n-naʿami yaḥkumu bihi dhawā ʿadlin min-kum hadyan bāligha l-kaʿbati ʾaw kaffāratun ṭaʿāmu masākīna ʾaw ʿadlu dhālika ṣiyāman li-yadhūqa wabāla ʾamrihi ʿafā l-lāhu ʿammā salafa wa man ʿāda fa-yantaqimu l-lāhu min-hu wa-llāhu ʿazīzun dhū ʾntiqāmin', 'Ey iman edenler! Siz hacc veya umre için ihramda iken av hayvanı öldürmeyin. Kim içinizden onu kasten öldürürse, cezası, öldürdüğü hayvanın dengi bir kurbanı Kâbe’ye ulaştırmak veya onun keffareti, yoksulları doyurmak yahut onun dengi oruç tutmaktır. Bu, yaptığı işin vebalini tatması içindir. Allah geçmişte olanı affetmiştir. Kim de bunu tekrarlarsa Allah onu cezalandırır. Allah mutlak güç sahibidir, intikam alandır.'),
(5, 96, 7, 124, 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَٰعًا لَّكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'uḥilla lakum ṣaydu l-baḥri wa ṭaʿāmuhu matāʿan lakum wa lis-sayyārati wa ḥurrima ʿalaykum ṣaydu l-barri mā dumtum ḥuruman wa-ttaqū l-lāha lladhī ilayhi tuḥsharūna', 'Deniz avı ve onu yemek size helâl kılındı; hem sizin hem de yolcuların faydalanması için. Kara avı ise, siz hac için ihramda bulunduğunuz müddetçe size haramdır. Allah''tan korkun. O, kendisidir ki, hepiniz O''nun huzurunda toplanacaksınız.'),
(5, 97, 7, 124, 'جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَٰٓئِدَ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'jaʿala ʾallāhu l-kaʿbata l-bayta l-ḥarāma qiyāman li-nnāsi wa-š-šahra l-ḥarāma wa-l-hady wa-l-qalāʾida ḏālika li-taʿlamū ʾanna ʾallāha yaʿlamu mā fī s-samāwāti wa-mā fī l-ʾarḍi wa-ʾanna ʾallāha bi-kulli šayʾin ʿalīmun', 'Allah, Kâbe''yi, o saygıdeğer evi, insanlar için bir (kıyam, yani) dirlik ve selâmet kaynağı yaptı; haram ayı, kurban edilmek üzere gönderilen hediyeleri ve (boyunlarına takılıp hürmet gerektiren) gerdanlıkları da (böyle yaptı). Bunlar, Allah''ın göklerde ve yerde ne varsa bildiğini ve sizin de Allah''ın her şeyi bildiğini bilmeniz içindir. Şüphesiz Allah her şeyi hakkıyla bilendir.'),
(5, 98, 7, 124, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'iʿlamū anna Allāha šadīdu l-ʿiqābi wa anna Allāha ġafūrun raḥīmun', 'Biliniz ki Allah''ın azabı şiddetlidir ve Allah Gafur''dur, Rahîm''dir.'),
(5, 99, 7, 124, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'mā ʿalā r-rasūli illā l-balāġu wa-llāhu yaʿlamu mā tubdūna wa-mā taktūmūna', 'Resulün üzerine düşen sadece tebliğdir. Allah, açığa vurduklarınızı da, gizlediklerinizi de bilir.'),
(5, 100, 7, 124, 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ', 'qul lā yastawī l-khabīthu wa-ṭ-ṭayyibu wa-law aʿjabaka kathratu l-khabīthi fa-ttaqū llāha yā ʾulī l-ʾalbābi laʿallakum tufliḥūna', 'De ki: "Kötü ile iyinin bir olmadığı, pis kokulunun çokluğu hoşuna gitse bile, Allah''tan korkun, ey akıl sahipleri! Umulur ki kurtuluşa erersiniz."'),
(5, 101, 7, 124, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا وَٱللَّهُ غَفُورٌ حَلِيمٌ', 'yā ayyuhā alladhīna āmanū lā tas''alū ʿan ʾashyāʾa ʾin tubda lakum tasuʾkum wa ʾin tas''alū ʿanhā ḥīna yunazzalu l-qurʾānu tubda lakum ʿafā allāhu ʿanhā wa allāhu ghafūrun ḥalīmun', 'Ey iman edenler! Size açıklanırsa hoşunuza gitmeyecek şeyler hakkında soru sormayın. Eğer Kur''an indirilirken sorarsanız, onlar size açıklanır. Allah onları affetmiştir. Allah çok bağışlayıcı, halimdir.'),
(5, 102, 7, 124, 'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ', 'qad saʾalahā qawmun min qablikum thumma aṣbaḥū bihā kāfirīn', 'Andan evvel de kavminiz sormuştu, sonra onunla kafir olmuşlardı.'),
(5, 103, 7, 124, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', 'mā jaʿala llāhu min baḥīratin walā sāʾibatin walā waṣīlatin walā ḥāmin walākinna llaḏīna kafarū yaftarūna ʿalā llāhi l-kaḏiba wa-ʾakṯaruhum lā yaʿqilūn', 'Allah, bahrîre, sâibe, vasîle ve hâm adlarında (putlar veya putlar için ayrılan hayvanlar) hiçbir şey kılmamıştır. Fakat kâfirler, Allah’a yalan uydururlar. Onların çoğu akıllarını kullanmazlar.'),
(5, 104, 7, 125, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', 'wa-ʾidhā qīla lahum taʿālaw ʾilā mā ʾanzala ʾllāhu wa-ʾilā r-rasūli qālū ḥasbunā mā wajadnā ʿalayhi ʾābāʾanā ʾa-wa-law kāna ʾābāʾuhum lā yaʿlamūna šayʾan wa-lā yahtadūna', 'Onlara: "Allah''ın indirdiğine ve Peygamber''e gelin" dendiği zaman, "Babalarımızı üzerinde bulduğumuz yol bize yeter" derler. Ya babaları bir şey bilmiyor ve doğru yolu bulamamış idilerse?'),
(5, 105, 7, 125, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'yāʾayyuhā lladhīna ʾāmanū ʿalaykum ʾanfusakum lā yaḍurrukum man ḍalla idhā htadaytum ʾilā llāhi marjiʿukum jamīʿan fayunabbiʾukum bimā kuntum taʿmalūn', 'Ey iman edenler! Siz kendinize bakın. Siz doğru yolda olduğunuzda, sapıtmış olanlar size zarar vermez. Hepinizin dönüşü Allah''adır. O zaman Allah, size yapmakta olduklarınızı haber verecektir.'),
(5, 106, 7, 125, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ وَلَا نَكْتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْءَاثِمِينَ', 'yā ayyuhā lladhīna āmānū shahādatu baynikum idhā ḥaḍara aḥadakumul mawtu ḥīnal waṣiyyati ithnāni dhawā ʿadlin minkum aw ākharāni min ghayrikum in antum ḍarabtum fīl arḍi faʾaṣābatkum muṣībatu lmawti taḥbisūnahumā mimbʿadi ṣalāti fayuqsimāni billāhi inirtabtum lā nashtarī bihi thamanan walaw kāna dhā qurbā walā naktumu shahādata llāhi innā idhan laminal ʾāthimīna', 'Ey iman edenler! Sizden birinize ölüm gelmek üzere olduğu zaman, vasiyetleşirken içinizden adalet sahibi iki kişi şahit tutmak size farz kılındı. Eğer yeryüzünde yolculuk yaparken başınıza ölüm gelirse ve şahit bulamazsanız, sizden olmayan iki kişiyi şahit tutun. Eğer şüpheye düşerseniz, onları namazdan sonra alıkorsunuz. Böylece Allah''a şöyle yemin ederler: ''Akraba bile olsa, bu yeminimizle hiçbir şeyi satmayız ve Allah''ın şahitliğini gizlemeyiz. Şüphesiz o zaman günahkârlardan oluruz.'''),
(5, 107, 7, 125, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'fa-in ʿuthira ʿalā annahumā istahaqqā ithman fa-ʾākhirāni yaqūmāni maqāmahumā mina alladhīna istahaqqa ʿalayhimu l-ʾawlayāni fa-yuqsimāni bi-llāhi la-šahādatunā ʾaḥaqqu min šahādatihimā wa-mā ʿtadaynā ʾinnā ʾidhan la-mina ẓ-ẓālimīna', 'Eğer o ikisinin (yemin edenlerin) günah işlemeye hak kazanmış oldukları anlaşılırsa, onların yerine, haklarında (günah işlemeye) hak kazanılmış olanlardan iki kişi geçsin. Bu ikisi Allah''a yemin ederek şöyle desinler: ''Yeminimiz, onların yemininden daha doğrudur. Biz haddi aşmadık, yoksa o takdirde zalimlerden oluruz.'''),
(5, 108, 7, 125, 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَٰنٌۢ بَعْدَ أَيْمَٰنِهِمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'dhālika adnā an yaʾtū bi-sh-shahādati ʿalā wajhihā aw yakhāfū an turadda aymānun baʿda aymānihim wa-ttaqū Allāha wa-smʿū wa-Allāhu lā yahdī l-qawma l-fāsiqīn', 'Bu, onların şahitliği gereği gibi getirmelerine veya yeminlerinden sonra (yeni) yeminlerle (gerçeği) gizlemeye kalkışmalarından çekinmelerine daha yakındır. Allah''tan korkun ve dinleyin. Allah fâsıklar topluluğunu doğru yola eriştirmez.'),
(5, 109, 7, 126, 'يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ قَالُوا۟ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 'yawma yajmaʿu ʾllāhu r-rusula fayaqūlu mādhā ʾujibtum qālū lā ʿilma lanā ʾinnaka ʾanta ʿallāmu l-ġuyūbi', 'Allah''ın, peygamberleri bir araya toplayacağı günü hatırla. O zaman onlara şöyle diyecektir: ''Size ne cevap verildi?'' Peygamberler diyecekler ki: ''Hiçbir bilgimiz yok. Şüphesiz ki sen, gaybı hakkıyla bilenisin.'''),
(5, 110, 7, 126, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَإِذْ عَلَّمْتُكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'idh qala allahu ya ''isa ibna maryama udhkur ni''mati ''alayka wa ''ala walidatik idh ayyad''tuka biruhi alqudusi tukallimu alnnaasa fi almaHdi wakahlan wa idh ''allamtuka alkitaba walHikmata waltawrata walinjila wa idh takhluqu mina alttini kahay''ati alttayri bi''idhni fatanfukhu fiha fatakunu tayran bi''idhni watubri''u al''akmaha wal''abraSa bi''idhni wa idh tukhriju almawta bi''idhni wa idh kafaftu bani isra''ila ''anka idh ji''tahum bilbayyinati falaqaalla dhiina kafaruu minhum in haadha illa siHr''un mubiinun', 'Hani Allah şöyle buyurmuştu: "Ey Meryem oğlu İsa! Sana ve annene olan nimetimi hatırla. Hani seni Rûhulkudüs (Cebrail) ile desteklemiştim de bana (Allah''ın izniyle) beşikte iken de, yetişkin iken de insanlarla konuşuyordun. Sana kitabı, hikmeti, Tevrat''ı ve İncil''i öğretmiştim. Hani benim iznimle çamurdan kuş (şekli) yapar, ona üfürürdün de benim iznimle kuş oluverirdi. Yine benim iznimle anadan doğma körleri ve abraş (alacalı hastalığa tutulmuş kimseler)i iyileştirirdin. Hani benim iznimle ölüleri (diriltirdin). Hani İsrailoğullarını senden (sana ilişmekten) men etmiştim; hani onlara apaçık delillerle gelmiştin de onlardan kâfir olanlar: "Bu, apaçık bir sihirden başka bir şey değildir" demişlerdi."'),
(5, 111, 7, 126, 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّۦنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', 'wa-ʾidh ʾawḥaytu ʾilā l-ḥawāriyyīna ʾan ʾāminū biyya wa-bi-rasūlī qālū ʾāmannā wa-šhad bi-ʾannanā muslimūna', 'Hani, o havarilere: "Bana ve Resulüme iman edin" diye vahyettiğimde, onlar: "İman ettik, şahit ol ki biz müslümanlarız" demişlerdi.'),
(5, 112, 7, 126, 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 'iḏ qāla l-ḥawāriyyūna yā ʿīsā bna maryama hal yastaṭīʿu rabbuka ʾan yunazzila ʿalaynā māʾidatan mina s-samāʾi qāla ttaqū l-laha ʾin kuntum muʾminīna', 'Hani Havariler: "Ey Meryem oğlu İsa! Bize gökten bir sofra indirebilir mi Rabbin?" demişlerdi. İsa da: "Eğer inanmışsanız, Allah''tan korkun!" demişti.'),
(5, 113, 7, 126, 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّٰهِدِينَ', 'qālū nurīdu an naʾkula minhā wa-taṭmaʾinna qulūbunā wa-naʿlama anna qad ṣadaqtanā wa-nakūna ʿalayhā mina sh-shāhidīn', 'Dediler ki: "Ondan yiyelim, kalplerimiz tatmin bulsun, senin bize doğru söylediğini bilelim ve ona (bizzat) şahitlik edenlerden olalım."'),
(5, 114, 7, 127, 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', 'qāla ʿīsā bnu maryama allāhumma rabbanā anzil ʿalaynā māʾidatan mina s-samāʾi takūnu lanā ʿīdan li-ʾawwalinā wa-ʾākhirinā wa-ʾāyatan minka wa-rzuqnā wa-ʾanta khayru r-rāziqīna', 'Meryem oğlu İsa şöyle dedi: "Allah''ım! Rabbimiz! Bize gökten bir sofra indir ki, hem bize hem de bizden sonrakilere bir bayram ve Senden bir mucize olsun. Bizi rızıklandır; Sen rızık verenlerin en hayırlısısın."'),
(5, 115, 7, 127, 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', 'qāla allāhu ʾinnī munazziluhā ʿalaykum famam yakufr baʿdu minkum faʾinnī ʾuʿaḏḏibuhu ʿaḏāban lā ʾuʿaḏḏibuhu ʾaḥadam minal-ʿālamīn', 'Allah şöyle buyurdu: "Şüphesiz ben onu sizin üzerinize indireceğim. Ama bundan sonra içinizden kim inkâr ederse, onu âlemlerden hiç kimseyi azaplandırmayacağım şekilde azaplandıracağım."'),
(5, 116, 7, 127, 'وَإِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَٰهَيْنِ مِن دُونِ ٱللَّهِ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 'Ve iz kālallāhu Yā ʿĪsabna Meryeme E ente kulte linnāsi itteḫiẕūnī ve ummiye ilāheyni min dūnillāhi Kāle subḥāneke Mā yekūnu lī en ekūle mā leyse lī biḥakkın İn kuntu kultuhu fekad ʿalimtehu Taʿlemu mā fī nefsī ve lā aʿlemu mā fī nefsike İnneke ente ʿallāmul-ġuyūbi', 'Allah şöyle diyecek: "Ey Meryem oğlu İsa! Sen mi insanlara, ''Beni ve annemi Allah''tan başka iki ilah edinin'' dedin?" İsa da şöyle diyecek: "Seni tenzih ederim! Hakkım olmayan bir şeyi söylemem bana yakışmaz. Eğer onu söylemiş olsaydım, elbette sen onu bilirdin. Sen benim içimdekini bilirsin, ben ise senin içindekini bilmem. Şüphesiz ki sen, gaybları en iyi bilensin."'),
(5, 117, 7, 127, 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'mā qultu lahum illā mā ʾamartani bihi ʾani ʿbudū ʾllāha rabbī wa rabbakum wa kuntu ʿalayhim shahīdan mā dumtu fīhim falammā tawaffaytanī kunta ʾanta ʾr-raqība ʿalayhim wa ʾanta ʿalā kulli shayʾin shahīd', 'Onlara, bana emrettiğin şeyden başkasını söylemedim: ''Rabbim ve Rabbiniz olan Allah''a kulluk edin!'' Onların içinde bulunduğum sürece ben de üzerlerinde şahit idim. Beni vefat ettirince, üzerlerinde gözetleyici sensin. Sen her şeye hakkıyla şahitsin.'),
(5, 118, 7, 127, 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'in tuʿaḏḏibhum fa-ʾinnahum ʿibāduka wa-ʾin taġfir lahum fa-ʾinnaka ʾanta l-ʿazīzu l-ḥakīmu', 'Eğer onları azaplandırırsan, şüphesiz onlar Senin kullarındır. Eğer onları bağışlarsan, şüphesiz Sen, Sen Azîz''sin, Hakîm''sin.'),
(5, 119, 7, 127, 'قَالَ ٱللَّهُ هَٰذَا يَوْمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدْقُهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'qāla llāhu hāḏā yawmu yanfaʿu ṣ-ṣādiqīna ṣidquhum lahum jannātun tajrī min taḥtihā l-ʾanhāru ḵālidīna fīhā ʾabadan raḍiya llāhu ʿanhum wa-raḍū ʿanhu ḏālika l-fawzu l-ʿaẓīmu', 'Allah şöyle buyurdu: "Bu, doğrulara doğruluklarının fayda vereceği gündür. Onlar için, içinden ırmaklar akan, içinde ebediyen kalacakları cennetler vardır. Allah onlardan razı olmuş, onlar da Allah''tan razı olmuşlardır. İşte bu, büyük kurtuluştur."'),
(5, 120, 7, 127, 'لِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ', 'lillāhi mulku s-semāwāti wa-l-arḍi wa mā fīhinna wa huwa ʿalā kulli shayʾin qadīr', 'Göklerin ve yerin ve onların içindekilerin mülkü Allah''ındır. Ve O, her şeye kadirdir.'),
(6, 1, 7, 128, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', 'al-ḥamdu li-llāhi lladhī khalaqa s-samāwāti wa-l-arḍa wa-jaʿala ẓ-ẓulumāti wa-n-nūra thumma lladhīna kafarū bi-rabbihim yaʿdilūn', 'Hamd, gökleri ve yeri yaratan, karanlıkları ve aydınlığı var eden Allah''a mahsustur. (Buna rağmen) kâfirler, Rablerine başkalarını denk tutuyorlar.'),
(6, 2, 7, 128, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا وَأَجَلٌ مُّسَمًّى عِندَهُۥ ثُمَّ أَنتُمْ تَمْتَرُونَ', 'huwa alladhī khalaqakum min ṭīnin thumma qaḍā ajalan wa ajelun musamman ʿindahu thumma antum tamtarūna', 'Sizi topraktan yaratan, sonra da (herkes için) belirli bir ecel tayin eden O’dur. Bir de O’nun katında (başka) bir ecel daha vardır. Sonra siz (yine de) şüphe ediyorsunuz.'),
(6, 3, 7, 128, 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', 'wa huwa allāhu fī s-samāwāti wa fī l-ʾarḍi yaʿlamu sirrakum wa jahrakum wa yaʿlamu mā taksibūna', 'O, göklerde de yerde de Allah''tır. Sizin gizlinizi ve açığa vurduğunuzu bilir. Ve kazanmakta olduğunuzu da bilir.'),
(6, 4, 7, 128, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 'wa mā taʾtīhim min ʾāyatin min ʾāyāti rabbihim ʾillā kānū ʿanhā muʿriḍīn', 'Onlara, Rablerinin ayetlerinden bir ayet gelmez ki, ondan yüz çevirmiş olmasınlar.'),
(6, 5, 7, 128, 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'faqad kadhdhabū bil-ḥaqqi lammā jāʾahum fasawfa yaʾtīhim anbāʾu mā kānū bihi yastahziʾūn', 'Nihayet kendilerine hak geldiğinde onu yalanladılar. Ama alay etmekte oldukları şeyin haberleri onlara birazdan gelecektir.'),
(6, 6, 7, 128, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 'ʾelem yerev-w kem ʾehleknā min ḳablihim min ḳarnin makkennāhum fī l-ʾarḍi mā lem numakkin lekum we-ʾerselnā s-semāʾa ʿaleyhim midrāran we-ǧaʿalnā l-ʾenhāra tecrī min taḥtihim fe-ʾehleknāhum bi-ẕunūbihim we-ʾenšeʾnā min baʿdihim ḳarnan ʾāḫarīn', 'Onlardan önce nice nesilleri helak ettiğimizi görmediler mi? Onları yeryüzünde size vermediğimiz imkanları vermiştik. Gökyüzünden üzerlerine bol bol yağmur indirmiş, altlarından ırmaklar akıtmıştık. Ama günahları yüzünden onları helak ettik ve onlardan sonra başka bir nesil var ettik.'),
(6, 7, 7, 128, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'wa law nazzalnā ʿalayka kitāban fī qarṭāsin fa-lamasūhu bi-aydīhim la-qāla alladhīna kafarū in hādhā illā siḥrun mubīnun', 'Eğer sana (indirdiğimiz) bir kitabı kâğıt içinde (yazılı) olarak indirmiş olsaydık da onlar onu elleriyle dokunmuş olsalardı, kâfir olanlar mutlaka şöyle derlerdi: "Bu, apaçık büyüden başkas ı değildir."'),
(6, 8, 7, 128, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', 'wa qālū lawlā unzila ʿalayhi malak wa law anzalnā malakan laquḍiya l-amr thumma lā yunẓarūn', 'Ve dediler ki: "Ona bir melek indirilmeli değil miydi?" Eğer bir melek indirmiş olsaydık, o zaman iş olup biterdi, sonra da onlara mühlet verilmezdi.'),
(6, 9, 7, 129, 'وَلَوْ جَعَلْنَٰهُ مَلَكًا لَّجَعَلْنَٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', 'wa-law jaʿalnāhu malakan la-jaʿalnāhu rajulan wa-la-labasnā ʿalayhim mā yalbisūn', 'Onu (peygamberi) bir melek yapsaydık, yine de onu (insan suretinde) bir erkek suretinde yapardık ve onları da şüpheye düşürürdük.'),
(6, 10, 7, 129, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'Ve lekad-istuhziʾe bi-rusulin min kablike fe-hâka billazîne sehıru minhum mâ kânû bihî yestehziʾûn', 'Andolsun ki senden önceki nice peygamberlerle de alay edildi de alay ettikleri şey, o alay edenleri kuşatıverdi.'),
(6, 11, 7, 129, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'Qul Sīrū fīl-arḍi Thumma-nẓurū Kayfa kāna ʿāqibatu-l-mukadhdhibīn', 'De ki: Yeryüzünde dolaşın da, peygamberleri yalanlayanların sonunun nasıl olduğuna bir bakın.'),
(6, 12, 7, 129, 'قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُل لِّلَّهِ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'qul liman mā fī s-samāwāti wa-l-arḍi qul li-llāhi kataba ʿalā nafsihi r-raḥmata le-yajmaʿannekum ilā yawmi l-qiyāmati lā rayba fīhi allaḏīna khasirū anfusahum fa-hum lā yuʾminūna', 'De ki: Göklerde ve yerde ne varsa kimindir? De ki: Allah''ındır. Kendi üzerine rahmet yazmıştır. Sizi, hakkında şüphe olmayan kıyamet gününde mutlaka toplayacaktır. Kendilerini ziyana uğratanlar işte onlardır, onlar inanmazlar.'),
(6, 13, 7, 129, 'وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa-lahū mā sakana fī l-layli wa-n-nahāri wa-huwa s-samīʿu l-ʿalīmu', 'Geceleyin ve gündüzün sükûnet bulduğu her şey O''nundur. O, her şeyi işitendir, her şeyi bilendir.'),
(6, 14, 7, 129, 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'qul ʾaġayra llāhi ʾattahiḏu waliyyan fāṭiri s-samāwāti wa-l-ʾarḍi wa-huwa yuṭʿimu wa-lā yuṭʿamu qul ʾinnī ʾumirtu ʾan ʾakūna ʾawwala man ʾaslama wa-lā takūnanna mina l-mušrikīn', 'De ki: "Gökleri ve yeri yoktan var eden, O, (herkesi) yedirdiği halde yedirilmeyen Allah''tan başkasını mı dost edineyim?" De ki: "Şüphesiz ben, (Allah''a) teslim olanların ilki olmakla emrolundum ve sakın müşriklerden olma!"'),
(6, 15, 7, 129, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'qul innī ʾakhāfu ʾin ʿaṣaytu rabbī ʿaḏāba yawmin ʿaẓīm', 'De ki: "Eğer Rabbime isyan edersem, o büyük günün azabından korkarım."'),
(6, 16, 7, 129, 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', 'man yuṣraf ʿanhu yawmaʾiḏin faqad raḥimahu waḏālika l-fawzu l-mubīnu', 'O gün kimden azap savılırsa, gerçekten Allah onu esirgemiş (rahmetine nail etmiş)tir. İşte bu, apaçık kurtuluştur.'),
(6, 17, 7, 129, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wa-ʾin yamsaska-llāhu bi-ḍurrin fa-lā kāšifa lahu ʾillā huwā wa-ʾin yamsaska bi-ḫayrin fa-huwa ʿalā kulli šayʾin qadīrun', 'Eğer Allah sana bir zarar dokundurursa, onu O''ndan başkası gideremez. Eğer sana bir hayır dokundurursa da O her şeye hakkıyla gücü yetendir.'),
(6, 18, 7, 129, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'wa huwa l-qāhiru fawqa ʿibādihi wa huwa l-ḥakīmu l-khabīr', 'O, kullarının üstünde kahredici (mutlak hakim) olandır. O, hikmet sahibi ve her şeyden haberdar olandır.'),
(6, 19, 7, 130, 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَٰدَةً قُلِ ٱللَّهُ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ وَأُوحِىَ إِلَىَّ هَٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ قُل لَّآ أَشْهَدُ قُلْ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'qul ʾayyu šayʾin ʾakbaru šahādatan quli ʾallāhu šahīdun baynī wa-baynakum wa-ʾūḥiya ʾilayya hāḏā l-qurʾānu li-ʾunḏirakum bihī wa-man balaga ʾa-ʾinnakum la-tašhadūna ʾanna maʿa ʾallāhi ʾālihatan ʾuḫrā qul lā ʾašhadu qul ʾinnamā huwa ʾilāhun wāḥidun wa-ʾinnanī barīʾun mimmā tušrikūna', 'De ki: "Şahitlik bakımından hangi şey daha büyüktür?" De ki: "Allah benimle sizin aranızı gözeten şahittir. Bu Kur''an bana, sizi ve ulaştığı herkesi onunla uyarıp korkutmam için vahyolundu. Gerçekten siz, Allah ile beraber başka ilahların da olduğuna mı şahitlik ediyorsunuz?" De ki: "Ben buna şahitlik etmem." De ki: "O, ancak tek bir ilâhtır ve ben sizin ortak koştuğunuz şeylerden uzağım."'),
(6, 20, 7, 130, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'alladhīna ātaynāhumu l-kitāba yaʿrifūnahu kamā yaʿrifūna abnāʾahumu alladhīna khasirū ʾanfusahumu fahum lā yuʾminūna', 'Kendilerine kitap verdiğimiz kimseler, onu (Hz. Muhammed''i), kendi oğullarını tanıdıkları gibi tanırlar. Kendilerini ziyana sokanlar var ya, işte onlar iman etmezler.'),
(6, 21, 7, 130, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'Ve men aẓlamu mimmeni-fterā ʿalā-llāhi kaḏiban au kaḏḏaba bi-ʾāyātihī ʾInnahū lā yufliḥu-ẓẓālimūn', 'Allah''a karşı yalan uyduran veya O''nun âyetlerini yalanlayan kimseden daha zâlim kim olabilir? Şüphesiz zâlimler kurtuluşa ermezler.'),
(6, 22, 7, 130, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'wa yawma naḥshuruhum jamīʿan thumma naqūlu lilladhīna ashrakū ayna shurakāʾukumulladhīna kuntum tazʿumūn', 'Ve o gün onları hep birlikte haşredeceğiz, sonra da şirk koşanlara diyeceğiz ki: ''Ortak koştuklarınız nerede?'''),
(6, 23, 7, 130, 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', 'thumma lam takun fitnatuhum illā an qālū wa-llāhi rabbina mā kunnā mushrikīn', 'Sonra onların (buna karşı) mazeretleri: "Rabbimiz Allah''a yemin olsun ki, biz müşriklerden değildik!" demekten başka bir şey olmadı.'),
(6, 24, 7, 130, 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'unẓur kayfa kaḏabū ʿalā anfusihim wa ḍalla ʿanhum mā kānū yaftarūn', 'Bak, kendi aleyhlerine nasıl da yalan uydurmuşlar! Ve uydurmakta oldukları şeyler onlardan nasıl da kaybolup gitmiştir!'),
(6, 25, 7, 130, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'wa-minhum man yastamiʿu ilayka wa-jaʿalnā ʿalā qulūbihim ʾakinatan ʾan yafqahūhu wa-fī ʾādhānihim waqran wa-ʾin yaraw kulla ʾāyatin lā yuʾminū bihā ḥattā ʾiḏā jāʾūka yujādilūnak yaqūlu ʾallaḏīna kafarū ʾin hāḏā ʾillā ʾasaṭīru l-ʾawwalīn', 'Onlardan sana kulak verenler de vardır. Onu (Kur''an''ı) anlamamaları için kalplerine kablar (örtüler) ve kulaklarına bir ağırlık koyduk. Onlar, her türlü mucizeyi görseler bile yine de ona inanmazlar. Nihayet sana geldiklerinde, o kâfirler şöyle derler: "Bu, evvelkilerin masallarından başkası değildir."'),
(6, 26, 7, 130, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'wa hum yanhavna ʿanhu wa yan''awna ʿanhu wa in yuhlika illa anfusahum wa ma yash''uruna', 'Onlar, hem ondan (Kur''an''dan) yüz çevirirler hem de ondan uzaklaşırlar. Onlar ancak kendilerini helak ederler ve bunun farkında değillerdir.'),
(6, 27, 7, 130, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'wa law tarā idh wuqifū ʿalā n-nār faqālū yālaytanā nuraddu wa lā nukadhdhiba bi-āyāti rabbina wa nakūna mina l-muʾminīn', 'Onlar, ateşin karşısında durduruldukları zamanı bir görsen! O zaman derler ki: "Keşke (dünyaya) geri döndürülsek de Rabbimizin ayetlerini yalanlamasak ve müminlerden olsaydık!"'),
(6, 28, 7, 131, 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'bal badā lahum mā kānū yukhfūna min qablu wa law ruddū la ʿādū limā nuhū ʿanhu wa innahum la kādhibūna', 'Hayır! Daha önce gizlemekte oldukları şeyler onlara (açığa çıkmış) göründü. Eğer döndürülselerdi, nehyolundukları şeye mutlaka dönerlerdi. Şüphesiz onlar yalancıdırlar.'),
(6, 29, 7, 131, 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'wa qālū in hiya illā ḥayātunā ad-dunyā wa mā naḥnu bimabʿūthīna', 'Bir de dediler ki: "Hayat, bizim şu dünya hayatımızdan başkası değildir. Biz tekrar diriltilecek değiliz."'),
(6, 30, 7, 131, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'wa-law tarā ʾidh wuqifū ʿalā rabbihim qāla ʾalaysa hādhā bil-ḥaqqi qālū balā wa-rabbanā qāla fa-dhūqū al-ʿadhāba bimā kuntum takfurūn', 'Onları, Rablerinin huzuruna çıkarıldıkları zaman bir görsen! (Allah) diyecek ki: "Bu (Kur''an''ın bildirdiği azap) hak değil miymiş?" Onlar: "Evet, Rabbimize yemin ederiz ki hakmış!" diyecekler. (Allah) diyecek ki: "İnkâr etmekte olduğunuz azabı tadın!"'),
(6, 31, 7, 131, 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ أَلَا سَآءَ مَا يَزِرُونَ', 'kad ḫasira l-leẕîne keẕẕebû biliḳâi l-lahi ḥattâ iẕâ câet-humu s-sâʿatu baġteten ḳâlû yâ ḥasratenâ ʿalâ mâ ferraṭnâ fîhâ ve hum yaḥmilûne evzârahum ʿalâ żuhûrihim elâ sâe mâ yezirûn', 'Allah''a kavuşmayı yalan sayanlar, hüsrana uğramışlardır. Nihayet kıyamet kendilerine ansızın gelince, “Orada işlediğimiz kusurlardan dolayı vah bize!” derler. Onlar günahlarını sırtlarına yüklenmiş olarak taşırlar. Dikkat edin, ne kötü bir yüktür o taşıdıkları!'),
(6, 32, 7, 131, 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ ٱلْءَاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', 'Ve mâl-hayâtüd-dün-yâ illâ la''ibün ve lehv. Ve led-dârul-âhiratü hayrun lillezîne yettekûn. Efelâ ta''kilûn.', 'Dünya hayatı sadece bir oyun ve eğlenceden ibarettir. Elbette ahiret yurdu, Allah''a karşı gelmekten sakınanlar için daha hayırlıdır. Hâlâ akıl eremiyor musunuz?'),
(6, 33, 7, 131, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 'qad naʿlamu ʾinnahu layahzununka alladhī yaqūlūn fa-ʾinnahum lā yukadhdhibūnaka wa-lākinna ẓ-ẓālimīna bi-ʾāyāti llāhi yajḥadūn', 'Andar olsun ki, onların söylediklerinin seni üzdüğünü biliyoruz. Onlar seni yalanlamıyorlar, fakat o zalimler Allah''ın ayetlerine karşı gelerek inkâr ediyorlar.'),
(6, 34, 7, 131, 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', 'Ve lekad kuzzibet rusulun min kablike fe saberû alâ mâ kuzzibû ve ûzû hattâ etâhum nasrunâ ve lâ mubeddile li kelimâtillâhi ve lekad câeke min nebeil murselîne', 'Andolsun ki, senden önce de nice peygamberler yalanlanmıştı da onlar, yalanlanmalarına ve eziyet görmelerine rağmen sabretmişlerdi; nihayet yardımımız onlara ulaşmıştı. Allah''ın kelimelerini değiştirecek kimse yoktur. Andolsun ki, peygamberlerin haberlerinden bir kısmı sana da gelmiştir.'),
(6, 35, 7, 131, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ', 'wa-ʾin kāna kabura ʿalayka ʾiʿrāḍuhum fa-ʾini-staṭaʿta ʾan tabtaḡiya nafāqan fī-l-ʾarḍi ʾaw sullaman fī-s-samāʾi fa-taʾtiyahum bi-ʾāyatin wa-law šāʾa-llāhu la-jamaʿahum ʿalā-l-hudā fa-lā takūnnanna mina-l-jāhilīn', 'Onların yüz çevirmesi sana ağır geldiyse, eğer (onları ikna edecek) bir delik açmaya veya bir merdivenle göğe yükselmeye gücün yetiyorsa, onlara bir ayet (mucize) getirmeye çalış! Allah dileseydi, elbette onları hidayet üzere toplardı. O halde, (bu konuda) cahillerden olma!'),
(6, 36, 7, 132, 'إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', 'innamā yastajību llaḏīna yasmaʿūn wal-mawtā yabʿaṯuhumu llāhu ṯumma ʾilayhi yurjaʿūn', 'Ancak (davete) icabet edenler, (hakka) kulak verenlerdir. Ölülere gelince, Allah onları (diriltip) kaldıracaktır. Sonra O''na döndürüleceklerdir.'),
(6, 37, 7, 132, 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'wa qālū lawlā nuzzila ʿalayhi ʾāyatun min rabbihī qul ʾinna ʾallāha qādirun ʿalā ʾan yunazzila ʾāyatan walākinna ʾaktharahum lā yaʿlamūn', 'Ve dediler ki: ''Rabbinden ona bir ayet (mucize) indirilmeli değil miydi?'' De ki: ''Şüphesiz Allah bir ayet indirmeye kadirdir; fakat onların çoğu bilmezler.'''),
(6, 38, 7, 132, 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', 'Ve mā min dābbatin fīl-arḍi ve lā ṭāʾirin yaṭīru bi-janāḥayhi illā umemun emthālukum Mā farraṭnā fīl-kitābi min shayʾin Thumma ilā rabbihim yuḥsharūna', 'Yeryüzünde yürüyen hayvanlar ve (ייה) kanatlarıyla uçan kuşlar olmasın ki, sizin gibi ümmetler olmasınlar. Biz Kitap''ta (Levh-i Mahfuz''da) hiçbir şeyi eksik bırakmadık. Bütün bunlar sonunda Rablerinin huzurunda toplanacaklardır.'),
(6, 39, 7, 132, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَٰتِ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa-lladhīna kadhdhabū bi-ʾāyātinā ṣummun wa-bukmun fī ẓ-ẓulumāti man yashaʾi llāhu yuḍlilhu wa-man yashaʾ yajʿalhu ʿalā ṣirāṭin mustaqīmin', 'Ayetlerimizi yalanlayanlar, karanlıklar içinde sağır ve dilsizdirler. Allah kimi dilerse onu saptırır, kimi dilerse onu dosdoğru bir yol üzerine koyar.'),
(6, 40, 7, 132, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ', 'Qul araʾaytakum in ʾatākum ʿadhābu llāhi ʾaw ʾatatkumus-sāʿatu ʾAghayra llāhi tadʿūna in kuntum ṣādiqīn', 'De ki: «Allah''ın azabı veya kıyamet (saati) başınıza gelirse, Allah''tan başkasını mı çağıracaksınız? Eğer doğru sözlüler iseniz (söyleyin).»'),
(6, 41, 7, 132, 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', 'Bal iyyāhu tadʿūn Feyakshifu mā tadʿūna ileyhi in shāʾa Wa tansawna mā tushrikūn', 'Hayır! Ancak O''na dua edersiniz de, dilerse kendisine yalvardığınız şeyi (musibeti) kaldırır ve siz (O''na) şirk koştuğunuz şeyleri unutursunuz.'),
(6, 42, 7, 132, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', 'Ve lekad erselnâ ilâ umemim min kablike feʾaḫaẕnâhum bilbeʾsâʾi veḍḍarrâʾi leʿallehum yeteḍarraʿûn', 'Andolsun ki senden önceki ümmetlere de elçiler gönderdik. Sonra onları, belki yalvarıp yakarırlar diye darlık ve sıkıntı ile yakaladık.'),
(6, 43, 7, 132, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ', 'falawlā idh jāʾahum baʾsunā taḍarraʿū walākin qasat qulūbuhum wazayyana lahumu sh-shayṭānu mā kānū yaʿmalūn', 'Nihayet onlara o şiddetli azabımız geldiğinde, yalvarmaları gerekmez miydi? Fakat kalpleri katılaştı ve şeytan da onlara yapmakta oldukları şeyleri güzel gösterdi.'),
(6, 44, 7, 132, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', 'fe-lemmā nesū mā żukkirū bihī fe-feṭaḥnā ʿalayhim ebvābe kulli şeyʾin ḥattā iḏā fariḥū bimā ūtū eḫaḏnāhum bagteten fe-iḏā hum mublisūn', 'Kendilerine hatırlatılan şeyi unuttuklarında, üzerlerine her şeyin kapılarını açtık. Nihayet kendilerine verilen nimetlerle sevinip şımarınca, onları ansızın yakaladık da bir anda bütün ümitlerini yitirmiş kimseler haline geldiler.'),
(6, 45, 7, 133, 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'faquṭiʿa dābiru l-qawmi lladhīna ẓalamū wa-l-ḥamdu lillāhi rabbi l-ʿālamīn', 'Böylece zulmeden kavmin kökü kesildi. Hamd, âlemlerin Rabbi Allah''a mahsustur.'),
(6, 46, 7, 133, 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ', 'qul ʾaraʾaytum ʾin ʾakhaḏa ʾallāhu samʿakum wa-ʾabṣārakum wa-ḫatama ʿalā qulūbikum man ʾilāhun ġayru ʾallāhi yaʾtīkum bihi ʾunẓur kayfa nuṣarrifu l-ʾāyāti ṯumma hum yaṣdifūna', 'De ki: «Söyleyin bakalım, eğer Allah sizin kulaklarınızı ve gözlerinizi alırsa ve kalplerinizin üzerine mühür basarsa, Allah''tan başka hangi ilah size bunları geri getirebilir? Bak, ayetleri nasıl çeşitli şekillerde açıklıyoruz. Yine de onlar yüz çeviriyorlar.»'),
(6, 47, 7, 133, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ', 'qul ʾaraʾaytakum ʾin ʾatākum ʿadhābu llāhi baghtatan ʾaw jahratan hal yuhlaku ʾillā l-qawmu ẓ-ẓālimūn', 'De ki: ''Hiç düşündünüz mü? Eğer size Allah''ın azabı ansızın veya açıkça gelirse, zalimler topluluğundan başkası mı helak olur?'''),
(6, 48, 7, 133, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 've-mā nursilu l-murselīne illā mubaşşirīne ve-munẕirīn fe-men āmena ve-aṣlaḥa fe-lā ḫawfun ʿaleyhim ve-lā hum yaḥzenūn', 'Biz peygamberleri ancak müjdeleyici ve uyarıcı olarak göndeririz. İman edip durumlarını düzeltenler için hiçbir korku yoktur ve onlar mahzun da olmayacaklardır.'),
(6, 49, 7, 133, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', 'wa-lladhīna kadhdhabū bi-ʾāyātinā yamassuhumu l-ʿadhābu bimā kānū yafsuqūna', 'Ayetlerimizi yalanlayanlara gelince, fasıklık yapmaları yüzünden azap onları saracaktır.'),
(6, 50, 7, 133, 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَفَلَا تَتَفَكَّرُونَ', 'qul lā aqūlu lakum ʿindī khazāʾinu llāhi walā aʿlamu l-ghayba walā aqūlu lakum ʾinnī malak ʾin ʾattabiʿu ʾillā mā yūḥā ʾilayya qul hal yastawī l-ʾaʿmā wal-baṣīr ʾafalā tatafakkarūn', 'De ki: Size, Allah''ın hazineleri benim yanımdadır demiyorum. Ben gaybı da bilmem. Size, ben bir meleğim de demiyorum. Ben sadece bana vahyolunana uyarım. De ki: Kör ile gören bir olur mu? Tefekkür etmez misiniz?'),
(6, 51, 7, 133, 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ', 'wa-anẓir bihi-lladhīna yakhāfūna an yuḥsharū ilā rabbihim laysa lahum min dūnihi waliyyun wa-lā shafīʿun laʿallahum yattaqūna', 'Kendisiyle, Rablerinin huzuruna toplanmaktan korkanları uyar; onların O''ndan başka ne bir dostu ne de bir şefaatçisi vardır. Umulur ki korunurlar.'),
(6, 52, 7, 133, 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', 'wa lā taṭrudi lladhīna yadʿūna rabbahum bil-ghadawāti wal-ʿashiyyi yurīdūna wajhahū mā ʿalayka min ḥisābihim min shayʾin wa mā min ḥisābika ʿalayhim min shayʾin fataṭrudahum fatakūna mina ẓẓālimīn', 'Sabah akşam Rablerine, O''nun rızasını dileyerek dua edenleri sakın kovma! Onların hesabından sana bir şey, senin hesabından da onlara bir şey düşmez. Eğer sen onları kovarsan, o zaman zalimlerden olursun.'),
(6, 53, 7, 134, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ', 'wa kadhalika fatanna ba''dahum bi ba''din li yaqooloo a ha''ulaa''i manna allahu ''alayhim mim bayninaa alaysa allahu bi a''lama bish-shaakireen', 'İşte böylece, kimini kimimizle denedik ki, (bu yüzden kâfirler şöyle) desinler: ''Allah, aramızdan bunlara mı lütufta bulundu?'' Allah, şükredenleri daha iyi bilen değil midir?'),
(6, 54, 7, 134, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ', 'wa ʾidhā jāʾaka lladhīna yuʾminūna bi-ʾāyātinā faqul salāmun ʿalaykum kataba rabbukum ʿalā nafsihi r-raḥmata ʾannahu man ʿamila minkum sūʾan bi-jahālatin thumma tāba min baʿdihi wa-ʾaṣlaḥa fa-ʾannahu ghafūrun raḥīm', 'Ayetlerimize iman edenler sana geldiği zaman, onlara de ki: "Selâm olsun size! Rabbiniz kendi üzerine merhamet yazdı. Öyle ki, sizden kim cahillikle bir kötülük işler, sonra ardından tevbe eder ve kendini ıslah ederse, şüphesiz ki O, çok bağışlayıcı, çok merhamet edicidir."'),
(6, 55, 7, 134, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', 'wa kadhalika nufaṣṣilu l-ʾāyāti wa li-tastabīna sabīlu l-mujrimīna', 'İşte bu şekilde ayetleri açıklıyoruz ki, suçluların yolu (uyanık) görünsün.'),
(6, 56, 7, 134, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', 'qul innī nuhītu ʾan ʾaʿbuda lladhīna tadʿūna min dūni l-lāhi qul lā ʾattabiʿu ʾahwāʾakum qad ḍalaltu ʾidhan wa mā ʾanā mina l-muhtadīna', 'De ki: "Ben, sizin Allah''tan başka taptıklarınıza kulluk etmekten men olundum." De ki: "Sizin arzularınıza uymam. (Eğer uyarsam) o takdirde ben sapmış olurum ve doğru yolu bulanlardan olmam."'),
(6, 57, 7, 134, 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ يَقُصُّ ٱلْحَقَّ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ', 'qul innī ʿalā bayyinatin mir rabbī wa kadhadhdhtum bihī mā ʿindī mā tastaʿcilūna bihī ini alḥukmu illā lillāh yaquṣṣu alḥaqqa wa huwa khayru al-fāṣilīn', 'De ki: "Ben Rabbimden (gelen) açık bir delil üzereyim. Sizin ise onu yalanladığınızı bana bildirdiniz. Sizin çarçabuk gelmesini istediğiniz şey (azap) benim yanımda değil. Hüküm ancak Allah''a aittir. O, hakkı anlatır ve O, en hayırlı hüküm verenlerin en hayırlısıdır."'),
(6, 58, 7, 134, 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ', 'Qul law anna ʿindī mā tastaʿcilūna bihī Laquḍiya l-amru baynī wa-baynakum Wa-llāhu aʿlamu biẓ-ẓālimīn', 'De ki: Eğer sizin acele etmekte olduğunuz şey (azap) yanımda olsaydı, elbette benimle sizin aranızda iş bitirilmiş olurdu. Allah, zalimleri daha iyi bilir.'),
(6, 59, 7, 134, 'وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'wa ʿindahu mafātiḥu l-ghaybi lā yaʿlamuhā ʾillā huwa wa yaʿlamu mā fī l-barri wa l-baḥri wa mā tasquṭu min waraqatin ʾillā yaʿlamuhā wa lā ḥabbatin fī ẓulumāti l-ʾarḍi wa lā raṭbin wa lā yābisin ʾillā fī kitābin mubīnin', 'Gaybın anahtarları O''nun yanındadır. Onları ancak O bilir. O, karada ve denizde ne varsa bilir. Hiçbir yaprak düşmez ki O bilmesin. Ne karanlıkta bir tane, ne de yaş ve kuru hiçbir şey vardır ki apaçık bir kitapta (Levh-i Mahfuz''da) olmasın.'),
(6, 60, 7, 135, 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'wa huwa alladhī yatawaffākum bil-layli wa yaʿlamu mā jaraḥtum bin-nahār thumma yabʿathukum fīhi liyūqḍā ajālun musammá thumma ilayhi marjiʿukum thumma yunabbiʾukum bimā kuntum taʿmalūn', 'Geceleyin sizi vefat ettiren (öldüren) ve gündüzleyin neler kazandığınızı bilen O''dur. Sonra, belirlenmiş bir süreye kadar (hayat bulmanız) için sizi gündüzleyin tekrar diriltir. Sonra dönüşünüz O''nadır. Sonra O, yaptıklarınızı size haber verecektir.'),
(6, 61, 7, 135, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 'wa-huwa l-qāhiru fawqa ʿibādihi wa-yursilu ʿalaykum ḥafaẓatan ḥattā ʾiḏā jāʾa ʾaḥadakum ul-mawt tawaffathu rusulunā wa-hum lā yufarriṭūn', 'O, kullarının üstünde kahredici (galip) olandır. Ve üzerinize koruyucular gönderir. Nihayet sizden birine ölüm geldiği vakit, (onun) elçilerimiz (olan melekler) canını alır. Onlar (elçilerimiz) görevlerinde kusur etmezler.'),
(6, 62, 7, 135, 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ', 'thumma ruddū ilā Allāhi mawlāhumu l-ḥaqqi alā lahu l-ḥukmu wa-huwa asraʿu l-ḥāsibīna', 'Sonra onlar, kendilerinin gerçek mevlâsı olan Allah''a döndürüldüler. Dikkat edin, hüküm O''nundur ve O, hesap soranların en süratlisidir.'),
(6, 63, 7, 135, 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'Qul man yunaccīkum min ẓulumāti l-barri wa-l-baḥri Tadʿūnahū taḍarruʿan wa-khufyatan La-in anjānā min hādhihi la-nakūnanna mina sh-shākirīn', 'De ki: "Karada ve denizde sizi kim kurtarır? Kendisine alçak sesle, gizlice yalvarırsınız. Andolsun ki, eğer bizi bundan kurtarırsa, elbette şükredenlerden oluruz diye dua edersiniz."'),
(6, 64, 7, 135, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ', 'qulillāhu yunaccikum minhā wa min kulli karbin thumma antum tuşrikūn', 'De ki: "Sizi bunlardan ve her türlü sıkıntıdan Allah kurtarır, sonra da siz (O''na) ortak koşarsınız."'),
(6, 65, 7, 135, 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ', 'Qul huwa l-qādiru ʿalā ʾan yabʿatha ʿalaykum ʿadhāban min fawqikum ʾaw min taḥti ʾarjulikum ʾaw yalbisakum shiyaʿan wa-yudhīqa baʿḍakum baʾsa baʿḍin ʾunẓur kayfa nuṣarrifu l-ʾāyāti laʿallahum yafqahūn', 'De ki: "O, size üstünüzden veya altınızdan bir azap göndermeye ya da sizi topluluklara ayırıp birbirinizin hışmını tattırmaya kadirdir." Bak, biz ayetleri nasıl çeşitli şekillerde açıklıyoruz ki, belki anlarlar.'),
(6, 66, 7, 135, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ', 'wa kadhdhaba bihi qawmuka wa huwa l-ḥaqqu qul lastu ʿalaykum bi-wakīlin', 'Kavmin onu yalanladı. Halbuki o, haktır. De ki: Ben sizin üzerinize bir vekil değilim.'),
(6, 67, 7, 135, 'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ', 'likulli nabaʾin mustaqarrun wa sawfa taʿlamūn', 'Herhangi bir haber için bir gerçekleşme zamanı vardır. Yakında siz de bileceksiniz.'),
(6, 68, 7, 135, 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'wa-idhā raʾayta lladhīna yakhūḍūna fī ʾāyātinā fa-ʾaʿriḍ ʿanhum ḥattā yakhūḍū fī ḥadīthin ghayrihī wa-immā yūnsiyannaka sh-shayṭānu falā taqʿud baʿda dh-dhikrā maʿa l-qawmi ẓ-ẓālimīn', 'Ayetlerimiz hakkında ileri geri konuşanları gördüğünde, onlar başka bir söze dalıncaya kadar onlardan yüz çevir. Eğer şeytan sana unutturursa, hatırladıktan sonra o zalim kimselerle oturma.'),
(6, 69, 7, 136, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', 've mā ʿalā ʾlladhīna yattaqūna min ḥisābihim min shayʾin ve lākin dhikrá laʿallahum yattaqūna', 'Onları sakınanlardan bir şey sorulmaz. Fakat yine de (onlara) öğüt vermek gerekir ki, sakınabilsinler.'),
(6, 70, 7, 136, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'wa dhari allatheena ittakhathoo deenahum la''iban wa lahwan wa gharrathumu alhayatu al-dunya wa dhakkir bihi an tubsala nafsum bima kasabat laysa laha min dooni Allahi waliyyun wa la shafee''un wa in ta''dil kulla ''adlin la yu''khath minha ula''ika allatheena ubsiloo bima kasaboo lahum sharabun min hameemin wa ''adhabun aleemun bima kanoo yakfuroon', 'Onları (hak dine girmekten alıkoyanları) ve dinlerini bir eğlence ve oyun edinenleri bırak. Dünya hayatı onları aldatmıştır. (Bununla birlikte) hiçbir kimse kazandığı şey yüzünden (ateşe) atılmayacak değildir. Kendisi için Allah''tan başka ne bir dost ne de bir şefaatçi vardır. Eğer o, bütün fidye teklif etse, ondan (bu fidye) kabul edilmez. İşte onlar, kazandıkları yüzünden (ateşe) atılmış olanlardır. Küfretmekte oldukları şeylerden dolayı onlar için kaynar su ve elem dolu bir azap vardır.'),
(6, 71, 7, 136, 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'qul anadʿū min dūni llāhi mā lā yanfaʿunā walā yaḍurrunā wanuraddu ʿalā ʾaʿqābinā baʿda ʾiḏ hadānā llāhu kallaḏī stahwat''hu ʾš-šayāṭīnu fī l-ʾarḍi ḥayrāna lahu ʾaṣḥābun yadʿūnahu ʾilā l-hudā ʾtinā qul ʾinna hudā llāhi huwa l-hudā wa ʾumirnā linuslima lirabbi l-ʿālamīn', 'De ki: "Allah''ı bırakıp da bize fayda sağlamayan ve zarar vermeyen şeylere mi tapalım? Ve Allah bizi doğru yola ilettikten sonra, şeytanların yeryüzünde şaşkın bırakıp, kendisini doğru yola çağıran arkadaşları olduğu halde, topuklarımızın üzerine geri mi dönelim? De ki: "Şüphesiz doğru yol, Allah''ın (gösterdiği) yoldur. Ve bize, âlemlerin Rabb''ine teslim olmamız emrolundu."'),
(6, 72, 7, 136, 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'wa an aqīmū aṣ-ṣalāta wa-ttaqūhu wa-huwa alladhī ilayhi tuḥsharūn', 'Bir de namazı dosdoğru kılın ve O''ndan korkup O''na karşı gelmekten sakının. Ve O, kendisidir ki, O''na toplanıp getirileceksiniz.'),
(6, 73, 7, 136, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَيَوْمَ يَقُولُ كُن فَيَكُونُ قَوْلُهُ ٱلْحَقُّ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'wa-huwa alladhī khalaqa al-samāwāti wa-al-arḍa bi-al-ḥaqqi wa-yawma yaqūlu kun fa-yakūnu qawluhu al-ḥaqqu wa-lahu al-mulku yawma yunfakhu fī al-ṣūri ʿālimu al-ghaybi wa-al-shahādati wa-huwa al-ḥakīmu al-khabīru', 'O, gökleri ve yeri hak olarak yaratan (ve) "Ol!" dediği gün her şey oluveren (ve) buyruğu haktır. Sûr''a üflendiği gün mülk O''nundur. O, gaybı ve şehadeti bilendir. O, Hikmet Sahibi''dir, (her şeyden) Haberdar''dır.'),
(6, 74, 7, 137, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍ مُّبِينٍ', 'wa-ʾidh qāla ʾibrāhīmu li-ʾabīhi ʾāzara ʾatat-takhidhu ʾaṣnāman ʾālihata ʾinnī ʾarāka wa-qawmaka fī ḍalālin mubīnin', 'Hani İbrahim babasına Âzer’e demişti ki: “Putları tanrılar mı ediniyorsun? Şüphesiz ben seni ve kavmini apaçık bir sapıklık içinde görüyorum.”'),
(6, 75, 7, 137, 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', 'wa kaḏālika nurī ibrāhīma malakūta s-samāwāti wa-l-arḍi wa-liyakūna mina l-mūqinīn', 'Böylece İbrahim''e göklerin ve yerin melekûtunu (mülk ve saltanatını) gösteriyor ve (bu sayede) kesin bilgiye erenlerden olmasını sağlıyorduk.'),
(6, 76, 7, 137, 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْءَافِلِينَ', 'fe lemmā cenne ʿaleyhi l-ley-lu raʾā kevke-ben qāla hāḏā rabbī fe lemmā efe-le qāla lā uḥibbu l-ʾāfi-līn', 'Üzerine gece basınca, bir yıldız görmüş ve "Bu benim Rabbimdir" demişti. Yıldız batınca da "Ben batanları sevmem" demişti.'),
(6, 77, 7, 137, 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', 'Fe lemmā ra''ā l-qamara bāziġan qāla hāḏā rabbī Fe lemmā afla qāla le''in lem yahdinī rabbī le''akūnenna min al-qawmi aḍ-ḍāllīn', 'Ay''ı doğarken görünce, "İşte bu benim Rabbimdir" dedi. Ay batınca da, "Andolsun ki, Rabbim bana doğru yolu göstermeseydi, mutlaka sapkın kavimden olurdum" dedi.'),
(6, 78, 7, 137, 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'fe lemmā raʾā-š-šemse bāziġaten ḳāle hāḏā rabbī hāḏā akbaru fe lemmā efelēt ḳāle yā ḳavmi innī berīʾum mimmā tušrikūn', 'Güneşi doğarken görünce, "İşte bu benim Rabbimdir! Bu daha büyük." dedi. Tam batınca da, "Ey kavmim! Ben sizin ortak koştuğunuz şeylerden uzağım." dedi.'),
(6, 79, 7, 137, 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 'innī wajjahtu wajhiya lilladhī faṭara s-samāwāti wa-l-arḍa ḥanīfan wa mā anā mina l-mushrikīn', 'Ben, hakka yönelen birisi olarak yüzümü, gökleri ve yeri yoktan var edene çevirdim. Ben müşriklerden değilim.'),
(6, 80, 7, 137, 'وَحَآجَّهُۥ قَوْمُهُۥ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ', 'waḥājjahu qawmuhu qāla ʾatuḥājjūnnī fī llāhi waqad hadānī walā ʾakhāfu mā tušrikūna bihi ʾillā ʾan yašāʾa rabbī šayʾan wasiʿa rabbī kulla šayʾin ʿilman ʾafalā tataḏakkarūna', 'Kavmi onunla mücadeleye girişince dedi ki: ''Allah hakkında benimle mücadele mi ediyorsunuz? Oysa O, bana yol gösterdi. Sizin O''na ortak koşmakta olduklarınızdan korkmam ben. Ancak Rabbim''in dilediği bir şey olursa, o başka. Rabbimin ilmi her şeyi kuşatmıştır. Hâlâ düşünmez misiniz?'''),
(6, 81, 7, 137, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًا فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ', 'wa kayfa ʾakhāfu mā ʾashraktum walā takhāfūna ʾannakum ʾashraktum billāhi mā lam yunazzil bihi ʿalaykum sulṭānan fa ʾayyu l-farīqayni ʾaḥaqqu bil-ʾamni ʾin kuntum taʿlamūna', 'Siz O''nu bırakıp da sizin hiçbir delil indirmediği şeyleri O''na ortak koşmanızdan dolayı ben sizin taptıklarınızdan korkar mıyım? Eğer (gerçeği) biliyorsanız, korkuya hangisi daha lâyıktır?'),
(6, 82, 7, 138, 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', 'elleẕîne âmenû ve lem yelbisû îmânehum biẓulmin ülâike lehumu-l''emnu ve hum muhtedûn', 'İman edenler ve imanlarına herhangi bir zulüm karıştırmayanlar var ya, işte güvenlik onlarındır ve onlar doğru yolu bulanlardır.'),
(6, 83, 7, 138, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', 'wa tilka ḥujjatunā ātaynāhā ibrāhīma ʿalā qawmihī narfaʿu darajātin man nashāʾu ʾinna rabbaka ḥakīmun ʿalīmun', 'İşte bu, kavmine karşı İbrahim''e verdiğimiz delilimizdir. Biz dilediklerimizi derecelerle yükseltiriz. Şüphesiz Rabbin hikmet sahibidir, hakkıyla bilendir.'),
(6, 84, 7, 138, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِن قَبْلُ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'wa wahabnā lahu ʾisḥāqa wa yaʿqūba kullan hadaynā wa nūḥan hadaynā min qablu wa min dhurriyyatihi dāwūda wa sulaymāna wa ʾayyūba wa yūsufa wa mūsā wa hārūna wa kaḏālika najzī lmuḥsinīna', 'Ona İshak''ı ve (torunu) Yakub''u bahşettik; her birini doğru yola ilettik. Daha önce de Nuh''u doğru yola iletmiştik. Onun soyundan da Davud''u, Süleyman''ı, Eyyub''u, Yusuf''u, Musa''yı ve Harun''u (doğru yola iletmiştik). İşte biz, iyilik yapanları böyle mükafatlandırırız.'),
(6, 85, 7, 138, 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ كُلٌّ مِّنَ ٱلصَّٰلِحِينَ', 'wa zakariyyā wa yaḥyā wa ʿīsā wa ilyās kullun mina ṣ-ṣāliḥīn', 'Zekeriya, Yahya, İsa ve İlyas da (salihlerden idi). Hepsi de iyilerden idi.'),
(6, 86, 7, 138, 'وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ', 'wa-ʾismāʿīla wa-l-yasaʿa wa-yūnuṣa wa-lūṭan wa-kullan faḍḍalnā ʿalā l-ʿālamīn', 'İsmail''i, Elyesa''yı, Yunus''u ve Lut''u da (hidayete erdirdik). Hepsini âlemlere üstün kıldık.'),
(6, 87, 7, 138, 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa-min ʾābāʾihim wa-dhurriyyātihim wa-ʾikhwānihim wa-jtabaynāhum wa-hadaynāhum ʾilā ṣirāṭin mustaqīm', 'Onların atalarından, zürriyetlerinden ve kardeşlerinden de (peygamberler seçtik). Onları (diğer insanlar arasından) seçtik ve dosdoğru yola ilettik.'),
(6, 88, 7, 138, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', 'dhālika hudā llāhi yahdī bihi man yashāʾu min ʿibādihī wa-law ashrakū la-ḥabiṭa ʿanhum mā kānū yaʿmalūn', 'İşte bu, Allah''ın hidayetidir. Kullarından dilediğini ona iletir. Eğer onlar ortak koşsalardı, elbette yaptıkları bütün amelleri boşa giderdi.'),
(6, 89, 7, 138, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ', 'ʾulāʾika lladhīna ʾātaynāhumu lkitāba walḥukma wannubūwata fāʾin yakfur bihā hāʾulāʾi fāqad wakkalna bihā qawman laysū bihā bikāfirīna', 'İşte bunlar, kendilerine kitap, hükümranlık ve peygamberlik verdiğimiz kimselerdir. Eğer bunları (bu nimetleri) inkâr ederlerse, o zaman biz de onlara karşı bunları inkâr etmeyecek bir toplumu görevlendiririz.'),
(6, 90, 7, 138, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ فَبِهُدَىٰهُمُ ٱقْتَدِهْ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ', 'ʾūlāʾike l-ladhīna hadā llāhu fabihudāhumu ʾqtedeh qul lā ʾasʾalukum ʿalayhi ʾajran ʾin huwa ʾillā dhikrā lil-ʿālamīn', 'İşte bunlar, Allah''ın hidayete erdirdiği kimselerdir. (Resûlüm!) Sen de onların bu hidayetine uy. (Onlara) de ki: Ben bunun için sizden bir ücret istemiyorum. Bu (Kur''an), âlemler için bir öğütten başka bir şey değildir.'),
(6, 91, 7, 139, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ ٱللَّهُ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', 'wa mā qadarū allāha ḥaqqa qadrihī ʾiḏ qālū mā ʾanzaala allāhu ʿalā bašarin min šayʾin qul man ʾanzaala l-kitāba l-laḏī jāʾa bihī mūsā nūran wa-hudan li-nnāsi tajʿalūnahū qarāṭīsa tubdūnahā wa-tukhfūna kaṯīran wa ʿullimtum mā lam taʿlamū ʾantum wa-lā ʾābāʾukum quli allāhu ṯumma ḏarhum fī ḵawḍihim yalʿabūna', 'Onlar, Allah''ın kadrini hakkıyla takdir edemediler. Hani onlar, "Allah hiçbir beşere bir şey indirmemiştir" demişlerdi. De ki: "Musa''nın insanlara bir nur ve hidayet olmak üzere getirdiği, sizin de (parça parça) yazıp, (bir kısmını) açıkladığınız ve çoğunu gizlediğiniz Kitabı kim indirdi? Hem sizin ve atalarınızın bilmediği şeyleri O (Allah) öğretmiştir." De ki: "Allah''tır." Sonra da onları, içinde ''oynadıkları'' (batıl) derinliklerine bırak.'),
(6, 92, 7, 139, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْءَاخِرَةِ يُؤْمِنُونَ بِهِۦ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'wa hāḏā kitābun anzalnāhu mubārakun muṣaddiqu l-laḏī bayna yadayhi wa li-tunḏira umma l-qurā wa man ḥawlahā wa l-laḏīna yuʾminūna bi-l-ʾāḵirati yuʾminūna bihi wa hum ʿalā ṣalātihim yuḥāfiẓūna', 'İşte bu (Kur''an), bizim indirdiğimiz, mübarek, kendinden öncekileri tasdik eden bir kitaptır. (Bununla) anaların anası olan Mekke''yi ve çevresindekileri uyarmanı ve ahirete inananların ona inanmalarını ve onların namazlarına dikkat etmelerini emrediyoruz. Onlar, namazlarını muhafaza ederler.'),
(6, 93, 7, 139, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ', 'wa man aẓlamu mimmani-ftara ʿala-llāhi kaḏiban aw qāla ūḥiya ilayya wa lam yūḥa ilayhi šayʾun wa man qāla saʾunzilu miṯla mā ʾanzala-llāhu wa law tarā ʾiḏi-ẓẓālimūna fī ġamarāti-lmawti wa-lmalāʾikatu bāsiṭū ʾaydiyahum ʾaḫriǧū ʾanfusakum al-yawma tuǧzawna ʿaḏāba-lhūni bimā kuntum taqūlūna ʿala-llāhi ġayra-lḥaqqi wa kuntum ʿan ʾāyātihi tastaʾbirūna', 'Allah''a karşı yalan uyduran veya kendisine hiçbir şey vahyedilmediği halde, "Bana da vahiy geldi" diyen ya da "Allah''ın indirdiği âyetlerin bir benzerini ben de indireceğim" diyenden daha zalim kim olabilir? O zalimler ölümün dehşetli anlarında, melekler de onlara ellerini uzatmışken, "Ruhlarınızı teslim edin! Bugün Allah''a karşı haksız şeyler söylemenizden ve O''nun âyetlerine kibirlenerek yüz çevirmenizden dolayı horlayan bir azapla cezalandırılacaksınız" (dediklerinde) hallerini bir görsen!'),
(6, 94, 7, 139, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', 'wa laqad ji''tumūnā furādā kamā khalaqnākum awwala marrah wa taraktum mā khawwaltumūkum warāʾa ẓuhūrikum wa mā narā maʿakum shufʿāʾakumul-ladhīna zaʿamtum annahum fīkum shurakāʾu laqad taqaṭṭaʿa baynakum wa ḍalla ʿankum mā kuntum tazʿumūn', 'Ve sizi ilk defa yarattığımız haliniz gibi bize tek başınıza geldiniz ve size verdiğimiz şeyleri arkanıza attınız. Ve sizin, aranızda ortaklar olduğunu zannettiğiniz şefaatçilerinizi yanınızda görmüyoruz. Yemin olsun ki, aranızdaki bağlar kesildi ve zannettiğiniz şeyler sizden kayboldu.'),
(6, 95, 7, 140, 'إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ذَٰلِكُمُ ٱللَّهُ فَأَنَّىٰ تُؤْفَكُونَ', 'ʾinna llāha fāliqa l-ḥabbi wa-n-nawā yukhriju l-ḥayya mina l-mayyiti wa-mukhriju l-mayyiti mina l-ḥayyi dhālikumu llāhu fa-ʾannā tuʾfakūna', 'Şüphesiz Allah, daneyi ve çekirdeği yaran (filizlendiren), ölüden diri çıkarandır ve diriden de ölü çıkarandır. İşte Allah budur. Nasıl da (hakka) çevriliyorsunuz?'),
(6, 96, 7, 140, 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'fāliqu l-iṣbāḥi wa-jaʿala l-layla sakanan wa-sh-shamsa wa-l-qamara ḥusbānan dhālika taqdīru l-ʿazīzi l-ʿalīmi', 'Sabahı yarıp (yaratan) O''dur. Geceyi dinlenme (vakti), güneşi ve ayı (vakitleri) hesaplama (vesilesi) kıldı. İşte bu, aziz ve alîm olan Allah''ın takdiridir.'),
(6, 97, 7, 140, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍ يَعْلَمُونَ', 'wa huwa alladhī jaʿala lakumu n-nujūma li-tah-tadū bihā fī ẓulumāti l-barri wa-l-baḥri qad faṣṣalnā l-ʾāyāti li-qawmin yaʿlamūn', 'O, sizin için yıldızları karada ve denizde (yolunuzu bulmak üzere) birer alâmet olarak yaratandır. Gerçekten biz, (hakikati) bilen bir kavim için âyetleri (hükümlerimizi) iyice açıkladık.'),
(6, 98, 7, 140, 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍ يَفْقَهُونَ', 'wa huwa alladhī ʾanshaʾakum min nafsin wāḥidatin famustaqarrun wamustawdaʿun qad faṣṣalnā al-ʾāyāti liqawmin yafqahūna', 'Ve O, sizi tek bir nefisten yaratıp var eden, sizin için bir karar (karargâh) ve bir emanet (konulma yeri) belirleyendir. Anlayan bir topluluk için âyetleri ayrı ayrı açıklamışızdır.'),
(6, 99, 7, 140, 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَٰبِهٍ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ إِنَّ فِى ذَٰلِكُمْ لَءَايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'wa huwa alladhī ʾanzala mina s-samāʾi māʾan fa ʾakhrajnā bihi nabāta kulli shayʾin fa ʾakhrajnā minhu khaḍiran nukhriju minhu ḥabban mutarākibān wa mina n-nakhli min ṭalʿihā qinwānun dāniyatun wa jannātin min ʾaʿnābin wa z-zaytūna wa r-rummāna mushtabihan wa ghayra mutashābihin ʾunẓurū ʾilā thamaruhā ʾidhā ʾathmara wa yanʿihī ʾinna fī dhālikum la ʾāyātin li qawmin yuʾminūna', 'O, gökten bir su indirendir. Biz onunla her şeyin bitkisini bitirip çıkardık. O bitkiden de yeşil ve birbirine girmiş başaklar çıkarırız. Ve hurmadan; tomurcuklarından sarkan salkımlar, birbirine benzeyen ve benzemeyen üzümler, zeytinler ve narlar çıkarırız. Meyveye durduğu ve olgunlaştığı zaman meyvesine bakın. Şüphesiz bunlarda iman eden bir topluluk için elbette deliller vardır.'),
(6, 100, 7, 140, 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', 'Ve ceʿalū lillāhi şurakāʾa l-cinne ve ḫalaqahum ve ḫaraqū lehu benīne ve benātīm biġayri ʿilmin Subḥānehu ve teʿālā ʿammā yaṣifūn', 'Halbuki O, sizin için yarattığı şeylerden (bir kısmını) putlara, (bir kısmını da) Allah''a ortak koştular. Oysa O, yarattığı şeylerin hepsini yaratmıştır. O''nu, onların isnat ettikleri sıfatlardan tenzih eder ve yüceltirim.'),
(6, 101, 7, 140, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌ وَخَلَقَ كُلَّ شَىْءٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'badiʿu s-semāwāti wa-l-ʾarḍi ʾannā yakūnu lahū waladun wa-lam takun lahū ṣāḥibatun wa-khalaqa kulla shayin wa-huwa bikulli shayin ʿalīmun', 'O, gökleri ve yeri örneksiz yaratandır. O''nun bir eşi olmadığı halde nasıl çocuğu olabilir? Halbuki O, her şeyi yaratmış ve her şeyi hakkıyla bilendir.'),
(6, 102, 7, 141, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَآ إِلَٰهَ إِلَّا هُوَ خَٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'dhālikumullāhu rabbukum lā ilāha illā huwā khāliqu kulli shayʾin faʿbudūhu wa huwā ʿalā kulli shayʾin wakīlun', 'İşte bu, sizin Rabbiniz Allah''tır. O''ndan başka hiçbir ilâh yoktur. Her şeyin yaratıcısı O''dur. O halde O''na kulluk edin. O, her şey üzerine vekildir.'),
(6, 103, 7, 141, 'لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'lā tudrikuhu l-ʾabsāru wa-huwa yudriku l-ʾabsāra wa-huwa l-laṭīfu l-khabīru', 'Gözler O''nu idrak edemez. O ise gözleri idrak eder. O, latif ve habîrdir.'),
(6, 104, 7, 141, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ وَمَنْ عَمِىَ فَعَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', 'qad jāʾakum baṣāʾiru mir rabbikum faman abṣara faliṉfsihi waman ʿamiyya faʿalayhā wamā ʾanā ʿalaykum biḥafīẓin', 'Andolsun ki size Rabbinizden apaçık deliller gelmiştir. Artık kim bunları görürse kendi lehine, kim de kör olursa kendi aleyhinedir. Ben üzerinize bir bekçi değilim.'),
(6, 105, 7, 141, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ', 'wa kaḏālika nuṣarrifu l-ʾāyāti wa liyqūlū darasta wa li nubayyinahu li qawmin yaʿlamūna', 'İşte böylece âyetleri çeşitli şekillerde açıklıyoruz ki, onlar (bu açıklamalar karşısında) "Sen (bu Kur''an''ı) okuyup öğrendin" desinler ve (bir de) bilebilen bir topluluğa (bu Kur''an''ı) açıklayalım diye.'),
(6, 106, 7, 141, 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ لَآ إِلَٰهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'ittabi'' mâ ûḥiye ileyke min rabbike lâ ilâhe illâ huve ve a''riḍ ''ani''l-muşrikîn', 'Rabbinden sana vahyolunana uy! O''ndan başka ilâh yoktur. Ve müşriklere aldırış etme!'),
(6, 107, 7, 141, 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'wa law shāʾa ʾallāhu mā ʾashrakū wa mā jaʿalnāka ʿalayhim ḥafīẓan wa mā ʾanta ʿalayhim bi-wakīlin', 'Allah dileseydi, onlar ortak koşmazlardı. Seni de onlara bir koruyucu yapmadık. Sen onlara vekil de değilsin.'),
(6, 108, 7, 141, 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'wa lā tasubbū alladhīna yadʿūna min dūni llāhi fa yasubbū llāha ʿadwan bi ghayri ʿilmin kadhālika zayyanā li kulli ummatin ʿamalahum thumma ilā rabbihim marjiʿuhum fa yunabbiʾuhum bimā kānū yaʿmalūna', 'Allah''tan başka yalvardıklarına sövmeyin; sonra onlar da bilgisizlik ve düşmanlık yüzünden Allah''a söverler. Böylece her ümmetin işini çekici kıldık. Sonra dönüşleri Rabb''lerinedir. O zaman onlara yapmakta olduklarını haber verecektir.'),
(6, 109, 7, 141, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا قُلْ إِنَّمَا ٱلْءَايَٰتُ عِندَ ٱللَّهِ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', 'wa-aqsamū bi-llāhi jahda aymānihim la-in jāʾathum āyatun la-yuʾminunna bihā qul innamā l-āyātu ʿinda llāhi wa-mā yushʿirukum annahā ʾidhā jāʾat lā yuʾminūn', 'Onlar, bütün güçleriyle Allah''a yemin etmişlerdi ki, kendilerine bir ayet (mucize) gelse, mutlaka ona inanacaklardı. De ki: "Ayetler ancak Allah katındandır." Onlar (ayetler) geldiği zaman da inanmayacaklarını size ne bildirecek?'),
(6, 110, 7, 141, 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'wa nuqallibu af''idatahum wa abṣārahum kamā lam yu''minū bihi awwala marrah wa nadharuhum fī ṭughyānihim yaʿmahūn', 'Onların kalplerini ve gözlerini, ilk defa inanmadıkları gibi (yine) çeviririz ve onları kendi azgınlıkları içinde şaşkın bir halde bırakırız.'),
(6, 111, 8, 142, 'وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', 'Velev enna nezzelna ileyhimul melaikeh Ve kellemahul mevta Ve haşerna aleyhim kulle şey''in kubula Maa kanu li yu''minu İlla en yeşa''allahu Ve lakinne ekserahum yechhelun', 'Onlara melekleri indirseydik, ölüler onlarla konuşsaydı ve her şeyi karşılarına toplayıp bir araya getirseydik, Allah dilemedikçe yine de inanmayacaklardı. Fakat çokları bunu bilmezler.'),
(6, 112, 8, 142, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'wa kaḏālika ǧaʿalnā li-kulli nabiyyin ʿaduwwan šayāṭīna l-ʾinsi wal-ǧinni yūḥī baʿḍuhum ʾilā baʿḍin zuḫrufa l-qawli ġurūran wa law šāʾa rabbuka mā faʿalūhu fa-ḏarhum wa mā yaftarūna', 'Böylece biz her peygamber için insanlardan ve cinlerden şeytanları düşman kıldık. Onların bir kısmı, diğerlerini aldatmak için süslü sözler fısıldarlar. Rabbin dileseydi onlar bunu yapamazlardı. Artık onları, uydurdukları şeylerle baş başa bırak.'),
(6, 113, 8, 142, 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', 'wa litasġā ilayhi af''idatu alladhīna lā yu''minūna bil''ākhirati wa liyarḍawhu wa liyaqtarifū mā hum muqtariifūna', 'Böylece, ahirete inanmayanların kalpleri ona (Kur''an''a) meyledip onu (ondan razı olmayı) ve böylece işlemekte oldukları (günahları) işlemeyi tercih etsinler.'),
(6, 114, 8, 142, 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًا وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'ʾafaghayra ʾallāhi ʾabtahī ḥakaman wahuwa ʾalladhī ʾanzala ʾilaykumu lkitāba mufaṣṣalan walladhīna ʾātaynāhumu lkitāba yaʿlamūna ʾannahu munazzalun min rabbika bilḥaqqi falā takūnanna mina lmumtarīna', 'Allah''tan başka bir hakem mi arayayım? Halbuki O, size Kitab''ı (Kur''an''ı) ayrıntılı olarak indirmiştir. Kendilerine verdiğimiz Kitap''takiler, onun Rabbinden hak olarak indirildiğini bilirler. Öyleyse sakın şüpheye düşenlerden olma!'),
(6, 115, 8, 142, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa tammat kalimatu rabbika sidqan wa ''adlan la mubaddila likalimatihi wa huwa as-samii''u al-''aliim', 'Rabbinin sözü hem doğruluk hem de adalet bakımından tamamlanmıştır. O''nun sözlerini değiştirecek hiçbir şey yoktur. O, her şeyi duyan, her şeyi bilendir.'),
(6, 116, 8, 142, 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'wa-ʾin tuṭiʿ ʾakthara man fī l-ʾarḍi yuḍillūka ʿan sabīli llāh ʾin yattabiʿūna ʾillā ẓ-ẓanna wa-ʾin hum ʾillā yakhruṣūna', 'Yeryüzündekilerin çoğuna uyacak olursan, seni Allah''ın yolundan saptırırlar. Onlar ancak zanna uyarlar ve onlar sadece yalan söylerler.'),
(6, 117, 8, 142, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ʾinna rabbaka huwa ʾaʿlamu man yaḍillu ʿan sabīlihī wa huwa ʾaʿlamu bil-muhtadīn', 'Şüphesiz Rabbin, kendi yolundan sapanları en iyi bilendir ve O, doğru yolu bulanları da en iyi bilendir.'),
(6, 118, 8, 142, 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ', 'fe kulū mimmā żukira-smullāhi ʿalayhi in kuntum bi-ʾāyātihi muʾminīn', 'O halde, âyetlerine iman edenlerdenseniz, üzerine Allah''ın adı anılan şeylerden yiyin.'),
(6, 119, 8, 143, 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', 've mâ lekum ellâ teʾkulû mim mâ żukira-smullāhi ʿaleyhi ve kad feṣṣale lekum mâ ḥarrema ʿaleykum illâ mâ-ḍṭurirtum ileyhi ve inne keśîran leyuḍillûne bi-ehvâʾihim bi-ġayri ʿilmin inne rabbeke huve aʿlemu bil-muʿtedîn', 'Üzerine Allah''ın adı anılarak kesilen hayvanlardan yememeniz için size ne oluyor da, -zorlanmadıkça- haram kıldıklarını size tek tek açıklamışken yemiyorsunuz? Şüphesiz ki çoğu, bilgisizce kendi arzularına uyarak saptırırlar. Şüphesiz Rabbin, haddi aşanları en iyi bilendir.'),
(6, 120, 8, 143, 'وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', 'wa dharū ẓāhira l-ithmi wa bāṭinahū inna lladhīna yaksibūna l-ithma sayujzawna bimā kānū yaqtarifūna', 'Açık ve gizli günahları bırakın. Şüphesiz günah kazananlar, kazanmakta oldukları yüzünden cezalandırılacaklardır.'),
(6, 121, 8, 143, 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', 'wa lā taʾkulū mimmā lam yuḏkari ʾismu ʾallāhi ʿalayhi wa ʾinnahu lafisuq wa ʾinna ʾaš-šayāṭīna layūḥūna ʾilā ʾawliyāʾihim liyujādilūkum wa ʾin ʾaṭaʿtumūhum ʾinnakum lamušrikūn', 'Üzerine Allah''ın adı anılmamış olan şeylerden yemeyin. Şüphesiz bu (yapmak) fısk (yoldan çıkmak)tır. Şeytanlar kendi dostlarına, sizinle tartışmaları için telkinlerde bulunurlar. Eğer onlara uyarsanız, şüphesiz siz de müşrik olursunuz.'),
(6, 122, 8, 143, 'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'a-wa man kāna maytan faʾaḥyaynāhu wa jaʿalnā lahu nūran yamshī bihi fī n-nāsi kaman mathaluhu fī ẓ-ẓulumāti laysa bi-khārijin minhā kadhālika zuyyina lil-kāfirīna mā kānū yaʿmalūn', 'Ölü iken diriltip, kendisine insanlar arasında yürüyebileceği bir nur verdiğimiz kimse, karanlıklar içinde kalıp ondan çıkamayan kimse gibi olur mi? İşte böylece kâfirlere yapmakta oldukları şeyler süslü gösterildi.'),
(6, 123, 8, 143, 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', 'wa kaḏālika ǧaʿalnā fī kulli qaryatin ʾakābira muǧrimīhā liyamkurū fīhā wa mā yamkurūna ʾillā bi-ʾanfusihim wa mā yašʿurūn', 'İşte böylece her şehirde, orada hile yapmaları için suçlularının büyüklerini (ileri gelenlerini) getirdik. Oysa onlar ancak kendilerine hile yaparlar ve bunun farkında değiller.'),
(6, 124, 8, 143, 'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', 'wa ʾidhā jāʾathum ʾāyatun qālū lan nuʾmina ḥattā nuʾtā mithla mā ʾūtiya rusulu ʾllāhi ʾllāhu ʾaʿlamu ḥaythu yajʿalu risālatahu sayūṣību ʾlladhīna ʾajramū ṣaghārun ʿinda ʾllāhi wa ʿadhābun shadīdun bimā kānū yamkurūn', 'Onlara bir ayet geldiğinde, "Allah''ın elçilerine verilenin bir benzeri bize de verilmedikçe inanmayız" derler. Allah, elçiliğini nereye vereceğini daha iyi bilir. Suçlu günahkarlara, tuzak kurmuş olmalarından dolayı Allah katında bir alçaklık ve şiddetli bir azap isabet edecektir.'),
(6, 125, 8, 144, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', 'fe-men yuridillâhu en yehdiyehu yeşraḥ ṣadrahu lil-islâmi ve-men yurid en yuḍillehu yecʿal ṣadrahu ḍeyyiḳan ḥaracen ke-ennemâ yaṣṣaʿʿadu fi-s-semâʾi ke-ḏâlike yecʿalu-llâhu-r-rics aʿlâ-lleẕîne lâ yuʾminûn', 'Allah kime hidayet etmek (doğru yolu göstermek) isterse, onun göğsünü İslâm''a açar. Kimi de saptırmak isterse, onun göğsünü dar ve sıkıntılı hale getirir. Öyle ki, (o kimse) göğe yükseliyormuş gibi hisseder. İşte Allah, inanmayanların üzerine pisliği (veya azabı) böylece koyar.'),
(6, 126, 8, 144, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍ يَذَّكَّرُونَ', 'wa hādhā ṣirāṭu rabbika mustaqīman qad faṣṣalnā l-ʾāyāti liqawmin yadhakkarūn', 'İşte bu, Rabbinin dosdoğru yoludur. Biz, öğüt alıp düşünecek bir kavim için ayetleri (böyle) açıkladık.'),
(6, 127, 8, 144, 'لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'lahum dāru s-selāmi ʿinda rabbihim wa huwa waliyyuhum bimā kānū yaʿmalūn', 'Rableri katında, onlar için ''dâru''s-selâm'' (esenlik yurdu) vardır. Yapmış olduklarından dolayı O, onların velisidir (dostu ve koruyucusudur).'),
(6, 128, 8, 144, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', 'wa-yawma yaḥshuruhum jamīʿan yā-maʿshara l-jinni qadi stakthartum mina l-ʾinsi wa-qāla ʾawliyāʾuhum mina l-ʾinsi rabbanā istamtaʿa baʿḍunā bi-baʿḍin wa-balaghnā ʾajalana lladhī ʾajjalta lanā qāla n-nāru mathwākum khālidīna fīhā ʾillā mā shāʾa ʾllāhu ʾinna rabbaka ḥakīmun ʿalīmun', 'Onları hep birlikte haşredeceği o gün şöyle diyecektir: "Ey cin topluluğu! İnsanlardan çoğunu (yolunuza) saptırdınız." İnsanlardan olan dostları ise diyecekler ki: "Rabbimiz! Birbirimizden yararlandık ve bize takdir ettiğin sürenin sonuna ulaştık." Allah buyuracak: "Ateş sizin barınağınızdır, orada Allah''ın dilediği müstesna, sürekli kalacaksınız. Şüphesiz Rabbin hikmet sahibidir, her şeyi bilendir."'),
(6, 129, 8, 144, 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'wa kaḏālika nuwallī baʿḍa ẓ-ẓālimīna baʿḍan bimā kānū yaksibūn', 'Ve işte böylece, kazanmakta oldukları şeylerden dolayı zalimlerin bir kısmını diğer bir kısmına dost yaparız.'),
(6, 130, 8, 144, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 'Yā maʿšara l-jinni wa-l-ʾinsi ʾAlem yaʾtikum rusulun minkum yaquṣṣūna ʿalaykum ʾāyātī wa-yunḏirūnakum liqāʾa yawmikum hāḏā Qālū šahidnā ʿalā ʾanfusinā wa-ġarrathumu l-ḥayātu d-dunyā wa-šahidū ʿalā ʾanfusihim ʾannahum kānū kāfirīn', 'Ey cin ve insan topluluğu! Size kendi içinizden ayetlerimi anlatacak ve bu gününüzle sizi uyaracak peygamberler gelmedi mi? "Kendi aleyhimize şahitlik ederiz" diyecekler. Dünya hayatı onları aldattı ve kâfir olduklarına dair kendi aleyhlerine şahitlik ettiler.'),
(6, 131, 8, 144, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَٰفِلُونَ', 'dhālika an lam yakun rabbuka muhlika l-qurā biẓulmin wa-ahluhā gāfilūn', 'Bu böyledir, çünkü Rabbin, halkı gafil (habersiz) iken zulüm ile şehirleri helak edici değildir.'),
(6, 132, 8, 145, 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'wa likullin darajātun mimmā ʿamilū wa mā rabbuka biġāfilin ʿammā yaʿmalūn', 'Herkesin yaptıklarından dolayı dereceleri vardır. Rabbin, onların yapmakta olduklarından gafil değildir.'),
(6, 133, 8, 145, 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', 'wa rabbuka l-ḡaniyyu ḏū r-raḥmah ʾin yašaʾ yuḏhibkum wa yastaḵlif min baʿdikum mā yašaʾu kamā ʾanšaʾakum min ḏurriyyati qawmin ʾāḵarīn', 'Senin Rabbin, zengin ve merhamet sahibidir. Dilerse sizi yok eder ve dilediği kimseleri sizin yerinize getirir. Tıpkı sizi başka bir kavmin soyundan (yeni bir nesil olarak) meydana getirdiği gibi.'),
(6, 134, 8, 145, 'إِنَّ مَا تُوعَدُونَ لَءَاتٍ وَمَآ أَنتُم بِمُعْجِزِينَ', 'inna mā tūʿadūna laʾātin wa mā ʾantum bimuʿjizīn', 'Şüphesiz size vaadedilen (azap veya mükâfat) mutlaka gelecektir ve siz (O''ndan) kaçıp kurtulamazsınız.'),
(6, 135, 8, 145, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'qul yā qawmi ʿmalū ʿalā makāntikum ʾinnī ʿāmilun fasawfa taʿlamūna man takūnu lahu ʿāqibatu d-dāri ʾinnahu lā yufliḥu ẓ-ẓālimūna', 'De ki: "Ey kavmim! Durumunuz ne ise ona göre yapmaya devam edin; ben de kendi durumuma göre yapacağım. Yurdun (güzel) sonunun kimin olacağını yakında bileceksiniz. Şüphesiz zalimler kurtuluşa ermezler."'),
(6, 136, 8, 145, 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ', 've ce''alū lillāhi mimmā zera''a mine-l-ḥarṡi ve-l-en''āmi naṣībâ feḳālū hāẕā lillāhi biza''mihim vehāẕā lişürakāinā femā kāne lişürakāihim felā yeṣilü ile-llâh vemā kāne lillâhi fehüve yeṣilü ilâ şürakāihim sâe mā yaḥkümûn', 'Kendi zanlarınca, Allah''ın yarattığı ekin ve hayvanlardan O''na bir pay ayırdılar da “Bu Allah''a aittir” dediler, “Bu da ortaklarımıza.” Ortaklarına ait olan Allah''a ulaşmaz, Allah''a ait olan ise ortaklarına ulaşır. Ne kötü hüküm veriyorlar!'),
(6, 137, 8, 145, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'wa kaḏālika zayyana li-kaṯīrin mina l-mušrikīna qatla awlādihim šurakāʾuhum li-yurdūhum wa li-yalbisū ʿalayhim dīnahum wa law šāʾa ḷḷāhu mā faʿalūhu fa-ḏarhum wa mā yaftarūna', 'Böylece, ortakları olan müşriklerin çoğuna, evlatlarını öldürmeyi güzel gösterdik ki, hem onları helak etsinler hem de dinlerini karıştırıp şüpheye düşürsünler. Rabbin dileseydi bunu yapamazlardı. Artık onları, uydurdukları şeylerle baş başa bırak.'),
(6, 138, 8, 146, 'وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', 'wa qālū hādhihi ʾanʿāmun wa ḥarthun ḥijrun lā yaṭʿamuhā ʾillā man nashāʾu bizʿumihim wa ʾanʿāmun ḥurrimat ẓuhūruhā wa ʾanʿāmun lā yadhkurūna ʾis-ma l-lāhi ʿalayhā ʾiftirāʾan ʿalayhi sayajzīhim bimā kānū yaftarūna', 'Dediler ki: "Bu hayvanlar ve ekinler dokunulmazdır. Onları sadece dilediğimiz kimseler yiyebilir!" (Yine) dediler ki: "Şu hayvanların sırtlarına binmek yasaktır." Bir de (onlar hakkında) Allah''ın adını anmadan kestikleri (hayvanlar) vardır. (Bütün bunları) Allah''a iftira etmek için uydurdular. Allah, uydurdukları yüzünden onları cezalandıracaktır.'),
(6, 139, 8, 146, 'وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', 'wa qālū mā fī buṭūni hādhihi l-anʿāmi khāliṣatun li-dhukūrinā wa muḥarramun ʿalā azwājina wa in yakun maytatan fahum fīhi shurakāʾu sayajzīhim waṣfahum ʾinnahu ḥakīmun ʿalīmun', 'Dediler ki: "Bu hayvanların karınlarındaki (yavru) bizim erkeklerimize özgüdür, kadınlarımıza ise haramdır." Eğer (yavru) ölü doğarsa, o zaman onlar bu hususta (erkekler ve kadınlar) ortaktırlar. Allah onların bu vasıflandırmalarının cezasını verecektir. Şüphesiz O, hükümrandır, (her şeyi) bilendir.'),
(6, 140, 8, 146, 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', 'qad khasira alladhīna qatalū ʾawlādahum safahan bighayri ʿilmin waḥarramū mā razaqahumu allāhu ʾiftirāʾan ʿalā allāhi qad ḍallū wamā kānū muhtadīna', 'Gerçekten de, çocuklarını bilgisizce ve Allah''a iftira ederek kasten öldürenler ziyana uğramışlardır. Allah''ın kendilerine verdiği rızkı haram kıldılar. Şüphesiz ki onlar sapmışlardır ve doğru yolda değillerdir.'),
(6, 141, 8, 146, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍ مَّعْرُوشَٰتٍ وَغَيْرَ مَعْرُوشَٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًا وَغَيْرَ مُتَشَٰبِهٍ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'wa huwa alladhī anshaʾa jannātin maʿrūshātin wa ghayra maʿrūshātin wa n-nakhla wa z-zarʿa mukhtalifan ukuluhu wa z-zaytūna wa r-rummāna mutashābihan wa ghayra mutashābihin kulū min thamarhi ʾidhā ʾathmara wa ʾātū ḥaqqahu yawma ḥaṣādihi wa lā tusrifū ʾinnahu lā yuḥibbu l-musrifīn', 'O, çardaklı ve çardaksız üzümleri, çeşit çeşit meyveleri, hurmaları, ekinleri birbirine benzeyen ve benzemeyen zeytin ve narları yaratan O''dur. Meyve verdiği zaman meyvesinden yiyin, hasat günü de hakkını verin ve israf etmeyin. Çünkü O, israf edenleri sevmez.'),
(6, 142, 8, 146, 'وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةً وَفَرْشًا كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 've minel-en''āmi ḥamūleten ve ferşan kulū mimmā razaqakumullāhu ve lā tettebi''ū khuṭuvātish-sheyṭāni innehuu lekum ''aduvvum mubīnun', 'O deve ve sığır gibi hayvanlardan yük taşıyanları ve (yününden, sütünden faydalanılan) kırkları da yaratan O''dur. Allah''ın size verdiği rızıklardan yiyin ve şeytanın adımlarını takip etmeyin. Şüphesiz o, sizin için apaçık bir düşmandır.'),
(6, 143, 8, 147, 'ثَمَٰنِيَةَ أَزْوَٰجٍ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'thamāniyata azwājin mina ḍ-ḍaʾni ʾithnayni wa mina l-maʿzi ʾithnayni qul ʾa-dh-dhakareyni ḥarrama ʾami l-ʾunthayayni ʾammā ʾištamalat ʿalayhi ʾarḥāmu l-ʾunthayayni nabbiʾūnī bi-ʿilmin ʾin kuntum ṣādiqīna', 'Sekiz çift olarak koyunlardan iki, keçilerden de iki. (Erkekleri mi, dişileri mi, yoksa iki dişinin rahimlerinin kapsadığı mı size haram kılındı?) De ki: ''Bunları size Allah mı haram kıldı, yoksa Allah''a yalan uyduruyorsunuz?'''),
(6, 144, 8, 147, 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'wa mina l-ibili ithnayn wa mina l-baqari ithnayn qul a dh-dhakarayni harrama am al-unthayayn amma ishtamalat ''alayhi arhamu l-unthayayn am kuntum shuhadaa''a idh wassakumu l-lahu bihatha fa man azhlamu mimmani ftara ''ala l-lahi kadhiban liyudilla n-nasa bighayri ''ilmin inna l-laha la yahdi l-qawma zh-zhalimina', 'Develerden iki, sığırlardan iki (erkek ve dişi çift olarak). De ki: ''İki erkeği mi haram kıldı, yoksa iki dişiyi mi, yahut iki dişinin rahimlerinde bulunan yavruları mı? Yoksa Allah bunları size vasiyet ederken siz şahitler miydiniz?'' Allah''a karşı yalan uydurarak, bilgisizce insanları saptıranlardan daha zalim kim olabilir? Şüphesiz Allah, zalimler topluluğunu doğru yola eriştirmez.'),
(6, 145, 8, 147, 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ', 'qul lā ajidu fī mā ūḥiya ilayya muḥarraman ʿalā ṭāʿimin yaṭʿamuhū illā an yakūna maytatan aw daman masfūḥan aw laḥma khinzīrin fa-innahu ricsun aw fisqan uhilla li-ġayri llāhi bihī fa-mani ḍṭurra ġayra bāġin wa-lā ʿādin fa-inna rabbaka ġafūrun raḥīmun', 'De ki: "Bana vahyolunanlar içinde, bir kimsenin yiyebileceği herhangi bir şey haram kılınmış bulmuyorum; ancak (leş) bir hayvan, yahut akıtılmış kan, yahut da domuz eti – ki bu murdardır – yahut Allah''tan başkası adına kesilmiş bir hayvan (müstesna). Ama kim çaresiz kalırsa, (haramlıkta) taşkınlık yapmamak ve zaruret hududunu aşmamak şartıyla (yiyebilir). Şüphesiz Rabbin çok bağışlayıcı, çok merhamet edicidir."'),
(6, 146, 8, 147, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ وَإِنَّا لَصَٰدِقُونَ', 'wa ʿalā alladhīna hādū ḥarramnā kulla dhī ẓufurin wa mina l-baqari wa l-ghanami ḥarramnā ʿalayhim shuhūmahumā illā mā ḥamalat ẓuhūruhumā awi l-ḥawāyā aw mā ikhtalaṭa biʿaẓmin dhālika jazaynāhum bibaghyihim wa innā laṣādiqūna', 'Yahudilere de tırnaklı (pençeli) olan her hayvanı haram kıldık. Onlara sığır ve koyunun da yağlarını haram ettik. Ancak, sırtlarında taşıdıkları veya bağırsaklarında bulunan veya kemiğe karışmış olanları müstesna. Bu, onlara taşkınlıkları yüzünden verdiğimiz cezadır. Şüphesiz biz doğru söyleyenleriz.'),
(6, 147, 8, 148, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 'fa-in kadhdhabūka fa-qul rabbukum dhū raḥmatin wāsiʿatin wa-lā yuraddu baʾsuhū ʿani l-qawmi l-mujrimīn', 'Eğer seni yalanlarlarsa, de ki: "Rabbiniz, engin rahmet sahibi olan (bir Rab''dır). Ancak O''nun azabı da suçlu-günahkâr topluluktan geri çevrilmez."'),
(6, 148, 8, 148, 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', 'sa-yaqūlu alladhīna ashrakū law shāʾa allāhu mā ashrak''nā wa-lā ābāʾunā wa-lā ḥarram''nā min shayʾin kadhālika kadhthaba alladhīna min qablihim ḥattā dhāqū baʾsanā qul hal ʿindakum min ʿilmin fa-tukhrjūhu lanā in tattabiʿūna illā al-ẓanna wa-in antum illā takhruṣūna', 'Allah''a ortak koşanlar diyecekler ki: "Allah dileseydi biz de atalarımız da O''na ortak koşmazdık ve hiçbir şeyi haram kılmazdık." Onlardan öncekiler de böyle yalanlamışlardı, sonunda azabımızı tattılar. De ki: "Yanınızda bize açıklayacağınız bir ilim var mı? Siz ancak zanna uyuyorsunuz ve siz ancak yalan söylüyorsunuz."'),
(6, 149, 8, 148, 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 'qul fa-lil-lāhi l-ḥujjatu l-bālighatu fa-law shāʾa la-hadākum ʾajmaʿīna', 'De ki: "En üstün delil Allah''ındır. Eğer O dileseydi, hepinizi hidayete erdirirdi."'),
(6, 150, 8, 148, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', 'qul halumma shuhadāʾakumul-ladhīna yashhadūna anna Allāha ḥarrama hādhā fa-in shahidū falā tashhad maʿahum walā tattabiʿ ahwāʾal-ladhīna kadhdhabū bi-āyātinā wal-ladhīna lā yuʾminūna bil-ʾākhirati wa hum bi-rabbihim yaʿdilūn', 'De ki: "Şahitlerinizi getirin!" Allah''ın haram kıldığına şahitlik edenler kimlerdir? Eğer onlar şahitlik ederlerse, sen onlarla birlikte şahitlik etme. Bizim ayetlerimizi yalanlayanların ve ahirete inanmayanların, Rablerine denk tuttuklarının hevalarına uyma.'),
(6, 151, 8, 148, 'قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 'qul taʿālaw ʾatlu mā ḥarrama rabbukum ʿalaykum ʾallā tušrikū bihi šayʾan wa bil-wālidayni ʾiḥsānan wa lā taqtulū ʾawlādakum min ʾimlāqin naḥnu narzuqukum wa ʾiyyāhum wa lā taqrabū l-fawāḥiša mā ẓahara minhā wa mā baṭana wa lā taqtulū n-nafsa llatī ḥarrama ʾllāhu ʾillā bil-ḥaqqi ḏālikum waṣṣākum bihi laʿallakum taʿqilūn', 'De ki: "Gelin, Rabbinizin size haram kıldığı şeyleri okuyayım: O''na hiçbir şeyi ortak koşmayın; anne babaya iyilik edin; çocuklarınızı geçimsizlik (fakirlik) endişesiyle öldürmeyin. Sizi de onları da biz rızıklandırırız. Zinaya yaklaşmayın; çünkü o, çirkin bir iştir ve çok kötüdür. Allah''ın haram kıldığı cana haksız yere kıymayın. İşte size bunları emrediyor ki, aklınızı kullanasınız."'),
(6, 152, 8, 149, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', 'wa-lā taqrabū mal-al-yetīmi illā bi-llatī hiya aḥsanu ḥattā yablugha ʾashuddahu wa-ʾawfū al-kayla wa-l-mīzāna bi-l-qisṭi lā nukallifu nafsan illā wusʿahā wa-iḏā qultum fa-ʿdilū wa-law kāna ḏā qurbā wa-bi-ʿahdi llāhi ʾawfū ḏālikum waṣṣākum bihi laʿallakum taḏakkarūn', 'Yetimin malına, (onu) en güzel bir biçimde koruyacakları müstesna, yaklaşmayın. Ve (kıyamet gününde) ölçüyü ve tartıyı adaletle tam yapın. Biz hiçbir nefse gücünün yeteceğinden başkasını yüklemeyiz. Ve konuştuğunuz zaman, (yakınlarınız da olsa) adil olun. Ve Allah''a verdiğiniz sözü tutun. İşte Allah, iyice hatırlayasınız diye size bunları emretti.'),
(6, 153, 8, 149, 'وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', 'wa anna hādhā ṣirāṭī mustaqīman fattabiʿūhu walā tattabiʿū as-subula fatafarraqa bikum ʿan sabīlihī dhālikum waṣṣākum bihī laʿallakum tattaqūn', 'Ve şüphe yok ki bu benim dosdoğru yolumdur; artık ona uyun ve öteki yollara uymayın ki sizi O''nun yolundan ayırmasın. İşte sakınmanız için size bunları tavsiye etti.'),
(6, 154, 8, 149, 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', 'thumma ātaynā Mūsā al-kitāba tamāman ʿalā alladhī ʾaḥsana wa tafṣīlan likulli shayʾin wa hudan wa raḥmah laʿallahum biliqāʾi rabbihim yuʾminūn', 'Sonra, iyilik yapanlara bir nimet olarak ve her şeyi ayrı ayrı açıklamak, bir hidayet ve bir rahmet olmak üzere, Musa''ya o Kitab''ı tamamladık ki, Rablerine kavuşacaklarına inanırlar.'),
(6, 155, 8, 149, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 'wa hādhā kitābun anzalnāhu mubārakun fāttabīʿūhu wāttqū laʿallakum turḥamūn', 'İşte bu, bizim indirdiğimiz mübarek bir kitaptır. Ona uyun ve Allah''tan korkup emirlerine uyun ki, merhamet olunasınız.'),
(6, 156, 8, 149, 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', 'ʾan taqūlū ʾinnāmā ʾunzilla l-kitābu ʿalā ṭāʾifateyni min qablinā wa-ʾin kunnā ʿan dirāsatihim la-ḡāfilīn', 'Size, "Kitap ancak bizden önceki iki topluluğa indirildi, biz onların okuduklarından habersiz idik" demeyesiniz diye (böyle yaptık).'),
(6, 157, 8, 149, 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', 'aw taqūlū law annā unzila ʿalaynā l-kitābu lakunnā ahdā minhum faqad jāʾakum bayyinatun mir rabbikum wa-hudan wa-raḥmah faman aẓlamu mimman kaḏḏaba bi-ʾāyāti llāhi wa-ṣadafa ʿanhā sanajzī l-laḏīna yaṣdifūna ʿan ʾāyātinā sūʾa l-ʿaḏābi bimā kānū yaṣdifūn', 'Yahut: “Eğer bize kitap indirilseydi, onlardan daha doğru yolda olurduk” demeyesiniz. İşte size Rabbinizden açık bir delil, bir hidayet ve bir rahmet gelmiştir. Allah’ın âyetlerini yalan sayıp onlardan yüz çevirenlerden daha zalim kim olabilir? Ayetlerimizden yüz çevirenleri, bu yüz çevirmeleri yüzünden azabın en kötüsüyle cezalandıracağız.'),
(6, 158, 8, 150, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًا قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 'hal yanẓurūna illā an taʾtiyahumu l-malāʾikatu aw yaʾtiya rabbuka aw yaʾtiya baʿḍu ʾāyāti rabbika yawma yaʾtī baʿḍu ʾāyāti rabbika lā yanfaʿu nafsan ʾīmānuhā lam takun ʾāmanat min qablu aw kasabat fī ʾīmānihā khayran quli ntaẓirū ʾinnā muntaẓirūn', 'Onlar, kendilerine meleklerin gelmesi, yahut Rabbinin gelmesi yahut da Rabbinin bazı âyetlerinin gelmesi dışında neyi gözetirler? Rabbinin bazı âyetleri geldiği gün, daha önce iman etmemiş veya imanında bir hayır kazanmamış olan kimseye o imanı fayda vermez. De ki: "Siz bekleyin, şüphesiz biz de beklemekteyiz."'),
(6, 159, 8, 150, 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', 'İnne-lleẕîne ferraḳû dînehum ve kânû şiya’an leste minhum fî şey’in İnnemâ emruhum ila-llâhi śümme yunebbiuhum bimâ kânû yef’alûn', 'Şüphesiz dinlerini parçalayanlar ve gruplara ayrılanlar var ya, sen hiçbir şeyde onlardan değilsin. Onların işi ancak Allah''a kalmıştır. Sonra Allah onlara yaptıklarını haber verecektir.'),
(6, 160, 8, 150, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', 'man jāʾa bil-ḥasanati fa-lahū ʿashru ʾamthālihā wa-man jāʾa bis-sayyiʾati fa-lā yujzā ʾillā mithlahā wa-hum lā yuẓlamūn', 'Kim bir iyilik getirirse, ona on katı vardır. Kim de bir kötülük getirirse, sadece onun kadar ceza görür ve onlara haksızlık edilmez.'),
(6, 161, 8, 150, 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'qul innani hadani rabbi ila siratin mustaqim dinan qayyiman millata ibrahima hanifan wa ma kana minal mushrikin', 'De ki: "Şüphesiz Rabbim beni doğru yola, dosdoğru dine, İbrahim''in bâtıldan uzaklaşmış olan dinine iletti. O, müşriklerden değildi."'),
(6, 162, 8, 150, 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'qul ʾinna ṣalātī wa-nusukī wa-maḥyāya wa-mamātī lillāhi rabbi l-ʿālamīn', 'De ki: Şüphesiz benim namazım, ibadetlerim, hayatım ve ölümüm, alemlerin Rabbi Allah içindir.'),
(6, 163, 8, 150, 'لَا شَرِيكَ لَهُۥ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', 'lā šarīka lahū wa bidhālike ʾumirtu wa ʾanā ʾawwalu l-muslimīn', 'O''nun ortağı yoktur. Bana bununla emredildi ve ben Müslümanların ilkiyim.'),
(6, 164, 8, 150, 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'qul ʾaġayra llāhi ʾabġī rabban wa-huwa rabbukulli šayʾin wa-lā taksibu kullu nafsin ʾillā ʿalayhā wa-lā taziru wāziratun wizra ʾuḫrā ṯumma ʾilā rabbikum marjiʿukum fa-yunabbiʾukum bimā kuntum fīhi taḫtalifūna', 'De ki: "Allah’tan başka bir Rab mı isteyeyim? Halbuki O, her şeyin Rabbidir. Hiçbir kimse kendi kazancından başkasını kazanamaz. Hiçbir günahkar, başka bir günahkarın günah yükünü taşımaz. Sonra dönüşünüz yalnız Rabbinizedir. O zaman size, üzerinde ihtilaf etmekte olduğunuz şeyleri O haber verecektir."'),
(6, 165, 8, 150, 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ', 'wa huwa lladhī jaʿalakum khalāʾifa l-arḍi wa rafaʿa baʿḍakum fawqa baʿḍin darajātin liyabluwakum fī mā ātākum ʾinna rabbaka sarīʿu l-ʿiqābi wa ʾinnahu la-ghafūrun raḥīmun', 'Yeryüzünde birbirinizin yerine geçirdiğiniz (halife kıldığınız) O''dur. Ve sizi derecelerle birbirinizden üstün kıldı ki, size verdikleriyle sizi imtihan etsin. Şüphesiz Rabbin azabı çarçabuk olandır ve O, gerçekten çok bağışlayandır, çok merhamet edendir.'),
(7, 1, 8, 151, 'الٓمٓصٓ', 'ʾAlif-lām-mīm-ṣād', 'Elif, Lam, Mim, Sad.'),
(7, 2, 8, 151, 'كِتَٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'kitābun unzila ilayka felā yukun fī ṣadriki ḥaracun minhu litunḏira bihi waḏikrā lilmuʾminīn', 'Bu, sana indirilen bir kitaptır. Artık bununla ilgili göğsünde bir darlık olmasın; (bu,) onunla insanları uyarman ve müminlere bir öğüt vermen içindir.'),
(7, 3, 8, 151, 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ قَلِيلًا مَّا تَذَكَّرُونَ', 'ittabiʿū mā ʾunzila ʾilaykum min rabbikum walā tattabiʿū min dūnihi ʾawliyāʾa qalīlan mā tadhakkarūn', 'Rabbinizden size indirilenlere uyun ve O''nun astlarından başka velilere uymayın. Ne kadar az öğüt alıyorsunuz!'),
(7, 4, 8, 151, 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتًا أَوْ هُمْ قَآئِلُونَ', 'wa kam min qaryatin ahlaknāhā fa jāʾahā baʾsunā bayātan aw hum qāʾilūn', 'Nice kasabalar (var ki) onları biz helak ettik; geceleri veya gündüzleri istirahat ederlerken azabımız onlara geliverdi.'),
(7, 5, 8, 151, 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَٰلِمِينَ', 'famā kāna daʿwāhum iḏ ǧāʾahum baʾsunā illā an qālū ʾinnā kunnā ẓālimīn', 'Nihayet kendilerine azabımız geldiğinde, feryatlarından başka bir şeyleri kalmadı: "Doğrusu biz zalimmişiz!" demekten başka.'),
(7, 6, 8, 151, 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', 'Fe-le-nes''elen-ne-llezîne ursile ileyhim Ve-le-nes''elen-ne-l-murselîn', 'Kendilerine (peygamber) gönderilenleri mutlaka soracağız ve gönderilen (peygamber)leri de mutlaka soracağız.'),
(7, 7, 8, 151, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ وَمَا كُنَّا غَآئِبِينَ', 'falanaquṣṣanna ʿalayhim biʿilmin wamā kunnā ġāʾibīn', 'Onlara, bildiklerimizle mutlaka haber vereceğiz. Biz, onlardan uzakta değiliz.'),
(7, 8, 8, 151, 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'wa-l-waznu yawmaʾiḏin al-ḥaqqu fa-man ṯaqulat mawāzīnuhu fa-ʾulāʾika humu al-mufliḥūn', 'O gün tartı haktır. Kimlerin tartıları ağır gelirse, işte onlar kurtuluşa erenlerdir.'),
(7, 9, 8, 151, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَظْلِمُونَ', 'Ve men khaffet mevāzīnuhu fe''ūlā''ikellezîne khasirū enfusehum bimā kānū bi''āyātinā yazlimūn', 'Kimlerin tartıları hafif gelirse, işte onlar kendi zararlarına olarak, âyetlerimize zulmetmekte oldukları için kendilerini ziyana uğratanlardır.'),
(7, 10, 8, 151, 'وَلَقَدْ مَكَّنَّٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ قَلِيلًا مَّا تَشْكُرُونَ', 'Ve andolsun ki sizi yeryüzüne yerleştirdik, ve orada sizin için geçim kaynakları yarattık. Ne kadar az şükrediyorsunuz!', 'Andolsun ki sizi yeryüzüne yerleştirdik ve orada sizin için geçim kaynakları yarattık. Ne kadar az şükrediyorsunuz!'),
(7, 11, 8, 151, 'وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ', 'Ve lekad ḣalaknâkum śümme savvernâkum śümme kulnâ lilmelâiketi-scudû li-âdeme fesecedû illâ iblîse lem yekun mine-ssâcidîn', 'Andolsun ki sizi yarattık, sonra size şekil verdik, sonra meleklere ''Âdem''e secde edin!'' dedik. İblis hariç hepsi secde ettiler; o, secde edenlerden olmadı.'),
(7, 12, 8, 152, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', 'qāla mā manaʿaka allā tasjuda ʾiḏ ʾamartuka qāla ʾanā ḫayrum minhu ḫalaqtanī min nārin wa-ḫalaqtahū min ṭīn', 'Allah şöyle dedi: "Sana emrettiğimde seni secde etmekten alıkoyan nedir?" (İblis) "Ben ondan daha hayırlıyım. Beni ateşten yarattın, onu ise çamurdan yarattın" dedi.'),
(7, 13, 8, 152, 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ', 'qāla fa-hbṭ min-hā fa-mā yakūnu laka an tatakabbara fī-hā fa-khruj innaka mina ṣ-ṣāghirīn', 'Allah şöyle dedi: ''Öyleyse oradan in! Senin orada büyüklük taslaman senin haddine değil. Artık çık! Çünkü sen aşağılananlardansın!'''),
(7, 14, 8, 152, 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'qāla anẓirnī ʾilā yawmi yubʿathūn', 'Dedi ki: "Bana, insanların yeniden diriltilecekleri güne kadar süre ver."'),
(7, 15, 8, 152, 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'qāla innaka mina l-munẓarīn', 'Allah şöyle buyurdu: "Sen, (azap edilmekten) ertelenenlerdensin."'),
(7, 16, 8, 152, 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', 'qāla fabimā aghwaytanī laʾaqʿudanna lahum ṣirāṭaka l-mustaqīma', 'Allah şöyle buyurur: "Beni azdırman sebebiyle, mutlaka onların (insanların) yoluna oturacağım. Sonra onlara önlerinden, arkalarından, sağlarından ve sollarından sokulacağım. Onların çoğunu şükredenlerden bulmayacaksın."'),
(7, 17, 8, 152, 'ثُمَّ لَءَاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ', 'thumma laʾātiyannahum min bayni ʾaydīhim wa-min khalfihim wa-ʿan ʾaymānihim wa-ʿan shamāʾilihim wa-lā tajidu ʾaktharahum shākirīn', 'Sonra onlara önlerinden, arkalarından, sağlarından ve sollarından sokulurum. Onların çoğunu şükredenlerden bulamayacaksın.'),
(7, 18, 8, 152, 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', 'qāla ʾkhruj minhā madhʾūman madḥūrā laman tabaʿaka minhum laʾamlaʾanna jahannama minkum ʾajmaʿīn', 'Allah buyurdu ki: "Haydi, oradan kovulmuş ve rahmetimden uzaklaştırılmış olarak çık! Andolsun ki, onlardan (insanlardan) sana uyanlarla birlikte cehennemi sizin hepinizle dolduracağım!"'),
(7, 19, 8, 152, 'وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 'wa-ʾādamu-skun ʾanta wa-zawjukal-jannata fakulā min ḥaythu shiʾtumā walā taqrabā hādhihi-sh-shajarata fatakūnā mina-ẓ-ẓālimīn', 'Adem''e de: ''Ey Adem! Sen ve eşin cennete yerleşin ve ikiniz de ondan, istediğiniz yerden bol bol yiyin. Ancak ş şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz'' dedik.'),
(7, 20, 8, 152, 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَٰلِدِينَ', 'fa waswasa lahumā ash-shayṭānu liyubdiya lahumā mā wūriya ʿanhumā min sawʾātihimā waqāla mā nahākumā rabbukumā ʿan hādhihi ash-shajarati illā an takūnā malakayni aw takūnā mina al-khālidīn', 'Derken şeytan, kendilerinden örtülmüş olan avret yerlerini kendilerine açmak için onlara vesvese verdi ve "Rabbiniz, bu ikinizden başka hiçbir kimseye bu ağaçtan yaklaşmamanızı, ancak melek olmamanız veya ebedî kalanlardan olmamanız için yasaklamıştır" dedi.'),
(7, 21, 8, 152, 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ', 'wa qāsamahumā ʾinnī lakumā lamina n-nāṣiḥīn', 'Ve onlara yemin ederek: "Şüphesiz ben sizin içinizden hayırlı olanlardanım" dedi.'),
(7, 22, 8, 152, 'فَدَلَّىٰهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ', 'fadallāhumā bighurūrin falammā dhāqā ash-shajarata badat lahumā saw''ātuhumā waṭafiqā yakhṣifāni ʿalayhimā min waraqi al-jannati wa nādāhumā rabbuhumā alam anhakumā ʿan tilkumā ash-shajarati wa aqul lakumā inna ash-shayṭāna lakumā ʿaduwwun mubīnun', 'Böylece onları aldatarak (aşağı) indirdi. Ağacın meyvesini tattıklarında, ayıp yerleri kendilerine göründü ve üzerlerine cennet yapraklarından örtmeye başladılar. Rableri onlara şöyle seslendi: "Ben sizi o ağaçtan menetmemiş miydim ve size şeytanın sizin için apaçık bir düşman olduğunu söylememiş miydim?"'),
(7, 23, 8, 153, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'qālā rabbanā ẓalamnā ʾanfusana wa-ʾin lam taghfir lanā wa-t-raḥamnā la-nakūnanna mina l-khāsirīn', 'İkisi de şöyle dediler: "Rabbimiz! Biz kendimize zulmettik. Eğer bize mağfiret etmez ve merhamet etmezsen, mutlaka ziyana uğrayanlardan oluruz."'),
(7, 24, 8, 153, 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'qāla hbiṭū baʿḍukum libaʿḍin ʿaduwwun walakum fī l-arḍi mustaqarun wamatāʿun ilā ḥīnin', 'Allah buyurdu: "Kiminiz kiminize düşman olarak inin! Sizin için yeryüzünde belirli bir zamana kadar kalıp yaşama (yerleşme) ve geçimlik vardır."'),
(7, 25, 8, 153, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', 'qāla fīhā taḥyawna wa fīhā tamūtūna wa minhā tukhrajūna', 'Dedi ki: ''Onun içinde yaşayacaksınız, onun içinde öleceksiniz ve onun içinden (sonunda) çıkarılacaksınız.'''),
(7, 26, 8, 153, 'يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'yā banī ādama qad anzalnā ʿalaykum libāsan yuwārī sawʾātikum wa rīshan wa libāsu t-taqwā dhālika khayrun dhālika min ʾāyāti llāhi laʿallahum yadhdhakkarūn', 'Ey Âdemoğulları! Size avret yerlerinizi örtecek bir giysi ve süslenecek bir giysi indirdik. Takva (Allah''a karşı gelmekten sakınma) giysisi ise daha hayırlıdır. İşte bu, Allah''ın ayetlerindendir. Umulur ki öğüt alıp düşünürler.'),
(7, 27, 8, 153, 'يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', 'yā banī ādama lā yaftinannakumu sh-shayṭānu kamā akhraja abawaykum mina l-jannati yanzicu ʿanhumā libāsahumā li-yuriyéhumā sawʾātihimā innahuu yarakum huwa wa-qabīluhuu min ḥaythu lā tarawnahum innā jaʿalnā sh-shayāṭīna awliyāʾa lilladhīna lā yuʾminūna', 'Ey Ademoğulları! Şeytan, ananızı babanızı (Âdem ile Havva''yı) cennetten çıkardığı gibi sizi de fitneye düşürmesin. O (şeytan) ve onun soyu, sizin kendilerini göremediğiniz yerden sizi görürler. Biz şeytanları, inanmayanların dostu kıldık.'),
(7, 28, 8, 153, 'وَإِذَا فَعَلُوا۟ فَٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'wa ʾiḏā faʿalū fāḥišatan qālū wajadnā ʿalayhā ʾābāʾanā wallāhu ʾamarana bihā qul ʾinna ʾallāha lā ʾamuru bilfaḥšāʾi ʾataqūlūna ʿalā ʾallāhi mā lā taʿlamūna', 'Onlar çirkin bir iş yaptıkları zaman: "Babalarımızı da bu (yolda) bulduk, Allah da bize bunu emretti" derler. De ki: "Allah çirkin işleri emretmez. Bilmediğiniz şeyleri Allah''a mı isnat ediyorsunuz?"'),
(7, 29, 8, 153, 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ', 'Qul Amara rabbī bil-qisṭi Wa aqīmū wujūhakum ʿinda kulli masjidin Wadʿūhu mukhliṣīna lahud-dīna Kamā badaʾakum taʿūdūna', 'De ki: "Rabbim adaleti emretti. Her mescitte yüzlerinizi (O''na) doğru tutun ve (O''na) inanarak, O''na yalvararak (dua edin). Nitekim sizi (ilk önce) yarattığı gibi (yine O''na) döneceksiniz."'),
(7, 30, 8, 153, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 'farīqan hadā wa farīqan ḥaqqa ʿalayhimu ḍ-ḍalālah innahumu-ttakhadhū-sh-shayāṭīna awliyāʾa min dūni-llāh wa yaḥsabūna annahum muhtadūn', 'Allah, kimi doğru yola iletirse doğru yolu bulan odur. Kimi de saptırırsa, işte onlar ziyana uğrayanların ta kendileridir. Andolsun ki biz cehennem için de birçok cin ve insan yarattık. Onların kalpleri vardır, ama onlarla anlayamazlar. Gözleri vardır, ama onlarla göremezler. Kulakları vardır, ama onlarla işitemezler. İşte bunlar hayvanlar gibidir, hatta daha da sapıktırlar. İşte bunlardır gaflete dalanlar. En güzel isimler Allah''ındır. O''na o isimlerle dua edin. O''nun isimleri konusunda eğriye sapanları bırakın. Onlar yapmakta olduklarının cezasını bulacaklardır.'),
(7, 31, 8, 154, 'يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'yā banī ādama khuḏū zinatakum ʿinda kulli masjidin wa kulū wa-šrabū wa lā tusrifū ʾinnahu lā yuḥibbu l-musrifīn', 'Ey Ademoğulları! Her mescid (ibadet yeri) yanında ziynetlerinizi (giyim ve süslerinizi) alın. Yiyin, için, fakat israf etmeyin. Çünkü O, israf edenleri sevmez.'),
(7, 32, 8, 154, 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَٰمَةِ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍ يَعْلَمُونَ', 'Qul man ḥarrama zinata Allāhi-llatī ʾakhraja liʿibādihi wa-ṭ-ṭayyibāti mina-r-rizq Qul hiya li-lladhīna ʾāmanū fī-l-ḥayāti-d-dunyā khāliṣatan yawma-l-qiyāmah Kadhālika nufeṣṣilu-l-ʾāyāti li-qawmin yaʿlamūn', 'De ki: "Allah''ın kulları için çıkardığı zineti ve rızık olarak verdiği güzel şeyleri kim haram kıldı?" De ki: "Bunlar, dünya hayatında iman edenler içindir; kıyamet günü ise yalnız onlara özgüdür. İşte biz, bilen bir topluluk için ayetleri böyle açıklıyoruz."'),
(7, 33, 8, 154, 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'qul innamā ḥarrama rabbīya l-fawāḥisha mā ẓahara minhā wa-mā baṭana wa-l-ithma wa-l-baghy bi-ghayri l-ḥaqqi wa-an tushrikū bi-llāhi mā lam yunazzil bihi sulṭānan wa-an taqūlū ʿalā llāhi mā lā taʿlamūn', 'De ki: "Rabbim yalnızca açık ve gizli çirkin şeyleri, günahı, haksız yere isyanı, hakkında hiçbir delil indirmediği şeyleri Allah’a ortak koşmanızı ve Allah hakkında bilmediğiniz şeyleri söylemenizi haram kılmıştır."'),
(7, 34, 8, 154, 'وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'wa li-kulli ummatin ajalun fa-idha jaa''a ajaluhum la yasta''khiruna sa''atan wa la yastaqdimun', 'Her ümmetin bir eceli vardır. Ecelleri geldiğinde ne bir an geri kalabilirler ne de bir an öne geçebilirler.'),
(7, 35, 8, 154, 'يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'yā banī ʾādama ʾimmā yaʾtiyannakum rusulun minkum yaquṣṣūna ʿalaykum ʾāyātī faman ittaqā waʾaṣlaḥa falā khawfun ʿalayhim walā hum yaḥzanūn', 'Ey Ademoğulları! Size kendi içinizden peygamberler gelip de size ayetlerimi anlattığında, kimler sakınır ve durumlarını düzeltirse, onlara korku yoktur ve onlar mahzun da olmayacaklardır.'),
(7, 36, 8, 154, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'wa-lladhīna kadhdhabū bi-ʾāyātinā wa-stakbarū ʿanhā ʾulāʾika ʾaṣḥābu n-nāri hum fīhā khālidūna', 'Ayetlerimizi yalanlayanlar ve onlara karşı kibirlenenler var ya, işte onlar ateşin halkıdırlar; orada ebedî kalırlar.'),
(7, 37, 8, 154, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 'feman aẓlamu mimmani-ftara ʿala-llāhi kaḏiban aw kaḏḏaba bi-ʾāyātihi ʾulāʾika yanāluhum naṣībuhum mina-l-kitāb ḥattā ʾiḏā jāʾathum rusulunā yatawaffawnahum qālū ʾayna mā kuntum tadʿūna min dūni-llāh qālū ḍallū ʿannā wa-šahidū ʿalā ʾanfusihim ʾannahum kānū kāfirīn', 'Allah''a karşı yalan uyduran veya O''nun ayetlerini yalanlayan kimseden daha zalim kim olabilir? İşte onlara Kitap''tan (takdir edilmiş) nasipleri ulaşacaktır. Nihayet kendilerine elçilerimiz gelip canlarını aldıklarında, onlara şöyle derler: "Allah''ı bırakıp da taptıklarınız nerede?" Derler ki: "Onlar bizden uzaklaşıp kayboldular." Ve kendi aleyhlerine, inkârcı olduklarına dair şahitlik ederler.'),
(7, 38, 8, 155, 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ', 'qāla dkhulū fī ʾumum qad khalat min qablikum mina l-jinni wa-l-ʾinsi fī n-nār kullamā dakhala ʾummatun laʿanat ʾukhtahā ḥattā ʾidhā ʾiddārakū fīhā jamīʿan qālat ʾukhrāhum li-ʾūlāhum rabbanā hāʾulāʾi ʾaḍallūnā fa-ʾātihiṁ ʿadhāban ḍiʿfan mina n-nār qāla likullin ḍiʿfun wa-lākin lā taʿlamūn', 'Allah buyurur ki: "Ateşe girin! Sizden önce geçmiş cin ve insan topluluklarıyla birlikte ateşe girin! Her ne zaman bir topluluk girse, öbürünü lanetleyecektir. Nihayet hepsi orada toplandığında, sonrakiler öncekiler için diyecekler ki: "Rabbimiz! Bunlar bizi saptırdılar. Onun için bunlara ateşten iki kat azap ver!" Allah buyurur ki: "Her biriniz için iki kat vardır. Fakat siz bilemezsiniz."'),
(7, 39, 8, 155, 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', 'wa qālat ʾūlāhum li-ʾuḫrāhum famā kāna lakum ʿalaynā min faḍlin faḏūqū al-ʿaḏāba bimā kuntum taksibūn', 'Onlardan ilki diğerine şöyle der: "Eğer sizin bize bir üstünlüğünüz varsa, o zaman tattığınız bu azabı, kazandıklarınız yüzünden tadın!"'),
(7, 40, 8, 155, 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', 'ʾinna alladhīna kadhdhabū bi-ʾāyātinā wa-stakbarū ʿanhā lā tuftaḥu lahum ʾabwābu s-samāʾi wa-lā yadkhulūna l-jannata ḥattā yalija l-jamalu fī sammi l-khiyāṭi wa-kadhālika najzī l-mujrimīna', 'Şüphesiz âyetlerimizi yalanlayan ve onlara kibirle karşı çıkanlar yok mu, işte onlara göğün kapıları açılmaz ve deve iğne deliğinden geçmedikçe cennete giremezler. Biz, suçluları işte böyle cezalandırırız.'),
(7, 41, 8, 155, 'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'lahum min jahannama mihādun wa min fawqihim ghawāshin wa kadhālika najzī aẓ-ẓālimīna', 'Onlar için cehennemden bir döşek ve üstlerinden de örtüler vardır. Zalimleri işte böyle cezalandırırız.'),
(7, 42, 8, 155, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti lā nukallifu nafsan ʾillā wusʿahā ʾulāʾika ʾaṣḥābu l-jannati hum fīhā khālidūna', 'İman edip salih amel işleyenlere gelince; biz hiçbir kimseye gücünün yeteceğinden başkasını teklif etmeyiz. İşte onlar cennet ehlidirler; onlar orada ebedî kalırlar.'),
(7, 43, 8, 155, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'wa-naz''anā mā fī ṣudūrihim min ġillin tajrī min taḥtihimu l-anhāru wa-qālū l-ḥamdu li-llāhi l-ladhī hadānā li-hādha wa-mā kunnā li-nahtadiya lawlā an hadānā llāhu la-qad jāʾat rusulu rabbina bi-l-ḥaqqi wa-nūdū an tilkumu l-jannatu ūritsumūhā bimā kuntum taʿmalūna', 'Ve onların göğüslerinde bulunan kindar duyguları söküp attık. Altlarından ırmaklar akar. Ve dediler ki: "Bizi buna ileten Allah''a hamdolsun. Eğer Allah bizi iletmeseydi, biz hidayete eremezdik. Andolsun ki Rabbimizin elçileri hak ile geldiler." Ve onlara şöyle seslenildi: "İşte bu, yapmakta olduğunuz ameller sebebiyle size miras bırakılan cennettir."'),
(7, 44, 8, 156, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا قَالُوا۟ نَعَمْ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', 'wa-nādā ʾaṣḥābu l-jannati ʾaṣḥāba n-nāri ʾan qad wajadnā mā waʿadanā rabbunā ḥaqqan fahal wajadtum mā waʿada rabbukum ḥaqqan qālū naʿam fa-ʾaḏḏana muʾaḏḏinun baynahum ʾan laʿnatu llāhi ʿalā ẓ-ẓālimīn', 'Cennet ehli, Cehennem ehlline, ''Rabbimizin bize vaadettiğini gerçek bulduk; sizin de Rabbinizin vaadettiğini gerçek bulduğunuzu gördünüz mü?'' diye seslenirler. ''Evet'' derler. Derken, ikisinin arasında bir çağrıcı, ''Allah''ın laneti zalimlerin üzerine olsun!'' diye seslenir.'),
(7, 45, 8, 156, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْءَاخِرَةِ كَٰفِرُونَ', 'alladhīna yaṣuddūna ʿan sabīli llāhi wa yabghūnahā ʿiwajan wa hum bi l-ʾākhirati kāfirūna', 'Onlar, Allah''ın yolundan alıkoyanlar ve onu eğri (kusurlu) göstermek isteyenlerdir. Onlar ahireti inkâr edenlerdir.'),
(7, 46, 8, 156, 'وَبَيْنَهُمَا حِجَابٌ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', 'wa baynahumā ḥijābun wa ʿalā l-ʾaʿrāfi rijālun yaʿrifūna kullam bisīmāhum wa nādaw ʾaṣḥāba l-jannati ʾan salāmun ʿalaykum lam yadkhulūhā wa hum yaṭmaʿūn', 'Onların arasında bir perde vardır. A''raf''ta da herkesi simalarından tanıyan erler bulunur. Cennet ehline, "Selâm size!" diye seslenirler. Bunlar henüz cennete girmemiş, ama ona hasret duyanlardır.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(7, 47, 8, 156, 'وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'wa-ʾiḏā ṣurifat ʾabṣāruhum tilqāʾa ʾaṣḥābi n-nāri qālū rabbanā lā tajʿal-nā maʿa l-qawmi ẓ-ẓālimīna', 'Gözleri cehennem ehline doğru çevrildiğinde ise, "Rabbimiz! Bizi zalimler topluluğu ile bir tutma!" derler.'),
(7, 48, 8, 156, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', 'wa-nādā ʾaṣḥābu l-ʾaʿrāfi rijālan yaʿrifūnahum bisīmāhum qālū mā ʾaghnā ʿankum jamʿukum wa-mā kuntum tastakbirūn', 'A''raf Ashabı da, simalarından tanıdıkları birtakım adamları çağırdı. "Topluluğunuz ve büyüklük taslamakta olduğunuz şeyler size hiçbir fayda sağlamadı mı?" dediler.'),
(7, 49, 8, 156, 'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', 'ʾahāʾul-ladhīna ʾaqsamtum lā yanāluhumu ʾllāhu bi-raḥmah udkhulū al-jannah lā khawfun ʿalaykum walā ʾantum taḥzanūn', 'Onlar, ''Allah onları rahmetine erdirmez'' diye yemin ettiğiniz kimseler değil midir? (Şimdi onlara) Girin cennete! Korku yoktur size; siz mahzun da olmayacaksınız.'),
(7, 50, 8, 156, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ', 'wa-nādā aṣḥābu n-nāri aṣḥāba l-jannati an afīḍū ʿalaynā mina l-māʾi aw mimmā razaqakumu llāh qālū inna llāha ḥarramahumā ʿalā l-kāfirīn', 'Cehennemlikler, cennetliklere, ''Bize biraz su dökün yahut Allah''ın size verdiği rızıktan bir şeyler verin'' diye seslenirler. Cennetlikler ise, ''Şüphesiz Allah, o ikisini de kâfirlere haram kılmıştır'' derler.'),
(7, 51, 8, 156, 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'alladhīna-ttakhadhū dīnahum lahwān wa laʿibān wa gharrathumu-l ḥayātu-d dunyā fa-l-yawma nansāhum kamā nasū liqāʾa yawmihim hādhā wa mā kānū bi-āyātinā yajḥadūn', 'Onlar, dinlerini bir eğlence ve oyun edindiler ve dünya hayatı onları aldattı. İşte onlar, bu günlerine kavuşmayı unuttukları ve ayetlerimizi inkâr ettikleri gibi, biz de bugün onları unutacağız.'),
(7, 52, 8, 157, 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'Ve lekad ciʾnāhum bi-kitābin fe-faṣṣalnāhu ʿalā ʿilmin hudan ve raḥmeten li-kavmin yuʾminūna', 'Andolsun ki Biz onlara, ilim üzere açıkladığımız bir Kitap getirdik ki, inanan bir toplum için hidayet ve rahmettir.'),
(7, 53, 8, 157, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'hal yanẓurūna illā taʾwīlahū yawma yaʾtī taʾwīluhū yaqūlu alladhīna nasūhu min qablu qad jāʾat rusulu rabbina bil-ḥaqqi fahal lanā min shufʿāʾa fayashfaʿū lanā aw nuraddu fanaʿmala ghayra alladhī kunnā naʿmalu qad khasirū anfusahum wa ḍalla ʿanhum mā kānū yaftarūna', 'Onlar, (Kur''an''ın) kendi açıklanmış hükmünü (veya azabının gerçekleşmesini) mi bekliyorlar? O hükmün gerçekleştiği gün, daha önce onu unutanlar şöyle derler: ''Andolsun ki Rabbimizin elçileri hak ile gelmişti. Şimdi bizim şefaatçilerimiz var mı ki bize şefaat etsinler? Veya (dünyaya) geri döndürülür müyüz de şimdiye kadar yaptıklarımızdan başkasını yaparız?'' Onlar, kendilerini ziyana uğratmışlardır ve uydurmakta oldukları şeyler de onlardan sapıp kaybolmuştur.'),
(7, 54, 8, 157, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'ʾinna rabbakumullāhu llaḏī ḫalaqa s-samāwāti wa-l-ʾarḍa fī sittati ʾayyāmin ṯumma stawā ʿalā l-ʿarši yuġšī l-layla n-nahāra yaṭlubuhū ḥaṯīṯan wa-š-šamsa wa-l-qamara wa-n-nujūma musaḫḫarātin bi-ʾamrihī ʾalā lahū l-ḫalqu wa-l-ʾamru tabāraka llāhu rabbul-ʿālamīn', 'Şüphesiz Rabbiniz Allah''tır. O, gökleri ve yeri altı günde yarattı, sonra Arş''a istiva etti. O, geceyi, durmaksızın onu kovalayan gündüze bürüdü. Güneşi, Ay''ı ve yıldızları da buyruğu altına almıştır. Bilesiniz ki yaratma ve emir (yetkisi) O''na aittir. Âlemlerin Rabbi Allah ne yücedir!'),
(7, 55, 8, 157, 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'udʿū rabbakum taḍarruʿan wa-khufyah ʾinnahu lā yuḥibbu l-muʿtadīn', 'Rabbinize alçakgönüllülükle ve gizlice dua edin. Şüphesiz O, haddi aşanları sevmez.'),
(7, 56, 8, 157, 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ', 'wa-lā tufsidū fī l-arḍi baʿda iṣlāḥihā wa-dʿūhu khawfan wa-ṭamʿan ʾinna raḥmata ʾllāhi qarībun mina l-muḥsinīn', 'Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın. O''na korkarak ve umut ederek dua edin. Şüphesiz Allah''ın rahmeti, iyilik edenlere yakındır.'),
(7, 57, 8, 157, 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', 'wa-huwa alladhī yursilu ar-riyāḥa bushram bayna yaday raḥmatihī ḥattā idhā aqallat saḥāban thiqālan suqnāhu libaladin mayyitin fa-anzalnā bihi al-māʾa fa-akhrajnā bihi min kulli ath-thamarāti kadhālika nukhriju al-mawtā laʿallakum tadhakkarūna', 'Rüzgârları rahmetinin önünde müjdeci olarak gönderen, böylece ağırlaşmış bulutları taşıdığında onu ölü bir beldeye sevk eden, sonra onunla suyu indirip her çeşit ürünü çıkaran O’dur. İşte ölüleri de böyle çıkaracağız ki, düşünüp öğüt alasınız.'),
(7, 58, 8, 158, 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ لِقَوْمٍ يَشْكُرُونَ', 'wa-l-baladu ṭ-ṭayyibu yakhruju nabātuhu bi-ʾidḥni rabbihi wa-l-ladhī khabutha lā yakhruju ʾillā nakadan kadhālika nuṣarrifu l-ʾāyāti li-qawmin yashkurūn', 'Hoş ve güzel belde, Rabbinin izniyle bitkisi (güzel) çıkar. Kötü ve verimsiz belde ise, ancak cılız bir bitki çıkarır. İşte biz, şükreden bir topluluk için ayetleri böyle açıklıyoruz.'),
(7, 59, 8, 158, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'leḳad erselnâ nûḥan ilâ ḳavmihî feḳâle yâ ḳavmi-ʿbudû-llâh mâ leküm min ilâhin gayruh innî eḫâfü ʿaleyküm ʿaẕâbe yevmin ʿaẓîm', 'Andolsun ki Nuh''u kavmine gönderdik de o şöyle dedi: "Ey kavmim! Allah''a kulluk edin. Sizin için O''ndan başka hiçbir ilah yoktur. Şüphesiz ben, sizin için büyük bir günün azabından korkuyorum."'),
(7, 60, 8, 158, 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍ مُّبِينٍ', 'qāla l-malaʾu min qawmihī innā lanarāka fī ḍalālin mubīnin', 'Kavminin ileri gelenleri şöyle dedi: "Doğrusu biz seni apaçık bir sapıklık içinde görüyoruz."'),
(7, 61, 8, 158, 'قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'qāla yā qawmi laysa biya ḍalālatun walākinnanī rasūlun min rabbi l-ʿālamīn', 'Dedi ki: "Ey kavmim! Bende bir delilik yok; ama ben âlemlerin Rabbi tarafından bir peygamberim."'),
(7, 62, 8, 158, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'uballighukum risālāti rabbī wa anṣaḥu lakum wa aʿlamu minallāhi mā lā taʿlamūn', 'Size Rabbimin vahyettiği şeyleri tebliğ ediyorum ve size öğüt veriyorum. Ve ben Allah''tan, sizin bilmediğiniz şeyleri biliyorum.'),
(7, 63, 8, 158, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', 'ʾa wa ʿajibtum ʾan jāʾakum dhikrum mir rabbikum ʿalā rajulimm minkum liyunḏirakum wa litattaqū wa laʿallakum turḥamūn', 'Yoksa size Rabbinizden, içinizden bir adam aracılığıyla bir öğüt (veya uyarı) gelmesine mi şaşırdınız? Sizi uyarması, Allah''tan korkup sakınmanız ve böylece rahmet olunmanız için (bunu yaptı).'),
(7, 64, 8, 158, 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', 'fa-kaḏḏabūhu fa-ʾanjaynāhu wa-llaḏīna maʿahu fī l-fulki wa-ʾaġraqnā llaḏīna kaḏḏabū bi-ʾāyātinā ʾinnahum kānū qawman ʿamīna', 'Böylece onu yalanladılar. Biz de onu ve gemide onunla birlikte olanları kurtardık. Ayetlerimizi yalanlayanları ise boğduk. Çünkü onlar kör bir kavim idiler.'),
(7, 65, 8, 158, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'wa ʾilā ʿādin ʾaḵāhum hūdā qāla yā qawmi ʿbudū llāha mā lakum min ʾilāhin ġayruhu ʾafalā tattaqūn', 'Ve Âd (kavmine) kardeşleri Hûd''u (gönderdik). Dedi ki: "Ey kavmim! Allah''a kulluk edin. Sizin O''ndan başka ilâhınız yoktur. Hâlâ (O''ndan) korkmayacak mısınız?"'),
(7, 66, 8, 158, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ', 'qāla l-malau lladhīna kafarū min qawmihī ʾinnā lanarāka fī safāhatin wa ʾinnā lanazunnuka mina l-kādhibīna', 'Kavminden inkâr eden ileri gelenler şöyle dediler: "Doğrusu biz seni bir sefâlet içinde görüyoruz ve gerçekten seni yalancılardan sanıyoruz."'),
(7, 67, 8, 158, 'قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'qāla yā qawmi laysa bī safāhatu wa lākinni rasūlun min rabbi l-ʿālamīn', 'Dedi ki: "Ey kavmim! Bende sefahat (akılsızlık, beyinsizlik) yoktur. Lakin ben, âlemlerin Rabbi tarafından bir peygamberim."'),
(7, 68, 8, 159, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', 'uballighukum risālāti rabbī wa anā lakum nāṣiḥun amīn', 'Ben size Rabbimin vahyettiği mesajları tebliğ ediyorum ve ben sizin için güvenilir bir öğütçüyüm.'),
(7, 69, 8, 159, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', 'ʾa wa ʿajibtum ʾan jāʾakum dhikrum mir rabbikum ʿalā rajulim minkum liyunḏirakum wa ḏkurū ʾiḏ ǧaʿalakum ḫulafāʾa mim baʿdi qawmi nūḥin wa zādakum fī l-ḫalqi baṣṭatan fa-ḏkurū ʾālāʾa llāhi laʿallakum tufliḥūn', 'Size Rabbinizden bir zikir (öğüt) adam içinizden birine gelmesiyle mi şaşırdınız? Sizi Nuh kavminden sonra halifeler kıldığını ve yaratılışta sizi daha geniş (güçlü) kıldığını hatırlayın. Allah''ın nimetlerini hatırlayın ki kurtuluşa eresiniz.'),
(7, 70, 8, 159, 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'qālū ʾaǰiʾtanā linaʿbuda ḷḷāha waḥdahū wanadhara mā kāna yaʿbudu ʾābāʾunā faʾtinā bimā taʿidunā ʾin kunta mina ṣ-ṣādiqīn', 'Dediler ki: "Putperestliği bırakıp yalnızca Allah''a kulluk edelim diye mi bize geldin? Atalarımızın taptığı şeyleri bırakmamızı mı istiyorsun? Eğer doğru sözlülerden isen, bizi tehdit ettiğin azabı getir!"'),
(7, 71, 8, 159, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'qāla qad waqaʿa ʿalaykum min rabbikum rijsun wa-ghaḍabun atujādilūnanī fī ʾasmāʾin sammaytumūhā ʾantum wa-ʾābāʾukum mā nazzala ʾllāhu bihā min sulṭānin fa-ntẓirū ʾinnī maʿakum mina l-muntaẓirīna', 'Dedi ki: "Rabbinizden üzerinize bir azap ve gazap hak olmuştur. Bana, sizin ve atalarınızın (bu konuda) hiçbir delil indirmediği birtakım isimler hakkında mı tartışıyorsunuz? Artık bekleyin! Şüphesiz ben de sizinle birlikte bekleyenlerdenim."'),
(7, 72, 8, 159, 'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَمَا كَانُوا۟ مُؤْمِنِينَ', 'faʾanjaynāhu wallaḏīna maʿahu biraḥmatim minnā waqaṭaʿnā dābira llaḏīna kaḏḏabū biʾāyātinā wamā kānū muʾminīn', 'Böylece onu ve beraberindekileri tarafımızdan bir rahmetle kurtardık ve ayetlerimizi yalanlayan ve inanmakta olanları da kökleri kesilmiş olarak helak ettik.'),
(7, 73, 8, 159, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ', 'waʾilā thamūda ʾakhāhum ṣāliḥan qāla yā qawmi ʿbudū ʾllāha mā lakum min ʾilāhin ġayruhu qad jāʾatkum bayyinatun mir rabbikum hāḏihi nāqatu ʾllāhi lakum ʾāyatan faḏarūhā taʾkul fī ʾarḍi ʾllāhi walā tamassūhā bisūʾin fayaʾhuḏakum ʿaḏābun ʾalīmun', 'Ve Semûd''a da kardeşleri Salih''i gönderdik. Dedi ki: ''Ey kavmim! Allah''a kulluk edin. Sizin O''ndan başka ilahınız yoktur. Rabbinizden size açık bir delil geldi. İşte bu Allah''ın dişi devesi size bir ayettir. Bırakın onu, Allah''ın arzında otlasın; ona kötülükle dokunmayın ki, sonra sizi elem dolu bir azap yakalamasın.'''),
(7, 74, 8, 160, 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'wa-dhkurū idh jaʿalakum khulafāʾa min baʿdi ʿādin wa-bawwaʾakum fī l-arḍi tattakhidhūna min suhūlihā quṣūran wa-tanḥitūna l-jibāla buyūtan fa-dhkurū ʾālāʾa llāhi wa-lā taʿthaw fī l-arḍi mufsidīna', 'Hani O, sizi Âd''dan sonra yerine getirdi ve sizi yeryüzünde yerleştirdi. Oraların (oval) düzlüklerinde saraylar yapıyor, dağları oyarak evler yapıyorsunuz. Artık Allah''ın ni''metlerini hatırlayın da yeryüzünde bozgunculuk yaparak fesat çıkarmayın.'),
(7, 75, 8, 160, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', 'qāla l-malaʾu lladhīna istakbarū min qawmihi lil-ladhīna ustuḍʿifū liman ʾāmana minhum ʾataʿlamūna ʾanna ṣāliḥan mursalun min rabbihī qālū ʾinnā bimā ʾursila bihi muʾminūn', 'Kavminin ileri gelenleri, büyüklük taslayanlar, zayıf düşürülmüş olanlara şöyle dediler: ''Salih''in Rabbinden (gönderilmiş) bir peygamber olduğunu biliyor musunuz?'' Onlar (zayıf düşürülenler) dediler ki: ''Doğrusu biz onunla gönderilene inanıyoruz.'''),
(7, 76, 8, 160, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 'qāla lladhīna istakbarū ʾinnā bil-ladhī ʾāmantum bihi kāfirūn', 'Büyüklük taslayanlar şöyle dedi: "Doğrusu biz, sizin inandığınızı inkâr edenleriz."'),
(7, 77, 8, 160, 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', 'faʿaqarū an-nāqata waʿataw ʿan ʾamri rabbihim wa qālū yā ṣāliḥu ʾtinā bimā taʿidunā ʾin kunta mina l-mursalīn', 'Derken deveyi kestiler ve Rablerinin emrine karşı geldiler. Ve dediler ki: "Ey Salih! Eğer gerçekten peygamberlerden isen, bizi tehdit ettiğin azabı getir!"'),
(7, 78, 8, 160, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'fa-ʾakhaḏathumu ʾr-rajfatu fa-ʾaṣbaḥū fī dārihim jāṯimīn', 'Derken, kendilerini o korkunç sarsıntı yakaladı da, oldukları yerde diz üstü çöke kaldılar.'),
(7, 79, 8, 160, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ', 'fa tawallā ʿanhum wa qāla yā qawmi laqad ablaghtukum risālata rabbī wa naṣaḥtu lakum wa lākin lā tuḥibbūna n-nāṣiḥīn', 'Bunun üzerine onlardan yüz çevirdi ve şöyle dedi: "Ey kavmim! Andolsun ki, size Rabbimin vahyettiğini tebliğ ettim ve size hayırlı niyetle öğüt verdim. Fakat siz, hayırhahları sevmiyorsunuz."'),
(7, 80, 8, 160, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', 'wa-lūṭan ʾiḏ qāla li-qawmihi ʾataʾtūna l-fāḥišata mā sabaqakum bihā min ʾaḥadin mina l-ʿālamīn', 'Lût''u da (hatırla). Hani kavmine demişti ki: "Sizden önce âlemlerden hiç kimsenin yapmadığı hayasızlığı mı yapıyorsunuz?"'),
(7, 81, 8, 160, 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', 'ʾinnakum lataʾtūna r-rijāla šahwatan min dūni n-nisāʾi bal ʾantum qawmun musrifūna', 'Siz gerçekten kadınları bırakıp şehvetle erkeklere yaklaşıyorsunuz. Hayır, siz sınırı aşan bir topluluksunuz.'),
(7, 82, 8, 161, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', 'wa mā kāna jawāba qawmihī ʾillā ʾan qālū ʾakhrijūhum min qaryatikum ʾinnahum ʾunāsun yataṭahharūn', 'Kavminin cevabı ise sadece şöyle demek oldu: "Onları memleketinizden çıkarın! Çünkü onlar, (kendini) temiz tutmaya çalışan insanlardır."'),
(7, 83, 8, 161, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'faʾanjaynāhu waʾahlahū ʾillā ʾimraʾatahū kānat mina l-ḡābirīn', 'Bunun üzerine onu ve ailesini kurtardık; ancak karısı müstesna. O, geride kalanlardan idi.'),
(7, 84, 8, 161, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'wa-amṭarnā ʿalayhim maṭaran fa-nẓur kayfa kāna ʿāqibatu l-mujrimīn', 'Ve üzerlerine bir yağmur indirdik. Bak, suçluların sonu nasıl oldu!'),
(7, 85, 8, 161, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'wa ʾilā madyana ʾaḫāhum ʃuʿayban qāla yā qawmi ʿbudū l-lāha mā lakum min ʾilāhin ġayruhu qad jāʾatkum bayyinatun mir rabbikum fa-ʾawfū l-kayla wa-l-mīzāna wa lā tabḫasū n-nāsa ʾašyāʾahum wa lā tufsidū fī l-ʾarḍi baʿda ʾiṣlāḥihā ḏālikum ḫayrun lakum ʾin kuntum muʾminīn', 'Medyen''e de kardeşleri Şuayb''ı (gönderdik). O, şöyle dedi: "Ey kavmim! Allah''a kulluk edin. Sizin O''ndan başka ilahınız yoktur. Rabbinizden size açık bir delil gelmiştir. Ölçüyü ve tartıyı tam yapın. İnsanların eşyalarını eksik vermeyin. Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın. Eğer inanıyorsanız, böylesi sizin için daha hayırlıdır."'),
(7, 86, 8, 161, 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'wa lā taqʿudū bikulli ṣirāṭin tūʿidūna wa taṣuddūna ʿan sabīli llāhi man ʾāmana bihi wa tabghūnahā ʿiwajan wa ḏkurū ʾiḏ kuntum qalīlan fa-kaṯṯarakum wa-nẓurū kayfa kāna ʿāqibatu l-mufsidīn', 'Yollara oturup da Allah yolundan iman edenleri çevirmeye, onu eğri göstermeye çalışmayın. Düşünün, siz azken O sizi çok yaptı. Bozguncuların sonunun nasıl olduğuna bir bakın.'),
(7, 87, 8, 161, 'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'wa ʾin kāna ṭāʾifatun mimmkum ʾāmanū billadhī ʾursiltu bihi wa ṭāʾifatun lam yuʾminū faṣbirū ḥattā yaḥkuma ʾallāhu baynanā wa huwa khayru l-ḥākimīn', 'Eğer içinizden bir topluluk, benimle gönderilene inanırsa, bir topluluk da inanmazsa, Allah aramızda hükmedinceye kadar sabredin. O, hükmedenlerin en hayırlısıdır.'),
(7, 88, 9, 162, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ', 'qāla l-malaʾu l-ladhīna istakbarū min qawmihī lanukhrijannaka yā shuʿaybu wa-lladhīna āmanū maʿaka min qaryatinā aw lataʿūdunna fī mīllatinā qāla awaw kunnā kārihīna', 'Kavminin ileri gelenleri, büyüklük taslayanlar şöyle dediler: ''Ey Şuayb! Seni ve seninle birlikte iman edenleri ya kentimizden çıkarırız, ya da mutlaka bizim dinimize dönersiniz.'' (Şuayb) dedi ki: ''İstemeyerek de olsa (çıkarılacak mıyız)?'''),
(7, 89, 9, 162, 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ', 'qadiftaraynā ʿalā llāhi kaḏiban in ʿudnā fī miltikum baʿda iḏ najjānā llāhu minhā wamā yakūnu lanā ʾan naʿūda fīhā ʾillā ʾan yašāʾa llāhu rabbunā wasiʿa rabbunā kulla šayʾin ʿilman ʿalā llāhi tawakkalnā rabbanā ʾiftaḥ baynanā wabayna qawminā bilḥaqqi waʾanta ḫayru l-fātiḥīn', 'Andai kata kita kembali ke dalam agama kamu sesudah Allah menyelamatkan kita daripadanya, tentulah kita telah mengada-adakan kebohongan terhadap Allah. Dan tidaklah menjadi hak kita kembali kepadanya, kecuali kalau Allah, Tuhan kami, menghendaki. Tuhan kami meliputi segala sesuatu dengan ilmu(-Nya); kepada Allah jualah kami bertawakkal. Wahai Tuhan kami, jadikanlah keputusan yang adil di antara kami dan kaum kami, dan Engkaulah sebaik-baik pemberi keputusan.'),
(7, 90, 9, 162, 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', 'waqāla l-malau lladhīna kafarū min qawmihī laʾini ttabaʿtum Shuʿayban ʾinnakum ʾidhan lakhasirūn', 'Kavminden kâfirler şöyle dediler: ''Andolsun ki, eğer Şuayb''e uyarsanız, o takdirde siz gerçekten ziyana uğrayanlardan olursunuz.'''),
(7, 91, 9, 162, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'fa-ʾakhaḏathumu ʾr-rajfatu fa-ʾaṣbaḥū fī dārihim jāṯimīn', 'Derken kendilerini o şiddetli sarsıntı yakaladı da, oldukları yerde diz üstü çöke kaldılar.'),
(7, 92, 9, 162, 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ', 'alladhīna kadhdhabū Shuʿayban kaʾan lam yaghnaw fīhā alladhīna kadhdhabū Shuʿayban kānū humu l-khāsirīn', 'Şuayb''ı yalanlayanlar, sanki orada hiç yaşamamışlar gibi oldular. Şüphesiz Şüayb''ı yalanlayanlar, işte onlar ziyana uğrayanların ta kendileridir.'),
(7, 93, 9, 162, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَٰفِرِينَ', 'fa tawallā ʿanhum wa qāla yā qawmi laqad ablaghtukum risālāti rabbī wa naṣaḥtu lakum fa kayfa āsā ʿalā qawmin kāfirīn', 'Bunun üzerine onlardan yüz çevirdi ve şöyle dedi: "Ey kavmim! Andolsun ki, Rabbimin vahyettiği şeyleri size ulaştırdım ve size öğüt verdim. Şimdi ben, kâfir bir topluma üzülür müyüm?"'),
(7, 94, 9, 162, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 've mā arsalnā fī qaryatin min nabiyyin illā ʾakhaḏnā ʾahalahā bil-baʾsāʾi wad-ḍarrāʾi laʿallahum yaḍḍarraʿūn', 'Hangi memlekete bir peygamber göndermişsek, oranın halkını şiddetli geçim sıkıntısı ve zarara uğrattık ki, yalvarsınlar.'),
(7, 95, 9, 162, 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'thumma baddalnā makāna s-sayyiʾati l-ḥasanata ḥattā ʿafaw wa qālū qad massa ʾābāʾanā ḍ-ḍarrāʾu wa-s-sarrāʾu fa ʾakhadhnāhum baghtatan wa hum lā yashʿurūn', 'Sonra, onların yerini iyilikle değiştirdik; sonunda çoğaldılar ve şöyle dediler: "Dedelerimize de darlık ve bolluk dokunmuştu." Bunun üzerine onları, hiç farkında olmadıkları bir sırada ansızın yakaladık.'),
(7, 96, 9, 163, 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'Ve lev enne ehle l-kurā āmānū v-vattaqaw Le fetaḥnā ʿalayhim berakātin mine s-semāʾi ve l-arḍi Ve lākin keḏḏebū Fe ʾaḵaḏnāhum bimā kānū yaksibūn', 'Oysaki kasaba halkı inanıp takva sahibi olsalardı, elbette üzerlerine gökten ve yerden bereketler açardık. Fakat yalanladılar, bu yüzden onları kazandıkları yüzünden yakalayıverdik.'),
(7, 97, 9, 163, 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًا وَهُمْ نَآئِمُونَ', 'ʾafʾamana ʾahlu l-qurā ʾan yaʾtiyahum baʾsunā bayātan wa-hum nāʾimūn', 'Kasabaların halkı, geceleyin uyurlarken kendilerine azabımızın gelmeyeceğinden güvende miydiler?'),
(7, 98, 9, 163, 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', 'Awa amina ahlul-qura An ya''tiyahum ba''sunā duḥan Wa hum yal''abūn', 'Kasabaların halkı, bizim azabımızın onlara kuşluk vaktinde, onlar (oyun ve eğlence içinde) iken gelmeyeceğinden emin mi oldular?'),
(7, 99, 9, 163, 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ', 'ʾafʾamanū makra ʾllāhi falā yaʾmanu makra ʾllāhi ʾillā l-qawmu l-khāsirūna', 'Yoksa Allah''ın tuzak ve hilesinden emin mi oldular? Halbuki hüsrana uğrayan topluluktan başkası Allah''ın tuzak ve hilesinden emin olamaz.'),
(7, 100, 9, 163, 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', 'Avelam yahdi lillazīne yarīṣūne l-arḍa mim baʿdi ahlihā An law našāʾu aṣabnāhum biẕunūbihim Wa naṭbaʿu ʿalā qulūbihim fehum lā yasmaʿūn', 'Onların ardından yeryüzüne varis olanlara, eğer dileyecek olursak, onları da günahları yüzünden helak edeceğimizi ve kalplerini mühürleyip de işitemez hale getireceğimizi bildiren (bir delil) kendilerine ulaşmadı mı? (Hala ibret almayacaklar mı?)'),
(7, 101, 9, 163, 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ', 'tilke l-qurā naquṣṣu ʿalayka min anbāʾihā wa-laqad jāʾathum rusuluhum bi-l-bayyināti fa-mā kānū li-yuʾminū bi-mā kaḏḏabū min qablu kaḏālika yaṭbaʿu llāhu ʿalā qulūbi l-kāfirīna', 'İşte bu şehirler (hakkında) sana anlattıklarımız, onlara peygamberleri apaçık delillerle gelmişti. Ama daha önce yalanladıklarını iman edecek değillerdi. İşte Allah, kâfirlerin kalplerini böyle mühürler.'),
(7, 102, 9, 163, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ', 've mā vecednā li-ʾekšerihim min ʿahdin ve in vecednā ʾekšerehum le-fāsiqīn', 'Onların çoğunda bir ahit (bağlılık) bulmadık. Ve onların çoğunu fasık (yoldan çıkmış) bulduk.'),
(7, 103, 9, 163, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'thumma baʿathnā min baʿdihim mūsā bi-āyātinā ilā firʿawna wa-malaʾihi faẓalamū bihā fa-nẓur kayfa kāna ʿāqibatu l-mufsidīn', 'Sonra onların ardından, kendilerine âyetlerimizle Mûsâ''yı Firavun ve onun ileri gelenlerine gönderdik. Onlar ise âyetlerimize karşı zulmettiler. İşte bu bozguncuların sonunun nasıl olduğuna bir bak!'),
(7, 104, 9, 163, 'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'waqāla mūsā yā firʿawnu innī rasūlun mir rabbil-ʿālamīn', 'Musa dedi ki: "Ey Firavun! Şüphesiz ben, âlemlerin Rabbi tarafından gönderilmiş bir elçiyim."'),
(7, 105, 9, 164, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', 'ḥaqīqun ʿalā an lā aqūla ʿala Allāhi illā al-ḥaqqa qad jiʾtukum bibayyinatin min rabbikum faʾarsil maʿiya banī Isrāʾīla', 'Allah''a karşı gerçekten başkasını söylememek benim için bir borçtur. Size Rabbimden açık bir delil (ayet) getirdim. Artık İsrailoğullarını benimle gönder.'),
(7, 106, 9, 164, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'qāla in kunta jiʾta bi-ʾāyatin fa-ʾti bihā ʾin kunta mina ṣ-ṣādiqīn', 'Dedi ki: Eğer doğru sözlülerden isen, (hakkı) gösteren bir mucize getirsene!'),
(7, 107, 9, 164, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', 'faʾalqā ʿaṣāhu faʾiḏā hiya ṯuʿbānun mubīnun', 'Bunun üzerine Musa asasını bıraktı. Bir de ne görsün, asa apaçık bir yılan oluverdi.'),
(7, 108, 9, 164, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 'wa-naz''a yadahū fa-idhā hiya bayḍāʾu li-n-nāẓirīn', 'Elini çıkardı, bir de baktılar ki, o, görenler için bembeyaz kesilmişti.'),
(7, 109, 9, 164, 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ', 'qāla l-malaʾu min qawmi firʿawna ʾinna hādhā lasāḥirun ʿalīm', 'Firavun kavminin ileri gelenleri şöyle dediler: "Bu, gerçekten çok bilgili bir büyücüdür."'),
(7, 110, 9, 164, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ فَمَاذَا تَأْمُرُونَ', 'yurīdu an yukhricakum min arḍikum famādhā taʾmurūn', 'Sizi toprağınızdan çıkarmak istiyor. Ne yapmamı emredersiniz?'),
(7, 111, 9, 164, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'qālū ʾarhihī wa-ʾakhāhu wa-ʾarsil fī l-madāʾini ḥāshirīn', 'Dediler ki: "Onu ve kardeşini (bir süre) ertele (alıkoy) ve şehirlere toplayıcılar (gönder)!'),
(7, 112, 9, 164, 'يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍ', 'ya''tūka bikulli sāḥirin ʿalīm', 'Sana her türlü bilgili büyücüyü getirirler.'),
(7, 113, 9, 164, 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 'wa jāʾa s-saḥaratu firʿawna qālū ʾinna lanā la-ʾajran ʾin kunnā naḥnu l-ḡālibīn', 'Sihirbazlar Firavun''a gelip dediler ki: Eğer galip gelirsek bize bir ücret mi var?'),
(7, 114, 9, 164, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', 'qāla naʿam wa-ʾinnakum la-mina l-muqarrabīn', 'Dedi ki: "Evet! Ve şüphesiz siz (bana) yaklaştırılanlardan olacaksınız."'),
(7, 115, 9, 164, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', 'qālū yā Mūsā immā an tulqiya wa immā an nakūna naḥnu l-mulqīna', 'Onlar şöyle dediler: "Ey Musa! Sen mi (önce) atmak istersin, yoksa biz mi atalım?"'),
(7, 116, 9, 164, 'قَالَ أَلْقُوا۟ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ', 'qāla ʾalqū falammā ʾalqaw saḥarū ʾaʿyuna n-nāsi wastarhabūhum wajāʾū bisiḥrin ʿaẓīmin', 'Musa dedi ki: ''Siz atın!'' Onlar atınca, insanların gözlerini büyülediler, onları korkuttular ve çok büyük bir sihir getirdiler.'),
(7, 117, 9, 164, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 'wa-awḥaynā ʾilā mūsā ʾan ʾalqi ʿaṣāk fa-ʾiḏā hiya talqafu mā yaʾfikūn', 'Ve Musa''ya, "Asânı at!" diye vahyettik. Bir de ne görsünler, o (asa), onların uydurmakta olduklarını yutuyor!'),
(7, 118, 9, 164, 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', 'Fevak''al-hakku Ve batale ma kânû ya''melûn', 'Nihayet hak yerini buldu ve onların bütün yapageldikleri şeyler batıl oldu.'),
(7, 119, 9, 164, 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ', 'fa ġulibū hunālika wa nqaleabū ṣāġirīn', 'İşte orada yenilgiye uğradılar ve küçük düşmüş olarak geri döndüler.'),
(7, 120, 9, 164, 'وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'wa-ulqiya as-saḥaratu sājidīn', 'Ve sihirbazlar secde ederek yere atıldılar.'),
(7, 121, 9, 165, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 'qālū ʾāmannā birabbi l-ʿālamīn', 'Dediler ki: "Âlemlerin Rabbine inandık."'),
(7, 122, 9, 165, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'rabbī mūsā wa hārūn', 'Musa ve Harun''un Rabbi.'),
(7, 123, 9, 165, 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّ هَٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا فَسَوْفَ تَعْلَمُونَ', 'qāla firʿawnu āmantum bihi qabla an ʾādhana lakum ʾinna hādhā lamakrun makartumūhu fī l-madīnati litukhrijū minhā ʾahalahā fasawfa taʿlamūn', 'Firavun dedi ki: Size izin vermeden önce ona iman mı ettiniz? Şüphesiz bu, sizin şehir halkını oradan çıkarmak için kurduğunuz bir tuzaktır. Yakında bileceksiniz!'),
(7, 124, 9, 165, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 'leʾuqaṭṭiʿanna ʾaydīyakum waʾarjulakum min khilāfin thumma leʾuṣallibannakum ʾajmaʿīna', 'Andolsun ki ellerinizi ve ayaklarınızı çaprazlama keseceğim, sonra da hepinizi mutlaka asacağım.'),
(7, 125, 9, 165, 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'qālū ʾinna ʾilā rabbina munqalibūn', 'Dediler ki: "Biz Rabbimize döneceğiz."'),
(7, 126, 9, 165, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ', 've mā tanqimu minnā illā an āmannā bi-ʾāyāti rabbina lammā jāʾatnā rabbanā ʾafrig ʿalaynā ṣabran ve tawaffanā muslimīn', 'Oysa bizi, Rabbimizin, bize geldiği zaman âyetlerine inandığımızdan başka bir sebeple ayıplamıyorsun. Rabbimiz! Üzerimize sabır dök (ver) ve bizi müslümanlar olarak (canımızı) al.'),
(7, 127, 9, 165, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ', 'waqāla l-malau min qawmi firʿawna ʾataḏaru mūsā waqawmahu līufsidū fī l-ʾarḍi wayaḏaraka waʾālihata ka qāla sanaqattilu ʾabnāʾahum wanastaḥyī nisāʾahum waʾinnanā fawqahum qāhirūna', 'Firavun kavminin ileri gelenleri dediler ki: "Musa''yı ve kavmini yeryüzünde bozgunculuk yapmaları ve seni ve ilahlarını bırakmaları için mi bırakacaksın?" (Firavun) dedi ki: "Onların erkek çocuklarını öldüreceğiz ve kadınlarını sağ bırakacağız. Şüphesiz biz onların üstünde kahrediciyiz."'),
(7, 128, 9, 165, 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'qāla mūsā liqawmihi istaʿīnū billāhi waṣbirū ʾinna l-ʾarḍa lillāhi yūriṯuhā man yašāʾu min ʿibādihī wa-l-ʿāqibatu lil-muttaqīna', 'Musa, kavmine şöyle dedi: Allah''tan yardım dileyin ve sabredin. Şüphesiz yeryüzü Allah''ındır. Kullarından dilediğine onu miras bırakır. Sonuç, Allah''a karşı gelmekten sakınanlarındır.'),
(7, 129, 9, 165, 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', 'qālū ʾūḏīnā min qabli ʾan taʾtiyanā wa-min baʿdi mā jiʾtanā qāla ʿasā rabbukum ʾan yuhlika ʿaduwwakum wa-yastahlikafakum fī l-ʾarḍi fa-yanẓura kayfa taʿmalūn', 'Dediler ki: "Sen bize gelmeden önce de, bize geldikten sonra da eziyete uğradık." (Musa) dedi ki: "Rabbiniz düşmanınızı helak etsin ve onların yerine sizi yeryüzüne yerleştirip nasıl davranacağınıza baksın."'),
(7, 130, 9, 165, 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', 'Ve lekad eḣażnâ âle fir''avne bi''s-sinîne ve naksin mine''s-semerâti le''allehum yeẕẕekkerûn', 'Andolsun ki biz, Firavun ailesini, belki öğüt alırlar diye yıllarca süren kıtlık ve ürün eksikliği ile yakaladık.'),
(7, 131, 9, 166, 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'fa-iḏā ǧāʾathumu l-ḥasanatu qālū lanā hāḏihi wa-in tuṣibhum sayyiʾatun yaṭṭayyarū bi-Mūsā wa-man maʿahu ʾalā ʾinnamā ṭāʾiruhum ʿinda Llāhi wa-lākinna ʾaktharahum lā yaʿlamūn', 'Onlara bir iyilik gelince, "Bu bizim hakkımızdır" derler. Başlarına bir kötülük gelince de, bunu Musa ve onunla birlikte olanların uğursuzluğuna yorarlardı. Haberiniz olsun ki, uğursuzlukları Allah katındandır. Fakat onların çoğu bunu bilmezler.'),
(7, 132, 9, 166, 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'wa qālū mahmā taʾtinā bihi min ʾāyatin li-tasḥaranā bihā famā naḥnu laka bi-muʾminīn', 'Ve dediler ki: ''Bize sihir yapmak için her ne kadar bir ayet getirirsen getir, biz sana inanacak değiliz.'''),
(7, 133, 9, 166, 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍ مُّفَصَّلَٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', 'fa-arsalnā ʿalayhimu ṭ-ṭūfāna wa-l-jarāda wa-l-qummala wa-ḍ-ḍafādiʿa wa-d-dama ʾāyātin mufaṣṣalātin fa-stakbarū wa-kānū qawman mujrimīna', 'Bunun üzerine onlara Tufan''ı, çekirgeyi, haşerâtı, kurbağaları ve kanı ayrı ayrı mucizeler olarak gönderdik. Yine de büyüklük tasladılar ve suçlu bir kavim oldular.'),
(7, 134, 9, 166, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', 'wa lammā waqaʿa ʿalayhimu r-rijzu qālū yā Mūsā dʿu lanā Rabbaka bimā ʿahida ʿindaka laʾin kashafta ʿannā r-rijza la nuʾminanna laka wa lanursilanna maʿaka Banī Isrāʾīla', 'Ne zaman ki üzerlerine azap çöktü, dediler ki: ''Ey Musa! Bizim için Rabbine, senin nezdinde bulunan ahdi (veya sana verdiği sözü) ile dua et. Eğer bu azabı bizden kaldırırsan, andolsun ki sana inanacağız ve seninle birlikte İsrailoğullarını göndereceğiz.'''),
(7, 135, 9, 166, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', 'felemmā keşefnā ʿanhumu r-ricza ilā ʾegeletin hum bāliġūhu iḏā hum yankuṯūn', 'Onlardan azabı, ulaştıkları bir süreye kadar kaldırdığımızda, hemen yine ahitlerini bozuyorlardı.'),
(7, 136, 9, 166, 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'fa-ntaqamnā minhum fa-agraqnāhum fī l-yammi bi-annahum kadhthabū bi-āyātinā wa-kānū ʿanhā ghāfilīn', 'Böylece onlardan intikam aldık da, ayetlerimizi yalanlamaları ve onlardan gafil olmaları yüzünden onları denizde boğduk.'),
(7, 137, 9, 166, 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', 'wa-awraṯnā l-qawma l-laḏīna kānū yustaḍʿafūna mašāriqa l-arḍi wa-maġāribahā l-latī bāraknā fīhā wa-tamat kalimat rubbika l-ḥusnā ʿalā banī isrāʾīla bimā ṣabarū wa-dammarnā mā kāna yaṣnaʿu firʿawnu wa-qawmuhū wa-mā kānū yaʿrišūn', 'Ve Mısır''da hor ve hakir görülen kavme, bereketlendirdiğimiz yerin doğularını da batılarını da miras bıraktık. Böylece Rabbinin güzel kelimesi İsrailoğulları''nın sabretmeleri sebebiyle tamamlandı. Ve Firavun ile kavminin yapmakta oldukları şeyleri ve onların kurmakta oldukları şeyleri de yerle bir ettik.'),
(7, 138, 9, 167, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًا كَمَا لَهُمْ ءَالِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ', 'wa-jāwaznā bi-banī ʾisrāʾīla l-baḥra fa-ʾataw ʿalā qawmin yaʿkufūna ʿalā ʾaṣnāmin lahum qālū yā-mūsā ʾijʿal lanā ʾilāhan kamā lahum ʾālihah qāla ʾinnakum qawmun tajhalūn', 'Nihayet İsrailoğullarını denizden geçirdik. (Orada) kendilerine ait birtakım putlara tapan bir topluluğa geldiler. (Onlar,) "Ey Musa! Onların ilahları olduğu gibi, bize de bir ilah yap!" dediler. (Musa,) "Siz gerçekten cahillik etmekte olan bir topluluksunuz!" dedi.'),
(7, 139, 9, 167, 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'ʾinna hāʾulāʾi mutabarun mā hum fīhi wa-bāṭilun mā kānū yaʿmalūn', 'Şüphesiz ki bunlar, içinde bulundukları şeyden ötürü helak olmuşlardır ve yapmakta oldukları şeyler de batıldır.'),
(7, 140, 9, 167, 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ', 'qāla ʾaḡayra ḷḷāhi ʾabḡīkum ʾilāhan wa-huwa faḍḍalakum ʿalā l-ʿālamīn', 'Allah şöyle dedi: "Sizi alemlere üstün kılan O iken, Allah''tan başka bir ilah mı arayayım size?"'),
(7, 141, 9, 167, 'وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'wa-ʾidh ʾanjaynākum min ʾāli firʿawna yasūmūnakum sūʾa l-ʿadhābi yuqattilūna ʾabnāʾakum wa-yastaḥyūna nisāʾakum wa-fī dhālikum balāʾun min rabbikum ʿaẓīmun', 'Hani sizi Firavun ailesinden kurtarmıştık. Onlar sizi kötü azaba uğratıyorlar, erkek çocuklarınızı kesiyor, kadınlarınızı diri bırakıyorlardı. İşte bunlarda Rabbinizden büyük bir imtihan vardı.'),
(7, 142, 9, 167, 'وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةً وَأَتْمَمْنَٰهَا بِعَشْرٍ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', 'wa wāʿadnā mūsā thalāthīna laylatan wa atmamnāhā bi ʿashrin fatamma mīqātu rabbihi ʾarbaʿīna laylah wa qāla mūsā li-ʾakhīhi hārūna ʾkhlunfī fī qawmī wa ʾaṣliḥ wa lā tattabiʿ sabīla l-mufsidīn', 'Biz Musa ile otuz geceye sözleştik ve bu süreyi on gece ile tamamladık. Böylece Rabbinin belirlediği süre kırk geceye tamamlandı. Musa, kardeşi Harun''a şöyle dedi: "Bana karşı yerine geç, toplumumda ıslah edici ol ve bozguncuların yoluna uyma."'),
(7, 143, 9, 167, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', 'wa lammā jāʾa mūsā limīqātinā wa kallamahū rabbuhū qāla rabbi ʾarinī ʾanẓur ʾilayka qāla lan tarānī wa lākin i nẓur ʾilā l-jabali fa ʾini staqarra makānahū fa sawfa tarānī fa lammā tajallā rabbuhū lil-jabali jaʿalahū dakkā wa kharra mūsā ṣaʿiqā fa lammā ʾafāqa qāla subḥānaka tubtu ʾilayka wa ʾanā ʾawwalu l-muʾminīn', 'Nihayet Musa tayin ettiğimiz vakte geldiğinde ve Rabbi onunla konuştuğunda, şöyle dedi: "Rabbim! Bana (kendini) göster, sana bakayım." (Rabbi): "Beni asla göremezsin. Fakat şu dağa bak; eğer o yerinde kalabilirse, sen de beni göreceksin." Rabbi dağa tecelli edince, onu un ufak etti ve Musa da baygın düştü. Kendine geldiğinde: "Sen yücesin! Sana tövbe ettim ve ben mü''minlerin ilkiyim" dedi.'),
(7, 144, 9, 168, 'قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 'qāla yā mūsā ʾinnī ʾiṣṭafaytuka ʿalā n-nāsi birisālātī wa bikalāmī fakhudh mā ʾātaytuk wa kun mina sh-shākirīn', 'Allah şöyle buyurdu: "Ey Musa! Sana risaletimle ve kelamımla hitap etmekle seni insanlar üzerine seçtim. Sana verdiğimi al ve şükredenlerden ol."'),
(7, 145, 9, 168, 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ', 'wa katabnā lahu fī l-ʾalwāḥi min kulli šayʾin mawʿiẓatan wa tafṣīlan li-kulli šayʾin fa-ḵuḏhā bi-quwwatin wa-ʾmur qawmaka yaʾḵuḏū bi-ʾaḥsani-hā sa-ʾurīkum dāra l-fāsiqīn', 'Ve ona levhalar içinde her şeyden bir öğüt ve her şeyin de ayrı ayrı açıklamasını yazdık. ''Onları kuvvetle tut ve kavmine de en güzel olanını almalarını emret!'' Size fasıkların yurdunu göstereceğiz.'),
(7, 146, 9, 168, 'سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'sa''aṣrifu ʿan ʾāyātiyya lladhīna yatakabbarūna fī l-ʾarḍi bighayri l-ḥaqqi wa-ʾin yaraw kulla ʾāyatin lā yuʾminū bihā wa-ʾin yaraw sabīla r-rušdi lā yattakhidhūhu sabīlan wa-ʾin yaraw sabīla l-ḡayyi yattakhidhūhu sabīlan ḏālika bi-ʾannahum kaḏḏabū bi-ʾāyātinā wa-kānū ʿanhā ḡāfilīna', 'Yeryüzünde haksız yere büyüklük taslayanları ayetlerimden uzaklaştıracağım. Onlar her bir mucizeyi görseler de ona inanmazlar. Doğru yolu görseler de onu yol edinmezler. Azgınlık yolunu görseler de onu yol edinirler. Bu böyledir, çünkü onlar ayetlerimizi yalanladılar ve onlardan gafil oldular.'),
(7, 147, 9, 168, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْءَاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'wa-lladhīna kadhdhabū bi-ʾāyātinā wa-liqāʾi l-ʾākhirati ḥabiṭat ʾaʿmāluhum hal yujzawna ʾillā mā kānū yaʿmalūn', 'Ayetlerimizi ve ahirete kavuşmayı yalanlayanlara gelince, onların amelleri boşa gitmiştir. Onlar, yapmakta olduklarından başkasıyla mı cezalandırılacaklar?'),
(7, 148, 9, 168, 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ', 'wa-ttakhaḏa qawmu mūsā min baʿdihi min ḥuliyyi-him ʿijlan jasadāan lahu ḫuwārun ʾa-lam yaraw ʾannahu lā yukallimuhum wa-lā yahdīhim sabīlā wa-ttaxaḏūhu wa-kānū ẓālimīn', 'Musa''nın ardından kavmi, (o yokken) kendi ziynetlerinden, böğürmesi olan bir buzağı heykeli edindiler. O buzağının kendileriyle konuşmadığını ve onlara bir yol göstermediğini görmüyorlar mıydı? Yine de onu (tanrı) edindiler ve zalimlerden oldular.'),
(7, 149, 9, 168, 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'wa lammā suqiṭa fī ʾaydīhim wa raʾaw ʾannahum qad ḍallū qālū laʾin lam yarḥamnā rabbunā wa yaghfir lanā lanakūnan na mina l-khāsirīn', 'Elleri pişmanlıkla dolduğunda ve gerçekten sapmış olduklarını gördüklerinde, şöyle dediler: ''Andolsun ki, eğer Rabbimiz bize merhamet etmez ve bizi bağışlamazsa, mutlaka biz ziyana uğrayanlardan oluruz.'''),
(7, 150, 9, 169, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'wa lammā rajaʿa mūsā ʾilā qawmihī ghaḍbāna ʾasifā qāla biʾsamā khalaf-tumūnī min baʿdī ʾaʿajaltum ʾamra rabbikum wa ʾalqā ʾal-ʾalwāḥa wa ʾakhaḏa bi-raʾsi ʾaḫīhi yajurruhu ʾilayhi qāla ʾibna ʾumma ʾinna ʾl-qawma ʾstaḍʿafūnī wa kādū yaqtulūnanī fa-lā tušmit bī ʾl-ʾaʿdāʾa wa lā tajʿalnī maʿa ʾl-qawmi ʾaẓ-ẓālimīn', 'Musa, kavmine kızgın ve üzgün bir halde dönünce dedi ki: "Benden sonra yerime ne kötü bir halef oldunuz! Rabbimin emrini çabuk mu yerine getirdiniz?" (Telif levhalarını) attı ve kardeşinin başından tutup kendine doğru çekmeye başladı. (Kardeşi) dedi ki: "Ey annemin oğlu! Bu kavim beni zayıf düşürdü, neredeyse beni öldüreceklerdi. Onun için bana düşmanları güldürme ve beni zalimler topluluğu ile birlikte kılma!"'),
(7, 151, 9, 169, 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'qāla rabbi ʾiġfir lī wa li-ʾaẖī wa ʾadẖilnā fī raḥmatik wa ʾanta ʾarḥamu ʾar-rāḥimīn', 'Rabbim! Beni ve kardeşimi bağışla. Bizi rahmetine dahil et. Sen merhametlilerin en merhametlisisin.'),
(7, 152, 9, 169, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', 'ʾinna lladhīna t-takhadhū l-ʿijla sayanaluhum ghaḍabun min rabbihim wa dhillatun fī l-ḥayāti d-dunyā wa kadhālika najzī l-muftarīn', 'Şüphesiz buzağıyı (tanrı edinenler) kendilerine Rablerinden bir gazap ve dünya hayatında bir alçaklık isabet edecektir. İşte biz, yalan uyduranları böyle cezalandırırız.'),
(7, 153, 9, 169, 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', 'wa-lladhīna ʿamilū s-sayyiʾāti thumma tābū min baʿdihā wa-ʾāmanū ʾinna rabbaka min baʿdihā la-ghafūrun raḥīmun', 'Kötülükleri işleyip de sonra tövbe edenler ve iman edenler, şüphesiz Rabbin, bu (tövbe ve imanlarından) sonra elbette bağışlayandır, merhamet edendir.'),
(7, 154, 9, 169, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 'wa lammā sakata ʿan Mūsā l-ghaḍabu ʾakhaḏa l-ʾalwāḥa wa fī nuskhatihā hudan wa raḥmatun lilladhīna hum li-Rabbihim yarhabūna', 'Musa''nın öfkesi geçince, levhaları aldı. Levhaların içinde, Rab''lerinden korkanlar için bir hidayet ve bir rahmet de vardı.'),
(7, 155, 9, 169, 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَٰتِنَا فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ', 'wa-khtāra Mūsā qawmahu sabʿīna rajulan limīqātinā falammā ʾakhaḏathumu ʾr-rajfatu qāla rabbi law shiʾta ʾahlaktahum min qablu wa-ʾiyyā ʾatuhlikunā bimā faʿala ʾs-sufahāʾu minnā ʾin hiya ʾillā fitnatuka tuḍillu bihā man tashāʾu wa-tahdī man tashāʾu ʾanta waliyyunā fa-ġfir lanā wa-rḥamnā wa-ʾanta ḫayru ʾl-ġāfirīn', 'Musa, buluşma vakti için kavminden yetmiş adam seçti. Kendilerini sarsıntı (deprem) alınca dedi ki: "Rabbim! Dileseydin onları daha önce helak ederdin, bizi de mi yaptığımızdan ötürü helak edeceksin? Bu, Senin imtihanından başka bir şey değildir. Onunla dilediğini saptırırsın, dilediğini de doğru yola iletirsin. Sen bizim Mevlâmızsın. Artık bizi bağışla ve bize merhamet et! Sen bağışlayanların en iyisisin."'),
(7, 156, 9, 170, 'وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْءَاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ', 'wa-ktub lanā fī hādhihi ad-dunyā ḥasanatan wa-fī al-ʾākhirati ʾinnā hudnā ʾilayk qāla ʿadhābī ʾuṣību bihi man ʾashāʾu wa-raḥmatī wasiʿat kulla shayin fa-sa-ʾaktubuhā lilladhīna yattaqūna wa-yuʾtūna az-zakāta wa-lladhīna hum bi-ʾāyātinā yuʾminūn', 'Ve bize bu dünyada da iyilik, ahirette de iyilik yaz! Şüphesiz biz sana yöneldik." (Allah) buyurdu ki: "Azabıma dilediğimi uğratırım, rahmetim ise her şeyi kuşatmıştır. Onu, bana karşı gelmekten sakınanlara, zekâtı verenlere ve ayetlerimize iman edenlere yazacağım."'),
(7, 157, 9, 170, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'alladhīna yattabiʿūna r-rasūla n-nabiyya l-ummiyya lladhī yajidūnahū maktūban ʿindahum fī t-tawrāti wa-l-injīli yaʾmuruhum bi-l-maʿrūfi wa-yanhāhum ʿani l-munkari wa-yuḥillu lahumu ṭ-ṭayyibāti wa-yuḥarrimu ʿalayhimu l-khabāʾitha wa-yaḍaʿu ʿanhum iṣrahum wa-l-aḡlāla llatī kānat ʿalayhim fa-lladhīna ʾāmanū bihi wa-ʿazzarūhu wa-naṣarūhu wa-ttabaʿū n-nūra lladhī ʾunzila maʿahu ʾulāʾika humu l-mufliḥūna', 'Onlar, yanlarındaki Tevrat ve İncil''de yazılı buldukları, ümmî olan, okuma yazma bilmeyen o Rasul''e uyanlardır. O, onlara iyiliği emreder, onları kötülükten men eder, temiz şeyleri helâl, pis şeyleri haram kılar ve onların ağır yüklerini, üzerlerindeki zincirleri indirir. O''na iman edenler, O''na saygı gösterenler, O''na yardım edenler ve O''nunla birlikte indirilen nura uyanlar var ya, işte onlar kurtuluşa erenlerdir.'),
(7, 158, 9, 170, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', 'Qul yā ayyuhā n-nāsu innī rasūlu llāhi ilaykum jamīʿan Alladhī lahu mulku s-samāwāti wa-l-arḍi Lā ilāha illā huwa yuḥyī wa-yumītu Fa-āminū bi-llāhi wa-rasūlihi n-nabiyyi l-ummiyyi lladhī yuʾminu bi-llāhi wa-kalimātihi Wa-ttabiʿūhu laʿallakum tahtadūna', 'De ki: "Ey insanlar! Gerçekten ben, göklerin ve yerin mülkü elinde olan, O''ndan başka tanrı olmayan, hayat veren ve hayat alan Allah''ın size gönderdiği elçisiyim. Artık Allah''a ve O''nun elçisi olan, Allah''a ve O''nun kelimelerine inanan o Nebî''ye (Peygamber''e) iman edin ve ona uyun ki, doğru yolu bulasınız."'),
(7, 159, 9, 170, 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'wa min qawmi mūsā ummatun yahdūna bil-ḥaqqi wa bihi yaʿdilūn', 'Musa''nın kavminden, hakka (yönelerek) doğru yolu gösteren ve onunla adaletli davranan bir topluluk da vardı.'),
(7, 160, 9, 171, 'وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'waqaṭṭaʿnāhumu ʾithnatā ʿashrata ʾasbāṭan ʾuman waʾawḥaynā ʾilā mūsā ʾidhistasqāhu qawmuhu ʾani ḍrib biʿaṣāka lḥajar fānbajasat minhu ʾithnatā ʿashrata ʿaynan qad ʿalima kullu ʾunāsin mashrabehum waẓallalnā ʿalayhimu lġamāma waʾanzalnā ʿalayhimu lmanna wassalwā kulū min ṭayyibāti mā razaqnākum wamā ẓalamūnā walākin kānū ʾanfusahum yaẓlimūn', 'Onları on iki topluluğa ayırdık. Musa''nın kavmi kendisinden su isteyince ona, "Asânı taşa vur!" diye vahyettik. Derken taştan on iki pınar fışkırdı. Her topluluk kendi su alacağı yeri bildi. Onların üzerine de bulutla gölge yaptık ve onlara kudret helvası ile bıldırcın indirdik. "Size rızık olarak verdiklerimizin temiz olanlarından yiyin!" (dedik). Onlar bize zulmetmediler, fakat kendi nefislerine zulmediyorlardı.'),
(7, 161, 9, 171, 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ', 'wa-ʾiḏ qīla lahumu uskunū hāḏihi l-qarjata wa-kulū min-hā ḥayṯu šiʾtum wa-qūlū ḥiṭṭatun wa-d-xulū l-bāba sujjadan naḡfirlakum ḫaṭīʾātikum sanazīdu l-muḥsinīna', 'Onlara: "Bu şehre yerleşin ve dilediğiniz yerden yiyin; ''Affet'' deyin ve kapıdan secde ederek girin ki, hatalarınızı bağışlayalım. İyilik edenlerin iyiliğini de artıracağız" denildiği zaman...'),
(7, 162, 9, 171, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', 'fabaddala alladhīna ẓalamū minhum qawlan ghayra alladhī qīla lahum faarsalnā ʿalayhim rijzan minas-samāʾi bimā kānū yaẓlimūn', 'Onlardan zulmedenler, kendilerine söylenenden başka bir sözle değiştirdiler. Biz de onlara, zulmetmekte oldukları için gökten bir azap gönderdik.'),
(7, 163, 9, 171, 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', 'wa-sʾalhum ʿani l-qaryati llatī kānat ḥāḍirata l-baḥri iḏ yaʿdūna fī s-sabti iḏ taʾtīhim ḥītānuhum yawma sabtihim šurraʿan wa-yawma lā yasbitūna lā taʾtīhim kaḏālika nablūhum bimā kānū yafusqūna', 'Onlara, denizin kenarında bulunan ve Sebt (Cumartesi) günü azgınlık eden kasabayı sor. Onlara Sebt günlerinde, diğer günlerden farklı olarak, balıkları açıktan görünüp gelirlerdi. İşte biz, fasıklık yapmaları yüzünden onları böyle imtihan ediyorduk.'),
(7, 164, 9, 172, 'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', 'wa-ʾiḏ qālat ʾummatun min-hum lima taʿiẓūna qawman allāhu muhlīkuhum ʾaw muʿaḏḏibuhum ʿaḏāban šadīdan qālū maʿḏiratan ʾilā rabbikum wa-laʿallahum yattaqūna', 'Onlardan bir topluluk şöyle demişti: "Allah''ın helak edeceği veya şiddetli bir azapla azaplandıracağı bir kavme ne diye öğüt veriyorsunuz?" (Diğerleri) "Rabbinize karşı bir mazeret (doldurmak) ve belki de sakınırlar diye (öğüt veriyoruz)" dedi.'),
(7, 165, 9, 172, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', 'fe-lemmā nesū mā żukkirū bihī encaynā-lleżīne yenhavne ʿani-ssūʾi ve-eḫaḏnā-lleżīne ẓalamū bi-ʿaẕābin baʾīsin bimā kānū yefsuqūne', 'Onlar, kendilerine hatırlatılanı unuttuklarında, fenalıktan men edenleri kurtardık ve zulmedenleri, fasık olmaları yüzünden, şiddetli bir azapla yakaladık.'),
(7, 166, 9, 172, 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 'fe lemmā ''atev ''ammā nuhū ''anhu ''ulnā lehum kūnū qiradeten ḥāsī''īn', 'Ne var ki onlar, kendilerine yasaklanan şeyden vazgeçmeyince kendilerine, "Aşağılık maymunlar olun!" dedik.'),
(7, 167, 9, 172, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ', 'wa-ʾidh taʾaḏḏana rabbuka layabʿaṯanna ʿalayhim ʾilā yawmi l-qiyāmati man yasūmuhum sūʾa l-ʿaḏābi ʾinna rabbaka lasarīʿu l-ʿiqābi wa-ʾinnahu la-ḡafūrun raḥīmun', 'Hani Rabbin, kıyamet gününe kadar onlara mutlaka azabın en kötüsünü uygulayacak kimseleri göndereceğini bildirmişti. Şüphesiz Rabbin cezalandırmada çok hızlıdır. Ve şüphesiz O, çok bağışlayıcıdır, çok merhametlidir.'),
(7, 168, 9, 172, 'وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًا مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', 'wa qaṭṭaʿnāhum fī l-arḍi umaman minhumu ṣ-ṣāliḥūna wa minhum dūna dhālika wa balawnāhum bil-ḥasanāti was-sayyiʾāti laʿallahum yarjiʿūna', 'Onları yeryüzünde ümmetlere ayırdık. İçlerinde salih olanlar da vardı, böyle olmayanlar da. Onları iyiliklerle ve kötülüklerle imtihan ettik ki, (belki) dönerler.'),
(7, 169, 9, 172, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ وَٱلدَّارُ ٱلْءَاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', 'faḫalafa min-baʿdihim ḫalfun waritū l-kitāb yaʾḫuḏūna ʿaraḍa hāḏā l-ʾadnā wa-yaqūlūna sayuġfaru lanā wa-in yaʾtihim ʿaraḍun miṯluhū yaʾḫuḏūh ʾalam yuʾḫaḏ ʿalayhim mīṯāqu l-kitābi ʾan lā yaqūlū ʿalā llāhi ʾillā l-ḥaqqa wa-darasū mā fīh wa-d-dāru l-ʾāḫirat khayrun li-llaḏīna yattaqūn ʾafalā taʿqilūn', 'Ancak onların ardından, Kitab''a vâris olan, bu dünyanın geçici menfaatini alan ve "Bize mağfiret olunacaktır" diyen bir nesil geldi. Kendilerine onun gibi bir geçici menfaat gelse, onu da alırlar. Kendilerinden Kitap (Tevrat) ahdi alınmadı mı ki, Allah hakkında haktan başkasını söylemeyeceklerdi? Ve onlar, Kitap''ta olanı da okudular. Ahiret yurdu, Allah''tan korkanlar için daha hayırlıdır. Hâlâ akıl etmiyor musunuz?'),
(7, 170, 9, 172, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', 'wa-lladhīna yumsikūna bi-l-kitābi wa-aqāmū ṣ-ṣalāta ʾinnā lā nuḍīʿu ʾajra l-muṣliḥīna', 'Kitaba sarılanlar ve namazı kılanlar ise (bilmelidirler ki) biz, güzel işler yapanların ecrini zâyi etmeyiz.'),
(7, 171, 9, 173, 'وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'wa-ʾiḏu natagnā l-jabala fawqahum ka-ʾannahu ẓullatun wa-ẓannū ʾannahu wāqiʿun bihim ḵuḏū mā ʾātaynākum bi-quwwatin wa-ḏkurū mā fīhi laʿallakum tattaqūna', 'Hani dağ (parçasını) üzerlerine bir gölge gibi kaldırmıştık da, zalimler topluluğu oldukları için, onun kendilerine düşeceğini sanmışlardı. (Onlara şöyle denilmişti:) "Size verdiğimizi kuvvetle tutun ve içinde olanı hatırlayın ki, korunabilesiniz."'),
(7, 172, 9, 173, 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا۟ بَلَىٰ شَهِدْنَآ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', 'wa-ʾiḏ ʾaḵaḏa rabbuka min banī ʾāḏama min ẓuhūrihim ḏurriyyatahum wa-ʾašhadahum ʿalā ʾanfusihim ʾalastu birabbikum qālū balā šahidnā ʾan taqūlū yawma l-qiyāmati ʾinnā kunnā ʿan hāḏā ġāfilīn', 'Hani Rabbin, Âdemoğullarının sırtlarından zürriyetlerini almış ve onları kendi nefislerine karşı şöyle ikrar ettirmişti: "Ben sizin Rabbiniz değil miyim?" Onlar da: "Evet, şahidiz!" demişlerdi. (Bunu) kıyamet günü: "Biz bundan habersizdik" demeyesiniz diye (yapmıştı).'),
(7, 173, 9, 173, 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', 'aw taqūlū innamā ashraka ʾābāʾunā min qablu wa kunnā dhurriyyatan min baʿdihim ʾafa tuhlikunā bimā faʿala l-mubṭilūn', 'Yoksa, ''Bizden önceki atalarımız şirk koşmuştu, biz de onlardan sonra gelen bir nesil olduk. Hatalı davrananların yaptıklarından ötürü bizi helak mi edeceksin?'' demeyesiniz.'),
(7, 174, 9, 173, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 'wa kadhalika nufassilu l-āyāti wa laʿallahum yarjiʿūna', 'İşte böylece ayetleri açıklıyoruz ki, belki de dönerler.'),
(7, 175, 9, 173, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', 'wa-tlu ʿalayhim nabaʾa alladhī ātaynāhu ʾāyātinā fa-nsalakha minhā fa-ʾatbaʿahu ʾl-shayṭānu fa-kāna mina ʾl-ghāwīna', 'Onlara, kendisine âyetlerimizi verdiğimiz, fakat onlardan sıyrılıp çıktığı, derken şeytanın peşine takıldığı ve böylece azgınlardan olduğu kimsenin haberini oku.'),
(7, 176, 9, 173, 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'Ve lev şiʾnā lerafaʿnāhu bihā velâkinnehû eḫlede ilel-arḍi vettebeʿa hevâhu femes̱eluhû kemes̱elil-kelbi in taḥmil ʿaleyhi yelhes̱ ev tetruk-hu yelhes̱ ẕâlike mes̱elul-ḳavmil-leẕîne keẕẕebû biʾâyâtinâ faḳṣuṣil-ḳaṣaṣa leʿallehum yetefekkerûn', 'Eğer dileseydik, onu o (ayetler) ile yüceltirdik. Fakat o, yere saplandı ve kendi hevesine uydu. Onun durumu, üzerine varsan da dilini sarkıtıp soluyan, kendi haline bıraksan da dilini sarkıtıp soluyan köpeğin durumu gibidir. İşte bu, ayetlerimizi yalanlayan kavmin misalidir. Kıssaları anlat; belki düşünürler.'),
(7, 177, 9, 173, 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', 'sāʾa mathalan al-qawmu alladhīna kadhdhabū bi-ʾāyātinā wa-ʾanfusahum kānū yaẓlimūn', 'Ayetlerimizi yalanlayan ve kendilerine zulmeden kimseler ne kötü bir misaldir!'),
(7, 178, 9, 173, 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'man yahdi allāhu fa-huwa l-muhtadī wa-man yuḍlil fa-ʾulāʾika humu l-khāsirūn', 'Allah''ın hidayete erdirdiği kimse doğru yolu bulmuştur. Kimi de saptırırsa, işte onlar ziyana uğrayanların ta kendileridir.'),
(7, 179, 9, 174, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'Ve lekad zera''nâ li-cehenneme kesîran mine''l-cinni ve''l-insi Lehum kulûbun lâ yefkahûne bihâ ve lehum a''yunun lâ yubsırûne bihâ ve lehum âzânun lâ yesme''ûne bihâ Ulâike ke''l-en''âmi bel hum edallu Ulâike humu''l-gâfilûn', 'Andolsun ki cin ve insanlardan birçoğunu cehennem için yarattık. Onların kalpleri vardır, onunla anlamazlar; gözleri vardır, onunla görmezler; kulakları vardır, onunla işitmezler. İşte onlar hayvanlar gibidirler, hatta daha da şaşkındırlar. İşte onlar gafillerin ta kendileridir.'),
(7, 180, 9, 174, 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', 'wa lil-lāhi l-asmāʾu l-ḥusnā fa-dʿūhu bihā wa dharū l-ladhīna yulḥidūna fī ʾasmāʾihī sayujzawna mā kānū yaʿmalūn', 'En güzel isimler Allah''ındır. O halde O''na o güzel isimlerle dua edin. O''nun isimleri hakkında gerçeği eğip bükenleri bırakın. Onlar yapmakta oldukları yüzünden yakında cezalandırılacaklardır.'),
(7, 181, 9, 174, 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'wa-mimman khalaqnā ummatun yahdūna bil-ḥaqqi wa-bihi yaʿdilūn', 'Yarattıklarımızdan, hakka (ve hakikate) yönelip onlarla adalet gösteren bir ümmet de vardır.'),
(7, 182, 9, 174, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'wa-lladhīna kadhdhabū bi-ʾāyātinā sanastadrijuhum min ḥaythu lā yaʿlamūn', 'Ayetlerimizi yalanlayanları, bilmedikleri bir yerden yavaş yavaş helaka yaklaştıracağız.'),
(7, 183, 9, 174, 'وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ', 'wa-umlī lahum ʾinna kaydī matīn', 'Onlara mühlet veririm. Şüphesiz benim tuzağım (kurduğum plan) çetindir.'),
(7, 184, 9, 174, 'أَوَلَمْ يَتَفَكَّرُوا۟ مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ', 'awalam yatafakkarū mā biṣāḥibihim min jinnah in huwa illā naẓīrun mubīn', 'Onlar, arkadaşlarında bir delilik olmadığını hiç düşünmediler mi? O, ancak apaçık bir uyarıcıdır.'),
(7, 185, 9, 174, 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 'E-ve lem yenẓurū fī m-m-l-kūti s-s-māwāti w-l-ʾarḍi wa mā x-l-qa llāhu m-n šayʾin Wa ʾan ʿasā ʾan yakūna qadi ʾ-q-t-r-b-a ʾ-j-luhum Fa-bi-ʾayyi ḥadīṯin baʿd-ahū yuʾminūn', 'Onlar, göklerin ve yerin melekûtuna (mülküne, saltanatına) ve Allah''ın yarattığı herhangi bir şeye bakmadılar mı? Ve belki de ecellerinin (ömürlerinin sonunun) yaklaşmış olabileceği ihtimalini düşünmediler mi? O halde ondan (Kur''an''dan) sonra hangi söze inanırlar?'),
(7, 186, 9, 174, 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'man yuḍlili llāhu falā hādiya lahū wayadheruhum fī ṭughyānihim yaʿmahūn', 'Allah''ın saptırdığı kimseye doğru yolu gösteren bulunmaz. Ve onları kendi azgınlıkları içinde şaşkın bir halde bırakır.'),
(7, 187, 9, 174, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'yas''alūnaka ''ani s-sā''ati ayyāna mursāhā qul innamā ''ilmuhā ''inda rabbī lā yucellīhā liwaqtihā illā huw thaqulat fī s-samāwāti wa-l-''arḍi lā ta''tīkum illā baghtatan yas''alūnaka ka''annaka ḥafiyyun ''anhā qul innamā ''ilmuhā ''inda llāhi wa-lākinna akthara n-nāsi lā ya''lamūn', 'Sana o saati sorarlar: "Onun demir atması ne zaman?" De ki: "Onun ilmi Rabbimin katındadır. Vaktinde ancak O açığa çıkarır. Göklerde ve yerde o (kıyamet) pek ağır bastı. O size ancak ansızın gelir." Sanki sen ondan haberdarmışsın gibi sana sorarlar. De ki: "Onun ilmi ancak Allah''ın katındadır, fakat insanların çoğu bilmezler."'),
(7, 188, 9, 175, 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ', 'qul lā amliku linafsī nafʿan wa lā ḍar ran ʾillā mā šāʾa ʾllāhu wa law kuntu ʾaʿlamu l-ḡayba la-stakṯartu mina l-ḵayri wa mā massaniyya s-sūʾu ʾin ʾanā ʾillā naḏīrun wa bašīrun li-qawmin ʾyūʾminūna', 'De ki: Ben kendi kendime ne bir fayda ne de bir zarar verebilirim. Allah''ın dilediği müstesna. Eğer ben gaybı bilseydim, elbette daha çok hayır elde etmek isterdim ve bana fenalık dokunmazdı. Ben sadece iman eden bir topluluk için bir uyarıcı ve müjdeleyiciyim.'),
(7, 189, 9, 175, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'huwa lladhī khalaqakum min nafsiv wāḥidatiw wa jaʿala minhā zawjahā liyaskuna ilayhā falammā taghashshāhā ḥamalat ḥamlan khafīfan famarrat bihi falammā athqalat daʿawā llāha rabbahumā laʾin ātaytanā ṣāliḥal lanakūnan na mina sh-shākirīn', 'O, sizi tek bir nefisten yaratan ve eşini ondan (bir parça olarak) var edendir; eşiyle bir araya geldiğinde, eşi (ona) hafif bir yük yüklenir ve (yüküyle) bir müddet devam eder. Nihayet eşi ağırlaştığında, ikisi de Rableri olan Allah''a dua ederler: ''Andolsun ki bize salih (bir evlat) verirsen, mutlaka şükredenlerden oluruz.'''),
(7, 190, 9, 175, 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'Fe lemmā āthāhumā ṣāliḥan Jaʿalā lahū shurakāʾ fīmā āthāhumā Fe teʿālā Allāhu ʿammā yushrikūn', 'Allah onlara salih (bir evlat) verince, verdiği şeyler hususunda O''na ortaklar koştular. Allah onların ortak koştukları şeylerden yücedir.'),
(7, 191, 9, 175, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ', 'ʾayušrikūn mā lā yaḫluqu šayʾan wa hum yuḫlaqūn', 'Onlar, kendileri yaratıldığı halde hiçbir şey yaratamayan şeyleri Allah''a ortak mı koşuyorlar?'),
(7, 192, 9, 175, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 'wa-lā yastaṭīʿūna lahum naṣran wa-lā anfusahum yanṣurūna', 'Onlara yardım etmeye güç yetiremezler ve kendilerine de yardım edemezler.'),
(7, 193, 9, 175, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ', 'wa-in tadʿūhum ilā l-hudā lā yattabiʿūkum sawāʾun ʿalaykum a-daʿawtumūhum am antum ṣāmitūn', 'Onları doğru yola çağırsanız sizi izlemezler. Onlara dua etseniz de siz sessiz kalsanız da sizin için birdir.'),
(7, 194, 9, 175, 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'ʾinna lladhīna tadʿūna min dūni llāhi ʿibādun ʾamthālukum fādʿūhum falyastajībū lakum ʾin kuntum ṣādiqīna', 'Şüphesiz ki Allah''tan başka taptıklarınız da sizin gibi kullardır. Eğer doğru sözlüler iseniz, haydi onları çağırın da size icabet etsinler!'),
(7, 195, 9, 175, 'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 'ʾalahum ʾarjulun yamshūna bihā ʾam lahum ʾaydin yabṭishūna bihā ʾam lahum ʾaʿyunun yubṣirūna bihā ʾam lahum ʾādhānun yasmaʿūna bihā quli ʾdʿū shurakāʾakum thumma kīdūni falā tunẓirūni', 'Yoksa onların, kendileriyle yürüdükleri ayakları mı var? Yahut onların, kendileriyle tuttukları elleri mi var? Yahut onların, kendileriyle gördükleri gözleri mi var? Yahut onların, kendileriyle işittikleri kulakları mı var? De ki: ''Ortaklarınızı çağırın, sonra bana tuzak kurun ve bana göz bile açtırmayın.'''),
(7, 196, 9, 176, 'إِنَّ وَلِۦِّىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ', 'inna walīyya allāhu alladhī nazzala al-kitāb wa huwa yatawallā aṣ-ṣāliḥīn', 'Şüphesiz benim velim Kitab''ı indiren Allah''tır. O, salihleri veli edinir.'),
(7, 197, 9, 176, 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 'wa-lladhīna tadʿūna min dūnihi lā yastaṭīʿūna naṣrakum walā ʾanfusahum yanṣurūn', 'Onun (Allah''ın) peşinden taptıklarınız, size yardım etmeye güç yetiremezler; kendi kendilerine bile yardım edemezler.'),
(7, 198, 9, 176, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', 'wa-ʾin tadʿūhum ʾilā al-hudā lā yasmaʿū wa-tarāhum yanẓurūna ʾilayka wa-hum lā yubṣirūna', 'Onları doğru yola çağırsanız işitmezler. Onları sana bakar gibi görürsün, halbuki onlar görmezler.'),
(7, 199, 9, 176, 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ', 'khudh il-ʿafwa wa-mur bil-ʿurfi wa-aʿriḍ ʿanil-jāhilīn', 'Affet, örfü emret ve cahillerden yüz çevir.'),
(7, 200, 9, 176, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', 'wa-immā yanzagannaka mina sh-shayṭāni nazġun fa-staʿiḏ bi-llāhi ʾinnahu samīʿun ʿalīmun', 'Eğer seni şeytandan bir kışkırtma dürtüklerse, hemen Allah''a sığın. Şüphesiz O, hakkıyla işitendir, bilendir.'),
(7, 201, 9, 176, 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', 'ʾinna lladhīna ttaqaw ʾidhā massahum ṭāʾifun mina shshayṭāni tadhakkarū faʾidhā hum mubiṣirūna', 'Şüphesiz takva sahipleri, kendilerine Şeytan''dan bir vesvese dokunduğunda, Allah''ı hatırlayıp hemen gerçeği görenler olurlar.'),
(7, 202, 9, 176, 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', 'wa-ʾikhwānuhum yamuddūnahum fī l-ḡayy ṯumma lā yuqṣirūn', 'Onların kardeşleri de onları azgınlıkta sürüklerler, sonra da geri durmazlar.'),
(7, 203, 9, 176, 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ', 'wa ʾiḏā lam taʾtihim bi-ʾāyatin qālū lawlā ǧtadaytahā qul ʾinnamā ʾattabiʿu mā yūḥā ʾilayya min rabbī hāḏā baṣāʾiru min rabbikum wa-hudan wa-raḥmatun li-qawmin yuʾminūna', 'Onlara bir ayet (delil) gelmediği zaman: "Neden bir ayet getirmedin?" derler. De ki: "Ben ancak bana Rabbimden vahyolunana uyarım. Bu (Kur''an), Rabbinizden gelen basiretler (açık deliller), iman eden bir topluluk için de yol gösterici ve rahmettir."'),
(7, 204, 9, 176, 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 'wa-idhā quriʾa l-qurʾānu fa-stamiʿū lahū wa-anṣitū laʿallakum turḥamūna', 'Kur''an okunduğu zaman onu dinleyin ve susun ki, merhamet olunasınız.'),
(7, 205, 9, 176, 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْءَاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ', 'wa-dhkur rabbaka fī nafsika taḍarruʿan wa-khīfatan wa-dūna l-jahri mina l-qawli bi-l-ghudūwwi wa-l-ʾāṣāli wa-lā takun mina l-ghāfilīna', 'Ve Rabbini içinden, dua ve korkuyla an. Ve alçak sesle, sabah akşam (an). Ve gafillerden olma.'),
(7, 206, 9, 176, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ', 'ʾinna lladhīna ʿinda rabbika lā yastakbirūna ʿan ʿibādatihi wa yusabbiḥūnahu wa lahu yasjudūna', 'Şüphesiz Rabbinin katında bulunanlar, O''na kulluk etmekten asla kibirlenmezler, O''nu tesbih ederler ve yalnız O''na secde ederler.'),
(8, 1, 9, 177, 'يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', 'yas''alūnaka ''ani l-ʾanfāli quli l-ʾanfālu li-llāhi wa-r-rasūli fa-ttaqū llāha wa-ʾaṣliḥū dhāta baynikum wa-ʾaṭīʿū llāha wa-rasūlahū ʾin kuntum mu''minīna', 'Sana ganimetleri soruyorlar. De ki: Ganimetler Allah''a ve Resûl''e aittir. İnanmışsanız Allah''tan korkun, birbirinizle aranızı düzeltin, Allah''a ve Resûlü''ne itaat edin.'),
(8, 2, 9, 177, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'ʾinnama l-muʾminūna lladhīna ʾidhā dhukira l-lāhu wajilat qulūbuhum wa ʾidhā tuliyat ʿalayhim ʾāyātuhu zādat-hum ʾīmānan wa ʿalā rabbihim yatawakkalūna', 'Mü''minler ancak, Allah anıldığı zaman yürekleri titreyen, kendilerine O''nun ayetleri okunduğunda imanlarını artıran ve yalnızca Rablerine güvenen kimselerdir.'),
(8, 3, 9, 177, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'alladhīna yuqīmūna ṣ-ṣalāta wa-mimmā razaqnāhum yunfiqūna', 'Onlar, namazı dosdoğru kılan, kendilerine verdiğimiz rızıktan da harcayanlardır.'),
(8, 4, 9, 177, 'أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'ʾūlāʾika humu l-muʾminūna ḥaqqan lahum daracātun ʿinda rabbihim wa-maġfiratun wa-rizqun karīmun', 'İşte gerçek müminler bunlardır. Rableri katında onlar için dereceler, mağfiret ve kerim bir rızık vardır.'),
(8, 5, 9, 177, 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَٰرِهُونَ', 'kamā ʾaḵrajaka rabbuka min baytika bil-ḥaqqi wa-ʾinna farīqan min al-muʾminīna lakārihūna', 'Hani Rabbin seni hak ile evinden çıkarmıştı. Halbuki o zaman müminlerden bir grup istemiyordu.'),
(8, 6, 9, 177, 'يُجَٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَمَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', 'Yucādilūneka fīl-ḥaqqi baʿdamā tabayyana Kaʾennemā yusāqūna ilal-mawti wa hum yanẓurūn', 'Sana hakkı, kendilerine apaçık belli olduktan sonra bile tartışma konusu yapıyorlar. Sanki onlar, göz göre göre ölüme sürülüyorlar.'),
(8, 7, 9, 177, 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَٰفِرِينَ', 'wa-ʾiḏ yāʿidukumū ʾllāhu ʾiḥdā ʾṭ-ṭāʾifatiyni ʾannahā lakum wa-tawaddūna ʾanna ġayra ḏāti ʾš-šawkati takūnu lakum wa-yurīdu ʾllāhu ʾan yuḥiqqā ʾl-ḥaqqa bi-kalimātihi wa-yaqṭaʿa dābira ʾl-kāfirīna', 'Hani Allah size iki taifeden birinin muhakkak sizin olacağını vaad ediyordu. Siz de o (silahsız) olanın sizin olmasını istiyordunuz. Halbuki Allah ise kendi kelimeleriyle hakkı gerçekleştirmek ve o kâfirlerin kökünü kesmek istiyordu.'),
(8, 8, 9, 177, 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'liyuḥiqqal-ḥaqqa wayubṭilal-bāṭila walaw karihal-mujrimūn', 'Böylece hakkı tahakkuk ettirmek ve batılı iptal etmek için (böyle yaptı); mücrimler hoşlanmasa da.'),
(8, 9, 9, 178, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ', 'idh tastaghīthūna rabbakum fastajāba lakum annī mumiddukum bi-alfin mina al-malāʾikati murdifīna', 'Hani siz Rabbinizden yardım istiyordunuz da, "Ben size, peş peşe bin melek ile yardım ediciyim" diye Rabbiniz duanızı kabul etmişti.'),
(8, 10, 9, 178, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'wa mā jaʿalahu ʾllāhu ʾillā bushra wa litaṭmaʾinna bihi qulūbukum wa mā n-naṣru ʾillā min ʿindi ʾllāh ʾinna ʾllāha ʿazīzun ḥakīm', 'Allah, bunu (bu zaferi) ancak bir müjde ve kalplerinizin böylece yatışması için yaptı. Yardım, yalnızca Allah''tandır. Şüphesiz Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir.'),
(8, 11, 9, 178, 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', 'idh yughashshīkumun-nuʿāsa amanatan minhu wa yunazzilu ʿalaykum minas-samāʾi māʾan liyuṭahhirakum bihi wa yudhhiba ʿankum rijza sh-shayṭāni wa liyarbita ʿalā qulūbikum wa yuthabbita bihi l-aqdāma', 'Hani O, katından bir güven işareti olarak sizi hafif bir uyukuya daldırmıştı. Sizi temizlemek, şeytanın pisliğini (vesveselerini) gidermek, kalplerinizi pekiştirmek ve (ayaklarınıza) sebat vermek için gökten bir su indirmişti.'),
(8, 12, 9, 178, 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ', 'iḏ yūḥī rabbuka ilā l-malāʾikati ʾannī maʿakum faṯabbitū l-laḏīna ʾāmanū saʾulqī fī qulūbi l-laḏīna kafarū r-ruʿba fa-ḍribū fawqa l-ʾaʿnāqi wa-ḍribū minhum kulla banānin', 'Hani Rabbin meleklere şöyle vahyediyordu: "Ben sizinle beraberim. İman edenlere destek olun. Ben kâfirlerin kalplerine korku salacağım. Artık onların boyunlarını vurun, her bir eklemlerini de vurun!"'),
(8, 13, 9, 178, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'dhālika bi-ʾannahum shāqqū al-lāha wa-rasūlahū wa-man yushāqiqi al-lāha wa-rasūlahū fa-ʾinna al-lāha shadīdu al-ʿiqābi', 'Bu böyledir, çünkü onlar Allah''a ve Resûlü''ne karşı geldiler. Kim Allah''a ve Resûlü''ne karşı gelirse, şüphesiz Allah''ın azabı çetindir.'),
(8, 14, 9, 178, 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَٰفِرِينَ عَذَابَ ٱلنَّارِ', 'dhālikum fa dhūqūhu wa anna lil-kāfirīna ʿadhāba n-nār', 'İşte bu, tadın onu! Ve kafirler için de ateş azabı vardır.'),
(8, 15, 9, 178, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', 'yā ayyuhā l-ladhīna āmānū idhā laqītumū l-ladhīna kafarū zaḥfan falā tuwallūhumu l-adbāra', 'Ey iman edenler! Savaş meydanında, kâfirlerle karşılaştığınızda, onlara arkalarınızı dönmeyin.'),
(8, 16, 9, 178, 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 've-men yuvellihim yevmeʾiḏin duburahu-ʾillā mutaḥarrifen li-qitālin ʾaw mutaḥayyizen ʾilā fiʾetin fa-qad bāʾa bi-ġaḍabin mina-llāhi ve-maʾwāhu ǧahannamu ve-biʾsa l-maṣīru', 'Kim o gün onlardan (düşmandan) -savaşmak için bir tarafa çekilmek veya bir gruba sığınmak dışında- yüz çevirirse, gerçekten Allah''tan bir gazaba uğramış olur. Onun varacağı yer cehennemdir. Ne kötü bir dönüş yeridir!'),
(8, 17, 9, 179, 'فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمْ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'fe lem tektulûhum ve lâkin nellâhe qetel-ehum ve mâ remeyte iz remeyte ve lâkin nellâhe remâ ve li yubliyel mu''minîne min-hu belâen hasenen in nellâhe semî''un ''alîmun', 'Onları siz öldürmediniz, fakat Allah öldürdü. (Resûlüm!) Sen atmadın, fakat Allah attı. (Bunu böyle yaptı ki) müminlere tarafından güzel bir imtihan yapsın. Şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir.'),
(8, 18, 9, 179, 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَٰفِرِينَ', 'dhālikum waʾanna ʾallāha mūhinū kaydi l-kāfirīn', 'İşte bu böyledir. Ve şüphesiz Allah kâfirlerin hilelerini zaafa uğratandır.'),
(8, 19, 9, 179, 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', 'in tastaftiḥū faqad jāʾakumul-fatḥu wa in tantahū fahuwa khayrun lakum wa in taʿūdū naʿud wa lan tuġniya ʿankum fiʾatukum shayʾan wa law kaṡurat wa anna Llāha maʿal-muʾminīn', 'Eğer (hak) ile batılın arasını ayırmanızı) istiyorsanız, işte size o hak (fetih) gelmiştir. Eğer (küfre) son verirseniz, bu sizin için daha hayırlıdır. Eğer (tekrar savaşa) dönerseniz, biz de (yardımımıza) döneriz. Topluluğunuz çok olsa bile, hiçbir işe yaramaz. Ve şüphesiz Allah, müminlerle beraberdir.'),
(8, 20, 9, 179, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', 'yā ayyuhā alladhīna āmanū aṭīʿū llāha wa rasūlahū wa lā tawallaw ʿanhu wa antum tasmaʿūna', 'Ey iman edenler! Allah''a ve Resûlü''ne itaat edin ve (onun emirlerini) işitip durduğunuz halde ondan yüz çevirmeyin.'),
(8, 21, 9, 179, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', 'wa lā takūnū ka-lladhīna qālū samiʿnā wa-hum lā yasmaʿūn', 'Ve onlar, "Dinledik" diyen ve işitmeyen kimseler gibi olmayın.'),
(8, 22, 9, 179, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', 'ʾinna şarra ʾd-dawābbi ʿinda ʾllāhi ṣ-ṣummu l-bukmu ʾllazīna lā yaʿqilūn', 'Şüphesiz, Allah katında (yürüyen) canlıların en kötüsü, (gerçeği) anlamayan sağırlar ve dilsizlerdir.'),
(8, 23, 9, 179, 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'wa law ʿalimallāhu fīhim khayran laʾasmāʿahum wa law ʾasmāʿahum latawallaw wa hum muʿriḍūn', 'Allah, onlarda bir hayır olduğunu bilseydi, elbette onları işittirirdi. (Fakat) onlara işittirseydi bile, mutlaka yüz çevirirlerdi ve onlar dönektirler.'),
(8, 24, 9, 179, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', 'yā ayyuhā alladhīna āmanū istajībū lillāhi wal-rasūli idhā daʿākum limā yuḥyīkum wa-ʿlamū anna Allāha yaḥūlu bayna al-marʾi wa-qalbihi wa-annahu ilayhi tuḥsharūna', 'Ey iman edenler! Sizi, hayat verecek şeylere davet ettiği zaman Allah''a ve Resûl''e uyun. Ve bilin ki Allah, kişi ile kalbi arasına girer ve yine siz O''na toplanacaksınız.'),
(8, 25, 9, 179, 'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'wa-ttaqū fitnatan lā tuṣībanna alladhīna ẓalamū minkum khāṣṣatan wa-ʿlamū anna Allāha shadīdu l-ʿiqābi', 'Bir de, içinizden sadece zulmedenlere isabet etmeyecek bir fitneden (beladan) sakının. Ve bilin ki Allah''ın azabı şiddetlidir.'),
(8, 26, 9, 180, 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ', 'wa-dhkurū idh antum qalīlun mustaḍʿafūna fī l-arḍi takhāfūna an yatakhṭṭafakumu n-nāsu fa-āwākum wa-ayyadakum binaṣrihi wa-razaqakum mina ṭ-ṭayyibāti laʿallakum tashkurūna', 'Hani siz azdınız, yeryüzünde zayıf düşürülmüş idiniz, insanların sizi kapıp götürmesinden korkuyordunuz. Derken O, sizi barındırdı, yardımıyla destekledi ve size temiz/helal rızıklar verdi ki şükredesiniz.'),
(8, 27, 9, 180, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', 'yā ayyuhā alladhīna āmanū lā takhūnū allāha wa-r-rasūla wa takhūnū amānātikum wa antum taʿlamūna', 'Ey iman edenler! Allah''a ve Peygambere hainlik etmeyin; bile bile kendi emanetlerinize de hainlik etmiş olursunuz.'),
(8, 28, 9, 180, 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'waʿlamū ʾannama ʾamwālukum wa-ʾawlādukum fitnah wa-ʾanna ʾallāha ʿindahu ʾajrun ʿaẓīm', 'Ve bilin ki, mallarınız ve evlatlarınız sizin için bir imtihan (vesilesi)dır ve şüphesiz Allah, O''nun katında büyük bir mükâfat vardır.'),
(8, 29, 9, 180, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'yā ayyuhā alladhīna āmanū in tattaqū allāha yajʿal lakum furqānan wa yukaffir ʿankum sayyiʾātikum wa yaghfir lakum wa allāhu dhū al-faḍli al-ʿaẓīm', 'Ey iman edenler! Allah''tan korkarsanız, O size doğruyu yanlıştan ayıran bir nur (furkan) verir, günahlarınızı örtüp bağışlar ve sizi altlarından ırmaklar akan cennetlere sokar. Allah, büyük lütuf sahibidir.'),
(8, 30, 9, 180, 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'wa-ʾiḏ y-amkuru bika l-laḏīna kafarū li-yuṯbitūka ʾaw yaqtulūka ʾaw yuḫrijūka wa-yamkurūna wa-yamkuru l-lāhu wa-l-lāhu ḫayru l-mākirīn', 'Hani kâfirler seni tutuklamak, ya da öldürmek, ya da (sürgün edip) çıkarmak için tuzak kuruyorlardı. Onlar tuzak kurarlar, Allah da tuzak kurar. Allah tuzak kuranların en iyisidir.'),
(8, 31, 9, 180, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'wa iḏā tutlā ʿalayhim ʾāyātunā qālū qad samiʿnā law našāʾu laqulnā miṯla hāḏā in hāḏā ʾillā ʾasaṭīru l-ʾawwalīn', 'Onlara âyetlerimiz okunduğu zaman: "Andolsun ki biz de işittik; eğer dilersek biz de bunun benzerini söyleyebiliriz. Bu, eskilerin masallarından başka bir şey değildir" derler.'),
(8, 32, 9, 180, 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ', 'wa-ʾidh qālū allāhumma ʾin kāna hādhā huwa l-ḥaqqa min ʿindika fa-ʾamṭir ʿalaynā ḥijāratan mina s-samāʾi ʾawi ʾtinā bi-ʿadhābin ʾalīmin', 'Ve hani demişlerdi: ''Allahım! Eğer bu, Senden gelmiş hak (kitap) ise, hemen üzerimize gökten taş yağdır veya bize elem dolu bir azap getir.'''),
(8, 33, 9, 180, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', 'wa mā kāna ʾllāhu liyūʿaḏḏibahum wa-ʾanta fīhim wa mā kāna ʾllāhu muʿaḏḏibahum wa-hum yastaġfirūn', 'Allah, sen içlerindeyken onlara azap edecek değildir. Ve Allah, onlar bağışlanma dilerlerken onlara azap edecek değildir.'),
(8, 34, 9, 181, 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'wa mā lahum allā yuʿaḏḏibahumu ʾllāhu wa hum yaṣuddūna ʿani l-masjidi l-ḥarāmi wa mā kānū ʾawliyāʾahu ʾin ʾawliyāʾuhu ʾillā l-muttaqūna wa lākinna ʾaktharahum lā yaʿlamūna', 'Allah, Mescid-i Haram''dan (onları) alıkoyarlarken ve ona (Mescid-i Haram''a) sahip çıkamazken onlara azap etmeyecek mi? Onun velileri ancak takva sahipleridir. Fakat onların çoğu bilmezler.'),
(8, 35, 9, 181, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'Ve mā kāne ṣalātuhum ʿinde l-bayti illā mukāʾan wa-taṣdiyatan Fe dhūqū l-ʿadhāba bimā kuntum takfurūn', 'Onların Beytullah yanındaki duaları ve ibadetleri ıslık çalmaktan ve el çırpmaktan başka bir şey değildi. "İnkâr etmekte olduğunuz şeyler yüzünden azabı tadın!" (denilecek).'),
(8, 36, 9, 181, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 'inna alladhīna kafarū yunfiqūna amwālahum liyaṣuddū ʿan sabīli Allāh fasayunfiqūnahā thumma takūnu ʿalayhim ḥasratan thumma yughlabūna wa-alladhīna kafarū ilā jahannama yuḥsharūna', 'Şüphesiz ki inkâr edenler, mallarını Allah yolundan (insanları) alıkoymak için harcarlar. Onları harcayacaklar, sonra bu onlara yürek acısı olacak, sonra da yenilecekler. Ve inkâr edenler topluca cehenneme sürülürler.'),
(8, 37, 9, 181, 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'li-yumayyiza l-lāhu l-khabītha mina ṭ-ṭayyibi wa-yajʿala l-khabītha baʿḍahū ʿalā baʿḍin fa-yarkumahū jamīʿan fa-yajʿalahū fī jahannama ʾulāʾika humu l-khāsirūna', 'Allah murdar olanı temiz olandan ayırmak, sonra murdar olanları bir kısmını diğerinin üstüne koyup hepsini bir araya yığarak cehenneme atmak için (böyle yapmıştır). İşte bunlardır ziyana uğrayanlar.'),
(8, 38, 9, 181, 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', 'qul lilladhīna kafarū in yantahū yughfar lahum mā qad salafa wa in yaʿūdū faqad maḍat sunnatu l-ʾawwalīna', 'De ki: "Kâfirlere söyle! Eğer (küfürden) vazgeçerlerse, geçmişte olanlar bağışlanır. Eğer dönerlerse, öncekilere uygulanan (kanun) zaten geçmiştir."'),
(8, 39, 9, 181, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ', 'wa qātilūhum ḥattā lā takūna fitnah wa yakūna d-dīnu kulluhu li-llāh fa-ʾini ntahaw fa-ʾinna llāha bimā yaʿmalūna baṣīr', 'Onlarla, fitne ortadan kalkıncaya ve din tamamen Allah''ın oluncaya kadar savaşın. Eğer vazgeçerlerse, şüphesiz Allah onların yaptıklarını görmektedir.'),
(8, 40, 9, 181, 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'wa-ʾin tawallaw fa-ʿlamū ʾanna-llāha mawlākum niʿma-l-mawlá wa-niʿma-n-naṣīr', 'Eğer yüz çevirirlerse, bilmiş olun ki Allah sizin Mevlânızdır. Ne güzel Mevlâ ve ne güzel yardımcıdır!'),
(8, 41, 10, 182, 'وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'waʿlamū ʾannamā ghanimtum min shayʾin faʾanna lillāhi khumusahū wa lir-rasūli wa liḏī l-qurbā wal-yatāmā wal-masākīni wabni s-sabīli ʾin kuntum ʾāmantum billāhi wa mā ʾanzalnā ʿalā ʿabdinā yawma l-furqāni yawma ltaqā l-jamʿāni wallāhu ʿalā kulli shayʾin qadīrun', 'Bilin ki, her ne kadar ganimet elde ederseniz, onun beşte biri mutlaka Allah''a, Peygamber''e, (ona) yakınlığı olanlara, yetimlere, yoksullara ve yolda kalmışlara aittir. Eğer Allah''a ve bizim, kulumuz üzerine indirdiğimiz o furkan gününe, iki topluluğun karşılaştığı o güne inanmışsanız (bunu böyle bilesiniz). Allah her şeye hakkıyla gücü yetendir.'),
(8, 42, 10, 182, 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 'idh antum bil-ʿudwati d-dunyā wa-hum bil-ʿudwati l-quṣwā wa-r-rakbu ʾasfala minkum wa-law tawāʿadtum la-khtalaftum fī l-mīʿādi wa-lākin li-yaqḍiya ʾllāhu ʾamran kāna mafʿūlan li-yahlika man halaka ʿan bayyinatin wa-yaḥyā man ḥayya ʿan bayyinatin wa-ʾinna ʾllāha la-samīʿun ʿalīmun', 'Hani siz vadinin yakın (en yakın) tarafında idiniz, onlar da vadinin uzak (en uzak) tarafında idiler. Kervan ise sizden daha aşağıda idi. Eğer siz (savaşmak için) bir araya gelmeyi planlasaydınız, mutlaka buluşma yerinde anlaşmazlığa düşerdiniz. Fakat Allah, olacak bir işi gerçekleştirmek için (böyle yaptı). Bu, helak olacak kimsenin apaçık bir delilden sonra helak olması, yaşayacak kimsenin de apaçık bir delilden sonra yaşaması içindir. Şüphesiz Allah, hakkıyla işitendir, hakkıyla bilendir.'),
(8, 43, 10, 182, 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'iḏ yūrikahumu ʾllāhu fī manāmika qalīlan wa-law ʾarākahum kaṯīran lafašiltum wa-latanāzaʿtum fī l-ʾamri wa-lākinna ʾllāha sallama ʾinnahu ʿalīmun bi-ḏāti ṣ-ṣudūri', 'Hani Allah, uykunda sana onları az göstermişti. Eğer onları sana çok gösterseydi, elbette gevşeyecektiniz ve iş hakkında (birbirinizle) anlaşmazlığa düşecektiniz. Fakat Allah (sizi bundan) korudu. Şüphesiz O, kalplerde olanı bilendir.'),
(8, 44, 10, 182, 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'wa-ʾiḏ yurīkumūhum-iḏi-ltaqaytum fī-ʾaʿyunikum qalīlan wa-yuqallilukum fī-ʾaʿyuni-him li-yaqḍiya-llāhu ʾamran kāna mafʿūlan wa-ʾilā-llāhi turjaʿu-l-ʾumūr', 'Hani Allah, size düşmanlarınızı (savaş meydanında) size az göründürdüğü, aynı zamanda sizi de onların gözlerinde az gösterdiği zamanı hatırlayın. Allah, olup bitecek bir işi gerçekleştirmek istiyordu. Bütün işler sonunda Allah''a döner.'),
(8, 45, 10, 182, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 'yā ayyuhā lladhīna āmānū idhā laqītum fiʾatan fāthbutū wādhkurū l-lāha kathīran laʿallakum tufliḥūn', 'Ey iman edenler! Bir toplulukla karşılaştığınızda sebat edin ve kurtuluşa ermeniz için Allah''ı çok zikredin.'),
(8, 46, 10, 183, 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ وَٱصْبِرُوٓا۟ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 'wa ʾaṭīʿū ʾllāha wa rasūlahū wa lā tanāzaʿū fatafšalū watadhhaba rīḥukum wa ʾiṣbirū ʾinna ʾllāha maʿa ʾaṣ-ṣābirīn', 'Allah''a ve Resûlü''ne itaat edin ve birbirinizle çekişmeyin ki gevşemeyesiniz ve kuvvetiniz (zaferiniz) gitmesin. Sabredin. Şüphesiz Allah sabredenlerle beraberdir.'),
(8, 47, 10, 183, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ', 'wa lā takūnū ka-lladhīna kharajū min diyārihim baṭaran wa riʾāʾa n-nāsi wa yaṣuddūna ʿan sabīli llāhi wa llāhu bimā yaʿmalūna muḥīṭun', 'Yurtlarından çalım satarak, insanlara gösteriş yaparak çıkan ve Allah yolundan alıkoyanlar gibi olmayın. Allah, onların yapmakta olduklarını kuşatıcıdır.'),
(8, 48, 10, 183, 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'wa-ʾiḏ ḏayyana lahumu ʾš-šayṭānu ʾaʿmālahum wa-qāla lā ġālaba lakumu ʾl-yawma mina ʾn-nāsi wa-ʾinnī jārun lakum fa-lammā tarāʾati ʾl-fiʾatāni nakasa ʿalā ʿaqibayhi wa-qāla ʾinnī barīʾun minkum ʾinnī ʾarā mā lā tarawna ʾinnī ʾaḫāfu ʾllāha wa-ʾllāhu šadīdu ʾl-ʿiqābi', 'Hani bir zaman şeytan onlara yaptıklarını süslemiş ve: "Bugün size hiçbir galip gelecek yoktur, hiç şüphesiz ben de sizin komşunuzum (yanınızdayım)" demişti. İki topluluk birbirini gördüğü zaman ise, (şeytan) önceki (tavrının) üzerine dönmüş ve: "Şüphesiz ben sizden uzağım, ben sizin görmediğiniz şeyleri görüyorum, şüphesiz ben Allah''tan korkuyorum, Allah''ın azabı çetindir" demişti.'),
(8, 49, 10, 183, 'إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'idh yaqūlu l-munāfiqūna wa-lladhīna fī qulūbihim maraḍun gharra hā''ulā''i dīnuhum wa-man yatawakkalu ʿalā llāhi fa-inna llāha ʿazīzun ḥakīmun', 'Hani, münafıklar ve kalplerinde hastalık bulunanlar şöyle diyorlardı: ''Bunları dinleri aldatmıştır.'' Oysa kim Allah''a güvenirse, bilsin ki Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir.'),
(8, 50, 10, 183, 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'wa law tarā idh yatawaffā alladhīna kafarū al-malāʾikatu yaḍribūna wujūhahum wa adbārahum wa dhūqū ʿadhāb al-ḥarīq', 'Kafirlerin canlarını alırken meleklerin, yüzlerine ve arkalarına vurup: "Tadın bakalım cehennem azabını!" dediklerini bir görsen!'),
(8, 51, 10, 183, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'dhālika bimā qaddamat ʾaydīkum wa ʾanna ʾallāha laysa biẓallāmin lil-ʿabīd', 'İşte bu, sizin ellerinizle işledikleriniz yüzündendir. Şüphesiz Allah kullarına asla zulmedici değildir.'),
(8, 52, 10, 183, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', 'kad''ābi ʾāli firʿawna wallaḏīna min qablihim kafarū bi-ʾāyāti llāhi fa-ʾaḵaḏahumu llāhu bi-ẕunūbihim ʾinna llāha qawiyyun šadīdu l-ʿiqābi', 'Firavun ailesinin ve onlardan öncekilerin gidişine benzedi. Allah''ın ayetlerini inkâr ettiler de Allah onları günahları yüzünden yakaladı. Şüphesiz Allah çok kuvvetli, azabı çok şiddetlidir.'),
(8, 53, 10, 184, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'dhālika biʾanna ʾllāha lam yaku mughayyiran niʿmata nʾamahā ʿalā qawmin ḥattā yughayyirū mā biʾanfusihim waʾanna ʾllāha samīʿun ʿalīmun', 'Bu böyledir, çünkü bir topluluğa verdiği bir nimeti, onlar kendi durumlarını değiştirmedikçe Allah değiştirmez. Şüphesiz Allah, hakkıyla işitendir, bilendir.'),
(8, 54, 10, 184, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَكُلٌّ كَانُوا۟ ظَٰلِمِينَ', 'kad''aabi aali fir''awna wallazeena min qablihim kazzaboo bi''aayaati rabbihim fa''ahlaknaahum bizunoobihim wa''aghraqnaa aala fir''awna wa kullun kaanoo zaalimeen', 'Durumları, tıpkı Firavun ailesinin ve onlardan öncekilerin durumu gibidir. Rablerinin ayetlerini yalanladılar da biz onları günahları yüzünden helak ettik ve Firavun ailesini boğduk. Hepsi zalimlerdi.'),
(8, 55, 10, 184, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', 'ʾinna ǧarra ʾad-dawābbi ʿinda ʾallāhi ʾalluḏīna kafarū fa-hum lā yuʾminūn', 'Şüphesiz, Allah katında (yürüyen) canlıların en kötüsü, inkâr edenlerdir; artık onlar iman etmezler.'),
(8, 56, 10, 184, 'ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', 'alladhīna ʿāhadta minhum thumma yanquḍūna ʿahdahum fī kulli marratin wahum lā yattaqūn', 'Onlardan ahid aldığın, sonra her defasında ahidlerini bozan ve onlar (Allah''tan) korkmayan kimseler...'),
(8, 57, 10, 184, 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', 'fa-immā tathqafannahum fī l-ḥarbi fa-sharrid bihim man khalfahum laʿallahum yadhdhakkarūn', 'Eğer savaşta onları yakalarsan, onlarla arkalarındakileri dağıt ki, ibret alsınlar.'),
(8, 58, 10, 184, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', 'wa-immā takhāfanna min qawmin khiyānatan fa-nbiḏ ilayhim ʿalā sawāʾin ʾinna ʾllāha lā yuḥibbu l-khāʾinīn', 'Eğer bir topluluğun (anlaşmalara uymayarak) hainlik yapacağından korkarsan, sen de onlara karşı (anlaşmayı) bozduğunu kendilerine eşit bir şekilde bildir. Şüphesiz Allah, hainleri sevmez.'),
(8, 59, 10, 184, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ إِنَّهُمْ لَا يُعْجِزُونَ', 'walā yaḥsabanna alladhīna kafarū sabaqū innahum lā yuʿjizūna', 'O kâfirler, (azaptan) kurtulacaklarını sanmasınlar! Şüphesiz onlar (bizi) âciz bırakamazlar.'),
(8, 60, 10, 184, 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'Ve aʿiddū lehum mā istaṭaʿtum min quvvetin ve min ribāṭi l-ḫayli turhibūna bihī ʿaduvva l-lāhi ve ʿaduvvakum ve āḫarīna min dūnihim lā taʿlamūnahumu l-lāhu yaʿlamuhum ve mā tunfiqū min şeyʾin fī sabīli l-lāhi yuvaffa ilaykum ve antum lā tuẓlamūna', 'Onlara karşı gücünüz yettiği kadar kuvvet ve atlı birlikler hazırlayın ki bununla Allah''ın düşmanını, sizin düşmanınızı ve onlardan başka sizin bilmediğiniz, ancak Allah''ın bildiği kimseleri korkutasınız. Allah yolunda ne harcarsanız, size eksiksiz ödenir ve siz haksızlığa uğratılmazsınız.'),
(8, 61, 10, 184, 'وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa-ʾin janahū li-s-salmi fa-ʾjnah lahā wa-tawakkal ʿalā ʾllāhi ʾinnahu huwa s-samīʿu l-ʿalīmu', 'Eğer barışa yanaşır (eğilim gösterir)lerse, sen de ona yanaş (eğilim göster) ve Allah''a güven. Şüphesiz O, hakkıyla işiten, kemaliyle bilendir.'),
(8, 62, 10, 185, 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', 'wa-ʾin yurīdū ʾan yakhdaʿūka fa-ʾinna ḥasbaka ʾallāhu huwa ʾalladhī ʾayyada-ka bi-naṣrihi wa-bi-l-muʾminīna', 'Eğer sana hile yapmak isterlerse, bil ki Allah sana yeter. O, seni yardımıyla ve müminlerle destekleyen O''dur.'),
(8, 63, 10, 185, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُۥ عَزِيزٌ حَكِيمٌ', 'wa ʾallafa bayna qulūbihim law ʾanfaqta mā fī l-ʾarḍi jamīʿan mā ʾallafta bayna qulūbihim wa-lākinna ʾallāha ʾallafa baynahum ʾinnahu ʿazīzun ḥakīmun', 'Onların kalplerini birbirine ısındıran O''dur. Sen yeryüzündeki her şeyi verseydin bile, onların kalplerini ancak O ısındırabilirdi. Şüphesiz O, Azîz''dir (mutlak galiptir), Hakîm''dir (hikmet sahibidir).'),
(8, 64, 10, 185, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'yā ayyuhā n-nabiyyu ḥasbuka llāhu wa-mani ttabaʿaka mina l-muʾminīn', 'Ey Peygamber! Sana ve sana uyan mü''minlere Allah yeter.'),
(8, 65, 10, 185, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'yā ayyuhā an-nabiyyu ḥarriḍi l-muʾminīna ʿalā l-qitāli in yakun minkum ʿišrūna ṣābirūna yaġlibū miʾatayni wa in yakun minkum miʾatun yaġlibū ʾalfa-n mina l-laḏīna kafarū bi-ʾannahum qawmun lā yafqahūna', 'Ey Peygamber! Müminleri savaşa teşvik et. Eğer içinizden sabreden yirmi kişi bulunursa, onlardan ikiyüz kişiye galip gelirler. Eğer içinizden yüz kişi bulunursa, kafirlerden bin kişiye galip gelirler. Çünkü onlar, anlayışsız bir kavimdir.'),
(8, 66, 10, 185, 'ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 'al''āna ḫaffafa ḷḷāhu ʿankum wa ʿalima anna fīkum ḍaʿfan fa-in yakun minkum mi''atun ṣābiratun yaglibū mi''atayni wa-in yakun minkum alfun yaglibū alifayni bi-iḏni ḷḷāhi wa ḷḷāhu maʿa ṣ-ṣābirīn', 'Şimdi Allah yükünüzü hafifletti ve içinizde bir zayıflık bulunduğunu bildi. Öyleyse içinizden sabırlı yüz kişi olursa, iki yüz kişiye galip gelirler; eğer bin kişi olursa, Allah''ın izniyle bin kişiye (iki bin kişiye) galip gelirler. Allah sabredenlerle beraberdir.'),
(8, 67, 10, 185, 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْءَاخِرَةَ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'mā kāna linabiyyin an yakūna lahu ʾasrā ḥattā yuthkhina fī l-ʾarḍi turīdūna ʿaraḍa d-dunyā wa-llāhu yurīdu l-ʾākhirata wa-llāhu ʿazīzun ḥakīmun', 'Hiçbir peygamber için, yeryüzünde (düşmanı) ağır bir şekilde yaralayıp (etkisiz hale getirinceye kadar) savaşmadıkça esir almak uygun değildir. Siz geçici dünya malını istiyorsunuz; Allah ise (size) ahireti istiyor. Allah Azîz''dir, Hakîm''dir.'),
(8, 68, 10, 185, 'لَّوْلَا كِتَٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ', 'lawlā kitābun mina llāhi sabaqa lamassakum fīmā ʾakhaḏtum ʿaḏābun ʿaẓīmun', 'Eğer Allah''tan bir yazgı (hüküm) daha önce geçmiş olmasaydı, aldığınız şeyden dolayı size mutlaka büyük bir azap dokunurdu.'),
(8, 69, 10, 185, 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'fakulū mimmā ghanimtum ḥalālan ṭayyibā wattaqū allāh ʾinna allāh ghafūrun raḥīm', 'Artık ganimet olarak aldıklarınızdan helal ve temiz olarak yiyin. Allah''tan korkun. Şüphesiz Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(8, 70, 10, 186, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'yā ayyuhā n-nabiyyu qul liman fī aydīkum mina l-asrā in yaʿlam allāhu fī qulūbikum khayran yuʾtikum khayran mimmā ukhidha minkum wa yaghfir lakum wa llāhu ghafūrun raḥīm', 'Ey Peygamber! Elinizdeki esirlere de ki: Eğer Allah kalplerinizde bir hayır (iyilik) bilirse, sizden alınan (fidye)den daha iyisini size verir ve sizi bağışlar. Allah çok bağışlayıcı, çok merhamet edicidir.'),
(8, 71, 10, 186, 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'wa-ʾin yurīdū ḵiyānetaka fapqat ḵānū ʾallāha min qablu fa-ʾamkana minhum wa-ʾallāhu ʿalīmun ḥakīmun', 'Eğer sana hıyanet etmek isterlerse, zaten onlar daha önce Allah''a hıyanet etmişlerdi. Bu yüzden Allah onlara (karşı sana) imkan ve fırsat vermiştir. Allah, her şeyi bilen, hüküm ve hikmet sahibi olandır.'),
(8, 72, 10, 186, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'ʾinna llaḏīna ʾāmanū wa-hāǧarū wa-ǧāhadū bi-ʾamwālihim wa-ʾanfusihim fī sabīli llaāhi wa llaḏīna ʾāwaw wa-naṣarū ʾūlāʾika baʿḍuhum ʾawliyāʾu baʿḍin wa llaḏīna ʾāmanū wa-lam yuhāǧirū mā lakum min walāyathim min šayʾin ḥattā yuhāǧirū wa ʾini stanaṣarūkum fī d-dīni fa-ʿalaykumu n-naṣru ʾillā ʿalā qawmin baynakum wa-baynahum mīṯāqun wa llaāhu bimā taʿmalūna baṣīrun', 'İman edip hicret edenler ve mallarıyla, canlarıyla Allah yolunda cihad edenler ile (hicret edenleri) barındıranlar ve yardım edenler var ya, işte onlar birbirlerinin velileridir. İman edip de hicret etmeyenlere gelince, hicret edinceye kadar onların velayetinden size hiçbir şey yoktur. Eğer dinleri hususunda sizden yardım isterlerse, üzerinizdeki yardımlaşma hakkı, sizinle aralarında antlaşma bulunan bir kavim hariç olmak üzere, jangidir. Allah yaptıklarınızı görmektedir.'),
(8, 73, 10, 186, 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ', 'wa-lladhīna kafarū baʿḍuhum awliyāʾu baʿḍin illā tafʿalūhu tukun fitnatun fī l-arḍi wa-fasādun kabīrun', 'İman edenler Allah yolunda savaşırlar; inkar edenler ise tağut (azgın putlar ve şeytan) yolunda savaşırlar. O halde şeytanın taraftarlarıyla savaşın; şüphe yok ki şeytanın hilekarlığı zayıftır.'),
(8, 74, 10, 186, 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'wa-lladhīna ʾāmanū wa-hādjarū wa-jāhadū fī sabīli-llāhi wa-lladhīna ʾāwaw wa-naṣarū ʾulāʾika humu-l-muʾminūna ḥaqqan lahum maghfiratun wa-rizqun karīmun', 'Allah yolunda hicret edenler ve Allah yolunda cihad edenler ve (din kardeşlerine) ev sahipliği yapanlar ve yardım edenler var ya, işte onlar gerçekten müminlerdir. Onlar için bir mağfiret ve kerim bir rızık vardır.'),
(8, 75, 10, 186, 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'wa-lladhīna ʾāmanū min baʿdu wahājarū wajāhadū maʿakum fa-ʾulāʾika minkum wa-ʾulū l-ʾarḥāmi baʿḍuhum ʾawlā bi-baʿḍin fī kitābi llāhi ʾinna llāha bi-kulli shayʾin ʿalīmun', 'Sonradan iman edip hicret edenler ve sizinle birlikte cihad edenler de sizdendir. Allah''ın Kitabı''nda (hükmünce) akraba olanlar birbirlerine (mirasta) daha layıktırlar. Şüphesiz Allah her şeyi hakkıyla bilendir.'),
(9, 1, 10, 187, 'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', 'baraa''atun minallahi wa rasoolihi ila allatheena ''aahad''tum minal mushrikeen', 'Allah’tan ve O’nun Resûlü’nden, kendileriyle antlaşma yaptığınız müşriklere bir ültimatomdur.'),
(9, 2, 10, 187, 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَٰفِرِينَ', 'fasīḥū fī l-arḍi ʾarbaʿata ʾashhurin wa-ʿlamū ʾannakum ġayru muʿjizī llāhi wa-ʾanna llāha mukhzī l-kāfirīn', 'Yeryüzünde dört ay daha dolaşın. Ve bilin ki siz Allah''ı aciz bırakacak değilsiniz. Ve Allah, kâfirleri rezil edecek olan(dır).'),
(9, 3, 10, 187, 'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ وَرَسُولُهُۥ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', 'wa ʾaḏānun mina ʾllāhi wa rasūlihi ʾilā n-nāsi yawma l-ḥajji l-ʾakbari ʾanna ʾllāha barīʾun mina l-mušrikīna wa rasūluhū fa-ʾin tubtum fa-huwa ḫayrun lakum wa-ʾin tawallaytum fa-ʿlamū ʾannakum ġayru muʿjizī ʾllāhi wa-bašširi l-laḏīna kafarū bi-ʿaḏābin ʾalīmin', 'Allah''tan ve Resûlü''nden, o büyük hac gününde insanlara bir duyuru: Allah ve Resûlü, müşriklerden uzaktır. Eğer tevbe ederseniz, bu sizin için hayırlıdır. Yüz çevirirseniz, Allah''ın sizi aciz bırakamayacağını bilin. Kâfir olanları ise elem dolu bir azapla müjdele.'),
(9, 4, 10, 187, 'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'illa alladhīna ʿāhadtum mina l-mushrikīn thumma lam yanquṣūkum shayʾan wa-lam yuẓāhirū ʿalaykum aḥadan fa-atimmū ilayhim ʿahdahum ilā muddatihim ʾinna ʾallāha yuḥibbu l-muttaqīn', 'Ancak, kendileriyle antlaşma yaptıklarınızdan sonra, antlaşmalarını hiçbir şekilde eksik bırakmayanlar ve sizin aleyhinize hiç kimseye arka çıkmayanlar bu hükmün dışındadır. Onlarla antlaşmalarını, anlaştığınız süre sonuna kadar tamamlayın. Şüphesiz Allah, kendisine karşı gelmekten sakınanları sever.'),
(9, 5, 10, 187, 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'faʾiḏā insalخصa ʾalʾašhuru ʾalḥurumu faqtulū ʾalmušrikīna ḥaiṯu waǧadtumūhum waχuḏūhum waḥṣurūhum waqʿudū lahum kulla marṣadin faʾin tābū waʾaqāmū ʾaṣṣalāta waʾātav ʾazzeḵāta faχallū sabīlahum ʾinna ʾallāha ġafūrun raḥīmun', 'Haram aylar (sürelerini) bitirip çıktığında, müşrikleri bulduğunuz yerde öldürün. Onları yakalayın, onları kuşatın ve onları gözetleme yerlerinin her birinde (pusuda) bekleyin. Eğer tevbe eder, namazı dosdoğru kılarlar ve zekatı verirlerse, artık onları serbest bırakın. Şüphesiz Allah, Gafûr''dur (çok bağışlayandır), Rahîm''dir (çok merhamet edendir).'),
(9, 6, 10, 187, 'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ', 'wa-ʾin ʾaḥadun mina l-mušrikīna staraka fa-ʾajirhu ḥattā yasmaʿa kalāma llāhi ṯumma ʾabliġhu maʾmanahū ḏālika bi-ʾannahum qawmun lā yaʿlamūna', 'Eğer müşriklerden biri senden aman dilerse, Allah''ın sözünü işitinceye kadar ona aman ver, sonra onu güvendiği yere ulaştır. Bu, onların bilmeyen bir kavim olmaları sebebiyledir.'),
(9, 7, 10, 188, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ فَمَا ٱسْتَقَٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'kayfa yakūnu lil-muşrikīna ʿahdun ʿinda Allāhi wa ʿinda rasūlihī illā alladhīna ʿāhadtum ʿinda l-masjidi l-ḥarāmi famā stqāmū lakum fastaqīmū lahum ʾinna Allāha yuḥibbu l-muttaqīna', 'Müşrikler için Allah katında ve O''nun Resûlü nezdinde nasıl bir ahit (veya anlaşma) olabilir? Ancak Mescid-i Haram yanında kendileriyle antlaşma yaptıklarınız müstesna. Onlar size karşı dürüst davrandıkları sürece siz de onlara karşı dürüst olun. Şüphesiz Allah, (emirlerine) karşı gelmekten sakınanları sever.'),
(9, 8, 10, 188, 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ', 'kayfa wa-in yaẓharū ʿalaykum lā yarqubū fīkum illaⁿ wa-lā ḏimmah yuṛḍūnakum bi-afwāhihim wa-taʾbā qulūbuhum wa-aktharuhum fāsiqūn', 'Nasıl olur da (onların durumu böyle iken, sizinle antlaşma yapmaları nasıl güven verir)? Halbuki onlar size galip gelseler, hakkınızda ne bir yemin ne de bir antlaşma gözetirler. Ağızlarıyla sizi razı ederler, oysa kalpleriInkâr eder. Onların çoğu yoldan çıkmışlardır.'),
(9, 9, 10, 188, 'ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'ishtaraū bi-ʾāyāti ʾllāhi thamanan qalīlan faṣaddū ʿan sabīlihī ʾinnahum sāʾa mā kānū yaʿmalūn', 'Onlar, Allah''ın ayetlerini az bir paraya sattılar da O''nun yolundan alıkoydular. Gerçekten onların yapmakta oldukları ne kötü şey!'),
(9, 10, 10, 188, 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', 'lā yarqubūna fī muʾminin ʾillan walā ḏimmah wa ʾulāʾika humu l-muʿtadūn', 'Onlar, bir mü''min hakkında ne bir yemin ne de bir ahde riayet gözetirler. İşte onlardır haddi aşanlar.'),
(9, 11, 10, 188, 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَنُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍ يَعْلَمُونَ', 'fa-in tābū wa-aqāmū ṣ-ṣalāta wa-ātū z-zakāta fa-ikhwānukum fī d-dīn wa-nufaṣṣilu l-ʾāyāti li-qawmin yaʿlamūn', 'Eğer tövbe ederler, namazı kılarlar ve zekâtı verirlerse, dinde sizin kardeşlerinizdir. Biz de ayetleri, bilen bir topluluk için ayrı ayrı açıklıyoruz.'),
(9, 12, 10, 188, 'وَإِن نَّكَثُوٓا۟ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', 'wa-in nakathū ʾaimānahum mim baʿdi ʿahdihim wa-ṭaʿanū fī dīnikum fa-qātilū ʾaʾimmatal-kufr ʾinnahum lā ʾaimāna lahum laʿallahum yantahūn', 'Eğer antlaşmalarından sonra yeminlerini bozarlar ve sizin dininize dil uzatırlarsa, küfür ele başlarıyla savaşın. Çünkü onların yeminleri yoktur; umulur ki vazgeçerler.'),
(9, 13, 10, 188, 'أَلَا تُقَٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ أَتَخْشَوْنَهُمْ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', 'ʾalā tuqātilūna qawman nakathū ʾaimānahum wa hammū bi-ʾikhrāji r-rasūli wa hum badaʾūkum ʾawwala marratin ʾatakhshawnahum fa-llāhu ʾaḥaqqu ʾan takhshawhu ʾin kuntum muʾminīna', 'Siz, yeminlerini bozan ve Resûl''ü çıkarmaya azmeden bir kavimle savaşmayacak mısınız? Hem de size ilk defa onlar başlamışlardı. Allah''tan korkmalısınız, eğer inanmışsanız.'),
(9, 14, 10, 189, 'قَٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ', 'qātilūhum yuʿaḏḏibhumu ʾllāhu bi-ʾaydīkum wa-yukhzihim wa-yanṣurkum ʿalayhim wa-yašfi ṣudūra qawmin mʾuminīn', 'Onlarla savaşın; Allah onları sizin ellerinizle azaplandıracak, onları rezil edecek, size karşı onlara galip getirecek ve müminler topluluğunun göğüslerini (kalplerini) şifaya kavuşturacaktır.'),
(9, 15, 10, 189, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'wa yuḏhibu ġayẓa qulūbihim wa yatūbu ʾllāhu ʿalā man yašāʾu wa ʾllāhu ʿalīmun ḥakīmun', 'Ve onların kalplerindeki öfkeyi gidersin. Allah dilediği kimsenin tevbesini kabul eder. Allah her şeyi bilen, hikmet sahibidir.'),
(9, 16, 10, 189, 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ʾam ḥasibtum ʾan tutrakū wa-lammā yaʿlamillāhu lladhīna jāhadū minkum wa-lam yattakhidhū min dūni llāhi wa-lā rasūlihī wa-lā l-muʾminīna walījatan wa-llāhu khabīrum bimā taʿmalūna', 'Yoksa siz, içinizden cihad edenleri ve Allah''tan, Resûlünden ve mü''minlerden başkasını sırdaş edinmeyenleri Allah bilmeden bırakılacağınızı mı sandınız? Allah, yaptıklarınızdan haberdardır.'),
(9, 17, 10, 189, 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَٰلِدُونَ', 'mā kāna lil-mušrikīna ʾan yaʿmurū masāǧida ʾllāhi šāhidīna ʿalā ʾnfusihim bil-kufr ʾūlāʾika ḥabiṭat ʾaʿmāluhum wa-fī n-nāri hum ḫālidūn', 'Müşriklerin, küfre tanıklık ederek Allah''ın mescitlerini imar etmeleri, Allah''tan başka kimseye yakışmaz. Onların yaptıkları boşa gitmiştir. Onlar ateşte ebedi kalacaklardır.'),
(9, 18, 10, 189, 'إِنَّمَا يَعْمُرُ مَسَٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ فَعَسَىٰٓ أُو۟لَٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', 'innamā yaʿmuru masājida Allāhi man ʾāmana bi-llāhi wa-l-yawmi l-ʾākhiri wa-ʾaqāma ṣ-ṣalāta wa-ʾātā z-zakāta wa-lam yakhsha ʾillā -llāha fa-ʿasā ʾu ʾulāʾika ʾan yakūnū min al-muhtadīn', 'Allah''ın mescitlerini ancak Allah''a ve ahiret gününe iman eden, namazı dosdoğru kılan, zekâtı veren ve Allah''tan başkasından korkmayan kimseler imar eder. İşte bunlar, doğru yolu bulanlardan olmaları umulanlardır.'),
(9, 19, 10, 189, 'أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَجَٰهَدَ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'a jaʿaltum siqāyata l-ḥājji wa ʿimārata l-masjidi l-ḥarāmi kaman ʾāmana bi-llāhi wa-l-yawmi l-ʾākhiri wa jāhada fī sabīli llāh lā yastawūna ʿinda llāh wa llāhu lā yahdī l-qawma ẓ-ẓālimīn', 'Siz, hacılara su vermeyi ve Mescid-i Haram''ı onarmayı, Allah''a ve ahiret gününe iman edip Allah yolunda cihat eden kimseyle bir mi tuttunuz? Onlar Allah katında bir olmazlar. Allah zalimler topluluğunu hidayete erdirmez.'),
(9, 20, 10, 189, 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'alladhīna ʾāmanū wa-hājarū wa-jāhadū fī sabīli llāhi bi-ʾamwālihim wa-ʾanfusihim ʾaʿẓamu darajatan ʿinda llāhi wa-ʾulāʾika humu l-fāʾizūn', 'Onlar, iman edenler, hicret edenler ve Allah yolunda mallarıyla ve canlarıyla cihad edenlerdir. Allah katında dereceleri daha büyüktür. İşte bunlar, murada erenlerdir.'),
(9, 21, 10, 190, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ', 'yubashshiruhum rabbuhum biraḥmatim minhu waridwanin wajannātin lahum fīhā naʿīmun muqīmun', 'Rableri onlara kendisinden bir rahmet, bir rıza ve kendileri için içinde ebedi nimetler bulunan cennetler müjdeler.'),
(9, 22, 10, 190, 'خَٰلِدِينَ فِيهَآ أَبَدًا إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'khālidīna fīhā ʾabadan ʾinna ʾallāha ʿindahu ʾajrun ʿaẓīmun', 'Onlar orada ebediyen kalıcıdırlar. Şüphesiz Allah, katında büyük mükâfat vardır.'),
(9, 23, 10, 190, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'yā ayyuhā lladhīna āmanū lā tattakhidhū ābāʾakum wa-ikhwānakum awliyāʾa ini staḥabbū l-kufra ʿalā l-īmāni wa-man yatawallahum minkum fa-ulāʾika humu ẓ-ẓālimūna', 'Ey iman edenler! Eğer iman etmektense küfrü tercih ederlerse, babalarınızı ve kardeşlerinizi veli edinmeyin. Sizden kim onları veli edinirse, işte onlar zalimlerin ta kendileridir.'),
(9, 24, 10, 190, 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'qul in kāna ʾābāʾukum wa-ʾabnāʾukum wa-ʾiḫwānukum wa-ʾazwājukum wa-ʿašīratukum wa-ʾamwālun ʾiqtaraftumūhā wa-tiǧāratun taḫšawna kasādahā wa-masākinu tarḍawnahā ʾaḥabba ʾilaykum mina ʾllāhi wa-rasūlihī wa-ǧihādin fī sabīlihī fa-tarabbaṣū ḥattā yaʾtiya ʾllāhu bi-ʾamrihī wa-ʾllāhu lā yahdī l-qawma l-fāsiqīn', 'De ki: Eğer babalarınız, oğullarınız, kardeşleriniz, eşleriniz, akrabalarınız, elde ettiğiniz mallar, kesintiye uğramasından korktuğunuz ticaret ve hoşnud olduğunuz meskenler, Allah''tan, Resûlü''nden ve O''nun yolunda cihad etmekten daha çok sevdiğiniz şeyler ise, artık Allah kendi emrini getirinceye kadar bekleyin. Allah fasıklar güruhunu hidayete erdirmez.'),
(9, 25, 10, 190, 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', 'leḳad neṣarakumu-llâhu fî mevâṭine keŝîratin veyevme ḥuneynin iż a`cebetküm keŝratüküm felem tuġni `anküm şey''â veḍâḳat `aleykumu-l''arḍu bimâ raḥubet ŝümme velleytüm müdbirîn', 'Andolsun ki Allah, birçok yerde ve Huneyn gününde size yardım etti. O gün çokluğunuz sizi böbürlendirmişti de bu size hiçbir fayda vermemişti. Yeryüzü bütün genişliğine rağmen size dar gelmişti. Sonra da arkanızı dönüp kaçmıştınız.'),
(9, 26, 10, 190, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'thumma anzele allāhu sakīnatahū ʿalā rasūlihī wa ʿalā l-muʾminīn wa anzele junūdan lam tarawhā wa ʿaḏḏaba lladhīna kafarū wa dhālika jazāʾu l-kāfirīn', 'Sonra Allah, Resûlüne ve müminlere sükûnetini indirdi. Sizin görmediğiniz orduları indirdi ve kâfir olanlara azap etti. İşte bu, kâfirlerin cezasıdır.'),
(9, 27, 10, 191, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'thumma yatūbu ʾallāhu mim baʿdi dhālika ʿalā man yashāʾu wa-ʾallāhu ghafūrun raḥīmun', 'Sonra Allah, bunun ardından dilediği kimsenin tevbesini kabul eder. Allah, Gafûr''dur, Rahîm''dir.'),
(9, 28, 10, 191, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ', 'yā ayyuhā lladhīna āmanū innamā l-mušrikūna nasasun falā yaqrabū l-masjida l-ḥarāma baʿda ʿāmihim hādhā wa in khiftum ʿaylatan fasawfa yughnīkumu llāhu min faḍlihi in shāʾa inna llāha ʿalīmun ḥakīmun', 'Ey iman edenler! Müşrikler ancak bir pisliktir. Bu yıldan sonra Mescid-i Haram''a yaklaşmasınlar. Eğer darlık görmekten korkarsanız, bilmiş olun ki Allah dilerse sizi kendi lütfundan zenginleştirecektir. Şüphesiz Allah bilendir, hikmet sahibidir.'),
(9, 29, 10, 191, 'قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَٰغِرُونَ', 'qātilū alladhīna lā yuʾminūna bi-llāhi wa-lā bi-l-yawmi l-ʾākhiri wa-lā yuḥarrimūna mā ḥarrama llāhu wa-rasūluhū wa-lā yadīnūna dīna l-ḥaqqi mina alladhīna ʾūtū l-kitāba ḥattā ʾyuʿṭū l-jizyata ʿan yadin wa-hum ṣāghirūna', 'Allah''a ve ahiret gününe inanmayan, Allah''ın ve Resûlü''nün haram kıldığını haram tanımayan ve hak dini benimsemeyen Ehl-i Kitap''tan olanlarla, o küçülerek kendi elleriyle cizyeyi verinceye kadar savaşın.'),
(9, 30, 10, 191, 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', 'waqālati l-yahūdu ʿuzayrun ibnu l-lāhi waqālati n-naṣārā l-masīḥu ibnu l-lāhi dhālika qawluhum bi-afwāhihim yuḍāhiʾūna qawla l-ladhīna kafarū min qablu qātaluhumu l-lāhu annā yuʾfakūna', 'Yahudiler, "Uzeyr Allah''ın oğludur" dediler. Hristiyanlar da, "Mesih Allah''ın oğludur" dediler. Bu, onların ağızlarıyla uydurdukları sözlerdir. (Onlar) daha önce inkâr edenlerin sözlerine benzetiyorlar. Allah onları kahretsin! Nasıl da (gerçekten) çevriliyorlar!'),
(9, 31, 10, 191, 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًا وَٰحِدًا لَّآ إِلَٰهَ إِلَّا هُوَ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ', 'ittakhadhū aḥbārahum wa ruhbānahum arbāban min dūni Allāh wa al-Masīḥa ibna Maryam wa mā umirū illā liyaʿbudū ilāhan wāḥidan lā ilāha illā huwa subḥānahū ʿammā yushrikūn', 'Onlar, Allah''ı bırakıp bilginlerini ve rahiplerini rablar edindiler; Meryem oğlu Mesih''i de. Oysa o, tek bir ilaha kulluk etmekle emrolunmuştu. O''ndan başka hiçbir ilah yoktur. Onların ortak koştukları şeylerden uzak ve yücedir.'),
(9, 32, 10, 192, 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'yurīdūna an yuṭfiʾū nūra llāhi biʾafwāhihim wayaʾbā llāhu ʾillā ʾan yutimma nūrāhu walaw kariha lkāfirūn', 'Ağızlarıyla Allah''ın nurunu söndürmek istiyorlar. Hâlbuki kâfirler istemese de Allah, nurunu tamamlamaktan başkasını istemez.'),
(9, 33, 10, 192, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 'huwa lladhī arsala rasūlahu bil-hudā wa dīni l-ḥaqqi liyuẓhirahu ʿalā d-dīni kullihī wa law kariha l-mušrikūn', 'O, Resûlü''nü hidayetle ve hak din ile gönderen O''dur. Onun (dinin) bütün dinlere üstün kılmak için, müşrikler hoşlanmasalar bile.'),
(9, 34, 10, 192, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'yā ayyuhā lladhīna āmānū inna kathīran mina l-aḥbāri wa-r-ruh''bāni layaʾkulūna amwāla n-nāsi bi-l-bāṭili wa yaṣud''dūna ʿan sabīli llāhi wa lladhīna yaknizūna dh-dhahaba wa-l-fiḍḍata wa lā yunfiqunahā fī sabīli llāhi fa bash''shirhum bi ʿadhābin alīmi', 'Ey iman edenler! Şüphesiz papazların ve rahiplerin birçoğu, insanların mallarını haksız yoldan yerler ve onları Allah yolundan alıkoyarlar. Altın ve gümüş biriktirip de Allah yolunda harcamayanlar var ya, işte onlara elem dolu bir azabı müjdele!'),
(9, 35, 10, 192, 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', 'yawma yuḥmā ʿalayhā fī nāri jahannama fatukwā bihā jibāhu hum wa junūbu hum wa ẓuhūru hum hādhā mā kanaztum li ʾanfusikum fadhūqū mā kuntum taknizūn', 'O gün, cehennem ateşinde onların alınları, yanları ve sırtları dağlanacak. İşte bu, sizin kendiniz için biriktirip sakladığınız şeydir. Biriktirip sakladıklarınızı tadın!'),
(9, 36, 10, 192, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَٰتِلُونَكُمْ كَآفَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'inna ''iddetesh-shuhuri ''indallahi ithnaa ''ashara shahran fi kitabi Allahi yawma khalaqas-samawati wal-ardha minhaa arba''atun hurumun dhalikad-dinu al-qayyim fala tadhlimoo feehenna anfusakum wa qatilool-mushrikeena kaffatan kama yuqatiloonakum kaffatan wa''lamoo anna Allaha ma''al-muttaqeen', 'Şüphesiz, Allah''ın gökleri ve yeri yarattığı günden beri, Allah''ın indinde ayların sayısı on ikidir. Bunlardan dördü haram aylardır. İşte bu, dosdoğru dindir. Bu aylarda kendinize zulmetmeyin. Bütün müşrikler size karşı topyekûn savaştıkları gibi siz de onlara karşı topyekûn savaşın. Ve bilin ki Allah, (günahlardan) korunanlarla beraberdir.'),
(9, 37, 10, 193, 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'ʾinnama n-nasīʾu ziyādatun fī l-kufri yuḍallu bihi l-laḏīna kafarū yuḥillūnahū ʿāman wa yuḥarrimūnahū ʿāman liyuwāṭiʾū ʿiddata mā ḥarrama ʾllāhu fayuḥillū mā ḥarrama ʾllāhu zuyyina lahum sūʾu ʾaʿmālihim wa ʾllāhu lā yahdī l-qawma l-kāfirīna', 'Nesî, küfürde bir ziyadeliktir. Kâfirler onunla sapıklığa düşürülürler; bir yıl onu helâl sayarlar, bir yıl da haram sayarlar ki Allah''ın haram kıldığının sayısına uysunlar da Allah''ın haram kıldığını helâl saymış olsunlar. Onların kötü amelleri kendilerine süslenmiş göründü. Allah kâfirler topluluğunu doğru yola eriştirmez.'),
(9, 38, 10, 193, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْءَاخِرَةِ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْءَاخِرَةِ إِلَّا قَلِيلٌ', 'yā ʾayyuhā lladhīna ʾāmanū mā lakum ʾidhā qīla lakumu nfirū fī sabīli llāhi ʾiththāqaltum ʾilā l-ʾarḍi ʾaraḍītum bil-ḥayāti d-dunyā mina l-ʾākhirati famā matāʿu l-ḥayāti d-dunyā fī l-ʾākhirati ʾillā qalīlun', 'Ey iman edenler! Size ne oluyor ki, "Allah yolunda topluca harb''e (cihada) çıkın!" dendiğinde, yere (dünyaya) ağırlık yapıp (yerinizde) ağırlaşıyorsunuz? Dünya hayatını ahiret hayatına karşılık mı seçtiniz? (Bilin ki) dünya hayatının (ahiret yanındaki) menfaati, ahirette (tahammül edilecek) az bir şeyden başka değildir.'),
(9, 39, 10, 193, 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'illā tanfirū yuʿaḏḏibkum ʿaḏāban alīman wa yastabdil qawman ġayrakum wa lā taḍurrūhu šayʾan wa llāhu ʿalā kulli šayʾin qadīrun', 'Eğer (cihad için) topluca harbde-y-e çıkmazsanız, sizi acı bir azabla muazzab eder ve sizden başka bir kavmı (yerinize) getirir ve siz ona hiçbir şeyle zarar veremezsiniz. Allah her şeye kadirdir.'),
(9, 40, 10, 193, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'illa tansurūhu faqad naṣarahu ʾllāhu ʾidh ʾakhrajahu ʾlladhīna kafarū thāniya ʾithnayni ʾidh humā fī ʾl-ghāri ʾidh yaqūlu li-ṣāḥibihi lā taḥzan ʾinna ʾllāha maʿanā fa-ʾanzala ʾllāhu sakīnatahū ʿalayhi wa-ʾayyada hū bi-junūdin lam tarawhā wa-jaʿala kalimata ʾlladhīna kafarū ʾs-suflā wa-kalimatu ʾllāhi hiya ʾl-ʿulyā wa-ʾllāhu ʿazīzun ḥakīmun', 'Siz ona yardım etmezseniz, Allah ona yardım etmişti. Hani kâfirler onu (Mekke''den) çıkardıkları zaman, ikinin biriydi; hani onlar mağaradaydılar. O, arkadaşına, ''Üzülme, çünkü Allah bizimle beraberdir'' diyordu. Bunun üzerine Allah onun üzerine sekinetini indirdi, onu görmediğiniz ordularla destekledi ve kâfirlerin sözünü alçalttı. Allah''ın sözü ise en yücedir. Allah aziz ve hakîm''dir.'),
(9, 41, 10, 194, 'ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'infirū khifāfan wa thiqālan wa jāhidū bi-amwālikum wa anfusikum fī sabīli Allāhi dhālikum khayrun lakum in kuntum taʿlamūn', 'Hafif ve ağır (yükümlülükte) olarak sefere çıkın ve mallarınızla ve canlarınızla Allah yolunda cihad edin. Eğer bilirseniz bu sizin için daha hayırlıdır.'),
(9, 42, 10, 194, 'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ', 'law kāna ʿaraḍan qarīban wa-safaran qāṣidan la-ttabaʿūka wa-lākin baʿudat ʿalayhimu sh-shuqqatu wa-sayahliifūna bi-llāhi law istaṭaʿnā la-kharajnā maʿakum yuhlikūna anfusahum wa-llāhu yaʿlamu innahum la-kādhibūna', 'Eğer dünya malı ve yakın bir sefer olsaydı, sana uyarlardı. Fakat onlara uzak bir mesafe ağır geldi. Yine de Allah''a yemin edecekler: ''Gücümüz yetseydi, sizinle birlikte çıkardık'' diyerek kendilerini helâk ederler. Allah onların yalancı olduklarını biliyor.'),
(9, 43, 10, 194, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ', 'ʿafā Allāhu ʿank lima ʾadzin-ta lahum ḥattā yatabayyana laka l-ladhīna ṣadaqū wa taʿlama l-kādhibīn', 'Allah seni affetti. Onlara (bu tebliğden sonra) ne diye izin verdin? Ta ki sana doğru söyleyenler belli oluncaya ve yalancıları bilinceye kadar (onlara izin vermemen gerekirdi).'),
(9, 44, 10, 194, 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 'lā yastaʾzinuka alladhīna yuʾminūna bi-llāhi wa-l-yawmi l-ʾākhiri an yujāhidū bi-ʾamwālihim wa-ʾanfusihim wa-llāhu ʿalīmun bi-l-muttaqīna', 'Allah''a ve ahiret gününe iman edenler, mallarıyla ve canlarıyla cihad etmek için senden izin istemezler. Allah takva sahiplerini bilir.'),
(9, 45, 10, 194, 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', 'innamā yastaʾzinuka llaḏīna lā yuʾminūna billāhi wal-yawmi l-ʾāḵiri wārtābat qulūbuhum fahum fī raybihim yataraddadūna', 'Ancak Allah''a ve ahiret gününe inanmayanlar ve kalpleri şüpheye düşmüş olanlar, kendi şüpheleri içinde bocalayanlar senden izin isterler.'),
(9, 46, 10, 194, 'وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ', 'Ve lev erādū el-ḫurūce le-eʿaddū lehu ʿuddeten Ve lākin kerihe Allāhu enbiʿāśehum fe-śebbeṭahum ve qīle eqʿudū meʿa el-qāʿidīne', 'Eğer çıkmak isteselerdi, elbette onun için bir hazırlık yaparlardı. Fakat Allah onların yola çıkmalarını kerih gördü de onları alıkoydu ve onlara, "Oturanlarla beraber oturun!" denildi.'),
(9, 47, 10, 194, 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'law kharajū fīkum mā zādūkum illā khabālan wa la-awḍaʿū khilālakum yabghūnakumu l-fitnata wa fīkum sammāʿūna lahum wa-llāhu ʿalīmun bi-ẓ-ẓālimīn', 'Eğer sizinle birlikte (seferde) çıksalardı, size azgınlıktan başka bir şeyde artış sağlamazlar ve aranıza fitne sokmak için koşarlardı. İçinizde onlara kulak verenler de vardır. Allah zalimleri bilir.'),
(9, 48, 10, 195, 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ', 'leḳadi-bteġavu-lfitnete min ḳabl ve ḳallebû leke-l''umûr ḥattâ câe-lḥaḳḳu ve żahera emru-llâhi ve hum kârihûn', 'Andolsun ki daha önce de fitne çıkarmak istemişlerdi. Sana karşı işleri altüst etmişlerdi. Nihayet hak geldi ve Allah''ın emri ortaya çıktı, oysa onlar istemiyorlardı.'),
(9, 49, 10, 195, 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'wa-minhum man yaqūlu ʾidhan lī walā taftinnī ʾalā fī l-fitnati saqaṭū wa-ʾinna Jahannama la-muḥīṭatun bil-kāfirīn', 'Onlardan öylesi de vardır ki: "Bana izin ver de fitneye düşmeyeyim" der. Haberiniz olsun ki, onlar zaten fitneye düşmüşlerdir. Ve şüphesiz ki cehennem, kâfirleri çepeçevre kuşatmıştır.'),
(9, 50, 10, 195, 'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', 'in tuṣibka ḥasanatun tasuʾhum wa in tuṣibka muṣībatun yaqūlū qad ʾakhadhnā ʾamranā min qablu wa yatawallaw wa hum fariḥūn', 'Eğer sana iyilik dokunursa, bu onları tasalandırır. Eğer başına bir musibet gelirse, "Zaten biz işimizi daha önce tedbir almıştık" derler ve onlar sevinerek (sana arkalarını dönüp) giderler.'),
(9, 51, 10, 195, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'qul lan yuṣībanā ʾillā mā kataba ʾallāhu lanā huwa mawlānā wa ʿalā ʾallāhi falyatawakkali l-muʾminūn', 'De ki: Allah''ın bizim için yazdığından başkası bize asla erişmez. O bizim Mevlamızdır. Ve müminler yalnız Allah''a güvenip dayansınlar.'),
(9, 52, 10, 195, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', 'qul hal tarabbaṣūna binā illā iḥdā al-ḥusnayayn wa naḥnu natarabbaṣu bikum an yuṣībakumu allāhu biʿadhābin min ʿindihī aw bi-aydīnā fatarabbaṣū innā maʿakum mutarabbaṣūn', 'De ki: "Siz bizim için iki güzellikteki şeylerden (zafer veya şehitlikten) başkasını mı bekliyorsunuz? Biz de sizin başınıza Allah tarafından bir azap gelmesini veya bizim elimizle azap olunmanızı bekleriz. Artık bekleyedurun! Şüphesiz biz de sizinle birlikte bekleyenleriz."'),
(9, 53, 10, 195, 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَٰسِقِينَ', 'Qul anfiqū ṭawʿan aw kargan lan yutaqabbala minkum ʾinnakum kuntum qawman fāsiqīn', 'De ki: İster gönüllü ister gönülsüz olarak harcayın, sizden asla kabul edilmeyecektir. Çünkü siz fasık bir kavim oldunuz.'),
(9, 54, 10, 195, 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ', 'wa mā manaʿahum an tuqbala minhum nafaqātuhum illā annahum kafarū billāhi wa birasūlihī wa lā yaʾtūna ṣ-ṣalāta illā wa hum kusālā wa lā yunfiqūna illā wa hum kārīhūn', 'Onların harcamalarının kabul edilmesini engelleyen şey, sadece Allah''a ve Resûlü''ne inanmamaları, namaza ancak isteksizce gelmeleri ve ancak istemeyerek harcamalarıdır.'),
(9, 55, 10, 196, 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'falā tuʿjibka ʾamwāluhum walā ʾawlāduhum ʾinnamā yurīdu ʾllāhu liyuʿaḏḏibahum bihā fī lḥayāti d-dunyā watazgoqa ʾanfusuhum wahum kāfirūn', 'Onların malları ve evlatları seni hayran bırakmasın. Allah, bunlarla onlara dünya hayatında azap etmek ve onların kafir oldukları halde canlarının çıkmasını istemektedir.'),
(9, 56, 10, 196, 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', 'wa-yaḥlifūna bi-llāhi ʾinnahum la-minkum wa-mā hum minkum wa-lākinna-hum qawmun yafraqūna', 'Onlar, sizin yemin ederler ki sizden oldukları halde, aslında sizden değillerdir. Fakat onlar korkudan böyle bir topluluktur.'),
(9, 57, 10, 196, 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', 'law yajidūna maljaʾan aw maghārātin aw muddakhallan la-wallaw ilayhi wa-hum yajmaḥūn', 'Onlar, bir sığınak veya (keşfedilmiş) mağaralar ya da girecek bir yer bulsalardı, ona doğru koşuşurlardı.'),
(9, 58, 10, 196, 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', 'wa-minhum man yalmiẓuka fī ṣ-ṣadaqāti fa-in uʿṭū min-hā raḍū wa-in lam yuʿṭaw min-hā idhā hum yaskhaṭūn', 'Onlardan öylesi de vardır ki, sadakalar (dağıtımı) hususunda sana dil uzatır. Eğer onlara (istedikleri) verilirse razı olurlar, verilmezse hemen kızarlar.'),
(9, 59, 10, 196, 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 'wa-law annahum raḍū mā ātāhumu llāhu wa-rasūluhū wa-qālū ḥasbunā llāhu sayuʾtīnā llāhu min faḍlihī wa-rasūluhū ʾinnā ʾilā llāhi rāghibūna', 'Onlar, Allah''ın ve Resûlü''nün kendilerine verdiğine razı olup da, "Allah bize yeter. Allah lütfundan ve Resûlü de bize ihsan edecektir. Şüphesiz biz Allah''a ragbet edenleriz" deselerdi, (daha hayırlı olurdu).'),
(9, 60, 10, 196, 'إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ فَرِيضَةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'ʾinnama ʾṣ-ṣadaqātu lil-fuqarāʾi wal-masākīni wal-ʿāmilīna ʿalayhā wal-muʾallafati qulūbuhum wa-fī ʾr-riqābi wal-ḡārimīna wa-fī sabīli ʾllāhi wa-ʾibni s-sabīli farīḍatan mina ʾllāhi wa-ʾllāhu ʿalīmun ḥakīmun', 'Sadakalar (zekâtlar) ancak şunlar içindir: düşkünler, miskinler, zekât toplayan memurlar, kalpleri (İslâm''a) ısındırılacak olanlar, (kölelikten kurtulmak için) esirler, borçlular, Allah yolunda (savaşanlar) ve yolda kalmışlar. Bu, Allah tarafından böyle farz kılınmıştır. Allah, her şeyi bilen, hikmet sahibidir.'),
(9, 61, 10, 196, 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ', 'Ve minhumullezîne yu''zûnennebiyye ve yekûlûne huve uzunun Kul uzunu hayrin lekum yu''minu billâhi ve yu''minu lil mu''minîne ve rahmetun lillezîne âmenû minkum Vellezîne yu''zûne resûlallâhi lehum azâbun elîmun', 'Onlardan öyleleri de vardır ki Peygamber''i incitirler ve “O (her söyleneni dinleyen) bir kulaktır” derler. De ki: “O, sizin için bir hayır kulağıdır. Allah''a inanır, müminlere de inanır (güvenir). Sizden iman edenler için bir rahmettir. Allah''ın Resûlü''nü incitenlere ise elem dolu bir azap vardır.”'),
(9, 62, 10, 197, 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', 'yaḥlifūna bi-llāhi lakum liyurḍūkum wa-llāhu wa-rasūluhū ʾaḥaqqu ʾan yurḍūhu ʾin kānū muʾminīn', 'Sizi razı etmek için Allah''a yemin ederler. Halbuki inanmış kimseler iseler, razı edilecekleri Allah ve Resûlüdür.'),
(9, 63, 10, 197, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًا فِيهَا ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', 'ʾelem yaʿlemū ʾennehū men yuḥāddi ʾllāhe wa rasūlahū faʾenne lehū nāra jahannama khālidan fīhā dhālika l-khizyu l-ʿaẓīmu', 'Allah''ın ve Resûlü''nün karşısına çıkan kimsenin, cehennem ateşine gireceğini ve orada ebedî kalacağını bilmediler mi? İşte bu, büyük bir rezilliktir.'),
(9, 64, 10, 197, 'يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ', 'yaḥẕaru l-munāfiqūna an tunazzala ʿalayhim surātun tunabbiʾuhum bimā fī qulūbihim quli stahziʾū ʾinna llāha mukhricun mā taḥẕarūn', 'Münafıklar, kalplerindekini kendilerine haber verecek bir sûrenin üzerlerine indirilmesinden çekinirler. De ki: ''Alay edin! Şüphesiz Allah, sizin çekindiğiniz şeyi ortaya çıkarıcıdır.'''),
(9, 65, 10, 197, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', 'Ve leʾin seʾeltehum leyaqūlunne innamā kunnā nakhūḍu ve nelʿabu Kul e bi-llāhi ve ʾāyātihī ve rasūlihī kuntum testehziʾūn', 'Andolsun ki onlara soracak olsan, "Biz sadece lafa dalmış şakalaşıyorduk" derler. De ki: "Allah ile, O''nun âyetleriyle ve Resûlü ile mi alay ediyordunuz?"'),
(9, 66, 10, 197, 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'Lā taʿtadhirū qad kafartum baʿda īmānikum In naʿfu ʿan ṭāʾifatin minkum nuʿadhdhib ṭāʾifatan bi-annahum kānū mujrimīn', 'Mazeret beyan etmeyin! İman ettikten sonra inkâr ettiniz. Sizden bir grubu affetsek de, bir başka grubu suçlu oldukları için azaplandıracağız.'),
(9, 67, 10, 197, 'ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ', 'al-munāfiqūna wa-al-munāfiqātu baʿḍuhum min baʿḍin yaʾmurūna bi-al-munkari wa-yanhawna ʿani al-maʿrūfi wa-yaqbiḍūna aydiyahum nasū al-lāha fa-nasīyahum inna al-munāfiqīna humu al-fāsiqūna', 'Münafık erkekler ve münafık kadınlar (birbirinin) benzeridir. Onlar kötülüğü emreder, iyilikten alıkoyarlar ve (hayır için) ellerini sıkı tutarlar. Allah''ı unutmuşlardır, bu yüzden Allah da onları unutmuştur. Şüphesiz münafıklar, fasıkların ta kendileridir.'),
(9, 68, 10, 197, 'وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا هِىَ حَسْبُهُمْ وَلَعَنَهُمُ ٱللَّهُ وَلَهُمْ عَذَابٌ مُّقِيمٌ', 'waʿada -llāhu -lmunāfiqīna wa-lmunāfiqāti wa-l-kuffāra nāra jahannama khālidīna fīhā hiya ḥasbuhum wa-laʿanahu -llāhu wa-lahum ʿaḏābun muqīmun', 'Allah, münafık erkeklerle münafık kadınlara ve kâfirlere, içinde ebedî kalacakları cehennem ateşini vaadetti. Bu onlara yeter. Allah onlara lânet etmiştir ve onlara ebedî azap vardır.'),
(9, 69, 10, 198, 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'kal-ladhīna min qablakum kānū ashadda minkum quwwatan wa-akthara amwālan wa-awlādan fastamtaʿū bi-khalāqihim fastamtaʿtum bi-khalāqikum kamā-stamtaʿa-lladhīna min qablukum bi-khalāqihim wa-khuḍtum ka-lladhī khāḍū ulāʾika ḥabiṭat aʿmāluhum fī-d-dunyā wa-l-ʾākhirati wa-ulāʾika humu-l-khāsirūn', 'Sizden öncekiler gibi; onlar sizden daha kuvvetli, daha çok mal ve evlât sahibi idiler. Kendi paylarına düşenle zevklenmişlerdi. Sizden öncekiler de kendi paylarına düşenle zevklendikleri gibi, siz de kendi paylarınıza düşenle zevklenmektesiniz. Tıpkı onların daldıkları gibi siz de daldınız. İşte onların amelleri dünyada da ahirette de boşa gitmiştir. İşte onlar ziyana uğrayanlardır.'),
(9, 70, 10, 198, 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'elem yeʾtihim nabaʾu ḷḷadhīna min qablihim qawmi nūḥin wa ʿādin wa thamūda wa qawmi ibrāhīma wa ʾaṣḥābi madyana wal-muʾtafikāti ʾatat-hum rusuluhum bil-bayyināti famā kāna ḷḷāhu liyaẓlimahum walākin kānū ʾanfusahum yaẓlimūna', 'Onlara, kendilerinden önceki Nuh kavminin, Âd ve Semûd''un, İbrahim kavminin, Medyen halkının ve altüst olan şehirlerin haberi gelmedi mi? Peygamberleri onlara apaçık deliller getirmişti. Allah onlara zulmetmiyordu; fakat onlar kendi kendilerine zulmediyorlardı.'),
(9, 71, 10, 198, 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'wa-l-muʾminūna wa-l-muʾminātu baʿḍuhum ʾawliyāʾu baʿḍin yaʾmurūna bi-l-maʿrūfi wa-yanhawna ʿani-l-munkari wa-yuqīmūna ṣ-ṣalāta wa-yuʾtūna z-zakāta wa-yuṭīʿūna -llāha wa-rasūlahū ʾulāʾika sayarḥamuhumu -llāhu ʾinna -llāha ʿazīzun ḥakīmun', 'Mü''min erkekler ve mü''min kadınlar birbirlerinin velileridir. İyiliği emreder, kötülükten vazgeçirir, namazı dosdoğru kılarlar, zekatı verirler. Allah''a ve Resûlü''ne itaat ederler. İşte Allah''ın kendilerine rahmet edeceği bunlardır. Şüphesiz Allah, Azîz''dir, Hakîm''dir.'),
(9, 72, 10, 198, 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'waʿada ʾllāhu l-muʾminīna wa-l-muʾmināti jannātin tajrī min taḥtihā l-ʾanhāru khālidīna fīhā wa-masākina ṭayyibatan fī jannāti ʿadnin wa-riḍwānun mina ʾllāhi ʾakbaru ḏālika huwa l-fawzu l-ʿaẓīmu', 'Allah, mümin erkeklere ve mümin kadınlara, altlarından ırmaklar akan, içinde ebedi kalacakları cennetler ve Adn cennetlerinde hoş mekanlar vaadetti. Allah''ın rızası ise hepsinden büyüktür. İşte bu, büyük kurtuluştur.'),
(9, 73, 10, 199, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'yā ayyuhā n-nabiyyu jāhidi l-kuffāra wa-l-munāfiqīn wa-ghluẓ ʿalayhim wa-maʾwāhum jahanam wa-biʾsa l-maṣīr', 'Ey Peygamber! Kâfirlerle ve münafıklarla cihad et ve onlara karşı sert davran. Onların varacağı yer cehennemdir. Ne kötü bir dönüş yeridir o!'),
(9, 74, 10, 199, 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'yaḥlifūna bi-llāhi mā qālū wa-laqad qālū kalimata l-kufri wa-kafarū baʿda islāmihim wa-hammū bimā lam yanālū wa-mā naqamū illā an aghnāhumu llāhu wa-rasūluhū min faḍlihī fa-in yatūbū yaku khayran lahum wa-in yatawallaw yuʿadhdhibhumu llāhu ʿadhāban alīman fī d-dunyā wa-l-ʾākhirati wa-mā lahum fī l-ʾarḍi min waliyyin wa-lā naṣīrin', 'Allah''a yemin ederler ki söylemediler. Andolsun ki küfür sözünü söylemişlerdi ve Müslüman olmalarından sonra kâfir olmuşlardı. Yapamayacakları şeylere de kastetmişlerdi. İntikam almalarının tek sebebi, Allah''ın ve Resûlü''nün lütfundan onları zenginleştirmiş olmasıydı. Eğer tevbe ederlerse, bu onlar için daha hayırlıdır. Eğer yüz çevirirlerse, Allah onları dünyada da ahirette de elem dolu bir azapla cezalandıracaktır. Ve onların yeryüzünde bir dostu da bir yardımcısı da yoktur.'),
(9, 75, 10, 199, 'وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ', 'wa-minhum man ʿāhada Allāha la-in ātānā min faḍlihi la-naṣṣaddaqanna wa-la-nakūmanna mina ṣ-ṣāliḥīn', 'Onlardan, "Andolsun ki Allah bize lütfundan verirse, mutlaka tasaddukta bulunacağız ve mutlaka salihlerden olacağız" diye Allah''a ahdedenler de vardır.'),
(9, 76, 10, 199, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'fe-lemmā ʾātāhum min faḍlihī bakhilū bihī wa-tawallaw wa-hum muʿriḍūn', 'Kendilerine O''nun bol fazlından verdiği gelince, ona cimrilik ettiler ve yüz çevirdiler. Zaten onlar, (haktan) yüz çevirenlerdi.'),
(9, 77, 10, 199, 'فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', 'faʾaʿqabahum nifāqan fī qulūbihim ʾilā yawmi yalqūnahū bimā ʾakhlafū ʾllāha mā waʿadūhu webimā kānū yakdhibūn', 'Böylece Allah''a verdikleri sözden caydıkları ve yalan söylemekte oldukları için, O''na kavuşacakları güne kadar kalplerine bir nifak (münafıklık) soktu.'),
(9, 78, 10, 199, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ', 'ʾelem yaʿlemū ʾenne ʾallāhe yaʿlemu sirrehum ve-necvāhum ve-ʾenne ʾallāhe ʿallāmu l-ġuyūb', 'Onlar, Allah''ın onların sırrını da, fısıltılarını da bildiğini ve Allah''ın gaybı çok iyi bilen olduğunu bilmediler mi?'),
(9, 79, 10, 199, 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'alladhīna yalmazūna l-muṭṭawwiʿīna mina l-muʾminīna fī ṣ-ṣadaqāti wa-lladhīna lā yajidūna illā juhdahum fa-yaskharūna minhum sakhiro l-lāhu minhum wa-lahum ʿadhābun alīmun', 'Onlar, hayırda gönül hoşluğu ile (mal) verenleri ve (mallarından) isteğe bağlı olarak bir şey bulamayanları (emekleriyle katkıda bulunanları) ayıplayanlar, onları alay edenlerdir. Allah onları alaya almıştır ve onlar için elem dolu bir azap vardır.'),
(9, 80, 10, 200, 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'istagfir lehum ev la testagfir lehum in testagfir lehum seb''iyne merreten felen yagfira allahu lehum zalike bi''ennehum keferu billahi ve resulihi wallahu la yehdi''l-kawme''l-fasikiyne', 'Onlar için ister bağışlanma dile, ister dileme! Onlar için yetmiş defa bağışlanma dilesen de Allah onları asla bağışlamayacaktır. Bu böyledir, çünkü onlar Allah''ı ve Resûlü''nü inkâr ettiler. Allah ise yoldan çıkmış bir topluluğu doğru yola iletmez.'),
(9, 81, 10, 200, 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا۟ يَفْقَهُونَ', 'fariḥa l-mukhallaifūna bimaqʿadihim ḫilāfa rasūli llāhi wa karihū an yujāhidū bi-amwālihim wa-anfusihim fī sabīli llāhi wa qālū lā tanfirū fī l-ḥarri qul nāru jahannama ašaddu ḥarran law kānū yafqahūna', 'Seferden (cihattan) geri bırakılanlar, Allah''ın Resûlü''ne muhalefet ederek (evlerinde) oturup kalmaları yüzünden sevindiler. Mallarıyla ve canlarıyla Allah yolunda cihad etmekten hoşlanmadılar ve ''Bu sıcakta sefere çıkmayın'' dediler. De ki: ''Cehennem ateşi daha sıcaktır.'' Eğer anlıyor olsalardı.'),
(9, 82, 10, 200, 'فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'falyaḍḥakū qalīlan walya''bū kathīran jazāʾam bimā kānū yaksibūn', 'Şimdi az gülsünler, çok ağlasınlar! Bu, kazanmakta olduklarının bir karşılığıdır.'),
(9, 83, 10, 200, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ', 'fa-ʾin rajaʿaka ʾallāhu ʾilā ṭāʾifatin minhum fa-staʾḏanūka lil-xurūǧi fa-qul lan taxrūǧū maʿiya ʾabadan wa-lan tuqātilū maʿiya ʿaduwwan ʾinnakum raḍītum bil-quʿūdi ʾawwala marratin fa-qʿudū maʿa l-xālifīna', 'Eğer Allah seni onlardan bir gruba döndürürse ve onlar senden (savaşa) çıkmak için izin isterlerse, de ki: "Ben sizinle hiçbir zaman çıkmayacağım ve sizinle birlikte hiçbir düşmana karşı savaşmayacağım. Çünkü siz ilk defa (savaşa) oturmaya razı oldunuz. Artık (evde) oturanlarla birlikte oturun."'),
(9, 84, 10, 200, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ', 'wa-lā tuṣalli ʿalāʾi ʾaḥadin min-hum māta ʾabadan wa-lā taqum ʿalā qabrihī ʾinnahum kafarū bi-llāhi wa-rasūlihī wa-mātū wa-hum fāsiqūn', 'Onlardan ölen hiç kimse için asla namaz kılma ve kabrinin başında da durma. Çünkü onlar Allah''a ve Resûlü''ne kâfir olmuşlardır ve fasık olarak ölmüşlerdir.'),
(9, 85, 10, 200, 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'wa-lā tuʿjibka ʾamwāluhum wa-ʾawlāduhum ʾinnamā yurīdu ʾllāhu ʾan yuʿaḏḏibahum bihā fī ʾd-dunyā wa-tazhaqa ʾanfusuhum wa-hum kāfirūn', 'Onların malları ve evlatları seni hayran bırakmasın; Allah bunlarla onları dünyada azaplandırmak ve onların canlarının kâfirler olarak çıkmasını istemektedir.'),
(9, 86, 10, 200, 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ', 'wa-idhā unzilat sūratun an āminū bi-llāhi wa-jāhidū maʿa rasūlihi istaʾżanaka ūlū ṭ-ṭawli minhum wa-qālū dharnā nakun maʿa l-qāʿidīn', 'Onlara, ''Allah''a iman edin ve Resûlü ile birlikte cihad edin'' diye bir sûre indirildiğinde, onlardan servet sahibi olanlar, ''Bırak bizi de oturanlarla birlikte oturalım'' diyerek senden izin isterler.'),
(9, 87, 10, 201, 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'raḍū biʾan yakūnū maʿa l-khawāliﬁ wa ṭubiʿa ʿalā qulūbihim fahum lā yafqahūn', 'Onlar, geride kalanlarla birlikte bulunmaya razı oldular. Ve kalpleri mühürlendi, bu yüzden onlar anlamazlar.'),
(9, 88, 10, 201, 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'lākin ar-rasūlu wa-lladhīna ʾāmanū maʿahu ǧāhadū bi-ʾamwālihim wa-ʾanfusihim wa-ʾulāʾika lahumu l-ḫayrātu wa-ʾulāʾika humu l-mufliḥūna', 'Fakat Peygamber ve onunla birlikte iman edenler, mallariyle ve canlariyle cihat ederler. İşte bunlar, hayir isleyenlerdir. Ve işte bunlar, kurtulusa erenlerdir.'),
(9, 89, 10, 201, 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'aʿadda ʾallāhu lahum jannātin tajrī min taḥtihā ʾalʾanhāru khālidīna fīhā ḏālika ʾal-fawzu ʾalʿaẓīmu', 'Allah onlara, içinde ebedi kalacakları, altlarından ırmaklar akan cennetler hazırlamıştır. İşte bu büyük kurtuluştur.'),
(9, 90, 10, 201, 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', 'wa jāʾa l-muʿaḏḏirūna mina l-ʾaʿrābi liyūʾḏana lahum wa qaʿada l-laḏīna kaḏabū l-lāha wa rasūlahū sayuṣību l-laḏīna kafarū minhum ʿaḏābun ʾalīmun', 'Bedevîlerden (mazeret) bildirenler geldiler, kendilerine (seferden geri kalmak için) izin verilsin diye. Allah''a ve Resûlü''ne yalan söyleyenler ise oturdular. Onlardan kâfir olanlara elem dolu bir azap isabet edecektir.'),
(9, 91, 10, 201, 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'laysa ʿalā ḍ-ḍuʿafāʾi wa-lā ʿalā l-marḍā wa-lā ʿalā lladhīna lā yajidūna mā yunfiqūna ḥarajun idhā naṣaḥū lillāhi wa-rasūlihī mā ʿalā l-muḥsinīna min sabīlin wa-llāhu ghafūrun raḥīmun', 'Zayıflar, hastalar ve harcayacak bir şey bulamayanlar için (sorumluluk) yoktur; meğer ki Allah''a ve Resûlüne karşı samimi olduklarında (sorumlulukları olur). İyilik edenlere karşı (sorumluluk) yolu yoktur. Allah, çok bağışlayandır, çok merhamet edendir.'),
(9, 92, 10, 201, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', 'walā ʿalā allaḏīna iḏā mā atawka litaḥmilahum qulta lā ʾajidu mā ʾaḥmilukum ʿalayhi tawallaw waʾaʿyunuhum tafīḍu mina ʾad-damʿi ḥazanāan ʾallā yajidū mā yunfiqūn', 'Onlar, sana, kendilerini bindirecek bir şey bulamadığın zaman, ''Size bindirecek bir şey bulamıyorum'' dediğin için, üzüntüden gözleri yaşlarla dolarak geri dönenler için de (sorumluluk) yoktur. Çünkü onlar, harcayacak bir şey bulamadılar.'),
(9, 93, 11, 201, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', 'innamā as-sabīlu ʿalā alladhīna yastaʾdhinūnaka wa-hum aghniyāʾu raḍū bi-an yakūnū maʿa al-khawāliﬁ wa-ṭabaʿa ʾallāhu ʿalā qulūbihim fa-hum lā yaʿlamūna', 'Yol, ancak zengin oldukları halde senden izin isteyenleredir. Onlar, geride kalanlarla birlikte olmaktan razı olmuşlardır. Allah da onların kalplerini mühürlemiştir, bu yüzden onlar bilmezler.'),
(9, 94, 11, 202, 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'yaʿtaḏirūna ʾilaykum ʾiḏā rajaʿtum ʾilayhim qul lā taʿtaḏirū lan nuʾmina lakum wasayarā allāhu ʿamalakum warasūluhū ṯumma turaddūna ʾilā ʿālimi l-ġaybi waš-šahādati fayunabbiʾukum bimā kuntum taʿmalūna', 'Size döndüğünüzde mazeret ileri sürecekler. De ki: ''Mazeret ileri sürmeyin; bize yalan söylediğinizi zaten Allah bize haber verdi. Allah sizin işinizi ve Peygamberi de görecektir. Sonra gizli ve aşikar her şeyi bilen Allah''a döndürüleceksiniz de O size yapmakta olduklarınızı haber verecektir.'''),
(9, 95, 11, 202, 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ فَأَعْرِضُوا۟ عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'sayaḥlifūna bil-lāhi lakum iðā nqalabtum ilayhim lituʿriḍū ʿanhum fa-aʿriḍū ʿanhum innahum rijsun wa-maʾwāhum jaḥannamu jazāʾan bimā kānū yaksibūn', 'Size, kendilerine döndüğünüzde, onlardan yüz çeviresiniz diye Allah''a yemin edecekler. Yüz çevirin onlardan! Çünkü onlar pisliktir. Kazandıklarına karşılık varacakları yer cehennemdir.'),
(9, 96, 11, 202, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'yaḥlifūna lakum litarḍaw ʿanhum fa-in tarḍaw ʿanhum fa-inna Allāha lā yarḍā ʿani l-qawmi l-fāsiqīn', 'Sizden razı olsunlar diye Allah''a yemin ederler. Eğer siz onlardan razı olsanız bile, Allah fasık topluluktan razı olmaz.'),
(9, 97, 11, 202, 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'al-aʿrābu ʾašaddu kufran wa-nifāqan wa-ʾajdaru ʾallā yaʿlamū ḥudūda mā ʾanzala ʾallāhu ʿalā rasūlihī wa-ʾallāhu ʿalīmun ḥakīmun', 'Bedevîler küfür ve münafıklık bakımından daha şiddetlidir. Allah''ın elçisine indirdiği sınırları bilmemeye daha layıktırlar. Allah ise bilendir, hikmet sahibidir.'),
(9, 98, 11, 202, 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'wa mina l-aʿrābi man yattakhiḏu mā yunfiqu maġraman wa yatarabbaṣu bikumu d-dawāʾira ʿalayhim dāʾiratu s-sawʾi wa llāhu samīʿun ʿalīmun', 'Bedevilerden öylesi vardır ki, (Allah yolunda) harcadığını bir angarya sayar ve sizin başınıza belalar gelip çatması için (onun) aleyhinizde dönmesini bekler. O kötü akıbetin kendi başlarına gelmesi (mümkündür). Allah, hakkıyla işitendir, bilendir.'),
(9, 99, 11, 202, 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 've minel-aʿrābi men yuʾminu billāhi vel-yevmil-ʾākhiri ve yettekhidhu mā yunfiqu qurbātin ʿindallāhi ve ṣalawātil-rasūli ʾalā ʾinnahā qurbatun lahum seyudkhiluhumullāhu fī raḥmatihī ʾinnallāha ġafūrun raḥīmun', 'Bedevilerden öylesi de vardır ki, Allah''a ve ahiret gününe inanır, (hayır için) harcadığını Allah katında bir yakınlığa ve Peygamber''in dualarına vesile edinir. Haberiniz olsun ki, bu onlar için bir yakınlıktır. Allah onları rahmetine kabul edecektir. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir.'),
(9, 100, 11, 203, 'وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'wa-s-sābiqūna l-awwalūna mina l-muhājirīna wa-l-ʾanṣāri wa-lladhīna ttabaʿūhum bi-ʾiḥsānin raḍiya -llāhu ʿanhum wa-raḍū ʿanhu wa-ʾaʿadda lahum jannātin tajrī taḥtahā l-ʾanhāru khālidīna fīhā ʾabadan dhālika l-fawzu l-ʿaẓīmu', 'Muhacirlerden ve Ensar''dan ilkleri ve onlara güzellikle uyanlar... Allah onlardan razı oldu, onlar da O''ndan razı oldular. Onlar için altlarından ırmaklar akan, içinde ebedi kalacakları cennetler hazırladı. İşte bu, büyük kurtuluştur.'),
(9, 101, 11, 203, 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ وَمِنْ أَهْلِ ٱلْمَدِينَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ', 'wa mimman hawlakum minal-aʿrābi munāfiqūn wa min ahli l-madīnati maradū ʿalan-nifāqi lā taʿlamuhum naḥnu naʿlamuhum sanuʿadhdhibuhum marratayn thumma yuraddūna ilā ʿadhābin ʿaẓīm', 'Çevrenizdeki bedevilerden münafıklar vardır. Medine halkından da münafıklıkta direnenler vardır. Sen onları bilmezsin, biz biliriz. Biz onları iki defa azaplandıracağız, sonra da büyük bir azaba uğratılacaklardır.'),
(9, 102, 11, 203, 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'wa-ʾākhirūna ʾiʿtarafū bi-dhunūbihim khalaṭū ʿamalan ṣāliḥan wa-ʾākhara sayyiʾan ʿasā ʾallāhu ʾan yatūba ʿalayhim ʾinna ʾallāha ghafūrun raḥīmun', 'Ve diğerleri günahlarını itiraf ettiler. Salih bir ameli başka bir kötü ile karıştırmışlardır. Umulur ki Allah onların tevbesini kabul eder. Şüphesiz Allah, Gafur''dur, Rahim''dir.'),
(9, 103, 11, 203, 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'khudh min amwālihim ṣadaqatan tuṭahhiruhum wa tuzakkīhim bihā wa ṣalli ʿalayhim ʾinna ṣalātaka sakanun lahum wa-llāhu samīʿun ʿalīmun', 'Onların mallarından sadaka al; bununla onları temizler, onları arındırırsın. Ve onlara dua et. Şüphesiz senin duaların onlara bir huzur ve dinginliktir. Allah, hakkıyla işitendir, bilendir.'),
(9, 104, 11, 203, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'ʾelem yaʿlemū ʾenne ʾallāhe huve yaqbelu t-tevbeta ʿan ʿibādihī ve yaʾḫuḏu ṣ-ṣadaqāti ve ʾenne ʾallāhe huve t-tevvābu r-raḥīmu', 'Onlar, Allah''ın kullarının tevbesini kabul eden, sadakaları (zekatları) alan ve şüphesiz Allah''ın tevbeleri kabul eden, esirgeyen olduğunu bilmediler mi?'),
(9, 105, 11, 203, 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'waquli ʿmalū fasa yarā allāhu ʿamalakum warasūluhū wal-muʾminūn wasaturaddūna ʾilā ʿālami l-ghaybi wash-shahādati fayunabbiʾukum bimā kuntum taʿmalūn', 'De ki: "(Herkes) amelini yapsın! Allah sizin amelinizi de, Resûlü de, müminler de görecektir. Ve gaybı ve görüneni bilen (Allah''a) döndürüleceksiniz de O size yapmakta olduklarınızı haber verecektir."'),
(9, 106, 11, 203, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'wa-ʾākhirūna murjawna li-ʾamri-llāhi ʾimmā yuʿaḏḏibuhum wa-ʾimmā yatūbu ʿalayhim wa-llāhu ʿalīmun ḥakīmun', 'Ve diğerleri de Allah''ın emrine bırakılmışlardır; ya onlara azap edecek, ya da tevbelerini kabul edecektir. Allah, her şeyi bilen, hikmet sahibi olandır.'),
(9, 107, 11, 204, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 'wa-lladhīna-ttakhadhū masjidan ḍirāran wa-kufran wa-tafrīqan bayna-l-muʾminīna wa-irṣādan liman ḥāraba-llāha wa-rasūlahū min qablu wa-la-yaḥlifunna in ʾaradnā ʾillā-l-ḥusnā wa-llāhu yashhadu ʾinnahum la-kādhibūna', 'Yine onlar, (müminlere) zarar vermek, küfretmek, müminlerin arasını ayırmak ve daha önce Allah''a ve Resûlü''ne karşı savaşmış olanı (orada) gözlemek için bir mescit edinenler de vardır. Onlar, ''Bizim iyilikten başka bir kastımız yok'' diye mutlaka yemin edecekler. Ama Allah onların yalancı olduklarına şahitlik eder.'),
(9, 108, 11, 204, 'لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', 'lā taqum fīhi abadan lamesjidun ussisa ʿalā t-taqwā min awwali yawmin aḥaqqu an taqūma fīhi fīhi rijālun yuḥibbūna an yataṭahharū wa-llāhu yuḥibbu l-muṭṭahhirīn', 'O namazgâhta asla (namaza) durma! İlk günden takva (Allah korkusu ve saygısı) üzerine kurulu olan, namaza durmaya daha layık olan bir mescit (vardır). Onda, temizlenmeyi seven adamlar vardır. Allah da temizlenenleri sever.'),
(9, 109, 11, 204, 'أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'ʾafaman ʾassasa bunyānahū ʿalā taqwah min Allāhi wa-riḍwānin ḵayrun ʾam man ʾassasa bunyānahū ʿalā šafā ǧurufin hārin fa-nʾhāra bihī fī nāri ǧahannam wa-Allāhu lā yahdī l-qawma ẓ-ẓālimīn', 'Binasını Allah''tan korkarak ve O''nun rızasını kazanma niyetiyle kuran kimse mi daha hayırlıdır, yoksa binasını uçuruma yaslayıp da onunla birlikte cehennem ateşine yuvarlanan kimse mi? Allah zalimler topluluğunu doğru yola iletmez.'),
(9, 110, 11, 204, 'لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'lā yazālu bunyānuhumu lladhī banaw riybatan fī qulūbihim illā an taqaṭṭaʿa qulūbuhum wallāhu ʿalīmun ḥakīmun', 'Yaptıkları bina, kalplerinde bir şüphe olarak kalmaya devam eder; ancak kalplerinin parçalanması müstesna. Allah, bilendir, hikmet sahibidir.'),
(9, 111, 11, 204, 'إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'inna llāha śtarā mina l-muʾminīna ʾanfusahum wa-ʾamvāluhum bi-ʾanna lahumu l-jannata yuqātilūna fī sabīli llāhi fa-yaqtulūna wa-yuʾqtalūna waʿdan ʿalayhi ḥaqqan fī t-tawrāti wa-l-ʾinjīli wa-l-qurʾāni wa-man ʾawfā bi-ʿahdihi mina llāhi fa-stabiširū bi-bayʿikumu l-laḏī bāyaʿtum bihi wa-ḏālika huwa l-fawzu l-ʿaẓīmu', 'Şüphesiz Allah, mü''minlerden canlarını ve mallarını, kendilerine (verilecek) cennet karşılığında satın almıştır. Onlar Allah yolunda savaşırlar, öldürürler ve ölürler. Bu, O''nun Tevrat''ta da, İncil''de de, Kur''an''da da kendi üzerine kesinleşmiş bir vaadidir. Verdiği sözü Allah''tan daha çok kim yerine getirebilir? O halde, yaptığınız bu alışverişten dolayı sevinin. İşte bu, büyük kurtuluştur.'),
(9, 112, 11, 205, 'ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْءَامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'at-tāʾibūna al-ʿābidūna al-ḥāmidūna as-sāʾiḥūna ar-rākiʿūna as-sājidūna al-ʾāmirūna bi-l-maʿrūf wa-n-nāhūna ʿani l-munkari wa-l-ḥāfiẓūna li-ḥudūdi llāh wa-bashshiri l-muʾminīn', 'Onlar, tövbe edenler, ibadet edenler, hamdedenler, oruç tutanlar, rükû edenler, secde edenler, iyiliği emredip kötülükten alıkoyanlar, Allah''ın sınırlarını koruyanlardır. Ve mü''minlere müjde ver.'),
(9, 113, 11, 205, 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ', 'mā kāna li-n-nabiyyi wa-lladhīna ʾāmanū ʾan yastaghfirū li-l-mushrikīna wa-law kānū ʾūlī qurbā min baʿdi mā tabayyana lahum ʾannahum ʾaṣḥābu l-jaḥīmi', 'Ne peygamberin ne de müminlerin, -onlar cehennem ehli oldukları kendilerine açıkça belli olduktan sonra- akrabaları olsalar bile, Allah''a ortak koşanlar için bağışlanma dilemeleri söz konusu olamaz.'),
(9, 114, 11, 205, 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ', 'wa mā kāna istighfāru ibrāhīma li-abīhi illā ʿan mawʿidatin waʿadahā ʾiyyāhu falammā tabayyana lahu ʾannahu ʿadūwun lillāhi tabarraʾa minhu ʾinna ibrāhīma la-ʾawwāhun ḥalīmun', 'İbrahim''in babası için af dilemesi, ancak ona verdiği bir sözden dolayı idi. Vaktâ ki ona, Allah''ın düşmanı olduğu açıkça belli olunca, ondan uzaklaştı. Şüphesiz İbrahim, çok içli, yumuşak huylu idi.'),
(9, 115, 11, 205, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 've mā kāna llāhu li-yuḍilla qawman baʿda iḏ hādāhum ḥattā yubayyina lahum mā yattaqūna ʾinna llāha bikulli šayʾin ʿalīmun', 'Allah, bir topluluğu doğru yola ilettikten sonra, onlara sakınacakları şeyleri açıklayıncaya kadar saptıracak değildir. Şüphesiz Allah her şeyi hakkıyla bilendir.'),
(9, 116, 11, 205, 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'ʾinna ʾallāha lahū mulku s-samāwāti wa-l-ʾarḍi yuḥyī wa-yumītu wa mā lakum min dūni ʾallāhi min waliyyin wa lā naṣīrin', 'Şüphesiz göklerin ve yerin mülkü Allah''ındır. O, diriltir ve öldürür. Ve sizin için Allah''tan başka ne bir dost ne de bir yardımcı vardır.'),
(9, 117, 11, 205, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ', 'leḳad tâba-llâhu `ale-nnebiyyi velmuhâcirîne vel''enṣâri-lleẕîne-ttebe`ûhu fî sâ`ati-l`usra min ba`di mâ kâde yezîġu ḳulûbu ferîḳin minhüm ŝümme tâbe `aleyhim innehu bihim raûfun raḥîm', 'Andolsun ki Allah, Peygamber''in, güçlük anında ona uyan muhacirlerin ve ensarın tevbelerini kabul etti. Onlardan bir kısmının kalpleri neredeyse kaymak üzereyken (Allah, onların tevbelerini kabul etti). Sonra yine onların tevbelerini kabul etti. Şüphesiz O, onlara karşı çok şefkatli, çok merhametlidir.'),
(9, 118, 11, 206, 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'wa ʿalā ṯ-ṯalāṯati l-laḏīna ḵullifū ḥattā ʾiḏā ḍāqat ʿalayhimu l-ʾarḍu bimā raḥubat wa ḍāqat ʿalayhim ʾanfusuhum wa ẓannū ʾan lā maljaʾa mina llāhi ʾillā ʾilayhi ṯumma tāba ʿalayhim li-yatūbū ʾinna llāha huwa t-tawwābu r-raḥīmu', 'Ve (muharebeye katılmayıp) geri bırakılan üç kişi de onların durumuna düştü. Nihayet o kadar ki, genişliğine rağmen yeryüzü onlara dar gelmeye başladı ve kendilerini de (canlarından) sıktılar. Allah''tan yine O''na sığınmaktan başka bir sığınak olmadığını anladılar. Sonra tevbe etmeleri için onların tevbesini kabul etti. Şüphesiz Allah, tevbeleri kabul edendir, esirgeyendir.'),
(9, 119, 11, 206, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ', 'yā ayyuhā alladhīna āmānū ittaqū allāh wa kūnū maʿa ṣ-ṣādiqīn', 'Ey iman edenler! Allah’tan korkun ve doğrularla beraber olun.'),
(9, 120, 11, 206, 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَٰلِحٌ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'mā kāna li-ʾahli l-madīnati wa-man ḥawlahum mina l-ʾaʿrābi ʾan yataḵallafū ʿan rasūli llāhi wa-lā yarğabū bi-ʾanfusihim ʿan nafsihiyy ḏālika bi-ʾannahum lā yuṣībuhum ẓamaʾun wa-lā naṣabun wa-lā maḵmaṣatun fī sabīli llāhi wa-lā yaṭaʾūna mawṭiʾan yagīẓu l-kuffāra wa-lā yanālūna min ʿaduwwin naylan ʾillā kutiba lahum bihiyy ʿamalun ṣāliḥun ʾinna llāha lā yuḍīʿu ʾajra l-muḥsinīna', 'Medine halkına ve çevresindeki bedevilere, Allah''ın Resûlü''nden geri kalmak ve O''nunla birlikte cihaddan yüz çevirip kendi canlarını onun canına tercih etmek yaraşmaz. Çünkü onların Allah yolunda başına gelen her susuzluk, her yorgunluk ve her açlık, yahut kâfirleri çileden çıkaran her hangi bir yere ayak basmaları ve düşmana karşı her hangi bir başarı kazanmaları, mutlaka kendileri için salih bir amel olarak yazılır. Şüphesiz Allah, iyilik edenlerin mükâfatını zâyi etmez.'),
(9, 121, 11, 206, 'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', 'wa-lā yunfiqūna nafaqatan ṣaḡīratan wa-lā kabīratan wa-lā yaqṭaʿūna wādiyan illā kutiba lahum li-yajziyahumu ʾllāhu ʾaḥsana mā kānū yaʿmalūna', 'Onlar, küçük veya büyük hiçbir harcama yapmazlar ve hiçbir vadiyi geçmezler ki, yaptıkları işin daha güzeliyle karşılık vermesi için haklarında (o amelleri) yazılmış olmasın.'),
(9, 122, 11, 206, 'وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', 'wa mā kāna l-muʾminūna li-yanfirū kāffatan fa-lawlā nafara min kulli firqatin minhum ṭāʾifatun li-yatafaqqahū fī d-dīni wa li-yunḏirū qawmahum iḏā rajaʿū ilayhim laʿallahum yaḥḏarūn', 'Hep birlikte seferber olmaları mü''minlere yaraşmaz. Her kaleden bir topluluk da dinde derin bilgi edinmek ve kavimleri savaştan döndüklerinde onları uyarmak için gelmeli değil midir? Umulur ki onlar da (günah işlemekten) sakınırlar.'),
(9, 123, 11, 207, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'yā ayyuhā l-ladhīna āmanū qātilū l-ladhīna yalūnakum mina l-kuffāri wa-l-yajidū fīkum ghiẓatan wa-ʿlamū anna l-lāha maʿa l-muttaqīna', 'Ey iman edenler! Size yakın olan kâfirlerle savaşın; onlar sizde bir sertlik bulsunlar. Ve Allah''ın, müttakîlerle beraber olduğunu bilin.'),
(9, 124, 11, 207, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًا وَهُمْ يَسْتَبْشِرُونَ', 'wa-idhā mā unzilat sūratun faminhum man yaqūlu ayyukum zādathu hādhihi īmānan fa-ammā alladhīna āmanū fazādathum īmānan wa-hum yastabshirūna', 'Bir sure indirildiğinde, onlardan kimi: "Bu, hanginizin imanını artırdı?" der. İman edenlere gelince, bu onların imanını artırmıştır ve onlar buna sevinirler.'),
(9, 125, 11, 207, 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ', 'waʾammā alladhīna fī qulūbihim maraḍun fazādat-hum rijsan ʾilā rijsihim wamātū wahum kāfirūna', 'Kalplerinde hastalık olanlara gelince, bu (Kur''an) onların pisliğini pisliklerinin üzerine artırmıştır ve onlar kâfir olarak ölmüşlerdir.'),
(9, 126, 11, 207, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', 'ʾawallā yarawna ʾannahum yuftanaūna fī kulli ʿāmin marratan ʾaw marratayni thumma lā yatūbūna walā hum yadhdhakkarūna', 'Onlar, her yıl bir veya iki defa imtihana tabi tutulduklarını görmüyorlar mı? Sonra da ne tövbe ediyorlar ne de öğüt alıyorlar.'),
(9, 127, 11, 207, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'wa-idhā mā unzilat sūratun naẓara baʿḍuhum ilā baʿḍin hal yarākum min aḥadin thumma nṣarafū ṣarafa -llāhu qulūbahum bi-annahum qawmun lā yafqahūna', 'Bir sure indirildiği zaman, birbirlerine bakarlar: ''Sizi birisi görüyor mu?'' diye. Sonra (bu sözlerle) uzaklaşırlardı. Allah onların kalplerini çevirmiştir, çünkü onlar anlamayan bir kavimdir.'),
(9, 128, 11, 207, 'لَقَدْ جَآءَكُمْ رَسُولٌۭ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌۭ رَّحِيمٌۭ', 'laqad jāʾakum rasūlun min anfusikum ʿazīzun ʿalayhi mā ʿanittum ḥarīṣun ʿalaykum bi-l-muʾminīna raʾūfun raḥīmun', 'Andolsun, size kendi içinizden öyle bir peygamber gelmiştir ki, sizin sıkıntıya uğramanız ona ağır gelir. O, size çok düşkün, mü''minlere karşı da çok şefkatli ve merhametlidir.'),
(9, 129, 11, 207, 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'fa-in tawallaw fa-qul ḥasbiya -llāhu lā ilāha illā huwa ʿalayhi tawakkaltu wa-huwa rabbu -l-ʿarshi -l-ʿaẓīm', 'Eğer yüz çevirirlerse de ki: "Allah bana yeter. O''ndan başka ilah yoktur. Ben ancak O''na tevekkül ettim. O, büyük Arş''ın Rabbidir."'),
(10, 1, 11, 208, 'الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', 'Elif, Lâm, Râ. Tilke âyâtü''l-kitâbi''l-hakîm.', 'Elif, Lâm, Râ. Bunlar hikmet dolu Kitab''ın âyetleridir.'),
(10, 2, 11, 208, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ قَالَ ٱلْكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٌ مُّبِينٌ', 'e-kâne li''n-nâsi ''aceben en evhaynâ ilâ raculin minhum en enżiri ''n-nâse ve beşşiri ''l-leẕîne âmenû enne lehum ḳademe ṣidḳin ''inde rabbihim ḳâle ''l-kâfirûne inne hâẕâ le-sâḥirun mubîn', 'İnsanlara, kendilerinden bir adama, "İnsanları uyar ve iman edenlere, Rableri katında kendileri için bir doğruluk makamı olduğunu müjdele" diye vahyetmemiz garip mi geldi? Kâfirler dediler ki: "Şüphesiz bu, apaçık bir sihirbazdır."'),
(10, 3, 11, 208, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُدَبِّرُ ٱلْأَمْرَ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ أَفَلَا تَذَكَّرُونَ', 'ʾinna rabbakumullāhu lladhī khalaqa s-samāwāti wa-l-ʾarḍa fī sittati ʾayyāmin thumma stawa ʿalā l-ʿarshi yudabbiru l-ʾamra mā min shafīʿin ʾillā min baʿdi ʾidhnihi dhālikumu llāhu rabbukum fa-ʿbudūhu ʾafalā tadhakkarūna', 'Şüphesiz Rabbiniz, gökleri ve yeri altı günde yaratan, sonra da Arş''a istiva eden Allah''tır. O, her işi evirip çevirendir. O''nun izni olmadıkça, hiç kimse şefaatçi olamaz. İşte bu Allah, sizin Rabbinizdir. O halde O''na kulluk edin. Hâlâ öğüt alıp düşünmüyor musunuz?'),
(10, 4, 11, 208, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا وَعْدَ ٱللَّهِ حَقًّا إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ بِٱلْقِسْطِ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'ilayhi marjiʿukum jamīʿan waʿda llāhi ḥaqqan ʾinnahu yabdāʾu l-khalqa thumma yuʿīduhu liyajziya lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti bil-qisṭi wa lladhīna kafarū lahum sharābun min ḥamīmin wa ʿadhābun ʾalīmun bimā kānū yakfurūna', 'Hep birlikte dönüşünüz O''nadır. Allah''ın vaadi haktır. Şüphesiz O, yaratmaya başlar, sonra iman edip salih amel işleyenleri adaletle mükafatlandırmak için onu (yaratmayı) iade eder. İnkâr edenlere ise, inkâr etmekte oldukları şeyden dolayı kaynar su ve elem dolu bir azap vardır.'),
(10, 5, 11, 208, 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ يُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍ يَعْلَمُونَ', 'huwa alladhī jaʿala ash-shamsa ḍiyāʾan wa-l-qamara nūran wa-qaddarahu manāzil li-taʿlamū ʿadada as-sinīna wa-l-ḥisāb mā khalaqa Allāhu dhālika illā bi-l-ḥaqq yufaṣṣilu al-ʾāyāti li-qawmin yaʿlamūn', 'O, güneşi bir ışık kaynağı, ayı da (parlak) bir nur kılan ve onun (ayın) burçlarını (veya evrelerini) takdir edendir ki, böylece yılların sayısını ve (zaman) hesabını öğrenmiş olasınız. Allah, bunları ancak hak (ve hikmet) ile yaratmıştır. O, bilen bir topluluk için âyetleri (delilleri) ayrı ayrı açıklar.'),
(10, 6, 11, 208, 'إِنَّ فِى ٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَءَايَٰتٍ لِّقَوْمٍ يَتَّقُونَ', 'ʾinna fī ʾikhtilāfi l-layli wa-n-nahāri wa-mā khalaqa ʾllāhu fī s-samāwāti wa-l-ʾarḍi laʾāyātin li-qawmin yattaqūna', 'Şüphesiz gece ile gündüzün art arda gelişinde ve Allah''ın göklerde ve yerde yarattığı şeylerde, O''na karşı gelmekten sakınan bir topluluk için (nice) deliller vardır.'),
(10, 7, 11, 209, 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ', 'ʾinna lladhīna lā yarjūna liqāʾanā wa raḍū bil-ḥayāti d-dunyā wa ṭmaʾannū bihā wa lladhīna hum ʿan ʾāyātinā ghāfilūn', 'Şüphesiz, bize kavuşmayı ummayanlar, dünya hayatından hoşnut olup ona aldananlar ve bizim ayetlerimizden gafil olanlar...'),
(10, 8, 11, 209, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', 'ʾūlāʾika maʾwāhumu ʾn-nāru bimā kānū yaksibūn', 'İşte onların barınakları, kazandıklarından ötürü ateştir.'),
(10, 9, 11, 209, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ فِى جَنَّٰتِ ٱلنَّعِيمِ', 'ʾinna lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti yahdīhim rabbuhum bi-ʾīmānihim tajrī min taḥtihimu l-ʾanhāru fī jannāti n-naʿīmi', 'Şüphesiz iman edip salih amel işleyenleri, imanları sebebiyle Rableri doğru yola iletir. Altlarından ırmaklar akan, Naîm cennetlerinde (onlar) {:?}'),
(10, 10, 11, 209, 'دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'daʿwāhum fīhā subḥānaka Allāhumma wa taḥiyyatuhum fīhā salāmun wa ʾākhiru daʿwāhum ʾani l-ḥamdu li-llāhi rabbi l-ʿālamīna', 'Onların oradaki duaları: "Sen yücesin, Allah''ım!" ve oradaki dilekleri: "Selam!"dır. Ve onların dualarının sonu: "Hamd, âlemlerin Rabbi Allah''a mahsustur." demeleridir.'),
(10, 11, 11, 209, 'وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'wa-law yuʿajjilu llāhu li-n-nāsi sh-shar-ra istiʿjālahum bi-l-khayri la-quḍiya ilayhim ajaluhum fa-naḏaru l-laḏīna lā yarjūna liqāʾanā fī ṭughyānihim yaʿmahūna', 'Eğer Allah, insanların hayra karşı gösterdikleri aceleciliği, kendileri hakkında (kötülüğe doğru) hemen yerine getirseydi, elbette onların ecelleri çoktan bitmiş olurdu. Ama bize kavuşmayı ummayanları, kendi azgınlıkları içinde bocalayıp dururlarken bırakırız.'),
(10, 12, 11, 209, 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'wa-ʾidhā massā l-ʾinsāna ḍ-ḍurru daʿānā li-jambihī ʾaw qāʿidan ʾaw qāʾiman fa-lammā kašafnā ʿanhu ḍurrahū marra ka-ʾan lam yadʿunā ʾilā ḍurrin massahū ka-dhālika zuyyina lil-musrifīna mā kānū yaʿmalūn', 'İnsana bir zarar dokunduğu zaman, yan yatmış, oturmuş veya ayakta durmuşken bize dua eder. Biz ondan zararı kaldırınca, sanki kendisine dokunan o zarar için bize hiç yalvarmamış gibi yoluna devam eder. İşte böylece, haddi aşanlara yapmakta oldukları şeyler süslü gösterildi.'),
(10, 13, 11, 209, 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 'Ve lekad ehleknâ el-kurûne min kablikum lemmâ zalemû ve câet-hum rusuluhum bi-l-beyyinâti ve mâ kânû li-yu''minû kezâlike neczî el-kavme el-mucrimîne', 'Andolsun ki sizden önceki nice nesilleri helak ettik. Çünkü onlar zulmetmişlerdi. Peygamberleri onlara apaçık delillerle gelmişti de onlar iman etmemişlerdi. İşte biz suçlu toplumu böyle cezalandırırız.'),
(10, 14, 11, 209, 'ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', 'thumma jaʿalnākum khalāʾifa fī l-arḍi min baʿdihim linanẓura kayfa taʿmalūn', 'Sonra, onların ardından sizi yeryüzüne halef kıldık ki, nasıl davranacağınızı görelim.'),
(10, 15, 11, 210, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'wa ʾiḏā tutlā ʿalayhim ʾāyātunā bayyinātin qāla l-laḏīna lā yarjūna liqāʾanā ʾti bi-qurʾānin ġayri hāḏā ʾaw baddilhu qul mā yakūnu lī ʾan ʾubaddilahu min tilqāʾi nafsī ʾin ʾattabiʿu ʾillā mā yūḥā ʾilayya ʾinnī ʾaḫāfu ʾin ʿaṣaytu rabbī ʿaḏāba yawmin ʿaẓīmin', 'Onlara âyetlerimiz açık olarak okunduğunda, bize kavuşmayı ummayanlar: "Bunun yerine başka bir Kur''an getir veya onu değiştir!" derler. De ki: "Onu kendi isteğimle değiştirmem benim için olmaz. Ben ancak bana vahyolunana uyarım. Eğer Rabbime isyan edersem, o büyük günün azabından korkarım."'),
(10, 16, 11, 210, 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ أَفَلَا تَعْقِلُونَ', 'qul law shāʾa allāhu mā talawtuhu ʿalaykum walā adrākum bihī faqad labithtu fīkum ʿumuran min qablihī ʾaflā taʿqilūn', 'De ki: Eğer Allah dileseydi, ben onu size okumazdım ve Allah da size onu (Kur''an''ı) bildirmezdi. Ben ondan önce sizin aranızda bir ömür (boyunca) yaşadım. Hâlâ akıl eremez misiniz?'),
(10, 17, 11, 210, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', 'fe-men aẓlamu mimmeni-ftarā ʿalā llāhi kaḏiban aw kaḏḏaba bi-ʾāyātihī ʾinnepū lā yufliḥu l-muǧrimūn', 'Allah''a karşı yalan uyduran veya O''nun âyetlerini yalanlayan kimseden daha zalim kim olabilir? Şüphesiz zalimler kurtuluşa eremezler.'),
(10, 18, 11, 210, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'wa yaʿbudūna min dūni llāhi mā lā yaḍurruhum wa lā yanfaʿuhum wa yaqūlūna hāʾulāʾi shufʿāʾunā ʿinda llāh qul ʾatunabbiʾūna llāha bimā lā yaʿlamu fī s-samāwāti wa lā fī l-ʾarḍi subḥānahū wa taʿālā ʿammā yushrikūn', 'Allah''ı bırakıp kendilerine zarar da fayda da vermeyecek şeylere tapıyorlar ve "Bunlar Allah katında bizim şefaatçilerimizdir" diyorlar. De ki: "Siz, göklerde ve yerde Allah''ın bilmediği bir şeyi mi O''na (yeni) haber veriyorsunuz? O, onların ortak koştukları şeylerden münezzehtir ve yücedir."'),
(10, 19, 11, 210, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', 'wa mā kāna n-nāsu illā ummatan wāḥidatan fa-khtalafū wa lawlā kalimatun sabaqat min rabbika la-quḍiya baynahum fīmā fīhi yakhtalifūn', 'İnsanlar (başlangıçta) tek bir ümmet idi. Allah, müjdeleyicileri ve uyarıcıları göndermek suretiyle ayrılığa düştüler. Eğer Rabbinden (verilmiş) bir söz olmasaydı, aralarında hüküm çoktan verilmiş olurdu.'),
(10, 20, 11, 210, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'wa yaqūlūna lawlā unzila ʿalayhi ʾāyatun mir rabbihī fa-qul ʾinnamā l-ghaybu li-llāhi fa-ntẓirū ʾinnī maʿakum mina l-muntaẓirīn', 'Ve derler ki: "Ona Rabbinden bir mucize indirilmeli değil miydi?" De ki: "Gayb Allah''ındır. Bekleyin! Ben de sizinle birlikte bekleyenlerdenim."'),
(10, 21, 11, 211, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', 'wa ʾidhā ʾadhaqnā n-nāsa raḥmatan min baʿdi ḍarrāʾa massathum ʾidhā lahum makrun fī ʾāyātinā quli l-lāhu ʾasraʿu makran ʾinna rusulanā yaktubūna mā tamkurūna', 'Onlara dokunan bir sıkıntıdan sonra kendilerine bir rahmet tattırdığımız zaman, hemen bizim âyetlerimiz hakkında hileye başvururlar. De ki: Allah, tuzak kurma hususunda daha süratli (veya daha hazırlıklıdır). Şüphesiz elçilerimiz sizin hilelerinizi yazmaktadır.'),
(10, 22, 11, 211, 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'huwa lladhī yusayyirukum fī l-barri wa-l-baḥri ḥattā idhā kuntum fī l-fulki wa-jarayna bihim bi-rīḥin ṭayyibatin wa-fariḥū bihā jāʾathā rīḥun ʿāṣifun wa-jāʾahumu l-mawju min kulli makānin wa-ẓannū annahum uḥīṭa bihim daʿawu llāha mukhliṣīna lahu d-dīna la-in anjaytanā min hādhihi la-nakūna nna mina sh-shākirīna', 'O, sizi karada ve denizde (dolaştıran/yürütendir). Hatta siz gemilerde bulunduğunuzda ve onlar hoş bir rüzgarla kendilerini götürdüğünde ve onunla sevindiklerinde, ona (gemilere) fırtınalı bir rüzgar geldi ve onlara her taraftan dalgalar geldi ve kendilerini kuşatıldığını sandılar. O zaman Allah''a, dini O''na halis kılarak dua ettiler: "Andolsun, eğer bizi bundan kurtarırsan, mutlaka şükredenlerden oluruz."'),
(10, 23, 11, 211, 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'felemmā anjāhum iḏā hum yabġūna fīl-arḍi biġayril-ḥaqqi yā ayyuhan-nāsu innamā bagyukum ʿalā anfusikum matāʿal-ḥayātid-dunyā ṯumma ilaynā marjiʿukum fanunabbiʾukum bimā kuntum taʿmalūn', 'Ancak kendilerini kurtarınca, hemen yeryüzünde haksız yere azgınlık yapmaya başladılar. Ey insanlar! Sizin azgınlığınız ancak kendi aleyhinizedir. (Bu dünya) hayatının geçici bir zevkidir. Sonra dönüşünüz yalnız bize olacaktır. O zaman size bütün yaptıklarınızı haber vereceğiz.'),
(10, 24, 11, 211, 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍ يَتَفَكَّرُونَ', 'ʾinnemā maṯelu l-ḥayāti d-dunyā kamāʾin ʾanzelnāhu mina s-samāʾi fa-ḵtalaṭa bihi nabātu l-ʾarḍi mimmā yaʾkulu n-nāsu wa-l-ʾanʿāmu ḥattā ʾiḏā ʾaḵaḏati l-ʾarḍu zuḵrufahā wa-zzayyanat wa-ẓanna ʾahluḥā ʾannahum qādirūna ʿalayhā ʾatāhā ʾamrunā laylan ʾaw nahāran fa-ǧaʿalnāhā ḥaṣīdan kaʾan lam taḡna bi-l-ʾamsi kaḏālika nufaṣṣilu l-ʾāyāti li-qawmin yatafakkarūna', 'Dünya hayatının durumu, ancak gökten indirdiğimiz bir su gibidir; onunla insanların ve hayvanların yediği yeryüzü bitkileri birbirine karışmış, (gelişip) güzelleşmiş ve sahipleri de ona (tamamen) hakim olduklarını sanmışken, geceleyin veya gündüzün emrimiz gelmiş ve onu sanki dün hiç yokmuş gibi kökünden biçilmiş bir hale getirmişizdir. İşte biz, düşünen bir kavim için ayetleri böyle açıklıyoruz.'),
(10, 25, 11, 211, 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa-llāhu yadʿū ʾilā dāri s-salāmi wa-yahdī man yashāʾu ʾilā ṣirāṭin mustaqīmin', 'Allah, (insanları) selam yurduna davet eder ve dilediğini de dosdoğru yola iletir.'),
(10, 26, 11, 212, 'لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', 'lilladhīna ʾaḥsanū al-ḥusnā wa-ziyādah wa-lā yarhaqu wujūhahum qatarun wa-lā dhillah ʾulāʾika ʾaṣḥābu al-jannah hum fīhā khālidūn', 'İyilik yapanlara daha güzeli (cennet) ve fazlası vardır. Onların yüzlerini ne bir karartı ne de bir zillet kaplar. İşte onlar cennet ehlidir; onlar orada ebedî kalırlar.'),
(10, 27, 11, 212, 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'wa-lladhīna kasabū s-sayyiʾāti jazāʾu sayyiʾatin bi-mithlihā wa-tarhaquhum dhillatun mā lahum mina llāhi min ʿāṣimin ka-ʾannamā ʾughshiyat wujūhuhum qiṭaʿan mina l-layli muẓliman ʾulāʾika ʾaṣḥābu n-nāri hum fīhā khālidūna', 'Kötülükleri kazananlara gelince, kötülüğün karşılığı onun misli kadardır. Onları bir zillet kaplar. Onları Allah''tan (kurtaracak) hiçbir koruyucu yoktur. Yüzleri sanki karanlık gecenin parçalarıyla örtülmüş gibidir. İşte bunlar ateş ehlidirler; orada ebedî kalırlar.'),
(10, 28, 11, 212, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', 'wa yawma naḥshuruhum jamīʿan thumma naqūlu lilladhīna ashrakū makānakum antum wa shurakāʾukum fa zayyalnā baynahum wa qāla shurakāʾuhum mā kuntum iyyānā taʿbudūn', 'Ve o gün onları hep birlikte mahşerde toplayacağız. Sonra şirk koşanlara: “Siz ve ortaklarınız (bulunduğunuz) yerinizde kalın!” diyeceğiz. Derken onların ortaklarını ayıracağız ve ortakları diyecekler ki: “Siz bize tapmıyordunuz.”'),
(10, 29, 11, 212, 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ', 'fa-kafā bi-llāhi shahīdan baynanā wa-baynakum in kunnā ʿan ʿibādatikum la-ghāfilīn', 'Sizinle bizim aramızda şahit olarak Allah yeter. Şüphesiz biz sizin kulluğunuzdan habersiz idik.'),
(10, 30, 11, 212, 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'hunālika tabluw kulu nufsin mā aslafat wa ruddū ilā Allāhi mawlāhumu l-ḥaqqi wa ḍalla ʿanhum mā kānū yaftarūna', 'İşte orada her nefis, geçmişte yaptıklarını imtihan olur; sonra hak mevlâları olan Allah''a döndürülürler ve uydurmakta oldukları şeyler onlardan kaybolup gider.'),
(10, 31, 11, 212, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ فَسَيَقُولُونَ ٱللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ', 'qul man yarzuqukum mina s-samāʾi wa-l-arḍi amman yamliku s-samʿa wa-l-abṣāra wa man yukhriju l-ḥayya mina l-mayyiti wa yukhriju l-mayyita mina l-ḥayyi wa man yudabbiru l-amra fa-sayaqūlūna llāhu fa-qul a-falā tattaqūna', 'De ki: Gökten ve yerden size kim rızık veriyor? Ya da kulaklarınıza ve gözlerinize kim sahip bulunuyor? Kim de ölüden diri çıkarır, diriden de ölü çıkarır? Ve kimdir işleri evirip çeviren? ''Allah'' diyeceklerdir. De ki: Öyleyse O''ndan hakkıyla korkmaz mısınız?'),
(10, 32, 11, 212, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ فَأَنَّىٰ تُصْرَفُونَ', 'fa ḏālikumu ʾllāhu rabbukumu l-ḥaqqu famāḏā baʿda l-ḥaqqi ʾillā ḍ-ḍalālu fa ʾannā tuṣrafūna', 'İşte bu sizin Rabbiniz olan Allah''tır. Hak''tan sonra sapıklıktan başka ne var? O halde nasıl oluyor da (haktan) çevriliyorsunuz?'),
(10, 33, 11, 212, 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', 'kadhālika ḥaqqat kalimatu rabbika ʿalā alladhīna fasaqū annahum lā yuʾminūn', 'İşte bu sebeple, yoldan çıkanların üzerine Rabbinin şu sözü hak olmuştur: Onlar iman etmezler.'),
(10, 34, 11, 213, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ فَأَنَّىٰ تُؤْفَكُونَ', 'qul hal min shurakāʾikum man yabdaʾu l-khalqa thumma yuʿīduhu quli l-lāhu yabdaʾu l-khalqa thumma yuʿīduhu faʾannā tuʾfakūn', 'De ki: ''Ortaklarınızdan, yaratmaya başlayıp sonra onu iade edecek olan var mı?'' De ki: ''Allah yaratmaya başlar, sonra onu iade eder. O halde nasıl (haktan) çevriliyorsunuz?'''),
(10, 35, 11, 213, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'qul hal min shurakāʾikum man yahdī ilā l-ḥaqqi quli l-lāhu yahdī lil-ḥaqqi afa man yahdī ilā l-ḥaqqi aḥaqqu an yuttabaʿa am man lā yahdī illā an yuhdā famā lakum kayfa taḥkumūna', 'De ki: "Ortaklarınızdan hakka yol gösteren var mı?" De ki: "Allah hakka yol gösterir. Hakka yol gösteren mi, yoksa (doğru yola) iletilmedikçe kendisi yol bulamayan mı uyulmaya daha layıktır? Ne oluyor size, nasıl hükmediyorsunuz?"'),
(10, 36, 11, 213, 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'wa mā yattabiʿu ʾaktharuhum ʾillā ẓannā ʾinna ẓ-ẓanna lā yughnī mina l-ḥaqqi šayʾā ʾinna -llāha ʿalīmun bi-mā yafʿalūn', 'Onların çoğu zandan başkasına uymaz. Şüphesiz zan, hak (gerçek) karşısında hiçbir fayda sağlamaz. Şüphesiz Allah, onların yapmakta olduklarını hakkıyla bilendir.'),
(10, 37, 11, 213, 'وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', 'wa mā kāna hāḏā l-qurʾānu ʾan yuftarā min dūni ʾllāhi wa lākin taṣdīqa ʾllḏī bayna yadayhi wa tafṣīla l-kitābi lā rayba fīhi min rabbi l-ʿālamīn', 'Bu Kur''an, Allah''tan başkası tarafından uydurulmuş değildir. Ancak o, kendinden öncekileri doğrulayan ve o (kitap) hakkında hiçbir şüphe olmayan, âlemlerin Rabbi tarafından indirilmiş bir (kitaptır).'),
(10, 38, 11, 213, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'am yaqūlūna-ftrāhu qul faʾtū bisūratin mithlihī w-adʿū mani-staṭaʿtum min dūni-llāhi in kuntum ṣādiqīna', 'Yoksa "Onu kendisi uydurdu" mu diyorlar? De ki: "Eğer doğru sözlüler iseniz, Allah''tan başka güvendiklerinizin hepsini çağırıp, Allah katından bana bir sure getirin."'),
(10, 39, 11, 213, 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'bal kaḏḏabū bimā lam yuḥīṭū biʿilmihī walam mā yaʾtihim taʾwīluhū kaḏālika kaḏḏaba llaḏīna min qablihim fanẓur kayfa kāna ʿāqibatu ẓẓālimīn', 'Hayır, onlar ilmini kavrayamadıkları ve kendilerine daha gelmemiş olan (sonuçları) yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Artık zalimlerin sonunun nasıl olduğuna bir bak!'),
(10, 40, 11, 213, 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', 'wa-minhum man yuʾminu bihi wa-minhum man lā yuʾminu bihi wa-rabbuka ʾaʿlamu bil-mufsidīn', 'Onlardan ona iman edenler de var, inanmayanlar da. Ve Rabbin, bozguncuları daha iyi bilendir.'),
(10, 41, 11, 213, 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', 'wa-ʾin kaḏḏabūka fa-quʾl lī ʿamalī wa-lakum ʿamalukum ʾantum barīʾūna mimmā ʾaʿmalu wa-ʾanā barīʾun mimmā taʿmalūna', 'Eğer seni yalanlarlarsa, de ki: "Benim yaptığım bana, sizin yaptığınız size aittir. Siz benim yaptığımdan uzaksınız, ben de sizin yaptıklarınızdan uzağım."'),
(10, 42, 11, 213, 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', 'wa-minhum man yastamiʿūna ilayka afa-anta tusmiʿu ṣ-ṣumma wa-law kānū lā yaʿqilūn', 'Onlardan sana kulak verenler de vardır. Sağırlara, -aklı ermese bile- sen mi işittireceksin?'),
(10, 43, 11, 214, 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', 'wa-minhum man yanẓuru ilayka afa-anta tahdī l-ʿumya wa-law kānū lā yubṣirūn', 'Onlardan sana bakanlar da vardır. Körleri, basiretleri olmasa bile sen mi doğru yola ileteceksin?'),
(10, 44, 11, 214, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', 'ʾinna llāha lā yaẓlimu n-nāsa šayʾan wa-lākinna n-nāsa ʾanfusahum yaẓlimūn', 'Şüphesiz Allah, insanlara hiçbir şeyle zulmetmez. Fakat insanlar kendi nefislerine zulmederler.'),
(10, 45, 11, 214, 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', 'wa-yawma yaḥshuruhum ka-an lam yalbathū illā sāʿatan mina an-nahāri yataʿārafoūna baynahum qad khasira alladhīna kadhthabū bi-liqāʾi Allāhi wa-mā kānū muhtadīna', 'Ve o gün Allah onları bir araya toplayacak da gündüzün sadece bir saat kadar kalmış gibi olacaklar. Birbirleriyle tanışırlar. Allah''a kavuşmayı yalanlayanlar ziyana uğramışlardır ve doğru yolu bulanlar olmamışlardır.'),
(10, 46, 11, 214, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', 'wa-ʾimmā nuriyannaka baʿḍa lladhī naʿiduhum ʾaw natawaffayannaka fa-ʾilaynā marjiʿuhum thumma llāhu shahīdun ʿalā mā yafʿalūn', 'Onlara vaadettiğimiz şeylerin bir kısmını sana gösterirsek veya (göstermeden) seni vefat ettirirsek (bile), onların dönüşleri Bizedir. Sonra Allah onların yapmakta olduklarına şahittir.'),
(10, 47, 11, 214, 'وَلِكُلِّ أُمَّةٍ رَّسُولٌ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'wa likulli ummatin rasūlun fa-idhā jāʾa rasūluhum quḍiya baynahum bil-qisṭi wa hum lā yuẓlamūn', 'Her ümmetin bir peygamberi vardır. Peygamberleri geldiğinde, aralarında adaletle hükmedilir ve onlara haksızlık yapılmaz.'),
(10, 48, 11, 214, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hādhā al-waʿdu in kuntum ṣādiqīn', 'Ve derler ki: "Eğer doğru sözlüler iseniz, bu vaad (getirdiğiniz azap) ne zaman?"'),
(10, 49, 11, 214, 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'qul lā amliku linafsī ḍarraw walā nafʿan illā mā shāʾa ʾllāhu likulli ummatin ʾajalun ʾidhā jāʾa ʾajaluhum falā yastʾakhirūna sāʿatan walā yastaqdimūna', 'De ki: "Allah''ın dilediği dışında kendi kendime bir fayda veya zarar verecek gücüm yoktur. Her ümmetin belirli bir eceli vardır. Ecelleri geldiğinde, ne bir an geri kalabilirler ne de bir an öne geçebilirler."'),
(10, 50, 11, 214, 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', 'qul ʾaraʾaytum ʾin ʾatākum ʿaḏābuhu bayātan ʾaw nahāran māḏā yastaʿjilu minhu l-mujrimūn', 'De ki: «Söyleyin bana, eğer O''nun azabı size geceleyin veya gündüzün gelirse, günahkârların ondan acele isteyecekleri ne vardır?»'),
(10, 51, 11, 214, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'ʾaṯumma ʾiḏā mā waqaʿa ʾāmantum bihi ʾāʾilāna waqad kuntum bihi tastaʿjilūn', 'Sonra, başınıza geldiği zaman mı ona iman edeceksiniz? Şimdi mi? Oysa daha önce siz onu acele istiyordunuz.'),
(10, 52, 11, 214, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', 'thumma qīla lilladhīna ẓalamū dhūqū ʿadhāba l-khuldi hal tujzawna illā bimā kuntum taksibūna', 'Sonra zulmedenlere: "Tadın bakalım şu sonsuz azabı! Yaptıklarınızdan başkasıyla mı cezalandırılacaksınız?" denilecektir.'),
(10, 53, 11, 214, 'وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ وَمَآ أَنتُم بِمُعْجِزِينَ', 'wa yastanbiʾūnaka aḥaqqun huwa qul ʾī warabbī ʾinnahu laḥaqqun wamā ʾantum bimuʿjizīn', 'Sana, "O (azap) gerçek mi?" diye soruyorlar. De ki: "Evet, Rabbime yemin ederim ki, o gerçektir ve siz (bundan) kurtulamazsınız."'),
(10, 54, 11, 215, 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 'wa-law anna likulli nafsin ẓalamat mā fī l-arḍi la-ftadat bihi wa-asarrū n-nadāmata lammā raʾawu l-ʿadhāb wa-quḍiya baynahum bil-qisṭ wa-hum lā yuẓlamūn', 'Zulmeden her nefse, yeryüzündeki her şey verilse de, onu mutlaka kurtulmalık olarak feda ederdi. Azabı gördüklerinde ise pişmanlıklarını gizlerler. Hem aralarında adaletle hükmedilir ve onlara haksızlık yapılmaz.'),
(10, 55, 11, 215, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'ʾalā ʾinna lillāhi mā fī s-samāwāti wa-l-ʾarḍi ʾalā ʾinna waʿda llāhi ḥaqqun wa-lākinna ʾaktharahum lā yaʿlamūn', 'Göklerde ve yerde ne varsa hepsi şüphesiz Allah''ındır. Haberiniz olsun ki Allah''ın vaadi haktır, fakat çokları bilmezler.'),
(10, 56, 11, 215, 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', 'huwa yuḥyī wa yumītu wa ʾilayhi turjaʿūna', 'O, diriltir ve öldürür. Ve yalnız O''na döndürüleceksiniz.'),
(10, 57, 11, 215, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', 'yā ayyuhā n-nāsu qad jāʾatkum mawʿiẓatun min rabbikum wa shifāʾun limā fī ṣ-ṣudūri wa hudan wa raḥmatun lil-muʾminīna', 'Ey insanlar! İşte size Rabbinizden bir öğüt, kalplerde olana bir şifa, müminler için bir hidayet ve bir rahmet gelmiştir.'),
(10, 58, 11, 215, 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'qul bifadli llāhi wabi raḥmatihī fabhi dhālika faly afr aḥū huwa khayrun mimmā yajmaʿūn', 'De ki: Allah''ın fazlı ve rahmetiyle sevinin! Bu, onların topladıklarından daha hayırlıdır.'),
(10, 59, 11, 215, 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', 'qul ʾaraʾaytum mā ʾanzala ʾallāhu lakum min rizqin fa-jaʿaltum minhu ḥarāman wa-ḥalālan qul ʾāllāhu ʾadhina lakum ʾam ʿalā ʾallāhi taftarūna', 'De ki: "Allah''ın sizin için indirdiği rızık hakkında bana haber verin. Siz ondan kimini haram, kimini de helal yaptınız." De ki: "Bunu size Allah mı izin verdi, yoksa Allah''a yalan mı uyduruyorsunuz?"'),
(10, 60, 11, 215, 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 'wa mā ẓannu lladhīna yaftarūna ʿalā llāhi l-kadhiba yawma l-qiyāmati ʾinna llāha ladhū faḍlin ʿalā n-nāsi wa lākinna ʾaktharahum lā yashkurūna', 'Allah''a yalan uyduranların kıyamet günündeki zannı/sanısı nedir? Şüphesiz Allah, insanlara karşı lütuf sahibidir, ancak onların çoğu şükretmez.'),
(10, 61, 11, 215, 'وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'wa mā takūnu fī shaʾnin wa mā tatlū minhu min qurʾānin wa lā taʿmalūna min ʿamalinn illā kunnā ʿalaykum shuhūdan ʾidh tufīḍūna fīhi wa mā yaʿzubu ʿan rabbika min mithqāli dharratin fī l-ʾarḍi wa lā fī s-samāʾi wa lā ʾaṣğara min dhālika wa lā ʾakbara illā fī kitābin mubīnin', 'Hiçbir durumda bulunmazsın, ondan (Kur''an''dan) hiçbir şey okumazsın ve siz de herhangi bir iş yapmazsınız ki, siz o işe dalmışken biz sizin üzerinizde şahit olmayalım. Yerde ve gökte zerre kadar bir şey ne gizli kalır ne de ondan daha küçük veya daha büyük bir şey, apaçık bir kitaptâ (Levh-i Mahfûz''da) yazılı olmaktan başka.'),
(10, 62, 11, 216, 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ʾalā ʾinna ʾawliyāʾa ḷḷāhi lā ḫawfun ʿalayhim walā hum yaḥzanūn', 'Dikkat edin! Allah''ın dostlarına korku yoktur ve onlar mahzun da olmayacaklardır.'),
(10, 63, 11, 216, 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'alladhīna ʾāmanū wa kānū yattaqūna', 'Onlar, iman edip takva sahibi olanlardır.'),
(10, 64, 11, 216, 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'Lehumu el-buşrâ fî el-hayâti ed-dunyâ ve fî el-âhirati lâ tebdîle likelimâti Allâhi zâlike huve el-fevzu el-azîmu', 'Dünya hayatında da ahirette de onlara müjde vardır. Allah''ın sözlerinde asla bir değişme yoktur. İşte bu, en büyük kurtuluştur.'),
(10, 65, 11, 216, 'وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa lā yaḥzunnuka qawluhum inna l-ʿizzata li-llāhi jamīʿan huwa s-samīʿu l-ʿalīmu', 'Onların sözleri seni üzmesin. Çünkü bütün izzet (güç ve şeref) Allah''ındır. O, hakkıyla işitendir, bilendir.'),
(10, 66, 11, 216, 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'ʾalā ʾinna li-llāhi man fī s-samāwāti wa-man fī l-ʾarḍi wa-mā yattabiʿu l-ladhīna yadʿūna min dūni llāhi shurakāʾa ʾin yattabiʿūna ʾillā ẓ-ẓanna wa-ʾin hum ʾillā yakhruṣūna', 'Göklerde ve yerde kim varsa hepsi Allah''ındır. Allah''ı bırakıp da ortak koştuklarının peşine takılanlar, ancak zanna uyar ve yalandan başka bir şeye sarılmazlar.'),
(10, 67, 11, 216, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', 'huwa lladhī jaʿala lakumu l-layla litaskunū fīhi wa-n-nahāra mubṣirā inna fī dhālika laʾāyātin liqawmin yasmaʿūn', 'O, geceyi size dinlenmeniz için, gündüzü de aydınlık olarak yaratan O''dur. Şüphesiz bunda, (sözümü) dinleyen bir kavim için nice ibretler vardır.'),
(10, 68, 11, 216, 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ هُوَ ٱلْغَنِىُّ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 'qālū-ttakhaḏa llāhu waladan subḥānahū huwa l-ġaniyyu lahū mā fī s-samāwāti wa mā fī l-arḍi in ʿindakum min sulṭānin bihāḏā ataqūlūna ʿalā llāhi mā lā taʿlamūna', 'Dediler ki: "Allah çocuk edindi." Haşa! O, müstağnidir. Göklerde ne var, yerde ne varsa hepsi O''nundur. Yanınızda bu hususta hiçbir delil yoktur. Allah hakkında bilmediğiniz şeyleri mi söylüyorsunuz?'),
(10, 69, 11, 216, 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 'Qul ʾinna alladhīna yaftarūna ʿalā allāhi l-kadhiba lā yufliḥūna', 'De ki: "Allah''a yalan uyduranlar asla kurtuluşa ermezler."'),
(10, 70, 11, 216, 'مَتَٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', 'matāʿun fī d-dunyā thumma ilaynā marjiʿuhum thumma nudhīquhumu l-ʿadhāba sh-shadīda bimā kānū yakfurūna', 'Dünya hayatında bir menfaat (var), sonra dönüşleri bizedir. Sonra da küfretmekte oldukları şeyden dolayı azabı şiddetli olarak tattıracağız.'),
(10, 71, 11, 217, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', 'wa-tlu ʿalayhim nabaʾa nūḥin iḏ qāla li-qawmihī yā-qawmi in kāna kabura ʿalaykum maqāmī wa-taḏkīrī bi-ʾāyāti llāhi fa-ʿalā llāhi tawakkaltu fa-ʾajmiʿū ʾamrakum wa-shurakāʾakum ṯumma lā yakun ʾamrukum ʿalaykum ġummatan ṯumma ʾqḍū ʾilayya wa-lā tunẓirūn', 'Onlara Nuh''un haberini oku. Hani o kavmine şöyle demişti: "Ey kavmim! Eğer benim sizin aranızda bulunmam ve Allah''ın ayetlerini hatırlatmam size ağır geldiyse, bilin ki ben bütün varlığımla Allah''a dayanmışımdır. Artık siz de ortaklarınızla birlikte toplanıp yapacağınız işi karara bağlayın, sonra da bana hiçbir endişe vermeyin."'),
(10, 72, 11, 217, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 'fa-in tawallaytum fa-mā sa''altukum min ajrin in ajriya illā ʿalā Allāhi wa-umirtu an akūna mina l-muslimīna', 'Eğer yüz çevirirseniz, (bilin ki) ben sizden bir ücret istemedim. Benim ücretim ancak Allah''a aittir. Ve ben, Müslümanlardan olmakla emrolundum.'),
(10, 73, 11, 217, 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 'fa-kaḏḏabūhu fa-najjaynāhu wa-man maʿahu fī l-fulki wa-jaʿalnāhum ḵalāʾifa wa-ʾaġraqnā l-laḏīna kaḏḏabū bi-ʾāyātinā fa-nẓur kayfa kāna ʿāqibatu l-munḏarīna', 'Böylece onu yalanladılar. Biz de onu ve onunla birlikte gemide olanları kurtardık ve onları (nesilleri) halifeler kıldık. Ayetlerimizi yalanlayanları ise boğduk. Uyarılanların sonunun nasıl olduğuna bir bak!'),
(10, 74, 11, 217, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', 'Tchumma baʿathnā min baʿdihi rusulan ilā qawmihim Fajāʾūhum bil-bayyināti Famā kānū liyūʾminū bimā kadhthabū bihi min qablu Kadhālika naṭbaʿu ʿalā qulūbi l-muʿtadhīn', 'Sonra onun ardından, kavimlerine peygamberler gönderdik. Onlara açık deliller getirdiler. Ama onlar, daha önce yalanladıklarını artık iman edecek değillerdi. İşte biz, haddi aşanların kalplerini böyle mühürleriz.'),
(10, 75, 11, 217, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', 'thumma baʿathnā min baʿdihim Mūsā wa Hārūna ilā Firʿawna wa malaʾihi bi-āyātinā fastakbarū wa kānū qawman mujrimīn', 'Sonra onların ardından Mûsâ''yı ve Hârûn''u, âyetlerimizle Firavun''a ve onun ileri gelenlerine gönderdik. Ama onlar kibirlendiler ve suçlu bir kavim oldular.'),
(10, 76, 11, 217, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ', 'fe-lemmā jāʾahumu l-ḥaqqu min ʿindinā qālū inna hādhā la-siḥrun mubīn', 'Nihayet katımızdan kendilerine hak gelince, "Bu, apaçık bir sihirdir" dediler.'),
(10, 77, 11, 217, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ', 'qāla mūsā ataqūlūna lil-ḥaqqi lammā jāʾakum ʾasiḥrun hāḏā walā yufliḥu s-sāḥirūn', 'Musa dedi ki: "Size hak geldiğinde onu sihir mi diyeceksiniz? Sihirbazların asla kurtuluşa ermeyeceği mi?'),
(10, 78, 11, 217, 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', 'qālū ʾa-jiʾtanā li-talfitanā ʿammā wajadnā ʿalayhi ʾābāʾanā wa-takūna lakumā l-kibriyāʾu fī l-ʾarḍi wa-mā naḥnu lakumā bi-muʾminīna', 'Dediler ki: "Sen bize atalarımızı üzerinde bulduğumuz şeyden (yoldan) çevirmek ve bu yerde sana ikinizin büyüklüğü (hâkimiyeti) geçsin diye mi geldin? Halbuki biz ikinize de inanacaklar değiliz."'),
(10, 79, 11, 218, 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍ', 'waqāla firʿawnu ʾītūnī bikulli sāḥirin ʿalīm', 'Firavun dedi ki: "Bana her şeyi bilen (bütün) sihirbazları getirin!"'),
(10, 80, 11, 218, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 'fe-lemmā jāʾa s-saḥaratu qāla lehum Mūsā alqū mā antum mulqūna', 'Sihirbazlar gelince, Musa onlara dedi ki: "Ortaya koyacağınız şeyi ortaya koyun!"'),
(10, 81, 11, 218, 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', 'fe-lemmā elqaw qāla Mūsā mā jiʾtum bihi s-siḥru ʾinna-llāha sayubṭiluhū ʾinna-llāha lā yuṣliḥu ʿamala l-mufsidīn', 'Onlar atınca Musa dedi ki: "Sizin getirdiğiniz şey büyüdür. Şüphesiz Allah onu iptal edecektir. Çünkü Allah, fesatçıların işini düzeltmez."'),
(10, 82, 11, 218, 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'wa yuḥiqqu llāhu l-ḥaqqa bikalimātihi wa law kariha l-mujrimūn', 'Allah, kelimeleriyle hakkı gerçekleştirecek ve (bunu) suçlular hoşlanmasa da (yapacaktır).'),
(10, 83, 11, 218, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', 'famā ʾāmana limūsā ʾillā ḏurriyyatun min qawmihī ʿalā ḫawfin min firʿawna wa-malʾihim ʾan yaftinahum wa-ʾinna firʿawna la-ʿālin fī l-ʾarḍi wa-ʾinnahu la-mina l-musrifīn', 'Bunun üzerine Musa''ya, kavminden sadece bir zürriyet (bir grup insan) iman etti; onlar da Firavun''dan ve onun ileri gelenlerinden, kendilerini fitneye düşürmelerinden korkuyorlardı. Ve şüphesiz Firavun, yeryüzünde (kendini) yüceltenlerden idi ve şüphesiz o, israf edenlerden idi.'),
(10, 84, 11, 218, 'وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', 'waqāla mūsā yā qawmi in kuntum ʾāmantum bi-llāhi fa-ʿalayhi tawakkalū ʾin kuntum muslimīn', 'Musa dedi ki: "Ey kavmim! Eğer siz Allah''a iman etmişseniz, O''na güvenip dayanın; eğer müslümanlar idiyseniz."'),
(10, 85, 11, 218, 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'Feqālū ʿAlā Allāhi tawakkalnā Rabbanā Lā tajʿalna fitnatan lil-qawmi aẓ-ẓālimīn', 'Bunun üzerine şöyle dediler: "Biz Allah’a güvendik. Rabbimiz! Bizi zalimler topluluğu için bir fitne (deneme, işkence) konusu kılma!"'),
(10, 86, 11, 218, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 'wa najjinā biraḥmatika mina l-qawmi l-kāfirīn', 'Ve bizi rahmetinle kâfirler topluluğundan kurtar.'),
(10, 87, 11, 218, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'wa-awḥaynā ilā Mūsā wa-akhīhi an tabawwaʾā li-qawmikumā bi-Miṣra buyūtan wa-jʿalū buyūtakum qiblatan wa-aqīmū aṣ-ṣalāta wa-bashshiri l-muʾminīn', 'Musa''ya ve kardeşine şöyle vahyettik: "Mısır''da kavminiz için evler hazırlayın ve evlerinizi namazgâh edinin, namazı dosdoğru kılın ve müminleri müjdele."'),
(10, 88, 11, 218, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'waqāla mūsā rabbanā ʾinnaka ʾātayta firʿawna wamalaʾahu zīnatann waʾamwālan fī l-ḥayāti d-dunyā rabbanā liyudillū ʿan sabīlik rabbanā ṭmis ʿalā ʾamwālihim wa-shdud ʿalā qulūbihim falā yuʾminū ḥattā yarawu l-ʿadhāba l-ʾalīm', 'Musa dedi ki: "Rabbimiz! Sen Firavun''a ve onun ileri gelenlerine dünya hayatında bir ziynet ve mallar verdin. Rabbimiz! (Onlar,) senin yolundan saptırsınlar diye mi (böyle yaptın)? Kendi mallarını yok et ve kalplerini sıkıştır ki, o acı azabı görecekleri zamana kadar iman etmesinler!"'),
(10, 89, 11, 219, 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', 'qāla qad ʾujībat daʿwatukumā fastaqīmā walā tattabiʿānni sabīla lladhīna lā yaʿlamūn', 'Allah şöyle buyurdu: "Andolsun, ikinizin de duası kabul olunmuştur. Artık siz (yolunuzda) dosdoğru gidin ve sakın bilgisizlerin yoluna uymayın."'),
(10, 90, 11, 219, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', 'wa-jāwaznā bi-banī ʾisrāʾīla l-baḥra fa-ʾatbaʿahum firʿawnu wa-junūduhu baghyan wa-ʿadwan ḥattā ʾiḏā ʾadrakahu l-gharaqu qāla ʾāmantu ʾannahu lā ʾilāha ʾillā l-laḏī ʾāmanat bihi banū ʾisrāʾīla wa-ʾanā mina l-muslimīna', 'İsrailoğullarını denizden geçirdik. Firavun ve orduları, düşmanlık ve saldırganlık amacıyla onları takip etti. Nihayet boğulma kendisini yakalayınca dedi ki: "İnanıyorum ki, İsrailoğullarının inandığı;
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(11, 28, 12, 224, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ', 'qāla yā qawmi ʾaraʾaytum ʾin kuntu ʿalā bayyinatin mir rabbī wa ʾātānī raḥmatan min ʿindihī fa ʿummiyat ʿalaykum ʾanulzimukumūhā wa ʾantum lahā kārithūn', 'O, şöyle dedi: "Ey kavmim! Söyleyin bana, eğer ben Rabbimden (gelen) açık bir delil (ayet) üzere isem ve O bana kendi katından bir rahmet (peygamberlik) vermişse, siz onu göremeyip üzerinize mi kapatıldı? Siz istemediğiniz halde sizi ona zorlayacak mıyız?"'),
(11, 29, 12, 225, 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', 'wa yā qawmi lā asʾalukum ʿalayhi mālā in ajriya illā ʿalā Allāhi wa mā anā biṭāridi alladhīna āmanū innahum mulāqū rabbihim wa lākinnī ʾarākum qawman tajhalūna', 'Ey kavmim! Ben bu tebliğime karşılık sizden bir mal istemiyorum. Benim mükâfatım ancak Allah''a aittir. Ben, iman edenleri (yanımdan) kovacak değilim. Çünkü onlar, Rablerine kavuşacaklardır. Fakat ben sizi, (gerçeği) bilmeyen bir kavim olarak görüyorum.'),
(11, 30, 12, 225, 'وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ', 'wa yā qawmi man yanṣurunī min Allāhi in ṭaradtuhum afalā tadhakkarūn', 'Ey kavmim! Eğer onları kovarsam, Allah''tan bana kim yardım eder? Hiç düşünmüyor musunuz?'),
(11, 31, 12, 225, 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'wa lā aqūlu lakum ʿindī khazāʾinu ʾllāhi wa lā ʾaʿlamu ʾl-ghayba wa lā aqūlu ʾinnī malakun wa lā aqūlu lilladhīna tazdarī ʾaʿyunukum lan yuʾtiyahumu ʾllāhu khayran ʾllāhu ʾaʿlamu bimā fī ʾansufihim ʾinnī ʾidhan laman ẓẓālimīna', 'Ben size ''Allah''ın hazineleri yanımdadır'' demem. Ben gaybı da bilmem. ''Ben bir meleğim'' de demem. Sizin hor gördüğünüz, gözlerinizin küçümsediği kimseler hakkında, ''Allah onlara hiçbir hayır vermez'' de demem. Onların nefislerinde olanı Allah daha iyi bilir. Eğer böyle söylersem, o takdirde gerçekten zalimlerden olurum.'),
(11, 32, 12, 225, 'قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'qālū yā nūḥu qad jādaltanā faʾaktharta jidālanā faʾtinā bimā taʿidunā ʾin kunta mina ṣ-ṣādiqīn', 'Dediler ki: "Ey Nuh! Bizimle tartıştın, hem de çok tartıştın. Eğer doğru söyleyenlerden isen, haydi bizi tehdit ettiğin azabı getir!"'),
(11, 33, 12, 225, 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', 'qāla innamā yaʾtīkum bihi ʾllāhu ʾin šāʾa wamā ʾantum bimuʿjizīn', 'Allah dilediği takdirde size onu getirir ve siz O''nu aciz bırakacak değilsiniz.'),
(11, 34, 12, 225, 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', 'wa-lā yanfaʿukum nuṣḥī ʾin ʾarattu ʾan ʾanṣaḥa lakum ʾin kāna ʾllāhu yurīdu ʾan yughwiyakum huwa rabbukum wa-ʾilayhi turjaʿūn', 'Eğer sizi azdırmak istemişse, benim size öğüt vermem size fayda vermez. O sizin Rabbinizdir ve O''na döndürüleceksiniz.'),
(11, 35, 12, 225, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ', 'am yaqūlūna-ftrāhu qul ini-ftraytuhu faʿalayya ijrāmī wa-anā barīʾun mimmā tujrimūna', 'Yoksa "Onu uydurdu" mu diyorlar? De ki: "Eğer onu uydurmuşsam, vebalim bana aittir. Ben ise sizin işlediğiniz suçlardan uzağım."'),
(11, 36, 12, 225, 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', 'wa ʾūḥiya ʾilā nūḥin ʾannahu lan yuʾmina min qawmika ʾillā man qad ʾāmana falā tabtaʾis bimā kānū yafʿalūn', 'Ve Nuh''a şöyle vahyolundu: "Kavminden inanmış olanlardan başka kimse inanmayacaktır. Artık onların yapmakta olduklarından dolayı üzülme."'),
(11, 37, 12, 225, 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', 'wa-ṣnaʿi l-fulka bi-aʿyuninā wa-waḥyinā wa-lā tukhāṭibnī fī lladhīna ẓalamū ʾinnahum mughraqūna', 'Gözümüzün önünde ve vahyimizle gemiyi yap. Zulmedenler hakkında bana hitap etme; çünkü onlar boğulacaklardır.'),
(11, 38, 12, 226, 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', 'wa yaṣnaʿu l-fulka wa kullamā marra ʿalayhi malaʾun min qawmihi sākhirū minhu qāla in taskharū minnā fa-innā naskharu minkum kamā taskharūn', 'Ve gemi yapıyordu. Kavminden bir topluluk her geçtiğinde onunla alay ediyorlardı. Dedi ki: "Eğer bizimle alay ederseniz, alay ettiğiniz gibi biz de sizinle alay edeceğiz."'),
(11, 39, 12, 226, 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', 'fasawfa taʿlamūna man yaʾtīhi ʿaḏābun yukhzīhi wa yaḥillu ʿalayhi ʿaḏābun muqīmun', 'O zaman kimin başına alçaltıcı bir azabın geleceğini ve kimin üzerine de sürekli bir azabın konulacağını bileceksiniz.'),
(11, 40, 12, 226, 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ', 'ḥattā ʾiḏā jāʾa ʾamrunā wa fāra ʾt-tannūru qulnā ʾiḥmil fīhā min kullin zawjayni ʾiṯnayn wa ʾahlaka ʾillā man sabaqa ʿalayhi ʾl-qawlu wa man ʾāmana wa mā ʾāmana maʿahū ʾillā qalīlun', 'Nihayet emrimiz gelip tandır kaynamaya başlayınca, dedik ki: "Her canlıdan (çiftlerden) birer çifti ve (tufanda) helak olacakların dışında kalan aileni ve iman edenleri gemiye bindir." Zaten onunla birlikte ancak az kimse iman etmişti.'),
(11, 41, 12, 226, 'وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ', 'waqāla rkaboū fīhā bismillāhi majrāhā wa mursāhā ʾinna rabbī laḡafūrun raḥīm', 'Ve "Binin ona! Onun denize/yüzeye inişi ve duruşu Allah''ın adıyla(dır)! Şüphesiz Rabbim çok bağışlayandır, çok merhamet edendir!" dedi.'),
(11, 42, 12, 226, 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ', 'wa hiya tajrī bihim fī mawjin kal-jibāli wa nādā Nūḥun ibnahu wa kāna fī maʿzilin yā bunayya-rkab maʿanā wa lā takun maʿa l-kāfirīn', 'Gemi, onları dağlar gibi dalgalar içinde götürüyordu. Nuh, bir kenarda duran oğluna, "Ey oğlum! Bize katıl, kâfirlerle birlikte olma!" diye seslendi.'),
(11, 43, 12, 226, 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', 'qāla saʾāwī ʾilā jabalin yaʿṣimunī mina l-māʾi qāla lā ʿāṣima l-yawma min ʾamri llāhi ʾillā man raḥima waḥāla baynahumā l-mawju fakāna mina l-muġraqīn', 'Dedi ki: "Beni sudan koruyacak bir dağa sığınırım." Dedi ki: "Bugün Allah''ın emrine karşı koruyucu yoktur, O''nun merhamet ettikleri müstesna." Ve ikisinin arasına dalga girdi de boğulanlardan oldu.'),
(11, 44, 12, 226, 'وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'wa qīla yā arḍu-bʿalī māʾaki wa yā samāʾu qliʿī wa ġīḍa l-māʾu wa quḍiya l-amru wa-stawet ʿalā l-jūdīyyi wa qīla buʿdan li-l-qawmi ẓ-ẓālimīn', 'Ve denildi ki: "Ey yer, suyunu yut! Ey gök, tut suyunu!" Ve su çekildi, iş de olup bitti. Gemi Cudi''ye oturdu ve zalimler güruhuna: "Uzak olun!" denildi.'),
(11, 45, 12, 226, 'وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ', 'wa-nādā nūḥun rabbahū faqāla rabbi ʾinna ʾibnī min ʾahlī wa-ʾinna waʿdaka l-ḥaqqu wa-ʾanta ʾaḥkamu l-ḥākimīn', 'Nuh, Rabbine seslendi ve şöyle dedi: "Rabbim! Şüphesiz oğlum ailemdendir ve şüphesiz Senin vaadin haktır. Sen hükmedenlerin en iyisisin."'),
(11, 46, 12, 227, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ', 'qāla yā nūḥu innahu laysa min ahli-k innahu ʿamalun ġayru ṣāliḥin falā tasʾalni mā laysa laka bihi ʿilmun innī aʿiẓuka an takūna mina l-jāhilīn', 'Allah şöyle buyurdu: "Ey Nuh! O, senin ailenden değildir. Çünkü o, salih olmayan bir amel işlemiştir. O halde hakkında bilgi sahibi olmadığın bir şeyi benden isteme. Cahillerden olmaman için sana öğüt veriyorum."'),
(11, 47, 12, 227, 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ', 'qāla rabbi innī ʾaʿūżu bike ʾan ʾasʾalake mā laysa lī bihi ʿilmun wa ʾillā taghfir lī wa tarḥamnī ʾakun mina l-khāsirīn', 'Rabbim! Senden, hakkında bilgim olmayan bir şeyi istemekten sana sığınırım. Eğer sen beni bağışlamaz ve bana merhamet etmezsen, hüsrana uğrayanlardan olurum.'),
(11, 48, 12, 227, 'قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ', 'qīla yā nūḥu hbiṭ bisalāmin minnā wa barakātin ʿalayka wa ʿalā umamin mimman maʿak wa umamun sanumattiʿuhum thumma yamas suhum minnā ʿadhābun alīmun', 'Ey Nuh! Sana bizden bir selamet ve bereketlerle (gemiden) in, seninle beraber olanlara da (insanlardan ve hayvanlardan) bereketler olsun. (Yine) onlardan bazı ümmetler vardır ki, onları biraz geçindireceğiz, sonra onlara bizden elem dolu bir azap dokunacaktır.'),
(11, 49, 12, 227, 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا فَٱصْبِرْ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ', 'tilka min anbāʾi l-ghaybi nūḥīhā ʾilayka mā kunta taʿlamuhā ʾanta wa lā qawmuka min qabli hādhā fa-ṣbir ʾinna l-ʿāqibata lil-muttaqīn', 'Bunlar, sana vahyettiğimiz gayb (gizli) haberlerindendir. Bunları sen de, kavmin de bundan önce bilmiyordunuz. Sabret. Şüphesiz ki akıbet, takva sahiplerinindir.'),
(11, 50, 12, 227, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', 'wa ʾilā ʿādin ʾaḫāhum hūdā qāla yā qawmi ʿbudū ʾllāha mā lakum min ʾilāhin ġayruhu ʾin ʾantum ʾillā muftirūn', 'Ve Âd (kavmine) kardeşleri Hûd''u (gönderdik). Dedi ki: "Ey kavmim! Allah''a kulluk edin. Sizin O''ndan başka ilâhınız yoktur. Siz ancak yalan uyduranlarsınız."'),
(11, 51, 12, 227, 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ أَفَلَا تَعْقِلُونَ', 'yā qawmi lā asʾalukum ʿalayhi ʾajran ʾin ʾajriya ʾillā ʿalā alladhī faṭaranī ʾafalā taʿqilūn', 'Ey kavmim! Ben bunu (tebliğ görevimi yerine getirme karşılığında) sizden bir ücret istemiyorum. Benim ecrim/mükâfatım, beni yaratana aittir. Hâlâ akıl erdiremiyor musunuz?'),
(11, 52, 12, 227, 'وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', 'wa yā qawmi-ġfirū rabbakum ṯumma tūbū ilayhi yursili as-samāʾa ʿalaykum midrāran wa yazidkum quwwatan ilā quwwatikum wa lā tatawallaw mujrimīn', 'Ey kavmim! Rabbinizden mağfiret isteyin, sonra O''na tövbe edin ki, göğü üzerinize bol bol bıraksın ve gücünüze güç katsın. Ve sakın suçlular olarak yüz çevirmeyin.'),
(11, 53, 12, 227, 'قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'qālū yā hūdu mā jiʾtanā bibayyinatin wamā naḥnu bitārikī ʾālihatinā ʿan qawlika wamā naḥnu laka bimūʾminīn', 'Dediler ki: "Ey Hûd! Bize açık bir delil (mucize) getirmedin. Senin sözünle biz ilahlarımızı asla terk etmeyiz ve biz sana inanacak da değiliz."'),
(11, 54, 12, 228, 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'in naqūlu illā ʿtarakā baʿḍu ʾālihatinā bisūʾin qāla ʾinnī ʾush''hidu ʾllāha wa-sh''hadū ʾannī barīʾun mimmā tushrikūna', 'Bizim, ''Seni ilahlarımızdan biri fenalığa uğratmış olmalı'' demekten başka bir şey söylediğimiz yok. (Hud) dedi ki: ''Şüphesiz ben Allah''ı şahit tutuyorum ve sizin O''na ortak koşmakta olduğunuz şeylerden uzak olduğumu da siz de şahit olun.'''),
(11, 55, 12, 228, 'مِن دُونِهِۦ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ', 'min dūnihī fakīdūnī jamīʿan thumma lā tunẓirūn', 'O''ndan başka (taptıklarınızla) bana tuzak kurun, sonra da bana göz bile açtırmayın!'),
(11, 56, 12, 228, 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'ʾinnī tawakkaltu ʿalā Llāhi rabbī wa rabbikum mā min dābbatin ʾillā huwa ʾākhidhum bi-nāṣiyatihā ʾinna rabbī ʿalā ṣirāṭim mustaqīm', 'Şüphesiz ben, benim de Rabbim sizin de Rabbiniz olan Allah''a tevekkül ettim. Hiçbir canlı yoktur ki, Allah onun alnından tutmuş olmasın. Şüphesiz benim Rabbim dosdoğru bir yol üzerindedir.'),
(11, 57, 12, 228, 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', 'fa-in tawallaw faqad ablaghtukum mā ursiltu bihi ilaykum wa-yastakhliqu rabbī qawman ghayrakum wa-lā taḍurrunahu shayʾan inna rabbī ʿalā kulli shayʾin ḥafīẓun', 'Eğer yüz çevirirseniz, (bilin ki) ben size gönderildiğim şeyi tebliğ ettim. Rabbim, yerinize başka bir kavim getirir. Siz O''na hiçbir zarar veremezsiniz. Şüphesiz Rabbim her şeyi gözetendir.'),
(11, 58, 12, 228, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍ', 'wa lammā jāʾa ʾamrunā najjaynā Hūdan wa-llaḏīna ʾāmanū maʿahū bi-raḥmatin minnā wa najjaynāhum min ʿaḏābin ġalīẓin', 'Emrimiz (azabımız) geldiği zaman, tarafımızdan bir rahmetle Hûd''u ve onunla birlikte iman edenleri kurtardık ve onları ağır bir azaptan kurtardık.'),
(11, 59, 12, 228, 'وَتِلْكَ عَادٌ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ', 'wa tilka ʿādun jaḥadū bi-ʾāyāti rabbihim wa ʿaṣaw rusulahu wa-ttabaʿū ʾamra kulli jabbārin ʿanīd', 'İşte Âd (kavmi)! Rablerinin âyetlerini inkâr ettiler, peygamberlerine isyan ettiler ve her inatçı zorbanın emrine uydular.'),
(11, 60, 12, 228, 'وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ', 'wa-utbiʿū fī hādhihi ʾd-dunyā laʿnatan wa-yawma ʾl-qiyāmati ʾalā ʾinna ʿādan kafarū rabbahum ʾalā buʿdan li-ʿādin qawmi hūdi', 'Ve bu dünyada ve kıyamet gününde bir la''nete uğratıldılar. Haberiniz olsun ki, Âd (kavmi) Rablerini inkâr ettiler. Haberiniz olsun ki, Hûd''un kavmi Âd, Allah''ın rahmetinden uzaklaştırıldı!'),
(11, 61, 12, 228, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ', 'wa ʾilā thamōda ʾakhāhum sāliḥan qāla yā qawmi ʿbudō ʾllāha mā lakum min ʾilāhin ġayruhū huwa ʾanshaʾakum mina l-ʾarḍi wastaʿmarakum fīhā fastaġfirōhu thumma tōbō ʾilayhi ʾinna Rabbī qarībun mujībun', 'Ve Semud''a da kardeşleri Salih''i (gönderdik). Dedi ki: ''Ey kavmim! Allah''a kulluk edin. Sizin O''ndan başka ilahınız yoktur. O sizi yerden (topraktan) yarattı ve sizi orada (dünyada) yaşattı. Artık O''ndan bağışlanma dileyin, sonra O''na tövbe edin. Şüphesiz Rabbim çok yakındır, (duaları) kabul edendir.'''),
(11, 62, 12, 228, 'قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَآ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ', 'qālū yā ṣāliḥu qad kunta fīnā marjuwwan qabla hāḏā atanhānā an naʿbuda mā yaʿbudu ʾābāʾunā wa ʾinnanā la fī shakkim mimmā tadʿūnā ʾilayhi murībin', 'Dediler ki: "Ey Salih! Bundan önce sen aramızda umut edilen biriydin. Şimdi babalarımızın taptığı şeylere tapmaktan bizi men mi ediyorsun? Doğrusu biz, senin bizi çağırdığın şeyden kuşku ve endişe içindeyiz."'),
(11, 63, 12, 229, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ', 'qāla yā qawmi araʾaytum in kuntu ʿalā bayyinatin min rabbī wa ātānī minhu raḥmah faman yanṣurunī mina llāhi in ʿaṣaytuhu famā tazīdūnanī ghayra takhsīr', 'O, şöyle dedi: "Ey kavmim! Eğer ben Rabbimden (gelen) açık bir delil üzerinde isem ve O bana kendi katından bir rahmet (peygamberlik) vermişse, o takdirde (söyleyin) bana, eğer O''na isyan edersem, Allah''tan beni kim kurtarabilir? (Bana) ancak azabı artırırsınız."'),
(11, 64, 12, 229, 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ', 'wa yā qawmi hādhihi nāqatu Allāhi lakum āyatan fa dhurūhā taʾkul fī arḍi Allāhi wa lā tamassūhā bisūʾin fa yaʾkhudhakum ʿadhābun qarībun', 'Ey kavmim! İşte size bir mucize olarak Allah''ın dişi devesi! Bırakın onu, Allah''ın yeryüzünde yesin; ona kötülükle dokunmayın ki sizi yakın bir azap yakalamasın.'),
(11, 65, 12, 229, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', 'faʿaqarūhā faqāla tamattaʿū fī dārikum thalāthata ayyāmin dhālika waʿdun ghayru makdhūbin', 'Böylece onu kestiler. (Salih:) "Evlerinizde üç gün daha yaşayın! Bu, yalanlanmayacak bir vaattir" dedi.'),
(11, 66, 12, 229, 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'fe-lemmā jāʾa ʾamrunā neccaynā ṣāliḥan wa-lleẕīne ʾāmenū maʿahu bi-raḥmetin minnā wa-min ḫizyi yewmiʾiẕin ʾinne rabbeke huwe l-qawiyyu l-ʿazīzu', 'Vaktâ ki emrimiz gelip çattı, tarafımızdan bir rahmetle Salih''i ve onunla birlikte iman edenleri, o günün rezilliğinden kurtardık. Şüphesiz Rabbin, mutlak kuvvet sahibi, mutlak izzet sahibidir.'),
(11, 67, 12, 229, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'wa-akhadha alladhīna ẓalamū ṣ-ṣayḥatu fa-aṣbaḥū fī diyārihim jāthimīna', 'Zalimlere o korkunç-çığlık gelip çattı da yurtlarında diz üstü çökeşmiş olarak sabahladılar.'),
(11, 68, 12, 229, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ', 'kaʾanna lam yaghnaw fīhā ʾalā ʾinna thʿamūd kafarū rabbahum ʾalā buʿdan li-thʿamūd', 'Sanki orada hiç yaşamamışlar gibi! Haberiniz olsun ki, Semûd (kavmi) Rablerini inkâr ettiler. Haberiniz olsun ki, Semûd (kavmi) Allah’ın rahmetinden uzaklaştırıldı!'),
(11, 69, 12, 229, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ', 'Ve lekad câet rusulunâ İbrâhîme bilbuşrâ Kâlû selâmen Kâle selâmun Fe mâ lebise en câe biiclin hanîzin', 'Andolsun ki elçilerimiz İbrahim''e müjde ile geldiler. "Selam!" dediler. O da "Selam!" dedi. Çok geçmeden kızartılmış bir buzağı getirdi.'),
(11, 70, 12, 229, 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ', 'fe-lemmā raʾā ʾaydiyahum lā taṣilu ʾilayhi nakirahum wa-ʾawjasa minhum ḵīfatan qālū lā taḵhaf ʾinnā ʾursilnā ʾilā qawmi lūṭin', 'Bunun üzerine, onların (misafirlerin) ellerinin ona (yemeğe) uzanmadığını görünce, onları (yabancı oldukları için) yadırgadı ve onlardan içine bir korku düştü. Dediler ki: "Korkma! Biz Lût kavmine gönderildik."'),
(11, 71, 12, 229, 'وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ', 'wa-mraʾatuhu qāʾimatun fa-ḍaḥikat fa-bashsharnāhā bi-isḥāqa wa-min warāʾi isḥāqa yaʿqūba', 'Ve hanımı ayakta idi. Birden gülüp ona İshak''ı ve İshak''ın ardından da Yakub''u müjdeledik.'),
(11, 72, 12, 230, 'قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَٰذَا بَعْلِى شَيْخًا إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌ', 'qālat yā waylatā aʾalidu wa-anā ʿajūzun wa-hādhā baʿlī shaykhan ʾinna hādhā la-shayʾun ʿajībun', 'Kadın dedi ki: Vay halime! Ben bir yaşlı kadınım, şu kocam da bir ihtiyar. Bu gerçekten şaşılacak bir şey!'),
(11, 73, 12, 230, 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ', 'qālū ʾataʿjabīna min ʾamri ʾllāhi raḥmatu ʾllāhi wa-barakātuhu ʿalaykum ʾahla l-bayti ʾinnahu ḥamīdun majīdun', 'Dediler ki: "Allah''ın emrine mi şaşıyorsun? Ey ev halkı! Allah''ın rahmeti ve bereketleri sizin üzerinizedir. Şüphesiz O, Hamîd''dir (övülmüştür), Mecîd''dir (şanı yücedir)."'),
(11, 74, 12, 230, 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ', 'fe-lemmā ḏahaba ʿan ibrāhīme r-rawʿu we-jāʾathu l-bušrā yudžilunā fī qawmi lūṭin', 'İbrahim''den o korku gidince ve ona müjde gelince, Lût kavmi hakkında bizimle tartışmaya başladı.'),
(11, 75, 12, 230, 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ', 'inna ibrāhīma laḥalīmun ʾawwāhun munīb', 'Şüphesiz İbrahim, gerçekten çok yumuşak huylu, içi içine sığmayan bir dua edici, (ve) kendisine yönelmiş idi.'),
(11, 76, 12, 230, 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', 'Yā Ibrāhīm Aʿriḍ ʿan hādhā Innahū qad jāʾa amru rabbika Wa innahum ātīhim ʿadhābun ghayru mardūd', 'Ey İbrahim! Bundan vazgeç. Şüphesiz Rabbinin emri geldi ve onlara asla geri çevrilmeyecek bir azap gelecektir.'),
(11, 77, 12, 230, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ', 'wa lammā jāʾat rusulunā lūṭan sīʾa bihim wa ḍāqa bihim ḏarʿan wa qāla hāḏā yawmun ʿaṣībun', 'Elçilerimiz Lut''a geldiğinde, onlar yüzünden içi sıkıldı, onları ağırlamaktan eli kolu bağlandı ve "Bu, çok çetin bir gün!" dedi.'),
(11, 78, 12, 230, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ', 'wa jāʾa-hū qawmu-hū yuhraʿūna ʾilayhi wa min qablu kānū yaʿmalūna s-sayyiʾāti qāla yā qawmi hāʾulāʾi banātī hunna ʾaṭharu lakum fa-ttaqū llāha wa lā tukhzūnī fī ḍayfī ʾalaysa minkum rajulun rašīd', 'Kavmi ona koşarak geldi. Daha önce de kötülükler yapmakta idiler. (Lut) dedi ki: "Ey kavmim! İşte şunlar benim kızlarımdır, sizin için daha temizdir. Artık Allah''tan korkun da beni misafirlerimin (şerefini) rencide etmeyin. İçinizde hiç akıllı bir adam yok mudur?"'),
(11, 79, 12, 230, 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', 'qālū laqad ʿalimta mā lanā fī banātika min ḥaqqin wa innaka lataʿlamu mā nurīdu', 'Dediler ki: "Andolsun, senin bildiğini biliyoruz. Bizim senin kızların üzerinde hiçbir hakkımız yoktur. Sen ise, bizim ne istediğimizi çok iyi biliyorsun."'),
(11, 80, 12, 230, 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ', 'qāla law anna lī bikum quwwatan aw ʾāwī ʾilā ruknin shadīdin', 'Ey kavmim! dedi, eğer size karşı bir gücüm olsaydı veya sığınabileceğim sağlam bir yere sığınabilseydim!'),
(11, 81, 12, 230, 'قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ', 'qālū yā Lūṭu innā rusulu rabbika lan yaṣilū ilaika faʾsri biʾahlikabiqiṭʿin min al-layli walā yaltafitu minkum ʾaḥadun ʾillā ʾimraʾataka ʾinnahu mụṣībuhā mā ʾaṣābahum ʾinna mawʿidahumu ṣ-ṣubḥu ʾalaysa ṣ-ṣubḥu biqarībin', 'Dediler ki: "Ey Lût! Biz, senin Rabb''inin elçileriyiz. Onlar sana asla ulaşamazlar. Derhal geceleyin ailenle birlikte yola çık ve sizden hiç kimse dönüp arkasına bakmasın! Ancak hanımın müstesna. Çünkü ona da onlara isabet eden azap isabet edecektir. Şüphesiz onların azap vadesi sabaha karşıdır. Zaten sabah yakın değil mi?"'),
(11, 82, 12, 231, 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ', 'fe-lemmā jāʾa ʾamrunā caʿalnā ʿāliyehā sāfelehā we-ʾamṭarnā ʿaleyhā ḥicāratan min sijjīlin manḍūd', 'Emrimiz (azabımız) gelince, oranın altını üstüne getirdik ve üzerlerine ateşte pişmiş balçıktan yapılmış, istif edilmiş taşlar yağdırdık.'),
(11, 83, 12, 231, 'مُّسَوَّمَةً عِندَ رَبِّكَ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍ', 'musawwamatan ʿinda rabbika wa mā hiya mina ẓ-ẓālimīna bibʿīd', 'Onlar, Rabbinin katında işaretlenmişti. Onlar zalimlerden uzak değildir.'),
(11, 84, 12, 231, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ', 'wa ilā madyana ʾaḫāhum šuʿaybā qāla yā qawmi ʿbudū llāha mā lakum min ʾilāhin ġayruhu wa lā tanquṣū l-mikyāla wa l-mīzāna ʾinnī ʾarākum biḫayrin wa ʾinnī ʾaḫāfu ʿalaykum ʿaḏāba yawmin muḥīṭin', 'Medyen''e de kardeşleri Şuayb''ı (gönderdik). O, şöyle dedi: "Ey kavmim! Allah''a kulluk edin. Sizin O''ndan başka ilahınız yoktur. Hem o ölçü ve tartıyı eksik yapmayın. Doğrusu ben sizi hayır (bolluk) içinde görüyorum. Ve ben sizin için kuşatıcı bir günün azabından korkuyorum."'),
(11, 85, 12, 231, 'وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'wa yā qawmi ʾawfū l-mikyāla wa l-mīzāna bi l-qisṭi wa lā tabkhasū n-nāsa ʾashyāʾahum wa lā taʿthaw fī l-ʾarḍi mufsidīn', 'Ey kavmim! Ölçüyü ve tartıyı adaletle tam yapın. İnsanların eşyalarını eksik vermeyin ve yeryüzünde bozgunculuk yaparak fesat çıkarmayın.'),
(11, 86, 12, 231, 'بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', 'baqiyyetu llāhi khayrun lakum in kuntum muʾminīn wamā ʾanā ʿalaykum biḥafīẓin', 'Allah''ın bakiyesi (artığı) sizin için daha hayırlıdır, eğer inanıyorsanız. Ben sizin üzerinizde bir koruyucu değilim.'),
(11, 87, 12, 231, 'قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', 'qālū yā šuʿaybu aṣalātuka taʾmuruka an natruka mā yaʿbudu ʾābāʾunā aw an nafʿala fī ʾamwālinā mā našāʾu ʾinnaka laʾanta l-ḥalīmu r-rašīdu', 'Dediler ki: "Ey Şuayb! Yoksa senin namazın mı sana, atalarımızın taptığı şeyleri bırakmamızı yahut mallarımızda dilediğimizi yapmaktan vazgeçmemizi mi emrediyor? Oysa sen, gerçekten sen, yumuşak huylu, aklı başında birisin!"'),
(11, 88, 12, 231, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 'qāla yā qawmi ʾaraʾaytum ʾin kuntu ʿalā bayyinatin min rabbī wa-razaqanī minhu rizqan ḥasanan wa mā ʾurīdu ʾan ʾukhālifakum ʾilā mā ʾanhākum ʿanhu ʾin ʾurīdu ʾillā l-ʾiṣlāḥa mā staṭaʿtu wa mā tawfīqī ʾillā bi-llāhi ʿalayhi tawakkaltu wa ʾilayhi ʾunību', 'Şuayb dedi ki: "Ey kavmim! Eğer ben Rabbimden (gelen) açık bir delil üzerinde isem ve O bana tarafından güzel bir rızık vermişse (ne dersiniz)? Ben size yasak ettiğim şeylere aykırı olarak size bir şey yapmak istemiyorum. Ben sadece gücüm yettiği kadar ıslah etmek istiyorum. Başarmam ancak Allah''ın yardımıyladır. O''na dayandım ve O''na döneceğim."'),
(11, 89, 12, 232, 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ', 'wa yā qawmi lā yajrimannakum shiqāqī an yuṣībakum mithlu mā aṣāba qawma nūḥin aw qawma hūdin aw qawma ṣāliḥin wa mā qawmu lūṭin minkum bibʿīd', 'Ey kavmim! Bana olan düşmanlığınız, Nuh kavminin veya Hud kavminin ya da Salih kavminin başına gelenin bir benzerinin sizin de başınıza gelmesine sebep olmasın. Lut kavmi de sizden uzak değildir.'),
(11, 90, 12, 232, 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ', 'wastaghfirū rabbakum thumma tūbū ilayhi inna rabbī raḥīmun wadūd', 'Rabbinizden bağışlanma dileyin, sonra O''na tövbe edin. Şüphesiz Rabbim çok bağışlayandır, çok merhametlidir.'),
(11, 91, 12, 232, 'قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ', 'qālū yā šuʿaybu mā nafquhu kathīran mimmā taqūlu wa-innā lanarāka fīnā ḍaʿīfan wa-lawlā rahṭuka la-rajamnāka wa-mā anta ʿalaynā biʿazīzin', 'Dediler ki: "Ey Şuayb! Söylediklerinin çoğunu anlamıyoruz. Doğrusu biz seni aramızda zayıf görüyoruz. Eğer kabilen olmasaydı, seni mutlaka taşlardık. Hem sen bize karşı güçlü değilsin."'),
(11, 92, 12, 232, 'قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ', 'qāla yā qawmi ʾarhaṭī ʾaʿazzu ʿalaykum mina llāhi wa-ttakhaḏtumūhu warāʾakum ẓihriyyā ʾinna rabbī bimā taʿmalūna muḥīṭun', 'Ey kavmim! Sizin için Allah''a karşı (söyleyecek sözüm) benim hısım akrabam daha mı üstün ki, onu (Allah''ı) arkanıza atıp unuttunuz? Şüphesiz Rabbim, yapmakta olduklarınızı çepeçevre kuşatmıştır.'),
(11, 93, 12, 232, 'وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ', 'wa yā qawmi ʿmalū ʿalā makāntikum ʾinnī ʿāmilun sawfa taʿlamūna man yaʾtīhi ʿaḏābun yukhzīhi wa man huwa kāḏibun wa-rtaqibū ʾinnī maʿakum raqībun', 'Ey kavmim! Yapacağınız şeyi yapın! Şüphesiz ben de yapacağım! Rezil edici azabın kime geleceğini ve kimin yalancı olduğunu yakında bileceksiniz. Gözetleyip bekleyin! Ben de sizinle birlikte gözleyip bekleyenlerdenim.'),
(11, 94, 12, 232, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'wa-lammā jāʾa ʾamrunā najjaynā Shuʿayban wa-lladhīna ʾāmanū maʿahu bi-raḥmatin minnā wa-ʾakhadhatِ lladhīna ẓalamū ṣ-ṣayḥatu fa-ʾaṣbaḥū fī diyārihim jāthimīna', 'Emrimiz geldiğinde, tarafımızdan bir rahmetle Şuayb''ı ve onunla birlikte iman edenleri kurtardık. Zulmedenleri ise korkunç bir ses yakaladı da oldukları yerde diz üstü çöke kaldılar.'),
(11, 95, 12, 232, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', 'kaʾan lam yaghnaw fīhā ʾalā buʿdan li-Madyana kamā baʿidat Thamūd', 'Sanki orada hiç yaşamamışlar gibi. Haberiniz olsun ki, Semûd kavmi nasıl uzaklaştırıldıysa, Medyen kavmi de öyle uzaklaştırılmıştır.'),
(11, 96, 12, 232, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'Ve lekad erselnâ Mûsâ bi-âyâtinâ ve sultânin mubîn', 'Andolsun ki Musa''yı ayetlerimizle ve apaçık bir delille gönderdik.'),
(11, 97, 12, 232, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ', 'ila firʿawna wa-malaihi fāttabaʿū amra firʿawna wa-mā amru firʿawna bi-rašīd', 'Firavun''a ve onun ileri gelenlerine. Firavun''un emrine uydular. Firavun''un emri ise doğru değildi.'),
(11, 98, 12, 233, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', 'yaqdimu qawmahu yawma l-qiyamati fa''awradahumu n-nara wa bi''sa l-wirdu l-mawruudu', 'Kıyamet günü kavminin önüne düşer, onları ateşe daldırır. O varılan yer ne kötü bir yerdir!'),
(11, 99, 12, 233, 'وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', 'wa-utbiʿū fī hādhihi laʿnatan wa-yawma l-qiyāmati biʾsa r-rifdu l-marfūdu', 'Ve bu dünyada ve kıyamet gününde bir lânete uğratıldılar. Ne kötü bir bağış!'),
(11, 100, 12, 233, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ مِنْهَا قَآئِمٌ وَحَصِيدٌ', 'dhālika min anbāʾi l-qurā naquṣṣuhu ʿalayka minhā qāʾimun waḥaṣīd', 'Bunlar, sana anlattığımız şehirler (halkları) hakkındaki haberlerden biridir. Onlardan kimisi ayaktadır, kimisi de biçilmiş ekin gibidir.'),
(11, 101, 12, 233, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ', 'wa mā ẓalamnāhum walākin ẓalamū ʾanfusahum famā ʾaġnat ʿanhum ʾālihatuhumu ʾallatī yadʿūna min dūni ʾallāhi min šayʾin lammā jāʾa ʾamru rabbika wa mā zādūhum ġayra tatbībin', 'Onlara biz zulmetmedik, fakat kendileri zulmettiler. Rabbinin emri geldiğinde, Allah''tan başka taptıkları tanrıları onlara hiçbir fayda sağlamadı; onların sadece helakini artırdı.'),
(11, 102, 12, 233, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ', 'wa kaḏālika ʾaḵḏu rabbika iḏā ʾaḵaḏa l-qurā wa hiya ẓālimah ʾinna ʾaḵḏahu ʾalīmun šadīd', 'Rabbin, zulmeden memleketleri (halklarını) yakaladığı zaman, işte böyle yakalar. Şüphesiz O''nun yakalaması elem dolu, pek şiddetlidir.'),
(11, 103, 12, 233, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّمَنْ خَافَ عَذَابَ ٱلْءَاخِرَةِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ', 'inna fī dhālika la-āyatan liman khāfa ʿadhāba al-ākhirah dhālika yawmun majmūʿun lahu an-nāsu wa-dhālika yawmun mashhūd', 'Şüphesiz bunda, ahiret azabından korkan kimseler için elbette bir ibret vardır. O, insanların toplandığı bir gündür; o, (tüm insanların) şahitlik edeceği bir gündür.'),
(11, 104, 12, 233, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ', 'wa mā nuʾakhkhiruhu ʾillā liʾajalin maʿdūd', 'Onları ancak belirli bir süreye kadar erteleriz.'),
(11, 105, 12, 233, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ', 'yawma yaʾtī lā takallamu nafṣun ʾillā bi-ʾiḏnihī faminhum šaqiyyun wa-saʿīd', 'O gün geldiğinde, (Allah''ın) izni olmadıkça hiç kimse konuşamaz. Artık onlardan kimi bedbaht, kimi de bahtiyardır.'),
(11, 106, 12, 233, 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ', 'fa-ʾammā alladhīna shaqū fa-fī n-nāri lahum fīhā zafīrun wa-shahīqun', 'Mutlu olanlar cennettedirler, bedbaht olanlar ise ateştedirler. Orada onların acı feryatları ve iç çekmeleri vardır.'),
(11, 107, 12, 233, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ', 'khālidīna fīhā mā dāmatis-samāwātu wal-arḍu illā mā shāʾa rabbuka ʾinna rabbaka faʿʿālun limā yurīdu', 'Onlar, gökler ve yer durdukça, Rabbinin dilediği müstesna, orada (cehennemde) sonsuza dek kalırlar. Şüphesiz Rabbin dilediğini hakkıyla yapandır.'),
(11, 108, 12, 233, 'وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ عَطَآءً غَيْرَ مَجْذُوذٍ', 'waʾammā alladhīna suʿidū pafī aljannati khālidīna fīhā mā dāmatis samāwātu walʾarḍu ʾillā mā shāʾa rabbuka ʿaṭāʾan ghayra majdhūdhin', 'Mutlu olanlara gelince, onlar cennettedirler; gökler ve yer durdukça, Rabbinin dilediği hariç, orada sonsuza dek kalacaklardır. Bu, kesintisi olmayan bir bağıştır.'),
(11, 109, 12, 234, 'فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ', 'falā taku fī miryatin mimmā yaʿbudu hāʾulāʾi mā yaʿbudūna illā kamā yaʿbudu ʾābāʾuhum min qablu wa-ʾinnā lamuwaffūhum naṣībahum ghayra manqūṣin', 'Onların taptıkları şeylerden şüpheye düşme; onlar ancak atalarının taptığı gibi taparlar. Ve biz de onlara paylarını eksiksiz olarak ödeyeceğiz.'),
(11, 110, 12, 234, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', 've lekad ʾātaynā mūsā l-kitāba fa-ukh''tulifa fīhi ve levlā kalimetun sebekat min rabbike lequḍiye beynehum ve ʾinnahum lefī şekkin minhu murībin', 'Andolsun ki Musa''ya Kitab''ı verdik de onda ayrılığa düşüldü. Eğer Rabbinden daha önce bir söz geçmiş olmasaydı, elbette aralarında hüküm verilirdi. Şüphesiz onlar, ondan yana kuşku veren bir tereddüt içindedirler.'),
(11, 111, 12, 234, 'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ', 'wa-ʾinna kullah-lamma layuwaffiyannahum rabbuka ʾaʿmalahum ʾinnahu bima yaʿmaluna khabirun', 'Ve her birine Rabbin amellerinin karşılığını mutlaka ödeyecektir. Şüphesiz O, yapmakta olduklarından haberdardır.'),
(11, 112, 12, 234, 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', 'fastaqim kamā umirta waman tāba maʿaka walā taṭghaw ʾinnahu bimā taʿmalūna baṣīr', 'Emrolunduğun gibi dosdoğru ol! Beraberindeki tövbe edenler de dosdoğru olsunlar. Ve azgınlık etmeyin. Şüphesiz O, yaptıklarınızı görmektedir.'),
(11, 113, 12, 234, 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', 'wa lā tarkanaū ilā lladhīna ẓalamū fatemassakumu n-nāru wa mā lakum min dūni llāhi min awliyāʾa thumma lā tunṣarūna', 'Zalimlere meyletmeyin, yoksa size ateş dokunur. Sizin Allah''tan başka dostlarınız yoktur, sonra (O''ndan başka kimseden) yardım göremezsiniz.'),
(11, 114, 12, 234, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', 'wa aqimi ṣ-ṣalāta ṭarafayi n-nahāri wa zulafan mina l-layli inna l-ḥasanāti yud''hibna s-sayyiʾāti dhālika dhikrā li-dh-dhākirīna', 'Gündüzün iki tarafında ve gecenin (ilk) saatlerinde dosdoğru namaz kıl. Şüphesiz iyilikler kötülükleri giderir. Bu, (Allah''ı) ananlar için bir öğüttür.'),
(11, 115, 12, 234, 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'waṣbir faʾinna ʾallāha lā yuḍīʿu ʾajra l-muḥsinīn', 'Sabret! Çünkü Allah iyilik edenlerin mükâfatını asla zayi etmez.'),
(11, 116, 12, 234, 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', 'falawlā kāna mina l-qurūni min qablikum ʾūlū baqiyyatin yanhawna ʿani l-fasādi fī l-ʾarḍi ʾillā qalīlan mimmānnajaynā minhum wa-ttabaʿa lladhīna ẓalamū mā ʾutrifū fīhi wa-kānū mujrimīn', 'Sizden önceki nesillerden, yeryüzünde bozgunculuk çıkarıp halkı ifsada çalışmak dışında iyilik ve fazilet sahibi kimseler bulunmalı değil miydi? Ama biz onlardan kurtardığımız pek azı müstesna, kurtuluşa erdirdiklerimiz dışında, orada (dünyada) zevk ve refaha dalıp gidenler, suçlu kâfirler oldular.'),
(11, 117, 12, 234, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ', 'wa mā kāna rabbuka liyuhlika l-qurā biẓulmin wa ʾahluhā muṣliḥūn', 'Senin Rabbin, halkı dürüst olduğu halde kasabaları haksız yere helak edecek değildi.'),
(11, 118, 12, 235, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ', 'wa law shāʾa rabbuka la-jaʿala n-nāsa ummatan wāḥidatan wa lā yazālūna mukhtalifīna', 'Rabbin dileseydi, insanları tek bir ümmet yapardı. Ama onlar ihtilafa düşmeye devam edeceklerdir.'),
(11, 119, 12, 235, 'إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'illa men raḥima rabbuk ve liḏālika ḵalaqahum ve tammat kelimetu rabbik laʾamlaʾanna ǧahannama minal-ǧinnati wan-nāsi ʾajmaʿīn', 'Ancak Rabbinin merhamet ettiği kimseler bunun dışındadır. Zaten O, insanları bunun için yaratmıştır. Ve Rabbinin şu sözü tamamlanmıştır: Andolsun ki cehennemi, cinlerden ve insanlardan bütünüyle dolduracağım!'),
(11, 120, 12, 235, 'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'wa kullannanaquṣṣu ʿalayka min ʾanbāʾi r-rusuli mā nuthabbitu bihi fūʾādaka wajāʾaka fī hādhihi l-ḥaqqu wamawʿiẓatun wadhikrā lil-muʾminīn', 'Resullerin haberlerinden sana anlattığımız her şeyi, senin kalbini (veya: gönlünü) sağlamlaştırmak için anlatıyoruz. Bunlarda sana hak, müminler için de bir öğüt ve hatırlatma gelmiştir.'),
(11, 121, 12, 235, 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ', 'wa qul lilladhīna lā yuʾminūn iʿmalū ʿalā makāntikum ʾinnā ʿāmilūn', 'İman etmeyenlere de ki: "Durumunuza göre elinizden geleni yapın! Şüphesiz biz de yapmaktayız!"'),
(11, 122, 12, 235, 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 'wa-ntẓirū ʾinnā muntaẓirūn', 'Ve gözetleyin, şüphesiz biz de gözeticileriz.'),
(11, 123, 12, 235, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'wa lillāhi ġaybu s-samāwāti wa l-ʾarḍi wa ʾilayhi yurjaʿu l-ʾamru kulluhū fa-ʿbudhu wa tawakkal ʿalayhi wa mā rabbuka biġāfilin ʿammā taʿmalūn', 'Göklerin ve yerin gaybı Allah''a aittir. Bütün işler O''na döndürülür. Öyleyse O''na kulluk et ve O''na tevekkül et. Senin Rabbin yaptıklarınızdan gafil değildir.'),
(12, 1, 12, 235, 'الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'Elif, Lâm, Ra. Tilke âyâtü''l-kitâbi''l-mubîn.', 'Elif, Lâm, Ra. Bunlar, apaçık olan Kitab''ın âyetleridir.'),
(12, 2, 12, 235, 'إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', 'ʾinnā ʾanzalnāhu qurʾānan ʿarabiyyan laʿallakum taʿqilūn', 'Doğrusu biz onu, akıllarınız ermesi için Arapça bir Kur''an olarak indirdik.'),
(12, 3, 12, 235, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ', 'naḥnu naquṣṣu ʿalayka aḥsana l-qaṣaṣi bimā awḥaynā ilayka hādhā l-qurʾāna wa-in kunta min qablihī la-mina l-ghāfilīna', 'Sana bu Kur''an''ı vahyederek kıssaların en güzelini anlatıyoruz. Halbuki bundan önce sen (bunlardan) habersizlerdendin.'),
(12, 4, 12, 235, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ', 'iż qāla yūsufu li-ʾabīhi yā ʾabati ʾinnī raʾaytu ʾaḥada ʿašara kawkaban wa-š-šamsa wa-l-qamara raʾaytuhum lī sājidīn', 'Hani Yusuf babasına demişti ki: "Babacığım! Gerçekten ben (rüyada) on bir yıldız, güneşi ve ayı gördüm. Gördüm ki onlar bana secde ediyorlar."'),
(12, 5, 12, 236, 'قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّ مُّبِينٌ', 'qāla yābunayya lā taqṣuṣ ruʾyāka ʿalā ʾikhwatika fayakīdū laka kaydan ʾinna ʾš-šayṭāna lil-ʾinsāni ʿaduwwun mubīnun', 'Babası şöyle dedi: "Yavrucuğum! Rüyanı kardeşlerine anlatma, yoksa sana bir tuzak kurarlar. Çünkü şeytan, insanın apaçık düşmanıdır."'),
(12, 6, 12, 236, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ', 'wa kaḏālika yajtabīka rabbuka wa yuʿallimuka min taʾwīli l-ʾaḥādīṯi wa yutimmu niʿmatahū ʿalayka wa ʿalā ʾāli yaʿqūba kamā ʾatammahā ʿalā ʾabawayka min qablu ʾibrāhīma wa ʾisḥāqa ʾinna rabbaka ʿalīmun ḥakīmun', 'Ve işte böyle Rabbin seni seçecek, sana (rüyaların) tevilini öğretecek ve daha önce ataların İbrahim ve İshak''a tamamladığı gibi nimetini senin ve Yakub''un soyunun üzerine tamamlayacaktır. Şüphesiz Rabbin, her şeyi bilen, hikmet sahibidir.'),
(12, 7, 12, 236, 'لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتٌ لِّلسَّآئِلِينَ', 'Lekad kâne fî Yûsufe ve ihvetihî âyâtun lissâilîn(e)', 'Andolsun ki Yûsuf ve kardeşlerinin kıssasında soranlar için ibretler vardır.'),
(12, 8, 12, 236, 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَٰلٍ مُّبِينٍ', 'idh qālū layūsufū wa-ʾaḫūhu ʾaḥabbu ʾilā ʾabīnā minnā wa naḥnu ʿuṣbah ʾinna ʾabānā lafī ḍalālin mubīn', 'Hani demişlerdi ki: ''Yusuf ve kardeşi babamız katında bize göre daha sevimlidir. Oysa biz (babamızın yanında) güçlü bir topluluğuz. Şüphesiz babamız apaçık bir sapıklık içindedir.'''),
(12, 9, 12, 236, 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَٰلِحِينَ', 'iqtulū yūsufa awi ṭraḥūhu arḍan yakhlu lakum wajhu abīkum wa takūnū min baʿdihī qawman ṣāliḥīn', 'Yusuf''u öldürün veya onu (herhangi) bir yere atıp bırakın ki babanızın yüzü size (size has) kalsın ve siz de ondan sonra hayırlı bir topluluk olasınız.'),
(12, 10, 12, 236, 'قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ', 'qāla qāʾilun minhum lā taqtulū yūsufa wa ʾalqūhu fī ġayābāti l-jubbi yaltaqiṭhu baʿḍu s-sayyārati ʾin kuntum fāʿilīna', 'İçlerinden bir sözcü dedi ki: ''Yusuf''u öldürmeyin, onu kuyunun dibine bırakın ki, eğer bir şey yapacaksanız, (oradan) bir kervan onu alsın.'''),
(12, 11, 12, 236, 'قَالُوا۟ يَٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ', 'qālū yā abānā mā laka lā taʾman-nā ʿalā Yūsufa wa innā lahu lī nāṣiḥūna', 'Dediler ki: "Ey babamız! Yusuf hakkında bize güvenmiyorsun. Oysa biz onun iyiliğini isteyenleriz."'),
(12, 12, 12, 236, 'أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'arsilhu maʿanā ghadan yartaʿ wa-yalʿab wa-innā lahu laḥāfiẓūn', 'Onu bizimle yarın gönder de serin sérin gezsin, oynasın. Şüphesiz biz onu koruyacağız.'),
(12, 13, 12, 236, 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ', 'qāla innī layaḥzununī an taḏ-habū bihī wa ʾaḫāfu ʾan yaʾkulahu ḏ-ḏiʾbu wa ʾantum ʿanhu ġāfilūn', 'Dedi ki: "Onu götürmeniz beni üzer ve sizin ondan gafil olduğunuz bir sırada onu kurdun yiyeceğinden korkarım."'),
(12, 14, 12, 236, 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَٰسِرُونَ', 'qālū laʾin ʾakalahu ʾaḏ-ḏiʾbu wa-naḥnu ʿuṣbatun ʾinnā ʾiḏan la-khāsirūn', 'Dediler ki: "Andolsun ki onu kurt yerse, biz de (bu kadar) kalabalıkken gerçekten hüsrana uğrayanlardan oluruz."'),
(12, 15, 12, 237, 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ', 'fe-lemmā żehebū bihi ve ecmeʿū en yecʿalūhu fī ġayābāti l-cubbi ve ūḥaynā ileyhi le-tunabbiʾennehum bi-ʾemrihim hāḏā ve hum lā yešʿurūn', 'Nihayet onu götürmeye karar verdiklerinde ve onu kuyunun derinliklerine atmayı ittifakla kararlaştırdıklarında, biz de ona şöyle vahyettik: "Andolsun ki sen onlara, onların bu işini, onlar farkında değilken, mutlaka haber vereceksin."'),
(12, 16, 12, 237, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ', 'wa jāʾū ʾabāhum ʿishāʾan yabkūn', 'Akşam karanlığında ağlayarak babalarına geldiler.'),
(12, 17, 12, 237, 'قَالُوا۟ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ', 'qālū yā abānā innā dhahabnā nastabiqu wataraknā Yūsufa ʿinda matāʿinā faʾakalahu ʾal-dhiʾbu wamā anta bimūʾminin lanā walaw kunnā ṣādiqīna', 'Dediler ki: "Ey babamız! Gerçekten biz Yusuf''u eşyamızın yanında bırakıp (yarışmak üzere) gittik. Sonra onu kurt yedi. Ama sen bize inanmazsın, gerçi biz doğru söyleyenler olsak bile."'),
(12, 18, 12, 237, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'wa jāʾū ʿalā qamīṣihi bi-damin kadhibin qāla bal sawwalat lakum anfusukum amran fa-ṣabrun jamīlun wa-llāhu l-mustaʿānu ʿalā mā taṣifūna', 'Ve onun gömleğine (sürülmüş) yalancı bir kanla geldiler. (Babaları) "Hayır, nefisleriniz sizi aldatıp hoş bir işe sürükledi. Artık bana güzel bir sabır (düşüyor). Anlattıklarınız (iddialarınız) üzerine Allah''tan yardım istenir" dedi.'),
(12, 19, 12, 237, 'وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ قَالَ يَٰبُشْرَىٰ هَٰذَا غُلَٰمٌ وَأَسَرُّوهُ بِضَٰعَةً وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', 'wa jāʾat sayyāratun fa ʾarsalū wāridahum fa ʾadlā dalwahū qāla yā bušrā hāḏā ġulāmun wa ʾasarruhū biḍāʿatan wa ʾallāhu ʿalīmun bimā yaʿmalūna', 'Bir kervan geldi. Bunun üzerine (suya) birini gönderdiler. O da kovasını sarkıttı. "Müjde! İşte bu bir oğlan!" dedi. Onu (bu kervana) bir ticaret malı olarak gizlediler. Oysa Allah onların yapmakta olduklarını biliyordu.'),
(12, 20, 12, 237, 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', 'wa sharawhu bi-thamanin bakhsin darāhima maʿdūdatin wa kānū fīhi mina al-zāhidīn', 'Onu az bir paraya, sayıları az birkaç dirheme sattılar. Zaten ona karşı ilgisiz kalmışlardı.'),
(12, 21, 12, 237, 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'waqāla lladhī shtarāhu min miṣra li-mraʾatihi akrimī mathwāhu ʿasā an yanfaʿanā aw nattakhidha waldan wa kadhālika makkannā li-yūsufa fī l-arḍi wa li-nuʿallimahu min taʾwīli l-aḥādīthi wa llāhu ghālibun ʿalā amrihi wa lākinna akthara n-nāsi lā yaʿlamūna', 'Onu Mısır''dan satın alan kimse, (karısına şöyle dedi:) "Onun ağırlanmasına güzel bak; umulur ki bize faydası dokunur, yahut onu evlat ediniriz." İşte böylece Yusuf''u o yere yerleştirdik ve ona (rüyaların) tabirinden (ilmini) öğrettik. Allah, emri (ప్‌) üzerinde galiptir, ancak insanların çoğu bunu bilmezler.'),
(12, 22, 12, 237, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'Wa lammā balagha ʾushuddahu ʾātaynāhu ḥukman wa ʿilman Wa kaḏālika najzī l-muḥsinīn', 'Ve Yusuf, gücüne (olgunluk çağına) erdiği zaman, ona hüküm (hikmet) ve ilim verdik. İşte biz, iyilik edenleri böyle mükâfatlandırırız.'),
(12, 23, 12, 238, 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ ٱللَّهِ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'wa-rāwadat-hu allatī huwa fī baytihā ʿan nafsihi wa-ghallaqati l-ʾabwāba wa-qālat hayta laka qāla maʿādha llāhi ʾinnahu rabbī ʾaḥsana mathwāya ʾinnahu lā yufliḥu ẓ-ẓālimūna', 'Onu, evinde tutan kadın (Züleyha) nefsinden (ona sahip olmak için) murad etti ve kapıları kilitleyip şöyle dedi: "Haydi gel!" (Yusuf) dedi ki: "Allah''a sığınırım! Gerçekten o benim rabbimdir, bana iyi bakmıştır. Şüphesiz zalimler kurtuluşa ermez."'),
(12, 24, 12, 238, 'وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', 've lekad hemmet bihī ve hemme bihā levlā en raʾā burhāne rabbihī keẕālike linaṣrife ʿanhu s-sūʾe ve l-faḥşāʾe innehū min ʿibādinā l-muḫlaṣīn', 'Andolsun ki kadın ona meyletmişti, eğer Rabbinin burhanını görmeseydi o da kadına meyledecekti. İşte böylece kötülüğü ve fuhşu ondan uzaklaştırmak için (yaptık). Şüphesiz o, bizim ihlaslı kullarımızdandı.'),
(12, 25, 12, 238, 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ', 'wastabaqā l-bāba wa qaddat qamīṣahu min duburi wa alfayā sayyidahā ladā l-bābi qālat mā jazāʾu man arāda bi-ʾahlika sūʾan ʾillā ʾan yusjana ʾaw ʿadhābun ʾalīmun', 'Kapıya doğru koştular ve (kadın) onun gömleğini arkadan yırttı. Kapının yanında efendisine rastladılar. Kadın dedi ki: "Ailene bir kötülük yapmak isteyenin cezası, zindana atılmaktan veya elem verici bir azaptan başka ne olabilir?"'),
(12, 26, 12, 238, 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ', 'qāla hiya rāwadatnī ʿan nafsī wa shahida shāhidun min ahlihā in kāna qamīṣuhu qudda min qubulin faṣadaqat wa huwa mina l-kādhibīn', 'Dedi ki: ''O, benim nefsime (benden) murad almak istedi. (O sırada) ailesinden bir şahit de şahitlik etti: ''Eğer onun gömleği ön tarafından yırtılmışsa, o zaman kadın doğru söylemiştir ve (erkek) yalancılardandır.'''),
(12, 27, 12, 238, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ', 'wa-ʾin kāna qamīṣuhu qudda min duburin fakadhabat wa-huwa mina ṣ-ṣādiqīn', 'Eğer onun gömleği arkadan yırtılmışsa, o zaman kadın yalan söylemiştir ve o (Yusuf) doğru söyleyenlerdendir.'),
(12, 28, 12, 238, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ', 'felemmā raʾā qamīṣahu qudda min duburin qāla innahū min kaydikunna inna kaydakunna ʿaẓīmun', 'Nihayet onun gömleğini, arkadan yırtılmış görünce dedi ki: "Doğrusu bu, sizin hilelerinizdendir. Gerçekten sizin hileleriniz pek büyüktür."'),
(12, 29, 12, 238, 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَٱسْتَغْفِرِى لِذَنۢبِكِ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', 'Yūsufu aʿriḍ ʿan hādhā Wastagfirī li-dhanbiki ʾInnaki kunti mina l-khāṭiʾīn', 'Yusuf! Bundan yüz çevir. (Kadınlar için de:) Günahından dolayı bağışlanma dile! Çünkü sen günahkârlardan idin.'),
(12, 30, 12, 238, 'وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍ مُّبِينٍ', 'waqāla niswatun fī l-madīnati imraʾatu l-ʿazīzi turāwidu fatāhā ʿan nafsihi qad shaghafahā ḥubban ʾinnā lanarāhā fī ḍalālin mubīni', 'Şehirde bir grup kadın dedi ki: "Aziz''in karısı (Züleyha) genç hizmetçisini (Yusuf''u) baştan çıkarmaya çalışıyor. Yüreğine aşkı düşürmüş! Şüphesiz biz onu apaçık bir sapıklık içinde görüyoruz."'),
(12, 31, 12, 239, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌ كَرِيمٌ', 'fe-lemmā semiʿat bi-makrihinna arsalet ileyhinna ve-aʿtedet lehunna muttakaʾan ve-ātat kul-le wāḥidatin minhunne sikkīnan ve-qāli-ti-khruj ʿaleyhinna fe-lemmā raʾayna-hū akbarnahu ve-qaṭṭaʿne eydiye-hunna ve-qum-ne ḥāsha li-llāhi mā hādhā basharan in hādhā illā malekun kerīmun', 'Kadınlar onun hilesini işitince, birbirlerine haber gönderip haber saldılar. Yusuf''un etrafına toplandılar. Ona bakıp (güzelliği karşısında) hayran kaldılar ve (kendilerinden geçerek) ellerini kestiler. ''Haşa! Bu bir beşer değil, ancak kerim bir melektir!'' dediler.'),
(12, 32, 12, 239, 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّٰغِرِينَ', 'qālat faḏālikunna llaḏī lumtunnanī fīhi wa laqad rāwadtu hū ʿan nafsi hī fastaʿṣama wa laʾin lam yafʿal mā ʾāmuruhū la yusjananna wa la yakūnan mina ṣ-ṣāġirīn', 'Kadın dedi ki: İşte bu, hakkında beni kınadığınız (erkek)dir. Andolsun, ben onu (nefsine) davet ettim, ama o, (benden) kaçındı. Yemin ederim ki, eğer emrettiğimi yapmazsa, mutlaka zindana atılacak ve mutlaka küçük düşenlerden olacaktır.'),
(12, 33, 12, 239, 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ', 'qāla rabbi s-siǧnu aḥabbu ʾilayya mimmā yadʿūnanī ʾilayhi wa-ʾillā taṣrif ʿannī kaydahunna ʾaṣbu ʾilayhinna wa-ʾakun mina l-ǧāhilīn', 'Rabbim! Zindan bana, onların beni davet ettikleri şeye tercih ederim. Eğer onların tuzaklarını benden çevirmezsen, onlara meylederim ve (böylece) cahillerden olurum.'),
(12, 34, 12, 239, 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'fastajāba lahu rabbuhu faṣarafa ʿanhu kaydahunna ʾinnahu huwa s-samīʿu l-ʿalīmu', 'Bunun üzerine Rabbi onun duasını kabul etti ve onlardan gelen hileli düzeni ondan uzaklaştırdı. Şüphesiz O, hakkıyla işiten, kemaliyle bilendir.'),
(12, 35, 12, 239, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْءَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ', 'thumma badā lahum min baʿdi mā raʾawu l-ʾāyāti layasjununnahū ḥattā ḥīnin', 'Nihayet, o alâmetleri (mucizeleri) gördükten sonra, onlara (zihinlerine) onun zindana atılmasına kadar bir müddet için (bu fikir) göründü.'),
(12, 36, 12, 239, 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا وَقَالَ ٱلْءَاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِۦٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'wa-dakhala maʿahu al-sijna fatayāni qāla aḥaduhumā innī arānī aʿṣiru khamrā wa-qāla al-ākharu innī arānī aḥmilu fawqa raʾsī khubzan taʾkulu al-ṭayru minhu nabbʾinā bi-taʾwīlihī ʾinnā narāka mina al-muḥsinīna', 'Onunla birlikte zindana iki genç adam da girdi. Biri, ''Ben (rüyada) üzüm sıkıyordum'' dedi. Diğeri ise, ''Ben (rüyada) başımın üzerinde ekmek taşıyordum, kuşlar da ondan yiyordu'' dedi. ''Bunun yorumunu bize haber ver. Şüphesiz biz seni iyilik edenlerden görüyoruz.'''),
(12, 37, 12, 239, 'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 'qāla lā yaʾtīkumā ṭaʿāmun turzaqānihi ʾillā nabaʾtukumā bitaʾwīlihi ʾqabla ʾan yaʾtiyakumā ḏālikumā mimmā ʿallamanī rabbī ʾinnī taraktu milleta qawmin lā yuʾminūna billāhi wa hum bil-ʾākhirati hum kāfirūna', 'O, şöyle dedi: "Size rızık olarak bir yiyecek gelmeden önce, onun ne olduğunu (nasıl bir şey olduğunu) size mutlaka haber vereceğim. Bu, Rabbimin bana öğrettiklerindendir. Şüphesiz ben, Allah''a inanmayan ve ahireti inkâr eden bir kavmin dinini terk ettim."'),
(12, 38, 12, 240, 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'wa-ttabaʿtu milleta ʾābāʾī ʾibrāhīma wa-ʾisḥāqa wa-yaʿqūba mā kāna lanā ʾan nushrika bi-llāhi min shayin dhālika min faḍli llāhi ʿalaynā wa-ʿalā n-nāsi wa-lākinna ʾakthara n-nāsi lā yashkurūna', 'Ve atalarım İbrahim, İshak ve Yakub''un dinine uydum. Allah''a hiçbir şeyi ortak koşmamız olamaz. Bu, Allah''ın bize ve bütün insanlara olan fazlındandır. Fakat insanların çoğu şükretmezler.'),
(12, 39, 12, 240, 'يَٰصَىٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'yā ṣāḥibayi s-siǧni ʾa ʾarbābun mutafariqūna ḫayrun ʾam allāhu l-wāḥidu l-qahhāru', 'Ey zindan arkadaşlarım! Dağınık (farklı) Rabler mi daha hayırlıdır, yoksa kahreden tek Allah mı?'),
(12, 40, 12, 240, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'mā taʿbudūna min dūnihi ʾillā ʾasmāʾan sammaytumūhā ʾantum wa-ʾābāʾukum mā ʾanzala ʾllāhu bihā min sulṭānin ʾini l-ḥukmu ʾillā li-llāhi ʾamara ʾallā taʿbudū ʾillā ʾiyyāhu dhālika d-dīnu l-qayyimu wa-lākinna ʾakthara n-nāsi lā yaʿlamūna', 'O''ndan başka taptıklarınız, sizin ve atalarınızın (verdiği) ismidir. Allah, onlarla ilgili hiçbir delil indirmemiştir. Hüküm ancak Allah''a aittir. O, kendisinden başkasına tapmamanızı emretmiştir. İşte bu dosdoğru dindir. Fakat insanların çoğu bilmezler.'),
(12, 41, 12, 240, 'يَٰصَىٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا وَأَمَّا ٱلْءَاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', 'yā ṣāḥibayi s-siǧni ammā ʾaḥadukumā fa-yasqī rabbahū ḫamran wa-ʾammā l-ʾāḫaru fa-yuṣlabu fa-taʾkulu ṭ-ṭayru min raʾsihī quḍiya l-ʾamru l-laḏī fīhi tastaftiyāni', 'Ey zindan arkadaşlarım! (Rüyanızın tabiri şudur:) İçinizden biri Rabbine şarap sunacaktır. Diğeri ise asılacak da kuşlar onun başından yiyecektir. İşte bu, sorup durduğunuz şeyin kesinleşmiş hükmüdür.'),
(12, 42, 12, 240, 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', 'waqāla lladhī ẓanna annahu nājin minhumā udhkur''nī ʿinda rabbika fa ansāhu sh-shayṭānu dhikra rabbihī falabitha fī s-sijni biḍʿa sinīna', 'İçlerinden kurtulacağını sandığı kimseye dedi ki: "Beni, (efendinin) yanında an. Fakat şeytan, ona (bu durumu) efendisinin yanında anmayı unutturdu. Bu yüzden Yusuf zindanda birkaç yıl daha kaldı."'),
(12, 43, 12, 240, 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', 'waqāla l-maliku innī ʾarā sabʿa baqarātin simānin yaʾkuluhunna sabʿun ʿijāfun wasabʿa sunbulātin khuḍrin waʾukhara yābisātin yā ʾayyuhā l-malaʾu ʾaftūnī fī ruʾyāya ʾin kuntum lirruʾyā taʿburūna', 'Kral dedi ki: "Ben yedi semiz inek yedi zayıf ineğin onları yediğini ve yedi yeşil başakla diğerlerini kuru (başakları) görüyorum. Ey ileri gelenler! Eğer rüya tabir ediyorsanız, bu rüyam hakkında bana (görüşlerinizi) söyleyin."'),
(12, 44, 12, 241, 'قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ', 'qālū ʾaḍḡāṯu ʾaḥlāmin wa mā naḥnu bi-taʾwīli l-ʾaḥlāmi bi-ʿālimīna', 'Dediler ki: Bunlar karmakarışık düşlerdir; biz böyle düşlerin yorumunu bilenlerden değiliz.'),
(12, 45, 12, 241, 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', 'waqāla lladhī najā minhumā wāddakkara baʿda ummatin anā unabbiʾukum bitāʾwīlihī faʾarsilūnī', 'Onlardan kurtulmuş olan ve uzun bir zaman sonra (Yusuf''u) hatırlayan kişi şöyle dedi: "Ben onun tabirini size haber vereyim, hemen beni (Yusuf''a) gönderin."'),
(12, 46, 12, 241, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 'Yūsufu ayyuhā ṣ-ṣiddīqu aftinā fī sabʿi baqarātin simānin yaʾkuluhunna sabʿun ʿijāfun wa-sabʿi sunbulātin khuḍrin wa-ukhar yābisātin laʿallī arjiʿu ilá n-nāsi laʿallahum yaʿlamūna', 'Ey doğru sözlü Yusuf! Bize yedi semiz ineği yedi zayıf ineğin yediğini ve yedi yeşil başakla diğer kuru başakları yorumla ki, insanlara (rüyalarının tabirini) döne bileyim, belki onlar da (durumu) öğrenirler.'),
(12, 47, 12, 241, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ', 'qāla tazraʿūna sabʿa sinīna daʾaban famā ḥaṣadtum fadẖūrūhu fī sunbulihī ʾillā qalīlan mimmā taʾkulūn', 'Yedi yıl boyunca (ürünleri) âdet üzere ekin. Sonra da (veriminden) yiyeceğiniz az bir miktar hariç, (topladıklarınızı) başağında bırakın.'),
(12, 48, 12, 241, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ', 'thumma yaʾtī min baʿdi ḏālika sabʿun šidādun yaʾkulna mā qaddamtum lahunna ʾillā qalīlan mimmā tuḥṣinūn', 'Sonra bunun ardından yedi kurak yıl gelecektir. (Bu yıllarda) sakladıklarınızdan az bir miktar hariç, onlar için biriktirdiğiniz her şeyi yiyeceklerdir.'),
(12, 49, 12, 241, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', 'thumma yaʾtī min baʿdi dhālika ʿāmun fīhi yughāthu n-nāsu wa fīhi yaʿṣirūn', 'Sonra bunun ardından, insanların yardım göreceği ve (o zaman) sıkıp-suyunu çıkaracakları bir yıl gelecektir.'),
(12, 50, 12, 241, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ', 'waqāla l-maliku ʾtiūnī bihi falammā jāʾahu r-rasūlu qāla rjiʿ ʾilā rabbika fasʾalhu mā bālu n-niswati llatī qaṭṭaʿna ʾaydiyahunna ʾinna rabbī bikaydihenna ʿalīmun', 'Kral dedi ki: ''Onu bana getirin!'' Elçi ona geldiğinde (Yusuf) dedi ki: ''Efendine dön de, ellerini kesen o kadınların durumunu sor. Şüphesiz Rabbim onların hilelerini bilendir.'''),
(12, 51, 12, 241, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 'qāla mā khaṭbukunna iḏ rāwadtunna Yūsufa ʿan nafsihi qulna ḥāsha lillāhi mā ʿalimnā ʿalayhi min sūʾin qālati mraʾatu l-ʿazīzi l-ʾāna ḥaṣḥaṣa l-ḥaqqu ʾanā rāwadtuhu ʿan nafsihi wa-ʾinnahu la mina ṣ-ṣādiqīn', 'Sultan dedi ki: "Onu baştan çıkarmak istediğinizde durumunuz neydi?" Kadınlar dediler ki: "Allah''a sığınırız! Onun hakkında hiçbir kötülük bilmiyoruz." Azîz''in karısı dedi ki: "Şimdi gerçek ortaya çıktı. Onu baştan çıkarmak isteyen bendim. Şüphesiz o, doğru söyleyenlerdendir."'),
(12, 52, 12, 241, 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', 'dhālika liyaʿlama annī lam ʾakhunhu bil-ghaybi wa-anna Allāha lā yahdī kayda l-khāʾinīna', 'Bunun sebebi, benim ona arkasından (ihanet etmediğimi) bilmesi ve Allah''ın hainlerin tuzakını başarılı kılmayacağını bilmesidir.'),
(12, 53, 13, 242, 'وَمَآ أُبَرِّئُ نَفْسِىٓ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ', 've mā ubarriʾu nafsī ʾinna n-nafsa laʾammāratum bis-sūʾi ʾillā mā raḥima rabbī ʾinna rabbī ġafūrun raḥīmun', 'Ben nefsimi temize çıkarmam. Çünkü nefis, daima kötülüğü emreder. Rabbimin mağfireti müstesna. Şüphesiz Rabbim, çok bağışlayandır, çok merhamet edendir.'),
(12, 54, 13, 242, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ', 'waqāla l-maliku ʾtiūnī bihi ʾastakhliṣhu linafsī falammā kallamahu qāla ʾinnaka l-yawma ladaynā makīnun ʾamīn', 'Kral dedi ki: "Onu bana getirin, kendim için onu seçeyim." Onunla konuşunca dedi ki: "Şüphesiz bugün sen, yanımızda güçlü ve güvenilir birisin."'),
(12, 55, 13, 242, 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ إِنِّى حَفِيظٌ عَلِيمٌ', 'qāla ǧʿalnī ʿalā ḫazāʾini l-ʾarḍi ʾinnī ḥafīẓun ʿalīmun', 'Onun üzerine (Yusuf''a): ''Beni Mısır hazinelerinin başına getir. Çünkü ben, (onları) koruyup gözeten (ve) bilgili (bir kimseyim)'' dedi.'),
(12, 56, 13, 242, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'wa kadhalika makkanna liyūsufa fī l-arḍi yatabawwaʾu minhā ḥaythu yashāʾu nuṣību biraḥmatinā man nashāʾu walā nuḍīʿu ajra l-muḥsinīna', 'İşte böylece Yusuf''u o yerde (Mısır''da) kudretli kıldık. Dilediği yerde konaklıyordu. Biz rahmetimizle dilediğimizi böyle üstün kılarız ve iyilik edenlerin mükâfatını zayi etmeyiz.'),
(12, 57, 13, 242, 'وَلَأَجْرُ ٱلْءَاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'wa laʾajru l-ʾākhirati khayrun lilladhīna ʾāmanū wa kānū yattaqūna', 'Ahiret sevabı ise iman edip takva sahibi olanlar için daha hayırlıdır.'),
(12, 58, 13, 242, 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', 'wa jāʾa ʾikhwatū yūsufa fadakhalū ʿalayhi faʿarafahum wa hum lahū munkirūn', 'Yusuf''un kardeşleri geldi ve onun yanına girdiler. Onu tanıdı, ama onlar onu tanımıyorlardı.'),
(12, 59, 13, 242, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', 'wa lammā jahhazahum bijahāzihim qāla ʾiʾtūnī bi-ʾakhin lakum min ʾabīkum ʾalā tarawna ʾannī ʾūfī l-kayla wa ʾanā khayru l-munzilīn', 'Onları azıklarıyla hazırladığı zaman (Yusuf) dedi ki: Babanızdan olan bir kardeşinizi bana getirin. Görmüyor musunuz, ben ölçüyü tam dolduruyorum ve ben misafirperverlerin en iyisiyim.'),
(12, 60, 13, 242, 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', 'fa-in lam taʾtūnī bihi fa-lā kayla lakum ʿindī wa-lā taqrabūn', 'Eğer onu bana getirmezseniz, artık benim yanımda sizin için ne bir ölçü (yiyecek) vardır, ne de bana (yaklaşabilirsiniz).'),
(12, 61, 13, 242, 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', 'qālū sanurāwidu ʿanhu abāhu wa-innā lafāʿilūn', 'Dediler ki: "Onu babasından (isteyeceğiz) ve biz şüphesiz bunu yapanlarız."'),
(12, 62, 13, 242, 'وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', 'waqāla lifityānihi ijʿalū biḍāʿatahum fī riḥālihim laʿallahum yaʿrifūnahā idhā nqalabū ilā ahlihim laʿallahum yarjiʿūn', 'Onlar, onun yanından ayrılınca dedi ki: "Onların sermayelerini (getirdikleri malları) yüklerine koyun, ailelerine döndüklerinde tanıyabilmeleri için. Umulur ki geri dönerler."'),
(12, 63, 13, 242, 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'fe-lemmā recaʿū ilā ebīhim qālū yā abānā muniʿa minnā l-kaylu fe-arsil maʿanā eḫānā naktal we-innā lehu leḥāfiẓūn', 'Babalarına döndüklerinde dediler ki: "Ey babamız! Bize ölçü (bir daha) verilmedi. Bu yüzden kardeşimizi (Yusuf''un kardeşi Bünyamin''i) bizimle birlikte (Mısır''a) gönder. Böylece bize ölçü verilir ve biz onu muhakkak koruyacağız."'),
(12, 64, 13, 243, 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ فَٱللَّهُ خَيْرٌ حَٰفِظًا وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'qāla hal ʾāmanukum ʿalayhi ʾillā kamā ʾamintukum ʿalā ʾaḵīhi min qablu fa-llāhu ḵayrun ḥāfiẓan wa-huwa ʾarḥamu ʾar-rāḥimīn', 'Dedi ki: "Onu size emanet etmek, daha önce kardeşini emanet ettiğim zamanki kadar güvenebilir miyim? Ancak Allah en hayırlı koruyucudur ve O, merhametlilerin en merhametlisidir."'),
(12, 65, 13, 243, 'وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ', 'wa lammā fataḥū matāʿahum wajadū biḍāʿatahum ruddat ilayhim qālū yā abānā mā nabġī hādhihi biḍāʿatunā ruddat ilaynā wa namīru ahlana wa naḥfaẓu akhāna wa nazdādu kayla baʿīrin dhālika kaylun yasīrun', 'Onlar eşyalarını açtıklarında, sermayelerinin kendilerine iade edildiğini gördüler. "Ey babamız!" dediler, "Daha ne isteyebiliriz? İşte sermayemiz bize iade edilmiş. Ailemize yiyecek getiririz, kardeşimize de sahip çıkarız ve bir deve yükü daha fazla alırız. Bu (sonuncusu) az bir yüktür."'),
(12, 66, 13, 243, 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', 'qāla lan ursilahu maʿakum ḥattā tuʾtūnī mawthiqan mina ʾllāhi lataʾtunanī bihi ʾillā ʾan yuḥāṭa bikum falammā ʾātūhu mawthiqahum qāla ʾllāhu ʿalā mā naqūlu wakīlun', 'Şöyle dedi: "Hiçbiriniz tarafından kuşatılmadıkça onu bana getireceğinize dair Allah''tan bir ahid almadıkça, onu sizinle asla göndermem." Onlar ahidlerini verince, Allah onların söylediklerine şahit tutuldu.'),
(12, 67, 13, 243, 'وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 'wa qāla yā baniyya lā tadkhulū min bābin wāḥidin wadkhulū min abwābin mutafarriqah wa mā ughnī ʿankum mina llāhi min shaiʾ ini l-ḥukmu illā li llāh ʿalayhi tawakkaltu wa ʿalayhi fa-l-yatawakkali l-mutawakkilūn', 'Ve (Yusuf) dedi ki: ''Yavrucuğum! Bir kapıdan girmeyin, ayrı ayrı kapılardan girin. (Babacığım!) Ben Allah''tan gelecek hiçbir şeyi sizden savamam. Hüküm ancak Allah''ındır. O''na tevekkül ettim ve tevekkül edenler de ancak O''na tevekkül etmelidirler.'''),
(12, 68, 13, 243, 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'wa lammā dakhalū min ḥaythu amarahum abūhum mā kāna yughnī ʿanhum mina llāhi min shayin illā ḥājatan fī nafsi yaʿqūba qaḍāhā wa innahu la dhū ʿilmin limā ʿallamnāhu wa lākina akthara n-nāsi lā yaʿlamūn', 'Babalarının kendilerine emrettiği yerden girdiklerinde, Allah''tan (gelecek) hiçbir şeyi onlardan savacak değildi. Ancak Yakub''un gönlünde bir dileği vardı, onu yerine getirdi. Şüphesiz o, Bizim kendisine öğrettiğimizden dolayı bilgi sahibi idi. Fakat insanların çoğu bilmezler.'),
(12, 69, 13, 243, 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', 'wa lammā dakhalū ʿalā Yūsufa āwā ilayhi akhāhu qāla innī anā akhūka falā tabtaʾis bimā kānū yaʿmalūn', 'Yusuf''un yanına girdiklerinde, (kardeşini) kendi yanına aldı ve şöyle dedi: "Ben senin kardeşinim. Artık onların yapmakta olduklarına üzülme."'),
(12, 70, 13, 244, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ', 'fe-lemmā cehhezehum bi-cehāzihim ceʿale s-siqāyete fī raḥli ʾeḫīhi summā ʾeḏḏene muʾeḏḏenun ʾeyyetuhā l-ʿīru ʾinnakum le-sāriqūne', 'Onları hazırlayınca, su kabını kardeşinin yüküne koydu. Sonra bir tellal: "Ey kafile! Siz gerçekten hırsızsınız!" diye seslendi.'),
(12, 71, 13, 244, 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', 'qālū waʾaqbalū ʿalayhim māḏā tafqidūn', 'Onlar, ona yönelerek: "Ne kaybettiniz?" dediler.'),
(12, 72, 13, 244, 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ', 'qālū nafqidu ṣuwāʿa l-maliki wa liman jāʾa bihi ḥimlu baʿīrin wa anā bihi zaʿīmun', 'Dediler ki: "Hükümdarın kabını kaybettik. Onu getirene bir deve yükü (sevap) vardır. Ben bunun kefiliyim."'),
(12, 73, 13, 244, 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ', 'qālū tallāhi laqad ʿalimtum mā jiʾnā linufside fī l-ʾarḍi wamā kunnā sāriqīna', 'Dediler ki: Allah''a yemin ederiz ki, siz de bilmektesiniz ki biz, yeryüzünde fesat çıkarmak için gelmedik ve biz hırsız da değiliz.'),
(12, 74, 13, 244, 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ', 'qālū famā jazāʾuhu in kuntum kādhibīn', 'Dediler ki: "Eğer yalancılardan iseniz, onun cezası nedir?"'),
(12, 75, 13, 244, 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'qālū jazāʾuhu man wujida fī raḥlihī fa-huwa jazāʾuhu kadhālika najzī ẓ-ẓālimīn', 'Dediler ki: "Onun cezası, kendisi hangi melikte bulunursa, işte onun cezası odur. Biz zalimleri böyle cezalandırırız."'),
(12, 76, 13, 244, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ', 'fa-badaʾa bi-ʾawʿiyatihim qabla wiʿāʾi ʾaḵīhi ṯumma-starḵarahā min wiʿāʾi ʾaḵīhi kaḏālika kidnā li-Yūsufa mā kāna li-yaʾḵuḏa ʾaḵāhu fī dīni-l-maliki ʾillā ʾan yašāʾa-llāhu narfaʿu darajātin man našāʾu wa-fawqa kulli ḏī ʿilmin ʿalīmun', 'Böylece, kardeşinin kabının önünde, onun kaplarını aramaya başladı. Sonra kardeşinin kabından onu çıkardı. İşte böylece Yusuf''a bir tuzak kurduk. Kralın kanununa göre kardeşini alamayacaktı, ancak Allah''ın dilediği müstesna. Biz dilediğimizi derecelerle yükseltiriz. Her ilim sahibinin üstünde daha üstün bir bilen vardır.'),
(12, 77, 13, 244, 'قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', 'qālū ʾin yasriq faqad saraqa ʾakhun lahū min qablu faʾasarrahā yūsuf fī nafsihi walan yubdihā lahum qāla ʾantum sharrun makānan wallāhu ʾaʿlamu bimā taṣifūna', 'Dediler ki: Eğer o çalmışsa, daha önce kardeşi de çalmıştı. Bunun üzerine Yusuf, bu sırrı içine attı ve onlara belli etmedi. (Kendi kendine) şöyle dedi: Siz durumca daha kötü bir yerdesiniz. Allah ise sizin vasfettiğiniz şeyi daha iyi bilendir.'),
(12, 78, 13, 244, 'قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'qālū yā ʾayyuhā ʾl-ʿazīzu ʾinna lahū ʾaban shaykhan kabīran fakhudh ʾaḥadanā makānahū ʾinnā narāka mina ʾl-muḥsinīna', 'Dediler ki: "Ey (aziz)! Şüphesiz onun çok yaşlı bir babası var. Bu yüzden bizden birini onun yerine al. Gerçekten biz seni iyilik edenlerden görüyoruz."'),
(12, 79, 13, 245, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَٰلِمُونَ', 'qāla maʿāḏa llāhi an naʾḵuḏa ʾillā man wajadnā matāʿanā ʿindahu ʾinnā ʾiḏan laẓālimūn', 'Allah''a sığınırım! dedi, Eşyamızı yanında bulduğumuz kimse hariç, başkasını alıkoyamayız. Çünkü o takdirde biz gerçekten zalimler oluruz.'),
(12, 80, 13, 245, 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'fe-lemmā-steyʾesū minhu khalasū najiyyan qāla kabīruhum a-lem taʿlamū anna abākum qad ʾakhadha ʿalaykum mawthiqan mina-llāhi wa-min qablu mā farratṭum fī Yūsufa fa-lan ʾabraḥa l-ʾarḍa ḥattā yaʾdhana lī ʾabī ʾaw yaḥkuma-llāhu lī wa-huwa khayru l-ḥākimīn', 'Nihayet ondan umutlarını kestiklerinde, aralarında gizlice konuşarak çekildiler. Onların büyüğü dedi ki: "Babanızın Allah adına size yemin verdiğini ve daha önce de Yusuf hakkında kusurlu davrandığınızı bilmiyor muydunuz? Bu yüzden babam bana izin verinceye veya Allah benim lehime bir hüküm verinceye kadar bu topraktan asla ayrılmayacağım. O, hükmedenlerin en iyisidir."'),
(12, 81, 13, 245, 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ', 'irğīʿū ilā abīkum faqūlū yā abānā inna ibneke ṣaraqa wa mā šahidnā illā bimā ʿalimnā wa mā kunnā lilġaybi ḥāfiẓīn', 'Babalarınıza dönün ve şöyle deyin: ''Ey babamız! Şüphesiz oğlun hırsızlık yaptı. Biz ancak bildiğimize şahitlik ettik. Gaybı bilenler değiliz.'''),
(12, 82, 13, 245, 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا وَإِنَّا لَصَٰدِقُونَ', 'wa-sʾali l-qaryata llatī kunnā fīhā wa-l-ʿīra llatī ʾaqbalnā fīhā wa-ʾinnanā laṣādiqūna', 'Ve bulunduğumuz kasabayı ve içinde bulunduğumuz kervanı sor. Ve şüphesiz biz doğru söyleyenleriz.'),
(12, 83, 13, 245, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'qāla bal sawwalat lakum anfusukum amran faṣabrun jamīlun ʿasā ʾallāhu ʾan yaʾtiyanī bihim jamīʿan ʾinnahu huwa l-ʿalīmu l-ḥakīmu', 'Dedi ki: "Hayır! Nefisleriniz size bir işi güzel gösterdi. Artık (bana) güzel bir sabır (düşüyor). Umarım Allah, bana onların hepsini birden getirecektir. Şüphesiz O, bilendir, hikmet sahibidir."'),
(12, 84, 13, 245, 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ', 'wa tawallā ʿanhum wa qāla yā ʾasafā ʿalā Yūsufa wa-byaḍḍat ʿaynāhu mina l-ḥuzni fa-huwa kaẓīmun', 'Onlardan yüz çevirdi ve "Ah Yusuf''a ne oldu!" dedi. Gözleri üzüntüden beyazlaştı ve kederinden içine kapanmıştı.'),
(12, 85, 13, 245, 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ', 'qālū tāllāhi taftäʾu tadhkuru Yūsufa ḥattā takūna ḥaraḍan aw takūna mina l-hālikīn', 'Dediler ki: "Allah''a yemin olsun ki, Yusuf''u anıp duracaksın; ta ki helak olmaya yüz tutanlardan olasın ya da helak olanlardan olursun."'),
(12, 86, 13, 245, 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'qāla innamā ashku baththī waḥuznī ilā Allāh wa aʿlamu mina Allāhi mā lā taʿlamūn', 'Dedi ki: "Ben derdimi ve üzüntümü yalnız Allah''a arz ederim ve sizin bilmediğiniz şeyleri Allah''tan bilirim."'),
(12, 87, 13, 246, 'يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ', 'yā baniyya ʾidh-habū fataḥassesū min Yūsufa wa-ʾakhīhi wa-lā taʾyasū min rawḥi ʾllāhi ʾinnahu lā yaʾyasu min rawḥi ʾllāhi ʾillā l-qawmu l-kāfirūn', 'Ey yavrularım! Yusuf''u ve kardeşini ara(yın) ve Allah''ın rahmetinden ümidinizi kesmeyin. Çünkü kâfirler topluluğundan başkası Allah''ın rahmetinden ümidini kesmez.'),
(12, 88, 13, 246, 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', 'fe-lemmā dehalū ʿalayhi qālū yā-ʾayyuhā l-ʿazīzu messanā wa-ʾahlanā ḍ-ḍurru wa-jiʾnā bi-biḍāʿatin muzjah fa-ʾawfi lenā l-kayla wa-taṣaddaq ʿalaynā ʾinna llāha yajzī l-mutaṣaddiqīn', 'Onu(n) yanına girdiklerinde şöyle dediler: "Ey Aziz! Bize ve aile halkımıza darlık (kıtlık) dokundu ve biz az bir sermaye ile geldik. Bize tam ölçü ver ve bize tasaddukta bulun. Şüphesiz Allah, tasadduk edenleri mükâfatlandırır."'),
(12, 89, 13, 246, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ', 'qāla hal ʿalimtum mā faʿaltum bi-yūsufa wa-ʾaḫīhi ʾiḏ ʾantum ǧāhilūn', 'Dedi ki: "Siz, (o zaman) cahil iken Yusuf''a ve kardeşine ne yaptığınızı bildiniz mi?"'),
(12, 90, 13, 246, 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'Qālū ʾa-ʾinnaka la-ʾanta Yūsufu Qāla ʾanā Yūsufu wa-hādā ʾakhī qad manna ʾllāhu ʿalaynā ʾinnahu man yattaqi wa-yaṣbir fa-ʾinna ʾllāha lā yuḍīʿu ʾajra l-muḥsinīn', 'Dediler ki: "Sen gerçekten sen misin Yusuf?" Dedi ki: "Ben Yusuf''um, bu da kardeşim. Allah bize lütufta bulundu. Şüphesiz ki kim takva sahibi olur ve sabrederse, Allah iyilik edenlerin mükafatını zayi etmez."'),
(12, 91, 13, 246, 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 'qālū tāllāhi laqad ʾātharakā ʾllāhu ʿalaynā wa-ʾinna kunnā la-khāṭiʾīn', 'Dediler ki: Allah''a yemin ederiz ki, Allah seni bize üstün kılmıştır ve biz gerçekten hata edenlerdeniz.'),
(12, 92, 13, 246, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ يَغْفِرُ ٱللَّهُ لَكُمْ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'qāla lā tathrība ʿalaykumu l-yawma yaghfiru llāhu lakum wa-huwa arḥamu r-rāḥimīna', 'Allah''ın sizi bağışlaması umulur; O, merhametlilerin en merhametlisidir. (Yusuf dedi ki:) "Bugün size bir kınama yok. Allah sizi affetsin! O, merhametlilerin en merhametlisidir."'),
(12, 93, 13, 246, 'ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', 'idhhabū bi-qamīṣī hādhā fa-alqūhu ʿalā wajhi abī yaʾti baṣīran wa-ʾtūnī bi-ʾahlukum ʾajmaʿīn', 'Bu gömleğimi götürün de babamın yüzüne sürün; (gözleri) hemen görmeye başlar. Ve bütün ailenizi bana getirin.'),
(12, 94, 13, 246, 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ لَوْلَآ أَن تُفَنِّدُونِ', 'wa lammā faṣalat il-ʿīru qāla abūhum ʾinnī la-ʾajidu rīḥa Yūsufa lawlā ʾan tufannidūn', 'Kervan ayrıldığı zaman, babaları dedi ki: "Eğer bana akıl sırrını bozmuş demezseniz, mutlaka Yusuf''un kokusunu alıyorum."'),
(12, 95, 13, 246, 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ', 'qālū ta-llāhi ʾinnaka la-fī ḍalālika al-qadīmi', 'Dediler ki: "Allah’a yemin ederiz ki, sen şüphesiz eski (o) sapıklığındasın!"'),
(12, 96, 13, 247, 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 'felemmā en jāʾa l-bašīru ʾalqāhu ʿalā wajhihī fārtadda baṣīran qāla ʾalam ʾaqul lakum ʾinnī ʾaʿlamu mina ʾllāhi mā lā taʿlamūna', 'Bunun üzerine müjdeci gelince, (gömleği) yüzüne sürdü de hemen gözleri açılıp görmeye başladı. (Yakup) dedi ki: "Ben size Allah tarafından, sizin bilmediğiniz şeyleri biliyorum, dememiş miydim?"'),
(12, 97, 13, 247, 'قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', 'qālū yā ʾabānā ʾstaghfir lanā dhunūbanā ʾinnanā kunnā khāṭiʾīn', 'Dediler ki: "Ey babamız! Günahlarımız için mağfiret dile. Şüphesiz bizler hatalı idik."'),
(12, 98, 13, 247, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'qāla sawfa ʾastaġfiru lakum rabbī ʾinnahu huwa l-ġafūru ʾr-raḥīmu', 'Şimdi babaları şöyle dedi: "Rabbimden sizin için af dileyeceğim. Şüphesiz O, çok bağışlayandır, çok merhamet edendir."'),
(12, 99, 13, 247, 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', 'fe-lemmā dehalū ʿalā Yūsufa ʾāwā ʾilayhi ʾabawayhi we-qāla ud-hulū Miṣra ʾin shāʾa ʾAllāhu ʾāminīna', 'Babaları (Yusuf''un yanına) girdiklerinde, (Yusuf) annesiyle babasını (yanına) alıp barındırdı ve şöyle dedi: "İnşallah, (hepsi) Mısır''a güvenlik içinde girecektir."'),
(12, 100, 13, 247, 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'wa rafaʿa ʾabawayhi ʿalā l-ʿarši wa kharrū lahu sujjadan wa qāla yā ʾabati hādhā taʾwīlu ruʾyāya min qablu qad jaʿalahā rabbī ḥaqqan wa qad ʾaḥsana bī ʾidh ʾakhrajanī mina s-sjini wa jāʾa bikum mina l-badwi min baʿdi ʾan nazagha ʾsh-shayṭānu baynī wa bayna ʾikhwati ʾinna rabbī laṭīfun limā yashāʾu ʾinnahu huwa l-ʿalīmu l-ḥakīmu', 'Babasıyla annesini tahtın üzerine çıkardı. Hepsi onun için secdeye kapandılar. Ve şöyle dedi: "Ey babacığım! İşte bu, daha önce görmüş olduğum rüyanın yorumudur. Rabbim onu gerçekten doğru çıkardı. Bana çok iyilik etti; çünkü beni zindandan çıkardı ve şeytan benimle kardeşlerimin arasını bozduktan sonra sizi çölden (getirip) iyileştirdi. Şüphesiz Rabbim dilediği şeyde pek lütufkârdır. O, her şeyi bilen, hikmet sahibi olandır."'),
(12, 101, 13, 247, 'رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 'Rabbi qad ātaytanī mina l-mulki wa ʿallamtanī min taʾwīli l-ʾaḥādīth Fāṭira s-samāwāti wa l-ʾarḍ ʾAnta waliyyī fī d-dunyā wa l-ʾākhirah Tawaffanī musilman wa ʾalḥiqnī bi-ṣ-ṣāliḥīn', 'Rabbim! Bana mülkten (otoriteden) bir nasip verdin ve bana hadislerin (olayların ve rüyaların) te''vilinden (yorumundan) öğrettin. Gökleri ve yeri yaratan! Sen benim dünyada ve ahirette velimsin (dostum, koruyucumsun). Beni Müslüman olarak (teslimiyet içinde) öldür ve bana salihler zümresine (kat) ulaşmayı nasip et.'),
(12, 102, 13, 247, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 'dhālika min anbāʾi l-ghaybi nūḥīhi ilayka wa mā kunta ladayhim idh ajmaʿū ʾamrahum wa hum yamkurūn', 'İşte bunlar sana vahyettiğimiz gayb (görünmeyen) haberlerindendir. Oysa onlar, hileli planlar kurarlarken yanlarında değildin.'),
(12, 103, 13, 247, 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', 'wa mā aktharu n-nāsi wa law ḥaraṣta bi-muʾminīn', 'Sen ne kadar hırs göstersen de, insanların çoğu iman etmezler.'),
(12, 104, 13, 248, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'wa mā tasʾaluhum ʿalayhi min ʾajrin ʾin huwa ʾillā dhikrun lil-ʿālamīn', 'Onlardan buna karşılık bir ücret istemiyorsun. O (Kur''an) ise, âlemler için yalnızca bir öğüttür.'),
(12, 105, 13, 248, 'وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 'wa kaʾayyin min ʾāyatin fī s-samāwāti wa-l-ʾarḍi yamurruʿūna ʿalayhā wa-hum ʿanhā muʿriḍūn', 'Göklerde ve yerde nice ayetler vardır ki üzerlerinden geçerler de onlar onlardan yüz çevirirler.'),
(12, 106, 13, 248, 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', 'wa mā yuʾminu ʾaktharuhum bi-llāhi ʾillā wa hum mušrikūn', 'Onların çoğu, Allah''a inanmış olsalar bile, mutlaka şirk koşarlar.'),
(12, 107, 13, 248, 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'ʾafaʾaminū ʾan taʾtiyahum ḡāšiyatun min ʿaḏābi ʾllāhi ʾaw taʾtiyahumu s-sāʿatu baḡtatan wa hum lā yašʿurūn', 'Yoksa Allah''ın azabından kendilerini bürüyüverecek bir felaketin gelmesine veya hiç farkında olmadıkları bir sırada kıyametin kopuvermesine karşı güvenlik mi kazandılar?'),
(12, 108, 13, 248, 'قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 'qul hādhihi sabīlī adʿū ilā llāhi ʿalā baṣīratin anā wa man ittabaʿanī wa subḥāna llāhi wa mā anā mina l-mušrikīn', 'De ki: "Ben ve bana uyanlar, basiret üzere Allah''a davet ederiz. Allah''ı tesbih ederim. Ben müşriklerden değilim."'),
(12, 109, 13, 248, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ أَفَلَا تَعْقِلُونَ', 'wa mā arsalnā min qablika illā rijālan nūḥī ilayhim min ahlil-qurā afalam yasīrū fīl-arḍi fayanẓurū kayfa kāna ʿāqibatul-ladhīna min qablihim wa dārul-ʾākhirati khayrun lil-ladhīnat-taqaw afalā taʿqilūn', 'Senden önce de yalnızca, kendilerine vahyettiğimiz bir takım erkekleri, şehir halkından olanları göndermiştik. Yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Elbette Allah''a karşı gelmekten sakınanlar için ahiret yurdu daha hayırlıdır. Hâlâ akıl erdiremiyor musunuz?'),
(12, 110, 13, 248, 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 'ḥattā ʾiḏā ʾistayʾasa ʾr-rusulu wa ẓannū ʾannahum qad kuḏibū jāʾahum naṣrunā fa nuǧǧiya man našāʾu wa lā yuraddu baʾsunā ʿani l-qawmi l-muǧrimīn', 'Nihayet peygamberler ümitlerini kestikleri ve yalanlandıklarını sandıkları bir sırada, onlara yardımımız geldi. Ve dilediğimiz kimseyi kurtardık. Azabımız ise suçlu topluluktan asla geri çevrilmez.'),
(12, 111, 13, 248, 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَٰبِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'leḳad kāne fī ḳaṣaṣihim ʿibratun liʾulī l-ʾalbāb mā kāne ḥadīthan yuftarā walākin taṣdīqa alladhī bayna yadayhi watafṣīla kulli shayʾin wahudan waraḥmatan liqawmin yuʾminūn', 'Andolsun ki onların kıssalarında akıl sahipleri için ibret vardır. Bu (Kur''an), uydurulmuş bir söz değildir; ancak kendinden öncekileri doğrulayan, her şeyi açıklayan, inanan bir toplum için de bir hidayet ve rahmettir.'),
(13, 1, 13, 249, 'الٓمٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'Alif, Lâm, Mim, Ra tilke ʾāyātu l-kitābi wa-lladhī ʾunzilla ʾilayka min rabbika l-ḥaqqu wa-lākinna ʾakthara n-nāsi lā yuʾminūna', 'Elif, Lâm, Mim, Ra. Bunlar sana Rabbinden indirilen Kitab''ın âyetleridir. Ancak insanların çoğu inanmazlar.'),
(13, 2, 13, 249, 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْءَايَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', 'Allāhu alladhī rafaʿa s-samāwāti bighayri ʿamadin tarawnahā thumma stawa ʿalā l-ʿarshi wa-sakhkhara sh-shamsa wa-l-qamara kullun yajrī li-ajalin musammā yudabbiru l-amra yufaṣṣilu l-āyāti laʿallakum bi-liqāʾi rabbikum tūqinūna', 'Allah, gökleri direksiz olarak yükselten, sonra Arş''a istiva eden, güneşi ve ayı buyruğu altına alan, her biri belirli bir vakte kadar akıp giden odur. O, bütün işleri evirip çevirir, ayetleri ayrı ayrı açıklar ki, Rabbinize kavuşacağınıza iman edesiniz.'),
(13, 3, 13, 249, 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَٰرًا وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'wa huwa alladhī madda al-arḍa wa jaʿala fīhā rawāsīya wa anhāran wa min kulli ath-thamarāti jaʿala fīhā zawjayni ithnayni yughshī al-layla an-nahāra inna fī dhālika la-ʾāyātin li-qawmin yatafakkarūna', 'O, yeryüzünü uzatıp yayan, ona sabit dağlar ve nehirler yerleştiren, meyvelerin her birinden orada ikişer çift yaratan O''dur. Geceyi de gündüzü de (birbirine) büründürür. Elbette bunlarda, tefekkür eden bir kavim için mutlaka ibretler vardır.'),
(13, 4, 13, 249, 'وَفِى ٱلْأَرْضِ قِطَعٌ مُّتَجَٰوِرَٰتٌ وَجَنَّٰتٌ مِّنْ أَعْنَٰبٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَآءٍ وَٰحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِى ٱلْأُكُلِ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'wa-fī l-arḍi qiṭaʿun mutajāwirātun wa-jannātun min ʾaʿnābin wa-zarʿun wa-nakhīlun ṣinwānun wa-ghayru ṣinwānin yusqā bi-māʾin wāḥidin wa-nufaḍḍilu baʿḍahā ʿalā baʿḍin fī l-ʾukuli ʾinna fī dhālika la-ʾāyātin li-qawmin yaʿqilūna', 'Yeryüzünde birbirine komşu birbirine benzeyen (çeşitli) topaklar, üzüm bağları, ekinler ve biribirine benzeyen ve benzemeyen hurma ağaçları vardır. (Bunların) hepsi bir su ile sulanır. Ve biz, yiyecek bakımından bazısını bazısına üstün kılarız. Şüphesiz ki bunlarda akl eden bir kavim için elbette âyetler vardır.'),
(13, 5, 13, 249, 'وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ وَأُو۟لَٰٓئِكَ ٱلْأَغْلَٰلُ فِىٓ أَعْنَاقِهِمْ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'wa-ʾin taʿjab fa-ʿajabun qawluhum ʾa-ʾidhā kunnā turāban ʾa-ʾinnanā la-fī khalqin jadīd ʾulāʾika alladhīna kafarū bi-rabbihim wa-ʾulāʾika l-ʾaḡlālu fī ʾaʿnāqihim wa-ʾulāʾika ʾaṣḥābu n-nāri hum fīhā ḵālidūn', 'Eğer (bunlara) şaşacaksan, onların "Biz toprağa karışıp dağıldıktan sonra mı, gerçekten biz mi yeni bir yaratılışta olacağız?" sözleri şaşılacak şeydir. İşte onlar Rablerine küfredenlerdir. İşte onlar boyunlarında halkalar bulunanlardır. İşte onlar ateşin yoldaşlarıdır; orada ebedî kalacaklardır.'),
(13, 6, 13, 250, 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَٰتُ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', 'wa yastaʿjilūnaka bi-s-sayyiʾati qabla l-ḥasanati wa qad khalat min qablihimu l-mathulātu wa inna rabbaka la-dhu maghfiratin li-n-nāsi ʿalā ẓulmihim wa inna rabbaka la-shadīdu l-ʿiqābi', 'Sana iyilikten önce kötülüğü acele istiyorlar. Oysa onlardan önce nice ibret alınacak olaylar gelip geçmiştir. Şüphesiz Rabbin, insanların zulümlerine rağmen bağışlama sahibidir. Ve şüphesiz Rabbin azabı da şiddetlidir.'),
(13, 7, 13, 250, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦٓ إِنَّمَآ أَنتَ مُنذِرٌ وَلِكُلِّ قَوْمٍ هَادٍ', 'wa yaqūlu alladhīna kafarū lawlā unzila ʿalayhi āyatun min rabbihī innamā anta mundhirun wa likulli qawmin hād', 'İnkâr edenler: "Ona Rabbinden bir alâmet (mucize) indirilmeli değil miydi?" derler. Sen ancak bir uyarıcısın ve her kavim için bir yol gösterici vardır.'),
(13, 8, 13, 250, 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', 'Allāhu yaʿlamu mā taḥmilu kullu unthā wa mā tagīḍu l-arḥāmu wa mā tazdādu wa kullu shayʾin ʿindahu bimiqdārin', 'Allah, her dişinin ne (taşıdığını), rahimlerin neyi eksiltip neyi artırdığını bilir. Ve her şey O''nun katında bir ölçü iledir.'),
(13, 9, 13, 250, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', 'ʿālimu l-ghaybi wa-sh-shahādati l-kabīru l-mutaʿāli', 'O, gaybı da, şehadeti de bilen, en yüce, en yüce olan.'),
(13, 10, 13, 250, 'سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', 'sawāʾun minkum man ʾasarra l-qawla wa-man jahara bihi wa-man huwa mustakhfin bil-layli wa-sāribun bin-nahār', 'İçinizden sözü saklayan da, onu açığa vuran da, geceleyin gizlenen de, gündüzün (açıkça) yol alan da Allah katında eşittir.'),
(13, 11, 13, 250, 'لَهُۥ مُعَقِّبَٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 'lahū muʿaqqibātun min bayni yadayhi wa min khalfihī yaḥfaẓūnahū min amri ʾllāh ʾinna ʾllāha lā yughayyiru mā biqawmin ḥattā yughayyirū mā biʾanfusihim wa ʾiḏā ʾarāda ʾllāhu biqawmin sūʾan falā maradda lahū wa mā lahum min dūnihī min wāl', 'Onun önünde ve ardından gelen, Allah''ın emriyle onu koruyan takipçileri vardır. Şüphesiz Allah, bir kavmin durumunu, onlar kendilerindekini (durumlarını, potansiyellerini) değiştirmedikçe değiştirmez. Allah bir kavme bir kötülük dilediğinde, onu geri çevirecek kimse yoktur. Ve onlar için O''ndan başka bir dost da yoktur.'),
(13, 12, 13, 250, 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', 'huwa alladhī yurīkumul-barqa khawfan wa ṭamaʿan wa yunshiʾus-saḥābal-thiqāl', 'O, korku ve umut olarak size şimşeği gösteren, (ve) ağırlaşmış bulutları (yüklü bulutları) meydana getirendir.'),
(13, 13, 13, 250, 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', 'wa yusabbiḥu r-raʿdu bi ḥamdihi wa l-malāʾikatu min khifatihi wa yursilu ṣ-ṣawāʿiqa fa yuṣību bihā man yashāʾu wa hum yujādilūna fī llāhi wa huwa shadīdu l-miḥāli', 'Gök gürültüsü de O''na hamdederek tesbih eder. Melekler de O''nun korkusundan dolayı tesbih ederler. Allah, yıldırımları gönderir de onlarla dilediğini vurur. Onlar ise Allah hakkında tartışırlar. Halbuki O, azabı çetin olandır.'),
(13, 14, 13, 251, 'لَهُۥ دَعْوَةُ ٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ وَمَا دُعَآءُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'lahū daʿwatu l-ḥaqqi wa-lladhīna yadʿūna min dūnihi lā yastajībūna lahum bi-shayʾin illā ka-bāsiṭi kaffayhi ilā l-māʾi li-yablugha fāhu wa-mā huwa bi-bālighihī wa-mā duʿāʾu l-kāfirīna illā fī ḍalālin', 'Hak olan davet O''nundur. O''ndan başka taptıkları şeyler, onlara hiçbir şeyle icabet edemezler; ancak, avucunu suya uzatmış, suyun ağzına ulaşmasını bekleyen kimse gibidir. Oysa ona ulaşmayacaktır. Kafirlerin duası ise ancak boşunadır.'),
(13, 15, 13, 251, 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَٰلُهُم بِٱلْغُدُوِّ وَٱلْءَاصَالِ', 'wa lil-lāhi yasjudu man fī s-samāwāti wa l-arḍi ṭawʿan wa kurhan wa ẓilāluhum bi l-ġudūwwi wa l-ʾāṣāl', 'Göklerde ve yerde kim varsa, ister istemez, gölgeleri de sabah akşam Allah''a secde eder.'),
(13, 16, 13, 251, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًا وَلَا ضَرًّا قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَٰتُ وَٱلنُّورُ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّٰرُ', 'qul man rabbus-samāwāti wal-arḍi qulillāhu qul afattakhaḏtum min dūnihī awliyāʾa lā yamlikūna li-anfusihim nafʿan wa lā ḍarṛan qul hal yastawīl-aʿmā wal-baṣīru am hal tastawīẓ-ẓulumātu wan-nūru am jaʿalū lillāhi shurakāʾa ḵalaqū kaḵalqihi fa-tašābaha l-ḵalqu ʿalayhim qulillāhu ḵāliqu kulli šayʾin wa huwal-wāḥidul-qahhāru', 'De ki: "Göklerin ve yerin Rabbi kimdir?" De ki: "Allah''tır." De ki: "O''ndan başka veliler mi edindiniz? Onlar kendi kendilerine bile ne fayda ne de zarar verebilirler." De ki: "Kör ile gören bir olur mu? Ya da karanlıklarla aydınlık bir olur mu? Yoksa Allah''ın, O''nun yarattığı gibi yaratan ortakları mı var da bu yaratma onlara (ortaklarına) benzer göründü?" De ki: "Her şeyin yaratıcısı Allah''tır. O, Vahid''dir, Kahhâr''dır."'),
(13, 17, 13, 251, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًا رَّابِيًا وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَٰعٍ زَبَدٌ مِّثْلُهُۥ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَٰطِلَ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءً وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', 'anzala mina s-samāʾi māʾan fa-sālat awdiyatun bi-qadarihā fa-ḥtamala s-saylu zabadan rābiya wa-mimmā yūqidūna ʿalayhi fī n-nāri ʾibtiġāʾa ḥilyatin ʾaw matāʿin zabadun miṯluhū kaḏālika yaḍribu llāhu l-ḥaqqa wa-l-bāṭila fa-ʾammā z-zabadu fa-yaḏhabu jufāʾan wa-ʾammā mā yanfaʿu n-nāsa fa-yamkuṯu fī l-ʾarḍi kaḏālika yaḍribu llāhu l-ʾamṯāla', 'Allah gökten bir su indirdi de dereler kendi ölçülerine göre çağlayıp aktı. Selin üzerine çıkan köpük de tıpkı bunun gibi oldu. Süs eşyası veya geçimlik eşya edinmek amacıyla ateşte erittikleri madenlerin üzerinde de bunun gibi bir köpük oluşur. İşte Allah, hak ile batılı böyle misal verir. Köpüğe gelince; o, solarak gider. İnsanlara faydalı olan şeye gelince; o, yeryüzünde kalır. İşte Allah, misalleri böyle verir.'),
(13, 18, 13, 251, 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', 'lilladhīna stajābū lirabbihimu l-ḥusnā wa-lladhīna lam yastajībū lahū law anna lahum mā fī l-arḍi jamīʿan wa-mithlahū maʿahū la-ftadaw bihi ulāʾika lahum sūʾu l-ḥisābi wa-maʾwāhum jahanam wa-biʾsa l-mihādu', 'Rablerine icabet edenlere en güzel (karşılık) vardır. Etmeyenlere gelince, yeryüzünde ne varsa hepsi ve onunla birlikte bir misli daha kendilerinin olsa da, mutlaka onu (bu azaptan) kurtulmak için fidye verirlerdi. İşte onlar için kötü bir hesap vardır. Varacakları yer cehennemdir. Ne kötü bir barınaktır o!'),
(13, 19, 13, 252, 'أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'ʾafaman yaʿlamu ʾannamaa ʾunzilla ʾilayka min rabbika l-ḥaqqu kaman huwa ʾaʿmaa ʾinnamaa yatadhakkaru ʾuowlū l-ʾalbābi', 'Rabbinden sana indirilenin hak olduğunu bilen kimse, (gözleri) kör olan kimse gibi olur mu? Ancak akıl sahipleri öğüt alırlar.'),
(13, 20, 13, 252, 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَٰقَ', 'alladhīna yūfūna biʿahdi llāhi walā yanquḍūna l-mīthāqa', 'Onlar, Allah''a verdikleri sözü yerine getirenler ve anlaşmayı bozmayanlardır.'),
(13, 21, 13, 252, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', 'wa-lladhīna yaṣilūna mā amara llāhu bihi ʾan yūṣala wa-yakhshawna rabbahum wa-yakhāfūna sūʾa l-ḥisābi', 'Onlar, Allah''ın birleştirmesini emrettiği şeyi birleştirenler, Rablerinden korkanlar ve hesabın kötü olmasından çekinenlerdir.'),
(13, 22, 13, 252, 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', 'wa-lladhīna ṣabarū ibtighāʾa wajhi rabbihim wa-aqāmū ṣ-ṣalāta wa-anfaqū mimmā razaqnāhum sirran wa-ʿalāniyatan wa-yadrāʾūna bi-l-ḥasanati s-sayyiʾata ʾulāʾika lahum ʿuqbā d-dāri', 'Onlar, Rablerinin rızasını arayarak sabreden, namazı dosdoğru kılan, kendilerine verdiğimiz rızıktan gizlice ve açıktan harcayan ve kötülüğü iyilikle ortadan kaldıranlardır. İşte bunlar için dünya yurdunun (güzel) akıbeti vardır.'),
(13, 23, 13, 252, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ وَٱلْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ', 'jannātu ʿadnin yadkhulūnahā wa-man ṣalaḥa min ʾābāʾihim wa-ʾazwājihim wa-dhurriyyātihim wa-l-malāʾikatu yadkhulūna ʿalayhim min kulli bābin', 'Adn cennetleri; onlara ve onların babalarından, eşlerinden ve zürriyetlerinden salih olanlara (oraları) girerler. Ve melekler de her kapıdan onların yanlarına girerler.'),
(13, 24, 13, 252, 'سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى ٱلدَّارِ', 'salāmun ʿalaykum bimā ṣabartum faniʿma ʿuqbā d-dār', 'Sabretmenizden ötürü size selam olsun! (Allah''ın) bu (mutlu) ahiret yurdu ne güzeldir!'),
(13, 25, 13, 252, 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 'wa-lladhīna yanquḍūna ʿahda llāhi min baʿdi mīthāqihi wa-yaqṭaʿūna mā ʾamara llāhu bihi ʾan yūṣala wa-yufsidūna fī l-ʾarḍi ʾulāʾika lahumu l-laʿnatu wa-lahum sūʾu d-dāri', 'Allah''ın, akidleştikten sonra ahdini bozanlar, Allah''ın birleştirmesini emrettiği şeyi kesip ayıranlar ve yeryüzünde fesat çıkaranlar var ya; işte onlara lanet vardır ve onlara o (kötü) ahiret yurdu vardır.'),
(13, 26, 13, 252, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْءَاخِرَةِ إِلَّا مَتَٰعٌ', 'Allāhu yabsūṭu r-rizqa liman yashāʾu wa-yaqdiru Wa-fariḥū bil-ḥayāti d-dunyā Wa-mā l-ḥayātu d-dunyā fī l-ʾākhirati ʾillā matāʿun', 'Allah rızkı dilediğine bollaştırır ve (dilediğine) kısar. Onlar dünya hayatıyla sevinip dururlar. Oysa dünya hayatı, ahiretin yanında (geçici) bir istifadeden başka bir şey değildir.'),
(13, 27, 13, 252, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', 'wa yaqūlu alladhīna kafarū lawlā unzila ʿalayhi āyatun min rabbihī qul inna Allāha yuḍillu man yashāʾu wa yahdī ilayhi man anāba', 'İnkâr edenler: "Ona Rabbinden bir mucize indirilmeli değil miydi?" derler. De ki: "Şüphesiz Allah dilediğini saptırır ve O''na yöneleni doğru yola iletir."'),
(13, 28, 13, 252, 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', 'alladhīna ʾāmanū wataṭmaʾinnu qulūbuhum bidhʾikri llāhi ʾalā bidhʾikri llāhi taṭmaʾinnu l-qulūbu', 'Onlar, inanıp kalpleri Allah''ı anmakla huzura kavuşanlardır. Evet, kalpler ancak Allah''ı anmakla huzura kavuşur.'),
(13, 29, 13, 253, 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍ', 'ellezîne âmenû ve ''amilu-ṣṣâliḥâti ṭûbâ lehum ve ḥusnu meʾâb', 'İman edip salih ameller işleyenlere ne mutlu! Varılacak güzel yer de onlarındır.'),
(13, 30, 13, 253, 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِىٓ أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَٰنِ قُلْ هُوَ رَبِّى لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', 'kadhalika arsalnāka fī ummatin qad khalat min qablihā umamun litutluwā ʿalayhimu alladhī awḥaynā ilayka wa hum yakfurūna birraḥmāni qul huwa rabbī lā ilāha illā huwa ʿalayhi tawakkaltu wa ilayhi matābi', 'Böylece sana vahyettiğimizi sana okumaları için seni de, kendilerinden önce nice ümmetler gelip geçmiş bir ümmetin içine gönderdik. Onlar ise Rahman''a nankörlük ediyorlar. De ki: ''O benim Rabbimdir. O''ndan başka ilah yoktur. O''na tevekkül ettim ve O''na yöneldim.'''),
(13, 31, 13, 253, 'وَلَوْ أَنَّ قُرْءَانًا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًا وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'wa-law anna qurʾānan suyyirat bihi l-jibālu aw quṭṭiʿat bihi l-arḍu aw kullima bihi l-mawtā bal lillāhi l-amru jamīʿan ʾafalam yaʾyasi lladhīna ʾāmanū ʾan law yashāʾu ʾllāhu lahadā n-nāsa jamīʿan wa-lā yazālu lladhīna kafarū tuṣībuhum bimā ṣanaʿū qāriʿatun aw taḥullu qarīban min dārihim ḥattā yaʾtiya waʿdu lillāhi ʾinna llāha lā yukhlifu l-mīʿāda', 'Eğer kendisiyle dağların yürütüldüğü, yerin parça parça edildiği veya ölülerin de kendisiyle konuşabildiği bir Kur''an olsaydı (yine de inanmazlardı). Hayır, bütün işler Allah''ındır. İman edenler, (artık) Allah dileseydi bütün insanları hidayete erdireceğini bilmediler mi? İnkar edenlere ise, yaptıklarından dolayı başlarına gelen bir felaket veya yurtlarına yakın bir yere inecek bir bela, hâlâ devamlı olarak gelip çatacaktır. Allah''ın vaadi mutlaka gerçekleşir. Şüphesiz Allah vaadinden dönmez.'),
(13, 32, 13, 253, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'Ve lekadistuhziʾe bi rusulin min kablike Fe emleytu lillezîne keferû Summe ehaztuhum Fe keyfe kâne ʿikâbi', 'Andolsun ki, senden önceki nice peygamberlerle de alay edildi de ben inkâr edenlere bir süre mühlet verdim, sonra onları yakaladım. Peki, azabım nasıl oldu!'),
(13, 33, 13, 253, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَٰهِرٍ مِّنَ ٱلْقَوْلِ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'ʾafaman huwa qāʾimun ʿalā kulli nafsin bimā kasabat wa-jaʿalū lillāhi shurakāʾa qul sammūhum ʾam tunabbiʾūnahū bimā lā yaʿlamu fī l-ʾarḍi ʾam biẓāhirin mina l-qawli bal zuyyina lilladhīna kafarū makruhum wa-ṣuddū ʿani s-sabīli wa-man yuḍlili l-lāhu famā lahū min hādin', 'Her nefsin kazandığı şey üzerinde duran kimse (onların ilahları gibi midir)? Onlar Allah''a ortaklar koştular. De ki: "Onları (ortakları) bana tanıtın! Yoksa siz, yeryüzünde Allah''ın bilmediği bir şeyi mi O''na haber veriyorsunuz? Yoksa (bu söyledikleriniz) boş bir sözden mi ibaret? Hayır, kâfirlere hileleri süslü gösterildi ve onlar yoldan alıkonuldular. Allah''ın şaşırtıp saptırdığı kimse için bir yol gösterici yoktur."'),
(13, 34, 13, 253, 'لَّهُمْ عَذَابٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَقُّ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', 'lahum ʿaḏābun fī l-ḥayāti d-dunyā wa-laʿaḏābu l-ʾāḫirati ʾašaqqu wa-mā lahum mina llāhi min wāqin', 'Onlar için dünya hayatında bir azap vardır. Elbette ahiret azabı daha zorludur ve onları Allah''tan koruyacak kimse de yoktur.'),
(13, 35, 13, 254, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ أُكُلُهَا دَآئِمٌ وَظِلُّهَا تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ وَّعُقْبَى ٱلْكَٰفِرِينَ ٱلنَّارُ', 'mathalu l-jannati llatī wuʿida l-muttaqūna tajrī min taḥtihā l-anhāru ukuluhā dāʾimun waẓilluhā tilka ʿuqbā lladhīna ttaqaw wa ʿuqbā l-kāfirīna n-nāru', 'Muttekilerin (Allah''a karşı gelmekten sakınanların) va''dolunduğu cennetin durumu şudur: Altından ırmaklar akar, yemişleri ve gölgeleri süreklidir. Bu, Allah''a karşı gelmekten sakınanların akıbetidir. Küfre sapanların akıbeti ise ateştir.'),
(13, 36, 13, 254, 'وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', 'wa-lladhīna ātaynāhumu l-kitāba yafraḥūna bimā unzila ilayka wa-mina l-aḥzābi man yunkiru baʿḍahu qul innamā umirtu an aʿbuda llāha wa-lā ushrika bihi ilayhi adʿū wa-ilayhi maʾāb', 'Kendilerine kitap verdiğimiz kimseler, sana indirilen (Kur''an) ile sevinirler. Ama gruplardan (dini gruplardan) kimisi onun (Kur''an''ın) bir kısmını inkâr eder. De ki: "Ben sadece Allah''a kulluk etmek ve O''na hiçbir şeyi ortak koşmamakla emrolundum. Ben yalnız O''na çağırırım ve dönüşüm de yalnız O''nadır."'),
(13, 37, 13, 254, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْمًا عَرَبِيًّا وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَمَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا وَاقٍ', 'wa kadhalika anzalnahu hukman ''arabiyyan wa la''ini ittaba''ta ahwaa''ahum ba''da ma ja''aka minal ''ilmi ma laka minal laahi min waliyyin wa la waqin', 'İşte böylece onu Arapça bir hüküm olarak indirdik. Eğer sana gelen bu ilimden sonra onların heveslerine uyacak olursan, (bil ki) senin için Allah''tan ne bir dost ne de bir koruyucu vardır.'),
(13, 38, 13, 254, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًا وَذُرِّيَّةً وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ لِكُلِّ أَجَلٍ كِتَابٌ', 'Ve lekad erselnâ rusulen min kablike ve ce''alnâ lehum ezvâcen ve zurriyyeten ve mâ kâne li resûlin en ye''tiye bi âyetin illâ bi iznillâhi li kulli ecelin kitâbun', 'Andolsun ki senden önce de resuller gönderdik. Onlara eşler ve zürriyetler verdik. Hiçbir resul, Allah''ın izni olmaksızın bir ayet (mucize) getiremez. Her ecel için bir yazı (hüküm) vardır.'),
(13, 39, 13, 254, 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ وَعِندَهُۥٓ أُمُّ ٱلْكِتَٰبِ', 'yamḥū llāhu mā yashāʾu wayuthbitu wa ʿindahu ʾummu l-kitābi', 'Allah dilediğini siler, dilediğini de sabit kılar. Ana kitap O''nun katındadır.'),
(13, 40, 13, 254, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَعَلَيْنَا ٱلْحِسَابُ', 'wa-in mā nuriyannaka baʿḍa lladhī naʿiduhum aw natawaffayannaka fa-innamā ʿalayka l-balāghu wa-ʿalaynā l-ḥisābu', 'Onlara vaadettiğimizin bir kısmını sana göstersek de, yahut seni vefat ettirsek de, onlara düşen sadece tebliğdir. Hesabı görmek de bize aittir.'),
(13, 41, 13, 254, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ وَهُوَ سَرِيعُ ٱلْحِسَابِ', 'ʾawal-lam yaraw ʾannā naʾtī l-ʾarḍa nanquṣuhā min ʾaṭrāfihā wa-llāhu yaḥkumu lā muʿaqqiba li-ḥukmihī wa-huwa sarīʿu l-ḥisāb', 'Onlar, yeryüzüne gelip onu etrafından eksilttiğimizi görmüyorlar mı? Hükmünde kimse engel olamaz. O, hesabı çabuk görendir.'),
(13, 42, 13, 254, 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًا يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ وَسَيَعْلَمُ ٱلْكُفَّٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', 'waqad makara alladhīna min qablihim falillāhi l-makru jamīʿan yaʿlamu mā taksibu kullu nafsin wasayaʿlamu l-kuffāru liman ʿuqbā d-dāri', 'Onlardan öncekiler de hileli düzenler kurmuşlardı. Ama bütün hileler, Allah''a aittir. O, her nefsin ne kazandığını bilir. O kâfirler, ahiret yurdunun kimin olacağını yakında bileceklerdir.'),
(13, 43, 13, 255, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًا قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ', 'wa yaqūlu alladhīna kafarū lasta mursalan qul kafā bil-lāhi shahīdan baynī wa baynakum wa man ʿindahu ʿilmu l-kitābi', 'İnkâr edenler: "Sen peygamber değilsin" derler. De ki: "Benimle sizin aranızda şahit olarak Allah yeter. Bir de yanında Kitap bilgisi olan (melek veya insan) yeter."'),
(14, 1, 13, 255, 'الٓر كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'Alif, Lâm, Ra kitābun anzalnāhu ilayka litukhrija an-nāsa mina ẓ-ẓulumāti ilá n-nūr bi-iẓni rabbihim ilá ṣirāṭi l-ʿazīzi l-ḥamīd', 'Elif, Lâm, Ra. (Ey Muhammed!) Bu sana indirdiğimiz bir kitaptır ki, insanları Rablerinin izniyle karanlıklardan aydınlığa, O’nun yüce ve övgüye layık olan yoluna çıkarman için (sana vahyolundu).'),
(14, 2, 13, 255, 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَوَيْلٌ لِّلْكَٰفِرِينَ مِنْ عَذَابٍ شَدِيدٍ', 'Allāhi-l-lezī lehu mā fi-s-semāwāti ve mā fi-l-ʾarḍi Ve veylun lil-kāfirīne min ʿazābin şedīdin', 'Göklerde ve yerde ne varsa hepsi O Allah''ındır. Kâfirler için ise (hem dünyada hem de ahirette) çetin bir azaptan dolayı vay haline!'),
(14, 3, 13, 255, 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْءَاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۭ بَعِيدٍ', 'alladhīna yastaḥibbūna al-ḥayāta ad-dunyā ʿalā al-ʾākhirah wa yaṣuddūna ʿan sabīli Allāh wa yabghūnahā ʿiwajan ʾulāʾika fī ḍalālin baʿīd', 'Onlar, dünya hayatını ahirete tercih edenler, Allah''ın yolundan alıkoyanlar ve onu eğri (kusurlu) göstermek isteyenlerdir. İşte bunlar, derin bir sapıklık içindedirler.'),
(14, 4, 13, 255, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'wa mā arsalnā min rasūlin illā bilisāni qawmihī liyubayyina lahum fayuḍillu allāhu man yashāʾu wa yahdī man yashāʾu wa huwa l-ʿazīzu l-ḥakīmu', 'Biz gönderdiğimiz her peygamberi, ancak kendi kavminin dilini konuşarak gönderdik ki, onlara (gerçekleri) açıkça anlatabilsin. Allah dilediğini saptırır, dilediğini de doğru yola iletir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir.'),
(14, 5, 13, 255, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'Ve lekad erselnâ Mûsâ bi-âyâtinâ en ahric kavmeke minez-zulümâti ilen-nûr ve zekkirhum bi-eyyâmillâh İnne fî zâlike leâyâtin likulli sabbârin şekûr', 'Andolsun ki Musa''yı ayetlerimizle gönderdik (ve dedik ki): "Kavmini karanlıklardan nura çıkar ve onlara Allah''ın günlerini hatırlat." Şüphesiz bunda çok sabreden, çok şükreden herkes için nice ayetler vardır.'),
(14, 6, 13, 256, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'wa-ʾidh qāla mūsā li-qawmihi udh-kurū niʿmata ʾllāhi ʿalaykum ʾidh ʾanjākum min ʾāli firʿawna yasūmūnakum sūʾa ʾl-ʿadhābi wa-yudhahbiḥūna ʾabnāʾakum wa-yastaḥyūna nisāʾakum wa-fī dhālikum balāʾun min rabbikum ʿaẓīmun', 'Hani Mûsâ, kavmine şöyle demişti: ''Allah''ın size olan nimetini hatırlayın; hani O sizi Firavun ailesinden kurtarmıştı. Onlar size azâbın en kötüsünü çektiriyor, erkek çocuklarınızı boğazlıyor, kadınlarınızı (kızlarınızı) sağ bırakıyorlardı. İşte bunlarda Rabbinizden büyük bir imtihan vardı.'''),
(14, 7, 13, 256, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ', 'wa-ʾidh taʾaḏḏana rabbukum la-ʾin šakartum la-ʾazīdannakum wa-la-ʾin káfartum ʾinna ʿaḏābī la-šadīd', 'Ve Rabbiniz şöyle bildirmişti: ''Andolsun, eğer şükrederseniz, elbette size nimetlerimi artırırım. Ve eğer nankörlük ederseniz, şüphesiz azabım çok şiddetlidir.'''),
(14, 8, 13, 256, 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', 'wa qāla mūsā in takfurū antum wa man fī l-arḍi jamīʿan fa-inna llāha la-ghanīyyun ḥamīd', 'Musa dedi ki: Siz ve yeryüzündekilerin hepsi küfretseniz, şüphesiz Allah zengindir, her türlü övgüye layıktır.'),
(14, 9, 13, 256, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍ', 'ʾalam yaʾtikum nabaʾu ḷḷadhīna min qablikum qawmi nūḥin wa ʿādin wa thamūda wa ḷḷadhīna min baʿdihim lā yaʿlamuhum ʾillā ḷḷāhu jāʾat-hum rusuluhum bil-bayyināti faraddū ʾaidiyahum fī ʾafwāhihim wa qālū ʾinnā kafarnā bimā ʾursiltum bihi wa ʾinnā la fī shakkim mimmā tadʿūnanā ʾilayhi mūrībin', 'Sizden önceki Nuh kavminin, Âd ve Semûd''un ve onlardan sonrakilerin haberi size gelmedi mi? Onları Allah''tan başkası bilmez. Peygamberleri onlara apaçık delillerle gelmişti. Onlar ise (elleriyle) ağızlarını kapayarak: "Biz size gönderilenleri inkâr ettik" dediler ve sizi çağırdığınız şeyden dolayı derin bir şüphe içindeyiz.'),
(14, 10, 13, 256, 'قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَٰنٍ مُّبِينٍ', 'qālat rusuluhum ʾafī llāhi shakkun fāṭiri s-samāwāti wa-l-ʾarḍi yadʿūkum liyaġfira lakum min dhunūbikum wa-yuʾaḫḫirakum ʾilā ʾajalin musammā qālū ʾin ʾantum ʾillā basharun miṯlunā turīdūna ʾan taṣuddūnā ʿammā kāna yaʿbudu ʾābāʾunā faʾtūnā bi-sulṭānin mubīnin', 'Resulleri onlara şöyle dedi: "Gökleri ve yeri yaratan Allah hakkında bir şüphe mi var? O, günahlarınızdan bir kısmını bağışlamak ve sizi belirli bir vakte kadar ertelemek için sizi (O''na) davet ediyor." Dediler ki: "Siz de bizim gibi insandan başka kimse değilsiniz. Bizi, atalarımızın taptığı şeylerden alıkoymak istiyorsunuz. Öyleyse bize apaçık bir delil getirin!"'),
(14, 11, 13, 257, 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌ مِّثْلُكُمْ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'qālat lahum rusuluhum in naḥnu illā basharun mithlukum walākinna Allāha yamunnu ʿalā man yashāʾu min ʿibādihī wamā kāna lanā an naʾtiyakum bisulṭānin illā bi-idhn Allāh wa ʿalā Allāhi falyatawakkali l-muʾminūn', 'Resulleri onlara şöyle dedi: "Biz de sizin gibi sadece birer beşeriz. Ancak Allah, kullarından dilediğine lütufta bulunur. Allah''ın izni olmadıkça size bir delil getirmemiz mümkün değildir. Artık müminler yalnız Allah''a güvenip dayansınlar."'),
(14, 12, 13, 257, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 'wa mā lanā allā natawakkala ʿalā Llāhi wa qad hadānā subulanā wa la-naṣbiranna ʿalā mā ʾādhaytumūnā wa ʿalā Llāhi fa-l-yatawakkali l-mutawakkilūna', 'Bize yollarımızı göstermişken Allah''a güvenmemek bize mi düşer? Bize yaptığınız eziyetlere elbette katlanacağız. Artık bütün güvenenler Allah''a güvenmelidir.'),
(14, 13, 13, 257, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّٰلِمِينَ', 'waqāla alladhīna kafarū lirusulihim lanukhrijannakum min arḍinā aw lataʿūdunnah fī miltinā faʾawḥā ʾilayhim rabbuhum lanuhlikanna ẓẓālimīn', 'İnkâr edenler, peygamberlerine şöyle dediler: "Andolsun ki, ya sizi ya ülkemizden çıkarırız ya da mutlaka bizim dinimize dönersiniz." Bunun üzerine Rableri onlara şöyle vahyetti: "Biz mutlaka zalimleri helâk edeceğiz."'),
(14, 14, 13, 257, 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', 'wa lanuskinannakumul-arḍa mim baʿdihim ḏālika liman khāfa maqāmī wa khāfa waʿīd', 'Onlardan sonra sizi o (yeryüzüne) elbette yerleştireceğiz. Bu, makamımdan korkan ve (azabımla) tehdidimden çekinen kimse içindir.'),
(14, 15, 13, 257, 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍ', 'wa-stafataḥū wa-khāba kullu jabbārin ʿanīd', 'Onlar (peygamberler) zafer istediler ve her inatçı zorba hüsrana uğradı.'),
(14, 16, 13, 257, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍ صَدِيدٍ', 'min warāʾihi jahannam wa yusqā min māʾin ṣadīd', 'Onun ardından cehennem vardır ve irinli su içirilir.'),
(14, 17, 13, 257, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌ', 'yatajarra''uhu wa la yakadu yusighuhu wa ya''tihi al-mawtu min kulli makanin wa ma huwa bi-mayyitin wa min wara''ihi ''adhabun ghalizhun', 'Onu zorla içer, yutkunur da bir türlü yutamaz. Her yandan ölüm ona gelir; ama ölemez. Ve arkasından da ağır bir azap vardır.'),
(14, 18, 13, 257, 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ أَعْمَٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', 'mathalu allatheena kafaroo birabbihim a''maluhum karamadin ishtaddat bihi alreehu fee yawmin ''aasifin la yaqdiroona mimma kasaboo ''ala shay''in thalika huwa aldalalu al-ba''eed', 'Rableri ile küfredenlerin durumu şudur: Onların amelleri, fırtınalı bir günde şiddetle esen rüzgarın savurduğu kül gibidir. Onlar kazandıklarından hiçbir şeye güç yetiremezler. İşte bu, uzak bir sapıklıktır.'),
(14, 19, 13, 258, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'ʾalam tara ʾanna ʾallāha ḵalaqa s-samāwāti wa-l-ʾarḍa bi-l-ḥaqqi ʾin yašaʾ yuḏhibkum wa yaʾti bi-ḵalqin jadīdin', 'Görmedin mi ki Allah, gökleri ve yeri hak ile yarattı? Dilerse sizi yok eder ve yerinize yeni bir topluluk getirir.'),
(14, 20, 13, 258, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'wa mā dhālika ʿalā Llāhi bi-ʿazīzin', 'Oysa bu, Allah''a zor değildir.'),
(14, 21, 13, 258, 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ', 'wa barazū lillāhi jamīʿan fa qāla ḍ-ḍuʿafāʾu lilladhīna stakbarū ʾinnā kunnā lakum tabaʿan fa hal ʾantum mughnūna ʿannā min ʿadhābi llāhi min shaiʾin qālū law hadānā llāhu lahadaynākum sawāʾun ʿalaynā ʾajaziʿnā ʾam ṣabarnā mā lanā min maḥīṣin', 'Hep birlikte Allah''ın huzuruna çıkarlar. Zayıf olanlar, büyüklük taslayanlara derler ki: "Şüphesiz biz size tabi idik. Şimdi Allah''ın azabından herhangi bir şeyi bizden savabilecek misiniz?" (Büyüklük taslayanlar) derler ki: "Eğer Allah bize hidayet etmiş olsaydı, biz de sizi doğru yola iletirdik. Şimdi bizim için feryat etmemiz de sabretmemiz de birdir. Artık bizim için kurtuluş yoktur."'),
(14, 22, 13, 258, 'وَقَالَ ٱلشَّيْطَٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ إِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', 'waqāla sh-shayṭānu lammā quḍiya l-amru ʾinna Allāha waʿadakum waʿda l-ḥaqqi wawaʿadtukum fa-ʾakhlaftukum wamā kāna lī ʿalaykum min sulṭānin ʾillā ʾan daʿawtukum fa-stajabtum lī falā talūmūnī walūmū ʾanfusakum mā ʾanā bi-muṣrikikum wamā ʾantum bi-muṣrikhīyya ʾinnī kafartu bimā ʾashraktumūni min qablu ʾinna ẓ-ẓālimīna lahum ʿadhābun ʾalīmun', 'Şeytan, iş olup bittikten sonra şöyle dedi: "Şüphesiz Allah size gerçek olanı vaat etti. Ben de size vaat ettim ama size yalan geldim. Zaten benim üzerinizde bir gücüm yoktu. Sadece sizi çağırdım, siz de bana uydunuz. O halde beni kınamayın, kendi kendinizi kınayın. Ben sizin yardımınıza yetişemem, siz de benim yardımımı alamayacaksınız. Nitekim ben daha önce sizin beni Allah''a ortak koşmanızı da tanımamıştım." Şüphesiz zalimler için elem dolu bir azap vardır.'),
(14, 23, 13, 258, 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ', 'wa-udkhila alladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti jannātin tajrī min taḥtihā l-ʾanhāru khālidīna fīhā bi-ʾidhni rabbihim taḥiyyatuhum fīhā salāmun', 'İman edip salih amel işleyenler ise, Rablerinin izniyle, içinde ebedi kalacakları, altlarından ırmaklar akan cennetlere konulmuşlardır. Oradaki esenlik dilekleri "Selâm"dır.'),
(14, 24, 13, 258, 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِى ٱلسَّمَآءِ', 'ʾalam tara kayfa ḍaraba ʾallāhu maṯalan kalimatan ṭayyibatan kašajaratin ṭayyibatin ʾaṣluhā ṯābitatun wa-farʿuhā fī ʾs-samāʾi', 'Allah''ın, güzel bir sözü nasıl misal verdiğini görmedin mi? (O söz) kökü yer(de) sabit, dalları gökte olan güzel bir ağaç gibidir.'),
(14, 25, 13, 259, 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'tuʾtī ʾukulahā kulla ḥīnin bi-ʾiḏni rabbihā wa-yaḍribu ʾllāhu ʾl-ʾamṯāla li-n-nāsi laʿallahum yataḏakkarūn', 'Her zaman meyvesini, Rabbi''nin izniyle verir. Allah, insanların ibret alması için misaller getirir.'),
(14, 26, 13, 259, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍ', 'wa mathalu kalimatin khabithatin kashajaratin khabithatin ijtuththat min fawqi al-ardi ma laha min qararin', 'Kötü bir sözün misali de, yerden koparılmış, kökü olmayan kötü bir ağaç gibidir.'),
(14, 27, 13, 259, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', 'yuthabbitu llāhu llaḏīna ʾāmanū bil-qawli ṯ-ṯābiti fil-ḥayāti d-dunyā wa-fī l-ʾākhirati wa-yuḍillu llāhu ẓ-ẓālimīna wa-yafʿalu llāhu mā yashāʾu', 'Allah, iman edenleri dünya hayatında da ahirette de o sabit sözle (diniyle) sâbit tutar. Ve Allah zalimleri saptırır. Allah dilediğini yapar.'),
(14, 28, 13, 259, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', 'ʾelem tere ʾilā l-ladhīne beddelū niʿmete llāhi kufran wa-ʾaḥellū qawmehum dāra l-bawāri', 'Allah''ın nimetini küfre değiştirenleri ve kavimlerini helak yurduna indirenleri görmedin mi?'),
(14, 29, 13, 259, 'جَهَنَّمَ يَصْلَوْنَهَا وَبِئْسَ ٱلْقَرَارُ', 'jahannama yaṣlawnahā wa biʾsa l-qarāru', 'Cehennem''e girerler; ne kötü bir duraktır o!'),
(14, 30, 13, 259, 'وَجَعَلُوا۟ لِلَّهِ أَندَادًا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', 'wa jaʿalū lillāhi andādan liyudillū ʿan sabīlihī qul tamattaʿū fa-inna maṣīrakum ilā n-nār', 'Ve Allah''a, O''nun yolundan saptırmak için eşler/ortaklar kıldılar. De ki: ''Eğlenip yaşayın! Şüphesiz varacağınız yer ateştir.'''),
(14, 31, 13, 259, 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَٰلٌ', 'qul liʿibādiya alladhīna āmānū yuqīmū ṣ-ṣalāta wayunfiqū mimmā razaqnāhum sirran waʿalāniyatan min qabli an yaʾtiya yawmun lā bayʿun fīhi walā khilālun', 'İman eden kullarıma söyle: Namazı dosdoğru kılsınlar ve kendilerine verdiğimiz rızıktan gizli olarak da, açıkça da harcasınlar. Alış-verişin ve dostluğun olmayacağı bir gün gelmeden önce (bunu yapsınlar).'),
(14, 32, 13, 259, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَسَخَّرَ لَكُمُ ٱلْأَنْهَٰرَ', 'Allahu-llezi haleka-s-semavati ve-l-arda Ve enzele mine-s-semai ma''an Fe-ahrece bihi mine-s-seme-rati rizkan lekum Ve sehhara lekumu-l-fulke li-tecriye fi-l-bahri bi-emrihi Ve sehhara lekumu-l-enhara', 'Allah, gökleri ve yeri yaratan, gökten bir su indirip onunla size rızık olarak türlü meyveler çıkaran, emriyle denizde seyreden gemileri size boyun eğdiren ve nehirleri de sizin için akıtan Allah''tır.'),
(14, 33, 13, 259, 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 'wa sakhkhara lakumu sh-shamsa wa-l-qamara dāʾibayni wa sakhkhara lakumu l-layla wa-n-nahāra', 'Ve güneşi ve ayı, ikisini de (yörüngelerinde) sürekli hareket halinde olarak sizin için boyun eğdirdi ve gece ile gündüzü de sizin için boyun eğdirdi.'),
(14, 34, 13, 260, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌ كَفَّارٌ', 'wa ʾātākum min kulli mā saʾaltumūhu wa ʾin taʿuddū niʿmata ʾallāhi lā tuḥṣūhā ʾinna l-ʾinsāna laẓalūmun kaffārun', 'Ve O, istediğiniz her şeyden size verdi. Eğer Allah''ın nimetlerini saymaya kalksanız, onları sayamazsınız. Gerçekten insan çok zalim, çok nankördür.'),
(14, 35, 13, 260, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَٰذَا ٱلْبَلَدَ ءَامِنًا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', 'wa-ʾidh qāla ʾibrāhīmu rabb-i-jʿal hādhā al-balada ʾāminan wa-j-nubnī wa-banīya ʾan naʿbuda al-ʾaṣnāma', 'Hani İbrahim şöyle demişti: "Rabbim! Bu beldeyi (Mekke''yi) güvenli kıl ve beni, oğullarımı putlara tapmaktan koru."'),
(14, 36, 13, 260, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌ رَّحِيمٌ', 'Rabbī innehunna aḍlalnya kaṯīram mina n-nās Faman tabaʿanī fa-innahu minnī Wa man ʿaṣānī fa-innaka ġafūrur raḥīm', 'Rabbim! Onlar (putlar) insanların çoğunu saptırdılar. Bana uyan benden, bana isyan eden ise şüphesiz sen Gafur''sun, Rahim''sin.'),
(14, 37, 13, 260, 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةً مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', 'Rabbanā innī askantu min dhurriyyatī biwādin ghayri dhī zarʿin ʿinda baytika al-muḥarrami Rabbanā liyuqīmū aṣ-ṣalāta Fajʿal afʾidatan min an-nāsi tahwī ilayhim Warzuqhum min ath-thamarāti laʿallahum yashkurūn', 'Ey Rabbimiz! Ben, zürriyetimden bir kısmını, senin Beyt-i Harem''inin yanında, ziraat yapraksız bir vadiye yerleştirdim. Ey Rabbimiz! Namazı dosdoğru kılmaları için, böyle yaptım. Sen de insanlardan bir kısmının gönüllerini onlara meylettir ve onları meyvelerden rızıklandır. Umulur ki, şükrederler.'),
(14, 38, 13, 260, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'Rabbanā innaka taʿlamu mā nukhfī wa mā nuʿlinu Wa mā yakhfā ʿalā Llāhi min shayʾin fī l-arḍi wa lā fī s-samāʾi', 'Rabbimiz! Şüphesiz sen, gizlediğimiz şeyi de, açığa vurduğumuz şeyi de bilirsin. Yerde ve gökte hiçbir şey Allah’tan gizli kalmaz.'),
(14, 39, 13, 260, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', 'el-ḥamdu lillâhi-lleẕî vehebe lî ‘ale-l-kiberi ismâ‘île ve isḥâḳa inne rabbî lesemî‘u-ddu‘âʾi', 'Hamd, bana yaşlılık halimde İsmail ve İshak''ı bağışlayan Allah''a mahsustur. Şüphesiz Rabbim, duaları hakkıyla işitendir.'),
(14, 40, 13, 260, 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى رَبَّنَا وَتَقَبَّلْ دُعَآءِ', 'Rabbi-jʿalnī muqīma-ṣ-ṣalāti wa-min dhurriyyatī Rabbanā wa-taqabbal duʿāʾi', 'Rabbim! Beni ve soyumdan gelecekleri namazı dosdoğru kılanlardan eyle. Rabbimiz! Duamı kabul buyur.'),
(14, 41, 13, 260, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', 'Rabbanā-ġfir lī wa li-wālidayya wa lil-muʾminīna yawma yaqūmu-l-ḥisāb(u)', 'Rabbimiz! Beni, annemi, babamı ve bütün müminleri, hesap gününde bağışla!'),
(14, 42, 13, 260, 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعْمَلُ ٱلظَّٰلِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ ٱلْأَبْصَٰرُ', 'wa lā taḥsabanna ʾallāha ġāfilan ʿammā yaʿmalu ẓ-ẓālimūn ʾinnamā yuʾaḫḫiruhum liyawmin tašḫaṣu fīhi ʾl-ʾabṣār', 'Sakın Allah''ı zalimlerin yaptıklarından habersiz sanma! O, onları ancak gözlerin dehşetle bakakalacağı bir güne erteliyor.'),
(14, 43, 13, 261, 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْـِٔدَتُهُمْ هَوَآءٌ', 'muhtıʿîne muqniʿī ruʾûsihim lā yertaddu ileyhim tarfuhum wa-ʾafʾidatuhum hawāʾun', 'Onlar, başları yukarı kalkık, gözleri kendilerine dönmeden, yürekleri bomboş bir halde koşarlar.'),
(14, 44, 13, 261, 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ', 'wa-ʾanẓir-i n-nāsa yawma yaʾtīhimu l-ʿaḏābu fa-yaqūlu l-laḏīna ẓalamū rabbana ʾaḫḫirnā ʾilā ʾaǧalin qarībin nujib daʿwataka wa-nattabiʿi r-rusula ʾa-wa-lam takūnū ʾaqsamtum min qablu mā lakum min zawālin', 'Ey Muhammed! İnsanlara, kendilerine azabın geleceği o günü haber ver de, o gün zalimler şöyle derler: "Rabbimiz! Bizi yakın bir zamana kadar ertele de senin davetine uyalım ve peygamberlere tabi olalım." (Onlara şöyle denilir:) "Daha önce sizin için zeval (yok oluş) olmadığını mı yemin ediyordunuz?"'),
(14, 45, 13, 261, 'وَسَكَنتُمْ فِى مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', 'wa sakantum fī masākini alladhīna ẓalamū anfusahum wa tabayyana lakum kayfa faʿalnā bihim wa ḍarabnā lakumu l-amthāla', 'Hem kendilerine zulmetmiş olanların yurtlarında oturmuş oldunuz ve onlara nasıl muamele ettiğimiz size açıkça belli olmuştu ve size örnekler vermiştik.'),
(14, 46, 13, 261, 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', 've qad makarū makrahum ve ʿinda l-lahi makruhum ve in kāna makruhum litazūla min''hu l-jibālu', 'Gerçekten onlar tuzaklarını kurdular. Oysa onların tuzağı Allah katındadır. Tuzakları dağları yerinden oynatacak olsa bile.'),
(14, 47, 13, 261, 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ إِنَّ ٱللَّهَ عَزِيزٌ ذُو ٱنتِقَامٍ', 'falā taḥsabanna ʾallāha mukhliﬀa waʿdihi rusuwlahu ʾinna ʾallāha ʿazīzun ḏū ʾintiqāmi', 'Sakın Allah''ın peygamberlerine verdiği sözden cayacağını sanma! Şüphesiz Allah, mutlak güç sahibi, intikam alandır.'),
(14, 48, 13, 261, 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَٰوَٰتُ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'yawma tubaddalu l-arḍu ghayra l-arḍi wa-s-samāwātu wa-barazū li-llāhi l-wāḥidi l-qahhāri', 'O gün, yer başka bir yer, gökler de başka bir yer olur. Ve insanlar, tek ve kahredici olan Allah''ın huzuruna çıkarlar.'),
(14, 49, 13, 261, 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'wa tarā l-mujrimīna yawmaʾiḏin muqarranīna fī l-ʾaṣfādi', 'O gün, günahkârların birbirlerine zincirlerle bağlanmış olduklarını görürsün.'),
(14, 50, 13, 261, 'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', 'sarābīluhum min qaṭirānin wa taghshā wujūhahumu n-nāru', 'Gömlekleri katrandandır ve yüzlerini ateş kaplayacaktır.'),
(14, 51, 13, 261, 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'li-yajziya llāhu kulla nafsin mā kasabat ʾinna llāha sarīʿu l-ḥisābi', 'Böylece Allah her nefse kazandığının karşılığını versin. Şüphesiz Allah, hesabı çabuk görendir.'),
(14, 52, 13, 261, 'هَٰذَا بَلَٰغٌ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'hādhā balāghun li-n-nāsi wa li-yunzharū bihi wa li-yaʿlamū annamā huwa ilāhun wāḥidun wa li-yadhdhakkara ulu l-albābi', 'Bu (Kur''an), insanları uyaracak, Allah''ın ancak tek bir ilah olduğunu bilecekler ve akıl sahiplerinin öğüt alacağı bir tebliğdir.'),
(15, 1, 14, 262, 'الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَقُرْءَانٍ مُّبِينٍ', 'Elif, Lâm, Ra. Tilke âyâtü''l-kitâbi ve kur''ânin mubîn.', 'Elif, Lâm, Ra. Bunlar Kitab''ın ve apaçık bir Kur''an''ın ayetleridir.'),
(15, 2, 14, 262, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', 'rubbamā yawaddu alladhīna kafarū law kānū muslimīn', 'Nice, o kâfirler, keşke müslüman olsaydık diye temenni ederler.'),
(15, 3, 14, 262, 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ فَسَوْفَ يَعْلَمُونَ', 'dharhum yaʾkulū wayatamattaʿū wayul''hihimu l-ʾamalu fasawfa yaʿlamūn', 'Bırak onları, yesinler ve zevklensinler; emelleri onları oyalaya dursun. Yakında (gerçeği) bilecekler.'),
(15, 4, 14, 262, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌ مَّعْلُومٌ', 'vema ahleknâ min karyetin illâ velehâ kitâbun ma''lûm', 'Biz, helak ettiğimiz hiçbir kasaba yoktur ki, onun belirli bir yazısı olmasın.'),
(15, 5, 14, 262, 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 'mā tasbiqu min ummatin ajalāhā wa mā yastaʾkhirūn', 'Hiçbir ümmet ne ecelinin önüne geçebilir, ne de gerisinde kalabilir.'),
(15, 6, 14, 262, 'وَقَالُوا۟ يَٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌ', 'wa qālū yā ayyuhā lladhī nuzzila ʿalayhi dh-dhikru innaka lamajnūn', 'Ve dediler ki: ''Ey kendisine zikir indirilen (Kur''an)! Şüphesiz sen delinin birisin!'''),
(15, 7, 14, 262, 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'law mā taʾtīnā bil-malāʾikati in kunta mina ṣ-ṣādiqīn', 'Eğer doğru sözlülerden isen, melekleri bize getirsene!'),
(15, 8, 14, 262, 'مَا نُنَزِّلُ ٱلْمَلَٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًا مُّنظَرِينَ', 'Mā nunazzilu l-malāʾikata illā bi-l-ḥaqqi Wa mā kānū ʾiḏan munẓarīn', 'Biz melekleri ancak hak ile indiririz ve o zaman onlara mühlet verilmez.'),
(15, 9, 14, 262, 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'ʾinnā naḥnu nazzalnā ḏ-ḏikra wa-ʾinnā lahu laḥāfiẓūn', 'Şüphesiz o zikri (Kur''an''ı) biz indirdik biz; ve elbette onu biz koruyacağız.'),
(15, 10, 14, 262, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', 'Ve lekad erselnâ min kablike fî şiyâʿi l-ʾevvelîne', 'Andolsun ki senden önce de, evvelki topluluklara elçiler göndermiştik.'),
(15, 11, 14, 262, 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'wa mā yaʾtīhim min rasūlin ʾillā kānū bihi yastahziʾūn', 'Onlara gelen hiçbir peygamber yoktur ki, onunla alay etmiş olmasınlar.'),
(15, 12, 14, 262, 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 'kadhalika naslukuhu fi qulubi al-mujrimīn', 'İşte biz o (inkârı ve küfrü), suçluların kalplerine böylece sokarız.'),
(15, 13, 14, 262, 'لَا يُؤْمِنُونَ بِهِۦ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', 'lā yuʾminūna bihi waqad ḵalat sunnatu l-ʾawwalīn', 'Ona inanmazlar. Halbuki öncekilerin kanunu (sünneti) geçmişti.'),
(15, 14, 14, 262, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', 'Velev fetahna ''aleyhim baban mines semā''i fezallu fīhi ya''rucūn', 'Onların üzerine gökten bir kapı açsak da, oradan göğe yükselip dursalar,'),
(15, 15, 14, 262, 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَٰرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ', 'leḳālû innemâ sukkirat ebṣârunâ bel naḥnü ḳavmüm mesḥûrûn', 'Mutlaka derlerdi ki: “Gözlerimiz döndürüldü (büyülendi). Hayır, biz büyülenmiş bir topluluğuz.”'),
(15, 16, 14, 263, 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', 'Ve lekad cealnâ fîs semâi burûcen Ve zeyyennâhâ lin nâzırîn', 'Andolsun, biz gökte burçlar yarattık ve onları seyredenler için süsledik.'),
(15, 17, 14, 263, 'وَحَفِظْنَٰهَا مِن كُلِّ شَيْطَٰنٍ رَّجِيمٍ', 'waḥafiẓnāhā min kulli shayṭānin rajīm', 'Ve onları her kovulmuş şeytandan koruduk.'),
(15, 18, 14, 263, 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌ مُّبِينٌ', 'illa menistaraḳa-ssemeʿa fe-etbeʿahu shihābun mubīnun', 'Ancak kulak hırsızlığı yapanlar müstesna; onları da apaçık bir ateş takip eder.'),
(15, 19, 14, 263, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍ مَّوْزُونٍ', 'wa-l-arḍa madadnāhā wa-alqaynā fīhā rawāsīa wa-anbatnā fīhā min kulli shayʾin mawzūnin', 'Yeri de döşedik, ona sabit dağlar yerleştirdik ve orada her şeyden ölçülü olarak bitirdik.'),
(15, 20, 14, 263, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', 'wa jaʿalnā lakum fīhā maʿāyisha wa man lastum lahū birāziqīn', 'Yine orada sizin için ve rızıklandıramayacağınız kimseler için geçimlikler kıldık.'),
(15, 21, 14, 263, 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍ مَّعْلُومٍ', 'wa-ʾin min šayʾin ʾillā ʿindanā ḫazāʾinuhū wa-mā nunazziluhū ʾillā bi-qadarin maʿlūmin', 'Her şeyin hazineleri yalnızca bizim yanımızdadır ve biz onu ancak belirli bir ölçüye göre indiririz.'),
(15, 22, 14, 263, 'وَأَرْسَلْنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ', 'waʾarsalnā r-riyāḥa lawāqiḥa faʾanzalnā mina s-samāʾi māʾan faʾasqaynākumūhu wamā ʾantum lahū biḫāzinīn', 'Biz rüzgârları aşılayıcı olarak gönderdik ve gökten bir su indirip onunla suvarıldınız. Onu depolayanlar sizler değilsiniz.'),
(15, 23, 14, 263, 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', 'wa-ʾinnā lanuḥnu nuḥyī wa-numītu wa-naḥnu l-wāriṯūn', 'Şüphesiz biz hem diriltiriz hem de öldürürüz ve varis olanlar da ancak biziz.'),
(15, 24, 14, 263, 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', 'Ve lekad ‘alimnâ-lmustakdimîne minkum ve lekad ‘alimnâ-lmusteʾḣirîn', 'Andolsun ki sizden önde gidenleri de biliriz, geride kalanları da biliriz.'),
(15, 25, 14, 263, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', 'waʾinna rabbaka huwa yaḥshuruhum ʾinnahu ḥakīmun ʿalīmun', 'Şüphesiz ki Rabbin, onları (hesap için) toplayacaktır. Şüphesiz O, hüküm ve hikmet sahibidir, her şeyi bilendir.'),
(15, 26, 14, 263, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'Ve lekad halaknâ el-insâne min salsâlin min hamein mesnûnin', 'Andolsun ki insanı, kuru çamurdan, şekillenmiş kara balçıktan yarattık.'),
(15, 27, 14, 263, 'وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', 'wa-l-jānnata khalaqnāhu min qablu min nāri s-samūmi', 'Cinleri de daha önce, (güneşsiz ve dumansız) ateşten yaratmıştık.'),
(15, 28, 14, 263, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'wa-ʾiḏ ḵāla rabbuka lil-malāʾikati ʾinnī ḵāliḵun bašaran min ṣalṣālin min ḥamāʾin masnūnin', 'Hani Rabbin meleklere şöyle demişti: "Ben, balçıktan, (işlenmiş) kuru topraktan bir beşer yaratacağım."'),
(15, 29, 14, 263, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'fa-idhā sawwaytuhu wa-nafakhtu fīhi min rūḥī fa-qaʿū lahu sājidīn', 'Onu bir biçime sokup ruhumdan üflediğimde, hemen ona secdeye kapanın!'),
(15, 30, 14, 263, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 'fasajadal-malāʾikatu kulluhum ajmaʿūn', 'Bunun üzerine meleklerin hepsi topluca secde ettiler.'),
(15, 31, 14, 263, 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'illa iblīsa abā an yakūna maʿa s-sājidīn', 'Ancak İblis, secde edenlerle beraber olmaktan kaçındı.'),
(15, 32, 14, 264, 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'qāla yā ʾiblīsu mā laka ʾallā takūna maʿa s-sājidīn', 'Allah, "Ey İblis! Secde edenlerle birlikte olmaktan seni alıkoyan nedir?" dedi.'),
(15, 33, 14, 264, 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'qāla lam akun li-ʾasjuda li-bašarin ḫalaqtahū min ṣalṣālin min ḥamāʾin masnūn', 'Dedi ki: "Ben, balçıktan, şekillendirilmiş (bir topraktan) yarattığın bir beşere secde edecek değilim."'),
(15, 34, 14, 264, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', 'qāla fa-ʾkhruj minhā fa-ʾinnaka rajīm', 'Allah şöyle buyurdu: "Artık oradan çık! Çünkü sen kovulmuş birisin."'),
(15, 35, 14, 264, 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', 'waʾinna ʿalayka l-laʿnata ʾilā yawmi d-dīn', 'Ve şüphesiz ki, din gününe kadar sana lanet vardır.'),
(15, 36, 14, 264, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'qāla rabbi faʾanẓirnī ʾilā yawmi yubʿathūn', 'Dedi ki: "Rabbim! Öyleyse, onların tekrar diriltilecekleri güne kadar bana mühlet ver."'),
(15, 37, 14, 264, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'qāla fa-ʾinnaka mina l-munẓarīn', 'Allah şöyle buyurdu: "Artık sen, (belirli bir) vakte kadar gözetlenenlerdensin."'),
(15, 38, 14, 264, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'ilā yawmi l-waqti l-maʿlūmi', 'Bilinen o vakit gününe kadar.'),
(15, 39, 14, 264, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'qāla rabbi bimā ʾaḡwaytanī laʾuzayyinanna lahum fī l-ʾarḍi walaʾuḡwiyannnahum ʾajmaʿīna', 'İblis şöyle dedi: "Rabbim! Beni azdırman sebebiyle, yemin ederim ki, ben de onlara (günahları) yeryüzünde süsleyip-püslü göstereceğim ve onların hepsini azdıracağım."'),
(15, 40, 14, 264, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 'illa ʿibādaka minhumu l-mukhlaṣīn', 'Onlardan ihlasa erdirilmiş kulların müstesna.'),
(15, 41, 14, 264, 'قَالَ هَٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', 'qāla hāḏā ṣirāṭun ʿalayya mustaqīm', 'Allah şöyle dedi: "İşte bu, bana dosdoğru gelen bir yoldur."'),
(15, 42, 14, 264, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', 'ʾinna ʿibādī laysa laka ʿalayhim sulṭānun ʾillā man-ittabaʿaka mina l-ḡāwīn', 'Şüphesiz benim kullarım üzerinde senin hiçbir gücün yoktur. Ancak azgınlardan sana uyanlar müstesna.'),
(15, 43, 14, 264, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', 'wa-ʾinna Jahannama lamaūʿiduhum ʾajmaʿīn', 'Ve şüphesiz cehennem, onların hepsinin vaad olunan yeridir.'),
(15, 44, 14, 264, 'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ', 'lahā sabʿatu ʾabwābin likulli bābin minhum juzʾun maqṣūmun', 'Onun yedi kapısı vardır; her kapıdan (girecek) belirli bir grup ayrılmıştır.'),
(15, 45, 14, 264, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَعُيُونٍ', 'ʾinna l-muttaqīna fī jannātin wa ʿuyūnin', 'Şüphesiz takva sahipleri cennetlerde ve pınar başlarındadır.'),
(15, 46, 14, 264, 'ٱدْخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 'udkhulūhā bisalāmin ʾāminīn', 'Oraya esenlikle, güvenlik içinde girin!'),
(15, 47, 14, 264, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ', 'wa-naz''anā mā fī ṣudūrihim min ḡillin ʾiḫwānan ʿalā sururin mutaqābilīn', 'Ve onların göğüslerinde kinden ne varsa, çekip çıkarırız; (onlar) kardeşler olarak tahtlar üzerinde karşılıklı otururlar.'),
(15, 48, 14, 264, 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', 'laa yamassuhum feehaa nasabun wa maa hum minhaa bimukhrajeen', 'Orada kendilerine hiçbir yorgunluk gelmez ve oradan çıkarılacak da değillerdir.'),
(15, 49, 14, 264, 'نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', 'nabbiʾ ʿibādī annī ʾanā l-ġafūru r-raḥīmu', 'Kullarıma haber ver; şüphesiz ben, evet ben, Gafûr''um, Rahîm''im.'),
(15, 50, 14, 264, 'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ', 'wa ʾanna ʿaḏābī huwa l-ʿaḏābu l-ʾalīmu', 'Ve benim azabımın da elîm (çok acı veren) azap olduğunu (bildir).'),
(15, 51, 14, 264, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', 'wa-nabbihum ʿan ḍayfi ibrāhīm', 'Onlara İbrahim''in misafirlerinden haber ver.'),
(15, 52, 14, 265, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًا قَالَ إِنَّا مِنكُمْ وَجِلُونَ', 'iḏ ḏaḵalū ʿalayhi fa-qālū salāman qāla ʾinnā minkum wajilūna', 'Hani onlar İbrahim''in yanına girip, "Selam!" demişlerdi. O da, "Şüphesiz biz sizden korkuyoruz" demişti.'),
(15, 53, 14, 265, 'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٍ', 'qālū lā tawjal ʾinnā nubashiruka biġulāmin ʿalīm', 'Dediler ki: Korkma! Biz sana bilgili bir oğul müjdeliyoruz.'),
(15, 54, 14, 265, 'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ', 'qāla ʾabaššartumūni ʿalā ʾan massaniya l-kibaru fabima tubašširūn', 'Dedi ki: "Bana yaşlılık gelmişken bana müjdemi mi verdiniz? O halde neyle müjdeliyorsunuz beni?"'),
(15, 55, 14, 265, 'قَالُوا۟ بَشَّرْنَٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَٰنِطِينَ', 'qālū bashsharnāka bil-ḥaqqi falā takun minal-qāniṭīn', 'Dediler ki: "Sana gerçeği müjdeledik, sakın umutsuzluğa kapılanlardan olma!"'),
(15, 56, 14, 265, 'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', 'qāla wa-man yaqnaṭu min raḥmati rabbihi ʾillā ḍ-ḍāllūn', 'Dedi ki: "Sapıklardan başkasını kim Rabbinden umut keser?"'),
(15, 57, 14, 265, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 'qāla famā khaṭbukum ayyuhā l-mursalūn', 'İbrahim şöyle dedi: "Ey elçiler, sizin işiniz nedir?"'),
(15, 58, 14, 265, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ', 'qālū inna ʾursilnā ʾilā qawmin mujrimīn', 'Dediler ki: "Biz, günahkâr bir kavme gönderildik."'),
(15, 59, 14, 265, 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ', 'illā ʾāla Lūṭin ʾinnā lamunecʿūhum ʾacmʿīn', 'İllâ âle Lût''un. Şüphesiz biz onları topluca kurtaracağız.'),
(15, 60, 14, 265, 'إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَآ إِنَّهَا لَمِنَ ٱلْغَٰبِرِينَ', 'illa-mraʾatahu qaddarnā ʾinnahā lamina-l-ġābirīn', 'Ancak karısı hariç; onu (helak edilenler arasında) takdir ettik. Şüphesiz o, (geride kalanlardan) olacaktır.'),
(15, 61, 14, 265, 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلْمُرْسَلُونَ', 'felemmā jāʾa ʾāla lūṭin l-murselūn', 'Lut kavmine elçiler geldiği zaman'),
(15, 62, 14, 265, 'قَالَ إِنَّكُمْ قَوْمٌ مُّنكَرُونَ', 'qāla ʾinnakum qawmun munkarūn', 'Dedi ki: "Siz, tanınmayan bir topluluksunuz."'),
(15, 63, 14, 265, 'قَالُوا۟ بَلْ جِئْنَٰكَ بِمَا كَانُوا۟ فِيهِ يَمْتَرُونَ', 'qālū bal jiʾnāka bimā kānū fīhi yamtirūn', 'Onlar şöyle dediler: "Hayır! Biz sana, onların hakkında şüphe edip durdukları şeyi getirdik."'),
(15, 64, 14, 265, 'وَأَتَيْنَٰكَ بِٱلْحَقِّ وَإِنَّا لَصَٰدِقُونَ', 'waʾataynāka bilḥaqqi waʾinnanā laṣādiqūna', 'Ve sana hakkı getirdik ve biz elbette doğru söyleyenleriz.'),
(15, 65, 14, 265, 'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَٱتَّبِعْ أَدْبَٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ وَٱمْضُوا۟ حَيْثُ تُؤْمَرُونَ', 'fa-ʾesri bi-ʾehlike bi-qiṭʿin mina l-layli wa-ttabiʿ ʾadbārahum wa-lā yaltafit minkum ʾaḥadun wa-mḍū ḥaythu tuʾmarūna', 'Ailenle birlikte gecenin bir bölümünde yola çık ve sen de onların ardından git. Sizden hiç kimse arkasına bakmasın ve emrolunduğunuz yere doğru ilerleyin.'),
(15, 66, 14, 265, 'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ٱلْأَمْرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقْطُوعٌ مُّصْبِحِينَ', 'wa qaḍaynā ʾilayhi dhālika l-ʾamra ʾanna dābira hāʾulāʾi maqṭūʿun muṣbiḥīna', 'Ve ona şu emri vahyettik: ''Sabah olunca bunların kökü kesilecektir.'''),
(15, 67, 14, 265, 'وَجَآءَ أَهْلُ ٱلْمَدِينَةِ يَسْتَبْشِرُونَ', 'wa jāʾa ʾahlu l-madīnati yastabširūn', 'Ve halkı şehrin müjdeleşerek geldiler.'),
(15, 68, 14, 265, 'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيْفِى فَلَا تَفْضَحُونِ', 'qāla inna hāʾulāʾi ḍayfī falā tafḍaḥūn', 'Dedi ki: "Şüphesiz bunlar benim misafirlerimdir, beni rezil etmeyin!"'),
(15, 69, 14, 265, 'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ', 'wa-ttaqū l-laha wa-lā tukhzūni', 'Allah''tan korkun ve beni rezil etmeyin.'),
(15, 70, 14, 265, 'قَالُوٓا۟ أَوَلَمْ نَنْهَكَ عَنِ ٱلْعَٰلَمِينَ', 'qālū ʾawalam nan-haka ʿani l-ʿālamīn', 'Dediler ki: "Doğrusu biz seni, (bizimle) cihan halkı hakkında menetmemiş miydik?"'),
(15, 71, 14, 266, 'قَالَ هَٰٓؤُلَآءِ بَنَاتِىٓ إِن كُنتُمْ فَٰعِلِينَ', 'qāla hāʾulāʾi bānatī ʾin kuntum fāʿilīn', 'Dedi ki: "Eğer yapacaklarınızın gereğini yapacaksanız, işte kızlarım!"'),
(15, 72, 14, 266, 'لَعَمْرُكَ إِنَّهُمْ لَفِى سَكْرَتِهِمْ يَعْمَهُونَ', 'laʿamruka ʾinnahum lafī sakratihim yaʿmahūn', 'Hayatına yemin ederim ki, onlardan çoğu sarhoşlukları içinde bocalayıp duruyorlardı.'),
(15, 73, 14, 266, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُشْرِقِينَ', 'faʾaḫaḏathumu ṣ-ṣayḥatu mušriqīn', 'Onları, tam güneşin doğduğu vakitte o korkunç, korkunç ses yakalayıverdi.'),
(15, 74, 14, 266, 'فَجَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةً مِّن سِجِّيلٍ', 'fa jaʿalnā ʿāliyahā sāfilahā wa amṭarnā ʿalayhim ḥijāratan min sijīlin', 'Böylece oranın altını üstüne getirdik ve üzerlerine balçıktan pişirilmiş taşlar yağdırdık.'),
(15, 75, 14, 266, 'إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّلْمُتَوَسِّمِينَ', 'ʾinna fī ḏālika la-ʾāyātin lil-mutawassimīn', 'Şüphesiz bunda, basiret sahipleri için elbette ibretler vardır.'),
(15, 76, 14, 266, 'وَإِنَّهَا لَبِسَبِيلٍ مُّقِيمٍ', 'wa-ʾinnahā labisabīlin muqīm', 'Şüphesiz bunlar, (hâlâ) yerle bir olmuş şehirlerin (üzerinden geçmektedirler).'),
(15, 77, 14, 266, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّلْمُؤْمِنِينَ', 'ʾinna fī ḏālika laʾāyatan lil-muʾminīn', 'Şüphesiz bunda, iman edenler için bir ayet vardır.'),
(15, 78, 14, 266, 'وَإِن كَانَ أَصْحَٰبُ ٱلْأَيْكَةِ لَظَٰلِمِينَ', 'wa-ʾinna kān ʾaṣḥābu l-ʾaykati la-ẓālimīn', 'Eyke halkı da gerçekten zalimlerdi.'),
(15, 79, 14, 266, 'فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍ مُّبِينٍ', 'fa-ntaqamnā minhum wa-innahumā la-bi-imāmin mubīn', 'Bunun üzerine onlardan intikam aldık. Şüphesiz ikisi de (Lût kavmi ve Şuayb kavmi) apaçık bir yol üzerindeydiler.'),
(15, 80, 14, 266, 'وَلَقَدْ كَذَّبَ أَصْحَٰبُ ٱلْحِجْرِ ٱلْمُرْسَلِينَ', 'Ve lekad kezzebet ashâbul hicril murselîn(murselîne).', 'Andolsun ki Hicr halkı da peygamberleri yalanladı.'),
(15, 81, 14, 266, 'وَءَاتَيْنَٰهُمْ ءَايَٰتِنَا فَكَانُوا۟ عَنْهَا مُعْرِضِينَ', 'wa ʾātaynāhum ʾāyātinā fakānū ʿanhā muʿriḍīn', 'Onlara ayetlerimizi verdik, ama onlardan yüz çeviriyorlardı.'),
(15, 82, 14, 266, 'وَكَانُوا۟ يَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا ءَامِنِينَ', 'wa kānū yanhitūna mina l-jibāli buyūtan ʾāminīn', 'Ve dağlardan evler yontuyorlardı, güvenli kimseler olarak.'),
(15, 83, 14, 266, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُصْبِحِينَ', 'faʾaḫaḏathumu ṣ-ṣayḥatu muṣbiḥīn', 'Sabah olunca, onları o korkunç ses yakalayıverdi.'),
(15, 84, 14, 266, 'فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'famā ʾaġnā ʿanhum mā kānū yaksibūn', 'Onların kazanmakta oldukları şeyler kendilerinden hiçbir fayda sağlamadı.'),
(15, 85, 14, 266, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَإِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ', 'wa mā khalaqnā s-samāwāti wa-l-arḍa wa mā baynahumā illā bi-l-ḥaqqi wa inna s-sāʿata la-ʾātiyatun fa-ṣfaḥi ṣ-ṣafḥa l-jamīla', 'Biz gökleri, yeri ve ikisi arasında bulunanları ancak hak ile yarattık. Şüphesiz kıyamet de mutlaka gelecektir. Şimdi sen güzel bir hoşgörü ile hareket et!'),
(15, 86, 14, 266, 'إِنَّ رَبَّكَ هُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'ʾinna rabbaka huwa l-ḵallāqu l-ʿalīmu', 'Şüphesiz Rabbin, her şeyi yaratan, her şeyi bilen''dir.'),
(15, 87, 14, 266, 'وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ', 'Ve lekad āteynāke seb''an mine''l-mes̱ānī ve''l-ḳur''āne''l-ʿaẓīm', 'Andolsun ki sana, tekrarlanan yedi ayeti (Fatiha''yı) ve yüce Kur''an''ı verdik.'),
(15, 88, 14, 266, 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَٱخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ', 'la tamuddenne ''aynekeyke ila ma metta''na bihi ''ezvacen minhum wa la tahzen ''aleyhim wa''khfidh canahake lilmu''minin', 'Onlardan çiftler halinde yararlandırdığımız şeylere göz dikme; onlara üzülme ve müminlere karşı tevazu kanatlarını indir.'),
(15, 89, 14, 266, 'وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ', 'wa-qul innī ʾanā n-naḏīru l-mubīnu', 'Ve de ki: "Şüphesiz ben, apaçık bir uyarıcıyım."'),
(15, 90, 14, 266, 'كَمَآ أَنزَلْنَا عَلَى ٱلْمُقْتَسِمِينَ', 'kamā anzalnā ʿalā l-muqtasimīn', 'Onlar, Kur''an''ı parçalara ayıranlara indirdiğimiz gibi...'),
(15, 91, 14, 267, 'ٱلَّذِينَ جَعَلُوا۟ ٱلْقُرْءَانَ عِضِينَ', 'alladhīna jaʿalū al-qurʾāna ʿiḍīna', 'Onlar ki Kur''an''ı parça parça ettiler.'),
(15, 92, 14, 267, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ أَجْمَعِينَ', 'Fewerabbike le nes''elennehum ecme''în', 'Rabbine yemin olsun ki, onların hepsini mutlaka sorguya çekeceğiz.'),
(15, 93, 14, 267, 'عَمَّا كَانُوا۟ يَعْمَلُونَ', 'ʿammā kānū yaʿmalūn', 'Onların yapmakta olduklarından.'),
(15, 94, 14, 267, 'فَٱصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'faṣdaʿ bimā tuʾmaru waʾaʿriḍ ʿani l-mušrikīn', 'Şimdi sen, emrolunduğun şeyi açıkça tebliğ et ve ortak koşanlardan yüz çevir.'),
(15, 95, 14, 267, 'إِنَّا كَفَيْنَٰكَ ٱلْمُسْتَهْزِءِينَ', 'ʾinnā kafaynāka l-mustahziʾīn', 'Şüphesiz ki alay edenlere karşı biz (sana) kâfîyiz.'),
(15, 96, 14, 267, 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَسَوْفَ يَعْلَمُونَ', 'alladhīna yajʿalūna maʿa ʾallāhi ʾilāhan ʾākhara fasawfa yaʿlamūna', 'Onlar, Allah ile beraber başka bir ilah edinenlerdir. Ama yakında (gerçeği) bilecekler.'),
(15, 97, 14, 267, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', 'Ve lekad na''lemu enneke yedîku sadruke bimâ yekûlûne', 'Andolsun ki onların söylediklerinden dolayı göğsünün daraldığını elbette biliyoruz.'),
(15, 98, 14, 267, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', 'fasabbih bihamdi rabbika wa kun minas-sājidīn', 'Şimdi Rabbini hamd ile tesbih et ve secde edenlerden ol.'),
(15, 99, 14, 267, 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', 'waʿbud rabbaka ḥattā yaʾtiyaka l-yaqīn', 'Rabbine, sana o kesin gerçek (ölüm) gelene kadar kulluk et.'),
(16, 1, 14, 267, 'أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'ʾatā ʾamru ʾllāhi falā tastaʿjilūhu subḥānahū wataʿālā ʿammā yušrikūn', 'Allah''ın emri geldi; onunla acele etmeyin. O, onların şirk koştuklarından münezzehtir ve yücedir.'),
(16, 2, 14, 267, 'يُنَزِّلُ ٱلْمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', 'yunazzilu l-malāʾikata bi-r-rūḥi min ʾamrihī ʿalā man yashāʾu min ʿibādihī ʾan ʾanẓirū ʾannehū lā ʾilāha ʾillā ʾanā fa-ttaqūn', 'Melekleri, emrinden olan ruh ile kullarından dilediğine indirir de: ''Benden başka hiçbir ilah yoktur, benden korkup sakının'' diye uyarın, diye (emreder).'),
(16, 3, 14, 267, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ تَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'x̱alaqa s-samāwāti wa-l-arḍa bi-l-ḥaqqi taʿālā ʿammā yušrikūn', 'O, gökleri ve yeri hak ile yaratmıştır. Onların ortak koştukları şeylerden yücedir.'),
(16, 4, 14, 267, 'خَلَقَ ٱلْإِنسَٰنَ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', 'xalaqa l-insāna min nuṭfah fa-iḏā huwa ḫaṣīmun mubīn', 'O, insanı bir nutfeden yarattı. Bir de bakarsın, (o insan) apaçık bir hasımdır.'),
(16, 5, 14, 267, 'وَٱلْأَنْعَٰمَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَٰفِعُ وَمِنْهَا تَأْكُلُونَ', 'wa-l-anʿāma ḫalaqahā lakum fīhā difʾun wa-manāfiʿu wa-min-hā taʾkulūn', 'Sıgınanlara (veya davarlara) gelince, onları da Allah yarattı. Onlarda sizin için ısınma (var), faydalar (var) ve onlardan yiyorsunuz.'),
(16, 6, 14, 267, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', 'wa lakum fīhā jamālun ḥīna turīḥūna wa ḥīna tasraḥūna', 'Onlar sizin için hem de onlarda sizin için bir güzellik (veya fayda) vardır; onları akşamleyin (ağırla-rından) getirdiğiniz zaman da, sabahleyin (meraya) saldığınız zaman da.'),
(16, 7, 14, 268, 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَّمْ تَكُونُوا۟ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'wa taḥmilu athqālakum ilā baladin lam takūnū bālighīhi illā bishiqqi l-anfusi inna rabbakum laraʾūfun raḥīm', 'Ve sizin ağır yüklerinizi, ancak nefislerinizle büyük zorluklarla ulaşabileceğiniz bir beldeye taşırlar. Şüphesiz Rabbiniz, gerçekten çok şefkatli, çok merhametlidir.'),
(16, 8, 14, 268, 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً وَيَخْلُقُ مَا لَا تَعْلَمُونَ', 'wa-l-khayla wa-l-bighāla wa-l-ḥamīra li-tarkabūhā wa-zīnata wa-yakhluqu mā lā taʿlamūna', 'Atları, katırları ve merkepleri de hem bindesiniz diye hem de bir zinet (görünüşte güzellik) olsun diye (yarattı). Ve bilmediğiniz şeyleri de yaratır.'),
(16, 9, 14, 268, 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 'wa ʿalā allāhi qaṣdu s-sabīli wa minhā jāʾirun wa law shāʾa lahadākum ajmaʿīna', 'Yolu dosdoğru göstermek Allah''a aittir. Ondan eğri olanlar da vardır. Eğer O dileseydi, sizin hepinizi hidayete erdirirdi.'),
(16, 10, 14, 268, 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً لَّكُم مِّنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ', 'huwa alladhī ʾanzala mina ʾssamāʾi māʾan lakum minhu sharābun waminhu shajarun fīhi tusīmūn', 'O, semadan bir su indirdi. İşte ondan size içecek vardır ve ondan (biten) ağaçlar da vardır ki (bunlardan) hayvanlarınızı otlatırsınız.'),
(16, 11, 14, 268, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', 'yunbitu lakum bihi z-zarʿa wa-z-zaytūna wa-n-nakhīla wa-l-aʿnaba wa min kulli ṯ-ṯamarāti inna fī ḏālika laʾāyatan li-qawmin yatafakkkarūna', 'O, sizin için onunla ekinler, zeytinler, hurmalar, üzümler ve daha nice ürünler bitirir. Elbette bunlarda tefekkür eden bir kavim için bir ayet (ibret) vardır.'),
(16, 12, 14, 268, 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'wa-sakhkhara lakumu l-layla wa-n-nahāra wa-sh-shamsa wa-l-qamara wa-n-nujūmu musakhkharātun bi-amrihī ʾinna fī dhālika la-ʾāyātin li-qawmin yaʿqilūna', 'Geceyi, gündüzü, güneşi ve ayı sizin hizmetinize verdi. Yıldızlar da O''nun emriyle hizmetinize verilmiştir. Elbette bunlarda aklını kullanan bir kavim için ibretler vardır.'),
(16, 13, 14, 268, 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّقَوْمٍ يَذَّكَّرُونَ', 've mā dharaʾa lakum fī l-ʾarḍi mukhtalifan ʾalwānuhū ʾinna fī dhālika laʾāyatan li-qawmin yadhdhakkarūn', 'Yine O, yeryüzünde sizin için türlü renklerde yarattığı şeyleri de (emrinize amade kıldı). Şüphesiz bunda, ibret alıp düşünecek bir topluluk için gerçekten bir ayet vardır.'),
(16, 14, 14, 268, 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'wa huwa alladhī sakhkhara l-baḥra li-taʾkulū minhu laḥman ṭariyyan wa tastakhrijū minhu ḥilyatan talbasūnahā wa tarā l-fulka mawākhira fīhi wa li-tabtaghū min faḍlihī wa laʿallakum tashkurūna', 'O, denizi emrinize veren ve ondan taze et yemeniz, ondan takıp giyeceğiniz süs eşyaları çıkarmanız için denizi sizin hizmetinize verendir. Ve onun (denizin) içinde gemilerin suyu yardığını görürsün. Bütün bunlar, O''nun lütfundan nasibinizi aramanız ve şükretmeniz içindir.'),
(16, 15, 14, 269, 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَٰرًا وَسُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', 'wa-alqā fī l-arḍi rawāsīa an tamīda bikum wa-anhāran wa-subulan laʿallakum tahtadūna', 'Yeryüzüne, sizi sarsmasın diye sarsılmaz dağlar koydu; nehirler ve yollar da, umulur ki doğru yolu bulasınız diye.'),
(16, 16, 14, 269, 'وَعَلَٰمَٰتٍ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', 'wa ʿalāmātin wa bi-n-najmi hum yahtadūna', 'Ve (onlar) alametlere ve yıldızlara da hidayet bulurlar.'),
(16, 17, 14, 269, 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ أَفَلَا تَذَكَّرُونَ', 'ʾafaman yaḫliqu kaman lā yaḫliqu ʾafalā taḏakkarūn', 'Yaratan, yaratamayan biri gibi midir? Hiç düşünmez misiniz?'),
(16, 18, 14, 269, 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ', 'wa-ʾin taʿuddū niʿmata ʾllāhi lā tuḥṣūhā ʾinna ʾllāha lagafūrun raḥīm', 'Allah''ın nimetini saymaya kalksanız, onu sayıp bitiremezsiniz. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir.'),
(16, 19, 14, 269, 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 'wa-llāhu yaʿlamu mā tusirrūna wa-mā tuʿlinūna', 'Allah, sizin gizlediklerinizi de, açığa vurduklarınızı da bilir.'),
(16, 20, 14, 269, 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ', 'wa-lladhīna yadʿūna min dūni llāhi lā yakhluqūna shayʾan wa-hum yukhlaqūna', 'Allah''tan başka taptıkları şeyler ise hiçbir şey yaratamazlar; kendileri yaratılmaktadırlar.'),
(16, 21, 14, 269, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'amwātun ghayru aḥyāʾin wa mā yashʿurūna ayyana yubʿathūna', 'Onlar, diri olmayan ölülerdir. Ne zaman diriltileceklerini de bilmezler.'),
(16, 22, 14, 269, 'إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ', 'ilāhukum ilāhun wāḥidun fa-alladhīna lā yuʾminūna bi-l-ʾākhirati qulūbuhum munkirotun wa-hum mustakbirūna', 'Sizin ilahınız tek bir ilahtır. Ahirete inanmayanların kalpleri inkarcı, kendileri ise kibirlenmektedirler.'),
(16, 23, 14, 269, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', 'lā jarama anna ʾallāha yaʿlamu mā yusirrūna wa mā yuʿlinūna ʾinnahu lā yuḥibbu l-mustakbirīna', 'Şüphesiz Allah, onların gizlediklerini de açıkladıklarını da bilir. Şüphesiz O, büyüklük taslayanları sevmez.'),
(16, 24, 14, 269, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ قَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'wa ʾiḏā qīla lahum māḏā ʾanzala rabbukum qālū ʾasāṭīru l-ʾawwalīn', 'Onlara: "Rabbiniz ne indirdi?" dendiği zaman, "(Bunlar) evvelce geçmişlerin masallarıdır" derler.'),
(16, 25, 14, 269, 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةً يَوْمَ ٱلْقِيَٰمَةِ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ أَلَا سَآءَ مَا يَزِرُونَ', 'liyaḥmilū ʾawzārahum kāmilatan yawma l-qiyāmati wa-min ʾawzāri l-ladhīna yuḍillūnahum bi-ghayri ʿilmin ʾalā sāʾa mā yazirūna', 'Böylece kıyamet günü kendi günahlarını ve bilgisizce saptırdıkları kimselerin günahlarından bir kısmını yüklenirler. Yüklendikleri şey ne kötüdür!'),
(16, 26, 14, 269, 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'qad makara alladhīna min qablihim faʾatā allāhu bunyānahum mina l-qawāʿidi fakharra ʿalayhimu s-saqfu min fawqihim wa ʾatāhumu l-ʿadhābu min ḥaythu lā yashʿurūn', 'Onlardan öncekiler de tuzak kurmuşlardı. Allah da onların yapılarını temelinden yıktı da üstlerinden tavan çöktü ve onlara azap, farkında olmadıkları yerden geldi.'),
(16, 27, 14, 270, 'ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَٰٓقُّونَ فِيهِمْ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَٰفِرِينَ', 'thumma yawma l-qiyāmati yukhzīhim wa-yaqūlu ayna shurakāʾīya lladhīna kuntum tushāqqūna fīhim qāla lladhīna ūtū l-ʿilma inna l-khizya l-yawma wa-s-sūʾa ʿalā l-kāfirīn', 'Sonra kıyamet günü (Allah) onlara: ''Benim, (hakkında) ayrılığa düştüğünüz (ve taptığınız) ortaklarım nerede?'' diye sorarak onları rezil edecek ve ''İlim verilenler şöyle diyecektir: Şüphesiz bugün rezillik ve fenalık kâfirleredir!'' diyeceklerdir.'),
(16, 28, 14, 270, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', 'alladhīna tatawaffāhumu l-malāʾikatu ẓālimī ʾanfusihim fa-ʾalqawu s-salama mā kunnā naʿmalu min sūʾin balā ʾinna llāha ʿalīmun bimā kuntum taʿmalūn', 'Onlar, meleklerin kendilerine zulmetmiş olarak canlarını aldıkları kimselerdir. O zaman (melekler teslimiyet göstererek) "Biz hiçbir kötülük yapmıyorduk" derler. Hayır! Şüphesiz Allah, yaptıklarınızı hakkıyla bilendir.'),
(16, 29, 14, 270, 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'fa-dkhulū abwāba jahannama khālidīna fīhā fa-la-biʾsa mathwā al-mutakabbirīn', 'Artık, içinde ebedî kalıcılar olarak cehennemin kapılarından girin! Kibirlenenlerin ne kötü bir kalma yeridir!'),
(16, 30, 14, 270, 'وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ قَالُوا۟ خَيْرًا لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', 'wa qīla lilladhīna ttaqaw mādhā anzala rabbukum qālū khayran lilladhīna aḥsanū fī hādhihi d-dunyā ḥasanatun wa ladāru l-ʾākhirati khayrun wa la niʿma dāru l-muttaqīn', 'Takva sahiplerine: "Rabbiniz ne indirdi?" denildiğinde, "Bu dünyada iyilik yapanlara bir iyilik vardır. Elbette ahiret yurdu daha hayırlıdır. Allah''a karşı gelmekten sakınanların yurdu ne güzeldir!" dediler.'),
(16, 31, 14, 270, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُمْ فِيهَا مَا يَشَآءُونَ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', 'jannātu ʿadnin yadkhulūnahā tajrī min taḥtihā l-anhāru lahum fīhā mā yashāʾūna kadhālika yajzī llāhu l-muttaqīna', 'Sürekli kalacakları Adn cennetleri (vardır); altlarından ırmaklar akar. Orada onlar için diledikleri her şey vardır. İşte Allah, takva sahiplerini böyle mükafatlandırır.'),
(16, 32, 14, 270, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', 'alladhīna tatawaffāhumu l-malāʾikatu ṭayyibīna yaqūlūna salāmun ʿalaykumu udkhulū l-jannata bimā kuntum taʿmalūna', 'Meleklerin, (canlarını alırken) kendilerine zulmetmedikleri kimseler: ''Selâm üzerinize olsun! Yapmış olduğunuz (iyi ameller) sebebiyle cennete girin'' dedikleri kimselerdir.'),
(16, 33, 14, 270, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'hal yanzurūna illā an taʾtiyahumu l-malāʾikatu aw yaʾtiya amru rabbika kaḏālika faʿala lladhīna min qablihim wa mā zalamahumu llāhu wa lākin kānū anfusahum yaẓlimūna', 'Onlar, kendilerine meleklerin gelmesini veya Rabbinin emrinin (azabının) gelmesini mi bekliyorlar? Onlardan öncekiler de böyle yapmıştı. Allah onlara zulmetmedi, fakat onlar kendi kendilerine zulmediyorlardı.'),
(16, 34, 14, 270, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'faʾaṣābahum sayyiʾātu mā ʿamilū waḥāqa bihim mā kānū bihī yastahziʾūn', 'Yaptıklarının kötülükleri onlara isabet etti ve alay etmekte oldukları şey (azap) onları kuşattı.'),
(16, 35, 14, 271, 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'waqāla lladhīna ashrakū law shāʾa llāhu mā ʿabadnā min dūnihi min shayʾin naḥnu walā ʾābāʾunā walā ḥarramnā min dūnihi min shayʾin kadhālika faʿala lladhīna min qablihim fahal ʿalā r-rusuli ʾillā l-balāghu l-mubīnu', 'Putperestler dediler ki: "Allah dileseydi, O''ndan başka hiçbir şeye tapmazdık; biz de atalarımız da. Ve O''nun emri olmadan hiçbir şeyi haram kılmazdık." Kendilerinden öncekiler de böyle demişlerdi. Resullere düşen, apaçık tebliğden başka mıdır?'),
(16, 36, 14, 271, 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'Ve lekad be''asnâ fî kulli ummetin resûlen eni''budûllâhe ve''ctenibût-tâğût(e) feminhum men hedâllâh(u) veminhum men hakkât ''aleyhi-d-dalâlet(u) fesîrû fîl-ard(i) fenzurû keyfe kâne ''âkibetul mukezzibîn(e)', 'Andolsun ki biz, her ümmete, "Allah''a kulluk edin ve tağuttan sakının" diye bir elçi gönderdik. Onlardan kimine Allah hidayet verdi, kimine de sapıklık hak oldu. Öyleyse yeryüzünde dolaşın da yalanlayanların sonunun nasıl olduğuna bir bakın.'),
(16, 37, 14, 271, 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'in taḥriṣ ʿalā hudāhum faʾinna ʾallāha lā yahdī man yuḍillu wa mā lahum min nṣṣirīn', 'Onları hidayete erdirmeye ne kadar düşkün olsan da, Allah dilediğini saptırır ve onlara yardım edecek kimse yoktur.'),
(16, 38, 14, 271, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'wa-aqsamū billāhi jahda aymānihim lā yabʿathu allāhu man yamūtu balā waʿdan ʿalayhi ḥaqqan wa-lākinna akthara an-nāsi lā yaʿlamūna', 'Onlar, bütün güçleriyle Allah''a yemin ederek, ''Ölen kimseyi Allah diriltmez'' dediler. Hayır! Bu, O''nun hak ve vacip olan bir vaadidir. Fakat insanların çoğu bilmezler.'),
(16, 39, 14, 271, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ', 'li-yubayyina lahumu alladhī yakhtalifūna fīhi wa-li-yaʿlama alladhīna kafarū anna-hum kānū kādhibīna', 'Onlara, ihtilaf ettikleri şeyleri açıklamak için ve kafirlerin de kendilerinin yalancılar olduklarını bilmeleri için (açıklayacağız).'),
(16, 40, 14, 271, 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', 'innamā qawlunā lishayʾin ʾidhā ʾaradnāhu ʾan naqūla lahuū kun fayakūnu', 'Bir şeyi dilediğimizde, ona sadece ''Ol!'' dememiz yeterlidir; o da hemen oluverir.'),
(16, 41, 14, 271, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةً وَلَأَجْرُ ٱلْءَاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'wa-lladhīna hājarū fī llāhi mim baʿdi mā ẓulimū lanubawwiʾannahum fī d-dunyā ḥasanatan wa-laʾajru l-ʾākhirati ʾakbaru law kānū yaʿlamūn', 'Kendilerine zulmedildikten sonra Allah için hicret edenlere gelince, onları dünyada mutlaka güzel bir yere yerleştireceğiz. Elbette ahiret ecri daha büyüktür, bir bilselerdi!'),
(16, 42, 14, 271, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'alladhīna ṣabarū wa ʿalā rabbihim yatawakkalūna', 'Onlar, sabreden ve Rablerine tevekkül eden kimselerdir.'),
(16, 43, 14, 272, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 've mā erselnā min ḳablike illā ricālen nūḥī ileyhim fesʾelū ehle-ẕẕikri in kuntum lā taʿlemūn', 'Senden önce de kendilerine vahyettiğimiz erkeklerden başkasını peygamber olarak göndermedik. Eğer bilmiyorsanız zikir ehline sorun.'),
(16, 44, 14, 272, 'بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', 'bilbayyināti wazzuburi waʾanzalnā ʾilayka ḏḏikra litubayyi na li n-nāsi mā nuzzila ʾilayhim walaʿallahum yatafakkarūna', 'Onları apaçık delillerle ve kitaplarla (gönderdik). İnsanlara indirileni onlara açıklaman ve onların da (üzerinde) düşünebilmeleri için sana da bu zikri (Kur’an’ı) indirdik.'),
(16, 45, 14, 272, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'ʾafa ʾamina lladhīna makarū s-sayyiʾāti ʾan yakhsifa l-lāhu bihimu l-ʾarḍa ʾaw yaʾtiyahumu l-ʿadhābu min ḥaythu lā yashʿurūna', 'Kötülük tuzakları kuranlar, Allah''ın kendilerini yere batırmayacağından veya farkında olmadıkları bir yerden azabın gelmeyeceğinden emin mi oldular?'),
(16, 46, 14, 272, 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', 'aw yaʾkhudhahum fī taqallubihim famā hum bimʿjizīn', 'Yahut onların (yolculuklarında) seyahat ederlerken kendilerini yakalaması da mümkündür. Onlar (Allah''ı) aciz bırakacak değillerdir.'),
(16, 47, 14, 272, 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'aw yaʾkhuḏahum ʿalā taxawwufin faʾinna rabbakum laraʾūfun raḥīm', 'Yahut onları (biraz) korkutarak yakalayıvermesin. Şüphesiz Rabbiniz çok şefkatli, çok merhametlidir.'),
(16, 48, 14, 272, 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍ يَتَفَيَّؤُا۟ ظِلَٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَٰخِرُونَ', 'ʾa-wa-lam yaraw ʾilā mā ḵalaqa ḷ-lāhu min šayʾin yatafay-ʾaʾu ẓilāluhu ʿani l-yamīni wa-š-šemāʾili sujjadan li-ḷ-lāhi wa-hum dāḵirūn', 'Onlar, Allah''ın yarattığı şeylere bakmadılar mı? (Onların) gölgeleri, Allah''a secde ederek sağdan ve soldan (yönelerek) gelmektedir; onlar (bu duruma) boyun eğmektedirler.'),
(16, 49, 14, 272, 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍ وَٱلْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', 'wa lil-lāhi yasjudu mā fī s-samāwāti wa mā fī l-arḍi min dābbatin wa l-malāʾikatu wa hum lā yastakbirūn', 'Göklerde ve yerde bulunan canlılar ve melekler de Allah''a secde ederler ve hiçbiri büyüklük taslamaz.'),
(16, 50, 14, 272, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'yakhāfūna rabbahum min fawqihim wayafʿalūna mā yuʾmarūna', 'Onlar, üstlerindeki Rablerinden korkarlar ve emrolundukları şeyi yaparlar.'),
(16, 51, 14, 272, 'وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰىَ فَٱرْهَبُونِ', 'waqāla llāhu lā tattakhidhū ʾilāhayni ʾithnayni ʾinnamā huwa ʾilāhun wāḥidun fa ʾiyyāya fa ʾrhabūni', 'Allah şöyle buyurdu: "İki ilâh edinmeyin. O, ancak tek bir ilâhtır. Yalnız benden korkun."'),
(16, 52, 14, 272, 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 'wa-lahū mā fī s-samāwāti wa-l-arḍi wa-lahu d-dīnu wāṣibā a-fa-ghayra llāhi tattaqūna', 'Göklerde ve yerde ne varsa hepsi O''nundur. Din de (itaat de) daima O''na aittir. Allah''tan başkasından mı korkuyorsunuz?'),
(16, 53, 14, 272, 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', 'wa mā bikum min niʿmatin fa mina llāhi thumma iḏā massakumu ḍ-ḍurru fa ilayhi tajʾarūna', 'Size ulaşan her nimet Allah''tandır. Sonra, size bir de sıkıntı dokunduğu zaman hemen O''na yalvarırsınız.'),
(16, 54, 14, 272, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 'thumma idhā kashafa al-ḍurra ʿankum idhā farīqun minkum bi-rabbihi yushrikūn', 'Sonra, sizden sıkıntıyı giderdiği zaman, hemen içinizden bir grup yine Rablerine ortak koşarlar.'),
(16, 55, 14, 273, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'liyakfurū bimā ātaynāhum fatemattaʿū fasawfa taʿlamūn', 'Kendilerine verdiğimiz nimetlere nankörlük etsinler de (dünyada) geçici olarak faydalansınlar! Ama yakında (gerçeği) bilecekler.'),
(16, 56, 14, 273, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَٰهُمْ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', 'wa yajʿalūna limā lā yaʿlamūna naṣīban mimmā razaqnāhum tallāhi latus''alunna ʿammā kuntum taftarūna', 'Onlar, kendilerinin bilmediği şeyler için bize bir pay ayırırlar. Allah''a yemin olsun ki, uydurmakta olduğunuz şeylerden mutlaka sorulacaksınız.'),
(16, 57, 14, 273, 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَٰتِ سُبْحَٰنَهُۥ وَلَهُم مَّا يَشْتَهُونَ', 'wa yajʿalūna lillāhi l-banāti subḥānahū wa lahum mā yashtahūna', 'Onlar, Allah''a kız çocukları isnat ederler. Hâşâ O, münezzehtir! Kendileri ise canlarının çektiği (erkek) çocukları edinirler.'),
(16, 58, 14, 273, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', 'wa-idhā bushshira aḥaduhum bi-l-unthā ẓalla wajhuhu muswaddan wa-huwa kaẓīm', 'Onlardan birine dişi (çocuk) müjdelendiği zaman, yüzü simsiyah kesilir ve büyük bir üzüntüye boğulur.'),
(16, 59, 14, 273, 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ أَلَا سَآءَ مَا يَحْكُمُونَ', 'yatawārā mina l-qawmi min sūʾi mā bushshira bihi ayum''sikuhu ʿalā hūnin am yadussuhu fī t-turābi alā sāʾa mā yaḥkumūna', 'Kızlarından (doğumu) hoşlanmadıkları şeyle Allah''a isnad ederler. Ve nefisleri de bunu ikrar eder. Onlar için (cehennemde) ateş vardır. Ne kötü hükmediyorlar!'),
(16, 60, 14, 273, 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ مَثَلُ ٱلسَّوْءِ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'lilladhīna lā yuʾminūna bil-ʾākhirati mathalu s-sawʾi wa lillāhi l-mathalu l-ʾaʿlā wa huwa l-ʿazīzu l-ḥakīmu', 'Ahiret''e inanmayanlara en kötü örnek vardır. En yüce örnek ise Allah''ındır. O, Azîz''dir, Hakîm''dir.'),
(16, 61, 14, 273, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'wa-law yuʾākhiḏu ʾllāhu n-nāsa bi-ẓulmihim mā taraka ʿalayhā min dābbatin wa-lākin yuʾakhkhiruhum ʾilā ʾajalin musammā fa-ʾiḏā jāʾa ʾajaluhum lā yastaʾkhirūna sāʿatan wa-lā yastaqdimūn', 'Allah, zulümleri yüzünden insanları (hemen) cezalandırsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat onları belirli bir süreye kadar erteler. Ecelleri geldiğinde ise ne bir an geri kalabilirler ne de bir an öne geçebilirler.'),
(16, 62, 14, 273, 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', 'wa yajʿalūna lillāhi mā yakrahūna wa taṣifu alsinatuhumu l-kaḏiba anna lahumu l-ḥusnā lā jarama anna lahumu n-nāra wa annahum mufraṭūna', 'Onlar, hoşlanmadıkları şeyleri Allah''a nispet ederler. Dilleri de yalan yere "en güzel şeyler bizimdir" der. Hiç şüphe yok ki onlar için ateş vardır ve onlar (orada) unutulmuşlardır.'),
(16, 63, 14, 273, 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'Tallāhi laqad arsalnā ilā umamin min qablika fazayyana lahumu sh-shayṭānu aʿmālahum fahuwa waliyyuhumu l-yawma wa lahum ʿadhābun alīmun', 'Allah''a yemin ederim ki, senden önce de ümmetlere peygamberler göndermiştik. (Fakat) şeytan onlara yaptıklarını süslü gösterdi. Bu yüzden (o gün) şeytan onların velisi (dostu) oldu ve onlar için elem dolu bir azap vardır.'),
(16, 64, 14, 273, 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 've mā ʾanzalnā ʿalayka l-kitāba ʾillā litubayyi-na lahumu l-ladhī ʾikhtalafū fīhi wa hudan wa raḥmatan li-qawmin yuʾminūn', 'Biz bu kitabı sana, ancak üzerinde anlaşmazlığa düştükleri şeyi onlara açıklayasın, iman eden bir topluluğa da bir hidayet ve bir rahmet olmak üzere indirdik.'),
(16, 65, 14, 274, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّقَوْمٍ يَسْمَعُونَ', 'wa-llāhu anzala mina s-samāʾi māʾan fa-aḥyā bihi l-arḍa baʿda mawtihā ʾinna fī dhālika la-ʾāyatan li-qawmin yasmaʿūn', 'Allah, gökten bir su indirdi de onunla yeryüzünü ölümünden sonra diriltti. Şüphesiz bunda, dinleyen bir kavim için elbette bir ibret vardır.'),
(16, 66, 14, 274, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشَّٰرِبِينَ', 'wa-inna lakum fi-l-anʿāmi la-ʿibrah nusqīkum mimmā fī buṭūnihi min bayni farthin wa-damin labanan khāliṣan sāʾighan li-sh-shāribīn', 'Gerçekten sığır ve koyun gibi hayvanlarda da sizin için bir ibret vardır. Onların karınlarındaki sütten, dışkı ile kan arasından, içenlerin boğazından kolayca geçen, halis bir süt çıkarıyoruz.'),
(16, 67, 14, 274, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّقَوْمٍ يَعْقِلُونَ', 'wa-min thamarāti an-nakhīli wa-l-aʿnābi tattakhidhūna minhu sakaran wa-rizqan ḥasanan ʾinna fī dhālika la-ʾāyatan li-qawmin yaʿqilūna', 'Ve hurma ve üzüm meyvelerinden (de size rızık verdik). Onlardan hem içki (seker) hem de güzel bir rızık edinirsiniz. Şüphesiz ki bunda, aklını kullanan bir topluluk için muhakkak bir ibret vardır.'),
(16, 68, 14, 274, 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', 'waʾawḥā rabbuka ʾilā n-naḥli ʾani ttaḵiḏī mina l-jibāli buyūtan wa mina š-šaǧari wa mimmā yaʿrišūna', 'Ve Rabbin bal arısına vahyetti: Dağlardan, ağaçlardan ve (insanların) kurdukları çardaklardan kendine evler edin.'),
(16, 69, 14, 274, 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', 'thumma kulī min kulli ʾith-thamarāti fa-slukī subula rabbiki dhululan yakhruju min buṭūnihā sharābun mukhtalifun ʾalwānuhū fīhi shifāʾun li-nnāsi ʾinna fī dhālika la-ʾāyatan li-qawmin yatafakkarūna', 'Sonra, her türlü meyveden ye de Rabbinin sana kolaylaştırdığı yollara gir; onların karınlarından çeşitli renklerde bir içecek çıkar. Onda insanlar için bir şifa vardır. Elbette bunda düşünen bir topluluk için bir ayet vardır.'),
(16, 70, 14, 274, 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌ قَدِيرٌ', 'wa-llāhu ḵalaqakum ṯumma yatawaffākum wa-minkum man yuraddu ʾilā ʾarḏali l-ʿumuri likay lā yaʿlama baʿda ʿilmin šayʾan ʾinna llāha ʿalīmun qadīrun', 'Allah sizi yarattı, sonra sizi vefat ettirecektir. İçinizden bir kısmı da, bildikten sonra hiçbir şeyi bilmeyecek hale gelinceye kadar ömrün en verimsiz çağına (veya en rezil, en aşağılık zamanına) ulaştırılır. Şüphesiz Allah, her şeyi bilen, kudreti her şeye yeten''dir.'),
(16, 71, 14, 274, 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِى ٱلرِّزْقِ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', 'wa-llāhu faḍḍala baʿḍakum ʿalā baʿḍin fī r-rizqi fa-mā lladhīna fuḍḍilū bi-raddī rizqihim ʿalā mā malakat aymānuhum fa-hum fīhi sawāʾun a-fa-bi-niʿmati l-lāhi yajḥadūn', 'Allah rızık hususunda kiminizi kiminize üstün kılmıştır. Üstün kılınanlar, kendi rızıklarından kölelerinin tam sahip olmaları için (onlara) vermezler. Allah''ın nimetini mi inkâr ediyorlar?'),
(16, 72, 14, 274, 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', 'wa-llāhu jaʿala lakum min anfusikum azwājan wa-jaʿala lakum min azwājikum banīna wa-ḥafadatan wa-razaqakum mina ṭ-ṭayyibāti afa-bi-l-bāṭili yuʾminūna wa-bi-niʿmati-llāhi hum yakfurūna', 'Allah, size kendi nefislerinizden eşler yarattı ve eşlerinizden de size oğullar ve torunlar meydana getirdi ve size temiz şeylerden rızık verdi. Artık onlar, batıla mı inanıyorlar ve Allah''ın nimetini inkâr mı ediyorlar?'),
(16, 73, 14, 275, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ شَيْـًٔا وَلَا يَسْتَطِيعُونَ', 'wa yaʿbudūna min dūni llāhi mā lā yamliku lahum rizqan mina s-samāwāti wa-l-arḍi shayʾan wa lā yastaṭīʿūna', 'Allah''ı bırakıp da, göklerden ve yerden hiçbir rızık sağlayamayan ve buna gücü de yetmeyen şeylere kulluk ederler.'),
(16, 74, 14, 275, 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'falā taḍribū lillāhi l-amthāla ʾinna llāha yaʿlamu wa ʾantum lā taʿlamūna', 'Allah''a misaller getirmeyin. Şüphesiz Allah bilir, siz bilmezsiniz.'),
(16, 75, 14, 275, 'ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَىْءٍ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا هَلْ يَسْتَوُۥنَ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ḍaraba -llāhu maṯalan ʿabdan mamlūkan lā yaqdiru ʿalā šayʾin wa-man razaqnāhu minnā rizqan ḥasanan fa-huwa yunfiqu minhu sirran wa-jahran hal yastawūna al-ḥamdu li-llāhi bal akṯaruhum lā yaʿlamūna', 'Allah, hiçbir şeye gücü yetmeyen ve efendisinin malı hakkında tasarrufta bulunamayan bir köle ile tarafımızdan kendisine güzel bir rızık verdiğimiz, böylece ondan gizli ve açık olarak harcayan kimseyi misal olarak verdi. Bunlar hiç eşit olur mu? Hamd Allah’a mahsustur. Fakat onların çoğu bilmezler.'),
(16, 76, 14, 275, 'وَضَرَبَ ٱللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ وَهُوَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'waḍaraba -llāhu maṯalan rajulayni ʾaḥaduhumā ʾabkamu lā yaqdiru ʿalā šayʾin wa huwa kallun ʿalā mawlāhu ʾaynamā yuwajjihhu lā yaʾti biḫayrin hal yastawī huwa wa man yaʾmuru bil-ʿadli wa huwa ʿalā ṣirāṭin mustaqīmin', 'Allah, (birbirine) zıt iki adam misali verdi: Biri dilsizdir, hiçbir şeye gücü yetmez ve efendisine bir yüktür; nereye gönderse bir hayır getiremez. Diğeri de adaletle emreden ve dosdoğru yol üzere bulunan kimse ile bir midir?'),
(16, 77, 14, 275, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wa lil-lāhi ġaybu s-samāwāti wal-arḍi wa mā amru s-sāʿati illā kalamḥi l-baṣari aw huwa aqrabu ʾinna llāha ʿalā kulli šayʾin qadīrun', 'Göklerin ve yerin gaybı/gizli olanı Allah''a aittir. Kıyamet (anının) emri, göz kırpması gibi veya daha yakından başkası değildir. Şüphesiz Allah, her şeye hakkıyla gücü yetendir.'),
(16, 78, 14, 275, 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـًٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ لَعَلَّكُمْ تَشْكُرُونَ', 'wa-llāhu ʾakhrajakum min buṭūni ʾummahātikum lā taʿlamūna šayʾan wa-jaʿala lakumu s-samʿa wa-l-ʾabṣāra wa-l-ʾafʾidata laʿallakum taškurūna', 'Allah sizi analarınızın karnından, hiçbir şey bilmezken çıkardı ve şükretmeniz için size kulaklar, gözler ve gönüller verdi.'),
(16, 79, 14, 275, 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'Elem yeraw ilā ṭ-ṭayri musakhkharātin fī jawwi s-samāʾi Mā yumsikuhunna illā Allāhu Inna fī dhālika laʾāyātin liqawmin yuʾminūna', 'Gök boşluğunda (belli bir düzene göre) uçurulan kuşları görmüyorlar mı? Onları ancak Allah tutuyor. Şüphesiz bunda iman eden bir kavim için nice deliller vardır.'),
(16, 80, 14, 276, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًا وَمَتَٰعًا إِلَىٰ حِينٍ', 'wa-llāhu jaʿala lakum min buyūtikum sakanan wa-jaʿala lakum min julūdi l-anʿāmi buyūtan tastakhiffūnahā yawma ẓaʿnikum wa-yawma iqāmatikum wa-min aṣwāfihā wa-awbārihā wa-ashʿārihā athāthan wa-matāʿan ilā ḥīnin', 'Allah, evlerinizi sizin için birer mesken kıldı. Yine Allah, (bazı) hayvan derilerinden size, hem göçlerinizde hem de yurtlarınızda (hafifçe) taşıyabileceğiniz evler (yapma imkânı) ve onların yünlerinden, yumoşlarından ve kıllarından da bir süreye kadar (yararlanacağınız) ev eşyası ve giyim eşyası kıldı.'),
(16, 81, 14, 276, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلًا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَٰنًا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', 'wa-llāhu jaʿala lakum mimmā khalaqa ẓilālan wa-jaʿala lakum mina l-jibāli aknānan wa-jaʿala lakum sarābīla taqīkumū l-ḥarra wa-sarābīla taqīkum baʾsakum kadhālika yutimmu niʿmatahū ʿalaykum laʿallakum tuslimūn', 'Allah, yarattığı şeylerden size gölgeler kıldı ve dağlarda sizin için barınaklar kıldı ve sizi sıcaktan koruyacak elbiseler ve savaş gücünüzden (koruyacak) elbiseler kıldı. İşte O, üzerinize nimetini böyle tamamlar. Umulur ki siz teslim olursunuz.'),
(16, 82, 14, 276, 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ٱلْمُبِينُ', 'fa-in tawallaw fa-innamā ʿalayka l-balāghu l-mubīn', 'Eğer yüz çevirirlerse, o zaman sana düşen sadece apaçık bir tebliğdir.'),
(16, 83, 14, 276, 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَٰفِرُونَ', 'yaʿrifūna niʿmata llāhi ṯumma yunkirūnahā waʾakṯaruhumu lkāfirūna', 'Onlar, Allah''ın nimetini bilirler, sonra da onu inkâr ederler. Onların çoğu kâfirdir.'),
(16, 84, 14, 276, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', 'wa-yawma nabʿathu min kulli ummatin shahīdan thumma lā yuʾdhnū lilladhīna kafarū wa-lā hum yustaʿtabūna', 'Her ümmetten bir şahit getireceğimiz ve (o zaman) inkâr edenlere (özür beyan etme) izni verilmeyeceği ve onlardan (rızâya uygun şekilde) hoşnutluk da istenmeyeceği günü (düşün)!'),
(16, 85, 14, 276, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', 'wa-idhā raʾā alladhīna ẓalamū al-ʿadhāba falā yukhaffafu ʿanhum walā hum yunẓarūn', 'Zalimler azabı gördükleri zaman, artık onlardan azap hafifletilmez ve onlara mühlet de verilmez.'),
(16, 86, 14, 276, 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ', 'wa-ʾidhā raʾā ʾalladhīna ʾashrakū shurakāʾahum qālū rabbanā hāʾulāʾi shurakāʾunā ʾalladhīna kunnā nadʿū min dūnika fa-ʾalqaw ʾilayhimu l-qawla ʾinnakum lakādhibūna', 'Koştu koşanlar, ortakları sandıkları şeyleri gördükleri zaman: "Rabbimiz! Bunlar, Senden başka taptığımız ortaklarımızdır" dediler. Fakat ortakları onlara: "Siz mutlaka yalancısınızdır" diye söz atarlar.'),
(16, 87, 14, 276, 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'wa-alqaw ilā allāhi yawmaʾiḏi n-salama wa-ḍalla ʿanhum mā kānū yaftarūna', 'Ve o gün Allah''a teslimiyetlerini arz ederler ve uydurmakta oldukları şeyler onlardan kaybolup gider.'),
(16, 88, 14, 277, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَٰهُمْ عَذَابًا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', 'alladhīna kafarū wa ṣaddū ʿan sabīli llāhi zidnāhum ʿadhāban fawqa l-ʿadhābi bimā kānū yufsidūna', 'Onlar ki inkâr ettiler ve Allah''ın yolundan alıkoydular; biz de bozgunculuk yapmaları yüzünden azap üstüne azap artırdık.'),
(16, 89, 14, 277, 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَٰبَ تِبْيَٰنًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ', 'wa-yawma nabʿathu fī kulli ummatin shahīdan ʿalayhim min anfusihim wa-jiʾnā bika shahīdan ʿalā hāʾulāʾi wa-nazzalnā ʿalayka l-kitāba tibyānan li-kulli shayʾin wa-hudan wa-raḥmatan wa-bushrā lil-muslimīn', 'Her ümmetten, kendilerine karşı bir şahit getireceğimiz ve seni de onlara karşı şahit olarak getireceğimiz günü (hatırla). Sana kitabı, her şeyi açıklayan bir yol gösterici, bir rahmet ve müslümanlar için bir müjde olarak indirdik.'),
(16, 90, 14, 277, 'إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'inna Allāha yaʾmuru bil-ʿadli wal-iḥsāni wa-ītāʾi dhīl-qurbā wa-yanhā ʿanil-faḥshāʾi wal-munkari wal-baghyi yaʿiẓukum laʿallakum tadkkarūn', 'Şüphesiz Allah, adaleti, iyilik yapmayı, yakınlara yardım etmeyi emreder. Hayâsızlığı, fenalığı ve azgınlığı da yasaklar. O, düşünesiniz diye size öğüt veriyor.'),
(16, 91, 14, 277, 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', 'wa-awfū bi-ʿahdi-llāhi ʾidhā ʿāhadtum wa-lā tanquḍū-l-ʾaymāna baʿda tawkīdihā wa-qad jaʿaltumu-llāha ʿalaykum kafīlan ʾinna-llāha yaʿlamu mā tafʿalūn', 'Allah ile ahitleştiğinizde O''nun ahdine vefâ edin. Anlaşmalarınızı pekiştirdikten sonra yeminlerinizi bozmayın. Oysa Allah''ı üzerinize kefil kılmışsınızdır. Şüphesiz Allah, yaptıklarınızı bilmektedir.'),
(16, 92, 14, 277, 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَٰثًا تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'wa lā takūnū ka-l-latī naqaḍat ġazlahā min baʿdi quwwatin ankāṯan tattahiḏūna aymānakum daḵalan baynakum an takūna ummatun hiya arbā min ummah innamā yablūkumū llāhu bihī wa la-yubayyinanna lakum yawma l-qiyāmati mā kuntum fīhi taḵtalifūn', 'Yeminlerinizi, kendisini (ipliğini) iyice eğirdikten sonra, bozan bir kadın gibi (olmayınız). Bir ümmet diğer bir ümmetten (sayıca) daha çok olduğu için, yeminlerinizi aranızda fesat aleti edinirsiniz. Allah bununla sizi ancak imtihan eder. Ve elbette, hakkında ihtilafa düşmekte olduğunuz şeyleri, kıyamet günü sizin için mutlaka açıklayacaktır.'),
(16, 93, 14, 277, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', 'wa-law shāʾa -llāhu la-jaʿalakum ummatan wāḥidatan wa-lākin yuḍillu man yashāʾu wa-yahdī man yashāʾu wa-la-tusʾalunna ʿammā kuntum taʿmalūna', 'Allah dileseydi sizi tek bir ümmet yapardı. Fakat dilediğini saptırır, dilediğini de doğru yola iletir. Ve yapmakta olduklarınızdan mutlaka sorulacaksınız.'),
(16, 94, 14, 278, 'وَلَا تَتَّخِذُوٓا۟ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ', 'walā tattakhidhū aimānakum dakhālan baynakum fatazilla qadamun baʿda thubūtihā watadhūqū as-sūʾa bimā ṣadadtum ʿan sabīli Allāhi walakum ʿadhābun ʿaẓīmun', 'Yeminlerinizi aranızda aldatma vasıtası yapmayın. Öyle yaparsanız, ayaklarınız (dînî) sebatından sonra kayar ve Allah yolundan sapmanız sebebiyle kötülüğü tadarsınız. Sizin için büyük bir azap da vardır.'),
(16, 95, 14, 278, 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'Ve lā teşterū biʿahdi Allāhi śemenen ḳalīlen İnnemā ʿinde Allāhi huve ḫayrun lekum İn kuntum taʿlemūn', 'Allah''ın ahdini az bir değere satmayın. Şüphesiz Allah katında olan, eğer bilirseniz sizin için daha hayırlıdır.'),
(16, 96, 14, 278, 'مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٍ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'mā ʿindakum yanfadu wa mā ʿinda llāhi bāqin wa la-najziyanna l-ladhīna ṣabarū ajrahum bi-ʾaḥsani mā kānū yaʿmalūn', 'Sizin yanınızdaki tükenir, Allah''ın yanındaki ise bakidir. Sabredenlere, yapmakta olduklarından daha güzelini mükâfat olarak vereceğiz.'),
(16, 97, 14, 278, 'مَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'man ʿamila ṣāliḥan min dhakarin aw unthā wa-huwa muʾminun fa-la-nuḥyiyannahū ḥayātan ṭayyibatan wa-la-najziyannahum ajrahum bi-ʾaḥsani mā kānū yaʿmalūn', 'Erkek veya kadın, her kim de mü''min olarak salih amel işlerse, onu mutlaka (dünyada) güzel bir hayat ile yaşatırız ve onlara yapmakta oldukları şeylerin daha güzeliyle ecir veririz.'),
(16, 98, 14, 278, 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'fa-iḏā qaraʾta l-qurʾāna fa-staʿiḏ bi-llāhi mina +...+ š-šayṭāni r-rajīmi', 'Kur''an okuduğun zaman, o recmedilmiş (kovulmuş) şeytandan Allah''a sığın.'),
(16, 99, 14, 278, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'ʾinnahu laysa lahu sulṭānun ʿalā alladhīna ʾāmanū wa ʿalā rabbihim yatawakkalūn', 'Şüphesiz ki o (şeytanın) iman edenler ve Rablerine güvenenler üzerinde bir nüfuzu yoktur.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(16, 100, 14, 278, 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', 'innamā sulṭānuhu ʿalā alladhīna yatawallawnahu wal-ladhīna hum bihi mushrikūn', 'Şüphesiz onun gücü, ancak ona (Allah''a) ortak koşanların ve onun kullarına karşı üstünlük taslayanların üzerindedir.'),
(16, 101, 14, 278, 'وَإِذَا بَدَّلْنَآ ءَايَةً مَّكَانَ ءَايَةٍ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'wa-ʾidhā baddalnā ʾāyatan makāna ʾāyatin wa-llāhu ʾaʿlamu bimā yunazzilu qālū ʾinnamā ʾanta muftarin bal ʾaktharuhum lā yaʿlamūna', 'Bir âyeti başka bir âyetle değiştirdiğimizde -ki Allah ne indirdiğini daha iyi bilir- "Sen ancak uyduruyorsun!" dediler. Hayır, onların çoğu bilmiyorlar.'),
(16, 102, 14, 278, 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ', 'qul nazzalahū rūḥu l-qudusi min rabbika bil-ḥaqqi liyuthabbita lladhīna āmānū wa hudan wa bushra lil-muslimīna', 'De ki: "Onu, iman edenleri sağlamlaştırmak ve Müslümanlara bir hidayet ve müjde olmak üzere, Rabbin tarafından hak ile Ruhu''l-Kudüs indirdi."'),
(16, 103, 14, 279, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّ وَهَٰذَا لِسَانٌ عَرَبِىٌّ مُّبِينٌ', 'Ve lekad na''lemu ennehum yekūlūne innemā yu''allimuhū beşerun lisānullezī yulhidūne ileyhi a''cemiyyun vehāzā lisānun arabiyyun mubīnun', 'Andolsun ki biz, onların: “Ona ancak bir insan öğretiyor” dediklerini biliyoruz. İftira ettikleri kimsenin dili yabancıdır, bu ise apaçık Arapça bir dildir.'),
(16, 104, 14, 279, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ʾinna lladhīna lā yuʾminūna bi-ʾāyāti llāhi lā yahdīhi llāhu wa-lahum ʿadhābun ʾalīmun', 'Şüphesiz Allah''ın ayetlerine inanmayanları Allah doğru yola eriştirmez ve onlara elem dolu bir azap vardır.'),
(16, 105, 14, 279, 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰذِبُونَ', 'innamā yaftarī l-kadhiba lladhīna lā yuʾminūna bi-ʾāyāti llāhi wa-ʾulāʾika humu l-kādhibūna', 'Yalanı ancak Allah''ın ayetlerine inanmayanlar uydurur. İşte onlardır yalancılar.'),
(16, 106, 14, 279, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'man kafara billāhi min baʿdi īmānihi illā man ukriha wa qalbuhu muṭmaʾinnun bil-īmāni walākin man ṣaraḥa bil-kufri ṣadran fa ʿalayhim ghaḍabun minallāhi wa lahum ʿadhābun ʿaẓīmun', 'Kim iman ettikten sonra Allah''ı inkâr ederse -kalbi imanla dolu olduğu halde (inkâra) zorlananlar hariç- fakat kim inkâra göğüs açarsa, işte onların üzerine Allah''tan bir gazap vardır ve onlara büyük bir azap vardır.'),
(16, 107, 14, 279, 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْءَاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'dhālika bi-ʾannahumu-staḥabbū-l-ḥayāta-d-dunyā ʿalā-l-ʾākhirah wa-ʾanna-llāha lā yahdī-l-qawma-l-kāfirīn', 'Bu böyledir, çünkü onlar dünya hayatını ahiret hayatına tercih ettiler ve Allah''ın kâfirler topluluğunu doğru yola iletmeyeceği gerçeği (yüzündendir).'),
(16, 108, 14, 279, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'ʾulāʾika lladhīna ṭabaʿa ʾllāhu ʿalā qulūbihim wa-samʿihim wa-ʾabṣārihim wa-ʾulāʾika humu l-ghāfilūn', 'İşte onların, kalplerini, kulaklarını ve gözlerini Allah mühürlemiştir. Onlar gaflete düşenlerin ta kendileridir.'),
(16, 109, 14, 279, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْخَٰسِرُونَ', 'lā jarama ʾannahum fī l-ʾākhirati humu l-khāsirūn', 'Şüphesiz onlar, ahirette en çok ziyana uğrayanlardır.'),
(16, 110, 14, 279, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', 'thumma inna rabbaka lilladhīna hājarū min baʿdi mā futinū thumma jāhadū waṣabarū inna rabbaka min baʿdihā laghafūrun raḥīmun', 'Sonra, eziyet gördükten sonra hicret eden, ardından da cihad edip sabreden kimselerin Rabbi, şüphesiz onların bu yaptıklarından sonra da çok bağışlayıcı, çok merhamet edicidir.'),
(16, 111, 14, 280, 'يَوْمَ تَأْتِى كُلُّ نَفْسٍ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 'yawma taʾtī kullu nafsin tujādilu ʿan nafsihā wa tuwaffā kullu nafsin mā ʿamilat wa hum lā yuẓlamūna', 'O gün, her nefis kendi kendini savunarak gelir ve her nefse yaptığı şeylerin karşılığı tam olarak ödenir; onlara haksızlık edilmez.'),
(16, 112, 14, 280, 'وَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', 'waḍaraba -llāhu mathalan qaryatan kānat ʾāminatan muṭmaʾinnatan yaʾtīhā rizquhā raghadan min kulli makānin fakafarat bi-ʾanʿumi -llāhi fa-ʾadhāqahā -llāhu libāsa -l-jūʿi wa-l-khawfi bimā kānū yafnaʿūn', 'Allah, bir şehri misal verdi: Burası güvenli ve huzurlu idi, rızkı da her taraftan bol bol geliyordu. Sonra Allah''ın nimetlerine nankörlük ettiler. Allah da onlara yaptıklarından dolayı açlık ve korku elbisesini tattırdı.'),
(16, 113, 14, 280, 'وَلَقَدْ جَآءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَٰلِمُونَ', 'Ve lekad câe-hum rasûlun min-hum fe-kezzebû-hu fe-eḣażehumu-l’ażâbu ve hum zâlimûn(e)', 'Andolsun ki onlara kendilerinden bir elçi geldi de onu yalanladılar. Bunun üzerine onlar zalimler iken azap onları yakaladı.'),
(16, 114, 14, 280, 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'fakulū mimmā razaqakumullāhu ḥalālan ṭayyibā wa-shkurū niʿmata Allāhi in kuntum iyyāhu taʿbudūn', 'Artık Allah''ın size verdiği helal ve temiz rızıklardan yiyin. Eğer O''na kulluk ediyorsanız, Allah''ın nimetine şükredin.'),
(16, 115, 14, 280, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'innamā ḥarrama ʿalaykumu l-maytata wa-d-dama wa-laḥma l-khinzīri wa mā uhilla li-ghayri llāhi bihī fa-mani ḍṭurra ghayra bāghin wa-lā ʿādin fa-inna llāha ghafūrun raḥīmun', 'O, size ancak leşi, kanı, domuz etini ve Allah''tan başkası adına kesileni haram kılmıştır. Ama kim darda kalırsa, -bağzı ve haddi aşmamak şartıyla- şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir.'),
(16, 116, 14, 280, 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌ وَهَٰذَا حَرَامٌ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 'wa lā taqūlū limā taṣifu ʾalsinatu-kumu l-kaḏiba hāḏā ḥalālun wa-hāḏā ḥarāmun li-taftirū ʿalā llāhi l-kaḏiba ʾinna llaḏīna yaftarūna ʿalā llāhi l-kaḏiba lā yufliḥūna', 'Dillerinizin yalan yere nitelediği şeye ''bu helaldir, şu haramdır'' demeyin. Çünkü Allah''a yalan isnad etmiş olursunuz. Şüphesiz Allah''a yalan isnad edenler kurtuluşa ermezler.'),
(16, 117, 14, 280, 'مَتَٰعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'matāʿun qalīlun wa lahum ʿadhābun alīmun', 'Az bir yararlanmadır ve onlar için elem dolu bir azap vardır.'),
(16, 118, 14, 280, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'wa ʿalā alladhīna hādū ḥarramnā mā qaṣaṣnā ʿalayka min qablu wa mā ẓalamnāhum walākin kānū anfusahum yaẓlimūn', 'Yahudilere, daha önce sana anlattığımız şeyleri haram kıldık. Onlara biz zulmetmedik, fakat onlar kendi kendilerine zulmediyorlardı.'),
(16, 119, 14, 281, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', 'thumma inna rabbaka lilladhīna ʿamilū s-sūʾa bijahālatin thumma tābū min baʿdi dhālika waʾaṣlaḥū inna rabbaka min baʿdihā laghafūrun raḥīmun', 'Sonra, şüphesiz Rabbin, bilgisizlik (veya günah) sebebiyle kötülük yapıp da ardından tevbe eden ve halini düzelten kimselere gelince, şüphesiz Rabbin, bundan sonra da çok bağışlayıcıdır, çok merhametlidir.'),
(16, 120, 14, 281, 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', 'inna ibrāhīm kāna ummatan qānitā lillāhi ḥanīfā wa-lam yaku mina l-mušrikīn', 'Şüphesiz İbrahim, Allah''a itaat eden, hakka yönelen bir önderdi ve müşriklerden değildi.'),
(16, 121, 14, 281, 'شَاكِرًا لِّأَنْعُمِهِ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'shākirāⁿ li-ʾanʿumihi ijtabāhu wa-hadāhu ʾilā ṣirāṭim mustaqīm', 'Allah''ın nimetlerine şükredici olarak onu seçmiş ve onu dosdoğru yola iletmiştir.'),
(16, 122, 14, 281, 'وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةً وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'wa ʾātaynāhu fī d-dunyā ḥasanatan wa ʾinnahu fī l-ʾākhirati lami-n aṣ-ṣāliḥīn', 'Biz ona dünyada da bir güzellik verdik. Şüphesiz o, ahirette de salihlerdendir.'),
(16, 123, 14, 281, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'thumma awḥaynā ʾilayka ʾani ʾttabiʿ milleta ʾibrāhīma ḥanīfan wamā kāna mina l-mušrikīn', 'Sonra da sana: "Hakka yönelen, müşriklerden olmayan İbrahim''in dinine uy!" diye vahyettik.'),
(16, 124, 14, 281, 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'innamā juʿila s-sabtu ʿalā lladhīna ḵtalafū fīhi wa-inna rabbaka layaḥkumu baynahum yawma l-qiyāmati fīmā kānū fīhi yaḵtalifūn', 'Şüphesiz Cumartesi (yasağı), sadece onun hakkında anlaşmazlığa düşenlerin üzerine farz kılındı. Ve şüphesiz Rabbin, anlaşmazlığa düştükleri hususlarda kıyamet günü onların arasında (doğru olanı) hükmedecektir.'),
(16, 125, 14, 281, 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'udʿu ilā sabīli rabbika bil-ḥikmati wal-mawʿiẓati l-ḥasanah wa jādilhum bi-llatī hiya aḥsan ʾinna rabbaka huwa ʾaʿlamu biman ḍalla ʿan sabīlihī wa huwa ʾaʿlamu bil-muhtadīn', 'Rabbinin yoluna hikmetle, güzel öğütle davet et ve onlarla en güzel şekilde mücadele et. Şüphesiz Rabbin, kendi yolundan sapanı en iyi bilendir ve hidayete erenleri de en iyi bilendir.'),
(16, 126, 14, 281, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّٰبِرِينَ', 'wa-ʾin ʿāqabtum fa-ʿāqibū bi-mithli mā ʿūqibtum bihi wa-la-ʾin ṣabartum la-huwa khayrun liṣ-ṣābirīn', 'Eğer ceza verecek olursanız, size yapılanın misliyle ceza verin. Ama sabrederseniz, elbette bu, sabredenler için daha hayırlıdır.'),
(16, 127, 14, 281, 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', 'waṣbir wa mā ṣabruka illā billāh walā taḥzan ʿalayhim walā taku fī ḍayqin mimmā yamkurūn', 'Sabret; senin sabrın da ancak Allah''ın yardımıyladır. Onlardan dolayı üzülme ve onların kurmakta oldukları tuzaklardan dolayı sıkıntıya düşme.'),
(16, 128, 14, 281, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', 'ʾinna ʾallāha maʿa ʾallazīna ʾttaqaw wa-ʾallazīna hum muḥsinūna', 'Şüphesiz Allah, kendisinden sakınanlarla ve iyilik yapanlarla beraberdir.'),
(17, 1, 15, 282, 'سُبْحَٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَٰتِنَآ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'subḥāna lladhī asrā biʿabdihi laylan mina l-masjidi l-ḥarāmi ilá l-masjidi l-ʾaqṣā lladhī bāraknā ḥawlahū linuriyahu min ʾāyātinā ʾinnahu huwa s-samīʿu l-baṣīr', 'Bir kulu''nu (Muhammed''i) bir gece Mescid-i Haram''dan, çevresini bereketli kıldığımız Mescid-i Aksa''ya (Kudüs''e) götürmesi, O''nun kudret ve azametindendir. Gerçekten O, her şeyi işiten, her şeyi gören''dir.'),
(17, 2, 15, 282, 'وَءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًا', 'wa ʾātaynā mūsā l-kitāba wa jaʿalnāhu hudan li-banī ʾisrāʾīla ʾallā tattakhidhū min dūnī wakīlan', 'Musa''ya Kitap verdik ve onu İsrailoğulları için bir hidayet rehberi kıldık. (Ve şöyle emrettik): Benden başkasını vekil edinmeyin.'),
(17, 3, 15, 282, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ إِنَّهُۥ كَانَ عَبْدًا شَكُورًا', 'dhurriyyata man ḥamalnā maʿa nūḥin ʾinnahu kāna ʿabdan shakurā', 'Ey Nuh''un gemisinde taşıdığımız kimselerin zürriyeti! Şüphesiz o çok şükreden bir kuldu.'),
(17, 4, 15, 282, 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّا كَبِيرًا', 'wa qaḍaynā ilā banī isrāʾīla fī l-kitābi latufsidunna fī l-arḍi marratayni walataʿlunna ʿuluwwan kabīran', 'İsrailoğulları''na Kitap''ta (şöyle) hükmettik: ''Yemin olsun, siz yeryüzünde iki defa bozgunculuk çıkaracaksınız ve büyük bir kibre kapılacaksınız!'''),
(17, 5, 15, 282, 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَآ أُو۟لِى بَأْسٍ شَدِيدٍ فَجَاسُوا۟ خِلَٰلَ ٱلدِّيَارِ وَكَانَ وَعْدًا مَّفْعُولًا', 'fa-idhā jāʾa waʿdu ʾūlāhumā baʿathnā ʿalaykum ʿibādan lanā ʾūlī baʾsin shadīdin fajāsū khilāla ʾd-diyāri wa-kāna waʿdan mafʿūlan', 'Onlardan birincisinin (vaad edilen azabın) zamanı gelince, üzerinize bizim tarafımızdan, çok kuvvetli savaşçılar (olan düşmanları) gönderdik. Onlar (şehirlerinizin) içine kadar sokuldular. Bu, yerine getirilmesi gereken bir vaad idi.'),
(17, 6, 15, 282, 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَٰكُم بِأَمْوَٰلٍ وَبَنِينَ وَجَعَلْنَٰكُمْ أَكْثَرَ نَفِيرًا', 'thumma ra-dadnā lakumu l-kar-rata ʿalayhim wa-amdadnākum bi-amwālin wa-banīna wa-jaʿalnākum akthara nafīran', 'Sonra size, onlara karşı tekrar başarı verdik; mallar ve oğullar ile sizi destekledik ve sayınızı artırdık.'),
(17, 7, 15, 282, 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ وَإِنْ أَسَأْتُمْ فَلَهَا فَإِذَا جَآءَ وَعْدُ ٱلْءَاخِرَةِ لِيَسُۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', 'in aḥsantum aḥsantum li-ʾanfusikum wa-ʾin ʾasaʾtum fa-lahā fa-ʾiḏā jāʾa waʿdu l-ʾāḵirati li-yasūʾū wujūhakaum wa-li-yadḵulū l-masjida kamā daḵalūhu ʾawwala marratin wa-li-yutabbirū mā ʿalaw taltbīran', 'Eğer iyilik ederseniz, kendi iyiliğiniz için etmiş olursunuz; eğer kötülük ederseniz, yine kendi aleyhinizedir. Nihayet ikinci (vaadimiz) geldiğinde, (yüzlerinizi) perişan etmeleri, ilkinde girdikleri gibi mescide (oraya) girmeleri ve el-ilerinde tuttukları her şeyi tamamen tahrip etmeleri için (onları gönderdik).'),
(17, 8, 15, 283, 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ وَإِنْ عُدتُّمْ عُدْنَا وَجَعَلْنَا جَهَنَّمَ لِلْكَٰفِرِينَ حَصِيرًا', 'ʿasā rabbukum an yarḥamakum wa-in ʿudtum ʿudnā wa-jaʿalnā jahannama lil-kāfirīna ḥaṣīran', 'Rabbinizin, size merhamet etmesi umulur. Eğer (yine) fesatlığa dönerseniz, Biz de (sizi) ateşe döndürürüz ve biz cehennemi kâfirler için bir zindan kıldık.'),
(17, 9, 15, 283, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا كَبِيرًا', 'ʾinna hādhā l-qurʾāna yahdī lillatī hiya ʾaqwamu wa yubashshiru l-muʾminīna lladhīna yaʿmalūna ṣ-ṣāliḥāti ʾanna lahum ʾajran kabīran', 'Şüphesiz bu Kur''an, insanları en doğru yola iletir ve salih amel işleyen müminlere, kendileri için büyük bir ecir olduğunu müjdeler.'),
(17, 10, 15, 283, 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', 'waʾanna alladhīna lā yuʾminūna bil-ʾākhirati ʾaʿtadnā lahum ʿadhāban ʾalīman', 'Ahiret''e inanmayanlar için ise elem dolu bir azap hazırlamışızdır.'),
(17, 11, 15, 283, 'وَيَدْعُ ٱلْإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ وَكَانَ ٱلْإِنسَٰنُ عَجُولًا', 'wa yadʿu l-insānu bi-sh-sharri duʿāʾahu bi-l-khayri wa kāna l-insānu ʿajūlan', 'İnsan, hayrı istediği gibi şerri de ister. İnsan çok acelecidir.'),
(17, 12, 15, 283, 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةً لِّتَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ وَكُلَّ شَىْءٍ فَصَّلْنَٰهُ تَفْصِيلًا', 'wa jaʿalnā l-layla wa-n-nahāra ʾāyatayni fa-maḥawnā ʾāyata l-layli wa jaʿalnā ʾāyata n-nahāri mubṣiratan li-tabtaḡū faḍlan min rabbikum wa li-taʿlamū ʿadada s-sinīna wa-l-ḥisāba wa kulla šayʾin faṣṣalnāhu tafṣīlan', 'Geceyi ve gündüzü iki ayet (delil) kıldık. Gece ayetini (karanlığını) silip gündüz ayetini (aydınlığını) ise Rabbinizden bir fazl (lütuf) aramanız ve yılların sayısını ve hesabı bilmeniz için aydınlatıcı yaptık. Ve her şeyi ayrı ayrı açıkladık.'),
(17, 13, 15, 283, 'وَكُلَّ إِنسَٰنٍ أَلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِى عُنُقِهِۦ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَٰمَةِ كِتَٰبًا يَلْقَىٰهُ مَنشُورًا', 'wa kulla insānin alzamnāhu ṭāʾirahu fī ʿunuqihī wa nukhriju lahu yawma l-qiyāmati kitāban yalqāhu manshūran', 'Her insanın amellerini boynuna astık. Kıyamet günü, önünde açık olarak bulacağı bir kitap çıkarırız.'),
(17, 14, 15, 283, 'ٱقْرَأْ كِتَٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًا', 'iqraʾ kitābaka kafā bi-nafsika l-yawma ʿalayka ḥasībā', 'Kitabını oku! Bugün sana hesap sorucu olarak kendi nefsin yeter.'),
(17, 15, 15, 283, 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا', 'mani-htedā fe-ennemā yahtedī li-nefsihī ve-men ḍalla fe-ennemā yaḍillu ‘aleyhā ve-lā teziru wāziratun wizra ukhrā ve-mā kunnā mu‘edh’ibīne ḥattā neba‘tha rasūlā', 'Kim doğru yolu bulursa, kendi iyiliği için bulmuştur. Kim de saparsa, kendi zararına sapmıştır. Hiçbir günahkar, başka bir günahkarın günah yükünü taşımaz. Biz, bir peygamber göndermedikçe azap edici değiliz.'),
(17, 16, 15, 283, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيرًا', 'wa ʾiḏā ʾaradnā ʾan nuhlika qaryatan ʾamar’nā mutrafīhā fefasaqū fīhā faḥaqqa ʿalayhā l-qawlu fadammarnāhā tadmīran', 'Bir şehri helak etmek istediğimizde, onun refah içinde yaşayan kodamanlarına (itaati) emrederiz de orada yoldan çıkarlar. Böylece o şehir aleyhine (helak) hükmü hak olur da biz de onu kökünden imha ederiz.'),
(17, 17, 15, 283, 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'wa kam ahlaknā mina l-qurūni min baʿdi nūḥin wa kafā birabbika bidhunūbi ʿibādihī khabīran baṣīran', 'Nuh''tan sonra nice nesilleri helak ettik. Kullarının günahlarından Rabbinin haberdar ve görüp-bilici olması yeter.'),
(17, 18, 15, 284, 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًا مَّدْحُورًا', 'man kāna yurīdu l-ʿājilata ʿajjelnā lahu fīhā mā našāʾu liman nurīdu ṯumma jaʿalnā lahu jahannama yaṣlāhā maḏmūman maḏḥūran', 'Kim bu geçici dünyayı isterse, ona dilediğimizi, dilediğimiz kimseye hemen veririz. Sonra da onu, kınanmış ve kovulmuş olarak cehenneme sokarız.'),
(17, 19, 15, 284, 'وَمَنْ أَرَادَ ٱلْءَاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًا', 'wa-man ʾarāda l-ʾākhirata wa-saʿā lahā saʿyahā wa-huwa muʾminun fa-ʾulāʾika kāna saʿyuhum mashkūran', 'Kim de ahireti ister ve ona inanarak gereğince çalışırsa, işte onların çalışmaları makbule geçmiş olacaktır.'),
(17, 20, 15, 284, 'كُلًّا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', 'kullan numiddu hāʾulāʾi wa hāʾulāʾi min ʿaṭāʾi rabbika wa mā kāna ʿaṭāʾu rabbika maḥẓūrā', 'Her birine, Rabbinin nimetinden uzatırız. Rabbinin nimeti kısıtlanmış değildir.'),
(17, 21, 15, 284, 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ وَلَلْءَاخِرَةُ أَكْبَرُ دَرَجَٰتٍ وَأَكْبَرُ تَفْضِيلًا', 'unẓur kayfa faḍḍalnā baʿḍahum ʿalā baʿḍin walalʾākhiratu ʾakbaru darajātin waʾakbaru tafḍīlan', 'Bak, onlardan bir kısmını diğerlerine nasıl üstün kıldık! Elbette ahiret, dereceler bakımından daha büyüktür ve fazlca daha büyüktür.'),
(17, 22, 15, 284, 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا', 'lā tajʿal maʿa llāhi ilāhan ʾākhara fataqʿada madhmūman makhdhūlan', 'Allah ile beraber başka bir ilah edinme; sonra kınanmış ve çaresiz kalmış olursun.'),
(17, 23, 15, 284, 'وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا', 'wa qaḍā rabbuka allā taʿbudū illā iyyāhu wa bil-wālidayni iḥsānan immā yablughanna ʿindaka l-kibara aḥaduhumā aw kilāhumā falā taqul lahumā uffin walā tanharhumā wa qul lahumā qawlan karīman', 'Rabbin, kendisinden başkasına asla tapmamayı ve ana babaya iyilik etmeyi emretti. Eğer onlardan biri veya her ikisi senin yanında yaşlılığa ulaşırsa, onlara:“Öf!” bile deme; onları azarlama; onlara karşı nazik ve güzel söz söyle.'),
(17, 24, 15, 284, 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا', 'wa-khfiḍ lahumā janāḥa dh-dhulli mina r-raḥmah wa-qul rabbi rḥamhumā kamā rabbayāni ṣaghīran', 'Onlara, merhamet ederek alçakgönüllülük kanadını ger ve şöyle de: "Rabbim! Onlar, küçüklüğümde bana merhamet ettikleri gibi sen de onlara merhamet et."'),
(17, 25, 15, 284, 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًا', 'rabbukum aʿlamu bimā fī nufūsikum in tūnū ṣāliḥīn faʾinnahu kāna lilʾawwābīna ġafūrā', 'Rabbiniz, sizin kalblerinizdekini en iyi bilendir. Eğer siz iyi kişiler olursanız, şüphesiz O, tevbe edenleri bağışlayıcıdır.'),
(17, 26, 15, 284, 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', 'wa-ʾāti ḏā l-qurbā ḥaqqahū wa-l-miskīna wa-bna s-sabīli wa-lā tubażẓir tabẓīran', 'Yakınlığı olanlara haklarını ver; düşkünlere ve yolcuya da. Bütün bunları savurganca harcama.'),
(17, 27, 15, 284, 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَٰطِينِ وَكَانَ ٱلشَّيْطَٰنُ لِرَبِّهِۦ كَفُورًا', 'ʾinna l-mubadhdhirīna kānū ʾikhwāna ʾsh-shayāṭīn wa kāna ʾsh-shayṭānu li-rabbihī kafūrā', 'Çünkü savurganlar, şeytanların kardeşleri idiler; şeytan ise Rabbine karşı çok nankördü.'),
(17, 28, 15, 285, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا', 'wa-immā tuʿriḍanna ʿanhumu ibtiġāʾa raḥmatin min rabbika terjūhā fa-qul lahum qawlan maysūran', 'Eğer Rabbinden umduğun bir rahmet sebebiyle onlardan yüz çevirecek olursan, o zaman onlara yumuşak bir söz söyle.'),
(17, 29, 15, 285, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا', 'wa lā tajʿal yadaka maghlūlatan ilā ʿunuqika wa lā tabsuth’hā kulla l-basṭi fataqʿuda malūman maḥsūrā', 'Elini boynuna bağlı (sıkı) kılma, hem de onu büsbütün açıp saçma. Sonra kınanmış ve eli sıkışık (perişan) bir halde oturakalırsın.'),
(17, 30, 15, 285, 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'inna rabbaka yabsutu r-rizqa liman yashaa''u wa yaqdiru innahu kana bi''ibadihi khabiran basiran', 'Şüphesiz Rabbin, dilediği kimin rızkını bollaştırır ve dilediğinin rızkını daraltır. Şüphesiz O, kullarının durumundan haberdardır, onları hakkıyla görmektedir.'),
(17, 31, 15, 285, 'وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقٍ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ إِنَّ قَتْلَهُمْ كَانَ خِطْـًٔا كَبِيرًا', 'wa lā taqtulū awlādakum khashyata imlāq naḥnu narzuquhum wa iyyākum inna qatlahum kāna khiṭʾan kabīran', 'Yoksulluk korkusuyla evlatlarınızı öldürmeyin. Onları da sizi de biz rızıklandırırız. Şüphesiz onları öldürmek büyük bir günahtır.'),
(17, 32, 15, 285, 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ إِنَّهُۥ كَانَ فَٰحِشَةً وَسَآءَ سَبِيلًا', 'wa lā taqrabū al-zinā ʾinnahu kāna fāḥiẗan wa sāʾa sabīlā', 'Zinaya yaklaşmayın. Çünkü o, çirkin bir hayâsızlık ve çok kötü bir yoldur.'),
(17, 33, 15, 285, 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَمَن قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰنًا فَلَا يُسْرِف فِّى ٱلْقَتْلِ إِنَّهُۥ كَانَ مَنصُورًا', 'wa lā taqtulū an-nafsa allatī ḥarrama Allāhu illā bil-ḥaqqi wa man qutila maẓlūman faqad jaʿalnā li-waliyyihi sulṭānan falā yusrif fī al-qatli innahu kāna manṣūran', 'Allah''ın haram kıldığı cana haksız yere kıymayın. Kim haksız yere öldürülürse, biz onun velisine (mirasçısına) bir yetki (hak) vermişizdir. Artık o, öldürmede aşırı gitmesin. Çünkü o, (zaten) yardıma mazhar olmuştur.'),
(17, 34, 15, 285, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ بِٱلْعَهْدِ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًا', 'wa lā taqrabū mal-yatīmi illā billatī hiya ʾaḥsanu ḥattā yabluġa ʾashuddahu wa ʾawfū bil-ʿahdi ʾinna al-ʿahda kāna masʾūlan', 'Yetimin malına, rüştüne erinceye kadar -ona en iyi şekilde yaklaşma dışında- dokunmayın. Ve ahde vefa gösterin. Çünkü ahde vefa, sorumluluğu gerektirir.'),
(17, 35, 15, 285, 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', 'wa-awfū l-kayla ʾidhā kiltum wa-zinū bi-l-qisṭāsi l-mustaqīmi dhālika khayrun wa-ʾaḥsanu taʾwīlan', 'Ölçtüğünüz zaman tam ölçün ve dosdoğru teraziyle tartın. Bu, hem hayırlı hem de sonuc (veya akıbet) bakımından daha güzeldir.'),
(17, 36, 15, 285, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًا', 'wa-lā taqfu mā laysa laka bihi ʿilmun ʾinna s-samʿa wa-l-baṣara wa-l-fuʾāda kullu ʾulāʾika kāna ʿanhu masʾūlan', 'Sana malum olmayan şeyin ardına düşme! Çünkü kulak, göz ve gönül, bunların hepsi sorumlu idi.'),
(17, 37, 15, 285, 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًا', 'wa-lā tamshi fī l-arḍi maraḥan ʾinnaka lan takhriqa l-arḍa wa-lan tablugha l-jibāla ṭūlan', 'Yeryüzünde böbürlenerek yürüme! Çünkü sen (yere) asla basamazsın ve boyca da dağlara asla ulaşamazsın.'),
(17, 38, 15, 285, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًا', 'kullu dhālika kāna sayyiʾuhu ʿinda rabbika makrūhan', 'Bütün bu sayılanlar, Rabbinin nezdinde sevimsiz (ve) çirkin şeyler idi.'),
(17, 39, 15, 286, 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًا مَّدْحُورًا', 'dhālika mimmāʾ awḥā ʾilayka rabbuka mina l-ḥikmah walā tajʿal maʿa llāhi ʾilāhan ʾākhara fatuʾlqā fī jahannama malūman madḥūrā', 'İşte bunlar, Rabbinin sana vahyettiği hikmetlerdir. Allah ile beraber başka bir ilâh uydurma ki, sonra kınanmış ve (rahmetinden) kovulmuş olarak cehenneme atılmayasın.'),
(17, 40, 15, 286, 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَٰٓئِكَةِ إِنَٰثًا إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا', 'ʾafaṣfākum rabbukum bil-banīna wattakhaḏa mina l-malāʾikati ʾināṯan ʾinnakum latqūlūna qawlan ʿaẓīman', 'Rabbiniz, erkek evlatları size seçip de melekleri dişiler mi edindi? Elbette siz, çok büyük sözler söylüyorsunuz.'),
(17, 41, 15, 286, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا', 'Ve lekad sarrafnâ fî hâzâ el-kurʾâni li yeẕẕekkerû ve mâ yezîduhum illâ nufûrâ', 'Andolsun ki Biz, bu Kur''an''da (hakikatleri) çeşitli şekillerde açıkladık ki düşünüp öğüt alsınlar. Oysa bu (açıklamalar), onların sadece nefretini artırır.'),
(17, 42, 15, 286, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌ كَمَا يَقُولُونَ إِذًا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًا', 'qul law kāna maʿahu ʾālihatun kamā yaqūlūn ʾidhan labtaghaw ʾilā dhī l-ʿarshi sabīlā', 'De ki: ''Eğer dedikleri gibi O''nunla beraber başka ilâhlar olsaydı, o zaman o zaman o Arş''ın sahibine bir yol ararlardı.'''),
(17, 43, 15, 286, 'سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا', 'subḥānahū wa taʿālā ʿammā yaqūlūna ʿuluwwan kabīrā', 'O, onların söylediklerinden çok yücedir, münezzehtir.'),
(17, 44, 15, 286, 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', 'tusabbihu lahu as-samāwātu as-sabʿu wa-l-arḍu wa-man fīhinna wa-in min shayʾin illā yusabbihu bi-ḥamdihi wa-lākin lā tafqahūna tasbīḥahum ʾinnahu kāna ḥalīman ġafūrā', 'Yedi gök, yer ve bunların içinde olan herkes O''nu tesbih eder. O''nu övgüyle tesbih etmeyen hiçbir şey yoktur. Ancak siz onların tesbihini anlamazsınız. O, halimdir, bağışlayıcıdır.'),
(17, 45, 15, 286, 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ حِجَابًا مَّسْتُورًا', 'wa ʾidhā qaraʾta l-qurʾāna jaʿalnā baynaka wa-bayna lladhīna lā yuʾminūna bi-l-ʾākhirati ḥijāban mastūrā', 'Sen Kur''an okuduğun zaman, seninle ahirete inanmayanların arasına gizleyici bir örtü koyarız.'),
(17, 46, 15, 286, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَٰرِهِمْ نُفُورًا', 'wa jaʿalnā ʿalā qulūbihim ʾakinatan ʾan yafqahūhu wa fī ʾādhānihim waqran wa ʾidhā dhakarta rabbaka fī l-qurʾāni waḥdahu wallaw ʿalā ʾadbārihim nufūran', 'Onların kalplerine, onu anlamalarını önleyecek perdeler ve kulaklarında bir ağırlık kıldık. Sen Kur''an''da sadece Rabbini andığında, onlar arkalarını dönüp nefret ederek uzaklaşırlar.'),
(17, 47, 15, 286, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', 'naḥnu ʾaʿlamu bimā yastamiʿūna bihi ʾidh yastamiʿūna ʾilayka wa-ʾidh hum najwā ʾidh yaqūlu ẓẓālimūna ʾin tattabiʿūna ʾillā rajulan masḥūrā', 'Onlar sana kulak verdiklerinde, onu ne şekilde dinlediklerini biz daha iyi biliriz. Kendi aralarında fısıldaştıklarında da (biliriz). O zalimler: "Siz ancak büyülenmiş bir adama uyuyorsunuz" derler.'),
(17, 48, 15, 286, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', 'unẓur kayfa ḍarabū laka l-ʾamthāl fa-ḍallū fa-lā yastaṭīʿūna sabīlā', 'Bak, sana nasıl örnekler verdiler de saptılar! Artık bir yol bulamayacaklardır.'),
(17, 49, 15, 286, 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', 'waqalū ʾaʾiḏā kunnā ʿiẓāman wa rufātan ʾainnā lamabʿūṯūna ḵalqan jadīdan', 'Ve dediler ki: ''Biz kemik ve toprak olduğumuzda, gerçekten biz mi yepyeni bir yaratılışla diriltileceğiz?'''),
(17, 50, 15, 287, 'قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', 'qul kōnū ḥijāratan ʾaw ḥadīdā', 'De ki: "İster taş olun, ister demir!"'),
(17, 51, 15, 287, 'أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ فَسَيَقُولُونَ مَن يُعِيدُنَا قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًا', 'aw ḵal qan mim mā yakburu fī ṣudūri kum fasa ya qūlūna man yuʿī dunā quli lladhī faṭara kum awwala marrati n fasa yunġi ḍūna ilayka ruʾūsa hum wa ya qūlūna matā huwa qul ʿasā an yakūna qarīban', 'Yahut göğüslerinizde büyüyen (veya sizi büyütecek) başka bir yaratık. ''Bizi kim tekrar diriltecek?'' diyecekler. De ki: ''Sizi ilk defa yaratan kimse.''Bunun üzerine sana başlarını sallayacaklar ve ''Ne zaman o?'' diyecekler. De ki: ''Yakın olması umulur.'''),
(17, 52, 15, 287, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا', 'yawma yadʿūkum fa-tastajībūna bi-ḥamdihi wa-taẓunnūna in labiṯtum illā qalīlan', 'Sizi çağırdığı o gün, O''na hamdederek çağrısına uyarsınız ve (dünyada) çok az kaldığınızı sanırsınız.'),
(17, 53, 15, 287, 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ إِنَّ ٱلشَّيْطَٰنَ يَنزَغُ بَيْنَهُمْ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلْإِنسَٰنِ عَدُوًّا مُّبِينًا', 'wa-qul li-ʿibādī yaqūlū al-latī hiya ʾaḥsanu ʾinna al-shayṭāna yanzaghu baynahum ʾinna al-shayṭāna kāna lil-ʾinsāni ʿaduwwan mubīnan', 'Kullarıma söyle, sözün en güzelini söylesinler. Çünkü şeytan aralarını bozar. Şüphesiz şeytan insanın apaçık düşmanıdır.'),
(17, 54, 15, 287, 'رَّبُّكُمْ أَعْلَمُ بِكُمْ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلًا', 'Rabbukum aʿlemu bikum İn yeşeʾ yerḥamkum Ev in yeşeʾ yuʿaẓẓibkum Ve mā erselnāke ʿaleyhim vekīlan', 'Rabbiniz sizi daha iyi bilir. Dilerse size merhamet eder veya dilerse size azap eder. (Ey Muhammed!) Biz seni onlara bir vekil olarak göndermedik.'),
(17, 55, 15, 287, 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّۦنَ عَلَىٰ بَعْضٍ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', 'wa-rabbuka aʿlamu biman fī s-samāwāti wa-l-arḍi wa-laqad faḍḍalnā baʿḍa n-nabiyyīna ʿalā baʿḍin wa-ātaynā Dāwūda zabūrā', 'Rabbin, göklerde ve yerde olanları en iyi bilendir. Andolsun ki, biz peygamberlerin kimini kimine üstün kıldık ve Davud''a da Zebur''u verdik.'),
(17, 56, 15, 287, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', 'quli-dʿū-lladhīna zaʿamtum min dūnihi falā yamlikūna kashfa-ḍ-ḍurri ʿankum walā taḥwīlā', 'De ki: ''Allah''ı bırakıp da (ilah olduklarını) sandığınız kimseleri çağırın. Bakalım onlar, sizden sıkıntıyı ne giderebilirler, ne de değiştirebilirler.'''),
(17, 57, 15, 287, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا', 'ʾŪlāʾika lladhīna yadʿūna yabtahūna ʾilā rabbihimu l-wasīlata ʾayuhum ʾaqrabu Wa yarjūna raḥmatahū wa yakhāfūna ʿadhābahū ʾInna ʿadhāba rabbika kāna maḥdhūrā', 'Onlar, kendilerine daha yakın olanı (Allah''a yaklaştıracak vesileyi) aramak üzere Rablerine dua ederler. O''nun rahmetini umarlar ve azabından korkarlar. Şüphesiz Rabbinin azabı korkunçtur.'),
(17, 58, 15, 287, 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'wa ʾinna min qaryatin ʾillā naḥnu muhlīkūhā qabla yawmi l-qiyāmati ʾaw muʿaḏḏibūhā ʿaḏāban šadīdan kāna ḏālika fī l-kitābi masṭūran', 'Kıyamet gününden önce, o ülkeyi ya helâk edeceğiz ya da şiddetli bir azapla cezalandıracağız. Bu, (Levh-i Mahfuz''da) yazılmış bulunuyor.'),
(17, 59, 15, 288, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْءَايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةً فَظَلَمُوا۟ بِهَا وَمَا نُرْسِلُ بِٱلْءَايَٰتِ إِلَّا تَخْوِيفًا', 've mā manaʿanā an nursila bil-ʾāyāti ʾillā ʾan kaḏḏaba bihā al-ʾawwalūn wa ʾāttaynā ṯamūda n-nāqata mubṣiratan fa-ẓalamū bihā wa mā nursilu bil-ʾāyāti ʾillā taḫwīfan', 'Bize, (önceki) milletlerin âyetleri yalanlamaları dışında, (bunları) göndermekten alıkoyan bir şey yoktu. Semûd kavmine de gözler önünde bir âyet olarak dişi deveyi vermiştik, ama on(unla) zulmettiler. Oysa biz âyetleri ancak korkutmak için göndeririz.'),
(17, 60, 15, 288, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَٰكَ إِلَّا فِتْنَةً لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَٰنًا كَبِيرًا', 'wa-ʾiḏ qulnā laka ʾinna rabbaka ʾaḥāṭa bi-n-nāsi wa-mā ǧaʿalnā r-ruʾyā llatī ʾaraynāka ʾillā fitnatan li-n-nāsi wa-š-šajarata l-malʿūnata fī l-qurʾāni wa-nuhawwīfuhum fa-mā yazīduhum ʾillā ṭuġyānan kabīran', 'Hani biz sana, "Şüphesiz Rabbin insanları çepeçevre kuşatmıştır" demiştik. Sana gösterdiğimiz o rüya (görme olayı) ile Kur''an''da lanetlenen ağacı da insanları imtihan etmek için (vesile kıldık). Biz onları korkutuyoruz ama bu, onlara büyük bir azgınlıktan başka bir şey sağlamıyor.'),
(17, 61, 15, 288, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا', 'wa-ʾiḏ qulnā lil-malāʾikati sǧudū li-ʾādama fa-saǧadū ʾillā ʾiblīsa qāla ʾa-saǧudu li-man ḫalaqta ṭīnā', 'Hani meleklere, "Adem''e secde edin" demiştik de İblis hariç hepsi secde etmişti. İblis, "Ben, ona mı secde edeyim? Ben ondan daha hayırlıyım. Beni ateşten yarattın, onu ise çamurdan yarattın" demişti.'),
(17, 62, 15, 288, 'قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًا', 'qāla ʾaraʾaytaka hāḏā lladī karramta ʿalayya laʾin ʾaḵḵartanī ʾilā yawmi lqiyāmati laʾaḥtanikanna ḏurriyyatahū ʾillā qalīlan', 'Şeytan dedi ki: ''Şu bana üstün kıldığın kimseyi görüyor musun? Yemin ederim ki, eğer beni kıyamete kadar tehir edersen, onun neslini -az bir kısmı hariç- mutlaka kendime bağlayacağım.'''),
(17, 63, 15, 288, 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءً مَّوْفُورًا', 'qāla ʾidhhab faman tabaʿaka minhum faʾinna jahannama jazāʾukum jazāʾan mawfūran', 'De ki: "Haydi git! Onlardan kim sana uyarsa, şüphesiz sizin cezanız cehennemdir; (bu,) yeterli bir karşılıktır."'),
(17, 64, 15, 288, 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ وَعِدْهُمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'wa-stafziz man istaṭaʿta minhum biṣawtika wa-ajlib ʿalayhim bikhaylika wa-rajilika wa-shārikhum fī l-amwāli wa-l-awlādi wa-ʿidhum wa-mā yaʿiduhumu sh-shayṭānu illā ghurūran', 'Onlardan gücüne gideni sesinle (kışkırtıp) uzaklaştır, süvarilerinle ve yayalarınla onların üzerine akın et, mallarda ve evlatlarda onlara ortak ol ve onlara vaatte bulun. Zaten şeytan onlara aldatmadan başka bir şey vaat etmez.'),
(17, 65, 15, 288, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ وَكَفَىٰ بِرَبِّكَ وَكِيلًا', 'ʾinna ʿibādī laysa laka ʿalayhim sulṭānun wa kafā birabbika wakīlan', 'Kullarıma karşı senin hiçbir gücün yoktur. Vekil olarak Rabbin yeter.'),
(17, 66, 15, 288, 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًا', 'Rabbukumul-lezī yuzcī lekumul-fulke fīl-bahri litabteğū min faḍlihī İnnēhū kāne bikum rahīmā', 'Rabbiniz, sizin için denizde gemileri yürüten (ve emrinize veren)dir ki O''nun fazlından (nimetlerinden) faydalanıp arayasınız. Şüphesiz O, size karşı çok merhametlidir.'),
(17, 67, 15, 289, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ وَكَانَ ٱلْإِنسَٰنُ كَفُورًا', 'wa ʾiḏā massakumu ḍ-ḍurru fī l-baḥri ḍalla man tadʿūna ʾillā ʾiyyāhu falammā naggākum ʾilā l-barri ʾaʿraḍtum wakāna l-ʾinsānu kafūrā', 'Denizde size bir sıkıntı dokunduğu zaman, (küfür ve isyan edenler) Allah''tan başka taptıklarınızın hepsi kaybolur. Ancak O (Allah) müstesnadır. Yine de sizi kurtarıp karaya çıkardığı zaman, (bundan) yüz çevirirsiniz. Zaten insan çok nankördür.'),
(17, 68, 15, 289, 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', 'ʾafʾamintum ʾan yaḵsifa bikum jāniba l-barri ʾaw yursila ʿalaykum ḥāṣibān ṯumma lā tajidū lakum wakīlān', 'Yoksa karanın (kara tarafının) bir yanını üzerinize batırmayacağından emin mi oldunuz? Yahut üzerinize taşlar savuran (bir fırtına) göndermeyeceğinden? Sonra kendinize bir vekil bulamazsınız.'),
(17, 69, 15, 289, 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًا', 'am amintum an yuʿīdakum fīhi tāratan ʾuḵrā fayursila ʿalaykum qāṣifan mina ʾr-rīḥi fayuğriqakum bimā kafaṛtum ṯumma lā tajidū lakum ʿalaynā bihi tabīʿan', 'Yoksa, sizi tekrar ona (denize) döndürüp üzerinize kudurgan bir rüzgar göndererek ve küfrettiğiniz için sizi boğarak, sonra da bu yaptıklarınıza karşı bize hiçbir yardımcı bulamayacağınızdan emin mi oldunuz?'),
(17, 70, 15, 289, 'وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍ مِّمَّنْ خَلَقْنَا تَفْضِيلًا', 'Ve lekad kerremnâ benî Âdeme ve hamelnâhum fîl berri vel bahri ve razaknâhum minet tayyibâti ve faddalnâhum alâ kesîrin mimmen halaknâ tafdîlen', 'Andolsun ki biz, Âdemoğullarını şerefli kıldık, onları karada ve denizde taşıdık, onlara temiz ve güzel rızıklar verdik ve onları yarattıklarımızın birçoğundan üstün kıldık.'),
(17, 71, 15, 289, 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَٰمِهِمْ فَمَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا', 'yawma nadʿū kulla unāsin biʾimāmihim faman ūtīya kitābahū biyemīnihi faʾulāʾika yaqraʾūna kitābahum walā yuẓlamūna fatīlan', 'Her insanı kendi önderiyle birlikte çağıracağımız o günü (hatırla). Kimin kitabı sağ eline verilirse, işte onlar kitaplarını okuyacaklar ve kendilerine bir ''çekirdek'' kadar bile haksızlık edilmeyecektir.'),
(17, 72, 15, 289, 'وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْءَاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا', 've men kāne fī hāḏihi aʿmā fehuve fī l-ʾāḫireti aʿmā ve ʾaḍallu sabīlā', 'Kim bu dünyada (hakka karşı) kör ise, âhirette de kördür ve yolca daha şaşkındır.'),
(17, 73, 15, 289, 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ وَإِذًا لَّٱتَّخَذُوكَ خَلِيلًا', 'wa-ʾin kādū leyefṭinūnaka ʿani lladhī ʾawḥaynā ʾilayka litafteriya ʿalaynā ghayrahu wa-ʾidhan lattakhadhūka khalīlan', 'Neredeyse seni sana vahyettiğimizden (Kur''an''dan) saptıracaklardı; böylece bize senin uydurduğun başka bir şeyi (peygamber olarak) uydurmanı isteyeceklerdi. O takdirde seni dost edinirlerdi.'),
(17, 74, 15, 289, 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًٔا قَلِيلًا', 'Ve levlâ en sebbetnâke lekad kidte terkenu ileyhim şey''en kalîlen', 'Eğer seni sağlamlaştırmamış olsaydık, neredeyse onlara birazcık meyledecektin.'),
(17, 75, 15, 289, 'إِذًا لَّأَذَقْنَٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا', 'idhan la''adhaqnaaka dhi''fa al-hayati wa dhi''fa al-mamaati thumma laa tajidu laka ''alaynaa naseeraa', 'O takdirde, elbette sana dünya hayatında da kat kat azap ve ölümden sonra da kat kat azap tattırırdık. Sonra bize karşı hiçbir yardımcı bulamazdın.'),
(17, 76, 15, 290, 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا وَإِذًا لَّا يَلْبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلًا', 'wa-ʾinna kādū layastafizzūnaka mina l-ʾarḍi liyukhrijūka minhā wa-ʾidhan lā yalbathūna khilāfaka ʾillā qalīlan', 'Neredeyse seni yeryüzünden (çıkarmak için) seni (oradan) çıkaracaklardı. Eğer böyle yapsalardı, senden sonra orada pek az kalırlardı.'),
(17, 77, 15, 290, 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 'sunnata man qad arsalnā qablaka min rusulinā wa lā tajidu li-sunnatinā taḥwīlan', 'Senden önce gönderdiğimiz bütün peygamberlerimize uyguladığımız sünnet (kanunumuz) budur. Bizim sünnetimizde hiçbir değişiklik bulamazsın.'),
(17, 78, 15, 290, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًا', 'aqimi ṣ-ṣalāta li-dulūki sh-shamsi ilā ghasaqi l-layli wa-qurʾāna l-fajri inna qurʾāna l-fajri kāna mashhūdan', 'Güneşin batıya meyletmesinden (öğle vaktinden) gecenin karanlığına kadar (belli vakitlerde) namaz kıl. Bir de sabah namazını kıl. Çünkü sabah namazası şahitlidir.'),
(17, 79, 15, 290, 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةً لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا', 'wa-mina l-layli fa-tahajjad bihi nafilatan laka ʿasā an yabʿathaka rabbuka maqāman maḥmūdan', 'Hem gecenin bir kısmında da uyanarak sana mahsus fazla bir namazla (teheccüd ile) namaz kıl. Rabbin seni makam-ı mahmûda eriştirecektir.'),
(17, 80, 15, 290, 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًا نَّصِيرًا', 'wa qul rabbi adkhilnī mudkhala ṣidqin wa akhrijnī mukhraja ṣidqin wajʿal lī min ladunka sulṭānan naṣīran', 'Ve de ki: Rabbim! Beni (gireceğim yere) doğrulukla girdir ve (çıkaracağım yerden) doğrulukla çıkar. Bana tarafından, (bana) yardımcı olacak bir güç ver.'),
(17, 81, 15, 290, 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًا', 'wa-qul jāʾa l-ḥaqqu wa-zahaga l-bāṭilu ʾinna l-bāṭila kāna zahūqan', 'Ve de ki: Hak geldi, batıl yok oldu. Şüphesiz batıl yok olucudur.'),
(17, 82, 15, 290, 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًا', 'wa nunazzilu mina l-qurʾāni mā huwa shifāʾun wa raḥmatun lil-muʾminīna wa lā yazīdu ẓ-ẓālimīna illā khasāran', 'Biz Kur''an''dan, inanalar için bir şifa ve rahmet olanı indiriyoruz. Zalimlerin ise bununla yalnızca zararları artar.'),
(17, 83, 15, 290, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًا', 'wa ʾidhā ʾanʿamnā ʿalā l-ʾinsāni ʾaʿraḍa wanaʾā bijānibihī wa ʾidhā massahu ʾššarru kāna yaʾūsan', 'İnsana nimet verdiğimiz zaman, (bizden) yüz çevirir ve yan çizer. Kendisine şer dokunduğu zaman ise (artık) ümitsizliğe düşer.'),
(17, 84, 15, 290, 'قُلْ كُلٌّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًا', 'Qul Kullun yaʿmalu ʿalā shākilatihi Fa rabbukum aʿlamu biman huwa ahdā sabīlan', 'De ki: Herkes kendi karakterine ve yaratılışına göre iş yapar. Rabbiniz, kimin daha doğru yolu tuttuğunu en iyi bilendir.'),
(17, 85, 15, 290, 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًا', 'wa yas''alūnaka ʿani ar-rūḥi quli ar-rūḥu min ʾamri rabbī wa mā ʾūtītum mina al-ʿilmi ʾillā qalīlā', 'Sana ruh''u sorarlar. De ki: "Ruh, Rabbimin emrindendir. Size az bir ilimden başkası verilmemiştir."'),
(17, 86, 15, 290, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', 'Ve leʾin şiʾnā lenazhebenne billazī awḥaynā ilayka summe lā tecidu leke bihī ʿalaynā wakīlā', 'Andolsun ki, eğer dileseydik sana vahyettiğimizi elbette giderirdik; sonra sen de bize karşı kendine bir vekil bulamazdın.'),
(17, 87, 15, 291, 'إِلَّا رَحْمَةً مِّن رَّبِّكَ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًا', 'illa raḥmeten min rabbike inne faḍlahū kāne ʿaleyke kebīran', 'Ancak Rabbinden bir rahmet olarak (oldu); şüphesiz O''nun fazlı senin üzerine büyük olmuştur.'),
(17, 88, 15, 291, 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا', 'qul laʾin ijtamaʿati l-ʾinsu wa-l-jinnu ʿalā ʾan yaʾtū bi-mithli hādhā l-qurʾāni lā yaʾtūna bi-mithlihī wa-law kāna baʿḍuhum li-baʿḍin ẓahīran', 'De ki: "Andolsun, insanlar ve cinler bir araya gelip bu Kur''an''ın bir benzerini getirmeye çalışsalar, birbirlerine destek olsalar bile, onun bir benzerini getiremezler."'),
(17, 89, 15, 291, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', 'Ve lekad sarrafnâ lin nâsi fî hâzâl kur''âni min kulli meselin Fe ebâ ekserun nâsi illâ kufûrâ', 'Andolsun ki biz, bu Kur''an''da insanlar için her türlü misali çeşitli şekillerde açıkladık. Yine de insanların çoğu nankörlükten başka bir şeyi kabul etmediler.'),
(17, 90, 15, 291, 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', 'wa qālū lan nuʾmina laka ḥattā tafjura lanā mina l-ʾarḍi yanbūʿan', 'Ve dediler ki: ''Biz sana inanmayız, ta ki bize yerden bir pınar fışkırtıncaya kadar.'''),
(17, 91, 15, 291, 'أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا', 'aw takūna laka jannatun min nakhīlin waʿinabin fatufaccira l-anhāra khilālahā tafjīran', 'Yahut sana hurmalardan ve üzümlerden bir bağ (bahçe) olsun da, aralarından bol bol dereler akıtmak suretiyle (bunları) akıtıp çıkavrasın.'),
(17, 92, 15, 291, 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا', 'aw tusqiṭa s-samāʾa kamā zaʿamta ʿalaynā kisafan aw taʾtiya bi-llāhi wa-l-malāʾikati qabīlan', 'Yahut, iddia ettiğin gibi, üzerimize gökten parçalar yağdırasın, yahut Allah''ı ve melekleri karşımıza getiresin.'),
(17, 93, 15, 291, 'أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰبًا نَّقْرَؤُهُۥ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا', 'aw yakūna laka baytun min zukhrufin aw tarqā fī s-samāʾi wa lan nuʾmina lirūqiyyika ḥattā tunazzila ʿalaynā kitāban naqraʾūhu qul subḥāna rabbī hal kuntu illā basharan rasūlan', 'Yahut senin altından bir evin olmalı yahut göğe yükselmelisin. Bize okuyacağımız bir kitap indirmedikçe senin bu yükselişine inanmayız. De ki: "Rabbimi yüceltirim! Ben, yalnızca bir beşer, bir elçiden başka değilim."'),
(17, 94, 15, 291, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًا رَّسُولًا', 'Ve mā manaʿa n-nāsa an yuʾminū iḏ ǧāʾahumu l-hudā illā an qālū ʾabaʿaṯa ʾllāhu bašaran rasūlā', 'Onlara hidayet geldiğinde insanların inanmalarına, "Allah bir beşeri mi peygamber olarak gönderdi?" demelerinden başka ne engel oldu?'),
(17, 95, 15, 291, 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَٰٓئِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًا رَّسُولًا', 'qul law kāna fī l-arḍi malāʾikatun yamshūna muṭmaʾinnīna lanazzalnā ʿalayhim mina s-samāʾi malakan rasūlan', 'De ki: Eğer yeryüzünde (insanlar değil de) birbirini tatmin ederek yürüyen melekler olsaydı, elbette onlara gökten bir melek peygamber indirirdik.'),
(17, 96, 15, 291, 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'qul kafā bi-llāhi šahīdan baynī wa-baynakum ʾinnahu kāna bi-ʿibādihī khabīran baṣīran', 'De ki: "Benimle sizin aranızda şahit olarak Allah yeter. Şüphesiz O, kullarının durumundan haberdardır, (her şeyi) görendir."'),
(17, 97, 15, 292, 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَىٰهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيرًا', 'vemen yahdi allāhu fehuve l-muhtedī vemen yuḍlil felen tecide lehum evliyāʾe min dūnihi ve naḥşuruhum yevme l-qiyāmeti ʿalā wucūhihim ʿumyan wa bukmāan wa ṣummāan meʾvāhum cahanneemu kullamā khabet zednāhum saʿīrāan', 'Allah kime hidayet ederse, işte doğru yolu bulan odur. Kimi de saptırırsa, artık onlara O''ndan başka dostlar bulamazsın. Ve Biz, kıyamet günü onların yüzüstü kör, dilsiz ve sağır olarak haşredeceğiz. Varacakları yer cehennemdir. Ateşi her dindiğinde, ateşi onlara artırırız.'),
(17, 98, 15, 292, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', 'dhālika jazāʾuhum bi-annahum kafarū bi-ʾāyātinā wa qālū ʾaʾidhā kunnā ʿiẓāman wa rufātan ʾa-innā la-mabʿūthūna khalqan jadīdan', 'İşte onların cezası, âyetlerimize inanmamaları ve "Biz kemik ve toprak olup çürüyünce mi, gerçekten biz mi yeni bir yaratılışla diriltileceğiz?" demeleridir.'),
(17, 99, 15, 292, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورًا', 'ʾawalam yaraw ʾanna ʾallāha ʾalladhī khalaqa ʾssamāwāti wal-ʾarḍa qādirun ʿalā ʾan yakhluqa mithlahum wa-jaʿala lahum ʾajalan lā rayba fīhi fa-ʾabā ʾl-ẓālimūna ʾillā kufūran', 'Onlar, gökleri ve yeri yaratan Allah''ın, kendilerinin benzerlerini yaratmaya da kadir olduğunu görmediler mi? Allah, kendileri için (ölüm) süresi tayin etmiştir; bunda şüphe yoktur. Ama zalimler inkârdan başkasını kabul etmediler.'),
(17, 100, 15, 292, 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ وَكَانَ ٱلْإِنسَٰنُ قَتُورًا', 'qul law ʾantum tamlikūna ḵazāʾina raḥmati rabbī ʾiḏan la-ʾamsaktum ḵašyata l-ʾinfāqi wa-kāna l-ʾinsānu qatūrā', 'De ki: "Eğer siz Rabbimin rahmet hazinelerine mâlik olsaydınız, o takdirde harcamak korkusuyla mutlaka tutardınız. Zaten insan çok cimridir."'),
(17, 101, 15, 292, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَٰتٍۭ بَيِّنَٰتٍ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَٰمُوسَىٰ مَسْحُورًا', 'Ve lekad âteynâ Mûsâ tis''a âyâtin beyyinâtin fes''el benî İsrâîle iz câehum fekâle lehû Fir''avnu innî le ezunnuke yâ Mûsâ mes''hûrâ(n)', 'Andolsun ki Musa''ya apaçık dokuz mucize verdik. İsrailoğullarına sor ki, o (Musa) onlara geldiğinde Firavun ona şöyle demişti: "Ey Musa, ben seni kesinlikle büyülenmiş sanıyorum."'),
(17, 102, 15, 292, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًا', 'qāla laqad ʿalimta mā ʾanzala hāʾulāʾi ʾillā rabbus-samāwāti wal-ʾarḍi baṣāʾira wa ʾinnī laʾaẓunnuka yā firʿawnu maṯbūrā', 'Musa dedi ki: "Andolsun, bunları, göklerin ve yerin Rabbi''nden başkasının indirmediğini sen de bilmişsindir. Ben de ey Firavun, senin helak edilmiş olduğunu sanıyorum."'),
(17, 103, 15, 292, 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعًا', 'faʾarāda ʾan yastafizza-hum mina l-ʾarḍi faʾaġraqnāhu wa-man maʿahu jamīʿan', 'Bunun üzerine (Firavun) onları ülkeden çıkarmak istedi. Biz de onu ve onunla birlikte olanların hepsini boğduk.'),
(17, 104, 15, 292, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْءَاخِرَةِ جِئْنَا بِكُمْ لَفِيفًا', 'wa-qulnā min baʿdihī li-banī ʾisrāʾīla skunū l-ʾarḍa fa-ʾiḏā jāʾa waʿdu l-ʾākhirati jiʾnā bikum lafīfan', 'Ve ondan sonra İsrailoğullarına şöyle dedik: ''Ey kavmim! Arz''a (ülkeye) yerleşin. Vaad olunan (fetih ve zafer) zamanı geldiğinde sizi dağınık bir halde bir araya toplayacağız.'''),
(17, 105, 15, 293, 'وَبِٱلْحَقِّ أَنزَلْنَٰهُ وَبِٱلْحَقِّ نَزَلَ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', 'wa-bi-l-ḥaqqi ʾanzalnāhu wa-bi-l-ḥaqqi nazala wa-mā ʾarsalnāka ʾillā mubashshiran wa-naḏīran', 'Onu hak ile indirdik ve hak ile indi. Seni ise ancak müjdeleyici ve uyarıcı olarak gönderdik.'),
(17, 106, 15, 293, 'وَقُرْءَانًا فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَٰهُ تَنزِيلًا', 'wa-qurʾānan faraqnāhu li-taqraʾahu ʿalā n-nāsi ʿalā mukthin wa-nazzalnāhu tanzīlan', 'Ve Kur''an''ı, insanlara yavaş yavaş okuyup açıklaman için onu ayırdık ve onu biz indirdik.'),
(17, 107, 15, 293, 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا', 'Qul āminū bihī aw lā tuʾminū ʾinna llaḏīna ūtū l-ʿilma min qablihī ʾiḏā yutlā ʿalayhim yakhirrūna lil-ʾaḏqāni sujjadā', 'De ki: "Ona (Kur''an''a) ister inanın, ister inanmayın. Daha önce kendilerine ilim verilenler okunduğu zaman, yüzüstü secdeye kapanırlar."'),
(17, 108, 15, 293, 'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا', 'wa yaqūlūna subḥāna rabbina ʾinna kāna waʿdu rabbina lamafʿūlan', 'Ve derler ki: "Rabbimizi tenzih ederiz! Doğrusu Rabbimizin vaadi mutlaka yerine gelecektir."'),
(17, 109, 15, 293, 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا', 'wa yakhirrūna lil-ʾadhqāni yabkūna wa yazīduhum khushūʿan', 'Yüzüstü kapanırlar, ağlaya ağlaya ve bu, onların huşûunu artırır.'),
(17, 110, 15, 293, 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَٰنَ أَيًّا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا', 'quli dʿū llāha awi dʿū r-raḥmāna ayyan mā tadʿū falahu l-asmāʾu l-ḥusnā walā tajhar biṣalātika walā tukhāfit bihā wabtaghi bayna dhālika sabīlā', 'De ki: ''İster Allah deyin, ister Rahman deyin. Hangisini derseniz deyin, en güzel isimler O''nundur. Namazında sesini ne çok yükselt, ne de çok kıs; ikisinin arasında bir yol tut.'),
(17, 111, 15, 293, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّ مِّنَ ٱلذُّلِّ وَكَبِّرْهُ تَكْبِيرًۢا', 'wa-quli l-ḥamdu li-llāhi lladhī lam yattakhidh waladan wa-lam yakun lahu sh-sharīku fī l-mulki wa-lam yakun lahu waliyyun mina dh-dhulli wa-kabbirhu takbīran', 'Ve de ki: Hamd, evlat edinmeyen, mülkte ortağı olmayan ve zilletten (dolayı) bir yardımcı edinmeyen Allah''a mahsustur. Ve O''nu büyükle yücelt.'),
(18, 1, 15, 293, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا', 'alḥamdu lillāhi alladhī ʾanzala ʿalā ʿabdihi l-kitāba wa-lam yajʿal lahu ʿiwajan', 'Hamd, kuluna Kitab''ı indiren ve ona hiçbir eğrilik koymayan Allah''a mahsustur.'),
(18, 2, 15, 293, 'قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا', 'Qayyiman Liyunḏira ba''san shadīdan min ladunhu Wa yubashshira al-mu''minīna alladhīna yaʿmalūna al-ṣāliḥāti Anna lahum ajran ḥasanan', 'Kıyamet gününü, (kıyamet) korkusunu (veya azabını) haber vermek ve salih amel işleyen müminlere, kendileri için güzel bir ecir (cennet) olduğunu müjdelemek için dosdoğru (bir kitap) olarak indirdi.'),
(18, 3, 15, 293, 'مَّٰكِثِينَ فِيهِ أَبَدًا', 'mākiṯīna fīhi ʾabadan', 'Onun içinde ebediyen kalacaklardır.'),
(18, 4, 15, 293, 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا', 'wa yunḏira ḏeena qaaloo ittakhaḏa allāhu waladan', 'Ve "Allah çocuk edindi" diyenleri uyarır.'),
(18, 5, 15, 294, 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍ وَلَا لِءَابَآئِهِمْ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَٰهِهِمْ إِن يَقُولُونَ إِلَّا كَذِبًا', 'mā lehum bihī min ʿilmin velā li-ābāʾihim kaburat kelimeten taḫruju min efvâhihim in yaqūlūne illā keẕibā', 'Onların bu konuda hiçbir bilgisi yoktur; atalarının da. Ağızlarından çıkan söz ne kadar büyük! Onlar düpedüz yalan söylemektedirler.'),
(18, 6, 15, 294, 'فَلَعَلَّكَ بَٰخِعٌ نَّفْسَكَ عَلَىٰٓ ءَاثَٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَٰذَا ٱلْحَدِيثِ أَسَفًا', 'falʿallaka bākhʿun nafsaka ʿalā ʾāthārihim ʾin lam yuʾminū bihādhā al-ḥadīthi ʾasafā', 'Eğer bu söze (Kur''an''a) inanmazlarsa, belki de sen, onların ardından üzüntüden kendini helak edeceksin.'),
(18, 7, 15, 294, 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا', 'ʾinnā jaʿalnā mā ʿalā l-ʾarḍi zīnatan lahā linabluwahum ʾayyahum ʾaḥsanu ʿamalan', 'Şüphesiz biz, yeryüzündeki şeyleri, onları imtihan etmek için bir ziynet yaptık.'),
(18, 8, 15, 294, 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا', 'waʾinnā lajāʿilūna mā ʿalayhā ṣaʿīdan juruzan', 'Ve şüphesiz biz, onun üzerindeki her şeyi kupkuru bir toprak haline getireceğiz.'),
(18, 9, 15, 294, 'أَمْ حَسِبْتَ أَنَّ أَصْحَٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَٰتِنَا عَجَبًا', 'am hasibta anna ashaba al-kahfi wa-r-raqimi kanu min ayatina ''ajaba', 'Yoksa, Ashâb-ı Kehf ve Rakîm''in bizim âyetlerimizden bir acâib olduklarını mı sandın?'),
(18, 10, 15, 294, 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا', 'idh awā l-fityatu ilā l-kahfi faqālū rabbanā ātinā min ladunka raḥmatan wahayyiʾ lanā min amrinā rashadan', 'Hani o genç yiğitler mağaraya sığınmışlar, "Rabbimiz! Bize katından bir rahmet ver ve bize şu işimizde doğru yolu göster!" demişlerdi.'),
(18, 11, 15, 294, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًا', 'faḍarabnā ʿalā ʾāḏānihim fī l-kahfi sinīna ʿadadan', 'Bunun üzerine biz de nice yıllar boyunca onların kulaklarını (tıkayıp uyuttuk) mağarada.'),
(18, 12, 15, 294, 'ثُمَّ بَعَثْنَٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًا', 'thumma baʿathnāhum linaʿlama ayyu l-ḥizbayni aḥṣā limā labithū amadan', 'Sonra, iki topluluktan hangisinin kaldıkları süreyi daha iyi saydığını bilmemiz için onları uyandırdık.'),
(18, 13, 15, 294, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدًى', 'Naḥnu naquṣṣu ʿalayka nabaʾahum bil-ḥaqq ʾInnahum fityatun ʾāmanū bi-rabbihim Wa-zidnāhum hudā', 'Onların haberlerini sana dosdoğru anlatıyoruz. Gerçekten onlar, Rablerine inanmış birkaç gençti ve biz de onların hidayetlerini artırmıştık.'),
(18, 14, 15, 294, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَٰهًا لَّقَدْ قُلْنَآ إِذًا شَطَطًا', 'wa-rabaṭnā ʿalā qulūbihim iḏ qāmū fa-qālū rabbanā rabbu s-samāwāti wa-l-ʾarḍi lan nadʿū min dūnihi ʾilāhan laqad qulnā ʾiḏan šaṭaṭan', 'Onların kalplerini (sağlamlaştırıp) öylece pekiştirdik ki, (o zaman) kalkıp şöyle demişlerdi: "Rabbimiz, göklerin ve yerin Rabbidir; biz O''ndan başkasına ilah demeyiz. (Eğer desek) o takdirde gerçekten batıl bir şey söylemiş oluruz."'),
(18, 15, 15, 294, 'هَٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَٰنٍۭ بَيِّنٍ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا', 'hā''ulā''i qawmunā ''ittakhadhū min dūnihi ''ālihatan lawlā ya''tūna ''alayhim bisulṭānin bayyin faman ''aẓlamu mimmani ''ftara ''alā Allāhi kadhiban', 'İşte bizim kavmimiz! O''ndan başka birtakım ilâhlar edindiler. Onlara (bu ilâhların tanrılığına dair) apaçık bir delil getirmeleri gerekmez miydi? Allah''a karşı yalan uydurandan daha zâlim kim olabilir?'),
(18, 16, 15, 295, 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا', 'wa-ʾiḏi-ʿtazaltumūhum wa-mā yaʿbudūna ʾillā-llāha fa-ʾawū ʾilā-l-kahfi yanšur-lakum rabbukum min-raḥmatihi wa-yuhayyiʾ-lakum min-ʾamrikum mirfaqan', 'Ve onlardan ve Allah''tan başka taptıklarından ayrıldığınız zaman, Kehf''e sığının. Rabbiniz size rahmetinden yayar ve size işinizden bir kolaylık sağlar.'),
(18, 17, 15, 295, 'وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍ مِّنْهُ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّا مُّرْشِدًا', 'wa tarā ash-shamsa idhā ṭalaʿat tazāwaru ʿan kahfihim dhāta al-yamīn wa idhā gharabat taqriḍuhum dhāta ash-shimāl wa hum fī fujwatin minhu dhālika min āyāti Allāh man yahdi Allāhu fa-huwa al-muhtadī wa man yuḍlil fa-lan tajida lahu waliyyan murshidā', 'Sen, güneşin doğduğu zaman mağaralarından sağa meylederek doğduğunu, battığı zaman da onlardan sola keserek battığını görürsün. Onlar ise, mağaranın açık bir bölümünde bulunuyorlardı. İşte bu, Allah''ın ayetlerindendir. Allah kime hidayet ederse, doğru yolu bulan odur. Kimi de saptırırsa, artık ona doğru yolu gösterici bir dost bulamazsın.'),
(18, 18, 15, 295, 'وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ وَكَلْبُهُم بَٰسِطٌ ذِرَاعَيْهِ بِٱلْوَصِيدِ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا', 'wa taḥsabuhum ayqāẓan wa hum ruqūd wa nuqallibuhum dhāta l-yamīni wa dhāta sh-shimāl wa kalbuhum bāsiṭun dhirāʿayhi bil-waṣīd lawi iṭṭalaʿta ʿalayhim la-wallayta minhum firāran wa la-muliʾta minhum ruʿban', 'Onları uykuda sanırsın, oysa onlar uyanıktırlar. Onları sağa sola çeviririz. Köpekleri ise girişte ön ayaklarını uzatmış yatıyordu. Eğer sen onları görseydin, arkana bakmadan kaçardın ve onların varlığından dolayı için korku ile dolardı.'),
(18, 19, 15, 295, 'وَكَذَٰلِكَ بَعَثْنَٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ قَالَ قَآئِلٌ مِّنْهُمْ كَمْ لَبِثْتُمْ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', 'wa kaḏālika baʿaṯnāhum li-tatasāʾalū baynahum qāla qāʾilun minhum kam labiṯtum qālū labiṯnā yawman ʾaw baʿḍa yawmin qālū rabbukum ʾaʿlamu bimā labiṯtum fa-bʿaṯū ʾaḥadakum bi-wariqikum hāḏihi ʾilā l-madīnati fa-l-yanẓur ʾayyuha ʾazkā ṭaʿāman fa-l-yaʾtikum bi-rizqin minhu wa-l-yataḷaṭṭaf wa-lā yušʿiranna bikum ʾaḥadan', 'İşte böylece biz onları, aralarındaki durumu birbirlerine sorsunlar diye uyandırdık. İçlerinden biri şöyle dedi: "Ne kadar kaldınız?" Dediler ki: "Bir gün veya günün bir parçası kadar kaldık." (Diğerleri ise şöyle) dediler: "Ne kadar kaldığınızı Rabbiniz daha iyi bilir. Şimdi siz, birinizi şu gümüş paralarınızla şehre gönderin de bak-sın bakalım, hangi yiyecek daha temizdir, ondan size bir rızık getirsin. Hem çok nazik davransın ve sakın ola ki sizi kimseye sezdirmesin."'),
(18, 20, 15, 295, 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًا', 'ʾinnahum ʾin yaẓharū ʿalaykum yarjumūkum ʾaw yuʿīdūkum fī mīllatihim walā tufliḥū ʾiḏan ʾabadan', 'Onlar üzerinize muttali olurlarsa sizi taşlarlar veya sizi kendi dinlerine iade ederler ve o zaman asla kurtuluşa eremezsiniz.'),
(18, 21, 15, 296, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًا رَّبُّهُمْ أَعْلَمُ بِهِمْ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًا', 'wa kadhalika aʿtharnā ʿalayhim li yaʿlamū anna waʿda Allāhi ḥaqqun wa anna s-sāʿata lā rayba fīhā idh yatanāzaʿūna baynahum amrahum fa qālū bnu ʿalayhim bunyānan rabbuhum aʿlamu bihim qāla lladhīna ghalabū ʿalā amrihim la nattakhidhan na ʿalayhim masjidan', 'İşte böylece biz onların durumunu insanlara bildirdik ki, Allah''ın vaadinin hak olduğunu ve kıyamet gününün gelmesinde hiçbir şüphe olmadığını bilip anlasınlar. Onlar kendi aralarında Ashab-ı Kehf''in durumunu tartışıyorlardı. Kimi: "Onların üzerine bir bina yapın." dedi. Rableri onların durumunu daha iyi bilir. Bu hususta tartışmaya girenler ise şöyle dediler: "Onların üzerine mutlaka bir mescit yapacağız."'),
(18, 22, 15, 296, 'سَيَقُولُونَ ثَلَٰثَةٌ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءً ظَٰهِرًا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًا', 'sayuqūlūna thalāthatun rābiʿuhum kalbuhum wayaqūlūna khamsatun sādisuhum kalbuhum rajman bil-ghaybi wayaqūlūna sabʿatun wathāminuhum kalbuhum qul rabbī ʾaʿlamu bi-ʿiddatihim mā yaʿlamuhum ʾillā qalīlun falā tumāri fīhim ʾillā mirāʾan ẓāhiran walā tastafti fīhim minhum ʾaḥadan', 'Onlar, "Üç" diyecekler, dördüncüleri köpekleridir. "Beş" diyecekler, altıncıları köpekleridir. "Yedi" diyecekler, sekizincileri köpekleridir. De ki: "Onların sayısını Rabbim daha iyi bilir. Onları ancak az kimse bilir." Onun için, bu hususta (bu sayı meselesinde) derinliğe dalanlardan başkasını sorma ve onlar hakkında bunlardan (ashaptan) hiç kimseye soru sorma.'),
(18, 23, 15, 296, 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌ ذَٰلِكَ غَدًا', 'wa-lā taqūlanna li-shayʾin ʾinnī fāʿilun dhālika ghadan', 'Hiçbir şey için, "Ben bunu yarın mutlaka yapacağım" demeyin.'),
(18, 24, 15, 296, 'إِلَّآ أَن يَشَآءَ ٱللَّهُ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَٰذَا رَشَدًا', 'illa an yeşāʾa ʾllāhu vadhkur rabbaka iḏā nesīte waqul ʿasā an yahdiyanī rabbī liʾaqraba min hāḏā rašadan', 'Allah''ın dilemesi dışında (bunları söyleme). Unuttuğun zaman Rabbini zikret ve ''Umarım Rabbim beni bundan daha yakın bir zamanda doğruya iletir'' de.'),
(18, 25, 15, 296, 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَٰثَ مِا۟ئَةٍ سِنِينَ وَٱزْدَادُوا۟ تِسْعًا', 'wa labiṯū fī kahfihim ṯalāṯa miʾatin sanīna wazdadū tisʿan', 'Onlar, mağaralarında üç yüz yıl kadar kalmışlar ve buna dokuz yıl daha ilave etmişlerdir.'),
(18, 26, 15, 296, 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ لَهُۥ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَبْصِرْ بِهِۦ وَأَسْمِعْ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًا', 'quli llāhu aʿlamu bimā labiṯū lahū ġaybu s-samāwāti wa-l-arḍi abṣir bihī wa-ʾasmiʿ mā lahum min dūnihī min waliyyin wa-lā yušriku fī ḥukmihī ʾaḥadan', 'De ki: "Onların ne kadar kaldıklarını en iyi Allah bilir. Göklerin ve yerin gizli olanları O''nundur. O ne kadar iyi gören, ne kadar iyi işitendir! O''nun, O''ndan başka dostu yoktur. O, kendi hükümranlığında hiçbir kimseyi ortak koşmaz."'),
(18, 27, 15, 296, 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 'wa-tl u mā ʾūḥiya ʾilayka min kitābi rabbika lā mubaddila li-kalimātihi wa-lan tajida min dūnihi multahadan', 'Ve sana Rabbinden vahyolunan kitabı (Kur''an''ı) oku. O''nun kelimelerini değiştirecek kimse yoktur ve O''ndan başka sığınacak bir yer de bulamazsın.'),
(18, 28, 15, 297, 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًا', 'waṣbir nafsaka maʿa lladhīna yadʿūna rabbahum bil-ghadawāti wal-ʿashiyyi yurīdūna wajhahū walā taʿdu ʿaynāka ʿanhum turīdu zīnata l-ḥayāti d-dunyā walā tuṭiʿ man aghfalnā qalbahu ʿan dhikrinā wattabaʿa hawāhu wa kāna amruhu furuṭan', 'Sabret, kendinle beraber sabah akşam Rablerine, O''nun rızasını dileyerek dua edenlerle beraber tut. Sakın gözlerini onlardan ayırma. Dünya hayatının ziynetini isteyerek onlardan başkasına yönelme. Kalbini Bizi anmaktan gafil kıldığımız ve kendi hevasına uymuş, işi gücü aşırılık olmuş kimselere de itaat etme.'),
(18, 29, 15, 297, 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ إِنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', 'wa quli l-ḥaqqu min rabbikum fa man shā''a fa-l-yu''min wa man shā''a fa-l-yakfur innā aʿtadnā liẓ-ẓālimīna nāran aḥāṭa bihim surāduquhā wa in yastaghīthū yughāthū bimā''in ka-l-muhli yashwī l-wujūha bi''sa sh-sharābu wa sā''at murtafaqan', 'Ve de ki: "Hak, Rabbinizdendir. Artık dileyen iman etsin, dileyen inkâr etsin." Şüphesiz biz zâlimler için öyle bir ateş hazırlamışızdır ki, (ateşten) duvarları onları çepeçevre kuşatmıştır. Eğer feryat ederlerse, erimiş maden gibi yüzleri haşlayan bir su ile imdada koşulurlar. Ne kötü bir içecek ve ne fena bir barınak!'),
(18, 30, 15, 297, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', 'ʾinna llaḏīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti ʾinnā lā nuḍīʿu ʾajra man ʾaḥsana ʿamalan', 'İman edip salih amel işleyenlere gelince; şüphesiz biz, güzel amel yapanın ecrini zayi etmeyiz.'),
(18, 31, 15, 297, 'أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا', 'ʾulāʾika lahum jannātu ʿadnin tajrī min taḥtihimu l-ʾanhāru yuḥallawna fīhā min ʾasāwira min dhahabin wa-yalbasūna thiyāban khuḍran min sundusin wa-ʾistabraqin muttakiʾīna fīhā ʿalā l-ʾarāʾiki niʿma th-thawābu wa-ḥasanat murtفaqan', 'İşte onlara, altlarından ırmaklar akan, içinde ebediyen kalacakları Adn cennetleri vardır. Orada altın bileziklerle süslenirler ve ipekten, astarı da atlastan (ince ve kalın) yeşil elbiseler giyerler. Orada tahtlar üzerinde yaslanırlar. Ne güzel sevap ve ne güzel bir dinlenme yeri!'),
(18, 32, 15, 297, 'وَٱضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَٰبٍ وَحَفَفْنَٰهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا', 'wa-ḍrib lahum maṯalan raǧulayni ǧaʿalnā li-ʾaḥadihimā ǧannatayni min ʾaʿnābin wa-ḥafafnāhumā bi-naḵlin wa-ǧaʿalnā baynahumā zarʿan', 'Onlara iki adam örneği ver: Onlardan birine iki üzüm bağı verdik ve ikisini de hurmalıklarla çevirdik, ikisinin arasında da ekinlik kıldık.'),
(18, 33, 15, 297, 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًٔا وَفَجَّرْنَا خِلَٰلَهُمَا نَهَرًا', 'kiltā al-jannatayni ātāt ukulahā wa-lam taẓlim minhu shayʾan wa-fajjar-nā khilālahumā naharan', 'İki bahçenin de her birinin ürünlerini verdiği ve hiçbir şeyi eksik bırakmadığı ve onların ortasından bir nehir fışkırttığımız zamanı hatırla.'),
(18, 34, 15, 297, 'وَكَانَ لَهُۥ ثَمَرٌ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا', 'wa-kāna lahu thamarun fa-qāla li-ṣāḥibihi wa-huwa yuḥāwiruhu anā aktharu minka mālān wa-aʿazzu nafaran', 'Onun (başka) ürünleri de vardı. Böylece sohbet ettiği arkadaşına dedi ki: "Ben malca senden daha zenginim ve topluluk (insan sayısı) bakımından daha güçlüyüm."'),
(18, 35, 15, 298, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدًا', 'wa-dakhala jannatahu wa-huwa ẓālimun li-nafsihī qāla mā ʾaẓunnu ʾan tabīda hādhihi ʾabadan', 'O, kendi nefsine zulmederek bahçesine girdi ve şöyle dedi: "Bunun hiç yok olacağını sanmıyorum."'),
(18, 36, 15, 298, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا', 'wa mā ʾaẓunnu s-sāʿata qāʾimatan wa laʾin rudidtu ʾilā rabbī laʾajidanna khayran minhā munqalaban', 'Saatin (kıyametin) kopacağını sanmıyorum. Eğer Rabbime döndürülürsem, muhakkak orada bundan daha hayırlı bir sonuç bulacağım.'),
(18, 37, 15, 298, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّىٰكَ رَجُلًا', 'qāla lahu ṣāḥibuhu wa huwa yuḥāwiruhu ʾakaferta bi-llaḏī xalaqaka min turābin ṯumma min nuṭfatin ṯumma sawwāka rajulan', 'Onunla konuşmakta olan arkadaşı şöyle dedi: "Seni topraktan, sonra bir damla sudan yaratan, sonra da seni (insan şeklinde) bir adam haline getiren o (Allah''ı) inkâr mı ettin?"'),
(18, 38, 15, 298, 'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًا', 'lākinnanā huwa Allāhu rabbī walā ushriku birabbī aḥadan', 'Ama (ben derim ki): O, Allah benim Rabbimdir ve ben Rabbime hiç kimseyi ortak koşmam.'),
(18, 39, 15, 298, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًا وَوَلَدًا', 'wa-lawlā idh dakhalt jannataka qulta mā shāʾa -llāhu lā quwwata illā bi-llāh in tarani anā aqalla minka mālān wa-waladān', 'Ne olurdu, bahçene girdiğin zaman: "Allah''ın dilediği olur; bende sizin kadar mal ve evlattan başka bir şey görmüyorum, (ama yine de) güç ancak Allah''tandır" dememiş olman! Sen beni mal ve evlat bakımından kendinden daha az görüyorsun.'),
(18, 40, 15, 298, 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًا زَلَقًا', 'faʿasā rabbī ʾan yuʾtiyanī khayran min jannatika wa yursila ʿalayhā ḥusbānan mina s-samāʾi fa tuṣbiḥa ṣaʿīdan zalaqan', 'Belki Rabbim bana senin bahçenden daha hayırlısını verir ve senin bahçenin üzerine gökten bir ateş (veya azap) gönderir de o, kaygan bir toprak haline geliverir.'),
(18, 41, 15, 298, 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًا', 'aw yuṣbiḥa māʾuhā ḡawran falan tastaṭīʿa lahu ṭalaban', 'Yahut suyu çekiliverir de bir daha onu bulmaya asla güç yetiremezsin.'),
(18, 42, 15, 298, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًا', 'wa ʾuḥīṭa bi-ṯamarihī fa-ʾaṣbaḥa yuqallibu kaffayhi ʿalā mā ʾanfaqafi hī wa hiya ḵāwiyatun ʿalā ʿurūšihā wa yaqūlu yālaytanī lam ʾušrik bi-rabbī ʾaḥadā', 'Onun ürünleri de (artık) yok edilmişti. Bu yüzden bağının duvarları üzerine çökmüşken, onun için harcadığı emeklere karşı avuçlarını ovuşturup duruyordu. "Keşke Rabbime hiç kimseyi ortak koşmasaydım!" diyordu.'),
(18, 43, 15, 298, 'وَلَمْ تَكُن لَّهُۥ فِئَةٌ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', 'wa lam takun lahu fia''atun yansurūnahu min dūni Allāh wa mā kāna muntaṣirā', 'Onu, Allah''tan başka savunacak bir topluluğu yoktu ve Allah''tan başka yardımcısı da olmadı.'),
(18, 44, 15, 298, 'هُنَالِكَ ٱلْوَلَٰيَةُ لِلَّهِ ٱلْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا', 'hunālika l-walāyatu lillāhi l-ḥaqqi huwa khayrun thawāban wa khayrun ʿuqbā', 'İşte o zaman velayet (hükümranlık, yönetim) haktır, Allah''ındır. O, sevap olarak da hayırlıdır, akıbet (sonuç) olarak da hayırlıdır.'),
(18, 45, 15, 298, 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ ٱلرِّيَٰحُ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقْتَدِرًا', 'wa-ḍrib lahum mathala al-ḥayāti ad-dunyā kamāʾin anzalnāhu mina as-samāʾi fa-khtalaṭa bihi nabātu al-arḍi fa-aṣbaḥa hashīman tadhrihu ar-riyāḥu wa-kāna Allāhu ʿalā kulli shayʾin muqtadiran', 'Onlara dünya hayatının misalini ver: (Gökten) indirdiğimiz bir su ile birbirine karışan bitkiler, derken rüzgarların savurduğu kuru bir ota dönüşüverdi. Allah her şeye gücü yetendir.'),
(18, 46, 15, 299, 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا', 'al-mālu wa-l-banūna zīnatu al-ḥayāti ad-dunyā wa-l-bāqiyātu aṣ-ṣāliḥātu khayrun ʿinda rabbika thawāban wa-khayrun amalā', 'Mal ve oğullar, dünya hayatının süsüdür. Ahiret ise, Rabbinin katında hem sevap olarak daha hayırlıdır hem de güzel bir akıbet.'),
(18, 47, 15, 299, 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةً وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا', 'wa yawma nusayyiru l-jibāla wa tarā l-arḍa bārizatan wa ḥasharnāhum fa-lam nughādir minhum aḥadan', 'Ve o gün dağları yürütürüz ve yeri dümdüz, bomboş görürsün. Ve onları mahşerde toplarız da içlerinden hiçbirini bırakmayız.'),
(18, 48, 15, 299, 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۭ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا', 'wa ʿuriḍū ʿalā rabbika ṣaffan laqad jiʾtūmūnā kamā khalaqnākum ʾawwala marratin bal zaʿamtum ʾallan najʿala lakum mawʿidan', 'Ve onları Rabbinin huzuruna saf saf arzederler. Andolsun ki, sizi ilk yarattığımız haldeki gibi bize tek başınıza geldiniz. Oysa siz, sizin için hiçbir zaman belirlemeyeceğimizi sanmıştınız.'),
(18, 49, 15, 299, 'وَوُضِعَ ٱلْكِتَٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ٱلْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا', 'wa wuḍiʿa l-kitābu fa-tarā l-mujrimīna mushfiqīna mimmā fīhi wa yaqūlūna yā-waylatanā māli hādhā l-kitābi lā yughādiru ṣaghīratan wa lā kabīratan illā aḥṣāhā wa wajadū mā ʿamilū ḥāḍiran wa lā yaẓlimu rabbuka aḥadan', 'Ve kitap konulmuştur. Suçluların, onda olanlardan dolayı içi içine sığmaz bir halde olduklarını görürsün. Ve derler ki: "Eyvah bize! Bu ne biçim kitapmış! Küçük, büyük hiçbir şey bırakmaksızın hepsini sayıp dökmüş!" Ve yaptıklarını hazır bulurlar. Ve senin Rabbin hiç kimseye zulmetmez.'),
(18, 50, 15, 299, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ بِئْسَ لِلظَّٰلِمِينَ بَدَلًا', 'wa-ʾiḏ qulnā lil-malāʾikati ʾisğudū li-ʾādama fa-sajadū ʾillā ʾiblīsa kāna mina l-ğinni fa-fasaqa ʿan ʾamri rabbihī ʾafa-tattaḫiḏūnahū wa-ḏurriyyatahū ʾawliyāʾa min dūnī wa-hum lakum ʿaduwwun biʾsa liẓ-ẓālimīna badalan', 'Hani meleklere, "Âdem''e secde edin" demiştik. İblis hariç hepsi secde etti. İblis ise cinlerdendi de Rabbinin emrinden dışarı çıktı. Şimdi siz, beni bırakıp da onu ve soyunu mi dostlar edineceksiniz? Oysa onlar sizin düşmanınızdır. Zalimler için bu ne kötü bir (tercih)tir!'),
(18, 51, 15, 299, 'مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًا', 'mā ash-hadtuhum khalqa as-samāwāti wal-arḍi walā khalqa anfusihim wa mā kuntu muttakhiḏa al-muḍillīna ʿaḍudā', 'Ben, onların ne göklerin ve yerin yaratılışına ne de kendi nefislerinin yaratılışına şahit tutmadım. Ben, (kötülüğe saptıranları) yardımcı edinmedim.'),
(18, 52, 15, 299, 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا', 'wa yawma yaqūlu nādū shurakāʾiya alladhīna zaʿamtum fadaʿawhum falam yastajībū lahum wa jaʿalnā baynahum mawbiqan', 'Ve o gün (Allah) şöyle der: ''Ortaklarım olduğunu iddia ettiklerinizi çağırın!'' Onları çağırdıklarında, kendilerine icabet etmezler ve onların arasına bir yıkım yeri koymuşuzdur.'),
(18, 53, 15, 299, 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًا', 'wa raʾā l-mujrimūna n-nāra fa-ẓannū ʾannahum muwāqiʿūhā wa lam yajidū ʿanhā maṣrifan', 'Mücrimler (suçlular) ateşi gördüler ve onun içine düşeceklerini sandılar. Ondan kaçacak bir yer de bulamadılar.'),
(18, 54, 15, 300, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍ وَكَانَ ٱلْإِنسَٰنُ أَكْثَرَ شَىْءٍ جَدَلًا', 'Ve lekad sarrafnâ fî hâzâl kur''âni lin nâsi min kulli meselin Ve kânel insânu eksere şey''in cedelâ', 'Andolsun ki Biz, bu Kur''an''da insanlar için her türlü misali çeşitli şekillerde açıkladık. İnsan ise tartışmaya en çok düşkün olandır.'),
(18, 55, 15, 300, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًا', 've ma mene''a en-nas en yu''minu iz caahumul-huda ve yestağfiru rabbehum illa en te''tiyehum sunnetul-evveline ev ye''tiyehumul-''azabu gubula', 'Onlara hidayet geldiğinde insanların inanmalarına ve Rablerinden bağışlanma dilemelerine, ancak öncekilerin sünnetinin (veya Allah''ın o günkü ilahi kanununun) kendilerine gelmesi veya azabın göz göre göre kendilerine gelmesi engel olmuştur.'),
(18, 56, 15, 300, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَمَآ أُنذِرُوا۟ هُزُوًا', 've mā nursilu l-murselīne illā mubaşşirīne ve munzirīn ve yucādilu l-lezīne keferū bi-l-bāṭili li-yudḥiḍū bihi l-ḥaqqa ve-ttahaḏū ʾāyātī ve mā ʾunḏirū huzuwan', 'Oysa biz peygamberleri ancak müjde vericiler ve uyarıcılar olarak göndeririz. Ama inkârcılar, hakkı batıl ile çürütmek için mücadele ederler. Ayetlerimizi ve kendilerine yapılan uyarıları da alay konusu edinirler.'),
(18, 57, 15, 300, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًا', 'wa-man ʾaẓlamu mimman dhukkira bi-ʾāyāti rabbihī fa-ʾaʿraḍa ʿanhā wa-nasīya mā qaddamat yadāhu ʾinnā jaʿalnā ʿalā qulūbihim ʾakinatan ʾan yafqahūhu wa-fī ʾādhānihim waqran wa-ʾin tadʿuhum ʾilā al-hudā fa-lan yahtadū ʾidhan ʾabadan', 'Rabbinin ayetleriyle öğütülüp de sonra onlardan yüz çeviren ve önceden yaptıklarını unutan kimseden daha zalim kim olabilir? Biz onların kalplerine, Kur''an''ı anlamalarını engellemek için perdeler gerdik; kulaklarına da bir ağırlık koyduk. Sen onları doğru yola çağırsan bile, o takdirde asla doğru yolu bulamazlar.'),
(18, 58, 15, 300, 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًا', 'wa rabbuka l-ḡafūru ḏū r-raḥmah law yuʾāḵiḏuhum bimā kasabū laʿajjala lahumu l-ʿaḏāb bal lahum mawʿid lan yaǧidū min dūnihi mawʾilā', 'Senin Rabbin Gafur''dur, merhamet sahibidir. Eğer onları kazandıklarıyla hemen yakalayıverseydi, elbette azabı acele verirdi. Fakat onlara belirli bir süre vardır; o zaman hiçbir sığınak bulamazlar.'),
(18, 59, 15, 300, 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا', 'wa tilka l-qurā ahlaḳnāhum lammā ẓalamū wa jaʿalnā li-mahliki-him mawʿidā', 'İşte o şehirler! Zulmettiklerinde onları helak ettik. Ve helakleri için de bir zaman belirlemiştik.'),
(18, 60, 15, 300, 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًا', 'waʾiḏ qāla mūsā lifatāhu lā ʾabraḥu ḥattā ʾabluġa majmaʿa l-baḥrayni ʾaw ʾamḍiya ḥuqubā', 'Hani Musa, yanındaki genc''e demişti ki: "İki denizin birleştiği yere gelinceye kadar durmaksızın yürüyeceğim ya da uzun yıllar (yol) gideceğim."'),
(18, 61, 15, 300, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًا', 'fe-lemmā beleġā mecmeʿa beynihimā nesiyā ḥūtehumā fetteḫaḏe sebīlehu fīl-baḥri serabā', 'İki denizin birleştiği yere vardıklarında balıklarını unuttular. Balık, denizde kendi yolunu tutmuştu.'),
(18, 62, 15, 301, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًا', 'fe-lemmā jāvazā qāla li-fetāhu ʾātinā ġadāʾanā laqad laqīnā min seferinā hādhā naṣabā', 'İki adam (Musa ve yanındaki zat) o yerden geçince, Musa yanındaki gence dedi ki: "Bize öğle yemeğimizi getir, bu yolculuğumuzdan dolayı gerçekten çok yorulduk."'),
(18, 63, 15, 301, 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَٰنُ أَنْ أَذْكُرَهُۥ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًا', 'qāla ʾaraʾayta ʾidh ʾawēna ʾilā ṣ-ṣakhrati fa-ʾinnī nasītu l-ḥūta wa-mā ʾansāniyhu ʾillā š-šayṭānu ʾan ʾadhkurahū wa-ttakhaḏa sabīlahū fī l-baḥri ʿajabā', '“Kayaya sığındığımız zaman ben balığı unutmuşumdur. Onu hatırlamamı bana ancak şeytan unutturmuş olmalı. Ve o, denizde acayip bir yol tuttu.”'),
(18, 64, 15, 301, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًا', 'qāla dhālika mā kunnā nabghī fa-rtaddā ʿalā ʾāthārihimā qaṣaṣan', 'Şöyle dedi: "İşte aradığımız şey buydu." Böylece ikisi, bıraktıkları izlerin üzerine geri döndüler.'),
(18, 65, 15, 301, 'فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًا', 'fevejadā ʿabdan min ʿibādinā ātaynāhu raḥmatan min ʿindinā veʿallamnāhu min ladunnā ʿilman', 'Derken kullarımızdan bir kul buldular. Ona tarafımızdan bir rahmet vermiş ve ona tarafımızdan bir ilim öğretmiştik.'),
(18, 66, 15, 301, 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا', 'qāla lahu mūsā hal attabiʿuka ʿalā an tuʿallimanī mimmā ʿullimta rushdan', 'Musa ona dedi ki: "Sana öğretilenden bana doğru bir irşad (yol gösterme) olman şartıyla sana tâbi olabilir miyim?"'),
(18, 67, 15, 301, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', 'qāla ʾinnaka lan tastaṭīʿa maʿiya ṣabran', 'Dedi ki: "Şüphesiz sen benimle beraberliğe sabretmeye asla güç yetiremezsin."'),
(18, 68, 15, 301, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًا', 'wa kayfa taṣbiru ʿalā mā lam tuḥiṭ bihi khubran', 'Hem, bilgice kapsamına almadığın bir şeye nasıl sabredebilirsin?'),
(18, 69, 15, 301, 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًا وَلَآ أَعْصِى لَكَ أَمْرًا', 'qāla satajidanī in shāʾa -llāhu ṣābirā wa lā ʾaʿṣī laka ʾamrā', 'Dedi ki: "İnşallah beni sabredici bulacaksın ve sana hiçbir hususta karşı gelmeyeceğim."'),
(18, 70, 15, 301, 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا', 'qāla fa-ʾinni ʾittabaʿtanī falā tasʾalni ʿan shayʾin ḥattā ʾuḥditha laka minhu dhikran', 'Dedi ki: "O halde bana uyarsan, hiçbir şey hakkında bana soru sorma ki, sana ondan bir hatırlatma (veya söz) yapayım."'),
(18, 71, 15, 301, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًا', 'fa-nṭalaqā ḥattā ʾiḏā rakibā fī s-safīnati kharaqahā qāla ʾakharaqtahā lituġriqa ʾahalahā laqad jiʾta šayʾan ʾimran', 'Böylece yola koyuldular. Nihayet bir gemiye bindiklerinde, (gemiyi yapan zat) gemiyi deldi. Musa: "Sen yolcularını boğmak için mi gemiyi deldin? Andolsun ki sen çok fena bir iş yaptın!" dedi.'),
(18, 72, 15, 301, 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', 'qāla ʾalam ʾaqul ʾinnaka lan tastaṭīʿa maʿiya ṣabran', 'Dedi ki: "Ben sana benimle beraberliğe sabretmenin imkânsız olduğunu söylemedim mi?"'),
(18, 73, 15, 301, 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًا', 'qāla lā tuʾākhidhnī bimā nasītu walā turhiqnī min ʾamrī ʿusrā', 'Dedi ki: Unuttuğum şeyden dolayı beni sorumlu tutma ve bana bu işimde bir zorluk çıkarma.'),
(18, 74, 15, 301, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمًا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةًۢ بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْـًٔا نُّكْرًا', 'fa-nṭalaqā ḥattā ʾiḏā laqiyā ġulāman fa-qatalahū qāla ʾaqatalta nafsan zakiyyatan bi-ġayri nafsin laqad jiʾta šayʾan nukran', 'Derken yürüdüler, ta ki bir oğlan çocuğu ile karşılaştıklarında, onu öldürdü. (Hızır) "Sen, kimseyi öldürmemişken, tertemiz bir cana karşılık temiz bir cana kıydın! Andolsun ki sen, çok kötü bir iş yaptın" dedi.'),
(18, 75, 16, 302, 'قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', 'qāla ʾalam ʾaqul laka ʾinnaka lan tastaṭīʿa maʿiya ṣabran', 'Dedi ki: "Sana, benimle beraberliğe asla dayanamayacağını söylememiş miydim?"'),
(18, 76, 16, 302, 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِى قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًا', 'qāla in saʾaltuka ʿan šayʾin baʿdahā falā tuṣāḥibnī qad balagta min ladunnī ʿuḏran', 'Dedi ki: "Eğer bundan sonra senden bir şey soracak olursam, artık benimle arkadaşlık etme. Gerçekten benim tarafımdan (mazerete ulaşmış) sona ermiş olursun."'),
(18, 77, 16, 302, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًا', 'fa-nṭalaqā ḥattā ʾiḏā ʾatayā ʾahla ḳaryatin istaṭʿamā ʾahlahā fa-ʾabaw ʾan yuḍayyifūhumā fa-wajadā fīhā ǧidāran yurīdu ʾan yanqaḍḍa fa-ʾaqāmahū qāla law šiʾta la-ttahaḏta ʿalayhi ʾajran', 'Bunun üzerine ikisi yola koyuldular. Nihayet bir kasabaya geldiklerinde, halkından yiyecek istediler. Kasaba halkı onlara misafirperverlik göstermekten kaçındı. Derken orada yıkılmaya yüz tutmuş bir duvar buldular. Hızır, duvarı düzeltti. (Bunun üzerine Musa) şöyle dedi: "Eğer isteseydin, elbette buna karşılık bir ücret alabilirdin."'),
(18, 78, 16, 302, 'قَالَ هَٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', 'qāla hāḏā firāqu baynī wa baynika saʾunabbiʾuka bi-taʾwīli mā lam tastaṭiʿ ʿalayhi ṣabran', 'Bu, benimle senin aranızdaki ayrılıktır. Sabredemediğin şeylerin (iç yüzünü) sana haber vereceğim.'),
(18, 79, 16, 302, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا', 'ammā s-safīnatu fakānat limasākīna yaʿmalūna fī l-baḥri faʾarattu ʾan ʾaʿībahā wa kāna warāʾahum malikun yaʾkhudhu kulla safīnatin ghaṣban', 'Geminin durumu ise, denizde çalışan birkaç yoksula aitti. Onu kusurlu hale getirmek istedim; çünkü onların ilerisinde, her sağlam gemiyi zorla almakta olan bir kral vardı.'),
(18, 80, 16, 302, 'وَأَمَّا ٱلْغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَٰنًا وَكُفْرًا', 'waʾammā l-ḡulāmu fakāna ʾabawāhu muʾminayni fahašīnā ʾan yurhiqahumā ṭuḡyānan wa kufrā', 'Çocuğa gelince, babası ve anası müminlerdi. Biz, çocuğun onları azgınlık ve küfürle bunaltmasından korktuk.'),
(18, 81, 16, 302, 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِّنْهُ زَكَوٰةً وَأَقْرَبَ رُحْمًا', 'faʾaradnā ʾan yubdilahumā rabbuhumā ḵayran minhu zakātan waʾaqraba ruḥman', 'Böylece Rablerinin, onlara bunun yerine daha temizini ve daha yakın akrabalık bağına sahip olanını vermesini diledik.'),
(18, 82, 16, 302, 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحًا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا', 'wa-ʾammā l-jidāru fakāna li-ḡulāmayni yatīmayni fī l-madīnati wa-kāna taḥtahu kanzun lahumā wa-kāna ʾabūhumā ṣāliḥan fa-ʾarāda rabbuka ʾan yablugā ʾašuddahumā wa-yastāẖrijā kanzahumā raḥmatan min rabbika wa-mā faʿaltuhu ʿan ʾamrī ḏālika taʾwīlu mā lam tasṭiʿ ʿalayhi ṣabran', 'Duvar''a gelince, şehirde bulunan iki yetim çocuğun idi; duvarın altında onlara ait bir hazine vardı. Babaları salih bir kimse idi. Rabbin, onların erginlik çağına ulaşmalarını ve Rabb''inden bir rahmet olarak hazinelerini çıkarmalarını istedi. Ben bunları kendi görüşüme göre yapmadım. İşte bu, senin sabredemediğin şeylerin yorumudur.'),
(18, 83, 16, 302, 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', 'wa yas''alūnaka ʿan dhī l-qarnayni qul sa''atlū ʿalaykum minhu dhikran', 'Sana Zülkarneyn''den soruyorlar. De ki: "Size ondan bir hatıra okuyacağım."'),
(18, 84, 16, 303, 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَىْءٍ سَبَبًا', 'ʾinnā makkannā la-hū fī l-ʾarḍi wa ʾātaynā-hu min kulli šayʾin sababā', 'Doğrusu biz onu yeryüzünde kudret sahibi kıldık ve ona (her şeye ulaşacak) bir yol verdik.'),
(18, 85, 16, 303, 'فَأَتْبَعَ سَبَبًا', 'fa-ʾatbaʿa sababā', 'Böylece o bir yol tuttu.'),
(18, 86, 16, 303, 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍ وَوَجَدَ عِندَهَا قَوْمًا قُلْنَا يَٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًا', 'ḥattā ʾiḏā balaga maġriba ʾš-šamsi wajadahā taġrubu fī ʿaynin ḥamiʾatin wajada ʿindahā qawman qulnā yā ḏā l-qarnayni ʾimmā ʾan tuʿaḏḏiba wa-ʾimmā ʾan tattaḵiḏa fīhim ḥusnan', 'Nihayet güneşin batışına ulaştığında, onu (güneşi) bulanık bir suda batıyor buldu ve onun yanında bir kavim buldu. Biz, ''Ey Zülkarneyn! İster azap et, ister onlara iyi davran.'' dedik.'),
(18, 87, 16, 303, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًا نُّكْرًا', 'qāla ammā man ẓalama fa-sawfa nuʿaḏḏibuhu ṯumma yuraddu ʾilā rabbihī fa-yuʿaḏḏibuhu ʿaḏāban nukran', 'Dedi ki: "Kim zulmederse onu azaplandıracağız, sonra Rabbine döndürülecek, böylece onu şiddetli bir azapla azaplandıracaktır."'),
(18, 88, 16, 303, 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًا', 'waʾammā man ʾāmana wa ʿamila ṣāliḥan falāhu jazāʾan al-ḥusnā wasanaqūlu lahu min ʾamrinā yusran', 'Kim iman edip salih amel işlemişse, ona en güzel karşılık vardır. Biz de ona işimizden kolaylık gösteririz.'),
(18, 89, 16, 303, 'ثُمَّ أَتْبَعَ سَبَبًا', 'thumma atbaʿa sababā', 'Sonra bir yol tuttu.'),
(18, 90, 16, 303, 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًا', 'ḥattā ʾiḏā balaga maṭliʿa ʾš-šamsi wa-ǧada-hā taṭluʿu ʿalā qawmin lam naǧʿal la-hum min dūni-hā sitran', 'Nihayet güneşin doğduğu yere ulaşınca, onu (güneşi) kendileri için ondan başka bir örtü kılmadığımız bir kavim üzerine doğarken buldu.'),
(18, 91, 16, 303, 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا', 'kadhālika waqad aḥaṭnā bimā ladayhi khubran', 'İşte böyle! Ve biz onun yanındaki her şeyi bilgimizle kuşatmıştık.'),
(18, 92, 16, 303, 'ثُمَّ أَتْبَعَ سَبَبًا', 'thumma atbaʿa sababā', 'Sonra başka bir yol tuttu.'),
(18, 93, 16, 303, 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًا', 'ḥattā ʾiḏā balaga bayna s-sadayni wajada min dūnihimā qawman lā yakādūna yafqahūna qawlan', 'Nihayet iki dağ arasına ulaştığında, onların önünde neredeyse hiçbir sözü anlamayan bir kavim buldu.'),
(18, 94, 16, 303, 'قَالُوا۟ يَٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا', 'qālū yā dhā l-qarnayni inna yaʾjūja wa-maʾjūja mufsidūna fī l-arḍi fa-hal najʿalu laka kharjan ʿalā ʾan tajʿala baynanā wa-baynahum saddan', 'Dediler ki: "Ey Zülkarneyn! Şüphesiz Ye''cüc ve Me''cüc (yeryüzünde) fesat çıkarıyorlar. Acaba biz sana bir vergi vermemiz karşılığında, ikimizin arasına bir sed yapacak mısın?"'),
(18, 95, 16, 303, 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', 'qāla mā makkannī fīhi rabbī khayrun fa-aʿīnūnī bi-quwwatin ajʿal baynakum wa-baynahum radman', 'Dedi ki: Rabbimin bana verdiği nimet sizin topladıklarınızdan daha hayırlıdır. Bana gücünüzle yardım edin de sizinle onun arasına aşılmaz bir engel koyayım.'),
(18, 96, 16, 303, 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًا', 'ʾātūnī zubara l-ḥadīd ḥattā ʾiḏā sāwā bayna ṣ-ṣadafayn qāla ʾinfuḵū ḥattā ʾiḏā ǧaʿalahū nāran qāla ʾātūnī ʾufriḡ ʿalayhi qiṭran', 'Bana demir kütleleri getirin! Nihayet iki dağın arasını eşitleyip doldurunca, "Ateş körükleyin!" dedi. Demiri eritip alev haline getirince de, "Bana erimiş bakır getirin, üzerine dökeceğim!" dedi.'),
(18, 97, 16, 303, 'فَمَا ٱسْطَٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَٰعُوا۟ لَهُۥ نَقْبًا', 'fe-mā-staʿū ʾen yaẓharūhu ve-mā-staṭāʿū lehu naqban', 'Böylece onu ne aşabildiler ne de içine bir delik açabildiler.'),
(18, 98, 16, 304, 'قَالَ هَٰذَا رَحْمَةٌ مِّن رَّبِّى فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ وَكَانَ وَعْدُ رَبِّى حَقًّا', 'qāla hāḏā raḥmatum mir rabbī faʾiḏā jāʾa waʿdu rabbī jaʿalahū dakkāʾa wa kāna waʿdu rabbī ḥaqqan', 'Bu, Rabbimden bir rahmettir. Rabbimin vaadi geldiği zaman, O (sözünü) yerle bir eder. Rabbimin vaadi haktır.'),
(18, 99, 16, 304, 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِى بَعْضٍ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَٰهُمْ جَمْعًا', 'wa taraknā baʿḍahum yawmaʾiḏin yamūju fī baʿḍin wa nufikha fī ṣ-ṣūri fa jamaʿnāhum jamʿan', 'Ve o gün biz onları bırakmıştık; birbiri içinde dalgalanıyorlardı. Ve sur''a üflenmişti; böylece onları bir araya toplamıştık.'),
(18, 100, 16, 304, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِّلْكَٰفِرِينَ عَرْضًا', 'wa ʿaraḍnā jahannama yawmaʾiḏin lil-kāfirīna ʿarḍan', 'Ve o gün cehennemi kâfirler için bir sergileme ile arzederiz.'),
(18, 101, 16, 304, 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', 'alladhīna kānat aʿyunuhum fī ġiṭāʾin ʿan dhikrī wa kānū lā yastaṭīʿūna samʿan', 'Onlar, gözleri zikrimden bir perdede olan ve (hakkı) işitme yeteneğinden yoksun bulunan kimselerdi.'),
(18, 102, 16, 304, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَٰفِرِينَ نُزُلًا', 'ʾafahisiba lladhīna kafarū ʾan yattakhidhū ʿibādī min dūnī ʾawliyāʾa ʾinnā ʾaʿtadnā jahannama lilkāfirīna nuzulan', 'Yoksa o kâfirler, Benim kullarımı benden başka dostlar edineceklerini mi sandılar? Şüphesiz Biz, kâfirler için bir konak olarak cehennemi hazırladık.'),
(18, 103, 16, 304, 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَٰلًا', 'Qul hal nunabbiʾukum bil-ʾakhsarīna ʾaʿmālan', 'De ki: "Amelce en çok ziyana uğrayanları size haber verelim mi?"'),
(18, 104, 16, 304, 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', 'alladhīna ḍalla saʿyuhum fī al-ḥayāti ad-dunyā wa hum yaḥsabūna ʾannahum yuḥsinūna ṣunʿan', 'Onlar, dünya hayatında kendileri güzel işler yaptıklarını sanırken, hayır ve çabaları boşa giden kimselerdir.'),
(18, 105, 16, 304, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَزْنًا', 'ʾūlāʾika lladhīna kafarū bi-ʾāyāti rabbihim wa-liqāʾihi fa-ḥabiṭat ʾaʿmāluhum fa-lā nuqīmu lahum yawma l-qiyāmati waznan', 'İşte Rablerinin ayetlerini ve O''na ulaşmayı (kıyameti) inkâr edenler bunlardır. Bu sebeple onların amelleri boşa gitmiştir. Kıyamet günü onlar için bir terazi tutmayacağız.'),
(18, 106, 16, 304, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَرُسُلِى هُزُوًا', 'dhālika jazāʾuhum jahannamu bimā kafarū wa-ttakhaḏū ʾāyātī wa-rusulī huzūʾan', 'İşte onların mükâfatı cehennemdir; çünkü inkâr ettiler ve âyetlerimi ve peygamberlerimi alaya aldılar.'),
(18, 107, 16, 304, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ٱلْفِرْدَوْسِ نُزُلًا', 'İnne-lleẕîne âmenû ve ‘amilû-ssâlihât kânet lehum cennâtu-lfirdevsi nuzulâ', 'Şüphesiz iman edip salih ameller işleyenlere gelince, Firdevs cennetleri onlara konak olmuştur.'),
(18, 108, 16, 304, 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا', 'khālidīna fīhā lā yabghūna ʿanhā ḥiwalan', 'Onlar orada ebedî kalırlar; oradan asla bir değişim istemezler.'),
(18, 109, 16, 304, 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًا لِّكَلِمَٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًا', 'qul law kāna l-baḥru midādan likalimāti rabbī lanafida l-baḥru qabla an tanfada kalimātu rabbī wa law jiʾnā bimithlihī madadan', 'De ki: "Rabbimin sözleri (ve yazısı) için deniz mürekkep olacak olsa, Rabbimin sözleri tükenmeden deniz mutlaka tükenirdi. Bir de O''nun (sözlerinin) bir misli kadar daha yardımcı getirsek bile (yine tükenmez)."'),
(18, 110, 16, 304, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًا صَٰلِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', 'Qul innama ana basharun mithlukum yooha ilayya annama ilahukum ilahun wahidun Faman kana yarjo liqa''a rabbihi falyakmal ''amalan salihan Wa la yushrik bi''ibadati rabbihi ahadan', 'De ki: "Ben de ancak sizin gibi bir beşerim. Bana, ilahınızın ancak bir tek ilah olduğu vahyolunuyor. Artık kim Rabbine kavuşmayı umuyorsa, salih amel işlesin ve Rabbine ibadetde hiç kimseyi ortak koşmasın."'),
(19, 1, 16, 305, 'كٓهيعٓصٓ', 'Kâf Hâ Yâ Ayn Sad', 'Kâf Hâ Yâ Ayn Sad'),
(19, 2, 16, 305, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', 'dhikru raḥmati rabbika ʿabda-hu Zakariyyā', 'Bu, Rabb''inin, kulu Zekeriya''ya olan rahmetinin anılmasıdır.'),
(19, 3, 16, 305, 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّا', 'iḏ nādā rabbahū nidāʾan ḫafiyyan', 'Hani O, Rabbine gizli bir niyazla niyaz etmişti.'),
(19, 4, 16, 305, 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا', 'qāla rabbi innī wahana l-ʿaẓmu minnī wa-štaʿala r-raʾsu šaybā wa-lam ʾakun bi-duʿāʾika rabbi šaqiyyā', 'O, şöyle demişti: "Rabbim! Kemiklerim zayıfladı, saçım ağardı; SANA dua etmekle hiçbir zaman bedbaht olmadım."'),
(19, 5, 16, 305, 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّا', 'wa-innī khiftu l-mawālīya min warāʾī wa-kānat imraʾatī ʿāqiran fa-habb lī min ladunka waliyyan', 'Ve ben, arkamdan (gelecek olan) akrabalar yüzünden endişelendim. Eşim de kısır. Bu yüzden bana kendi katından bir veli (varis) ver.'),
(19, 6, 16, 305, 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ وَٱجْعَلْهُ رَبِّ رَضِيًّا', 'yarithunī wa yarithu min āl-i yaʿqūb wajʿalhu rabbī raḍiyyan', 'Bana ve Âl-i Ya''kub''a mirasçı olacak ve Rabbim, (onu) hoşnutluğuna ermiş kıl! (Dedi).'),
(19, 7, 16, 305, 'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّا', 'Yā Zekeriyya innā nubashshiruka bighulāmin ismuhu Yaḥyā Lam najʿal lahu min qablu samiyyā', 'Ey Zekeriya! Biz sana, adı Yahya olan bir oğlan müjdeleyiz. Daha önce ona kimseyi adaş kılmadık.'),
(19, 8, 16, 305, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَكَانَتِ ٱمْرَأَتِى عَاقِرًا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّا', 'qāla rabbi annā yakūnu lī ġulāmun wa kānat imraʾatī ʿāqiran wa qad balaġtu mina l-kibari ʿitiyyan', 'O, şöyle dedi: "Rabbim! Karım kısır olduğu ve ben de yaşlılıktan takatten düştüğüm halde benim nasıl çocuğum olabilir?"'),
(19, 9, 16, 305, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًٔا', 'qāla kadhālika qāla rabbuka huwa ʿalayya hayyinun waqad khalaqtuka min qablu wa lam taku shayʾan', 'O (Allah) şöyle buyurdu: Öyledir! Rabbin buyurdu ki: Bu bana göre kolaydır. Nitekim seni daha önce hiçbir şey değilken yaratmışımdır.'),
(19, 10, 16, 305, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٍ سَوِيًّا', 'qāla rabbi-jʿal lī ʾāyatan qāla ʾāyatuka ʾallā tukallima n-nāsa thalātha layālin saawiyyan', 'O, "Rabbim! Bana bir alâmet (işaret) ver!" dedi. (Allah) Buyurdu ki: "Senin alâmetin, insanlarla üç gün, (dâhilî) konuşamayacak olmandır; ancak (işaretle konuşabilirsin)."'),
(19, 11, 16, 305, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةً وَعَشِيًّا', 'faḫaraja ʿalā qawmihi mina l-miḥrābi faʾawḥā ʾilayhim ʾan sabbiḥū bukrataw wa-ʿashiyyan', 'Böylece Zekeriya mabedden (iç odasından) kavminin üzerine çıktı ve onlara, ''Sabah akşam (Allah''ı) tesbih edin'' diye işaret etti.'),
(19, 12, 16, 306, 'يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّا', 'yā yaḥyā khuḏi l-kitāba bi-quwwatin wa ātaynāhu l-ḥukma ṣabiyyan', 'Ey Yahya! Kitabı kuvvetle tut. (Onu) henüz beşikte bir çocukken (ona hikmet verdik).'),
(19, 13, 16, 306, 'وَحَنَانًا مِّن لَّدُنَّا وَزَكَوٰةً وَكَانَ تَقِيًّا', 'wa ḥanānan min ladunnā wa zakātan wa kāna taqiyyan', 'Ve tarafımızdan bir şefkat ve temizlik (verdik). O, takva sahibi idi.'),
(19, 14, 16, 306, 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا', 'wa barram biwālidayhi wa lam yakun jabbāran ʿaṣiyyan', 'Annesine babasına karşı da iyi hâlli idi, zorba ve isyânkâr değildi.'),
(19, 15, 16, 306, 'وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا', 'wa salāmun ʿalayhi yawma wulida wa yawma yamūtu wa yawma yubʿathu ḥayyan', 'Doğduğu gün, öleceği gün ve (bir de) diri olarak (kabirden) kaldırılacağı gün ona selam (selamet) vardır.'),
(19, 16, 16, 306, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا', 'wa-dhkur fī l-kitābi Maryama idhi ntabadhat min ahlihā makānan sharqiyyan', 'Kitap''ta Meryem''i de an. Hani o, ailesinden ayrılarak (veya bir kenara çekilerek) doğu tarafında bir yer tutmuştu.'),
(19, 17, 16, 306, 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا', 'fa-ttakhaḏat min dūnihim ḥijāban fa-arsalnā ilayhā rūḥanā fa-tamatṯala lahā bašaran sawiyyan', 'Bunun üzerine Meryem onlardan (insanlardan) ayrılarak tenha bir yer edindi. Biz de ona Cebrail''i gönderdik de ona tam bir insan şeklinde göründü.'),
(19, 18, 16, 306, 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيًّا', 'qālat innī ʾaʿūżu bi-r-raḥmāni minka ʾin kunta taqiyyan', 'Kadın dedi ki: "Ben senden, eğer Allah''tan korkuyorsan, Rahman''a sığınırım."'),
(19, 19, 16, 306, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًا زَكِيًّا', 'qāla innamā anā rasūlu rabbiki liʾaheba laki ġulāman zakiyyā', 'Melek şöyle dedi: "Ben yalnızca Rabb''inin sana tertemiz bir erkek çocuk armağan etmek için gönderdiği bir elçisiyim."'),
(19, 20, 16, 306, 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَلَمْ يَمْسَسْنِى بَشَرٌ وَلَمْ أَكُ بَغِيًّا', 'qālat ʾannā yakūnu lī ġulāmun wa lam yamsasnī bašarun wa lam ʾaku baġiyyan', 'O, şöyle dedi: "Ey Rabbim! Bana bir beşer dokunmamışken ve ben azgın bir kadın değilken, benim nasıl çocuğum olabilir?"'),
(19, 21, 16, 306, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌ وَلِنَجْعَلَهُۥٓ ءَايَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا', 'qāla kaḏāliki qāla rabbuki huwa ʿalayya hayyinun wa linajʿalahū ʾāyatan li-n-nāsi wa raḥmatan minnā wa kāna ʾamran maqḍiyyan', 'Dedi ki: "Öyle! Rabbim buyurdu ki: Bu bana kolaydır. Onu insanlara bir mucize ve tarafımızdan bir rahmet kılmak için (böyle yaptık). Ve bu, (ezelde) hükmedilmiş bir iştir."'),
(19, 22, 16, 306, 'فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًا قَصِيًّا', 'faḥamalathu fa-ntabadhat bihi makānan qaṣiyyā', 'Böylece ona hamile kaldı ve onunla uzak bir yere çekildi.'),
(19, 23, 16, 306, 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا', 'faʾajāʾahā l-maḵāḍu ʾilā jiḏʿi n-naxlati qālat yālaytanī mittu qabla hāḏā wa-kuntu nasyan mansiyyan', 'Derken doğum sancısı onu bir hurma ağacına sürükledi. "Keşke bundan önce ölüp gitseydim de unutulmuş olsaydım!" dedi.'),
(19, 24, 16, 306, 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا', 'fanādāhā min taḥtihā allā taḥzanī qad jaʿala rabbuki taḥteki sariyyan', 'Bunun üzerine Meryem''in alt tarafından bir ses ona seslendi: "Hüzünlenme! Rabbin senin (aşağı) tarafında bir dere (su) yaratmıştır."'),
(19, 25, 16, 306, 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّا', 'wa huzzī ʾilayki bi-jiżʿi n-nakhla(ti) tusāqiṭ ʿalayki ruṭaban janiyyā(n)', 'Ağacın sana doğru olan gövdesini silkele, üzerine taze ve olgun hurmalar dökülsün.'),
(19, 26, 16, 307, 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًا فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّا', 'fakulī wa-šrabī wa-qirrī ʿaynan fa-immā tarayinna mina l-bašari aḥadan fa-qūlī innī naḏartu li-r-raḥmāni ṣawman fa-lan ukallima l-yawma insiyyan', 'Artık ye, iç, gözünün (gönlünün) aydınlığı (huzuru) olsun! Eğer insanlardan birini görürsen, de ki: "Ben, Rahman''a bir oruç adadım, bu yüzden bugün hiçbir insanla konuşmayacağım."'),
(19, 27, 16, 307, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًٔا فَرِيًّا', 'faʾatat bihi qawmahā taḥmiluhū qālū yā Maryam laqad jiʾti shayʾan fariyyan', 'Bunun üzerine onu (çocuğu) kavmine getirdi. (Onlar:) ''Ey Meryem! Andolsun ki sen, çok çirkin bir şey yaptın!'' dediler.'),
(19, 28, 16, 307, 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا', 'yā ʾukhta hārūna mā kāna ʾabūki ʾimraʾa sawʾin wa mā kānat ʾumuki bagiyyan', 'Ey Harun''un kız kardeşi! Senin baban kötü bir kimse değildi ve annen de azgın bir kadın değildi.'),
(19, 29, 16, 307, 'فَأَشَارَتْ إِلَيْهِ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّا', 'fa-ashārat ilayhi qālū kayfa nukallimu man kāna fī l-mahdi ṣabiyyan', 'Bunun üzerine (Meryem) çocuğa işaret etti. ''Beşikteki bir bebekle biz nasıl konuşabiliriz?'' dediler.'),
(19, 30, 16, 307, 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّا', 'qāla innī ʿabdu llāh ʾātānīya l-kitāb wa-jaʿalanī nabiyyan', 'Bunun üzerine (çocuk) şöyle dedi: "Şüphesiz ben Allah''ın kuluyum. Bana Kitap''ı verdi ve beni bir peygamber kıldı."'),
(19, 31, 16, 307, 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا', 'wa jaʿalanī mubārakan ʾayna mā kuntu wa ʾōṣānī biṣ-ṣalāti waz-zakāti mā dumtu ḥayyā', 'Nerede olursam olayım beni mübarek kıldı ve yaşadığım sürece bana namazı ve zekâtı emretti.'),
(19, 32, 16, 307, 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا', 'wa barram biwālidatī wa lam yajʿalnī jabbāran shaqiyyan', 'Ve anneme karşı da iyi hâller içinde bulunmayı (emretti); beni zorba birската ve isyankâr kılmadı.'),
(19, 33, 16, 307, 'وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا', 'wa-s-salāmu ʿalayya yawma wulidtu wa-yawma amūtu wa-yawma ubʿathu ḥayyan', 'Doğduğum gün, öleceğim gün ve diri olarak (yeniden) diriltileceğim gün selamet benim üzerimedir.'),
(19, 34, 16, 307, 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', 'dhālika ʿīsā bnu maryama qawla l-ḥaqqi lladhī fīhi yamtarūn', 'İşte Meryem oğlu İsa! Bu, hakkında şüpheye düştükleri hak sözdür.'),
(19, 35, 16, 307, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ سُبْحَٰنَهُۥٓ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'mā kāna li-llāhi an yattakhiḏa min waladin subḥānahū iḏā qaḍā ʾamran fa-ʾinnamā yaqūlu lahū kun fa-yakūnu', 'Allah, bir çocuk edinme)!= (hakkı) yoktur. O, bir şeyin olmasını dilediği zaman, ona sadece "Ol!" der, o da olur.'),
(19, 36, 16, 307, 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'waʾinna ʾallāha rabbī warabbakum faʿbudūhu hāḏā ṣirāṭun mustaqīm', 'Şüphesiz Allah benim de Rabbim, sizin de Rabbinizdir. O halde yalnız O''na kulluk edin. İşte dosdoğru yol budur.'),
(19, 37, 16, 307, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', 'fa-ḵtalafa l-aḥzābu min baynihim fa-waylun lilladhīna kafarū min mashhadi yawmin ʿaẓīm', 'Böylece onların arasından çıkan topluluklar ayrılığa düştüler. Büyük bir günde şahitlikten dolayı, vay o kâfirlerin haline!'),
(19, 38, 16, 307, 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍ مُّبِينٍ', 'ʾasmaʿ bihim wa-ʾabṣir yawma yaʾtūnanā lākinni ẓ-ẓālimūna l-yawma fī ḍalālin mubīnin', 'Onları hem işitici hem de görücü olacağımız gün (onların hali) ne olacak! Ama zalimler, bugünkü apaçık bir sapıklık içindedirler.'),
(19, 39, 16, 308, 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', 'wa-ʾanḏirhum yawma l-ḥasrati ʾiḏ ḳuḍiya l-ʾamru wa-hum fī ġaflatin wa-hum lā yuʾminūna', 'Onları, iş olup bittiğinde, onlar gaflet içinde iken ve onlar inanmazken, pişmanlık (hasret) günüyle uyar.'),
(19, 40, 16, 308, 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', 'ʾinnā naḥnu narīṯu l-ʾarḍa wa-man ʿalayhā wa-ʾilayna yurjaʿūn', 'Şüphesiz ki toprağa ve üzerindekilere biz varis oluruz ve onların tamamı bize döndürülecektir.'),
(19, 41, 16, 308, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', 'wa-dhkur fī l-kitābi ibrāhīma ʾinnahu kāna ṣiddīqan nabiyyā', 'Kitapta İbrahim''i de an. Çünkü o, dosdoğru bir peygamberdi.'),
(19, 42, 16, 308, 'إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا', 'idh qāla li-ʾabīhi yā ʾabati lima taʿbudu mā lā yasmaʿu walā yubṣiru walā yughnī ʿanka shayʾan', 'Hani o, babasına şöyle demişti: "Ey babacığım! Duymayan, görmeyen ve sana hiçbir fayda sağlamayan şeylere niçin tapıyorsun?"'),
(19, 43, 16, 308, 'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا', 'yā abati innī qad jāʾanī mina l-ʿilmi mā lam yaʾtika fāttabiʿnī ahdika ṣirāṭan saʾwiyyan', 'Ey babacığım! Bana, sana gelmemiş olan bir ilim gelmiştir. Bana uy ki seni doğru bir yola çıkarayım.'),
(19, 44, 16, 308, 'يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّا', 'yā ʾabati lā taʿbud-i sh-shayṭān ʾinna sh-shayṭāna kāna lir-raḥmāni ʿaṣiyyan', 'Ey babacığım! Şeytana kulluk etme. Şüphesiz şeytan, Rahmân''a isyan etmiştir.'),
(19, 45, 16, 308, 'يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّا', 'yā ʾabati ʾinnī ʾakhāfu ʾan yamassaka ʿaḏābun min ar-raḥmāni fatakūna liš-šayṭāni waliyyan', 'Ey babacığım! Doğrusu ben, Rahman (olan Allah) tarafından sana bir azap dokunmasından korkuyorum da sonra şeytana bir yardımcı olursun.'),
(19, 46, 16, 308, 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَٱهْجُرْنِى مَلِيًّا', 'qāla ʾarāġibun ʾanta ʿan ʾālihātī yā ʾibrāhīm laʾin lam tantahi laʾarjumannaka waʾhjurnī maliyyan', 'Babası şöyle dedi: ''Ey İbrahim! Sen benim ilâhlarımdan yüz mü çeviriyorsun? Eğer vazgeçmezsen, andolsun ki seni recmederim (taşlarım). Şimdi senden sonsuza dek ayrıl!'''),
(19, 47, 16, 308, 'قَالَ سَلَٰمٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ إِنَّهُۥ كَانَ بِى حَفِيًّا', 'qāla salāmun ʿalayka saʾastaghfiru laka rabbī ʾinnahu kāna bī ḥafiyyan', 'O, "Sana selam olsun! Rabbimden senin için mağfiret dileyeceğim. Çünkü O, bana çok lütufkârdır" dedi.'),
(19, 48, 16, 308, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّا', 'wa-ʾaʿtazilukum wa-mā tadʿūna min dūni-llāhi wa-ʾadʿū rabbī ʿasā ʾallā ʾakūna bi-duʿāʾi rabbī šaqiyyā', 'Ve sizi ve Allah''tan başka taptıklarınızı terk ediyorum. Rabbime dua ediyorum. Umarım Rabbime dua etmekle bedbaht olmam.'),
(19, 49, 16, 308, 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَكُلًّا جَعَلْنَا نَبِيًّا', 'fe-lemmā-ʿtazelehum ve-mā yaʿbudūne min dūni-llāh ve-hebnā lehu ʾisḥāqa ve-yaʿqūb ve-kullen jaʿalnā nabiyyan', 'Onlardan ve Allah''tan başka taptıklarından uzaklaştığı zaman, ona İshak''ı ve Yakub''u bahşettik ve her birini peygamber yaptık.'),
(19, 50, 16, 308, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا', 'wa wahabnā lahum min raḥmatinā wa jaʿalnā lahum lisāna ṣidqin ʿaliyyā', 'Onlara rahmetimizden bağışladık ve onlara yüce bir doğruluk dili (övülmüş bir anı) verdik.'),
(19, 51, 16, 308, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ إِنَّهُۥ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا', 'wa-dhkur fī l-kitābi Mūsā ʾinnahu kāna mukhlaṣan wa-kāna rasūlan nabiyyan', 'Kitapta Musa''yı da an. Çünkü o, ihlasa erilmiş bir kul ve (aynı zamanda) bir resul, bir nebî idi.'),
(19, 52, 16, 309, 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّا', 'wa-nādaynāhu min jānibi ṭ-ṭūri l-ʾaymani wa-qarrabnāhu najiyyan', 'Ve onu Tur''un sağ tarafından çağırdık ve kendisiyle gizli konuşmak için onu yaklaştırdık.'),
(19, 53, 16, 309, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّا', 'wa wahabnā lahu min raḥmatinā akhāhu Hārūna nabiyyan', 'Ve ona, kendi rahmetimizden, kardeşi Harun''u bir nebî olarak bahşettik.'),
(19, 54, 16, 309, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا', 'wa-dhkur fī l-kitābi ʾismāʿīla ʾinnahu kāna ṣādiqa l-waʿdi wa-kāna rasūlan nabiyyā', 'Kitapta İsmail''i de an. Gerçekten o, sözünde duran bir peygamberdi.'),
(19, 55, 16, 309, 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّا', 'wa kāna yaʾmuru ʾahlahū biṣ-ṣalāti waz-zakāti wa kāna ʿinda rabbihī marḍiyyan', 'Ve ailesine namazı ve zekâtı emrederdi ve Rabbi katında çok sevilmişti.'),
(19, 56, 16, 309, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', 'wa-dhkur fī l-kitābi idrīsa ʾinnahu kāna ṣiddīqan nabiyyan', 'Ve Kitap''ta İdris''i de an. Şüphesiz o, dosdoğru bir peygamberdi.'),
(19, 57, 16, 309, 'وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا', 'wa rafaʿnāhu makānan ʿaliyyā', 'Onu yüce bir makama yükselttik.'),
(19, 58, 16, 309, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًا وَبُكِيًّا', 'Ulâike-lleẕîne en’ama-llâhu ‘aleyhim mine-nnebiyyîn(e) min ẕürriyyeti âdeme vemimmen hamelnâ me’a nûhin vemin ẕürriyyeti ibrâhîme ve-isrâîl(e) vemimmen hedeynâ ve-ctebeynâ İẕâ tutlâ ‘aleyhim âyâtu-rrahmâni ħarrû succeden vebukiyyâ', 'İşte onlar, Allah''ın kendilerine nimet verdiği peygamberlerden, Âdem''in soyundan, Nuh ile birlikte taşıdıklarımızdan, İbrahim ve İsrail''in soyundan olanlardır. Ve hidayet verdiklerimizden ve seçtiklerimizdendirler. Rahman''ın ayetleri onlara okunduğunda secdeye kapanır ve ağlarlardı.'),
(19, 59, 16, 309, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ فَسَوْفَ يَلْقَوْنَ غَيًّا', 'faḫalafa minbaʿdihim ḫalfun ʾaḍāʿū ṣ-ṣalāta wattabaʿū š-šahawāti fasawfa yalqawna ġayyan', 'Onların ardından yerlerine, namazı zayi eden, şehvetlerine uyan bir nesil geldi. İşte onlar gayya''ya (cehennemdeki bir vadiye) boylanacaklardır.'),
(19, 60, 16, 309, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًٔا', 'illa men tāba wa-ʾāmana wa-ʿamila ṣāliḥan fa-ʾulāʾika yadkhulūna l-jannata wa-lā yuẓlamūna šayʾan', 'Ancak tövbe eden, iman eden ve salih amel işleyenler müstesnadır. İşte onlar cennete girecekler ve hiçbir şeyden haksızlığa uğramayacaklardır.'),
(19, 61, 16, 309, 'جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّا', 'jannāti ʿadnin allatī waʿada ʾar-raḥmānu ʿibādahu bil-ghaybi ʾinnahu kāna waʿduhu ʾmaʾtiyyan', 'Rahmân''ın, kullarına gıyaben vaadettiği Adn cennetleri; şüphesiz O''nun vaadi yerini bulacaktır.'),
(19, 62, 16, 309, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًا وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا', 'lā yasmaʿūna fīhā laghwan illā salāman wa lahum rizquhum fīhā bukrataw wa ʿashiyyan', 'Orada boş bir söz işitmezler; ancak ''Selam!'' derler. Orada rızıkları da sabah akşam (hazır)dır.'),
(19, 63, 16, 309, 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا', 'tilka l-jannatu llatī nūrithu min ʿibādinā man kāna taqiyyan', 'İşte bu, kullarımızdan takva sahibi olan kimselere miras vereceğimiz cennettir.'),
(19, 64, 16, 309, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ وَمَا كَانَ رَبُّكَ نَسِيًّا', 'wa mā natanazzalu illā bi-amri rabbika lahū mā bayna aydīnā wa mā khalfanā wa mā bayna dhālika wa mā kāna rabbuka nasiyyan', 'Biz (melekler) ancak Rabbinin emriyle ineriz. Önümüzde, ardımızda ve ikisinin arasında ne varsa hepsi O''na aittir. Senin Rabbin asla unutkan değildir.'),
(19, 65, 16, 310, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا', 'rabbü-s-semāwāti ve-l-ʾarḍi ve-mā beyynehumā fa-ʿbudhu ve-ṣṭabir li-ʿibādatihī hel taʿlemu lehu semiyyan', 'Göklerin, yerin ve ikisi arasında bulunan her şeyin Rabbidir. Şu halde O''na kulluk et ve O''nun kulluğuna sabret. Hiç O''nun adını taşıyan birini bilir misin?'),
(19, 66, 16, 310, 'وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', 'wa yaqūlu l-insānu aʾiḏā mā mittu lasawfa ʾuḫraju ḥayyan', 'İnsan der ki: "Ben öldüğüm zaman, diri olarak (kabrimden) çıkarılacak mıyım?"'),
(19, 67, 16, 310, 'أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًٔا', 'ʾa-wa-lā yadhkuru l-ʾinsānu ʾannanā khalaqnāhu min qablu wa-lam yaku šayʾan', 'İnsan, daha önce hiçbir şey değilken kendisini yarattığımızı hatırlamıyor mu?'),
(19, 68, 16, 310, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا', 'fa-wa-rabbika la-naḥshurannahum wa-l-shayāṭīna thumma la-nuḥḍirannahum ḥawla jahannama jithiyyā', 'Rabbine yemin olsun ki, onları ve şeytanları mutlaka bir araya toplayacağız, sonra da onları mutlaka cehennemin etrafında diz çökmüş bir halde hazır bulunduracağız.'),
(19, 69, 16, 310, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّا', 'thumma lananziaʿanna min kulli shīʿatin ayyuhum ashadd ʿalā r-raḥmāni ʿitiyyan', 'Sonra her topluluktan, Rahman''a karşı en çok azgın olanları mutlaka çekip alacağız.'),
(19, 70, 16, 310, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا', 'thumma lanaḥnu ʾaʿlamu bi-lladhīna hum ʾawlā bihā ṣaliyyā', 'Sonra biz elbette, oraya (ateşe) en çok müstahak olanları daha iyi biliriz.'),
(19, 71, 16, 310, 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا', 'wa-ʾin minkum ʾillā wāriduhā kāna ʿalā rabbika ḥatman maʾḍiyyan', 'İçinizden cehenneme varmayacak hiç kimse yoktur. Bu, Rabbin için kesinleşmiş bir hükümdür.'),
(19, 72, 16, 310, 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّا', 'thumma nunajjī allaḏīna ittaqaw wa nadharu ẓ-ẓālimīna fīhā jithiyyan', 'Sonra, takva sahiplerini kurtarırız ve zalimleri orada diz çökmüş halde bırakırız.'),
(19, 73, 16, 310, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا', 'wa-idhā tutlā ʿalayhim ʾāyātunā bayyinātin qāla alladhīna kafarū lilladhīna ʾāmanū ʾayyu l-farīqayni khayrun maqāman wa-ʾaḥsanu nadiyyan', 'Onlara açık seçik âyetlerimiz okunduğunda, kâfirler iman edenlere dediler ki: "Hangi tarafın makamı daha hayırlı, meclisi daha güzeldir?"'),
(19, 74, 16, 310, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًا وَرِءْيًا', 'wa-kam ahlāknā qablahum min qarnin hum aḥsanu athāthan wa-riʾyan', 'Onlardan önce nice nesilleri helak ettik ki, onlar hem mal ve mülkçe hem de görünüşçe daha güzel idiler.'),
(19, 75, 16, 310, 'قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا', 'Qul man kāna fīḍ-ḍalālati falyamdud lahu r-Raḥmānu maddan Ḥattā iḏā raʾaw mā yūʿadūna Immā l-ʿaḏāba wa immā s-sāʿata Fasayaʿlamūna man huwa šarrun makānan wa aḍʿafu jundan', 'De ki: "Kim sapıklık içinde ise, Rahman (olan Allah) onu uzattıkça uzatır. Nihayet kendilerine vaad olunan azabı veya (kıyamet) saatini gördükleri zaman, kimin yeri daha kötü ve kimin ordusu daha zayıf olduğunu bileceklerdir."'),
(19, 76, 16, 310, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًى وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا', 'wa yazīdu ʾallāhu lladhīna ʾhtadaw hudā wa l-bāqiyātu ṣ-ṣāliḥātu khayrun ʿinda rabbika thawāban wa khayrun maraddan', 'Allah, doğru yola gidenlerin hidayetini artırır. Baki kalacak olan salih ameller, Rabbinin katında sevap bakımından da, akıbet bakımından da daha hayırlıdır.'),
(19, 77, 16, 311, 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا', 'ʾafaraʾayta lladhī kafara bi-ʾāyātinā waqāla la-ʾūtiyanna mālan wa-waladan', 'Şimdi âyetlerimizi inkâr eden ve "Bana mutlaka mal ve evlat verilecek" diyen kimseyi gördün mü?'),
(19, 78, 16, 311, 'أَطَّلَعَ ٱلْغَيْبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًا', 'aṭṭalaʿa l-ghayba ami-ttakhaḏa ʿinda r-raḥmāni ʿahdan', 'Yoksa gaybı mı bildi, yoksa Rahman''ın katında bir ahit mi aldı?'),
(19, 79, 16, 311, 'كَلَّا سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلْعَذَابِ مَدًّا', 'kallā sanaktubu mā yaqūlu wa namuddu lahu min al-ʿaḏābi maddā', 'Hayır! Söylemekte olduklarını yazacağız ve azabı iyice uzatacağız.'),
(19, 80, 16, 311, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَأْتِينَا فَرْدًا', 'wa narithuhu ma yaqoolu wa ya''teena fardan', 'Söylediği şeyleri ona miras bırakacağız ve bize yalnız gelecek.'),
(19, 81, 16, 311, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لِّيَكُونُوا۟ لَهُمْ عِزًّا', 'wa-ttakhadhū min dūni Allāhi ʾālihatan li-yakūnū lahum ʿizzan', 'Ve Allah''tan başka ilahlar edindiler, kendilerine bir izzet (güç, şeref) olmaları için.'),
(19, 82, 16, 311, 'كَلَّا سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا', 'kallā sayakfurūna biʿibādatihim wayakūnūna ʿalayhim ḍiddan', 'Hayır! Onların ibadetlerini inkâr edecekler ve onlara düşman olacaklardır.'),
(19, 83, 16, 311, 'أَلَمْ تَرَ أَنَّآ أَرْسَلْنَا ٱلشَّيَٰطِينَ عَلَى ٱلْكَٰفِرِينَ تَؤُزُّهُمْ أَزًّا', 'elem tera enna arsalna ash-shayateena ''ala al-kafireena ta''uzzuhum azzan', 'Onları iyice kışkırtıp azdıran şeytanları o kâfirlerin üzerine gönderdiğimizi görmedin mi?'),
(19, 84, 16, 311, 'فَلَا تَعْجَلْ عَلَيْهِمْ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا', 'falā taʿjal ʿalayhim innamā naʿuddu lahum ʿaddan', 'Onlar için acele etme. Biz onların günlerini sayıp duruyoruz.'),
(19, 85, 16, 311, 'يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَٰنِ وَفْدًا', 'yawma naḥshuru l-muttaqīna ilā r-raḥmāni wafdan', 'O gün, Allah''a karşı gelmekten sakınanları, Rahman''ın huzuruna birer heyet halinde toplayacağımız günü (hatırla).'),
(19, 86, 16, 311, 'وَنَسُوقُ ٱلْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًا', 'wa nasūqu l-mujrimīna ʾilā jahannama wirdan', 'Ve suçluları susamış bir halde cehenneme süreriz.'),
(19, 87, 16, 311, 'لَّا يَمْلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًا', 'lā yamlikūna sh-shafāʿata illā man-ittakhadha ʿinda r-raḥmāni ʿahdan', 'Rahmân katında bir ahid edinmiş olanlar dışında, hiç kimse şefaat hakkına sahip olamaz.'),
(19, 88, 16, 311, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا', 'wa qālū ʾittakhaḏa ʾar-raḥmānu waladan', 'Ve dediler ki: "Rahmân, bir çocuk edinmiştir."'),
(19, 89, 16, 311, 'لَّقَدْ جِئْتُمْ شَيْـًٔا إِدًّا', 'leḳad ciʾtüm şeyʾen idden', 'Andolsun ki siz, çok çirkin bir şey yaptınız.'),
(19, 90, 16, 311, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ٱلْأَرْضُ وَتَخِرُّ ٱلْجِبَالُ هَدًّا', 'takādu s-semāwātu yetafaṭṭarna minhu wa tanshaqqu l-arḍu wa takhirru l-jibālu haddan', 'Neredeyse gökler ondan parçalanacak, yer yarılacaktı ve dağlar yıkılıp düşecekti.'),
(19, 91, 16, 311, 'أَن دَعَوْا۟ لِلرَّحْمَٰنِ وَلَدًا', 'ʾan daʿaw li-r-raḥmāni waladan', 'Çünkü Rahman olan Allah''a bir çocuk isnat ettiler.'),
(19, 92, 16, 311, 'وَمَا يَنۢبَغِى لِلرَّحْمَٰنِ أَن يَتَّخِذَ وَلَدًا', 've-mā yenbeġī lir-raḥmāni en yetteḫiḏa veledan', 'Oysa Rahmân için bir çocuk edinmek söz konusu olamaz.'),
(19, 93, 16, 311, 'إِن كُلُّ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِلَّآ ءَاتِى ٱلرَّحْمَٰنِ عَبْدًا', 'in kullu men fi-s-semāwāti ve-l-arḍi illā ʾātī-r-raḥmāni ʿabdan', 'Göklerde ve yerde kim varsa, Rahman''a kul olarak gelecektir.'),
(19, 94, 16, 311, 'لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّا', 'laqad aḥṣāhum wa ʿaddahum ʿaddan', 'Andığın gibi, onları tek tek saymış ve tek tek saymıştır.'),
(19, 95, 16, 311, 'وَكُلُّهُمْ ءَاتِيهِ يَوْمَ ٱلْقِيَٰمَةِ فَرْدًا', 'wa kulluhum ʾātihi yawma l-qiyāmati fardan', 'Ve her biri, kıyamet gününde O''na tek başına gelecektir.'),
(19, 96, 16, 312, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَيَجْعَلُ لَهُمُ ٱلرَّحْمَٰنُ وُدًّا', 'ʾinna lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti sayajʿalu lahumu r-raḥmānu wuddan', 'Şüphesiz iman edip salih amel işleyenler için, Rahman (olan Allah) göğüslerinde bir sevgi (ve yakınlık) yaratacaktır.'),
(19, 97, 16, 312, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْمًا لُّدًّا', 'fa-innamā yassarnāhu bi-lisānika li-tubashshira bihi l-muttaqīna wa-tunḏira bihi qawman luddan', 'Onu senin dilinde (indirerek) kolaylaştırmamızın sebebi, müttakileri müjdelemen ve azgın bir toplumu uyarman içindir.'),
(19, 98, 16, 312, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًۢا', 've kem ehleknā kablehum min karnin hel tuḥissu minhum min aḥadin ev tesmeʿu lehum rikzā', 'Onlardan önce nice nesilleri helak ettik. Onlardan herhangi birini hissediyor musun veya onların hafif bir sesini işitiyor musun?'),
(20, 1, 16, 312, 'طه', 'ṭāhā', 'Tâ, Hâ.'),
(20, 2, 16, 312, 'مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ', 'Mā anzalnā ʿalayka l-Qurʾāna li-tashqā', 'Sana bu Kur''an''ı sıkıntıya uğrayasın diye indirmedik.'),
(20, 3, 16, 312, 'إِلَّا تَذْكِرَةً لِّمَن يَخْشَىٰ', 'illa tadhkiratan liman yakhsha', 'Ancak Allah''tan gereğince korkan kimseler için bir öğüt (bir hatırlatmadır).'),
(20, 4, 16, 312, 'تَنزِيلًا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَٰوَٰتِ ٱلْعُلَى', 'tanzīlan mimmam ḵalaqa l-arḍa wa-s-samāwāti l-ʿulā', 'Yeri ve gökleri yaratan tarafından indirilmiştir.'),
(20, 5, 16, 312, 'ٱلرَّحْمَٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ', 'ar-raḥmānu ʿalā l-ʿarshi stawā', 'Rahmân, Arş''a istivâ etti.'),
(20, 6, 16, 312, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ٱلثَّرَىٰ', 'lahū mā fī s-samāwāti wa mā fī l-arḍi wa mā baynahumā wa mā taḥta th-thará', 'Göklerde ve yerde ne varsa, ikisinin arasında ve toprağın altında ne varsa hepsi O''nundur.'),
(20, 7, 16, 312, 'وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى', 'wa ʾin tajhar bil-qawli fa ʾinnahuu yaʿlamu s-sirra wa ʾakhfaa', 'Ve eğer sözü açığa vuracak olursan, şüphesiz O, gizli olanı ve daha gizli olanı bilir.'),
(20, 8, 16, 312, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ', 'Allāhu lā ilāha illā huw lahu l-asmāʾu l-ḥusnā', 'Allah! O''ndan başka ilah yoktur. En güzel isimler O''nundur.'),
(20, 9, 16, 312, 'وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'wa hal atāka ḥadīthu mūsā', 'Musa''nın haberi sana geldi mi?'),
(20, 10, 16, 312, 'إِذْ رَءَا نَارًا فَقَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى ٱلنَّارِ هُدًى', 'iḏ raʾā nāran fa-qāla li-ʾahlihi ʾimkuṯū ʾinnī ʾānastu nāran laʿallī ʾātīkum minhā bi-qabasin ʾaw ʾajidu ʿalā n-nāri hudan', 'Hani o, bir ateş görmüş ve ailesine şöyle demişti: "Siz burada kalın, çünkü ben bir ateş gördüm, belki ondan size bir kor getiririm ya da ateşin yanında bir yol gösterici bulurum."'),
(20, 11, 16, 312, 'فَلَمَّآ أَتَىٰهَا نُودِىَ يَٰمُوسَىٰٓ', 'fe-lemmā atāhā nūdiye yā Mūsā', 'Böylece ona geldiği zaman, ona şöyle nida olundu: "Ey Musa!"'),
(20, 12, 16, 312, 'إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 'ʾinnī ʾanā rabbuka fa-ḵlaʿ naʿlayka ʾinnaka bi-l-wādi l-muqaddasi ṭuvā', 'Şüphesiz Ben, Ben senin Rabbinim. Ayakkabılarını çıkar. Çünkü sen, mukaddes (kutsal) vadi olan Tuvâ''dasın.'),
(20, 13, 16, 313, 'وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ', 'wa-ʾanā ʾikhtar-tuk fa-stamiʿ limā yūḥā', 'Ve seni seçtim, öyleyse vahyedileni dinle!'),
(20, 14, 16, 313, 'إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ', 'ʾinnani ʾanā ʾallāhu lā ʾilāha ʾillā ʾanā faʿbudnī waʾaqimi ṣ-ṣalāta lidh-dhikrī', 'Şüphesiz Ben Allah''ım! Benden başka hiçbir ilah yoktur. Bana kulluk et ve beni zikretmek (anmak) için dosdoğru namaz kıl.'),
(20, 15, 16, 313, 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا تَسْعَىٰ', 'inna as-sāʿata ʾātiyah ʾakādu ʾukhfīhā li-tujzā kullu nafsin bimā tasʿā', 'Şüphesiz kıyamet gelip çatacaktır. Herkesin kazandığına göre karşılığını alması için, onu neredeyse gizli tutuyorum.'),
(20, 16, 16, 313, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُؤْمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرْدَىٰ', 'falā yaṣuddannaka ʿanhā man lā yuʾminu bihā wattabaʿa hawāhu fatardā', 'Sakın ondan (yüz çevirme), çünkü ona inanmayan ve kendi hevasına uyan kimse seni ondan alıkoymasın. Sonra helak olursun.'),
(20, 17, 16, 313, 'وَمَا تِلْكَ بِيَمِينِكَ يَٰمُوسَىٰ', 'wa mā tilka bi-yamīnika yā Mūsā', 'Ey Musa! Sağ elindeki nedir?'),
(20, 18, 16, 313, 'قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُا۟ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔارِبُ أُخْرَىٰ', 'qāla hiya ʿaṣāya ʾatawakkaʾu ʿalayhā wa ʾahushshu bihā ʿalā ġanamī wa lī fīhā maʾāribu ʾuḫrā', 'O, "Bu benim asamdır; ona dayanırım, onunla davarlarımı (ağaçlardan) silkerim ve ondan başka faydalar da sağlarım" dedi.'),
(20, 19, 16, 313, 'قَالَ أَلْقِهَا يَٰمُوسَىٰ', 'qāla ʾalqihā yā Mūsā', 'Allah şöyle buyurdu: "Ey Musa, onu at!"'),
(20, 20, 16, 313, 'فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌ تَسْعَىٰ', 'fa-alqāhā fa-idhā hiya ḥayyatun tasʿā', 'Böylece onu attı. Bir de ne görsün, o, (yerde) yürüyen bir yılan oluverdi.'),
(20, 21, 16, 313, 'قَالَ خُذْهَا وَلَا تَخَفْ سَنُعِيدُهَا سِيرَتَهَا ٱلْأُولَىٰ', 'qāla khudh-hā wa lā takhaf sanuʿīduhā sīratahā l-ʾūlā', 'Allah şöyle buyurdu: "Al onu ve korkma! Biz onu eski haline döndüreceğiz."'),
(20, 22, 16, 313, 'وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ', 'wa-ḍmum yadaka ilā janāḥika takharju bayḍāʾa min ghayri sūʾin āyatan ʾukhrā', 'Elini kanadına (koltuk altına) sok, kusursuz (birazdan) bembeyaz bir halde çıkacaktır. Bu, başka bir mucizedir.'),
(20, 23, 16, 313, 'لِنُرِيَكَ مِنْ ءَايَٰتِنَا ٱلْكُبْرَى', 'li-nuriyaka min ʾāyātinā al-kubrā', 'Sana en büyük ayetlerimizden bir kısmını göstermek için.'),
(20, 24, 16, 313, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'idhhab ilā firʿawna ʾinnahu ṭaghā', 'Firavun''a git. Çünkü o, azmış bulunuyor.'),
(20, 25, 16, 313, 'قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى', 'qāla rabbi-ʾšraḥ lī ṣadrī', 'Musa dedi ki: "Rabbim! Gönlümü aç, ferahlat."'),
(20, 26, 16, 313, 'وَيَسِّرْ لِىٓ أَمْرِى', 'wa yassir lī amrī', 'Ve işimi bana kolaylaştır.'),
(20, 27, 16, 313, 'وَٱحْلُلْ عُقْدَةً مِّن لِّسَانِى', 'wa-ḥlul ʿuqdatam min lisānī', 'Ve dilimdeki düğümü çöz.'),
(20, 28, 16, 313, 'يَفْقَهُوا۟ قَوْلِى', 'yafquhū qawlī', 'Sözlerimi iyice anlasınlar.'),
(20, 29, 16, 313, 'وَٱجْعَل لِّى وَزِيرًا مِّنْ أَهْلِى', 'wa-jʿal lī wazīran min ahli', 'Ve ailemden bana bir yardımcı kıl!'),
(20, 30, 16, 313, 'هَٰرُونَ أَخِى', 'Hārūna ʾaḫī', 'Harun, kardeşim'),
(20, 31, 16, 313, 'ٱشْدُدْ بِهِۦٓ أَزْرِى', 'ishdud bihi ʾazrī', 'Onunla sırtımı (iyice) pekiştir.'),
(20, 32, 16, 313, 'وَأَشْرِكْهُ فِىٓ أَمْرِى', 'wa-ʾašrikhu fī ʾamrī', 'Ve onu işimde de bana ortak kıl.'),
(20, 33, 16, 313, 'كَىْ نُسَبِّحَكَ كَثِيرًا', 'kay nusabbiḥaka kathīran', 'Onu çok tesbih edelim diye.'),
(20, 34, 16, 313, 'وَنَذْكُرَكَ كَثِيرًا', 'wa nadhkuraka kathīran', 'Ve seni çok zikredelim.'),
(20, 35, 16, 313, 'إِنَّكَ كُنتَ بِنَا بَصِيرًا', 'ʾinnaka kunta binā baṣīran', 'Şüphesiz sen bizi görüyor idin.'),
(20, 36, 16, 313, 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ', 'qāla qad ūtīta suʾlaka yā mūsā', 'Allah şöyle buyurdu: "Ey Musa! İstediğin şey sana verilmiştir."'),
(20, 37, 16, 313, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', 'Ve lekad menennâ aleyke merraten uhrâ', 'Andolsun ki sana bir başka defa daha lütufta bulunmuştuk.'),
(20, 38, 16, 314, 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 'idh awḥaynā ilā ummika mā yūḥā', 'Hani annene vahyettiğimizi vahyettiğimiz zamanı hatırla.'),
(20, 39, 16, 314, 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُۥ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', 'ani-qḏifīhi fī-t-tābūti fa-qḏifīhi fī-l-yemmi fa-l-yulqihi-l-yammu bi-s-sāḥili yaʾḫuḏhu ʿaduwwun lī wa-ʿaduwwun lahu wa-ʾalqaytu ʿalayka maḥabbatan minnī wa-li-tuṣnaʿa ʿalā ʿaynī', 'Onu sandığa bırak, sonra onu denize bırak; deniz onu karaya atsın; onu bana düşman olan ve ona da düşman olan biri alacaktır. Hem sana benden bir sevgi (sevgililik) vermiştir ve gözümün önünde yetiştirilmen için (bunu yaptık).'),
(20, 40, 16, 314, 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًا فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَٰمُوسَىٰ', 'idh tamshī ukhtuka fataqūlu hal adullukum ʿalā man yakfuluhū farajaʿnāka ilā ummika kay taqarra ʿayunuhā walā taḥzana waqatalta nafṣan fanajjaynāka mina l-ghammi wafatannāka futūnan falabithta sinīna fī ahli madyana thumma jiʾta ʿalā qadarin yā mūsā', 'Hani kız kardeşin (onun yanına gidip): ''Onu himayesine alacak birini size göstereyim mi?'' diyordu. Böylece seni, gözü aydınlanıp üzülmemen için annene geri verdik. Sen bir de birini öldürmüştün; biz de seni o gamdan kurtarmış ve seni çeşitli sıkıntılarla denemiştik. Sonra yıllarca Medyen halkı arasında kaldın. Nihayet ey Musa, (vakti gelince) bana geldin.'),
(20, 41, 16, 314, 'وَٱصْطَنَعْتُكَ لِنَفْسِى', 'wa-ṣṭanaʿtuka li-nafsī', 'Ve seni Kendim için seçtim (yetiştirdim).'),
(20, 42, 16, 314, 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى', 'idhhab anta wa akhuka bi-āyātī wa lā taniyā fī dhikrī', 'Sen ve kardeşin ayetlerimle gidin ve beni anmada gevşeklik göstermeyin.'),
(20, 43, 16, 314, 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'idh''habā ilā Fir''awn innahuu ṭaghā', 'Haydi ikiniz Firavun''a gidin. Şüphesiz o azmıştır.'),
(20, 44, 16, 314, 'فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', 'faqūlā lahu qawlan layyinā laʿallahu yatażakkaru aw yakhshā', 'Böylece ona yumuşak bir söz söyleyin; olur ki, öğüt alıp düşünür ya da (Allah''tan) korkar.'),
(20, 45, 16, 314, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', 'qālā rabbana ʾinnanā nakhāfu ʾan yafruṭa ʿalaynā ʾaw ʾan yaṭghā', 'Dediler ki: "Rabbimiz! Doğrusu biz, onun bize hemen azap etmesinden veya azgınlığını artırmasından korkuyoruz."'),
(20, 46, 16, 314, 'قَالَ لَا تَخَافَآ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ', 'qāla lā takhāfā ʾinnanī maʿakumā ʾasmaʿu wa ʾarā', 'Buyurdu: "Korkmayın! Şüphesiz Ben sizinle beraberim; işitirim ve görürüm."'),
(20, 47, 16, 314, 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَٰكَ بِـَٔايَةٍ مِّن رَّبِّكَ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', 'faʾtiyāhu faqūlā ʾinnā rasūlā rabbika faʾarsil maʿanā banī ʾisrāʾīla walā tuʿaḏḏibhum qad jiʾnāka bi-ʾāyatin min rabbika was-salāmu ʿalā mani-ttabaʿa al-hudā', 'Buna göre ona gidin ve deyin ki: ''Biz Rabbinin elçileriyiz. İsrailoğullarını bizimle birlikte (Mısır''dan) gönder. Onlara azap etme! Andolsun ki sana Rabbinden açık bir delil getirdik. Kim doğru yola (hidayete) uyarsa, selamet onunla olur.'''),
(20, 48, 16, 314, 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', 'ʾinnā qad ʾūḥiya ʾilaynā ʾanna l-ʿaḏāba ʿalā man kaḏḏaba wa-tawallā', 'Şüphesiz ki bize, azabın, yalanlayıp yüz çeviren kimseye isabet edeceği vahyolundu.'),
(20, 49, 16, 314, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', 'qāla faman rabbukumā yā mūsā', 'Firavun: ''Ey Musa! Sizin Rabbiniz kimdir?'' dedi.'),
(20, 50, 16, 314, 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', 'qāla rabbunā alladhī ʾaʿṭā kulla shayin khalqahū thumma hadā', 'O, Rabbimizdir ki her şeye hilkatini (yaradılış cevherini) vermiş, sonra da ona (muhtaç olduğu şeyleri) ilham etmiştir.'),
(20, 51, 16, 314, 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', 'qāla famā balu l-qurūni l-ʾūlā', 'O, şöyle dedi: "Önceki nesillerin durumu neydi?"'),
(20, 52, 16, 315, 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', 'qāla ʿilmuhā ʿinda rabbī fī kitābin lā yaḍillu rabbī walā yansā', 'Musa dedi ki: "Onun bilgisi Rabbimin katında, (gizli) bir kitaptadır. Rabbim şaşırmaz ve unutmaz."'),
(20, 53, 16, 315, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًا مِّن نَّبَاتٍ شَتَّىٰ', 'alladhī jaʿala lakumu l-arḍa mahdan wa salaka lakum fīhā subulan wa anzala mina s-samāʾi māʾan fa ʾakhrajnā bihi ʾazwājan min nabātin shattā', 'O ki, yeri sizin için bir beşik yaptı, orada size yollar açtı ve gökten bir su indirdi. Bununla türlü türlü bitkilerden çiftler çıkardık.'),
(20, 54, 16, 315, 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', 'kulū wa-rʿaw anʿāmakum inna fī dhālika la-ʾāyātin li-ʾulī n-nuhā', 'Yiyin ve hayvanlarınızı otlatın. Şüphesiz bunlarda, aklı erenler için (Allah''ın varlığına) nice deliller vardır.'),
(20, 55, 16, 315, 'مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', 'min-hā ḫalaqnākum ve fī-hā nuʿīdukum ve min-hā nuḫricukum tāratan ʾuḫrā', 'Sizi ondan yarattık, sizi ona iade edeceğiz ve sizi bir kere daha ondan çıkaracağız.'),
(20, 56, 16, 315, 'وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', 'Ve lekad ereynâhu âyâtinâ kullehâ fekezzebe ve ebâ', 'Andolsun ki ona bütün ayetlerimizi gösterdik de o yalanladı ve yüz çevirdi.'),
(20, 57, 16, 315, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ', 'qāla ʾajiʾtanā litukhrijanā min ʾarḍinā bisiḥrika yā mūsā', 'Firavun dedi ki: "Ey Musa! Büyünle bizi toprağımızdan çıkarmak için mi geldin?"'),
(20, 58, 16, 315, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًا سُوًى', 'fele neʾtiyenneke bisihrin mislihī fe-icʿal beynenā vebeyneke mevʿiden lā nuḫlifuhū naḥnu velā ente mekānen suven', 'Biz de sana onun benzeri bir sihirle geleceğiz. Şimdi bizimle senin aranda bir buluşma yeri ve zamanı tayin et ki, ne biz cayalım ne de sen; düz bir yerde olsun.'),
(20, 59, 16, 315, 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًى', 'qāla mawʿidukum yawmu ʾz-zīnati wa-ʾan yuḥshara ʾn-nāsu ḍuḥan', 'Mûsa dedi ki: "Sizinle buluşma vakti, Zînet Günüdür ve insanların toplanacağı vakit de kuşluk vaktidir."'),
(20, 60, 16, 315, 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', 'fa tawallā firʿawnu fa jamaʿa kaydahū thumma atā', 'Bunun üzerine Firavun dönüp gitti, hilesini topladı, sonra geldi.'),
(20, 61, 16, 315, 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', 'qāla lahum mūsā waylakum lā taftirū ʿalā allāhi kadhiban fayusḥitakum biʿadhābin waqad khāba mani ʾiftarā', 'Musa onlara şöyle dedi: "Yazıklar olsun size! Allah''a yalan uydurarak O''nun azabıyla kökünüzü kesip yok ettirmeyin. Kim yalan uydurursa mutlaka perişan olur."'),
(20, 62, 16, 315, 'فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', 'fa-tanāzaʿū ʾamrahum baynahum wa-ʾasarru an-najwā', 'Bunun üzerine, aralarındaki işi tartıştılar ve gizlice konuştular.'),
(20, 63, 16, 315, 'قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', 'qālū ʾin hāḏāni lasāḥirāni yurīdāni ʾan yuḫrijākum min ʾarḍikum bisiḥrihimā wa yaḏhabā bi ṭarīqatikumu l-muṯlā', 'Dediler ki: "Bu ikisi, büyüleriyle sizi yurdunuzdan çıkarmak ve sizin örnek yolunuzu ortadan kaldırmak isteyen iki büyücüdür."'),
(20, 64, 16, 315, 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّا وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', 'faʾajmiʿū kaydakum thumma ʾtū ṣaffan waqad ʾaflaḥa l-yawma mani ʾstʿalā', 'Bunun üzerine hilelerinizi toplayın, sonra saf halinde (toplanıp) gelin. Ve kim üstün gelirse, bugün gerçekten kurtulmuştur.'),
(20, 65, 16, 316, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', 'qālū yā Mūsā immā an tulqiya wa immā an nakūna awwala man alqā', 'Dediler ki: "Ey Musa! Sen mi (önce) atacaksın, yoksa biz mi ilk atanlar olacağız?"'),
(20, 66, 16, 316, 'قَالَ بَلْ أَلْقُوا۟ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', 'qāla bal ʾalqū faʾiḏā ḥibāluhum waʿiṣiyyuhum yuxayylu ʾilayhi min siḥrihim ʾannahā tasʿā', 'O, ''Hayır! Siz atın!'' dedi. Bir de ne görsün, onların ipleri ve değnekleri, sihirden ötürü kendisine sanki koşuyormuş gibi göründü.'),
(20, 67, 16, 316, 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةً مُّوسَىٰ', 'fa-awjasa fī nafsihī khīfatan Mūsā', 'Bunun üzerine Musa, içinde bir korku hissetti.'),
(20, 68, 16, 316, 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', 'qulnā lā takhaf innaka anta l-ʾaʿlā', 'Biz, "Korkma! Şüphesiz sen, üstün olan sensin!" dedik.'),
(20, 69, 16, 316, 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', 'wa-ʾalqi mā fī yamīnika talqafu mā ṣanaʿū ʾinnamā ṣanaʿū kaydu sāḥirin wa-lā yufliḥu s-sāḥiru ḥaythu ʾatā', 'Elindeki değneği bırak! Onların yaptığını yutacaktır. Onların yaptıkları ancak bir sihirbaz hilesidir. Sihirbaz ise nerede olsa kurtulamaz.'),
(20, 70, 16, 316, 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', 'faʾulqiya s-saḥaratu sujjadan qālū ʾāmannā birabbi hārūna wa-mūsā', 'Büyücüler secdeye kapandılar ve şöyle dediler: "İman ettik Harun''un ve Musa''nın Rabbine."'),
(20, 71, 16, 316, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًا وَأَبْقَىٰ', 'qāla ʾāmantum lahu qabla ʾan ʾādhana lakum ʾinnahu lakabīrukumu lladhī ʿallamakumu s-siḥra falaʾuqaṭṭiʿanna ʾaydiyakum waʾarjulakum min ḵilāfin walaʾuṣallibannakum fī juḏūʿi n-naxli walataʿlamunna ʾayyunā ʾašaddu ʿaḏāban waʾabqā', 'Firavun: "Ben size izin vermeden önce ona iman ettiniz ha! Andolsun ki, ellerinizi ve ayaklarınızı çapraz olarak keseceğim ve hepinizi hurma dallarına asacağım. Böylece hangimizin azabının daha şiddetli ve daha kalıcı olduğunu öğreneceksiniz!" dedi.'),
(20, 72, 16, 316, 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا فَٱقْضِ مَآ أَنتَ قَاضٍ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', 'qālū lan nuʾthiraka ʿalā mā jāʾanā mina l-bayyināti wa-lladhī faṭaranā fa-qḍi mā ʾanta qāḍin ʾinnamā taqḍī hādhihi l-ḥayāta d-dunyā', 'Onlar, "Biz sana, bize gelen açık delillere ve bizi yaratan Yüce Allah''a tercih edemeyiz. Şimdi sen, vereceğin hükmü ver. Çünkü sen ancak bu dünya hayatına hükmedebilirsin" dediler.'),
(20, 73, 16, 316, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ وَٱللَّهُ خَيْرٌ وَأَبْقَىٰٓ', 'ʾinnā ʾāmannā birabbinā liyaġfira lanā ḫaṭāyānā wa mā ʾakrah-tanā ʿalayhi mina s-siḥr wa-llāhu ḫayrun wa ʾabqā', 'Şüphesiz biz Rabbimize iman ettik. O da bizim günahlarımızı ve senin bizi yapmaya zorladığın sihri bağışlasın. Allah, (sevap ve azap bakımından) hayırlı ve (mükafat ve cezası) daha kalıcıdır.'),
(20, 74, 16, 316, 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'ʾinnahuu man yaʾti rabbahuu mujriman faʾinna lahuu jahannama laa yamūtu fiihā wa laa yaḥyāa', 'Şüphesiz ki, Rabbine suçlu olarak gelen kimse için cehennem vardır; orada ne ölür ne de hayat bulur.'),
(20, 75, 16, 316, 'وَمَن يَأْتِهِۦ مُؤْمِنًا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ', 'Ve men ye''tihi mu''minen kad ''amile es-sâlihâti fe''ulâike lehumu ed-deracâtu el-''ulâ', 'Kim de ona mümin olarak ve salih ameller işlemiş bir halde gelirse, işte onlar için en yüksek dereceler vardır.'),
(20, 76, 16, 316, 'جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', 'jannātu ʿadnin tajrī min taḥtihā l-anhāru khālidīna fīhā wa dhālika jazāʾu man tazakkā', 'Adn cennetleri, içinden ırmaklar akan, orada ebediyen kalacakları. İşte bu, arınanların mükâfatıdır.'),
(20, 77, 16, 317, 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًا فِى ٱلْبَحْرِ يَبَسًا لَّا تَخَٰفُ دَرَكًا وَلَا تَخْشَىٰ', 'Ve lekad evhaynâ ilâ Mûsâ en esri biʿibâdî faḍrib lehum tarîkan fîl baḥri yebesen lâ teḫâfu deraken ve lâ taḫşâ', 'Andolsun ki Musa''ya şöyle vahyettik: "Kullarımı geceleyin yola çıkar; onlar için denizde kuru bir yol aç. Yetişilmekten korkma ve endişe etme."'),
(20, 78, 16, 317, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', 'fa-atbaʿahum firʿawnu bi-junūdihī fa-ghashiyahum mina l-yammi mā ghashiyahum', 'Böylece Firavun ordusuyla onların peşine düştü. Onları denizden ne kapladıysa kapladı.'),
(20, 79, 16, 317, 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', 'wa ʾaḍalla firʿawnu qawmahū wamā hadā', 'Firavun da kavmini saptırdı ve onlara doğru yolu göstermedi.'),
(20, 80, 16, 317, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', 'yā banī ʾisrāʾīla qad ʾanjaynākum min ʿadūwwikkum wa wāʿadnākum jāniba ṭ-ṭūri l-ʾaymana wa nazalna ʿalaykumu l-manna wa s-salwā', 'Ey İsrailoğulları! Sizi düşmanınızdan kurtardığımızı ve Tûr''un sağ yanına size bir vaatte bulunduğumuzu ve üzerinize men ve salwâ indirdiğimizi hatırlayın.'),
(20, 81, 16, 317, 'كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', 'kulū min tayyibāti mā razaqnākum walā taṭghaw fīhi fayaḥilla ʿalaykum ghaḍabī waman yaḥlil ʿalayhi ghaḍabī faqad hawā', 'Size verdiğimiz rızıkların temiz olanlarından yiyin, bu hususta azgınlık etmeyin ki gazabım üzerinize inmesin. Kimin üzerine gazabım inerse, o gerçekten helak olmuş olur.'),
(20, 82, 16, 317, 'وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا ثُمَّ ٱهْتَدَىٰ', 'waʾinnī laghaffārun liman tāba waʾāmana waʿamila ṣāliḥan thumma ʾhtadā', 'Ve şüphesiz ben, tevbe eden, iman eden, salih amel işleyen ve sonra doğru yolu tutan kimse(ler) için elbette çok bağışlayıcıyım.'),
(20, 83, 16, 317, 'وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ', 'wa mā ʾaʿjalaka ʿan qawmika yā Mūsā', 'Ey Musa! Seni kavminden (ayrılıp) acele getiren nedir?'),
(20, 84, 16, 317, 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', 'qāla hum ʾūlāʾi ʿalā ʾaṯarī wa ʿajiltu ʾilayka rabbi li-tarḍā', 'Dedi ki: "Onlar benim peşimdeler, ben de Senden razı olman için sana gelmekte acele ettim."'),
(20, 85, 16, 317, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', 'qāla fa-ʾinnanā qad fatannā qawmaka min baʿdika wa-ʾaḍallahumu s-sāmiriyyu', 'Dedi ki: "Şüphesiz biz senden sonra kavmini imtihana çektik ve Sâmirî onları saptırdı."'),
(20, 86, 16, 317, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', 'farajaʿa mūsā ʾilā qawmihī ġaḍbāna ʾasifā qāla yā qawmi ʾalam yaʿidkum rabbukum waʿdan ḥasanā ʾafaṭāla ʿalaykumu l-ʿahdu ʾam ʾaradtum ʾan yaḥilla ʿalaykum ġaḍabun min rabbikum fa-ʾaḫlaftum mawʿidī', 'Bunun üzerine Musa, kavmine kızgın ve üzgün bir halde döndü. Dedi ki: "Ey kavmim! Rabbiniz size güzel bir vaadde bulunmadı mı? Yoksa bu süre uzadı da bana mı uymadınız, yoksa Rabbinizden üzerinize bir gazap inmesini mi istediniz de bana verdiğiniz sözden caydınız?"'),
(20, 87, 16, 317, 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', 'qālū mā ʾakhlafna mawʿidaka bimalkinā walākinna ḥummilnā ʾawzāran min zīnati l-qawmi fayaqadhfanhā fakadhālika ʾalqā s-sāmiriyyu', 'Dediler ki: "Sana verdiğimiz sözden, gücümüz yettiği halde biz caymadık. Fakat biz, (Mısırlıların) ziynet eşyalarından bir takım ağır yükler yüklenmiştik. Sonra onları attık. İşte böylece Samiri de attı."'),
(20, 88, 16, 318, 'فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ', 'faʾakhraja lahum ʿijlan jasadāan lahū khuwārun fapālū hādhā ʾilāhukum waʾilāhu mūsā fanasiya', 'Bunun üzerine onlara böğürebilen bir buzağı heykeli çıkardı ve "Bu sizin tanrınızdır ve Musa''nın da tanrısıdır, fakat o unuttu" dediler.'),
(20, 89, 16, 318, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا', 'ʾafalā yarawna ʾallā yarjiʿu ʾilayhim qawlan walā yamliku lahum ḍarran walā nafʿan', 'Onların, kendilerine hiçbir sözle cevap vermediğini ve onlara ne bir zarar ne de bir fayda sağlama gücüne sahip olmadığını görmüyorlar mı?'),
(20, 90, 16, 318, 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', 'Ve lekad kāle lehum Hārūnu min kablu Yā kavmi innamā futintum bihī Ve inne rabbekumu''r-Rahmānu Fettebiʿūnī ve etīʿū emrī', 'Andolsun ki Harun daha önce onlara şöyle demişti: “Ey kavmim! Siz onunla imtihan edildiniz. Şüphesiz sizin Rabbiniz Rahman’dır. Öyleyse bana uyun ve emrime itaat edin.”'),
(20, 91, 16, 318, 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', 'qālū lan nabraḥa ʿalayhi ʿākifīn ḥattā yarjiʿa ilaynā Mūsā', 'Dediler ki: "Musa bize dönünceye kadar biz kesinlikle ona (buzağıya) tapmaktan asla vazgeçmeyeceğiz."'),
(20, 92, 16, 318, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', 'qāla yā hārūnu mā manaʿaka iḍ raʾaytahum ḍallū', 'Harun dedi ki: "Onları saptıklarını gördüğün zaman seni ne alıkoydu?"'),
(20, 93, 16, 318, 'أَلَّا تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِى', 'ʾallā tatabiʿani ʾafaʿaṣayta ʾamrī', 'Sakın bana uymadın mı? Yoksa emrime isyan mı ettin?'),
(20, 94, 16, 318, 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', 'qāla yābnaʾumme lā taʾkhuḏ bilḥiyate wəlā biraʾsī ʾinnī xašītu ʾan taqūla farraʾta bayna banī ʾisrāʾīla wələm tərqub qawlī', 'O, "Ey annem! dedi, sakın beni tutma, sakın başımı da yolma! Ben senin, İsrailoğullarını ayırdığını ve sözümü beklemediğini söylemenden korktum."'),
(20, 95, 16, 318, 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ', 'qāla famā khaṭbuka yā Sāmiriyyu', 'Allah şöyle dedi: "Ey Samiri! Senin asıl derdin neydi?"'),
(20, 96, 16, 318, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', 'qāla baṣurtu bimā lam yabṣurū bihi faqabaḍtu qabḍatan min athari r-rasūli fanabaḏtuhā wa kaḏālika sawwalat lī nafsi', 'O, şöyle dedi: "Ben onların görmediğini gördüm. Bu, (Cebrail''in) izinden bir avuç toprak aldım da onu attım. Nefsim bana böylece hoş gösterdi."'),
(20, 97, 16, 318, 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُۥ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًا لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', 'qāla fa-dh-hab fa-inna laka fī l-ḥayāti an taqūla lā misāsa wa-inna laka mawʿidan lan tukhlafahu wa-nẓur ilā ilāhika lladhī ẓilta ʿalayhi ʿākifā lanuḥarriqannahū thumma lanansifannahū fī l-yammi nasfā', 'Musa dedi ki: "Haydi defol! Hayatın boyunca ''Bana dokunmayın!'' diyeceksin. Şüphesiz senin için bir de (azap) vaadi var ki, ondan asla kurtulamayacaksın. Bir de tapmakta olduğun ilahına bak; biz onu mutlaka yakacağız, sonra da onu denize savuracağız."'),
(20, 98, 16, 318, 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ وَسِعَ كُلَّ شَىْءٍ عِلْمًا', 'ʾinnemā ʾilāhukumullāhu lladhī lā ʾilāhe ʾillā huve vesiʿa kulla šayʾin ʿilmen', 'Sizin ilahınız, O''ndan başka ilah olmayan Allah''tır. O, ilmiyle her şeyi kuşatmıştır.'),
(20, 99, 16, 319, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًا', 'kadhalika naquṣṣu ʿalayka min anbāʾi mā qad sabaqa waqad ātaynāka min ladunnā dhikran', 'İşte böylece sana geçmişe dair haberlerden anlatıyoruz. Ve şüphesiz sana tarafımızdan bir zikir (Kur''an) verdik.'),
(20, 100, 16, 319, 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا', 'man aʿraḍa ʿanhu faʾinnahu yaḥmilu yawma l-qiyāmati wizran', 'Kim bundan yüz çevirirse, şüphesiz kıyamet günü ağır bir yük yüklenir.'),
(20, 101, 16, 319, 'خَٰلِدِينَ فِيهِ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًا', 'khālidīna fīhi wa sāʾa lahum yawma l-qiyāmati ḥimlan', 'Onlar orada ebedi kalırlar. Ve kıyamet günü onların yükü ne kötü olur!'),
(20, 102, 16, 319, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا', 'yawma yunfahu fī ṣ-ṣūri wa-naḥshuru l-mujrimīna yawmaʾiḏin zurqan', 'Sur''a üflendiği gün, suçluları o gün gözleri morarmış olarak haşrederiz.'),
(20, 103, 16, 319, 'يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا', 'yatakhāfatūna baynahum in labiṯtum illā ʿašran', 'Onlar kendi aralarında fısıldaşırlar: ''Siz sadece on gün kaldınız.'''),
(20, 104, 16, 319, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا', 'naḥnu ʾaʿlamu bimā yaqūlūna ʾidh yaqūlu ʾamthaluhum ṭarīqatan ʾin labiṯtum ʾillā yawman', 'Onların ne dediklerini biz daha iyi biliriz. Onların en doğru yolu tutanları: ''Siz ancak bir gün kaldınız'' dediği zaman.'),
(20, 105, 16, 319, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًا', 'wa yas''alūnaka ʿani l-jibāli fa-qul yansifu-hā rabbī nasfan', 'Bir de sana dağlardan soruyorlar. De ki: "Rabbim onları darmadağın edip savuracak."'),
(20, 106, 16, 319, 'فَيَذَرُهَا قَاعًا صَفْصَفًا', 'feyadheruhaa qaaʿan ṣafṣafā', 'Artık onu dümdüz, pürüzsüz bir halde bırakır.'),
(20, 107, 16, 319, 'لَّا تَرَىٰ فِيهَا عِوَجًا وَلَآ أَمْتًا', 'lā tarā fīhā ʿiwajan wa lā amtan', 'Orada eğrilik ve dolambaçlılık görmezsin.'),
(20, 108, 16, 319, 'يَوْمَئِذٍ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا', 'yawmaʾiḏin yattabiʿūna d-dāʿiya lā ʿiwaja lahū wa ḫašʿati l-ʾaṣwātu li-r-raḥmāni falā tasmaʿu ʾillā hamsan', 'O gün, (insanlar) davetçiye uyarlar; ondan asla bir eğrilik göremezler. Rahmân''a karşı sesler kısılır. Artık sen, sadece bir fısıltı işitirsin.'),
(20, 109, 16, 319, 'يَوْمَئِذٍ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًا', 'yawmaʾiḏin lā tanfaʿu ʾaššafāʿatu ʾillā man ʾaḏina lahu ʾar-raḥmānu wa raḍiya lahu qawlan', 'O gün, Rahman''ın izin verdiği ve sözünden razı olduğu kimse dışında hiç kimsenin şefaati fayda vermez.'),
(20, 110, 16, 319, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًا', 'yaʿlamu mā bayna ʾaydīhim wa mā ḫalfahum walā yuḥīṭūna bihi ʿilman', 'Onların önlerinde ve arkalarında olan her şeyi bilir. Oysa onlar, ilmiyle onu kuşatamazlar.'),
(20, 111, 16, 319, 'وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا', 'waʿanati l-wujūhu li-l-ḥayyi l-qayyūmi waqad khāba man ḥamala ẓulman', 'Ve yüzler, diri ve kayyum olan Allah''a boyun eğmiştir. Ve zulüm yüklenen kimse ise, umudunu kaybetmiştir.'),
(20, 112, 16, 319, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا', 'wa-man yaʿmal mina ṣ-ṣāliḥāti wa-huwa muʾminun fa-lā yakhāfu ẓulman wa-lā haḍman', 'Kim de mümin olarak salih amellerden her ne yaparsa, artık o, ne bir zulümden ne de bir haksızlığa uğramaktan korkacaktır.'),
(20, 113, 16, 319, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا', 'wa kaḏālika anzalnāhu qurʾānan ʿarabiyyan wa ṣarrafnā fīhi mina l-waʿīd laʿallahum yattaqūn ʾaw yuḥdiṯu lahum ḏikran', 'Ve işte böylece onu Arapça bir Kur''an olarak indirdik ve içinde uyarıları çeşitli şekillerde açıkladık ki, umulur ki onlar (Allah''tan) korkarlar veya bu onlara bir hatırlayıcı olur.'),
(20, 114, 16, 320, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ وَقُل رَّبِّ زِدْنِى عِلْمًا', 'fa-taʿālā-llāhu-l-maliku-l-ḥaqqu wa-lā taʿjal bi-l-qurʾāni min qabli an yuqḍā ilayka waḥyuhū wa-qul rabbi zidnī ʿilman', 'Gerçek Melik ve Hak olan Allah, yücelerin yücesidir. Sana vahyi tamamlanmadan Kur''an''ı okumada acele etme. Ve şöyle de: Rabbim! ilmimi artır.'),
(20, 115, 16, 320, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا', 'Ve lekad ʿahidnā ilā Ādeme min kablu fenesiye ve lem necid lehū ʿazmen', 'Andolsun, daha önce Âdem''e ahit vermiştik de unuttu. Onda bir azim bulamadık.'),
(20, 116, 16, 320, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', 'wa-ʾiḏ ḳulnā lil-malāʾikati ʾsǧudū li-ʾādam fasǧadū ʾillā ʾiblīsa ʾabā', 'Hani meleklere, "Adem''e secde edin" demiştik. İblis hariç, hepsi secde etmişti. İblis diretti.'),
(20, 117, 16, 320, 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', 'fa-qulnā yā ʾādamu ʾinna hādhā ʿaduwwun laka wa-li-zawjika fa-lā yukhrijannakumā mina l-jannati fa-tashqā', 'Bunun üzerine biz de şöyle dedik: "Ey Âdem! Şüphesiz bu (iblis), hem sana hem de eşine düşmandır. Sakın sizi cennetten çıkarmasın, sonra bedbaht olursun."'),
(20, 118, 16, 320, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', 'ʾinna laka ʾallā tajūʿa fīhā walā taʿrā', 'Şüphesiz ki senin için orada ne açlık ne de çıplaklık vardır.'),
(20, 119, 16, 320, 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', 'wa annaka lā taẓmaʾu fīhā wa lā taḍḥā', 'Ve sen orada ne susuz kalırsın ne de çıplak kalırsın.'),
(20, 120, 16, 320, 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ', 'fa-waswasa ilayhi sh-shayṭānu qāla yā ʾĀdama hal ʾadulluka ʿalā shajarati l-khuldi wa-mulkin lā yablā', 'Bunun üzerine şeytan ona vesvese verdi. "Ey Adem!" dedi, "Sana ebedilik ağacını ve çökmesi olmayan bir saltanatı göstereyim mi?"'),
(20, 121, 16, 320, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', 'faʾakalā minhā fabadat lahumā sawʾātuhumā waṭafiqā yakhṣifāni ʿalayhimā min waraqi l-jannati wa ʿaṣā ʾĀdamu rabbahū faġawā', 'Böylece ondan yediler. Hemen ayıp yerleri kendilerine açılıverdi ve üzerlerine cennet (ağaçlarının) yapraklarından örtmeye başladılar. Adem de Rabbine isyan etti ve azdı.'),
(20, 122, 16, 320, 'ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', 'thumma ijtābāhu rabbuhū fatāba ʿalayhi wahadā', 'Sonra Rabbi onu seçti, tevbesini kabul etti ve ona yol gösterdi.'),
(20, 123, 16, 320, 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', 'qāla ihbiṭā min''hā jamīʿan baʿḍukum libaʿḍin ʿaduwwun fa''immā ya''tiyannakum minnī hudan famani ''ttabaʿa hudāya falā yaḍillu walā yashqā', 'Allah buyurdu: "Hepiniz oradan (cennetten) inin! Birbirinize düşman olacaksınız. Benden size bir hidayet geldiğinde, kim benim hidayetime uyarsa, artık o ne sapar ne de bedbaht olur."'),
(20, 124, 16, 320, 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةً ضَنكًا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ', 'wa-man aʿraḍa ʿan dhikrī fa-inna lahuū maʿīshatan ḍankā wa-naḥshuruhu yawma l-qiyāmati aʿmā', 'Kim de Benim zikrimden yüz çevirirse, şüphesiz onun için sıkıntılı bir hayat vardır. Ve Biz, kıyamet günü onu kör olarak haşrederiz.'),
(20, 125, 16, 320, 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا', 'qāla rabbi lima ḥashartani ʾaʿmā waqad kuntu baṣīrā', 'Rabbim! Beni neden kör olarak haşrettin? Oysa ben, (dünyada) bir basireti olan biriydim.'),
(20, 126, 16, 321, 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', 'qāla kaḏālika ʾatatka ʾāyātunā fanasīta-hā wa kaḏālika l-yawma tunsā', 'Allah şöyle buyurur: "Aynen öyle! Sana âyetlerimiz gelmişti de sen onlara uymayı unutmuştun. İşte bu şekilde, bugün sen de (cehenneme atılarak) unutulacaksın."'),
(20, 127, 16, 321, 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', 'wa kadhalika najzee man asrafa walam yu''min bi''ayati rabbihee wal''adhabu al''akhirati ashadd wabaqaa', 'İşte, israf eden ve Rabbinin ayetlerine inanmayan kimseyi biz böyle cezalandırırız. Elbette ahiret azabı daha şiddetli ve daha kalıcıdır.'),
(20, 128, 16, 321, 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', 'ʾafalam yahdi lahum kam ʾahlaknā qablahum min al-qurūni yamshūna fī masākinihim ʾinna fī dhālika la-ʾāyātin li-ʾūlī an-nuhā', 'Onlara, kendilerinden önce nice nesilleri yok ettiğimizi görmeleri kendilerine yol göstermedi mi? (Şimdi) onların yerlerinde yürüyorlar. Bunda, akıl sahipleri için elbette ibretler vardır.'),
(20, 129, 16, 321, 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى', 'wa lawlā kalimatun sabaqat min rabbika lakāna lizāman wa ajalum musammā', 'Ve eğer Rabbinden (verilmiş) bir kelime (söz) daha önce geçmiş olmasaydı, (azap) mutlaka gerekli olurdu ve belirli bir süre (de tayin edilmişti).'),
(20, 130, 16, 321, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', 'faṣbir ʿalā mā yaqūlūn wa-sabhiḥ bi-ḥamdi rabbika qabla ṭulūʿi sh-shamsi wa-qabla ghurūbihā wa-min ʾānāʾi l-layli fa-sabhiḥ wa-ʾaṭrāfa n-nahār laʿallaka tarḍā', 'Onların söylediklerine sabret. Güneşin doğuşundan önce ve batışından önce Rabbini hamd ile tesbih et. Gecenin bazı saatlerinde ve gündüzün en uç vakitlerinde de tesbih et ki hoşnut olasın.'),
(20, 131, 16, 321, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ', 'wa-lā tamuddenna ʿaynayka ʾilā mā mattaʿnā bihi ʾazwājan minhum zahrata l-ḥayāti d-dunyā linafitanahum fīhi wa-rizqu rabbika khayrun wa-ʾabqā', 'Ve onlardan çiftler halinde yararlandırdığımız şeylere, dünya hayatının zinetine, onları imtihan etmek için; gözlerini uzatma. Rabbinin rızkı daha hayırlı ve daha süreklidir.'),
(20, 132, 16, 321, 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا لَا نَسْـَٔلُكَ رِزْقًا نَّحْنُ نَرْزُقُكَ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ', 'waʾmur ʾahlaḵa biṣṣalāti waṣṭabir ʿalayhā lā nasʾaluka rizqan naḥnu narzuquka wa l-ʿāqibatu li t-taqwā', 'Aileni namaza emret ve sen de ona sabırla devam et. Senden rızık istemiyoruz; biz seni rızıklandırırız. Güzel akıbet takva sahiplerinindir.'),
(20, 133, 16, 321, 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍ مِّن رَّبِّهِۦٓ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'wa qālū lawlā yaʾtīnā bi-ʾāyatin min rabbihim ʾa wa lam taʾtihim bayyinatu mā fī ṣ-ṣuḥufi l-ʾūlā', 'Ve dediler ki: ''Rabbinden bize bir mucize getirmeli değil miydi?'' İlk (kitaplardaki) delil onlara gelmedi mi?'),
(20, 134, 16, 321, 'وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', 'wa-law annā ahlaknāhum bi-ʿadhābin min qablihī laqālū rabbanā lawlā arsalta ilaynā rasūlan fa-nattabiʿa āyātika min qabli an nadhilla wa-nakhzā', 'Onları daha önce bir azapla helak etseydik, mutlaka şöyle derlerdi: "Rabbimiz! Bizi bir peygamber göndereydin de, alçalıp rezil olmadan önce senin ayetlerine uysaydık!'),
(20, 135, 16, 321, 'قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا۟ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', 'qul kullun muterabbiṣun feterabbiṣū fasataʿlamūna man aṣḥābu ṣ-ṣirāṭi s-sawiyyi wa mani ihtedā', 'De ki: "Hepimiz beklemekteyiz. Artık siz de bekleyin. Düz yolun ve doğru gidenin kimler olduğunu yakında bileceksiniz."'),
(21, 1, 17, 322, 'ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ', 'iqtaraba li-n-nāsi ḥisābuhum wa-hum fī ġaflatim muʿriḍūn', 'İnsanların hesaba çekileceği (zaman) yaklaştı, halbuki onlar gaflet içinde yüz çevirmişlerdir.'),
(21, 2, 17, 322, 'مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 'mā yaʾtīhim min dhikrin min rabbihim muḥdaṯin illā stamaʿūhu wa hum yalʿabūn', 'Onlara Rablerinden yeni bir uyarı gelmez ki, mutlaka onu, eğlenirler bir halde dinlemiş olmasınlar.'),
(21, 3, 17, 322, 'لَاهِيَةً قُلُوبُهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', 'lāhiyatan qulūbuhum wa asarrū an-najwā alladhīna ẓalamū hal hādhā illā basharun mithlukum afa taʾtūna as-siḥra wa antum tubṣirūn', 'Kalpleri gaflet içinde olan zalimler gizlice şöyle fısıldaştılar: "Bu da sizin gibi bir insandan başkası değil. Gördüğünüz halde büyüye mi kapılıyorsunuz?"'),
(21, 4, 17, 322, 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'qāla rabbī yaʿlamu l-qawla fī s-samāʾi wa-l-arḍi wa-huwa s-samīʿu l-ʿalīmu', 'Rabbim, gökte ve yerde olan her sözü bilmektedir. O, işitendir, bilendir.'),
(21, 5, 17, 322, 'بَلْ قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌ فَلْيَأْتِنَا بِـَٔايَةٍ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', 'bal qālū ʾaḍġāṯu ʾaḥlāmin bali ʾiftarāhu bal huwa šāʿirun falyʾatinā bi-ʾāyatin kamā ʾursila l-ʾawwalūna', 'Hayır, onlar: "Bunlar karmakarışık düşlerdir; hayır, onu kendisi uydurdu; hayır, o bir şairdir; öncekilere gönderildiği gibi bize de bir mucize getirmeli değil miydi?" dediler.'),
(21, 6, 17, 322, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَٰهَآ أَفَهُمْ يُؤْمِنُونَ', 'Mā āmanat qablahum min qaryatin ahlaknāhā Afahum yuʾminūn', 'Onlardan önce helak ettiğimiz hiçbir memleket halkı iman etmemişti. Şimdi bunlar mı iman edecek?'),
(21, 7, 17, 322, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 've mā erselnā kableke illā ricālen nūḥī ileyhim fesʾelū ehle-ẕẕikri in kuntum lā taʿlemūn', 'Senden önce de kendilerine vahyettiğimiz ricalden (erkeklerden) başkasını göndermedik. Eğer bilmiyorsanız zikir ehline (ilim sahiplerine) sorun.'),
(21, 8, 17, 322, 'وَمَا جَعَلْنَٰهُمْ جَسَدًا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ', 've ma ceʿalnāhum ceseden lā yeʾkulūne ṭ-ṭaʿāme ve ma kānū khālidīne', 'Onları, yemek yemeyen bir ceset yapmadık ve onlar ölümsüz de değillerdi.'),
(21, 9, 17, 322, 'ثُمَّ صَدَقْنَٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', 'thumma ṣadaqnahumu l-waʿda faʾanjaynāhum wa-man neshāʾu wa-ʾahlaknā l-musrifīna', 'Nihayet onlara olan vaadimizi yerine getirdik. Böylece hem onları hem de dilediğimizi kurtardık ve aşırı gidenleri helak ettik.'),
(21, 10, 17, 322, 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًا فِيهِ ذِكْرُكُمْ أَفَلَا تَعْقِلُونَ', 'laqad anzalnā ilaykum kitāban fīhi dhikrukum afalā taʿqilūn', 'And لقد (Andolsun ki) biz size, içinde sizin zikriniz (değeriniz, şerefiniz) bulunan bir kitap indirdik. Hâlâ akıl erdiremiyor musunuz?'),
(21, 11, 17, 323, 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَالِمَةً وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', 'wa-kam qaṣamnā min qaryatin kānat ẓālimatan wa-anšaʾnā baʿdahā qawman ʾāḵarīn', 'Zalim bir beldeyi (halkını) nice helak ettik ve onlardan sonra başka bir kavim (nesil) vücuda getirdik.'),
(21, 12, 17, 323, 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', 'felemmā ʾaḥassū baʾsanā ʾiḏā hum minhā yarkuḍūn', 'Nihayet azabımızı hissettiklerinde, bir de ne görsünler! Hemen oradan (kaçışmaya) koşuyorlardı.'),
(21, 13, 17, 323, 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', 'lā tarkuḍū warjiʿū ilā mā utriftum fīhi wa masākinikum laʿallakum tusʾalūn', 'Kaçmayın! İçinde şımartıldığınız şeylere ve yurtlarınıza dönün ki sorgulanabilesiniz!'),
(21, 14, 17, 323, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'qālū yā waylanā innā kunnā ẓālimīn', 'Dediler ki: "Vay halimize! Gerçekten biz zalimmişiz."'),
(21, 15, 17, 323, 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ', 'fe-mā zālat tilke daʿwāhum ḥattā jaʿalnāhum ḥaṣīdan khāmidīn', 'Onların bu yakarışları, kendilerini biçilmiş ekin ve sönmüş bir duruma getirinceye kadar devam etti.'),
(21, 16, 17, 323, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 'Ve mā halaqnā as-samāʾa ve-l-arḍa ve mā beynahumā lāʿibīn', 'Biz göğü ve yeri ve ikisinin arasında bulunanları bir eğlence (oyun) olsun diye yaratmadık.'),
(21, 17, 17, 323, 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًا لَّٱتَّخَذْنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', 'law aradnā an nattakhidha lahwā lattakhadhnāhu min ladunnā in kunnā fāʿilīn', 'Eğer biz bir eğlence edinmek isteseydik, onu kendi katımızdan edinirdik. (Ama) biz böyle yapanlardan değiliz.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(21, 18, 17, 323, 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', 'bal naqdhifu bil-ḥaqqi ʿalal-bāṭili fa-yadmaghuhu fa-iḏā huwa zāhiqun wa-lakumul-waylu mimmā taṣifūn', 'Hayır, biz hakkı batılın üzerine fırlatırız da onu mahveder. Bir de bakarsınız ki batıl yok olup gitmiştir. (Onun hakkınızda) söylediğiniz (bu) şeyler yüzünden size yazıklar olsun!'),
(21, 19, 17, 323, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', 'wa-lahū man fī s-samāwāti wa-l-ʾarḍi wa-man ʿindahu lā yastakbirūna ʿan ʿibādatihi wa-lā yastaḥsirūna', 'Göklerde ve yerde kim varsa O''nundur. O''nun katında bulunanlar da O''na kulluk etmekten çekinmezler ve yorulmazlar.'),
(21, 20, 17, 323, 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', 'yusabbiḥūna al-layla wa-n-nahāra lā yafturūn', 'Onlar, gece ve gündüz demeden, hiç bıkıp usanmadan O''nu tesbih ederler.'),
(21, 21, 17, 323, 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةً مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', 'ʾami-ttakhaḏū ʾālihatan mina-l-ʾarḍi hum yūnširūn', 'Yoksa yerden, (ölüleri) diriltecek tanrılar mı edindiler?'),
(21, 22, 17, 323, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'law kāna fīhimā ʾālihatun ʾillā ʾllāhu lafasadatā fasubḥāna ʾllāhi rabbi l-ʿarshi ʿammā yaṣifūna', 'Eğer yerde ve gökte Allah''tan başka ilahlar olsaydı, kesinlikle ikisi de (yer ve gök) fesada uğrardı. Arş''ın Rabbi olan Allah, onların vasfettiklerinden münezzehtir.'),
(21, 23, 17, 323, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', 'lā yus''alu ʿammā yafʿalu wa hum yus''alūn', 'O, yaptığından sorulmaz, ama onlar sorulurlar.'),
(21, 24, 17, 323, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ فَهُم مُّعْرِضُونَ', 'ʾami-t-takhadhū min dūnihi ʾālihata qul hātū bur''hānakum hādhā dhikru man maʿīya wa dhikru man qablī bal ʾaktharuhum lā yaʿlamūna l-ḥaqqa fa-hum muʿriḍūna', 'Yoksa O''ndan başka ilahlar mı edindiler? De ki: ''Kesin delilinizi getirin. Bu, benimle birlikte olanların zikri (Kur''an) ve benden önceki (peygamberlerin) zikridir.'' Hayır, onların çoğu hakkı bilmiyorlar, bu yüzden yüz çeviriyorlar.'),
(21, 25, 17, 324, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', 'wa mā arsalnā min qablika min rasūlin illā nūḥī ilayhi annahu lā ilāha illā anā faʿbudūn', 'Senden önce de hiçbir resul göndermedik ki ona: "Benden başka tanrı yoktur, yalnızca Bana kulluk edin!" diye vahyetmiş olmayalım.'),
(21, 26, 17, 324, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا سُبْحَٰنَهُۥ بَلْ عِبَادٌ مُّكْرَمُونَ', 'wa qālū t-takhadha r-raḥmānu waladan subḥānahū bal ʿibādun mukramūn', 'Rahmân, ''çocuk edindi'' dediler. O, yüceler yücesidir. Hayır, (o dedikleriniz) ancak Allah''ın ağırlanmış kullarıdır.'),
(21, 27, 17, 324, 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', 'lā yasbiqūnahū bil-qawli wa hum bi-amrihī yaʿmalūn', 'Onlar, söz (açısından) O''nun önüne geçemezler ve O''nun emriyle hareket ederler.'),
(21, 28, 17, 324, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', 'yaʿlamu mā bayna ʾaydīhim wa mā ḵalfahum wa lā yášfaʿūna ʾillā limani ʾirtaḍā wa hum min ḵašyatihī mušfiqūna', 'Onların önlerinde ve arkalarında olanları bilir. Ve onlar, O''nun korkusundan saygı duyarlar.'),
(21, 29, 17, 324, 'وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'wa-man yaqul minhum innī ilāhun min dūnihi fa-dhālika najzīhi jahannama kadhālika najzī aẓ-ẓālimīn', 'Onlardan her kim, ''Ben O''ndan başka bir ilahım'' derse, işte onu cehennemle cezalandırırız. Biz zalimleri işte böyle cezalandırırız.'),
(21, 30, 17, 324, 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَٰهُمَا وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ أَفَلَا يُؤْمِنُونَ', 'ʾAwalem yere-lladhīne keferū ʾenna-s-semāwāti we-l-ʾarḍa kānetā ratqan fefetaqnāhumā we-jeʿalnā mine-l-māʾi kulle šayʾin ḥayyin ʾAfelā yuʾminūn', 'İnkâr edenler, gökler ve yer bitişik iken bizim onları ayırdığımızı ve her canlı şeyi sudan yarattığımızı görmediler mi? Hâlâ inanmıyorlar mı?'),
(21, 31, 17, 324, 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ', 'wa jaʿalnā fī l-arḍi rawāsī an tamīda bihim wa jaʿalnā fīhā fijājan subulan laʿallahum yahtadūn', 'Yeryüzünde, onları sarsmasın diye sarsılmaz dağlar yarattık ve onlara, yolu bulabilsinler diye geniş yollar ve açıklıklar yaptık.'),
(21, 32, 17, 324, 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًا مَّحْفُوظًا وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ', 'wa jaʿalnā s-samāʾa saqfan maḥfūẓan wa hum ʿan āyātihā muʿriḍūn', 'Göğü korunmuş bir tavan kıldık. Onlar ise, göğün (varlığına ve kudretimize) delalet eden âyetlerinden yüz çeviriyorlar.'),
(21, 33, 17, 324, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ فِى فَلَكٍ يَسْبَحُونَ', 'wa huwa lladhī khalaqa l-layla wa-n-nahāra wa-sh-shamsa wa-l-qamara kullun fī falakin yasbaḥūna', 'Geceyi, gündüzü, güneşi ve ayı yaratan O''dur. (Kullarının) hepsi kendi yörüngelerinde yüzmektedirler.'),
(21, 34, 17, 324, 'وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ ٱلْخُلْدَ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ', 've-mā ceʿalnā li-beşerin min ḳablike l-ḫulde fe-ʾin mittte fe-humu l-ḫālidūn', 'Senden önce de hiçbir beşere kalıcılık vermedik. Şimdi sen ölürsen, onlar sonsuza dek kalacaklar mı?'),
(21, 35, 17, 324, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ', 'kullu nafsin dhāʾiqatu l-mawti wa nablūkum bi-sh-sharri wa-l-khayri fitnatan wa ilayna turjaʿūna', 'Her nefis ölümü tadacaktır. Sizi imtihan için şer ve hayır ile deneriz. Ve siz bize döndürüleceksiniz.'),
(21, 36, 17, 325, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ', 'wa ʾiḏā raʾāka ʾallaḏīna kafarū ʾin yattaḵiḏūnaḵa ʾillā huzuwan ʾahāḏā ʾallaḏī yaḏkuru ʾālihataḵum wa hum biḏikri ʾar-raḥmāni hum kāfirūn', 'Onları inkâr edenler seni ancak alaya alırlar: "Sizin ilâhlarınızı mı anıyor?" derler. Oysa kendileri, çok esirgeyen (Allah)''ın zikrinden (Kur''an''dan) kâfirdirler.'),
(21, 37, 17, 325, 'خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ', 'Khuliqa al-insānu min ʿajalin Saʾūrikum ʾāyātī Falā tastaʿjilūni', 'İnsan aceleden (sıkıntıdan) yaratılmıştır. Size ayetlerimi yakında göstereceğim. Acele etmeyin bana!'),
(21, 38, 17, 325, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hāḏā al-waʿdu in kuntum ṣādiqīna', 'Ve derler ki: "Eğer doğru sözlüler iseniz, bu vaat ne zaman?"'),
(21, 39, 17, 325, 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', 'law yaʿlamu alladhīna kafarū ḥīna lā yakuffūna ʿan wujūhihimu n-nāra walā ʿan ẓuhūrihim walā hum yunṣarūn', 'İnkâr edenler, ne yüzlerinden ne de sırtlarından ateşi savamayacakları ve hiçbir yardım göremeyecekleri zamanı bir bilselerdi!'),
(21, 40, 17, 325, 'بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', 'bal taʾtīhim baghtatan fatabhathum falā yastaṭīʿūna raddahā walā hum yunẓarūn', 'Hayır, onlara ansızın geliverir de onları şaşkına çevirir. Ne ondan kurtulmaya güçleri yeter, ne de onlara mühlet verilir.'),
(21, 41, 17, 325, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'Ve lekadistuhziʾe birusulin min kablike fehâka billazîne sehırû minhum mâ kânû bihî yestehziʾûn', 'Andolsun ki, senden önceki nice peygamberlerle alay edildi de alay etmekte oldukları şey, o alay edenleri kuşatıverdi.'),
(21, 42, 17, 325, 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', 'qul man yaklaʾukum bi-l-layli wa-n-nahāri mina ʾr-raḥmāni bal hum ʿan dhikri rabbihim muʿriḍūna', 'De ki: "Geceleyin ve gündüz sizi Rahman olan Allah''tan kim korur? Hayır, onlar Rablerinin zikrinden yüz çeviriyorlar."'),
(21, 43, 17, 325, 'أَمْ لَهُمْ ءَالِهَةٌ تَمْنَعُهُم مِّن دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', 'am lahum ʾālihatun tamnaʿuhum min dūninā lā yastaṭīʿūna naṣra ʾanfusihim walā hum minnā yuṣḥabūn', 'Yoksa onlara, bizden başka kendilerini koruyabilecek ilahları mı var? Oysa onlar (bu ilahlar) kendilerine bile yardım edemezler ve bizden de bir destek görmezler.'),
(21, 44, 17, 325, 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ أَفَهُمُ ٱلْغَٰلِبُونَ', 'bal mattaʿnā hāʾulāʾi wa-ābāʾahum ḥattā ṭāla ʿalayhimu l-ʿumuru ʾaflā yarawna ʾannā naʾtī l-ʾarḍa nanquṣuhā min ʾaṭrāfihā ʾafahumu l-ḡālibūna', 'Hayır, biz onları ve atalarını, ömürleri uzadıkça dünya nimetlerinden faydalandırdık. Onların, toprağı (onların mülkü olan yerleri) etrafından eksilttiğimizi görmüyorlar mı? Üstün gelenler onlar mı?'),
(21, 45, 17, 326, 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 'qul innemā unẕirukum bil-waḥy welā yesmeʿu ṣ-ṣummu d-duʿāʾ iẕā mā yunẕarūn', 'De ki: Ben sizi ancak vahiyle uyarırım. Fakat uyarıldıkları zaman sağırlar çağrıyı işitmezler.'),
(21, 46, 17, 326, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'Ve leʾin messet-hum nefḥatun min ʿaḏābi rabbike le-yeqūlunne yā veylenā innā kunnā ẓālimīn', 'Andolsun ki, Rabbinin azabından onlara küçücük bir esinti dokunsa, mutlaka diyecekler ki: "Vay halimize! Şüphesiz biz zalimler idik."'),
(21, 47, 17, 326, 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَٰسِبِينَ', 'wa naḍaʿu l-mawāzīna l-qisṭa li-yawmi l-qiyāmati fa-lā tuẓlamu nafsuñ shayʾan wa in kāna mithqāla ḥabbatin min khardalin ataynā bihā wa kafā bi-nā ḥāsibīna', 'Biz kıyamet günü için adalet terazilerini kurarız. Hiç kimse zerre kadar haksızlığa uğratılmaz. İsterse bir hardal tanesi ağırlığında olsun, (onu getiririz). Ve hesap gören olarak biz yeteriz.'),
(21, 48, 17, 326, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءً وَذِكْرًا لِّلْمُتَّقِينَ', 'Ve lekad āteynā Mūsā ve Hārūne el-Furkāne ve ḍiyāen ve ẕikran lilmutteqīne', 'Andolsun ki Musa''ya ve Harun''a Furkan''ı (hak ile batılı ayıranı), bir ışık ve takva sahipleri için bir öğüt olarak verdik.'),
(21, 49, 17, 326, 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', 'alladhīna yakhshawna rabbahum bil-ghaybi wa hum minas-sāʿati mushfiqūna', 'Onlar, Rablerinden (hem) gāyib (kendilerini görmedikleri halde) korkarlar ve onlar kıyametten de titreyenlerdir.'),
(21, 50, 17, 326, 'وَهَٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَٰهُ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', 'wa hādhā dhikrun mubārakun anzalnāhu afa antum lahū munkirūn', 'İşte bu da bizim indirdiğimiz mübarek bir zikirdir. Şimdi siz onu inkâr mı ediyorsunuz?'),
(21, 51, 17, 326, 'وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', 've lekad ʾātaynā ʾibrāhīme ruşdehu min kablu ve kunnā bihī ʿālimīn', 'Andolsun ki daha önce İbrahim''e rüşdünü (doğru yolu bulma yeteneğini) vermiştik ve biz onu çok iyi biliyorduk.'),
(21, 52, 17, 326, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ', 'iż qāla li-ʾabīhi wa-qawmihi mā hāḏihi ʾat-tamaṯīlu ʾallatī ʾantum lahā ʿākifūn', 'Hani babasına ve kavmine şöyle demişti: ''Bu tasvirler (heykeller) nedir ki siz onlara kapanıyorsunuz?'''),
(21, 53, 17, 326, 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', 'qālū wajadnā ʾābāʾanā lahā ʿābidīn', 'Dediler ki: "Babalarımızı da onlara tapar bulduk."'),
(21, 54, 17, 326, 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍ مُّبِينٍ', 'qāla laqad kuntum antum wa-ābāʾukum fī ḍalālin mubīn', 'Onlar şöyle dediler: "Andolsun ki, siz de atalarınız da apaçık bir sapıklık içindeydiniz."'),
(21, 55, 17, 326, 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ', 'qālū ʾaǧiʾtanā bil-ḥaqqi ʾam ʾanta min al-lāʿibīn', 'Dediler ki: "Yoksa bize hakkı mı getirdin, yoksa sen oyuncu kimselerden misin?"'),
(21, 56, 17, 326, 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', 'Qāla bal rabbukum rabbus-samāwāti wal-arḍilladhī faṭarahunna Wa anā ʿalā dhālikum minash-shāhidīn', 'Dedi ki: "Hayır! Rabbim, göklerin ve yerin Rabbidir; O, onları yaratandır ve ben de buna şahitlerdenim."'),
(21, 57, 17, 326, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', 'wa-ta-llāhi la-ʾakīda-nna ʾaṣnāma-kum baʿda ʾan tuwallū mudbirīn', 'Allah''a yemin ederim ki, siz arkanızı dönüp gittikten sonra, putlarınıza bir tuzak kuracağım.'),
(21, 58, 17, 327, 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', 'fa jaʿalahum juḏāḏan illā kabīran lahum laʿallahum ilayhi yarjiʿūn', 'Böylece onları, kendilerine başvururlar diye, (sağ kalan) en büyüğü hariç, un ufak etti.'),
(21, 59, 17, 327, 'قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', 'qālū man faʿala hāḏā bi-ʾālihatinā ʾinnahuu lamina ẓ-ẓālimīn', 'Dediler ki: "Putlarımıza bunu kim yaptıysa, gerçekten o zalimlerden biridir!"'),
(21, 60, 17, 327, 'قَالُوا۟ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', 'qālū samiʿnā fatā yadhkuruhum yuqālu lahu ʾIbrāhīmu', 'Dediler ki: Onları diline dolayan, kendisine İbrahim denilen bir gencin sözlerini işittik.'),
(21, 61, 17, 327, 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', 'qālū faʾtū bihī ʿalā ʾaʿyuni n-nāsi laʿallahum yashhadūn', 'Dediler ki: ''Ey İbrahim! Eğer (bu dediklerini) yapacaklardan isen, haydi onu (yaptıracağın azabı) insanların gözü önünde getirsene!'''),
(21, 62, 17, 327, 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ', 'qālū ʾaʾanta faʿalta hādhā bi-ʾālihatinā yā ʾibrāhīm', 'Dediler ki: "Ey İbrahim! Bunu ilahlarımıza sen mi yaptın?"'),
(21, 63, 17, 327, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', 'qāla bal faʿalahū kabīruhum hādhā fasʾalūhum in kānū yanṭiqūn', 'Şöyle dedi: "Hayır! Onların büyüğü, şunu yapmıştı; eğer konuşabiliyorlarsa, onlara sorun!"'),
(21, 64, 17, 327, 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ', 'farajaʿū ilā anfusihim faqālū innakum antumu ẓ-ẓālimūn', 'Böylece vicdanlarına dönüp dediler ki: "Gerçekten siz haksızlık edenlersiniz."'),
(21, 65, 17, 327, 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', 'thumma nukisū ʿalā ruʾūsihim laqad ʿalimta mā hāʾulāʾi yanṭiqūn', 'Sonra (hakikati) anlayıp akılları başlarına geldiler: "Andolsun ki sen, ey İbrahim, bunların konuşmadığını biliyorsun!" dediler.'),
(21, 66, 17, 327, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًٔا وَلَا يَضُرُّكُمْ', 'qāla afataʿbudūna min dūni llāhi mā lā yanfaʿukum shayʾan walā yaḍurrukum', 'O, şöyle dedi: "O halde Allah''ı bırakıp da size hiçbir fayda sağlamayan ve zarar da vermeyen şeylere mi tapıyorsunuz?"'),
(21, 67, 17, 327, 'أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَفَلَا تَعْقِلُونَ', 'ʾufun lakum wa limā taʿbudūna min dūni llāhi ʾaflā taʿqilūna', 'Size ve Allah''tan başka taptıklarınıza yazıklar olsun! Hâlâ akıllanmayacak mısınız?'),
(21, 68, 17, 327, 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ', 'qālū ḥarriqūhu wa-nṣurū ʾālihata-kum ʾin kuntum fāʿilīn', 'Dediler ki: "Eğer (bir şey) yapacaksanız, onu yakın ve ilahlarınızı savunun!"'),
(21, 69, 17, 327, 'قُلْنَا يَٰنَارُ كُونِى بَرْدًا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', 'qulnā yā nāru kūnī bārdan wa salāman ʿalā ʾibrāhīm', 'Biz de, "Ey ateş! İbrahim''e karşı serin ve zararsız ol!" dedik.'),
(21, 70, 17, 327, 'وَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ', 'wa arādū bihi kaydan fajaʿalnāhumu l-akhsarīn', 'Ve ona bir tuzak kurmak istediler. Biz de onları en çok hüsrana uğrayanlar kıldık.'),
(21, 71, 17, 327, 'وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ', 'wa-najjaynāhu wa-lūṭan ʾilā l-ʾarḍi llatī bāraknā fīhā lil-ʿālamīn', 'Onu ve Lut''u, içine bereketler verdiğimiz topraklara kurtardık.'),
(21, 72, 17, 327, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةً وَكُلًّا جَعَلْنَا صَٰلِحِينَ', 'wa wahabnā lahu ʾisḥāqa wa yaʿqūba nāfilatan wa kullan jaʿalnā ṣāliḥīn', 'Biz ona İshak''ı ve (torunu) Yakub''u bir bağış olarak verdik ve her birini salihler kıldık.'),
(21, 73, 17, 328, 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ وَكَانُوا۟ لَنَا عَٰبِدِينَ', 'wa jaʿalnāhum ʾaimmatan yahdūna bi-ʾamrinā wa ʾawḥaynā ʾilayhim fiʿla l-khayrāt wa ʾiqāma ṣ-ṣalāh wa ʾītāʾa z-zakāh wa kānū lanā ʿābidīn', 'Onları, buyruğumuzla doğru yola ileten önderler kıldık. Hayır işleri yapmalarını, namazı dosdoğru kılmalarını ve zekâtı vermelerini kendilerine vahyettik. Onlar bize kulluk edenlerdi.'),
(21, 74, 17, 328, 'وَلُوطًا ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَٰسِقِينَ', 'wa-lūṭan ʾātayināhu ḥukman wa-ʿilman wa-najjaynāhu mina l-qaryati llatī kānat taʿmalu l-khabāʾith ʾinnahum kānū qawma sawʾin fāsiqīn', 'Lût''u da hatırlayın. Hani ona hüküm (hikmet) ve ilim vermiştik. Onu, kötü işler yapmakta olan kasabadan kurtarmıştık. Şüphesiz onlar, yoldan çıkmış kötü bir kavim idiler.'),
(21, 75, 17, 328, 'وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', 'wa adkhalnāhu fī raḥmatinā innahu mina ṣ-ṣāliḥīn', 'Onu rahmetimize dahil ettik. Çünkü o, salihlerden idi.'),
(21, 76, 17, 328, 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'wa-nūḥan iḏ nādā min qablu fastajabnā lahu fanajjaynāhu wa-ahlahu mina l-karbi l-ʿaẓīm', 'Nuh''u da (an). Hani o, daha önce (bize) şöyle niyaz etmişti: ''Ben, bu yalancılar topluluğu yüzünden bana yardım et!'' Biz de onun duasını kabul ettik, kendisini ve ailesini o büyük üzüntüden kurtardık.'),
(21, 77, 17, 328, 'وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'wa naṣarnāhu mina l-qawmi l-ladhīna kadhthabū bi-ʾāyātinā ʾinnahum kānū qawma sawʾin fa ʾaghraqnāhum ʾajmaʿīna', 'Ve onları, ayetlerimizi yalanlayan bir kavimden koruduk. Şüphesiz onlar kötü bir kavim idiler; bu yüzden onları hep birlikte boğduk.'),
(21, 78, 17, 328, 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ', 'wa-dāwūda wa-sulaymāna ʾidha yaḥkumāni fī l-ḥarthi ʾidha nafashat fīhi ghanamu l-qawmi wa-kunnā li-ḥukmihim shāhidīna', 'Davud''u ve Süleyman''ı da (hatırla). Hani onlar, bir ekin hakkında hüküm veriyorlardı; çünkü halkın koyunları o ekinin içine girip yayılmıştı. Biz de onların hükmüne şahit idik.'),
(21, 79, 17, 328, 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ وَكُنَّا فَٰعِلِينَ', 'fafahhamnāhā Sulaymāna wa kull an ātaynā ḥukman wa ʿilman wa sakkharnā maʿa Dāwūda l-jibāla yusabbiḥna wa ṭ-ṭayra wa kunnā fāʿilīna', 'Bunun üzerine onun hükmünü Süleyman''a biz anlatmıştık. Her birine de hüküm (hikmet) ve ilim verdik. Dâvûd ile birlikte tesbih eden dağları ve kuşları da buyruğumuza verdik. Bütün bunları yapan biziz.'),
(21, 80, 17, 328, 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ فَهَلْ أَنتُمْ شَٰكِرُونَ', 'wa ʿallamnāhu ṣanʿata labūsin lakum lituḥṣinakum mim baʾsikum fahal antum shākirūn', 'Ona sizin için zırh yapma sanatını öğrettik ki sizi savaşlarınızda korusun. Hâl böyle iken şükredecek misiniz?'),
(21, 81, 17, 328, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ', 'wa-li-sulaymāna r-rīḥa ʿāṣifatan tajrī bi-ʾamrihī ʾilā l-ʾarḍi l-latī bāraknā fīhā wa-kunnā bi-kulli shayin ʿālimīn', 'Ve Süleyman için de rüzgârı (emrine verdik): onun emriyle bereketlendirdiğimiz topraklara doğru esmekteydi. Ve Biz her şeyi bilenleriz.'),
(21, 82, 17, 329, 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَٰفِظِينَ', 'wa mina sh-shayāṭīni man yaghūṣūna lahu wa yaʿmalūna ʿamalan dūna dhālika wa kunnā lahum ḥāfiẓīna', 'Onların şeytanlarından, onun için dalgıçlık yapan ve bundan başka işler de görenler vardı. Ve biz onları gözetleyip koruyorduk.'),
(21, 83, 17, 329, 'وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'wa-ʾayyūba ʾiḏ nādā rabbahū ʾannī massaniya ḍ-ḍurru wa-ʾanta ʾarḥamu r-rāḥimīn', 'Eyüp''ü de hatırla. Hani o Rabbine şöyle niyaz etmişti: ''Elem (dert ve sıkıntı) bana dokundu. Sen, merhamet edenlerin en merhametlisisin.'''),
(21, 84, 17, 329, 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ', 'fastajabnā lahu fakašafnā mā bihi min ṣurr wa ātaynāhu ʾahla hu wa miṯlahum maʿahum raḥmatan min ʿindinā wa ḏikrā lil-ʿābidīn', 'Böylece onun duasın kabul ettik, katımızdan bir rahmet ve kullar için bir öğüt olmak üzere, kendisinde bulunan sıkıntıyı giderdik ve ona ailesini, onlarla birlikte bir kat daha verdik.'),
(21, 85, 17, 329, 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ كُلٌّ مِّنَ ٱلصَّٰبِرِينَ', 'wa-ʾismāʿīla wa-ʾidrīsa wa-ḏā l-kifli kullun min aṣ-ṣābirīn', 'İsmail''i, İdris''i ve Zülkifl''i de (hatırla). Onların hepsi iyilerdendi.'),
(21, 86, 17, 329, 'وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', 'wa adkhalnāhum fī raḥmatinā innahum mina ṣ-ṣāliḥīn', 'Ve onları rahmetimize dahil ettik. Şüphesiz onlar salihlerdendi.'),
(21, 87, 17, 329, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', 'waḏā ʾn-nūni iḏ ḏahaba muġāḍibā faẓanna ʾanna lan naqdira ʿalayhi fanādā fī ẓ-ẓulumāti ʾan lā ʾilāha ʾillā ʾanta subḥānaka ʾinnī kuntu mina ẓ-ẓālimīn', 'Zünnun''u da (an). Hani o, öfkelenerek (kavminden) ayrılmış ve kendisini sıkıntıya sokmayacağımızı sanmıştı. (Fakat) Karanlıklar içinde: ''Senden başka ilah yoktur. Sen yücelerdeсин. Şüphesiz ben zalimlerden oldum'' diye dua etmişti.'),
(21, 88, 17, 329, 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ وَكَذَٰلِكَ نُۨجِى ٱلْمُؤْمِنِينَ', 'fastajabnā lahu wa-najjaynāhu mina l-ğammi wa-kaḏālika nuʾjī l-muʾminīn', 'Böylece onun duasını kabul ettik ve onu üzüntüden kurtardık. İşte biz, iman edenleri böyle kurtarırız.'),
(21, 89, 17, 329, 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', 'wa zakariyyā idh nādā rabbahū rabbi lā tadhaṟnī fardā wa anta khayru l-wāriṯīn', 'Ve Zekeriya''yı da an; hani o Rabbine şöyle niyaz etmişti: "Rabbim! Beni (tek başıma) bırakma; sen vârislerin en hayırlısısın."'),
(21, 90, 17, 329, 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا وَكَانُوا۟ لَنَا خَٰشِعِينَ', 'fastajabnā lahu wa wahabnā lahu Yaḥyā wa aṣlaḥnā lahu zawjahū innahum kānū yusāriʿūna fī l-khayrāt wa yadʿūnanā raghaban wa rahaban wa kānū lanā khāshiʿīn', 'Böylece onun duasın kabul ettik, ona Yahya''yı armağan ettik ve eşini de kendisi için ıslah ettik. Çünkü onlar hayır işlerinde yarışır, bizden hem umarak hem korkarak dua ederlerdi ve bize derin bir saygı ile bağlı bulunurlardı.'),
(21, 91, 17, 330, 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةً لِّلْعَٰلَمِينَ', 'wa-allatī ʾaḥṣanat farjahā fanafakhanā fīhā min rūḥinā wa-jaʿalnāhā wa-bnahā ʾāyatan lil-ʿālamīn', 'Namusunu korumuş olanı da (an). Biz ona ruhumuzdan üfledik ve onu ve oğlunu âlemler için bir mucize kıldık.'),
(21, 92, 17, 330, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', 'ʾinna hāḏihi ʾummatukum ʾummatan wāḥidatan wa ʾanā rabbukum fa-ʿbudūn', 'Şüphesiz bu sizin ümmetinizdir; (hepsi) bir tek ümmettir. Ben de sizin Rabbinizim. Bana kulluk edin.'),
(21, 93, 17, 330, 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ كُلٌّ إِلَيْنَا رَٰجِعُونَ', 'wa taqaṭṭaʿū amrahum baynahum kullun ilayna rājiʿūn', 'Ancak onlar kendi aralarında işlerini (dinlerini) parça parça ettiler. Hepsi bize döneceklerdir.'),
(21, 94, 17, 330, 'فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', 'fe-men yaʿmalu mina ṣ-ṣāliḥāti wa-huwa muʾminun fa-lā kufrāna li-saʿyihi wa-innā lahu kātibūna', 'Kim mümin olarak salih amel işlerse, onun gayreti asla inkâr edilmez. Şüphesiz biz onu yazmaktayız.'),
(21, 95, 17, 330, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', 'wa ḥarāmun ʿalā qaryatin ʾahlaknāhā ʾannahum lā yarjiʿūn', 'Helak ettiğimiz hiçbir kasaba halkı (dünyaya) geri dönmezler.'),
(21, 96, 17, 330, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ', 'ḥattā ʾiḏā futiḥat Yaʾjūju wa-Maʾjūju wa-hum min kulli ḥadabin yansilūna', 'Nihayet Ye''cüc ve Me''cüc''ün önleri açıldığında ve onlar her bir tepeden akın ederlerken...'),
(21, 97, 17, 330, 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ', 'wa-qtaraba l-waʿdu l-ḥaqqu fa-idhā hiya shākhishatun abṣāru lladhīna kafarū yā waylatanā qad kunnā fī ghaflatin min hādhā bal kunnā ẓālimīna', 'Gerçek vaat (kıyamet) yaklaştı. İşte o zaman, kâfirlerin gözleri donakalır. "Eyvah bize! Gerçekten biz, bu (durumdan) habersiz idik. Hatta biz zalim kimseler idik." derler.'),
(21, 98, 17, 330, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', 'ʾinnakum wa mā taʿbudūna min dūni llāhi ḥaṣabu jahannama ʾantum lahā wāridūna', 'Şüphesiz siz ve Allah''tan başka taptıklarınız, cehennem odunusunuz. Siz oraya gireceksiniz.'),
(21, 99, 17, 330, 'لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا وَكُلٌّ فِيهَا خَٰلِدُونَ', 'law kāna hāʾulāʾi ʾālihatan mā waradūhā wa kullun fīhā khālidūn', 'Eğer bunlar ilah olsaydı, oraya (cehenneme) hiçbiri girmezdi. Hepsi orada ebedî kalıcıdır.'),
(21, 100, 17, 330, 'لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ', 'lahum fīhā zafīrun wa hum fīhā lā yasmaʿūna', 'Onlar orada feryat ederler ve orada (hakikati) işitmezler.'),
(21, 101, 17, 330, 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ', 'ʾinna lladhīna sabaqat lahum minnā l-ḥusnā ʾulāʾika ʿanhā mubʿadūna', 'Bizden kendileri için en güzel olanın (cennetin) geçmiş olduğu kimseler var ya, işte onlar oradan (cehennemden) uzaklaştırılmışlardır.'),
(21, 102, 17, 331, 'لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ', 'lā yasmaʿūna ḥasīsahā wa-hum fī mā ʾištahāt ʾanfusuhum khālidūn', 'Onlar, onun sesini (uğultusunu) işitmezler. Onlar, canlarının çektiği nimetler içinde ebedî kalacaklardır.'),
(21, 103, 17, 331, 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', 'lā yaḥzunuhumu l-fazaʿu l-ʾakbaru wa tatalaqqāhumu l-malāʾikatu hādhā yawmukumu l-ladhī kuntum tūʿadūna', 'O büyük dehşet onları üzmez. Melekler de onlara: "Size vaad olunan gün işte bugündür!" diyerek karşılarlar.'),
(21, 104, 17, 331, 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ وَعْدًا عَلَيْنَآ إِنَّا كُنَّا فَٰعِلِينَ', 'yawma naṭwī s-samāʾa kaṭayy is-sijilli lil-kutubi kamā badaʾnā awwala khalqin nuʿīduhu waʿdan ʿalaynā ʾinnā kunnā fāʿilīna', 'O gün, göğü, kitapların yazıldığı sahifeleri dürüp katladığımız gibi katlarız. İlk defa yarattığımız gibi, vaadimizi yerine getirmek üzere onu (yeni baştan) yaratacağız. Şüphesiz biz (bunu) yapıcılarız.'),
(21, 105, 17, 331, 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ', 'wa laqad katabnā fī z-zabūri min baʿdi dh-dhikri anna l-arḍa yariṯuhā ʿibādiya ṣ-ṣāliḥūna', 'Yemin olsun, Zikir''den (Tevrat''tan) sonra (da) Zebur''da şöyle yazdık: Şüphesiz yeryüzüne benim salih kullarım varis olacaktır.'),
(21, 106, 17, 331, 'إِنَّ فِى هَٰذَا لَبَلَٰغًا لِّقَوْمٍ عَٰبِدِينَ', 'ʾinna fī hādhā labalāghan liqawmin ʿābidīn', 'Şüphesiz ki bunda, kulluk eden bir kavim için elbette bir tebliğ (yeterli bir mesaj) vardır.'),
(21, 107, 17, 331, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ', 've mā arsalnāka illā raḥmatan lil-ʿālamīn', 'Seni ancak alemlere bir rahmet olarak gönderdik.'),
(21, 108, 17, 331, 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَهَلْ أَنتُم مُّسْلِمُونَ', 'qul innemā yūḥā ilayya ennemā ilāhukum ilāhun wāḥidun fehal entum muslimūn', 'De ki: "Benim vahyedilenim ancak, sizin ilahınızın tek bir ilah olduğudur. Artık siz (O''na) teslim olacak mısınız?"'),
(21, 109, 17, 331, 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ', 'fa-in tawallaw fa-qul āḏantukum ʿalā sawāʾin wa-in adrī aqarībun am baʿīdun mā tūʿadūn', 'Eğer yüz çevirirlerse, de ki: "Hepinize eşit olarak bildirdim (uyardım). Vaat olunduğunuz şeyin yakın mı uzak mı olduğunu da bilmiyorum."'),
(21, 110, 17, 331, 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 'ʾinnahuu yaʿlamu l-jahra mina l-qawli wa yaʿlamu maa taktumuun', 'Doğrusu O, sözün açığa vurulanını da bilir, gizlediğinizi de bilir.'),
(21, 111, 17, 331, 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'wa-ʾin ʾadrī laʿallahu ḥiftanatun lakum wa-matāʿun ʾilā ḥīnin', 'Ve ben bilmem, belki de bu sizin için bir imtihan ve belli bir zamana kadar bir faydalanmadır.'),
(21, 112, 17, 331, 'قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'qāla rabbi ḥkum bil-ḥaqqi wa rabbunā r-raḥmānu l-mustaʿānu ʿalā mā taṣifūna', 'Ey Rabbim! Hak ile hükmet. Ve Rabbimiz, sizin vasıflandırdıklarınıza karşı yardım istenendir.'),
(22, 1, 17, 332, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌ', 'yā ayyuhā n-nāsu ttaqū rabbakum inna zalzalaha s-sāʿati shayʾun ʿaẓīm', 'Ey insanlar! Rabbinizden çekinip korkun. Şüphesiz, kıyamet gününün zelzelesi (sarsıntısı) büyük bir şeydir.'),
(22, 2, 17, 332, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ', 'yawma tarawnahā tadh-halu kullu murḍiʿatin ʿammā arḍaʿat wa taḍaʿu kullu dhāti ḥamlin ḥamlahā wa tarā an-nāsa sukārā wa mā hum bisukārā wa lākinna ʿadhāba Allāhi shadīd', 'Onu (o dehşetli anı) gördüğün gün, her emziren kadın emzirmekte olduğu (bebeğinden) gafil olur ve her hamile kadın yükünü (çocuğunu) düşürür. İnsanları sarhoş bir halde görürsün; oysa sarhoş değillerdir. Fakat Allah''ın azabı (çok) şiddetlidir.'),
(22, 3, 17, 332, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَٰنٍ مَّرِيدٍ', 'wa mina n-nāsi man yujādilu fī llāhi biġayri ʿilmin wa yattabiʿu kulla šayṭānin marīdin', 'İnsanlardan öylesi vardır ki, bilgisizce Allah hakkında tartışır ve her inatçı şeytanın peşine düşer.'),
(22, 4, 17, 332, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'kutiba ʿalayhi ʾannahu man tawallāhu fa-ʾannahu yuḍilluhu wa-yahdīhi ʾilā ʿadhābi s-saʿīri', 'Onun hakkında şöyle yazılmıştır: Kim onu (bu görevi) sırtına alırsa, gerçekten o kimseyi saptırır ve onu yakıcı azaba iletir.'),
(22, 5, 17, 332, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍ شَيْـًٔا وَتَرَى ٱلْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'yā ayyuhā n-nāsu in kuntum fī raybin mina l-baʿthi fa-innā khalaqnākum min turābin thumma min nuṭfatin thumma min ʿalaqatin thumma min muḍghatin mukhallaqatin wa-ghayri mukhallaqatin li-nubayyi na lakum wa-nuqirru fī l-arḥāmi mā nashāʾu ilā ajalin musammā thumma nukhrijukum ṭiflan thumma li-tablughū ʾashuddakum wa-minkum man yutawaffā wa-minkum man yuraddu ilā ʾardhali l-ʿumuri li-kaylā yaʿlama min baʿdi ʿilmin shayʾan wa-tarā l-arḍa hāmidatan fa-idhā ʾanzalnā ʿalayhā l-māʾa ihtazzat wa-rabat wa-ʾanbatat min kulli zawjin bahījin', 'Ey insanlar! Eğer yeniden dirilme hususunda bir şüphe içindeyseniz, (bilin ki) biz sizi topraktan, sonra bir damla sudan, sonra bir pıhtıdan, sonra da hem şekli (insan ve diğer varlıklar gibi) belli olmuş hem de belli olmamış bir et parçasından yarattık. Size (kudretimizi) açıkça göstermek için (bunları açıklıyoruz). Dilediğimizi, belirlenmiş bir vakte kadar rahimlerde tutarız. Sonra sizi (bir bebek olarak) dışarı çıkarırız. İçinizden kimi vefat ettirilir, kimi de bilgili iken hiçbir şeyi bilemez hale gelinceye kadar ömrün en düşkün (zavallı) zamanına ulaştırılır. Yeryüzünü kupkuru ve cansız görürsün. Biz üzerine yağmuru indirdiğimizde ise, o canlanır, kabarır ve her türlü güzel (ve çiftli) bitkiler bitirir. Şüphesiz Allah, yücedir, her şeyden haberdardır.'),
(22, 6, 17, 333, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ḏālika biʾanna ʾallāha huwa ʾalḥaqqu wa ʾannahu yuḥyī ʾalmawta wa ʾannahu ʿalā kulli šayʾin qadīrun', 'İşte bu böyledir; çünkü Allah, hakkın ta kendisidir ve O, ölüleri diriltir; şüphesiz O, her şeye hakkıyla gücü yetendir.'),
(22, 7, 17, 333, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', 'wa-anna s-sāʿata ʾātiyatun lā rayba fīhā wa-anna Llāha yabʿathu man fī l-qubūri', 'Şüphesiz kıyamet günü gelecektir; bunda hiçbir şüphe yoktur. Ve şüphesiz Allah, kabirlerde olanları diriltecektir.'),
(22, 8, 17, 333, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ', 'wa mina n-nāsi man yujādilu fī llāhi bighayri ʿilmin walā hudan walā kitābin munīrin', 'İnsanlardan kimi de bilgisizce, yol göstermeksizin ve aydınlatıcı bir kitap olmaksızın Allah hakkında tartışır.'),
(22, 9, 17, 333, 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَٰمَةِ عَذَابَ ٱلْحَرِيقِ', 'thāniya ʿiṭfihi liyuḍilla ʿan sabīli llāh lahū fī d-dunyā khizyun wa nudhīquhu yawma l-qiyāmati ʿadhāba l-ḥarīqi', 'Kıvırıp yüz çevirir ki, Allah''ın yolundan saptırsın. Ona bu dünyada bir perişanlık vardır; kıyamet gününde ise ona yakıcı azabı tattırırız.'),
(22, 10, 17, 333, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'dhālika bimā qaddamat yadāka wa anna Llāha laysa biẓallāmin lil-ʿabīd', 'İşte bu, kendi ellerinle yaptığın yüzündendir. Şüphesiz Allah kullarına zulmedici değildir.'),
(22, 11, 17, 333, 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْءَاخِرَةَ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 'wa mina n-nāsi man yaʿbudu l-lāha ʿalā ḥarfin fa-in ʾaṣābahū khayrun ʾiṭmaʾanna bihī wa-in ʾaṣābathū fitnatun nqallaba ʿalā wajhihī khasira d-dunyā wa-l-ʾākhirata dhālika huwa l-khusrānu l-mubīnu', 'İnsanlardan kimi de Allah''a bir yar (uç)tan tapar. Eğer kendisine bir hayır (iyilik) gelirse, onunla tatmin bulur. Şayet başına bir fitne (musibet) gelirse, yüzüstü dönüverir. O, dünyayı da ahireti de kaybetmiştir. İşte bu, apaçık bir ziyandır.'),
(22, 12, 17, 333, 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', 'yadʿū min dūni llāhi mā lā yaḍurruhu wa mā lā yanfaʿuhu ḏālika huwa ḍ-ḍalālu l-baʿīd', 'Allah''ı bırakıp da kendisine zarar vermeyecek ve fayda sağlamayacak şeylere dua eder. İşte bu, (hak yoldan) uzak bir sapıklıktır.'),
(22, 13, 17, 333, 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', 'yad''ū liman ḍarruhu ʾaqrabu min naf''ihi labiʾsa l-mawla wa labiʾsa l-ʿashīr', 'Zararı faydasından daha yakın olana dua eder. Ne kötü bir yardımcı ve ne kötü bir dost!'),
(22, 14, 17, 333, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 'ʾinna llāha yudkhilu llaḏīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti jannātin tajrī min taḥtihā l-ʾanhāru ʾinna llāha yafʿalu mā yūrīdu', 'Şüphesiz Allah, iman edip salih amel işleyenleri, altlarından ırmaklar akan cennetlere koyar. Şüphesiz Allah dilediğini yapar.'),
(22, 15, 17, 333, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', 'man kāna yaẓunnu an lan yanṣurahū ʾllāhu fī ʾd-dunyā wa-ʾl-ʾākhirati falyamdud bisababin ʾilā ʾs-samāʾi thumma lyaqṭaʿ falyanẓur hal yuʾdhibanna kayduhu mā yagīẓu', 'Kim Allah''ın ona dünyada ve ahirette asla yardım etmeyeceğini sanıyorsa, hemen göğe bir ip uzatsın, sonra (kendini) assın ve bir baksın; bu hilesi (boğulması) öfkesini giderecek mi?'),
(22, 16, 17, 334, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', 'wa kadhalika anzalnahu ayatin bayyinatin wa anna Allaha yahdi man yuridu', 'İşte böylece onu apaçık ayetler olarak indirdik. Şüphesiz Allah, dilediği kimseyi doğru yola iletir.'),
(22, 17, 17, 334, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'ʾinna lladhīna ʾāmanū wal-ladhīna hādū waṣ-ṣābiʾīna wan-naṣārā wal-majūsa wal-ladhīna ʾashrakū ʾinna llāha yafṣilu baynahum yawma l-qiyāmati ʾinna llāha ʿalā kulli shayʾin shahīdun', 'Şüphesiz iman edenler, Yahudiler, Sabiîler, Hristiyanlar, Mecusiler ve şirk koşanlar var ya, Allah şüphesiz kıyamet günü haklarında (doğru) hükmü verecektir. Çünkü Allah her şeyi hakkıyla bilendir.'),
(22, 18, 17, 334, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌ مِّنَ ٱلنَّاسِ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ', 'ʾalam tara ʾanna ʾallāha yasjudu lahū man fī s-samāwāti wa man fī l-ʾarḍi wa-sh-shamsu wa-l-qamaru wa-n-nujūmu wa-l-jibālu wa-sh-shajaru wa-d-dawābbu wa kathīrun mina n-nāsi wa kathīrun ḥaqqa ʿalayhi l-ʿaḏābu wa man yuhini ʾallāhu famā lahū min mukrimin ʾinna ʾallāha yafʿalu mā yashāʾu', 'Görmedin mi, göklerde olanlar da, yerde olanlar da, güneş de, ay da, yıldızlar da, dağlar da, ağaçlar da, hayvanlar da, insanlar da ve (yine) insanlar ve cinlerden de kendisi aleyhine azap hükmü gerçekleşmiş olanlar da Allah''a secde ederler. Allah''ın hor gördüğüne ise kimse ikram edemez. Şüphesiz Allah dilediğini yapar.'),
(22, 19, 17, 334, 'هَٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', 'hādhāni khaṣmāni ikhtaṣamū fī rabbihim fa-lladhīna kafarū quṭṭiʿat lahum thiyābun min nārin yuṣabbu min fawqi ruʾūsihimu l-ḥamīmu', 'İşte birbirine düşen iki taraf! Rableri hakkında tartışıyorlardı. İnkar edenlere gelince, onlara ateşten elbiseler biçilmiştir; başlarının üstünden de kaynar su dökülür.'),
(22, 20, 17, 334, 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', 'yuṣharu bihī mā fī buṭūnihim wa-l-julūdu', 'Onların karınlarındaki ve derileri erir.'),
(22, 21, 17, 334, 'وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍ', 'wa lahum maqāmiʿu min ḥadīd', 'Ve onların, demirden kamçıları vardır.'),
(22, 22, 17, 334, 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'kullamā arādū an yakhrujū minhā min ġammin uʿīdū fīhā wa ḏūqū ʿaḏāb al-ḥarīq', 'Ne zaman oradan, bir üzüntüden (kurtulmak) için çıkmak isteseler, oraya geri çevrilirler ve onlara ''Yakma azabını tadın!'' (denir).'),
(22, 23, 17, 334, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'ʾinna ʾallāha yudkhilu ʾalladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti jannātin tajrī min taḥtihā l-ʾanhāru yuḥallawna fīhā min ʾasāwira min dhahabin wa luʾluʾan wa libāsuhum fīhā ḥarīrun', 'Şüphesiz Allah, iman edip salih amel işleyenleri, altlarından ırmaklar akan, içinde süs eşyalarıyla (altın bileziklerle) ve ipekten elbiselerle donatılmış olarak cennetlere kabul eder.'),
(22, 24, 17, 335, 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', 'wa hudū ilā aṭ-ṭayyibi mina al-qawli wa hudū ilā ṣirāṭi al-ḥamīd', 'Ve onları (o müminleri) tertemiz sözlere ve her türlü övgüye lâyık olan Allah''ın yoluna iletmişti.'),
(22, 25, 17, 335, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً ٱلْعَٰكِفُ فِيهِ وَٱلْبَادِ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ', 'ʾinna lladhīna kafarū wayaṣuddūna ʿan sabīli l-lāhi wal-masjidi l-ḥarāmi lledhī jaʿalnāhu li-nnāsi sawāʾan l-ʿākifu fīhi wal-bādi waman yurid fīhi bi-ʾilḥādin bi-ẓulmin nudhihqu min ʿadhābin ʾalīmin', 'Şüphesiz inkâr edenler ve (insanları) Allah''ın yolundan ve -orada yerleşik olanla dışarıdan geleni eşit kıldığımız- Mescid-i Haram''dan alıkoyanlar, zulmederek orada haktan sapanı, elem dolu bir azaptan tattıracağız.'),
(22, 26, 17, 335, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'wa-ʾiḏ bawwaʾnā li-ʾibrāhīma makāna l-bayti ʾan lā tušrik bī šayʾan wa-ṭahhir baytiya li-ṭ-ṭāʾifīna wa-l-qāʾimīna wa-r-rukkāʿi s-sujūd', 'Hani biz İbrahim''e o evin yerini belirlemiş ve şöyle demiştik: Bana hiçbir şeyi ortak koşma; evimi tavaf edenler, namaz kılanlar ve rüku edenler (ve secde edenler) için temiz tut.'),
(22, 27, 17, 335, 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ', 'waʾaḏḏin fī n-nāsi bi l-ḥajji yaʾtūka rijālan wa ʿalā kulli ḍāmirin yaʾtīna min kulli fajjin ʿamīqin', 'Nihayet insanları hacca çağır; hem yaya hem de nice nice uzak yollardan gelen yorgun develer üzerinde sana gelsinler.'),
(22, 28, 17, 335, 'لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', 'li-yash-hadū manāfiʿa lahum wa-yadh-kurū sm-a llāhi fī ʾayyāmin maʿlūmātin ʿalā mā razaqahum mim bahīmati l-ʾanʿāmi fa-kulū minhā wa-ʾaṭʿimū l-bāʾisa l-faqīra', 'Böylece kendileri için birtakım faydaları görsünler ve kendilerine rızık olarak verdiği (kurbanlık) hayvanlar üzerine belirli günlerde Allah''ın adını anıp (kessinler). Artık onlardan hem kendiniz yiyin hem de sıkıntıya düşen, fakir olan kimselere de yedirin.'),
(22, 29, 17, 335, 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', 'thumma lyaqḍū tafathahum walyūfū nuḏūrahum walyatṭawwafū bil-bayti l-ʿatīq', 'Sonra kirlerini gidersinler, adaklarını yerine getirsinler ve Beyt-i Atik''i tavaf etsinler.'),
(22, 30, 17, 335, 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيْرٌ لَّهُۥ عِندَ رَبِّهِۦ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', 'dhālika wa man yuʿaẓẓim ḥurumāti llāhi fa-huwa khayrun lahū ʿinda rabbihī wa uḥillat lakumu l-anʿāmu illā mā yutlā ʿalaykum fa-jtanibū r-rijsa mina l-awthāni wa-jtanibū qawla z-zūri', 'İşte bunlardır. Kim Allah''ın haram kıldığı şeylere saygı gösterirse, bu, Rabbi katında kendisi için hayırlıdır. Size okunacak olanlar (haram oldukları) dışında, öteki hayvanlar size helâl kılındı. Artık putlardan pis olanlardan kaçının ve yalan sözden kaçının.'),
(22, 31, 17, 336, 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍ سَحِيقٍ', 'ḥunafāʾa li-llāhi ghayra mushrikīna bihi wa-man yushrik bi-llāhi fa-kaʾannamā kharra mina s-samāʾi fa-takhtafuhu ṭ-ṭayru ʾaw tahwī bihi r-rīḥu fī makānin saḥīqin', 'Allah''a yönelerek, O''na ortak koşmaksızın (itaat edin). Kim Allah''a ortak koşarsa, gökten düşmüş de onu ya kapıp parçalamış ya da rüzgar onu uzak bir yere atmış gibidir.'),
(22, 32, 17, 336, 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', 'dhālika wa man yuʿaẓẓim shaʿāʾira ʾllāhi fa-ʾinnahā min taqwā ʾl-qulūbi', 'İşte böyle; kim Allah''ın nişanelerine saygı gösterirse, bu, kalplerin takvasındandır.'),
(22, 33, 17, 336, 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', 'lakum fīhā manāfiʿu ʾilā ʾajalin musammā thumma maḥilluhā ʾilā l-bayti l-ʿatīq', 'Onlar için belirli bir süreye kadar (çeşitli) faydalar vardır. Sonra onların varacakları yer Beyt-i Atik''tir (Kâbe''dir).'),
(22, 34, 17, 336, 'وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَلَهُۥٓ أَسْلِمُوا۟ وَبَشِّرِ ٱلْمُخْبِتِينَ', 'wa likulli ummatin jaʿalnā mansakan liyaḏkurū ʾisma ʾallāhi ʿalā mā razaqahum mim bahīmati l-ʾanʿām fa-ʾilāhukum ʾilāhun wāḥidun fa-lahū ʾaslimū wa-bašširi l-muḫbitīn', 'Her ümmete, kendilerine rızık olarak verdiği (o) hayvanlardan kurban kesmeyi gerekli kıldık. Hepinizin ilahı bir tek ilahtır. Yalnız O''na teslim olun. (Ey Muhammed!) O derin saygı gösterenleri müjdele.'),
(22, 35, 17, 336, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'alladhīna idhā dhukira allāhu wajilat qulūbuhum wa-al-ṣābirīna ʿalā mā aṣābahum wa-al-muqimī al-ṣalāti wa-mimmā razaqnāhum yunfiqūna', 'Onlar, Allah zikredildiği zaman kalpleri titreyen, başlarına gelene sabreden, namazı dosdoğru kılan ve kendilerine verdiğimiz rızıktan (hayır için) harcayanlardır.'),
(22, 36, 17, 336, 'وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'wa-l-budna ǧaʿalnāhā lakum min šaʿāʾiri ʾllāhi lakum fīhā ḫayrun fa-ḏkurū ʾsma ʾllāhi ʿalayhā ṣawāffa fa-ʾiḏā waǧabat ǧunūbuhā fakulū minhā wa-ʾaṭʿimū l-qāniʿa wa-l-muʿtarra kaḏālika saḫḫarnāhā lakum laʿallakum taškurón', 'Kurbanlık deve ve sığırları da Allah''ın dininin nişanelerinden kıldık. Sizin için onlarda hayır vardır. Şu halde, onlar yan yatıp yatarken üzerlerine Allah''ın ismini anın. Canları çıktığında artık onlardan hem kendiniz yiyin hem de kanaatkâr fakire ve dilenene yedirin. İşte böylece, şükretmeniz için onları size boyun eğdirdik.'),
(22, 37, 17, 336, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَبَشِّرِ ٱلْمُحْسِنِينَ', 'lan yanāla allāha luḥūmuhā walā dimāʾuhā walākin yanāluhu al-taqwā minkum kaḏālika saḵḵarahā lakum litukabbirū allāha ʿalā mā hadākum wa-bašširi al-muḥsinīn', 'Onların etleri ve kanları Allah''a ulaşmaz. Lakin O''na sizin takvanız ulaşır. Böylece onları sizin için ram etti ki, size yol göstermesine karşılık Allah''ı tekbir edesiniz. (Ey Muhammed!) İyilik edenleri müjdele.'),
(22, 38, 17, 336, 'إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ', 'inna llāha yudāfiʿu ʿani llaḏīna ʾāmanū inna llāha lā yuḥibbu kulla ḫawwānin kafūr', 'Şüphesiz Allah, iman edenleri savunur. Gerçekten Allah, hiçbir haini, hiçbir nankörü sevmez.'),
(22, 39, 17, 337, 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', 'udhinna lilladhīna yuqātalūna bi''annahum ẓulimū wa''inna Allāha ʿalā naṣrihim laqadīr', 'Kendilerine savaş açılanlara, zulme uğradıkları için (savaşma ve) izin verildi. Şüphesiz Allah, onlara yardım etmeye de kadirdir.'),
(22, 40, 17, 337, 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌ وَصَلَوَٰتٌ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًا وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'alladhīna ukhrijū min diyārihim bighayri ḥaqqin illā an yaqūlū rabbunā allāhu walawlā dafʿu allāhi annāsa baʿḍahum bibaʿḍin lahuddimat ṣawāmiʿu wabyiʿun waṣalawātun wamasājidu yudhkaru fīhā ismu allāhi kathīran walayanṣuranna allāhu man yanṣuruhū ʾinna allāha laqawiyyun ʿazīzun', 'Onlar ki, yalnızca: "Rabbimiz Allah''tır" demeleri yüzünden, haklı bir sebep olmaksızın yurtlarından çıkarıldılar. Eğer Allah''ın, insanları birbirleriyle savıp defetmesi olmasaydı, manastırlar, kiliseler, havralar ve içinde Allah''ın adı çokça anılan mescitler mutlaka yıkılır, viran olurdu. Allah, kendi dinine yardım edenlere mutlaka yardım eder. Şüphesiz Allah, çok güçlüdür, mutlak güç sahibidir.'),
(22, 41, 17, 337, 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ وَلِلَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'alladhīna in makkannāhum fī l-arḍi aqāmū ṣ-ṣalāta wa-ātū z-zakāta wa-amarū bil-maʿrūfi wa-nahaw ʿani l-munkari wa-lillāhi ʿāqibatu l-umūri', 'Onlar ki, eğer kendilerine yeryüzünde imkân ve iktidar verirsek, namazı dosdoğru kılarlar, zekâtı verirler, iyiliği emrederler ve kötülükten nehyederler. Bütün işlerin sonu Allah''a aittir.'),
(22, 42, 17, 337, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ', 'wa-ʾin yukadhdhibūka faqad kadhdhabat qablahum qawmu nūḥin wa-ʿādin wath-thamūdu', 'Eğer seni yalanlarlarsa, onlardan önce Nuh''un kavmi, Âd ve Semûd da yalanlamıştı.'),
(22, 43, 17, 337, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍ', 'wa qawmu ibrāhīma wa qawmu lūṭin', 'İbrahim''in kavmi ve Lut kavmi de (yalanlamışlardı).'),
(22, 44, 17, 337, 'وَأَصْحَٰبُ مَدْيَنَ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ نَكِيرِ', 'waʾaṣḥābu madyana wakudhdhiba mūsā faʾamlaytu lilkāfirīna thumma ʾakhaḏtuhum fakayfa kāna nakīri', 'Medyen halkı da ve Musa da yalanlandı. Ben de kâfirlere mühlet verdim, sonra onları yakaladım. Benim inkârım (cezalandırmam) nasıl oldu!'),
(22, 45, 17, 337, 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ', 'fa-kaʾayyin min qaryatin ʾahlaknāhā wa-hiya ẓālimatun fa-hiya khāwiyatun ʿalā ʿurūshihā wa-biʾrin muʿaṭṭalatin wa-qaṣrin mashīdin', 'Zalim oldukları halde helak ettiğimiz nice memleketler vardır ki, evleri duvarlarının üzerine çökmüş durumdadır. Nice kullanılmaz hale gelmiş kuyular ve sağlam yapılar da (helak olmuştur).'),
(22, 46, 17, 337, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌ يَسْمَعُونَ بِهَا فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', 'ʾafalam yasīrū fī l-ʾarḍi fatakūna lahum qulūbun yaʿqilūna bihā ʾaw ʾādhānun yasmaʿūna bihā faʾinnahā lā taʿmā l-ʾabṣāru walākin taʿmā l-qulūbu llatī fī ṣ-ṣudūri', 'Yeryüzünde dolaşmadılar mı? Zira onların, akl edecekleri kalpleri veya işitecekleri kulakları olurdu. Ama gerçek şu ki, gözler kör olmaz; lakin göğüslerde bulunan kalpler kör olur.'),
(22, 47, 17, 338, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ', 'wa yastaʿjilūnaka bil-ʿadhābi wa lan yukhlifa Allāhu waʿdahu wa inna yawman ʿinda rabbika ka-alfi sanatin mimmā taʿuddūna', 'Sana azabı acele istiyorlar. Halbuki Allah vaadinden dönmez. Ve şüphe yok ki, Rabbinin katında bir gün, sizin saydıklarınızdan bin sene gibidir.'),
(22, 48, 17, 338, 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', 'wa kaʾayyin min qaryatin ʾamlaytu lahā wa hiya ẓālimatun thumma ʾakhaḏtuhā wa ʾilayya l-maṣīru', 'Nice kasabalara (halkına) zulmetmiş oldukları halde mühlet verdim, sonra onları yakaladım. Dönüş yalnız Banadır.'),
(22, 49, 17, 338, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌ مُّبِينٌ', 'qul yā ayyuhā n-nāsu innamā anā lakum nadīrun mubīn', 'De ki: "Ey insanlar! Ben sizin için yalnızca apaçık bir uyarıcıyım."'),
(22, 50, 17, 338, 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'fa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti lahum maghfiratun wa-rizqun karīmun', 'İman edip salih amel işleyenlere gelince, onlar için bir bağışlanma ve değerli bir rızık vardır.'),
(22, 51, 17, 338, 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'wa-lladhīna saʿaw fī ʾāyātinā muʿājizīna ʾulāʾika ʾaṣḥābu l-jaḥīmi', 'Ayetlerimizi geçersiz kılmaya çalışıp (boşa çıkaranlar), işte onlar cehennem ehlidir.'),
(22, 52, 17, 338, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'wa mā arsalnā min qablika min rasūlin wa lā nabiyyin illā iḏā tamannā alqā ʾš-šayṭānu fī ʾumniyyatihī fayansahu ʾllāhu mā yulqī ʾš-šayṭānu ṯumma yuḥkimu ʾllāhu ʾāyātihi wa ʾllāhu ʿalīmun ḥakīmun', 'Senden önce hiçbir Resûl ve Nebî göndermedik ki, bir temennide bulunduğu zaman Şeytan onun temennisine (vesvese verip) bir şeyler atmasın. Allah, Şeytan''ın attığını mahveder, sonra Allah âyetlerini sağlamlaştırır. Allah, Alîm''dir, Hakîm''dir.'),
(22, 53, 17, 338, 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَٰنُ فِتْنَةً لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْقَاسِيَةِ قُلُوبُهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍ', 'li-yajʿala mā yulqī sh-shayṭānu fitnatan lilladhīna fī qulūbihim maraḍun wa-l-qāsiyati qulūbuhum wa-inna ẓ-ẓālimīna la-fī shiqāqin baʿīd', 'Böylece Allah, şeytanın attığını (vesvesesini) kalplerinde hastalık bulunanlar ve katı kalpliler için bir fitne (imtihan) kılmaktadır. Şüphesiz zalimler, (haktan) uzak bir ayrılık içindedirler.'),
(22, 54, 17, 338, 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa-liyaʿlama alladhīna ūtū al-ʿilma annahu al-ḥaqqu min rabbika fa-yuʾminū bihi fa-tukhbita lahu qulūbuhum wa-inna Allāha la-hādī alladhīna āmānū ilā ṣirāṭin mustaqīm', 'Böylece, kendilerine ilim verilmiş olanlar, bunun (Kur''an''ın) Rabbinden gelen hak olduğunu bilsinler de ona iman etsinler, böylece kalpleri ona (Allah''a) saygı duysun. Şüphesiz Allah, iman edenleri doğru yola iletir.'),
(22, 55, 17, 338, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', 'wa lā yazālu lladhīna kafarū fī miryatin minhu ḥattā taʾtiyahumu s-sāʿatu baghtatan aw yaʾtiyahum ʿadhābu yawmin ʿaqīmin', 'İnkâr edenler ise, kendilerine o (kıyamet) saati ansızın gelinceye veya (yaşadıkları) akim bir günün azabı kendilerine ulaşıncaya kadar ondan (Kur''an''dan veya Allah''tan) yana bir şüphe içinde olmaya devam ederler.'),
(22, 56, 17, 339, 'ٱلْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ', 'al-mulku yawmaʾiḏin lillāh yaḥkumu baynahum fa-llaḏīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti fī jannāti n-naʿīm', 'O gün mülk (hükümranlık) Allah''ındır. Aralarında O hükmeder. İman edip salih amel işleyenler, Naîm cennetlerindedirler.'),
(22, 57, 17, 339, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا فَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'wa-lladhīna kafarū wa-kadhdhabū bi-ʾāyātinā fa-ʾulāʾika lahum ʿadhābun muhīnun', 'İnkâr edip âyetlerimizi yalanlayanlara gelince, işte onlar, onlar için rezil edici bir azap vardır.'),
(22, 58, 17, 339, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًا وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'wa-lladhīna hājarū fī sabīli-llāhi thumma qutilū aw mātū layarzuqannahumu-llāhu rizqan ḥasanan wa-inna-llāha lahuwa khayru-rrāziqīn', 'Allah yolunda hicret edip sonra öldürülen veya ölen kimselere Allah, elbette güzel bir rızık verecektir. Şüphesiz Allah, rızık verenlerin en hayırlısıdır.'),
(22, 59, 17, 339, 'لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُۥ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌ', 'leyudḫilennehum mudḫalen yerḍavnehu ve inne-llâhe leʿalîmun ḥalîm', 'Şüphesiz onları hoşnut olacakları bir yere sokacaktır. Ve şüphesiz Allah, elbette hakkıyla bilendir, halimdir.'),
(22, 60, 17, 339, 'ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', 'dhālika wa-man ʿāqaba bi-mithli mā ʿūqiba bihi thumma bughiya ʿalayhi la-yanṣurannahu allāhu ʾinna allāha la-ʿafūwun ghafūr', 'İşte böyle; kim kendisine yapılanın misliyle karşılıkta bulunur da, sonra yine kendisine zulmedilmiş olursa, elbette Allah ona yardım eder. Şüphesiz Allah affedicidir, bağışlayıcıdır.'),
(22, 61, 17, 339, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'dhālika biʾanna ʾallāha yūliju l-layla fī n-nahāri wa yūliju n-nahāra fī l-layli wa ʾanna ʾallāha samīʿum baṣīr', 'İşte bu, Allah''ın geceyi gündüze sokması ve gündüzü geceye sokması nedeniyledir. Ve Allah''ın Semi'' (işiten) ve Basir (gören) olmasındandır.'),
(22, 62, 17, 339, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'dhālika biʾanna ʾallāha huwa l-ḥaqqu waʾanna mā yadʿūna min dūnihi huwa l-bāṭilu waʾanna ʾallāha huwa l-ʿaliyyu l-kabīru', 'İşte bu böyledir; çünkü Allah, hakkın ta kendisidir ve O''ndan başka taptıkları ise bâtıldır. Ve Allah, yücedir, büyüktür.'),
(22, 63, 17, 339, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', 'ʾalam tara ʾanna ʾallāha ʾanzala mina s-samāʾi māʾan fatuṣbiḥu l-ʾarḍu muḫḍaratan ʾinna ʾallāha laṭīfun ḫabīrun', 'Görmedin mi, Allah gökten bir su indirdi de yer kupkuru iken yemyeşil kesildi. Şüphesiz Allah, incelikleri görüp bilendir, her şeyden haberdar olandır.'),
(22, 64, 17, 339, 'لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'lahū mā fī s-samāwāti wa mā fī l-arḍi wa inna llāha lahuwa l-ġaniyyu l-ḥamīd', 'Göklerde ve yerde ne varsa hepsi O''nundur. Şüphesiz Allah, zengin olan, övgüye layık olan da O''dur.'),
(22, 65, 17, 340, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', 'elem tera enne-llāhe sekkhara lekum mā fī-l-arḍi ve-l-fulke tecrī fī-l-baḥri bi-ʾamrihī ve yumsiku-s-semāʾa ʾen teqaʿa ʿalā-l-arḍi ʾillā bi-ʾiḏnihī ʾinne-llāhe bi-n-nāsi le-raʾūfun raḥīm', 'Yeryüzündekileri ve buyruğuyla denizde akıp giden gemileri sizin için Allah''ın boyun eğdirdiğini görmedin mi? Ve göğü de izni olmadıkça yeryüzüne düşmekten O tutuyor. Şüphesiz Allah, insanlara karşı çok şefkatlidir, çok merhametlidir.'),
(22, 66, 17, 340, 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ', 'wa huwa alladhī aḥyākum thumma yumītukum thumma yuḥyīkum inna al-insāna lakafūr', 'Ve O, sizi (topraktan) diriltti, sonra sizi öldürecek, sonra sizi (tekrar) diriltecektir. Şüphesiz insan çok nankördür.'),
(22, 67, 17, 340, 'لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ فَلَا يُنَٰزِعُنَّكَ فِى ٱلْأَمْرِ وَٱدْعُ إِلَىٰ رَبِّكَ إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ', 'likulli ummatin jaʿalnā mansakan hum nāsikūhu falā yunāziʿunnaka fī l-amri wa-dʿu ilā rabbika innaka laʿalā hudan mustaqīmin', 'Her ümmet için bir kurban kesme usulü tayin ettik. Artık onlar da bu hususta seninle çekişmesinler. Rabbine davet et. Şüphesiz sen, dosdoğru bir yol üzerindesin.'),
(22, 68, 17, 340, 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', 'wa-ʾin jādālūka fa-quli-llāhu ʾaʿlamu bimā taʿmalūn', 'Onlar seninle tartışırlarsa, şöyle de: Allah, sizin yapmakta olduklarınızı en iyi bilendir.'),
(22, 69, 17, 340, 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'Allāhu yaḥkumu baynakum yawma l-qiyāmati fīmā kuntum fīhi takhtalifūn', 'Allah, kıyamet günü sizin aranızda, üzerinde anlaşmazlığa düştüğünüz şey hakkında hüküm verecektir.'),
(22, 70, 17, 340, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'ʾelem taʿlem ʾenne llāhe yaʿlemu mā fī s-semāʾi wa-l-ʾarḍi ʾinne ḏālika fī kitābin ʾinne ḏālika ʿalā llāhi yasīrun', 'Göklerde ve yerde olanları Allah''ın bildiğini bilmedin mi? Şüphesiz bunlar bir kitaptadır. Şüphesiz bunlar Allah için kolaydır.'),
(22, 71, 17, 340, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', 'wa yaʿbudūna min dūni llāhi mā lam yunazzil bihi ʾ sulṭānan wa mā laysa lahum bihi ʾ ʿilmun wa mā liẓ-ẓālimīna min naṣīrin', 'Onlar, Allah''ın kendilerine hiçbir delil indirmediği ve haklarında hiçbir bilgi sahibi olmadıkları şeylere taparlar. Zalimler için hiçbir yardımcı yoktur.'),
(22, 72, 17, 340, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ وَبِئْسَ ٱلْمَصِيرُ', 'wa ʾidhā tutlā ʿalayhim ʾāyātunā bayyinātin taʿrifu fī wujūhi lladhīna kafarū lmunkaṟa yakādūna yasṭūna billadhīna yatlūna ʿalayhim ʾāyātinā qul ʾafaʾunabbiʾukum bisharrin min dhālikum ʾannāru waʿadahā ʾallāhu lladhīna kafarū wa biʾsa lmaṣīr', 'Onlara açık seçik ayetlerimiz okunduğunda, o kâfirlerin yüzlerinde inkârı görürsün. Neredeyse kendilerine ayetlerimizi okuyanlara saldıracaklar. De ki: "Şimdi size bundan daha kötüsünü haber vereyim mi? Allah, o kâfirleri kendisiyle korkutuyor. Ne kötü bir akıbet!"'),
(22, 73, 17, 341, 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', 'yā ʾayyuhā n-nāsu ḍuriba mathalun fa-stamiʿū lahū ʾinna llaḏīna tadʿūna min dūni llāhi lan yaḫluqū ḏubāban wa-lawi ǧtamaʿū lahū wa-ʾin yaslubhumu ḏ-ḏubābu šayʾan lā yastanqiḏūhu minhu ḍaʿufa ṭ-ṭālibu wa-l-maṭlūbu', 'Ey insanlar! Bir misal verildi, onu dinleyin. Şüphesiz ki Allah''tan başka taptıklarınız, bir sinek bile yaratamazlar. Velev ki onun için toplansalar. Eğer sinek onlardan bir şeyi kapıp alsa, onu ondan kurtaramazlar. İsteyen de, istenen de âciz kalmıştır.'),
(22, 74, 17, 341, 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'Mā qadarū ''llāha ḥaqqa qadrihī ʾInna ''llāha laqawiyyun ʿazīz', 'Onlar, Allah''ın kadrini hakkıyla takdir edemediler. Şüphesiz Allah, en kuvvetli, en üstün ve en mutlak güç sahibidir.'),
(22, 75, 17, 341, 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَٰٓئِكَةِ رُسُلًا وَمِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'Allāhu yaṣṭafī mina l-malāʾikati rusulan wa mina n-nāsi ʾinna Llāha samīʿun baṣīr', 'Allah, meleklerden de resuller seçer, insanlardan da. Şüphesiz Allah, hakkıyla işitendir, hakkıyla görendir.'),
(22, 76, 17, 341, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'yaʿlamu mā bayna ʾaydīhim wamā ḵalfa-hum wa-ʾilā llāhi turjaʿu l-ʾumūru', 'Onların önlerinde ve arkalarında olanları bilir. Bütün işler Allah''a döndürülür.'),
(22, 77, 17, 341, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ', 'yā ayyuhā alladhīna āmanū irkaʿū wa-sjudū wa-ʿbudū rabbakum wa-fʿalū l-khayra laʿallakum tufliḥūn', 'Ey iman edenler! Rükû edin, secde edin, Rabbinize kulluk edin ve hayır işleyin ki kurtuluşa eresiniz.'),
(22, 78, 17, 341, 'وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'wajāhidū fī allāhi ḥaqqa jihādihī huwa ijtabākum wamā jaʿala ʿalaykum fī ad-dīni min ḥaraji millata abīkum ibrāhīma huwa sammākumu al-muslimīna min qablu wa fī hādhā liyakūna ar-rasūlu shahīdan ʿalaykum watakūnū shuhadāʾa ʿalā an-nāsi fa aqīmū aṣ-ṣalāta wa ātū az-zakāta wa ʿtaṣimū bi allāhi huwa mawlākum faniʿma al-mawlá wa niʿma an-naṣīru', 'Allah yolunda, O''nun hakiki cihad ile cihad edin. O, sizi seçti ve din hususunda üzerinize hiçbir zorluk yüklemedi. Babanız İbrahim''in dinine uyun. O (Allah) daha önce de sizi Müslümanlar diye isimlendirdi ve bu (Kur''an''da) da, Elçi size şahit olsun ve siz de insanlara şahit olasınız diye (böyle isimlendirdi). Artık dosdoğru namazı kılın, zekâtı verin ve Allah''a sarılın. O sizin Mevlânızdır. Ne güzel Mevlâ ve ne güzel yardımcı!'),
(23, 1, 18, 342, 'قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', 'ḳad efleḥa-lmüʾminûn(e)', 'Mü''minler gerçekten kurtuluşa ermişlerdir.'),
(23, 2, 18, 342, 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ', 'alladhīna hum fī ṣalātihim khāshiʿūn', 'Onlar, namazlarında huşû içindedirler.'),
(23, 3, 18, 342, 'وَٱلَّذِينَ هُمْ عَنِ ٱللَّغْوِ مُعْرِضُونَ', 'wa-lladhīna hum ʿani l-laghwi muʿriḍūna', 'Onlar ki, boş şeylerden yüz çevirirler.'),
(23, 4, 18, 342, 'وَٱلَّذِينَ هُمْ لِلزَّكَوٰةِ فَٰعِلُونَ', 'wa-lladhīna hum li-z-zakāti fāʿilūna', 'Ve onlar ki, zekâtı yerine getirirler.'),
(23, 5, 18, 342, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'wa-lladhīna hum lifurūjihim ḥāfiẓūn', 'Ve onlar ki, iffetlerini korurlar.'),
(23, 6, 18, 342, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'illa ʿalā ʾazwājihim ʾaw mā malakat ʾaymānuhum fa-ʾinnahum ġayru malūmīn', 'Ancak eşleri ve cariyeleri müstesna; çünkü onlar kınanmazlar.'),
(23, 7, 18, 342, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 'fe-meni-btagā warāʾa dhālika fa-ʾulāʾika humu l-ʿādūn', 'Kim bunun ötesine geçmek isterse, işte onlar haddi aşanlardır.'),
(23, 8, 18, 342, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'wa-lladhīna hum li-ʾamānātihim wa-ʿahdihim rāʿūna', 'Ve onlar, emanetlerine ve ahidlerine riayet edenlerdir.'),
(23, 9, 18, 342, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ', 'wa-lladhīna hum ʿalā ṣalawātihim yuḥāfiẓūna', 'Ve onlar ki, namazlarına dikkat ederler.'),
(23, 10, 18, 342, 'أُو۟لَٰٓئِكَ هُمُ ٱلْوَٰرِثُونَ', 'ʾulāʾika humu l-wāriṯūn', 'İşte onlar, varis olanlardır.'),
(23, 11, 18, 342, 'ٱلَّذِينَ يَرِثُونَ ٱلْفِرْدَوْسَ هُمْ فِيهَا خَٰلِدُونَ', 'alladhīna yarithūna l-fir''dawsa hum fīhā khālidūna', 'Onlar Firdevs''e varis olacaklardır; orada ebedî kalacaklardır.'),
(23, 12, 18, 342, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن سُلَٰلَةٍ مِّن طِينٍ', 'Ve lekad halaknâ el-insâne min sulâletin min tînin', 'Andolsun ki insanı çamurdan süzülmüş bir özden yarattık.'),
(23, 13, 18, 342, 'ثُمَّ جَعَلْنَٰهُ نُطْفَةً فِى قَرَارٍ مَّكِينٍ', 'thumma jaʿalnāhu nuṭfatan fī qarārin makīn', 'Sonra onu, karar kılacak bir damla sudan (spermden) yarattık.'),
(23, 14, 18, 342, 'ثُمَّ خَلَقْنَا ٱلنُّطْفَةَ عَلَقَةً فَخَلَقْنَا ٱلْعَلَقَةَ مُضْغَةً فَخَلَقْنَا ٱلْمُضْغَةَ عِظَٰمًا فَكَسَوْنَا ٱلْعِظَٰمَ لَحْمًا ثُمَّ أَنشَأْنَٰهُ خَلْقًا ءَاخَرَ فَتَبَارَكَ ٱللَّهُ أَحْسَنُ ٱلْخَٰلِقِينَ', 'thumma khalaqnā an-nuṭfata ʿalaqatan fa-khalaqnā al-ʿalaqata muḍghatan fa-khalaqnā al-muḍghata ʿiẓāman fa-kasavnā al-ʿiẓāma laḥman thumma anshaʾnāhu khalqan ʾākhar fa-tabāraka Allāhu ʾaḥsanu al-khāliqīn', 'Sonra o az bir damla suyu bir alak (embriyo) haline getirdik, sonra o alakı bir mudğa (çiğnenmiş et parçası) yaptık, sonra o mudğayı kemikler halinde yarattık ve sonra kemiklerin üzerini etle kapladık. Nihayet onu başka bir yaratık olarak inşa ettik. Yaratıcıların en güzeli olan Allah, ne yücedir!'),
(23, 15, 18, 342, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', 'thumma innakum baʿda dhālika lamayyi tūn', 'Sonra bunun ardından şüphesiz siz öleceksiniz.'),
(23, 16, 18, 342, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ تُبْعَثُونَ', 'thumma innakum yawma l-qiyāmati tubʿathūn', 'Sonra, şüphesiz siz kıyamet günü tekrar diriltileceksiniz.'),
(23, 17, 18, 342, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَٰفِلِينَ', 'Ve lekad halaknâ fevkakum seb''a tarâik Ve mâ kunnâ anil-halkı gâfilîn', 'Andolsun ki sizin üstünüzde yedi yol yarattık. Biz yaratmaktan gafil değiliz.'),
(23, 18, 18, 343, 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَسْكَنَّٰهُ فِى ٱلْأَرْضِ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَٰدِرُونَ', 'waʾanzalnā mina s-samāʾi māʾan biqadarin faʾaskannāhu fī l-ʾarḍi waʾinnā ʿalā ḏahābin bihi ladirūna', 'Biz gökten bir ölçüye göre su indirdik ve onu yeryüzünde tuttuk. Şüphesiz biz onu gidermeye de kâdiriz.'),
(23, 19, 18, 343, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', 'faʾanšaʾnā lakum bihi jannātin min naxīlin waʾaʿnābin lakum fīhā fawākihu kaṯīratun waminhā taʾkulūna', 'Bununla size hurmalardan ve üzümlerden bahçeler meydana getirdik; sizin için orada birçok meyveler de vardır ve siz onlardan yiyorsunuz.'),
(23, 20, 18, 343, 'وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍ لِّلْءَاكِلِينَ', 'wa shajaratan takhruju min ṭūri sayināʾa tanbutu bi-d-duhni wa ṣibghin lil-ʾākilīn', 'Ve Sina dağından çıkan, (meyvesi) yağlı ve yiyenler için bir boya olan bir ağacı da (yarattık).'),
(23, 21, 18, 343, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', 'wa-ʾinna lakum fī l-ʾanʿāmi la-ʿibrah nusqīkum mimmā fī buṭūnihā wa-lakum fīhā manāfiʿu kathīrah wa-minhā taʾkulūn', 'Gerçekten sizin için hayvanlarda da bir ibret vardır. Onların karınlarındaki sütten size içiriyoruz ve onlarda sizin için daha birçok faydalar vardır ve onlardan yiyorsunuz.'),
(23, 22, 18, 343, 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'wa ʿalayhā wa ʿalā l-fulki tuḥmalūn', 'Onların ve gemilerin üzerinde taşınırsınız.'),
(23, 23, 18, 343, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'Ve lekad erselnâ Nûhan ilâ kavmihî fekâle yâ kavmi''budûllâhe mâ lekum min ilâhin gayruhû efelâ tettekûn', 'Andolsun ki Nûh''u kavmine gönderdik de o şöyle dedi: “Ey kavmim! Allah''a kulluk edin. Sizin için O''ndan başka hiçbir ilah yoktur. Hâlâ sakınmayacak mısınız?”'),
(23, 24, 18, 343, 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةً مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 'faqāla l-malāʾu l-ladhīna kafarū min qawmihī mā hādhā illā basharun mithlukum yurīdu an yatafaḍḍala ʿalaykum wa-law shāʾa -llāhu la-anzala malāʾikatan mā samiʿnā bihādhā fī ʾābāʾinā l-ʾawwalīna', 'Bunun üzerine, kavminden kâfir olup ileri gelenler dediler ki: "Bu sizin gibi bir beşerden başkası değildir. Sizin gibi bir insan olup sizin üzerinize üstünlük taslamak istiyor. Eğer Allah dileseydi, (bu konuda) melekler indirirdi. Biz atalarımızdan böyle bir şey duymadık."'),
(23, 25, 18, 343, 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍ', 'in huve illā raculun bihī cinnah feterabbaṣū bihī ḥattā ḥīn', 'O, yalnızca kendisinde bir delilik bulunan bir adamdır. Bir süreye kadar ona göz kulak olun!'),
(23, 26, 18, 343, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'qāla rabbi nṣurnī bimā kaḏḏebūn', 'Dedi: "Rabbim! Beni yalanlamalarına karşılık bana yardım et!"'),
(23, 27, 18, 343, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', 'faʾawḥaynā ʾilayhi ʾani ʾṣnaʿi l-fulka bi-ʾaʿyuninā wa-waḥyinā fa-ʾiḏā jāʾa ʾamrunā wa-fāra t-tannūru fa-sluk fīhā min kullin zawjayni ʾiṯnayn wa-ʾahlaka ʾillā man sabaqa ʿalayhi l-qawlu minhum wa-lā tuḫāṭibnī fī l-laḏīna ẓalamū ʾinnahum muġraqūna', 'Bunun üzerine ona şöyle vahyettik: Gözlerimizin önünde ve vahyimizle gemiyi yap. Bizim emrimiz gelip de tandır coşunca, onun içine her birinden birer çift ve aileni de –daha önce aleyhinde söz söylenmiş olanlar hariç– bindir. Zulmedenler hakkında bana hitap etme; çünkü onlar boğulacaklardır.'),
(23, 28, 18, 344, 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'fa-idhā stawtayta anta wa-man maʿaka ʿalā l-fulki fa-quli l-ḥamdu li-llāhi lladhī najjānā mina l-qawmi ẓ-ẓālimīn', 'Sen ve beraberindekiler gemiye yerleştiğinizde, "Bizi zalimler topluluğundan kurtaran Allah''a hamdolsun" de.'),
(23, 29, 18, 344, 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', 'wa-qul rabbi anzilnī munzalan mubārakā wa-anta khayru l-munzilīn', 'Ve de ki: Rabbim! Beni mübarek bir yere indir ve Sen, (insanları) indirenlerin en hayırlısısın.'),
(23, 30, 18, 344, 'إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ وَإِن كُنَّا لَمُبْتَلِينَ', 'inna fī dhālika la''āyātin wa in kunnā lamubtaliīn', 'Şüphesiz bunda nice ibretler vardır. Biz de gerçekten imtihan edenleriz.'),
(23, 31, 18, 344, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 'thumma anshaʾnā min baʿdihim qarnan ʾākharīn', 'Sonra onların ardından başka bir nesil daha vücuda getirdik.'),
(23, 32, 18, 344, 'فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'faʾarsalnā fīhim rasūlan minhum ʾani ʿbudū ʾllāha mā lakum min ʾilāhin ġayruhu ʾafalā tattaqūn', 'Onların içlerinden kendilerine bir peygamber gönderdik. (Onlara şöyle dedi:) ''Allah''a kulluk edin. Sizin O''ndan başka ilahınız yoktur. Hâlâ (O''ndan) korkmayacak mısınız?'''),
(23, 33, 18, 344, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْءَاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', 'waqāla l-malau min qawmihi alladhīna kafarū wal-kadhdhabū biliqāʾi l-ʾākhirati wa-ʾatrafnāhum fī l-ḥayāti d-dunyā mā hādhā ʾillā basharun mithlukum yaʾkulu mimmā taʾkulūna minhu wayashrabu mimmā tashrabūn', 'Kavminden, inkâr eden ve ahiretle karşılaşmayı yalanlayan, kendilerini dünya hayatında refaha erdirdiğimiz ileri gelenler şöyle dediler: "Bu, sizin gibi bir beşerden başkası değildir. Sizin yediğinizden yer, sizin içtiğinizden içer."'),
(23, 34, 18, 344, 'وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', 'Ve leʾin eṭaʿtum beşeran miṡlekum İnnekum iẕen leḫāsirūn', 'Andolsun ki eğer sizin gibi bir beşere itaat ederseniz, o takdirde siz mutlaka hüsrana uğrayanlardan olursunuz.'),
(23, 35, 18, 344, 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ', 'Ayaʿidukum annakum iḏā mttum wa-kuntum turāban wa-ʿiẓāman annakum muḫrajūn', 'Sizden (birinin) öldüğü, toprak ve kemik haline geldiği zaman, kendinizin (kabirlerinizden) çıkarılacağınızı mı vaad ediyor?'),
(23, 36, 18, 344, 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', 'hayhāta hayhāta limā tūʿadūn', 'Vade olunduğunuz şey ne kadar da uzak!'),
(23, 37, 18, 344, 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 'ʾin hiya ʾillā ḥayātunā d-dunyā namūtu wa-naḥyā wa-mā naḥnu bi-mabʿūthīna', 'Onun (dünyanın) ötesinde bizim için sadece bu dünyadaki hayatımız vardır. Ölürüz ve yaşarız. Bizi yeniden diriltecek kimse yoktur.'),
(23, 38, 18, 344, 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', 'ʾin huwa ʾillā rajulun ʾiftarā ʿalā ʾllāhi kaḏibā wa mā naḥnu lahu bi-muʾminīn', 'O, Allah''a karşı yalan uydurmaktan başka bir şey yapmayan bir adamdan başkası değildir. Biz ona inanacak değiliz.'),
(23, 39, 18, 344, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'qāla rabbi nṣurnī bimā kaḏḏebūn', 'Dediler ki: "Rabbim! Beni yalanlamalarına karşı bana yardım et!"'),
(23, 40, 18, 344, 'قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَٰدِمِينَ', 'qāla ʿammā qalīlin layuṣbiḥunna nādimīn', 'Biraz zaman geçince, pişman olacaklar dedi.'),
(23, 41, 18, 344, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءً فَبُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'faʾaḵaḏathumu ṣ-ṣayḥatu bil-ḥaqqi fajaʿalnāhum ġuṯāʾan fabaʿdan lil-qawmi ẓ-ẓālimīn', 'Nihayet, hak ettikleri sayha (sayha) onları yakaladı ve onları (çöpe atılmış) bir sel köpüğü haline getirdik. Zalimler topluluğunun canı cehenneme!'),
(23, 42, 18, 344, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', 'thumma anshaʾnā min baʿdihim qurunًا ʾākhirīn', 'Sonra onların ardından başka nesiller daha vücuda getirdik.'),
(23, 43, 18, 345, 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 'mā tasbiqu min ummatin ajalāhā wa mā yastakhirūn', 'Hiçbir ümmet ne kendi süresini öne alabilir, ne de geri bırakabilir.'),
(23, 44, 18, 345, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَٰهُمْ أَحَادِيثَ فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ', 'thumma arsálnā rusulanā tatrā kullamā jāʾa ummatan rasūluhā kadhthabūhu fa-atbaʿnā baʿḍahum baʿḍan wa-jaʿalnāhum aḥādīth fa-buʿdan li-qawmin lā yuʾminūn', 'Sonra peş peşe peygamberlerimizi gönderdik. Her ümmete peygamberi geldiğinde onu yalanladılar. Biz de onları birbirine (yok oluşta) takib ettirdik ve onları (ibret) hikâyeleri yaptık. Artık uzak olsun o kavim ki inanmazlar.'),
(23, 45, 18, 345, 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'thumma arṣalnā Mūsā wa-akhāhu Hārūna bi-āyātinā wa-sulṭānin mubīnin', 'Sonra Mûsâ''yı ve kardeşi Hârûn''u da âyetlerimizle ve apaçık bir delille gönderdik.'),
(23, 46, 18, 345, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', 'ilā firʿawna wa-malaihi fastakbarū wa-kānū qawman ʿālīn', 'Firavun''a ve onun ileri gelenlerine gönderdik. Onlar ise büyüklük tasladılar ve zaten yoldan çıkmış bir kavim idiler.'),
(23, 47, 18, 345, 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ', 'faqālūʾa nuʾminu libašarayni miṯlinā waqawmuhumā lanā ʿābidūn', 'Bunun üzerine şöyle dediler: "Bizim gibi iki insana inanır mıyız? Oysa onların kavimleri bize kulluk etmektedir."'),
(23, 48, 18, 345, 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', 'fe-keżżebūhumā fe-kānū min el-muhlekīn', 'Böylece ikisini de yalanladılar ve helak edilenlerden oldular.'),
(23, 49, 18, 345, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ', 'Ve lekad āteynā Mūsā el-kitābe leʿallehum yehtedūn', 'Andolsun ki Musa''ya Kitab''ı verdik ki onlar doğru yolu bulsunlar.'),
(23, 50, 18, 345, 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ', 'wa jaʿalnā bna maryama wa ummahū āyatan wa āwaynāhumā ilā rabwatin dhāti qarārin wa maʿīnin', 'Meryem''in oğlu ile annesini birer delil kıldık ve onları, barınmaya elverişli, sakin bir yere, bir suya (ulaşan) bir tepeye yerleştirdik.'),
(23, 51, 18, 345, 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَٰتِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ', 'yā ayyuhā ar-rusulu kulū mina aṭ-ṭayyibāti wa-ʿmalū ṣāliḥan ʾinnī bimā taʿmalūna ʿalīmun', 'Ey Resûller! Temiz ve helal olan şeylerden yiyin ve salih amel işleyin. Şüphesiz ben, sizin yapmakta olduklarınızı hakkıyla bilenim.'),
(23, 52, 18, 345, 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', 'wa-ʾinna hādhihi ʾummatukum ʾummatan wāḥidatan wa-ʾanā rabbukum fa-ttaqūn', 'Şüphesiz bu sizin ümmetiniz, bir tek ümmettir. Ben de sizin Rabbinizim. Benden korkup sakının.'),
(23, 53, 18, 345, 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 'fetaqaṭṭaʿū amrahum baynahum zuburan kullu ḥizbin bimā ladayhim fariḥūn', 'Ancak onlar, aralarındaki işlerini kendi aralarında parça parça edindiler. Her bir grup, kendi sahip olduklarıyla sevinip böbürlenmektedir.'),
(23, 54, 18, 345, 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', 'faḏarhum fī ġamratihim ḥattā ḥīn', 'Onları ta ki bir zamana kadar kendi dalgınlıkları içinde bırak.'),
(23, 55, 18, 345, 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍ وَبَنِينَ', 'ʾayaḥsabūna ʾannama numiddūhum bihi min māliniw wa-banīn', 'Onlar, kendilerine verdiğimiz mal ve oğullardan dolayı...'),
(23, 56, 18, 345, 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ بَل لَّا يَشْعُرُونَ', 'nusāriʿu lahum fī l-khayrāti bal lā yashʿurūna', 'Onlara hayırlarda yarışırız. Hayır, onlar anlamazlar.'),
(23, 57, 18, 345, 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 'inna alladhīna hum min khashyati rabbihim mushfiqūn', 'Şüphesiz onlar, Rablerinin haşyetinden (korkusundan) titreyenlerdir.'),
(23, 58, 18, 345, 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ', 'wa-lladhīna hum bi-ʾāyāti rabbihim yuʾminūna', 'Ve onlar ki Rablerinin ayetlerine inanırlar.'),
(23, 59, 18, 345, 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', 'wa-lladhīna hum bi-rabbihim lā yushrikūn', 'Onlar ki, Rablerine şirk koşmazlar.'),
(23, 60, 18, 346, 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', 'wa-lladhīna yuʾtūna mā ʾātāw wa-qulūbuhum wajilatun ʾannahum ʾilā rabbihim rājiʿūna', 'Onlar, verdiklerini verdikleri halde kalpleri titreyerek (verirler); çünkü onlar Rablerine döneceklerdir.'),
(23, 61, 18, 346, 'أُو۟لَٰٓئِكَ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ', 'ʾūlāʾika yusāriʿūna fī l-khayrātِ wa hum lahā sābiqūna', 'İşte onlar hayırlarda yarışanlardır ve hayırlarda öne geçenlerdir.'),
(23, 62, 18, 346, 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَلَدَيْنَا كِتَٰبٌ يَنطِقُ بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'wa-lā nukallifu nafsan ʾillā wusʿahā wa-ladaynā kitābun yanṭiqu bi-l-ḥaqqi wa-hum lā yuẓlamūn', 'Biz hiç kimseyi gücünün yeteceğinden başkasıyla sorumlu tutmayız. Nezdimizde hakkı söyleyen bir kitap vardır ve onlar haksızlığa uğratılmazlar.'),
(23, 63, 18, 346, 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ', 'bal qulūbihim fī ġamratim min hāḏā wa lahum aʿmālun min dūni ḏālika hum lahā ʿāmilūn', 'Hayır, onların kalpleri bundan (bu hakikatten) bir gaflet içindedir. Dahası, onların bundan başka yapageldikleri (ve yapacakları) işleri de vardır.'),
(23, 64, 18, 346, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', 'ḥattā ʾiḏā ʾaḵaḏnā mutrafīhim bil-ʿaḏābi ʾiḏā hum yajʾarūn', 'Nihayet onlardan refah içinde olanları azapla yakaladığımızda, hemen figan etmeye başlarlar.'),
(23, 65, 18, 346, 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 'lā tajʾarū al-yawm ʾinnakum minnā lā tunṣarūn', 'Bugün (boşuna) feryat etmeyin! Çünkü bizden (yardım görüp) kurtarılacak değilsiniz.'),
(23, 66, 18, 346, 'قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', 'qad kānat ʾāyātī tutlā ʿalaykum fakuntum ʿalā ʾaʿqābikim tanikisūn', 'Andolsun, size ayetlerim okunurdu da sizler topuklarınızın üzerine gerisin geri dönüyordunuz.'),
(23, 67, 18, 346, 'مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًا تَهْجُرُونَ', 'mustakbirîne bihî sāmiran tahcurûn', 'Onu (Kur''an''ı) hor görerek toplanıp geceleyin (boş konuşmalarla) sohbet ederdiniz.'),
(23, 68, 18, 346, 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', 'ʾafalam yudabbirū al-qawla ʾam jāʾahum mā lam yaʾti ʾābāʾahumu al-ʾawwalīna', 'Yoksa onlar, (sana vahyolunan) sözü (Kur''an''ı) hiç düşünmediler mi? Yoksa onlara, atalarına gelmemiş bir şey mi geldi?'),
(23, 69, 18, 346, 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', 'ʾam lam yaʿrifū rasūlahum fa-hum lahū munkiūna', 'Yoksa peygamberlerini tanımadılar da onun için mi inkâr ediyorlar?'),
(23, 70, 18, 346, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ', 'am yaqūlūna bihi jinnah bal jāʾahum bil-ḥaqqi wa ʾaktharuhum lil-ḥaqqi kārīhūn', 'Yoksa onlar, "O''nda bir delilik mi var?" diyorlar. Hayır, o onlara hakkı getirdi; fakat onlardan çoğu haktan hoşlanmıyorlar.'),
(23, 71, 18, 346, 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', 'wa-lawi-ttabaʿa-l-ḥaqqu ahwāʾahum la-fasadati-s-samāwātu wa-l-arḍu wa-man fīhinna bal ataynāhum bi-dhikrihim fa-hum ʿan dhikrihim muʿriḍūna', 'Eğer hak, onların arzularına uysaydı, kesinlikle gökler ve yer ve bunlarda bulunan her şey fesada uğrardı. Hayır, biz onlara şanlarını (Kur''an''ı) getirdik, fakat onlar kendi şanlarından (Kur''an''dan) yüz çeviriyorlar.'),
(23, 72, 18, 346, 'أَمْ تَسْـَٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'am tasʾaluhum kharjan fakharāju rabbika khayrun wahuwa khayru ʾr-rāziqīn', 'Yoksa onlardan bir ücret mi istiyorsun? Rabbinin verdiği rızık daha hayırlıdır. O, rızık verenlerin en hayırlısıdır.'),
(23, 73, 18, 346, 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa-ʾinnaka latadʿūhum ʾilā ṣirāṭin mustaqīm', 'Şüphesiz sen onları dosdoğru bir yola çağırıyorsun.'),
(23, 74, 18, 346, 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', 'waʾinna alladhīna lā yuʾminūna bil-ʾākhirati ʿani ṣ-ṣirāṭi lanākibūna', 'Şüphesiz âhirete inanmayanlar dosdoğru yoldan sapmışlardır.'),
(23, 75, 18, 347, 'وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا۟ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'Ve lev rahımnâhum ve keşefnâ mâ bihim min durrin leleccû fî tuğyânihim ya''mehûn', 'Eğer onlara merhamet etseydik ve başlarındaki sıkıntıyı giderseydik, yine de azgınlıkları içinde bocalayıp dururlardı.'),
(23, 76, 18, 347, 'وَلَقَدْ أَخَذْنَٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', 'Ve lekad eḣażnâhum bil’ażâbi femâ-stekânû lirabbihim vemâ yeteḍarra’ûn', 'Andolsun ki onları azapla yakaladık da yine Rablerine boyun eğmediler ve yalvarıp yakarmadılar.'),
(23, 77, 18, 347, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', 'ḥattā iḏā fataḥnā ʿalayhim bāban ḏā ʿaḏābin šadīdin iḏā hum fīhi mublisūn', 'Nihayet üzerlerine şiddetli azap kapısını açtığımızda, birdenbire onların bütün ümitleri kesilir.'),
(23, 78, 18, 347, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'wa huwa alladhī ʾanshaʾa lakumu s-samʿa wa-l-ʾabṣāra wa-l-ʾafʾidata qalīlan mā tashkurūna', 'Ve O, sizin için kulakları, gözleri ve gönülleri yaratan O''dur. Ne az şükrediyorsunuz!'),
(23, 79, 18, 347, 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'wa huwa alladhī dharaʾakum fī l-arḍi wa ilayhi tuḥsharūna', 'Ve O, sizi yeryüzünde türetip var edendir ve siz O''na toplanacaksınız.'),
(23, 80, 18, 347, 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَٰفُ ٱلَّيْلِ وَٱلنَّهَارِ أَفَلَا تَعْقِلُونَ', 'wa huwa alladhī yuḥyī wa yumītu wa lahu ikhtilāfu allayli wa nnahāri afalā taʿqilūna', 'O, yaşatan ve öldüren O''dur. Gece ile gündüzün değişmesi de O''nadır. Hâlâ akıl erdiremiyor musunuz?'),
(23, 81, 18, 347, 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', 'bal qālū mithla mā qāla l-awwalūn', 'Hayır, dediler, onların dedikleri gibi.'),
(23, 82, 18, 347, 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'qālū ʾaʾiḏā mitnā wa-kunnā turāban wa-ʿiẓāman ʾaʾinnanā la-mabʿūṯūn', 'Dediler ki: "Biz kemik olup toprak haline geldiğimizde mi, gerçekten biz mi yeniden diriltilecekmişiz?"'),
(23, 83, 18, 347, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'Lekad vuʿidnâ nahnu ve âbâʾunâ hâẕâ min kablu İn hâẕâ illâ esâṭîru-l-evvelîn', 'Andolsun ki, bu bize de daha önce atalarımıza da vaat edilmişti. Bu, öncekilerin masallarından başka bir şey değildir.'),
(23, 84, 18, 347, 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 'qul limani l-arḍu wa-man fīhā in kuntum taʿlamūn', 'De ki: "Eğer biliyorsanız, yer ve onun içindekiler kime aittir?"'),
(23, 85, 18, 347, 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَذَكَّرُونَ', 'sayqūlūna lillāhi qul aflā tadkkarūna', 'Onlar diyecekler ki: "Allah''ındır." De ki: "Hiç düşünmez misiniz?"'),
(23, 86, 18, 347, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'qul man rabbus-samāwātis-sabʿi wa rabbul-ʿarshil-ʿaẓīm', 'De ki: "Yedi göğün Rabbi ve yüce Arş''ın Rabbi kimdir?"'),
(23, 87, 18, 347, 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَتَّقُونَ', 'sayeqūlūna lillāh qul afalā tattaqūn', 'Onlar: ''Allah'' diyecekler. De ki: ''O halde Allah''tan korkmaz mısınız?'''),
(23, 88, 18, 347, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 'qul man biyadihii malakūtu kulli shaiʾin wa huwa yujīru walā yujāru ʿalayhi in kuntum taʿlamūn', 'De ki: "Her şeyin melekûtu (mülkü ve saltanatı) kimin elinde bulunan ve O''nun himaye edip kimsenin himaye edemediği kimdir? Eğer biliyorsanız (söyleyin)."'),
(23, 89, 18, 347, 'سَيَقُولُونَ لِلَّهِ قُلْ فَأَنَّىٰ تُسْحَرُونَ', 'sa-yaqūlūna li-llāh qul fa-annā tusḥarūn', 'Onlar: "Allah''ındır" diyecekler. De ki: "Öyleyse nasıl oluyorda büyüleniyorsunuz?"'),
(23, 90, 18, 348, 'بَلْ أَتَيْنَٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ', 'bal ataynāhum bil-ḥaqqi wa-innahum lākādhibūn', 'Hayır, onlara hakkı getirdik ve onlar gerçekten yalancıdırlar.'),
(23, 91, 18, 348, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'mā-ttakhaḏa-llāhu min waladin wa-mā kāna maʿahu min ilāhin iḏan laḏahaba kullu ilāhi-m bimā ḫalaqa wa-laʿalā baʿḍuhum ʿalā baʿḍin subḥāna-llāhi ʿammā yaṣifūna', 'Allah çocuk edinmemiştir ve O''nunla beraber başka hiçbir ilah da yoktur. (Eğer olsaydı) O zaman her bir ilah yarattığı şeyi (tek başına bırakıp) kendi başına giderdi ve mutlaka onlardan biri diğerine üstün gelirdi. Allah, onların vasfettiklerinden münezzehtir.'),
(23, 92, 18, 348, 'عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'ʿālimi l-ghaybi wa-sh-shahādati fataʿālā ʿammā yushrikūn', 'O, gaybı ve görüleni bilendir. Onların ortak koştuklarından yücedir.'),
(23, 93, 18, 348, 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', 'qul rabbi immā turiyanī mā yūʿadūn', 'De ki: Rabbim! Eğer onlara vaad olunanı (azabı) bana mutlaka göstereceksen,'),
(23, 94, 18, 348, 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'Rabbī falā tajʿalnī fī l-qawmi ẓ-ẓālimīn', 'Rabbim! Beni zalimler topluluğu içinde bulundurma!'),
(23, 95, 18, 348, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ', 'waʾinnā ʿalā ʾan nuriyaka mā naʿiduhum laqādirūn', 'Onlara vaadettiğimiz azabı sana göstermeye bizim gücümüz yeter.'),
(23, 96, 18, 348, 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', 'udfaʿ billatī hiya ʾaḥsanu s-sayyiʾata naḥnu ʾaʿlamu bimā yaṣifūna', 'Kötülüğü en güzel olanla sav. Biz onların yakıştırmakta olduklarını daha iyi bilmekteyiz.'),
(23, 97, 18, 348, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 'wa-qul rabbi aʿūżu bika min hamazāti sh-shayāṭīn', 'Ve de ki: Rabbim! Senden şeytanların vesveselerinden Sana sığınırım.'),
(23, 98, 18, 348, 'وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ', 'wa ʾaʿūḏu bika rabbī ʾan yaḥḍurūn', 'Ve Rabbim! Sığınırım Sana onların bana gelmesinden.'),
(23, 99, 18, 348, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', 'ḥattā ʾiḏā jāʾa ʾaḥadahumu l-mawtu qāla rabbi ʾirjiʿūn', 'Nihayet onlardan birine ölüm geldiği zaman, der ki: "Rabbim! Beni dünyaya geri gönderin."'),
(23, 100, 18, 348, 'لَعَلِّىٓ أَعْمَلُ صَٰلِحًا فِيمَا تَرَكْتُ كَلَّآ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'laʿallī ʾaʿmalu ṣāliḥan fīmā taraktu kallā ʾinnahā kalimatun huwa qāʾiluhā wa-min warāʾihim barzakhun ʾilā yawmi yubʿathūn', 'Belki iyi bir amel işlerim bıraktığım şeyden dolayı. Hayır! Bu, onun söylediği bir sözden ibarettir. Onların önlerinde, tekrar dirilecekleri güne kadar bir berzah (engel) vardır.'),
(23, 101, 18, 348, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَآءَلُونَ', 'fa-ʾidhā nufikha fī ṣ-ṣūri fa-lā ʾansāba baynahum yawmaʾiḏin wa-lā yatasaʾalūn', 'Sur''a üflendiği zaman, artık aralarında o gün ne soy-sop (bağı) vardır, ne de birbirlerine soru sorabilirler.'),
(23, 102, 18, 348, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'fe-men thaqulat mawāzīnuhu fa-ʾulāʾika humu l-mufliḥūn', 'Mizânları (sevapları) ağır gelenler var ya, işte onlar kurtuluşa erenlerdir.'),
(23, 103, 18, 348, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فِى جَهَنَّمَ خَٰلِدُونَ', 'wa-man khaffat mawāzīnuhu fa-ʾulāʾika alladhīna khasirū ʾanfusahum fī Jahannama khālidūn', 'Kimlerin tartıları hafif gelirse, işte onlar kendilerini ziyana uğratanlardır; cehennemde ebedî kalıcıdırlar.'),
(23, 104, 18, 348, 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ', 'talfaḥu wujūhahumu n-nāru wa hum fīhā kāliḥūn', 'Ateş onların yüzlerini yakar ve onlar orada (acıdan) yüzleri buruşuk kalırlar.'),
(23, 105, 18, 349, 'أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', 'ʾa-lam takun ʾāyātī tutlā ʿalaykum fa-kuntum bihā tukaḏḏibūn', 'Ayetlerim size okunurdu da siz onları yalan mı sayardınız?'),
(23, 106, 18, 349, 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَآلِّينَ', 'qālū rabbanā ghalabat ʿalaynā shiʾwatunā wa-kunnā qawman ḍāllīn', 'Onlar şöyle derler: "Rabbimiz! Bizi azgınlığımız (bedbahtlığımız) alt etti ve biz azmış bir topluluk idik."'),
(23, 107, 18, 349, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ', 'Rabbanā akhrijnā minhā Fa-in ʿudnā fa-innanā ẓālimūn', 'Ey Rabbimiz! Bizi buradan çıkar. Eğer (bundan sonra yine küfre) dönersek, o takdirde biz gerçekten zalimleriz.'),
(23, 108, 18, 349, 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', 'qāla ʾikhsaʾū fīhā walā tukallimūni', 'Allah şöyle buyurur: "Orada alçaldıkça alçalın ve bana bir söz söylemeyin!"'),
(23, 109, 18, 349, 'إِنَّهُۥ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'ʾinnahu kāna farīqun min ʿibādī yaqūlūna rabbana ʾāmannā fāḡfir lanā wārḥamnā waʾanta ḵayru ʾr-rāḥimīn', 'Onlar ki, "Rabbimiz! İman ettik. Artık bizi bağışla ve bize merhamet et; sen merhamet edenlerin en iyisisin!" diyecekler.'),
(23, 110, 18, 349, 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', 'fāttakhaḏtūmuhum siḫriyyan ḥattā ʾansawkum ḏikrī wa-kuntum minhum taḍḥakūn', 'Onları alay konusu edindiniz, ta ki bu durum sizi beni anmaktan alıkoydu ve siz onlara gülüp eğleniyordunuz.'),
(23, 111, 18, 349, 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', 'innī jazaytuhumu l-yawma bimā ṣabarū annahum humu l-fāʾizūn', 'Şüphesiz ben, sabretmelerinden dolayı onları bugün mükâfatlandırdım. Gerçekten onlar, muradına erenlerin ta kendileridir.'),
(23, 112, 18, 349, 'قَٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', 'qāla kam labiṯtum fī l-arḍi ʿadada sinīn', 'Dedi ki: "Yeryüzünde kaç yıl kaldınız (sayarak)?"'),
(23, 113, 18, 349, 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَسْـَٔلِ ٱلْعَآدِّينَ', 'qālū labithnā yawman aw baʿḍa yawmin fasʾali l-ʿāddīna', 'Dediler ki: “Bir gün yahut bir günden daha az bir süre kaldık. Saymayı bilenlere sor!”'),
(23, 114, 18, 349, 'قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', 'qāla in labiṯtum illā qalīlan law annakum kuntum taʿlamūn', 'Dedi ki: "Eğer bilirmiş olsaydınız, siz az bir zaman kalmış olursunuz."'),
(23, 115, 18, 349, 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', 'ʾafahasibtum ʾannama ḫalaqnakum ʿabaṯan wa ʾannakum ʾilayna la turjaʿūn', 'Sizi boşuna yarattığımızı ve bize döndürülmeyeceğinizi mi sandınız?'),
(23, 116, 18, 349, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', 'Fa taʿālā Allāhu al-maliku al-ḥaqqu Lā ilāha illā huwa Rabbu al-ʿarshi al-karīmi', 'Gerçek Melik ve Hak olan Allah, yücelerin yücesidir. O''ndan başka ilah yoktur. O, Arş-ı Kerim''in Rabbidir.'),
(23, 117, 18, 349, 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 've men yedʿu maʿa llāhi ilāhan ʾākhara lā burhāna lahu bihi fa-ʾinnamā ḥisābuhu ʿinda rabbihi ʾinnahu lā yufliḥu l-kāfirūn', 'Kim Allah ile beraber başka bir ilâha taparsa, ki bu hususta hiçbir delili de yoksa, o takdirde onun hesabı ancak Rabbi katındadır. Şüphesiz ki kâfirler kurtuluşa eremezler.'),
(23, 118, 18, 349, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'wa-qul rabbi-ghfir warḥam wa-anta khayru-r-rāḥimīn', 'Ve de ki: Rabbim! Bağışla ve merhamet et! Sen merhamet edenlerin en iyisisin!'),
(24, 1, 18, 350, 'سُورَةٌ أَنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتٍۭ بَيِّنَٰتٍ لَّعَلَّكُمْ تَذَكَّرُونَ', 'sūratun anzalnāhā wa faraḍnāhā wa anzalnā fīhā ʾāyātin bayyinātin laʿallakum tadhakkarūn', 'Bu, sizin için indirdiğimiz ve farz kıldığımız mübarek bir suredir. Umulur ki, öğüt alırsınız diye onda apaçık ayetler indirdik.'),
(24, 2, 18, 350, 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ ٱلْمُؤْمِنِينَ', 'Ez-zāniyatu vez-zānī, fajlidū kulla wāḥidin minhumā mi''ata jaldah. Wa lā ta''khużkum bihimā ra''fatun fī dīni Allāh. In kuntum tu''minūna billāhi wal-yawmi l-ʾākhir. Wa-lyashhad ʿaḏābahumā ṭā''ifatun min al-mu''minīn.', 'Zina eden kadın ve zina eden erkek, ikisinden her birine yüz değnek vurun. Eğer Allah''a ve ahiret gününe inanıyorsanız, Allah''ın dininde onlara merhamet etme hususunda bir gevşeklik göstermeyin. Ve onların cezalandırılmasına mü''minlerden bir topluluk da şahit olsun.'),
(24, 3, 18, 350, 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', 'Azzānī lā yankiḥu illā zāniyatan aw muşrikatan Vazzāniyatu lā yankiḥuhā illā zānin aw muşrikun Wa ḥurrima dhālika ʿalā l-muʾminīn', 'Zina eden erkek, zina eden veya Allah''a ortak koşan kadından başkasıyla evlenmez. Zina eden kadın da, zina eden veya Allah''a ortak koşan erkekten başkasıyla evlenmez. Bu, müminlere haram kılınmıştır.'),
(24, 4, 18, 350, 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا۟ لَهُمْ شَهَٰدَةً أَبَدًا وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'wa-lladhīna yarmūna l-muḥṣanāti thumma lam yaʾtū bi-arbaʿati shuhadāʾa fa-jladūhum thamānīna jaldatan wa-lā taqbalū lahum shahādatan ʾabadan wa-ʾulāʾika humu l-fāsiqūna', 'Namuslu kadınlara (iffetli olduklarını ispat edemeden) zina isnadında bulunup da, sonra dörd (veya daha fazla) şahit getiremeyenler, işte onlar seksen değnek (dayak) ile cezalandırılırlar ve onların şahitlikleri ebediyyen kabul edilmez. Onlar fasıkların ta kendileridir.'),
(24, 5, 18, 350, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'illa alladhīna tābū min baʿdi dhālika waʾaṣlaḥū faʾinna Allāha ghafūrun raḥīmun', 'Ancak bundan sonra tevbe eden ve durumlarını düzeltenler başka. Şüphesiz Allah, çok bağışlayıcıdır, çok merhamet edicidir.'),
(24, 6, 18, 350, 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَٰدَٰتٍۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 'wa-lladhīna yarmūna azwājahum wa-lam yakun lahum shuhadāʾu illā anfusuhum fa-shahādatu aḥadihim arbaʿu shahādātin bi-llāhi ʾinnahuu la-mina ṣ-ṣādiqīn', 'Eşlerini (zina ile) itham edip de kendilerinden başka şahitleri olmayanlar, işte onlardan her birinin şahitliği, Allah''a dört defa yemin ederek: ''Şüphesiz ki o, doğru söyleyenlerdendir'' demesidir.'),
(24, 7, 18, 350, 'وَٱلْخَٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَٰذِبِينَ', 'wa-l-khāmisatu anna laʿnata Allāhi ʿalayhi in kāna mina l-kādhibīn', 'Beşincisi de, eğer (kocası) yalancılardan ise, Allah''ın lanetinin kendi üzerine olmasını (söylemesidir).'),
(24, 8, 18, 350, 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتٍۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلْكَٰذِبِينَ', 'wayadraʾu ʿanhā l-ʿadhāba an tash-hada ʾarbaʿa shahādātin bi-llāhi ʾinnahu la-mina l-kādhibīna', 'Kadın tarafından cezayı kaldıracak olan şey, dört defa Allah''a yemin ederek onun yalancılardan olduğuna şehadet etmesidir.'),
(24, 9, 18, 350, 'وَٱلْخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ', 'wa-l-khāmisata anna ghaḍaba ʾllāhi ʿalayhā ʾin kāna mina ṣ-ṣādiqīn', 'Beşincisi de, eğer kocası doğru söyleyenlerden ise, Allah''ın gazabının kendi üzerine olmasını (dilemesidir).'),
(24, 10, 18, 350, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', 'wa lawlā faḍlu llāhi ʿalaykum wa raḥmatuhū wa anna llāha tawwābun ḥakīm', 'Eğer Allah''ın size fazlı ve rahmeti olmasaydı ve Allah, tevbeleri kabul eden, hüküm ve hikmet sahibi olmasaydı (haliniz nice olurdu).'),
(24, 11, 18, 351, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌ مِّنكُمْ لَا تَحْسَبُوهُ شَرًّا لَّكُم بَلْ هُوَ خَيْرٌ لَّكُمْ لِكُلِّ ٱمْرِئٍ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌ', 'ʾinna lladhīna jāʾū bil-ʾifki ʿuṣbatun minkum lā taḥsabūhu sharran lakum bal huwa khayrun lakum likulli mriʾin minhum mā ʾiktasaba min al-ʾithmi wa lladhī tawallā kibriyahu minhum lahu ʿadhābun ʿaẓīmun', 'Şüphesiz ki, (Hz. Âişe hakkında) yalan uyduranlar sizden bir topluluktur. Onu (bu olayı) sizin için bir şer (kötülük) sanmayın; aksine o sizin için bir hayırdır. Onlardan her birine, kazandığı günah nispetinde (ceza) vardır. Onlardan (bu iftiranın) büyüğünü üzerine alana gelince, onun için de büyük bir azap vardır.'),
(24, 12, 18, 351, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بِأَنفُسِهِمْ خَيْرًا وَقَالُوا۟ هَٰذَآ إِفْكٌ مُّبِينٌ', 'lawlā iḏ samiʿtumūhu ẓanna l-muʾminūna wa-l-muʾminātu bi-ʾanfusihim ḫayran wa qālū hāḏā ʾifkun mubīnun', 'Onu (iftirayı) işittiğiniz zaman, iman eden erkekler ve iman eden kadınlar (neden) kendi vicdanları hakkında iyi zanda bulunmadılar da "Bu, apaçık bir iftiradır" demediler mi?'),
(24, 13, 18, 351, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَٰذِبُونَ', 'lawlā jāū ʿalayhi bi-arbaʿati shuhadāʾa fa-ʾidh lam yaʾtū bi-shuhadāʾi fa-ʾulāʾika ʿinda Allāhi humu l-kādhibūna', 'Onu (bu iftirayı) dört şahit getirmeyenler, işte onlar Allah katında yalancıların ta kendileridir.'),
(24, 14, 18, 351, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', 'wa lawlā faḍlu llāhi ʿalaykum wa raḥmatuhū fī d-dunyā wa l-ʾākhirati lamassakum fī mā ʾafaḍtum fīhi ʿadhābun ʿaẓīmun', 'Eğer dünya ve ahirette Allah''ın size olan fazlı ve rahmeti olmasaydı, içine daldığınız o şeyden dolayı size mutlaka büyük bir azap dokunurdu.'),
(24, 15, 18, 351, 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَتَحْسَبُونَهُۥ هَيِّنًا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌ', 'idh talaqqawnahuu bi-alsinatikum wa taqūlūna bi-afwāhikum mā laysa lakum bihii ʿilmun wa taḥsabūnahuu hayyinan wa huwa ʿinda llāhi ʿaẓīmun', 'Hani siz onu dilinize dolamış, ağızlarınızla da hakkında hiçbir bilginiz olmayan şeyi söylemiştiniz. Bunu önemsiz sanıyordunuz, oysa Allah katında çok büyük (bir suç) idi.'),
(24, 16, 18, 351, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمٌ', 'wa lawlā idh samiʿtumūhu qultum mā yakūnu lanā an natakallama bihādhā subḥānak hādhā buhtānun ʿaẓīm', 'Onu işittiğiniz zaman, "Bu konuda konuşmamız bize yakışmaz. Sübhanakesin! Bu, büyük bir iftiradır" demeliydiniz.'),
(24, 17, 18, 351, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', 'yaʿiẓukumullāhu an taʿūdū limithlihī abadan in kuntum muʾminīn', 'Allah size öğüt veriyor: Eğer inanmışsanız, böylesi bir şeye bir daha asla dönmeyin.'),
(24, 18, 18, 351, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'wa yubayyinu allāhu lakumu l-ʾāyāti wa allāhu ʿalīmun ḥakīmun', 'Allah size ayetleri açıklar. Allah, her şeyi bilen, hikmet sahibi olandır.'),
(24, 19, 18, 351, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'ʾinna lladhīna yuḥibbūna ʾan tashīʿa l-fāḥishatu fī lladhīna ʾāmanū lahum ʿadhābun ʾalīmun fī d-dunyā wa-l-ʾākhirati wa-llāhu yaʿlamu wa-ʾantum lā taʿlamūna', 'Şüphesiz, iman edenler içinde çirkin şeylerin yayılmasını arzu edenler için dünyada da ahirette de büyük azap vardır. Allah bilir, siz bilmezsiniz.'),
(24, 20, 18, 351, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌ رَّحِيمٌ', 'wa lawlā faḍlu llāhi ʿalaykum wa raḥmatuhū wa anna llāha raʾūfun raḥīm', 'Eğer üzerinizde Allah''ın lütfu ve merhameti olmasaydı ve Allah''ın çok esirgeyici, çok merhametli olması (durumu) olmasaydı, (haliniz nice olurdu).'),
(24, 21, 18, 352, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'yā ayyuhā lladhīna āmānū lā tattabiʿū khuṭuwāti sh-shayṭāni wa man yattabiʿ khuṭuwāti sh-shayṭāni fa-innahu yaʾmuru bi-l-faḥshāʾi wa-l-munkari wa lawlā faḍlu l-lāhi ʿalaykum wa-raḥmatuhū mā zakā minkum min aḥadin abadan wa-lākinna l-lāha yuzakkī man yashāʾu wa-l-lāhu samīʿun ʿalīmun', 'Ey iman edenler! Şeytanın adımlarını takip etmeyin. Kim şeytanın adımlarını takip ederse, bilsin ki o, fuhuş ve münkeri emreder. Eğer üzerinizde Allah''ın lütuf ve merhameti olmasaydı, sizden hiçbir kimse asla temize çıkamazdı. Fakat Allah dilediğini temizler. Allah, hakkıyla işitendir, bilendir.'),
(24, 22, 18, 352, 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَٰكِينَ وَٱلْمُهَٰجِرِينَ فِى سَبِيلِ ٱللَّهِ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'wa lā yaʾtalī ʾulū al-faḍli minkum wa-s-saʿati ʾan yuʾtū ʾulī al-qurbā wa-l-masākīna wa-l-muhājirīna fī sabīli Allāhi wa-l-yaʿfū wa-l-yaṣfaḥū ʾalā tuḥibbūna ʾan yagfira Allāhu lakum wa-Allāhu ghafūrun raḥīmun', 'İçinizden faziletli ve servet sahibi olanlar, akrabalara, yoksullara ve Allah yolunda hicret edenlere vermekten (vermemeye) yemin etmesinler; affetsinler ve hoş görsünler. Allah''ın sizi bağışlamasını istemez misiniz? Allah çok bağışlayandır, çok merhamet edendir.'),
(24, 23, 18, 352, 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ٱلْغَٰفِلَٰتِ ٱلْمُؤْمِنَٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'ʾinna lladhīna yarmūna l-muḥṣanāti l-ghāfilāti l-muʾmināti luʿinū fī d-dunyā wa-l-ʾākhirati wa lahum ʿadhābun ʿaẓīmun', 'Namuslu, (hayâsızlık)dan habersiz, (yaratılıştan) imanlı kadınlara zinâ isnâd edenler, dünyâda ve âhiretde lânetlenmişlerdir. Onlar için büyük bir azâb da vardır.'),
(24, 24, 18, 352, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'yawma tash-hadu ʿalayhim ʾalsinatuhum wa-ʾaydīhim wa-ʾarjuluhum bimā kānū yāʿmalūn', 'O gün, onların dilleri, elleri ve ayakları, yaptıkları şeyler yüzünden aleyhlerine şahitlik edecektir.'),
(24, 25, 18, 352, 'يَوْمَئِذٍ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', 'yawmaʾiḏin yuwaffīhimu ʾllāhu dīnahumu l-ḥaqqa wayaʿlamūna ʾanna ʾllāha huwa l-ḥaqqu l-mubīnu', 'O gün Allah onlara hak ettikleri cezalarını tastamam verir ve onların, Allah''ın apaçık hak olduğunu bildikleri zaman.'),
(24, 26, 18, 352, 'ٱلْخَبِيثَٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَٰتِ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِ أُو۟لَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'al-khabīthātu lil-khabīthīna wa-al-khabīthūna lil-khabīthāti wa-aṭ-ṭayyibātu liṭ-ṭayyibīna wa-aṭ-ṭayyibūna liṭ-ṭayyibāti ʾulāʾika mubarraʾūna mimmā yaqūlūna lahum maghfiratun wa-rizqun karīmun', 'Kötü kadınlar kötü erkeklere, kötü erkekler de kötü kadınlara; temiz kadınlar temiz erkeklere, temiz erkekler de temiz kadınlara yaraşır. Bunlar, onların söylediklerinden uzaktırlar. Kendileri için bağışlanma ve cömertçe verilmiş bir rızık vardır.'),
(24, 27, 18, 352, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'yā ʾayyuhā lladhīna ʾāmanū lā tadkhulū buyūtan ghayra buyūtikum ḥattā tastaʾnisū wa tusallimū ʿalā ʾahlihā dhālikum khayrun lakum laʿallakum tadhakkarūn', 'Ey iman edenler! Kendi evlerinizden başka evlere, sahipleriyle tanışıp (izin almadan) girmeyin. Eğer düşünürseniz, bu sizin için daha hayırlıdır.'),
(24, 28, 18, 353, 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ هُوَ أَزْكَىٰ لَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', 'fa-in lam tacudū fīhā aḥadan falā tadḫulūhā ḥattā yuʾḏana lakum wa-in qīla lakumu rgicū faricū huwa azkā lakum wa-llāhu bimā tacmalūna ʿalīmun', 'Eğer orada kimseyi bulamazsanız, size izin verilinceye kadar oraya girmeyin. Eğer size "Geri dönün" denirse, hemen dönün. Bu sizin için daha temizdir. Allah yaptıklarınızı bilir.'),
(24, 29, 18, 353, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَٰعٌ لَّكُمْ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'laysa ʿalaykum junāḥun an tadkhulū buyūtan ġayra maskūnatin fīhā matāʿun lakum wallāhu yaʿlamu mā tubdūna wa mā taktūmūna', 'İçinde sizin için bir eşya (faydalanacak şeyler) bulunan meskûn olmayan evlere girmenizde size bir günah yoktur. Allah, açıkladıklarınızı da, gizlediklerinizi de bilir.'),
(24, 30, 18, 353, 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ذَٰلِكَ أَزْكَىٰ لَهُمْ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', 'qul lil-muʾminīna yaghuḍḍū min abṣārihim wa yaḥfaẓū furūjahum dhālika azkā lahum ʾinna Llāha khabīrum bimā yaṣnaʿūn', 'Mü''min erkeklere söyle: Gözlerini haramdan sakınsınlar ve iffetlerini korusunlar. Bu, onların daha temiz kalmasını sağlar. Şüphesiz Allah, onların yapmakta olduklarından haberdardır.'),
(24, 31, 18, 353, 'وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', 'wa-qul lil-muʾmināti yagḍuḍna min abṣārihinna wa-yaḥfaẓna furūjahunna wa-lā yubdīna zīnatahunna illā mā ẓahara min-hā wal-yaḍribna bi-khumurihinna ʿalā juyūbihinna wa-lā yubdīna zīnatahunna illā li-buʿūlatihinna aw ābāʾihinna aw ābāʾi buʿūlatihinna aw abnāʾihinna aw abnāʾi buʿūlatihinna aw ikhwānihinna aw banī ikhwānihinna aw banī akhawātihinna aw nisāʾihinna aw mā malakat aymānuhunna awi al-tābiʿīna ghayri ʾūlī al-ʾirbati mina al-rijāli awi al-ṭifli alladhīna lam yaẓharū ʿalā ʿawrāti al-nisāʾi wa-lā yaḍribna bi-arjulihinna li-yuʿlama mā yukhfīna min zīnatihinna wa-tūbū ʾilā Allāhi jamīʿan ʾayyuha al-muʾminūna laʿallakum tufliḥūna', 'Mümin kadınlara da söyle: Gözlerini haramdan sakınsınlar ve iffetlerini korusunlar. Zinetlerini açığa vurmasınlar; meğer ki bunlardan zahir olanı müstesna. Baş örtülerini yakalarının üzerine kadar salsınlar. Zinetlerini ise kocaları, yahut babaları, yahut kocalarının babaları, yahut kendi oğulları, yahut kocalarının oğulları, yahut kardeşleri, yahut kardeşlerinin oğulları, yahut kız kardeşlerinin oğulları, yahut kendi kadınları (diğer kadınlar), yahut sahipleri (köleleri), yahut erkeklikten kesilmiş hizmetçileri, yahut kadınların avret mahallerini henüz anlamayan çocukları müstesna (açığa vurmasınlar). Bir de gizledikleri zinetleri bilinsin diye ayaklarını (yere) vurmasınlar. Ey müminler topluluğu! Hepiniz Allah''a tevbe ediniz ki kurtuluşa eresiniz.'),
(24, 32, 18, 354, 'وَأَنكِحُوا۟ ٱلْأَيَٰمَىٰ مِنكُمْ وَٱلصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'wa-ankihū l-ayāmā min-kum wa-ṣ-ṣāliḥīna min ʿibādikum wa-imāʾikum in yakūnū fuqarāʾa yughnihimu llāhu min faḍlihī wa-llāhu wāsiʿun ʿalīm', 'Sizden bekâr olanları ve kölelerinizden, cariyelerinizden sâlih (iyi) olanları evlendirin. Eğer fakir iseler, Allah lütfundan onları zenginleştirir. Allah, (rahmetiyle) geniş olan, (her şeyi) bilen''dir.'),
(24, 33, 18, 354, 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ وَلَا تُكْرِهُوا۟ فَتَيَٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ', 'wa-l-yastaʿfifi l-ladhīna lā yajidūna nikāḥan ḥattā yughniyahumu l-lāhu min faḍlihī wa-lladhīna yabtughūna l-kitāba mimmā malakat aymānukum fa-kātibūhum in ʿalimtum fīhim khayran wa-ātūhum min māli l-lāhi lladhī ātākum wa-lā tukrihū fatayātikum ʿalā l-bigāʾi in aradna taḥaṣṣunan li-tabtaghū ʿaraḍa l-ḥayāti d-dunyā wa-man yukrihunn fa-inna l-lāha min baʿdi ikrāhihinna ghafūrun raḥīmun', 'İçinizden bekâr olup evlenmeye gücü yetmeyenler, Allah''ın lütfundan onları zenginleştirmesine kadar iffetli davransınlar. Cariyelerinizden hürriyet bedeli ödemek isteyenler olursa, onlara (anlaşma yapma imkânı) verin. Allah''ın size verdiği maldan onlara da verin. Dünya hayatının geçici menfaatini elde etmek için, cariyelerinizi fuhşa zorlamayın; eğer onlar (iffetli) kalmak isterlerse. Kim onları (fuhşa) zorlarsa, bilmelidir ki zorlamalarından sonra Allah (onları) affedici, esirgeyicidir.'),
(24, 34, 18, 354, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَمَثَلًا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ', 've lekad enzelnâ ileykum âyâtin mubeyyinâtin ve meselen mine-lleẕîne ḫalev min ḳablikum ve mev''iżaten lilmutteḳîn', 'Andolsun ki size apaçık ayetler, sizden önce gelip geçenlerden örnekler ve takva sahipleri için bir öğüt indirdik.'),
(24, 35, 18, 354, 'ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍ فِيهَا مِصْبَاحٌ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَٰرَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَىٰ نُورٍ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَٰلَ لِلنَّاسِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'Allāhu nūru s-semāwāti wa-l-ʾarḍi Mathalu nūrihī kamishkāwatin fīhā miṣbāḥun Al-miṣbāḥu fī zujājah Az-zujājah ka-ʾannahā kawkabun durriyyun Yūqadu min shajaratin mubārakatin zaytūnatin lā sharqiyyatin wa-lā gharbiyyatin Yakādu zaytu hā yuḍīʾu wa-law lam tamsas-hu nārun Nūrun ʿalā nūrin Yahdī Allāhu li-nūrihī man yashāʾu Wa yaḍribu Allāhu l-ʾamthāla li-nnāsi Wa-llāhu bi-kulli shayʾin ʿalīmun', 'Allah, göklerin ve yerin nurudur. O''nun nurunun misali, içinde kandil bulunan bir oyuk gibidir. O kandil bir cam içindedir. O cam, sanki inci gibi parlayan bir yıldızdır. Mübarek bir ağaçtan, ne doğuya ne de batıya ait zeytin ağacından tutuşturulur. Kendisine ateş değmese bile, yağı neredeyse ışık verecek hale gelmiştir. Nur üstüne nur. Allah dilediği kimseyi kendi nuruna iletir. Allah insanlara örnekler verir. Allah her şeyi bilendir.'),
(24, 36, 18, 354, 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْءَاصَالِ', 'fī buyūtin ʾadhina ʾallāhu ʾan turfaca wa yudh-kara fīhā ʾismuhū yusabbiḥu lahu fīhā bil-ghuduwwi wal-ʾāṣāli', 'Allah''ın, yükseltilmesine ve içlerinde adının anılmasına izin verdiği evlerde...'),
(24, 37, 18, 355, 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَٰرَةٌ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَٰرُ', 'ricālun lā tulhīhim tijāratun wa lā bayʿun ʿan dhikri Allāhi wa iqāmi ṣ-ṣalāti wa ītāʾi z-zakāti yakhāfūna yawman tataqallabu fīhi l-qulūbu wa l-ʾabṣāru', 'O adamlar ki, ne ticaret ne de alışveriş onları Allah''ı anmaktan, namazı dosdoğru kılmaktan ve zekâtı vermekten alıkoyar. Onlar, kalplerin ve gözlerin dehşetle döneceği günden korkarlar.'),
(24, 38, 18, 355, 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 'li-yajziyahumu llāhu aḥsana mā ʿamilū wa-yazīdahum min faḍlihī wa-llāhu yarzuqu man yashāʾu bi-ghayri ḥisābin', 'Allah''ın, yapmakta olduklarının en güzeliyle onlara karşılığını vermesi ve onlara lütfundan (daha da) artırması için (böyle yaparlar). Allah, dilediğini hesapsız rızıklandırır.'),
(24, 39, 18, 355, 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'wa-lladhīna kafarū aʿmāluhum kasarābin bīqīʿatin yaḥsabuhu ẓ-ẓamʾānu māʾan ḥattā ʾidhā jāʾahu lam yajidhu shayʾan wa-wajada llāha ʿindahu fa-waffāhu ḥisābahu wa-llāhu sarīʿu l-ḥisābi', 'İnkâr edenlere gelince, onların amelleri ıssız bir çöldeki seraba benzer. Susamış olan onu su sanır. Nihayet ona vardığında hiçbir şey bulamaz. (Bununla birlikte) Allah''ı yanında bulur; böylece Allah onun hesabını tam olarak öder. Allah, hesabı çabuk görendir.'),
(24, 40, 18, 355, 'أَوْ كَظُلُمَٰتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَىٰهُ مَوْجٌ مِّن فَوْقِهِۦ مَوْجٌ مِّن فَوْقِهِۦ سَحَابٌ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًا فَمَا لَهُۥ مِن نُّورٍ', 'aw kaẓulumātin fī baḥrin lujjiyyin yagshāhu mawjun min fawqihi mawjun min fawqihi saḥābun ẓulumātun baʿḍuhā fawqa baʿḍin iḏā ʾaḫraja yadasū lam yakad yarāhā wa man lam yajʿali ʾllāhu lahu nūran famā lahu min nūrin', 'Yahut (onların durumu) engin bir denizde olan karanlıklar gibidir. Onu dalgalar örtüyor, üstünde dalgalar var, üstünde de bulutlar var. Birbiri üstüne yığılmış karanlıklar! Elini çıkarsa, neredeyse onu göremeyecek. Allah''ın kendisine nur vermediği kimsenin nuru yoktur.'),
(24, 41, 18, 355, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٰٓفَّٰتٍ كُلٌّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'ʾalam tara ʾanna ʾallāha yusabbiḥu lahu man fī s-samāwāti wa-l-ʾarḍi wa-ṭ-ṭayru ṣāffātin kullun qad ʿalima ṣalātahu wa-tasbīḥahu wa-llāhu ʿalīmun bimā yafʿalūna', 'Görmedin mi ki, göklerde ve yerde olanlar ve saf saf uçan kuşlar, hep Allah''ı tesbih ederler. Hepsi kendi duasını ve tesbihini bilmiştir. Allah, onların yapmakta olduklarını bilendir.'),
(24, 42, 18, 355, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'wa li-llāhi mulku s-samāwāti wa-l-arḍi wa ilā llāhi l-maṣīru', 'Göklerin ve yerin mülkiyeti Allah''ındır. Ve dönüş yalnız Allah''adır.'),
(24, 43, 18, 355, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍ فِيهَا مِنۢ بَرَدٍ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَٰرِ', 'ʾalam tara ʾanna ʾallāha yuzjī saḥāban ṯumma yuʾallifu baynahu ṯumma yajʿaluhu rukāman fatarā l-wadqa yaḫruju min ḫilālihī wa yunazzilu mina s-samāʾi min ǧibālin fīhā min baradin fa yuṣību bihī man yašāʾu wa yaṣrifuhu ʿan man yašāʾu yakādu sanā barqihi yaḏhabu bi l-ʾabṣāri', 'Görmedin mi ki Allah, bulutları sevk eder, sonra onları aralarında birleştirir, sonra da üst üste yığar da sen de aralarından çıkan yağmuru görürsün. Gökten, içinde dolu taneleri bulunan dağlar gibi bulutlardan indirir de onu dilediği kimseye isabet ettirir, dilediği kimsenin de üzerinden savar. O''nun (o) şimşeğinin parıltısı ise neredeyse gözleri alıp götürecektir.'),
(24, 44, 18, 356, 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'yuqallibu l-lāhu l-layla wa-n-nahāra ʾinna fī dhālika la-ʿibrah-tan li-ʾulī l-ʾabṣār', 'Allah, gece ile gündüzü evirip çevirir. Şüphesiz bunda basiret sahipleri için elbette bir ibret vardır.'),
(24, 45, 18, 356, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wa-llāhu ḫalaqa kulla dābbatin min māʾin fa-minhum man yamšī ʿalā baṭnihi wa-minhum man yamšī ʿalā riǧlayni wa-minhum man yamšī ʿalā ʾarbaʿin yaḫluqu llāhu mā yašāʾu ʾinna llāha ʿalā kulli šayʾin qadīrun', 'Allah her canlıyı sudan yarattı. Onlardan kimi sırtüstü sürünür, kimi iki ayak üzerinde yürür, kimi de dört ayak üzerinde yürür. Allah dilediğini yaratır. Şüphesiz Allah her şeye hakkıyla gücü yetendir.'),
(24, 46, 18, 356, 'لَّقَدْ أَنزَلْنَآ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'leḳad enzelnâ âyâtim mübeyyinâtin vellâhü yehdî mey yeşâü ilâ ṣirâṭim müsteḳîm', 'Andolsun ki biz, apaçık ayetler indirdik. Allah, dilediğini doğru yola iletir.'),
(24, 47, 18, 356, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'wa-yaqūlūna ʾāmannā bi-llāhi wa-bi-r-rasūli wa-ʾaṭaʿnā thumma yatawallā farīqun min-hum min-baʿdi dhālika wa-mā ʾulāʾika bi-l-muʾminīna', 'Allah''a ve Resûl''e iman ettik ve itaat ettik derler. Sonra onlardan bir grup, bunun ardından yüz çevirir. Onlar inanmış kimseler değillerdir.'),
(24, 48, 18, 356, 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ', 'wa ʾiḏā duʿū ʾilā llāhi wa-rasūlihi liyahkuma baynahum ʾiḏā farīqun minhum muʿriḍūna', 'Onlar, aralarında hükmetmesi için Allah''a ve Resûlü''ne davet olunduklarında, bakarsın onlardan bir grup yüz çevirir.'),
(24, 49, 18, 356, 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', 'wa-ʾin yakun lahumu l-ḥaqqu yaʾtū ʾilayhi mudhʿinīn', 'Onların lehine hak ortaya çıktığında, ona boyun eğerek gelirler.'),
(24, 50, 18, 356, 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'ʾafī qulūbihim maraḍun ʾami irtābū ʾam yakhāfūna ʾan yaḥīfa ʾllāhu ʿalayhim wa-rasūluhū bal ʾūlāʾika humu ẓẓālimūna', 'Yoksa kalplerinde bir hastalık mı var, yoksa şüpheye mi düştüler, yahut Allah ve Resûlü''nün kendilerine haksızlık yapmasından mı korkuyorlar? Hayır, işte onlar zalimlerdir.'),
(24, 51, 18, 356, 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'innamā kāna qawla l-muʾminīna ʾidhā duʿū ʾilā llāhi wa-rasūlihi li-yaḥkuma baynahum ʾan yaqūlū samʿinā wa-ʾaṭaʿnā wa-ʾulāʾika humu l-mufliḥūn', 'Mü''minlerin, aralarında hükmetmesi için Allah''a ve Resûlü''ne davet olunduklarında, ''İşittik ve itaat ettik'' demelerinden başka sözleri yoktur. İşte onlar, kurtuluşa erenlerin ta kendileridir.'),
(24, 52, 18, 356, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'wa-man yuṭiʿi l-lāha wa-rasūlahū wa-yakhsha l-lāha wa-yattaqhi fa-ʾulāʾika humu l-fāʾizūn', 'Kim Allah''a ve Resûlü''ne itaat eder, Allah''tan gereğince korkar ve O''ndan sakınırsa, işte onlar başarıya erenlerin ta kendileridir.'),
(24, 53, 18, 356, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ قُل لَّا تُقْسِمُوا۟ طَاعَةٌ مَّعْرُوفَةٌ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'waʾaqsamū billāhi jahda ʾaymānihim laʾin ʾamartahum layakhrujunna qul lā tuqsimū ṭāʿatun maʿrūfatun ʾinna llāha khabīrun bimā taʿmalūna', 'Onlar, bütün güçleriyle Allah''a yemin ederek, ''Eğer kendilerine emredersek mutlaka (savaşa) çıkacaklarını'' söylemişlerdi. De ki: ''Yemin etmeyin! İtaat bilinen (güzel) bir itaattir. Şüphesiz Allah, yaptıklarınızdan haberdardır.'''),
(24, 54, 18, 357, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'qul ʾaṭīʿū ʾllāha wa-ʾaṭīʿū ʾr-rasūla fa-ʾin tawallaw fa-ʾinnamā ʿalayhi mā ḥummila wa-ʿalaykum mā ḥummiltum wa-ʾin tuṭīʿūhu tahtadū wa-mā ʿalā ʾr-rasūli ʾillā ʾl-balāġu ʾl-mubīnu', 'De ki: Allah’a itaat edin, Peygamber’e de itaat edin. Eğer yüz çevirirseniz, şunu bilin ki Peygamber’in sorumluluğu ona yüklenen (tebliğ görevi), sizin sorumluluğunuz da size yüklenen (emirleri yerine getirme)dir. Eğer ona itaat ederseniz doğru yolu bulmuş olursunuz. Peygamber’e düşen ise sadece apaçık tebliğdir.'),
(24, 55, 18, 357, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًٔا وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'Va''ada Allahu allazina amanu minkum wa ''amilu as-salihati layastakhlifannahum fi al-ardi kama astakhlafa allazina min qablihim walayumakkinanna lahum dinahumu allazi irtada lahum walayubaddilannahum min ba''di khawfihim amnan ya''budunani la yushrikuna bi shay''an waman kafara ba''da zalika fa''ula''ika humu al-fasiqun', 'Allah, sizden iman edip salih ameller işleyenlere vaat etti ki, kendilerinden öncekileri halife kıldığı gibi onları da yeryüzünde mutlaka halife kılacak, kendileri için razı olduğu dinlerini onlara sağlam bir şekilde yerleştirecek ve korkularının ardından onları güvenliğe çevirecektir. Bana kulluk edecekler, Bana hiçbir şeyi ortak koşmayacaklar. Kim bundan sonra inkâr ederse, işte onlar fasıkların ta kendileridir.'),
(24, 56, 18, 357, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 'wa aqīmū ṣ-ṣalāta wa ātū z-zakāta wa aṭīʿū r-rasūla laʿallakum turḥamūn', 'Namazı dosdoğru kılın, zekâtı verin ve Peygamber''e itaat edin ki merhamet olunasınız.'),
(24, 57, 18, 357, 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَأْوَىٰهُمُ ٱلنَّارُ وَلَبِئْسَ ٱلْمَصِيرُ', 'lā taḥsabanna alladhīna kafarū muʿjizīna fī l-arḍi wa maʾwāhumu n-nāru wa labiʾsa l-maṣīru', 'Kâfirlerin yeryüzünde (Allah''ı) aciz bırakacaklarını sanma. Onların varacakları yer mutlaka ateştir. Ne kötü bir dönüş yeridir!'),
(24, 58, 18, 357, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ثَلَٰثُ عَوْرَٰتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'yā ayyuhā l-ladhīna āmanū li-yastaʾdhin-kum-u l-ladhīna malakat aymānukum wa-l-ladhīna lam yablughū l-ḥuluma min-kum thalātha marrātin min qabli ṣalāti l-fajri wa-ḥīna taḍaʿūna thiyāba-kum mina ẓ-ẓahīrati wa-min baʿdi ṣalāti l-ʿishāʾi thalāthu ʿawrātin lakum laysa ʿalay-kum wa-lā ʿalay-him junāḥun baʿda-hunna ṭawwāfūna ʿalay-kum baʿḍu-kum ʿalā baʿḍin kadhālika yubayyinu l-lāhu la-kumu l-ʾāyāti wa-l-lāhu ʿalīmun ḥakīmun', 'Ey iman edenler! (Kendi evinizde) sizinle birlikte mülkiyetiniz altında bulunanlar (köleleriniz ve cariyeleriniz) ve içinizden henüz ergenlik çağına gelmemiş olanlar da (size hizmet etmek için) üç vakitte izin istesinler: Sabah namazından önce, öğleyin (öğle uykusu için) evden çıktığınızda ve yatsı namazından sonra. Bunlar sizin için üç mahrem vakittir. Bu vakitlerden sonra (birbirinize) girip çıkmanızda size de onlara da bir günah yoktur. Allah, size ayetleri böyle açıklıyor. Allah, her şeyi bilen, hüküm ve hikmet sahibidir.'),
(24, 59, 18, 358, 'وَإِذَا بَلَغَ ٱلْأَطْفَٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'wa ʾiḏā balaġa l-ʾaṭfālu minkumu l-ḥuluma falyastaʾḏinū kamā ʾistaʾḏana l-laḏīna min qablihim kaḏālika yubayyinu l-lāhu lakum ʾāyātihi wa-llāhu ʿalīmun ḥakīmun', 'Sizden olan çocuklar ergenlik çağına erdiklerinde, kendilerinden öncekilerin (izin istedikleri) gibi izin istesinler. Allah, ayetlerini size böyle açıklar. Allah, Alîm''dir, Hakîm''dir.'),
(24, 60, 18, 358, 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍ وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'wa-l-qawāʿidu mina n-nisāʾi l-latī lā yarjūna nikāḥan fa-laysa ʿalayhinna junāḥun an yaḍaʿna thiyābahunna ghayra mutabarrijātin bi-zīnatin wa-an yastaʿfifna khayrun lahunna wa-llāhu samīʿun ʿalīmun', 'Kadınlardan hayızdan kesilmiş (yaşlı) olup artık nikâh umudu kalmamış olanlar için, zinetlerini (göğüslerini vb.) göstermeksizin dış giysilerini çıkarmalarında bir vebal yoktur. Ancak iffetli davranmaları kendileri için daha hayırlıdır. Allah, hakkıyla işiten, kemaliyle bilendir.'),
(24, 61, 18, 358, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًا فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ ٱللَّهِ مُبَٰرَكَةً طَيِّبَةً كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 'laysa ʿalā l-ʾaʿmā ḥaracun walā ʿalā l-ʾaʿraji ḥaracun walā ʿalā l-marīḍi ḥaracun walā ʿalā ʾanfusikum ʾan taʾkulū min buyūtukum ʾaw buyūti ʾābāʾikum ʾaw buyūti ʾummahātikum ʾaw buyūti ʾikhwānikum ʾaw buyūti ʾakhawātikum ʾaw buyūti ʾaʿmāmikum ʾaw buyūti ʿammātikum ʾaw buyūti ʾakhwālikum ʾaw buyūti khālatikum ʾaw mā malaktum mafātiḥahū ʾaw ṣadīqikum laysa ʿalaykum junāḥun ʾan taʾkulū jamīʿan ʾaw ʾashtātan faʾiḏā dakhaltum buyūtan fasallimū ʿalā ʾanfusikum taḥiyyatan min ʿindi l-lāhi mubārakatan ṭayyibatan kaḏālika yubayyinullāhu lakumu l-ʾāyāti laʿallakum taʿqilūn', 'Kör üzerine bir zorluk yoktur, topal üzerine bir zorluk yoktur, hasta üzerine bir zorluk yoktur. Sizin de evlerinizden veya babalarınızın evlerinden veya analarınızın evlerinden veya erkek kardeşlerinizin evlerinden veya kız kardeşlerinizin evlerinden veya babalarınızın (amcalarının) evlerinden veya analarınızın (halalarının) evlerinden veya annelerinizin (teyzenizin) evlerinden veya babalarınızın (dayınızın) evlerinden veya (anahtarlarına) sahip olduğunuz (evlerden) veya dostlarınızın evlerinden yemenizde bir vebal yoktur. Hep birlikte veya ayrı ayrı yemeniz de sizin için bir günah değildir. Evlere girdiğiniz zaman birbirinize Allah katından mübarek ve hoş bir esenleme ile selam verin. İşte Allah, size ayetleri böyle açıklar ki, düşünüp akıl eresiniz.'),
(24, 62, 18, 359, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'innamā l-muʾminūna l-ladhīna ʾāmanū bi-llāhi wa-rasūlihī wa-ʾidhā kānū maʿahu ʿalā ʾamrin jāmiʿin lam yadhhabū ḥattā yastaʾdhinūhu ʾinna lladhīna yastaʾdhinūnaka ʾulāʾika lladhīna yuʾminūna bi-llāhi wa-rasūlihī fa-ʾidhā staʾdhanūka li-baʿḍi shaʾnihim fa-ʾadhan liman shiʾta minhum wa-staghfir lahumu l-lāha ʾinna l-lāha ghafūrun raḥīmun', 'Mü''minler ancak, Allah''a ve Resûlü''ne inanmış olanlar; onlar toplu bir iş üzere onunla birlikte oldukları zaman, ondan izin almadıkça gitmeyenlerdir. Şüphesiz senden izin isteyenler, işte onlar Allah''a ve Resûlü''ne inanmış olanlardır. Öyleyse senden, bazı işleri için izin istediklerinde, onlardan dilediğine izin ver ve onlara Allah''tan mağfiret dile. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir.'),
(24, 63, 18, 359, 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًا قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', 'lā tajʿalū duʿāʾa r-rasūli bayna kum ka-duʿāʾi baʿḍikum baʿḍan qad yaʿlamu llāhu l-ladhīna yatasallalūna minkum liwādhan fa-l-yaḥḏhari l-ladhīna yukhālifūna ʿan amrihī an tuṣībahum fitnatun aw yuṣībahum ʿadhābun alīmun', 'Resûl''ün çağrısını, içinizde birbirinizi çağırdığınız gibi sanmayın. İçinizden bir kısmınızın, gizlice sıvlıp çıktığını Allah bilmektedir. Bu emre aykırı davrananlar, başlarına bir belâ gelmesinden veya kendilerine çok elem verici bir azap isabet etmesinden sakınsınlar.'),
(24, 64, 18, 359, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 'ʾalā ʾinna li-llāhi mā fī s-samāwāti wa-l-ʾarḍi qad yaʿlamu mā ʾantum ʿalayhi wa-yawma yurjaʿūna ʾilayhi fa-yunabbiʾuhum bimā ʿamilū wa-llāhu bi-kulli shayin ʿalīmun', 'Göklerde ve yerde ne varsa hepsi şüphesiz Allah''ındır. O, sizin neyin üzerinde olduğunuzu bilir. Ve O''na döndürülecekleri gün, yaptıklarını onlara haber verecektir. Allah her şeyi bilir.'),
(25, 1, 18, 359, 'تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا', 'tabāraka alladhī nazzala l-furqāna ʿalā ʿabdihi līyakūna lil-ʿālamīna nadhīrā', 'Kullarına Furkan''ı indiren, alemlere bir uyarıcı olsun diye, mübarektir.'),
(25, 2, 18, 359, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍ فَقَدَّرَهُۥ تَقْدِيرًا', 'alladhī lahu mulku s-samāwāti wa-l-arḍi wa-lam yattakhidh waladan wa-lam yakun lahu sharīkun fī l-mulki wa-khalaqa kulla shayʾin fa-qaddarahu taqdīran', 'O, göklerin ve yerin mülkü/hükümranlığı Kendisine ait olandır. Çocuk edinmemiştir. Mülkte ortağı da yoktur. O, her şeyi yaratmış ve ona bir ölçü/kader belirlemiştir.'),
(25, 3, 18, 360, 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَوٰةً وَلَا نُشُورًا', 'wa-ttakhadhū min dūnihi ʾālihatan lā yakhluqūna shayʾan wa-hum yukhlaqūna wa-lā yamlikūna li-ʾanfusihim ḍar-ran wa-lā nafʿan wa-lā yamlikūna mawtan wa-lā ḥayā-tan wa-lā nushūran', 'Bununla birlikte, (onlar) Allah''tan başka ilahlar edindiler; oysa o ilahlar hiçbir şey yaratamazlar, tam tersine kendileri yaratılmaktadırlar. Onlar, kendilerine ne bir zarar ne de bir fayda sağlama gücüne sahip değillerdir. Ne ölüm ne de yaşam ne de yeniden diriltme gücüne de sahip değillerdir.'),
(25, 4, 18, 360, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ فَقَدْ جَآءُو ظُلْمًا وَزُورًا', 'waqāla alladhīna kafarū in hādhā illā ifkuniftarāhu wa aʿānahū ʿalayhi qawmun ākharūna falaqad jāʾū ẓulman wa zūrā', 'İnkâr edenler: "Bu, onun uydurduğu bir yalandan başka bir şey değildir. Başka bir topluluk da ona yardım etmiştir" dediler. Böylece gerçekten zulüm ve iftira ile geldiler.'),
(25, 5, 18, 360, 'وَقَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا', 'wa qālū ʾasāṭīru l-ʾawwalīna ʾiktatabahā fa-hiya tumlā ʿalayhi bukrataw wa-ʾaṣīlā', 'Ve dediler ki: "(Bunlar) evvelkilerin masallarıdır; başkasına yazdırmış, sabah akşam ona okunmaktadır."'),
(25, 6, 18, 360, 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا', 'qul ʾanzalahu ʾalladhī yaʿlamu ʾs-sirra fī ʾs-samāwāti wa-l-ʾarḍi ʾinnahu kāna ghafūran raḥīman', 'De ki: "Onu, göklerde ve yerde gizli olan her şeyi bilen (Allah) indirdi. Şüphesiz O, çok bağışlayıcı, çok merhametlidir."'),
(25, 7, 18, 360, 'وَقَالُوا۟ مَالِ هَٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُۥ نَذِيرًا', 'wa qālū mā hādhā ar-rasūli yaʾkulu ṭ-ṭaʿāma wa yamshī fī l-ʾaswāqi lawlā ʾunzlila ʾilayhi malakun fa yakūna maʿahu nadhīran', 'Dediler ki: ''Bu ne biçim peygamber! Yemek yer, çarşılarda gezer. Ona bir melek indirilmeliydi de onunla birlikte (Allah''ın azabını) haber veren bir uyarıcı olmalıydı!'''),
(25, 8, 18, 360, 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌ يَأْكُلُ مِنْهَا وَقَالَ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', 'aw yulqā ilayhi kanzun aw takūnu lahu jannatun yaʾkulu minhā waqāla ẓẓālimūna in tattabiʿūna illā rajulan masḥūran', 'Yahut ona bir hazine verilseydi, yahut yediği bir bahçe olsaydı (ya da şöyle dediler): "Siz büyülenmiş bir adamdan başkasına uymuyorsunuz."'),
(25, 9, 18, 360, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', 'unẓur kayfa ḍarabū laka l-ʾamthāl fa-ḍallū fa-lā yastaṭīʿūna sabīlā', 'Bak, sana nasıl misaller getirdiler de saptılar ve bir yol bulamıyorlar.'),
(25, 10, 18, 360, 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', 'tabāraka alladhī in shāʾa jaʿala laka khayran min dhālika jannātin tajrī min taḥtihā l-anhāru wa-yajʿal laka quṣūran', 'Ne yüce ve bereketli, dilerse sana bundan daha hayırlısını, altından ırmaklar akan cennetler veren ve sana köşkler yapandır!'),
(25, 11, 18, 360, 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', 'bal kaḏḏabū bis-sāʿati wa-ʾaʿtadnā liman kaḏḏaba bis-sāʿati saʿīrā', 'Hayır, onlar kıyamet saatini yalanladılar. Kıyamet saatini yalanlayanlar için çılgın alevli ateşi hazırladık.'),
(25, 12, 18, 361, 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍ سَمِعُوا۟ لَهَا تَغَيُّظًا وَزَفِيرًا', 'idhā raʾathum min makānin baʿīd samiʿū lahā taghayyuẓan wa-zafīran', 'Onları uzaktan gördüğünde, onun (cehennemin) kaynamasını ve uğultusunu işitirler.'),
(25, 13, 18, 361, 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًا ضَيِّقًا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًا', 'wa-idhā ulqū min-hā makānan ḍayyiqan muqarranīn daʿaw hunālika thubūrā', 'Onlar oradan dar bir yere atıldıklarında, zincirlenmiş oldukları halde, orada "Vay halimize!" diye feryat ederler.'),
(25, 14, 18, 361, 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًا وَٰحِدًا وَٱدْعُوا۟ ثُبُورًا كَثِيرًا', 'lā tadʿū al-yawma thubūran wāḥidan wa-dʿū thubūran kathīran', 'Bugün bir tek helak çağrısı yapmayın, çok sayıda helak çağrısı yapın!'),
(25, 15, 18, 361, 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ كَانَتْ لَهُمْ جَزَآءً وَمَصِيرًا', 'Qul ʾadhālika khayrun ʾam jannatu l-khuldi llatī wuʿida l-muttaqūna Kānat lahum jazāʾan wa-maṣīran', 'De ki: "Bu mu daha hayırlıdır, yoksa takva sahiplerine vaad olunan ebedîlik cenneti mi? O, onlara bir mükâfat ve dönüş yeri olarak (hazırlanmıştır)."'),
(25, 16, 18, 361, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ كَانَ عَلَىٰ رَبِّكَ وَعْدًا مَّسْـُٔولًا', 'lahum fīhā mā yašāʾūna khālidīna kāna ʿalā rabbika waʿdan masʾūlan', 'Onlar için orada diledikleri her şey vardır. Rabbinin katında gerçekleşmesi istenmiş bir vaattir.'),
(25, 17, 18, 361, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', 'wa-yawma yaḥshuruhum wa-mā yaʿbudūna min dūni ʾllāhi fa-yaqūlu ʾa-ʾantum ʾaḍlaltum ʿibādī hāʾulāʾi ʾam hum ḍallū s-sabīla', 'Onları ve Allah''tan başka taptıklarını bir araya toplayacağı gün, şöyle diyecektir: "Bu kullarımı siz mi saptırdınız, yoksa kendileri mi yolu kaybettiler?"'),
(25, 18, 18, 361, 'قَالُوا۟ سُبْحَٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًا', 'qālū subḥānaka mā kāna yanbaghī lanā an nattakhidha min dūnika min awliyāʾa walākin mattaʿtahum wa-ābāʾahum ḥattā nasū adh-dhikra wa kānū qawman būran', 'Onlar şöyle dediler: "Seni tenzih ederiz! Bizim, Senden başka veliler edinmemiz bize yakışmazdı. Fakat Sen onları ve atalarını, zikri (Kur''an''ı) unutup helak oluncaya kadar dünya nimetlerinden faydalandırdın. Onlar, helaki hak etmiş bir kavim idiler."'),
(25, 19, 18, 361, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًا وَلَا نَصْرًا وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًا كَبِيرًا', 'faqad kadhdhabūkum bimā taqūlūn famā tastaṭīʿūna ṣarfan walā naṣran waman yaẓlim minkum nudhiqhu ʿadhāban kabīran', 'Böylece söyledikleriniz yüzünden onları yalanlamış oldunuz. Artık ne azabı savmaya gücünüz yeter ne de kendinize yardım etmeye. Sizden kim zulmederse ona büyük bir azap tattırırız.'),
(25, 20, 18, 361, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ وَكَانَ رَبُّكَ بَصِيرًا', 've mā arsalnā qablaka mina l-murselīne illā ʾennehum leyaʾkulūne ṭ-ṭaʿāme veyamshūne fī l-ʾaswāqi ve ceʿalnā baʿḍakum li-baʿḍin fitnaten ʾataṣbirūne ve kāne rabbuka baṣīran', 'Senden önce gönderdiğimiz bütün peygamberler de elbette yemek yerler ve çarşılarda gezerlerdi. (Biz) sizin birbirinizi imtihan etmeniz için kiminizi kiminize (imtihan) vesilesi kıldık. Sabredecek misiniz? Rabbin her şeyi hakkıyla görendir.'),
(25, 21, 19, 362, 'وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّا كَبِيرًا', 'waqāla alladhīna lā yarjūna liqāʾanā lawlā unzila ʿalaynā al-malāʾikatu aw narā rabbanā laqadi istakbarū fī anfusihim wa ʿataw ʿutuwwan kabīran', 'Bize ulaşmayı ummayanlar: "Melekler bize indirilmeliydi ya da Rabbimizi görmeliydik" dediler. Andolsun ki onlar, kendi nefislerinde büyüklük tasladılar ve azgınlıkta da iyice azdılar.'),
(25, 22, 19, 362, 'يَوْمَ يَرَوْنَ ٱلْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا', 'yawma yarawna l-malāʾikata lā bushṛā yawmaʾiḏin lil-mujrimīn wa-yaqūlūna ḥijran maḥjūran', 'Melekleri görecekleri o gün, suçlular için bir müjde yoktur ve ''Bu, (haram kılınmış) engellenmiş bir şeydir'' diyeceklerdir.'),
(25, 23, 19, 362, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍ فَجَعَلْنَٰهُ هَبَآءً مَّنثُورًا', 'waqadimnā ilā mā ʿamilū min ʿamalin fajaʿalnāhu habāʾan manthūrā', 'Onların yaptıkları her işe gelince, biz de onu dağınık bir toz haline getirmişizdir.'),
(25, 24, 19, 362, 'أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا', 'aṣḥābu l-jannati yawmaʾiḏin ḫayrun mustaqarran wa-ʾaḥsanu maqīlan', 'O gün, cennet ehlinin kalacağı yer daha hayırlı, dinlenme yeri daha güzeldir.'),
(25, 25, 19, 362, 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَٰمِ وَنُزِّلَ ٱلْمَلَٰٓئِكَةُ تَنزِيلًا', 'wa yawma tashaqqaqu s-samāʾu bil-ghamāmi wa nuzzila l-malāʾikatu tanzīlan', 'Gök, bulutlarla yarılıp parçalandığı ve melekler saf saf indirildiği o günü (hatırla).'),
(25, 26, 19, 362, 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًا', 'al-mulku yawma''iḏi l-ḥaqqu li-r-raḥmāni wa kāna yawman ʿalā l-kāfirīna ʿasīran', 'O gün mülk, Rahman olan Allah''ındır. Kâfirler için de zorlu bir gün olacaktır.'),
(25, 27, 19, 362, 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًا', 'wa yawma yaʿaḍḍu ẓ-ẓālimu ʿalā yadayhi yaqūlu yālaytanī t-takhadhtu maʿa r-rasūli sabīlā', 'Ve o gün zalim, ellerini ısırır, "Eyvah! Ben de o peygamberle birlikte bir yol tutmalıydım!" der.'),
(25, 28, 19, 362, 'يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا', 'yā waylatā laytanī lam attakhidh fulānan khalīlā', 'Eyvahlar bana! Keşke falan kimseyi dost edinmeseydim!'),
(25, 29, 19, 362, 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى وَكَانَ ٱلشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًا', 'Lekad edallenî aniz-zikri ba''de iz câenî Ve kâneş-şeytânu lil''insâni hazûlâ', 'Andolsun ki beni zikirden (Kur''an''dan) saptırdı, bana geldikten sonra. Şeytan insan için çokça yüzüstü bırakandır.'),
(25, 30, 19, 362, 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَٰذَا ٱلْقُرْءَانَ مَهْجُورًا', 'waqāla r-rasūlu yā rabbī inna qawmī-ttakhadhū hādhā l-qurʾāna mahjūran', 'Resûl şöyle dedi: "Ey Rabbim! Gerçekten benim kavmim bu Kur''an''ı (terk edip) terk ettiler."'),
(25, 31, 19, 362, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا مِّنَ ٱلْمُجْرِمِينَ وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا', 'wa kadhalika ja''alna likulli nabiyyin ''aduwwan minal-mujrimīn wa kafā birabbika hādiyan wa nasīran', 'İşte böylece biz her peygamber için suçlulardan bir düşman kıldık. Yol göstermesi ve yardım etmesi bakımından Rabbin yeter.'),
(25, 32, 19, 362, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةً وَٰحِدَةً كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ وَرَتَّلْنَٰهُ تَرْتِيلًا', 'waqāla alladhīna kafarū lawlā nuzzila ʿalayhi l-qurʾānu jumalatan wāḥidatan kadhālika linuthabbita bihi fūʾādaka waratallnāhu tartīlan', 'İnkâr edenler şöyle dediler: "O Kur''an ona bir bütün halinde indirilmeli değil miydi?" Biz de onu senin kalbini sağlamlaştırmak için böyle (parça parça) indirdik ve onu tane tane okuduk.'),
(25, 33, 19, 363, 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', 'wa-lā yaʾtūna-ka bi-maṯalin illā jiʾnā-ka bi-l-ḥaqqi wa-aḥsana tafsīran', 'Onlar sana hiçbir örnek getirmediler ki, biz sana gerçeği ve en güzel açıklamayı getirmemiş olalım.'),
(25, 34, 19, 363, 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا', 'alladhīna yuḥsharūna ʿalā wujūhihim ilā jahannama ʾulāʾika sharru makānan waʾaḍallu sabīlā', 'Onlar, yüzüstü cehenneme toplanacak olanlardır. İşte bunlar, yer bakımından daha kötü ve yol bakımından daha sapkındırlar.'),
(25, 35, 19, 363, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًا', 'Ve lekad âteynâ Mûsâ el-Kitâbe ve ce''alnâ me''ahû ehâhu Hârûne vezîrâ', 'Andolsun ki Musa''ya Kitab''ı verdik ve kardeşi Harun''u da onunla birlikte vezir yaptık.'),
(25, 36, 19, 363, 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًا', 'Fequlnāż-habā ilal-qawmil-lezīne kezzebū bi-āyātinā Fedemmernāhum tadmīrā', 'Bunun üzerine şöyle dedik: "Haydi gidin, ayetlerimizi yalanlayan o kavme! Sonra onları kökünden helak ettik."'),
(25, 37, 19, 363, 'وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةً وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًا', 'wa-qawma nūḥin lammā kadhdhabū ar-rusula aghraqnāhum wa-jaʿalnāhum lin-nāsi āyatan wa-aʿtadnā liẓ-ẓālimīna ʿadhāban alīman', 'Nuh''un kavmini de, peygamberleri yalanladıkları zaman boğduk ve onları insanlara bir ibret yaptık. Biz zalimler için acı bir azap hazırladık.'),
(25, 38, 19, 363, 'وَعَادًا وَثَمُودَا۟ وَأَصْحَٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًا', 'wa ʿādan wa thsmūdā wa ʾaṣḥāba r-rassi wa qurūnan bayna dhālika kathīran', 'Ad''ı, Semud''u, Ashab-ı Ress''i ve bunlar arasındaki nice nesilleri de helak ettik.'),
(25, 39, 19, 363, 'وَكُلًّا ضَرَبْنَا لَهُ ٱلْأَمْثَٰلَ وَكُلًّا تَبَّرْنَا تَتْبِيرًا', 'wa-kullan ḍarabnā lahu l-ʾamṯāla wa-kullan tabbarnā tatbīran', 'Her birine misaller verdik ve her birini de kökünden yok ettik.'),
(25, 40, 19, 363, 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًا', 'Ve lekad etev alel karyetilletî umtırat metaressevʾi Efelem yekûnû yeravnehâ Bel kânû lâ yercûne nuşûrâ', 'Andolsun ki onlar, üzerlerine kötü yağmur yağdırılan kasabaya uğramışlardı. Onu görmüyorlar mıydı? Hayır, onlar yeniden dirilmeyi ummuyorlardı.'),
(25, 41, 19, 363, 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', 'wa ʾiḏā raʾawka ʾin yattaḫiḏūnakā ʾillā huzuwan ʾahāḏā ʾallaḏī baʿaṯa ʾallāhu rasūlan', 'Onlar seni gördükleri zaman, seni alaydan başka bir şey edinmezler. "Allah''ın gönderdiği elçi bu mudur?" derler.'),
(25, 42, 19, 363, 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', 'in kāda layuḍillunā ʿan ʾālihatinā lawlā ʾan ṣabarnā ʿalayhā wa sawfa yaʿlamūna ḥīna yarawna l-ʿaḏāba man ʾaḍallu sabīlā', 'Neredeyse ilahlarımızdan bizi saptıracaktı; eğer onlara karşı sabırlı olmasaydık. Azabı gördükleri zaman kimin yolunun daha sapık olduğunu bileceklerdir.'),
(25, 43, 19, 363, 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 'ʾaraʾayta mani-ttakhaḏa ʾilāhahu h می‌دهد ʾafaʾanta takūnu ʿalayhi wakīlan', 'Hevasını ilah edineni gördün mü? O halde onun üzerine vekil olabilir misin?'),
(25, 44, 19, 364, 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ سَبِيلًا', 'am taḥsabun anna aktharahum yasmaʿūna aw yaʿqilūn in hum illā kal-anʿāmi bal hum aḍallu sabīlā', 'Yoksa onların çoğunun gerçekten (sözümüzü) işittiğini veya aklettiğini mi sanırsın? Onlar hayvanlar gibidir; hayır, yolca daha sapıktırlar.'),
(25, 45, 19, 364, 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًا', 'ʾelem tere ʾilā rabbike keyfe medde ẓẓille velev şāʾe leğeaʿelehu sākinan ṡumme ğeaʿelnā ʾššemse ʿaleyhi delīlen', 'Rabbini, gölgeyi nasıl uzattığını görmedin mi? Eğer dileseydi onu hareketsiz kılabilirdi. Sonra biz, güneşi ona bir delil kıldık.'),
(25, 46, 19, 364, 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًا يَسِيرًا', 'thumma qabaḍnāhu ilaynā qabḍan yasīrā', 'Sonra onu (gölgeyi) kendimize doğru yavaşça çekeriz.'),
(25, 47, 19, 364, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًا وَٱلنَّوْمَ سُبَاتًا وَجَعَلَ ٱلنَّهَارَ نُشُورًا', 'wa huwa alladhī jaʿala lakumu allayla libāsan wa-n-nawma subātan wa jaʿala an-nahāra nushūran', 'O, geceyi size bir örtü, uykuyu bir dinlenme, gündüzü de (dirilip) yayılma vakti yapan (ve her şeyden) haberdar olandır.'),
(25, 48, 19, 364, 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا', 'wa-huwa alladhī arsala ar-riyāḥa bushran bayna yaday raḥmatihī wa-anzalnā mina as-samāʾi māʾan ṭahūrā', 'O, rahmetinin önünde müjde olarak rüzgarları gönderen, gökten de tertemiz bir su indirendir.'),
(25, 49, 19, 364, 'لِّنُحْۦِىَ بِهِۦ بَلْدَةً مَّيْتًا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًا وَأَنَاسِىَّ كَثِيرًا', 'li-nuḥyiya bihi baldatan maytan wa-nusqiyahu mim-mā khalaqnā anʿāman wa-anāsiyya kaṡīran', 'Onunla (yağmurla) ölüp çoraklaşmış bir beldeyi diriltmek ve yarattığımız nice hayvanlara ve insanlara su vermek için (göndeririz).'),
(25, 50, 19, 364, 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', 'wa laqad ṣarrafnāhu baynahum li-yadhakkarū fa-abā aktharu an-nāsi illā kufūran', 'Onu (suyu) aralarında çeşitli şekillerde dağıttık ki düşünüp öğüt alsınlar. Fakat insanların çoğu nankörlükten başkasını kabul etmedi.'),
(25, 51, 19, 364, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيرًا', 'Velev şi''nâ lebe''asnâ fî kulli karyetin nezhîrâ(n)', 'Eğer dileseydik, her şehre bir uyarıcı gönderirdik.'),
(25, 52, 19, 364, 'فَلَا تُطِعِ ٱلْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًا كَبِيرًا', 'falā tuṭiʿi l-kāfirīna wa-jāhid''hum bihī jihādan kabīran', 'O halde kâfirlere boyun eğme ve onlara karşı bu Kur''an''la büyük bir cihad yap.'),
(25, 53, 19, 364, 'وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَٰذَا عَذْبٌ فُرَاتٌ وَهَٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا', 'wa huwa alladhī maraja l-baḥrayni hādhā ʿadhbun furātun wa hādhā milḥun ujājun wa jaʿala baynahumā barzakhan wa ḥijran maḥjūran', 'O, biri tatlı ve susuzluğu giderici, diğeri tuzlu ve acı olan iki denizi birbirine salıveren, aralarına da bir engel ve geçilmez bir sınır koyan Allah’tır.'),
(25, 54, 19, 364, 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًا فَجَعَلَهُۥ نَسَبًا وَصِهْرًا وَكَانَ رَبُّكَ قَدِيرًا', 'wa huwa alladhī khalaqa mina l-māʾi basharan fa jaʿalahu nasaban wa ṣihran wa kāna rabbuka qadīran', 'Suyu (sperm) bir damla sudan insanı yaratan, sonra onu soy-sop ve sıhriyet bağıyla insan yapan O''dur. Senin Rabbin her şeye gücü yetendir.'),
(25, 55, 19, 364, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًا', 'wa yaʿbudūna min dūni llāhi mā lā yanfaʿuhum wa lā yaḍurruhum wa kāna l-kāfiru ʿalā rabbihī ẓahīran', 'Onlar, Allah''tan başka, kendilerine fayda da zarar da vermeyen şeylere taparlar. Ve kâfir, Rabbine karşı (şeytanlara veya kendi nefsine) arka çıkandır.'),
(25, 56, 19, 365, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', 'wa mā arsalnāka illā mubashshiran wa nadhīran', 'Seni ancak müjdeleyici ve uyarıcı olarak gönderdik.'),
(25, 57, 19, 365, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'qul mā ʾasʾalukum ʿalayhi min ʾajrin ʾillā man šāʾa ʾan yattakhiḏa ʾilā rabbihi sabīlā', 'De ki: "Buna karşılık sizden hiçbir ücret istemiyorum; ancak kim Rabbine doğru bir yol tutmak isterse (bu başka)."'),
(25, 58, 19, 365, 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 'wa tawakkal ʿalā l-ḥayyi l-ladhī lā yamūtu wa sabbih bi-ḥamdihi wa kafā bihi bi-dhunūbi ʿibādihi khabīran', 'Ölmeyen daima diri olan Allah''a güvenip dayan. O''nu hamdiyle tesbih et. O, kullarının günahlarından haberdar olarak yeter.'),
(25, 59, 19, 365, 'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًا', 'alladhī khalaqa as-samāwāti wa-l-arḍa wa mā baynahumā fī sittati ayyāmin thumma istawā ʿalā l-ʿarshi r-raḥmānu fa-s''al bihi khabīran', 'O, gökleri, yeri ve ikisi arasında bulunanları altı günde yaratan, sonra da Arş''a istivâ eden Rahmân''dır. O halde, onun hakkında bilgili birine sor.'),
(25, 60, 19, 365, 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا', 'wa ʾiḏā qīla lahumu ʾsǧudū li-r-raḥmāni qālū wa mā ʾr-raḥmānu ʾan-asǧudu li-mā taʾmurunā wa zādahum nufūran', 'Onlara: "Rahmân''a secde edin!" dendiği zaman, "Rahmân da nedir? Biz senin emrettiğin şeye mi secde edeceğiz?" derler ve bu onlara daha da nefret ve kaçınma artırır.'),
(25, 61, 19, 365, 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَٰجًا وَقَمَرًا مُّنِيرًا', 'tabāraka alladhī jaʿala fī ʾssamāʾi burūjan wa jaʿala fīhā sirājan wa qamaran munīran', 'Semada burçlar yaratan, onların içinde bir kandil ve nurlu bir Ay yaratan yüce Allah''tır.'),
(25, 62, 19, 365, 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا', 'wa-huwa lladhī jaʿala l-layla wa-n-nahāra khilfatan liman arāda an yadhdhakkara aw arāda shukūran', 'O, öğüt almak veya şükretmek isteyen kimse için gece ile gündüzü birbiri ardınca getiren (müteâkiben kılan) zât-ı şânı haşmet-penâhîdir.'),
(25, 63, 19, 365, 'وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًا', 'wa ʿibādu r-raḥmāni l-ladhīna yamshūna ʿalā l-arḍi hawnan wa idhā khāṭabahumu l-jāhilūna qālū salāman', 'Rahmân''ın (وَعِبَادُ ٱلرَّحْمَٰنِ) kulları (ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًا) yeryüzünde vakarla yürüyenlerdir (وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ) ve cahiller kendilerine (sözle) sataştığında (قَالُوا۟ سَلَٰمًا) ''selâm'' derler.'),
(25, 64, 19, 365, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَٰمًا', 'wa-lladhīna yabītūna li-rabbihim sujaddan wa-qiyāman', 'Onlar, Rablerine geceleyin secde ederek ve kıyamda durarak ibadet ederler.'),
(25, 65, 19, 365, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'wa-lladhīna yaqūlūna rabbanā ṣrif ʿannā ʿadhāba jahannama ʾinna ʿadhābahā kāna gharāman', 'Onlar ki, "Rabbimiz! Cehennem azabını üzerimizden sav. Çünkü onun azabı daimîdir" derler.'),
(25, 66, 19, 365, 'إِنَّهَا سَآءَتْ مُسْتَقَرًّا وَمُقَامًا', 'ʾinnahā sāʾat mustaqarran wa-muqāman', 'Şüphesiz cehennem, ne kötü bir durak ve ne kötü bir yerleşim yeridir.'),
(25, 67, 19, 365, 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا', 'wa-lladhīna idhā anfaqū lam yusrifū walm yaqturu wākāna bayna dhālika qawāman', 'Onlar, harcadıklarında israf etmeyen ve cimrilik yapmayan, bunun ikisi arasında orta yolu tutanlardır.'),
(25, 68, 19, 366, 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا', 'wa-lladhīna lā yadʿūna maʿa llāhi ilāhan ʾākhar wa-lā yaqtulūna n-nafsa llatī ḥarrama llāhu ʾillā bi-l-ḥaqqi wa-lā yaznūna wa-man yafʿal dhālika yalqa ʾathāman', 'Ve onlar ki, Allah ile beraber başka bir ilâha tapmazlar; Allah''ın haram kıldığı cana, haklı bir sebep olmadıkça kıymazlar ve zina etmezler. Bunları yapan kimse günahının cezasını bulur.'),
(25, 69, 19, 366, 'يُضَٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', 'yuḍāʿaf lahu l-ʿaḏābu yawma l-qiyāmati wa y a k h l u d fīhi muhānan', 'Kıyamet gününde azabı kat kat artırılır ve orada temelli olarak zelil kalır.'),
(25, 70, 19, 366, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَٰلِحًا فَأُو۟لَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتٍ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'illa men tāba wa-ʾāmana wa-ʿamila ʿamalan ṣāliḥan fa-ʾulāʾika yubaddilu ʾllāhu sayyiʾātihim ḥasanātin wa-kāna ʾllāhu ghafūran raḥīman', 'Ancak tövbe eden, iman eden ve salih amel işleyen kimseler bunun dışındadır. Allah''ın, işte onların kötülüklerini iyiliklere çevirmesi umulur. Allah, Gafûr''dur, Rahîm''dir.'),
(25, 71, 19, 366, 'وَمَن تَابَ وَعَمِلَ صَٰلِحًا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًا', 've men tābe ve ''amile ṣāliḥan fe''innehu yetūbu ilallāhi matābā', 'Kim tevbe eder ve salih amel işlerse, şüphesiz o, tevbesi kabul edilmiş olarak Allah''a yönelir.'),
(25, 72, 19, 366, 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًا', 'wa-lladhīna lā yash-hadūna z-zūr wa-idhā marrū bil-laghwi marrū kirāman', 'Onlar ki yalan yere şahitlik etmezler ve faydasız bir şeyle karşılaştıklarında vakarla geçerler.'),
(25, 73, 19, 366, 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّا وَعُمْيَانًا', 'wa-lladhīna idhā dhukkirū bi-āyāti rabbihim lam yakhirrū ʿalayhā ṣumman wa-ʿumyānan', 'Onlar, Rablerinin ayetleriyle öğüt verildiklerinde, onlara karşı sağır ve körler olarak düşmeyenlerdir.'),
(25, 74, 19, 366, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'wa-lladhīna yaqūlūna rabbanā hab lanā min azwājina wa-dhurriyyātinā qurrata aʿyunin wa-jʿalnā lil-muttaqīna imāman', 'Ve onlar ki, "Rabbimiz! Bize göz aydınlığı olacak eşler ve zürriyetler ihsan et ve bizi takva sahiplerine önder kıl" derler.'),
(25, 75, 19, 366, 'أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَٰمًا', 'ʾūlāʾika yujzawna l-ḡurfata bimā ṣabarū wa yulaqqawna fīhā taḥiyyatan wa salāman', 'İşte onlar, sabretmelerine karşılık (cennette) yüksek makamlara nail olacaklar ve orada sağlık ve selamet dileğiyle karşılanacaklardır.'),
(25, 76, 19, 366, 'خَٰلِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا', 'khālidīna fīhā ḥasanat mustaqarran wa muqāman', 'Onlar orada ebedî kalıcıdırlar. Orası ne güzel bir durak ve ne güzel bir ikametgâhtır.'),
(25, 77, 19, 366, 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', 'qul mā yaʿbaʾu bikum rabbī lawlā duʿāʾukum faqad kaḏḏabtum fa-sawfa yakūnu lizāman', 'De ki: "Rabbim sizin için, dua ve yakarışınız olmasaydı, hiçbir değer vermezdi. Nitekim siz (gerçeği) yalanladınız; bu yüzden azap kaçınılmaz olacaktır."'),
(26, 1, 19, 367, 'طسٓمٓ', 'Ṭā, Sīn, Mīm', 'Tâ, Sîn, Mîm.'),
(26, 2, 19, 367, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'tilka āyātu l-kitābi l-mubīni', 'Bunlar, apaçık olan Kitab''ın ayetleridir.'),
(26, 3, 19, 367, 'لَعَلَّكَ بَٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', 'laʿallaka bākhiʿun nafsaka allā yakūnū muminīn', 'Onlar iman etmiyorlar diye neredeyse kendini helak edeceksin.'),
(26, 4, 19, 367, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَٰقُهُمْ لَهَا خَٰضِعِينَ', 'in našʾa nunazzil ʿalayhim mina s-samāʾi ʾāyatan fa-ẓallat ʾaʿnāquhum lahā khāḍiʿīn', 'Eğer dilersek, onların üzerine gökten bir mucize indiririz de boyunları ona eğiliverir.'),
(26, 5, 19, 367, 'وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ ٱلرَّحْمَٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', 've mā yeʾtīhim min ḏikrin mina r-raḥmāni muḥdaṯin illā kānū ʿanhu muʿriḍīn', 'Onlara, çok esirgeyen (Allah) tarafından yeni bir uyarı (ayet) gelmeksizin, onlardan yüz çevirecekleri bir şey gelmez.'),
(26, 6, 19, 367, 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'Feqed keẕẕebū Fesey''etīhim enbe''ū mā kānū bihī yestehzi''ūn', 'Onlar yalanladılar. Alay etmekte oldukları şeylerin haberleri kendilerine birazdan gelecektir.'),
(26, 7, 19, 367, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', 'E-ve-lem yerav ilal-arḍi kem-enbetnā fīhā min kulli zevcin kerīm', 'Onlar, yeryüzüne bakıp da orada her güzel çiftten nice bitkiler bitirdiğimizi görmediler mi?'),
(26, 8, 19, 367, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'inna fī dhālika laʾāyatan wa mā kāna ʾaktharuhum muʾminīn', 'Şüphesiz bunda bir ayet vardır. Ama çoğu iman etmiş değildir.'),
(26, 9, 19, 367, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, engin merhamet sahibidir.'),
(26, 10, 19, 367, 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'wa-ʾiḏ nādā rabbuka mūsā ʾani ʾti l-qawma ẓ-ẓālimīn', 'Hani Rabbin Mûsâ''ya şöyle nida etmişti: "O zalimler topluluğuna git!"'),
(26, 11, 19, 367, 'قَوْمَ فِرْعَوْنَ أَلَا يَتَّقُونَ', 'qawma firʿawna ʾalā yattaqūn', 'Firavun''un kavmi! Hala korkup sakınmayacaklar mı?'),
(26, 12, 19, 367, 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'qāla rabbi innī ʾakhāfu ʾan yukadhibūn', 'Dedi ki: "Rabbim! Doğrusu ben, beni yalanlamalarından korkuyorum."'),
(26, 13, 19, 367, 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَٰرُونَ', 'wa yaḍīqu ṣadrī wa lā yanṭaliqu lisānī faʾarsil ʾilā hārūn', 'Göğsüm daralır ve dilim çözülmez. Bu yüzden Hârûn''a da (elçi gönder).'),
(26, 14, 19, 367, 'وَلَهُمْ عَلَىَّ ذَنۢبٌ فَأَخَافُ أَن يَقْتُلُونِ', 'wa lahum ʿalayya dhanbun fa-ʾakhāfu ʾan yaqtulūn', 'Hem benim üzerimde bir günahım var, bu yüzden beni öldürmelerinden korkuyorum.'),
(26, 15, 19, 367, 'قَالَ كَلَّا فَٱذْهَبَا بِـَٔايَٰتِنَآ إِنَّا مَعَكُم مُّسْتَمِعُونَ', 'qāla kalla fa-dh-habā bi-ʾāyātinā ʾinnā maʿakum mustamiʿūn', 'Allah şöyle dedi: "Hayır, gidin! Ayetlerimizle birlikte siz ikiniz de (onlara) gidin. Şüphesiz biz sizinle beraberiz, (sözlerinizi) işitiyoruz."'),
(26, 16, 19, 367, 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 'faʾtiyā firʿawna fəqūlā ʾinnā rasūlu rabbil-ʿālamīn', 'Bunun üzerine ikiniz Firavun''a gidin ve deyin ki: "Şüphesiz biz, âlemlerin Rabbi''nin elçisiyiz."'),
(26, 17, 19, 367, 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', 'ʾan ʾarsil maʿanā banī ʾisrāʾīla', 'Beni İsrail''i bizimle birlikte gönder.'),
(26, 18, 19, 367, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', 'qāla ʾalam nurabbīka fīnā walīdan walabiṯta fīnā min ʿumrika sinīna', 'Firavun: "Seni çocukken yanımızda büyütmedik mi? Ve ömründen nice yıllar bize hizmet etmedin mi?" dedi.'),
(26, 19, 19, 367, 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَٰفِرِينَ', 'wa-faʿalta faʿlataka allatī faʿalta wa-anta mina l-kāfirīn', 'Ve yaptığın o yaptığını yaptın, halbuki sen kâfirlerdensin.'),
(26, 20, 19, 368, 'قَالَ فَعَلْتُهَآ إِذًا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 'qāla faʿaltuhā ʾiḏan wa-ʾanā mina ḍ-ḍāllīn', 'Musa şöyle dedi: "O zaman onu yapmıştım, ben sapmışlardan idim."'),
(26, 21, 19, 368, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', 'fafaraṟtu minkum lammā xiftukum fawahebe lī rabbī ḥukman wa-jaʿalanī mina l-murselīn', 'Böylece sizden korkunca içinizden kaçtım. Sonra Rabbim bana bir hikmet (hükümranlık, peygamberlik) bağışladı ve beni peygamberlerden kıldı.'),
(26, 22, 19, 368, 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', 'wa tilka niʿmatun tamunnuḥā ʿalayya an ʿabbadta banī ʾisrāʾīla', 'Ve bu, İsrailoğullarını köle edinmenle bana karşı bir lütuf mudur?'),
(26, 23, 19, 368, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَٰلَمِينَ', 'qāla firʿawnu wa mā rabbul-ʿālamīn', 'Firavun dedi ki: "Âlemlerin Rabbi de nedir?"'),
(26, 24, 19, 368, 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ', 'qāla rabbus-samāwāti wal-arḍi wa mā baynahumā in kuntum mūqinīn', 'Göklerin ve yerin ve ikisinin arasında bulunanların Rabbi, dedi, eğer inanacak kimseler iseniz.'),
(26, 25, 19, 368, 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', 'qāla liman ḥawlahu ʾalā tastamiʿūn', 'Çevresindekilere şöyle dedi: "Hiç dinlemiyor musunuz?"'),
(26, 26, 19, 368, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'qāla rabbukum wa-rabb u ʾābāʾikum u l-ʾawwalīn', 'Firavun şöyle dedi: "Sizin de, geçmiş atalarınızın da Rabbi...'),
(26, 27, 19, 368, 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ', 'qāla inna rasūlakumu lladhī ur''sila ilaykum lamajnūn', 'Dedi ki: "Size gönderilen o elçiniz mutlaka mecnundur!"'),
(26, 28, 19, 368, 'قَالَ رَبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَمَا بَيْنَهُمَآ إِن كُنتُمْ تَعْقِلُونَ', 'qāla rabbi l-mašriqi wa-l-maġribi wa-mā baynahumā ʾin kuntum taʿqilūn', 'Ben, eğer aklınızı kullanacak olursanız, doğunun ve batının ve ikisi arasındakilerin Rabbiyim, dedi.'),
(26, 29, 19, 368, 'قَالَ لَئِنِ ٱتَّخَذْتَ إِلَٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ', 'qāla laʾin ittakhadhta ʾilāhan ġayrī laʾajʿalannaka mina l-masjūnīn', 'Firavun: "Andolsun ki, eğer benden başkasını ilah edinirsen, mutlaka seni zindana atılanlardan yapacağım!" dedi.'),
(26, 30, 19, 368, 'قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍ مُّبِينٍ', 'qāla ʾa-wa-law jiʾtuka bi-šayʾin mubīnin', 'Dedi ki: "Sana apaçık bir şey getirmiş olsam da mı?"'),
(26, 31, 19, 368, 'قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'qāla faʾti bihī ʾin kunta mina ṣ-ṣādiqīn', 'Musa dedi ki: "Eğer doğru söyleyenlerden isen, haydi onu (değneğini) getir!"'),
(26, 32, 19, 368, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', 'faʾalqā ʿaṣāhu faʾiḏā hiya ṯuʿbānun mubīnun', 'Bunun üzerine Musa asasını bıraktı. Bir de ne görsün, o, apaçık bir yılan oluverdi.'),
(26, 33, 19, 368, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 'wa-nazʿa yadahū fa-iḏā hiya bayḍāʾu li-n-nāẓirīn', 'Elini çıkardı, bir de ne görsünler, bembeyaz kesilmişti.'),
(26, 34, 19, 368, 'قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ', 'qāla lil-malaʾi ḥawlahū ʾinna hādhā la-sāḥirun ʿalīm', 'Firavun, etrafındakilere şöyle dedi: "Şüphesiz bu, çok bilgili bir büyücüdür."'),
(26, 35, 19, 368, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ', 'yurīdu an yukhricakum min arḍikum bisiḥrihī famāḏā taʾmurūn', 'Sihriyle sizi yurdunuzdan çıkarmak istiyor. Ne yapmamı tavsiye edersiniz?'),
(26, 36, 19, 368, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَٱبْعَثْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'qālū ʾarǧih wa-ʾaḫāhu wa-bʿaṯ fī l-madāʾini ḥāširīn', 'Dediler ki: ''Onu ve kardeşini beklet, şehirlere de toplayıcılar gönder.'''),
(26, 37, 19, 368, 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ', 'yaʾtūka bikulli saḥḥārin ʿalīm', 'Sana her bilgili büyücüyü getirsinler.'),
(26, 38, 19, 368, 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوْمٍ مَّعْلُومٍ', 'fa-jumiʿa s-saḥaratu li-mīqāti yawmin maʿlūmin', 'Büyücüler, belirlenmiş bir günün vakti için toplandı.'),
(26, 39, 19, 368, 'وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ', 'wa qīla li-n-nāsi hal antum mujtamiʿūn', 'Ve insanlara şöyle denildi: "Toplanacak mısınız?"'),
(26, 40, 19, 369, 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 'laʿallanā nattabiʿu s-saḥarata in kānū humu l-ḡālibīn', 'Eğer üstün gelenler büyücüler olacaksa, belki biz de onlara uyarız.'),
(26, 41, 19, 369, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 'felemmā jāʾa s-saḥaratu qālū lifirʿawna ʾaʾinna lanā laʾajran ʾin kunnā naḥnu l-ḡālibīn', 'Büyücüler gelince, Firavun''a şöyle dediler: "Eğer galip gelirsek, bize mutlaka bir mükâfat vardır, değil mi?"'),
(26, 42, 19, 369, 'قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ ٱلْمُقَرَّبِينَ', 'qāla naʿam wa-ʾinnakum ʾiḏan la-mina l-muqarrabīn', 'Dedi: "Evet! Ve şüphesiz siz o takdirde mutlaka benim yakınlarımdan olursunuz."'),
(26, 43, 19, 369, 'قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 'qāla lahum Mūsā ʾalqū mā ʾantum mulqūna', 'Musa onlara dedi ki: "Atın bakalım, sizin atmakta olduğunuz şeyleri!"'),
(26, 44, 19, 369, 'فَأَلْقَوْا۟ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا۟ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ٱلْغَٰلِبُونَ', 'faʾalqaw ḥibālahum waʿiṣiyyahum waqālū biʿizzati firʿawna ʾinnā lanahnu l-ḡālibūn', 'Bunun üzerine iplerini ve sopalarını attılar. Firavun''un izzeti adına, biz gerçekten galip olanlarız! dediler.'),
(26, 45, 19, 369, 'فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 'faʾalqā Mūsā ʿasāhu faʾiḏā hiya talqafulmā yaʾfikūn', 'Bunun üzerine Musa asasını attı. Bir de ne görsünler, asa onların uydurarak ortaya attıklarını yutuyor!'),
(26, 46, 19, 369, 'فَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'fa-ulqiya as-saḥaratu sajidīn', 'Bunun üzerine sihirbazlar secdeye kapandılar.'),
(26, 47, 19, 369, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 'qālū ʾāmannā birabbi l-ʿālamīn', 'Dediler ki: "Âlemlerin Rabbine inandık."'),
(26, 48, 19, 369, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'Rabbi Mūsā wa Hārūn', 'Musa ve Harun''un Rabbi.'),
(26, 49, 19, 369, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 'qāla ʾāmantum lahu qabla ʾan ʾādhana lakum ʾinnahu lakabīrukumu lladhī ʿallamakumu s-siḥra fal sawfa taʿlamūna la ʾuqaṭṭiʿanna ʾaydiyakum wa ʾarjulakum min khilāfin wa la ʾuṣallibannakum ʾajmaʿīna', 'Firavun: "Ben size izin vermeden önce ona inandınız demek! Andolsun ki o, sizin en büyüğünüzdür; size sihri o öğretmiştir. Andolsun ki ben de sizin ellerinizi ve ayaklarınızı çapraz olarak keseceğim ve hepinizi mutlaka asacağım!" dedi.'),
(26, 50, 19, 369, 'قَالُوا۟ لَا ضَيْرَ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'qālū lā ḍayra ʾinnā ʾilā rabbina munqalibūna', 'Dediler ki: "Zararı yok! Şüphesiz biz Rabbimize döneceğiz."'),
(26, 51, 19, 369, 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', 'innā naṭmaʿu an yagfira lanā rabbunā khaṭāyānā an kunnā awwala l-muʾminīn', 'Gerçekten biz, ilk inananlar olmamız sebebiyle Rabbimizin bizi bağışlamasını umarız.'),
(26, 52, 19, 369, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', 'waʾawḥaynā ʾilā mūsā ʾan ʾasri biʿibādī ʾinnakum muttabaʿūn', 'Musa''ya da şöyle vahyettik: "Kullarımla geceleyin yola çık, çünkü takip edileceksiniz."'),
(26, 53, 19, 369, 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'faʾarsala firʿawnu fī l-madāʾini ḥāshirīn', 'Bunun üzerine Firavun, şehirlere (ordu) toplayıcılar gönderdi.'),
(26, 54, 19, 369, 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ', 'ʾinna hāʾulāʾi laširẕimatun qalīlūn', 'Şüphesiz bunlar, azınlıkta kalan bir gruptur.'),
(26, 55, 19, 369, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', 'wa-ʾinnahum lanā laḡāʾiẓūn', 'Ve şüphesiz ki onlar bize gerçekten çok kızgındırlar.'),
(26, 56, 19, 369, 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', 'wa-ʾinnā la-jamīʿun ḥādhirūn', 'Ve şüphesiz biz, hep birlikte tedbir alanlarız.'),
(26, 57, 19, 369, 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍ وَعُيُونٍ', 'faʾakhrajnāhum min jannātin waʿuyūnin', 'Böylece onları bağlardan ve pınarlardan çıkardık.'),
(26, 58, 19, 369, 'وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ', 'wa kunūzin wa maqāmin karīm', 'Ve hazineler ve değerli bir makam!'),
(26, 59, 19, 369, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', 'kadhālika wa-awrathnāhā banī isrāʾīl', 'İşte böyle! Ve onları İsrailoğullarına miras bıraktık.'),
(26, 60, 19, 369, 'فَأَتْبَعُوهُم مُّشْرِقِينَ', 'fa-atbaʿūhum mushrikīn', 'Böylece onları, güneşin doğduğu vakitte takip ettiler.'),
(26, 61, 19, 370, 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', 'fe-lemmā terāʾā l-cemʿāni qāla aṣḥābu Mūsā ʾinnā le-mudrakūna', 'İki topluluk birbirini gördüğü zaman, Mûsâ''nın ashâbı: "Andolsun ki, biz yakalandık!" dediler.'),
(26, 62, 19, 370, 'قَالَ كَلَّآ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', 'qāla kallaʾ ʾinna maʿiya rabbī sayahdīn', 'Musa dedi ki: "Hayır! Şüphesiz Rabbim benimle beraberdir, bana yol gösterecektir."'),
(26, 63, 19, 370, 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ', 'faʾawḥaynā ʾilā mūsā ʾani ḍrib biʿaṣāka l-baḥra fa-nfalq fakāna kullu firqin ka-l-ṭawdi l-ʿaẓīmi', 'Bunun üzerine Musa''ya, ''Asânı denize vur!'' diye vahyettik. Deniz yarıldı da her biri yüce bir dağ gibi oldu.'),
(26, 64, 19, 370, 'وَأَزْلَفْنَا ثَمَّ ٱلْءَاخَرِينَ', 'wa-azlafna thamma l-ākharīn', 'Ve diğerlerini de orada yaklaştırdık.'),
(26, 65, 19, 370, 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', 'waʾanjaynā Mūsā waman maʿahu ʾajmaʿīn', 'Ve Mûsâ''yı ve onunla birlikte olanların hepsini kurtardık.'),
(26, 66, 19, 370, 'ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ', 'thumma aghraqnā al-ʾākhirīn', 'Sonra diğerlerini (suda) boğduk.'),
(26, 67, 19, 370, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'inna fī ḏālika la-ʾāyatan wa-mā kāna ʾakṯaruhum muʾminīn', 'Şüphesiz bunda bir ayet vardır. Onların çoğu iman etmiş değillerdi.'),
(26, 68, 19, 370, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Ve şüphesiz Rabbin, O mutlak güç sahibidir, (O) çok merhametlidir.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(26, 69, 19, 370, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ', 'wa-tlu ʿalayhim nabaʾa ibrāhīm', 'Onlara İbrahim''in haberini de oku.'),
(26, 70, 19, 370, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ', 'iż qāla li-ʾabīhi wa-qawmihi mā taʿbudūn', 'Hani babasına ve kavmine demişti ki: «Neler tapıyorsunuz?»'),
(26, 71, 19, 370, 'قَالُوا۟ نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَٰكِفِينَ', 'qālū naʿbudu ʾaṣnāman fanazallu lahā ʿākifīn', 'Dediler ki: "Putlara taparız, biz de onlara bağlı kalırız."'),
(26, 72, 19, 370, 'قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ', 'qāla hal yasmaʿūnakum iḏ taʿdūn', 'Onlar, taptıklarınız, sizi işitiyorlar mı? dedi.'),
(26, 73, 19, 370, 'أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ', 'aw yanfaʿūnakum aw yaḍurrūna', 'Yoksa size fayda mı sağlarlar yahut zarar mı verirler?'),
(26, 74, 19, 370, 'قَالُوا۟ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ', 'qālū bal wajadnā ābāʾanā kaḏālika yafʿalūn', 'Dediler ki: Hayır, biz atalarımızı da böyle yaparken bulduk.'),
(26, 75, 19, 370, 'قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ', 'qāla afaraʾaytum mā kuntum taʿbudūn', 'Dediler ki: "Gördünüz mü, tapmakta olduğunuz şeyleri?'),
(26, 76, 19, 370, 'أَنتُمْ وَءَابَآؤُكُمُ ٱلْأَقْدَمُونَ', 'antum wa-ābāʾukumul-ʾaqdamūn', 'Siz ve geçmiş atalarınız.'),
(26, 77, 19, 370, 'فَإِنَّهُمْ عَدُوٌّ لِّىٓ إِلَّا رَبَّ ٱلْعَٰلَمِينَ', 'fa-ʾinnahum ʿaduwwun lī ʾillā rabb-a l-ʿālamīn', 'Çünkü onlar (putlar) âlemlerin Rabbi olan benim dışımda bana düşmandırlar.'),
(26, 78, 19, 370, 'ٱلَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ', 'alladhī khalaqanī fa-huwa yahdīn', 'O, beni yaratan, sonra da bana yol gösterendir.'),
(26, 79, 19, 370, 'وَٱلَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ', 'wa-lladhī huwa yuṭʿimunī wa-yasqīn', 'Ve O, benim hem doyuranım hem de sulayanımdır.'),
(26, 80, 19, 370, 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', 'wa ʾiḏā mariḍtu fa-huwa yašfīn', 'Ve hastalandığım zaman O, bana şifa verir.'),
(26, 81, 19, 370, 'وَٱلَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ', 'wa-lladhī yumītunī thumma yuḥyīn', 'Beni öldüren, sonra da (yeniden) dirilten O''dur.'),
(26, 82, 19, 370, 'وَٱلَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيٓـَٔتِى يَوْمَ ٱلدِّينِ', 'wa-lladhī ʾaṭmaʿu ʾan yaghfira lī khaṭīʾatī yawma d-dīn', 'Ve benim, din günü hatamı bağışlayacağını umduğum.'),
(26, 83, 19, 370, 'رَبِّ هَبْ لِى حُكْمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 'Rabbi hab li ḥukman Ve alḥiqni biṣ-ṣāliḥīn', 'Rabbim! Bana hüküm (hikmet) ver ve beni salihlerin arasına kat!'),
(26, 84, 19, 371, 'وَٱجْعَل لِّى لِسَانَ صِدْقٍ فِى ٱلْءَاخِرِينَ', 'wa-jʿal lī lisāna ṣidqin fī l-ʾākhirīn', 'Ve bana, sonrakiler arasında bir doğruluk dili (veya anılış) ver.'),
(26, 85, 19, 371, 'وَٱجْعَلْنِى مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ', 'wa-jʿalnī min warathati jannati n-naʿīm', 'Ve beni, Nîmât Cenneti''nin vârislerinden kıl.'),
(26, 86, 19, 371, 'وَٱغْفِرْ لِأَبِىٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ', 'wa-ġfir li-ʾabī ʾinnahu kāna mina ḍ-ḍāllīn', 'Babamı da bağışla; çünkü o, sapmışlardan idi.'),
(26, 87, 19, 371, 'وَلَا تُخْزِنِى يَوْمَ يُبْعَثُونَ', 'wa-lā tukhzinī yawma yubʿathūna', 'Onların (diriltilecekleri) o gün beni rezil rüsvâ etme!'),
(26, 88, 19, 371, 'يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ', 'yawma lā yanfaʿu mālun walā banūn', 'O gün, mal da, oğullar da fayda vermez.'),
(26, 89, 19, 371, 'إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍ سَلِيمٍ', 'illa men etā allāhe biqalbin salīm', 'Ancak Allah''a kalp selâmetiyle gelenler (bu azaptan kurtulur).'),
(26, 90, 19, 371, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ', 'wa-uzlifati l-jannatu li-l-muttaqīn', 'Ve takva sahipleri için cennet yaklaştırılmıştır.'),
(26, 91, 19, 371, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِلْغَاوِينَ', 'wa burrizati l-jaḥīmu lil-ghāwīn', 'Ve cehennem, azgınlar için açıkça ortaya konulmuştur.'),
(26, 92, 19, 371, 'وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ', 'wa qīla lahum ayna mā kuntum taʿbudūn', 'Onlara şöyle denir: ''Allah’tan başka taptıklarınız nerede?'''),
(26, 93, 19, 371, 'مِن دُونِ ٱللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ', 'min dūni llāh hal yanṣurūnakum aw yantaṣirūn', 'Allah''tan başka taptıklarınız size yardım edebilir mi, yahut kendileri yardım görebilirler mi?'),
(26, 94, 19, 371, 'فَكُبْكِبُوا۟ فِيهَا هُمْ وَٱلْغَاوُۥنَ', 'fakubkibū fīhā hum wal-ġāwūn', 'İşte onlar ve azgınlar hep birlikte oraya (cehenneme) atıldılar.'),
(26, 95, 19, 371, 'وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ', 'wa junūdu ʾiblīsa ʾajmaʿūn', 'Ve İblis''in bütün orduları da.'),
(26, 96, 19, 371, 'قَالُوا۟ وَهُمْ فِيهَا يَخْتَصِمُونَ', 'qālū wa hum fīhā yaḫtaṣimūn', 'Onlar, orada birbirleriyle tartışırlarken şöyle derler:'),
(26, 97, 19, 371, 'تَٱللَّهِ إِن كُنَّا لَفِى ضَلَٰلٍ مُّبِينٍ', 'tallāhi in kunnā lafī ḍalālin mubīn', 'Allah''a yemin ederim ki, biz gerçekten apaçık bir sapıklık içindeydik.'),
(26, 98, 19, 371, 'إِذْ نُسَوِّيكُم بِرَبِّ ٱلْعَٰلَمِينَ', 'idh nusawwīkum bi-rabb al-ʿālamīn', 'Hani sizi âlemlerin Rabbi ile bir tutuyorduk.'),
(26, 99, 19, 371, 'وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ', 've mā aḍallanā illā l-mujrimūn', 'Bizi ancak suçlular saptırmıştır.'),
(26, 100, 19, 371, 'فَمَا لَنَا مِن شَٰفِعِينَ', 'famā lanā min shāfiʿīn', 'Artık bizim için ne bir şefaatçi vardır'),
(26, 101, 19, 371, 'وَلَا صَدِيقٍ حَمِيمٍ', 'wa-lā ṣadīqin ḥamīmin', 'Ve candan bir dostu da (bulamaz).'),
(26, 102, 19, 371, 'فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'falaw anna lanā karratan fanakūna minal-muʾminīn', 'Keşke bizim için bir dönüş olsaydı da müminlerden olsaydık!'),
(26, 103, 19, 371, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'ʾinna fī ḏālika laʾāyatan wa-mā kāna ʾakṯaruhum muʾminīn', 'Şüphesiz bunda bir ibret vardır. Onların çoğu iman etmiş değillerdi.'),
(26, 104, 19, 371, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, engin merhamet sahibidir.'),
(26, 105, 19, 371, 'كَذَّبَتْ قَوْمُ نُوحٍ ٱلْمُرْسَلِينَ', 'kadhdhabat qawmu nūḥin l-mur''salīn', 'Nûh''un kavmi de peygamberleri yalanladı.'),
(26, 106, 19, 371, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ', 'idh qāla lahum akhūhum nūḥun alā tattaqūn', 'Hani kardeşleri Nuh onlara şöyle demişti: "Hiç Allah''tan korkmaz mısınız?"'),
(26, 107, 19, 371, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'ʾinnī lakum rasūlun ʾamīn', 'Şüphesiz ben, size gönderilmiş güvenilir bir elçiyim.'),
(26, 108, 19, 371, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fattaqūllāha waʾaṭīʿūnī', 'Öyleyse Allah''tan korkun ve bana itaat edin.'),
(26, 109, 19, 371, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 've-mā esʾelukum ʿalayhi min ecri in ecriye illā ʿalā rabbi l-ʿālemīn', 'Buna karşılık sizden bir ücret istemiyorum. Benim ecrim ancak âlemlerin Rabbi''ne aittir.'),
(26, 110, 19, 371, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fattaqū Allāha wa ʾaṭīʿūnī', 'Artık siz Allah''tan korkun ve bana itaat edin.'),
(26, 111, 19, 371, 'قَالُوٓا۟ أَنُؤْمِنُ لَكَ وَٱتَّبَعَكَ ٱلْأَرْذَلُونَ', 'qālū ʾanūʾminu laka wa-ttabaʿaka l-ʾarẓalūna', 'Dediler ki: "Sana mı iman edelim? Sana, en aşağı kimseler tabi olmuştur."'),
(26, 112, 19, 372, 'قَالَ وَمَا عِلْمِى بِمَا كَانُوا۟ يَعْمَلُونَ', 'qāla wa mā ʿilmī bimā kānū yaʿmalūn', 'Dedi ki: "Onların ne yaptıklarını bilmem ben!"'),
(26, 113, 19, 372, 'إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى لَوْ تَشْعُرُونَ', 'ʾin ḥisābuhum ʾillā ʿalā rabbī law tasʿurūn', 'Onların hesabı, ancak Rabbim''in üzerindedir; bir bilebilseniz!'),
(26, 114, 19, 372, 'وَمَآ أَنَا۠ بِطَارِدِ ٱلْمُؤْمِنِينَ', 'wa mā anā biṭāridi l-muʾminīn', 'Ben müminleri kovacak değilim.'),
(26, 115, 19, 372, 'إِنْ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', 'ʾin ʾanā ʾillā naḏīrun mubīnun', 'Ben, apaçık bir uyarıcıdan başkası değilim.'),
(26, 116, 19, 372, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلْمَرْجُومِينَ', 'qālū laʾin lam tantahi yā nūḥu latakūnanna mina l-marjūmīn', 'Dediler ki: ''Ey Nuh! Eğer vazgeçmezsen, andolsun ki taşlananlardan olacaksın!'''),
(26, 117, 19, 372, 'قَالَ رَبِّ إِنَّ قَوْمِى كَذَّبُونِ', 'qāla rabbi ʾinna qawmī kaḏḏabūn', '«Rabbim! Kavmim beni yalanladı.»'),
(26, 118, 19, 372, 'فَٱفْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًا وَنَجِّنِى وَمَن مَّعِىَ مِنَ ٱلْمُؤْمِنِينَ', 'fa-ftaḥ baynī wa-baynahum fatḥan wa-najjinī wa-man maʿiya mina l-muʾminīn', 'Ey Rabbim! Benimle onların arasını adil bir şekilde aç (hükmünü ver) ve beni ve beraberimdeki mü''minleri kurtar!'),
(26, 119, 19, 372, 'فَأَنجَيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'faʾanjaynāhu wa man maʿahu fī l-fulki l-mašḥūn', 'Böylece onu ve onunla birlikte gemide bulunanları kurtardık.'),
(26, 120, 19, 372, 'ثُمَّ أَغْرَقْنَا بَعْدُ ٱلْبَاقِينَ', 'thumma aghraqnā baʿdu l-bāqīn', 'Sonra diğerlerini boğduk.'),
(26, 121, 19, 372, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'inna fī dhālika laʾāyatan wa mā kāna aktharuhum muʾminīn', 'Şüphesiz bunda bir ayet vardır. Onların çoğu iman etmiş değillerdi.'),
(26, 122, 19, 372, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, engin merhamet sahibidir.'),
(26, 123, 19, 372, 'كَذَّبَتْ عَادٌ ٱلْمُرْسَلِينَ', 'kaḏḏabat ʿādu l-murselīn', 'Ad kavmi de peygamberleri yalanladı.'),
(26, 124, 19, 372, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ', 'idh qāla lahum akhūhum Hūdun alā tattaqūna', 'Hani kardeşleri Hûd onlara şöyle demişti: "Hâlâ Allah’tan korkmaz mısınız?"'),
(26, 125, 19, 372, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'ʾinnī lakum rasūlun ʾamīn', 'Şüphesiz ben, size gönderilmiş güvenilir bir elçiyim.'),
(26, 126, 19, 372, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fattaqū Allāh wa ʾaṭīʿūn', 'Artık Allah''tan korkun ve bana itaat edin.'),
(26, 127, 19, 372, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 've mâ esʾelukum ʿaleyhi min ecri in ecriye illâ ʿalâ rabbil-ʿâlemîn', 'Buna karşılık sizden bir ücret istemiyorum. Benim ecrim ancak âlemlerin Rabbi''ne aittir.'),
(26, 128, 19, 372, 'أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ', 'ʾatabnūna bikulli rīʿin ʾāyatan taʿbathūna', 'Siz her tepenin başına birer bina mı yapıyorsunuz ki boş yere oyalanıp duruyorsunuz?'),
(26, 129, 19, 372, 'وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ', 'wa tattakhidhūna maṣāniʿa laʿallakum takhludūna', 'Ve siz, sanki sonsuza dek yaşayacakmış gibi, saraylar ve kaleler edininiyorsunuz.'),
(26, 130, 19, 372, 'وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ', 'wa-idhā baṭashtum baṭashtum jabbārīn', 'Ancak (birini) yakaladığınız zaman, zorba bir zorba olarak yakalarsınız.'),
(26, 131, 19, 372, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fa-ttaqū Allāha wa-aṭīʿūnī', 'Artık Allah''tan korkun ve bana itaat edin.'),
(26, 132, 19, 372, 'وَٱتَّقُوا۟ ٱلَّذِىٓ أَمَدَّكُم بِمَا تَعْلَمُونَ', 'wa-ttaqū alladhī ʾamaddakum bimā taʿlamūn', 'Ve bildiğiniz şeylerle size yardım eden Allah''tan korkup sakının.'),
(26, 133, 19, 372, 'أَمَدَّكُم بِأَنْعَٰمٍ وَبَنِينَ', 'amaddakum bi-anʿāmin wa-banīn', 'Hem size hayvanlar ve oğullar ile destek vermiştir.'),
(26, 134, 19, 372, 'وَجَنَّٰتٍ وَعُيُونٍ', 'wa-jannātin wa-ʿuyūnin', 'Ve bahçeler ve pınarlar!'),
(26, 135, 19, 372, 'إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'ʾinnī ʾakhāfu ʿalaykum ʿadhāba yawmin ʿaẓīm', 'Şüphesiz ben, sizin için büyük bir günün azabından korkarım.'),
(26, 136, 19, 372, 'قَالُوا۟ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ ٱلْوَٰعِظِينَ', 'qālū sawāʾun ʿalaynā a-waʿaẓta am lam takun mina l-wāʿiẓīn', 'Dediler ki: ''Bize öğüt versen de, öğüt verenlerden olmasan da fark etmez.'''),
(26, 137, 19, 373, 'إِنْ هَٰذَآ إِلَّا خُلُقُ ٱلْأَوَّلِينَ', 'in hādhā illā khuluqu l-ʾawwalīn', 'Bu, gerçekten öncekilerin âdetlerinden başkası değildir.'),
(26, 138, 19, 373, 'وَمَا نَحْنُ بِمُعَذَّبِينَ', 'wa mā naḥnu bimuʿaḏḏibīn', 'Ve biz azap olunacak kimseler değiliz.'),
(26, 139, 19, 373, 'فَكَذَّبُوهُ فَأَهْلَكْنَٰهُمْ إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'fa-kaḏḏabūhu fa-ahlaknāhum ʾinna fī ḏālika la-ʾāyatan wa-mā kāna ʾakṯaruhum muʾminīn', 'Böylece onları yalanladılar. Biz de onları helak ettik. Şüphesiz bunda bir ibret vardır. Onların çoğu iman etmiş değillerdi.'),
(26, 140, 19, 373, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, engin merhamet sahibidir.'),
(26, 141, 19, 373, 'كَذَّبَتْ ثَمُودُ ٱلْمُرْسَلِينَ', 'kadhabat thamūdu l-mur''salīn', 'Semûd (kavmi) de peygamberleri yalanladı.'),
(26, 142, 19, 373, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ صَٰلِحٌ أَلَا تَتَّقُونَ', 'idh qāla lahum akhūhum ṣāliḥun alā tattaqūn', 'Hani onlara kardeşleri Salih: "Allah''tan korkmaz mısınız?" demişti.'),
(26, 143, 19, 373, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'innī lakum rasūlun amīn', 'Şüphesiz ben, sizin için gönderilmiş güvenilir bir elçiyim.'),
(26, 144, 19, 373, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fattaqū Allāha wa ʾaṭīʿūnī', 'Artık Allah''tan korkun ve bana itaat edin.'),
(26, 145, 19, 373, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 've mā asʾalukum ʿalayhi min ʾajrin ʾin ʾajriya ʾillā ʿalā rabbi l-ʿālamīn', 'Buna karşılık sizden bir ücret istemiyorum. Benim ecrim ancak âlemlerin Rabbi''ne aittir.'),
(26, 146, 19, 373, 'أَتُتْرَكُونَ فِى مَا هَٰهُنَآ ءَامِنِينَ', 'ʾatu-trakūna fī mā hāhunā ʾāminīn', 'Sizi burada güvende mi bırakacaklar?'),
(26, 147, 19, 373, 'فِى جَنَّٰتٍ وَعُيُونٍ', 'fī jannātin wa ʿuyūnin', 'Nice bahçeler ve pınarlar içindedirler.'),
(26, 148, 19, 373, 'وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ', 'wa-zurūʿin wa-nakhlin ṭalʿuhā haḍīm', 'Ve ekinler ve salkımları olgunlaşmış hurma ağaçları.'),
(26, 149, 19, 373, 'وَتَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا فَٰرِهِينَ', 'wa tanḥitūna mina l-jibāli buyūtan fārihīn', 'Dağlardan evler oyuyorsunuz, bir gurur ve sevinç içinde.'),
(26, 150, 19, 373, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fāttaqū Allāha wa ʾaṭīʿūnī', 'Artık Allah''tan korkun ve bana itaat edin.'),
(26, 151, 19, 373, 'وَلَا تُطِيعُوٓا۟ أَمْرَ ٱلْمُسْرِفِينَ', 'wa lā tuṭīʿū amra l-musrifīn', 'Ve haddi aşanların emrine uymayın.'),
(26, 152, 19, 373, 'ٱلَّذِينَ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', 'alladhīna yufsidūna fī l-arḍi wa lā yuṣliḥūna', 'Onlar ki, yeryüzünde fesat çıkarırlar ve ıslah etmezler.'),
(26, 153, 19, 373, 'قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ', 'qālū innamā anta mina l-musahharīn', 'Dediler ki: "Sen ancak büyülenmişlerden birisin."'),
(26, 154, 19, 373, 'مَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'mā anta illā basharun mithlunā faʾti biʾāyatin in kunta mina ṣ-ṣādiqīn', 'Sen ancak bizim gibi bir insansın. Eğer doğru sözlülerden isen, bize bir ayet (mucize) getir.'),
(26, 155, 19, 373, 'قَالَ هَٰذِهِۦ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ', 'qāla hādhihi nāqatun lahā shirbun walakum shirbu yawmin maʿlūmin', 'Dedi ki: "İşte bu, bir dişi deve; suvarılması da bir gün sizin, bir gün de bizimdir."'),
(26, 156, 19, 373, 'وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ', 'wa lā tamassūhā bisūʾin fayaʾkhudhakum ʿadhābu yawmin ʿaẓīmin', 'Ona kötülükle dokunmayın ki, sonra sizi büyük bir günün azabı yakalamasın.'),
(26, 157, 19, 373, 'فَعَقَرُوهَا فَأَصْبَحُوا۟ نَٰدِمِينَ', 'faʿaqarūhā faʾaṣbaḥū nādimīn', 'Böylece deveyi kestiler. Sonra da pişman oldular.'),
(26, 158, 19, 373, 'فَأَخَذَهُمُ ٱلْعَذَابُ إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'faʾakhaḏahumu l-ʿaḏābu ʾinna fī ḏālika laʾāyatan wa-mā kāna ʾakṯaruhum muʾminīna', 'Nihayetinde onlara o azap geldi. Şüphesiz bunda bir ibret vardır. Ama onların çoğu iman etmiş değildi.'),
(26, 159, 19, 373, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, engin merhamet sahibidir.'),
(26, 160, 19, 374, 'كَذَّبَتْ قَوْمُ لُوطٍ ٱلْمُرْسَلِينَ', 'kadhabat qawmu lūṭin al-mursalin', 'Lût kavmi de peygamberleri yalanladı.'),
(26, 161, 19, 374, 'إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ', 'idh qāla lahum akhūhum Lūṭun alā tattaqūna', 'Hani onlara kardeşleri Lût şöyle demişti: "Allah''tan korkmaz mısınız?"'),
(26, 162, 19, 374, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'ʾinnī lakum rasūlun ʾamīn', 'Şüphesiz ben, size gönderilmiş güvenilir bir elçiyim.'),
(26, 163, 19, 374, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'fattaqū Allāha wa ʾaṭīʿūnī', 'Şimdi sizden Allah''tan korkup bana itaat edin.'),
(26, 164, 19, 374, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 'wa mā as''alukum ʿalayhi min ʾajrin ʾin ʾajriya ʾillā ʿalā rabbi l-ʿālamīn', 'Buna karşılık sizden bir ücret istemiyorum. Benim ecrim ancak âlemlerin Rabbi''ne aittir.'),
(26, 165, 19, 374, 'أَتَأْتُونَ ٱلذُّكْرَانَ مِنَ ٱلْعَٰلَمِينَ', 'ʾataʾtūna ḏ-ḏukrāna mina l-ʿālamīn', 'Alemlerden erkeklere mi yaklaşıyorsunuz?'),
(26, 166, 19, 374, 'وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَٰجِكُم بَلْ أَنتُمْ قَوْمٌ عَادُونَ', 've tadhurūna mā khalaqa lakum rabbukum min azwājikum bal antum qawmun ʿādūna', 'Ve Rabbinizin sizin için yaratmış olduğu eşlerinizi bırakıp da... Hayır, siz azgın bir topluluksunuz.'),
(26, 167, 19, 374, 'قَالُوا۟ لَئِن لَّمْ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلْمُخْرَجِينَ', 'qālū laʾin lam tantahi Lūṭu latakūnnanna mina l-mukhrajīna', 'Dediler ki: "Ey Lût! Eğer vazgeçmezsen, mutlaka (yurdumuzdan) sürülenlerden olacaksın."'),
(26, 168, 19, 374, 'قَالَ إِنِّى لِعَمَلِكُم مِّنَ ٱلْقَالِينَ', 'qāla innī liʿamalikum mina l-qālin', 'Dedi ki: "Şüphesiz ben sizin yaptıklarınızdan tiksinip nefret edenlerdenim."'),
(26, 169, 19, 374, 'رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ', 'Rabbî neccinî ve ehli mimmâ yaʿmalûn', 'Rabbim! Beni ve ailemi onların yapmakta olduklarından kurtar.'),
(26, 170, 19, 374, 'فَنَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'fa-najjaynāhu wa-ahlahu ajmaʿīn', 'Böylece onu ve bütün ailesini kurtardık.'),
(26, 171, 19, 374, 'إِلَّا عَجُوزًا فِى ٱلْغَٰبِرِينَ', 'illa ʿajūzan fī l-ġābirīn', 'Ancak yaşlı bir kadın hariç, geride kalanlar arasında.'),
(26, 172, 19, 374, 'ثُمَّ دَمَّرْنَا ٱلْءَاخَرِينَ', 'thumma dammarnā l-ʾākhirīn', 'Sonra diğerlerini helak ettik.'),
(26, 173, 19, 374, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'wa-amṭarnā ʿalayhim maṭaran fasāʾa maṭaru l-munḏarīn', 'Ve üzerlerine bir yağmur indirdik. İşte o uyarılanların yağmuru ne kötü!'),
(26, 174, 19, 374, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'ʾinna fī ḏālika la-ʾāyatan wa-mā kāna ʾakṯaruhum muʾminīn', 'Şüphesiz bunlarda bir ayet vardır, ama çoğu iman etmezler.'),
(26, 175, 19, 374, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'wa-ʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, sonsuz merhamet sahibidir.'),
(26, 176, 19, 374, 'كَذَّبَ أَصْحَٰبُ لْـَٔيْكَةِ ٱلْمُرْسَلِينَ', 'kaḏḏaba aṣḥābu l-ʾaykati l-murselīn', 'Eyke Ashabı da peygamberleri yalanladı.'),
(26, 177, 19, 374, 'إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ', 'idh qāla lahum shuʿaybun alā tattaqūn', 'Şuayb onlara şöyle dediği zaman: "Hiç Allah''tan korkmaz mısınız?"'),
(26, 178, 19, 374, 'إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'ʾinnī lakum rasūlun ʾamīn', 'Şüphesiz ben, size gönderilmiş güvenilir bir elçiyim.'),
(26, 179, 19, 374, 'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'Fattaqū Allāh Wa aṭīʿūnī', 'Artık Allah’tan korkun ve bana itaat edin.'),
(26, 180, 19, 374, 'وَمَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ ٱلْعَٰلَمِينَ', 've mā ʾasʾalukum ʿalayhi min ʾajrin ʾin ʾajriya ʾillā ʿalā rabbi l-ʿālamīn', 'Buna karşılık sizden bir ücret istemiyorum. Benim ecrim ancak âlemlerin Rabbi''ne aittir.'),
(26, 181, 19, 374, 'أَوْفُوا۟ ٱلْكَيْلَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُخْسِرِينَ', 'awfū l-kayla wa lā takūnū min al-mukhsirīn', 'Ölçüyü tam yapın ve (hakkı) eksiltenlerden olmayın.'),
(26, 182, 19, 374, 'وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ', 'wa-zinū bi-l-qisṭāsi l-mustaqīm', 'Ve teraziyle, dosdoğru tartın.'),
(26, 183, 19, 374, 'وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'wa lā tabkhasū an-nāsa ʾashyāʾahum wa lā taʿthaw fī al-ʾarḍi mufsidīn', 'İnsanların eşyalarını eksik tartmayın ve yeryüzünde bozgunculuk yaparak fesat çıkarmayın.'),
(26, 184, 19, 375, 'وَٱتَّقُوا۟ ٱلَّذِى خَلَقَكُمْ وَٱلْجِبِلَّةَ ٱلْأَوَّلِينَ', 'wa-ttaqū alladhī khalaqakum wa-l-jibillata l-awwalīn', 'Sizi ve daha önceki nesilleri yaratanı takva sahibi olun.'),
(26, 185, 19, 375, 'قَالُوٓا۟ إِنَّمَآ أَنتَ مِنَ ٱلْمُسَحَّرِينَ', 'qālū innamā anta mina l-musahharīn', 'Dediler ki: "Sen ancak büyülenmişlerdensin!"'),
(26, 186, 19, 375, 'وَمَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلْكَٰذِبِينَ', 've-mā anta illā beşerun miṯluna ve-in naẓunnuke le-mine-l-kāẕibīn', 'Oysa sen de bizim gibi bir insansın. Ve biz seni kesinlikle yalancılardan sanıyoruz.'),
(26, 187, 19, 375, 'فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'faʾsqiṭ ʿalaynā kisafan mina s-samāʾi ʾin kunta mina ṣ-ṣādiqīn', 'Eğer doğru sözlülerden isen, üzerimize gökten parçalar düşür!'),
(26, 188, 19, 375, 'قَالَ رَبِّىٓ أَعْلَمُ بِمَا تَعْمَلُونَ', 'qāla rabbī ʾaʿlamu bimā taʿmalūn', 'Rabbim, yaptıklarınızı en iyi bilendir.'),
(26, 189, 19, 375, 'فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ ٱلظُّلَّةِ إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ', 'fa-kaḏḏabūhu fa-ʾaḵaḏahum ʿaḏābu yawmi ẓ-ẓullati ʾinnahu kāna ʿaḏāba yawmin ʿaẓīmin', 'Böylece onu yalanladılar. Nihayet, o gölgelik (günü) azabı onları yakaladı. Gerçekten o, büyük bir günün azabı idi.'),
(26, 190, 19, 375, 'إِنَّ فِى ذَٰلِكَ لَءَايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 'inna fī dhālika la''āyatan wa mā kāna aktharuhum mu''minīn', 'Şüphesiz bunda (bu olayda) bir ibret vardır. Onların çoğu iman etmiş değillerdi.'),
(26, 191, 19, 375, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'waʾinna rabbaka lahuwa l-ʿazīzu r-raḥīmu', 'Şüphesiz Rabbin, mutlak güç sahibi, engin merhamet sahibidir.'),
(26, 192, 19, 375, 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلْعَٰلَمِينَ', 'waʾinnahu latanzīlu rabbi l-ʿālamīn', 'Gerçekten o (Kur''an), âlemlerin Rabbi tarafından indirilmiştir.'),
(26, 193, 19, 375, 'نَزَلَ بِهِ ٱلرُّوحُ ٱلْأَمِينُ', 'nazala bihi r-rūḥu l-ʾamīn', 'Onu, Rûh-ul Emîn (Cebrail) indirdi.'),
(26, 194, 19, 375, 'عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ ٱلْمُنذِرِينَ', 'ʿalā qalbika litakūna mina l-munḏirīn', 'Seni, korkutuculardan olasın diye, kalbine indirilmiştir.'),
(26, 195, 19, 375, 'بِلِسَانٍ عَرَبِىٍّ مُّبِينٍ', 'bi lisānin ʿarabiyyin mubīn', 'Apaçık Arapça bir dil ile.'),
(26, 196, 19, 375, 'وَإِنَّهُۥ لَفِى زُبُرِ ٱلْأَوَّلِينَ', 'wa ʾinnahu la fī zuburi l-ʾawwalīn', 'Ve şüphesiz ki o (Kur''an), öncekilerin kitaplarında da vardır.'),
(26, 197, 19, 375, 'أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَٰٓؤُا۟ بَنِىٓ إِسْرَٰٓءِيلَ', 'awalam yakun lahum āyatan an yaʿlamahu ʿulamāʾu banī isrāʾīl', 'İsrailoğulları''nın alimlerinin onu bilmesi, kendileri için bir delil değil miydi?'),
(26, 198, 19, 375, 'وَلَوْ نَزَّلْنَٰهُ عَلَىٰ بَعْضِ ٱلْأَعْجَمِينَ', 'wa-law nazzalnāhu ʿalā baʿḍi l-ʾaʿjamīn', 'Onu Acemlerden (Arap olmayanlardan) bir kısmına indirseydik,'),
(26, 199, 19, 375, 'فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا۟ بِهِۦ مُؤْمِنِينَ', 'faqaraʾahu ʿalayhim mā kānū bihi muʾminīn', 'Onlara okudu; yine de ona inanmıyorlardı.'),
(26, 200, 19, 375, 'كَذَٰلِكَ سَلَكْنَٰهُ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 'kadhalika salaknāhu fī qulūbi l-mujrimīn', 'Böylece onu, suçluların kalplerine sokarız.'),
(26, 201, 19, 375, 'لَا يُؤْمِنُونَ بِهِۦ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 'lā yuʾminūna bihi ḥattā yarawu l-ʿadhāba l-ʾalīm', 'Ona inanmazlar, tâ ki o acıklı azabı görüp de inanırlar.'),
(26, 202, 19, 375, 'فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'fa-yaʾtiyahum baghtatan wa-hum lā yashʿurūn', 'Derken, hiç farkında olmadıkları bir sırada onlara ansızın geliverir.'),
(26, 203, 19, 375, 'فَيَقُولُوا۟ هَلْ نَحْنُ مُنظَرُونَ', 'feyeqūlū hel naḥnu munẓarūn', 'Bunun üzerine şöyle derler: ''Bize mühlet mi verilecek?'''),
(26, 204, 19, 375, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'ʾafabiʿaḏābinā yastaʿjilūn', 'Onlar azabımızın çarçabuk gelmesini mi istiyorlar?'),
(26, 205, 19, 375, 'أَفَرَءَيْتَ إِن مَّتَّعْنَٰهُمْ سِنِينَ', 'Afa ra''ayta in metta''nahum sineen', 'Söyle onlara: Eğer onları yıllarca (dünya nimetlerinden) faydalandırsak...'),
(26, 206, 19, 375, 'ثُمَّ جَآءَهُم مَّا كَانُوا۟ يُوعَدُونَ', 'thumma jāʾahum mā kānū yūʿadūn', 'Sonra kendilerine vaad olunan şey geldi.'),
(26, 207, 19, 376, 'مَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يُمَتَّعُونَ', 'Mā aġnā ʿanhum mā kānū yumattaʿūn', 'Onları, içinde bulundukları zevk ve refah dünyalığı hiç fayda sağlamadı.'),
(26, 208, 19, 376, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ', 'Ve mā ahlaknā min karyatin illā lehā munzirūn', 'Biz hiçbir memleketi, kendilerine uyarıcılar olmaksızın helak etmedik.'),
(26, 209, 19, 376, 'ذِكْرَىٰ وَمَا كُنَّا ظَٰلِمِينَ', 'Ḏikrâ Ve mâ kunnâ ẓâlimîn', 'Bir öğüt olarak (böyle yaptık). Biz zalimler değiliz.'),
(26, 210, 19, 376, 'وَمَا تَنَزَّلَتْ بِهِ ٱلشَّيَٰطِينُ', 'wa mā tanazzalat bihi sh-shayāṭīn', 'Onu (Kur''an''ı) şeytanlar indirmemiştir.'),
(26, 211, 19, 376, 'وَمَا يَنۢبَغِى لَهُمْ وَمَا يَسْتَطِيعُونَ', 'wa mā yanbaghī lahum wa mā yastaṭīʿūn', 'Onlara yaraşmaz ve güçleri de yetmez.'),
(26, 212, 19, 376, 'إِنَّهُمْ عَنِ ٱلسَّمْعِ لَمَعْزُولُونَ', 'innahum ''ani s-sam''i la ma''zūlūn', 'Onlar, (Kur''an''ı) dinlemekten kesinlikle uzaklaştırılmışlardır.'),
(26, 213, 19, 376, 'فَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلْمُعَذَّبِينَ', 'falā tadʿu maʿa llāhi ilāhan ʾākhara fatakūna mina l-muʿaḏḏibīn', 'Allah ile beraber başka bir ilaha tapma, yoksa azap edilenlerden olursun.'),
(26, 214, 19, 376, 'وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ', 'wa-ʾanẓir ʿašīrataka ʾl-ʾaqrabīn', 'Akraba yakınlarını uyar.'),
(26, 215, 19, 376, 'وَٱخْفِضْ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'wa-khfiḍ janāḥaka limani-ttabaʿaka mina l-muʾminīn', 'Ve sana uyan mü''minlere karşı gönlünü alçalt.'),
(26, 216, 19, 376, 'فَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', 'fa-ʾin ʿaṣawka fa-qul ʾinnī barīʾum mimmā taʿmalūn', 'Eğer sana isyan ederlerse, de ki: "Ben sizin yapmakta olduklarınızdan uzağım."'),
(26, 217, 19, 376, 'وَتَوَكَّلْ عَلَى ٱلْعَزِيزِ ٱلرَّحِيمِ', 'wa tawakkal ʿalā l-ʿazīzi r-raḥīmi', 'Ve mutlak galip, esirgeyen o (Allah''a) güven. (217)'),
(26, 218, 19, 376, 'ٱلَّذِى يَرَىٰكَ حِينَ تَقُومُ', 'alladhī yarāka ḥīna taqūm', 'O, seni namaza kalktığın zaman görür.'),
(26, 219, 19, 376, 'وَتَقَلُّبَكَ فِى ٱلسَّٰجِدِينَ', 'wa taqallubaka fī s-sājidīn', 'Ve secde edenlerin arasındaki dolaşmanı (da görsün).'),
(26, 220, 19, 376, 'إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'ʾinnahuu huwa s-samīʿu l-ʿalīm', 'Şüphesiz O, hakkıyla işitendir, hakkıyla bilendir.'),
(26, 221, 19, 376, 'هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ', 'hal unabbiʾukum ʿalā man tanazzalu ʾl-shayāṭīn', 'Şeytanların kime indiğini size haber vereyim mi?'),
(26, 222, 19, 376, 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍ', 'tanaẕẕelu ʿalā kulli ʾeffākin ʾeṯīm', 'Onlar, her günahkâr yalancıya iner.'),
(26, 223, 19, 376, 'يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ', 'yul''qūna s-sam''a wa-aktharuhum kādhibūn', 'Onlar (şeytanlar) gizlice kulak kabartırlar ve onların çoğu yalancıdır.'),
(26, 224, 19, 376, 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ', 'wa-sh-shuʿarāʾu yattabiʿuhumu l-ghāwūn', 'Şairlere gelince, onlara da sapkınlar uyar.'),
(26, 225, 19, 376, 'أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ', 'ʾelem tere ʾennehum fī kulli wādin yehīmūn', 'Onların her vadiye daldıklarını görmedin mi?'),
(26, 226, 19, 376, 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', 'waʾannahum yaqūlūna mā lā yafʿalūna', 'Ve onların, yapmadıklarını söyledikleri.'),
(26, 227, 19, 376, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ', 'illa alladhīna ʾāmanū wa ʿamilū aṣ-ṣāliḥāti wa dhakarū allāha kathīran wa-ntasarū min baʿdi mā ẓulimū wa sa-yaʿlamu alladhīna ẓalamū ʾayya munqalabin yanqalibūn', 'Ancak iman edip salih amel işleyenler, Allah''ı çok zikredenler ve kendilerine zulmedildikten sonra (hakkını) savunanlar bunun dışındadır. Zulmedenler, yakında hangi akıbete uğrayacaklarını bileceklerdir.'),
(27, 1, 19, 377, 'طسٓ تِلْكَ ءَايَٰتُ ٱلْقُرْءَانِ وَكِتَابٍ مُّبِينٍ', 'Ṭā, Sīn tilke ʾāyātu l-qurʾāni wa-kitābin mubīnin', 'Tâ, Sîn. Bunlar Kur''an''ın ve apaçık olan bir kitabın âyetleridir.'),
(27, 2, 19, 377, 'هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'hudan wa bushra lilmu''minīn', 'Mü''minler için bir hidayet ve müjde olarak.'),
(27, 3, 19, 377, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 'alladhīna yuqīmūna ṣ-ṣalāta wa yuʾtūna z-zakāta wa hum bil-ʾākhirati hum yūqinūna', 'Onlar, namazı dosdoğru kılan, zekâtı veren ve ahirete de kesin olarak iman edenlerdir.'),
(27, 4, 19, 377, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَٰلَهُمْ فَهُمْ يَعْمَهُونَ', 'ʾinna lladhīna lā yuʾminūna bil-ʾākhirati zayyanā lahum ʾaʿmālahum fahum yaʿmahūna', 'Ahiret''e inanmayanların, yaptıkları işleri kendilerine güzel gösterdik; böylece onlar (bu yüzden) şaşkınlık içinde bocalar dururlar.'),
(27, 5, 19, 377, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', 'ʾūlāʾika lladhīna lahum sūʾu lʿadhābi wahum fī lʾākhirati humu lʾakhsarūna', 'İşte onlara dünyada da kötü azap vardır; ahirette ise en çok hüsrana uğrayanlar onlardır.'),
(27, 6, 19, 377, 'وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ', 'waʾinnaka latulqqā l-qurʾāna min ladun ḥakīmin ʿalīmin', 'Şüphesiz ki sen, Kur''an''ı, hüküm ve hikmet sahibi, her şeyi bilen Allah katından alıyorsun.'),
(27, 7, 19, 377, 'إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ', 'idh qāla mūsā li-ʾahlihi ʾinnī ʾānastu nāran sa-ʾātiykum minhā bi-khabarin ʾaw ʾātiykum bi-shihābin qabasin laʿallakum taṣṭalūna', 'Hani Musa ailesine şöyle demişti: "Ben bir ateş gördüm. Size oradan bir haber getireceğim veya ısınmanız için bir kor getireceğim."'),
(27, 8, 19, 377, 'فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'felemmā jāʾahā nūdiya an būrika man fī n-nāri wa man ḥawlahā wa subḥāna llāhi rabbi l-ʿālamīn', 'Böylece oraya geldiğinde, şöyle seslenildi: Ateşin (bulunduğu yerin) etrafındakiler ve etrafında bulunanlar mübarek kılınmıştır! Ve âlemlerin Rabbi Allah, her türlü kusurdan münezzehtir!'),
(27, 9, 19, 377, 'يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'Yā Mūsā innahu anā Allāhu l-ʿazīzu l-ḥakīm(u)', 'Ey Musa! Gerçek şu ki, Ben Allah''ım, Azîz''im, Hakîm''im.'),
(27, 10, 19, 377, 'وَأَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ', 'wa-ʾalqi ʿaṣāk fa-lammā raʾāhā tahtazzu ka-ʾannahā jānnun wa-wallā mudbiran wa-lam yuʿaqqib yā Mūsā lā taḫaf ʾinnī lā yaḫāfu ladayya l-mursilūn', 'Değneğini at! Değneği bir yılan gibi kımıldadığını görünce, arkasına bakmadan kaçtı. "Ey Musa! Korkma! Şüphesiz benim yanımda peygamberler korkmaz."'),
(27, 11, 19, 377, 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ', 'illa men ẓalame thumma beddele ḥusnan baʿda sūʾin faʾinnī ġafūrun raḥīmun', 'Ancak zulmeden, sonra da zülmü iyilikle değiştiren kimse (bu hükmün dışındadır). Şüphesiz ben çok bağışlayan, çok merhamet edenim.'),
(27, 12, 19, 377, 'وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ فِى تِسْعِ ءَايَٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'wa-ʾadkhil yadaka fī jaybika takharju bayḍāʾa min ghayri sūʾin fī tisʿi ʾāyātin ʾilā firʿawna wa-qawmihī ʾinnahum kānū qawman fāsiqīn', 'Elini koynuna sok, kusursuz bembeyaz bir halde çıksın. Bunlar, Firavun ve kavmine (gösterilecek) dokuz mu''cizeden biridir. Çünkü onlar yoldan çıkmış bir kavim olmuşlardı.'),
(27, 13, 19, 377, 'فَلَمَّا جَآءَتْهُمْ ءَايَٰتُنَا مُبْصِرَةً قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ', 'felemmā jāʾethum ʾāyātunā mubṣiratan qālū hādhā siḥrun mubīnun', 'Nihayet onlara apaçık deliller (ayetlerimiz) geldiğinde, dediler ki: "Bu, apaçık bir sihirdir."'),
(27, 14, 19, 378, 'وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 'wa jaha-doo bi-ha wa-staiqanat-ha anfusuhum ẓulman wa ʿuluwwan fa-nẓur kayfa kāna ʿāqibatu l-mufsidīn', 'Onu (o mucizeyi) kalpleriyle kabul ettikleri halde, zulüm ve kibirlerinden ötürü onu inkâr ettiler. Bozguncuların sonunun nasıl olduğuna bir bak!'),
(27, 15, 19, 378, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَٰنَ عِلْمًا وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ', 'Ve lekad āteynā Dāvūde ve Suleymāne ʿilmā Ve qālā el-ḥamdu lillāhi elleẕī faḍḍalanā ʿalā kaṯīrin min ʿibādihi el-muʾminīn', 'Andolsun ki Davud''a ve Süleyman''a ilim verdik. Onlar da dediler ki: "Hamd, bizi mümin kullarının birçoğundan üstün kılan Allah''a mahsustur."'),
(27, 16, 19, 378, 'وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ إِنَّ هَٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ', 'wa waritha sulaymānu dāwūda wa qāla yā ayyuhā an-nāsu ʿullimnā manṭiqa aṭ-ṭayri wa ūtīnā min kulli shayʾin ʾinna hādhā lahuwa al-faḍlu al-mubīnu', 'Süleyman, Davud''a varis oldu ve şöyle dedi: "Ey insanlar! Bize kuş dili öğretildi ve bize her şeyden (bolca) verildi. Şüphesiz bu, apaçık bir lütuftur."'),
(27, 17, 19, 378, 'وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ', 'wa ḥushira li-Sulaymāna junūduhu min al-jinni wal-insi waṭ-ṭayri fa-hum yūzaʿūna', 'Süleyman''ın, cinlerden, insanlardan ve kuşlardan oluşan orduları toplandı. Hepsi bir arada tutuluyordu.'),
(27, 18, 19, 378, 'حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌ يَٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ', 'ḥattā iḏā ataw ʿalā wādi n-namli qālat namlatun yā ayyuhā n-namlu d-xulū masākinakum lā yaḥṭimannakum Sulaymānu wa-junūduhū wa-hum lā yašʿurūn', 'Nihayet karınca vadisine geldikleri zaman, bir karınca dedi ki: "Ey karıncalar! Yuvalarınıza girin; Süleyman ve orduları farkında olmadan sizi ezmesin!"'),
(27, 19, 19, 378, 'فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّٰلِحِينَ', 'fa-tabassama ḍāḥikan min qawlihā wa-qāla rabbi awziʿnī an ashkura niʿmata-ka allatī anʿamta ʿalayya wa-ʿalā wālidayya wa-an aʿmala ṣāliḥan tarḍāhu wa-adkhilnī bi-raḥmati-ka fī ʿibādi-ka ṣ-ṣāliḥīn', 'Bunun üzerine (Süleyman) dediğine gülümseyerek sevindi ve "Rabbim! Bana ve ana babama verdiğin nimetlere şükretmemi ve razı olacağın salih ameller işlememi nasip et; beni de lütfunla salih kullarının arasına kat!" dedi.'),
(27, 20, 19, 378, 'وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ', 'wa-tafaqqada aṭ-ṭayra fa-qāla mā liya lā ʾarā al-hudhuda ʾam kāna mina l-ḡāʾibīna', 'Ve kuşları gözden geçirdi (inceledi) de şöyle dedi: "Hüdhüdü neden göremiyorum? Yoksa o kayıplardan mı oldu?"'),
(27, 21, 19, 378, 'لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَٰنٍ مُّبِينٍ', 'la-uʿaḏḏibannahū ʿaḏāban šadīdan aw la-aḏbaḥannahū aw leyaʾtiyannī bi-sulṭānin mubīn', 'Onu mutlaka şiddetli bir azapla cezalandıracağım veya onu mutlaka keseceğim yahut bana apaçık bir delil getirecek.'),
(27, 22, 19, 378, 'فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍ يَقِينٍ', 'fe-me-keṯa ġayra baʿīdin fe-qāla aḥaṭtu bimā lem tuḥiṭ bi-hi wa-jiʾtuka min sabaʾin bi-nebeʾin yaqīnin', 'Derken çok da uzak olmayan bir yerde kaldı ve şöyle dedi: "Ben, onun muttali olmadığı bir şeyi muttali oldum ve sana Sebe''den (gelen) kesin bir haber getirdim."'),
(27, 23, 19, 379, 'إِنِّى وَجَدتُّ ٱمْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ', 'innī wajadtu imraʾatan tamlikuhum wa ūtīyat min kulli shayʾin wa lahā ʿarshun ʿaẓīm', 'Gerçekten ben, onlara hükmeden, kendilerine her şeyden verilmiş ve büyük bir tahtı olan bir kadın buldum.'),
(27, 24, 19, 379, 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', 'wajadtuha waqawmaha yasjuduna lishshamsi min dooni Allahi wazayyana lahumu shshaytanu a''malahum fasa ddahum ''ani assabili fahum la yahtaduna', 'Onu ve kavmini Allah''ı bırakıp güneşe secde ederken buldum. Şeytan onlara yaptıklarını süslemiş ve onları doğru yoldan alıkoymuş. Bu yüzden onlar doğru yolu bulamıyorlar.'),
(27, 25, 19, 379, 'أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', 'ʾallā yasjudū lillāhi llaḏī yuḫriju l-ḫabʾa fī s-samāwāti wa-l-ʾarḍi wa-yaʿlamu mā tuḫfūna wa-mā tuʿlinūn', 'Onlar, göklerde ve yerde olanı açığa çıkaran, gizlediğiniz ve açıkladığınız her şeyi bilen Allah''a secde etmiyorlar mı?'),
(27, 26, 19, 379, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'Allāhu lā ilāha illā huwe Rabbul-ʿarshil-ʿaẓīm', 'Allah! O''ndan başka hiçbir ilah yoktur. O, yüce Arş''ın Rabbidir.'),
(27, 27, 19, 379, 'قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَٰذِبِينَ', 'qāla sananẓuru aṣadaqta am kunta mina l-kādhibīn', 'Dedi ki: ''Bakalım doğru mu söylüyorsun, yoksa yalancılardan mı oldun?'''),
(27, 28, 19, 379, 'ٱذْهَب بِّكِتَٰبِى هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ', 'idhhab bikitābī hādhā fa-ʾalqihi ʾilayhim thumma tawalla ʿanhum fa-nẓur mādhā yarjiʿūn', 'Bu kitabımı götür, onlara at; sonra onlardan çekil de ne (söyleyeceklerini) gözetle.'),
(27, 29, 19, 379, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌ كَرِيمٌ', 'qālat yā ayyuhā l-malāʾu innī ulqiya ilayya kitābun karīmun', 'O, şöyle dedi: "Ey ileri gelenler! Bana çok önemli bir mektup atıldı."'),
(27, 30, 19, 379, 'إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'ʾinnahu min Sulaymāna wa ʾinnahu bismillāhi r-raḥmāni r-raḥīmi', 'Şüphesiz ki o, Süleyman''dan gelmektedir ve o, ''Bismillahirrahmannirrahim'' (dir).'),
(27, 31, 19, 379, 'أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ', 'ʾallā taʿlū ʿalayye waʾtūnī muslimīn', 'Sakın bana karşı büyüklük taslamayın ve bana tam bir teslimiyetle gelin!'),
(27, 32, 19, 379, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', 'qālat yā ayyuhā l-malāʾu aftūnī fī amrī mā kuntu qāṭiʿatan amran ḥattā tashhadūn', 'Dedi ki: "Ey ileri gelenler! Bu işimde bana görüşlerinizi bildirin. Ben sizin yanınızda bulunmadıkça bir işi asla kararlaştırmış değilim."'),
(27, 33, 19, 379, 'قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍ وَأُو۟لُوا۟ بَأْسٍ شَدِيدٍ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ', 'qālū naḥnu ʾūlū ḳuvvatin wa-ʾūlū baʾsin shadīdin wa-l-ʾamru ʾilayki fa-nẓurī māḏā taʾmurīna', 'Dediler ki: "Biz kuvvet ve şiddetli savaş gücü sahibiyiz. Emir ise sende. Şimdi ne emredeceğini bir gör bakalım."'),
(27, 34, 19, 379, 'قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةً وَكَذَٰلِكَ يَفْعَلُونَ', 'qālat ʾinna l-mulūka ʾiḏā daxalū qaryatan ʾafsadūhā wa-jaʿalū ʾaʿizzaʾta ʾahlihā ʾaḏillatan wa-kaḏālika yafʿalūn', 'Melik (Hükümdar)lar bir memlekete girdikleri zaman, orayı perişan ederler ve halkının ileri gelenlerini zelil (âciz ve hakir) kılarlar. İşte onlar böyle yaparlar.'),
(27, 35, 19, 379, 'وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ', 'waʾinnī mursilatun ʾilayhim bihadīyatin fanāẓiratun bimā yarjiʿu l-mursalūna', 'Ve ben onlara bir hediye göndereceğim ve elçilerin neyle döneceğini göreceğim.'),
(27, 36, 19, 380, 'فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', 'fe-lemmā jāʾa Sulaymān qāla a-tumiddūnenī bi-māl fe-mā ātānī ʾllāhu ḫayrun mimmā ātākum bal ʾantum bi-hadiyyatikum tafrāḥūn', 'Resûl gelince Süleyman ona dedi ki: "Bana mal ile mi yardım etmek istiyorsunuz? Allah’ın bana verdiği, size verdiğinden daha hayırlıdır. Hayır, siz hediyenizle sevinirsiniz."'),
(27, 37, 19, 380, 'ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَٰغِرُونَ', 'irciʿ ileyhim felenʾtiyennem bi cünûdin lâ kibela lehum bihâ ve lenuḫricennehum minhâ ʾeẕilleten ve hum ṣâġirûn', 'Onlara dön; çünkü onlara karşı, kendilerinin karşı koyamayacağı ordularla geliriz ve onları oradan, hor ve hakir kimseler olarak mutlaka çıkarırız.'),
(27, 38, 19, 380, 'قَالَ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ', 'qāla yā ayyuhā l-malāʾu ayyukum yaʾtīnī biʿarshihā qabla an yaʾtūnī musli­mīn', 'Süleyman şöyle dedi: "Ey ileri gelenler! Hangi­niz bana, onların bana teslim ol­madan önce, onun (Belkıs''ın) tahtını getirebilir?"'),
(27, 39, 19, 380, 'قَالَ عِفْرِيتٌ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ', 'qāla ʿifrītu mmina l-jinni ʾanā ʾātīka bihī qabla ʾan taqūma min maqāmika wa-ʾinnī ʿalayhi laqawiyyun ʾamīnun', 'Cinlerden bir ifrit şöyle dedi: ''Ben sana, sen daha yerinden kalkmadan onu getiririm. Ve şüphesiz ben, buna gerçekten güç yetiren güvenilir biriyim.'''),
(27, 40, 19, 380, 'قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌ مِّنَ ٱلْكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ', 'qāla lladhī ʿindahu ʿilmun mina lkitābi ʾanā ʾātīka bihi qabla ʾan yartadda ʾilayka ṭarfuk falammā raʾāhu mustaqirran ʿindahu qāla hādhā min faḍli rabbī liyabluwanī ʾaʾashkuru ʾam ʾakfuru waman shakara faʾinnamā yashkuru linafsihi waman kafara faʾinna rabbī ghaniyyun karīmun', 'Kitaptan bir ilme sahip olan kişi şöyle dedi: "Gözünü kırpma süresi içinde onu sana getirebilirim." (Melik) tahtı yanında hazır görünce, "Bu, Rabbimin bir lütfudur. Şükür mü edeceğim, yoksa nankörlük mü edeceğim diye beni denemek için (getirdi). Kim şükrederse, ancak kendi iyiliği için şükreder. Kim de nankörlük ederse (bilsin ki) Rabbim zengindir, kerem sahibidir." dedi.'),
(27, 41, 19, 380, 'قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ', 'qāla nakkirū lahā ʿarshahā nanẓur atahتدī am takūnu mina lladhīna lā yahtadūn', 'Süleyman şöyle dedi: ''Onun tahtını tanınmaz hale getirin, bakalım doğru yolu bulabilecek mi, yoksa bulamayanlardan mı olacak?'''),
(27, 42, 19, 380, 'فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُۥ هُوَ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', 'fe-lemmā jāʾat qīla ʾahākadhā ʿarshuki qālat kaʾanahu huwa wa-ʾūtīnā l-ʿilma min qablihā wa-kunnā musliimīn', 'Tahtı (ona) getirildiği zaman, (Süleyman) "Senin tahtın böyle mi idi?" dedi. (Belkıs) "Sanki o, (bu)," dedi. "Zaten bize daha önce (bu) ilim verilmişti ve biz müslüman idik."'),
(27, 43, 19, 380, 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ إِنَّهَا كَانَتْ مِن قَوْمٍ كَٰفِرِينَ', 'wa ṣaddahā mā kānat taʿbudu min dūni llāh ʾinnahā kānat min qawmin kāfirīn', 'Onları, Allah''ı bırakıp taptıkları şeyler engelledi. Çünkü onlar kâfir bir kavim idiler.'),
(27, 44, 19, 380, 'قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'qīla lahā dkhulī ṣ-ṣarḥa falammā raʾathu ḥasibathu lujjah wa-kašafat ʿan sāqayhā qāla innahu ṣarḥum mumarradum min qawārīra qālat rabbī innī ẓalamtu nafsī wa-aslamtu maʿa sulaymāna lillāhi rabbi l-ʿālamīna', 'Ona şöyle denildi: "Saraya gir!" Sarayı görünce derin bir su sandı ve (eteğini) dizlerine kadar çekti. (Süleyman) dedi ki: "Şüphesiz bu, camdan yapılmış, (düzeltilip) parlatılmış bir saraydır." O (Belkıs) dedi ki: "Rabbim! Gerçekten ben kendime zulmettim. (Artık) ben Süleyman ile birlikte âlemlerin Rabbi olan Allah''a teslim oldum."'),
(27, 45, 19, 381, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', 'Ve lekad erselnâ ilâ Semûde ehâhum Sâlihan eni''budûllâhe fe izâ hum ferîkâni yahtasımûn(e)', 'Andolsun ki Semûd kavmine kardeşleri Salih''i gönderdik ki: "Allah''a kulluk edin!" (desin). Bir de ne göresin, onlar çekişen iki fırka olmuşlar.'),
(27, 46, 19, 381, 'قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'qāla yā qawmi lima tastaʿjilūna bi-s-sayyiʾati qabla l-ḥasanati lawlā tastaghfirūna ʾllāha laʿallakum turḥamūna', 'Ey kavmim! Niçin iyilikten önce kötülüğe koşarsınız? Kurtuluşa ermeniz için Allah''tan bağışlanma dilemeniz gerekmez mi?'),
(27, 47, 19, 381, 'قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ قَالَ طَٰٓئِرُكُمْ عِندَ ٱللَّهِ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ', 'qālū ṭṭayyarnā bika wa biman maʿak qāla ṭāʾirukum ʿinda Llāh bal antum qawmun tuftanūn', 'Dediler ki: “Seninle ve maiyyetindekilerle uğursuzluğa uğradık.” (Salih) dedi ki: “Uğursuzluğunuz Allah katındadır. Hayır, sizler imtihana çekilen bir kavimsiniz.”'),
(27, 48, 19, 381, 'وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', 'wa kāna fī l-madīnati tisʿatu rahṭin yufsidūna fī l-arḍi wa lā yuṣliḥūna', 'Şehirde dokuz kişilik bir grup vardı; onlar yeryüzünde bozgunculuk çıkarır, ıslah etmezlerdi.'),
(27, 49, 19, 381, 'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ', 'qālū taqāsamū billāhi lanubayyitannahu wa''ahlahū thumma lanaqūlanna liwaliyyihī mā shahidnā mahlika ahlihī wa''innā laṣādiqūna', 'Dediler ki: "Birbirinize yemin edin! Gecenin bir vaktinde ona ve ailesine baskın yapalım, sonra da velisine: ''Biz ailesinin yok oluşuna tanık olmadık, gerçekten doğru söylüyoruz'' diyelim."'),
(27, 50, 19, 381, 'وَمَكَرُوا۟ مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ', 'wa makarū makran wa makarnā makran wa hum lā yashʿurūn', 'Onlar bir tuzak kurdular. Biz de bir tuzak kurduk. Onlar farkında değillerdi.'),
(27, 51, 19, 381, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', 'fa-nẓur kayfa kāna ʿāqibatu makrihim ʾannā dammarnāhum wa-qawmahum ʾajmaʿīn', 'Böylece onların tuzaklarının sonu nasıl oldu, bir bak! Şüphesiz biz onları ve bütün kavimlerini helak ettik.'),
(27, 52, 19, 381, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّقَوْمٍ يَعْلَمُونَ', 'fa tilka buyūtuhum khāwiyatan bimā ẓalamū inna fī dhālika laʾāyatan liqawmin yaʿlamūn', 'İşte zulmetmeleri yüzünden evleri bomboş kalmış olanlar bunlardır. Elbette bunda bilen bir kavim için bir ibret vardır.'),
(27, 53, 19, 381, 'وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'wa-ʾanjaynā alladhīna ʾāmanū wa-kānū yattaqūna', 'İman edip takva sahibi olanları kurtarmıştık.'),
(27, 54, 19, 381, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ', 'wa-lūṭan ʾiḏ qāla li-qawmihi ʾataʾtūna l-fāḥišata wa-ʾantum tuṣirūn', 'Lût''u da (hatırla). Hani o kavmine demişti ki: "Göz göre göre o hayasızlığı mı yapıyorsunuz?"'),
(27, 55, 19, 381, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ', 'ʾaʾinnakum lataʾtūna r-rijāla shahwatan min dūni n-nisāʾi bal ʾantum qawmun tajhalūna', 'Gerçekten siz, kadınları bırakıp şehvetle erkeklere mi yaklaşıyorsunuz? Hayır, siz (bunu yapan) bilgisiz bir toplumsunuz!'),
(27, 56, 20, 382, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', 'famā kāna jawāba qawmihi ʾillā ʾan qālū ʾaḫrijū ʾāla lūṭin min qaryatikum ʾinnahum ʾunāsun yataṭahharūn', 'Kavminin cevabı ise ancak şöyle demek oldu: "Lut ailesini kasabanızdan çıkarın! Çünkü onlar, (ne pisliğe bulaştığı) bilinmeyen insanlardır."'),
(27, 57, 20, 382, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ ٱلْغَٰبِرِينَ', 'faʾanjaynāhu waʾahlahū ʾillā ʾimraʾatahū qaddarnāhā mina l-ḡābiriin', 'Bunun üzerine onu ve ailesini, karısı hariç kurtardık. Karısının ise geride kalanlardan olmasını takdir ettik.'),
(27, 58, 20, 382, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'wa-amṭarnā ʿalayhim maṭaran fa-sāʾa maṭaru l-munḏarīn', 'Ve üzerlerine bir yağmur indirdik. Uyarılmış olanların yağmuru ne kötü!'),
(27, 59, 20, 382, 'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', 'quli l-ḥamdu li-llāhi wa-salāmun ʿalā ʿibādihi l-ladhīna ṣṭafā ʾāllāhu khayrun ʾammā yushrikūn', 'De ki: Hamd Allah’a mahsustur ve O’nun seçtiği kullarına selâm! Allah mı daha hayırlıdır, yoksa onların ortak koştukları şeyler mi?'),
(27, 60, 20, 382, 'أَمَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ', 'Ammæn halaka-s-semāwāti ve-l-arḍa ve enzele lekum mine-s-semāʾi māʾen fe-anbatnā bihi ḥadāʾiḳa żāta behcetin mā kâne lekum en tunbitū şecerahā E-ilāhun meʿa-llāh Bel hum kavmun yaʿdilūn', 'Yoksa, gökleri ve yeri yaratan ve size gökten bir su indirip onunla sevinçli bahçeler bitiren kimdir? Sizin için o ağaçları bitirmek mümkün mü idi? Allah ile birlikte başka bir ilâh mı? Hayır, onlar (gerçeği) eğip saptıran bir topluluktur.'),
(27, 61, 20, 382, 'أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًا وَجَعَلَ خِلَٰلَهَآ أَنْهَٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'amman jaʿala l-arḍa qarāran wa-jaʿala khilālahā anhāran wa-jaʿala lahā rawāsiyya wa-jaʿala bayna l-baḥrayni ḥājizan a-ʾilāhun maʿa llāhi bal ʾaktharuhum lā yaʿlamūn', 'Yoksa yeryüzünü durulacak bir yer kılan, aralarında ırmaklar yaratan, ona dağlar yerleştiren ve iki denizi birbirinden ayıran bir engel koyan mı (daha hayırlıdır)? Allah ile birlikte başka bir ilâh mı vardır? Hayır, onların çoğu bilmezler.'),
(27, 62, 20, 382, 'أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قَلِيلًا مَّا تَذَكَّرُونَ', 'amman yucību l-muḍṭarra iḏā daʿāhu wa-yakshifu s-sūʾa wa-yajʿalukum khulafāʾa l-arḍi aʾilāhun maʿa llāhi qalīlan mā taḏakkarūna', 'Yoksa darda kaldığında dua edene icabet eden, kötülüğü (derdi) ortadan kaldıran ve sizi yeryüzünün halifeleri kılan mı (daha hayırlıdır)? Allah ile birlikte başka bir ilah mı var? Ne az düşünüyorsunuz!'),
(27, 63, 20, 382, 'أَمَّن يَهْدِيكُمْ فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ أَءِلَٰهٌ مَّعَ ٱللَّهِ تَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'Amman yahdīkum fī ẓulumāti l-barri wa-l-baḥri wa-man yursilu r-riyāḥa bushrā bayna yaday raḥmatihī a-ʾilāhun maʿa Llāhi taʿālā Llāhu ʿammā yushrikūn', 'Yoksa karanlıklar içinde karada ve denizde size kim yol gösterir ve rüzgârları rahmetinin önünden müjdeci olarak kim gönderir? Allah ile birlikte başka ilâh mı vardır? Allah, onların ortak koştukları şeylerden çok yücedir.'),
(27, 64, 20, 383, 'أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'amman yebdeʾu l-ḫalqa ṯumma yuʿīduhu wa-man yarzuqukum mina s-samāʾi wa-l-ʾarḍi ʾaʾilāhun maʿa ʾllāhi qul hātū burhānākum ʾin kuntum ṣādiqīn', 'Yoksa, yaratmayı başlatan, sonra onu iade edecek ve sizi gökten ve yerden rızıklandıran kimdir? Allah ile birlikte başka bir ilah mı var? De ki: ''Eğer doğru sözlüler iseniz, delillerinizi getirin!'''),
(27, 65, 20, 383, 'قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'qul lā yaʿlamu man fī s-samāwāti wa-l-arḍi l-ġayba illā llāh wa mā yašʿurūna ayyana yubʿathūn', 'De ki: Göklerde ve yerde olan gaybı Allah''tan başkası bilmez. Onlar ne zaman diriltileceklerini de bilmezler.'),
(27, 66, 20, 383, 'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْءَاخِرَةِ بَلْ هُمْ فِى شَكٍّ مِّنْهَا بَلْ هُم مِّنْهَا عَمُونَ', 'bal idrâke ʿilmuhum fī l-ʾākhirati bal hum fī shakkim minhā bal hum minhā ʿamūna', 'Hayır, onların ilmi âhiret hakkında (bu hususta) tam bir bilgiye ulaşamamıştır. Hayır, onlar ondan (o âhiretten) yana bir şüphe içindedirler. Hayır, onlar ondan yana kördürler.'),
(27, 67, 20, 383, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ', 'waqāla alladhīna kafarū aʾidhā kunnā turāban waʾābāʾunā aʾinnanā lamukhrajūna', 'İnkâr edenler şöyle dediler: "Biz ve atalarımız toprağa karıştıktan sonra, biz mi gerçekten (yeni baştan) çıkarılacağız?"'),
(27, 68, 20, 383, 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'Lekad vuʿidnâ hâẕâ nahnu ve âbâunâ min kablu İn hâẕâ illâ esâṭîru-l-evvelîn', 'Andolsun ki, bu bize ve daha önce atalarımıza da vaat edilmişti. Bu, öncekilerin masallarından başka bir şey değildir.'),
(27, 69, 20, 383, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'qul sīrū fī l-arḍi fa-nẓurū kayfa kāna ʿāqibatu l-mujrimīn', 'De ki: "Yeryüzünde dolaşın da, suçluların sonunun nasıl olduğuna bir bakın."'),
(27, 70, 20, 383, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', 'wa lā taḥzan ʿalayhim wa lā takun fī ḍayqin mimmā yamkurūn', 'Onlardan dolayı üzülme ve onların kurmakta oldukları tuzaklardan dolayı da sıkıntıya düşme.'),
(27, 71, 20, 383, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hādhā al-waʿdu in kuntum ṣādiqīna', 'Ve derler ki: "Eğer doğru sözlüler iseniz, bu vaad ne zaman?"'),
(27, 72, 20, 383, 'قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ', 'qul ʿasā ʾan yakūna radifa lakum baʿḍu lladhī tastaʿcilūn', 'De ki: "Belki de çarçabucak gelmesini istediğinizin bir kısmı size yetişmiştir."'),
(27, 73, 20, 383, 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 'wa-ʾinna rabbaka la-dhū faḍlin ʿalā n-nāsi wa-lākinna ʾaktharahum lā yashkurūna', 'Ve şüphesiz Rabbin, insanlara karşı büyük lütuf sahibidir; ancak onların çoğu şükretmezler.'),
(27, 74, 20, 383, 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'wa-ʾinna rabbaka layaʿlamu mā tukinnu ṣudūruhum wa-mā yuʿlinūna', 'Şüphesiz Rabbin, onların göğüslerinin neler sakladığını ve neleri açıkladıklarını elbette bilir.'),
(27, 75, 20, 383, 'وَمَا مِنْ غَآئِبَةٍ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'wa mā min ghāʾibatin fī s-samāʾi wa-l-ʾarḍi ʾillā fī kitābin mubīnin', 'Göklerde ve yerde hiçbir gizli şey yoktur ki apaçık bir kitapta olmasın.'),
(27, 76, 20, 383, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ', 'ʾinna hāḏā l-qurʾāna yaquṣṣu ʿalā banī ʾisrāʾīla ʾakṯara ʾallaḏī hum fīhi yaḵtalifūn', 'Şüphesiz bu Kur''an, İsrailoğullarına hakkında ihtilafa düştükleri şeylerin çoğunu anlatmaktadır.'),
(27, 77, 20, 384, 'وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', 'wa-ʾinnahu la-hudan wa-raḥmatun lil-muʾminīn', 'Şüphesiz o (Kur''an), müminler için bir hidayet ve bir rahmettir.'),
(27, 78, 20, 384, 'إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ', 'ʾinna rabbaka yaqḍī baynahum biḥukmihī wa-huwa l-ʿazīzu l-ʿalīmu', 'Şüphesiz Rabbin, hükmüyle onların arasını (haklıyı haksızdan) ayıracaktır. O, mutlak güç sahibidir, her şeyi hakkıyla bilendir.'),
(27, 79, 20, 384, 'فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ', 'fa-tawakkal ʿalā Allāhi ʾinnaka ʿalā l-ḥaqqi l-mubīni', 'Allah''a güven; çünkü sen apaçık hak üzeresin.'),
(27, 80, 20, 384, 'إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'ʾinnaka lā tusmiʿu l-mawtā wa lā tusmiʿu ṣ-ṣumma d-duʿāʾa ʾiḏā wallaw mudbirīn', 'Şüphesiz sen ölülere (sözünü) duyuramazsın ve arkalarını dönüp kaçarken sağırların da duymasını sağlayamazsın.'),
(27, 81, 20, 384, 'وَمَآ أَنتَ بِهَٰدِى ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', 'wa mā anta bi-hādī l-ʿumī ʿan ḍalālatihim in tusmiʿu illā man yuʾminu bi-ʾāyātinā fa-hum muslimūn', 'Onları sapıklıklarından dolayı körlere yol gösterecek değilsin. Sen ancak âyetlerimize inanıp da müslüman olanlara duyurabilirsin.'),
(27, 82, 20, 384, 'وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَٰتِنَا لَا يُوقِنُونَ', 'wa ʾiḏā waqaʿa l-qawlu ʿalayhim ʾaḵrajnā lahum dābbatan mina l-ʾarḍi tukallimuhum ʾanna n-nāsa kānū bi-ʾāyātinā lā yūqinūn', 'Ve o söz (azap) üzerlerine geldiğinde, yerden kendileriyle konuşan bir dâbbe çıkarırız. Şüphesiz insanlar âyetlerimize inanmıyorlardı.'),
(27, 83, 20, 384, 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمْ يُوزَعُونَ', 'wa-yawma naḥshuru min kulli ummatin fawjan mimman yukadhdhibu bi-ʾāyātinā fa-hum yūzaʿūn', 'Her ümmetten âyetlerimizi yalanlayanlardan bir topluluk toplayacağımız o günü (hatırla); artık onlar (toplanıp) bir arada tutulurlar.'),
(27, 84, 20, 384, 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', 'ḥattā ʾiḏā jāʾū qāla ʾakaḏḏabtum bi-ʾāyātī wa-lam tuḥīṭū bihā ʿilman ʾammāḏā kuntum taʿmalūn', 'Nihayet o topluluklar gelince, Allah şöyle buyurur: "Ayetlerimi, onları kavrayamadığınız halde yalan mı saydınız? Yoksa ne yapıyordunuz?"'),
(27, 85, 20, 384, 'وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ', 'wa waqaʿa l-qawlu ʿalayhim bimā ẓalamū fa-hum lā yanṭiqūn', 'Ve zulmetmeleri yüzünden başlarına söz (azap) gerçekleşti, bu yüzden konuşamazlar.'),
(27, 86, 20, 384, 'أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'ʾelem yeraw ʾennā ceʿalnā l-layle liyaskunū fīhi wel-nehāre mubṣirā ʾinne fī ḏālika laʾyātin li-qawmin yuʾminūn', 'Onlar, geceyi kendilerine bir sakinlik vesilesi kılalım ve gündüzü de bir aydınlık yapalım diye yaratmadığımızı görmediler mi? Elbette bunlarda iman eden bir topluluk için nice ayetler vardır.'),
(27, 87, 20, 384, 'وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ', 'wa yawma yunfakhu fiṣ-ṣūri fafaaziʿa man fi s-samāwāti wa man fi l-arḍi illā man shāʾa ʾllāhu wa kullun atawhu dākhirīna', 'Sûr''a üflendiği gün, Allah''ın dilediği müstesna olmak üzere göklerde kim var, yerde kim varsa dehşete kapılır. Hepsi de boyunlarını bükerek O''na gelirler.'),
(27, 88, 20, 384, 'وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ', 'wa tarā l-jibāla taḥsabuhā jāmidatan wa hiya tamurru marra s-saḥābi ṣunʿa llāhi lladhī ʾatqana kulla shayin ʾinnahu ḵabīrun bimā tafʿalūn', 'Dağları görürsün de donmuş sanırsın; oysa onlar bulutların yürümesi gibi yürüyorlar. (Bu,) her şeyi sapasağlam yapan Allah''ın sanatıdır. Şüphesiz O, yapmakta olduklarınızdan haberdardır.'),
(27, 89, 20, 385, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ', 'man jāʾa bil-ḥasanati fa-lahū khayrun minhā wa-hum min fazaiñ yawmaiḏin āmīnūn', 'Kim bir iyilikle gelirse, ona daha iyisi vardır; ve onlar o günkü dehşetten güvendedirler.'),
(27, 90, 20, 385, 'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'wa-man jāʾa bi-s-sayyiʾati fa-kubbat wujūhuhum fī n-nāri hal tujzawna ʾillā mā kuntum taʿmalūna', 'Kim de kötülükle gelirse, yüzüstü ateşe atılır. Siz ancak yaptıklarınızın karşılığını alırsınız.'),
(27, 91, 20, 385, 'إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 'innamā umirtu an aʿbuda rabba hādhihi l-baldati lladhī ḥarramahā wa lahu kullu shayʾin wa umirtu an akūna mina l-muslimīn', 'Ben sadece, bu şehrin (Mekke''nin), onu harem kılan Rabbine kulluk etmekle emrolundum. Zaten her şey O''nundur. Ve bana Müslümanlardan olmam emredildi.'),
(27, 92, 20, 385, 'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ', 've en etluvel-qur''ane femen-ihteda fe''innema yehtedi linefsih ve men dalle fequl innema ene minel-munzirin', 'Ve Kur''an''ı okumam (emredildi). Kim doğru yolu bulursa, ancak kendisi için bulmuş olur. Kim de saparsa, de ki: “Ben ancak uyarıcılardanım.”'),
(27, 93, 20, 385, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'wa quli l-ḥamdu li-llāhi sayurīkum ʾāyātihi fa-taʿrifūnahā wa mā rabbuka bi-ḡāfilin ʿammā taʿmalūna', 'Ve de ki: Hamd, Allah''a mahsustur. O, size ayetlerini gösterecek de onları tanıyacaksınız. Rabbin, yaptıklarınızdan gafil değildir.'),
(28, 1, 20, 385, 'طسٓمٓ', 'Ṭā, Sīn, Mīm', 'Ta, Sin, Mim.'),
(28, 2, 20, 385, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'tilka āyātu l-kitābi l-mubīni', 'Bunlar, apaçık olan Kitab''ın ayetleridir.'),
(28, 3, 20, 385, 'نَتْلُوا۟ عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِٱلْحَقِّ لِقَوْمٍ يُؤْمِنُونَ', 'natlū ʿalayka min nabaʾi Mūsā wa-Firʿawna bil-ḥaqqi li-qawmin yuʾminūn', 'Sana Musa ve Firavun''un haberlerinden bir kısmını, iman edecek bir topluluk için hak olarak okuyacağız.'),
(28, 4, 20, 385, 'إِنَّ فِرْعَوْنَ عَلَا فِى ٱلْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَآئِفَةً مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ إِنَّهُۥ كَانَ مِنَ ٱلْمُفْسِدِينَ', 'inna firʿawna ʿalā fī l-arḍi wa-jaʿala ʾahalahā shiyaʿan yastaḍʿifu ṭāʾifatan minhum yudhabiḥu ʾabnāʾahum wa-yastaḥyī nisāʾahum ʾinnahu kāna mina l-mufsidīna', 'Şüphesiz Firavun, yeryüzünde (malı, mülkü ve askerî gücüyle) yücelmişti ve halkını (milletini) çeşitli gruplara ayırmıştı. Onlardan bir grubun zayıf bırakılması için (onların) erkek çocuklarını öldürüyor, kadınlarını ise sağ bırakıyordu. Çünkü o, bozgunculardan idi.'),
(28, 5, 20, 385, 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ ٱلْوَٰرِثِينَ', 'wa-nurīdu an namunna ʿalā alladhīna istuḍʿifū fī l-arḍi wa-najʿalahum ʾaimmatan wa-najʿalahumu l-wārithīna', 'Yeryüzünde zayıf düşürülenlere lütufta bulunmak, onları (halkın) önderleri yapmak ve onlara mirasçılar kılmak istedik.'),
(28, 6, 20, 386, 'وَنُمَكِّنَ لَهُمْ فِى ٱلْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا۟ يَحْذَرُونَ', 'wa numakkina lahum fī l-arḍi wa nurī firʿawna wa hāmāna wa junūdahumā minhum mā kānū yaḥdharūna', 'Ve onları yeryüzünde iktidar sahibi kılalım ve Firavun ile Hâmân''a ve onların ordularına, kendilerinden korkup çekindikleri şeyi gösterelim.'),
(28, 7, 20, 386, 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ', 'waʾawḥaynā ʾilā ʾummi mūsā ʾan ʾarḍiʿīhi faʾiḏā ḵifti ʿalayhi faʾalqīhi fī l-yamm walā taḵāfī walā taḥzanī ʾinnā rāddūhu ʾilayki wajāʿilūhu mina l-mursilīn', 'Musa''nın annesine şöyle vahyettik: "Onu emzir. Kendisi hakkında bir korku duydığında, onu denize (Tîh''e) bırakıver. Korkma ve üzülme. Şüphesiz biz onu sana döndüreceğiz ve onu peygamberlerden kılacağız."'),
(28, 8, 20, 386, 'فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا إِنَّ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُوا۟ خَٰطِـِٔينَ', 'fa-ltaqaṭa-hū ʾālu firʿawna li-yakūna lahum ʿaduwwan wa-ḥazanan ʾinna firʿawna wa-hāmāna wa-junūda-humā kānū ḵāṭiʾīna', 'Böylece Firavun ailesi onu, kendilerine düşman ve (sonunda) üzüntü kaynağı olması için aldılar. Şüphesiz Firavun ve Hâmân ile orduları günahkârlardı.'),
(28, 9, 20, 386, 'وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّى وَلَكَ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَهُمْ لَا يَشْعُرُونَ', 'wa qālati mraʾatu firʿawna qurratu ʿaynin lī walaka lā taqtulūhu ʿasā an yanfaʿanā aw nattakhidha wًا wa hum lā yashʿurūna', 'Firavun''un karısı şöyle dedi: "(Bu bebek) bana da sana da bir göz aydınlığıdır! Onu öldürmeyin. Umulur ki bize faydası dokunur veya onu evlat ediniriz." Onlar (Firavun ve çevresi) ise bunun farkında değillerdi.'),
(28, 10, 20, 386, 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًا إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'waʾaṣbaḥa fūʾādu ʾummi mūsā fārigā ʾin kādat latubdī bihi lawlā ʾan rabaṭnā ʿalā qalbihā litakūna mina l-muʾminīn', 'Musa''nın annesinin gönlü (korkudan) bomboş bir hal aldı. Eğer biz onun kalbini (sağlam tutup) bağlamasaydık, neredeyse (çocuğunu) açığa vuracaktı. O, mü''minlerden olması için (böyle yaptık).'),
(28, 11, 20, 386, 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ فَبَصُرَتْ بِهِۦ عَن جُنُبٍ وَهُمْ لَا يَشْعُرُونَ', 'wa qālat li-ukhtihi quṣṣīhi fa-baṣurat bihi ʿan junubin wa hum lā yashʿurūn', 'Onun kız kardeşine dedi ki: "Onu takip et." O da uzaktan onu gözledi; onlar farkında değillerdi.'),
(28, 12, 20, 386, 'وَحَرَّمْنَا عَلَيْهِ ٱلْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَٰصِحُونَ', 'wa ḥarramnā ʿalayhi l-marāḍiʿa min qablu faqālat hal adullukum ʿalā ahli baytin yakfulūnahu lakum wa hum lahū nāṣiḥūn', 'Daha önce ona hiçbir sütaneyi haram kıldık. Bunun üzerine (Ablası) dedi ki: Size onun için bakıp büyütecek, ona iyi davranacak bir aileye (annelik yapacak birini) göstereyim mi? İşte onlar ona iyi bakacaklardır.'),
(28, 13, 20, 386, 'فَرَدَدْنَٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Faradadnāhu ilā ummihī Kay taqarra ʿaynuḥā Wa lā taḥzana Wa li-taʿlama anna waʿda Allāhi ḥaqqun Wa lākina aktharahum lā yaʿlamūn', 'Böylece onu annesine döndürdük ki, gözü aydınlansın, üzülmesin ve Allah''ın vaadinin hak olduğunu bilsin. Fakat onların çoğu bilmezler.'),
(28, 14, 20, 387, 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسْتَوَىٰٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'wa lammā balagha ʾashuddahu wa-stawā ʾātaynāhu ḥukman wa-ʿilman wa kaḏālika najzī l-muḥsinīn', 'Ve tam gücüne ulaştığında ve olgunlaştığında ona hüküm (ve nübüvvet) ve ilim verdik. İşte biz, iyilik edenleri böyle mükafatlandırırız.'),
(28, 15, 20, 387, 'وَدَخَلَ ٱلْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنْ عَدُوِّهِۦ فَٱسْتَغَٰثَهُ ٱلَّذِى مِن شِيعَتِهِۦ عَلَى ٱلَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ قَالَ هَٰذَا مِنْ عَمَلِ ٱلشَّيْطَٰنِ إِنَّهُۥ عَدُوٌّ مُّضِلٌّ مُّبِينٌ', 'wa-dakhala l-madīnata ʿalā ḥīni ghaflatin min ahlihā fa-wajada fīhā rajulayni yaqtaṣilāni hādhā min shīʿatihi wa-hādhā min ʿaduwwihi fa-staghāthahu alladhī min shīʿatihi ʿalā alladhī min ʿaduwwihi fa-waka-zahu Mūsā fa-qaḍā ʿalayhi qāla hādhā min ʿamali sh-shayṭāni innahu ʿaduwwun muḍillun mubīnun', 'O, halkının gaflet anında şehre girdi. Orada birbirleriyle vuruşan iki adam buldu. Biri kendi taraftarlarından, diğeri düşmanlarından idi. Kendi taraftarlarından olan, düşmanlarından olana karşı ondan yardım istedi. Bunun üzerine Musa, düşmanlarından olan o adama bir yumruk vurdu ve onu öldürdü. "Bu, şeytanın işindendir. Şüphesiz o, apaçık bir düşman ve saptırıcıdır" dedi.'),
(28, 16, 20, 387, 'قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'qāla rabbi innī ẓalamtu nafsī fāghfir lī faghafara lahū innahu huwa l-ghafūru r-raḥīmu', 'Dedi ki: "Rabbim! Şüphesiz ben kendime zulmettim. Sen beni bağışla." Allah da onu bağışladı. Şüphesiz O, Gafûr''dur, Rahîm''dir.'),
(28, 17, 20, 387, 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ', 'qāla rabbi bimā anʿamta ʿalayye falan akūna ẓahīran lil-mujrimīn', 'Musa dedi ki: Rabbim! Bana lütfettiğin nimetlere karşılık, artık suçlulara asla arka çıkmayacağım.'),
(28, 18, 20, 387, 'فَأَصْبَحَ فِى ٱلْمَدِينَةِ خَآئِفًا يَتَرَقَّبُ فَإِذَا ٱلَّذِى ٱسْتَنصَرَهُۥ بِٱلْأَمْسِ يَسْتَصْرِخُهُۥ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّ مُّبِينٌ', 'faʾaṣbaḥa fī l-madīnati ḫāʾifan yatarakkabu faʾiḏā llaḏī istanṣarahu bil-ʾamusi yastaṣriḫuhu qāla lahu mūsā ʾinnaka laġawiyyun mubīnun', 'Böylece şehirde korku içinde etrafı gözetleyerek sabahladı. Bir de ne görsün! Dün kendisinden yardım isteyen adam, yine ona yetişti. Musa ona dedi ki: "Sen gerçekten azgın birisin!"'),
(28, 19, 20, 387, 'فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ', 'felemmā en erāda en yebṭiśa bi-lleẕī huve ʿaduvvun lehumā qāla yā mūsā eturīdu en taqteleni kemā qatelte nefsen bil-ʾemsi in turīdu ʾillā en tekūne ǧabbāran fīl-ʾarḍi ve mā turīdu en tekūne minel-muṣliḥīn', 'Nihayet, kendisinin onlara düşman olduğu kimseye (kavgada) yakalamak isteyince, şöyle dedi: "Ey Musa! Dün bir cana kıydığın gibi beni de mi öldürmek istiyorsun? Sen ancak yeryüzünde bir zorba olmak istiyorsun. Ve ıslah edicilerden olmak istemiyorsun."'),
(28, 20, 20, 387, 'وَجَآءَ رَجُلٌ مِّنْ أَقْصَا ٱلْمَدِينَةِ يَسْعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَٱخْرُجْ إِنِّى لَكَ مِنَ ٱلنَّٰصِحِينَ', 'wa jāʾa rajulun min ʾaqṣā l-madīnati yasʿā qāla yā Mūsā ʾinna l-malaʾa yaʾtami rūn bika liyaqtulūk fākhruj ʾinnī laka mina n-nāṣiḥīn', 'Şehrin uzak bir ucundan bir adam koşarak geldi. Dedi ki: "Ey Musa! İleri gelenler seni öldürmek için toplanmışlar. Hemen çık git, şüphesiz ben sana öğüt verenlerdenim."'),
(28, 21, 20, 387, 'فَخَرَجَ مِنْهَا خَآئِفًا يَتَرَقَّبُ قَالَ رَبِّ نَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'fa-kharaja min-hā khāʾifan yatarqqabu qāla rabbi najjinī min al-qawmi aẓ-ẓālimīn', 'Bunun üzerine oradan korkarak etrafı kolaçan ederek çıktı. "Rabbim! Beni zalimler topluluğundan kurtar!" dedi.'),
(28, 22, 20, 388, 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ', 'wa lammā tawajjaha tilqāʾa madyana qāla ʿasā rabbī an yahdiyanī sawāʾa s-sabīl', 'Medyen''e yönelince dedi ki: "Umarım Rabbim beni doğru yola iletir."'),
(28, 23, 20, 388, 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ ٱلنَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمْرَأَتَيْنِ تَذُودَانِ قَالَ مَا خَطْبُكُمَا قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ ٱلرِّعَآءُ وَأَبُونَا شَيْخٌ كَبِيرٌ', 'wa lammā warada māʾa madyana wajada ʿalayhi ummatan min an-nāsi yasqūna wa wajada min dūnihimu imraʾatayni tadhūdāni qāla mā khaṭbukumā qālatā lā nasqī ḥattā yuṣdira ar-riʿāʾu wa abūnā shaykhun kabīrun', 'Medyen suyuna vardığında, orada (halkın) hayvanlarını sulayan bir topluluk buldu. Ve onların gerisinde, (koyunlarını) engelleyen iki kadın buldu. ''Derdi(niz) nedir?'' dedi. ''Çobanlar sulayıncaya kadar biz (sulayamayız)'' dediler, ''babamız ise yaşlı bir ihtiyar.'''),
(28, 24, 20, 388, 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ', 'fasqā lahuma thumma tawallā ilā al-ẓilli faqāla rabbi innī limā anzalta ilayya min khayrin faqīr', 'Bunun üzerine Musa, onlara (koyunlarını) suladı. Sonra gölgeye çekilip şöyle dedi: "Rabbim! Bana indireceğin her hayra gerçekten muhtacım."'),
(28, 25, 20, 388, 'فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى ٱسْتِحْيَآءٍ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ٱلْقَصَصَ قَالَ لَا تَخَفْ نَجَوْتَ مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'fa-jāʾathu iḥdāhumā tamshī ʿalā istiḥyāʾin qālat inna abī yadʿūka li-yajziyaka ajra mā saqayta lanā fa-lammā jāʾahu wa-qaṣṣa ʿalayhi l-qaṣaṣa qāla lā takhaf najawta mina l-qawmi ẓ-ẓālimīn', 'Derken iki kadından biri, utana utana ona geldi. "Babam, bizim için yaptığın bu hizmetin karşılığını vermek üzere seni çağırıyor" dedi. Musa, ona gelip başından geçenları anlatınca, "Korkma, o zalimler güruhundan kurtuldun" dedi.'),
(28, 26, 20, 388, 'قَالَتْ إِحْدَىٰهُمَا يَٰٓأَبَتِ ٱسْتَـْٔجِرْهُ إِنَّ خَيْرَ مَنِ ٱسْتَـْٔجَرْتَ ٱلْقَوِىُّ ٱلْأَمِينُ', 'qālat iḥdāhumā yāʾabati ʾistaʾjirhu ʾinna ḫayra mani ʾistaʾjirta l-qawiyyu l-ʾamīnu', 'Onlardan biri şöyle dedi: "Ey babacığım! Onü kirala. Şüphesiz ki, kiralayacağın en hayırlı kimse, güçlü ve güvenilir olandır."'),
(28, 27, 20, 388, 'قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ٱبْنَتَىَّ هَٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَٰنِىَ حِجَجٍ فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ', 'qāla innī urīdu an unkiḥaka iḥdā ibnatayya hātayni ʿalā an taʾjuranī thamāniya ḥijajin fa-in atmamta ʿashran fa-min ʿindika wa mā urīdu an ashugga ʿalayka sa-tajidunī in shāʾa ʾllāhu mina ṣ-ṣāliḥīna', 'Dedi ki: "Ben bu iki kızımdan birini sana nikahlamak istiyorum. Ancak bana sekiz yıl hizmet etmen şartıyla. Eğer on yılı tamamlarsan, bu senin tarafındandır. Ben seni zorlamak istemiyorum. İnşallah beni salihlerden bulacaksın."'),
(28, 28, 20, 388, 'قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ أَيَّمَا ٱلْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', 'qāla dhālika baynī wa baynaka ayyamā l-ajalayni qaḍaytu falā ʿudwāna ʿalayya wa-llāhu ʿalā mā naqūlu wakīlun', 'O dedi ki: "Bu benimle senin aranda bir ahit. İki süreden hangisini tamamlarsam tamamlayayım, artık bana bir kınama yoktur. Söylediklerimize Allah vekildir."'),
(28, 29, 20, 389, 'فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ', 'fe-lemmā qaḍā mūsā l-ʾajala wa-sāra bi-ʾahlihī ʾānasa min jānibi ṭ-ṭūri nāran qāla li-ʾahlihī-mkūthū ʾinnī ʾānastu nāran la-ʿallī ʾātīkum min-hā bi-khabarin ʾaw jaḏwatin mina n-nāri la-ʿallakum taṣṭalūna', 'Musa müddeti bitirip ailesiyle yola çıkınca, Tur''un yamacından bir ateş görmüş ve ailesine şöyle demişti: "Siz burada kalın, çünkü ben bir ateş gördüm. Umarım ki size oradan bir haber getiririm ya da ateşten bir kor getiririm ki ısınırsınız."'),
(28, 30, 20, 389, 'فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَٰطِئِ ٱلْوَادِ ٱلْأَيْمَنِ فِى ٱلْبُقْعَةِ ٱلْمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّىٓ أَنَا ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'felemmā atāhā nūdiye min shāṭiʾi l-wādi l-aymani fī l-buqʿati l-mubārakati mina sh-shajarati an yā Mūsā ʾinnī ʾanā llāhu rabb u l-ʿālamīna', 'Vaktâ ki ona (ateşe) geldiğinde, mübarek yerdeki vadinin sağ tarafından, o ağaçtan şöyle seslenildi: "Ey Musa! Şüphe yok, ben Allah''ım, âlemlerin Rabbi''yim."'),
(28, 31, 20, 389, 'وَأَنْ أَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ إِنَّكَ مِنَ ٱلْءَامِنِينَ', 'wa ʾan ʾalqi ʿaṣāk falammā raʾāhā tahtazzu kaʾannahā jānnun wallā mudbiran wa lam yuʿaqqib yā Mūsā ʾaqbil wa lā taḫaf ʾinnaka mina l-ʾāminīn', 'Değneğini at! Değneğini at! Değneği attığında, onu yılan gibi kıvrandığını görünce, arkasına bakmadan kaçtı. "Ey Musa! Dön ve korkma. Şüphesiz sen emniyette olanlardansın."'),
(28, 32, 20, 389, 'ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ وَٱضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ ٱلرَّهْبِ فَذَٰنِكَ بُرْهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'Usluk yedeke fi ceybike tahruc beydā''e min ġayri sū'' Vaḍmum ileyke cenāḥake mine''r-rehbi Fe ḏānika burhānāni min rabbike ilā fir''avne ve mele''ihī İnnahum kānū qawman fāsiqīn', 'Elini koynuna sok, kusursuz bir şekilde bembeyaz olarak çıksın. Korkudan da (ötürü) kolunu kendine çek. İşte bunlar, Rabbinden Firavun''a ve onun ileri gelenlerine (gönderilmiş) iki delildir. Çünkü onlar yoldan çıkmış bir kavim olmuşlardır.'),
(28, 33, 20, 389, 'قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ', 'qāla rabbi innī qataltu minhum nafsan faʾakhāfu ʾan yaqtulūn', 'Musa dedi ki: "Rabbim! Ben onlardan birini öldürdüm. Bu yüzden onların beni öldürmelerinden korkuyorum."'),
(28, 34, 20, 389, 'وَأَخِى هَٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًا فَأَرْسِلْهُ مَعِىَ رِدْءًا يُصَدِّقُنِىٓ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'wa-ʾaḫī hārūnu huwa ʾafṣaḥu minnī lisānan fa-ʾarsilhu maʿiya ridʾan yuṣaddiqunī ʾinnī ʾaḫāfu ʾan yukadhibūnī', 'Kardeşim Harun da benim dilimden daha açık konuşandır. Bu yüzden onu benimle birlikte, beni doğrulayan bir yardımcı olarak gönder. Çünkü ben, onların beni yalanlamalarından korkuyorum.'),
(28, 35, 20, 389, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰنًا فَلَا يَصِلُونَ إِلَيْكُمَا بِـَٔايَٰتِنَآ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلْغَٰلِبُونَ', 'qāla sanašuddu ʿaḍudaka bi-ʾaḵīka wa-najʿalu lakumā sulṭānan fa-lā yaṣilūna ʾilaykumā bi-ʾāyātinā ʾantumā wa-mani ʾittabaʿakumā al-ḡālibūn', 'Allah şöyle dedi: "Seni kardeşinle güçlendireceğiz ve ikinize de bir kudret vereceğiz. Ayetlerimiz sayesinde onlar size ulaşamayacaklar. Siz ve size tabi olanlar galip geleceksiniz."'),
(28, 36, 20, 390, 'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 'felemmā cāʾehum mūsā bi-ʾāyātinā bayyinātin qālū mā hādhā ʾillā siḥrun mufteran ve mā samiʿnā bihādhā fī ʾābāʾinā l-ʾawwalīn', 'Ne zaman ki onlara âyetlerimiz apaçık delillerle gelmişken Musa, "Bu, uydurulmuş bir sihirden başkası değildir. Biz bunu önceki atalarımızdan duymadık" dediler.'),
(28, 37, 20, 390, 'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'waqāla mūsā rabbī ʾaʿlamu biman jāʾa bil-hudā min ʿindihi wa man takūnu lahū ʿāqibatu ḍ-dāri ʾinnahu lā yufliḥu ẓ-ẓālimūna', 'Musa dedi ki: "Rabbim, kimin O''nun katından bir hidayetle geldiğini ve kimin için (güzel) bir akıbetin olacağını en iyi bilen(dir). Şüphesiz zalimler kurtuluşa ermezler."'),
(28, 38, 20, 390, 'وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى فَأَوْقِدْ لِى يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجْعَل لِّى صَرْحًا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ ٱلْكَٰذِبِينَ', 'waqāla firʿawnu yā ayyuhā l-malaʾu mā ʿalimtu lakum min ʾilāhin ġayrī faʾawqid lī yā hāmānu ʿalā ṭ-ṭīni fajʿal lī ṣarḥan laʿallī ʾaṭṭaliʿu ʾilā ʾilāhi mūsā wa ʾinnī laʾaẓunnuḥu mina l-kāḏibīn', 'Firavun dedi ki: "Ey ileri gelenler! Sizin için benden başka bir ilah tanımıyorum. Ey Hâmân! Bana tuğladan bir kule yap, belki yollara çıkar, böylece Mûsâ''nın ilâhına muttali olurum. Şüphesiz ben onu yalancılardan sanıyorum."'),
(28, 39, 20, 390, 'وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', 'wa-stakbara huwa wa-junūduhu fī l-arḍi bi-ghayri l-ḥaqqi wa-ẓannū annahum ilaynā lā yurjaʿūna', 'Ve kendisi ve orduları yeryüzünde haksız yere büyüklük tasladılar ve bizim tarafımıza asla döndürülmeyeceklerini sandılar.'),
(28, 40, 20, 390, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'faʾaḫaḏnāhu waǧunūda-hū fanabaḏnāhum fī al-yamm fa-nẓur kayfa kāna ʿāqibatu ẓ-ẓālimīn', 'Böylece onu ve ordusunu yakaladık ve onları denize attık. Zalimlerin sonunun nasıl olduğuna bir bak!'),
(28, 41, 20, 390, 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَدْعُونَ إِلَى ٱلنَّارِ وَيَوْمَ ٱلْقِيَٰمَةِ لَا يُنصَرُونَ', 'wa jaʿalnāhum ʾaimmatan yadʿūna ʾilā n-nār wa yawma l-qiyāmati lā yunṣarūn', 'Onları, ateşe çağıran önderler kıldık. Kıyamet günü ise onlara yardım edilmez.'),
(28, 42, 20, 390, 'وَأَتْبَعْنَٰهُمْ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ هُم مِّنَ ٱلْمَقْبُوحِينَ', 'wa-atbaʿnāhum fī hādhihi ad-dunyā laʿnatan wa-yawma al-qiyāmati hum mina al-maqbūḥīn', 'Onları bu dünyada bir lanete uğrattık. Kıyamet gününde ise onlar (çirkin yüzlü olup) çirkinleştirilmişlerden olacaklardır.'),
(28, 43, 20, 390, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ٱلْقُرُونَ ٱلْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'wa laqad ātaynā Mūsā al-kitāba min baʿdi mā ahlaknā al-qurūna al-ūlā baṣāʾira lil-nāsi wa hudan wa raḥmah laʿallahum yatadhakkarūna', 'Nihayet ilk nesilleri helak ettikten sonra Musa''ya, insanlar için aydınlatıcılar, yol gösterici ve rahmet olmak üzere o Kitab''ı verdik ki, öğüt alıp düşünebilsinler.'),
(28, 44, 20, 391, 'وَمَا كُنتَ بِجَانِبِ ٱلْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ٱلْأَمْرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ', 'wa mā kunta bi-jānibi l-gharbī idh qaḍaynā ilā Mūsā l-amra wa mā kunta mina sh-shāhidīn', 'Biz Mûsâ''ya o emri (vahyimizi) verdiğimiz zaman sen Batı tarafında değildin; (o vahyedilene) şahit de değildin.'),
(28, 45, 20, 391, 'وَلَٰكِنَّآ أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ ٱلْعُمُرُ وَمَا كُنتَ ثَاوِيًا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ', 'wa-lākinna anshaʾnā qurūnan fa-taṭāwala ʿalayhimu l-ʿumuru wa-mā kunta thāwiyan fī ʾahli madyana tatlū ʿalayhim ʾāyātinā wa-lākinna kunnā mursilīna', 'Fakat biz nice nesiller var ettik de, üzerlerine ömürler uzadı. Sen Medyen halkı arasında ikamet edip de onlara ayetlerimizi okuyan biri değildin. Fakat biz (peygamber) gönderen idik.'),
(28, 46, 20, 391, 'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'wa mā kunta bi-jānibi ṭ-ṭūri iḏ nādaynā wa lākin raḥmatan min rabbika li-tunḏira qawman mā atāhum min naḏīrin min qablika laʿallahum yataḏakkarūn', 'Sen Tur''un yanında bulunmuyordun; biz (ona) seslendiğimiz zaman. Fakat Rabbinden bir rahmet olarak (bildiriyoruz ki) senden önce kendilerine hiçbir uyarıcı gelmemiş bir kavmi uyarabilesin, umulur ki onlar öğüt alırlar.'),
(28, 47, 20, 391, 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'wa lawlā an tuṣībahum muṣībatum bimā qaddamat aydīhim fayqūlū rabbanā lawlā arsalta ilaynā rasūlan fanattabiʿa āyātika wa nakūna mina l-muʾminīn', 'Eğer, kendi elleriyle yaptıkları yüzünden başlarına bir musibet gelmeden önce (onlara azap etmeseydik) şöyle demeyecekler miydi: ''Rabbimiz! Bize bir peygamber gönderseydin de ayetlerine uysaydık ve mü''minlerden olsaydık!'''),
(28, 48, 20, 391, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوا۟ لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ أَوَلَمْ يَكْفُرُوا۟ بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ قَالُوا۟ سِحْرَانِ تَظَٰهَرَا وَقَالُوٓا۟ إِنَّا بِكُلٍّ كَٰفِرُونَ', 'fe-lemmā jāʾahumu l-ḥaqqu min ʿindinā qālū lawlā ʾūtīye miṯla mā ʾūtīye Mūsā ʾa-wa-lam yakfurū bimā ʾūtīye Mūsā min qablu qālū siḥrāni taẓāharā wa-qālū ʾinnā bi-kullin kāfirūn', 'Yanlarına tarafımızdan hak gelince, şöyle dediler: "Ona, Musa''ya verilmiş olanın bir benzeri verilseydi ya!" Daha önce Musa''ya verilmiş olanı inkâr etmediler mi? "İki sihir birbirine arka çıkmış!" dediler. "Biz hepsini inkâr edenleriz!" dediler.'),
(28, 49, 20, 391, 'قُلْ فَأْتُوا۟ بِكِتَٰبٍ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ', 'qul faʾtū bikitābin min ʿindi llāhi huwa ʾahdā min-humā ʾattabiʿhu ʾin kuntum ṣādiqīn', 'De ki: "Eğer doğru sözlüler iseniz, Allah''tan bir kitap getirin ki, onlardan daha doğru yolu göstersin de ona uyayım."'),
(28, 50, 20, 391, 'فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًى مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'fa-in lam yastajībū laka fa-ʿlam annamā yattabiʿūna ahwāʾahum wa-man aḍallu mimmani-ttabaʿa hawāhu bi-ghayri hudan mina ʾllāhi ʾinna ʾllāha lā yahdī l-qawma ẓ-ẓālimīna', 'Eğer sana icabet etmezlerse, bil ki onlar ancak kendi hevalarına (isteklerine) uyuyorlar. Allah''tan bir hidayetle olmayan kimse, kendi hevasına uyan kimseden daha sapık kimdir? Şüphesiz Allah, zalimler topluluğunu hidayete erdirmez.'),
(28, 51, 20, 392, 'وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'Ve lekad vessalnâ lehumul kavle leallehum yetezekkerûn', 'Andolsun ki Biz, öğüt alsınlar diye sözü (vahyi) onlara ardı ardına ulaştırdık.'),
(28, 52, 20, 392, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ', 'alladhīna ātaynāhumu l-kitāba min qablihī hum bihī yuʾminūna', 'Kendilerine daha önce kitap verdiklerimiz, ona (Kur''an''a) inanırlar.'),
(28, 53, 20, 392, 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا۟ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ', 'wa ʾiḏā yutlā ʿalayhim qālū ʾāmannā bihi ʾinnahu l-ḥaqqu min rabbina ʾinnā kunnā min qablihi muslimīn', 'Onlara okunduğu zaman: "Ona inandık. Şüphesiz o, Rabbimizden gelen hak (kitaptır). Gerçekten biz daha önce de Müslüman idik" derler.'),
(28, 54, 20, 392, 'أُو۟لَٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا۟ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'ʾūlāʾika yuʾtawna ʾajrahum marratayni bimā ṣabarū wayadraʾūna bil-ḥasanati as-sayyiʾata wamimmā razaqnāhum yunfiqūn', 'İşte onlar, sabretmelerinden dolayı ecirleri iki kat verilecek olanlardır. Ve onlar, kötülüğü iyilikle savarlar ve kendilerine verdiğimiz rızıktan infak ederler.'),
(28, 55, 20, 392, 'وَإِذَا سَمِعُوا۟ ٱللَّغْوَ أَعْرَضُوا۟ عَنْهُ وَقَالُوا۟ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِى ٱلْجَٰهِلِينَ', 'wa ʾidhā samiʿū l-laghwa ʾaʿraḍū ʿanhu wa qālū lanā ʾaʿmālunā wa lakum ʾaʿmālukum salāmun ʿalaykum lā nabtaḡī l-jāhilīn', 'Onlar, boş söz işittikleri zaman ondan yüz çevirirler ve: "Bizim amellerimiz bize, sizin amelleriniz size aittir. Size selam olsun. Biz cahillerle düş kalk etmek istemeyiz" derler.'),
(28, 56, 20, 392, 'إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ʾinnaka lā tahdī man ʾaḥbabta wa-lākinna ʾallāha yahdī man yašāʾu wa-huwa ʾaʿlamu bi-l-muhtadīna', 'Şüphesiz sen istediğini hidayete erdiremezsin, ancak Allah dilediğini hidayete erdirir. Ve O, hidayete erecek olanları daha iyi bilir.'),
(28, 57, 20, 392, 'وَقَالُوٓا۟ إِن نَّتَّبِعِ ٱلْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'wa qālū in nattabiʿi l-hudā maʿaka nutakhaṭṭaf min arḍinā a-wa-lam numakkin lahum ḥaraman ʾāminan yujbā ʾilayhi thamarātu kulli shayʾin rizqan min ladunnā wa-lākinna ʾaktharahum lā yaʿlamūn', 'Ve dediler ki: "Eğer seninle birlikte hidayete uyar, (yani Kur''an''a uyar)sak, bulunduğumuz yerden kapılıp gideriz." Onları, tarafımızdan bir rızık olarak her şeyin mahsullerinin toplandığı güvenli, dokunulmaz bir haremde (Mekke''de) yerleştirmedik mi? Fakat onların çoğu bilmezler.'),
(28, 58, 20, 392, 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍۭ بَطِرَتْ مَعِيشَتَهَا فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمْ إِلَّا قَلِيلًا وَكُنَّا نَحْنُ ٱلْوَٰرِثِينَ', 'wa kam ahlāknā min qaryatin baṭirat maʿīshatahā fatilka masākinuhum lam tuskun min baʿdihim illā qalīlan wa kunnā naḥnu l-wāriṯīn', 'Onların refah içinde yaşayan nice kasabalarını helak ettik. İşte onların yerleri; kendilerinden sonra oralarda pek az kimse oturmuştur. Ve biz varisleriz.'),
(28, 59, 20, 392, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًا يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ', 've mā kāne rabbuke muhlika l-qurā ḥattā yebʿaṯa fī ʾummihā rasūlan yatlū ʿalayhim ʾāyātinā ve mā kunnā muhlīki l-qurā ʾillā wa-ʾahluhā ẓālimūn', 'Rabbin, şehirleri, kendilerine âyetlerimizi okuyan bir peygamber göndermedikçe helâk edici değildir. Biz şehirleri ancak halkı zalim iken helâk ederiz.'),
(28, 60, 20, 393, 'وَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰٓ أَفَلَا تَعْقِلُونَ', 'wa mā ʾūtītum min šayʾin famatāʿu l-ḥayāti d-dunyā wa zīnatuhā wa mā ʿinda llāhi ḫayrun wa ʾabqā ʾafla taʿqilūn', 'Size verilen herhangi bir şey, dünya hayatının geçici bir zevki ve süsüdür. Allah katında olan ise daha hayırlı ve daha kalıcıdır. Hâlâ akıl erdiremiyor musunuz?'),
(28, 61, 20, 393, 'أَفَمَن وَعَدْنَٰهُ وَعْدًا حَسَنًا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ هُوَ يَوْمَ ٱلْقِيَٰمَةِ مِنَ ٱلْمُحْضَرِينَ', 'ʾafaman waʿadnāhu waʿdan ḥasanan fahuwa lāqīhi kaman mattaʿnāhu matāʿa l-ḥayāti d-dunyā thumma huwa yawma l-qiyāmati mina l-muḥḍarīn', 'Kendisine güzel bir vaatte bulunduğumuz, böylece ona kavuşacak olan kimse, dünya hayatının geçici zevkine eriştirdiğimiz, sonra da kıyamet günü (azaba) getirilecek kimse gibi midir?'),
(28, 62, 20, 393, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'wa-yawma yunādīhim fa-yaqūlu ayna shurakāʾīya alladhīna kuntum tazʿumūna', 'Ve o günü (hatırla) ki, Allah onlara seslenir de şöyle der: ''Benim ortaklarım olduğunu iddia ettiğiniz putlar nerede?'''),
(28, 63, 20, 393, 'قَالَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا تَبَرَّأْنَآ إِلَيْكَ مَا كَانُوٓا۟ إِيَّانَا يَعْبُدُونَ', 'qāla lladhīna ḥaqqa ʿalayhimu l-qawlu rabbanā hāʾulāʾi lladhīna aghwaynā aghwaynāhum kamā ghawaynā tabarraʾnā ilayka mā kānū ʾiyyānā yaʿbudūna', 'Onlar hakkında (azap) söz hak olmuş olanlar şöyle derler: "Rabbimiz! Bunlar bizim azdırdıklarımızdır. Biz azmış olduğumuz gibi, bunları da azdırdık. Senden uzağız (berîyiz). Onlar bize kulluk etmiyorlardı."'),
(28, 64, 20, 393, 'وَقِيلَ ٱدْعُوا۟ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَرَأَوُا۟ ٱلْعَذَابَ لَوْ أَنَّهُمْ كَانُوا۟ يَهْتَدُونَ', 'wa qīla dʿū shurakāʾakum fadaʿawhum falam yastajībū lahum waraʾawu l-ʿadhāba law ʾannahum kānū yahtadūn', 'Ve denildi ki: ''Ortaklarınızı çağırın!'' Onlar da kendilerine çağırdılar, fakat onlara icabet etmediler. Ve azabı gördüler. Keşke onlar (doğru) yolu bulmuş olsalardı!'),
(28, 65, 20, 393, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ٱلْمُرْسَلِينَ', 'wa-yawma yunādīhim fa-yaqūlu mādhā ʾajabtumū l-mursalin', 'O gün Allah onlara seslenir ve şöyle der: ''Peygamberlere ne cevap verdiniz?'''),
(28, 66, 20, 393, 'فَعَمِيَتْ عَلَيْهِمُ ٱلْأَنۢبَآءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَآءَلُونَ', 'faʿamiyat ʿalayhimu l-ʾanbāʾu yawmaʾiḏin fa-hum lā yatasāʾalūn', 'Artık o gün onlara (hakikatin) delilleri körlenmiş (kapalı) olur da birbirlerine soru soramazlar.'),
(28, 67, 20, 393, 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلْمُفْلِحِينَ', 'faʾammā man tāba waʾāmana waʿamila ṣāliḥan faʿasā ʾan yakūna mina l-mufliḥīn', 'Ancak tevbe eden, iman eden ve salih amel işleyen kimseye gelince, umulur ki o, kurtuluşa erenlerden olur.'),
(28, 68, 20, 393, 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ سُبْحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'wa-rabbuka yakhluqu mā yashāʾu wa-yakhtāru mā kāna lahumu l-khiyaratu subḥāna llāhi wa-taʿālā ʿammā yushrikūna', 'Rabbin dilediğini yaratır ve seçer. Onların seçme hakkı yoktur. Allah, onların ortak koştuklarından münezzehtir ve yücedir.'),
(28, 69, 20, 393, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'wa rabbuka yaʿlamu mā tukinnu ṣudūruhum wa mā yuʿlinūn', 'Ve Rabbin, onların göğüslerinin ne sakladığını ve neyi açıkladıklarını bilir.'),
(28, 70, 20, 393, 'وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَهُ ٱلْحَمْدُ فِى ٱلْأُولَىٰ وَٱلْءَاخِرَةِ وَلَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', 'wa huwa allāhu lā ilāha illā huwa lahu l-ḥamdu fī l-ʾūlā wa-l-ʾākhirati wa lahu l-ḥukmu wa ʾilayhi turjaʿūna', 'O, Allah''tır. O''ndan başka ilah yoktur. Hamd, O''na dünyada da âhirette de mahsustur. Hüküm de yalnız O''nundur ve siz de ancak O''na döndürüleceksiniz.'),
(28, 71, 20, 394, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِضِيَآءٍ أَفَلَا تَسْمَعُونَ', 'qul ʾaraʾaytum ʾin jaʿala ʾallāhu ʿalaykumu l-layla sarmadan ʾilā yawmi l-qiyāmati man ʾilāhun ġayru ʾallāhi yaʾtīkum biḍiyāʾin ʾafalā tasmaʿūna', 'De ki: "Hiç düşündünüz mü? Eğer Allah, kıyamet gününe kadar üzerinizde geceyi daimi kılsa, Allah''tan başka hangi ilah size bir ışık getirebilir? Hala işitmiyor musunuz?"'),
(28, 72, 20, 394, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلنَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ أَفَلَا تُبْصِرُونَ', 'qul ʾaraʾaytum ʾin jaʿala ʾallāhu ʿalaykumu n-nahāra sarmadan ʾilā yawmi l-qiyāmati man ʾilāhun ġayru ʾallāhi yaʾtīkum bi-laylin taskunūna fīhi ʾafalā tubṣirūna', 'De ki: «Şu sizin başınıza gelenleri bir düşünsenize! Allah, kıyamet gününe kadar gündüzü üzerinize kalıcı kılsa, Allah''tan başka hangi ilah size geceyi getirebilir ki siz de onda dinlenesiniz? Hâlâ görmüyor musunuz?»'),
(28, 73, 20, 394, 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ لِتَسْكُنُوا۟ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'wa min raḥmatihi jaʿala lakumu l-layla wa-n-nahāra li-taskunū fīhi wa li-tabtaghū min faḍlihi wa laʿallakum tashkurūn', 'O''nun rahmetinden (dolayı) geceyi ve gündüzü sizin için yarattı ki, geceleyin onda (dinlenip) sakin olasınız, gündüzün de O''nun kereminden (rızkınızı) arayasınız. Şükredesiniz diye.'),
(28, 74, 20, 394, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 'wa-yawma yunādīhim fa-yaqūlu ayna shurakāʾīya alladhīna kuntum tazʿumūna', 'Ve o gün Allah onlara seslenir de şöyle der: ''Benim, (varlığını) iddia edip durduğunuz ortaklarım nerede?'''),
(28, 75, 20, 394, 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا۟ بُرْهَٰنَكُمْ فَعَلِمُوٓا۟ أَنَّ ٱلْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'wa-nazʿanā min kulli ummatin shahīdan fa-qulnā hātū bur''hānakum fa-ʿalimū anna al-ḥaqqa li-llāhi wa-ḍalla ʿanhum mā kānū yaftarūn', 'Her ümmetten bir şahit çekip çıkardık. Sonra onlara: "Kesin delilinizi getirin!" dedik. İşte o zaman, hakkın Allah''a ait olduğunu anladılar ve uydurmuş oldukları şeyler onlardan kaybolup gitti.'),
(28, 76, 20, 394, 'إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ وَءَاتَيْنَٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ', 'ʾinna qārūna kāna min qawmi mūsā fabagā ʿalayhim waʾātaynāhu mina lkunūzi mā ʾinna mafātiḥahū latanūʾu bil-ʿuṣbati ʾūlī lquwwati ʾidh qāla lahu qawmuhu lā tafraḥ ʾinna llāha lā yuḥibbu lfariḥīna', 'Karun, Musa''nın kavminden idi. Ama onlara karşı azgınlık etti. Biz ona öyle hazineler vermiştik ki, anahtarlarını taşımak bile güçlü kuvvetli bir topluluğa ağır gelirdi. Hani kavmi ona şöyle demişti: "Şımarma! Allah şımaranları sevmez."'),
(28, 77, 20, 394, 'وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْءَاخِرَةَ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 'wa-btaghi fīmā ʾātāka ʾllāhu ʾd-dāra ʾl-ʾākhirata wa-lā tansā naṣībaka mina ʾd-dunyā wa-ʾaḥsin kamā ʾaḥsana ʾllāhu ʾilayka wa-lā tabghi ʾl-fasāda fī ʾl-ʾarḍi ʾinna ʾllāha lā yuḥibbu ʾl-mufsidīna', 'Allah''ın sana verdiğiyle ahiret yurdunu ara, dünyadan da nasibini unutma. Allah''ın sana iyilik yaptığı gibi sen de iyilik yap. Yeryüzünde bozgunculuk isteme. Şüphesiz Allah, bozguncuları sevmez.'),
(28, 78, 20, 395, 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ أَوَلَمْ يَعْلَمْ أَنَّ ٱللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ ٱلْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ٱلْمُجْرِمُونَ', 'qāla innamā ʾūtītuhu ʿalā ʿilmin ʿindī ʾa-wa-lam yaʿlam ʾanna ʾallāha qad ʾahlaka min qablihī mina l-qurūni man huwa ʾashaddu minhu quwwatan wa-ʾaktharu jamʿan wa-lā yusʾalu ʿan dhunūbihimu l-mujrimūn', 'O, şöyle dedi: "Bu bana ancak bende olan bir ilim sayesinde verilmiştir." O, kendinden önce Allah''ın, kendilerinden daha kuvvetli ve daha çok mal ve topluluk sahibi nice nesilleri helak etmiş olduğunu bilmez mi? Mücrimlere günahlarından sorulmaz.'),
(28, 79, 20, 395, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍ', 'faḫaraja ʿalā qawmihī fī zīnatihi qāla lladhīna yurīdūna l-ḥayāta d-dunyā yālayta lanā miṯla mā ūtīya qārūnu ʾinnahuu laḏū ḥaẓẓin ʿaẓīmin', 'Nihayet Karun, ziynetiyle kavminin karşısına çıktı. Dünya hayatını arzu edenler şöyle dedi: "Keşke Karun''a verilenin bir benzeri bize de verilseydi! Doğrusu o, büyük bir nasip sahibidir."'),
(28, 80, 20, 395, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَيْلَكُمْ ثَوَابُ ٱللَّهِ خَيْرٌ لِّمَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ', 'Ve kâle-lleẕîne ûtû-l''ilm(e) veylekum śevâbu(A)llâhi ḣayrun limen âmen(e) ve ''amile sâlihâ(n) velâ yulekkâhâ illâ-ssâbirûn(e)', 'Kendilerine ilim verilmiş olanlar ise şöyle dediler: "Yazıklar olsun size! Allah''ın sevabı, iman edip salih amel işleyenler için daha hayırlıdır. Ona ancak sabredenler kavuşturulur."'),
(28, 81, 20, 395, 'فَخَسَفْنَا بِهِۦ وَبِدَارِهِ ٱلْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلْمُنتَصِرِينَ', 'faḫasafnā bihi wa-bidārihi l-arḍa famā kāna lahu min fiʾatin yanṣurūnahu min dūni llāhi wa-mā kāna mina l-muntaṣirīn', 'Nihayet onu ve sarayını yere batırdık. Allah''tan başka ona yardım edecek bir topluluğu da yoktu; kendi de kurtulamadı.'),
(28, 82, 20, 395, 'وَأَصْبَحَ ٱلَّذِينَ تَمَنَّوْا۟ مَكَانَهُۥ بِٱلْأَمْسِ يَقُولُونَ وَيْكَأَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَوْلَآ أَن مَّنَّ ٱللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'waʾaṣbaḥa lladhīna tamanaw makānahū bil-ʾamsi yaqūlūna waykaʾanna l-lāha yabsūṭu r-rizqa liman yashāʾu min ʿibādihī waqdiru lawlā ʾan manna l-lāhu ʿalaynā lakhasafa binā waykaʾannahu lā yufliḥu l-kāfirūna', 'Ve onun yerinde olmayı dileyenler dün gibi (olmuşlardı), şimdi ise: "Demek ki Allah, kullarından dilediğine rızkı bollaştırır ve ona darlık verir. Eğer Allah bize lütfetmeseydi, herhalde bizi de yerin dibine geçirirdi. Demek ki kâfirler kurtuluşa ermezler." diyorlar.'),
(28, 83, 20, 395, 'تِلْكَ ٱلدَّارُ ٱلْءَاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِى ٱلْأَرْضِ وَلَا فَسَادًا وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'tilka d-dāru l-ʾākhiratu najʿaluhā lilladhīna lā yurīdūna ʿuluwwan fī l-ʾarḍi wa lā fasādan wa l-ʿāqibatu lil-muttaqīna', 'İşte bu ahiret yurdunu, biz yeryüzünde böbürlenmeyi ve bozgunculuğu istemeyen kimselere nasip ederiz. (En güzel) akıbet ise takva sahiplerinindir.'),
(28, 84, 20, 395, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَى ٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'man jāʾa bil-ḥasanati fa-lahū khayrun min-hā wa-man jāʾa bis-sayyiʾati fa-lā yujzā l-ladhīna ʿamilū s-sayyiʾāti illā mā kānū yaʿmalūn', 'Kim bir iyilik getirirse, ona daha iyisi vardır. Kim de bir kötülük getirirse, kötülük yapanlar yalnız yaptıklarıyla cezalandırılırlar.'),
(28, 85, 20, 396, 'إِنَّ ٱلَّذِى فَرَضَ عَلَيْكَ ٱلْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍ قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِٱلْهُدَىٰ وَمَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', 'ʾinna lladhī faraḍa ʿalayka l-qurʾāna la-rādduka ʾilā maʿādin qul rabbī ʾaʿlamu man jāʾa bil-hudā wa-man huwa fī ḍalālin mubīnin', 'Şüphesiz Kur''an''ı sana farz kılan (indiren) Allah, elbette seni dönülecek yere döndürecektir. De ki: "Rabbim, kimin hidayetle geldiğini ve kimin apaçık bir sapıklık içinde olduğunu en iyi bilendir."'),
(28, 86, 20, 396, 'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَٰبُ إِلَّا رَحْمَةً مِّن رَّبِّكَ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَٰفِرِينَ', 'wa-mā kunta tarjū an yulqā ilayka l-kitābu illā raḥmatan min rabbika falā takūnanna ẓahīran lil-kāfirīn', 'Sen bu kitabı (Kur''an''ı) ummazdın; ancak Rabbinden bir rahmet olarak (sana verildi). Artık kâfirlere arka çıkma.'),
(28, 87, 20, 396, 'وَلَا يَصُدُّنَّكَ عَنْ ءَايَٰتِ ٱللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ وَٱدْعُ إِلَىٰ رَبِّكَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'wa-lā yaṣuddunnaka ʿan ʾāyāti ʾllāhi baʿda ʾiḏ ʾunzīlat ʾilayka wa-dʿu ʾilā rabbika wa-lā takūnanna mina l-mušrikīn', 'Sana indirildikten sonra seni Allah''ın ayetlerinden alıkoymasınlar. Rabbine davet et ve sakın ortak koşanlardan olma.'),
(28, 88, 20, 396, 'وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَآ إِلَٰهَ إِلَّا هُوَ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', 'wa lā tadʿu maʿa llāhi ilāhan ʾākhara lā ilāha ʾillā huwa kullu šayʾin hālikun ʾillā wajhahu lahu l-ḥukmu wa ʾilayhi turjaʿūna', 'Allah ile beraber başka bir ilaha tapıp yalvarma; O''ndan başka ilah yoktur. O''nun zatından başka her şey helak olacaktır. Hüküm, yalnızca O''nundur ve siz de yalnızca O''na döndürüleceksiniz.'),
(29, 1, 20, 396, 'الٓمٓ', 'ʾElif, Lām, Mīm', 'Elif, Lâm, Mîm.'),
(29, 2, 20, 396, 'أَحَسِبَ ٱلنَّاسُ أَن يُتْرَكُوٓا۟ أَن يَقُولُوٓا۟ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ', 'aḥasiba n-nāsu an yutrakū an yaqūlū āmmanā wa-hum lā yuftenūn', 'İnsanlar, ''inandık'' demekle, imtihana çekilmeden bırakılacaklarını mı sandılar?'),
(29, 3, 20, 396, 'وَلَقَدْ فَتَنَّا ٱلَّذِينَ مِن قَبْلِهِمْ فَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُوا۟ وَلَيَعْلَمَنَّ ٱلْكَٰذِبِينَ', 'Ve lekad fetennâ-lleẕîne min kablihim Feleya’lemenna(A)llâhu-lleẕîne sadeķû veleya’lemenne-lkâẕibîn(e)', 'Andolsun ki Biz, onlardan öncekileri de denedik. Allah, elbette doğru söyleyenleri de bilecek, yalancıları da elbette bilecektir.'),
(29, 4, 20, 396, 'أَمْ حَسِبَ ٱلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسْبِقُونَا سَآءَ مَا يَحْكُمُونَ', 'am ḥasiba alladhīna yaʿmalūna s-sayyiʾāti an yasbiqūnā sāʾa mā yaḥkumūna', 'Yoksa kötülükleri yapanlar, Bizi geçebileceklerini mi sandılar? Ne kötü hükmediyorlar!'),
(29, 5, 20, 396, 'مَن كَانَ يَرْجُوا۟ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَءَاتٍ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'man kāna yarjū liqāʾa llāhi faʾinna ʾajala llāhi laʾātin wa-huwa s-samīʿu l-ʿalīmu', 'Kim Allah''a kavuşmayı umuyorsa, bilsin ki Allah''ın belirlediği o an mutlaka gelecektir. O, hakkıyla işiten, hakkıyla bilendir.'),
(29, 6, 20, 396, 'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفْسِهِۦٓ إِنَّ ٱللَّهَ لَغَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 've-men-cāhada-fe-ʾinnemā-yucāhidu-li-nafsihī ʾinna-llāhe-le-ġaniyyun-ʿani-l-ʿālemīn', 'Kim cihad ederse, ancak kendi iyiliği için cihad etmiş olur. Şüphesiz Allah, âlemlerden müstağnidir.'),
(29, 7, 20, 397, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti lanukaffiranna ʿanhum sayyiʾātihim wa-lanajziyannahum ʾaḥsana lladhī kānū yaʿmalūna', 'İman edip salih amel işleyenlerin günahlarını elbette örteceğiz ve onlara yapmakta olduklarının daha güzeliyle karşılık vereceğiz.'),
(29, 8, 20, 397, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حُسْنًا وَإِن جَٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَآ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'wa waṣṣaynā al-insāna biwālidayhi ḥusnan wa in jāhadāka litushrika bī mā laysa laka bihi ʿilmun falā tuṭiʿhumā ilayya marjiʿukum fa-unabbiʾukum bimā kuntum taʿmalūn', 'Biz insana, ana babasına iyilik etmesini vasiyet ettik. Eğer onlar, seni hakkında bilgin olmayan bir şeyi bana ortak koşman için zorlarlarsa, onlara itaat etme. Dönüşünüz banadır. O zaman size yapmakta olduklarınızı haber vereceğim.'),
(29, 9, 20, 397, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُدْخِلَنَّهُمْ فِى ٱلصَّٰلِحِينَ', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti lanudkhilannahum fī ṣ-ṣāliḥīna', 'İman edip salih amel işleyenleri ise elbette salihlerin arasına sokacağız.'),
(29, 10, 20, 397, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِىَ فِى ٱللَّهِ جَعَلَ فِتْنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِ وَلَئِن جَآءَ نَصْرٌ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ أَوَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ ٱلْعَٰلَمِينَ', 'wa min an-nāsi man yaqūlu ʾāmannā bi-llāhi fa-ʾidhā ʾūḏiya fī llāhi jaʿala fitnata n-nāsi ka-ʿaḏābi llāhi wa la-ʾin jāʾa naṣrun min rabbika la-yaqūlunna ʾinnā kunnā maʿakum ʾa-wa-laysa llāhu bi-ʾaʿlama bimā fī ṣudūri l-ʿālamīn', 'İnsanlardan öylesi vardır ki: "Allah''a inandık" der. Fakat Allah yolunda bir eziyete uğradığı zaman, insanların işkencesini Allah''ın azabı gibi tutar. Yemin ederim ki, eğer Rabbinden bir zafer gelirse, mutlaka "Biz de sizinle beraberiz" derler. Allah, bütün alemlerin göğüslerinde olanı daha iyi bilen değil midir?'),
(29, 11, 20, 397, 'وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَٰفِقِينَ', 'wa layaclamanna allahu allatheena amanoo walayaclamanna almunafiqeen', 'Allah, iman edenleri mutlaka bilecek ve elbette münafıkları da bilecektir.'),
(29, 12, 20, 397, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيَٰكُمْ وَمَا هُم بِحَٰمِلِينَ مِنْ خَطَٰيَٰهُم مِّن شَىْءٍ إِنَّهُمْ لَكَٰذِبُونَ', 'waqāla alladhīna kafarū lilladhīna ʾāmanū ittabiʿū sabīlanā walnaḥmil khaṭāyākum wamā hum biḥāmilīna min khaṭāyāhum min shayin ʾinnahum lakādhibūna', 'İnkâr edenler, iman edenlere şöyle dediler: "Bizim yolumuza uyun, sizin günahlarınızı biz yüklenelim." Hâlbuki onların günahlarından hiçbir şey yüklenici değillerdir. Şüphesiz onlar yalancıdırlar.'),
(29, 13, 20, 397, 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ وَلَيُسْـَٔلُنَّ يَوْمَ ٱلْقِيَٰمَةِ عَمَّا كَانُوا۟ يَفْتَرُونَ', 'wa layahmilunna athqālahum wa athqālan maʿa athqālihim wa layus''alunna yawma l-qiyāmati ʿammā kānū y<bos>ftirūn', 'Ve mutlaka kendi ağırlıklarını ve kendi ağırlıklarıyla birlikte başka ağırlıkları da taşıyacaklar ve kıyamet gününde uydurmakta oldukları şeyler hakkında mutlaka sorulacaklardır.'),
(29, 14, 20, 397, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَٰلِمُونَ', 'Ve lekad erselnâ Nûhan ilâ kavmihî fe lebiśe fîhim elfe senetin illâ hamsîne ''âmâ fe eḣażehumu-ṭṭûfânu ve hum zâlimûn', 'Andolsun ki Nuh''u kavmine gönderdik de onların arasında bin yıldan elli yıl eksik kaldı. Sonunda onlar zulmederlerken tufan onları yakalayıverdi.'),
(29, 15, 20, 398, 'فَأَنجَيْنَٰهُ وَأَصْحَٰبَ ٱلسَّفِينَةِ وَجَعَلْنَٰهَآ ءَايَةً لِّلْعَٰلَمِينَ', 'faʾanjaynāhu waʾaṣḥāba s-safīnati wajaʿalnāhā ʾāyatan lil-ʿālamīn', 'Böylece onu ve gemi halkını kurtardık ve onu âlemlere bir ayet (ibret) kıldık.'),
(29, 16, 20, 398, 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'wa-ʾibrāhīma ʾiḏ ḳāla li-ḳawmihi uʿbudū ḷḷāha wa-ttaqūhu ḏālikum ḫayrun lakum ʾin kuntum taʿlamūn', 'İbrahim''i de (hatırla); hani kavmine demişti ki: Allah''a kulluk edin ve O''ndan korkun. Eğer bilirseniz, bu sizin için daha hayırlıdır.'),
(29, 17, 20, 398, 'إِنَّمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَوْثَٰنًا وَتَخْلُقُونَ إِفْكًا إِنَّ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ إِلَيْهِ تُرْجَعُونَ', 'innamā taʿbudūna min dūni ʾllāhi ʾawthānan wa-takhluqūna ʾifkan ʾinna ʾlladhīna taʿbudūna min dūni ʾllāhi lā yamlikūna lakum rizqan fa-ʾibtaḡū ʿinda ʾllāhi ʾr-rizqa wa-ʿbudūhu wa-škurū lahu ʾilayhi turjaʿūna', 'Siz Allah''tan başka birtakım putlara tapıyorsunuz ve yalan uyduruyorsunuz. Şüphesiz sizin Allah''tan başka taptıklarınız, size rızık verme gücüne sahip değillerdir. Öyleyse rızkı Allah katında arayın, O''na kulluk edin ve O''na şükredin. Siz O''na döndürüleceksiniz.'),
(29, 18, 20, 398, 'وَإِن تُكَذِّبُوا۟ فَقَدْ كَذَّبَ أُمَمٌ مِّن قَبْلِكُمْ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'wa-in tukadhdhibū faqad kadhdhaba umamun min qablikum wa-mā ʿalā ar-rasūli illā al-balāghu al-mubīn', 'Eğer yalanlarsanız, bilin ki sizden önceki nice ümmetler de yalanlamışlardı. Peygamberin üzerine düşen ise apaçık tebliğden başkası değildir.'),
(29, 19, 20, 398, 'أَوَلَمْ يَرَوْا۟ كَيْفَ يُبْدِئُ ٱللَّهُ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥٓ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'ʾAwalem yeraw keyfe yubdiʾullāhu l-ḫalqa thumma yuʿīduhu ʾInne dhālika ʿalallāhi yasīr', 'Onlar, Allah''ın yaratmayı nasıl başlattığını, sonra onu nasıl iade edeceğini görmediler mi? Şüphesiz bu, Allah için kolaydır.'),
(29, 20, 20, 398, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ بَدَأَ ٱلْخَلْقَ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشْأَةَ ٱلْءَاخِرَةَ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'Qul Sīrū fī l-arḍi Fa-nẓurū kayfa badaʾa l-khalqa Thumma ʾallāhu yunshiʾu n-nashʾata l-ʾākhirata ʾInna ʾallāha ʿalā kulli shayʾin qadīrun', 'De ki: "Yeryüzünde dolaşın da yaratmaya nasıl başladığına bir bakın. Sonra Allah, ahiret (yeni) yaratılışını da (inşa eder). Şüphesiz Allah, her şeye hakkıyla gücü yetendir."'),
(29, 21, 20, 398, 'يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ وَإِلَيْهِ تُقْلَبُونَ', 'yuʿaḏḏibu man yašāʾu wayarḥamu man yašāʾu waʾilayhi tuqlabūna', 'Dilediğini azaplandırır, dilediğine merhamet eder ve O''na döndürüleceksiniz.'),
(29, 22, 20, 398, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'wa mā antum bimuʿjizīna fī l-arḍi walā fī s-samāʾi wa mā lakum min dūni llāhi min waliyyin walā naṣīrin', 'Siz ne yeryüzünde (azabımızdan) kurtulabilirsiniz, ne de gökte. Sizin Allah''tan başka ne bir dostunuz ne de bir yardımcınız vardır.'),
(29, 23, 20, 398, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', 'wa-lladhīna kafarū bi-ʾāyāti llāhi wa-liqāʾihi ʾulāʾika yaʾisū min raḥmetī wa-ʾulāʾika lahum ʿadhābun ʾalīmun', 'Allah''ın ayetlerini ve O''na kavuşmayı inkâr edenler, işte onlar benim rahmetimden ümit kesmişlerdir ve işte onlar için elem dolu bir azap vardır.'),
(29, 24, 20, 399, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'famā kāna jawāba qawmihi illā an qālū iqtulūhu aw ḥarriqūhu faʾanjāhu ʾllāhu mina n-nāri ʾinna fī dhālika laʾāyātin liqawmin yuʾminūna', 'İbrahim''in kavminin cevabı: "Onu öldürün veya yakın!" demekten başka bir şey değildi. Allah onu ateşten kurtardı. Elbette bunda, iman eden bir kavim için ibretler vardır.'),
(29, 25, 20, 399, 'وَقَالَ إِنَّمَا ٱتَّخَذْتُم مِّن دُونِ ٱللَّهِ أَوْثَٰنًا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 'waqāla innamā-ttakhaḏtum min dūni-llāhi ʾawṯānan mawaddata baynikum fī-lḥayāti-ddunyā ṯumma yawma-lqiyāmati yakfuru baʿḍukum bibaʿḍin wayalʿanu baʿḍukum baʿḍan wamaʾwākumu-nnāru wamā lakum min nāṣirīn', 'İbrahim dedi ki: "Siz, dünya hayatında aranızdaki sevgi (bağlantısı) uğruna Allah''tan başka putlar edindiniz. Sonra kıyamet günü birbirinize düşman kesilecek ve birbirinize lanet edeceksiniz. Varacağınız yer ise ateştir ve hiçbir yardımcılarınız yoktur."'),
(29, 26, 20, 399, 'فَـَٔامَنَ لَهُۥ لُوطٌ وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'faʾāmana laḥū lūṭun waqāla ʾinnī muhājirun ʾilā rabbī ʾinnahu huwa l-ʿazīzu l-ḥakīmu', 'Bunun üzerine Lût ona iman etti ve (İbrahim) dedi ki: "Ben Rabbime hicret ediyorum. Şüphesiz O, Azîz’dir, Hakîm’dir."'),
(29, 27, 20, 399, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'wa wahabnā lahu ʾisḥāqa wa yaʿqūba wa jaʿalnā fī dhurriyyatihi n-nubūwata wa l-kitāba wa ʾātaynāhu ʾajrahu fī d-dunyā wa ʾinnahu fī l-ʾākhirati la mina ṣ-ṣāliḥīna', 'Biz ona İshak''ı ve (torunu) Yakub''u bahşettik ve onun soyundan gelenlere peygamberlik ve kitap verdik. Dünyada ona mükâfatını verdik. Şüphesiz o, ahirette de iyi kimselerden olacaktır.'),
(29, 28, 20, 399, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', 'wa-lūṭan ʾiḏ qāla li-qawmihī ʾinnakum la-taʾtūna l-fāḥišata mā sabaqakum bihā min ʾaḥadin mina l-ʿālamīn', 'Lût''u da (gönderdik). Hani kavmine demişti ki: "Siz, sizden önce âlemlerden hiç kimsenin yapmadığı bir hayasızlığı yapıyorsunuz."'),
(29, 29, 20, 399, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ وَتَقْطَعُونَ ٱلسَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ ٱلْمُنكَرَ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱئْتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'ʾaʾinnakum lataʾtūna r-rijāla wa-taqṭaʿūna s-sabīla wa-taʾtūna fī nādīkumu l-munkara fa-mā kāna jawāba qawmihī ʾillā ʾan qālū ʾtinā bi-ʿadhābi llāhi ʾin kunta mina ṣ-ṣādiqīn', 'Gerçekten siz kadınları bırakıp şehvetle erkeklere yaklaşiyor, yol kesiyor ve toplantılarınızda fenalıklar yapıyorsunuz. Kavminin cevabı ise: "Eğer doğru sözlülerden isen, haydi bana Allah''ın azabını getir!" demekten başka bir şey olmadı.'),
(29, 30, 20, 399, 'قَالَ رَبِّ ٱنصُرْنِى عَلَى ٱلْقَوْمِ ٱلْمُفْسِدِينَ', 'qāla rabbi nṣurnī ʿalā l-qawmi l-mufsidīn', 'Onun üzerine Allah''ın azabı gelince dedi ki: "Rabbim! Beni, fesat çıkaran topluluğa karşı muzaffer kıl."'),
(29, 31, 20, 400, 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ إِنَّ أَهْلَهَا كَانُوا۟ ظَٰلِمِينَ', 'wa-lammā jāʾat rusulunā ibrāhīma bi-l-bushrā qālū ʾinnā muhlīkū ʾahli hādhihi l-qaryati ʾinna ʾahlahā kānū ẓālimīna', 'Elçilerimiz (melekler) İbrahim''e müjde ile geldiklerinde, dediler ki: "Biz bu memleket halkını helak edeceğiz; çünkü onların halkı zalim kimselerdi."'),
(29, 32, 20, 400, 'قَالَ إِنَّ فِيهَا لُوطًا قَالُوا۟ نَحْنُ أَعْلَمُ بِمَن فِيهَا لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'qāla inna fīhā lūṭan qālū naḥnu aʿlamu biman fīhā lanunajiyannahū waʾahlahū ʾillā ʾimraʾatahū kānat mina l-ḡābirīn', 'O (Lut) dedi ki: "Ama orada Lut var." Dediler ki: "Biz orada kimlerin olduğunu daha iyi biliriz. Elbette onu ve ailesini kurtaracağız, ancak karısı hariç; o, geride kalanlardan olacaktır."'),
(29, 33, 20, 400, 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا۟ لَا تَخَفْ وَلَا تَحْزَنْ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ٱمْرَأَتَكَ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 'wa lammā an jāʾat rusulunā Lūṭan sīʾa bihim wa ḍāqa bihim ḏarʿan wa qālū lā taḫaf wa lā taḥzan ʾinnā munajjūka wa ʾahlaka ʾillā ʾmraʾataka kānat mina l-ḡābirīn', 'Elçilerimiz Lut''a geldiğinde, onlar yüzünden Lut fenalaştı ve içi daraldı. "Korkma, üzülme! Biz seni ve aileni kurtaracağız, ancak karın bunun (helakin) gerisinde kalanlardan olacaktır" dediler.'),
(29, 34, 20, 400, 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'Innā munzilūna ʿalā ʾahli hādhihi l-qarʾyati rijzan mina s-samāʾi bimā kānū yafsuqūn', 'Bu şehir halkının üzerine, fasıklık etmeleri yüzünden gökten bir azap indireceğiz.'),
(29, 35, 20, 400, 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ', 'wa laqad taraknā minhā āyatan bayyinatan liqawmin yaʿqilūn', 'Gerçekten biz, aklını kullanan bir kavim için ondan (o beldeden) apaçık bir ibret (ayet) bıraktık.'),
(29, 36, 20, 400, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ وَٱرْجُوا۟ ٱلْيَوْمَ ٱلْءَاخِرَ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'waʾilā madyana ʾaḫāhum šuʿayban faqāla yā qawmi ʿbudū llāha warjū l-yawma l-ʾāḫira walā taʿṯaw fī l-ʾarḍi mufsidīn', 'Medyen''e de kardeşleri Şuayb''ı gönderdik. Şöyle dedi: "Ey kavmim! Allah''a kulluk edin, ahiret gününe ümit bağlayın ve yeryüzünde bozgunculuk yaparak fesat çıkarmayın."'),
(29, 37, 20, 400, 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'fa-kaḏḏabūhu fa-ʾaḵaḏathumu ʾr-rajfatu fa-ʾaṣbaḥū fī dārihim jāṯimīn', 'Böylece onu yalanladılar. Bu yüzden kendilerini şiddetli bir sarsıntı yakaladı da bulundukları yerde diz üstü çöke kaldılar.'),
(29, 38, 20, 400, 'وَعَادًا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ', 'wa ʿādan wa th<sub>a</sub>mūdā wa qad tabayyana lakum min masākinihim wa zayyana lahumu <sup>sh-</sup>shayṭānu ʾaʿmālahum fa ṣaddahum ʿani s-sabīl wa kānū mustabṣirīn', 'Ve Âd ve Semûd''u da (helak ettik). Onların meskenlerinden (nasıl helak oldukları) size apaçık belli olmuştur. Şeytan, onlara yaptıklarını süslü gösterdi de onları yoldan çıkardı. Onlar (gerçeği) görebilecek durumda idiler.'),
(29, 39, 20, 401, 'وَقَٰرُونَ وَفِرْعَوْنَ وَهَٰمَٰنَ وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ وَمَا كَانُوا۟ سَٰبِقِينَ', 'wa-Qārūna wa-Firʿawna wa-Hāmāna wa-laqad jāʾahum Mūsā bi-l-bayyināti fa-stakbarū fī l-arḍi wa-mā kānū sabiqīna', 'Karun''u, Firavun''u ve Haman''ı da (helak ettik). Andolsun ki Musa onlara apaçık delillerle gelmişti de, yeryüzünde büyüklük taslamışlardı ve (azabımızdan) kurtulacak değillerdi.'),
(29, 40, 20, 401, 'فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'fakullan akhadhna bidhanbihi faminhum man arsalna ''alayhi hasiban waminhum man akhadhat''hu al-sayhatu waminhum man khasafna bihi al-arda waminhum man aghraqna wama kana Allahu liyadhlimahum walakin kanoo anfusahum yadhlimoon', 'Her birini kendi günahıyla yakaladık. Onlardan kimi üzerine taş yağdırdığımız, kimi de o korkunç sayha (çığlık) ile yakaladığımız, kimi de yeri batırdığımız, kimi de suda boğduğumuz kimselerdir. Allah onlara zulmetmiyordu, fakat onlar kendi nefislerine zulmediyorlardı.'),
(29, 41, 20, 401, 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًا وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ لَوْ كَانُوا۟ يَعْلَمُونَ', 'Mathalu allatheena ittakhathoo min dooni Allahi awliyāʾa kamathali al-ʿankabooti ittakhathat baytan Wa inna awhana al-buyooti labaytu al-ʿankabooti law kanoo yaʿlamoon', 'Allah''tan başka dostlar edinenlerin durumu, örümceğin durumu gibidir. Örümcek, (kendine) bir ev edinir. Halbuki evlerin en çürüğü, örümcek evidir; bir bilselerdi!'),
(29, 42, 20, 401, 'إِنَّ ٱللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ʾinna ʾallāha yaʿlamu mā yadʿūna min dūnihi min šayʾin wa-huwa l-ʿazīzu l-ḥakīmu', 'Şüphesiz Allah, onların O''ndan başka taptıkları şeyleri bilir. O, Azîz''dir, Hakîm''dir.'),
(29, 43, 20, 401, 'وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ وَمَا يَعْقِلُهَآ إِلَّا ٱلْعَٰلِمُونَ', 'wa tilka l-ʾamthālu naḍribuhā li-n-nāsi wa mā yaʿqiluhā ʾillā l-ʿālimūna', 'İşte bu misalleri insanlara açıklıyoruz; ancak onları bilenlerden başkası düşünüp anlamaz.'),
(29, 44, 20, 401, 'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّلْمُؤْمِنِينَ', 'ḫalaqa ʾllāhu ʾs-samāwāti wa-l-ʾarḍa bi-l-ḥaqq ʾinna fī ḏālika la-ʾāyatan li-l-muʾminīn', 'Allah, gökleri ve yeri hak ile yaratmıştır. Şüphesiz bunda, iman edenler için bir ayet vardır.'),
(29, 45, 20, 401, 'ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', 'Uṭlu mā ūḥiya ilayka mina l-kitābi Wa aqimi ṣ-ṣalāta ʾInna ṣ-ṣalāta tanhā ʿani l-faḥshāʾi wa l-munkari Wa la dhikru llāhi ʾakbaru Wa llāhu yaʿlamu mā taṣnaʿūna', 'Sana vahyedilen Kitab''ı oku ve namazı kıl. Şüphesiz namaz, hayasızlıktan ve kötülükten alıkoyar. Elbette Allah''ı anmak en büyüktür. Allah, yaptıklarınızı bilir.'),
(29, 46, 21, 402, 'وَلَا تُجَٰدِلُوٓا۟ أَهْلَ ٱلْكِتَٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 'wa lā tujādilū ahla l-kitābi illā bi-llatī hiya aḥsanu illā l-ladhīna ẓalamū minhum wa qūlū āmmanā bi-lladhī unzila ilaynā wa unzila ilaykum wa ilāhanā wa ilāhukum wāḥidun wa naḥnu lahuū muslimūna', 'Onlarla, kendilerinden zulmedenler hariç, Kitap ehliyle ancak en güzel bir şekilde tartışın ve deyin ki: "Bize indirilene de, size indirilene de inandık; Tanrımız da Tanrınız da birdir ve biz O''na teslim olmuşuzdur."'),
(29, 47, 21, 402, 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ فَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يُؤْمِنُونَ بِهِۦ وَمِنْ هَٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلْكَٰفِرُونَ', 'wa kaḏālika anzalnā ilayka l-kitāb fa-llaḏīna ātaināhumu l-kitāba yuʾminūna bihī wa min hāʾulāʾi man yuʾminu bihī wa mā yajḥadu bi-āyātinā illā l-kāfirūn', 'Sana da (Resûlüm) kitabı indirdik. Kendilerine kitap verdiklerimiz ona inanırlar. Bunlardan da ona inananlar vardır. Âyetlerimizi ancak kâfirler inkâr eder.'),
(29, 48, 21, 402, 'وَمَا كُنتَ تَتْلُوا۟ مِن قَبْلِهِۦ مِن كِتَٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَ إِذًا لَّٱرْتَابَ ٱلْمُبْطِلُونَ', 'Ve mā kunte tetlū min qablihī min kitābin ve lā taḫuṭṭuhū bi-yamīnike iḏan la-rtāba l-mubṭilūn', 'Sen, daha önce hiçbir kitap okumadığın ve onu sağ elinle de yazmadığın halde, eğer böyle olmasaydı, şüpheye düşenler mutlaka şüphelenirlerdi.'),
(29, 49, 21, 402, 'بَلْ هُوَ ءَايَٰتٌۢ بَيِّنَٰتٌ فِى صُدُورِ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ', 'bal huwa āyātun bayyinātun fī ṣudūri lladhīna ūtū lʿilma wa mā yajḥadu bi-āyātinā illā ẓẓālimūn', 'Hayır, o (Kur''an) kendilerine ilim verilenlerin göğüslerinde (kalplerinde) açık ayetlerdir. Bizim ayetlerimizi ancak zalimler inkâr eder.'),
(29, 50, 21, 402, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌ مِّن رَّبِّهِۦ قُلْ إِنَّمَا ٱلْءَايَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'wa qālū lawlā unzila ʿalayhi ʾāyātun min rabbihī qul ʾinnamā al-ʾāyātu ʿinda Allāh wa ʾinnamā ʾanā nadhīrun mubīn', 'Bir de dediler ki: "Ona Rabbinden (indirilmiş) mucizeler (ayetler) indirilmeli değil miydi?" De ki: "Mucizeler ancak Allah katındandır. Ben ise sadece apaçık bir uyarıcıyım."'),
(29, 51, 21, 402, 'أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ إِنَّ فِى ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ', 'ʾawalam yakfihim ʾannā ʾanzalnā ʿalayka l-kitāba yutlā ʿalayhim ʾinna fī dhālika laraḥmataw wa dhikrā liqawmi yuʾminūn', 'Onlara, sana indirdiğimiz Kitab''ın okunması onlara yetmedi mi? Şüphesiz bunda, iman eden bir kavim için bir rahmet ve bir öğüt vardır.'),
(29, 52, 21, 402, 'قُلْ كَفَىٰ بِٱللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ ءَامَنُوا۟ بِٱلْبَٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'Qul kafā bil-lāhi baynī wa-baynakum shahīdan Yaʿlamu mā fī s-samāwāti wal-arḍi Wa-lladhīna āmanū bil-bāṭili wa-kafarū bil-lāhi ʾUlāʾika humu l-khāsirūn', 'De ki: "Benimle sizin aranızda şahit olarak Allah yeter. O, göklerde ve yerde ne varsa bilir. İnanıp yararlı işler yapanlar ile batıla inanıp Allah''ı inkâr edenler var ya, işte onlar ziyana uğrayanlardır."'),
(29, 53, 21, 403, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَوْلَآ أَجَلٌ مُّسَمًّى لَّجَآءَهُمُ ٱلْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'wa yastaʿjilūnaka bil-ʿadhābi wa lawlā ajalun musammā lajāʾahumu l-ʿadhābu wa layaʾtiyannahum baghtatan wa hum lā yashʿurūn', 'Sana aceleyle azap getirmelerini isterler. Eğer belirlenmiş bir süre olmasaydı, onlara azap gelirdi. Ve elbette onlara, hiç farkında olmadıkları bir sırada ansızın gelecektir.'),
(29, 54, 21, 403, 'يَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'yastaʿcilūnak-a bil-ʿadhābi wa-inna Jahannama la-muḥīṭatun bil-kāfirīn', 'Sana acele ile azabı getirmelerini istiyorlar. Oysa cehennem, kâfirleri gerçekten kuşatmıştır.'),
(29, 55, 21, 403, 'يَوْمَ يَغْشَىٰهُمُ ٱلْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا۟ مَا كُنتُمْ تَعْمَلُونَ', 'yawma yaghsāhumu l-ʿadhābu min fawqihim wa-min taḥti arjulihim wa-yaqūlu dhūqū mā kuntum taʿmalūn', 'O gün azap, hem üstlerinden hem altlarından onları saracak ve (Allah) şöyle diyecektir: ''Tadın bakalım yaptıklarınızı!'''),
(29, 56, 21, 403, 'يَٰعِبَادِىَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ أَرْضِى وَٰسِعَةٌ فَإِيَّٰىَ فَٱعْبُدُونِ', 'yā ʿibādiya llaḏīna āmānū ʾinna ʾarḍī wāsiʿatun fa-ʾiyyāya fa-ʿbudūn', 'Ey iman eden kullarım! Şüphesiz benim yeryüzüm geniştir. Yalnız bana ibadet edin.'),
(29, 57, 21, 403, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ثُمَّ إِلَيْنَا تُرْجَعُونَ', 'kullu nafsin dhāʾiqatu l-mawti thumma ilayna turjaʿūna', 'Her nefis ölümü tadacaktır. Sonra bize döndürüleceksiniz.'),
(29, 58, 21, 403, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti lanubawwiʾannahum mina l-jannati ghurafan tajrī min taḥtihā l-ʾanhāru khālidīna fīhā niʿma ʾajru l-ʿāmilīna', 'İman edip salih amel işleyenleri ise, içinde ebedi kalacakları, altlarından ırmaklar akan cennet köşklerine yerleştireceğiz. (Salih) amelde bulunanların ecri ne güzeldir!'),
(29, 59, 21, 403, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'alladhīna ṣabarū wa ʿalā rabbihim yatawakkalūna', 'Onlar sabredenler ve Rablerine tevekkül edenlerdir.'),
(29, 60, 21, 403, 'وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa ka''ayyin min dābbatin lā taḥmilu rizqahā allāhu yarzuquhā wa''iyyākum wa huwa as-samīʿu al-ʿalīmu', 'Nice de (nice) canlılar vardır ki rızıklarını (yüklerini) yüklenmezler. Onları da sizleri de Allah rızıklandırır. Ve O, Semi''dir, Alîm''dir.'),
(29, 61, 21, 403, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', 'veleʾin seʾeltehum men ḫaleḳa essemâvâti velʾarḍa vesexḫara eşşemse velḳamera leyaḳûlünnallâhu feʾennâ yüʾfekûn', 'Andolsun ki onlara: “Gökleri ve yeri kim yarattı, güneşi ve ayı kim boyun eğdirdi?” diye sorsan, mutlaka “Allah” diyeceklerdir. O halde nasıl (haktan) çevriliyorlar?'),
(29, 62, 21, 403, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'Allāhu yabsutu r-rizqa liman yešāʾu min ʿibādihī wa yaqdiru lahū ʾinna Llāha bikulli šayʾin ʿalīmun', 'Allah kullarından dilediğinin rızkını genişletir ve (dilediğininkini) daraltır. Şüphesiz Allah her şeyi bilendir.'),
(29, 63, 21, 403, 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'Ve leʾin seʾeltehum men nezzele mine-s-semâʾi mâʾen feʾaḥyâ bihi-l-arḍa min baʿdi mevtihâ leyekūlunne-llâhu ḳuli-l-ḥamdu lillâhi bel ekśeruhum lâ yaʿḳilûn', 'Andolsun ki onlara, gökten su indirip de onunla ölümünden sonra yeryüzünü dirilten kimdir diye sorsan, mutlaka “Allah’tır” derler. De ki: “Hamd Allah’a mahsustur.” Hayır, onların çoğu akıl etmezler.'),
(29, 64, 21, 404, 'وَمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌ وَلَعِبٌ وَإِنَّ ٱلدَّارَ ٱلْءَاخِرَةَ لَهِىَ ٱلْحَيَوَانُ لَوْ كَانُوا۟ يَعْلَمُونَ', 've mā hādhihi l-ḥayātu d-dunyā illā lahwun wa laʿibun wa inna d-dāra l-ʾākhirata lahiya l-ḥayawānu law kānū yaʿlamūna', 'Bu dünya hayatı ancak bir oyun ve eğlenceden ibarettir. Ahiret yurdu ise, asıl hayat odur. Keşke bilselerdi.'),
(29, 65, 21, 404, 'فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ', 'fa-ʾidhā rakibū fī l-fulki daʿawu llāha mukhliṣīna lahu d-dīna fa-lammā najjāhum ʾilā l-barri ʾidhā hum yušrikūn', 'Gemiye bindikleri zaman, dini Allah''a has kılarak O''na dua ederler. Allah onları karaya kurtarınca, bir de bakarsın şirk koşmaktadırlar.'),
(29, 66, 21, 404, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا۟ فَسَوْفَ يَعْلَمُونَ', 'liyakfurū bimā ātaynāhum walīyatamattaʿū fasawfa yaʿlamūn', 'Kendilerine verdiğimiz nimetlere nankörlük etmeleri ve zevk edip yaşamaları için (onları böylece bırakırız). Ama yakında bileceklerdir.'),
(29, 67, 21, 404, 'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ', 'E-ve-lem yerav ennā ceʿalnā ḥarāmen ʾāminen ve-yutekhaṭṭafu n-nāsu min ḥavlihim E-fe-bil-bāṭili yuʾminūne ve-bi-niʿmeti llāhi yakfurūne', 'Onlar, bizim (Mekke''yi) güvenli bir harem kıldığımızı ve etraflarındaki insanların ise kapılıp götürüldüklerini görmüyorlar mı? Hala batıla inanıp Allah''ın nimetine nankörlük mü ediyorlar?'),
(29, 68, 21, 404, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِٱلْحَقِّ لَمَّا جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', 'Ve men aẓlamu mimmeni-fterā ʿalā Allāhi kaḏiban aw kaḏḏaba bil-ḥaqqi lammā ǧāʾahu ʾAleysa fī Ǧahannama maṯwan lil-kāfirīn', 'Allah''a karşı yalan uyduran veya kendisine geldiğinde hakkı yalanlayandan daha zalim kim olabilir? Kâfirler için cehennemde bir yer değil midir?'),
(29, 69, 21, 404, 'وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ', 'wa-lladhīna jāhadū fīnā lanahdiyannahum subulanā wa-inna llāha lamaʿa l-muḥsinīna', 'Bizim uğrumuzda cihad edenleri elbette kendi yollarımıza ileteceğiz. Şüphesiz Allah, iyilik edenlerle beraberdir.'),
(30, 1, 21, 404, 'الٓمٓ', 'Elif, Lâm, Mîm.', 'Elif, Lâm, Mîm.'),
(30, 2, 21, 404, 'غُلِبَتِ ٱلرُّومُ', 'ghulibat ir-rūm', 'Rum Suresi'),
(30, 3, 21, 404, 'فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'fī adnal-arḍi wa hum min baʿdi ġalibihim sayaglibūn', 'Yeryüzünün en yakın (en alçak) tarafında ve onlar, yenilgilerinden sonra galip geleceklerdir.'),
(30, 4, 21, 404, 'فِى بِضْعِ سِنِينَ لِلَّهِ ٱلْأَمْرُ مِن قَبْلُ وَمِنۢ بَعْدُ وَيَوْمَئِذٍ يَفْرَحُ ٱلْمُؤْمِنُونَ', 'fī biḍʿi sinīn lillāhi l-amru min qablu wa-min baʿd wa-yawmaʾiḏin yafraḥu l-muʾminūn', 'Olay, daha önce de sonra da Allah''ın emri iledir. Ve o gün mü''minler sevineceklerdir.'),
(30, 5, 21, 404, 'بِنَصْرِ ٱللَّهِ يَنصُرُ مَن يَشَآءُ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'binasri llāh yanṣuru man yashāʾu wa huwa l-ʿazīzu r-raḥīmu', 'Allah''ın yardımıyla. O, dilediğini yardımıyla destekler. O, mutlak güç sahibidir, engin merhamet sahibidir.'),
(30, 6, 21, 405, 'وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'waʿda llāhi lā yukhlifu llāhu waʿdahū walākinna akthara n-nāsi lā yaʿlamūn', 'Allah''ın vaadi haktır. Allah vaadinden dönmez, fakat insanların çoğu bilmezler.'),
(30, 7, 21, 405, 'يَعْلَمُونَ ظَٰهِرًا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْءَاخِرَةِ هُمْ غَٰفِلُونَ', 'yaʿlamūna ẓāhiran mina l-ḥayāti d-dunyā wa-hum ʿani l-ʾākhirati hum ġāfilūn', 'Onlar dünya hayatının sadece dışını bilirler; ahiretten ise tamamen habersizdirler.'),
(30, 8, 21, 405, 'أَوَلَمْ يَتَفَكَّرُوا۟ فِىٓ أَنفُسِهِم مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَٰفِرُونَ', 'ʾawalam yatafakkarū fī ʾanfusihim mā khalaqa ʾllāhu s-samāwāti wa-l-ʾarḍa wa-mā baynahumā ʾillā bi-l-ḥaqqi wa-ʾajalin musammā wa-ʾinna kathīran mīn an-nāsi bi-liqāʾi rabbihim lakāfirūn', 'Onlar, Allah''ın gökleri, yeri ve ikisinin arasında bulunanları ancak hak ile ve belirli bir süre için yarattığını düşünmediler mi? Doğrusu insanların çoğu, Rablerine kavuşmayı inkâr ederler.'),
(30, 9, 21, 405, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا۟ ٱلْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'ʾA-wa-lam yasīrū fī l-ʾarḍi fa-yanẓurū kayfa kāna ʿāqibatu l-ladhīna min qablihim Kānū ʾashadda minhum quwwatan Wa-ʾathārū l-ʾarḍa wa-ʿamarūhā ʾakthara mimmā ʿamarūhā Wa-jāʾathum rusuluhum bil-bayyināti Fa-mā kāna l-lāhu li-yaẓlimahum wa-lākin kānū ʾanfusahum yaẓlimūn', 'Onlar, yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Onlar, kendilerinden daha kuvvetli idiler. Yeryüzünü ekip biçtiler ve ondan daha fazla imar ettiler. Peygamberleri onlara apaçık delillerle gelmişti. Allah onlara zulmetmiyordu, fakat onlar kendi nefislerine zulmediyorlardı.'),
(30, 10, 21, 405, 'ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ ٱلسُّوٓأَىٰٓ أَن كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا يَسْتَهْزِءُونَ', 'thumma kāna ʿāqibata alladhīna asāʾū as-sūʾā an kadhdhabū bi-ʾāyāti Allāhi wa kānū bihā yastahziʾūna', 'Sonra kötülük yapanların akıbeti, Allah''ın ayetlerini yalanlamaları ve onlarla alay ediyor olmalarıydı.'),
(30, 11, 21, 405, 'ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'Allāhu yabdaʾu l-ḫalqa ṯumma yuʿīduhu ṯumma ʾilayhi turjaʿūna', 'Allah, yaratmayı başlatır, sonra onu iade eder, sonra O''na döndürüleceksiniz.'),
(30, 12, 21, 405, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ', 'wa-yawma taqūmu s-sāʿatu yublisu l-mujrimūna', 'Kıyamet saatinin kopacağı gün, suçlular umutsuzluğa düşerler.'),
(30, 13, 21, 405, 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَٰٓؤُا۟ وَكَانُوا۟ بِشُرَكَآئِهِمْ كَٰفِرِينَ', 'wa lam yakun lahum min shurakāʾihim shufʿaʾā wa kānū bi shurakāʾihim kāfirīn', 'Onların ortaklarından kendilerine şefaat edecek kimseler de olmadı ve (onlar) ortak koştukları şeyleri inkâr ettiler.'),
(30, 14, 21, 405, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ', 'wa-yawma taqūmu s-sāʿatu yawmaʾiḏin yatafarraqūna', 'Ve o gün kıyamet koptuğu zaman, o gün (insanlar) bölük bölük ayrılırlar.'),
(30, 15, 21, 405, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَهُمْ فِى رَوْضَةٍ يُحْبَرُونَ', 'fa-ammā alladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti fa-hum fī rawḍatin yuḥbarūna', 'İman edip salih amel işleyenlere gelince, onlar cennet bahçesinde (mutlu) olacaklardır.'),
(30, 16, 21, 406, 'وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآئِ ٱلْءَاخِرَةِ فَأُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', 'waʾammā alladhīna kafarū wa kadhdhabū biʾāyātinā wa liqāʾi l-ʾākhirati faʾulāʾika fī l-ʿadhābi muḥḍarūna', 'İman edip salih amel işleyenlere gelince, onlar cennettedirler; orada ebediyen kalırlar. Allah''a verdikleri söze sadık kalanlara gelince, Allah onların iyiliklerini kat kat artırır ve onlara büyük bir mükâfat verir.'),
(30, 17, 21, 406, 'فَسُبْحَٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', 'fasubḥāna llāhi ḥīna tumsūna waḥīna tuṣbiḥūna', 'Öyleyse akşama girdiğinizde ve sabaha çıktığınızda Allah''ı tesbih edin.'),
(30, 18, 21, 406, 'وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ', 'wa-lahu l-ḥamdu fī s-samāwāti wa-l-arḍi wa-ʿashiyyan wa-ḥīna tuẓ-hirūn', 'Göklerde ve yerde hamd O''na mahsustur; akşam vakti ve öğle vaktinde de O''na mahsustur.'),
(30, 19, 21, 406, 'يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَكَذَٰلِكَ تُخْرَجُونَ', 'yukhriju l-ḥayya mina l-mayyiti wa yukhriju l-mayyita mina l-ḥayyi wa yuḥyi l-arḍa baʿda mawatihā wa kaḏālika tukhrajūna', 'O, canlıyı ölümden çıkarır ve ölüyü de canlıdan çıkarır. Yeryüzünü ölümünden sonra O diriltir. Siz de (kabirlerinizden) işte böyle çıkarılacaksınız.'),
(30, 20, 21, 406, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُم بَشَرٌ تَنتَشِرُونَ', 'wa-min ʾāyātihi ʾan ḵalaqakum min turābin ṯumma ʾiḏā ʾantum bašarun tantaširūn', 'Ve O''nun ayetlerinden biri de sizi topraktan yaratması, sonra da bir de ne göresiniz, siz beşer olup yeryüzüne yayılmaktasınız.'),
(30, 21, 21, 406, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'Ve min ʾāyātihī ʾan ḫalaqa lakum min ʾanfusikum ʾazwājan litaskunū ʾilayhā Ve ǧaʿala baynakum mawaddatan wa-raḥmah ʾInna fī ḏālika la-ʾāyātin li-qawmin yatafakkirūn', 'Ve O''nun ayetlerinden biri de, kendileriyle kaynaşıp teskin bulacağınız eşleri sizin için yaratması ve aranıza sevgi ve merhamet koymasıdır. Şüphesiz bunda, tefekkür eden bir kavim için gerçekten ayetler vardır.'),
(30, 22, 21, 406, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّلْعَٰلِمِينَ', 'Ve min ʾāyātihī khalqu s-samāwāti wal-ʾarḍi wakhtilāfu ʾalsinatikum wa-ʾalwānikum ʾInna fī dhālika la-ʾāyātin lil-ʿālimīn', 'Göklerin ve yerin yaratılması, dillerinizin ve renklerinizin farklılığı da O''nun (varlığının) delillerindendir. Elbette bunlarda, bilenler için ibretler vardır.'),
(30, 23, 21, 406, 'وَمِنْ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيْلِ وَٱلنَّهَارِ وَٱبْتِغَآؤُكُم مِّن فَضْلِهِۦٓ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', 'wa-min ʾāyātihi manāmukum bil-layli wa-n-nahāri wa-btigāʾukum min faḍlihi ʾinna fī dhālika la-ʾāyātin li-qawmin yasmaʿūna', 'Geceleyin ve gündüzün uyumanız ve O''nun lütfundan (rızkınızı) aramanız da O''nun ayetlerindendir. Şüphesiz bunda, işiten bir kavim için nice ayetler vardır.'),
(30, 24, 21, 406, 'وَمِنْ ءَايَٰتِهِۦ يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءً فَيُحْىِۦ بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'wa-min ʾāyātihi yurīkum al-barqa khawfan wa-ṭamaʿan wa-yunazzilu mina as-samāʾi māʾan fa-yuḥyī bihi al-ʾarḍa baʿda mawrihā ʾinna fī dhālika la-ʾāyātin li-qawmin yaʿqilūn', 'O''nun ayetlerinden biri de, hem korku hem de ümit veren şimşeği size göstermesi ve gökten su indirerek, ölümünden sonra yeryüzünü canlandırmasıdır. Elbette bunda aklını kullanan bir topluluk için ibretler vardır.'),
(30, 25, 21, 407, 'وَمِنْ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلْأَرْضُ بِأَمْرِهِۦ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ ٱلْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ', 'wa-min ʾāyātihi ʾan taqūma s-samāʾu wa-l-ʾarḍu bi-ʾamrihi thumma ʾiḏā daʿākum daʿwatan mina l-ʾarḍi ʾiḏā ʾantum taḫrujūn', 'Göklerin ve yerin, O''nun emriyle durağı durması da O''nun varlığının delillerindendir. Sonra yeri kazıp (toprağı eşip) çıkardığı bir anda siz, (kabirlerinizden) çıkarsınız.'),
(30, 26, 21, 407, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', 'wa-lahū man fī s-samāwāti wa-l-arḍi kullun lahū qānitūna', 'Göklerde ve yerde kim varsa O''nundur. Hepsi O''na boyun eğmektedir.'),
(30, 27, 21, 407, 'وَهُوَ ٱلَّذِى يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ وَلَهُ ٱلْمَثَلُ ٱلْأَعْلَىٰ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'wa-huwa l-ladhī yabdau l-khalqa thumma yuʿīduhu wa-huwa ahwanu ʿalayhi wa-lahu l-mathalu l-aʿlā fī s-samāwāti wa-l-arḍi wa-huwa l-ʿazīzu l-ḥakīmu', 'O, yaratmayı başlatıp sonra onu iade eden (tekrar eden)dir. O, O''na daha kolaydır. Göklerde ve yerde en yüce misal O''nundur. Ve O, Azîz''dir, Hakîm''dir.'),
(30, 28, 21, 407, 'ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍ يَعْقِلُونَ', 'ḍaraba lakum mathalan min anfusikum hal lakum mimma malakat aymānukum min shurakāʾa fī mā razaqnākum fa-antum fīhi sawāʾun takhāfūnahum kak̲h̲īfatukum anfusakum kadhālika nufaṣṣilu l-ʾāyāti liqawmin yaʿqilūna', 'Allah, kendi kendinize size bir misal vermektedir: Size verdiğimiz rızıklarda, kölelerinizden herhangi biri üzerinde ortak mıdır ki siz (onlarla) eşit olmaktan korkasınız ve onlardan, kendinizden çekindiğiniz gibi çekinesiniz? İşte biz, aklını kullanan bir topluluk için ayetleri böyle açıklıyoruz.'),
(30, 29, 21, 407, 'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓا۟ أَهْوَآءَهُم بِغَيْرِ عِلْمٍ فَمَن يَهْدِى مَنْ أَضَلَّ ٱللَّهُ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'bal-i-ttabaʿa-lladhīna ẓalamū ahwāʾahum bi-ghayri ʿilmin fa-man yahdī man aḍalla-llāhu wa-mā lahum min nāṣirīn', 'Hayır, o zalimler hiçbir bilgiye dayanmadan kendi heveslerine uydular. Allah''ın saptırdığını kim doğru yola iletebilir? Onların hiçbir yardımcıları yoktur.'),
(30, 30, 21, 407, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'Fa aqim wajhaka lid-dīni ḥanīfan Fiṭrata Allāhi llatī faṭara n-nāsa ʿalayhā Lā tabdīla li-khalqi Allāh Dhālika d-dīnu l-qayyim Wa lākinna akthara n-nāsi lā yaʿlamūn', 'Öyleyse, hanîf olarak (tevhide yönelmiş olarak) yüzünü dine çevir. Allah''ın insanları üzerinde yarattığı fıtrat (dine yatkınlığı) üzerine (doğrul). Allah''ın yaratışında hiçbir değiştirme yoktur. İşte bu, dosdoğru dindir. Ancak insanların çoğu bilmezler.'),
(30, 31, 21, 407, 'مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ', 'munībīna ilayhi wāttaqūhu wa aqīmū ṣ-ṣalāta wa lā takūnū mina l-mušrikīn', 'O''na yönelerek (O''na dönerek) O''ndan korkun, namazı dosdoğru kılın ve müşriklerden olmayın.'),
(30, 32, 21, 407, 'مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 'mina alladhīna farraqū dīnahum wa kānū shiyaʿan kullu ḥizbin bimā ladayhim fariḥūn', 'Onlar, dinlerini parça parça edip gruplara ayrılanlardan oldular. Her bir grup, kendi ellerinde olanla sevinir.'),
(30, 33, 21, 408, 'وَإِذَا مَسَّ ٱلنَّاسَ ضُرٌّ دَعَوْا۟ رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', 'wa ''idhā massa an-nāsa ḍurrun daʿaw rabbahum munībīna ''ilayhi thumma ''idhā ''adhāqahum minhu raḥmatan ''idhā farīqun minhum bi-rabbihim yushrikūn', 'İnsanlara bir sıkıntı dokunduğu zaman, ona yönelerek Rablerine dua ederler. Sonra Allah onlara kendinden bir rahmet tattırdığı zaman, bakarsın onlardan bir kısmı Rablerine şirk koşarlar.'),
(30, 34, 21, 408, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'liyakfurū bimā ātaynāhum fatemattaʿū fasawfa taʿlamūn', 'Kendilerine verdiğimiz nimetlere nankörlük etsinler diye (böyle yaptık). Artık (dünyada) zevk edip yaşayın; ama yakında (gerçeği) bileceksiniz.'),
(30, 35, 21, 408, 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَٰنًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ يُشْرِكُونَ', 'am anzalnā ʿalayhim sulṭānan fa-huwa yatakallamu bimā kānū bihi yushrikūn', 'Yoksa onlara (kendi lehlerine) bir delil mi indirdik ki o, onların ortak koştukları şeyler hakkında konuşuyor?'),
(30, 36, 21, 408, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً فَرِحُوا۟ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', 'wa-idhā adhāqnā an-nāsa raḥmatan fariḥū bihā wa-in tuṣibhum sayyiʾatun bimā qaddamat aydīhim idhā hum yaqnaṭūn', 'İnsanlara bir rahmet tattırdığımız zaman ona sevinirler. Ve eğer kendilerine yaptıkları (günahlar) yüzünden bir kötülük isabet ederse, hemen umutsuzluğa kapılırlar.'),
(30, 37, 21, 408, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'E-ve lem yeraw ennellāhe yebsuṭur-rizqa li-men yeşāʾu wa-yaqdiru İnne fī żālika le-āyātin li-kavmin yuʾminūn', 'Onlar, Allah''ın dilediğine rızkı bol verdiğini ve (dilediğinden de) kıstığını görmüyorlar mı? Elbette bunda, iman eden bir kavim için ibretler vardır.'),
(30, 38, 21, 408, 'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'faʾāti ḏā l-qurbā ḥaqqahū wa l-miskīna wa bna s-sabīli ḏālika ḫayrun li-lläḏīna yurīdūna wajha llāhi wa ʾulāʾika humu l-mufliḥūna', 'Yakınlığı olanlara haklarını ver; hem yoksula, hem de yolcuya da. Allah''ın rızasını dileyenler için bu, en iyisidir. İşte bunlardır kurtuluşa erenler.'),
(30, 39, 21, 408, 'وَمَآ ءَاتَيْتُم مِّن رِّبًا لِّيَرْبُوَا۟ فِىٓ أَمْوَٰلِ ٱلنَّاسِ فَلَا يَرْبُوا۟ عِندَ ٱللَّهِ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍ تُرِيدُونَ وَجْهَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُضْعِفُونَ', 'Ve mā ātaytum min riban liyarbūa fī amwāli n-nāsi falā yarbūa ʿinda llāhi Ve mā ātaytum min zakātin turīdūna wajha llāhi faʾūlāʾika humu l-muḍʿifūna', 'İnsanların malları içinde, artması umuduyla verdiğiniz her ribâ (faiz), Allah katında artmaz. Ama Allah''ın rızasını dileyerek verdiğiniz zekâtlar ise, işte onlar (mallarını kat kat) artıranlardır.'),
(30, 40, 21, 408, 'ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'Allāhu alladhī khalaqakum thumma razaqakum thumma yumītu kum thumma yuḥyīkum Hal min shurakā''ikum man yaf''alu min dhālikum min shay''in Subḥānahū wa taʿālā ʿammā yushrikūn', 'Allah, sizi yaratan, sonra rızık veren, sonra sizi öldüren, sonra sizi dirilten Allah''tır. Ortaklarınızdan herhangi biri bunlardan herhangi birini yapabilir mi? O, onların ortak koştuklarından münezzeh ve yücedir.'),
(30, 41, 21, 408, 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', 'ẓahara l-fasādu fī l-barri wa-l-baḥri bimā kasabat ʾaydī n-nāsi li-yudīqahum baʿḍa l-ladhī ʿamilū laʿallahum yarjiʿūna', 'İnsanların kendi işledikleri yüzünden karada ve denizde fesat ve bozulma ortaya çıkmıştır. Böylece Allah, işlediklerinin (kötülüklerinin) bir kısmını onlara tattıracaktır; belki de (hakka) dönerler.'),
(30, 42, 21, 409, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', 'qul sīrū fī l-arḍi fa-nẓurū kayfa kāna ʿāqibatu l-ladhīna min qablu kāna aktharuhum mushrikīna', 'De ki: "Yeryüzünde dolaşın da daha öncekilerin akıbeti nasıl olmuş görün. Onların çoğu müşrikti."'),
(30, 43, 21, 409, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ٱلْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ يَوْمَئِذٍ يَصَّدَّعُونَ', 'faʾaqim wajhaka lid-dīni l-qayyim min qabli ʾan yaʾtiya yawmun lā maradda lahū mina llāh yawmaʾiḏin yaṣṣaddaʿūn', 'Artık, Allah''tan gelmesi muhakkak olan ve kendisini geri çevirecek bir gün gelmezden önce, yüzünü dosdoğru dine çevir. O gün insanlar bölük bölük ayrılacaklardır.'),
(30, 44, 21, 409, 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَمَنْ عَمِلَ صَٰلِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ', 'man kafara faʿalayhi kuphruhu wa man ʿamila ṣāliḥan falaʾnfusihim yamhadūn', 'Kim inkâr ederse, inkârı kendi aleyhinedir. Kim de salih amel işlerse, onlar kendi hazırlıklarını (cennet için) yapmış olurlar.'),
(30, 45, 21, 409, 'لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ إِنَّهُۥ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 'li-yajziya alladhīna āmānū wa ʿamilū ṣ-ṣāliḥāti min faḍlihī ʾinnahu lā yuḥibbu l-kāfirīn', 'Böylece iman edip salih amel işleyenlere kendi fazlından mükâfat verecektir. Şüphesiz O, kâfirleri sevmez.'),
(30, 46, 21, 409, 'وَمِنْ ءَايَٰتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ ٱلْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'wa min āyātihī ʾan yursila r-riyāḥa mubashshirātin wa liyudhīqakum min raḥmatihī wa litajriya l-fulku bi-ʾamrihī wa litabtughū min faḍlihī wa laʿallakum tashkurūn', 'Rüzgârları müjde vericiler olarak göndermesi, size rahmetinden tattırması, emriyle gemilerin seyretmesi ve sizin de O''nun fazlından (nasibinizi) aramanız O''nun ayetlerindendir. Umulur ki şükredersiniz.'),
(30, 47, 21, 409, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ', 'Ve lekad erselnâ min kablike rusulen ilâ kavmihim Fe câûhum bil beyyinâti Fentekamnâ minellezîne ecramû Ve kâne hakkan aleynâ nasrul mu''minîne', 'Andolsun ki senden önce de kendi kavimlerine nice elçiler gönderdik. Onlara apaçık delillerle geldiler. Sonra biz de suç işleyenlerden intikam aldık. Müminlere yardım etmek üzerimize bir hak idi.'),
(30, 48, 21, 409, 'ٱللَّهُ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُۥ فِى ٱلسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 'Allāhu alladhī yursilu ar-riyāḥa fatuthīru saḥāban fayabsuṭuhu fī as-samāʾi kayfa yashāʾu wa yajʿaluhu kisafan fatara al-wadqa yakhruju min khilālihī fa-idhā aṣāba bihī man yashāʾu min ʿibādihī idhā hum yastabshirūn', 'Allah, rüzgârları gönderen, böylece bulutları kımıldatan, sonra onları gökte dilediği gibi yayıp parça parça eden ve ardından da onların arasından yağmurun çıktığını göreceğin O''dur. Nihayet bu yağmurla kullarından dilediğine ulaştırdığı zaman, hemen sevinirler.'),
(30, 49, 21, 409, 'وَإِن كَانُوا۟ مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ', 'wa-ʾinna kānū min qabli ʾan yunazzala ʿalayhim min qablihi lamublisīn', 'Ve daha önce, ona indirilmeden önce, gerçekten de umutsuzluğa kapılmışlardı.'),
(30, 50, 21, 409, 'فَٱنظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'fa-nẓur ilā āthāri raḥmati llāhi kayfa yuḥyi l-arḍa baʿda mawatihā ʾinna dhālika la-muḥyi l-mawtā wa-huwa ʿalā kulli shayʾin qadīr', 'Allah''ın rahmetinin eserlerine bak; yeryüzünü ölümünden sonra nasıl diriltiyor! Şüphesiz O, ölüleri de işte böyle diriltir. O, her şeye hakkıyla gücü yetendir.'),
(30, 51, 21, 410, 'وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا۟ مِنۢ بَعْدِهِۦ يَكْفُرُونَ', 'Ve leʾin erselnâ rîhan feraʾavhu musferran leżallû min baʿdihî yekfurûn', 'Andolsun ki eğer bir rüzgar göndersek de onu (ekini) sararmış görseler, ardından mutlaka nankörlük etmeye başlarlar.'),
(30, 52, 21, 410, 'فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'fa-innaka lā tusmiʿu l-mawtā wa-lā tusmiʿu ṣ-ṣumma d-duʿāʾa idhā wallaw mudbirīn', 'Şüphesiz sen ölülere (sözünü) duyuramazsın ve arkalarını dönüp kaçmış olduklarında sağırlara da daveti duyuramazsın.'),
(30, 53, 21, 410, 'وَمَآ أَنتَ بِهَٰدِ ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', 've mā anta bi-hādī l-ʿumī ʿan ḍalālatihim in tusmiʿu illā men yuʾminu bi-ʾāyātinā fe-hum muslimūn', 'Sen, onların sapıklıklarından dolayı körlere yol gösterici değilsin. Sen, ancak âyetlerimize iman edip de müslüman olanlara (sözümüzü) duyurabilirsin.'),
(30, 54, 21, 410, 'ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً يَخْلُقُ مَا يَشَآءُ وَهُوَ ٱلْعَلِيمُ ٱلْقَدِيرُ', 'Allāhu alladhī khalaqakum min ḍaʿfin thumma jaʿala min baʿdi ḍaʿfin quwwatan thumma jaʿala min baʿdi quwwatin ḍaʿfan wa-shaybatan yakhluqu mā yashāʾu wa-huwa l-ʿalīmu l-qadīru', 'Allah, sizi zayıf yaratan, sonra zayıflıktan sonra güç veren, sonra güçten sonra yine zayıflık ve ihtiyarlık veren Allah''tır. O, dilediğini yaratır. Ve O, en iyi bilen, her şeye gücü yeten''dir.'),
(30, 55, 21, 410, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ', 'wa yawma taqūmu s-sāʿatu yuqsimu l-mujrimūna mā labithū ġayra sāʿatin kaḏālika kānū yuʾfakūna', 'Kıyamet kopacağı gün, suçlular ''Bir saatten başka kalmadık'' diye yemin ederler. İşte onlar (gerçekten) nasıl da aldatılıyorlardı!'),
(30, 56, 21, 410, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَٱلْإِيمَٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَٰبِ ٱللَّهِ إِلَىٰ يَوْمِ ٱلْبَعْثِ فَهَٰذَا يَوْمُ ٱلْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', 'waqāla alladhīna ūtū al-ʿilma wa-l-ʾīmāna laqad labitstum fī kitābi Allāhi ʾilā yawmi al-baʿthi fahādhā yawmu al-baʿthi walākinnakum kuntum lā taʿlamūna', 'Kendilerine ilim ve iman verilenler şöyle derler: "Andolsun ki siz, Allah''ın yazısında (hükmünde) belirlenmiş olan kıyamet gününe kadar kaldınız. İşte bu, kıyamet günüdür. Ama siz (bunu) bilmiyordunuz."'),
(30, 57, 21, 410, 'فَيَوْمَئِذٍ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُوا۟ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', 'fa-yawmaʾiḏin lā yanfaʿu ʾallaḏīna ẓalamū maʿḏiratuhum wa-lā hum yustaʿtabūn', 'İşte o gün, zulmedenlere mazeretleri fayda vermez ve onlardan (Allah''ı razı edecek amellerle) hoşnutluk da istenmez.'),
(30, 58, 21, 410, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ وَلَئِن جِئْتَهُم بِـَٔايَةٍ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', 'Ve lekad darabnâ lin-nâsi fî hâzâl-kur''âni min kulli mesel Ve lein ci''tehum bi-âyetin le-yekûlunne-llezîne keferû İn entum illâ mubtılûn', 'Andolsun ki Biz, bu Kur''an''da insanlar için her türlü misali verdik. Andolsun ki onlara bir ayet getirsen, o inkâr edenler mutlaka şöyle diyeceklerdir: "Siz ancak bâtıl şeyler ortaya koyanlarsınız."'),
(30, 59, 21, 410, 'كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ', 'kadhalika yatba''u Allahu ''ala qulubi alladhina la ya''lamun', 'İşte Allah, bilmeyenlerin kalpleri üzerine böyle mühür basar.'),
(30, 60, 21, 410, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ', 'faṣbir ʾinna waʿda ʾllāhi ḥaqqun walā yastakiffannaka ʾlladhīna lā yūqinūn', 'Öyleyse sabret. Şüphesiz Allah''ın vaadi haktır. Ayetlerimizi yalanlayanlar veya bilgi sahibi olmayanlar seni asla hafifliğe sevk etmesin.'),
(31, 1, 21, 411, 'الٓمٓ', 'ʾelāme', 'Elif, Lâm, Mîm.'),
(31, 2, 21, 411, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', 'tilka ʾāyātu l-kitābi l-ḥakīmi', 'Bunlar, hikmet dolu Kitab''ın ayetleridir.'),
(31, 3, 21, 411, 'هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ', 'hudan wa raḥmatan lil-muḥsinīn', 'Onlar, iyilik edenlere bir hidayet ve bir rahmettir.'),
(31, 4, 21, 411, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 'alladhīna yuqīmūna ṣ-ṣalāta wa yuʾtūna z-zakāta wa hum bil-ʾākhirati hum yūqinūna', 'Onlar, namazı dosdoğru kılan, zekâtı veren ve ahirete de kesin olarak iman edenlerdir.'),
(31, 5, 21, 411, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'ʾūlāʾika ʿalā hudan min rabbihim wa ʾūlāʾika humu l-mufliḥūn', 'İşte onlar, Rab''leri tarafından (verilen) hidayet üzeredirler ve işte onlar, kurtuluşa erenlerdir.'),
(31, 6, 21, 411, 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'wa min an-nāsi man yashtarī lahwa al-ḥadīth liyuḍilla ʿan sabīli Allāhi biġayri ʿilmin wa yattakhidhahā huzuwan ulāʾika lahum ʿaḏābun muhīnun', 'İnsanlardan, Allah''ın yolundan (başkalarını) saptırmak için, hiçbir bilgiye sahip olmadan ve onu bir eğlence edinerek, boş ve anlamsız sözleri satın alan kimseler vardır. İşte bunlara rezil edici bir azap vardır.'),
(31, 7, 21, 411, 'وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', 'wa ʾiḏā tutlā ʿalayhi ʾāyātunā wallā mustakbirā kaʾan lam yasmaʿhā kaʾanna fī ʾuḏunayhi waqran fabašširhu biʿaḏābin ʾalīm', 'Ve ona âyetlerimiz okunduğu zaman, sanki onları hiç işitmemiş gibi, kulaklarında bir ağırlık varmış (gibi) büyüklük taslayarak yüz çevirir. İşte onu acı bir azapla müjdele!'),
(31, 8, 21, 411, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ ٱلنَّعِيمِ', 'ʾinna lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti lahum jannātu n-naʿīmi', 'Şüphesiz iman edip salih amel işleyenler için Naîm cennetleri vardır.'),
(31, 9, 21, 411, 'خَٰلِدِينَ فِيهَا وَعْدَ ٱللَّهِ حَقًّا وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'khālidīna fīhā waʿda Allāhi ḥaqqan wa huwa al-ʿazīzu al-ḥakīmu', 'Onlar orada ebedî kalıcıdırlar. Allah''ın vaadi haktır. O, Azîz''dir, Hakîm''dir.'),
(31, 10, 21, 411, 'خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', 'xalaqa s-samāwāti biġayri ʿamadin tarawnahā wa-alqā fī l-arḍi rawāsīya an tamīda bikum wa-baṯṯa fīhā min kulli dābbatin wa-anzalnā mina s-samāʾi māʾan fa-anbatnā fīhā min kulli zawjin karīmin', 'O, gökleri, direkleri görmediğiniz halde yarattı. Yeryüzüne de, sizi sarsmasın diye sarsılmaz dağlar koydu. Ve onun içinde her tür canlıdan yaydı. Gökten de su indirip orada her güzel çiftten bitkiler bitirdik.'),
(31, 11, 21, 411, 'هَٰذَا خَلْقُ ٱللَّهِ فَأَرُونِى مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦ بَلِ ٱلظَّٰلِمُونَ فِى ضَلَٰلٍ مُّبِينٍ', 'hādhā khalqu llāhi faʾarūnī mādhā khalaqa lladhīna min dūnihi bali ẓ-ẓālimūna fī ḍalālin mubīnin', 'Bu, Allah''ın yarattığıdır. Haydi gösterin bana O''ndan başkaları neler yaratmışlardır! Hayır, zalimler apaçık bir sapıklık içindedirler.'),
(31, 12, 21, 412, 'وَلَقَدْ ءَاتَيْنَا لُقْمَٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'Ve lekad āteynā Lukmāne el-hikmete enişkur lillāhi Ve men yeşkur fe-innemā yeşkur li-nefsihī Ve men kefera fe-innallāhe Ġanīyun Hamīdun', 'Andolsun ki Lokmân''a hikmet verdik: "Allah''a şükret!" Kim şükrederse ancak kendi lehine şükretmiş olur. Kim de nankörlük ederse, şüphesiz Allah Ganî''dir (hiçbir şeye muhtaç değildir), Hamîd''dir (övülmeye layıktır).'),
(31, 13, 21, 412, 'وَإِذْ قَالَ لُقْمَٰنُ لِٱبْنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ', 'wa-ʾidh qāla luqmānu li-bnihī wa-huwa yaʿiẓuhu yā-bunayya lā tušrik bi-l-lāhi ʾinna ʾš-širka la-ẓulmun ʿaẓīmun', 'Ve Lokman''ın, öğüt verirken oğluna şöyle dediğini hatırla: Yavrucuğum! Allah''a ortak koşma! Doğrusu şirk, elbette büyük bir zulümdür.'),
(31, 14, 21, 412, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ', 'wa waṣṣaynā al-insāna biwālidayhi ḥamalat''hu ummuhu wahnann ʿalā wahnin wa fiṣāluhu fī ʿāmayni ani shkur lī walwālidayka ilayya al-maṣīru', 'Biz insana, annesinin onu her gün azar azar zayıflayarak taşıdığını ve sütten kesilmesinin de iki yıl içinde olduğunu vasiyet ettik. (Onun için) hem bana hem de ana babana şükret. Dönüş yalnız banadır.'),
(31, 15, 21, 412, 'وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًا وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'wa-in jāhadāka ʿalā an tušrika bī mā laysa laka bihi ʿilmun falā tuṭiʿhumā wa-ṣāḥibhumā fī d-dunyā maʿrūfan wa-ttabiʿ sabīla man anāba ilayya thumma ilayya marjiʿukum fa-unabbiʾukum bimā kuntum taʿmalūn', 'Eğer, hakkında bilgin olmayan bir şeyi bana ortak koşman için seni zorlarlarsa, onlara itaat etme. Onlarla dünyada iyi geçin; Bana yönelenlerin yoluna uy. Sonra dönüşünüz yalnız Banadır. O zaman size yapmakta olduklarınızı haber vereceğim.'),
(31, 16, 21, 412, 'يَٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِى صَخْرَةٍ أَوْ فِى ٱلسَّمَٰوَٰتِ أَوْ فِى ٱلْأَرْضِ يَأْتِ بِهَا ٱللَّهُ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', 'yā bunayya inneha in taku mithqāla ḥabbatin min khardalin fatakun fī ṣakhratin aw fī s-samāwāti aw fī l-arḍi yaʾti bihā llāh inna llāha laṭīfun khabīr', 'Yavrucuğum! Şüphesiz yapılan bir hardal tanesi ağırlığındaki şey bile, ister bir kayanın içinde, ister göklerde, ister yerde olsun, Allah onu getirir. Şüphesiz Allah, latif (en ince işleri bilen) ve habîr (her şeyden haberdar) olandır.'),
(31, 17, 21, 412, 'يَٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 'yābunayya aqimi ṣ-ṣalāta waʾmur bil-maʿrūfi wanha ʿanil-munkari waṣbir ʿalā mā ʾaṣābaka ʾinna dhālika min ʿazmi l-ʾumūri', 'Yavrucuğum! Namazı kıl, iyiliği emret, kötülükten vazgeçir ve başına gelene sabret. Şüphesiz bunlar, azim gerektiren işlerdendir.'),
(31, 18, 21, 412, 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', 'wa lā tuṣaʿʿir ḵaddaka li-n-nāsi wa lā tamši fī l-arḍi maraḥan ʾinna llāha lā yuḥibbu kulla muḵtālin faḵūrin', 'Yüzünü insanlardan (tükürterek) çevirme ve yeryüzünde böbürlenerek yürüme! Çünkü Allah, kendini beğenip övünenlerin hiç birini sevmez.'),
(31, 19, 21, 412, 'وَٱقْصِدْ فِى مَشْيِكَ وَٱغْضُضْ مِن صَوْتِكَ إِنَّ أَنكَرَ ٱلْأَصْوَٰتِ لَصَوْتُ ٱلْحَمِيرِ', 'wa-qṣid fī mashyika wa-ghḍuḍ min ṣawtika inna ankara l-aṣwāti laṣawtu l-ḥamīri', 'Yürüyüşünde tabii (orta) ol ve sesinden (yüksek sesle konuşmaktan) da çekin. Şüphesiz, sesların en çirkin olanı, eşeklerin sesidir.'),
(31, 20, 21, 413, 'أَلَمْ تَرَوْا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةً وَبَاطِنَةً وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ', 'ʾalam taraw ʾanna ʾallāha saḵḵara lakum mā fī s-samāwāti wa mā fī l-ʾarḍi wa ʾasbaḡa ʿalaykum niʿamahu ẓāhiratan wa bāṭinatan wa mina n-nāsi man yujādilu fī ʾallāhi biḡayri ʿilmin wa lā hudan wa lā kitābin munīrin', 'Görmediniz mi ki Allah, göklerde ve yerde ne varsa hepsini sizin hizmetinize vermiş, açık ve gizli bütün nimetlerini üzerinize yaymıştır? İnsanlardan öylesi vardır ki, ne bir bilgisi, ne bir yol göstericisi, ne de aydınlatıcı bir kitabı olmadan Allah hakkında tartışmaya girer.'),
(31, 21, 21, 413, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'wa ʾiḏā qīla lahumu ʾttabiʿū mā ʾanzala ʾllāhu qālū bal nattabiʿu mā wajadnā ʿalayhi ʾābāʾanā ʾawalaw kāna ʾš-šayṭānu yadʿūhum ʾilā ʿaḏābi ʾs-saʿīri', 'Onlara, "Allah’ın indirdiğine uyun" dendiğinde, "Hayır, biz atalarımızı üzerinde bulduğumuz yola uyarız" derler. Şeytan onları çılgın ateşin azabına çağırıyor olsa bile mi?'),
(31, 22, 21, 413, 'وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'wa-man yuslim wajhahu ʾilā ʾallāhi wa-huwa muḥsinun fa-qadi stamsaka bi-l-ʿurwati l-wuthqā wa-ʾilā ʾallāhi ʿāqibatu l-ʾumūri', 'Kim yüzünü Allah''a çevirir ve iyilik edenlerden olursa, şüphesiz o, en sağlam kulpa tutunmuş olur. Bütün işlerin sonu ancak Allah''adır.'),
(31, 23, 21, 413, 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا۟ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'wa man kafara falā yaḥzunnaka kufrhuʾ ʾilayna marjiʿuhum fananabbiʾuhum bimā ʿamilūʾ ʾinna ʾallāha ʿalīmun biḏāti ṣ-ṣudūr', 'Kim inkâr ederse, onun inkârı seni üzmesin. Onların dönüşü banadır. O zaman onlara yaptıklarını haber vereceğiz. Şüphesiz Allah, göğüslerde olanı bilendir.'),
(31, 24, 21, 413, 'نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ', 'numatti''uhum qalilan thumma naḍṭarruhum ila ''adhabin ghalizhin', 'Onları az bir süre (dünya nimetlerinden) faydalandırırız, sonra da onlara ağır bir azaba sürükleriz.'),
(31, 25, 21, 413, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'Ve leʾin seʾeltehum men ḫaleḳa es-semâvâti ve el-ʾarḍa leyaḳūlunne Allâhu ḳuli el-ḥamdu lillâhi bel ekṡeruhum lâ yaʿlemūne', 'Andolsun ki onlara, “Gökleri ve yeri kim yarattı?” diye sorsan, mutlaka “Allah” diyeceklerdir. De ki: “Hamd Allah’a mahsustur.” Hayır, onların çoğu bilmezler.'),
(31, 26, 21, 413, 'لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'lillāhi mā fī s-samāwāti wa-l-arḍi ʾinna llāha huwa l-ġaniyyu l-ḥamīd', 'Göklerde ve yerde ne varsa hepsi Allah''ındır. Şüphesiz Allah, zengin olan, övgüye lâyık olanın ta kendisidir.'),
(31, 27, 21, 413, 'وَلَوْ أَنَّمَا فِى ٱلْأَرْضِ مِن شَجَرَةٍ أَقْلَٰمٌ وَٱلْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَٰتُ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'wa law annamā fī l-arḍi min shajaratin aqlāmun wa l-baḥru yamudduhu min baʿdihi sabʿatu abḥurin mā nafida-t kalimātu llāhi ʾinna llāha ʿazīzun ḥakīmun', 'Yeryüzündeki ağaçların hepsi kalem olsaydı, deniz de mürekkep olsaydı ve hatta denizden sonra yedi deniz daha olsaydı, yine de Allah''ın kelimeleri tükenmezdi. Şüphesiz Allah, Azîz''dir (mutlak güç sahibidir), Hakîm''dir (hüküm ve hikmet sahibidir).'),
(31, 28, 21, 413, 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'mā khalqukum walā baththukum illā kanafsin wāḥidatin ʾinna Llāha samīʿun baṣīrun', 'Sizi yaratmak da, tekrar diriltmek de ancak tek bir nefis gibidir. Şüphesiz Allah, hakkıyla işitendir, hakkıyla görendir.'),
(31, 29, 21, 414, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِىٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى وَأَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ', 'ʾalam tara ʾanna ʾallāha yūliju l-layla fī n-nahāri wa yūliju n-nahāra fī l-layli wa saḵḵara š-šamsa wa l-qamara kullun yajrī ʾilā ʾajalin musamman wa ʾanna ʾallāha bimā taʿmalūna ḵabīrun', 'Görmedin mi ki Allah, geceyi gündüze sokar ve gündüzü geceye sokar. Güneş ve Ay''ı da sizin emrinize amade kılmıştır. Her biri belirlenmiş bir vakte kadar akar. Ve şüphesiz Allah, yaptıklarınızdan haberdardır.'),
(31, 30, 21, 414, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'dhālika biʾanna ʾllāha huwa l-ḥaqqu waʾanna mā yadʿūna min dūnihi l-bāṭilu waʾanna ʾllāha huwa l-ʿaliyyu l-kabīru', 'İşte bu, Allah''ın hakk (gerçek) olduğunu ve O''nun dışında taptıklarının batıl (asılsız) olduğunu ve Allah''ın yüce ve büyük olduğunu bilmendir.'),
(31, 31, 21, 414, 'أَلَمْ تَرَ أَنَّ ٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِنِعْمَتِ ٱللَّهِ لِيُرِيَكُم مِّنْ ءَايَٰتِهِۦٓ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'ʾalam tara ʾanna l-fulka tajrī fī l-baḥri biniʿmati llāhi liyuriyakum min ʾāyātihī ʾinna fī dhālika laʾāyātin likulli ṣabbārin shakkūr', 'Görmedin mi ki, (o) gemiler, Allah''ın (sana olan) nimetlerinden (dolayı) denizde akıp gitmektedir. (Bu,) size O''nun ayetlerinden bir kısmını göstermek içindir. Şüphesiz bunda, (her) çok sabreden ve çok şükreden için elbette ibretler vardır.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(31, 32, 21, 414, 'وَإِذَا غَشِيَهُم مَّوْجٌ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍ كَفُورٍ', 'wa-ʾiḏā ġašiyahum mawjun kaẓ-ẓulali daʿawu ʾllāha muḫliṣīna lahu ʾd-dīna fa-lammā najjāhum ʾilā ʾl-barri fa-minhum muqtaṣidun wa-mā yajḥadu bi-ʾāyātinā ʾillā kullu ḫattārin kafūrin', 'Onları bir gölge gibi dalgalar kapladığı zaman, dini yalnız O''na has kılarak Allah''a yalvarırlar. Fakat Allah onları karaya çıkarıp kurtarınca, onlardan bir kısmı doğru yolda kalır. Zaten bizim ayetlerimizi, pek nankör vefasızlardan başkası inkar etmez.'),
(31, 33, 21, 414, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'yā ayyuhā n-nāsu ttaqū rabbakum wa-khshaw yawman lā yajzī wālidun ʿan waladihi wa-lā mawlūdun huwa jāzin ʿan wālidihi shayʾan inna waʿda llāhi ḥaqqun fa-lā taghurannakumul ḥayātu d-dunyā wa-lā yaghurrannakum bi-llāhi l-ghurūru', 'Ey insanlar! Rabbinizden çekinin ve babanın evladından, evladın da babasından hiçbir fedakârlık yapamayacağı (ve kimsenin kimseye bir fayda sağlayamayacağı) bir günden korkun. Şüphesiz Allah''ın vaadi gerçektir. Sakın dünya hayatı sizi aldatmasın; o çok aldatıcı da (şeytan) sizi Allah ile aldatmasın.'),
(31, 34, 21, 414, 'إِنَّ ٱللَّهَ عِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلْغَيْثَ وَيَعْلَمُ مَا فِى ٱلْأَرْحَامِ وَمَا تَدْرِى نَفْسٌ مَّاذَا تَكْسِبُ غَدًا وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍ تَمُوتُ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۢ', 'ʾinna ʾllāha ʿindahu ʿilmu s-sāʿah wa yunazzilu l-ḡayṯa wa yaʿlamu mā fī l-ʾarḥāmi wa mā tadrī nafsu m-māḏā taksibu ḡadā wa mā tadrī nafsu m-bi-ʾayyi ʾarḍin tamūtu ʾinna ʾllāha ʿalīmun ḵabīrun', 'Şüphesiz kıyamet ilmu Allah''ın yanındadır. Yağmuru O indirir, rahimlerde olanı O bilir. Hiç kimse yarın ne kazanacağını bilemez. Hiç kimse hangi topraklarda öleceğini de bilemez. Şüphesiz Allah, her şeyi bilen, her şeyden haberdar olandır.'),
(32, 1, 21, 415, 'الٓمٓ', 'ʾAlif-lām-mīm', 'Elif, Lâm, Mîm.'),
(32, 2, 21, 415, 'تَنزِيلُ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', 'Tanzīlu l-kitābi lā rayba fīhi min Rabbi l-ʿālamīn', 'Bu Kitab''ın indirilmesi, şüphe yok ki, âlemlerin Rabbi''ndendir.'),
(32, 3, 21, 415, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ بَلْ هُوَ ٱلْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', 'am yaqūlūna-ftrāhu bal huwa-lḥaqqu min rabbika litunḏira qawman mā atāhum min naḏīrin min qablika laʿallahum yahtadūna', 'Yoksa "Onu kendiliğinden uydurdu" mu diyorlar? Hayır, o Rabbinden gelen bir gerçektir. Senden önce kendilerine hiçbir uyarıcı gelmemiş bir kavmi uyarman için ki, doğru yolu bulalar.'),
(32, 4, 21, 415, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا شَفِيعٍ أَفَلَا تَتَذَكَّرُونَ', 'Allāhu alladhī khalaqa s-samāwāti wa-l-arḍa wa mā baynahumā fī sittati ayyāmin thumma stawā ʿalā l-ʿarshi mā lakum min dūnihi min waliyyin wa lā shafīʿin afalā tatadhakkarūna', 'Allah, gökleri ve yeri ve ikisi arasında bulunanları altı günde yaratan, sonra da Arş''a istivâ eden (yücelen)dir. Sizin O''ndan başka ne bir dostunuz ne de bir şefaatçiniz vardır. Hâlâ düşünmüyor musunuz?'),
(32, 5, 21, 415, 'يُدَبِّرُ ٱلْأَمْرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍ مِّمَّا تَعُدُّونَ', 'yudebbiru l-amra mina s-samāʾi ilā l-arḍi thumma yaʿruju ilayhi fī yawmin kāna miqdāruhu ʾalfa sanatin mimmā taʿuddūna', 'Gökten yere kadar olan bütün işleri O takdir edip yönetir. Sonra (bütün işler) sizin saymakta olduğunuz bin yıl kadar tutan bir günde O''na yükselir.'),
(32, 6, 21, 415, 'ذَٰلِكَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'dhālika ʿālimu l-ghaybi wa-sh-shahādati l-ʿazīzu r-raḥīmu', 'O, gaybı ve şehadeti bilen, mutlak güç sahibi, sonsuz merhamet sahibidir.'),
(32, 7, 21, 415, 'ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ وَبَدَأَ خَلْقَ ٱلْإِنسَٰنِ مِن طِينٍ', 'alladhī ʾaḥsana kulla shayʾin ḵalaqahū wa badaʾa ḵalqa l-ʾinsāni min ṭīn', 'O ki yarattığı her şeyi güzel yapmış ve insanı yaratmaya çamurdan başlamıştır.'),
(32, 8, 21, 415, 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةٍ مِّن مَّآءٍ مَّهِينٍ', 'thumma jaʿala naslahū min sulālatin min māʾin mahīnin', 'Sonra onun neslini, (insan) soyunu, (ve) aşağılayıcı bir sudan (spermden) bir özden (oluşturdu).'),
(32, 9, 21, 415, 'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'thumma sawwāhu wa nafakha fīhi min rūḥihi wa jaʿala lakumu s-samʿa wa-l-abṣāra wa-l-ʾafʾidata qalīlan mā tashkurūn', 'Sonra onu (insanı) düzgün bir biçimde yaratıp ona kendi ruhundan üfledi ve size kulaklar, gözler ve kalpler verdi. Ne kadar az şükrediyorsunuz!'),
(32, 10, 21, 415, 'وَقَالُوٓا۟ أَءِذَا ضَلَلْنَا فِى ٱلْأَرْضِ أَءِنَّا لَفِى خَلْقٍ جَدِيدٍۭ بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَٰفِرُونَ', 'wa qālū ʾaʾiḏā ḍalalnā fī l-ʾarḍi ʾaʾinnā lafī ḵalqin ǧadīd bal hum biliqāʾi rabbihim kāfirūn', 'Ve dediler ki: "Biz (toprakta) kaybolup gittikten sonra, gerçekten biz mi yeni bir yaratılışta olacağız?" Hayır, onlar Rablerine kavuşmayı inkâr edenlerdir.'),
(32, 11, 21, 415, 'قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'Qul yatawaffākum malaku l-mawti lladhī wukila bikum Thumma ilā rabbikum turjaʿūn', 'De ki: Sizinle görevlendirilen ölüm meleği canınızı alacak, sonra döndürülüp Rabbinize götürüleceksiniz.'),
(32, 12, 21, 416, 'وَلَوْ تَرَىٰٓ إِذِ ٱلْمُجْرِمُونَ نَاكِسُوا۟ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَٱرْجِعْنَا نَعْمَلْ صَٰلِحًا إِنَّا مُوقِنُونَ', 'wa law tarā iḏi l-muǧrimūna nākisū ruʾūsahim ʿinda rabbihim rabbanā abṣarnā wa-samiʿnā fa-rǧiʿnā naʿmal ṣāliḥan ʾinnā mūqinūna', 'Suçluları, Rablerinin huzurunda başlarını eğmiş olarak bir görsen! (Onlar şöyle derler:) "Rabbimiz! Gördük ve işittik. Şimdi bizi (dünyaya) geri gönder de salih amel işleyelim. Gerçekten biz artık iyice inanıyoruz."'),
(32, 13, 21, 416, 'وَلَوْ شِئْنَا لَءَاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'wa law shiʾnā laʾātaynā kulla nafsin hudāhā wa lākin ḥaqqa l-qawlu minnī laʾamlaʾanna jahannama mina l-jinnati wa n-nāsi ʾajmaʿīn', 'Eğer dileseydik, her nefse kendi hidayetini verirdik. Fakat benden şöyle bir söz (hakk) olarak gerçekleşti: Andolsun ki cehennemi, cinlerden ve insanlardan bütünüyle dolduracağım.'),
(32, 14, 21, 416, 'فَذُوقُوا۟ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَآ إِنَّا نَسِينَٰكُمْ وَذُوقُوا۟ عَذَابَ ٱلْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ', 'fa dhūqū bimā nasītum liqāʾa yawmikum hādhā ʾinnā nasīnākum wa dhūqū ʿadhāba l-khuldi bimā kuntum taʿmalūn', 'Şimdi tadın! Bu güne kavuşmayı unuttuğunuz için. Şüphesiz biz de sizi unuttuk. Tadın! Ebedîlik azabını, yapmakta olduğunuz işler yüzünden.'),
(32, 15, 21, 416, 'إِنَّمَا يُؤْمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًا وَسَبَّحُوا۟ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ', 'innamā yuʾminu bi-ʾāyātinā alladhīna idhā dhukkirū bihā kharrū sujjadan wa sabbahū biḥamdi rabbihim wa hum lā yastakbirūna', 'Bizim ayetlerimize ancak, kendilerine hatırlatıldığı zaman, onlar (secde ederek) düşenler, Rablerine hamdederek tesbih edenler ve büyüklük taslamayanlardır.'),
(32, 16, 21, 416, 'تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'tatajāfā junūbuhum ʿani l-maḍājiʿi yadʿūna rabbahum khawfan wa-ṭamaʿan wa-mimmā razaqnāhum yunfiqūna', 'Onlar, korku ve umutla Rablerine dua etmek üzere (ibadet için) yataklarından uzaklaşırlar. Kendilerine verdiğimiz rızıktan da harcarlar.'),
(32, 17, 21, 416, 'فَلَا تَعْلَمُ نَفْسٌ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍ جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'falā taʿlamu nafsun mā ʾukhfiya lahum min qurrati ʾaʿyunin jazāʾam bimā kānū yaʿmalūn', 'Yaptıklarına karşılık olarak, onlara göz aydınlığı olacak (nimetlerden) hangisinin kendileri için saklandığını hiçbir kimse bilemez.'),
(32, 18, 21, 416, 'أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا لَّا يَسْتَوُۥنَ', 'ʾafaman kāna muʾminan kaman kāna fāsiqan lā yastawūna', 'Mü''min olan kimse, fasık (yoldan çıkmış) olan kimse gibi olur mu? Hayır, onlar bir olmazlar.'),
(32, 19, 21, 416, 'أَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ جَنَّٰتُ ٱلْمَأْوَىٰ نُزُلًۢا بِمَا كَانُوا۟ يَعْمَلُونَ', 'Ammā alladhīna āmānū wa ʿamilū ṣ-ṣāliḥāt Fa lahum jannātu l-maʾwā nuzulan bimā kānū yaʿmalūn', 'İman edip salih amel işleyenlere gelince, yapmakta olduklarına karşılık olmak üzere, barınma yerleri olarak cennetler onlarındır.'),
(32, 20, 21, 416, 'وَأَمَّا ٱلَّذِينَ فَسَقُوا۟ فَمَأْوَىٰهُمُ ٱلنَّارُ كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَآ أُعِيدُوا۟ فِيهَا وَقِيلَ لَهُمْ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'waʾammā alladhīna fasaqū famaʾwāhumu n-nāru kullamā ʾarādū ʾan yakhrujū minhā uʿīdū fīhā waqīla lahum dhūqū ʿadhāba n-nāri lladhī kuntum bihi tukadhdhibūna', 'Fasık olup çıkanlara gelince, onların barınağı ateştir. Oradan her çıkmak istediklerinde, oraya geri çevrilirler ve onlara şöyle denir: "Yalanlamakta olduğunuz cehennem azabını tadın!"'),
(32, 21, 21, 417, 'وَلَنُذِيقَنَّهُم مِّنَ ٱلْعَذَابِ ٱلْأَدْنَىٰ دُونَ ٱلْعَذَابِ ٱلْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', 'wa lanudhīqannahum minal-ʿadhābil-adnā dūnal-ʿadhābil-akbar lʿallahum yarjiʿūn', 'Ve onları, belki dönerler diye, o büyük azaptan başka daha yakın olan azaptan da tattıracağız.'),
(32, 22, 21, 417, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ', 'wa-man aẓlamu mimman dhukkira bi-āyāti rabbihī thumma aʿraḍa ʿanhā ʾinnā mina l-mujrimīna muntaqimūn', 'Rabbinin ayetleriyle uyarılıp da sonra onlardan yüz çeviren kimseden daha zalim kim olabilir? Şüphesiz ki biz, suçlulardan intikam alıcılarız.'),
(32, 23, 21, 417, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَلَا تَكُن فِى مِرْيَةٍ مِّن لِّقَآئِهِۦ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'Ve lekad āteynā Mūsā el-Kitābe felā tekun fī miryetin min likāʾihī ve ceʿalnāhu huden li-benī Isrāʾīl', 'Andolsun ki Musa''ya Kitab''ı verdik. Bu yüzden sen, ona kavuşmaktan şüphe içinde olma. Onu İsrailoğulları için bir hidayet rehberi kıldık.'),
(32, 24, 21, 417, 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ وَكَانُوا۟ بِـَٔايَٰتِنَا يُوقِنُونَ', 'wa-jaʿalnā minhum ʾaʾimmatan yahdūna bi-ʾamrinā lamma ṣabarū wa-kānū bi-ʾāyātinā yūqinūn', 'Onlardan, sabredip ayetlerimize kesin olarak inanıyorlardı diye, buyruğumuzla doğru yolu gösteren önderler kıldık.'),
(32, 25, 21, 417, 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'ʾinna rabbaka huwa yafṣilu baynahum yawma l-qiyāmati fīmā kānū fīhi yaḵtalifūn', 'Şüphesiz ki Rabbin, kıyamet günü onların arasında, üzerinde ihtilaf ettikleri hususta hükmünü verecektir.'),
(32, 26, 21, 417, 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ أَفَلَا يَسْمَعُونَ', 'ʾa-wa-lam yahdi lahum kam ʾahlaknā min qablihim mina l-qurūni yamshūna fī masākinihim ʾinna fī dhālika la-ʾāyātin ʾafa-lā yasmaʿūna', 'Onlara, kendilerinden önce nice nesilleri yok ettiğimizi görmeleri (onları doğru yola) sevketmedi mi? Onlar, şimdi onların yerlerinde yürüyorlar. Bunda mutlaka ibretler vardır. Hâlâ işitmiyorlar mı?'),
(32, 27, 21, 417, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَسُوقُ ٱلْمَآءَ إِلَى ٱلْأَرْضِ ٱلْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمْ أَفَلَا يُبْصِرُونَ', 'ʾawalam yaraw ʾannā nasūqu l-māʾa ʾilā l-ʾarḍi l-juruzi fanukhriju bihi z-zarʿan taʾkulu minhu ʾanʿāmuhum wa-ʾanfusuhum ʾafalā yubṣirūn', 'Onlar, suyu (kurak) toprağa sürmekte olduğumuzu ve onunla ekinler bitirip de hem hayvanlarının hem de kendilerinin yediği şeyleri çıkarmakta olduğumuzu görmüyorlar mı? Hâlâ basiretli bakmayacaklar mı?'),
(32, 28, 21, 417, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hādhā l-fatḥu in kuntum ṣādiqīn', 'Ve derler ki: "Eğer doğru sözlüler iseniz, bu fetih ne zaman?"'),
(32, 29, 21, 417, 'قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ', 'qul yawma l-fatḥi lā yanfaʿu lladhīna kafarū ʾīmānuhum walā hum yunẓarūn', 'De ki: Fetih (o hakla batılın ayrıldığı) günü, o küfredenlere imanları fayda vermez ve onlara mühlet de verilmez.'),
(32, 30, 21, 417, 'فَأَعْرِضْ عَنْهُمْ وَٱنتَظِرْ إِنَّهُم مُّنتَظِرُونَ', 'fa-ʾaʿriḍ ʿanhum wa-ntẓir ʾinnahum muntaẓirūn', 'Onlardan yüz çevir ve bekle; şüphesiz onlar da beklemektedirler.'),
(33, 1, 21, 418, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'yā ayyuhā n-nabiyyu ttaqi l-lāha wa lā tuṭiʿi l-kāfirīna wa l-munāfiqīna inna l-lāha kāna ʿalīman ḥakīman', 'Ey Peygamber! Allah''tan kork, kâfirlere ve münafıklara uyma. Şüphesiz Allah, bilendir, hikmet sahibidir.'),
(33, 2, 21, 418, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'wa-ttabiʿ mā yūḥā ilayka min rabbika ʾinna ʾallāha kāna bimā taʿmalūna khabīran', 'Rabbinden sana vahyolunana uy. Şüphesiz Allah, yaptıklarınızdan haberdardır.'),
(33, 3, 21, 418, 'وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'wa tawakkal ʿalā Allāh wa kafā bi-llāhi wakīlā', 'Ve Allah''a güvenip dayan. Vekil olarak Allah yeter.'),
(33, 4, 21, 418, 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّٰٓـِٔى تُظَٰهِرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ', 'mā jaʿala ʾallāhu liragulin min qalbayni fī gawfihi wa mā jaʿala ʾazwāgaka-llāʾī tuẓāhirūna minhunna ʾummāhātikum wa mā jaʿala ʾadʿiyāʾaka-ʾabnāʾakum ḏālikum qawlukum bi-ʾafwāhikum wa-llāhu yaqūlu-lḥaqqa wa-huwa yahdī-ssabīla', 'Allah, bir adamın içine iki kalp koymamıştır. Sizin zihar yaptığınız eşlerinizi de analarınız kılmamıştır. Evlatlıklarınızı da kendi oğullarınız yapmamıştır. Bunlar sizin ağızlarınızla söylediğiniz (boş) sözlerdir. Allah hakkı söyler ve O, doğru yola iletir.'),
(33, 5, 21, 418, 'ٱدْعُوهُمْ لِءَابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'udʿūhum liʾābāʾihim huwa ʾaqsaṭu ʿinda ʾllāh faʾin lam taʿlamū ʾābāʾahum faʾikhwānukum fī d-dīni wa mawālikum wa laysa ʿalaykum junāḥun fīmā ʾakhṭaʾtum bihi wa lākin mā taʿammadat qulūbukum wa kāna ʾllāhu ghafūran raḥīmā', 'Onları babalarına (nispet ederek) çağırın. Bu, Allah katında daha adil bir davranıştır. Eğer babalarını bilmiyorsanız, o takdirde onlar dinde sizin kardeşleriniz ve mevalinizdir (dostlarınızdır). Yanılarak yaptıklarınızdan dolayı size bir vebal yoktur. Ancak kalplerinizin kasıtlı olarak yaptıklarından dolayı sorumlusunuz. Allah, çok bağışlayıcıdır, çok merhametlidir.'),
(33, 6, 21, 418, 'ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'an-nabiyyu awlā bil-muʾminīna min anfusihim wa-ʾazwājuhu ʾummahātuhum wa-ʾulū al-ʾarḥāmi baʿḍuhum ʾawlā bi-baʿḍin fī kitābi ʾallāhi mina al-muʾminīna wal-muhājirīna ʾillā ʾan tafʿalū ʾilā ʾawliyāʾikum maʿrūfan kāna dhālika fī al-kitābi masṭūran', 'Peygamber, müminlere kendi nefislerinden daha yakındır. Onun eşleri de onların anneleridir. Rahim sahipleri (akrabalar) ise Allah''ın Kitabı''nda, diğer müminlerden ve muhacirlerden (birbirlerine) daha yakındırlar; meğer ki dostlarınıza bir iyilik yapasınız. Bu, Kitap''ta (yazılmış) bir sırdır.'),
(33, 7, 21, 419, 'وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّۦنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', 'wa-ʾiḏ ʾaḵaḏnā mina n-nabiyyi-na mīṯāqa-hum wa-min-ka wa-min Nūḥin wa-ʾIbrāhīma wa-Mūsā wa-ʿĪsā b-ni Maryama wa-ʾaḵaḏnā min-hum mīṯāqan ġaliẓan', 'Hani biz peygamberlerden (itaat ve sadakat üzere) ahidlerini ve senden, Nuh''tan, İbrahim''den, Musa''dan ve Meryem oğlu İsa''dan da (böyle) ahidlerini almıştık. (Onlardan) sağlam bir söz almıştık.'),
(33, 8, 21, 419, 'لِّيَسْـَٔلَ ٱلصَّٰدِقِينَ عَن صِدْقِهِمْ وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًا', 'liyas''ala aṣ-ṣādiqīna ʿan ṣidqihim wa aʿadda lil-kāfirīna ʿadhāban alīman', 'Böylece Allah, doğrulara doğruluklarından dolayı mükâfat verir ve kâfirlere de elem dolu bir azap hazırlar.'),
(33, 9, 21, 419, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 'yā ʾayyuhā lladhīna ʾāmanū udhkurū niʿmata llāhi ʿalaykum idh jāʾatkum junūdun fa ʾarsalnā ʿalayhim rīḥan wa junūdan lam tarawhā wa kāna llāhu bimā taʿmalūna baṣīran', 'Ey iman edenler! Allah''ın size olan nimetini hatırlayın. Hani size ordular gelmişti de, biz onların üzerine bir rüzgâr ve sizin görmediğiniz ordular göndermiştik. Allah, yaptıklarınızı hakkıyla görmektedir.'),
(33, 10, 21, 419, 'إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', 'idh jāʾūkum min fawqikum wa-min ʾasfala minkum wa-idh zāghat al-ʾabṣāru wa-balaghat al-qulūbu al-ḥanājira wa-taẓunnūna bi-llāhi ẓ-ẓunūnā', 'Hani onlar size hem üstünüzden hem altınızdan gelmişlerdi. Hani gözler kaymış, yürekler ağızlara gelmişti. Allah hakkında türlü zanlarda bulunuyordunuz.'),
(33, 11, 21, 419, 'هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًا شَدِيدًا', 'hunālika-b-ubtuliya-l-muʾminūn wa-zulzilū zilzālan šadīdā', 'İşte orada müminler denendiler ve şiddetli bir sarsıntıya uğradılar.'),
(33, 12, 21, 419, 'وَإِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا', 'wa-ʾiḏ yaqūlu l-munāfiqūna wa-llaḏīna fī qulūbihim maraḍun mā waʿadanā llāhu wa-rasūluhū ʾillā ḡurūran', 'Hani, münafıklar ve kalplerinde hastalık olanlar şöyle diyorlardı: "Allah ve Rasûlü bize sadece aldatıcı bir vaadde bulunmuşlardır."'),
(33, 13, 21, 419, 'وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ وَيَسْتَـْٔذِنُ فَرِيقٌ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ إِن يُرِيدُونَ إِلَّا فِرَارًا', 'wa-ʾiḏ qālat ṭāʾifatun min-hum yā ʾahla yaṯriba lā muqāma lakum farjiʿū wa-yastaʾḏinu farīqun min-humu n-nabiyya yaqūlūna ʾinna buyūtanā ʿawratun wa-mā hiya bi-ʿawratin ʾin yurīdūna ʾillā firāran', 'Hani onlardan bir grup: "Ey Yesrib (Medine) halkı! Sizin için duracak yer yok, hemen dönün!" demişti. Yine onlardan bir topluluk da: "Evlerimiz (korunmaya muhtaç, düşmana açık) bomboş kalmıştır" diyerek Peygamber''den izin istiyordu. Oysa evleri bomboş kalmış değildi; onlar sadece kaçmak istiyorlardı.'),
(33, 14, 21, 419, 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَءَاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًا', 'wa-law dukhilat ʿalayhim min aqṭārihā thumma suʾilū al-fitnata laʾātūhā wa-mā talabbaṯū bihā ʾillā yasīrā', 'Onların üzerine şehirlerin her tarafından girilseydi, sonra da kendilerine fitne (irtidat) teklif edilseydi, mutlaka onu kabul ederlerdi ve ona pek az bir zaman tutunurlardı.'),
(33, 15, 21, 419, 'وَلَقَدْ كَانُوا۟ عَٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَٰرَ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًا', 'Ve lekad kânû ''âhedûllâhe min kablu lâ yuvellûnel edbâra ve kâne ''ahdullâhi mes''ûlâ', 'Andolsun ki daha önce Allah''a, arkalarını dönmeyeceklerine dair söz vermişlerdi. Allah''a verilen söz ise sorumluluk gerektirir.'),
(33, 16, 21, 420, 'قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا', 'qul lan yanfaʿakumu l-firāru in farartum mina l-mawti awi l-qatli wa-idhan lā tumattaʿūna illā qalīlan', 'De ki: Eğer ölümden veya öldürülmekten kaçacak olursanız, kaçmanız size asla fayda vermez. O takdirde de (dünyada) pek az bir süre yaşatılırsınız.'),
(33, 17, 21, 420, 'قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'Kul men zâ ellezî ya''sımukum minallâhi in erâde bikum sûen ev erâde bikum rahmeten ve lâ yecidûne lehum min dûnillâhi veliyyen ve lâ nasîrâ', 'De ki: "Eğer Allah size bir kötülük dilerse veya bir rahmet dilerse, sizi O''ndan kim koruyabilir?" Onlar, Allah''tan başka kendilerine ne bir dost ne de bir yardımcı bulabilirler.'),
(33, 18, 21, 420, 'قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا', 'qad yaʿlamu llāhu l-muʿawwiqīna minkum wa-l-qāʾilīna li-ʾikhwānihim halumma ʾilayna wa-lā yaʾtūna l-baʾsa ʾillā qalīlan', 'Allah, içinizden (savaşa katılmayıp) alıkoyanları ve kardeşlerine, "Bize gelin, (savaşa) çıkmayın" diyenleri bilir. Zaten onlar, savaşın pek azına gelirler.'),
(33, 19, 21, 420, 'أَشِحَّةً عَلَيْكُمْ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ أُو۟لَٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَٰلَهُمْ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'ʾashiḥḥatan ʿalaykum faʾiḏā ǧāʾa ʾl-ḫawfu raʾaytahum yanẓurūna ʾilayka tadūru ʾaʿyunuhum ka-llaḏī ʾuġšā ʿalayhi mina ʾl-mawt faʾiḏā ḏahaba ʾl-ḫawfu salaqūkum bi-ʾalsinatin ḥidādin ʾashiḥḥatan ʿalā ʾl-ḫayr ʾulāʾika lam ʾūʾminū faʾaḥbaṭa ʾllāhu ʾaʿmālahum wa-kāna ḏālika ʿalā ʾllāhi yasīran', 'Size karşı cimri (ve hasis) davranırlar. Korku geldiği zaman, ölümün kendisini çarptığı kimse gibi gözlerinin kayarak sana baktığını görürsün. Korku gidince, ganimet (veya hayır) konusunda size karşı keskin dilleriyle (sövüp sayarak) size saldırırlar. Bunlar iman etmemişlerdir. Allah onların amellerini boşa çıkarmıştır. Bu, Allah''a göre kolaydır.'),
(33, 20, 21, 420, 'يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ وَلَوْ كَانُوا۟ فِيكُم مَّا قَٰتَلُوٓا۟ إِلَّا قَلِيلًا', 'yaḥsabūna l-ʾaḥzāba lam yaḏ-habū wa-ʾin yaʾti l-ʾaḥzābu yawaddū law ʾanna-hum bādūna fī l-ʾaʿrābi yasʾalūna ʿan ʾanbāʾikum wa-law kānū fīkum mā qātalū ʾillā qalīlan', 'Onlar, (düşman) grupların gitmediğini sanırlar. Eğer gruplar (tekrar) gelecek olursa, (çöle) göçebeler arasında bulunup size ait haberleri soran bedeviler olmayı ne kadar isterler! İçinizde olsalar bile, pek az savaşırlardı.'),
(33, 21, 21, 420, 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًا', 'laqad kāna lakum fī rasūli llāhi uswatun ḥasanatun liman kāna yarjū llāha wa-l-yawma l-ʾākhira wa-dhakara llāha kathīran', 'Andra ki, Allah''ın Resûlü sizin için güzel bir örnek (üsve-i hasene) vardır. Allah''a ve ahiret gününe kavuşmayı uman, Allah''ı çok zikreden kimseler için.'),
(33, 22, 21, 420, 'وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًا وَتَسْلِيمًا', 'Ve lemmā raʾā l-muʾminūna l-aḥzāb Qālū hādhā mā waʿadanā llāhu wa rasūluh Wa ṣadaqa llāhu wa rasūluh Wa mā zādahum illā īmānan wa taslīmā', 'Mü''minler toplulukları (grupları) gördükleri zaman dediler ki: "Bu, Allah''ın ve Resûlü''nün bize vaadettiği şeydir. Allah ve Resûlü doğru söylemiştir." Bu, onların ancak imanlarını ve teslimiyetlerini artırdı.'),
(33, 23, 21, 421, 'مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌ صَدَقُوا۟ مَا عَٰهَدُوا۟ ٱللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا۟ تَبْدِيلًا', 'minel mu''minîne ricālun ṣadaqū mā ʿāhadūllāhe ʿalayhi faminhum men qaḍā naḥbehu veminhum men yantaẓir ve mā baddelū tabdīlā', 'Mü''minlerden öyle adamlar vardır ki, Allah''a verdikleri söze (bağlılıkta) sadakat gösterdiler. Onlardan kimi adağını yerine getirdi (canını verdi), kimi de (o görevi beklemektedir). Onlar, verdikleri sözü hiçbir şekilde değiştirmediler.'),
(33, 24, 21, 421, 'لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'li-yajziya Allāhu ṣ-ṣādiqīna bi-ṣidqihim wa yuʿaḏḏiba l-munāfiqīna in šāʾa aw yatūba ʿalayhim ʾinna Allāha kāna ġafūran raḥīmā', 'Böylece Allah, doğrulara doğruluklarının mükâfatını versin ve dilerse munafıklara azap etsin veya onlara tövbe nasip etsin. Şüphesiz Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(33, 25, 21, 421, 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًا وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًا', 'wa radda allāhu alladhīna kafarū bi ghayẓihim lam yanālū khayran wa kafā allāhu l muʾminīna l qitāla wa kāna allāhu qawiyyan ʿazīzan', 'Allah, inkâr edenleri hiçbir fayda elde edememiş olarak kin ve öfkeleriyle geri çevirdi. Ve Allah, müminlere (yardımıyla) savaş(ın yükünü) kaldırmada kâfî geldi. Allah, kâvi (çok güçlü) ve azîz (mutlak galip) olandır.'),
(33, 26, 21, 421, 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا', 'wa anzalalladhīna dhāharūhum min ahlil-kitābi min ṣayāṣīhim wa qadhafa fī qulūbihimu ar-ruʿba farīqan taqtulūna wa taʾsirūna farīqan', 'Kendileriyle zâhirleşen (eşleriyle ilişkilerini kesen) Ehl-i Kitap''tan olanları ise kalelerinden indirdi ve onların kalplerine korku saldı. Bir kısmını öldürüyordunuz, bir kısmını da esir alıyordunuz.'),
(33, 27, 21, 421, 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَـُٔوهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', 'wa awraṯakum arḍahum wa diyārahum wa amwālahum wa arḍan lam taṭaʾūhā wa kāna ʾallāhu ʿalā kulli šayʾin qadīrā', 'Ve onların topraklarına, yurtlarına ve mallarına ve henüz ayak basmadığınız topraklara sizi mirasçı kıldı. Allah her şeye hakkıyla gücü yetendir.'),
(33, 28, 21, 421, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا', 'yā ayyuhā an-nabiyyu qul li-azwājika in kuntunna turidna al-ḥayāta ad-dunyā wa-zīnatahā fa-taʿālayna umattiʿkunna wa-usarriḥkunna sarāḥan jamīlan', 'Ey Peygamber! Hanımlarına şöyle söyle: Eğer dünya hayatını ve zinetini istiyorsanız, gelin size (istediğiniz şeyler) hakkında bir şeyler vereyim ve sizi güzel bir şekilde boşayayım.'),
(33, 29, 21, 421, 'وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْءَاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًا', 'Ve in kuntunne turidne Allâhe ve resûlehu ve ed-dâre el-âhirete fe-inne Allâhe e''adde lil-muhsinâti minkunne ecran azîmen', 'Eğer Allah''ı, Resûlü''nü ve ahiret yurdunu istiyorsanız, şüphesiz Allah, aranızdan iyilik yapanlara büyük bir ecir hazırlamıştır.'),
(33, 30, 21, 421, 'يَٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍ مُّبَيِّنَةٍ يُضَٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'yā nisāʾa n-nabiyyi man yaʾti minkunna bi-fāḥishatin mubayyinatin yuḍāʿaf lahā l-ʿadhābu ḍiʿfayni wa-kāna dhālika ʿalā llāhi yasīran', 'Ey Peygamber''in hanımları! Sizden kim açık bir hayâsızlık yaparsa, ona azap iki kat verilir. Bu da Allah''a göre kolaydır.'),
(33, 31, 22, 422, 'وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا', 've men yaqnutu minkunne lillâhi ve resûlihî ve taʿmelu ṣāliḥan nuʾtihâ ʾacrahâ merreteyni ve ʾaʿtednâ lehâ rizqan kerîmâ', 'Sizlerden kim Allah''a ve Resûlü''ne itaat eder ve salih amel işlerse, onun mükâfatını iki kat veririz ve ona güzel bir rızık hazırlarız.'),
(33, 32, 22, 422, 'يَٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا', 'yā nisāʾa n-nabiyyi lastunna ka-aḥadin mina n-nisāʾi ini ttaqaytunna falā takhḍaʿna bil-qawli fa-yaṭmaʿa lladhī fī qalbihi marḍun wa-qulna qawlan maʿrūfan', 'Ey Peygamber''in hanımları! Siz (kadınlardan) hiçbiri gibi değilsiniz. Eğer (Allah''tan) korkarsanız, (erkeklere) çekici gelecek şekilde konuşmayın ki, kalbinde hastalık olan kimse tama etmesin. Ve (onlarla) güzel ve dosdoğru söz söyleyin.'),
(33, 33, 22, 422, 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَٰهِلِيَّةِ ٱلْأُولَىٰ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', 'wa-qarna fī buyūtikinna wa-lā tabarrajna tabarruja l-jāhiliyyati l-ūlā wa-aqimna ṣ-ṣalāta wa-ātīna z-zakāta wa-aṭiʿna -llāha wa-rasūlahū ʾinnamā yurīdu -llāhu li-yudhhiba ʿankumu r-rijsa ʾahla l-bayti wa-yuṭahhirakum taṭhīrā', 'Evlerinizde ikamet edin, ilk cahiliye devrindeki gibi açılıp saçılmayın. Namazı dosdoğru kılın, zekâtı verin, Allah''a ve Resûlü''ne itaat edin. Ey Ehl-i Beyt! Allah sizden kusuru gidermek ve sizi tertemiz yapmak istiyor.'),
(33, 34, 22, 422, 'وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ ٱللَّهِ وَٱلْحِكْمَةِ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', 'wa-dh-kur-na mā yutlā fī buyūtikunna min āyāti-llāhi wa-l-ḥikmah ʾinna-llāha kāna laṭīfan khabīran', 'Ve evlerinizde okunan Allah''ın ayetlerini ve hikmeti hatırlayın. Şüphesiz Allah, latif (en ince şeylerden haberdar) ve habir (her şeyden) haberdardır.'),
(33, 35, 22, 422, 'إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱلْقَٰنِتِينَ وَٱلْقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلْخَٰشِعِينَ وَٱلْخَٰشِعَٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلْحَٰفِظِينَ فُرُوجَهُمْ وَٱلْحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', 'ʾinna l-muslimīna wa-l-muslimāti wa-l-muʾminīna wa-l-muʾmināti wa-l-qānitīna wa-l-qānitāti wa-ṣ-ṣādiqīna wa-ṣ-ṣādiqāti wa-ṣ-ṣābirīna wa-ṣ-ṣābirāti wa-l-khāshiʿīna wa-l-khāshiʿāti wa-l-mutaṣaddiqīna wa-l-mutaṣaddiqāti wa-ṣ-ṣāʾimīna wa-ṣ-ṣāʾimāti wa-l-ḥāfiẓīna furūjahum wa-l-ḥāfiẓāti wa-dh-dhākirīna llāha kathīran wa-dh-dhākirāti ʾaʿadda llāhu lahum maghfiratan wa-ʾajran ʿaẓīman', 'Şüphesiz, Müslüman erkekler ve Müslüman kadınlar, mümin erkekler ve mümin kadınlar, itaat eden erkekler ve itaat eden kadınlar, doğru söyleyen erkekler ve doğru söyleyen kadınlar, sabreden erkekler ve sabreden kadınlar, Allah''a derin saygı gösteren erkekler ve Allah''a derin saygı gösteren kadınlar, sadaka veren erkekler ve sadaka veren kadınlar, oruç tutan erkekler ve oruç tutan kadınlar, namuslarını koruyan erkekler ve namuslarını koruyan kadınlar, Allah''ı çok zikreden erkekler ve Allah''ı çok zikreden kadınlar için Allah bağışlanma ve büyük bir ecir hazırlamıştır.'),
(33, 36, 22, 423, 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا', 'wa mā kāna limuʾminin wa lā muʾminatin iḏā qaḍā ʾllāhu wa rasūluhū ʾamran ʾan yakūna lahumu l-ḵiyāratu min ʾamrihim wa man yaʿṣi ʾllāha wa rasūlahū fapaqad ḍalla ḍalālan mubīnan', 'Allah ve Resûlü bir işe hükmettiği zaman, hiçbir inanmış erkek ve hiçbir inanmış kadın için o işi kendi isteklerine göre seçme hakkı yoktur. Kim Allah''a ve Resûlü''ne isyan ederse, şüphesiz ki apaçık bir sapıklığa sapmış olur.'),
(33, 37, 22, 423, 'وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', 'wa-ʾidh taqūlu lilladhī ʾanʿama ʾllāhu ʿalayhi wa-ʾanʿamta ʿalayhi ʾmsik ʿalayka zawjaka wa-ttaqi ʾllāh wa-tukhfī fī nafsika mā ʾllāhu mubdīhi wa-takhshā n-nāsa wa-ʾllāhu ʾaḥaqqu ʾan takhshāh falammā qaḍā zaydun minhā waṭaran zawwajnākahā likay lā yakūna ʿalā l-muʾminīna ḥarujun fī ʾazwāji ʾadʿiyāʾihim ʾidhā qaḍaw minhunna waṭaran wa-kāna ʾamru ʾllāhi mafʿūlan', 'Hani, Allah''ın kendisini nimetlendirdiği ve senin de kendisine iyilikte bulunduğun kimseye: "Eşini (kendinde) tut, Allah''tan kork!" diyordun. Allah''ın açığa vuracağı şeyi içinde gizliyordun. İnsanlardan çekiniyordun. Oysa Allah, kendisinden çekinmene daha layıktır. Sonunda Zeyd, eşiyle ilişkisini kesince, biz onu sana eş olarak verdik ki, evlatlıklarının eşleriyle ilişkileri kesildiğinde, iman edenler (bu konuda) bir darlık çekmesinler. Allah''ın emri (yerine getirilmiş) bir iştir.'),
(33, 38, 22, 423, 'مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًا مَّقْدُورًا', 'mā kāna ʿalā n-nabiyyi min ḥarjin fīmā faraḍa llāhu lahu sunnata llāhi fī l-ladhīna ḵalaw min qablu wa kāna amru llāhi qadaran maqdūran', 'Allah''ın, kendisi için farz kıldığı hususlarda peygamber üzerine bir darlık (veya günah) yoktur. Allah''ın geçmiştekiler hakkındaki kanunu da böyledir. Allah''ın emri ise takdir edilmiş bir kaderdir.'),
(33, 39, 22, 423, 'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', 'alladhīna yuballighūna risālāti llāhi wa yakhshawnahu wa lā yakhshawna aḥadan illā llāha wa kafā bi llāhi ḥasībā', 'Onlar, Allah''ın risaletlerini tebliğ eden, O''ndan korkan ve O''ndan başka kimseden korkmayan kimselerdir. Hesap görücü olarak Allah yeter.'),
(33, 40, 22, 423, 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّۦنَ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', 'mā kāna muḥammadun abā ʾaḥadin min rijālikum walākin rasūla ʾllāhi wa khātama n-nabiyyīna wa kāna ʾllāhu bikulli shayin ʿalīmā', 'Muhammed, sizin erkeklerinizden hiçbirinin babası değildir; ancak Allah''ın Resûlü ve peygamberlerin sonuncusudur. Allah, her şeyi hakkıyla bilendir.'),
(33, 41, 22, 423, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًا كَثِيرًا', 'yā ayyuhā alladhīna āmanū dhkurū allāha dhikran kathīran', 'Ey iman edenler! Allah''ı çokça zikredin.'),
(33, 42, 22, 423, 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', 'wa sabbuḥūhu bukrataw wa ʾaṣīlā', 'Ve O''nu sabah akşam tesbih edin.'),
(33, 43, 22, 423, 'هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا', 'huwa alladhī yuṣallī ʿalaykum wa-malāʾikatuhu li-yukhrigakum mina ẓ-ẓulumāti ilá n-nūr wa-kāna bi-l-muʾminīna raḥīmā', 'O, size hem kendi katından hem de melekleri aracılığıyla rahmet etmekte ve sizi karanlıklardan aydınlığa çıkarmaktadır. O, müminlere karşı çok merhametlidir.'),
(33, 44, 22, 424, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا', 'taḥiyyatuhum yawma yalqawnahū salām wa aʿadda lahum ajran karīman', 'Onların Allah''a kavuşacakları gün, kendilerine ''selâm''dır. Ve O, onlara çok değerli bir mükâfat hazırlamıştır.'),
(33, 45, 22, 424, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', 'yā ayyuhā n-nabiyyu innā arsalnāka shāhidan wa-mubashshiran wa-nadhīran', 'Ey Peygamber! Şüphesiz biz seni bir şahit, bir müjdeleyici ve bir uyarıcı olarak gönderdik.'),
(33, 46, 22, 424, 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا', 'wa dāʿiyan ilā llāhi bi iḏnihi wa sirājan munīran', 'Ve O''nu, izniyle Allah''a davet eden ve (hidayet nuruyla) aydınlatan bir kandil olarak (gönderdik).'),
(33, 47, 22, 424, 'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًا كَبِيرًا', 'wa bashshiri l-muʾminīna bi-ʾanna lahum mina llāhi faḍlan kabīran', 'Mü''minlere, kendileri için Allah''tan büyük bir lütuf olduğunu müjdele.'),
(33, 48, 22, 424, 'وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'wa lā tuṭiʿi l-kāfirīna wa-l-munāfiqīna wa daʿ adhāhum wa tawakkal ʿalā llāhi wa kafā bi-llāhi wakīlan', 'Onları dinleme, kâfirlerle ve münafıklarla uzlaşma, onlara eziyet etme ve Allah''a tevekkül et. Vekil olarak Allah yeter.'),
(33, 49, 22, 424, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا', 'yā ʾayyuhā llaḏīna ʾāmanū iḏā nakaḥtumul muʾmināti ṯumma ṭallaqtumūhunna min qabli ʾan tamassūhunna famā lakum ʿalayhinna min ʿiddatin taʿtadūnahā famat tiʿūhunna wasarriḥūhunna sarāḥan jamīlan', 'Ey iman edenler! Mümin kadınları nikahlayıp da onlara dokunmadan (gerdeğe girmeden) önce boşadığınız takdirde, üzerlerine sayacağınız bir iddet (bekleme süresi) yoktur. Bu durumda onlara, ya uygun bir şekilde bir miktar mal verin (mut''a) ya da onları güzel bir şekilde salıverin. Ve onlara karşı sizin üzerinizde bir hak iddia edilecek bir iddet de yoktur.'),
(33, 50, 22, 424, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'yā ayyuhā an-nabiyyu innā aḥlalnā laka azwājaka allātī ātayta ujūrahunna wa mā malakat yamīnuka mimmā afāʾa allāhu ʿalayka wa banāti ʿammika wa banāti ʿammātika wa banāti khālika wa banāti khālātika allātī hājarne maʿaka wamraʾatan muʾminatan in wahabat nafsahā lin-nabiyyi in arāda an-nabiyyu an yastankihahā khāliṣatan laka min dūni al-muʾminīna qad ʿalimnā mā faraḍnā ʿalayhim fī azwājihim wa mā malakat aymānuhum likaylā yakūna ʿalayka ḥarujun wakāna allāhu ghafūran raḥīmā', 'Ey Peygamber! Biz sana eşlerini, mehirlerini verdiğin hanımlarını, Allah''ın sana ganimet olarak ihsan ettiklerinden elinin altında bulunan cariyeleri, seninle birlikte hicret eden amcanın kızlarını, halanın kızlarını, dayının kızlarını ve teyzelerinin kızlarını (sana helal kıldık). Bir de (diğer) mümin kadınlardan, kendisini Peygamber''e hibe eden (veren) kadını da (sana helal kıldık). Peygamber''in onu nikâhlaması durumunda, (bu) müminler için değil, (sadece) senin için bir darlık olmasın (diye böyle yaptık). Biz onların eşleri ve ellerinin altında bulunanlar hakkında ne farz kıldığımızı biliyoruz. (Bütün bunlar) senin için bir darlık olmasın diyedir. Allah, çok bağışlayandır, çok merhamet edendir.'),
(33, 51, 22, 425, 'تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًا', 'turjī man tashāʾu minhunna wa tuʾwī ilayka man tashāʾu wa mani-btaghayta mimman ʿazalta falā junāḥa ʿalayka dhālika adnā an tuqarra ʾaʿyunuhunna wa lā yaḥzan na wa yarḍayna bimā ʾātaytahunna kulluhunna wallāhu yaʿlamu mā fī qulūbikum wa kāna llāhu ʿalīman ḥalīmā', 'Onlardan dilediğini geri bırakabilir, dilediğini de yanına alabilirsin. Kendilerine ayırdıklarından uzaklaştırdıklarından her kimi istersen onu kendine alabilirsin. Bu, onların üzülmemeleri, razı olmaları ve kendilerine verdiğinle herkesin hoşnut olması için en uygun olanıdır. Allah, kalplerinizdekini bilir. Allah, hakkıyla bilendir, halîmdir.'),
(33, 52, 22, 425, 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا', 'lā yaḥillu laka n-nisāʾu min baʿdu wa lā an tabaddala bihinna min azwājin wa law aʿjabaka ḥusnuhunna illā mā malakat yamīnuka wa kāna ʾllāhu ʿalā kulli shayʾin raqībā', 'Bundan sonra kadınlar sana helâl değildir; onları başka zevcelerle değiştirmek de, hoşuna gitseler bile. Ancak sahip olduğun (cariye) müstesna. Allah her şeyi gözetendir.'),
(33, 53, 22, 425, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا', 'yā ayyuhā l-ladhīna āmānū lā tadkhulū buyūta n-nabiyyi illā an yuʾdhana lakum ilā ṭaʿāmin ghayra nāẓirīna ināhu walākin idhā duʿītum fa-dkhulū fa-idhā ṭaʿimtum fa-ntashirū walā mustaʾnisīna li-ḥadīthin inna dhālikum kāna yuʾdhī n-nabiyya fa-yastaḥyī minkum wa-llāhu lā yastaḥyī mina l-ḥaqqi wa-idhā saʾaltumūhunna matāʿan fa-sʾalūhunna min warāʾi ḥijābin dhālikum aṭharu li-qulūbikum wa-qulūbihinna wa-mā kāna lakum an tuʾdhū rasūla l-lāhi walā an tankiḥū azwājahū min baʿdihi abadan inna dhālikum kāna ʿinda l-lāhi ʿaẓīman', 'Ey iman edenler! Peygamber''in evlerine, izin verilmedikçe ve yemeğin pişmesini beklemeksizin dalmayınız. Ancak çağrıldığınız zaman girin. Yemeği yediğinizde dağılıp gidin, sohbet etmek için de oyalanmayın. Şüphesiz bunlar Peygamber''i incitiyor da O sizden utanıyor. Allah ise hakkı söylemekten utanmaz. Peygamber''in hanımlarından bir şey istediğinizde, onu (perde arkasından) hicabın ardından isteyin. Bu, sizin kalpleriniz için de, onların kalpleri için de daha temizdir. Allah''ın Resûlü''nü incitmeniz ve ondan sonra hanımlarını nikâhlamanız asla size helâl olmaz. Şüphesiz bunlar Allah katında çok büyüktür.'),
(33, 54, 22, 425, 'إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', 'in tubdū shayʾan aw tukhfūhu faʾinna ʾallāha kāna bikulli shayʾin ʿalīman', 'Eğer siz bir şeyi açığa vursanız da gizleseniz de, şüphesiz Allah her şeyi bilmektedir.'),
(33, 55, 22, 426, 'لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ وَٱتَّقِينَ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', 'lā junāḥa ʿalayhinna fī ʾābāʾihinna wa lā ʾabnāʾihinna wa lā ʾikhwānihinna wa lā ʾabnāʾi ʾikhwānihinna wa lā ʾabnāʾi ʾakhawātihinna wa lā nisāʾihinna wa lā mā malakat ʾaymānuhunna wāttaqīna ʾllāha ʾinna ʾllāha kāna ʿalā kulli šayʾin šahīdan', 'Onların babaları, oğulları, kardeşleri, erkek kardeşlerinin oğulları, kız kardeşlerinin oğulları, kendi kadınları (diğer kadınları) ve sahip oldukları cariyeler konusunda bir günahı yoktur. (Ey kadınlar!) Allah''tan korkun. Şüphesiz Allah her şeye şahittir.'),
(33, 56, 22, 426, 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', 'ʾinna ʾallāha wa-malāʾikatahu yuṣallūna ʿalā n-nabiyyi yā ʾayyuhā lladhīna ʾāmanū ṣallū ʿalayhi wa-sallimū taslīman', 'Şüphesiz Allah ve melekleri Peygamber''e salât ederler. Ey iman edenler! Siz de ona salât edin ve (ona) tam bir teslimiyetle selâm verin.'),
(33, 57, 22, 426, 'إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا', 'ʾinna lladhīna yuʾdhūna llāha wa rasūlahū laʿanahumu llāhu fī d-dunyā wa l-ʾākhirati wa ʾaʿadda lahum ʿadhāban muhīnan', 'Şüphesiz Allah''a ve Resûlü''ne eziyet edenlere Allah, dünyada ve ahirette lanet etmiştir. Ve onlara alçaltıcı bir azap hazırlamıştır.'),
(33, 58, 22, 426, 'وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'wa-lladhīna yuʾdhūna l-muʾminīna wa-l-muʾmināti bighayri mā iktasabū faqadi ḥtamalū buhtānan wa-ithman mubīnan', 'Mü''min erkeklere ve mü''min kadınlara, yapmadıkları bir şeyden dolayı eziyet edenler, şüphesiz ki büyük bir bühtan ve apaçık bir günah yüklenmişlerdir.'),
(33, 59, 22, 426, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'yā ayyuhā n-nabiyyu qul li-ʾazwājika wa-banātika wa-nisāʾi l-muʾminīna yudnīna ʿalayhina min jālābībihinna ḏālika ʾadnā ʾan yuʿrafna falā yuʾḏayna wa-kāna ʾllāhu ġafūran raḥīmā', 'Ey Peygamber! Hanımlarına, kızlarına ve müminlerin kadınlarına, dış giysilerinden bir kısmını örterek üzerine almalarını söyle. Bu, onların tanınıp (eğlenilip) incitilmemeleri için daha uygundur. Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(33, 60, 22, 426, 'لَّئِن لَّمْ يَنتَهِ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا', 'leʾin lem yentehi el-munāfiqūne ve elleẕīne fī qulūbihim maraḍun ve el-murcifūne fī el-medīneti lenuğriyenneke bihim śümme lā yucāvirūneke fīhā illā qalīlen', 'Andolsun ki eğer münafıklar, kalplerinde hastalık bulunanlar ve şehirde asılsız haber yayanlar (bu tutumlarından) vazgeçmezlerse, seni onlara karşı kesinlikle kışkırtırız; sonra orada seninle birlikte pek az kalabilirler.'),
(33, 61, 22, 426, 'مَّلْعُونِينَ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًا', 'malʿūnīna ʾaẏnammā ṯuqifū ʾuḫiḏū waqututilū taqtīlan', 'Lanetlenmişler olarak nerede rastlanırlarsa yakalanırlar ve şiddetli bir şekilde öldürülürler.'),
(33, 62, 22, 426, 'سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', 'sunnata llāhi fī lladhīna khalaw min qablu walana tajida li sunnati llāhi tabdīlā', 'Allah''ın, geçmiştekiler hakkında (uyguladığı) kanunudur. Allah''ın kanununda asla bir değişiklik bulamazsın.'),
(33, 63, 22, 427, 'يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', 'yas''aluka n-nāsu ʿani s-sāʿati qul innamā ʿilmuhā ʿinda llāhi wa mā yudrīka laʿalla s-sāʿata takūnu qarīban', 'İnsanlar sana o saati soruyorlar. De ki: "Onun ilmi ancak Allah''ın yanındadır." Sen nereden bileceksin? Umulur ki o saat pek yakın.'),
(33, 64, 22, 427, 'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', 'inna llāhə laʿana l-kāfirīn waʾaʿadda lahum saʿīrā', 'Şüphesiz Allah kâfirleri lanetlemiş ve onlara çılgın alevli bir ateş hazırlamıştır.'),
(33, 65, 22, 427, 'خَٰلِدِينَ فِيهَآ أَبَدًا لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', 'khālidīna fīhā ʾabadan lā yajidūna waliyyan wa lā naṣīran', 'Onlar orada ebedî olarak kalırlar; bir dost ve bir yardımcı bulamazlar.'),
(33, 66, 22, 427, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠', 'yawma tuqallabu wujūhuhum fī n-nār yaqūlūna yālaytanā aṭaʿnā llāha wa aṭaʿnā r-rasūlā', 'O gün yüzleri ateşte çevrilirken, "Keşke Allah''a itaat etseydik, keşke Peygamber''e de itaat etseydik!" derler.'),
(33, 67, 22, 427, 'وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', 'wa qālū rabbanā ʾinnā ʾaṭaʿnā sādatanā wa kubarāʾanā fa ʾaḍallūnā s-sabīlā', 'Ve dediler ki: "Rabbimiz! Şüphesiz biz efendilerimize ve büyüklerimize itaat ettik de bizi yoldan saptırdılar.'),
(33, 68, 22, 427, 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًا كَبِيرًا', 'Rabbena āti-him dhiʿfayni mine l-ʿadhābi Wa-lʿan-hum laʿnan kabīran', 'Rabbimiz! Onlara azaptan iki kat ver ve onları büyük bir lanetle lanetle!'),
(33, 69, 22, 427, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ وَكَانَ عِندَ ٱللَّهِ وَجِيهًا', 'yā ayyuhā alladhīna āmānū lā takūnū ka-alladhīna ādhaw mūsā fa-barraʾahu allāhu mimmā qālū wa-kāna ʿinda allāhi wajīhan', 'Ey iman edenler! Mûsâ''ya eziyet edenler gibi olmayın. Allah onu, onların söylediklerinden temize çıkardı. O, Allah katında itibarlı idi.'),
(33, 70, 22, 427, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًا سَدِيدًا', 'yā ayyuhā alladhīna āmanū ittqū allāh wa qūlū qawlan sadīdā', 'Ey iman edenler! Allah''a karşı gelmekten sakının ve doğru söz söyleyin.'),
(33, 71, 22, 427, 'يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا', 'yuṣliḥ lakum aʿmālakum wa yaghfir lakum dhunūbakum wa man yuṭiʿi l-lāha wa rasūlahu faqad fāza fawzan ʿaẓīman', 'A''mâlinizi sizin için ıslah eder ve günahlarınızı mağfiret eder. Kim Allah''a ve Resûlü''ne itaat ederse, o takdirde büyük bir kurtuluşa ermiş olur.'),
(33, 72, 22, 427, 'إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَٰنُ إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا', 'ʾinnā ʿaraḍnā l-ʾamānata ʿalā s-samāwāti wa-l-ʾarḍi wa-l-jibāli fa-ʾabayna ʾan yaḥmilnahā wa-ʾashfaqna minhā wa-ḥamalahā l-ʾinsānu ʾinnahu kāna ẓalūman jahūlā', 'Şüphesiz biz emaneti göklere, yeryüzüne ve dağlara arz ettik de onlar onu yüklenmekten çekindiler, ondan ürktüler. Onu insan yüklendi. Şüphesiz o çok zalim, çok cahildir.'),
(33, 73, 22, 427, 'لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًۢا', 'liyuʿaḏḏiba ʾllāhu lmunāfiqīna walmunāfiqāti walmušrikīna walmušrikāti wayatūba ʾllāhu ʿalā lmuʾminīna walmuʾmināti wakāna ʾllāhu ġafūran raḥīmā', 'Allah''ın, münafık erkekleri ve münafık kadınları, müşrik erkekleri ve müşrik kadınları azaplandırması için; hem de Allah''ın mü''min erkeklere ve mü''min kadınlara tevbelerini kabul etmesi için. Allah Gafûr''dur, Rahîm''dir.'),
(34, 1, 22, 428, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْءَاخِرَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'alḥamdu lillāhi alladhī lahū mā fī s-samāwāti wa mā fī l-arḍi wa lahū l-ḥamdu fī l-ʾākhirati wa huwa l-ḥakīmu l-khabīru', 'Hamd, göklerde ve yerde ne varsa O''na ait olan Allah''a mahsustur. Ahirette de hamd O''na mahsustur. O, hüküm ve hikmet sahibi, her şeyden haberdar olandır.'),
(34, 2, 22, 428, 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ', 'yaʿlamu mā yaliju fī l-arḍi wa-mā yakhruju minhā wa-mā yanzilu mina s-samāʾi wa-mā yaʿruju fīhā wa-huwa r-raḥīmu l-ġafūr', 'Yere gireni, ondan çıkanı, gökten ineni ve ona yükseleni bilir. O, çok bağışlayandır, çok merhametlidir.'),
(34, 3, 22, 428, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَٰلِمِ ٱلْغَيْبِ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'waqāla alladhīna kafarū lā taʾtīnā s-sāʿah qul balā wa rabbī lataʾtiyannakum ʿālimi l-ghayb lā yaʿzubu ʿanhu mithqālu dharratin fī s-samāwāti walā fī l-arḍ walā ʾaṣgharu min dhālika walā ʾakbar ʾillā fī kitābin mubīn', 'İnkâr edenler şöyle dediler: "Ne o, kıyamet bize gelmez!" De ki: "Hayır, gaybı bilen Rabbim hakkı için, o size mutlaka gelecektir. Göklerde ve yerde zerre kadar bir şey O''ndan gizli kalmaz. Bundan daha küçüğü de daha büyüğü de müstesna olmamak üzere, hepsi apaçık bir kitaptadır."'),
(34, 4, 22, 428, 'لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'li-yecziye ellezîne âmenû ve ''amilû es-sâlihâti ülâike lehum mağfiretun ve rızkun kerîmun', 'Bu, iman edip salih ameller işleyenleri mükâfatlandırması içindir. İşte onlara bağışlanma ve cömert bir rızık vardır.'),
(34, 5, 22, 428, 'وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', 'wa-lladhīna saʿaw fī ʾāyātinā muʿājizīna ʾulāʾika lahum ʿadhābun min rijzin ʾalīmun', 'Ayetlerimiz hususunda acze düşürmeye çalışarak koşanlara gelince, işte onlar için elem dolu azap vardır.'),
(34, 6, 22, 428, 'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'wa yarā alladhīna ūtū al-ʿilma alladhī unzila ilayka min rabbika huwa al-ḥaqqa wa yahdī ilā ṣirāṭi al-ʿazīzi al-ḥamīd', 'Kendilerine ilim verilenler, sana Rabbinden indirilenin hak olduğunu ve O''nun mutlak güç sahibi, her türlü övgüye layık olanın yoluna ilettiğini görürler.'),
(34, 7, 22, 428, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ', 'waqāla alladhīna kafarū hal nadullukum ʿalā rajulin yunabbiʾukum idhā muzziqtum kulla mumazzaqin ʾinnakum la fī khalqin jadīdin', 'İnkâr edenler şöyle dedi: "Çürüyüp paramparça olduğunuz zaman, sizi yeniden bir yaratılış içinde mi bulacağız?" dedi.'),
(34, 8, 22, 429, 'أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَٰلِ ٱلْبَعِيدِ', 'Aftarā ʿalā Llāhi kaḏiban am bihi ǧinnah Bal allaḏīna lā yuʾminūna bil-ʾāḫirah fīl-ʿaḏābi waḍ-ḍalāli l-baʿīd', 'Yoksa Allah''a karşı yalan mı uydurmuştur, yoksa kendisinde bir delilik mi var? Hayır, ahirete inanmayanlar azapta ve derin bir sapıklık içindedirler.'),
(34, 9, 22, 429, 'أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ ٱلسَّمَآءِ إِنَّ فِى ذَٰلِكَ لَءَايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ', 'Efelem yerav ilā mā beyne eydīhim ve mā ḫalfehum mine''s-semāʾi ve''l-ʾarḍi İn neşeʾ naḫsif bihimu''l-ʾarḍa Ev nusqiṭ ʿaleyhim kissefen mine''s-semāʾi İnne fī ḏālika laʾāyaten li-kulli ʿabdim munībi', 'Onlar, önlerinde ve arkalarında bulunan gökten ve yerden (olanlara) bakmadılar mı? Eğer dileyecek olursak, onları yere batırırız veya üzerlerine gökten parçalar düşürürüz. Şüphesiz ki bunda, (her) Allah''a yönelen kul için bir ayet vardır.'),
(34, 10, 22, 429, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ وَأَلَنَّا لَهُ ٱلْحَدِيدَ', 'Ve lekad āteynā Dāvūde minnā faḍlā Yā cibālu evvibī meʿahū veṭ-ṭayr Ve elennā lehul-ḥadīd', 'Andolsun ki Davud''a tarafımızdan bir lütuf verdik. “Ey dağlar, onunla birlikte tesbih edin! Ey kuşlar!” dedik. Ve demiri ona yumuşattık.'),
(34, 11, 22, 429, 'أَنِ ٱعْمَلْ سَٰبِغَٰتٍ وَقَدِّرْ فِى ٱلسَّرْدِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ', 'ani-ʿmal sābigāti wa-qaddir fī-s-sardi wa-ʿmalū ṣāliḥan ʾinnī bimā taʿmalūna baṣīrun', 'Zırhlar yap ve dokuma işinde ölçüyü ayarla. Ve salih amel işleyin. Şüphesiz ben, yaptıklarınızı görüyorum.'),
(34, 12, 22, 429, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ', 'Wa li-Sulaymāna r-rīḥa ġudūwuhā šahrun wa rawāḥuhā šahrun Wa ''asálnā lahu ʿayna l-qiṭri Wa mina l-jinni man yaʿmalu bayna yadayhi bi-''iḏni Rabbihi Wa man yazig minhum ʿan ''amrinā nuḏiqhu min ʿaḏābi s-saʿīri', 'Ve Süleyman için de rüzgârı (onun buyruğuna verdik): onun sabah gidişi bir ay, akşam dönüşü de bir aydır. Ve ona erimiş madeni (veya kaynağını) akıttık. Ve cinlerden de Rabbinin izniyle onun önünde çalışanlar vardı. Onlardan kim emrimizden saparsa, onu çılgın ateşin azabından tattırırız.'),
(34, 13, 22, 429, 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٍ كَٱلْجَوَابِ وَقُدُورٍ رَّاسِيَٰتٍ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا وَقَلِيلٌ مِّنْ عِبَادِىَ ٱلشَّكُورُ', 'yaʿmalūna lahū mā yashāʾu min maḥārība wa tamāthīla wa jifānin kaljawābi wa qudūrin rāsiyātin iʿmalū ʾāla Dāwūda shukran wa qalīlun min ʿibādīya al-shakkūru', 'Onun için dilediği şeylerden (istediklerini) yaparlardı: saraylar, heykeller, havuzlar gibi büyük çanaklar ve sabit (yerinden oynatılamayan) kazanlar. Ey Davud ailesi! Şükretmek için çalışın. Kullarım arasında şükredenler azdır.'),
(34, 14, 22, 429, 'فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ', 'felemmâ kadaynâ ''aleyhi-lmevte mâ dellehum ''alâ mevtihî illâ dâbbetu-l''ardi te''kulu minse''etehû felemmâ harra tebeyyene-ti-lcinni en lev kânû ya''lemûne-lğaybe mâ lebişû fî-l''azâbi-lmuhîni', 'Nihayet onun (Süleyman''ın) ölümüne hükmettiğimizde, onun öldüğünü onlara ancak yerde yürüyen bir mahluk (ağaç kurdu) haber verdi. O, değneğini yiyordu. Böy lece yıkılıp yere düşünce, cinler anladılar ki, eğer gaybı biliyor olsalardı, o aşağılayıcı azap içinde kalmazlardı.'),
(34, 15, 22, 430, 'لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ', 'leḳad kâne lisebeʾin fî meskenihim âyetün cennetâni ʿan yemînin veşimâlin külû min rizḳi rabbiküm veşkurû lehû beldetün ṭayyibetün verabbün gafûr', 'Andolsun, Sebe'' kavmi için oturdukları yerde bir ibret vardı: Sağdan ve soldan iki bahçe. (Onlara şöyle denilmişti:) "Rabbinizin rızkından yiyin ve O''na şükredin. Güzel bir belde ve çok bağışlayıcı bir Rab!"'),
(34, 16, 22, 430, 'فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ', 'fa-aʿraḍū fa-arsalnā ʿalayhim sayla l-ʿarimi wa-baddalnāhum bi-jannatayhim jannatayni dhawātay ukulin khamṭin wa-aṯlin wa-shayʾin min sidrin qalīlin', 'Onlar yüz çevirdiler, biz de üzerlerine Arim seli gönderdik ve onların o iki cennetini, buruk yemişli, acı otlu ve az miktarda sidr ağacı olan iki cennete çevirdik.'),
(34, 17, 22, 430, 'ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُوا۟ وَهَلْ نُجَٰزِىٓ إِلَّا ٱلْكَفُورَ', 'dhālika jazaynāhum bimā kafarū wa hal nujāzī illā l-kafūr', 'İşte bu, inkâr ettikleri yüzünden onlara verdiğimiz cezadır. Biz, inkâr edenden başkasını cezalandırır mıyız?'),
(34, 18, 22, 430, 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَٰرَكْنَا فِيهَا قُرًى ظَٰهِرَةً وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ', 'wa-jaʿalnā baynahum wa-bayna l-qurā llatī bāraknā fīhā quran ẓāhiratan wa-qaddarnā fīhā s-sayra sīrū fīhā layāliya wa-ayyāman ʾāminīn', 'Onlarla, feyz verdiğimiz memleketler arasına, görünür şehirler koyduk ve aralarında (seyahat) mesafesini tâyin ettik. "Onlarda geceli gündüzzlü, hem de emin olarak geziniz!"'),
(34, 19, 22, 430, 'فَقَالُوا۟ رَبَّنَا بَٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَٰهُمْ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'faqālū rabbanā bāʿid bayna asfārinā waẓalamū anfusahum fajaʿalnāhum ʾaḥādīth wamazzaqnāhum kulla mumazzaqin ʾinna fī dhālika laʾāyātin likulli ṣabbārin shakkūrin', 'Bunun üzerine şöyle dediler: "Rabbimiz! Bizim şehirlerimiz arasındaki mesafeyi uzaklaştır!" Böylece kendilerine zulmettiler. Biz de onları ibret alınacak bir duruma getirdik ve onları paramparça ettik. Şüphesiz bunda, sabreden ve şükreden herkes için nice ibretler vardır.'),
(34, 20, 22, 430, 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ', 'Ve lekad saddaka ''aleyhim İblîsu zannehu fettebe''ûhu illâ ferîkan mine-lmu''minîn', 'Şüphesiz İblis, onlar hakkındaki zannını doğru çıkardı da müminlerden bir grup hariç, ona uydular.'),
(34, 21, 22, 430, 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْءَاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', 'wa mā kāna lahu ʿalayhim min sulṭānin illā linaʿlama man yuʾminu bil-ʾākhirati mimman huwa minhā fī shakin wa rabbuka ʿalā kulli shayʾin ḥafīẓun', 'Onun onlar üzerinde hiçbir zorlayıcı gücü yoktu; ancak ahirete iman edenle ondan şüphe içinde olanı bilmemiz için (böyle yaptık). Rabbin her şeyi gözetendir.'),
(34, 22, 22, 430, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ', 'Qul idʿūllaḏīna zaʿamtum min dūni llāh Lā yamlikūna miṯqāla ḏarratin fī s-samāwāti walā fī l-ʾarḍ Wa mā lahum fīhimā min širkin Wa mā lahu minhum min ẓahīrin', 'De ki: Allah''tan başka ilah olarak nitelediklerinizi çağırın. Onlar, ne göklerde ne de yerde zerre kadar bir şeye sahip değillerdir. Onların bu ikisinde de bir ortaklıkları yoktur ve O''nun onlardan bir yardımcısı da yoktur.'),
(34, 23, 22, 431, 'وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ قَالُوا۟ ٱلْحَقَّ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'wa-lā tanfaʿu sh-shafāʿatu ʿindahu ʾillā liman ʾadhina lahu ḥattā ʾidhā fuzziʿa ʿan qulūbihim qālū mādhā qāla rabbukum qālū l-ḥaqqa wa-huwa l-ʿaliyyu l-kabīr', 'Allah katında, O''nun izin verdiği kimseler dışında hiç kimsenin şefaat etme faydası olmaz. Nihayet kalplerinden korku giderilince, ''Rabbiniz ne buyurdu?'' derler. (Diğer melekler) ''Gerçeği!'' derler. O, yücedir, büyüktür.'),
(34, 24, 22, 431, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍ مُّبِينٍ', 'qul man yarzuqukum min as-samāwāti wal-arḍi quli -llāhu wa inna-ā aw iyyā-kum laʿalā hudan aw fī ḍalālin mubīnin', 'De ki: "Göklerden ve yerden size kim rızık veriyor?" De ki: "Allah. Şüphesiz biz veya siz, ya doğru bir yol üzerindeyiz ya da apaçık bir sapıklık içindeyiz."'),
(34, 25, 22, 431, 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', 'Qul Lā tus''alūna ʿammā ajramnā Wa lā nus''alu ʿammā taʿmalūn', 'De ki: ''Siz, bizim ne günah işlediğimizden sorulmazsınız, biz de sizin yapmakta olduklarınızdan sorulmayız.'''),
(34, 26, 22, 431, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ', 'Qul Yajmaʿu baynanā rabbunā Thumma yaftaḥu baynanā bil-ḥaqqi Wa huwa l-fattaḥu l-ʿalīmu', 'De ki: "Rabbimiz hepimizi bir araya toplayacak, sonra aramızda hak ile hüküm verecektir. O, (hükmüyle) açan, (her şeyi) bilendir."'),
(34, 27, 22, 431, 'قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ كَلَّا بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'qul arūnīya alladhīna alḥaqtum bihi shurakāʾ kallā bal huwa allāhu l-ʿazīzu l-ḥakīmu', 'De ki: ''Ona (Allah''a) kattığınız ortakları bana gösterin.'' Hayır! O, mutlak güç sahibi, hüküm ve hikmet sahibi olan Allah''tır.'),
(34, 28, 22, 431, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'Ve mā arsalnāke illā kāffatan lin-nāsi bashīran wa nadhīran Wa lākinna akthara n-nāsi lā yaʿlamūn', 'Biz seni, insanlara müjdeleyici ve uyarıcı olarak, hepsine (tüm insanlığa) gönderdik. Fakat insanların çoğu bilmezler.'),
(34, 29, 22, 431, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hādhā al-waʿdu in kuntum ṣādiqīn', 'Ve derler ki: Eğer doğru sözlüler iseniz, bu vaad ne zaman gerçekleşecek?'),
(34, 30, 22, 431, 'قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ', 'qul lakum mīʿādu yawmin lā tastʾakhirūna ʿanhu sāʿatan walā tastaqdimūna', 'De ki: "Sizin için belirlenmiş bir gün vardır; ne bir an geri kalabilirsiniz ne de bir an öne geçebilirsiniz."'),
(34, 31, 22, 431, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ', 'waqāla alladhīna kafarū lan nuʾmina bihādhā al-qurʾāni walā bi-lladhī bayna yadayhi walaw tarā ʾidhi aẓ-ẓālimūna mawqūfūna ʿinda rabbihim yarjiʿu baʿḍuhum ʾilā baʿḍin al-qawla yaqūlu alladhīna istuḍʿifū li-lladhīna istakbarū lawlā ʾantum lakunnā muʾminīna', 'İnkâr edenler şöyle dediler: "Bu Kur''an''a da, ondan öncekilere de inanmayacağız." Zalimlerin Rablerinin katında durdurulup birbirlerine söz atarken bir görsen! Zayıf bırakılanlar, büyüklük taslayanlara derler ki: "Siz olmasaydınız, biz mutlaka iman ederdik."'),
(34, 32, 22, 432, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم بَلْ كُنتُم مُّجْرِمِينَ', 'qāla alladhīna istakbarū lilladhīna istuḍʿifū anaḥnu ṣadadnākum ʿani l-hudā baʿda iḏ ǧāʾakum bal kuntum mujrimīn', 'Büyüklük taslayanlar, zayıf düşürülenlere şöyle derler: "Size hidayet geldikten sonra biz mi sizi ondan alıkoyduk? Hayır, siz mücrimdiniz."'),
(34, 33, 22, 432, 'وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'waqāla alladhīna sustuḍʿifū lil-ladhīna istakbarū bal makru l-layli wa-n-nahāri idh taʾmurūnanā an nakfura bi-llāhi wa-najʿala lahuū andādā wa-asarrū n-nadāmata lammā raʾawu l-ʿadhāba wa-jaʿalnā l-ʾaghlāla fī ʾaʿnāqi lladhīna kafarū hal yujzawna ʾillā mā kānū yaʿmalūna', 'Aşağılananlar, büyüklük taslayanlara şöyle derler: "Hayır! Gece ve gündüz kurduğunuz hileler (bizi Allah''a karşıydı). Bize Allah''ı inkâr etmemizi ve O''na eşler koşmamızı emrediyordunuz." Azabı gördüklerinde pişmanlıklarını gizlerler. O kâfirlerin boyunlarına demir halkalar geçiririz. Onlar, yapmakta olduklarından başkasının cezasına mı çarptırılırlar?'),
(34, 34, 22, 432, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'wa mā arsalnā fī qaryatin min nadhīrin illā qāla mutrafūhā ʾinnā bimā ʾursiltum bihi kāfirūn', 'Biz hangi memlekete bir uyarıcı göndermişsek, oranın refaha alışmış ileri gelenleri: "Biz sizin gönderildiğiniz şeyleri inkâr ediyoruz" demişlerdir.'),
(34, 35, 22, 432, 'وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ', 'wa qālū naḥnu aktharu amwālan wa awlādan wa mā naḥnu bimuʿadhdhabīna', 'Dediler ki: "Mallarımız ve evlatlarımız daha çoktur. Biz azaba uğratılacak değiliz."'),
(34, 36, 22, 432, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'qul ʾinna rabbī yabsṭu r-rizqa liman yašāʾu wa-yaqdiru wa-lākinna ʾakṯara n-nāsi lā yaʿlamūn', 'De ki: Şüphesiz Rabbim rızkı dilediği kimse için genişletir ve daraltır. Fakat insanların çoğu bilmezler.'),
(34, 37, 22, 432, 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَٰتِ ءَامِنُونَ', 've mā amwālukum ve lā awlādukum bi-llatī tuqarrubukum ʿindanā zulfa illā men āmena ve amile ṣāliḥan fa-ʾulāʾike lehum cezāʾu ḍ-ḍiʿfi bimā ʿamilū ve hum fī l-ġurufāti ʾāminūn', 'Mallarınız ve evlatlarınız sizi Allah''a yaklaştıracak varlıklar değildir. Ancak iman edip salih amel işleyenler müstesna. İşte onlar için yaptıklarına karşılık kat kat mükâfat vardır. Onlar cennet odalarında güven içindedirler.'),
(34, 38, 22, 432, 'وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', 'wa-lladhīna yasʿawna fī ʾāyātinā muʿājizīna ʾulāʾika fī l-ʿadhābi muḥḍarūna', 'Ayetlerimizi aciz bırakmak (boşa çıkarmak) için çabalayanlar ise azap içinde hazır bulundurulacaklardır.'),
(34, 39, 22, 432, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'qul inne rabbī yabsṭu r-rizqa liman yashāʾu min ʿibādihī wa yaqdiru lahū wa mā anfaqtum min shayin fa-huwa yukhliufuhū wa huwa khayru r-rāziqīn', 'De ki: "Şüphesiz Rabbim kullarından dilediğine rızkı bollaştırır ve (dilediğine) kısar. Her neyi hayır olarak verirseniz, O onun yerine yenisini verir. O, rızık verenlerin en hayırlısıdır."'),
(34, 40, 22, 433, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ', 'wa-yawma yaḥshuruhum jamīʿan thumma yaqūlu lil-malāʾikati ʾahāʾulāʾi ʾiyyākum kānū yaʿbudūn', 'Ve o gün (Allah) onları hep birlikte mahşerde toplayacak, sonra meleklere şöyle diyecektir: ''Bunlar sizi mi tapıyorlardı?'''),
(34, 41, 22, 433, 'قَالُوا۟ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', 'qālū subḥānaka anta waliyyunā min dūnihim bal kānū yaʿbudūna l-jinna aktharuhum bihim muʾminūna', 'Dediler ki: "Seni tenzih ederiz! Onlar değil, Sensin bizim velimiz. Hayır, onlar Cinlere tapıyorlardı; çoğu onlara inanmışlardı."'),
(34, 42, 22, 433, 'فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'fa-l-yawma lā yamliku baʿḍukum libaʿḍin nafʿan wa-lā ḍarṛan wa-naqūlu li-lladhīna ẓalamū dhūqū ʿadhāba n-nāri llatī kuntum bihā tukadhdhibūna', 'Bugün birbirunuza fayda veya zarar verecek bir şeye mâlik olamazsınız. Ve zulmedenlere deriz ki: "Yalanlamakta olduğunuz ateş azabını tadın!"'),
(34, 43, 22, 433, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'wa-idhā tutlā ʿalayhim ʾāyātunā bayyinātin qālū mā hādhā ʾillā rajulun yurīdu ʾan yaṣuddakum ʿammā kāna yaʿbudu ʾābāʾukum wa-qālū mā hādhā ʾillā ʾifkun muftarán wa-qāla lladhīna kafarū lil-ḥaqqi lammā jāʾahum ʾin hādhā ʾillā siḥrun mubīnun', 'Onlara apaçık âyetlerimiz okunduğu zaman, dediler ki: "Bu, sizin atalarınızın taptığı şeylerden sizi çevirmek isteyen bir adamdan başkası değildir." Ve dediler ki: "Bu, uydurulmuş bir yalandan başka bir şey değildir." İnkâr edenler, kendilerine geldiği zaman hak için dediler ki: "Bu, apaçık bir sihirden başka bir şey değildir."'),
(34, 44, 22, 433, 'وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ', 've mā ʾātaynāhum min kutubin yadrusūnahā ve mā ʾarsalnā ʾilayhim qablaka min naḏīrin', 'Onlara okudukları kitaplar indirmedik ve senden önce onlara bir uyarıcı da göndermedik.'),
(34, 45, 22, 433, 'وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى فَكَيْفَ كَانَ نَكِيرِ', 'wa kadhdhaba alladhīna min qablihim wa mā balaghū miʿshāra mā ātaynāhum fakadhdhabū rusulī fakayfa kāna nakīrī', 'Onlardan öncekiler de yalanlamışlardı. Bunlar, kendilerine verdiğimizin (onların) onda birine bile ulaşamamışlardı. (Yine de) peygamberlerimi yalanladılar. Beni tanıma ve inkâr etmem nasıl oldu!'),
(34, 46, 22, 433, 'قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ مَا بِصَاحِبِكُم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ', 'qul innamā ʾaʿiẓukum biwāḥidatin ʾan taqūmū lillāhi maṯnā wafurādā ṯumma tatafakkarū mā biṣāḥibikum min jinnahtin ʾin huwa ʾillā naḏīrun lakum bayna yaday ʿaḏābin šadīdin', 'De ki: "Size bir tek öğüt veriyorum: Allah için ikili veya tek başınıza kalkıp sonra da arkadaşınızda (Peygamber''de) bir delilik olmadığını düşünmenizdir. O, ancak şiddetli bir azabın öncesinde sizi uyaran bir peygamberdir."'),
(34, 47, 22, 433, 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'Qul Mā saʾaltukum min ʾajrin fahuwa lakum ʾIn ʾajriya ʾillā ʿalā Allāhi Wahuwa ʿalā kulli shayʾin shahīd', 'De ki: Size her ne kadar bir ücret istemişsem, o sizin olsun. Benim ücretim ancak Allah’a aittir. O, her şeye hakkıyla şahittir.'),
(34, 48, 22, 433, 'قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّٰمُ ٱلْغُيُوبِ', 'qul ʾinna rabbī yaqẓifu bil-ḥaqqi ʿallāmu l-ġuyūbi', 'De ki: "Rabbim, hakkı (gerçeği) ortaya atar; O, bütün gaybları (gizli olanları) hakkıyla bilendir."'),
(34, 49, 22, 434, 'قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَٰطِلُ وَمَا يُعِيدُ', 'Qul Jāʾa l-ḥaqqu Wa mā yubdiʾu l-bāṭilu Wa mā yuʿīdu', 'De ki: Hak geldi, batıl ise ne başlayabilir ne de geri dönebilir.'),
(34, 50, 22, 434, 'قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ إِنَّهُۥ سَمِيعٌ قَرِيبٌ', 'qul in ḍalaltu fa-ʾinnamā ʾaḍillu ʿalā nafsi wa-ʾini ʾihtadaytu fa-bimā yūḥī ʾilayya rabbī ʾinnahu samīʿun qarīb', 'De ki: Eğer ben saparsam, sapıklığım kendi aleyhimedir. Eğer doğru yolu bulursam, bu da Rabbimin bana vahyettiği iledir. Şüphesiz O, her şeyi işitendir, yakın olandır.'),
(34, 51, 22, 434, 'وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍ قَرِيبٍ', 'wa law tarā idh faziʿū falā fawta wa ukhidhū min makānin qarīb', 'Onları dehşete kapıldıkları zaman bir görsen! Artık kurtuluş yoktur. Ve yakın bir yerden yakalanmışlardır.'),
(34, 52, 22, 434, 'وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍ', 'wa qālū ʾāmannā bihi wa ʾannā lahumu t-tanāwushu min makānin baʿīd', 'Ve dediler ki: "Ona inandık." Halbuki ondan uzak bir yerde iken ona nasıl yetişebilirler?'),
(34, 53, 22, 434, 'وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍ', 'waqad kafarū bihī min qablu wayaqdhifūna bil-ghaybi mim makānin baʿīd', 'Halbuki daha önce onu inkâr etmişlerdi. Hem de uzaktan gayba taş atıyorlardı.'),
(34, 54, 22, 434, 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ فِى شَكٍّ مُّرِيبٍۭ', 'wa ḥīla baynahum wa bayna mā yashtahūna kamā fuʿila bi-ashyāʿihim min qablu innahum kānū fī shakkim murībin', 'Onlarla arzu ettikleri şeyler arasına bir engel konulmuştur. Nitekim onlardan önce kendilerine benzeyenlere de böyle yapılmıştı. Çünkü onlar, (hakikati) şüpheye düşüren bir tereddüt içinde idiler.'),
(35, 1, 22, 434, 'ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'alḥamdu li-llāhi fāṭiri s-samāwāti wa-l-arḍi jāʿili l-malāʾikati rusulan ʾūlī ʾajniḥatin maṯnā wa-ṯulāṯa wa-rubāʿa yazīdu fī l-khalqi mā yašāʾu ʾinna llāha ʿalā kulli šayʾin qadīrun', 'Gökleri ve yeri yoktan var eden, melekleri ikişer, üçer ve dörder kanatlı elçiler kılan Allah’a hamdolsun. O, yaratmada dilediğini artırır. Şüphesiz Allah her şeye hakkıyla gücü yetendir.'),
(35, 2, 22, 434, 'مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'mā yaftaḥi l-lāhu lil-nāsi min raḥmatin falā mumsika lahā wa mā yumsik falā mursila lahu min baʿdihi wa huwa l-ʿazīzu l-ḥakīmu', 'Allah''ın insanlara açtığı rahmet mi, artık onu tutacak yoktur. O''nun tuttuğunu da O''ndan sonra salıverecek yoktur. O, Azîz''dir, Hakîm''dir.'),
(35, 3, 22, 434, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ هَلْ مِنْ خَٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', 'yā ayyuhā n-nāsu dhkurū niʿmata llāhi ʿalaykum hal min xāliqin ġayru llāhi yerzukukum mina s-samāʾi wa l-ʾarḍi lā ʾilāha ʾillā huw fa ʾannā tuʾfakūn', 'Ey insanlar! Allah''ın size olan nimetini hatırlayın. Gökten ve yerden sizi rızıklandıran Allah''tan başka bir yaratıcı mı var? O''ndan başka ilah yoktur. Nasıl oluyor da (haktan) çevriliyorsunuz?'),
(35, 4, 22, 435, 'وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'wa-in yukadhdhibuka faqad kuththibat rusulun min qablika wa-ila allahi turja''u al-umuru', 'Eğer seni yalanlarlarsa, bil ki onlardan önceki nice peygamberler de yalanlanmıştır. Bütün işler sonunda Allah''a döndürülür.'),
(35, 5, 22, 435, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'yā ayyuhā an-nāsu inna waʿda Allāhi ḥaqqun falā taghurrannakumul-ḥayātu ad-dunyā walā yaghurrannakum billāhi al-ghurūru', 'Ey insanlar! Şüphesiz Allah''ın vaadi gerçektir. Sakın dünya hayatı sizi aldatmasın; sakın çok aldatıcı olan şeytan sizi Allah ile aldatmasın.'),
(35, 6, 22, 435, 'إِنَّ ٱلشَّيْطَٰنَ لَكُمْ عَدُوٌّ فَٱتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَٰبِ ٱلسَّعِيرِ', 'ʾinna ʾš-šayṭāna lakum ʿaduwwun fa-ttāḫiḏūhu ʿaduwwan ʾinnamā yadʿū ḥizbahu li-yakūnū min ʾaṣḥābi s-saʿīri', 'Şüphesiz şeytan sizin için bir düşmandır. Öyleyse onu düşman edinin. O, kendi taraftarlarını ancak ateşin yoldaşları olmaları için çağırır.'),
(35, 7, 22, 435, 'ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌ شَدِيدٌ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'alladhīna kafarū lahum ʿadhābun shadīd walladhīna āmānū wa ʿamilū ṣ-ṣāliḥāti lahum maghfiratun wa ajrun kabīr', 'İnkâr edenler için çetin bir azap vardır. İman edip sâlih amel işleyenler için de mağfiret ve büyük bir mükâfat vardır.'),
(35, 8, 22, 435, 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ', 'afaman zuyyine lehuu suu''u ''amelihii fara''aahu hasenen fe''innallaaha yudıllu men yeshaaa''u ve yahdii men yeshaaa'' felâa tezheb nefsuke ''aleyhim haseraatin ''innallaaha ''aliimun bimaa yasna''uun', 'Kötü ameli kendisine güzel gösterilip de onu güzel gören kimse (ile iman edip salih amel işleyen bir olur mu)? Şüphe yok ki Allah, dilediğini saptırır, dilediğini de doğru yola iletir. O halde, onlara (onların hallerine) üzülerek kendini mahvetme! Şüphesiz Allah, onların yapmakta olduklarını hakkıyla bilendir.'),
(35, 9, 22, 435, 'وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا كَذَٰلِكَ ٱلنُّشُورُ', 'wa-llāhu alladhī arsala r-riyāḥa fatuthīru saḥāban fasuqnāhu ilā baladin mayyitin faʾaḥyaynā bihi l-ʾarḍa baʿda mawtihā kadhālika n-nushūru', 'Allah, rüzgârları gönderendir. Rüzgârlar, bulutları harekete geçirir. Biz de o bulutları ölü bir beldeye sevk ederiz de onunla yeryüzünü ölümünden sonra diriltiriz. İşte ölümden sonra diriliş de böyledir.'),
(35, 10, 22, 435, 'مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّٰلِحُ يَرْفَعُهُۥ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَدِيدٌ وَمَكْرُ أُو۟لَٰٓئِكَ هُوَ يَبُورُ', 'man kāna yurīdu l-ʿizze-ta fa-li-llāhi l-ʿizze-tu jamīʿā-n ilayhi yaṣʿadu l-kalimu ṭ-ṭayyibu wa-l-ʿamalu ṣ-ṣāliḥu yarfaʿuhu-ū wa-llaḏīna yamkurūna s-sayyi-ʾāti lahum ʿaḏābun shadīd wa-makru ʾu-lāʾi-ka huwa yabūr', 'Kim izzet (güç ve şeref) istiyorsa, bilsin ki izzetin tamamı Allah''ındır. O''na en iyi sözler yükselir ve salih amel de onu yükseltir. Kötülükler tuzak kuranlara gelince, onlar için çetin bir azap vardır ve onların tuzakları (boşa çıkıp) yok olacaktır.'),
(35, 11, 22, 435, 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'wa-llāhu ḵalaqakum min turābin thumma min nuṭfatin thumma ǧaʿalakum azwāǧan wa-mā taḥmilu min ʾunṯā wa-lā taḍaʿu ʾillā bi-ʿilmihī wa-mā yuʿammaru min muʿammarin wa-lā yunqaṣu min ʿumurihi ʾillā fī kitābin ʾinna ḏālika ʿalā llāhi yasīrun', 'Allah sizi topraktan, sonra bir nutfeden yarattı. Sonra da sizi çiftler (erkek ve kadın) kıldı. Bir dişi ne gebe kalır ve ne de doğurur ki O''nun bilgisi dışında olsun. Bir ömür sürene ömür verilmesi ve ömrünün eksiltilmesi de ancak O''nun ilminde (yazılı)dır. Şüphesiz bunlar Allah''a göre kolaydır.'),
(35, 12, 22, 436, 'وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَٰذَا مِلْحٌ أُجَاجٌ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'wa mā yastawī l-baḥrān hādhā ʿadhbun furātun sāʾighun sharābuhu wa hādhā milḥun ujājun wa min kullin taʾkulūna laḥman ṭariyyan wa tastakhrijūna ḥilyatan talbasūnahā wa tarā l-fulka fīhi mawākhira li-tabtaghū min faḍlihī wa laʿallakum tashkurūna', 'İki deniz bir olmaz. Birisi tatlı, susuzluğu giderici, içimi kolaydır; diğeri tuzlu ve acıdır. Hepsinden taze et yersiniz ve takınacağınız süs eşyaları çıkarırsınız. Onun bol nimetinden arayıp-gözetmeniz için gemilerin de onu yararak (ilerlediğini) görürsün. Umulur ki şükredersiniz.'),
(35, 13, 22, 436, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ', 'yūliju l-layla fī n-nahāri wa yūliju n-nahāra fī l-layli wa saḵḵara š-šamsa wa l-qamara kullun yajrī li-ʾajalin musammā ḏālikumu llāhu rabbukum lahu l-mulku wa l-laḏīna tadʿūna min dūnihi mā yamlikūna min qiṭmīrin', 'Geceyi gündüze sokar, gündüzü de geceye sokar. Güneşi ve Ay''ı buyruğu altına almıştır. Her biri belirlenmiş bir vakte kadar akar. İşte bu, Rabbiniz Allah''tır. Mülk O''nundur. O''ndan başka taptıklarınız, bir ''kıtmir'' (hurma çekirdeği zarı) kadar bile hükümran olamazlar.'),
(35, 14, 22, 436, 'إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ وَيَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ', 'in tadʿūhum lā yasmaʿū duʿāʾakum wa-law samiʿū mā istajābū lakum wa-yawma l-qiyāmati yakfurūna bi-shir’kikum wa-lā yunabbiʾuka mithlu khabīrin', 'Onları çağırsanız, çağrınızı işitmezler. İşitseler bile, size cevap veremezler. Kıyamet günü ise sizin ortak koştuğunuzu reddederler. Ve sana, her şeyi bilen (Allah) gibi haber verecek kimse yoktur.'),
(35, 15, 22, 436, 'يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'yā ayyuhā n-nāsu antumul-fuqarāʾu ilā llāhi wa llāhu huwal-ġaniyyul-ḥamīdu', 'Ey insanlar! Siz Allah''a muhtaç olanlarsınız. Zengin olan ve her türlü övgüye layık olan ancak Allah''tır.'),
(35, 16, 22, 436, 'إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'in yaša yuḏhibkum wa yaʾti bi-ḫalqin ǧadīd', 'Eğer dilerse, sizi giderip yok eder ve yeni bir yaratık getirir.'),
(35, 17, 22, 436, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'wa mā dhālika ʿalā Llāhi bi ʿazīzin', 'Halbuki bu, Allah''a göre zor değildir.'),
(35, 18, 22, 436, 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'wa lā taziru wāziratun wizra ʾuḵrā wa ʾin tadʿu muṯqalatun ʾilā ḥimlihā lā yuḥmal minhu šayʾun wa law kāna ḏā qurbā ʾinnamā tunḏiru ʾallaḏīna yaḵšawna rabbahum bil-ḡaybi wa ʾaqāmū ṣ-ṣalāh wa man tazakkā fa-ʾinnamā yatazakkā li-nafsihi wa ʾilā llāhi l-maṣīr', 'Hiçbir günahkar, başkasının günah yükünü çekmez. Eğer ağır yüklü bir kimse, onu taşımak için (başkasını) çağırsa, -bu kimse akrabası bile olsa- onun yükünden hiçbir şey taşınmaz. Sen ancak, görmedikleri halde Rablerinden korkanları ve namazı kılanları uyarabilirsin. Kim temizlenirse, kendi iyiliği için temizlenmiş olur. Dönüş Allah''adır.'),
(35, 19, 22, 437, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ', 've-mā yestewī l-aʿmā ve-l-baṣīr', 'Kör ile basiretli bir olmaz.'),
(35, 20, 22, 437, 'وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ', 'wa-lā ẓ-ẓulumātu wa-lā n-nūru', 'Karanlıklar da eşit olmaz, aydınlık da.'),
(35, 21, 22, 437, 'وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ', 'wa-l-aẓ-ẓillu wa-la al-ḥarūru', 'Ne gölge ve ne de (yakıcı) sıcak.'),
(35, 22, 22, 437, 'وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى ٱلْقُبُورِ', 've mā yastawī l-ʾaḥyāʾu wa lā l-ʾamwātu ʾinna llāha yusmiʿu man yashāʾu wa mā ʾanta bi-musmiʿin man fī l-qubūri', 'Ne de ölüler bir olmaz. Şüphesiz Allah, dilediği kimseye işittirir. Sen kabirlerde olanlara işittirecek değilsin.'),
(35, 23, 22, 437, 'إِنْ أَنتَ إِلَّا نَذِيرٌ', 'ʾin ʾanta ʾillā naḏīrun', 'Sen, yalnızca bir uyarıcısın.'),
(35, 24, 22, 437, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ', 'ʾinnā ʾarsalnāka bil-ḥaqqi bashīran wa nadhīran wa ʾin min ʾummatin ʾillā khalā fīhā nadhīrun', 'Şüphesiz biz seni hak ile müjdeleyici ve uyarıcı olarak gönderdik. İçinde uyarıcı bulunmamış hiçbir ümmet yoktur.'),
(35, 25, 22, 437, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَٰبِ ٱلْمُنِيرِ', 'wa-in yukadhdhibūka faqad kadhdhaba alladhīna min qablihim jāʾathum rusuluhum bil-bayyināti wa-biz-zuburi wa-bil-kitābi al-munīri', 'Eğer seni yalanlarlarsa, onlardan öncekiler de yalanlamışlardı. Onlara peygamberleri apaçık delillerle, sahifelerle ve aydınlatıcı kitapla gelmişti.'),
(35, 26, 22, 437, 'ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ فَكَيْفَ كَانَ نَكِيرِ', 'thumma akhadhtu alladhīna kafarū fakayfa kāna nakīrī', 'Sonra kâfir olanları yakaladım. (O zaman) benim inkârım (cezam) nasıl oldu?'),
(35, 27, 22, 437, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ', 'Elem tera enne Allāhe enzele mines-semāʾi māʾan Feʾahraknā bihi semerātin muhtelifan elwānuhā Ve minel-gibāli cudadun bīḍun ve ḥumrun muhtelifun elwānuhā ve ġarābību sūd', 'Görmedin mi, Allah gökten bir su indirdi de onunla renkleri türlü türlü ürünler çıkardık. Dağlardan da beyaz ve kırmızı renklerde, değişik yollara ayrılmış (veya çeşitli) yollar vardır.'),
(35, 28, 22, 437, 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', 'wa mina n-nāsi wa d-dawābbi wa l-anʿāmi mukhtalifun alwānuhu kadhālika innamā yakhshā llāha min ʿibādihī l-ʿulamāʾu inna llāha ʿazīzun ghafūrun', 'İnsanlardan, (canlı) hayvanlardan ve (diğer) evcil hayvanlardan da yine onun gibi renkleri değişik olanlar vardır. Kulları içinde Allah''tan ancak âlimler [O''nun büyüklüğünü ve kudretini bilenler] korkar. Şüphesiz Allah, Azîz''dir (mutlak güç sahibidir), Gafûr''dur (çok bağışlayandır).'),
(35, 29, 22, 437, 'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَٰرَةً لَّن تَبُورَ', 'ʾinna alladhīna yatlūna kitāba llāhi wa ʾaqāmū ṣ-ṣalāta wa ʾanfaqū mimmā razaqnāhum sirran wa ʿalāniyatan yarjūna tijāratan lan tabūra', 'Şüphesiz Allah''ın Kitabını okuyanlar, namazı kılanlar ve kendilerine verdiğimiz rızıktan gizli ve açık olarak harcayanlar, asla zarar etmeyecek (tükenmeyecek) bir ticaret umarlar.'),
(35, 30, 22, 437, 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ إِنَّهُۥ غَفُورٌ شَكُورٌ', 'liyuwaffiyahum ujūrahum wayazīdahum min faḍlihī ʾinnahuw ġafūrun šakūr', 'Onların mükâfatlarını tam olarak ödemesi ve lütfundan onlara fazlasıyla vermesi için. Şüphesiz O, çok bağışlayandır, çok şükredene karşılığını verendir.'),
(35, 31, 22, 438, 'وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌ', 'wa-lladhī ʾawḥaynā ʾilayka mina l-kitābi huwa l-ḥaqqu muṣaddiqan limā bayna yadayhi ʾinna llāha bi-ʿibādhihī la-khabīrun baṣīrun', 'Sana vahyettiğimiz Kitap da, kendinden öncekileri doğrulayan hak (olan)dır. Şüphesiz Allah, kullarının durumundan hakkıyla haberdar, (her şeylerini) hakkıyla görendir.'),
(35, 32, 22, 438, 'ثُمَّ أَوْرَثْنَا ٱلْكِتَٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 'thumma awrathnā l-kitāba lladhīna ṣṭafaynā min ʿibādinā faminhum ẓālimun linafsihi waminhum muqtaṣidun waminhum sābiqūm bil-khayrāti bi-idhni llāhi dhālika huwa l-faḍlu l-kabīru', 'Sonra, kullarımızdan seçtiğimiz kimselere o kitabı miras kıldık. Onlardan, kendi nefsine zulmedenler, onlardan orta yolu tutanlar ve onlardan Allah''ın izniyle hayırlarda öne geçenler vardır. İşte bu, büyük lütfun ta kendisidir.'),
(35, 33, 22, 438, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'jannātu ʿadnin yadkhulūnahā yuḥallawna fīhā min ʾasāwira min dhahabin wa-luʾluʾan wa-libāsuhum fīhā ḥarīrun', 'Adn cennetleri; oraya girerler, orada altından bileziklerle ve incilerle süslenirler. Oradaki elbiseleri ise ipektir.'),
(35, 34, 22, 438, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ', 'wa qālū al-ḥamdu li-llāhi alladhī ʾadhhaba ʿannā al-ḥazana ʾinna rabbanā la-ghafūrun shakkūrun', 'Ve dediler ki: Hamd, bizden hüznü gideren Allah''a mahsustur. Şüphesiz Rabbimiz, Gafûr''dur, Şekûr''dur.'),
(35, 35, 22, 438, 'ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ', 'alladhī ʾaḥallanā dāra l-muqāmati min faḍlihī lā yamassunā fīhā naṣabun walā yamassunā fīhā lughūbun', 'O ki, fazlından dolayı bizi kalıcı yurda (cennete) yerleştirdi; burada bize bir yorgunluk da dokunmaz, usanç da dokunmaz.'),
(35, 36, 22, 438, 'وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ', 'wa-lladhīna kafarū lahum nāru jahannama lā yuqḍā ʿalayhim fa-yamūtū wa-lā yukhaffafu ʿanhum min ʿadhābihā kadhālika najzī kulla kafūr', 'İnkâr edenlere gelince; onlara cehennem ateşi vardır. Ne (ölümle) hükmedilir ki ölsünler, ne de onlardan azabı hafifletilir. İşte biz, her nankörü böyle cezalandırırız.'),
(35, 37, 22, 438, 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ فَذُوقُوا۟ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', 'wa hum yaṣṭarikhūna fīhā rabbana ʾakhrijnā naʿmal ṣāliḥan ghayra lladhī kunnā naʿmalu ʾa wa lam nuʿammir kum mā yatadhakkaru fīhi man tadhakkara wa jāʾakumu n-nad hīru fa dhūqū fa mā liẓ-ẓālimīna min naṣīri', 'Onlar orada, "Rabbimiz! Bizi çıkar, yapageldiklerimizden başka, salih amel işleyelim!" diye feryat ederler. (Allah Teâlâ şöyle buyurur:) "Sizi, düşünebilen kimsenin düşünebileceği kadar bir ömürle yaşatmadık mı? Hem size uyarıcı da gelmişti. Artık tadın! Zalimler için hiçbir yardımcı yoktur."'),
(35, 38, 22, 438, 'إِنَّ ٱللَّهَ عَٰلِمُ غَيْبِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'ʾinna llāha ʿālimu ḡaybi s-samāwāti wa-l-ʾarḍi ʾinnahu ʿalīmun bi-ḏāti ṣ-ṣudūri', 'Şüphesiz Allah, göklerin ve yerin gaybini (gizli olanlarını) bilendir. Şüphesiz O, göğüslerin özünü (kalplerde olanı) bilendir.'),
(35, 39, 22, 439, 'هُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا', 'huwa lladhī jaʿalakum khalāʾifa fī l-arḍi faman kafara faʿalayhi kufrhu walā yazīdu l-kāfirīna kufrhum ʿinda rabbihim illā maqtan walā yazīdu l-kāfirīna kufrhum illā khasāran', 'O, sizi yeryüzünde halifeler kılan (veya eden) zâttır. Artık kim inkâr ederse, inkârı kendi aleyhinedir. Kâfirlerin inkârı, Rableri katında kendilerine (azaptan) başka bir artış sağlamaz. Kâfirlerin inkârı, onlara (azaptan) başka bir artış sağlamaz.'),
(35, 40, 22, 439, 'قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ بَلْ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', 'Qul araʾaytum shurakāʾakumu lladhīna tadʿūna min dūni llāhi Arūnī mādhā khalaqū mina l-arḍi Am lahum shirkun fī s-samāwāti Am ātaynāhum kitāban fahum ʿalā bayyinatin minhu Bal in yaʿidu ẓ-ẓālimūna baʿḍuhum baʿḍan illā ghurūran', 'De ki: "Hiç düşündünüz mü? Allah''tan başka tapmakta olduğunuz ortaklarınızı (söyleyin bana)! Onlar yerden ne yaratmışlardır? Yoksa onların göklerde bir ortaklığı mı vardır? Yoksa biz onlara bir kitap verdik de onlar o kitaptan (gelen) apaçık bir delil üzere midirler? Hayır! O zalimler birbirlerine aldatmadan başka bir şey vaad etmezler."'),
(35, 41, 22, 439, 'إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّنۢ بَعْدِهِۦٓ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', 'ʾinna ʾallāha yumsiku ʾssamāwāti wa-l-ʾarḍa ʾan tazūlā wa-laʾin zālatā ʾin ʾamsakahumā min ʾaḥadin min baʿdihī ʾinnahū kāna ḥalīman ġafūrā', 'Şüphesiz Allah, gökleri ve yeri, yok olup gitmelerinden dolayı tutar. Andolsun ki eğer onlar yok olup giderlerse, O''ndan başka hiç kimse onları tutamaz. Şüphesiz O, halimdir, çok bağışlayandır.'),
(35, 42, 22, 439, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا', 'waʾaqsamū billāhi jahda ʾaymānihim laʾin jāʾahum naḏīrun layakūnnunna ʾahdā min ʾiḥdā ʾil-ʾumam falammā jāʾahum naḏīrun mā zādahum ʾillā nufūran', 'Onlar, bütün güçleriyle Allah''a yemin ederek: ''Kendilerine bir uyarıcı gelirse, hiç şüphesiz diğer ümmetlerden daha çok doğru yolda olacaklardır'' demişlerdi. Ne var ki, onlara bir uyarıcı geldiğinde, bu onların hakka olan nefretinden başka bir şeyi artırmadı.'),
(35, 43, 22, 439, 'ٱسْتِكْبَارًا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا', 'istikbāran fīl-arḍi wa makras-sayyiʾi wa lā yaḥīqu l-makrus-sayyiʾu illā bi-ʾahlihī fa-hal yanẓurūna illā sunnatal-ʾawwalīna fa-lan tajida li-sunnatillāhi tabdīlan wa lan tajida li-sunnatillāhi taḥwīlan', 'Yeryüzünde bir kibir taslama ve kötü tuzak kurma (vebalini çekmezler). Kötü tuzak ise ancak kuranların başınadır. (Onlar) Vaktiyle geçenlerin (Allah''ın) yasalarından başkasını mı gözleyip bekliyorlar? Allah''ın yasasında asla bir değişiklik bulamazsın ve Allah''ın yasasında asla bir sapma bulamazsın.'),
(35, 44, 22, 439, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا', 'awalam yasīrū fī l-arḍi fa-yanẓurū kayfa kāna ʿāqibatu l-ladhīna min qablihim wa kānū ashadda minhum quwwatan wa mā kāna l-lāhu li-yuʿjizahu min shayʾin fī s-samāwāti wa lā fī l-arḍi ʾinnahu kāna ʿalīman qadīran', 'Onlar yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Halbuki onlar, bunlardan daha kuvvetli idiler. Ne göklerde ne de yerde Allah''ı aciz bırakacak hiçbir şey yoktur. O, her şeyi bilen, her şeye gücü yetendir.'),
(35, 45, 22, 440, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا', 'wa law yu''ākhiḏu ʾllāhu n-nāsa bimā kasabū mā taraka ʿalā ẓahrihā min dābbatin wa lākin yu''aḫḫiruhum ʾilā ʾajalin musammā fa-ʾiḏā jāʾa ʾajaluhum fa-ʾinna ʾllāha kāna bi-ʿibādihī baṣīrā', 'Eğer Allah, insanları kazandıklarıyla hesaba çekecek olsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat onları belirli bir vakte kadar ertelemektedir. Ecelleri geldiğinde ise şüphesiz Allah kullarını hakkıyla görendir.'),
(36, 1, 22, 440, 'يسٓ', 'yā sīn', 'Yâ Sîn'),
(36, 2, 22, 440, 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', 'wa-l-qurʾāni l-ḥakīmi', 'Yemin olsun, hikmet dolu Kur’an’a ki,'),
(36, 3, 22, 440, 'إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'ʾinnaka lamina l-mur''salīn', 'Şüphesiz sen gönderilenlerdensin.'),
(36, 4, 22, 440, 'عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'ʿalā ṣirāṭin mustaqīm', 'Dosdoğru bir yol üzerindedir.'),
(36, 5, 22, 440, 'تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ', 'tanzīla l-ʿazīzi r-raḥīmi', 'O, mutlak güç sahibi, engin merhamet sahibi tarafından indirilmiştir.'),
(36, 6, 22, 440, 'لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ', 'li-tunḏira qawman mā unḏira ʾābāʾuhum fa-hum ġāfilūn', 'Onları, ataları uyarılmamış, bu yüzden de gaflet içinde kalmış bir kavmi uyarman için (gönderdik).'),
(36, 7, 22, 440, 'لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', 'leḳad ḥaḳḳa-lḳavlu `alâ ekŝerihim fehum lâ yu''minûn', 'Andolsun ki söz, onların çoğunun üzerine hak olmuştur; bu yüzden onlar iman etmezler.'),
(36, 8, 22, 440, 'إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ', 'ʾinnā jaʿalnā fī ʾaʿnāqihim ʾaḡlālan fa-hiya ʾilā l-ʾaḏqāni fa-hum muqmaḥūna', 'Onların boyunlarına, çenelerine kadar uzanan demir halkalar geçirdik. Bu yüzden başları yukarı kalkıktır.'),
(36, 9, 22, 440, 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ', 'wa jaʿalnā mim bayni aydīhim saddan wa min khalfihim saddan fa ʾaghshaynahum fa hum lā yubṣirūn', 'Ve onlardan önde bir sed, arkalarından da bir sed yaptık. Böylece onları örtü altına aldık, artık onlar görmezler.'),
(36, 10, 22, 440, 'وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 'wa sawāʾun ʿalayhim ʾaʾanḏartahum ʾam lam tunḏirhum lā yuʾminūn', 'Onları uyarsan da uyarmasan da birdir; inanmayacaklar.'),
(36, 11, 22, 440, 'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ', 'innamā tunẕiru mani-ttabaʿa ẕ-ẕikra wa-khaşiya r-raḥmāna bil-ghaybi fa-bashirhu bi-maghfiratin wa-ajrin karīmin', 'Sen ancak zikre uyan ve görünmeden Rab''den korkan kimseyi uyarabilirsin. İşte onu bir bağışlanma ve büyük bir ecirle müjdele.'),
(36, 12, 22, 440, 'إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍ مُّبِينٍ', 'ʾinnā naḥnu nuḥyī l-mawtā wa naktubu mā qaddamū wa ʾāthārahum wa kulla shayʾin ʾaḥṣaynāhu fī ʾimāmin mubīnin', 'Şüphesiz ölüleri biz diriltiriz ve onların (geleceğe) gönderdikleri şeyleri ve bıraktıkları eserleri yazarız. Zaten biz her şeyi apaçık bir ''imam''da (bilgi kaynağında, ana kitapta) sayıp tespit etmişizdir.'),
(36, 13, 22, 441, 'وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ', 'wa-ḍrib lahum maṯalan aṣḥāb al-qaryah iḏ ǧāʾahā al-murselūn', 'Onlara o şehir halkını misal ver. Hani onlara elçiler gelmişti.'),
(36, 14, 22, 441, 'إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ', 'idh arsalnā ilayhimu ithnayni fakadhdhabūhumā fʿazzaznā bithālithin faqālū innā ilaykum mursalūna', 'Onlara iki elçi göndermiştik, ama onları yalanladılar. Biz de üçüncü bir elçi ile onları destekledik. Bunun üzerine, ''Biz size gönderilmiş elçileriz'' dediler.'),
(36, 15, 22, 441, 'قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ', 'qālū mā ʾantum ʾillā basharun mithlunā wamā ʾanzala ʾrraḥmānu min shayʾin ʾin ʾantum ʾillā takdhibūna', 'Dediler ki: Sizler bizler gibi sadece insanlardan ibaretsiniz. Rahman hiçbir şey indirmemiştir. Sizler sadece yalan söylüyorsunuz.'),
(36, 16, 22, 441, 'قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', 'qālū rabbunā yaʿlamu innā ilaykum lamursalūna', 'Dediler ki: Rabbimiz biliyor, şüphesiz biz size gönderilmiş elçileriz.'),
(36, 17, 22, 441, 'وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 've mā ʿalaynā ʾillā l-balāġu l-mubīn', 'Ve bizim üzerimize düşen apaçık tebliğden başkası değildir.'),
(36, 18, 22, 441, 'قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ', 'qālū inna taṭayyarna bikum laʾin lam tantahū lanarjumannakum wa layamassannakum minnā ʿadhābun ʾalīmun', 'Dediler ki: ''Sizin yüzünüzden uğursuzluğa uğradık. Eğer vazgeçmezseniz, sizi mutlaka taşlarız ve bizden size elem dolu bir azap dokunur.'''),
(36, 19, 22, 441, 'قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ أَئِن ذُكِّرْتُم بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', 'qālū ṭāʾirukum maʿakum aʾin dhukkirtum bal ʾantum qawmun musrifūna', 'Dediler ki: ''Sizin uğursuzluğunuz sizinle birliktedir. Size öğüt verildi diye mi (böyle yapıyorsunuz)? Hayır, siz israfçı bir toplumsunuz.'''),
(36, 20, 22, 441, 'وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ', 'wa jāʾa min ʾaqṣā l-madīnati rajulun yasʿā qāla yā qawmi ʾittabiʿū l-mursilīn', 'Şehrin uzak tarafından bir adam koşarak geldi. "Ey kavmim!" dedi, "Elçilere uyun."'),
(36, 21, 22, 441, 'ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ', 'ittabiʿū man lā yasʾalukum ajran wa hum muhtadūna', 'Sizden bir karşılık istemeyen ve doğru yolu bulan kimselere uyun.'),
(36, 22, 22, 441, 'وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ', 'wa mā liya lā ʾaʿbudu l-ladhī faṭaranī wa ʾilayhi turjaʿūna', 'Bana ne oluyor da beni yaratanı kulluk etmeyeyim? Ve siz de O''na döndürüleceksiniz.'),
(36, 23, 22, 441, 'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًٔا وَلَا يُنقِذُونِ', 'ʾaʾattakhidhu min dūnihi ʾālihah ʾin yuridni ʾr-raḥmānu biḍurrin lā tughni ʿannī shafāʿatuhum shayʾan wa lā yunqidhūn', 'O''nu bırakıp da başka ilahlar mı edineyim? Eğer Rahman (olan Allah) bana bir zarar irade ederse, onların şefaatı benden hiçbir fayda sağlamaz ve beni kurtaramazlar.'),
(36, 24, 22, 441, 'إِنِّىٓ إِذًا لَّفِى ضَلَٰلٍ مُّبِينٍ', 'ʾinnī ʾiḏan lafī ḍalālin mubīn', 'O takdirde ben apaçık bir sapıklık içinde olurum.'),
(36, 25, 22, 441, 'إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ', 'ʾinnī ʾāmantu birabbikum fāsmʿūnī', 'Şüphesiz ben sizin Rabbinize iman ettim; artık bana kulak verin!'),
(36, 26, 22, 441, 'قِيلَ ٱدْخُلِ ٱلْجَنَّةَ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ', 'qīla dkhuli l-jannata qāla yālayta qawmī yaʿlamūn', 'Ona, "Cennete gir!" denildi. O, "Keşke kavmim bilseydi!" dedi.'),
(36, 27, 22, 441, 'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ', 'bimā ġafara lī rabbī vecaʿalanī mine-l-mukramīn', 'Rabbimin beni bağışladığını ve beni ikram edilenlerden kıldığını (söylemişti).'),
(36, 28, 23, 442, 'وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ', 'wa mā anzalnā ʿalā qawmihī mim baʿdihī min jundim min as-samāʾi wa mā kunnā munzilīn', 'Ve onun kavmi üzerine kendisinden sonra gökten hiçbir ordu indirmedik ve indirecek de değildik.'),
(36, 29, 23, 442, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَٰمِدُونَ', 'in kānat illā ṣayḥatan wāḥidatan fa-iḏā hum khāmidūn', 'Eğer yalnızca korkunç bir ses olsaydı, hemen hepsi sönüp yok olurlardı.'),
(36, 30, 23, 442, 'يَٰحَسْرَةً عَلَى ٱلْعِبَادِ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'yā ḥasratan ʿalā l-ʿibādi mā yaʾtīhim min rasūlin illā kānū bihi yastahziʾūn', 'Yazıklar olsun o kullara! Kendilerine gelen her peygamberle alay ederlerdi.'),
(36, 31, 23, 442, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', 'ʾelem yerevʾ kem ʾehleknā ḳabléhum mine-l-ḳurūni ʾennehum ʾileyhim lā yerdžiʿūne', 'Onlardan önce nice nesilleri helak ettiğimizi görmediler mi? (Onlar) kendilerine geri dönmemektedirler.'),
(36, 32, 23, 442, 'وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', 'wa ʾinna kulla lammā jamīʿun ladaynā muḥḍarūn', 'Ve şüphesiz ki hepsi, topluca huzurumuza getirileceklerdir.'),
(36, 33, 23, 442, 'وَءَايَةٌ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ', 'wa-āyatun lahumu l-arḍu l-maytatu aḥyaynāhā wa-akhrajnā minhā ḥabban faminhu yaʾkulūn', 'Onlar için bir delil de (o) topraktır. Biz onu (kuraklıktan sonra) dirilttik ve ondan taneler çıkardık da onlardan yiyorlar.'),
(36, 34, 23, 442, 'وَجَعَلْنَا فِيهَا جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ', 'wa jaʿalnā fīhā jannātin min nakhīlin wa aʿnābin wa fajjarnā fīhā mina l-ʿuyūni', 'Onun için (yeryüzünde) bir delil de, (şöyle) buyurmamızdır: Biz ondan (topraktan) suyu çıkardık ve onunla taneler bitirdik; hem onunla beslenirler.'),
(36, 35, 23, 442, 'لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ', 'liyaʾkulū min ṯamarihī wa mā ʿamilathu ʾaydīhim ʾafla yaškurūn', 'Onların, hem ondan (meyvelerinden) yemeleri hem de ellerinin (yapıp) ürettiği (ürünlerden) yararlanmaları için. Hâlâ şükretmiyorlar mı?'),
(36, 36, 23, 442, 'سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', 'subḥāna lladhī khalaqa l-ʾazwāja kullahā mimmā tunbitu l-ʾarḍu wa min ʾanfusihim wa mimmā lā yaʿlamūn', 'Bütün çiftleri yaratanın yüceliği ne kadar aşkındır! Yerin bitirdiklerinden, kendi nefislerinden ve onların bilmediği şeylerden (çiftler yaratmıştır).'),
(36, 37, 23, 442, 'وَءَايَةٌ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', 'wa-āyatun lahumu al-laylu naslaḫu minhu al-nahāra fa-iḏā hum muẓlimūna', 'Gece de onlara bir delildir. Gündüzü ondan çıkarırız da bir anda karanlığa gömülürler.'),
(36, 38, 23, 442, 'وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 've''ş-şemsu tecriy li-musteqarrin leha żalike takdiru''l-`azizi''l-`alim', 'Güneş de kendi yörüngesinde akıp gitmektedir. Bu, mutlak güç sahibi ve hakkıyla bilen Allah''ın takdiridir.'),
(36, 39, 23, 442, 'وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ', 'wa-l-qamara qaddarnāhu manāzila ḥattā ʿāda ka-l-ʿurjūni l-qadīmi', 'Ve Ay''ı da, sonunda eski eğri hurma dalı gibi oluncaya kadar, çeşitli evrelerden geçirdik.'),
(36, 40, 23, 442, 'لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ', 'la ash-shamsu yanbaghi laha an tudrika al-qamara wa la al-laylu sabiqu an-nahari wa kullun fi falakin yasbahuna', 'Ne güneşin Ay''a yetişmesi ona gerekir, ne de gecenin gündüzü geçmesi. Ve onların her biri bir yörüngede yüzmektedir.'),
(36, 41, 23, 443, 'وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'wa-āyatun lahum annā ḥamalnā dhurriyyatahum fī l-fulki l-mashḥūn', 'Onlar için bir delil de, onların nesillerini o dolu gemi içinde taşımış olmamızdır.'),
(36, 42, 23, 443, 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ', 'wa ḵalaqnā lahum mim miṯlihi mā yarkabūn', 'Onlar için kendisi gibi binecekleri (binekler) de yarattık.'),
(36, 43, 23, 443, 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', 'wa ʾin našʾa nuġriqhum falā ṣarīḵa lahum walā hum yunqaḏūn', 'Ve eğer dilersek, onları boğarız da ne bir imdatçıları olur ne de kurtarılırlar.'),
(36, 44, 23, 443, 'إِلَّا رَحْمَةً مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍ', 'illa raḥmetan minnā wa matāʿan ilā ḥīn', 'Ancak tarafımızdan bir rahmet ve belirli bir zamana kadar bir yararlanma (olsaydı).'),
(36, 45, 23, 443, 'وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', 'wa-ʾidhā qīla lahumu-ttqū mā bayna ʾaydīkum wa-mā khalfakum laʿallakum turḥamūn', 'Onlara: "Önünüzde ve arkanızda olan (geçmiş ve gelecek günahlardan) sakının ki, esirgenesiniz" dendiği zaman da, Rablerinin âyetlerinden her hangi bir âyet gelip de onlara yüz çevirmeyenlerden başkası iman etmez.'),
(36, 46, 23, 443, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 'wa mā taʾtīhim min ʾāyatin min ʾāyāti rabbihim ʾillā kānū ʿanhā muʿriḍīn', 'Onlara, Rablerinin ayetlerinden bir ayet gelmeksizin, ondan yüz çevirenler olmazdı.'),
(36, 47, 23, 443, 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ مُّبِينٍ', 'wa-ʾidhā qīla lahum ʾanfiqū mimmā razaqakumū ʾllāhu qāla ʾlladhīna kafarū lilladhīna ʾāmanū ʾanuṭʿimu man law yashāʾū ʾllāhu ʾaṭʿamahū ʾin ʾantum ʾillā fī ḍalālin mubīnin', 'Onlara: "Allah''ın size verdiği rızıktan hayra sarfedin" denildiği zaman, inkâr edenler iman edenlere dediler ki: "Allah''ın, eğer dileyecek olsaydı yedireceği kimseleri biz mi doyuracağız? Siz ancak apaçık bir sapıklık içindesiniz."'),
(36, 48, 23, 443, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hādhā al-waʿdu in kuntum ṣādiqīn', 'Ve derler: ''Eğer doğru sözlüler iseniz, bu vaad (olan azap) ne zaman?'''),
(36, 49, 23, 443, 'مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', 'Mā yanẓurūna illā ṣayḥatan wāḥidatan taʾkhuḏuhum wa hum yakh iṣṣimūn', 'Onlar, kendilerini yakalayıverecek tek bir korkunç sesten başkasını gözetmezler. Onlar çekişip dururlarken...'),
(36, 50, 23, 443, 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ', 'falā yastaṭīʿūna tawṣiyatan walā ʾilā ʾahlihim yarjiʿūn', 'Ne bir vasiyet etmeye güçleri yeter, ne de ailelerine dönebilirler.'),
(36, 51, 23, 443, 'وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', 'wa nufikha fī ṣ-ṣūri fa-ʾiḏā hum mina l-ʾajdāṯi ʾilā rabbihim yansilūn', 'Nihayet sûra üflenince, bir de ne görsünler! Hepsi kabirlerinden (dirilip) telaşla Rablerine koşuyorlar.'),
(36, 52, 23, 443, 'قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ', 'qālū yā waylanā man baʿathanā min marqadinā hādhā mā waʿada r-raḥmānu wa ṣadaqa l-mursalūna', 'Dediler ki: "Vay halimize! Bizi kabrimizden kim kaldırdı? Bu, Rahman’ın vaadettiği şeydir. Peygamberler de doğru söylemiş."'),
(36, 53, 23, 443, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', 'in kānet illā ṣayḥatan wāḥidatan fa-iḏā hum jamīʿun ladaynā muḥḍarūn', 'O, yalnız korkunç bir ses (sayha) oluverdi, bir de ne görelim, hepsi birden toplanıp (hesap için) dergahımıza getirilmişlerdi.'),
(36, 54, 23, 443, 'فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'fa-l-yawma lā tuẓlamu nafṣun shayʾan wa lā tujzawna illā mā kuntum taʿmalūn', 'Artık bugün hiçbir kimseye zerre kadar zulmedilmez. Ve siz ancak yaptıklarınızın karşılığını alırsınız.'),
(36, 55, 23, 444, 'إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍ فَٰكِهُونَ', 'ʾinna ʾaṣḥāba l-jannati l-yawma fī šuġulin fākihūna', 'Şüphesiz cennet ehli o gün bir meşguliyet içindedirler; onlar ve eşleri gölgeliklerde, yaslanmışlardır.'),
(36, 56, 23, 444, 'هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ', 'hum wa azwājuhum fī ẓilālin ʿalā l-ʾarāʾiki muttakiʾūna', 'Onlar ve eşleri, gölgeliklerde, koltuklara yaslanmışlardır.'),
(36, 57, 23, 444, 'لَهُمْ فِيهَا فَٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ', 'lahum fīhā fākihah wa lahum mā yaddaʿūn', 'Onlar için orada (cennette) her türlü meyve vardır ve onların orada arzu ettikleri her şey vardır.'),
(36, 58, 23, 444, 'سَلَٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ', 'salāmun qawlan mir rabbir raḥīm', 'Rahîm (olan) bir Rab''den bir söz olarak: Selâm!'),
(36, 59, 23, 444, 'وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ', 'wa-mtāzū al-yawma ayyuhā al-mujrimūn', 'Ey suçlular! Bugün siz (onlardan) ayrılın!'),
(36, 60, 23, 444, 'أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'ʾelem ʾaʿhed ʾileykum yā-benī ʾādama ʾen lā taʿbudū ʾš-šayṭāna ʾinnahuu ʾelaykum ʿaduvvun mubīnun', 'Ey Ademoğulları! Size, şeytana kulluk etmeyin diye ahdetmedim mi? Çünkü o, size apaçık bir düşmandır.'),
(36, 61, 23, 444, 'وَأَنِ ٱعْبُدُونِى هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'wa-ʾan-i-ʿbudūnī hādhā ṣirāṭun mustaqīm', 'Ve Bana kulluk edin. İşte bu, dosdoğru yoldur.'),
(36, 62, 23, 444, 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ', 'Ve lekad edalle minkum cibillen kesîrâ E fe lem tekûnû ta''kılûn', 'Andolsun ki o, sizden pek çok nesli saptırmıştı. Hâlâ akıl etmez misiniz?'),
(36, 63, 23, 444, 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'hāḏihi jahanamul-latī kuntum tūʿadūn', 'İşte bu, size vaad olunan cehennemdir.'),
(36, 64, 23, 444, 'ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', 'iṣlawhā l-yawma bimā kuntum takfurūn', 'Bugün, küfrede gelmekte olduğunuz şeyden dolayı oraya girin!'),
(36, 65, 23, 444, 'ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'al-yawma nakhtimu ʿalā ʾafwāhihim wa tukallimunā ʾaydīhim wa tash-hadu ʾarjuluhum bimā kānū yaksibūn', 'Bugün onların ağızlarını mühürleriz. Bize elleri konuşur ve ayakları kazandıklarını şahitlik eder.'),
(36, 66, 23, 444, 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ', 'wa law nashāʾu laṭamasnā ʿalā ʾaʿyunihim fastabaqū aṣ-ṣirāṭa fa-ʾannā yubṣirūn', 'Eğer dilemiş olsaydık, onları düpedüz kör ederdik de (o zaman) yolu bulmaya çalışırlardı, ama nasıl görebilirlerdi?'),
(36, 67, 23, 444, 'وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّا وَلَا يَرْجِعُونَ', 'wa law nashāʾu la-masakhnāhum ʿalā makānatihim fa-mā staṭāʿū muḍiyyan wa lā yarjiʿūn', 'Dileseydik onları oldukları yerde başka bir şekle sokardık da ne ileri gidebilirler ne de geri dönebilirlerdi.'),
(36, 68, 23, 444, 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ أَفَلَا يَعْقِلُونَ', 'wa-man nuʿammir-hu nunakkis-hu fī l-khalqi ʾafalā yaʿqilūn', 'Kimi ömrünü uzatırsak onu yaratılışta geri çeviririz. Hala akıl erdiremiyorlar mı?'),
(36, 69, 23, 444, 'وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ', 've mâ ''allemnâhu-ş şi''ra ve mâ yenbeğî lehu in huve illâ zikrun ve kur''ânun mubînun', 'Biz ona şiir öğretmedik. Zaten (ona) yakışmazdı. O, ancak bir öğüt ve apaçık bir Kur''an''dır.'),
(36, 70, 23, 444, 'لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ', 'liyunḏira man kāna ḥayyan wayuḥiqqa l-qawlu ʿalā l-kāfirīn', 'Onu, diri olanı uyarması ve kâfirler için de sözün (azabın) hak olması için (indirdik).'),
(36, 71, 23, 445, 'أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًا فَهُمْ لَهَا مَٰلِكُونَ', 'E ve lem yeraw ennā halaknā lehum mimmā ''amilat eydīnā an''āman fehum lehā mālikūn', 'Onların, ellerimizle (kudretimizle) yarattığımız hayvanları görmediler mi ki, onlara malik olmuşlardır?'),
(36, 72, 23, 445, 'وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', 'wa dhallalnāhā lahum faminhā rakūbuhum waminhā yaʾkulūn', 'Onları kendileri için boyun eğdirdik; işte bunlardan bir kısmı binekleri, bir kısmı da kendilerini yerler.'),
(36, 73, 23, 445, 'وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ', 'wa lahum fīhā manāfiʿu wa mashāribu ʾafalā yashkurūna', 'Onlar için (o hayvanlarda) hem (çeşitli) faydalar ve hem de içecekler (süt) vardır. Hâlâ şükretmiyorlar mı?'),
(36, 74, 23, 445, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ', 'wa-ttakhaḏū min dūni ʾllāhi ʾālihatan laʿallahum yunṣarūn', 'Onlar, kendilerine yardım edilmesi umuduyla Allah''tan başka tanrılar edindiler.'),
(36, 75, 23, 445, 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ', 'la yastaṭīʿūna naṣrahum wa hum lahum jundun muḥḍarūn', 'Onlara yardım etmeye güç yetiremezler ve onlar, kendileri için (o taptıkları şeylerin) hazır bir ordusu (veya hizmetçisi) durumundadırlar.'),
(36, 76, 23, 445, 'فَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'falā yaḥzunnuka qawluhum ʾinnā naʿlamu mā yusirrūna wa mā yuʿlinūn', 'Onların sözleri seni üzmesin. Şüphesiz biz, onların gizlediklerini de, açığa vurduklarını da bilmekteyiz.'),
(36, 77, 23, 445, 'أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', 'awalam yara al-insānu annā khalaqnāhu min nuṭfah fa-idhā huwa khaṣīmun mubīn', 'İnsan, kendisini bir nutfeden (spermden) yarattığımızı görmedi mi ki, hemen apaçık bir hasım kesildi?'),
(36, 78, 23, 445, 'وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌ', 'wa ḍaraba lanā mathalan wanasiya khalqahū qāla man yuḥyī l-ʿiẓāma wahiya ramīmun', 'Kendisi yaratılışı unutarak bize bir misal getirdi ve dedi ki: "Çürümüş kemikleri kim diriltecek?"'),
(36, 79, 23, 445, 'قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', 'Qul yuḥyīhā alladhī ʾanshaʾahā ʾawwala marrah Wa-huwa bikulli khalqin ʿalīm', 'De ki: Onları ilk defa yaratan diriltecektir. O, her şeyi hakkıyla bilendir.'),
(36, 80, 23, 445, 'ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ', 'alladhī jaʿala lakum mina sh-shajari l-akhḍari nāran fa-idhā antum minhu tūqidūn', 'O, yeşil ağaçtan sizin için bir ateş yaptı da siz ondan tutuşturuyorsunuz.'),
(36, 81, 23, 445, 'أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'E ve leyse ellezi halaka''s-semavati ve''l-arda bi kadirin ala en yahluka mislehum Bela Ve huve''l-hallaku''l-alim', 'Gökleri ve yeri yaratan, onların benzerini yaratmaya da kadir değil midir? Evet, O, her şeyi yaratan, hakkıyla bilendir.'),
(36, 82, 23, 445, 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ', 'innamā ʾamruhu ʾiḏā ʾarāda šayʾan ʾan yaqūla lahu ʾkun fayakūnu', 'Bir şeyi dilediği zaman, O''nun emri sadece: "Ol!" demektir. O da oluverir.'),
(36, 83, 23, 445, 'فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ', 'fasubḥāna lladhī biyadihi malakūtu kulli shayʾin wa إليه turjaʿūna', 'Her şeyin melekûtu (mülkü ve tasarrufu) kendi elinde bulunan ve O''na döndürülecek olan (Allah) ne yücedir!'),
(37, 1, 23, 446, 'وَٱلصَّٰٓفَّٰتِ صَفًّا', 'wa-ṣ-ṣāffāti ṣaffan', 'Saf bağlamış olanlara yemin olsun.'),
(37, 2, 23, 446, 'فَٱلزَّٰجِرَٰتِ زَجْرًا', 'fa-z-zācirāti zajrā', 'Yasaklayıp uyaranlara yemin olsun.'),
(37, 3, 23, 446, 'فَٱلتَّٰلِيَٰتِ ذِكْرًا', 'fa-l-tāliyati dhikran', 'O tertip üzere dizilenler ki, bir zikir (Kur''an) okurlar.'),
(37, 4, 23, 446, 'إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌ', 'inna ilāhakum lawāḥidun', 'Şüphesiz sizin ilahınız birdir.'),
(37, 5, 23, 446, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَٰرِقِ', 'rabbü-s-semāwāti ve-l-ʾarḍi ve-mā beynehumā ve-rabbü-l-meşāriqi', 'Göklerin, yerin ve ikisi arasında bulunanların Rabbi ve doğuların Rabbi.'),
(37, 6, 23, 446, 'إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ', 'ʾinnā zayyanā s-samāʾa d-dunyā bi-zīnatin l-kawākib', 'Doğrusu biz, en yakın göğü bir süsle, yıldızlarla süsledik.'),
(37, 7, 23, 446, 'وَحِفْظًا مِّن كُلِّ شَيْطَٰنٍ مَّارِدٍ', 'wa ḥifẓan min kulli shaiṭānin mārida', 'Ve onu her türlü azgın şeytandan bir koruma olarak (yarattık).'),
(37, 8, 23, 446, 'لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ', 'lā yassammaʿūna ilā l-malāʾi l-aʿlā wa yuqdhahūna min kulli jānibin', 'Onlar, (kendi) yüce topluluğu dinleyemezler ve her taraftan kovulurlar.'),
(37, 9, 23, 446, 'دُحُورًا وَلَهُمْ عَذَابٌ وَاصِبٌ', 'duḥūran wa lahum ʿadhābun wāṣibun', 'kovulmuş olarak ve onlara sürekli azap vardır.'),
(37, 10, 23, 446, 'إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌ ثَاقِبٌ', 'illa men khaṭifa l-khaṭfah fa-atbaʿahu shihābun thāqibun', 'Ancak kulak hırsızlığı yapanlar müstesna; peşlerini parlak bir ateş (şihab-ı sakıb) takip eder.'),
(37, 11, 23, 446, 'فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ إِنَّا خَلَقْنَٰهُم مِّن طِينٍ لَّازِبٍۭ', 'fastaftehim a-hum aşaddu khalqan am man khalqanā innā khalqnahum min ṭīnin lāzib', 'Şimdi onlara sor: Onlar mı daha zorlu yaratılışlı, yoksa bizim yarattığımız (diğer varlıklar) mı? Gerçekten biz onları yapışkan bir çamurdan yarattık.'),
(37, 12, 23, 446, 'بَلْ عَجِبْتَ وَيَسْخَرُونَ', 'bal ʿajibta wa yaskharūn', 'Hayır, sen onlara şaşırırsın da onlar alay ederler.'),
(37, 13, 23, 446, 'وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ', 'waʾiḏā ḏukkirū lā yaḏkurūn', 'Onlar hatırlatıldıkları zaman hatırlamazlar.'),
(37, 14, 23, 446, 'وَإِذَا رَأَوْا۟ ءَايَةً يَسْتَسْخِرُونَ', 'wa ʾiḏā raʾaw ʾāyatan yastasḫirūn', 'Onlar bir ayet (mucize) gördüklerinde birbirlerine alay ederler.'),
(37, 15, 23, 446, 'وَقَالُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'wa qālū in hāḏā illā siḥrum mubīn', 'Ve dediler ki: "Bu, apaçık bir sihirden başkası değildir."'),
(37, 16, 23, 446, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'ʾaʾidhā mitnā wa-kunnā turāban wa-ʿiẓāman ʾaʾinnanā la-mabʿūthūn', 'Gerçekten biz, kemikler haline gelip toprak olduğumuzda mı, biz mi yeniden diriltilecekmişiz?'),
(37, 17, 23, 446, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 'ʾawe ʾābāʾunā ʾel-ʾawwelūn', 'Yoksa ilk atalarımız mı?'),
(37, 18, 23, 446, 'قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ', 'qul naʿam wa ʾantum dākhirūn', 'De ki: Evet! Ve sizler horlanmaktasınız.'),
(37, 19, 23, 446, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ فَإِذَا هُمْ يَنظُرُونَ', 'Fa innama hiya zajratun wahidatun Fa idha hum yanzuruna', 'O halde, yalnızca tek bir çığlık! Hemen onların gözleri açılır.'),
(37, 20, 23, 446, 'وَقَالُوا۟ يَٰوَيْلَنَا هَٰذَا يَوْمُ ٱلدِّينِ', 'wa qālū yā waylanā hādhā yawmu d-dīni', 'Ve dediler ki: "Vay halimize! Bu, din günüdür!"'),
(37, 21, 23, 446, 'هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'hādhā yawmu l-faṣli l-ladhī kuntum bihī tukadhdhibūn', 'İşte bu, yalanlayıp durduğunuz o ayırma (hüküm) günüdür.'),
(37, 22, 23, 446, 'ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ', 'iḥshurū alladhīna ẓalamū waʾazwājahum wamā kānū yaʿbudūna', 'O zalimleri ve onların eşlerini ve taptıklarını bir araya getirin.'),
(37, 23, 23, 446, 'مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ', 'min dūni llāhi fa-hdūhum ilā ṣirāṭi l-jaḥīmi', 'Allah''tan başka (taptıklarınızdan) onları Cehennem''e giden yola iletin.'),
(37, 24, 23, 446, 'وَقِفُوهُمْ إِنَّهُم مَّسْـُٔولُونَ', 'waqifūhum innahum mas''ūlūn', 'Onları durdurun; çünkü onlar sorguya çekileceklerdir.'),
(37, 25, 23, 447, 'مَا لَكُمْ لَا تَنَاصَرُونَ', 'mā lakum lā tanāṣarūn', 'Size ne oluyor ki birbirinize yardım etmiyorsunuz?'),
(37, 26, 23, 447, 'بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ', 'bal humu l-yawma mustaslimūn', 'Hayır, onların hepsi o gün Allah''a teslim olmuşlardır.'),
(37, 27, 23, 447, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', 'wa-ʾaqbala baʿḍuhum ʿalā baʿḍin yatasāʾalūn', 'Ve birbirlerine dönüp soruşmaya başladılar.'),
(37, 28, 23, 447, 'قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ', 'qālū ʾinnakum kuntum taʾtūnanā ʿani l-yamīn', 'Dediler ki: "Siz bize sağ yanımızdan (bize gelip duruyordunuz)."'),
(37, 29, 23, 447, 'قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ', 'qālū bal lam takūnū muʾminīn', 'Onlar şöyle derler: "Hayır, siz zaten iman etmemiş idiniz."'),
(37, 30, 23, 447, 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍۭ بَلْ كُنتُمْ قَوْمًا طَٰغِينَ', 'wa mā kāna lanā ʿalaykum min sulṭānin bal kuntum qawman ṭāghīna', 'Oysa sizin üzerinizde bizim hiçbir gücümüz yoktu. Hayır, siz azgın bir kavimdiniz.'),
(37, 31, 23, 447, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ إِنَّا لَذَآئِقُونَ', 'faḥaqqa ʿalaynā qawlu rabbina ʾinnā laḏāʾiqūna', 'Böylece Rabbimizin şu sözü bizim hakkımızda gerçekleşmiş oldu: "Biz mutlaka azabı tadacağız."'),
(37, 32, 23, 447, 'فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ', 'faʾaġwaynākum ʾinnā kunnā ġāwīn', 'Böylece sizi azdırdık; çünkü biz azgın idik.'),
(37, 33, 23, 447, 'فَإِنَّهُمْ يَوْمَئِذٍ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 'fa-ʾinnahum yawmaʾiḏin fī l-ʿaḏābi muštarikūn', 'O gün onlar da azapta ortaklaşacaklardır.'),
(37, 34, 23, 447, 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 'innā kaḏālika nafʿalu bil-mujrimīn', 'Şüphesiz biz, suçlulara böyle yaparız.'),
(37, 35, 23, 447, 'إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ', 'innahum kānū idhā qīla lahum lā ilāha illā Allāh yastakbirūn', 'Onlar, kendilerine ''Allah''tan başka ilah yoktur'' denildiği zaman, büyüklük taslayanlardı.'),
(37, 36, 23, 447, 'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍ مَّجْنُونٍۭ', 'wa yaqūlūna ʾa-ʾinnanā la-tārikū ʾālihata-nā li-shāʿirin majnūnin', 'Ve derler ki: ''Biz, aklını yitirmiş bir şair yüzünden ilahlarımızı gerçekten terk mi edeceğiz?'''),
(37, 37, 23, 447, 'بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ', 'bal jāʾa bil-ḥaqqi wa ṣaddaqa l-murselīn', 'Hayır, o hak ile geldi ve o peygamberleri tasdik etti.'),
(37, 38, 23, 447, 'إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ', 'ʾinnakum laḏāʾiqū ʾl-ʿaḏāb ʾl-ʾalīm', 'Şüphesiz siz, o acı azabı tadacaksınız.'),
(37, 39, 23, 447, 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'Ve mā tujzawna illā mā kuntum taʿmalūn', 'Oysa siz ancak yapmakta olduklarınızla cezalandırılacaksınız.'),
(37, 40, 23, 447, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'illa ʿibāda llāhi l-mukhlaṣīna', 'Allah''ın halis kulları müstesna.'),
(37, 41, 23, 447, 'أُو۟لَٰٓئِكَ لَهُمْ رِزْقٌ مَّعْلُومٌ', 'ʾulāʾika lahum rizqun maʿlūmun', 'İşte onlar için bilinen bir rızık vardır.'),
(37, 42, 23, 447, 'فَوَٰكِهُ وَهُم مُّكْرَمُونَ', 'fawākihu wa hum mukramūna', 'Onların orada çeşit çeşit meyveleri ve kendileri için ikramlar vardır.'),
(37, 43, 23, 447, 'فِى جَنَّٰتِ ٱلنَّعِيمِ', 'fī jannāti n-naʿīmi', 'Onlar, Naîm cennetlerindedirler.'),
(37, 44, 23, 447, 'عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ', 'ʿalā sururin mutaqābilīn', 'Onlar, tahtlar üzerinde karşılıklı otururlar.'),
(37, 45, 23, 447, 'يُطَافُ عَلَيْهِم بِكَأْسٍ مِّن مَّعِينٍۭ', 'yuṭāfu ʿalayhim bikasi min maʿīn', 'Onların etrafında (doldurulmuş) kadehler dolaştırılır.'),
(37, 46, 23, 447, 'بَيْضَآءَ لَذَّةٍ لِّلشَّٰرِبِينَ', 'bayḍāʾa laḏḏatin liš-šāribīn', 'Beyaz, içenler için lezzet verici.'),
(37, 47, 23, 447, 'لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ', 'lā fīhā ġawlun wa lā hum ʿanhā yunzafūn', 'Orada ne bir kafa karışıklığı vardır, ne de onlar onunla sarhoş olurlar.'),
(37, 48, 23, 447, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ عِينٌ', 'wa ʿindahum qāṣirātu ṭ-ṭarfi ʿīn', 'Yanlarında bakışlarını eşlerine çevirmiş, iri gözlü hûriler vardır.'),
(37, 49, 23, 447, 'كَأَنَّهُنَّ بَيْضٌ مَّكْنُونٌ', 'kaʾannahunna bayḍun maknūn', 'Sanki onlar, saklanmış yumurtalar gibidir.'),
(37, 50, 23, 447, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', 'faʾaqbala baʿḍuhum ʿalā baʿḍin yatasāʾalūn', 'Bunun üzerine birbirlerine dönüp sorarlar.'),
(37, 51, 23, 447, 'قَالَ قَآئِلٌ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌ', 'qāla qāʾilun minhum innī kāna lī qarīnun', 'Onlardan biri şöyle der: "Benim bir yakınım vardı."'),
(37, 52, 23, 448, 'يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ', 'yaqūlu ʾaʾinnaka lamina l-muṣaddiqīn', 'Der ki: "Gerçekten sen, (bunları) doğrulayanlardan mısın?"'),
(37, 53, 23, 448, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ', 'ʾaʾiḏā mitnā wa-kunnā turāban wa-ʿiẓāman ʾaʾinnā la-madīnūn', 'Gerçekten biz, kemikler haline gelip toprağa karıştıktan sonra, gerçekten biz mi (diriltilip) ceza veya mükafat göreceğiz?'),
(37, 54, 23, 448, 'قَالَ هَلْ أَنتُم مُّطَّلِعُونَ', 'qāla hal ʾantum muṭṭaliʿūn', 'Der ki: "Hiç, siz (orada) görüp gözetenler misiniz?"'),
(37, 55, 23, 448, 'فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ', 'faṭṭalaʿa faraʾāhu fī sawāʾi l-jaḥīm', 'Böylece göz attı da onu tam cehennemin ortasında gördü.'),
(37, 56, 23, 448, 'قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ', 'qāla taḷḷāhi in kidta laturdinī', 'Dedi ki: "Allah''a yemin ederim ki, az kalsın beni helak edecektin!"'),
(37, 57, 23, 448, 'وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ', 'wa-lawlā niʿmatu rabbī lakuntu mina l-muḥḍarīn', 'Eğer Rabbimin nimeti olmasaydı, muhakkak ben de (o azap yerine getirilenlerden) حاضر kılınanlardan olurdum.'),
(37, 58, 23, 448, 'أَفَمَا نَحْنُ بِمَيِّتِينَ', 'afamā naḥnu bimayyinīn', 'Öyleyse biz ölecek miyiz?'),
(37, 59, 23, 448, 'إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ', 'illa mawtatana l-ūlā wa mā naḥnu bi-muʿaḏḏibīn', 'Ancak ilk ölümümüz mü? Ve biz azap olunacak değiliz.'),
(37, 60, 23, 448, 'إِنَّ هَٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'ʾinna hāḏā lahuwa l-fawzu l-ʿaẓīm', 'Şüphesiz bu, büyük bir kurtuluştur.'),
(37, 61, 23, 448, 'لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ٱلْعَٰمِلُونَ', 'li-mithli hādhā fal-yaʿmalil-ʿāmilūn', 'İşte bunun gibi bir şey için çalışıp çabalayanlar çalışıp çabalasınlar!'),
(37, 62, 23, 448, 'أَذَٰلِكَ خَيْرٌ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ', 'ʾaḏālika ḫayrun nuzulan ʾam šajaratu z-zaqqūmi', 'Bu mu daha hayırlı, yoksa Zakkum ağacı mı?'),
(37, 63, 23, 448, 'إِنَّا جَعَلْنَٰهَا فِتْنَةً لِّلظَّٰلِمِينَ', 'ʾinnā jaʿalnāhā fitnatan liẓ-ẓālimīn', 'Şüphesiz biz onu, zalimler için bir fitne (imtihan, azap sebebi) kıldık.'),
(37, 64, 23, 448, 'إِنَّهَا شَجَرَةٌ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ', 'ʾinnahā šajaratun taḫruju fī ʾaṣli l-ğaḥīm', 'Şüphesiz ki o, cehennemin dibinden çıkan bir ağaçtır.'),
(37, 65, 23, 448, 'طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ', 'ṭalʿuhā kaʾannehū ruʾūsu ʾš-šayāṭīn', 'Onların meyveleri sanki şeytanların başları gibidir.'),
(37, 66, 23, 448, 'فَإِنَّهُمْ لَءَاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 'faʾinnahum laʾākilūna minhā famāʾilūna minhā al-buṭūna', 'Onlar muhakkak ondan yiyeceklerdir. Ve onların karınları ondan dolacaktır.'),
(37, 67, 23, 448, 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيمٍ', 'thumma inna lahum ʿalayhā lashawban min ḥamīm', 'Sonra onların üzerine, ondan (kaynar sudan) bir içecek vardır.'),
(37, 68, 23, 448, 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ', 'thumma inna marji''ahum la''ila al-jahim', 'Sonra onların dönüşleri mutlaka cehennemedir.'),
(37, 69, 23, 448, 'إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ', 'innahum alfaw ʾābāʾahum ḍāllīn', 'Onlar, atalarını sapık bulmuşlardı.'),
(37, 70, 23, 448, 'فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ', 'fahum ʿalā āthārihim yuhraʿūn', 'Onlar, kendi atalarının izleri üzerinde (koşarak) ilerlerler.'),
(37, 71, 23, 448, 'وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ', 'Ve lekad dalle kablehum ekserul evvelîne', 'Andolsun ki onlardan önce, önceki nesillerin çoğu da sapmıştı.'),
(37, 72, 23, 448, 'وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ', 'Ve lekad erselnâ fîhim munzirîn', 'Andolsun ki, biz onların arasına uyarıcılar göndermiştik.'),
(37, 73, 23, 448, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 'fa-nẓur kayfa kāna ʿāqibatu l-munḏarīn', 'Artık uyarılmış olanların sonu nasıl olmuştur, bir bak!'),
(37, 74, 23, 448, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'illa ʿibāda llāhi l-mukhlaṣīn', 'Ancak Allah''ın seçkin kulları müstesna.'),
(37, 75, 23, 448, 'وَلَقَدْ نَادَىٰنَا نُوحٌ فَلَنِعْمَ ٱلْمُجِيبُونَ', 'Ve lekad nâdânâ Nûhun fe le ni''mel mucîbûn', 'Andolsun ki Nuh Bize seslenmişti de Biz ne güzel icabet edenleriz!'),
(37, 76, 23, 448, 'وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'wa-najjaynāhu wa-ahlahū mina l-karbi l-ʿaẓīm', 'Onu ve ailesini o büyük sıkıntıdan kurtardık.'),
(37, 77, 23, 449, 'وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ', 'wa jaʿalnā dhurriyyatahu humu l-bāqīn', 'Ve zürriyetini kendisini halef kıldık.'),
(37, 78, 23, 449, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 'wa taraknā ʿalayhi fī l-ʾākhirīn', 'Ve onu sonraki nesiller arasında (kalıcı bir şöhretle) bıraktık.'),
(37, 79, 23, 449, 'سَلَٰمٌ عَلَىٰ نُوحٍ فِى ٱلْعَٰلَمِينَ', 'Salāmun ʿalā Nūḥin fī l-ʿālamīn', 'Nuh''a âlemlerden bir selam!'),
(37, 80, 23, 449, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'innā kaḏālika najzī l-muḥsinīn', 'Şüphesiz biz, iyilik edenleri işte böyle mükafatlandırırız.'),
(37, 81, 23, 449, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'ʾinnahu min ʿibādinā ʾl-muʾminīn', 'Şüphesiz o, bizim mümin kullarımızdandı.'),
(37, 82, 23, 449, 'ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ', 'thumma aghraqnā l-ākhirīn', 'Sonra diğerlerini suda boğduk.'),
(37, 83, 23, 449, 'وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ', 'wa-inna min shīʿatihi la-ibrāhīm', 'Şüphesiz İbrahim de O''nun (din) yolundan gidenlerdendi.'),
(37, 84, 23, 449, 'إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍ سَلِيمٍ', 'iż jāʾa rabbahū bi-qalbin salīm', 'Hani o, Rabbine tertemiz bir kalple gelmişti.'),
(37, 85, 23, 449, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ', 'iż qāla li-ʾabīhi wa-qawmihi māḏā taʿbudūn', 'Hani o, babasına ve kavmine şöyle demişti: ''Siz neye tapıyorsunuz?'''),
(37, 86, 23, 449, 'أَئِفْكًا ءَالِهَةً دُونَ ٱللَّهِ تُرِيدُونَ', 'ʾaʾifkan ʾālihatā dūna ʾllāhi turīdūna', 'Allah''tan başka ilahlar mı demek istiyorsunuz?'),
(37, 87, 23, 449, 'فَمَا ظَنُّكُم بِرَبِّ ٱلْعَٰلَمِينَ', 'famā ẓannukum birabbi l-ʿālamīn', 'Âlemlerin Rabbi hakkında zannınız nedir?'),
(37, 88, 23, 449, 'فَنَظَرَ نَظْرَةً فِى ٱلنُّجُومِ', 'fanaẓara naẓratan fī n-nujūmi', 'Bunun üzerine bir kere yıldızlara baktı.'),
(37, 89, 23, 449, 'فَقَالَ إِنِّى سَقِيمٌ', 'faqāla innī saqīmun', 'Bunun üzerine şöyle dedi: "Ben hastayım."'),
(37, 90, 23, 449, 'فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ', 'fa tawallaw ʿanhu mudbirīn', 'Bunun üzerine onlar, arkalarını dönüp gittiler.'),
(37, 91, 23, 449, 'فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ', 'farāġa ʾilā ʾālihati-him fa-qāla ʾalā taʾkulūn', 'Bunun üzerine onların ilâhlarına yöneldi ve onlara şöyle dedi: "Yemez misiniz?"'),
(37, 92, 23, 449, 'مَا لَكُمْ لَا تَنطِقُونَ', 'mā lakum lā tanṭiqūn', 'Size ne oluyor da konuşmuyorsunuz?'),
(37, 93, 23, 449, 'فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ', 'farāġa ʿalayhim ḍarban bil-yamīn', 'Bunun üzerine onlara sağlarıyla vurdu.'),
(37, 94, 23, 449, 'فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ', 'faʾaqbalū ʾilayhi yaziffūna', 'Bunun üzerine ona doğru koşarak geldiler.'),
(37, 95, 23, 449, 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', 'qāla ʾaʿbudūna mā tanḥitūna', 'Dediler ki: "Siz mi, kendi yonttuklarınızı mı tapıyorsunuz?"'),
(37, 96, 23, 449, 'وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', 'wa-llāhu ḵalaqakum wa-mā taʿmalūn', 'Halbuki sizi de, yaptığınız şeyleri de Allah yarattı.'),
(37, 97, 23, 449, 'قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَٰنًا فَأَلْقُوهُ فِى ٱلْجَحِيمِ', 'qālū ibnū lahū bunyānan faʾalqūhu fī l-jaḥīmi', 'Dediler ki: "Onu bir bina içinde yakıp ateşe atın!"'),
(37, 98, 23, 449, 'فَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَسْفَلِينَ', 'faʾarādū bihi kaydan fajaʿalnāhumu l-ʾasfalīn', 'Böylece ona bir tuzak kurmak istediler. Ama onları aşağılanmışların en aşağısı kıldık.'),
(37, 99, 23, 449, 'وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ', 'waqāla innī ḏāhibun ʾilā rabbī sayahdīn', 'Ve dedi ki: "Ben Rabbime giden biriyim; O bana yol gösterecektir."'),
(37, 100, 23, 449, 'رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ', 'Rabbi hab li mineṣ-ṣāliḥīn', 'Rabbim! Bana salihlerden (bir evlat) ver.'),
(37, 101, 23, 449, 'فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍ', 'fabashsharnāhu bighulāmin ḥalīm', 'Böylece onu, halim bir oğul müjdesiyle müjdeledik.'),
(37, 102, 23, 449, 'فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ', 'fe-lemmā beleġa meʿahu-s-seʿye ḳāle yā-buneyye innī erā fi-l-menāmi ennī aẕbeḥuke fe-nẓur māẕā terā ḳāle yā-ebeti-fʿal mā tuʾmeru setecidunī in śāʾa-llāhu mine-ṣ-ṣābirīn', 'Onunla birlikte koşup yürümeye başlayınca dedi ki: "Yavrucuğum! Ben rüyamda seni kurban ettiğimi görüyorum. Bak, ne dersin?" Dedi ki: "Babacığım! Emrolunduğun şeyi yap. İnşallah beni sabredenlerden bulacaksın."'),
(37, 103, 23, 450, 'فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ', 'fe-lemmā eslemā ve telllehu lil-cebīn', 'İkisi de Allah''a teslim olup teslim olunca, onu alnı üzerine yatırdı.'),
(37, 104, 23, 450, 'وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ', 'wa-nādaynāhu ʾan yā ʾibrāhīmu', 'Ve onu şöyle çağırdık: "Ey İbrahim!"'),
(37, 105, 23, 450, 'قَدْ صَدَّقْتَ ٱلرُّءْيَآ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'qad ṣaddaqta r-ruʾyā ʾinnā kaḏālika najzī l-muḥsinīn', 'Gerçekten sen, rüyanın gereğini yerine getirdin. Şüphesiz biz, iyilik yapanları böyle mükafatlandırırız.'),
(37, 106, 23, 450, 'إِنَّ هَٰذَا لَهُوَ ٱلْبَلَٰٓؤُا۟ ٱلْمُبِينُ', 'ʾinna hāḏā lahuwa l-balāʾu l-mubīn', 'Şüphesiz bu, apaçık bir imtihandır.'),
(37, 107, 23, 450, 'وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍ', 'wa-fadaynāhu bi-dhiḥbin ʿaẓīm', 'Onu büyük bir kurbanlık fidye ile kurtardık.'),
(37, 108, 23, 450, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 'wa taraknā ʿalayhi fī l-ʾākhirīn', 'Onu (iyilikle) sonrakiler arasında (kalıcı bir miras) bıraktık.'),
(37, 109, 23, 450, 'سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ', 'salāmun ʿalā ʾibrāhīm', 'İbrahim''e selam!'),
(37, 110, 23, 450, 'كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'kadhalika najzi al-muhsinin', 'İşte böylece iyilik edenleri mükâfatlandırırız.'),
(37, 111, 23, 450, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'ʾinnahu min ʿibādinā al-muʾminīn', 'Şüphesiz o, bizim mümin kullarımızdandır.'),
(37, 112, 23, 450, 'وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّا مِّنَ ٱلصَّٰلِحِينَ', 'wa bashsharnāhu bi-ʾisḥāqa nabiyyan mina ṣ-ṣāliḥīn', 'Bunun üzerine ona, salihlerden bir peygamber olarak İshak''ı müjdeledik.'),
(37, 113, 23, 450, 'وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِّنَفْسِهِۦ مُبِينٌ', 'wa bārakna ʿalayhi wa ʿalā ʾisḥāqa wa min dhurriyyatihimā muḥsinun wa ẓālimun linafsihi mubīnun', 'Onu ve İshak''ı mübarek kıldık. Onların nesillerinden de hem iyilik yapan hem de kendi nefsine açıkça zulmeden kimseler vardı.'),
(37, 114, 23, 450, 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 'Ve lekad menennâ alâ Mûsâ ve Hârûn', 'Andolsun ki Musa''ya ve Harun''a lütufta bulunduk.'),
(37, 115, 23, 450, 'وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'wa-najjaynāhumā wa-qawmahumā mina l-karbi l-ʿaẓīm', 'Ve onları ve kavimlerini o büyük sıkıntıdan kurtardık.'),
(37, 116, 23, 450, 'وَنَصَرْنَٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 'wa naṣarnāhum fakānū humu l-ghālibīn', 'Ve onlara yardım ettik de, böylece üstün gelenler kendileri oldular.'),
(37, 117, 23, 450, 'وَءَاتَيْنَٰهُمَا ٱلْكِتَٰبَ ٱلْمُسْتَبِينَ', 'wa ʾātaynāhumā l-kitāba l-mustabīna', 'Ve onlara apaçık olan Kitab''ı verdik.'),
(37, 118, 23, 450, 'وَهَدَيْنَٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 'wa hadaynāhumā aṣ-ṣirāṭa al-mustaqīm', 'Ve onları dosdoğru yola ilettik.'),
(37, 119, 23, 450, 'وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْءَاخِرِينَ', 'wa taraknā ʿalayhimā fī l-ʾākhirīn', 'Ve ikisini de sonrakilerin arasında (hayırla anılacak şekilde) bıraktık.'),
(37, 120, 23, 450, 'سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 'salāmun ʿalā Mūsā wa Hārūn', 'Selâm Musa''ya ve Harun''a!'),
(37, 121, 23, 450, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'ʾinnā kaḏālika najzī l-muḥsinīn', 'Şüphesiz biz, iyilik yapanları işte böyle mükafatlandırırız.'),
(37, 122, 23, 450, 'إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'innahumā min ʿibādinā l-muʾminīn', 'Şüphesiz onlar, bizim iman etmiş kullarımızdandı.'),
(37, 123, 23, 450, 'وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ', 'wa ʾinna ʾilyāsa lami-na l-mursalin', 'Şüphesiz İlyas da peygamberlerdendi.'),
(37, 124, 23, 450, 'إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ', 'iḏ ḳāla li-ḳavmihī ʾalā tattaḳūn', 'Hani o, kavmine şöyle demişti: "Siz (Allah''tan) korkmaz mısınız?"'),
(37, 125, 23, 450, 'أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ', 'ʾatadʿūna baʿlan watadha rūnʾaḥsana l-ḵāli qīn', 'Siz Ba''l''e mi dua ediyorsunuz ve en iyi yaratıcıyı terk mi ediyorsunuz?'),
(37, 126, 23, 450, 'ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'Allāha rabbakum wa rabba ʾābāʾikumul-ʾawwalīn', 'Allah''tır sizin Rabbiniz ve ilk atalarınızın da Rabbidir.'),
(37, 127, 23, 451, 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', 'fa-kaḏḏabūhu fa-ʾinnahum la-muḥḍarūn', 'Böylece onu yalanladılar. Şüphesiz ki onlar, (azap için) mutlaka hazır bulundurulacaklardır.'),
(37, 128, 23, 451, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'illa ʿibāda llāhi l-mukhlaṣīn', 'Ancak Allah''ın seçkin kulları müstesna.'),
(37, 129, 23, 451, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 'wa taraknā ʿalayhi fī l-ʾākhirīna', 'Ve onu sonraki nesiller arasında bir (kalıntı) olarak bıraktık.'),
(37, 130, 23, 451, 'سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ', 'Salāmun ʿalā ʾİlyāsīn', 'Selam, İlyasin''e!'),
(37, 131, 23, 451, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'innā kaḏālika najzī l-muḥsinīn', 'Şüphesiz biz, iyilik edenleri işte böyle mükafatlandırırız.'),
(37, 132, 23, 451, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 'ʾinnahu min ʿibādinā ʾl-muʾminīn', 'Şüphesiz o, bizim mümin kullarımızdandı.'),
(37, 133, 23, 451, 'وَإِنَّ لُوطًا لَّمِنَ ٱلْمُرْسَلِينَ', 'wa-inna Lūṭan la-mina l-mursalin', 'Şüphesiz Lut da peygamberlerdendi.'),
(37, 134, 23, 451, 'إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 'idh najjaynāhu wa ahlihi ajmaʿīn', 'Hani onu ve ailesinin tamamını kurtarmıştık.'),
(37, 135, 23, 451, 'إِلَّا عَجُوزًا فِى ٱلْغَٰبِرِينَ', 'illa ʿajūzan fī l-ġābirīn', 'Ancak geride kalan yaşlı bir kadın hariç.'),
(37, 136, 23, 451, 'ثُمَّ دَمَّرْنَا ٱلْءَاخَرِينَ', 'thumma dammarnā l-ʾākhirīn', 'Sonra diğerlerini helak ettik.'),
(37, 137, 23, 451, 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', 'wa-ʾinnakum latamurru-na ʿalayhim muṣbiḥīna', 'Şüphesiz siz, sabahları onların yanından geçmektesiniz.'),
(37, 138, 23, 451, 'وَبِٱلَّيْلِ أَفَلَا تَعْقِلُونَ', 'wa bi-l-layli ʾafalā taʿqilūna', 'Ve geceleyin (de helak olmuş milletlerin hallerini görüp ibret almaz mısınız)? Akıl erdirmiyor musunuz?'),
(37, 139, 23, 451, 'وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ', 'waʾinna Yūnus la-mina l-mursalin', 'Ve şüphesiz Yunus da gönderilmişlerdendi.'),
(37, 140, 23, 451, 'إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ', 'idh abaq ilā l-fulki l-mashḥūn', 'Hani o, dolu bir gemiye kaçmıştı.'),
(37, 141, 23, 451, 'فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ', 'fasāhama fakāna mina l-mudḥaḍīn', 'Bunun üzerine kur''a çekti ve (gemideki yükü atmak için) neticede mahrum kalanlardan oldu.'),
(37, 142, 23, 451, 'فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌ', 'fa-ltqamahū l-ḥūtu wa-huwa mulīmun', 'Derken onu balık yuttu; o ise kınanmış idi.'),
(37, 143, 23, 451, 'فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ', 'falawlā annahu kāna mina l-musabbiḥīn', 'Eğer o, Allah''ı tesbih edenlerden olmasaydı'),
(37, 144, 23, 451, 'لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'lalabiṯa fī baṭnihi ʾilā yawmi yubʿaṯūn', 'Onun karnında, yeniden diriltilecekleri güne kadar kalırdı.'),
(37, 145, 23, 451, 'فَنَبَذْنَٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌ', 'fanabaḏnāhu bil-ʿarāʾi wa huwa saqīmun', 'Böylece onu ıssız bir yere atmışken o, hasta idi.'),
(37, 146, 23, 451, 'وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ', 'wa anbatnā ʿalayhi shajaratan min yaqṭīn', 'Onun üzerine kabak türünden bir ağaç bitirdik.'),
(37, 147, 23, 451, 'وَأَرْسَلْنَٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ', 'waʾarsalnāhu ʾilā miʾati ʾalfin ʾaw yazīdūn', 'Onu yüz bin veya daha fazla kişiye elçi olarak gönderdik.'),
(37, 148, 23, 451, 'فَـَٔامَنُوا۟ فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ', 'faʾāmanū famattaʿnāhum ʾilā ḥīnin', 'Böylece iman ettiler de onları belirli bir zamana kadar yaşattık.'),
(37, 149, 23, 451, 'فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ', 'fastaftehim ʾal-rabbika l-banātu wa-lahumu l-banūna', 'Şimdi onlara sor: Rablerine kızlar mı var da oğullar onlarındır?'),
(37, 150, 23, 451, 'أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًا وَهُمْ شَٰهِدُونَ', 'am ḵalaqnā l-malāʾikata ʾināṯan wa-hum šāhidūn', 'Yoksa biz melekleri dişi olarak yarattık da onlar şahit mi bulunuyorlardı?'),
(37, 151, 23, 451, 'أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ', 'ʾalā ʾinnahum min ʾifkihim layaqūlūn', 'Onlar, gerçekten yalan uydurarak şöyle derler:'),
(37, 152, 23, 451, 'وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'walada allāhu wa-innahum lakādhibūna', 'Allah çocuk edinmiştir" dedi. Şüphesiz onlar elbette yalancıdırlar.'),
(37, 153, 23, 451, 'أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ', 'aṣṭafā l-banāti ʿalā l-banīna', 'Yoksa O, oğullara karşı kızları mı seçti?'),
(37, 154, 23, 452, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'mā lakum kayfa taḥkumūn', 'Size ne oluyor, nasıl hükmediyorsunuz?'),
(37, 155, 23, 452, 'أَفَلَا تَذَكَّرُونَ', 'ʾafalā taḏakkarūn', 'Onlar hala ibret almayacaklar mı?'),
(37, 156, 23, 452, 'أَمْ لَكُمْ سُلْطَٰنٌ مُّبِينٌ', 'ʾam lakum sulṭānun mubīn', 'Yoksa size apaçık bir delil (yetki) mi vardı?'),
(37, 157, 23, 452, 'فَأْتُوا۟ بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'faʾtū bikitābi kum ʾin kuntum ṣādiqīn', 'Eğer doğru sözlüler idiyseniz, haydi kitabınızı getirin!'),
(37, 158, 23, 452, 'وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًا وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ', 'wa jaʿalū baynahū wa bayna l-jinnati nasabā wa laqad ʿalimat il-jinnatu ʾinnahum la-muḥḍarūn', 'Oysa onlar, (Allah ile) cinler arasında bir soy bağı uydurdular. Halbuki cinler de bilmektedir ki, şüphesiz onlar (bu iftirayı edenler) mutlaka (hesaba çekilmek üzere) getirileceklerdir.'),
(37, 159, 23, 452, 'سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'subḥāna llāhi ʿammā yaṣifūn', 'Allah, onların vasfettiklerinden münezzehtir.'),
(37, 160, 23, 452, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'illa ʿibāda llāhi l-mukhlaṣīn', 'Ancak Allah''ın seçkin kulları müstesna.'),
(37, 161, 23, 452, 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', 'fa-ʾinnakum wa-mā taʿbudūna', 'Şüphesiz siz ve taptıklarınız'),
(37, 162, 23, 452, 'مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ', 'mā antum ʿalayhi bifātinīn', 'Siz onun üzerinde (insanları) fitneye düşürecek değilsiniz.'),
(37, 163, 23, 452, 'إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ', 'illa men huve ṣāli al-jaḥīm', 'Ancak çılgın ateşin (azabına) girecek olan müstesna.'),
(37, 164, 23, 452, 'وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌ مَّعْلُومٌ', 'wa mā minnā illā lahū maqāmun maʿlūmun', 'Onlar (melekler) şöyle derler: "Hiçbirimiz yoktur ki onun (Allah''ın katında) bilinen bir makamı olmasın."'),
(37, 165, 23, 452, 'وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ', 'wa-ʾinnā la-naḥnu ʾaṣ-ṣāffūna', 'Ve şüphesiz biz, saf tutanlarız.'),
(37, 166, 23, 452, 'وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ', 'waʾinnā lanahnu l-musabbiḥūn', 'Ve şüphesiz biz, biz tesbih edenleriz.'),
(37, 167, 23, 452, 'وَإِن كَانُوا۟ لَيَقُولُونَ', 'wa-ʾinna kānū layuqūlūna', 'Ve eğer onlar şöyle diyorlardı:'),
(37, 168, 23, 452, 'لَوْ أَنَّ عِندَنَا ذِكْرًا مِّنَ ٱلْأَوَّلِينَ', 'law anna ʿindanā dhikran min al-ʾawwalīn', 'Eğer yanımızda öncekilerden bir öğüt olsaydı,'),
(37, 169, 23, 452, 'لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 'lekunnâ ''ibâda(A)llâhi-lmuḣlaśîn(e)', 'Elbette Allah’ın ihlaslı kulları olurduk.'),
(37, 170, 23, 452, 'فَكَفَرُوا۟ بِهِۦ فَسَوْفَ يَعْلَمُونَ', 'fa-kafarū bihi fa-sawfa yaʿlamūn', 'Böylece ona (Kur''an''a) kâfir oldular. Yakında (gerçeği) bilecekler.'),
(37, 171, 23, 452, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ', 'wa laqad sagaḇat kalimatu-nā li-ʿibādi-nā l-mursaliīn', 'Yemin olsun, gönderdiğimiz kullarımız hakkında sözümüz geçti.'),
(37, 172, 23, 452, 'إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ', 'ʾinnahum lahumu l-manṣūrūn', 'Şüphesiz onlar, galip gelecek olanlardır.'),
(37, 173, 23, 452, 'وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ', 'wa-ʾinna jun-danā lahumu l-ḡālibūn', 'Ve şüphesiz ki bizim ordumuz, elbette galip gelecek olanlar onlardır.'),
(37, 174, 23, 452, 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', 'fe-tevel-la ʿan-hum ḥattā ḥīn', 'Onlardan bir süreye kadar yüz çevir.'),
(37, 175, 23, 452, 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', 'wa-ʾabṣirhum fa-sawfa yubṣirūn', 'Onları gör; yakında onlar da görecekler.'),
(37, 176, 23, 452, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 'ʾafabiʿaḏābinā yastaʿǧilūn', 'Onlar azabımızı mı çarçabuk istiyorlar?'),
(37, 177, 23, 452, 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ', 'fa-iḏā nazala bisāḥatihim fasāʾa ṣabāḥu l-munḏarīn', 'Ne zaman ki onların yurduna inecek olursa, uyarılmış olanların sabahı ne kötü olur!'),
(37, 178, 23, 452, 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ', 'wa tawalla ʿanhum ḥattā ḥīn', 'Onlardan bir süreye kadar yüz çevir.'),
(37, 179, 23, 452, 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ', 'waʾabṣir fasawfa yubṣirūn', 'Ve (onlara) gör! Yakında onlar da görecekler.'),
(37, 180, 23, 452, 'سُبْحَٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ', 'subḥāna rabbika rabbi l-ʿizzati ʿammā yaṣifūn', 'Rabbin, yücelik sahibi Rabbin, onların vasfettiklerinden uzaktır.'),
(37, 181, 23, 452, 'وَسَلَٰمٌ عَلَى ٱلْمُرْسَلِينَ', 'wa salāmun ʿalā l-mur''salīn', 'Selam, gönderilmiş olan peygamberleredir.'),
(37, 182, 23, 452, 'وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'wa-l-ḥamdu li-llāhi rabbi l-ʿālamīn', 'Hamd, âlemlerin Rabbi Allah''a mahsustur.'),
(38, 1, 23, 453, 'صٓ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ', 'Sâd Ve''l-kur''āni zi''z-zikr', 'Sâd. Bu öğüt dolu Kur''an''a andolsun.'),
(38, 2, 23, 453, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى عِزَّةٍ وَشِقَاقٍ', 'balil-ladhīna kafarū fī ʿizzatin wa-shiqāq', 'Hayır, o küfredenler bir gurur ve bir ayrılık içindedirler.'),
(38, 3, 23, 453, 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍ', 'Kam ahleknā min qablihim min qarnin Fanādaw Wa lāta ḥīna manāṣin', 'Onlardan önce nice nesilleri helak ettik. (Helak ettiğimiz o kavimler) imdat diye bağırdılar, ama artık kurtuluş zamanı değildi.'),
(38, 4, 23, 453, 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ ٱلْكَٰفِرُونَ هَٰذَا سَٰحِرٌ كَذَّابٌ', 'wa ʿajībū ʾan jāʾahum munḏirun minhum wa qāla l-kāfirūna hāḏā sāḥirun kaḏḏābun', 'Onlar, kendilerinden bir uyarıcının gelmesine şaştılar ve kâfirler: ''Bu, büyücü, yalancıdır'' dediler.'),
(38, 5, 23, 453, 'أَجَعَلَ ٱلْءَالِهَةَ إِلَٰهًا وَٰحِدًا إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌ', 'a- ja''ala l-ālihata ilāhan wāḥidan inna hādhā la-shay''un ''ujābun', 'Putu tek bir ilah mı yaptı? Gerçekten bu, şaşılacak bir şeydir.'),
(38, 6, 23, 453, 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ إِنَّ هَٰذَا لَشَىْءٌ يُرَادُ', 'wa-nṭalaqa l-malaʾu minhum ani ʾimšū wa-ṣbirū ʿalā ʾālihati-kum ʾinna hāḏā la-šayʾun yurādu', 'Onlardan ileri gelenler şöyle diyerek yola koyuldular: "Haydi gidin, tanrılarınıza bağlı kalmaya devam edin! Şüphesiz bu, (yapılmakta) istenen bir şeydir."'),
(38, 7, 23, 453, 'مَا سَمِعْنَا بِهَٰذَا فِى ٱلْمِلَّةِ ٱلْءَاخِرَةِ إِنْ هَٰذَآ إِلَّا ٱخْتِلَٰقٌ', 'mā samiʿnā bihādhā fī l-millati l-ʾākhirati in hādhā illā ḵtilāqun', 'Biz bu (Kur''an)yı önceki millet(ler)de duymadık. Bu, (eski masallardan) başka bir şey değildir. Bu, düpedüz uydurmadır.'),
(38, 8, 23, 453, 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', 'a''unzila ''alayhi dh-dhikru min baynina bal hum fi shakkim min dhikri bal lamma yadhuqu ''adhabi', 'Kur''an, aramızdan ona mı indirildi? Hayır, onlar benim uyarımı/Kur''an''ımı tatmadılar/denemediler. Daha doğrusu onlar benim azabımı tatmadılar.'),
(38, 9, 23, 453, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', 'ʾam ʿindahum ḫazāʾinu raḥmati rabbika l-ʿazīzi l-wahhābi', 'Yoksa, aziz ve Vehhab olan Rabb''inin hazineleri onların yanına mı?'),
(38, 10, 23, 453, 'أَمْ لَهُم مُّلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَٰبِ', 'am lahum mulku s-semāwāti wa-l-arḍi wa mā baynahumā fa-l-yartaqū fī l-asbāb', 'Yoksa onların, göklerin ve yerin ve ikisinin arasında bulunanların mülkiyeti mi var? Öyleyse (bu iddialarını ispatlamak için) o sebeplere tırmansınlar!'),
(38, 11, 23, 453, 'جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ ٱلْأَحْزَابِ', 'jundun mā hunālika mahzūmun mina l-ʾaḥzāb', 'Orada, topluluklardan bir bölük, bozguna uğramış bir ordudur.'),
(38, 12, 23, 453, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', 'kadhdhabat qablahum qawmu nūḥin wa ʿādin wa firʿawnu dhū l-ʾawtādi', 'Onlardan önce Nuh''un kavmi, Âd kavmi ve kazıklar sahibi Firavun da yalanlamıştı.'),
(38, 13, 23, 453, 'وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَٰبُ لْـَٔيْكَةِ أُو۟لَٰٓئِكَ ٱلْأَحْزَابُ', 'wa-thamūdu wa-qawmu lūṭin wa-aṣḥābu l-ʾaykati ʾulāʾika l-ʾaḥzābu', 'Semûd, Lût kavmi ve Eyke halkı da (böyleydi). İşte onlar, (peygamberlere karşı) birleşen topluluklardır.'),
(38, 14, 23, 453, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', 'in kullun illā kadhdhaba ar-rusula faḥaqqa ʿiqāb', 'Onlardan her biri peygamberleri yalanladı da azabım böylece gerçekleşti.'),
(38, 15, 23, 453, 'وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ', 'wa mā yanẓuru hāʾulāʾi illā ṣaiḥatan wāḥidatan mā lahā min fawāq', 'Bunlar, (kıyametin kopmasını) bir tek sayhadan başkasını beklemiyorlar; ki o, bir an bile durup dinlenmesi olmayacak bir sayhadır.'),
(38, 16, 23, 453, 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', 'wa qālū rabbanā ʿajjil lanā qiṭṭanā qabla yawmi l-ḥisāb', 'Onlar şöyle dediler: "Rabbimiz! Hesap gününden önce bize (azabımızdan) payımızı çabuk ver!"'),
(38, 17, 23, 454, 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ إِنَّهُۥٓ أَوَّابٌ', 'iṣbir ʿalā mā yaqūlūn wādhkur ʿabdanā Dāwūda dhā l-ʾayd ʾinnahu ʾawwāb', 'Onların söylediklerine sabret ve kulumuz Davud''u hatırla. O, (bize) yönelip-dönen biriydi.'),
(38, 18, 23, 454, 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', 'innā sakhkharnā al-jibāla maʿahu yusabbiḥna bil-ʿashiyyi wal-ishrāqi', 'Şüphesiz biz, dağları onunla birlikte (emrimize) amade kıldık; akşam sabah tesbih ederlerdi.'),
(38, 19, 23, 454, 'وَٱلطَّيْرَ مَحْشُورَةً كُلٌّ لَّهُۥٓ أَوَّابٌ', 'wa-ṭ-ṭayra maḥshūratan kullun lahū ʾawwābun', 'Kuşları da toplanmış bir halde (onun emrine verdik). Hepsi ona yönelip-dönenlerdi.'),
(38, 20, 23, 454, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', 'wa shaddadna mulkahū wa ātaynāhu l-ḥikmata wa faṣla l-khiṭābi', 'Onun mülkünü güçlendirmiştik ve ona hikmet ve (hak ile batılı) ayıran bir anlayış vermiştik.'),
(38, 21, 23, 454, 'وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', 'wa hal atāka nabaʾu l-khaṣmi iḏ tasawwarū l-miḥrāba', 'Sana o hasmın haberi geldi mi? Hani onlar duvarı aşıp mihraba çıkmışlardı.'),
(38, 22, 23, 454, 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ قَالُوا۟ لَا تَخَفْ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', 'idh daxalū ʿalā Dāwūda fafaziʿa minhum qālū lā takhaf khaṣmāni baghā baʿḍunā ʿalā baʿḍin fa-ḥkum baynanā bil-ḥaqqi wa-lā tushṭiṭ wa-hdinā ilā sawāʾi ṣ-ṣirāṭi', 'Onlar Davud''un yanına girdiklerinde, onlardan irkilmişti. "Korkma!" dediler. "Biz birbirine düşmüş iki davacıyız. Aleyhimize hükmetme, bizi doğru yola ilet.'),
(38, 23, 23, 454, 'إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', 'ʾinna hāḏā ʾaxī lahū tisʿun wa-tisʿūna naʿjatan wa-lī naʿjatun wāḥidatun fa-qāla ʾakfilnīhā wa-ʿazzanī fī l-ḵiṭāb', 'Şüphesiz bu benim kardeşimdir; onun doksandokuz dişi (koyunu) var, benim ise bir dişi (koyunum) var. "Bunu bana ver" dedi ve konuşmada bana üstün geldi.'),
(38, 24, 23, 454, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ وَإِنَّ كَثِيرًا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌ مَّا هُمْ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ', 'qāla laqad ẓalamaka bisuʾāli naʿjatika ilā niʿājihi waʾinna kathīran mina l-khulṭāʾi layabghī baʿḍuhum ʿalā baʿḍin illā lladhīna ʾāmanū waʿamilū ṣ-ṣāliḥāti waqalīlun mā hum waẓanna Dāwūdu ʾannama fatannāhu fastaghfara rabbahū wa kharra rākiʿan wa ʾanāba', 'O şöyle dedi: "Andolsun ki, senin koyununu kendi koyunlarına katmakla o sana zulmetmiştir. Zaten (ortaklardan) çoğu birbirine karşı tecavüzkârlık eder. Ancak iman edip salih amel işleyenler başka. Bunlar da ne kadar az! Davud, bizim kendisini bu suretle imtihan ettiğimizi anladı. Bunun üzerine Rabbinden mağfiret diledi, (ve) secdeye kapandı ve (bize) yöneldi."'),
(38, 25, 23, 454, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', 'faġafarnā lahū ḏālika wa-inna lahū ʿindanā lazulfā wa-ḥusna maʾābin', 'Böylece biz ona bu kusurunu bağışladık. Gerçekten onun bizim katımızda yakınlığı ve güzel bir akıbeti vardır.'),
(38, 26, 23, 454, 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةً فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', 'Yā Dāwūdu innā jaʿalnāka ḵalīfatan fī l-ʾarḍi Faḥkum bayna n-nāsi bil-ḥaqqi Wa lā tattabiʿi l-hawā Fayuḍillaka ʿan sabīli llāhi ʾInna lladhīna yaḍillūna ʿan sabīli llāhi Lahum ʿadhābun shadīdun bimā nasū yawma l-ḥisābi', 'Ey Davud! Biz seni yeryüzünde bir halife kıldık. Onun için insanlar arasında hak ile hükmet. Heva''ya uyma, yoksa seni Allah''ın yolundan saptırır. Şüphesiz Allah''ın yolundan sapanlar için, hesap günü unutmalarından dolayı şiddetli bir azap vardır.'),
(38, 27, 23, 455, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًا ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', 'wa mā khalaqnā as-samāʾa wal-arḍa wa mā baynahumā bāṭilā dhālika ẓannu lladhīna kafarū fa-waylun lilladhīna kafarū mina n-nār', 'Biz göğü ve yeri ve ikisinin arasındakileri boşuna yaratmadık. Bu, küfredenlerin zannıdır. Artık küfredenlerin vay haline ateşten!'),
(38, 28, 23, 455, 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', 'ʾam najʿalu lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti kal-mufsidīna fī l-ʾarḍi ʾam najʿalu l-muttaqīna kal-fujjāri', 'Yoksa iman edip salih amel işleyenleri yeryüzünde fesat çıkaranlar gibi mi tutacağız? Yahut takva sahiplerini, facirler (kötülük yapanlar) gibi mi tutacağız?'),
(38, 29, 23, 455, 'كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'kitābun ʾanzalnāhu ʾilayka mubārakun liyaddeberū ʾāyātihi wa liyatadhakkara ʾulū ʾel-ʾelbābi', 'Bu, sana indirdiğimiz mübarek bir kitaptır ki, âyetlerini düşünsünler ve aklı olanlar ibret alsın.'),
(38, 30, 23, 455, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ نِعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'wa wahabnā li-Dāwūda Sulaymāna niʿma l-ʿabdu ʾinnahu ʾawwābun', 'Böylece biz de Dâvûd''a Süleyman''ı bahşettik. O ne güzel kuldu! Daima Allah''a yönelirdi.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(38, 31, 23, 455, 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ', 'iż ʿuriḍa ʿalayhi bi-l-ʿashiyyi ṣ-ṣāfinātu l-jiyādu', 'Hani ona bir akşamüstü, alımlı, durmuş, (koşmaya hazır) cins atlar sunulmuştu.'),
(38, 32, 23, 455, 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', 'faqāla innī ʾaḥbabtu ḥubba l-khayri ʿan dhikri rabbī ḥattā tawārat bi-l-ḥijāb', 'Bunun üzerine şöyle dedi: "Ben, mal sevgisini, Rabbimi anmaktan (dolayı tercih ettim). Nihayet güneş perde arkasına gizlendi."'),
(38, 33, 23, 455, 'رُدُّوهَا عَلَىَّ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', 'rudduhā ʿalayye faṭafiq a masḥan bis-sūqi wal-aʿnāq', 'Onları bana geri getirin! deyip bacak ve boyunlarını sıvazlamaya başladı.'),
(38, 34, 23, 455, 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ', 'Ve lekad fetennâ Suleymâne ve elkaynâ alâ kursiyyihi ceseden summe enâbe', 'Andolsun, Süleyman''ı imtihan ettik ve tahtının üzerine bir ceset bıraktık. Sonra o, (bize) yöneldi.'),
(38, 35, 23, 455, 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'qāla rabbi ʾighfir lī waheb lī mulkan lā yanbaġī li-ʾaḥadin min baʿdī ʾinnaka ʾanta l-wahhābu', 'Dedi ki: Rabbim! Beni bağışla ve bana, benden sonra kimseye yaraşmayacak bir mülk (hükümranlık) ver. Şüphesiz sen, daima ihsan edensin.'),
(38, 36, 23, 455, 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', 'fasakhkharnā lahu ar-rīḥa tajrī bi-amrihi rukhāʾan ḥaythu aṣāb', 'Bunun üzerine rüzgârı ona boyun eğdirdik; onun emriyle dilediği yere kolayca eserdi.'),
(38, 37, 23, 455, 'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ', 'wa-sh-shayāṭīna kulla bannāʾin wa-ghawwāṣin', 'Ve şeytanları da; her bir yapı ustası ve dalgıç olanları da.'),
(38, 38, 23, 455, 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'wa ʾākhirīna muqarranīna fī l-ʾaṣfādi', 'Ve diğerlerini de zincirler içinde birbirine bağlanmış (olarak verdik).'),
(38, 39, 23, 455, 'هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ', 'hādhā ʿaṭāʾunā fāmnun ʾaw ʾamsik bighayri ḥisābin', 'İşte bu, bizim ihsanımızdır; (onun için) sen hem ver hem de tut, (hesap sorulmaz).'),
(38, 40, 23, 455, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', 'wa-ʾinna lahu ʿindanā lazulfā wa-ḥusna maʾāb', 'Şüphesiz onun için katımızda bir yakınlık ve güzel bir akıbet vardır.'),
(38, 41, 23, 455, 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍ وَعَذَابٍ', 'wa-dhkur ʿabdanā ʾayyūba ʾidh nādā rabbahū ʾannī massaniya ʾš-šayṭānu bi-nuṣbin wa-ʿaḏābin', 'Kulumuz Eyyûb''u da hatırla. Hani o Rabbine, "Şüphesiz şeytan bana bir yorgunluk ve azap dokundurdu" diye niyaz etmişti.'),
(38, 42, 23, 455, 'ٱرْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌۢ بَارِدٌ وَشَرَابٌ', 'urkuḍ bi-riclik hādhā muġtasalun bāridun wa-sharāb', 'Ayağını yere vur! İşte bu, yıkanılacak ve içilecek serin bir su!'),
(38, 43, 23, 456, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'wa wahabnā lahu ʾahlahu wa mithlahum maʿahum raḥmatan minnā wa dhikrā liʾulī al-ʾalbāb', 'Ve ona ailesini ve onlarla birlikte bir mislini, tarafımızdan bir rahmet ve akıl sahipleri için bir öğüt olmak üzere bağışladık.'),
(38, 44, 23, 456, 'وَخُذْ بِيَدِكَ ضِغْثًا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ إِنَّا وَجَدْنَٰهُ صَابِرًا نِّعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'wa-khudh bi-yadika ḍighthan fa-ḍrib bihi wa-lā taḥnath ʾinnā wajadnāhu ṣābiran niʿma l-ʿabdu ʾinnahu ʾawwābun', 'Ve eline bir demet al da onunla vur; yeminini bozma. Şüphesiz biz onu sabredici bulduk. O ne güzel kul! O, (bize) yönelen (bir kul) idi.'),
(38, 45, 23, 456, 'وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ', 'wa-dhkur ʿibādanā ʾibrāhīma wa-ʾisḥāqa wa-yaʿqūba ʾulī l-ʾaydī wa-l-ʾabṣār', 'Kullarımız İbrahim, İshak ve Yakub''u hatırla. Onlar kuvvetli kullardı, basiret sahipleriydi.'),
(38, 46, 23, 456, 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍ ذِكْرَى ٱلدَّارِ', 'ʾinna-ʾā ʾakhlaṣnā-hum bi-khāliṣatin dhikrā ʾd-dāri', 'Onları, ahiret yurdunu hatırlama gibi halis bir özellikle ayırdık.'),
(38, 47, 23, 456, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', 'waʾinnakum ʿindanā lama min al-muṣṭafayna al-ʾaḫyār', 'Şüphesiz onlar bizim katımızda seçkinlerden ve iyilerden olmakla birlikte gerçekten de öylelerdir.'),
(38, 48, 23, 456, 'وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ وَكُلٌّ مِّنَ ٱلْأَخْيَارِ', 'wa-dhkur Ismāʿīla wa-l-Yasaʿa wa-dhā l-Kifli wa-kullun mina l-ʾakhyāri', 'İsmail''i, Elyesa''yı ve Zülkifl''i de an. Hepsi de iyilerdendi.'),
(38, 49, 23, 456, 'هَٰذَا ذِكْرٌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍ', 'hādhā dhikrun wa-inna lil-muttaqīna laḥusna maʾābin', 'İşte bu bir öğüttür. Ve şüphesiz takva sahipleri için elbette çok güzel bir dönüş yeri vardır.'),
(38, 50, 23, 456, 'جَنَّٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ ٱلْأَبْوَٰبُ', 'jannāti ʿadnin mufattaḥatan lahumu l-ʾabwābu', 'Adn cennetleri; onlar için kapıları açıktır.'),
(38, 51, 23, 456, 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ', 'muttaqi''īna fīhā yad''ūna fīhā bifākihah kathīrah wašarāb', 'Onlar orada, tahtlara yaslanmışlardır. Orada bol meyve ve şarap isterler.'),
(38, 52, 23, 456, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', 'wa ʿindaha qāṣirātu ṭ-ṭarfi ʾatrāb', 'Ve onların yanında, bakışlarını eşlerine çevirmiş, yaşları bir olanlar vardır.'),
(38, 53, 23, 456, 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', 'hādhā mā tūʿadūna liyawmi l-ḥisāb', 'İşte bu, hesap günü için size vaadedilen şeydir.'),
(38, 54, 23, 456, 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', 'ʾinna hāḏā la-ruznunā mā lahū min nafād', 'Şüphesiz bu, katımızdan verilmiş rızkımızdır; asla tükenmez.'),
(38, 55, 23, 456, 'هَٰذَا وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍ', 'hādhā wa-inna liṭ-ṭāghīna la-sharra maʾāb', 'İşte bu! Ve şüphesiz azgınlar için gerçekten kötü bir dönüş yeri vardır.'),
(38, 56, 23, 456, 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', 'jahannama yaṣlawnahā fa-biʾsa l-mihādu', 'Cehennem! Orada yanacaklar. Ne kötü bir barınaktır!'),
(38, 57, 23, 456, 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ', 'hādhā falyadhūqūhu ḥamīmun wa ghassāq', 'İşte bu! Artık tadın onu; kaynar su ve irin!'),
(38, 58, 23, 456, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', 'wa ʾākhara min shaklihī ʾazwāj', 'Ve onun benzerinden başka azaplar da vardır.'),
(38, 59, 23, 456, 'هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ لَا مَرْحَبًۢا بِهِمْ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', 'hādhā fawjun muqtahimun maʿakum lā marḥaban bihim ʾinnahum ṣālū ʾn-nār', 'İşte bu, sizinle birlikte cehenneme girecek bir bölüktür. Onlara rahat bir hayat yoktur! Çünkü onlar ateşe gireceklerdir.'),
(38, 60, 23, 456, 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ أَنتُمْ قَدَّمْتُمُوهُ لَنَا فَبِئْسَ ٱلْقَرَارُ', 'qālū bal ʾantum lā marḥaban bikum ʾantum qaddamtumūhu lanā fabiʾsa l-qarāru', 'Onlar şöyle derler: "Hayır! Sizi kimse buyur etmesin! Bu azabı siz mi bize hazırladınız?" Ne kötü bir barınaktır bu!'),
(38, 61, 23, 456, 'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِى ٱلنَّارِ', 'qālū rabbanā man qaddama lanā hāḏā fazidhu ʿaḏāban ḍiʿfan fī n-nāri', 'Dediler ki: Rabbimiz! Bunu (bu azabı) bize kim hazırladıysa, ona ateşin içinde kat kat azap artır!'),
(38, 62, 23, 457, 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', 'wa qālū mā lanā lā narā rijālan kunnā naʿudduhum mina l-ashrāri', 'Dediler ki: ''Dünyada kendilerini kötülerden saydığımız (veya kötülerden sayıp azap edeceğimizi) adamları niçin burada göremiyoruz?'''),
(38, 63, 23, 457, 'أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ', 'ʾattakhaḏnāhum siḵriyyan ʾam zāḡat ʿanhumu l-ʾabṣāru', 'Onları alay konusu mu edindik, yoksa gözlerimiz mi onlardan kayboldu?'),
(38, 64, 23, 457, 'إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ ٱلنَّارِ', 'ʾinna ḏālika laḥaqqun taḫāṣumu ʾahli n-nāri', 'İşte bu, gerçekten cehennem ehlinin (birbiriyle) çekişmesi gerçeğidir.'),
(38, 65, 23, 457, 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'Qul innama anā mundhirun Wa mā min ilāhin illā Allāhu l-Wāḥidu l-Qahhāru', 'De ki: "Ben ancak bir uyarıcıyım. Allah''tan başka hiçbir ilah yoktur; O, Vahid''dir, Kahhâr''dır."'),
(38, 66, 23, 457, 'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'rabbus-semāwāti wal-arḍi wa mā baynahumal-ʿazīzul-ġaffār', 'Göklerin, yerin ve ikisi arasında bulunanların Rabbi, O, Azîz, Gafûr''dur.'),
(38, 67, 23, 457, 'قُلْ هُوَ نَبَؤٌا۟ عَظِيمٌ', 'qul huwa nabaʾun ʿaẓīm', 'De ki: "O, büyük bir haberdir."'),
(38, 68, 23, 457, 'أَنتُمْ عَنْهُ مُعْرِضُونَ', 'ʾantum ʿanhu muʿriḍūn', 'Siz ondan yüz çevirenlersiniz.'),
(38, 69, 23, 457, 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', 'Mā kāna lī min ʿilmin bil-malʾi l-ʾaʿlā ʾiḏ yaḵtaṣimūn', 'Ben, (meleklerin) tartıştıkları zaman, yüce topluluk hakkında bir bilgim yoktu.'),
(38, 70, 23, 457, 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'in yūḥā ilayya illā annamā anā naẓīrun mubīn', 'Bana ancak, ''Ben apaçık bir uyarıcıyım'' diye vahyolunuyor.'),
(38, 71, 23, 457, 'إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن طِينٍ', 'iż qāla rabbuka lil-malāʾikati ʾinnī khāliqum basharan min ṭīnin', 'Hani Rabbin meleklere şöyle demişti: "Ben çamurdan bir insan yaratacağım."'),
(38, 72, 23, 457, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'fa-idhā sawwaytuhu wa-nafakhtu fīhi min rūḥī fa-qaʿū lahu sājidīn', 'Onu bir biçime sokup ruhumdan üflediğimde, hemen ona secde ederek yere kapanın!'),
(38, 73, 23, 457, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 'fasajadal-malāʾikatu kulluhum ajmaʿūn', 'Bunun üzerine meleklerin hepsi topluca secde ettiler.'),
(38, 74, 23, 457, 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 'illa iblīsa istakbara wa-kāna mina l-kāfirīn', 'Ancak İblis hariç! O, büyüklük taslamış ve kâfirlerden olmuştu.'),
(38, 75, 23, 457, 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', 'qāla yā iblīsu mā manaʿaka an tasjuda limā khalaqtu biyadayya astakbarta am kunta mina l-ʿālīn', 'İblis dedi ki: "Sana ellerimle yarattığıma secde etmekten ne alıkoydu? İstek mi duydun, yoksa yücelerden mi oldun?"'),
(38, 76, 23, 457, 'قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', 'qāla ʾanā ḫayrum-minhu ḫalaqtani min nārin wa ḫalaqta-hū min ṭīnin', 'O, "Ben ondan daha hayırlıyım. Beni ateşten yarattın, onu ise çamurdan yarattın" dedi.'),
(38, 77, 23, 457, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', 'qāla fa-ʾkhruj minhā fa-ʾinnaka rajīm', 'Allah şöyle buyurdu: "Çık oradan! Çünkü sen kovulmuş birisin."'),
(38, 78, 23, 457, 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', 'waʾinna ʿalayka laʿnatī ʾilā yawmi d-dīn', 'Ve şüphesiz ki, lânetim kıyamet gününe kadar senin üzerinedir.'),
(38, 79, 23, 457, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'qāla rabbi faʾanẓirnī ʾilā yawmi yubʿathūn', 'Dedi ki: Rabbim! Öyleyse (insanların) tekrar diriltilecekleri güne kadar bana mühlet ver.'),
(38, 80, 23, 457, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 'qāla faʾinnaka mina l-munẓarīn', 'Allah şöyle buyurdu: "Sen, (azap edilmekten) geciktirilenlerdensin."'),
(38, 81, 23, 457, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'ilā yawmi l-waqti l-maʿlūmi', 'Belli bir vakte kadar.'),
(38, 82, 23, 457, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'qāla fabiʿizzatika laʾughwiyannahum ʾajmaʿīn', 'Dedi ki: "Senin izzetine yemin ederim ki, onların hepsini mutlaka saptıracağım."'),
(38, 83, 23, 457, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 'illa ʿibādaka minhumu l-mukhlaṣīn', 'Ancak onlardan ihlasa erdirilmiş kulların müstesna.'),
(38, 84, 23, 458, 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', 'qāla fa-l-ḥaqqu wa-l-ḥaqqa ʾaqūlu', 'Allah şöyle buyurdu: "Gerçek benim ve gerçeği söylüyorum."'),
(38, 85, 23, 458, 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', 'leʾemleʾenne cehenneme minke ve mimmen tebiʿake minhum ecmeʿīne', 'Andolsun ki cehennemi senden ve onlardan sana uyanların hepsiyle dolduracağım.'),
(38, 86, 23, 458, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', 'qul mā ʾasʾalukum ʿalayhi min ʾajrin wa mā ʾanā mina l-mutakallifīn', 'De ki: "Buna karşılık sizden bir ücret istemiyorum. Ben teklif edici (veya yapmacık davranan) kimselerden değilim."'),
(38, 87, 23, 458, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'ʾin huwe ʾillā ḏikrun lil-ʿālamīn', 'O (Kur''an), âlemler için yalnızca bir öğüttür.'),
(38, 88, 23, 458, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', 'wa lataclamunna naba''ahu ba''da ḥīn', 'Ve elbette siz onun haberini bir zaman sonra bileceksiniz.'),
(39, 1, 23, 458, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'Tanzīlu l-kitābi mina llāhi l-ʿazīzi l-ḥakīm', 'Bu Kitabın indirilmesi, mutlak güç sahibi, hüküm ve hikmet sahibi Allah''tandır.'),
(39, 2, 23, 458, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', 'ʾinnā ʾanzalnā ʾilayka l-kitāba bil-ḥaqqi fa-ʿbud ʾllāha mukhliṣan lahū d-dīna', 'Şüphesiz biz Kitab''ı sana hak olarak indirdik. Onun için sen de Allah''a, dini O''na halis kılarak kulluk et.'),
(39, 3, 23, 458, 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌ كَفَّارٌ', 'ʾalā li-llāhi d-dīnu l-khāliṣu wa-lladhīna t-takhadhū min dūnihi ʾawliyāʾa mā naʿbuduhum ʾillā li-yuqarribūnā ʾilā llāhi zulfā ʾinna llāha yaḥkumu baynahum fī mā hum fīhi yaḫtalifūna ʾinna llāha lā yahdī man huwa kādhibun kaffārun', 'Bilesiniz ki, halis din yalnız Allah''ındır. O''ndan başka veliler edinip de, ''Onlar bizi Allah''a yaklaştırsınlar diye şefaat etsinler diye (tuttuk) '' diyenler, şüphesiz Allah onların ihtilaf edip durdukları şey hakkında aralarında hüküm verecektir. Şüphesiz Allah, yalancı ve çok kâfir olan kimseyi doğru yola iletmez.'),
(39, 4, 23, 458, 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ سُبْحَٰنَهُۥ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'law arāda ʾallāhu ʾan yattakhidha waladan la-ṣṭafā mimmā yakhluqu mā yashāʾu subḥānahū huwa ʾallāhu l-wāḥidu l-qahhāru', 'Allah çocuk edinmek dileseydi, elbette yarattıklarından dilediğini seçerdi. O, yücedir! O, Allah''tır; birdir, kahredici olandır.'),
(39, 5, 23, 458, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'khalaqa as-samāwāti wa-al-arḍa bi-al-ḥaqqi yukawwiru al-layla ʿalā an-nahāri wa yukawwiru an-nahāra ʿalā al-qamari wa sakhkhara ash-shamsa wa-al-qamara kullun yajrī li-ajalin musammā alā huwa al-ʿazīzu al-ghaffāru', 'Gökleri ve yeri hak ile yarattı. Geceyi gündüzün üzerine dolar, gündüzü de gecenin üzerine dolar. Güneşi ve Ay''ı buyruğu altına alıp hizmete amade kıldı. Her biri belirlenmiş bir vakte kadar akar. Haberiniz olsun ki O, mutlak güç sahibidir, çok bağışlayandır.'),
(39, 6, 23, 459, 'خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًا مِّنۢ بَعْدِ خَلْقٍ فِى ظُلُمَٰتٍ ثَلَٰثٍ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُصْرَفُونَ', 'xalaqakum min nafsin wāḥidatin thumma jaʿala minhā zawjahā wa-anzala lakum mina l-anʿāmi thamāniyata azwājin yakhluqukum fī buṭūni ummahātikum khalqan min baʿdi khalqin fī ẓulumātin thalāthin dhālikumu llāhu rabbukum lahu l-mulku lā ilāha illā huwa fa-annā tuṣrafūna', 'Sizi tek bir nefisten yarattı. Sonra ondan eşini vücuda getirdi ve sizin için hayvanlardan sekiz çift indirdi. Sizi analarınızın karınlarında, üç karanlık içinde, bir yaratılıştan sonra diğer bir yaratılışa mazhar kılarak yaratmaktadır. İşte bu, Rabbiniz olan Allah''tır. Mülk O''nundur. O''ndan başka ilah yoktur. Buna rağmen nasıl oluyor da O''ndan çevriliyorsunuz?'),
(39, 7, 23, 459, 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'in takfurū fa-inna Allāha ghaniyyun ʿankum wa-lā yarḍā li-ʿibādihi l-kufra wa-in tashkurū yarḍahu lakum wa-lā taziru wāziratun wizra ʾukhrā thumma ilā Rabbikum marjiʿukum fa-yunabbiʾukum bimā kuntum taʿmalūn ʾinnahu ʿalīmun bi-dhāti ṣ-ṣudūr', 'Eğer inkâr ederseniz, şüphesiz Allah''ın size ihtiyacı yoktur. Bununla birlikte O, kullarının inkâr etmesinden razı olmaz. Eğer şükrederseniz bundan razı olur. Hiçbir günahkâr, başka bir günahkârın günahını yüklenmez. Sonra dönüşünüz Rabbinizedir. O zaman O, size yaptıklarınızı haber verecektir. Şüphesiz O, göğüslerde olanı hakkıyla bilendir.'),
(39, 8, 23, 459, 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا إِنَّكَ مِنْ أَصْحَٰبِ ٱلنَّارِ', 'wa ʾiḏā massā l-ʾinsāna ḍurrun daʿā rabbahū munīban ʾilayhi ṯumma ʾiḏā ḫawwalhū niʿmatan minhu nasīya mā kāna yadʿū ʾilayhi min qablu wa jaʿala li-llāhi ʾandādan li-yuḍilla ʿan sabīlihī qul tamattaʿ bi-kufrika qalīlan ʾinnaka min ʾaṣḥābi n-nāri', 'İnsana bir zarar dokunduğu zaman Rabbine yönelerek O''na dua eder. Sonra Rabb''i tarafından bir nimet verildiğinde, daha önce O''na yalvardığını unutur ve Allah yolundan saptırmak için O''na eşler koşar. De ki: "Küfrünle az bir süre daha faydalan; çünkü sen ateş ehlindensin."'),
(39, 9, 23, 459, 'أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ ٱلْءَاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'Ammen huve qānitun ʾānāʾa l-layli sāğidan waqāʾiman yaḥẕaru l-ʾākhirata wa yarğū raḥmata rabbihī Qul hal yastawī l-laẕīna yaʿlamūna wa l-laẕīna lā yaʿlamūn ʾInnamā yataẕakkaru ʾulū l-ʾalbāb', 'Yoksa gece saatlerinde (taat için) kalkıp secde ederek ve kıyamda durarak, ahiretten çekinip Rabbinin rahmetini uman kimse mi (daha hayırlıdır)? De ki: Hiç bilenlerle bilmeyenler bir olur mu? Ancak akıl sahipleri (bunları) hakkıyla takdir eder.'),
(39, 10, 23, 459, 'قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ', 'Qul yā ʿibādi lladhīna āmanū ttaqū rabbakum Lilladhīna aḥsanū fī hādhihi d-dunyā ḥasanatun Wa-arḍu llāhi wāsiʿatun Innamā yuwaffā ṣ-ṣābirūna ajrahum bi-ghayri ḥisābin', 'De ki: "Ey iman eden kullarım! Rabbinize karşı gelmekten sakının. Bu dünyada iyilik yapanlara iyilik vardır. Allah''ın yeryüzü genişti. Şüphesiz sabredenlere ecirleri hesapsızca ödenir."'),
(39, 11, 23, 460, 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', 'Qul innī umirtu an aʿbuda Llāha mukhliṣan lahū d-dīna', 'De ki: "Ben, dini Allah''a halis kılarak O''na kulluk etmekle emrolundum."'),
(39, 12, 23, 460, 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', 'wa ʾumirtu li-ʾan ʾakūna ʾawwala l-muslimīn', 'Ben, Müslümanların ilki olmakla emrolundum.'),
(39, 13, 23, 460, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'qul innī ʾakhāfu ʾin ʿaṣaytu rabbī ʿaḏāba yawmin ʿaẓīm', 'De ki: Eğer Rabbime isyan edersem, o büyük günün azabından korkarım.'),
(39, 14, 23, 460, 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى', 'qul allāha aʿbudu mukhliṣan lahū dīnī', 'De ki: "Ben, dini Allah''a halis kılarak O''na kulluk ederim."'),
(39, 15, 23, 460, 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ قُلْ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 'faʿbudū mā shiʾtum min dūnihi qul inna l-khāṣirīna lladhīna khasirū anfusahum wa-ahlīhim yawma l-qiyāmati ʾalā dhālika huwa l-khusrānu l-mubīnu', 'Onun dışındakilerden dilediğinizi kulluk edin! De ki: "Gerçekten hüsrana uğrayanlar, kıyamet günü kendilerini ve ailelerini hüsrana uğratanlardır." Dikkat edin! İşte bu, apaçık olan hüsranın ta kendisidir.'),
(39, 16, 23, 460, 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ يَٰعِبَادِ فَٱتَّقُونِ', 'lahum min fawqihim ẕulalun minan-nar wa min taḥtihim ẕulalun ḏalika yukhawwifu-llahu bihi ʿibādahu yā ʿibādi f-ʾttaqūn', 'Onların üstlerinde ateşten gölgeler, altlarında da ateşten gölgeler vardır. İşte Allah, kullarını bununla korkutuyor. Ey kullarım, benden korkun!'),
(39, 17, 23, 460, 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ فَبَشِّرْ عِبَادِ', 'wa-lladhīna-jtanebū-ṭ-ṭāghūta an yaʿbudūhā wa-anābū ilā-llāhi lahumu-l-bushrā fa-bashshir ʿibādi', 'Onlar ki, tâğûta kulluk etmekten kaçındılar ve Allah''a yöneldiler; müjde onlara! Müjde ver kullarıma!'),
(39, 18, 23, 460, 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 'ellezîne yestemi''ûne-lḳavle feyettebi''ûne aḥseneh ülâike-lleẕîne hedâhumu-llâh ve ülâike hum ülû-l''elbâb', 'Onlar ki sözü dinlerler de onun en güzeline uyarlar. İşte onlar, Allah''ın hidayet ettiği kimselerdir ve işte onlar, akıl sahiplerinin ta kendileridir.'),
(39, 19, 23, 460, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', 'ʾafaman ḥaqqa ʿalayhi kalimatu l-ʿadhābi ʾafaʾanta tunqidhū man fī n-nāri', 'Üzerine azap kelimesi hak olmuş kimse (ateşte kalan kimse) ile ateşin içindeki kimseyi sen mi kurtaracaksın?'),
(39, 20, 23, 460, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', 'lākin alladhīna ittaqaw rabbahum lahum ghurafun min fawqihā ghurafun mabniyyatun tajrī min taḥtihā al-anhāru waʿda Allāhi lā yukhlifu Allāhu al-mīʿāda', 'Ancak Rablerine karşı gelmekten sakınanlar için, onların üstünde de üst üste yapılmış köşkler vardır. Altlarından ırmaklar akar. Allah va''dinden dönmez. Bu, Allah''ın gerçek va''didir.'),
(39, 21, 23, 460, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'elem tera enne-llāhe enzele mine-s-semāʾi māʾan feselikehu yenābīʿa fī-l-ʾarḍi summe yuḫriju bihi zarʿan muḫtalifen elvānuhu summe yehīju fetarāhu muṣfarran summe yecʿaluhu ḥuṭāman ʾinne fī ḏālika laḏikrā liʾūlī-l-ʾalbābi', 'Görmedin mi Allah, gökten bir su indirdi de onu yerin içine akar kaynaklar yaptı. Sonra onunla türlü renklerde ekinler bitirir. Sonra o ekinler kurur da sararmış olduğunu görürsün. Sonra da onu çerçöp yapar. Şüphesiz bunlarda akıl sahipleri için bir ibret vardır.'),
(39, 22, 23, 461, 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ فَوَيْلٌ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', 'ʾafaman šaraḥa ʾllāhu ṣadrahu lil-ʾislāmi fahuwa ʿalā nūrin mir-rabbihī fawaylun lil-qāsiyati qulūbuhum min ḏikri ʾllāhi ʾulāʾika fī ḍalālin mubīnin', 'Allah''ın, göğsünü İslam''a açtığı kimse, Rabbinden (gelen) bir nur üzere değil midir? Kalpleri Allah''ı anmaktan katılaşanlara gelince, yazıklar olsun onlara! İşte onlar apaçık bir sapıklık içindedirler.'),
(39, 23, 23, 461, 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'Allahu nazzala aḥsana l-ḥadīthi kitāban mutashābihan mathāniya Taqshaʿirru minhu julūdu alladhīna yakhshawna rabbahum Thumma talīnu julūduhum waqulūbuhum ilā dhikri Allāhi Dhālika hudā Allāhi yahdī bihi man yashāʾu Wa man yuḍlili Allāhu famā lahu min hādin', 'Allah, sözün en güzelini, (âyetleri) birbirine benzeyen ve (mânâları) tekrarlanan bir kitap olarak indirmiştir. Rablerinden içleri titreyenlerin derileri ondan ürperir. Sonra derileri ve kalpleri Allah''ın zikrine ısınıp yumuşar. İşte bu, Allah''ın, dilediğini kendisiyle doğru yola ilettiği hidayetidir. Allah''ın şaşırtıp-saptırdığı kimseye de yol gösterici yoktur.'),
(39, 24, 23, 461, 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', 'ʾafaman yattaqī biwajhihī sūʾa l-ʿadhābi yawma l-qiyāmati waqīla l-lẓālimīna dhūqū mā kuntum taksibūna', 'Yüzüyle azabın kötülüğünden korunmaya çalışanı (cehennem ateşine atılanı) kıyamet günü azabın kötülüğünden koruyabilen kimse midir? Ve zalimlere: ''Kazandığınızı tadın!'' denilir.'),
(39, 25, 23, 461, 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 'kaḏḏaba llaḏīna min qablihim fa atāhumu lʿaḏābu min ẖaytu lā yashʿurūna', 'Onlardan öncekiler de yalanlamışlardı. Böylece onlara farkında olmadıkları bir yerden azap gelmişti.'),
(39, 26, 23, 461, 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'faʾaḏāqahumu ʾllāhu l-ḵizya fī l-ḥayāti d-dunyā wa-laʿaḏābu l-ʾāḵirati ʾakbaru law kānū yʿlamūn', 'Bunun üzerine Allah, dünya hayatında onlara rezilliği tattırdı. Elbette ahiret azabı daha büyüktür; bir bilselerdi!'),
(39, 27, 23, 461, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ', 'Ve lekad darabnâ lin nâsi fî hâzâl kur''âni min kulli meselin leallehum yetezekkerûn(yetezekkerûne)', 'Andolsun ki Biz, bu Kur''an''da insanlar için her türlü misali verdik ki onlar öğüt alsınlar.'),
(39, 28, 23, 461, 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ', 'Qurʾānan ʿarabiyyan ghayra dhī ʿiwajin Laʿallahum yattaqūna', 'Hiçbir eğriliği olmayan Arapça bir Kur''an (bu), umulur ki (onlar) korunurlar.'),
(39, 29, 23, 461, 'ضَرَبَ ٱللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'ḍaraba llāhu mathalan rajulan fīhi shurakāʾu mutashākisūna wa rajulan salaman li rajulin hal yastawiyāni mathalan al-ḥamdu li llāhi bal aktharuhum lā yaʿlamūna', 'Allah, aralarında (haklarda) birbirine giren ortakların bulunduğu bir adamla, sadece bir kişiye ait olan (veya sadece bir kişiye teslim olmuş) bir adamı misal verdi. Hiç bu ikisi misal bakımından bir olur mu? Hamd Allah''a mahsustur. Hayır, onların çoğu bilmezler.'),
(39, 30, 23, 461, 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ', 'ʾinnaka mayyitun wa ʾinnahum mayyitūna', 'Şüphesiz sen de öleceksin, onlar da ölecekler.'),
(39, 31, 23, 461, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', 'thumma innakum yawma l-qiyāmati ʿinda rabbikum takhtaṣimūn', 'Sonra kıyamet günü Rabbinizin katında birbirinizle dâvâlaşacaksınız.'),
(39, 32, 24, 462, 'فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', 'faman aẓlamu mimman kaḏaba ʿalā Allāhi wa-kaḏḏaba biṣ-ṣidqi iḏ jāʾahu alaysa fī Jahannama maṯwan lil-kāfirīn', 'Allah''a karşı yalan uyduran ve kendisine geldiğinde hakkı yalan sayandan daha zalim kim olabilir? Kâfirler için cehennemde bir barınak yok mudur?'),
(39, 33, 24, 462, 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'wa-lladhī jāʾa bi-ṣ-ṣidqi wa ṣaddaqa bihi ʾulāʾika humu l-muttaqūn', 'Hak ile gelen ve onu tasdik edenler var ya, işte onlar takva sahipleridir.'),
(39, 34, 24, 462, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 'lahum mā yashāʾūna ʿinda rabbihim dhālika jazāʾu l-muḥsinīn', 'Rableri katında diledikleri şey onlarındır. İşte bu, iyilik edenlerin mükâfatıdır.'),
(39, 35, 24, 462, 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'liyukaffira llāhu ʿanhum aswaʾa lladhī ʿamilū wayajziyahum ajrahum biʾaḥsani lladhī kānū yaʿmalūn', 'Böylece Allah, onların yaptıkları en kötü şeyleri (günahlarını) örtecek ve onlara, yapmakta oldukları (güzel amellerin) en iyisinin karşılığını verecektir.'),
(39, 36, 24, 462, 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'ʾalaysa llāhu bikāfin ʿabdahū wayukhawwifūnaka bi-lladhīna min dūnihi waman yuḍlili llāhu famā lahu min hādin', 'Allah kuluna kâfi değil mi? Onlar seni Allah''tan başka (taptıkları putlar) ile korkutuyorlar. Allah''ın, kimi saptırmasına gelince, artık ona doğru yolu gösteren bulunmaz.'),
(39, 37, 24, 462, 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ أَلَيْسَ ٱللَّهُ بِعَزِيزٍ ذِى ٱنتِقَامٍ', 'wa-man yahdi allāhu fa-mā lahu min muḍillin a-laysa allāhu bi-ʿazīzin dhī intiqāmin', 'Allah''ın hidayet ettiği kimseye saptırıcı bulunmaz. Allah''ın, mutlak güç sahibi, intikam sahibi olduğunu bilmezler mi?'),
(39, 38, 24, 462, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ قُلْ حَسْبِىَ ٱللَّهُ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', 'Ve leʾin seʾeltehum men ḫaleḳa es-semāvāti vel-ʾarḍa leyaḳūlunne Allāhu Ḳul eferaʾeytum mā tedʿūne min dūni Allāhi İn erādeniye Allāhu biḍurrin hel hunne kāşifātu ḍurrihi Ev erādenī biraḥmetin hel hunne mumsikātu raḥmetihī Ḳul ḥasbiye Allāhu ʿaleyhi yetevekkelu el-mutevekkilūne', 'Andolsun ki onlara: “Gökleri ve yeri kim yarattı?” diye sorsan, mutlaka “Allah” diyeceklerdir. De ki: “Peki, Allah’tan başka taptığınız şeyleri gördünüz mü? Eğer Allah bana bir zarar vermek istese, onlar O’nun zararını giderebilirler mi? Yahut bana bir rahmet dilese, onlar O’nun rahmetini tutabilirler mi?” De ki: “Bana Allah yeter. Tevekkül edenler ancak O’na tevekkül ederler.”'),
(39, 39, 24, 462, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ فَسَوْفَ تَعْلَمُونَ', 'qul yā qawmi ʿmalū ʿalā makāntikum innī ʿāmilun fa-sawfa taʿlamūn', 'De ki: "Ey kavmim! Durumunuz ne olursa olsun, (bütün) gücünüzle) yapacağınızı yapın. Şüphesiz ben de yapacağımı yapıyorum. Yakında (sonunuzun) ne olacağını bileceksiniz."'),
(39, 40, 24, 462, 'مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', 'man yaʾtīhi ʿaḏābun yuhzīhi wa yaḥillu ʿalayhi ʿaḏābun muqīmun', 'Kendisini rezil edecek bir azap gelene ve üzerine kalıcı bir azap inecek kişiye gelince...'),
(39, 41, 24, 463, 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'ʾinnā ʾanzalnā ʿalayka l-kitāba li-nnāsi bi-l-ḥaqqi fa-mani ʾhtadā fa-li-nafsihi wa-man ḍalla fa-ʾinnamā yaḍillu ʿalayhā wa-mā ʾanta ʿalayhim bi-wakīlin', 'Şüphesiz biz sana kitabı insanlar için hak olarak indirdik. Kim doğru yola gelirse kendi lehinedir. Kim de saparsa kendi aleyhinedir. Sen onlara vekil değilsin.'),
(39, 42, 24, 463, 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'Allāhu yatawaffā l-anfusa ḥīna mawatihā Wa-llatī lam tamut fī manāmihā Fa-yumsiku llatī qaḍā ʿalayhā l-mawta Wa-yursilu l-ukhrā ilā ajalim musammā Inna fī dhālika la-ʾāyātin li-qawmin yatafakkarūn', 'Allah, ölüm anlarında ruhlarını kabzeder. Henüz ölmemiş olanların da uykularında ruhlarını kabzeder. Sonra ölümüne hükmettiği (ruhları) tutar, diğerlerini ise belirlenmiş bir süreye kadar salıverir. Elbette bunda, tefekkür eden bir kavim için nice ibretler vardır.'),
(39, 43, 24, 463, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًٔا وَلَا يَعْقِلُونَ', 'amı-t-taḫaḏū min dūni-llāhi šufʿāʾa qul ʾawalaw kānū lā yamlikūna šayʾan walā yaʿqilūn', 'Yoksa Allah''tan başka şefaatçiler mi edindiler? De ki: Onlar hiçbir şeye mâlik olmasalar ve akıl erdiremeseler de mi?'),
(39, 44, 24, 463, 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًا لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'qul lillāhi sh-shafāʿatu jamīʿan lahu mulku s-samāwāti wa-l-arḍi thumma ilayhi turjaʿūna', 'De ki: Şefaat tamamen Allah''ındır. Göklerin ve yerin mülkiyeti de O''nundur. Sonra O''na döndürüleceksiniz.'),
(39, 45, 24, 463, 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 'wa ʾiḏā ḏukira ʾallāhu waḥdahū ʾišmaʾazzat qulūbu ʾallaḏīna lā yuʾminūna bil-ʾāḵirah wa ʾiḏā ḏukira ʾallaḏīna min dūnihi ʾiḏā hum yastabširūn', 'Allah''ın adı tek başına anıldığında, ahirete inanmayanların kalpleri sıkılır. Ama O''ndan başkaları anıldığında, hemen sevinirler.'),
(39, 46, 24, 463, 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'quli llāhumma fāṭira s-samāwāti wa-l-arḍi ʿālima l-ghaybi wa-sh-shahādati anta taḥkumu bayna ʿibādika fī mā kānū fīhi yakhtalifūn', 'De ki: "Allahım! Gökleri ve yeri yaratan, gaybı ve görüneni bilen, kullarının ayrılığa düştükleri hususlarda aralarında hükmedecek olan sensin!"'),
(39, 47, 24, 463, 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', 'wa-ʾanna lilladhīna ẓalamū mā fī l-ʾarḍi jamīʿan wa-mithlahū maʿahū la-ftadaw bihī min sūʾi l-ʿadhābi yawmi l-qiyāmati wa-badā lahum mina llāhi mā lam yakūnū yaḥtasibūna', 'Eğer yeryüzünde bulunan her şey ve onunla birlikte bir misli daha zalimlerin olsaydı, kıyamet günündeki azabın fenalığından kurtulmak için mutlaka (bunların) hepsini feda ederlerdi. İşte o gün onlara Allah tarafından, hiç beklemedikleri (bir azap) da açığa çıkar.'),
(39, 48, 24, 464, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'wa badā lahum sayyiʾātu mā kasabū wa ḥāqa bihim mā kānū bihī yastahziʾūn', 'Ve onlara, kazandıklarının kötülükleri göründü ve alay etmekte oldukları şey onları kuşattı.'),
(39, 49, 24, 464, 'فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ بَلْ هِىَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'faʾiḏā massā l-ʾinsāna ḍurrun daʿānā ṯumma ʾiḏā ḫawwalnāhu niʿmetan minnā qāla ʾinnamā ʾūtītuhu ʿalā ʿilmin bal hiya fitnatun wa-lākinna ʾakṯarahum lā yaʿlamūn', 'İnsana bir zarar dokunduğu zaman bize dua eder. Sonra ona tarafımızdan bir nimet verdiğimizde, ''Bu, ancak benim bilgim sayesinde bana verildi'' der. Hayır! O bir imtihandır, fakat çokları bilmezler.'),
(39, 50, 24, 464, 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'qad qālahā alladhīna min qablihim famā aghnā ʿanhum mā kānū yaksibūn', 'Onlardan öncekiler de böyle söylemişlerdi de kazandıkları kendilerinden hiçbir şeyi gidermemişti.'),
(39, 51, 24, 464, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', 'faʾaṣābahum sayyiʾātu mā kasabū wa-llaḏīna ẓalamū min hāʾulāʾi sayuṣībuhum sayyiʾātu mā kasabū wa mā hum bi-muʿjizīna', 'Onları kazandıklarının kötülükleri isabet etti. Ve zulmedenlerden olanlar da, kazandıklarının kötülükleri onlara isabet edecektir ve onlar (bizi) aciz bırakacak değillerdir.'),
(39, 52, 24, 464, 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'ʾawalam yaʿlamū ʾanna ʾallāha yabsṭu ʾr-rizqa liman yašāʾu wa yaqdiru ʾinna fī ḏālika laʾāyātin liqawmin ʾyūʾminūn', 'Onlar, Allah''ın dilediğine rızkı bol verdiğini ve (dilediğine de) ölçtüğünü bilmediler mi? Şüphesiz bunda, iman eden bir kavim için nice ibretler vardır.'),
(39, 53, 24, 464, 'قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'Qul yā ʿibādiya alladhīna asrafū ʿalā anfusihim Lā taqnaṭū min raḥmati Allāh Inna Allāha yaghfiru al-dhunūba jamīʿan Innahu huwa al-Ghafūru al-Raḥīm', 'De ki: (Ey kendi nefislerine karşı haddi aşmış kullarım!) Allah''ın rahmetinden ümidinizi kesmeyin. Şüphesiz Allah bütün günahları bağışlar. Şüphesiz O, çok bağışlayıcı, çok merhamet edicidir.'),
(39, 54, 24, 464, 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', 'wa ʾanībū ʾilā rabbikum wa ʾaslimū lahū min qabli ʾan yaʾtiyakumu l-ʿaḏābu ṯumma lā tunṣarūn', 'Ve Rabbinize (yönelip) dönün ve size azap gelip çatmadan, sonra yardım olunmamak (durumuna düşmeden) O''na teslim olun.'),
(39, 55, 24, 464, 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ', 'wa-ttabiʿū ʾaḥsana mā ʾunzila ʾilaykum min rabbikum min qabli ʾan yaʾtiyakumu l-ʿaḏābu bagtatan wa-ʾantum lā tašʿurūn', 'Rabbinizden size indirilmiş olan en güzel şeye uyun; haberiniz olmadan, ansızın azap gelip çatmadan önce.'),
(39, 56, 24, 464, 'أَن تَقُولَ نَفْسٌ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', 'ʾan taqūla nafsun yā ḥasratā ʿalā mā farrṭtu fī janbi llāhi wa ʾinna kuntu lami n as-sākhirīn', ' (Kıyamet günü) bir nefis şöyle diye(r): Vay halime! Allah''ın yanında (emirlerine karşı) kusuruma bak! Ben gerçekten alay edenlerdendim!'),
(39, 57, 24, 465, 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', 'aw taqūla law anna Allāha hadānī lakuntu mina l-muttaqīna', 'Yahut: ''Allah bana hidayet etseydi, elbette muttaki (sakınan)lardan olurdum'' demesin.'),
(39, 58, 24, 465, 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', 'aw taqūla ḥīna tarā l-ʿadhāb law anna lī karratan fa-akūna mina l-muḥsinīn', 'Yahut azabı gördüğü zaman: ''Keşke benim için bir dönüş (dünyaya bir daha gitme) olsaydı da güzel iş yapanlardan olsaydım!'' diyeceği zaman.'),
(39, 59, 24, 465, 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ', 'balā qad jāʾatka ʾāyātī fakadhdhabta bihā wastakbarta wakunta mina l-kāfirīn', 'Hayır! Sana âyetlerim gelmişti de onları yalan saymış, büyüklük taslamış ve kâfirlerden olmuştun.'),
(39, 60, 24, 465, 'وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ', 'wa-yawma l-qiyāmati tarā lladhīna kadhabū ʿalā llāhi wujūhuhum muswaddatun ʾalaysa fī jahannama mathwā lil-mutakabbirīna', 'Kıyamet günü, Allah''a karşı yalan uyduranların yüzlerinin simsiyah kesilmiş olduğunu görürsün. Cehennemde kibirlenenler için bir barınak yok mudur?'),
(39, 61, 24, 465, 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', 'wa yunajjī Allāhu alladhīna ittaqaw bimafāzatihim lā yamassuhumu as-sūʾu wa lā hum yaḥzanūn', 'Allah, takva sahiplerini kurtuluşlarıyla kurtarır. Onlara kötülük dokunmaz ve onlar mahzun da olmazlar.'),
(39, 62, 24, 465, 'ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'Allāhu khāliqu kulli shayʾin Wa huwa ʿalā kulli shayʾin wakīlun', 'Allah her şeyin yaratıcısıdır. O, her şey üzerinde vekildir.'),
(39, 63, 24, 465, 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'lahū maqālīdu s-samāwāti wa-l-ʾarḍi wa-lladhīna kafarū bi-ʾāyāti llāhi ʾulāʾika humu l-khāsirūna', 'Göklerin ve yerin anahtarları O''nundur. Allah''ın âyetlerini inkâr edenler ise ziyana uğrayanların ta kendileridir.'),
(39, 64, 24, 465, 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ', 'Qul Afaġayra Allāhi Taʾmurūnnī Aʿbudu Ayyuhā al-jāhilūn', 'De ki: "Ey cahiller! Bana Allah''tan başkasını mı emrediyorsunuz?"'),
(39, 65, 24, 465, 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'Ve lekad ūḥiye ileyke ve ilâlleẕîne min kablike leʾin eşrakte leyaḥbeṭanne ʿameluke ve letekūnenne mine-l-ḫâsirîn', 'Andolsun ki sana da, senden öncekilere de vahyolunmuştur ki: Eğer şirk koşarsan, amelin kesinlikle boşa gider ve mutlaka hüsrana uğrayanlardan olursun.'),
(39, 66, 24, 465, 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 'bal-lāh-e fa-ʿbud wa-kun min-a sh-shākirīn', 'Hayır! Artık Allah''a kulluk et ve şükredenlerden ol!'),
(39, 67, 24, 465, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'wa mā qadarū allāha ḥaqqa qadrihī wa al-arḍu jamīʿan qabḍatuhu yawma al-qiyāmah wa as-samāwātu maṭwiyyātun bi-yamīnihī subḥānahū wa taʿālā ʿammā yushrikūn', 'Onlar, Allah''ı gereği gibi takdir edemediler. Kıyamet gününde bütün yeryüzü O''nun bir avucu, gökler de O''nun sağlığıyla dürülmüş haldedir. O, onların ortak koştuklarından münezzehtir ve yücedir.'),
(39, 68, 24, 466, 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ', 'wa-nufikha fī ṣ-ṣūri fa-ṣaʿiqa man fī s-samāwāti wa-man fī l-arḍi illā man shāʾa -llāhu thumma nufikha fīhi ʾukhrā fa-ʾidhā hum qiyāmun yanẓurūna', 'Sur''a üflenir. Göklerde ve yerde olan herkes, Allah''ın diledikleri müstesna, bayılır kalır. Sonra ona bir daha üflenir, bir de ne görsünler, onlar ayağa kalkmış bakıyorlar.'),
(39, 69, 24, 466, 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّۦنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'wa-ashraqati l-arḍu bi-nūri rabbihā wa-wuḍiʿa l-kitābu wa-jīʾa bi-n-nabiyyīna wa-sh-shuhadāʾi wa-quḍiya baynahum bi-l-ḥaqqi wa-hum lā yuẓlamūna', 'Yeryüzü, Rabbini''nin nuruyla aydınlanır. (Amel) defterleri ortaya konur. Peygamberler ve şahitler getirilip aralarında hak ile hüküm verilir ve onlara haksızlık yapılmaz.'),
(39, 70, 24, 466, 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', 'wa wuffiyat kullu nafsin mā ʿamilat wa huwa ʾaʿlamu bimā yafʿalūn', 'Her nefis, yaptığının karşılığını tam olarak almıştır. O, onların yapmakta olduklarını en iyi bilendir.'),
(39, 71, 24, 466, 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ', 'wa-sīqa lladhīna kafarū ilā jahannama zumaran ḥattā idhā jāʾūhā futiḥat abwābuhā wa-qāla lahum ḵazanatuhā alam yaʾtikum rusulun minkum yatlūna ʿalaykum ʾāyāti rabbikum wa-yunḏirūnakum liqāʾa yawmikum hāḏā qālū balā wa-lākin ḥaqqat kalimatu l-ʿaḏābi ʿalā l-kāfirīn', 'Kâfirler zümeler halinde cehenneme sevkedilirler. Nihayet oraya geldiklerinde, kapıları açılır ve onlara cehennem bekçileri der ki: "Size içinizden Rabbinizin âyetlerini okuyan ve bu gününüze kavuşacağınız hakkında sizi uyaran peygamberler gelmedi mi?" Derler ki: "Evet, geldi." Fakat azap kelimesi kâfirler üzerine hak olmuştu.'),
(39, 72, 24, 466, 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'qīla dkhulū abwāba jahannama khālidīna fīhā fabīʾsa mathwā lmutakabbirīn', 'Şöyle denildi: "Ebedî kalmak üzere cehennem kapılarından girin! Kibirlenenlerin kalacağı yer ne kötüdür!"'),
(39, 73, 24, 466, 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ', 'wa-sīqa alladhīna ittaqaw rabbahum ilā al-jannati zumaran ḥattā idhā jāʾūhā wa-futiḥat abwābuha wa-qāla lahum khazanatuhā salāmun ʿalaykum ṭibtum fa-dkhulūhā khālidīn', 'Rablerine karşı gelmekten sakınanlar ise bölük bölük cennete sevk edilirler. Nihayet oraya vardıklarında kapıları açılır ve onlara hazineleri şöyle der: "Selam olsun size! Hoş ve güzel geldiniz! Ebediyen kalmak üzere girin oraya!"'),
(39, 74, 24, 466, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 'wa qālū l-ḥamdu li-llāhi l-ladhī ṣadaqanā waʿdahu wa-awراثanā l-arḍa natabawwaʾu mina l-jannati ḥaythu nashāʾu fa niʿma ajru l-ʿāmilīna', 'Ve dediler ki: Hamd, vaadini gerçekleştiren, bizi (cennetin) yerlerinden dilediğimiz yerde konaklayacağımız şekilde mirasçı kılan Allah''a mahsustur. Çalışanların mükâfatı ne güzeldir!'),
(39, 75, 24, 467, 'وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'wa tarā al-malāʾikata ḥāffīna min ḥawli al-ʿarshi yusabbiḥūna biḥamdi rabbihim wa quḍiya baynahum bil-ḥaqqi wa qīla al-ḥamdu lillāhi rabbi al-ʿālamīn', 'Melekleri de Arş''ın etrafını çevirmiş oldukları halde görürsün. Hep Rablerini hamd ile tesbih ederler. Ve aralarında hak ile hüküm verilmiştir. Ve: "Hamd, âlemlerin Rabbi Allah''a mahsustur!" denilir.'),
(40, 1, 24, 467, 'حمٓ', 'Ḥā Mīm', 'Ha, Mim.'),
(40, 2, 24, 467, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'tanzīlu l-kitābi mina llāhi l-ʿazīzi l-ʿalīmi', 'Bu Kitabın indirilmesi, mutlak güç sahibi, hakkıyla bilen Allah tarafındandır.'),
(40, 3, 24, 467, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ لَآ إِلَٰهَ إِلَّا هُوَ إِلَيْهِ ٱلْمَصِيرُ', 'ghāfiri dh-dhanbi wa qābili t-tawbi shadīdi l-ʿiqābi dhī ṭ-ṭawli lā ilāha illā huwa ilayhi l-maṣīru', 'O, günahı bağışlayan, tevbeyi kabul eden, azabı çetin olan, lütuf sahibi Allah''tır. O''ndan başka ilah yoktur. Dönüş O''nadır.'),
(40, 4, 24, 467, 'مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَٰدِ', 'mā yujādilu fī ʾāyāti llāhi ʾillā llaḏīna kafarū falā yagṟurka taqallubuhum fī l-bilādi', 'Allah''ın ayetleri hakkında, kendilerine gelmiş olan bir delil olmaksızın, sadece çekişip duranlar tartışır. (Onların bu tutumları) seni aldatmasın. Onlar şehirlerde (istediği gibi) gezip dolaşırlar.'),
(40, 5, 24, 467, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ وَجَٰدَلُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'kadhdhabat qablahum qawmu nūḥin wal-ʾaḥzābu min baʿdihim wahammat kullu ʾummatin birasūlihim liyaʾkhudhūhu wajādalū bil-bāṭili liyudḥiḍū bihi l-ḥaqqa faʾakhadhtuhum fakayfa kāna ʿiqāb', 'Onlardan önce Nuh''un kavmi ve onlardan sonraki topluluklar da (peygamberleri) yalanlamışlardı. Her ümmet, kendi peygamberini yakalamaya (öldürmeye) kastetmişti. Onlar, hakkı batılla ortadan kaldırmak için mücadele ettiler. Ben de onları yakalayıverdim. Benim cezalandırmam nasıl oldu (görülmedi mi)?'),
(40, 6, 24, 467, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَٰبُ ٱلنَّارِ', 'wa kaḏālika ḥaqqat kalimatu rabbika ʿalā llaḏīna kafarū ʾannahum ʾaṣḥābu n-nār', 'Ve işte böylece Rabbinin sözü, kâfirler üzerine hak olmuştur; şüphesiz onlar ateşin yoldaşlarıdır.'),
(40, 7, 24, 467, 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', 'alladhīna yaḥmilūna l-ʿarsha waman ḥawlahū yusabbiḥūna biḥamdi rabbihim wa yuʾminūna bihi wa yastaghfirūna lilladhīna ʾāmanū rabbanā wasiʿta kulla shayin raḥmatan wa ʿilman fāghfir lilladhīna tābū wa-ttabaʿū sabīlaka wa qihim ʿadhāba l-jaḥīmi', 'Arşı taşıyanlar ve onun etrafındakiler, Rablerini hamd ile tesbih ederler, O''na inanırlar ve iman edenler için bağışlanma dilerler: "Rabbimiz! Sen her şeyi rahmetinle ve ilminle kuşattın. Tövbeye yönelenlere ve senin yoluna uyanlara mağfiret eyle ve onları cehennem azabından koru."'),
(40, 8, 24, 468, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'Rabbanā wa-adkhilhum jannāti ʿadnin allatī waʿadtahum wa-man ṣalaḥa min ʾābāʾihim wa-ʾazwājihim wa-ẕurriyyātihim ʾinnaka ʾanta l-ʿazīzu l-ḥakīmu', 'Ey Rabbimiz! Onları de kendilerine vaadettiğin Adn cennetlerine sok; babalarından, eşlerinden ve zürriyetlerinden salih olanları da. Şüphesiz Sen, Azîz''sin, Hakîm''sin.'),
(40, 9, 24, 468, 'وَقِهِمُ ٱلسَّيِّـَٔاتِ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'waqihim-u s-sayyi''āt wa man taqi s-sayyi''āti yawma''iḏin faqad raḥimtehū wa ḏālika huwa l-fawzu l-ʿaẓīm', 'Ve onları fenalıklardan koru. O gün kim fenalıklardan korunursa, şüphesiz onu rahmetine nail etmiş olursun. İşte bu, büyük kurtuluştur.'),
(40, 10, 24, 468, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَٰنِ فَتَكْفُرُونَ', 'ʾinna lladhīna kafarū yunādawna lamaqtu llāhi ʾakbaru min maqtikum ʾanfusakum ʾidh tudʿawna ʾilā l-ʾīmāni fatakfurūna', 'Şüphesiz inkâr edenlere şöyle seslenilir: Allah''ın (size) buğzetmesi, sizin kendi nefsinize buğzetmenizden daha büyüktür. Çünkü siz (dünyada) imana davet olunuyordunuz da inkâr ediyordunuz.'),
(40, 11, 24, 468, 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ', 'qālū rabbanā amattanā ithnatayni waʾaḥyaytanā ithnatayni faʿtarafnā bidhunūbinā fahal ʾilā khurūjin min sabīlin', 'Dediler ki: Rabbimiz! Bizi iki defa öldürdün, iki defa dirilttin. Günahlarımızı itiraf ettik. Şimdi (bu ateşten) çıkmaya bir yol var mıdır?'),
(40, 12, 24, 468, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', 'dhālikum biʾannahu ʾidhā duʿiya-llāhu waḥdahu kafar tum wa ʾin yushrak bihi tuʾminū fa-l-ḥukmu li-llāhi l-ʿaliyyi l-kabīr', 'İşte bu, Allah’a tek olarak ibadet edildiğinde inkâr etmenizden, O’na ortak koşulduğunda ise inanmanızdandır. Artık hüküm, yüce ve büyük olan Allah’a aittir.'),
(40, 13, 24, 468, 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًا وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', 'huwa alladhī yurīkum ʾāyātihi wayunazzilu lakum mina ʾssamāʾi rizqan wamā yatadhakkaru ʾillā man yūnību', 'O, size ayetlerini gösteren ve sizin için gökten bir rızık indirendir. Ancak (Allah''a) yönelen kimse öğüt alabilir.'),
(40, 14, 24, 468, 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'fa-dʿū l-lāha mukhliṣīna lahū d-dīna wa-law kariha l-kāfirūna', 'Öyleyse dini Allah''a halis kılarak O''na dua edin. İsterse kâfirler hoşlanmasın.'),
(40, 15, 24, 468, 'رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', 'rafīʿu d-darağāti ḏū l-ʿarši yulqī r-rūḥa min ʾamrihī ʿalā man yašāʾu min ʿibādihī liyunḏira yawma t-talāqi', 'Dereceleri yükselten, Arş''ın sahibi olan O, iradesindeki (emir) ruhu kullarından dilediğine vahiy yoluyla indirir ki, o (vahy ile) insanları kavuşma günüyle uyarır.'),
(40, 16, 24, 468, 'يَوْمَ هُم بَٰرِزُونَ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'yawma hum bārizūna lā yakhfā ʿalā llāhi minhum shayʾun limani l-mulku l-yawma li llāhi l-wāḥidi l-qahhāri', 'O gün onlar meydana çıkarlar; onlardan hiçbir şey Allah''a gizli kalmaz. Mülk (hükümranlık) kimindir? Allah''ındır! Tek ve Kahhar olanındır!'),
(40, 17, 24, 469, 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ لَا ظُلْمَ ٱلْيَوْمَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'alyawma tujzā kullunafsin bimā kasabat lā ẓulmal-yawm ʾinnallāha sarīʿul-ḥisāb', 'Bugün her nefis kazandığıyla karşılık görür. Bugün haksızlık yoktur. Şüphesiz Allah, hesabı çabuk görendir.'),
(40, 18, 24, 469, 'وَأَنذِرْهُمْ يَوْمَ ٱلْءَازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ', 'Ve enẕirhum yevme-l-âzife(ti) İẕi-lḳulûbu lede-lḥanâciri kâżimîn(e) Mâ liżżâlimîne min ḥamîmin velâ şefî’in yuṭâ’(u)', 'Onları yaklaşan gün ile uyar! O gün kalpler gırtlaklara dayanmıştır, yutkunup dururlar. Zalimler için ne bir dost ne de sözü dinlenir bir şefaatçi vardır.'),
(40, 19, 24, 469, 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', 'yaʿlamu khāʾinata l-ʾaʿyuni wa mā tukhfī ṣ-ṣudūru', 'Gözlerin hainliğini ve kalplerin gizlediğini bilir.'),
(40, 20, 24, 469, 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'wa-llāhu yaqḍī bi-l-ḥaqqi wa-lladhīna yadʿūna min dūnihi lā yaqḍūna bi-shayʾin ʾinna-llāha huwa s-samīʿu l-baṣīru', 'Allah, hak ile hükmeder. O''ndan başka taptıkları ise hiçbir şeyle hükmedemezler. Şüphesiz Allah, hakkıyla işitendir, hakkıyla görendir.'),
(40, 21, 24, 469, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', 'awalam yasīrū fī l-arḍi fayanzaūrū kayfa kāna ʿāqibatu l-ladhīna kānū min qablihim kānū hum ashadda minhum quwwatan wa-āthāran fī l-arḍi fa-akhadha humu l-lāhu bidhunūbihim wa mā kāna lahum mina l-lāhi min wāqin', 'Onlar yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Oysa onlar, kendilerinden daha güçlü idiler ve yeryüzünde daha çok iz bırakmışlardı. Allah da onları günahları yüzünden yakaladı. Onları Allah''tan koruyacak hiç kimse de yoktu.'),
(40, 22, 24, 469, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ إِنَّهُۥ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', 'dhālika bi-annahum kānat taʾtīhim rusuluhum bil-bayyināti fa-kafarū fa-akhaḏahumu ʾllāhu ʾinnahu qawiyyun shadīdu l-ʿiqābi', 'İşte bu, onlara peygamberleri apaçık delillerle geldiği halde inkâr etmeleri yüzündendir. Allah da onları (cezalandırarak) yakalayıverdi. Şüphesiz O, kuvvetlidir, azabı çetindir.'),
(40, 23, 24, 469, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'Ve lekad erselnâ Mûsâ bi-âyâtinâ ve sultânin mubîn', 'Andolsun ki Musa''yı ayetlerimizle ve apaçık bir delille gönderdik.'),
(40, 24, 24, 469, 'إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌ كَذَّابٌ', 'ilā firʿawna wa-hāmāna wa-qārūna faqālū sāḥirun kadhdhābun', 'Firavun''a, Hâmân''a ve Kārûn''a (gönderdik). Dediler ki: ''Bu, çok büyük bir sihirbaz, çok büyük bir yalancıdır!'''),
(40, 25, 24, 469, 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'Fe lemmā jāʾahum bil-ḥaqqi min ʿindinā Qālū-qtulū ʾabnāʾa-l-laḏīna ʾāmanū maʿahū Wastaḥyū nisāʾahum Wa mā kaydu-l-kāfirīna ʾillā fī ḍalālin', 'Nihayet onlara tarafımızdan hak (gerçek) geldiğinde, "Onunla birlikte iman edenlerin erkek çocuklarını öldürün, kadınlarını ise sağ bırakın!" dediler. Ama kafirlerin hileli düzenleri ancak boşa çıkacaktır.'),
(40, 26, 24, 470, 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', 'waqāla firʿawunu dharūnī ʾaqtul mūsā walyadʿu rabbahū ʾinnī ʾakhāfu ʾan yubaddila dīnakum ʾaw ʾan yuẓhira fī l-ʾarḍi l-fasāda', 'Firavun şöyle dedi: "Bırakın beni, Mûsâ''yı öldüreyim de Rabbine yalvarsın! Ben, onun dininizi değiştirmesinden yahut yeryüzünde fesat çıkarmasından korkuyorum."'),
(40, 27, 24, 470, 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', 'wa qāla mūsā innī ʿudhtu birabbī wa rabbikum min kulli mutakabbirin lā yuʾminu biyawmi l-ḥisābi', 'Musa dedi ki: "Ben, hesap gününe inanmayan her kibirliden, benim de Rabbime ve sizin de Rabbinize sığınırım."'),
(40, 28, 24, 470, 'وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ وَإِن يَكُ كَٰذِبًا فَعَلَيْهِ كَذِبُهُۥ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', 'waqāla rajulun muʾminun min ʾāli firʿawna yaktumu ʾīmānahu ʾataqtulūna rajulan ʾan yaqūla rabbiyya ʾallāhu waqad jāʾakum bilbayyināti min rabbikum waʾin yaku kādhiban fāʿalayhi kadhibuhu waʾin yaku ṣādiqan yuṣibkum baʿḍu ʾalladhī yaʿidukum ʾinna ʾallāha lā yahdī man huwa musrifun kadhdhābun', 'Firavun ailesinden, imanını gizleyen mümin bir adam şöyle dedi: "Bir adamı, ''Rabbim Allah''tır'' dediği için mi öldüreceksiniz? Oysa o size Rabbinizden açık delillerle gelmiştir. Eğer yalancı ise yalanı kendi aleyhinedir. Eğer doğru sözlü ise, sizi tehdit ettiği azabın bir kısmı size isabet eder. Şüphesiz Allah, aşırı giden yalancıyı doğru yola iletmez."'),
(40, 29, 24, 470, 'يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', 'yā qawmi lakumu l-mulku l-yawma ẓāhirīna fī l-arḍi fa-man yanṣurunā min baʾsi llāhi in jāʾanā qāla firʿawnu mā urīkum illā mā arā wa mā ahdīkum illā sabīla r-rashādi', 'Ey kavmim! Bugün mülk sizindir, yeryüzünde siz üstünsünüz. Fakat azabımız geliverirse, bize kim yardım eder? Firavun dedi ki: Ben size ancak gördüğümü gösteriyorum ve sizi ancak doğru yola irşad ediyorum.'),
(40, 30, 24, 470, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', 'waqāla lladhī ʾāmana yā qawmi ʾinnī ʾakhāfu ʿalaykum mithla yawmi lʾaḥzāb', 'İman etmiş olan adam dedi ki: "Ey kavmim! Şüphesiz ben, (geçmiş) toplulukların günlerindeki gibi bir günün sizin başınıza gelmesinden korkuyorum."'),
(40, 31, 24, 470, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ', 'mithla daʾbi qawmi nūḥin wa ʿādin wathamūda wa-lladhīna min baʿdihim wa mā allāhu yurīdu ẓulman lil-ʿibād', 'Nuh kavminin, Âd ve Semûd''un ve onlardan sonra gelenlerin gidişi gibi. Allah kullara zulmetmek istemez.'),
(40, 32, 24, 470, 'وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', 'wa yā qawmi innī ʾakhāfu ʿalaykum yawma t-tanādi', 'Ey kavmim! Ben sizin için o (büyük) günü, (birbirinizi) çağrışma gününü düşünüyorum.'),
(40, 33, 24, 470, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 'yawma tuwallūna mudbirīn mā lakum minallāhi min ʿāṣim wa man yuḍlili -llāhu fa-mā lahū min hād', 'O gün, geriye dönüp kaçacaksınız. Sizi Allah''tan koruyacak hiç kimse yoktur. Allah''ın saptırdığı kimseye de yol gösterici bulunmaz.'),
(40, 34, 24, 471, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ', 'Ve lekad câekum Yûsufu min kablu bilbeyyinâti femâ ziltum fî şekkin mimmâ câekum bihî hattâ izâ heleke kultum len yeb''asallâhu min ba''dihî resûlâ kezâlike yudillullâhu men huve musrifun murtâb', 'Andolsun ki daha önce Yusuf da size apaçık delillerle gelmişti de onun size getirdiği şeyler hakkında şüphe içinde kalmıştınız. Nihayet o ölünce de: "Allah ondan sonra asla bir elçi göndermeyecektir" demiştiniz. İşte Allah, haddi aşan, şüpheci kimseyi böyle saptırır.'),
(40, 35, 24, 471, 'ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', 'alladhīna yujādilūna fī ʾāyāti llāhi bighayri sulṭānin ʾatāhum kabura maqtan ʿinda llāhi waʿinda lladhīna ʾāmanū kadhālika yaṭbaʿu llāhu ʿalā kulli qalbi mutakabbirin jabbārin', 'Kendilerine gelmiş bir delil olmaksızın Allah''ın âyetleri hakkında tartışanlar, nezdinde büyük bir gazaba uğrarlar. İşte Allah, her kibirli zorbanın kalbinin üzerine böyle mühür basar.'),
(40, 36, 24, 471, 'وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ', 'waqāla firʿawnu yā hāmāna ibni lī ṣarḥan laʿallī ʾabluġu l-ʾasbāb', 'Firavun dedi ki: "Ey Hâmân! Bana yüksek bir kule yap; belki yollara, göklerin yollarına ulaşırım.'),
(40, 37, 24, 471, 'أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًا وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ', 'asbāba s-samāwāti faʾaṭṭaliʿa ʾilā ʾilāhi Mūsā waʾinnī laʾaẓunnuḥū kādhiban wa kaḏālika zuyyina li-firʿawna sūʾu ʿamalihi wa ṣudda ʿani s-sabīli wa mā kaydu firʿawna ʾillā fī tabābin', 'Göklerin yollarına (ulaşarak) Musa''nın ilahına muttali olayım. Şüphesiz ben onu yalancılardan sanıyorum." dedi. İşte böylece firavun''a yaptığı kötü işler süslü gösterildi ve (haktan) alıkonuldu. Firavun''un hileli düzeni ise tamamen bir ziyanda idi.'),
(40, 38, 24, 471, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', 'waqāla lladhī ʾāmana yā qawmi ttabiʿūnī ʾahdikum sabīla rrašādi', 'İman etmiş olan o kimse dedi ki: "Ey kavmim! Bana uyun, sizi doğru yola ileteyim."'),
(40, 39, 24, 471, 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌ وَإِنَّ ٱلْءَاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', 'yā qawmi innamā hādhihi l-ḥayātu d-dunyā matāʿun wa inna l-ʾākhirata hiya dāru l-qarāri', 'Ey kavmim! Bu dünya hayatı ancak geçici bir metadır (bir zevktir), şüphesiz ki ahiret yurdu ise kalıcı olan yurttur.'),
(40, 40, 24, 471, 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ', 'man ʿamila sayyiʾatan falā yujzā ʾillā miṯlahā wa-man ʿamila ṣāliḥan min ḏakarin ʾaw ʾunṯā wa-huwa muʾminun fa-ʾulāʾika yadḫulūna l-jannata yurzaqūna fīhā bi-ġayri ḥisābin', 'Kim bir kötülük yaparsa, onun kadar ceza görür. Kim de inanmış olarak er veya kadın, iyi bir iş yaparsa, işte onlar cennete girerler; orada onlara hesapsız rızık verilir.'),
(40, 41, 24, 472, 'وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', 'wa yā qawmi mā lī adʿūkum ilā an-najāti wa tadʿūnanī ilā an-nāri', 'Ey kavmim! Ben sizi (cennete götürecek) kurtuluşa davet ediyorum, siz ise beni ateşe davet ediyorsunuz.'),
(40, 42, 24, 472, 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ', 'tadʿūnanī li-ʾakfura bi-llāhi wa-ʾušrika bihi mā laysa lī bihi ʿilmun wa-ʾanā ʾadʿūkum ʾilā l-ʿazīzi l-ḡaffāri', 'Beni, Allah''ı inkâr edip hakkında bilgim olmayan şeyi O''na ortak koşmaya mı çağırıyorsunuz? Ben sizi, mutlak güç sahibi, çok bağışlayıcı olana çağırıyorum.'),
(40, 43, 24, 472, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى ٱلدُّنْيَا وَلَا فِى ٱلْءَاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ', 'lā jarama annamā tadʿūnanī ilayhi laysa lahū daʿwatun fī d-dunyā wa lā fī l-ʾākhirati wa anna maradanā ʾilā llāhi wa ʾanna l-musrifīna hum ʾaṣḥābu n-nāri', 'Şüphesiz sizin beni çağırdığınız şeyin dünyada da ahirette de bir daveti yoktur. Ve ancak Allah''adır dönüşümüz. Ve şüphesiz o israf edenler, ateşin yoldaşlarıdır.'),
(40, 44, 24, 472, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', 'fasataẕkurūna mā aqūlu lakum wa ufa wiḍu amrī ilā Allāh inna Allāha baṣīrun bil-ʿibād', 'Sizlere söylediğim şeyi ileride hatırlayacaksınız. Ben işimi Allah''a havale ediyorum. Şüphesiz Allah kullarını hakkıyla görendir.'),
(40, 45, 24, 472, 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', 'fawaqāhu-llāhu sayyi''āti mā makarū waḥāqa bi''āli fir''awna sū''u-l''aḏāb', 'Böylece Allah onu, kurdukları tuzakların kötülüğünden korudu. Firavun ailesini ise o korkunç azap kuşattı.'),
(40, 46, 24, 472, 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', 'An-nāru yuʿraḍūna ʿalayhā ġuduwwan wa ʿashiyyan Wa yawma taqūmu s-sāʿatu Adkhilū ʾāla firʿawna ʾashadda l-ʿaḏābi', 'Ateş; sabah akşam ona sunulurlar. Kıyamet koptuğu gün de: ''Firavun ailesini en şiddetli azaba sokun!'' denilir.'),
(40, 47, 24, 472, 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ ٱلنَّارِ', 'wa-ʾidh yataḥājjūna fī n-nār fa-yaqūlu ḍ-ḍuʿafāʾu l-ladhīna istakbarū ʾinnā kunnā lakum tabaʿan fa-hal ʾantum muġnūna ʿannā naṣīban mina n-nār', 'Onlar (birbirleriyle) ateşin içinde tartışırlarken, zayıf olanlar büyüklük taslayanlara şöyle derler: "Şüphesiz biz size tabi olmuştuk. Şimdi (bize) ateşten bir paydan bir nebze olsun kurtarabilecek misiniz?"'),
(40, 48, 24, 472, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', 'qāla lladhīna stakbarū innā kullun fīhā ʾinna llāha qad ḥakama bayna l-ʿibād', 'İçlerinde büyüklük taslayanlar şöyle dediler: "Doğrusu hepimiz onun içindeyiz. Şüphesiz Allah kullar arasında hükmünü vermiştir."'),
(40, 49, 24, 472, 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ ٱلْعَذَابِ', 'waqāla lladhīna fī n-nāri likhazanati jahannama udʿū rabbakum yukhaffif ʿannā yawman mina l-ʿadhābi', 'Cehennemlikler, cehennem bekçilerine: "Rabbinize yalvarın da, bizden bir gün azabı hafifletsin" dediler.'),
(40, 50, 24, 473, 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ قَالُوا۟ بَلَىٰ قَالُوا۟ فَٱدْعُوا۟ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'qālū ʾa-wa-lam taku taʾtīkum rusulukum bi-l-bayyināti qālū balā qālū fa-dʿū wa-mā duʿāʾu l-kāfirīna ʾillā fī ḍalālin', 'Dediler ki: "Resulleriniz size apaçık delillerle gelmedi mi?" (Diğerleri) "Evet, geldi!" dediler. (İlk grup) "Öyleyse (artık) dua edin! Allah kâfirlerin duasından başkasını boşuna çıkarmayacaktır!" dediler.'),
(40, 51, 24, 473, 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ', 'innā lananṣuru rusulanā wallaḏīna ʾāmanū fīl-ḥayāti d-dunyā wa yawma yaqūmu l-ʾašhād', 'Şüphesiz biz, peygamberlerimize ve iman edenlere hem dünya hayatında hem de şahitlerin (hakikatin) ortaya çıkacağı günde mutlaka yardım ederiz.'),
(40, 52, 24, 473, 'يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 'yawma lā yanfaʿu ẓ-ẓālimīna maʿẕiratuhum wa lahumu l-laʿnatu wa lahum sūʾu d-dāri', 'O gün, zalimlere ne özürleri fayda verir ne de lânet ve ne de o kötü yurt.'),
(40, 53, 24, 473, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ', 'Ve lekad āteynā Mūsā el-hudā ve evrasnā benī İsrāʾīle el-kitābe', 'Andolsun ki Musa''ya hidayeti verdik ve İsrailoğulları''na Kitab''ı miras bıraktık.'),
(40, 54, 24, 473, 'هُدًى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'hudan wa dhikra li''uli al-albab', 'Bu, basiret sahipleri için bir hidayet ve bir öğüttür.'),
(40, 55, 24, 473, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'faṣbir ʾinna waʿda llāhi ḥaqqun wastaghfir li-ḏanbika wa-sabbih bi-ḥamdi rabbika bi-l-ʿašiyyi wa-l-ʾibkāri', 'Şimdi sabret. Şüphesiz Allah''ın vaadi haktır. Günahın için de mağfiret dile. Akşam ve sabah Rabbini hamd ile tesbih et.'),
(40, 56, 24, 473, 'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَٰلِغِيهِ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'ʾinna llaḏīna yujādilūna fī ʾāyāti llaāhi biġayri sulṭānin ʾatāhum ʾin fī ṣudūrihim ʾillā kibrun mā hum bibāliġīhi fa-staʿiḏ billāhi ʾinnahu huwa s-samīʿu l-baṣīru', 'Şüphesiz, kendilerine gelmiş bir delil olmaksızın Allah''ın âyetleri hakkında tartışanların göğüslerinde, ulaşamayacakları bir büyüklükten başka bir şey yoktur. Sen hemen Allah''a sığın. Şüphesiz O, hakkıyla işiten, hakkıyla görendir.'),
(40, 57, 24, 473, 'لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'laḫalqu s-samāwāti wa-l-arḍi akbaru min ḫalqi n-nāsi wa-lākinna akṯara n-nāsi lā yaʿlamūn', 'Gökleri ve yeri yaratmak, insanları yaratmaktan daha büyüktür; fakat insanların çoğu bilmezler.'),
(40, 58, 24, 473, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ قَلِيلًا مَّا تَتَذَكَّرُونَ', 'wa mā yastawī l-aʿmā wa-l-baṣīr wa-lladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāt wa lā l-musīʾu qalīlan mā tataḏakkarūn', 'Kör ile gören, iman edip salih amel işleyenlerle kötü iş yapan bir olmaz. Ne kadar az düşünüyorsunuz!'),
(40, 59, 24, 474, 'إِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'inna s-sāʿata laʾātiyatun lā rayba fīhā wa-lākinna ʾakthara n-nāsi lā yuʾminūn', 'Şüphesiz kıyamet saati mutlaka gelecektir; bunda hiçbir şüphe yoktur. Fakat insanların çoğu inanmıyorlar.'),
(40, 60, 24, 474, 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', 'waqāla rabbukumudʿūnī ʾastajib lakum ʾinna llaḏīna yastakbirūna ʿan ʿibādatī sayadkhulūna jahannama dākhirīn', 'Rabbiniz şöyle buyurdu: Bana dua edin, size icabet edeyim. Şüphesiz bana kulluk etmekten yüz çevirenler, horlanmış bir halde cehenneme gireceklerdir.'),
(40, 61, 24, 474, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'Allāhu alladhī jaʿala lakumu l-layla litaskunū fīhi wa-n-nahāra mubṣiran ʾInna Allāha ladhū faḍlin ʿalā n-nāsi Wa-lākinna ʾakthara n-nāsi lā yashkurūn', 'Allah, geceyi size dinlenmeniz için, gündüzü de aydınlatıcı olarak yaratandır. Şüphesiz Allah, insanlara karşı lütuf sahibidir. Fakat insanların çoğu şükretmez.'),
(40, 62, 24, 474, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', 'dhālikumu llāhu rabbukum khāliqu kulli shayʾin lā ilāha illā huwa faʾannā tuʾfakūna', 'İşte Allah sizin Rabbinizdir. O, her şeyin yaratıcısıdır. O''ndan başka ilah yoktur. Bu halde nasıl olur da (haktan) çevrilirsiniz?'),
(40, 63, 24, 474, 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 'kadhālika yuʾfaku alladhīna kānū bi-ʾāyāti llāhi yajḥadūn', 'İşte böyle çevrilir (hakka inanmaktan vazgeçer) Allah''ın ayetlerini inkâr edenler.'),
(40, 64, 24, 474, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًا وَٱلسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'Allāhu alladhī jaʿala lakumu l-arḍa qarāran wa-s-samāʾa bināʾan wa-ṣawwarakum fa-aḥsana ṣuwarakum wa-razaqakum mina ṭ-ṭayyibāt Dhālikumu llāhu rabbukum fa-tabāraka llāhu rabbu l-ʿālamīn', 'Allah, yeryüzünü sizin için bir durak (karar) kıldı, göğü de bir tavan (bina) yaptı. Size en güzel şekli verdi ve sizi iyi ve temiz şeylerle rızıklandırdı. İşte Allah sizin Rabbinizdir. Âlemlerin Rabbi olan Allah, ne yücedir!'),
(40, 65, 24, 474, 'هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'huwa l-ḥayyu lā ilāha illā huwa fa-dʿūhu mukhliṣīna lahu d-dīna l-ḥamdu li-llāhi rabbi l-ʿālamīna', 'O, daima diridir; O''ndan başka ilah yoktur. Dini yalnız O''na halis kılarak O''na dua edin. Hamd, âlemlerin Rabbi Allah''a mahsustur.'),
(40, 66, 24, 474, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'qul innī nuhītu an aʿbuda lladhīna tadʿūna min dūni llāh lammā jāʾaniya lbayyinātu min rabbī wa ʾumirtu an ʾuslima lirabbi lʿālamīn', 'De ki: "Ben, Rabbimden açık deliller gelince, Allah''ı bırakıp da sizin tapmakta olduğunuz şeylere tapmaktan nehyolundum ve alemlerin Rabbine teslim olmakla emrolundum."'),
(40, 67, 24, 475, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًا وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ وَلِتَبْلُغُوٓا۟ أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', 'huwa alladhī khalaqakum min turābin thumma min nuṭfatin thumma min ʿalaqatin thumma yukhrijukum ṭiflan thumma litablugū ʾashuddakum thumma litakūnū shuyūkhan waminakum man yutawaffā min qablu walitablugū ajalan musamman walʿallakum taʿqilūn', 'Sizi topraktan, sonra nutfeden, sonra alakadan yaratan, sonra sizi bebek olarak çıkaran, sonra güçlü kuvvetli olmanız için yaşatan, sonra da ihtiyarlamanız için (yaşatan) ve içinizden daha önce vefat ettirilecekler de vardır. Ve belirlenmiş bir süreye ulaşmanız ve akıl etmeniz için (bunları yapar).'),
(40, 68, 24, 475, 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'huwa lladhī yuḥyī wa yumītu fa-idhā qaḍā amran fa-innamā yaqūlu lahu kun fa-yakūnu', 'O, sizi topraktan, sonra bir damla sudan, sonra bir embriyodan yaratan, sonra sizi çocuk olarak çıkaran, sonra sizi olgunluk çağına ulaştıran, sonra da yaşlanıp ölen, içinizden de daha önce ölmüş olanlar bulunan, işte budur. O, bir şeyin yaratılmasını takdir etti mi, ona sadece "Ol!" der, o da oluverir.'),
(40, 69, 24, 475, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', 'ʾalam tara ʾilā alladhīna yujādilūna fī ʾāyāti llāhi ʾannā yuṣrafūna', 'Allah''ın ayetleri hakkında tartışanları görmedin mi? Nasıl da (gerçekten) çevriliyorlar!'),
(40, 70, 24, 475, 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ', 'alladhīna kadhdhabū bil-kitābi wa bimā arsálnā bihi rusulanā fasawfa yaʿlamūn', 'Onlar, Kitabı ve peygamberlerimizi gönderdiğimiz şeyleri yalanlayanlardır. Artık onlar bilecekler.'),
(40, 71, 24, 475, 'إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ', 'iḏi l-ʾaġlālu fī ʾaʿnāqihim wa-s-salāsilu yusḥabūn', 'O zaman (o) demir halkalar boyunlarında ve (o) zincirler(le) sürüklenirler.'),
(40, 72, 24, 475, 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', 'fī l-ḥamīmi thumma fī n-nāri yusjarūna', 'Kaynar su içinde, sonra ateşte yakılırlar.'),
(40, 73, 24, 475, 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', 'thumma qīla lahum ʾayna mā kuntum tušrikūn', 'Sonra onlara denildi ki: "Allah''a koştuğunuz ortaklar nerede?"'),
(40, 74, 24, 475, 'مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًٔا كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ', 'min dūni llāh qālū ḍallū ʿannā bal lam nakun nadʿū min qablu šayʾan kaḏālika yuḍillu llāhu lkāfirīn', 'Allah''tan başka taptıklarınızdan sorulacak olursa, derler ki: ''Bizden öncekiler sapıtmışlardı. Onların taptıkları şeyler, biz onlara tapmadan önce de bizi doğru yola iletmiyorlardı.'' İşte Allah, kâfirleri böyle saptırır.'),
(40, 75, 24, 475, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', 'dhālikum bimā kuntum tafraḥūna fī l-arḍi bighayri l-ḥaqqi wa bimā kuntum tamraḥūn', 'Bu, yeryüzünde haksız yere sevindiğiniz ve böbürlenip durduğunuzdan dolayıdır.'),
(40, 76, 24, 475, 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'udkhulū abwāba jahannama khālidīna fīhā fabia''sa mathwā al-mutakabbirīn', 'Cehennem kapılarından, içinde ebedi kalıcılar olarak girin! Kibirlenenlerin ne kötü bir kalma yeridir!'),
(40, 77, 24, 475, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', 'faṣbir ʾinna waʿda llāhi ḥaqqun faʾimmā nuriyannaka baʿḍa lladhī naʿiduhum ʾaw natawaffayannaka faʾilaynā yurjaʿūna', 'Sabret! Şüphesiz Allah''ın vaadi haktır. Onlara vaat ettiğimizin bir kısmını sana göstersek de, yahut (göstermeden) seni vefat ettirsek de, nihayet bize döndürüleceklerdir.'),
(40, 78, 24, 476, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', 'Ve lekad erselnâ rusulen min kablike minhum men kasasnâ aleyke ve minhum men lem naksus aleyke Ve mâ kâne li resûlin en ye''tiye bi âyetin illâ bi iznillâhi Fe izâ câe emrullâhi kudıye bil hakkı ve hasire hunâlikel mubtılûn(mubtılûne)', 'Andolsun ki senden önce de nice resûller gönderdik. Onlardan kimini sana anlattık, kimini de anlatmadık. Hiçbir resûl, Allah’ın izni olmaksızın bir mucize getiremez. Allah’ın emri geldiğinde ise hak ile hükmedilir ve işte o zaman bâtılı savunanlar hüsrana uğrarlar.'),
(40, 79, 24, 476, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', 'Allāhu alladhī jaʿala lakumu l-anʿāma litarkabū min''hā wa min''hā taʾkulūna', 'Allah, hayvanları sizin için yaratmıştır; onlardan kimini binek edinir, kimini de yersiniz.'),
(40, 80, 24, 476, 'وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'wa lakum fīhā manāfiʿu wa li-tablughū ʿalayhā ḥājatan fī ṣudūrikum wa ʿalayhā wa ʿalā l-fulki tuḥmalūna', 'Onlarda sizin için daha nice faydalar vardır ve onların (veya onların üstündeki gemilerin) sayesinde göğüslerinizde (arzuladığınız) bir şeye ulaşasınız diye (onlar yaratılmıştır). Ve onların üzerine ve gemiler üzerine taşınırsınız.'),
(40, 81, 24, 476, 'وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ', 'wa yurīkum ʾāyātihi fa ʾayya ʾāyāti llāhi tunkiirūn', 'O, size ayetlerini gösterir. Allah''ın ayetlerinden hangisini inkar ediyorsunuz?'),
(40, 82, 24, 476, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'ʾa-fa-lam yasīrū fī l-ʾarḍi fa-yanẓurū kayfa kāna ʿāqibatu l-ladhīna min qablihim kānū ʾakthara minhum wa-ʾashadda quwwatan wa-ʾāthāran fī l-ʾarḍi fa-mā ʾaghnā ʿanhum mā kānū yaksibūn', 'Yeryüzünde dolaşıp da kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Onlar, bunlardan daha çok ve daha kuvvetli idiler ve yeryüzünde daha çok eser bırakmışlardı. Ama kazandıkları kendilerinden hiçbir şeyi sağlamadı.'),
(40, 83, 24, 476, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'fe-lemmā jāʾethum rusuluhum bil-bayyināti feriḥū bimā ʿindahum min al-ʿilmi wa ḥāqa bihim mā kānū bihī yastahziʾūna', 'Onlara peygamberleri apaçık delillerle geldiğinde, yanlarındaki bilgiden dolayı sevindiler. Oysa alay etmekte oldukları şey (azap) onları kuşatmıştır.'),
(40, 84, 24, 476, 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', 'fe-lemmā raʾaw baʾsenā qālūʾ ʾāmannā bi-llāhi waḥdehu wa-kafarnā bimā kunnā bihi muhlirīn', 'Vardığımız azabı gördükleri zaman, dediler ki: "Allah''a, O''nun birliğine inandık ve daha önce O''na koştuğumuz ortakları tanımadık."'),
(40, 85, 24, 476, 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ', 'fe-lem yeku yenfeʿuhum īmānuhum lammā raʾaw baʾsanā sunnata ʾllāhi llatī qad ḵalat fī ʿibādihī wa-ḵasira hunālika l-kāfirūn', 'Nihayet azabımızı gördükleri zaman imanları kendilerine hiçbir fayda vermedi. Allah''ın (ezelî ve<bos>î) kanunu budur; kulları hakkında (bu kanun) cari olmuştur. İşte o zaman kâfirler hüsrana uğradılar.'),
(41, 1, 24, 477, 'حمٓ', 'ḥa mīm', 'Ha, Mim.'),
(41, 2, 24, 477, 'تَنزِيلٌ مِّنَ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'tanzīlun mina r-raḥmāni r-raḥīm', 'O, Rahman ve Rahim olan Allah''tan indirilmiştir.'),
(41, 3, 24, 477, 'كِتَٰبٌ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ', 'kitābun fuṣṣilat ʾāyātuhu qurʾānan ʿarabiyyan li-qawmin yaʿlamūn', 'Kendisine ait ayetler Arapça bir Kur''an olarak, bilen bir topluluk için ayrı ayrı açıklanmıştır.'),
(41, 4, 24, 477, 'بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 'bashīran wa nadhīran fa-aʿraḍa aktharuhum fa-hum lā yasmaʿūn', 'Müjdeleyici ve uyarıcı olarak (gönderdik). Ama çoğu yüz çevirdi; onlar işitmezler.'),
(41, 5, 24, 477, 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَٱعْمَلْ إِنَّنَا عَٰمِلُونَ', 'wa qālū qulūbunā fī ʾakinna-tin mimmā tadʿūnā ʾilayhi wa fī ʾāḏāninā waqrun wa min bayninā wa baynika ḥijābun fa-ʿmal ʾinnanā ʿāmilūn', 'Dediler ki: ''Kalplerimiz, bizi çağırdığın şeyin perdesi ardındadır. Kulaklarımızda bir ağırlık var. Hem bizimle senin aranda bir perde var. Artık sen kendi yoluna git, biz de kendi yolumuza gidiyoruz.'''),
(41, 6, 24, 477, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ وَوَيْلٌ لِّلْمُشْرِكِينَ', 'qul innemā anā başarun miṯlukum yūḥā ilayya ennemā ilāhukum ilāhun wāḥidun fastaqīmū ilayhi wastaġfirūhu wawailun lilmuşrikīn', 'De ki: "Ben de ancak sizin gibi bir beşerim. Bana, ilâhınızın ancak bir tek ilâh olduğu vahyolunuyor. Artık O''na yönelin ve O''ndan mağfiret dileyin. Vay haline o ortak koşanların!"'),
(41, 7, 24, 477, 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 'alladhīna lā yuʾtūna z-zakāta wa hum bi-l-ʾākhirati hum kāfirūna', 'Onlar, zekât vermeyenler ve ahireti inkâr edenlerdir.'),
(41, 8, 24, 477, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 'inna alladhīna ʾāmanū wa ʿamilū aṣ-ṣāliḥāti lahum ʾajrun ghayru mamnūnin', 'İman edip salih amel işleyenlere gelince, onlara kesintisiz bir ecir vardır.'),
(41, 9, 24, 477, 'قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًا ذَٰلِكَ رَبُّ ٱلْعَٰلَمِينَ', 'qul ʾaʾinnakum latakfurūna billadhī khalaqa l-ʾarḍa fī yawmayni watatjaʿalūna lahu ʾandādā dhālika rabbul-ʿālamīn', 'De ki: "Siz gerçekten, yeri iki günde yaratanı inkâr edip O’na ortaklar mı koşuyorsunuz? İşte O, âlemlerin Rabbidir."'),
(41, 10, 24, 477, 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ', 'wa jaʿala fīhā rawāsīya min fawqihā wa bāraka fīhā wa qaddara fīhā aqwātahā fī ʾarbaʿati ʾayyāmin sawāʾan lis-sāʾilīn', 'O, yeryüzünde dağlar yarattı ve onu bereketli kıldı; orada (her canlı için) rızıklarını takdir etti. Bütün bunları (isteyip) soranlar için dört günde tamamladı.'),
(41, 11, 24, 477, 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَآ أَتَيْنَا طَآئِعِينَ', 'thumma-stawā ʾilā-s-samāʾi wa-hiya dukhānun fa-qāla lahā wa-li-l-ʾarḍi ʾtiyā ṭawʿan ʾaw karhan qālatā ʾataynā ṭāʾiʿīn', 'Sonra göğe yöneldi; duman halinde olan göğe. Ona ve yeryüzüne: "İsteyerek veya istemeyerek gelin!" dedi. İkisi de: "İsteyerek geldik!" dediler.'),
(41, 12, 24, 478, 'فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَحِفْظًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'faqadāhunna sabʿa samāwātin fī yawmayni waʾawḥā fī kulli samāʾin ʾamrahā wazayyanā s-samāʾa d-dunyā bimaṣābīḥa waḥifẓan ḏālika t-taqdiru l-ʿazīzi l-ʿalīmi', 'Böylece onlara, iki gün içinde yedi göğü tamamladı ve her göğe görevini vahyetti. Ve biz dünya göğünü kandillerle süsledik ve onu koruduk. İşte bu, mutlak güç sahibi, hakkıyla bilen Allah''ın takdiridir.'),
(41, 13, 24, 478, 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةً مِّثْلَ صَٰعِقَةِ عَادٍ وَثَمُودَ', 'fa-in aʿraḍū fa-qul anḏartukum ṣāʿiqatan miṯla ṣāʿiqati ʿādin wa-ṯamūd', 'Yüz çevirirlerse, de ki: ''Ben sizi ''Ad ve Semûd kavimlerinin başına gelen (o korkunç azap) gibi bir azapla uyardım.'''),
(41, 14, 24, 478, 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةً فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'iḏ ǧāʾathumu r-rusulu min bayni ʾaydīhim wa-min ḫalfihim ʾallā taʿbudū ʾillā llāh qālū law šāʾa rabbunā la-ʾanzala malāʾikatan fa-ʾinnā bimā ʾursiltum bihi kāfirūn', 'Hani onlara önlerinden ve arkalarından (gelerek) şöyle demişti: ''Allah''tan başkasına tapmayın!'' Dediler ki: ''Eğer Rabbimiz dileseydi, mutlaka melekler indirirdi. Bu yüzden biz sizinle gönderilenlere inanmıyoruz.'''),
(41, 15, 24, 478, 'فَأَمَّا عَادٌ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً وَكَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'Fa''ammā ʿādun fastakbarū fī l-arḍi bighayri l-ḥaqqi Wa qālū man ʾashaddu minnā quwwatan ʾAwa lam yaraw ʾanna Llāha l-ladhī khalaqahum huwa ʾashaddu minhum quwwatan Wa kānū bi-ʾāyātinā yajḥadūna', 'Ad topluluğuna gelince; onlar yeryüzünde haksız yere büyüklendiler ve "Bizden daha güçlü kim var?" dediler. Onlar, kendilerini yaratan Allah''ın kendilerinden daha güçlü olduğunu görmüyorlar mıydı? Onlar bizim ayetlerimizi inkar ediyorlardı.'),
(41, 16, 24, 478, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِىٓ أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْءَاخِرَةِ أَخْزَىٰ وَهُمْ لَا يُنصَرُونَ', 'faʾarsalnā ʿalayhim rīḥan ṣarṣaran fī ʾayyāmin naḥisātin linuḏīqahum ʿaḏāba l-ḥizyi fī l-ḥayāti d-dunyā walaʿaḏābu l-ʾākhirati ʾakhzā wahum lā yunṣarūn', 'Derken onlara o uğursuz günlerde dondurucu bir rüzgâr gönderdik. Böylece dünya hayatında onlara (o) rezillik azabını tattırdık. Elbette ahiret azabı daha rezil edicidir ve onlar yardım göremezler.'),
(41, 17, 24, 478, 'وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', 'waʾammā th-mūdu fahadaynāhum fa-stahabbū l-ʿamā ʿalā l-hudā fa-ʾakhadhat-hum ṣāʿiqatu l-ʿadhābi l-hūni bimā kānū yaksibūn', 'Semûd’a gelince, onlara yol göstermiştik, fakat körlüğü hidayete tercih etmişlerdi. Bu yüzden, kazanmakta oldukları şeyleri yüzünden onları alçaltıcı azap yıldırımı yakaladı.'),
(41, 18, 24, 478, 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'wa najjaynā alladhīna āmānū wa kānū yattaqūn', 'İman edip takva sahibi olanları kurtardık.'),
(41, 19, 24, 478, 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', 'wa-yawma yuḥsharu ʾaʿdāʾu ʾllāhi ʾilā n-nāri fa-hum yūzaʿūn', 'Allah''ın düşmanları ateşe toplanacağı gün, işte o zaman hepsi bir araya getirilir.'),
(41, 20, 24, 478, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'ḥattā ʾiḏā mā jāʾūhā šahida ʿalayhim samʿuhum wa-ʾabṣāruhum wa-julūduhum bimā kānū yaʿmalūn', 'Nihayet oraya geldiklerinde, kulakları, gözleri ve derileri, yaptıkları yüzünden aleyhlerine şahitlik edecektir.'),
(41, 21, 24, 479, 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ', 'wa qālū li-julūdihim lima shahidtum ʿalaynā qālū anṭaqanā Allāhu alladhī anṭaqa kulla shayʾin wa huwa khalaqakum awwala marratin wa ilayhi turjaʿūna', 'Onlar derilerine: ''Neden aleyhimize şahitlik ettiniz?'' dediler. Derileri: ''Bizi konuşturdu, her şeyi konuşturup yaratan Allah, sizi ilk defa yaratan da O''dur ve O''na döndürüleceksiniz'' dediler.'),
(41, 22, 24, 479, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ', 'wa mā kuntum tastatirūna an yashhada ʿalaykum samʿukum walā ʾabsārukum walā julūdukum walākin ẓanantum ʾanna ʾllāha lā yaʿlamu kaṯīran mimmā taʿmalūn', 'Oysa siz, kulaklarınızın, gözlerinizin ve derilerinizin aleyhinize tanıklık etmesinden çekiniyor (saklanıyordunuz). Lakin siz, yaptıklarınızın çoğunu Allah''ın bilmediğini sanmıştınız.'),
(41, 23, 24, 479, 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ', 'wa dhālikum ẓannukumulladhī ẓanantum birabbikum ardkum faʾaṣbaḥtum minal-khāsirīn', 'İşte bu sizin Rabbiniz hakkındaki zannınızdır ki sizi helâke sürüklemiştir. Böylece hüsrana uğrayanlardan oldunuz.'),
(41, 24, 24, 479, 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', 'fa-ʾin yaṣbirū fa-l-nāru maṯwan lahum wa-ʾin yastaʿtibū fa-mā hum mina l-muʿtabīn', 'Eğer sabrederlerse, ateş onların barınağıdır. Eğer hoşnutluklarını kazanmaya çalışırlarsa, onlardan hoşnutluk duyulacak kimseler değillerdir.'),
(41, 25, 24, 479, 'وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'wa qayyaḍnā lahum quranaāʾa fa zayyanū lahum mā bayna aydīhim wa mā khalfahum wa ḥaqqa ʿalayhimu l-qawlu fī ʾumamin qad khalat min qablihim mina l-jinni wal-ʾinsi ʾinnahum kānū khāsirīna', 'Onlara birtakım arkadaş (şeytanlar) tayin ettik de onlar, ellerinin önündeki (dünyadaki işlerini) ve arkalarındaki (geleceklerini) süsleyip (kötü göstermişlerdir). Ve cinlerden ve insanlardan kendilerinden önce geçmiş ümmetler (topluluklar) hakkında (gerçekleşmesi) vacip olan azap sözü, onların da aleyhine gerçekleşti. Çünkü onlar hüsrana uğrayanlardı.'),
(41, 26, 24, 479, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', 'waqāla alladhīna kafarū lā tasmaʿū lihadhā alqurʾāni walghaw fīhi laʿallakum taghlibūna', 'İnkâr edenler şöyle dediler: ''Bu Kur''an''ı dinlemeyin ve o okunurken yaygara koparın ki belki üstün gelirsiniz.'''),
(41, 27, 24, 479, 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'falānuḏīqanna llaḏīna kafarū ʿaḏāban šadīdā walā najziannahum aswaʾa llaḏī kānū yaʿmalūn', 'Böylece o kâfirlere şiddetli azabı tattıracağız ve onları, yapmakta oldukları şeylerin en kötüsüyle cezalandıracağız.'),
(41, 28, 24, 479, 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'dhālika jazāʾu ʾaʿdāʾi ʾllāhi ʾn-nāru lahum fīhā dāru ʾl-khuldi jazāʾam bimā kānū bi-ʾāyātinā yajḥadūna', 'İşte Allah düşmanlarının cezası ateştir. Onlar için orada, âyetlerimizi inkâr etmelerine karşılık ebedî bir yurt vardır.'),
(41, 29, 24, 479, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', 'waqāla alladhīna kafarū rabbanā arinā alladhayni aḍallānā min al-jinni wal-insi najʿalhumā taḥta aqdāminā liyakūnā min al-asfalīn', 'İnkâr edenler şöyle dediler: "Rabbimiz! Bizi saptıran cinlerden ve insanlardan olanları bize göster de onları ayaklarımızın altına alalım ki en aşağılardan olsunlar."'),
(41, 30, 24, 480, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'ʾinna llaḏīna qālū rabbunā ʾallāhu ṯumma starke qāmu tatanazzalu ʿalayhimu l-malāʾikatu ʾallā taḫāfū walā taḥzanū waʾabširū bil-jannati llatī kuntum tūʿadūna', 'Şüphesiz, "Rabbimiz Allah''tır" deyip de sonra dosdoğru olanlar var ya, onların üzerine korku yoktur ve onlar mahzun da olmayacaklardır. İşte onlar cennet ehlidir. Onlar, va''dedilmiş olmaları sebebiyle orada ebedî kalacaklardır.'),
(41, 31, 24, 480, 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 'naḥnu awliyāʾukum fī l-ḥayāti d-dunyā wa-fī l-ʾākhirati wa-lakum fīhā mā tashtahī ʾanfusukum wa-lakum fīhā mā taddaʿūn', 'Biz dünya hayatında da ahirette de sizin velileriniziz. Orada sizin için canlarınızın çektiği her şey vardır ve istediğiniz her şey de sizin içindir.'),
(41, 32, 24, 480, 'نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ', 'nuzulan min ghafūrin rahīm', 'Rahîm ve Gafûr olan Allah''tan bir ikram olarak.'),
(41, 33, 24, 480, 'وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', 'wa-man aḥsanu qawlan mimman daʿā ilā llāhi wa-ʿamila ṣāliḥan wa-qāla innani mina l-muslimīn', 'Allah''a davet eden, salih amel işleyen ve ''Ben Müslümanlardanım'' diyen kimden daha güzel sözlü olabilir? (Onun sözünden daha güzeli yoktur.)'),
(41, 34, 24, 480, 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ', 'wa lā tastawī l-ḥasanatu wa lā s-sayyiʾatu idfaʿ bi-llatī hiya ʾaḥsanu fa-ʾiḏā llaḏī baynaka wa baynahū ʿadāwatun ka-ʾannahū walīyun ḥamīmun', 'İyilikle kötülük bir olmaz. Sen, kötülüğü en güzel bir şekilde sav. O zaman seninle arasında düşmanlık bulunan kimse, sanki sıcak bir dost olur.'),
(41, 35, 24, 480, 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ', 'wa mā yulaqqāhā ʾillā alladhīna ṣabarū wa mā yulaqqāhā ʾillā dhū ḥaẓẓin ʿaẓīm', 'Bu (erdem) ancak sabreden kimselere verilir ve bu (erdem) ancak büyük nasip sahibi kimselere verilir.'),
(41, 36, 24, 480, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'wa-immā yanzagannaka mina sh-shayṭāni nazʿun fa-staʿidh bi-llāhi ʾinnahu huwa s-samīʿu l-ʿalīmu', 'Eğer seni şeytandan bir kışkırtma (vesvese) dürtecek olursa, hemen Allah''a sığın. Şüphesiz O, hakkıyla işitendir, bilendir.'),
(41, 37, 24, 480, 'وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'wa-min ʾāyātihi l-laylu wa-n-nahāru wa-š-šamsu wa-l-qamaru lā tasjudū li-š-šamsi wa-lā li-l-qamari wa-sjudū li-llāhi lladhī khalaqahunna ʾin kuntum ʾiyyāhu taʿbudūna', 'Gece, gündüz, güneş ve ay da O''nun delillerindendir. Güneşe ve aya secde etmeyin. Eğer O''na kulluk ediyorsanız, onları yaratan Allah''a secde edin.'),
(41, 38, 24, 480, 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ', 'fa-ʾini istakbarū fa-lladhīna ʿinda rabbika yusabbiḥūna lahu bi-llayli wa-n-nahāri wa-hum lā yasʾamūna', 'Eğer yine de büyüklük taslarlarsa, bilsinler ki Rabbinin katındaki (melekler) O''na gece ve gündüz hiç bıkmadan tesbih ederler.'),
(41, 39, 24, 481, 'وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'wa-min ʾāyātihi ʾannaka tarā l-ʾarḍa khāshiʿatan fa-ʾidhā ʾanzalnā ʿalayhā l-māʾa ihtazzat wa-rabat ʾinna lladhī ʾaḥyāhā la-muḥyī l-mawtā ʾinnahu ʿalā kulli shayʾin qadīr', 'Yeryüzünün kupkuru ve cansız olduğunu görmen de O''nun varlığının delillerindendir. Biz üzerine yağmuru indirdiğimizde, hemen harekete geçer ve kabarır. Şüphesiz O, cansızları da diriltir. O, her şeye hakkıyla gücü yetendir.'),
(41, 40, 24, 481, 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًا يَوْمَ ٱلْقِيَٰمَةِ ٱعْمَلُوا۟ مَا شِئْتُمْ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', 'ʾinna lladhīna yulḥidūna fī ʾāyātinā lā yakhfawna ʿalaynā ʾafaman yulqā fī n-nāri khayrun ʾam man yaʾtī ʾāminan yawma l-qiyāmati uʿmalū mā shiʾtum ʾinnahu bimā taʿmalūna baṣīrun', 'Şüphesiz ayetlerimizi eğip bükenler bize gizli kalmaz. Peki, ateşe atılan mı daha hayırlıdır, yoksa kıyamet günü güven içinde gelip duran mı? Dilediğinizi yapın! Şüphesiz O, yaptıklarınızı hakkıyla görmektedir.'),
(41, 41, 24, 481, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ', 'inna alladhīna kafarū bi-dh-dhikri lammā jāʾahum wa-innahū la-kitābun ʿazīz', 'Şüphesiz, kendilerine gelen Kuran''a (öğüt/zikir) inanmayanlar (bilsinler ki) o, gerçekten de üstün ve güçlü bir kitaptır.'),
(41, 42, 24, 481, 'لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ', 'lā yaʾtīhi l-bāṭilu min bayni yadayhi walā min khalfihī tanzīlun min ḥakīmin ḥamīdin', 'O, önünden de, ardından da batılın gelemiyeceği, hikmet sahibi, övülmüş olan tarafından indirilmiş bir kitaptır.'),
(41, 43, 24, 481, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ', 'mā yuqālu laka illā mā qad qīla lir-rusuli min qablika ʾinna rabbaka la-dhū maghfiratin wa-dhū ʿiqābin ʾalīmin', 'Sana söylenen yalnızca, senden önceki resullere söylenmiş olandır. Şüphesiz Rabbin hem bağışlama hem de elem dolu azap sahibi olandır.'),
(41, 44, 24, 481, 'وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ءَا۬عْجَمِىٌّ وَعَرَبِىٌّ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًى وَشِفَآءٌ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍ', 'wa-law jaʿalnāhu qurʾānan ʾaʿjamiyyan laqālū lawlā fuṣṣilat ʾāyātuhu ʾaʿjamiyyun wa-ʿarabiyyun qul huwa lilladhīna ʾāmanū hudan wa-shifāʾun wa-lladhīna lā yuʾminūna fī ʾādhānihim waqrun wa-huwa ʿalayhim ʿamā ʾulāʾika yunādawna min makānin baʿīdin', 'Eğer biz onu Arapça''dan başka bir dilde bir Kur''an yapsaydık, herhalde "Ayetleri niçin açıklanmamıştır? Arapça''dan başka bir dil mi ve Arap mı?" derlerdi. De ki: "O, iman edenler için bir hidayet ve şifadır. İman etmeyenlerin ise kulaklarında bir ağırlık vardır ve o (Kur''an) onlara göre bir körlüktür. İşte onlar (sanki) uzak bir yerden çağrılıyorlar."'),
(41, 45, 24, 481, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', 've lekad ʾātaynā mūsā l-kitāba fa-ukh''tulifa fīhi ve levlā kalimatun sabaqat min rabbika lequḍiya baynahum ve ʾinnahum lafī shakkin min''hu murībin', 'Andolsun ki Musa''ya Kitab''ı verdik de onda ayrılığa düşüldü. Eğer Rabbinden daha önce bir söz geçmemiş olsaydı, aralarında hüküm verilmişti. Şüphesiz onlar, ondan kuşku veren bir şüphe içindedirler.'),
(41, 46, 24, 481, 'مَّنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'man ʿamila ṣāliḥan faliynafsihi waman asāʾa faliynayhā wamā rabbuka bizallāmin lilʿabīd', 'Kim iyi bir iş yaparsa, kendi lehinedir. Kim de kötülük yaparsa, kendi aleyhinedir. Rabbin kullarına asla zulmedici değildir.'),
(41, 47, 25, 482, 'إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍ', 'ʾilayhi yuraddu ʿilmu s-sāʿah wa mā taḫruju min ṯamarātin min ʾakmāmihā wa mā taḥmilu min ʾunṯā wa lā taḍaʿu ʾillā bi-ʿilmihī wa yawma yunādīhim ʾayna ṯurakāʾī qālū ʾāḏannāka mā minnā min ṯahīd', 'Kıyamet saatinin ilmi O''na aittir. O''nun ilmi olmadan ne bir meyve tomurcuğundan çıkar, ne de bir dişi (yükünü) taşır ve ne de (vaktinden önce veya sonra) doğurur. O gün Allah onlara: ''Benim ortaklarım nerede?'' diye seslenir. Onlar: ''Sana hiçbir delil bırakmadığımızı (veya sana hiçbir şahidimiz olmadığını) sana arz ederiz'' derler.'),
(41, 48, 25, 482, 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍ', 'waḍalla ʿanhum mā kānū y adʿūna min qablu wa ẓannū mā lahum min maḥīṣin', 'Daha önce tapmakta oldukları şeyler onlardan kaybolup gitti ve kendileri için kaçıp kurtulacak bir yer olmadığını anladılar.'),
(41, 49, 25, 482, 'لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌ قَنُوطٌ', 'lā yasʾamu l-insānu min duʿāʾi l-khayri wa-in massahu sh-sharru fa-yaʾūsun qanūṭun', 'İnsan hayır istemekten bıkan, yorulmayan bir yapıdadır. Fakat ona bir şer dokunduğunda ise umutsuzluğa kapılan, karamsar kesilir.'),
(41, 50, 25, 482, 'وَلَئِنْ أَذَقْنَٰهُ رَحْمَةً مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ', 'Ve leʾin eẕaḳnāhu raḥmeten minnā min baʿdi ḍarrāʾe messethu leyaḳūlenne hāẕā lī vemā eẓunnü-ssāʿate ḳāʾimeh veleʾin ruciʿtü ilā rabbī inne lī ʿindehu lelḥusnā Felenünabbiʾenne-lleẕīne keferū bimā ʿamilū velenüẕīḳannehüm min ʿaẕābin ġalīẓ', 'Andolsun ki, eğer ona dokunan bir sıkıntıdan sonra katımızdan bir rahmet tattırırsak, mutlaka şöyle der: “Bu benim hakkımdır. Kıyametin kopacağını da sanmıyorum. Şayet Rabbime döndürülürsem, şüphesiz O’nun katında benim için daha güzeli vardır.” Biz de inkâr edenlere yaptıklarını mutlaka bildireceğiz ve onlara şiddetli bir azaptan tattıracağız.'),
(41, 51, 25, 482, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ', 'wa ʾidhā ʾanʿamnā ʿalā l-ʾinsāni ʾaʿraḍa wanaʾbijānibihi wa ʾidhā massahu ʾš-šarru faḏūduʿāʾin ʿarīḍin', 'İnsana bir nimet verdiğimizde (yüz çevirir) ve yan çizer. Kendisine bir şer dokunduğunda ise (bize) yalvarıp yakaran biridir.'),
(41, 52, 25, 482, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍ', 'qul ʾaraʾaytum ʾin kāna min ʿindi llāhi thumma kofartum bihi man ʾaḍallu mimman huwa fī shiqāqin baʿīd', 'De ki: ''Hiç düşündünüz mü? Eğer bu (Kur''an), Allah katından gelip de siz onu inkâr etmişseniz, o zaman derin bir ayrılık içinde bulunan kimseden daha sapık kim olabilir?'''),
(41, 53, 25, 482, 'سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْءَافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'Sanurīhim āyātinā fīl-āfāqi wa fī ʾanfusihim Ḥattā yatabayyana lahum ʾannehu l-ḥaqqu ʾAwa lam yakfi birabbika ʾannehu ʿalā kulli shayʾin shahīdun', 'Onlara hem ufuklarda hem de kendi nefislerinde ayetlerimizi göstereceğiz, ta ki kendilerine bunun hak olduğu açıkça belli olana kadar. Rabbinin, her şeye şahit olması yetmez mi?'),
(41, 54, 25, 482, 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍ مُّحِيطٌۢ', 'ʾalā ʾinnahum fī miryatin min liqāʾi rabbihim ʾalā ʾinnahuu bikulli shayʾin muḥīṭun', 'Gözünüz aydın! Onlar, Rablerine kavuşma konusunda şüphe içindedirler. Gözünüz aydın! O, her şeyi kuşatmıştır.'),
(42, 1, 25, 483, 'حمٓ', 'Hâ, Mîm', 'Hâ, Mîm.'),
(42, 2, 25, 483, 'عٓسٓقٓ', 'ʿAsq', 'Hâ, Mîm, Ayn, Sîn, Kaf.'),
(42, 3, 25, 483, 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'kadhālika yūḥī ilayka wa-ilā alladhīna min qablika allāhu l-ʿazīzu l-ḥakīmu', 'İşte böyle; aziz, hikmet sahibi Allah, sana ve senden öncekilere vahyetmektedir.'),
(42, 4, 25, 483, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'lahū mā fī s-samāwāti wa mā fī l-arḍi wa huwa l-ʿaliyyu l-ʿaẓīmu', 'Göklerde ve yerde ne varsa hepsi O''nundur. O, yücedir, azamet sahibidir.'),
(42, 5, 25, 483, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ وَٱلْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'takādu s-samāwātu yetafaṭṭarna min fawqihinna wa-l-malāʾikatu yusabbiḥūna bi-ḥamdi rabbihim wa-yastaġfirūna liman fī l-arḍi ʾalā ʾinna Llāha huwa l-ġafūru ʾr-raḥīmu', 'Neredeyse gökler, üstlerinden çatlayacaklar. Melekler de Rablerini hamd ile tesbih ederler ve yeryüzündekiler için istiğfar ederler. Haberiniz olsun ki, Allah, evet O, Gafur''dur, Rahim''dir.'),
(42, 6, 25, 483, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 'wa-lladhīna-ttakhadhū min dūnihi ʾawliyāʾa allāhu ḥafīẓun ʿalayhim wa-mā ʾanta ʿalayhim bi-wakīlin', 'Onlardan başkasını veliler edinenler (var ya), Allah onların üzerlerinde gözetleyicidir. Sen onlara vekil değilsin.'),
(42, 7, 25, 483, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِى ٱلْجَنَّةِ وَفَرِيقٌ فِى ٱلسَّعِيرِ', 'wa kaḏālika awḥaynā ʾilayka qurʾānan ʿarabiyyan li-tunḏira ʾumma l-qurā wa man ḥawlahā wa tunḏira yawma l-jamʿi lā rayba fīhi farīqun fī l-jannati wa farīqun fī s-saʿīri', 'İşte sana böyle Arapça bir Kur''an vahyettik ki, hem anayurt halkını (Mekke''yi) ve çevresindekileri uyar, hem de toplanma (kıyamet) gününü haber ver. O günde hiç şüphe yoktur. Bir bölük cennettedir, bir bölük de cehennemdedir.'),
(42, 8, 25, 483, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِىٍّ وَلَا نَصِيرٍ', 'wa law shāʾa ʾallāhu la-jaʿalahum ʾummatan wāḥidatan wa lākin yudkhilu man yashāʾu fī raḥmatihī wa-ẓ-ẓālimūna mā lahum min waliyyin wa lā naṣīrin', 'Allah dileseydi, onları tek bir ümmet yapardı. Ancak O, dilediğini rahmetine kabul eder. Zalimlere gelince, onlar için ne bir dost ne de bir yardımcı vardır.'),
(42, 9, 25, 483, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ʾami t-takhadhū min dūnihi ʾawliyāʾa fa-llāhu huwa l-walīyu wa-huwa yuḥyī l-mawtā wa-huwa ʿalā kulli shayʾin qadīrun', 'Yoksa O''ndan başka veliler mi edindiler? Halbuki veli ancak Allah''tır. O, ölüleri diriltir. O, her şeye hakkıyla kadirdir.'),
(42, 10, 25, 483, 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 've-mā-ḫteliftum fīhi min şey''in fe-ḥukmuhu ilā-llāh ḏālikumu-llāhu rabbī ʿalayhi-tevekkeltu ve-ileyhi unīb', 'Aranızda herhangi bir hususta ihtilafa düştüğünüzde, onun hükmü Allah''a aittir. İşte bu, Rabbim Allah''tır. Yalnız O''na tevekkül ettim ve yalnız O''na (yönelip) dönerim.'),
(42, 11, 25, 484, 'فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًا يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِۦ شَىْءٌ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'fāṭiru s-samāwāti wa-l-arḍi jaʿala lakum min anfusikum azwājan wa mina l-anʿāmi azwājan yadhraʾukum fīhi laysa ka-mithlihi shayʾun wa huwa s-samīʿu l-baṣīru', 'O, gökleri ve yeri yoktan var edendir. Size kendi nefislerinizden eşler yarattı ve hayvanlardan da çiftler yarattı. Sizi bu şekilde türetmektedir. O''nun benzeri hiçbir şey yoktur. O, Semi''dir (bütün sesleri işitir), Basir''dir (bütün görüleri bilir).'),
(42, 12, 25, 484, 'لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌ', 'lahū maqālīdu s-samāwāti wa-l-arḍi yabsuṭu r-rizqa liman yashāʾu wa-yaqdiru ʾinnahuū bikulli shayin ʿalīmun', 'Göklerin ve yerin anahtarları O''nundur. Dilediğine rızkı bol verir, dilediğine de kısar. Şüphesiz O, her şeyi bilendir.'),
(42, 13, 25, 484, 'شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', 'sharaʿa lakum mina d-dīni mā waṣṣā bihi Nūḥan wa-lladhī awḥaynā ilayka wa mā waṣṣaynā bihi ʾIbrāhīma wa Mūsā wa ʿĪsā ʾan ʾaqīmū d-dīna wa lā tatafarraqū fīhi kabura ʿalā l-mušrikīna mā tadʿūhum ʾilayhi Allāhu yajtabī ʾilayhi man yašāʾu wa yahdī ʾilayhi man yunību', 'O, size dinden (din olarak) Nuh''a emrettiğini ve sana vahyettiğimizi, İbrahim''e, Musa''ya ve İsa''ya emrettiğimizi şöyle tâyin etti: ''Dini dosdoğru ayakta tutun ve onda ayrılığa düşmeyin.'' Kendisini çağırdığın şey, müşriklere ağır geldi. Allah dilediğini kendine seçer ve O''na yöneleni kendine iletir.'),
(42, 14, 25, 484, 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍ مُّسَمًّى لَّقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', 've mā teferraḳū illā min baʿdi mā jāʾahumu l-ʿilmu bagyāⁿ beynehum ve levlā kelimetun sebeḳat min rabbike ilā ʾechelin musemmāⁿ laḳuḍiye beynehum ve inne l-leẕîne ūriṯū l-kitābe min baʿdihim lefī şekkin minhu mūrîb', 'Onlar, kendilerine ilim geldikten sonra, aralarındaki ihtiras ve taassuptan (hakka karşı düşmanlıklarından) dolayı ayrılığa düştüler. Eğer Rabbinden (verilmiş) belirli bir süreye kadar (verilmiş) bir söz olmasaydı, mutlaka aralarında iş (hüküm) bitirilirdi. Onlardan sonra kitaba vâris kılınanlar da onun hakkında derin bir şüphe içindedirler.'),
(42, 15, 25, 484, 'فَلِذَٰلِكَ فَٱدْعُ وَٱسْتَقِمْ كَمَآ أُمِرْتَ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٍ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ٱللَّهُ يَجْمَعُ بَيْنَنَا وَإِلَيْهِ ٱلْمَصِيرُ', 'falidhālika fadʿu wāstaqim kamā umirta walā tattabiʿ ahwāʾahum wa qul ʾāmantu bimā ʾanzala ʾllāhu min kitābin wa ʾumirtu li-ʾaʿdila baynakum ʾllāhu rabbunā wa rabbukum lanā ʾaʿmālunā wa lakum ʾaʿmālukum lā ḥujjata baynanā wa baynakum ʾllāhu yajmaʿu baynanā wa ʾilayhi l-maṣīru', 'İşte bu yüzden (seni hakka ve doğru yola ilettik), haydi (buna inanarak) davet et ve emrolunduğun gibi dosdoğru ol. Onların keyiflerine uyma ve de ki: "Allah''ın indirdiği her kitaba inandım; bana aranızda adaletle davranmam emrolundu. Allah bizim de Rabbimizdir, sizin de Rabbinizdir. Bizim yaptıklarımız bize, sizin yaptıklarınız size aittir. Aramızda (tartışılacak) bir husus kalmamıştır. Allah hepimizi bir araya toplayacaktır ve dönüş O''nadır."'),
(42, 16, 25, 485, 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ', 'wa-lladhīna yuḥājjūna fī llāhi min baʿdi mā istujība lahu ḥujjatuhum dāḥiḍatun ʿinda rabbihim wa ʿalayhim ghaḍabun wa lahum ʿadhābun shadīdun', 'Kendilerine icabet olunduktan sonra, Allah hakkında (delillerini) tartışanların delilleri Rableri katında batıldır. Onların üzerine bir gazap vardır ve onlar için çetin bir azap da vardır.'),
(42, 17, 25, 485, 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌ', 'Allāhu alladhī anzala l-kitāba bil-ḥaqqi wal-mīzān wa mā yudrīka laʿalla s-sāʿata qarīb', 'Allah, Kitab''ı ve Mizan''ı hak olarak indiren O''dur. Ve ne bilirsin, belki de o saat (kıyamet) yakındır.'),
(42, 18, 25, 485, 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَٰلٍۭ بَعِيدٍ', 'yastaʿjilu bihā allaḏīna lā yuʾminūna bihā waallaḏīna ʾāmanū mušfiqūna minhā wayaʿlamūna ʾannahā alḥaqqu ʾalā ʾinna allaḏīna yumārūna fī s-sāʿati lafī ḍalālin baʿīdin', 'Onu, ona inanmayanlar acele istiyorlar. İman edenler ise ondan çekinirler ve onun hakk olduğunu bilirler. Haberiniz olsun ki, kıyamet saati hakkında tartışıp duranlar, derin bir sapıklık içindedirler.'),
(42, 19, 25, 485, 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'Allāhu laṭīfum biʿibādihi yarzuku man yashāʾu wa huwa l-qawiyyu l-ʿazīzu', 'Allah kullarına lütufkârdır. Dilediğini rızıklandırır. O, kuvvetli ve mutlak güç sahibidir.'),
(42, 20, 25, 485, 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْءَاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِن نَّصِيبٍ', 'man kāna yurīdu ḥarṯa l-ʾāxirati nazid lahu fī ḥarṯihi wa-man kāna yurīdu ḥarṯa d-dunyā nuʾtihi minhā wa-mā lahu fī l-ʾāxirati min naṣīb', 'Kim ahiret ekinini (hasadını) isterse, onun ekinine bereket veririz. Kim de dünya ekinini (hasadını) isterse, ona ondan veririz. Ancak onun ahirette hiçbir nasibi yoktur.'),
(42, 21, 25, 485, 'أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', 'ʾam lahum shurakāʾu sharaʿū lahum mina d-dīni mā lam yaʾḏan bihi ʾllāhu wa-lawlā kalimatul-faṣli laquḍiya baynahum wa-ʾinna ẓ-ẓālimīna lahum ʿaḏābun ʾalīmun', 'Yoksa onların, Allah''ın izin vermediği bir dini kendilerine meşru kılan ortakları mı vardır? Eğer (azabın ertelenmesiyle ilgili) bir kelime olmasaydı, aralarında çoktan hüküm verilmişti. Şüphesiz zalimler için elem dolu bir azap vardır.'),
(42, 22, 25, 485, 'تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 'tarā aẓ-ẓālimīna mushfiqīna mimmā kasabū wa-huwa wāqiʿum bihim wa-llaḏīna ʾāmanū wa-ʿamilū aṣ-ṣāliḥāti fī rawḍāti l-jannāti lahum mā yašāʾūna ʿinda rabbihim ḏālika huwa l-faḍlu l-kabīru', 'Zalimleri, kazandıklarından dolayı korkuya kapılmış görürsün. O (yaptıkları) ise onlara mutlaka isabet edecektir. İman edip salih amel işleyenler ise cennet bahçelerindedir. Rablerinin katında onlara diledikleri her şey vardır. İşte bu, o büyük fazıldır.'),
(42, 23, 25, 486, 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا إِنَّ ٱللَّهَ غَفُورٌ شَكُورٌ', 'dhālika lladhī yubashshiru llāhu ʿibādahu lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāt qul lā ʾasʾalukum ʿalayhi ʾajran ʾillā l-mawaddata fī l-qurbā wa-man yaqtari f ḥasanatan nazid lahu fīhā ḥusnan ʾinna llāha ghafūrun shakkūr', 'İşte bu, Allah''ın, iman edip salih amel işleyen kullarını müjdelediği şeydir. De ki: "Ben buna karşılık sizden (tebliğime) bir ücret istemiyorum, ancak yakınlara sevgiyi (dostluğu) başka türlü istemem." Kim bir iyilik kazanırsa, Biz onun iyiliğini artırırız. Şüphesiz Allah, Gafûr''dur, Şekûr''dur.'),
(42, 24, 25, 486, 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'am yaqūlūna-ftará ʿalá-llāhi kaḏibā fa-ʾin yašaʾi-llāhu yaḫtim ʿalá qalbika wa-yamḥu-llāhu-l-bāṭila wa-yuḥiqqu-l-ḥaqqa bi-kalimātihi ʾinnahu ʿalīmun bi-ḏāti-ṣ-ṣudūri', 'Yoksa: "Allah''a bir yalan uydurdu" mu diyorlar? Eğer Allah dilerse senin kalbini mühürler. Allah, bâtılı yok eder ve sözleriyle hakkı gerçekleştirir. Şüphesiz O, göğüslerde olanı hakkıyla bilendir.'),
(42, 25, 25, 486, 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', 'wa-huwa alladhī yaqbalu t-tawbah ʿan ʿibādihi wa-yaʿfū ʿani s-sayyiʾāt wa-yaʿlamu mā tafʿalūn', 'O, kullarının tevbesini kabul eden, kötülüklerini affeden ve sizin yaptıklarınızı bilendir.'),
(42, 26, 25, 486, 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ', 'wa yastajību llaḏīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti wa yazīduhum min faḍlihī wa l-kāfirūna lahum ʿaḏābun šadīdun', 'İman edip salih amel işleyenlere gelince, Allah onların dualarını kabul eder ve onlara lütfundan fazlasıyla verir. Kafirler ise onlara çetin bir azap vardır.'),
(42, 27, 25, 486, 'وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌ', 'wa law basaṭa allāhu ar-rizqa liʿibādihī la-bagaw fī al-arḍi wa lākin yunazzilu bi-qadarin mā yashāʾu ʾinnahu bi-ʿibādihī khabīrun baṣīrun', 'Eğer Allah kullarına rızkı bol bol verseydi, yeryüzünde mutlaka azgınlık ederlerdi. Fakat O, dilediği ölçüde indirir. Şüphesiz O, kullarından haberi olan, (her şeyi) görendir.'),
(42, 28, 25, 486, 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', 'wa huwa alladhī yunazzilu al-ghaytha min baʿdi mā qanaṭū wa yanshuru raḥmatahu wa huwa al-walīyu al-ḥamīd', 'O, ümitlerini kestikten sonra yağmuru indiren ve rahmetini yayan O''dur. O, dost ve övgüye layık olandır.'),
(42, 29, 25, 486, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌ', 'wa-min ʾāyātihi ḵalqu s-samāwāti wa-l-ʾarḍi wa-mā baththa fīhimā min dābbatin wa-huwa ʿalā jamʿihim ʾiḏā yašāʾu qadīrun', 'O’nun delillerinden, göklerin ve yerin yaratılması ve yaydığı canlılardır. Ve O, dilediği zaman onları bir araya toplamaya da gücü yetendir.'),
(42, 30, 25, 486, 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ', 'Ve mā aṣābekum mim muṣībatin fe bimā kasabat aydīkum ve yaʿfū ʿan kaṡīrin', 'Size isabet eden her musibet, kendi ellerinizle işledikleriniz yüzündendir. (Allah) yine de çoğunu affeder.'),
(42, 31, 25, 486, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 've mā antum bi-muʿjizīna fī l-arḍi ve mā lakum min dūni llāhi min waliyyin wa lā naṣīrin', 'Hem siz yeryüzünde (Allah''ı) âciz bırakacak değilsiniz. Sizin için Allah''tan başka bir dost ve bir yardımcı da yoktur.'),
(42, 32, 25, 487, 'وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 'Ve min ʾāyātihī al-jawāri fī al-baḥri ka-l-ʾaʿlāmi', 'Denizde (dağlar gibi) gemiler de O''nun (varlığının) delillerindendir.'),
(42, 33, 25, 487, 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'in yeşeʾ yuskini r-rîḥa fa-yaẓlalne ravācida ʿalā ẓahrihī inna fī ḏālika laʾāyātin li-kulli ṣabbārin šakūr', 'Eğer dilerse rüzgârı durdurur da onlar (gemiler) denizin üstünde hareketsiz kalakalırlar. Elbette bunlarda, çok sabreden ve çok şükreden herkes için ibretler vardır.'),
(42, 34, 25, 487, 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍ', 'aw yūbiqhunna bimā kasabū wa yaʿfu ʿan kathīr', 'Yahut onların kazandıkları yüzünden onları helak eder ve çoğundan da vazgeçer.'),
(42, 35, 25, 487, 'وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍ', 'wa yaʿlama alladhīna yujādilūna fī ʾāyātinā mā lahum min maḥīṣin', 'Ayetlerimiz hakkında tartışanlara, kendileri için hiçbir kurtuluş olmadığını bilmeleri için (böyle yaparız).'),
(42, 36, 25, 487, 'فَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'famā ūtītum min shayʾin famatāʿu l-ḥayāti d-dunyā wamā ʿinda llāhi khayrun wa-ʾabqā lilladhīna ʾāmanū wa-ʿalā rabbihim yatawakkalūna', 'Size verilen herhangi bir şey, dünya hayatının geçici bir zevkidir. İman edip Rablerine güvenenler için Allah katında olan ise daha hayırlı ve daha kalıcıdır.'),
(42, 37, 25, 487, 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', 'wa-lladhīna yajtanibūna kabāʾira l-ithmi wa-l-fawāḥisha wa-idhā mā ghaḍibū hum yaghfirūn', 'Onlar, büyük günahlardan ve hayasızlıklardan kaçınırlar. Ve onlar, kızdıkları zaman bağışlarlar.'),
(42, 38, 25, 487, 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'wa-lladhīna istajābū li-rabbihim wa-aqāmū ṣ-ṣalāta wa-amruhum shūrā baynahum wa-mimmā razaqnāhum yunfiqūna', 'Rablerinin çağrısına cevap verenler, namazı dosdoğru kılanlar, işleri kendi aralarında bir şûrâ (danışma) ile yürüyenler ve kendilerine verdiğimiz rızıktan yerli yerince harcayanlar.'),
(42, 39, 25, 487, 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', 'wa-lladhīna idhā aṣābahumu l-baghyu hum yantaṣirūn', 'Onlar, kendilerine zulüm ve haksızlık yapıldığı zaman, birbirlerine yardım edenlerdir.'),
(42, 40, 25, 487, 'وَجَزَٰٓؤُا۟ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'wa-jazāʾu sayyiʾatin sayyiʾatun mithluhā fa-man ʿafā wa-aṣlaḥa fa-ʾajruhu ʿalā Allāh ʾinnahu lā yuḥibbu ẓ-ẓālimīn', 'Bir kötülüğün karşılığı, onun gibi bir kötülüktür. Ama kim affeder ve ıslah ederse, onun ecri Allah''a aittir. Şüphesiz O, zalimleri sevmez.'),
(42, 41, 25, 487, 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', 'wa-lamani-ntasara baʿda ẓulmihi fa-ʾulāʾika mā ʿalayhim min sabīl', 'Zulme uğradıktan sonra, kim de haklı çıkarılırsa, işte onların aleyhine herhangi bir yol (sorumluluk) yoktur.'),
(42, 42, 25, 487, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', 'innamā s-sabīlu ʿalā l-ladhīna yaẓlimūna n-nāsa wa yabghūna fī l-arḍi bighayri l-ḥaqqi ulāʾika lahum ʿadhābun alīmun', 'Yol, ancak insanlara zulmedenlere ve yeryüzünde haksız yere taşkınlık edenlere karşıdır. İşte onlar için elem dolu bir azap vardır.'),
(42, 43, 25, 487, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', 'wa-laman ṣabara wa-ghafara ʾinna dhālika lamina ʿazmi l-ʾumūri', 'Kim sabreder ve bağışlarsa, şüphesiz bu, azmedilmesi gereken işlerdendir.'),
(42, 44, 25, 487, 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّ مِّنۢ بَعْدِهِۦ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ', 'wa-man yuḍlili-llāhu fa-mā lahu min waliyyin min baʿdihi wa-tara-ẓ-ẓālimīna lammā raʾawu-l-ʿaḏāba yaqūlūna hal ilā maraddin min sabīlin', 'Allah''ın saptırdığı kimse için O''ndan başka dost yoktur. Zulmedenleri azabı gördükleri zaman "Geri dönmeye bir yol var mı?" derken görürsün.'),
(42, 45, 25, 488, 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍ مُّقِيمٍ', 'wa tarāhum yuʿraḍūna ʿalayhā khāshiʿīna mina dhulli yanẓurūna min ṭarfin khafiyyin wa qāla alladhīna āmanū inna l-khāsirīna alladhīna khasirū anfusahum wa ahliyahum yawma l-qiyāmati alā inna ẓ-ẓālimīna fī ʿadhābin muqīmin', 'Onları, zillet içinde titreyerek ateşe arz olunurlarken görürsün. Gözleri bir noktaya dalmış bir halde bakarlar. İman edenler ise şöyle derler: "Şüphesiz ki hüsrana uğrayanlar, kıyamet günü kendilerini ve ailelerini ziyana uğratanlardır." Haberiniz olsun ki, zalimler daimi bir azap içindedirler.'),
(42, 46, 25, 488, 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', 've-mā kāne lehum min evliyāʾe yensurûnehum min dûni-llāhi ve-men yuḍlili-llāhu fe-mā lehu min sebīlin', 'Onların, Allah''tan başka kendilerine yardım edecek velileri de yoktur. Allah''ın saptırdığı kimse için ise kurtuluş yolu yoktur.'),
(42, 47, 25, 488, 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ', 'istecībū lirabbikum min qabli en ye''tiye yevmun lā meradde lehū minallāhi mā lekum min melcein yevme''iẕin vemā lekum min nekīrin', 'Rabbinizin çağrısına, Allah''tan geri çevrilmesi imkânsız bir gün gelmeden önce icabet edin. O gün sizin ne sığınacak bir yeriniz ne de (inkârınızı) reddedecek bir gücünüz vardır.'),
(42, 48, 25, 488, 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌ', 'faʾin ʾaʿraḍū famā ʾarsalnāka ʿalayhim ḥafīẓan ʾin ʿalayka ʾillā l-balāġu waʾinnā ʾiḏā ʾaḏaqnā l-ʾinsāna minnā raḥmatan fariḥa bihā waʾin tuṣibhum sayyiʾatun bimā qaddamat ʾaydīhim faʾinna l-ʾinsāna kafūrun', 'Eğer yüz çevirirlerse, (bil ki) seni onlara bir koruyucu olarak göndermedik. Sana düşen, yalnızca tebliğdir. Doğrusu biz insana tarafımızdan bir rahmet tattırdığımız zaman onunla sevinir. Ama kendi işledikleri (kötülükler) yüzünden başlarına bir kötülük gelirse, işte o zaman insan pek nankördür.'),
(42, 49, 25, 488, 'لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَخْلُقُ مَا يَشَآءُ يَهَبُ لِمَن يَشَآءُ إِنَٰثًا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', 'lillāhi mulku s-semāwāti wa-l-arḍi yaḫluqu mā yašāʾu yahabu liman yašāʾu ināṯan wa yahabu liman yašāʾu ḏ-ḏukūra', 'Göklerin ve yerin mülkiyeti/hükümranlığı Allah''ındır. Dilediğini yaratır. Dilediğine kızlar, dilediğine erkekler bahşeder.'),
(42, 50, 25, 488, 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَٰثًا وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا إِنَّهُۥ عَلِيمٌ قَدِيرٌ', 'aw yuzawwijuhum dhukrānan wa-ināthan wa yajʿalu man yashāʾu ʿaqīman ʾinnahu ʿalīmun qadīrun', 'Yahut onları erkekler ve dişiler olmak üzere çift yapabilir ve dilediğini de kısır kılabilir. Şüphesiz O, bilendir, güç yetirendir.'),
(42, 51, 25, 488, 'وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ إِنَّهُۥ عَلِىٌّ حَكِيمٌ', 've mā kāna li-beşerin en yukellimehu-llāhu illā vaḥyan ev min verāʾi ḥicābin ev yursile rasūlan fe-yūḥiya bi-ʾiḏnihi mā yešāʾu ʾinnehu ʿaliyyun ḥakīmun', 'Allah, bir insanla ancak vahiy yoluyla, yahut bir perdenin arkasından konuşmak suretiyle veya bir elçi gönderip izniyle dilediğini vahyetmesi suretiyle konuşur. O, yücedir, hikmet sahibidir.'),
(42, 52, 25, 489, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'wa kaḏālika awḥaynā ʾilayka rūḥan min ʾamrinā mā kunta tadrī mā l-kitābu walā l-ʾīmānu wa lākin jaʿalnāhu nūran nahdī bihi man našāʾu min ʿibādinā wa ʾinnaka latahdī ʾilā ṣirāṭin mustaqīmin', 'İşte böylece sana da emrimizden bir ruh (olan Kur''an''ı) vahyettik. Sen kitap nedir, iman nedir bilmezdin. Fakat biz onu kullarımızdan dilediğimizi kendisiyle doğru yola eriştireceğimiz bir nur kıldık. Şüphesiz sen de (insanlara) doğru bir yola yöneltiyorsun.'),
(42, 53, 25, 489, 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', 'ṣirāṭi llāhi llaḏī lahū mā fī s-samāwāti wa mā fī l-arḍi ʾalā ʾilā llāhi taṣīru l-ʾumūru', 'Allah''ın yoludur. Göklerde ve yerde ne varsa O''na aittir. Dikkat edin, bütün işler sonunda Allah''a döner.'),
(43, 1, 25, 489, 'حمٓ', 'Ḥā Mīm', 'Ha, Mim.'),
(43, 2, 25, 489, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', 'wa-l-kitābi l-mubīni', 'Yemin olsun apaçık olan Kitab''a.'),
(43, 3, 25, 489, 'إِنَّا جَعَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', 'innā jaʿalnāhu qurʾānan ʿarabiyyan laʿallakum taʿqilūn', 'Şüphesiz biz onu, akıl erdiresiniz diye Arapça bir Kur''an olarak indirdik.'),
(43, 4, 25, 489, 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', 'waʾinnahu fī ʾummi l-kitābi ladaynā laʿaliyyun ḥakīm', 'Şüphesiz o, katımızda bulunan ana kitaptadır; O, yücedir, hikmet sahibidir.'),
(43, 5, 25, 489, 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًا مُّسْرِفِينَ', 'ʾafanaḍribu ʿankumu ḏ-ḏikra ṣafḥan ʾan kuntum qawman musrifīn', 'Siz israf eden bir kavim olduğunuz için, öğüdü üzerinizden atmalı mıyız?'),
(43, 6, 25, 489, 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّ فِى ٱلْأَوَّلِينَ', 'wa kam arsalnā min nabiyyin fī l-awwalīn', 'Ve öncekiler içinde nice peygamberler gönderdik.'),
(43, 7, 25, 489, 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'wa mā yaʾtīhim min nabiyyin ʾillā kānū bihi yastahziʾūn', 'Onlara gelip de bir peygamber istisna olmamak üzere, hep onunla alay ederlerdi.'),
(43, 8, 25, 489, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', 'faʾahlaknā ʾašadda minhum baṭšan wa maḍā maṯalu l-ʾawwalīn', 'Onlardan daha çetin kuvvetli olanları helak ettik. Ve öncekilerin örneği (de geçti).'),
(43, 9, 25, 489, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', 'Ve leʾin seʾeltehum men ḫaleḳa es-semāvāti ve el-ʾarḍa leyaḳūlunne ḫaleḳahunne el-ʿazīzu el-ʿalīmu', 'Andolsun ki onlara, “Gökleri ve yeri kim yarattı?” diye sorsan, mutlaka “Onları O Azîz ve Alîm olan yarattı” derler.'),
(43, 10, 25, 489, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَجَعَلَ لَكُمْ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', 'alladhī jaʿala lakumu l-arḍa mahdan wa jaʿala lakum fīhā subulan laʿallakum tahtadūn', 'O, yeri sizin için bir beşik yaptı ve orada sizin için yollar var etti ki, doğru yolu bulasınız.'),
(43, 11, 25, 490, 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَنشَرْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ تُخْرَجُونَ', 'wa-lladhī nazzala mina s-samāʾi māʾan bi-qadarin fa-anšarnā bihi baldatan maytan ka-dhālika tukhrajūn', 'O, gökten bir mikdar (ölçü) ile su indirendir. Biz onunla ölüp çürümüş bir beldeyi (toprağı) diriltiriz. İşte siz de (kabirlerinizden) böyle çıkarılacaksınız.'),
(43, 12, 25, 490, 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَٰمِ مَا تَرْكَبُونَ', 'wa-lladhī khalaqa l-ʾazwāja kullahā wa-jaʿala lakum mina l-fulki wa-l-ʾanʿāmi mā tarkabūn', 'O, bütün çiftleri yaratan ve hem gemilerden hem de hayvanlardan size bineceğiniz şeyleri var edendir.'),
(43, 13, 25, 490, 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', 'litas tawū ʿalā ẓuhūrihī thumma tadhkurū niʿmata rabbikum idhā stawraytum ʿalayhi wa taqūlū subḥāna alladhī sakhkhara lanā hādhā wamā kunnā lahū muqrinīn', 'Onların üzerine yerleşip sabitlendiğinizde, Rabbinizin nimetini hatırlayarak şöyle dediğinizde: ''Bunu bize boyun eğdiren münezzehtir; yoksa biz bunlara güç yetiremezdik.'''),
(43, 14, 25, 490, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', 'wa-innā ilā rabbina lamunqalibūna', 'Ve şüphesiz biz behemehal rabbimize döneceğiz.'),
(43, 15, 25, 490, 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ مُّبِينٌ', 'wa jaʿalū lahu min ʿibādihī juzʾan ʾinna l-ʾinsāna laka fūr um mubīn', 'Onlar, O''nun kulları arasından O''na bir parça (bir eş) kıldılar. Gerçekten insan, apaçık bir nankördür.'),
(43, 16, 25, 490, 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَىٰكُم بِٱلْبَنِينَ', 'ʾami-ttakhaḏa mim-mā yaḫluqu banātin wa-ʾaṣfākum bil-banīna', 'Yoksa O, yarattıklarından dolayı kızlar edinmiş de oğulları size mi ayırmıştır?'),
(43, 17, 25, 490, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلًا ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', 'wa ʾiḏā buššira ʾaḥaduhum bimā ḍaraba lil-raḥmāni maṯalan ẓalla wajhuhuۥ muswaddan wa huwa kaẓīmun', 'Onlardan biri, Rahman''a nispet edilen bir benzetme ile müjdelendiğinde, yüzü simsiyah kesilir ve o, üzüntüsünden yutkunur.'),
(43, 18, 25, 490, 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍ', 'A-vemen yunashshaʾu fīl-ḥilyati Ve hüve fīl-khiṣāmi ġayru mubīni', 'Yoksa (o), ziynet içinde yetiştirilip de, tartışma anında derdini açıkça ifade edemeyen mi (olur)?'),
(43, 19, 25, 490, 'وَجَعَلُوا۟ ٱلْمَلَٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَٰدُ ٱلرَّحْمَٰنِ إِنَٰثًا أَشَهِدُوا۟ خَلْقَهُمْ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ', 'wa jaʿalū l-malāʾikata lladhīna hum ʿibādu r-raḥmāni ināthan ashahidū khalqahum satuktabu shahādatuhum wa yusʾalūn', 'Onlar, Rahman''ın kulları olan melekleri de dişi saydılar. Onların yaratılışlarına mı şahit oldular? Hayır, onların şahitlikleri yazılacak ve sorguya çekileceklerdir.'),
(43, 20, 25, 490, 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَخْرُصُونَ', 'wa qālū law shāʾa ar-raḥmānu mā ʿabadnāhum mā lahum bi-dhālika min ʿilmin in hum illā yakhruṣūna', 'Ve dediler ki: "Rahmân dileseydi onlara tapmazdık." Onların bu konuda hiçbir bilgileri yoktur. Onlar sadece yalan uyduruyorlar.'),
(43, 21, 25, 490, 'أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', 'am ʾātaynāhum kitāban min qablihī fahum bihī mustamsikūn', 'Yoksa onlara ondan önce bir kitap mı verdik de ona tutunuyorlar?'),
(43, 22, 25, 490, 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ', 'bal qālū inna wajadnā ābāʾanā ʿalā ummatin wa-innā ʿalā āthārihim muhtadūn', 'Hayır, dediler: Biz atalarımızı bir din üzerinde bulduk, biz de onların izlerine uyarız.'),
(43, 23, 25, 491, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ', 'wa kaḏālika mā arsalnā min qablika fī qaryatin min naḏīrin illā qāla mutrafūhā innā wajadnā ābāʾanā ʿalā ummatin wa innā ʿalā āṯārihim muqtadūna', 'İşte böyle! Senden önce de hiçbir memlekete bir uyarıcı göndermiş olmayız ki, oranın zenginleri: "Biz atalarımızı bir din üzerinde bulduk; biz de onların izlerine uyarız" dememiş olsunlar.'),
(43, 24, 25, 491, 'قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'qāla ʾaʾaw ʾilaw jiʾtukum bi-ʾahdā mimmā wajadtum ʿalayhi ʾābāʾakum qālū ʾinnā bimā ʾursiltum bihi kāfirūn', 'Dediler ki: ''Biz atalarımızı bir yol üzere bulduk, biz de onların izlerine uyarız.'''),
(43, 25, 25, 491, 'فَٱنتَقَمْنَا مِنْهُمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'fa-ntaqamnā minhum fa-nẓur kayfa kāna ʿāqibatu l-muḵaḏḏibīn', 'Böylece onlardan intikam aldık. Bir bak, yalanlayanların sonu nasıl oldu!'),
(43, 26, 25, 491, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ', 'wa-ʾiḏ qāla ʾibrāhīmu li-ʾabīhi wa-qawmihi ʾinnanī barāʾun mimmā taʿbudūna', 'Hani İbrahim babasına ve kavmine demişti ki: "Ben sizin taptıklarınızdan uzağım."'),
(43, 27, 25, 491, 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', 'ʾillā l-ladhī faṭaranī fa-ʾinnahuۥ sayahdīnī', 'Ancak beni yaratana bakarım; çünkü O, bana yol gösterecektir.'),
(43, 28, 25, 491, 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةً فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', 'wa jaʿalahā kalimatan bāqiyatan fī ʿaqibihi laʿallahum yarjiʿūn', 'Ve onu, kendisinden sonra gelecekler arasında kalıcı bir söz kıldı; umulur ki (bu sözle) geri dönerler.'),
(43, 29, 25, 491, 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌ مُّبِينٌ', 'Bal mettu''tu ha''ula''i ve aba''ahum hatta ja''ahumul-hakku ve rasulum mubinu', 'Hayır! Ben bunlara ve atalarına, kendilerine o hak (Kur''an) ve her şeyi açıklayan bir peygamber gelinceye kadar dünya nimetlerinden faydalanma imkânı verdim.'),
(43, 30, 25, 491, 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌ وَإِنَّا بِهِۦ كَٰفِرُونَ', 'wa lammā jāʾahumu l-ḥaqqu qālū hādhā siḥrun wa innā bihi kāfirūna', 'Ne zaman ki onlara hak geldi, şöyle dediler: "Bu bir sihirdir ve biz onu inkâr edenleriz."'),
(43, 31, 25, 491, 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', 'waqālū lawlā nuzżila hādhā l-qurʾānu ʿalā rajulim mina l-qaryatayni ʿaẓīm', 'Dediler ki: ''Bu Kur''an, iki şehirden (Mekke ve Taif''ten) büyük bir adama indirilmeli değil miydi?'''),
(43, 32, 25, 491, 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'ʾahum yaqsimūna raḥmata rabbika naḥnu qasamnā baynahum maʿīshatahum fī al-ḥayāti ad-dunyā wa rafaʿnā baʿḍahum fawqa baʿḍin darajātin li yattakhidha baʿḍuhum baʿḍan sukhriyyan wa raḥmatu rabbika khayrun mimmā yajmaʿūn', 'Onlar mı Rabbinin rahmetini taksim ediyorlar? Hâlbuki biz, dünya hayatında onların geçimliklerini aralarında biz taksim ettik ve onlardan bir kısmını diğerlerine derecelerle üstün kıldık ki, birbirlerini (hizmetçi olarak) tutsunlar. Rabbinin rahmeti ise onların toplamakta olduklarından daha hayırlıdır.'),
(43, 33, 25, 491, 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 'wa-lawlā an yakūna an-nāsu ummatan wāḥidatan la-jaʿalnā li-man yakfuru bi-r-raḥmāni li-buyūtihim suqufan min fiḍḍatin wa-maʿārija ʿalayhā yaẓharūna', 'Eğer insanların küfürde birleşen tek bir ümmet olmasından korkulmasaydı, Rahman''ı inkâr edenlerin evlerinin tavanlarını gümüşten ve üzerine çıkacakları (diğer) merdivenleri de gümüşten yapardık.'),
(43, 34, 25, 492, 'وَلِبُيُوتِهِمْ أَبْوَٰبًا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', 'wa libuyūtihim abwāban wa sururan ʿalayhā yattakiʾūn', 'Ve evlerine de kapılar ve üzerine yaslanacakları koltuklar (yapardık).'),
(43, 35, 25, 492, 'وَزُخْرُفًا وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْءَاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', 'wa-zukhrufan wa-inna kullu dhālika lammā matāʿu l-ḥayāti d-dunyā wa-l-ākhiratu ʿinda rabbika lil-muttaqīn', 'Ve ziynet (altın, gümüş vb.). Ve şüphesiz bütün bunlar, dünya hayatının geçici bir faydasıdır. Ve ahiret, Rabbinin katında takva sahipleri içindir.'),
(43, 36, 25, 492, 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًا فَهُوَ لَهُۥ قَرِينٌ', 'wa-man yaʿshu ʿan dhikri r-raḥmāni nuqayyiḍu lahu sh-shayṭāna fa-huwa lahu qarīnun', 'Rahmân''ı anmaktan yüz çevirene, şeytanı arkadaş ederiz; artık bu, onun ayrılmaz dostudur.'),
(43, 37, 25, 492, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 'waʾinnāhum layaṣuddūnahum ʿani s-sabīli wayaḥsabūna ʾannahum muhtadūna', 'Onlar (şeytanlar) kendilerini doğru yoldan alıkoyarlar ve (böyle yapanlar) kendilerinin doğru yolda olduklarını sanırlar.'),
(43, 38, 25, 492, 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', 'ḥattā ʾiḏā jāʾanā qāla yālayta baynī wa baynaka buʿda l-mašriqayni fa biʾsa l-qarīnu', 'Nihayet bize geldiğinde, (pişman olarak) şöyle der: ''Keşke benimle senin aranda doğu ile batı arası kadar bir mesafe olsaydı! Ne kötü bir arkadaş!'''),
(43, 39, 25, 492, 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 'wa-lan yanfaʿakum al-yawma idh dhalamtum annakum fī al-ʿadhābi mushtarikūn', 'Nihayet o gün, (kendinize) zulmetmişken, azapta ortak olduğunuza size hiçbir fayda sağlamaz.'),
(43, 40, 25, 492, 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍ مُّبِينٍ', 'ʾafaʾanta tusmiʿu ṣ-ṣumma ʾaw tahdī l-ʿumya waman kāna fī ḍalālin mubīnin', 'Onlar, sağır olanlara, kör olanlara ve apaçık bir sapıklık içinde bulunanlara sen mi duyuracaksın?'),
(43, 41, 25, 492, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', 'fa-immā nadhhabanna bika fa-ʾinnanā minhum muntaqimūn', 'Eğer seni (onların başına) alırsak, o zaman onlardan mutlaka intikam alırız.'),
(43, 42, 25, 492, 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', 'aw nuriyannaka alladhī waʿadnāhum fa-innā ʿalayhim muqtadirūn', 'Yoksa, onlara vaadettiğimiz şeyi sana gösteririz de, şüphesiz biz onlara güç yetirenleriz.'),
(43, 43, 25, 492, 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ إِنَّكَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'fastamsik billadhī ūḥiya ilayka innaka ʿalā ṣirāṭin mustaqīm', 'Sana vahyolunana sarıl! Şüphesiz sen dosdoğru bir yol üzeresin.'),
(43, 44, 25, 492, 'وَإِنَّهُۥ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ وَسَوْفَ تُسْـَٔلُونَ', 'waʾinnahu ladhikrun laka waliliqawmik wasawfa tusʾalūn', 'Şüphesiz ki o (Kur''an), sana ve senin kavmine bir zikirdir (bir öğüt ve şereftir). Ve siz (bundan) sorulacaksınız.'),
(43, 45, 25, 492, 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةً يُعْبَدُونَ', 'wa-sʾal man arsalnā min qablika min rusulinā ʾa-jaʿalnā min dūni ʾr-raḥmāni ʾālihatan yuʿbadūn', 'Sendən əvvəl göndərdiyimiz elçilərimizə də soruş: "Məgər Biz, Mərhəmətli Allahdan başqa ibadət ediləcək tanrılar təyin etdikmi?"'),
(43, 46, 25, 492, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 'Ve lekad arselnā Mūsā bi-āyātinā ilā Firʿawna ve meleʾihi Fe-qāla innī rasūlu Rabbi l-ʿālamīn', 'Andolsun ki Musa''yı ayetlerimizle Firavun''a ve ileri gelenlerine gönderdik de o şöyle dedi: "Şüphesiz ben âlemlerin Rabbinin elçisiyim."'),
(43, 47, 25, 492, 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', 'fe-lemmā jāʾahum bi-ʾāyātinā ʾiḏā hum minhā yaḍḥakūn', 'Onları ayetlerimiz geldiğinde bir de ne görsünler, hemen gülmeye başladılar!'),
(43, 48, 25, 493, 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', 'wa mā nurīhim min āyatin illā hiya akbaru min ukhtihā wa ʾakhaḏnāhum bil-ʿaḏābi laʿallahum yarjiʿūn', 'Onlara gösterdiğimiz hiçbir ayet, kendinden önceki (benzeri)nden daha büyük değildi. Onları azapla yakaladık ki, (yola) dönsünler.'),
(43, 49, 25, 493, 'وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', 'wa qālū yā ayyuha s-sāḥiru udʿu lanā rabbaka bimā ʿahida ʿindaka ʾinnanā lamuhtadūna', 'Dediler ki: "Ey büyücü! Bizim için Rabbine, sana verdiği ahde dayanarak dua et! Şüphesiz biz doğru yola gireceğiz."'),
(43, 50, 25, 493, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', 'fe-lemmā keşefnā ʿanhumu l-ʿaẕābe iẕā hum yenkuṯūn', 'Ne zaman ki azabı üzerlerinden kaldırdık, bir de baktık ki onlar ahdlerini bozuyorlar.'),
(43, 51, 25, 493, 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ أَفَلَا تُبْصِرُونَ', 'wa-nādā firʿawnu fī qawmihi qāla yā qawmi ʾalaysa lī mulku miṣra wa-hāḏihi l-ʾanhāru tajrī min taḥtī ʾafalā tubṣirūna', 'Firavun kavminin içinde seslendi, dedi ki: "Ey kavmim! Mısır’ın mülkü bana ait değil mi? Ve şu altımdan akıp giden nehirler (bana ait) değil mi? Hâlâ basiret etmiyor musunuz?"'),
(43, 52, 25, 493, 'أَمْ أَنَا۠ خَيْرٌ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ', 'Am anā khayrun min hādhā alladhī huwa mahīnun walā yakādu yubīn(u)', 'Yoksa ben mi daha hayırlıyım, şu aşağılık ve neredeyse derdini anlatamayacak olan (bu adam)dan?'),
(43, 53, 25, 493, 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ', 'falawlā ulqiya ʿalayhi ʾaswiratun min dhahabi ʾaw jāʾa maʿahu l-malāʾikatu muqtarinīna', 'Ona altın bilezikler atılmış olmalı değil miydi, yahut onunla beraber (yardımcı) melekler gelmeli değil miydi?'),
(43, 54, 25, 493, 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'fastakhaffa qawmahuu faa''aṭa''uuh innahum kaanuu qawman faasiqiin', 'Böylece kavmini küçümsedi de onlara itaat ettiler. Çünkü onlar yoldan çıkmış bir kavim idiler.'),
(43, 55, 25, 493, 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'felemmā asefūnā intaqamnā minhum feʾaġraqnāhum ʾacmʿīn', 'Nihayet bizi gazaplandırdıklarında onlardan intikam aldık da hepsini boğduk.'),
(43, 56, 25, 493, 'فَجَعَلْنَٰهُمْ سَلَفًا وَمَثَلًا لِّلْءَاخِرِينَ', 'fa jaʿalnāhum salafan wa maṡalan lil-ʾākhirīn', 'Onları hem bir ibret örneği ve hem de sonrakiler için bir misal kıldık.'),
(43, 57, 25, 493, 'وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', 'wa lammā ḍuriba ʾibnu maryama maṯalan iḏā qawmuka minhu yaṣidduwn', 'Meryem''in oğlu (İsa) misal olarak sunulduğu zaman, senin kavmin hemen ona karşı yaygara koparıyor.'),
(43, 58, 25, 493, 'وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا بَلْ هُمْ قَوْمٌ خَصِمُونَ', 'wa qālū a ʾālihatunā khayrun am huwa mā ḍarabūhu laka ʾillā jadalā bal hum qawmun khaṣimūn', 'Dediler ki: "Bizim ilahlarımız mı daha hayırlı, yoksa o mu?" Onu sana ancak tartışmak için örnek verdiler. Hayır, onlar kendilerini savunup duran bir topluluktur.'),
(43, 59, 25, 493, 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'ʾin huwa ʾillā ʿabdu n ʾanʿamnā ʿalayhi wa-jaʿalnāhu maṯalan li-banī ʾisrāʾīla', 'O, yalnızca kendisini nimetlendirdiğimiz ve İsrailoğullarına bir örnek kıldığımız bir kuldan başkası değildir.'),
(43, 60, 25, 493, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةً فِى ٱلْأَرْضِ يَخْلُفُونَ', 'wa law nashāʾu la-jaʿalnā minkum malāʾikatan fī l-arḍi yakhlafūn', 'Dileseydik, sizin yerinize yerden (halife) melekler kılardık.'),
(43, 61, 25, 494, 'وَإِنَّهُۥ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'waʾinnahu laʿilmun lissāʿati falā tamtarunna bihā wāttabiʿūni hādhā ṣirāṭun mustaqīmun', 'Şüphesiz o (Hz. İsa), kıyamet (için bir) ilimdir. Öyleyse ondan şüphe etmeyin ve bana uyun. Bu, dosdoğru yoldur.'),
(43, 62, 25, 494, 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'wa-lā yaṣuddannakumu sh-shayṭānu ʾinnahuu lakum ʿaduwwun mubīnun', 'Sakın sizi şeytan alıkoymasın. Çünkü o, sizin için apaçık bir düşmandır.'),
(43, 63, 25, 494, 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'wa lammā jāʾa ʿīsā bil-bayyināti qāla qad jiʾtukum bil-ḥikmati wa li-ʾubayyina lakum baʿḍa lladhī takhtalifūna fīhi fattaqū l-lāha wa ʾaṭīʿūnī', 'Nihayet İsa, apaçık delillerle gelince, şöyle dedi: "Ben size hikmetle (ilim ve nübüvvetle) geldim. Size, hakkında ihtilâf etmekte olduğunuz bazı şeyleri açıklamak için buradayım. Artık Allah’tan korkun ve bana itaat edin."'),
(43, 64, 25, 494, 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'ʾinna ʾallāha huwa rabbī wa rabbukum fa-ʿbudūhu hāḏā ṣirāṭun mustaqīm', 'Şüphesiz Allah, benim de Rabbim, sizin de Rabbinizdir. Öyleyse O''na kulluk edin. İşte bu, dosdoğru yoldur.'),
(43, 65, 25, 494, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', 'fa-ḵtalafa l-ʾaḥzābu min baynihim fa-waylun lilladhīna ẓalamū min ʿadhābi yawmin ʾalīm', 'Onların arasındaki fırkalar ihtilafa düştüler. Zulmedenlere, o can yakıcı günün azabından dolayı yazıklar olsun!'),
(43, 66, 25, 494, 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'hal naẓurūna illā s-sāʿata an taʾtiyahum baghtatan wa hum lā yashʿurūna', 'Onlar, kendilerine ansızın, hiç farkında olmadıkları bir sırada gelivermesinden başka, sadece o saati mi bekliyorlar?'),
(43, 67, 25, 494, 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', 'al-ʾakhillāʾu yawmaʾiḏin baʿḍuhum libaʿḍin ʿaduwwun ʾillā al-muttaqīn', 'O gün, dostlar birbirine düşman kesilir. Ancak Allah''a karşı gelmekten sakınanlar (bu durumdan müstesnadır).'),
(43, 68, 25, 494, 'يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', 'yā ʿibādi lā khawfun ʿalaykumu l-yawma wa lā antum taḥzanūna', 'Ey kullarım! Bugün size korku yoktur ve siz mahzun da olmayacaksınız.'),
(43, 69, 25, 494, 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', 'alladhīna ʾāmanū bi-ʾāyātinā wa kānū muslimīn', 'Onlar, bizim âyetlerimize inanmış ve müslüman olmuş kimselerdir.'),
(43, 70, 25, 494, 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', 'udkhulū l-jannata ʾantum wa-ʾazwājukum tuḥbarūn', 'Cennete siz ve eşleriniz, ağırlanarak girin.'),
(43, 71, 25, 494, 'يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ وَأَنتُمْ فِيهَا خَٰلِدُونَ', 'yuṭāfu ʿalayhim biṣiḥāfin min dhahabiw waʾakwābi wafīhā mā tashtahīhi l-ʾanfusu walataḏḏu l-ʾaʿyunu waʾantum fīhā khālidūna', 'Onların etrafında altın tepsiler ve kadehler dolaştırılır. Canların çektiği ve gözlerin lezzet aldığı her şey oradadır. Siz de orada ebedî kalacaksınız.'),
(43, 72, 25, 494, 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'wa tilka l-jannatu llatī ūrithtumūhā bimā kuntum taʿmalūn', 'İşte bu, yapmakta olduklarınız sebebiyle size miras bırakılan cennettir.'),
(43, 73, 25, 494, 'لَكُمْ فِيهَا فَٰكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ', 'lakum fīhā fākihah-tun kathīrah-tun min-hā taʾkulūn', 'Onlar için orada çok meyveler vardır; onlardan yiyeceksiniz.'),
(43, 74, 25, 495, 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ', 'ʾinna l-mujrimīna fī ʿaḏābi Jahannama ḫālidūn', 'Şüphesiz ki suçlular cehennem azabındadır, orada ebedî kalacaklardır.'),
(43, 75, 25, 495, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', 'lā yufattaru ʿanhum wa hum fīhi mublisūn', 'Onlardan azap hafifletilmez ve orada umutlarını yitirmişlerdir.'),
(43, 76, 25, 495, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ', 'wa mā ẓalamnāhum wa lākin kānū humu ẓ-ẓālimīn', 'Onlara zulmetmedik, fakat kendileri zalimlerdi.'),
(43, 77, 25, 495, 'وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُم مَّٰكِثُونَ', 'wa-nādaw yā-māliku li-yaqḍi ʿalaynā rabbuka qāla innakum mākithūna', 'Ey Mâlik! dedi ler, Rabbine söyle de bizi öldürsün. (Mâlik) da dedi ki: Siz burada ebedî kalacaksınız.'),
(43, 78, 25, 495, 'لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ', 'leḳad ci''nâküm bilḥaḳḳi velâkinne ekŝeraküm lilḥaḳḳi kârihûn', 'Andolsun ki size hakkı getirdik, fakat çoğunuz haktan hoşlanmayanlarsınız.'),
(43, 79, 25, 495, 'أَمْ أَبْرَمُوٓا۟ أَمْرًا فَإِنَّا مُبْرِمُونَ', 'ʾam ʾabramū ʾamran fa-ʾinnā mubrimūn', 'Yoksa bir plan mı yaptılar? Şüphesiz biz de plan yapmaktayız.'),
(43, 80, 25, 495, 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', 'am yaḥsabūna annanā lā nasmaʿu sirrahum wa-najwāhum balā wa-rusulunā ladayhim yaktubūn', 'Yoksa onlar, bizim sırlarını ve gizli konuşmalarını işitmediğimizi mi sanıyorlar? Hayır! Biz onların yanlarındaki elçilerimiz de yazıyorlar.'),
(43, 81, 25, 495, 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ', 'qul in kāna lir-raḥmāni waladun fa-ʾanā ʾawwalu l-ʿābidīn', 'De ki: "Eğer Rahmân''ın bir çocuğu olsaydı, (o çocuğa) tapanların ilki ben olurdum."'),
(43, 82, 25, 495, 'سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'subḥāna rabbi s-samāwāti wa-l-arḍi rabbi l-ʿarshi ʿammā yaṣifūn', 'Göklerin ve yerin Rabbi, Arş''ın Rabbi, onların vasfettiklerinden münezzehtir.'),
(43, 83, 25, 495, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'faḏarhum yaḫūḍū wa yalʿabū ḥattā yulāqū yawmahumu llaḏī yūʿadūn', 'Onları bırak, dalsınlar ve oynaya dursunlar, kendilerine vaad olunan o günlerine kavuşuncaya kadar.'),
(43, 84, 25, 495, 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌ وَفِى ٱلْأَرْضِ إِلَٰهٌ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'wa-huwa alladhī fī s-samāʾi ʾilāhun wa-fī l-ʾarḍi ʾilāhun wa-huwa l-ḥakīmu l-ʿalīmu', 'O, gökte ilah olandır ve yerde de ilah olandır. O, hüküm ve hikmet sahibi olan, hakkıyla bilendir.'),
(43, 85, 25, 495, 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', 'wa tabāraka alladhī lahu mulku s-samāwāti wa-l-arḍi wa mā baynahumā wa ʿindahu ʿilmu s-sāʿah wa ilayhi turjaʿūn', 'Göklerin, yerin ve ikisinin arasında bulunanların mülkiyeti/hükümranlığı kendisine ait olan ve kıyamet (saati) bilgisi de O''nun katında bulunan, yine O''na döndürüleceğiniz Yüce/Mübarek O''dur.'),
(43, 86, 25, 495, 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 'wa lā yamliku alladhīna yadʿūna min dūnihi ash-shafāʿata illā man shahida bil-ḥaqqi wa hum yaʿlamūn', 'Onu bırakıp taptıkları şeyler, şefaat hakkına sahip olamazlar; ancak hakka tanıklık eden ve (gerçeği) bilenler (bu hakkı) elde edebilirler.'),
(43, 87, 25, 495, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', 'Ve leʾin seʾeltehum men halakahum leyekūlunne Allāhu feʾennā yuʾfekūn', 'Andolsun ki onlara kendilerini kimin yarattığını sorsan, mutlaka “Allah” derler. O halde nasıl (haktan) çevriliyorlar?'),
(43, 88, 25, 495, 'وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوْمٌ لَّا يُؤْمِنُونَ', 'waqīlihi yā rabbi inna hāʾulāʾi qawmun lā yuʾminūn', 'Ve "Ey Rabbim! Şüphesiz bunlar iman etmeyen bir kavimdir!" demesi.'),
(43, 89, 25, 495, 'فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمٌ فَسَوْفَ يَعْلَمُونَ', 'faṣfaḥ ʿanhum waqul salāmun fasawfa yaʿlamūn', 'Onlardan yüz çevir ve (onlara) ''Selam!'' de. Yakında bileceklerdir.'),
(44, 1, 25, 496, 'حمٓ', 'Ha, Mim', 'Ha, Mim.'),
(44, 2, 25, 496, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', 'wa-l-kitābi l-mubīni', 'Apa yang jelas menerangkan Kitab itu.'),
(44, 3, 25, 496, 'إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةٍ مُّبَٰرَكَةٍ إِنَّا كُنَّا مُنذِرِينَ', 'ʾinnā ʾanzalnāhu fī laylatin mubārakatin ʾinnā kunnā munḏirīn', 'Şüphesiz biz onu mübarek bir gecede indirdik. Şüphesiz biz uyarıcılarız.'),
(44, 4, 25, 496, 'فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ', 'fīhā yufraqu kullu ʾamrin ḥakīm', 'O gecede her hikmetli iş tarafımızdan bir emirle ayrılır.'),
(44, 5, 25, 496, 'أَمْرًا مِّنْ عِندِنَآ إِنَّا كُنَّا مُرْسِلِينَ', 'amran min ʿindinā innā kunnā mursilīn', 'Katımızdan bir emir olarak. Şüphesiz Biz, (peygamberler) gönderenleriz.'),
(44, 6, 25, 496, 'رَحْمَةً مِّن رَّبِّكَ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'raḥmetan mir rabbika ʾinnahu huwa s-semīʿu l-ʿalīmu', 'Rabbinden bir rahmet olarak. Şüphesiz O, hakkıyla işiten, hakkıyla bilendir.'),
(44, 7, 25, 496, 'رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ', 'rabbi s-semāwāti wa-l-arḍi wa mā baynahumā in kuntum mūqinīn', 'Rab, göklerin ve yerin ve ikisinin arasında bulunanların, eğer inanclı iseniz.'),
(44, 8, 25, 496, 'لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 'lā ʾilāha ʾillā huwā yuḥyī wa yumītu rabbukum wa rabbi ʾābāʾikum al-ʾawwalīn', 'O''ndan başka hiçbir ilah yoktur; dirilten ve öldüren O''dur. Sizin ve ilk atalarınızın Rabbidir.'),
(44, 9, 25, 496, 'بَلْ هُمْ فِى شَكٍّ يَلْعَبُونَ', 'bal hum fī shakk-in yalʿabūn', 'Hayır, onlar bir şüphe içindedirler, (Kur''an ile) eğlenmektedirler.'),
(44, 10, 25, 496, 'فَٱرْتَقِبْ يَوْمَ تَأْتِى ٱلسَّمَآءُ بِدُخَانٍ مُّبِينٍ', 'fa-rtaqib yawma taʾtī s-samāʾu bi-dukhānin mubīnin', 'O halde, göğün açık bir duman çıkaracağı günü gözetle!'),
(44, 11, 25, 496, 'يَغْشَى ٱلنَّاسَ هَٰذَا عَذَابٌ أَلِيمٌ', 'yaghsā an-nāsa hādhā ʿadhābun alīmun', 'Bu, insanları saracak elem dolu bir azaptır.'),
(44, 12, 25, 496, 'رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ', 'Rabbanā-kşif ʿannā-l-ʿaḏāb ʾInnā muʾminūn', 'Ey Rabbimiz! Bizden azabı kaldır, çünkü biz iman edenleriz.'),
(44, 13, 25, 496, 'أَنَّىٰ لَهُمُ ٱلذِّكْرَىٰ وَقَدْ جَآءَهُمْ رَسُولٌ مُّبِينٌ', 'annā lahumu dh-dhikrā waqad jāʾahum rasūlun mubīn', 'Onlar için öğüt nerede? Oysa onlara apaçık bir elçi gelmişti.'),
(44, 14, 25, 496, 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌ مَّجْنُونٌ', 'thumma tawallaw ʿanhu wa qālū muʿallamun majnūn', 'Sonra ondan yüz çevirdiler ve ''Bu, öğretilmiş bir mecnundur'' dediler.'),
(44, 15, 25, 496, 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا إِنَّكُمْ عَآئِدُونَ', 'innā kāshifū al-ʿadhābi qalīlan innakum ʿāʾidūn', 'Gerçekten biz azabı biraz kaldıracağız; ama siz (eski halinize) döneceksiniz.'),
(44, 16, 25, 496, 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', 'yawma nabṭiṣu l-baṭshata l-kubrā ʾinnā muntaqimūn', 'O gün, (kâfirlerin) en büyük bir azapla yakalayacağımız gündür. Şüphesiz biz (onlardan) intikam alacağız.'),
(44, 17, 25, 496, 'وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ', 'wa laqad fatannā qablahum qawma firʿawna wa jāʾahum rasūlun karīmun', 'Andarolsun ki onlardan önce Firavun''un kavmini de imtihan ettik ve onlara kerim bir resul geldi.'),
(44, 18, 25, 496, 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', 'ʾan ʾaddū ʾilayya ʿibāda ʾllāhi ʾinnī lakum rasūlun ʾamīnun', 'Ey kullarım! Bana gelince, ben sizin için güvenilir bir elçiyim.'),
(44, 19, 25, 497, 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ إِنِّىٓ ءَاتِيكُم بِسُلْطَٰنٍ مُّبِينٍ', 'wa an lā taʿlū ʿalā Allāh ʾinnī ʾātīkum bisulṭānin mubīn', 'Ve Allah''a karşı büyüklük taslamayın. Şüphesiz ben size apaçık bir delil (yetki) ile geldim.'),
(44, 20, 25, 497, 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', 'wa-innī ʿudhtu bi-rabbī wa-rabbikum an tarjumūn', 'Ve ben, sizin de Rabbiniz olan Rabbime sığınırım, beni taşlamanızdan.'),
(44, 21, 25, 497, 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', 'wa-in lam tuʾminū lī fa-ʿtazilūnī', 'Eğer bana iman etmeyecek olursanız, benden uzak durun!'),
(44, 22, 25, 497, 'فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوْمٌ مُّجْرِمُونَ', 'fadʿā rabbahū anna hāʾulāʾi qawmun mujrimūn', 'Bunun üzerine Rabbi''ne şöyle dua etti: ''Bunlar, suçlu bir kavimdir.'''),
(44, 23, 25, 497, 'فَأَسْرِ بِعِبَادِى لَيْلًا إِنَّكُم مُّتَّبَعُونَ', 'faʾsri biʿibādī laylan ʾinnakum muttabaʿūn', 'Kullarımla geceleyin yürü. Şüphesiz siz takip edileceksiniz.'),
(44, 24, 25, 497, 'وَٱتْرُكِ ٱلْبَحْرَ رَهْوًا إِنَّهُمْ جُندٌ مُّغْرَقُونَ', 'wa-truk il-baḥra rahwan innahum jundun mughraqūn', 'Denizi sakin bırak, çünkü onlar boğulacak bir ordudur.'),
(44, 25, 25, 497, 'كَمْ تَرَكُوا۟ مِن جَنَّٰتٍ وَعُيُونٍ', 'kam tarakū min jannātin wa ʿuyūnin', 'Ne kadar çok bahçeler ve pınarlar bıraktılar!'),
(44, 26, 25, 497, 'وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ', 'wa-zurūʿin wa-maqāmin karīm', 'Ve nice ekinler ve güzel bir makam (da)'),
(44, 27, 25, 497, 'وَنَعْمَةٍ كَانُوا۟ فِيهَا فَٰكِهِينَ', 'wa-naʿmatin kānū fīhā fākihīn', 'Ve içinde şımarıp eğlendikleri nice nimetler (bıraktılar).'),
(44, 28, 25, 497, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا قَوْمًا ءَاخَرِينَ', 'kadhālika wa-awrathnāhā qawman ākharīn', 'İşte böyle! Ve biz onları başka bir kavme miras bıraktık.'),
(44, 29, 25, 497, 'فَمَا بَكَتْ عَلَيْهِمُ ٱلسَّمَآءُ وَٱلْأَرْضُ وَمَا كَانُوا۟ مُنظَرِينَ', 'famā bakat ʿalayhimu s-samāʾu wa-l-arḍu wa mā kānū munẓarīn', 'Ne gökler onların üzerine ağladı, ne de yer; onlara mühlet de verilmedi.'),
(44, 30, 25, 497, 'وَلَقَدْ نَجَّيْنَا بَنِىٓ إِسْرَٰٓءِيلَ مِنَ ٱلْعَذَابِ ٱلْمُهِينِ', 've lekad neccaynâ benî isrâîl mine-l''ażâbi-lmuhîn(i)', 'Andolsun ki İsrailoğulları''nı alçaltıcı azaptan kurtardık.'),
(44, 31, 25, 497, 'مِن فِرْعَوْنَ إِنَّهُۥ كَانَ عَالِيًا مِّنَ ٱلْمُسْرِفِينَ', 'min firʿawna ʾinnahu kāna ʿāliyan mina l-musrifīna', 'Firavun''dan (kurtardık). Çünkü o, haddi aşanlardan biriydi.'),
(44, 32, 25, 497, 'وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ', 'wa laqadi-khtarnāhum ʿalā ʿilmin ʿalā l-ʿālamīn', 'Yemin olsun ki biz onları, (bütün) âlemlere (olan) bilgimizle seçmişizdir.'),
(44, 33, 25, 497, 'وَءَاتَيْنَٰهُم مِّنَ ٱلْءَايَٰتِ مَا فِيهِ بَلَٰٓؤٌا۟ مُّبِينٌ', 'wa ʾātaynāhum mina l-ʾāyāti mā fīhi balāʾun mubīnun', 'Onlara, içinde apaçık bir imtihan bulunan nice ayetler verdik.'),
(44, 34, 25, 497, 'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ', 'ʾinna hāʾulāʾi layaqūlūn', 'Şüphesiz ki bunlar, mutlaka şöyle derler:'),
(44, 35, 25, 497, 'إِنْ هِىَ إِلَّا مَوْتَتُنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ', 'in hiya illā mevtatunā l-ʾūlā ve mā naḥnu bimunšarīn', 'İlk ölümümüzden başka bir şey değildir ve biz yeniden diriltilecek değiliz.'),
(44, 36, 25, 497, 'فَأْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 'faʾtū bi-ʾābāʾinā ʾin kuntum ṣādiqīn', 'Eğer doğru sözlüler iseniz, atalarımızı getirin!'),
(44, 37, 25, 497, 'أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَٱلَّذِينَ مِن قَبْلِهِمْ أَهْلَكْنَٰهُمْ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'ʾahum ḫayrun ʾam qawmu tubbaʿin wa-llaḏīna min qablihim ʾahlaknāhum ʾinnahum kānū mujrimīn', 'Onlar mı daha hayırlı, yoksa Tubba kavmi ve onlardan öncekiler mi? Biz onları helak ettik. Çünkü onlar mücrim idiler.'),
(44, 38, 25, 497, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 'wa mā khalaqnā as-samāwāti wal-arḍa wa mā baynahumā lāʿibīn', 'Biz, gökleri ve yeri ve ikisinin arasında bulunanları bir eğlence (oyun) olsun diye yaratmadık.'),
(44, 39, 25, 497, 'مَا خَلَقْنَٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'Mā khalaqnahumā illā bil-ḥaqqi Wa-lākinna aktharahum lā yaʿlamūn', 'Onları ancak hak ile yarattık; fakat çokları bilmezler.'),
(44, 40, 25, 498, 'إِنَّ يَوْمَ ٱلْفَصْلِ مِيقَٰتُهُمْ أَجْمَعِينَ', 'ʾinna yawma l-faṣli mīqātuhum ʾajmaʿīn', 'Şüphesiz ki fasıl (hak ile batılın ayrılacağı) günü, onların hepsinin toplanma (vadesi)dir.'),
(44, 41, 25, 498, 'يَوْمَ لَا يُغْنِى مَوْلًى عَن مَّوْلًى شَيْـًٔا وَلَا هُمْ يُنصَرُونَ', 'yawma lā yughnī mawlan ʿan mawlan shayʾan walā hum yunṣarūn', 'Öyle bir gün ki, hiçbir dost diğer bir dostu hiçbir şeyden kurtaramaz ve onlara yardım da edilmez.'),
(44, 42, 25, 498, 'إِلَّا مَن رَّحِمَ ٱللَّهُ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 'illa men raḥima Allāhu innahu huwa l-ʿazīzu r-raḥīmu', 'Ancak Allah''ın merhamet ettiği kimseler müstesna. Şüphesiz O, mutlak güç sahibidir, çok merhametlidir.'),
(44, 43, 25, 498, 'إِنَّ شَجَرَتَ ٱلزَّقُّومِ', 'inna shajarata z-zaqqūmi', 'Şüphesiz zakkum ağacı'),
(44, 44, 25, 498, 'طَعَامُ ٱلْأَثِيمِ', 'ṭaʿāmu l-ʾathīmi', 'Günahkârın yiyeceği.'),
(44, 45, 25, 498, 'كَٱلْمُهْلِ يَغْلِى فِى ٱلْبُطُونِ', 'kal-muhli yaghlī fīl-buṭūn', 'Kaynar su gibi, karınlarının içinde kaynamaktadır.'),
(44, 46, 25, 498, 'كَغَلْىِ ٱلْحَمِيمِ', 'kaġalyi l-ḥamīm', 'Kaynar suyun kaynaması gibidir.'),
(44, 47, 25, 498, 'خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ', 'khudhūhu faʿtʿlūhu ilā sawāʾi l-jaḥīm', 'Onu yakalayın da cehennemin ortasına sürükleyip atın!'),
(44, 48, 25, 498, 'ثُمَّ صُبُّوا۟ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ٱلْحَمِيمِ', 'thumma ṣubbū fawqa raʾsihi min ʿadhābi l-ḥamīm', 'Sonra onun başına haşîmî (kaynar su) azabından boca edin.'),
(44, 49, 25, 498, 'ذُقْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْكَرِيمُ', 'dhuq innaka anta l-ʿazīzu l-karīmu', 'Tad bakalım! Gerçekten sen, o çok güçlü, çok şerefli olan sensin!'),
(44, 50, 25, 498, 'إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ', 'ʾinna hāḏā mā kuntum bihi tamtarūn', 'Şüphesiz bu, sizin tereddüt edip durduğunuz şeydir.'),
(44, 51, 25, 498, 'إِنَّ ٱلْمُتَّقِينَ فِى مَقَامٍ أَمِينٍ', 'ʾinna l-muttaqīna fī maqāmin ʾamīnin', 'Şüphesiz takva sahipleri güvenli bir makamdadırlar.'),
(44, 52, 25, 498, 'فِى جَنَّٰتٍ وَعُيُونٍ', 'fī jannātin wa ʿuyūnin', 'Onlar, (o gün) cennetlerde ve pınar başlarında.'),
(44, 53, 25, 498, 'يَلْبَسُونَ مِن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَقَٰبِلِينَ', 'yalbasūna min sundusin wa istabraqin mutaqābilīn', 'İnce ve kalın ipekten (giysiler) giyerler, karşılıklı otururlar.'),
(44, 54, 25, 498, 'كَذَٰلِكَ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍ', 'kadhalika wa zawwajnahum biḥūrin ʿīn', 'İşte böyle! Biz de onları iri gözlü (ve güzel) hurilerle evlendirmişizdir.'),
(44, 55, 25, 498, 'يَدْعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ', 'yadʿūna fīhā bikulli fākihatin ʾāminīn', 'Onlar orada her türlü meyveden (isteyip) emin olarak çağırırlar.'),
(44, 56, 25, 498, 'لَا يَذُوقُونَ فِيهَا ٱلْمَوْتَ إِلَّا ٱلْمَوْتَةَ ٱلْأُولَىٰ وَوَقَىٰهُمْ عَذَابَ ٱلْجَحِيمِ', 'lā yaḏūqūna fīhā l-mawta ʾillā l-mawta l-ʾūlā wa waqāhum ʿaḏāba l-ğaḥīm', 'Orada ilk ölümden başka bir ölüm tatmazlar. Ve onları cehennem azabından korumuştur.'),
(44, 57, 25, 498, 'فَضْلًا مِّن رَّبِّكَ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'faḍlan min rabbika dhālika huwa l-fawzu l-ʿaẓīmu', 'Rabbinin bir lütfudur. İşte büyük kurtuluş budur.'),
(44, 58, 25, 498, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'fa-ʾinnamā yassarnāhu bi-lisānika laʿallahum yataḏakkarūn', 'Biz onu senin dilinde ancak, düşünüp ibret alsınlar diye kolaylaştırdık.'),
(44, 59, 25, 498, 'فَٱرْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ', 'fartaqib innahum murtaqibūn', 'Artık gözetle! Şüphesiz onlar da gözetleyicidirler.'),
(45, 1, 25, 499, 'حمٓ', 'Ḥā Mīm', 'Ha, Mim.'),
(45, 2, 25, 499, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'Tanzīlu l-kitābi mina llāhi l-ʿazīzi l-ḥakīmi', 'Bu Kitabın indirilişi, mutlak güç sahibi, hüküm ve hikmet sahibi Allah''tandır.'),
(45, 3, 25, 499, 'إِنَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَءَايَٰتٍ لِّلْمُؤْمِنِينَ', 'inna fī s-samāwāti wa-l-arḍi la-āyātin lil-muʾminīn', 'Şüphesiz göklerde ve yerde iman edenler için (Allah''ın varlığına ve kudretine) nice deliller vardır.'),
(45, 4, 25, 499, 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٌ لِّقَوْمٍ يُوقِنُونَ', 'wa-fī khalqikum wa-mā yubaththu min dābbatin ʾāyātun li-qawmin yūqinūn', 'Sizi yaratmamızda ve yeryüzünde yaydığı her türlü canlıda, kesin bilgiye ulaşmak isteyen bir topluluk için nice deliller vardır.'),
(45, 5, 25, 499, 'وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَٰحِ ءَايَٰتٌ لِّقَوْمٍ يَعْقِلُونَ', 'wa-khtilāfi l-layli wa-n-nahāri wa-mā anzala l-lāhu mina s-samāʾi min rizqin fa-aḥyā bihi l-arḍa baʿda mawatihā wa-taṣrīfi r-riyāḥi āyātun li-qawmin yaʿqilūna', 'Gece ile gündüzün değişmesi, Allah''ın gökten indirip de onunla yeryüzünü ölümünden sonra canlandırdığı rızık ve rüzgârların yön değiştirmesi de, aklını kullanan bir topluluk için Allah''ın varlığının delilleridir.'),
(45, 6, 25, 499, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤْمِنُونَ', 'tilka āyātu llāhi natlūhā ʿalayka bil-ḥaqqi fa-bi-ʾayyi ḥadīthin baʿda llāhi wa-ʾāyātihi yuʾminūna', 'Bunlar, sana hak olarak okuduğumuz Allah''ın ayetleridir. Allah''a ve O''nun ayetlerine inanmadıktan sonra hangi söze inanacaklar?'),
(45, 7, 25, 499, 'وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ', 'waylun likulli ʾaffākin ʾathīmin', 'Ve o, her yalancı günahkara yazıklar olsun!'),
(45, 8, 25, 499, 'يَسْمَعُ ءَايَٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', 'yasmaʿu ʾāyāti ʾllāhi tutlā ʿalayhi ṯumma yuṣirru mustakbiran kaʾan lam yasmaʿhā fabašširhu biʿaḏābin ʾalīmin', 'Allah''ın ayetleri kendisine okunduğu zaman, büyüklük taslayarak sanki onları hiç işitmemiş gibi davranır. Ona acı bir azabı müjdele!'),
(45, 9, 25, 499, 'وَإِذَا عَلِمَ مِنْ ءَايَٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'wa ʾiḏā ʿalima min ʾāyātinā šayʾan ittaxaḏahā huzuwan ʾulāʾika lahum ʿaḏābun muhīnun', 'Onlar, bizim ayetlerimizden bir şey öğrendiklerinde onu alay konusu edinirler. İşte onlar için rezil edici bir azap vardır.'),
(45, 10, 25, 499, 'مِّن وَرَآئِهِمْ جَهَنَّمُ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'min warāʾihim jahannam wa lā yughnī ʿanhum mā kasabū shayʾan wa lā mā ʾittakhadhū min dūni ʾllāhi ʾawliyāʾa wa lahum ʿadhābun ʿaẓīmun', 'Onların ardından cehennem vardır. Kazandıkları hiçbir şey, Allah''tan başka edindikleri veliler de kendilerinden hiçbir fayda sağlamaz. Onlar için büyük bir azap vardır.'),
(45, 11, 25, 499, 'هَٰذَا هُدًى وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', 'hādhā hudan wa-lladhīna kafarū bi-āyāti rabbihim lahum ʿadhābun min rijzin alīmun', 'Bu bir hidayettir. Rablerinin ayetlerini inkâr edenlere ise şiddetli, acı veren bir azap vardır.'),
(45, 12, 25, 499, 'ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Allāhu alladhī sakhkhara lakumu l-baḥra litajriya l-fulku fīhi bi-amrihī wa-litabtaghū min faḍlihī wa-laʿallakum tashkurūn', 'Allah, O’dur ki denizi sizin emrinize amade kıldı ki, gemiler onun üzerinde (Allah’ın) emriyle akıp gitsin ve O’nun lütfundan (rızkınızı) arayasınız. Umulur ki şükredersiniz.'),
(45, 13, 25, 499, 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًا مِّنْهُ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'wa-sakhkhara lakum mā fī s-samāwāti wa-mā fī l-arḍi jamīʿan minhu inna fī dhālika la-ʾāyātin li-qawmin yatafakkarūn', 'Göklerde ve yerde ne varsa hepsini, (kendi) katından sizin buyruğunuza amade kılmıştır. Elbette bunlarda, düşünen bir topluluk için ibretler vardır.'),
(45, 14, 25, 500, 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'qul lilladhīna ʾāmanū yaghfirū lilladhīna lā yarjūna ʾayyāma ʾllāhi liyajziya qawman bimā kānū yaksibūna', 'İman edenlere söyle: Allah''ın günlerini ummayanları bağışlasınlar. Çünkü her topluluğu, kazandıklarıyla cezalandıracaktır.'),
(45, 15, 25, 500, 'مَنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'man ʿamila ṣāliḥan faliṉfsihi veman asāʾa feʿalayhā ṯumma ilā rabbikum turjaʿūna', 'Kim iyi bir iş yaparsa, kendi lehine yapmış olur. Kim de kötülük yaparsa, kendi aleyhine yapmış olur. Sonra Rabbinize döndürüleceksiniz.'),
(45, 16, 25, 500, 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَى ٱلْعَٰلَمِينَ', 've lekad ʾātaynā banī ʾisrāʾīle l-kitābe vel-ḥukme ven-nubuvvete ve razaknāhum mine ṭ-ṭayyibāti ve faḍḍalnāhum ʿale l-ʿālemīne', 'Andolsun ki biz, İsrailoğulları''na Kitab''ı, hükmü ve peygamberliği verdik, onları temiz ve güzel şeylerden rızıklandırdık ve onları âlemlere üstün kıldık.'),
(45, 17, 25, 500, 'وَءَاتَيْنَٰهُم بَيِّنَٰتٍ مِّنَ ٱلْأَمْرِ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 'wa ʾātaynāhum bayyinātin mina l-ʾamri famā ḵtalafū ʾillā min baʿdi mā jāʾahumu l-ʿilmu baghyan baynahum ʾinna rabbaka yaqḍī baynahum yawma l-qiyāmati fīmā kānū fīhi yaḵtalifūn', 'Onlara emir (din) konusunda apaçık deliller verdik. Kendilerine ilim geldikten sonra, aralarındaki kıskançlık ve azgınlık yüzünden ayrılığa düştüler. Şüphesiz Rabbin, kıyamet gününde, hakkında ayrılığa düştükleri hususlarda aralarında O hükmedecektir.'),
(45, 18, 25, 500, 'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', 'thumma jaʿalnāka ʿalā sharīʿatin mina l-amri fāttabiʿhā walā tattabiʿ ahwāʾa lladhīna lā yaʿlamūn', 'Sonra sana dinden bir şeriat (yol) verdik. Sen ona uy ve bilmeyenlerin heveslerine uyma.'),
(45, 19, 25, 500, 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًٔا وَإِنَّ ٱلظَّٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', 'ʾinnahum lan yughnū ʿanka mina llāhi shayʾan wa ʾinna ẓ-ẓālimīna baʿḍuhum ʾawliyāʾu baʿḍin wa llāhu waliyyu l-muttaqīna', 'Şüphesiz onlar, Allah''tan (gelecek) hiçbir şeyi senden asla savamazlar. Şüphesiz zalimler birbirlerinin velileridir. Allah ise takva sahiplerinin velisidir.'),
(45, 20, 25, 500, 'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُوقِنُونَ', 'hādhā baṣāʾiru li-n-nāsi wa-hudan wa-raḥmatun li-qawmin yūqinūna', 'Bu (Kur''an), insanlar için basiretlerdir, yakîn (kesin bilgi) sahibi bir topluluk için de bir hidayet ve bir rahmettir.'),
(45, 21, 25, 500, 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءً مَّحْيَاهُمْ وَمَمَاتُهُمْ سَآءَ مَا يَحْكُمُونَ', 'am ḥasiba lladhīna ij''taraḥū s-sayyiʾāti an najʿalahum ka-lladhīna āmanū wa ʿamilū ṣ-ṣāliḥāti sawāʾan maḥyāhum wa mamātuhum sāʾa mā yaḥkumūna', 'Yoksa kötülükleri işleyenler, iman edip salih amel işleyenler gibi olacağımızı mı sandılar? Hükümlerinin ne kadar kötü!'),
(45, 22, 25, 500, 'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'wa ḵalaqa ʾllāhu ʾssamāwāti wa-l-ʾarḍa bi-l-ḥaqqi wa li-tujzā kullu nafsin bimā kasabat wa hum lā yuẓlamūn', 'Allah, gökleri ve yeri hak ile yaratmıştır. Her nefis, kazandığıyla karşılığını alsın diye (böyle yapmıştır). Onlar zulme uğratılmazlar.'),
(45, 23, 25, 501, 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةً فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ أَفَلَا تَذَكَّرُونَ', 'ʾafaraʾayta mani-ttakhaḏa ʾilāhahu hāwāhu wa-ʾaḍallahul-lāhu ʿalā ʿilmin wa-khatama ʿalā samʿihi wa-qalbihi wa-jaʿala ʿalā baṣarihi ġišāwatan fa-man yahdīhi mim-baʿdil-lāhi ʾafalā taḏakkarūn', 'Kendi hevasını ilah edineni gördün mü? Allah, bilgisini gerektirerek onu saptırmış, kulaklarını ve kalbini mühürlemiş ve gözlerinin üzerine de bir perde çekmiştir. Allah''tan başka ona kim yol gösterebilir? Hâlâ öğüt alıp düşünmez misiniz?'),
(45, 24, 25, 501, 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَظُنُّونَ', 'wa qālū mā hiya illā ḥayātunā ad-dunyā namūtu wa naḥyā wa mā yuhlikunā illā ad-dahru wa mā lahum biḏālika min ʿilmin in hum illā yaẓunnūn', 'Ve dediler ki: "Hayat ancak bu dünyada bizim için geçerli olan hayatımızdır; ölürüz ve yaşarız. Bizi helak eden ancak zamandır." Onların bu hususta hiçbir bilgileri yoktur. Onlar ancak zanda bulunuyorlar.'),
(45, 25, 25, 501, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 'wa-idhā tutlā ʿalayhim ʾāyātunā bayyinātin mā kāna ḥujjatahum ʾillā ʾan qālū ʾtiū bi-ʾābāʾinā ʾin kuntum ṣādiqīn', 'Onlara âyetlerimiz apaçık okunduğunda, delilleri ancak: "Eğer doğru söylüyorsanız, atalarımızı getirin" demekten başka bir şey olmayanların delilleri şunlardır.'),
(45, 26, 25, 501, 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'quli ʾallāhu yuḥyīkum thumma yumītukum thumma yajmaʿukum ʾilā yawmi l-qiyāmati lā rayba fīhi walākinna ʾakthara n-nāsi lā yaʿlamūn', 'De ki: "Sizi Allah yaşatır, sonra öldürür, sonra da kendisinde şüphe olmayan kıyamet günü toplar. Fakat insanların çoğu bilmezler."'),
(45, 27, 25, 501, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَخْسَرُ ٱلْمُبْطِلُونَ', 'wa lil-lāhi mulku s-samāwāti wa l-arḍi wa yawma taqūmu s-sāʿatu yawmaʾiḏin yakhsaru l-mubṭilūna', 'Göklerin ve yerin mülkiyeti/hükümranlığı Allah''a aittir. Kıyamet (saat) koptuğu gün, işte o gün batıl ehli/boş işler yapanlar hüsrana uğrayacaktır.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(45, 28, 25, 501, 'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً كُلُّ أُمَّةٍ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'wa tarā kulla ummatin jāthiyatan kullu ummatin tudʿā ilā kitābihā al-yawma tujzawna mā kuntum taʿmalūn', 'Her ümmetin diz çökmüş olduğunu görürsün. Her ümmet kendi kitabına çağrılır. (Onlara şöyle denir:) ''Bugün yaptıklarınızla cezalandırılacaksınız.'''),
(45, 29, 25, 501, 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', 'hādhā kitābunā yanṭiqu ʿalaykum bil-ḥaqqi ʾinnā kunnā nastansikhu mā kuntum taʿmalūn', 'İşte bu, aleyhinize hak ile konuşan kitabımızdır. Çünkü biz, yapmakta olduklarınızı kaydediyorduk.'),
(45, 30, 25, 501, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', 'faʾammā alladhīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti fayudkhiluhum rabbuhum fī raḥmatihi dhālika huwa l-fawzu l-mubīnu', 'İman edip salih amel işleyenlere gelince, Rableri onları rahmetine kabul eder. İşte bu, apaçık kurtuluştur.'),
(45, 31, 25, 501, 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ', 'waʾammā alladhīna kafarū ʾafalam takun ʾāyātī tutlā ʿalaykum fastakbartum wakuntum qawman mujrimīn', 'İnkâr edenlere gelince, onlara: "Ayetlerim size okunuyordu da siz yine de büyüklük taslayıp suçlu bir kavim olmuştunuz, değil mi?" (denilir).'),
(45, 32, 25, 501, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', 'wa iḏā qīla ʾinna waʿda ʾallāhi ḥaqqun wa-s-sāʿatu lā rayba fīhā qultum mā nadrī mā s-sāʿatu ʾin naẓunnu ʾillā ẓannā wa mā naḥnu bi-mustayqinīn', 'Hani, "Şüphesiz Allah''ın vaadi gerçektir ve kıyamet gününün gelmesinde hiçbir şüphe yoktur" denildiğinde siz, "Kıyamet nedir, bilmiyoruz! Biz sadece zannederiz, biz kesin bilgiye ermiş değiliz" demiştiniz.'),
(45, 33, 25, 502, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'wa badā lahum sayyiʾātu mā ʿamilū wa ḥāqa bihim mā kānū bihī yastahziʾūn', 'Ve yaptıkları şeytani işler onlara göründü ve alay etmekte oldukları şey onları kuşattı.'),
(45, 34, 25, 502, 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 'wa qīla l-yawma nansākum kamā nasītum liqāʾa yawmikum hādhā wa maʾwākumu n-nāru wa mā lakum min nāṣirīn', 'Ve şöyle denildi: "Bugün biz de sizi, tıpkı sizin bu gününüze kavuşmayı unuttuğunuz gibi unutacağız. Varacağınız yer ateştir ve sizin için hiçbir yardımcı yoktur."'),
(45, 35, 25, 502, 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَٰتِ ٱللَّهِ هُزُوًا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 'dhālikum bi-ʾannakumū t-takhadhtum ʾāyāti llāhi huzuwan wa-gharratkumū l-ḥayātu d-dunyā fa-l-yawma lā yukhrajūna minhā wa-lā hum yustaʿtabūna', 'Bu sizin, Allah''ın âyetlerini alaya almanızdan ve dünya hayatının sizi aldatmasından dolayıdır. İşte o gün onlara oradan çıkarılma yoktur ve onlar (Allah''ın rızasını kazanmak için) özür dilemeye de sevkedilmezler.'),
(45, 36, 25, 502, 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَٰلَمِينَ', 'Falillāhil-ḥamdu rabbiṣ-semāwāti wa rabbi l-arḍi rabbi l-ʿālamīn', 'Göklerin ve yerin Rabbi, alemlerin Rabbi Allah''ındır hamd!'),
(45, 37, 25, 502, 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'wa-lahu l-kibriyāʾu fī s-samāwāti wa-l-arḍi wa-huwa l-ʿazīzu l-ḥakīmu', 'Göklerde ve yerde büyüklük O''na aittir. O, Azîz''dir, Hakîm''dir.'),
(46, 1, 26, 502, 'حمٓ', 'Ḥā Mīm', 'Ha, Mim.'),
(46, 2, 26, 502, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'Tanzīlu l-kitābi mina l-lāhi l-ʿazīzi l-ḥakīm', 'Bu Kitabın indirilmesi, O mutlak güç sahibi, hüküm ve hikmet sahibi Allah''tandır.'),
(46, 3, 26, 502, 'مَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', 'Mā khalaqnā s-samāwāti wa-l-arḍa wa mā baynahumā illā bi-l-ḥaqqi wa ajalim musammā Wa-lladhīna kafarū ʿammā unḏirū muʿriḍūna', 'Biz gökleri ve yeri ve aralarındakileri ancak hak ile ve belirli bir süre için yarattık. İnkâr edenler, kendilerine yapılan uyarıdan yüz çevirmektedirler.'),
(46, 4, 26, 502, 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ ٱئْتُونِى بِكِتَٰبٍ مِّن قَبْلِ هَٰذَآ أَوْ أَثَٰرَةٍ مِّنْ عِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'qul ʾaraʾaytum mā tadʿūna min dūni ʾllāhi ʾarūnī māḏā ḫalaqū mina l-ʾarḍi ʾam lahum širkuⁿ fī s-samāwāti ʾtūnī bikitābiⁿ min qabli hāḏā ʾaw ʾaṯāratiⁿ min ʿilmin ʾin kuntum ṣādiqīna', 'De ki: «Şunları bana bildirin; Allah''tan başka taptıklarınız, yeryüzünden ne yaratmışlardır? Yoksa onların göklerde bir ortaklığı mı vardır? Eğer doğru sözlüler iseniz, bundan önceki bir kitap veya (bilgi) kalıntısı getirin bana!»'),
(46, 5, 26, 502, 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَٰفِلُونَ', 'Ve men aḍallu mimmen yedʿū min dūni-llāhi men lā yastacību lehū ʾilā yawmi-lqiyāmati ve hum ʿan duʿāʾihim ġāfilūn', 'Allah''tan başka, kıyamet gününe kadar kendisine cevap veremeyecek ve kendilerinin de dualarından haberi olmayan kimselere dua eden kimseden daha sapık kim olabilir?'),
(46, 6, 26, 503, 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءً وَكَانُوا۟ بِعِبَادَتِهِمْ كَٰفِرِينَ', 'wa-ʾidhā ḥushira n-nāsu kānū lahum ʾaʿdāʾan wa-kānū bi-ʿibādatihim kāfirīna', 'İnsanlar toplandığı zaman (onların) düşmanları olurlar ve taptıklarına küfrederler.'),
(46, 7, 26, 503, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَٰذَا سِحْرٌ مُّبِينٌ', 'wa ʾiḏā tutlā ʿalayhim ʾāyātunā bayyināt qāla lladīna kafarū lilḥaqqi lammā jāʾahum hāḏā siḥrun mubīn', 'Onlara apaçık âyetlerimiz okunduğu zaman, o kâfirler: "Bu, apaçık bir sihirdir" dediler.'),
(46, 8, 26, 503, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'am yaqūlūna iftārāhu qul in iftáraytuhu falā tamlikūna lī mina Allāhi shayʾan huwa ʾaʿlamu bimā tufīḍūna fīhi kafā bihi shahīdan baynī wa-baynakum wa-huwa l-ghafūru r-raḥīmu', 'Yoksa, "Onu kendisi uydurdu" mu diyorlar? De ki: "Eğer onu uydurmuşsam, (o zaman) Allah''tan bana hiçbir şey sağlayamazsınız. O, sizin hakkında neler konuştuğunuzu çok iyi bilendir. Benimle sizin aranızda O''nun şahit olması yeter. O, çok bağışlayandır, çok merhamet edendir."'),
(46, 9, 26, 503, 'قُلْ مَا كُنتُ بِدْعًا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', 'qul mā kuntu bidʿan mina r-rusuli wa mā adrī mā yufʿalu bī wa lā bikum in attabiʿu illā mā yūḥā ilayya wa mā anā illā nadhīrun mubīnun', 'De ki: Ben peygamberlerin ilki değilim. Bana ve size ne yapılacağını da bilmem. Ben ancak bana vahyolunana uyarım ve ben apaçık bir uyarıcıdan başkası değilim.'),
(46, 10, 26, 503, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'qul ʾaraʾaytum ʾin kāna min ʿindi llāhi wa-kafartum bihi wa-šahida šāhidun min banī ʾisrāʾīla ʿalā mithlihi fa-ʾāmana wa-stakbartum ʾinna llāha lā yahdī l-qawma ẓ-ẓālimīn', 'De ki: «Bana haber verin! Eğer bu (Kur''an) Allah tarafından (gelmiş) olup da siz onu inkâr etmişseniz ve İsrailoğullarından bir şahit de onun benzerine (benzeri gelmiş olduğuna) şehadet edip kendisi iman etmiş ve siz de kibirlenmişseniz (ne yaparsınız)? Şüphesiz Allah, zalimler güruhunu doğru yola eriştirmez.»'),
(46, 11, 26, 503, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًا مَّا سَبَقُونَآ إِلَيْهِ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكٌ قَدِيمٌ', 'waqāla lladhīna kafarū lilladhīna ʾāmanū law kāna khayran mā sabaqūnā ʾilayhi wa-ʾidh lam yahtadū bihi fasayaqūlūna hādhā ʾifkun qadīmun', 'İnkâr edenler, iman edenlere dediler ki: "Bu (Kur''an) hayır olsaydı, onu bize getirmeden önce ona inanmazlardı." Ve hidayete ermedikleri için de "Bu, evvelki uydurulmuş masallardan başka bir şey değildir!" diyeceklerdir.'),
(46, 12, 26, 503, 'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً وَهَٰذَا كِتَٰبٌ مُّصَدِّقٌ لِّسَانًا عَرَبِيًّا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', 'wa min qablihi kitābu Mūsā imāman wa raḥmah wa hādhā kitābun muṣaddiqun lisānan ʿarabiyyan liyunzira alladhīna ẓalamū wa bushra lilmuḥsinīn', 'Ve ondan önce de Musa''nın, bir önder ve bir rahmet olarak getirdiği Kitap vardı. İşte bu da (Kur''an) Arapça''dır, zalimleri uyarmak ve iyilik edenlere müjde vermek üzere, kendinden öncekileri doğrulayan bir Kitaptır.'),
(46, 13, 26, 503, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'ʾinna lladhīna qālū rabbunā ʾllāhu thumma stiqāmū falā khawfun ʿalayhim walā hum yaḥzanūna', 'Şüphesiz, "Rabbimiz Allah’tır" deyip de sonra dosdoğru olanlar için hiçbir korku yoktur ve onlar mahzun da olmayacaklardır.'),
(46, 14, 26, 503, 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'ʾulāʾika ʾaṣḥābu l-jannati khālidīna fīhā jazāʾam bimā kānū yaʿmalūn', 'İşte onlar, yapmakta oldukları amellerin bir karşılığı olarak, içinde ebedi kalacakları cennet ehlidirler.'),
(46, 15, 26, 504, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ إِحْسَٰنًا حَمَلَتْهُ أُمُّهُۥ كُرْهًا وَوَضَعَتْهُ كُرْهًا وَحَمْلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهْرًا حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', 'wa waṣṣaynā al-insāna biwālidayhi iḥsānan ḥamalat''hu ummuhu kurhan wawadaʿat''hu kurhan wa ḥamlu''hu wafiṣālu''hu thalāthūna shahran ḥattā idhā balagha ashuddahu wabalagha arbaʿīna sanatan qāla rabbi awziʿnī an ashkura niʿmataka allatī anʿamta ʿalayya waʿalā wālidayya wa an aʿmala ṣāliḥan tarḍāhu wa aṣliḥ lī fī dhurriyyatī innī tubtu ilayka wa innī mina al-muslimīna', 'İnsana da annesi babasına iyilik etmeyi emrettik. Annesi onu zorlukla taşıdı ve zorlukla doğurdu. Onun (anne karnında) taşınması ile sütten kesilmesi otuz ay sürer. Nihayet olgunluk çağına erip kırk yaşına geldiğinde şöyle der: "Rabbim! Bana ve anneme babama verdiğin nimetlere şükretmemi, razı olacağın salih amel işlememi nasip et. Benim için zürriyetimden de salahiyetli kimseler kıl. Şüphesiz ben tevbe edip sana yöneldim ve şüphesiz ben müslümanlardanım."'),
(46, 16, 26, 504, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَٰبِ ٱلْجَنَّةِ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'ʾūlāʾik alladhīna nataqabbalu ʿanhum ʾaḥsana mā ʿamilū wa natajāwazu ʿan sayyiʾātihim fī ʾaṣḥābi l-jannati waʿda ṣ-ṣidqi lladhī kānū yūʿadūn', 'İşte onlar, kendilerinden yapmış olduklarının en güzelini kabul ettiğimiz ve kötülüklerini bağışladığımız kimselerdir. Bunlar, cennetlikler arasındadır. Bu, onlara vaad olunan doğru vaaddir.'),
(46, 17, 26, 504, 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'wa-lladhī qāla li-wālidayhi uffin lakumā a-taʿidāninī an ukhraja wa-qad khalati l-qurūnu min qablī wa-humā yastaghīthāni l-lāha waylaka āmin inna waʿda l-lāhi ḥaqqun fa-yaqūlu mā hādhā illā asāṭīru l-awwalīna', 'Ana babasına: "Öf size! Beni tekrar diriltileceğimi mi vaat ediyorsunuz? Halbuki benden önce nice nesiller gelip geçmiş, yok olup gitmiştir. Oysa siz ikiniz Allah''tan yardım dileyin! Yazıklar olsun sana, iman et! Şüphesiz Allah''ın vaadi gerçektir" diyen kimseye (ne büyük azap!) diyen kimseye (ne büyük azap!). O ise: "Bu, öncekilerin masallarından başka bir şey değildir" der.'),
(46, 18, 26, 504, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'ʾUlaʾika lladhīna ḥaqqa ʿalayhimu l-qawlu fī ʾumamin qad ḵalat min qablihim mina l-jinni wa-l-ʾinsi ʾInnahum kānū khāsirīna', 'İşte bunlar, kendilerinden önce geçmiş cin ve insan toplulukları içinde haklarında azap sözü gerçekleşmiş olanlardır. Çünkü onlar ziyana uğrayanlardı.'),
(46, 19, 26, 504, 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَلِيُوَفِّيَهُمْ أَعْمَٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', 'wa likullin darajātun mimmā ʿamilū wa liyuwaffiyahum aʿmālahum wa hum lā yuẓlamūn', 'Herkesin yaptıklarına karşılık dereceleri vardır. (Allah) onlara yaptıklarının karşılığını tastamam verir ve onlara zulmedilmez.'),
(46, 20, 26, 504, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', 'wa-yawma yuʿraḍu l-ladhīna kafarū ʿalā n-nār adh-habtum ṭayyibātikum fī ḥayātikumu d-dunyā wa-stamtatum bihā fa-l-yawma tujzawna ʿadhāba l-hūni bimā kuntum tastakbirūna fī l-arḍi bi-ghayri l-ḥaqqi wa-bimā kuntum tafsuqūna', 'Kâfirler ateşe arz olundukları gün (onlara şöyle denir): "Dünya hayatınızda bütün güzel şeylerinizi harcadınız ve onlardan zevk aldınız. Bu yüzden bugün, yeryüzünde haksız yere büyüklük taslamanızdan ve fasıklık etmenizden dolayı aşağılayıcı azap ile cezalandırılacaksınız."'),
(46, 21, 26, 505, 'وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'wa-dhkur ʾakhā ʿādin ʾidh ʾanḏara qawmahū bi-l-ʾaḥqāfi wa-qad ḵalati ʾn-nuḏuru min bayni yadayhi wa-min ḵalfihi ʾallā taʿbudū ʾillā ʾllāh ʾinnī ʾakhāfu ʿalaykum ʿaḏāba yawmin ʿaẓīmin', 'Ad kavminin (soylarından) kardeşi (Hud''u) hatırla. Hani o, Ahkaf denilen yerde kavmini uyararak şöyle demişti: ''Benden önce ve sonra da nice peygamberler gelip geçti. Allah''tan başkasına kulluk etmeyin. Şüphesiz ben, sizin için büyük bir günün azabından korkuyorum.'''),
(46, 22, 26, 505, 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'qālū ʾaǰiʾtanā litaʾfikana ʿan ʾālihatinā faʾtinā bimā taʿidunā ʾin kunta mina ṣ-ṣādiqīn', 'Dediler ki: "Sen bize ilahlarımızdan vazgeçirmek için mi geldin? Eğer doğru söyleyenlerden isen, haydi bizi tehdit ettiğin azabı getir!"'),
(46, 23, 26, 505, 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', 'qāla innamā l-ʿilmu ʿinda llāhi wa ubullighukum mā ursiltu bihi wa lākinnī arākum qawman tajhalūn', 'Onun ilmi ancak Allah''ın yanındadır. Size gönderildiğim şeyi tebliğ ediyorum ve sizin cahil bir kavim olduğunuzu görüyorum.'),
(46, 24, 26, 505, 'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَٰذَا عَارِضٌ مُّمْطِرُنَا بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ', 'fe lemmā raʾevhu ʿāriḍan mustaqbile ʾawdiyetihim qālū hāḏā ʿāriḍun mumṭirunā bel huve mā staʿceltum bihī rīḥun fīhā ʿaḏābun ʾelīmun', 'Nihayet onu, vadi(ler)ine doğru yönelmiş bir bulut halinde gördüklerinde: "Bu bize yağmur getirecek bir buluttur!" dediler. Hayır! O, sizin acele istediğiniz şeydir; içinde elem dolu bir azap bulunan bir rüzgardır.'),
(46, 25, 26, 505, 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمْ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 'tudammiru kulla shay''in bi''amri rabbihā fa''aṣbaḥū lā yura illā masākinuhum kadhālika najzī l-qawma l-mujrimīn', 'Rabbinin emriyle her şeyi yerle bir eden (bir rüzgar) idi. İşte biz, suçlu toplumu böyle cezalandırırız.'),
(46, 26, 26, 505, 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَٰرًا وَأَفْـِٔدَةً فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'Ve lekad mekkennâhum fîmâ in mekkennâkum fîhi Ve cealnâ lehum sem''an ve ebsâran ve ef''ideten Femâ ağnâ anhum sem''uhum ve lâ ebsâruhum ve lâ ef''idetuhum min şey''in İz kânû yechadûne bi''âyâti(A)llâhi Ve hâka bihim mâ kânû bihî yestehzi''ûn', 'Andolsun ki Biz onları, size vermediğimiz imkanlarla güçlendirmiştik. Onlara kulaklar, gözler ve kalpler vermiştik. Fakat Allah''ın ayetlerini inkar etmeleri yüzünden ne kulakları, ne gözleri ne de kalpleri onlara hiçbir fayda sağlamadı. Ve alay ettikleri şey onları kuşattı.'),
(46, 27, 26, 505, 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْءَايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ', 'wa laqad ahlaknā mā ḥawlakum min al-qurā wa ṣarrafnā al-āyāti laʿallahum yarjiʿūn', 'Çevrenizdeki memleketleri helak ettik ve belki dönerler diye ayetleri (çeşitli şekillerde) açıkladık.'),
(46, 28, 26, 505, 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ بَلْ ضَلُّوا۟ عَنْهُمْ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', 'falawlā naṣarahumu-lladhīna-ttakhadhū min dūni-llāhi qurbānan ʾālihah bal ḍallū ʿanhum wa-dhālika ʾifkuhum wa-mā kānū yaftarūn', 'Allah''tan başka, O''na yakınlık sağlamak üzere tanrı edindikleri kimseler onlara yardım etmeli değil miydi? Hayır! Onlar kendilerinden kaybolup gittiler. İşte bu, onların yalanı ve uydurmakta oldukları şeydir.'),
(46, 29, 26, 506, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', 'wa-ʾiḏ ṣarafnā ʾilayka nafaran min al-jinni yastamiʿūna al-qurʾāna fal-lammā ḥaḍarūhu qālū ʾanṣitū fal-lammā quḍiya wallaw ʾilā qawmihim munḏirīn', 'Hani cinlerden bir grubu sana yöneltmiştik de Kur''an dinlemeye geldiklerinde birbirlerine, "Susun!" demişlerdi. Kur''an okunup bitince de kavimlerine uyarıcılar olarak dönmüşlerdi.'),
(46, 30, 26, 506, 'قَالُوا۟ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ', 'qālū yā qawmanā innā samiʿnā kitāban unzila min baʿdi Mūsā muṣaddiqan limā bayna yadayhi yahdī ilā l-ḥaqqi wa-ilā ṭarīqin mustaqīm', 'Dediler ki: "Ey kavmimiz! Gerçekten biz, Musa''dan sonra indirilen, önündekileri doğrulayan, Allah''a çağıran ve dosdoğru yolu gösteren bir Kitap dinledik."'),
(46, 31, 26, 506, 'يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ', 'yā qawmanā ʾajībū dāʿiya ʾllāhi wa ʾāminū bihi yaghfir lakum min dhunūbikum wa yujirakum min ʿadhābin ʾalīmin', 'Ey kavmimiz! Allah''ın davetçisine uyun ve O''na iman edin ki günahlarınızdan bir kısmını bağışlasın ve sizi elem dolu bir azaptan korusun.'),
(46, 32, 26, 506, 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', 'Ve men lā yucib dāʿiya Allāhi felaysa bimuʿcizin fīl-ʾarḍi veleysa lehū min dūnihi ʾawliyāʾu ʾUlaāʾike fī ḍalālin mubīnin', 'Allah''ın davetçisine icabet etmeyene gelince, yeryüzünde (Allah''ı) aciz bırakacak değildir. Onların Allah''tan başka yardımcıları da yoktur. İşte bunlar apaçık bir sapıklık içindedirler.'),
(46, 33, 26, 506, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'E velemd yerav enne-llāhe-lleẕī halaka-s-semāvāti ve-l-ʾarḍa ve lem yaʿye bihalqihinne biqādirin ʿalā ʾen yuḥyiye-l-mevtā Belā ʾInnehu ʿalā kulli şeyʾin qadīrun', 'Onlar, gökleri ve yeri yaratan ve onları yaratmakla yorulmayan Allah''ın, ölüleri diriltmeye de gücü yetmediğini görmediler mi? Hayır! Şüphesiz O, her şeye hakkıyla gücü yetendir.'),
(46, 34, 26, 506, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'wa-yawma yuʿraḍu alladhīna kafarū ʿalā an-nār ʾalaysa hādhā bi-l-ḥaqq qālū balā wa-rabbanā qāla fa-dhūqū al-ʿadhāba bimā kuntum takfurūn', 'İnkâr edenler ateşe arz olundukları gün: "Bu, hak değil mi?" diye sorulurlar. Onlar: "Evet, Rabbimize yemin ederiz ki, hak" derler. Allah: "Öyleyse inkâr etmekte olduğunuz şeyden dolayı azabı tadın!" buyurur.'),
(46, 35, 26, 506, 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّن نَّهَارٍۭ بَلَٰغٌ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَٰسِقُونَ', 'faṣbir kamā ṣabara ʾūlū l-ʿazmi mina r-rusuli walā tastaʿjil lahum kaʾannahum yawma yarawna mā yūʿadūna lam yalbathū ʾillā sāʿatan min nahārin balāghun fahal yuhlaku ʾillā l-qawmu l-fāsiqūna', 'O halde, azim sahibi peygamberlerin sabrettiği gibi sabret. Onlar için acele etme. Onlar, va''dolundukları şeyi gördükleri gün, sanki dünyada bir saatten başka kalmamış gibi olurlar. (Bu,) bir tebliğdir. Yoldan çıkmış bir topluluktan başkası helak olur mu?'),
(47, 1, 26, 507, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَٰلَهُمْ', 'alladhīna kafarū wa ṣaddū ʿan sabīli llāhi aḍalla ʾaʿmālahum', 'İnkâr edenler ve Allah''ın yolundan alıkoyanlar var ya, Allah onların amellerini boşa çıkarmıştır.'),
(47, 2, 26, 507, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', 'wa-lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāt wa-ʾāmanū bimā nuzzila ʿalā Muḥammad wa-huwa l-ḥaqqu min rabbihim kaffara ʿanhum sayyiʾātihim wa-ʾaṣlaḥa bālahum', 'İman edip salih amel işleyenler, Muhammed''e indirilen (Kur''an''a) iman edenler ve onun Rablerinden gelen hak olduğunu bilenler var ya, Allah onların kötülüklerini örtmüş ve durumlarını düzeltmiştir.'),
(47, 3, 26, 507, 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ', 'dhālika bi-ʾanna alladhīna kafarū ʾittabaʿū al-bāṭila wa-ʾanna alladhīna ʾāmanū ʾittabaʿū al-ḥaqqa min rabbihim kadhālika yaḍribu allāhu lil-nāsi ʾamthālahum', 'Bu böyledir; çünkü küfredenler batıla uymuşlar, iman edenler de Rablerinden gelen hakka uymuşlardır. İşte Allah, insanların kendilerine (verdiği) örnekleri böyle açıklıyor.'),
(47, 4, 26, 507, 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَٰلَهُمْ', 'fa-idhā laqītumulladhīna kafarū fa-ḍarba r-riqābi ḥattā idhā athkhantumūhum fa-shuddū l-wathāqa fa-immā mannan baʿdu wa-immā fidāʾan ḥattā taḍaʿa l-ḥarbu awzārahā dhālika wa-law yashāʾu Llāhu la-ntasara minhum wa-lākin li-yabluwa baʿḍakum bi-baʿḍin wa-lladhīna qutilū fī sabīli Llāhi fa-lan yuḍilla aʿmālahum', 'Artık onlarla karşılaştığınızda, (önce) boyunlarını vurun. Nihayet onları iyice zayıflattığınızda (ağır yaraladığınızda) kalanları da sağlam bir şekilde bağlayın. Bundan sonra (esirleri) ya karşılıksız veya fidye karşılığı salıverirsiniz. Savaş, yüklerini bırakıncaya kadar (böyle devam eder). İşte durum budur. Eğer Allah dileseydi, onlardan (intikam alırdı) ama sizi birbirinizle denemek için (böyle yapmıştır). Allah yolunda öldürülenlerin amellerini ise asla boşa çıkarmayacaktır.'),
(47, 5, 26, 507, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 'sayahdīhim wa yuṣliḥu bālahum', 'Onları doğru yola iletecek ve onların durumlarını düzeltecektir.'),
(47, 6, 26, 507, 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', 'wa yudkhiluhumu l-jannata ʿarrafahā lahum', 'Ve onları, kendilerine tanıtmış olduğu cennete sokacaktır.'),
(47, 7, 26, 507, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', 'yā ayyuhā lladhīna āmanū in tanṣurū llaha yanṣurkum wa yuthabbit aqdāmakum', 'Ey iman edenler! Eğer siz Allah''a (dinin) yardım ederseniz, O da size yardım eder ve ayaklarınızı sabit tutar.'),
(47, 8, 26, 507, 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًا لَّهُمْ وَأَضَلَّ أَعْمَٰلَهُمْ', 'wa-lladhīna kafarū fataʿsan lahum wa-aḍalla aʿmālahum', 'İnkâr edenler ise, onlara yazıklar olsun! Ve (Allah) onların amellerini boşa çıkarmıştır.'),
(47, 9, 26, 507, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'dhālika bi-ʾannahum karihū mā ʾanzala ʾllāhu fa-ʾaḥbaṭa ʾaʿmālahum', 'Bu böyledir; çünkü onlar Allah''ın indirdiğini hoş görmediler. Bu yüzden Allah onların amellerini boşa çıkardı.'),
(47, 10, 26, 507, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ دَمَّرَ ٱللَّهُ عَلَيْهِمْ وَلِلْكَٰفِرِينَ أَمْثَٰلُهَا', 'ʾafalam yasīrū fī l-ʾarḍi fayanẓurū kayfa kāna ʿāqibatu l-ladhīna min qablihim dammara l-lāhu ʿalayhim wa lil-kāfirīna ʾamthāluhā', 'Yeryüzünde dolaşıp da kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Allah onların üzerine yıkım indirdi. Kafirler için de (buna benzer azaplar) vardır.'),
(47, 11, 26, 507, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', 'dhālika biʾanna ʾllāha mawlā ʾlladhīna ʾāmanū wa ʾanna ʾlkāfirīna lā mawlā lahum', 'Bu böyledir, çünkü Allah, iman edenlerin mevlasıdır (dostu, koruyucusu, yardımcısıdır); kafirlere gelince, onların hiçbir mevlası (dostu, koruyucusu, yardımcısı) yoktur.'),
(47, 12, 26, 508, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَٰمُ وَٱلنَّارُ مَثْوًى لَّهُمْ', 'ʾinna llāha yudkhilu llaḏīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti jannātin tajrī min taḥtihā l-ʾanhāru wa-llaḏīna kafarū yatamattaʿūna wa-yaʾkulūna kamā taʾkulu l-ʾanʿāmu wa-n-nāru maṯwan lahum', 'Şüphesiz Allah, iman edip salih amel işleyenleri, altlarından ırmaklar akan cennetlere koyacaktır. İnkâr edenler ise (dünya zevklerinden) yararlanırlar ve hayvanların yediği gibi yerler. Onların varacakları yer ateştir.'),
(47, 13, 26, 508, 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَٰهُمْ فَلَا نَاصِرَ لَهُمْ', 'wa ka''ayyin min qaryatin hiya ''ashaddu quwwatan min qaryatika allati ''akhrajatka ''ahlaknahum fala nasira lahum', 'Seni yurdundan çıkaran nice kasaba halkı, onlardan daha kuvvetli idi. Biz onları helak ettik. Onlara yardım edecek kimse de yoktur.'),
(47, 14, 26, 508, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', 'ʾafaman kāna ʿalā bayyinatin mir rabbihī kaman zuyyina lahu sūʾu ʿamalihī wā-ttabaʿū ʾahwāʾahum', 'Rabbinden (gelen) açık bir delil üzerinde bulunan kimse, kötü ameli kendisine süslenip-pazarlanmış ve kendi heveslerine uymuş kimse gibi midir?'),
(47, 15, 26, 508, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ فِيهَآ أَنْهَٰرٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ وَأَنْهَٰرٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَٰرٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّٰرِبِينَ وَأَنْهَٰرٌ مِّنْ عَسَلٍ مُّصَفًّى وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌ مِّن رَّبِّهِمْ كَمَنْ هُوَ خَٰلِدٌ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًا فَقَطَّعَ أَمْعَآءَهُمْ', 'mathalu l-jannati llatī wuʿida l-muttaqūna fīhā anhārun min māʾin ghayri āsini wa anhārun min labanin lam yataghayyar ṭaʿmuhu wa anhārun min khamrin ladhdhatin lish-shāribīna wa anhārun min ʿasalin muṣaffan wa lahum fīhā min kulli th-thamarāti wa maghfiratun min rabbihim kaman huwa khālidu n-nāri wa suqū māʾan ḥamīman fa qaṭṭaʿa ʾamʿāʾahum', 'Allah''a karşı gelmekten sakınanlara va''dedilen cennetin durumu şöyledir: Orada bozulmayan su ırmakları, tadı değişmeyen süt ırmakları, içenlere lezzet veren şarap ırmakları ve süzme bal ırmakları vardır. Orada onlar için her türlü meyveden (her çeşit ürün) ve Rab''lerinden bir bağışlanma da vardır. Bunlar, hiç ateşin içinde temelli kalacak ve karınlarını parçalayan kaynar su içirilecek kimselerin durumu gibi midir? (Elbette ki değildir.)'),
(47, 16, 26, 508, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', 'wa-minhum man yastamiʿu ilayka ḥattā ʾidhā kharajū min ʿindika qālū lilladhīna ʾūtū al-ʿilma mādhā qāla ʾānifan ʾulāʾika lladhīna ṭabaʿa ʾallāhu ʿalā qulūbihim wa-ttabaʿū ʾahwāʾahum', 'Onlardan seni dinleyenler de vardır. Nihayet yanından çıktıkları zaman, kendilerine ilim verilenlere: "Az önce ne dedi?" diye sorarlar. İşte bunlar, Allah’ın kalplerini mühürlediği ve kendi heveslerine uyan kimselerdir.'),
(47, 17, 26, 508, 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', 'wa-lladhīna ihtadaw zādahum hudan wa-ātāhum taqwāhum', 'Hidayete erenlere gelince, Allah onların hidayetlerini artırmış ve onlara takvalarını (kötülükten korunma bilincini) vermiştir.'),
(47, 18, 26, 508, 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً فَقَدْ جَآءَ أَشْرَاطُهَا فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', 'fa hal yanẓurūna illā s-sāʿata an taʾtiyahum baghtatan fa qad jāʾa ashraṭuhā fa ʾannā lahum ʾidhā jāʾathum dhikrāhum', 'Onlar, kendilerine ansızın gelivermesinden başka, kıyamet gününü mü bekliyorlar? Andolsun ki, kıyametin alâmetleri gelmiştir. Kendilerine (o azap) geldiği zaman ibret almaları onlara ne fayda verir?'),
(47, 19, 26, 508, 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', 'faʿlam ʾannahu lā ʾilāha ʾillā llāhu wāstaghfir liḏanbika walilmūʾminīna walmūʾmināti wallāhu yaʿlamu mutaḳallabakum wamathwākum', 'Bil ki, Allah''tan başka ilah yoktur. Hem kendi kusurun için hem de inanmış erkekler ve inanmış kadınlar için af dile. Allah sizin dönüp dolaşacağınız yerleri de, varacağınız son noktayı da bilir.'),
(47, 20, 26, 509, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌ فَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا ٱلْقِتَالُ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ فَأَوْلَىٰ لَهُمْ', 'wa yaqūlu alladhīna ʾāmanū lawlā nuzzilat sūratun fa-ʾidhā ʾunzzilat sūratun muḥkamatun wa dhukira fīhā al-qitālu raʾayta alladhīna fī qulūbihim maraḍun yanẓurūna ʾilayka naẓara al-maghshiyyi ʿalayhi mina al-mawti fa-ʾawlā lahum', 'İman edenler derler ki: "Keşke bir sure indirilmeliydi!" Fakat (savaşmayı emreden) açık ve net bir sure indirilince, kalplerinde hastalık olanları, ölüm baygınlığı geçiren kimse gibi sana baktıklarını görürsün. Artık onlara yazıklar olsun!'),
(47, 21, 26, 509, 'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًا لَّهُمْ', 'ṭāʿatun waqawlun maʿrūfun faʾiḏā ʿazama l-ʾamru falaw ṣadaqū l-lāha lakāna ḵayran lahum', 'İtaat ve güzel söz (vardır). İş ciddiye bindiğinde, eğer Allah''a karşı dürüst olsalardı, onlar için daha hayırlı olurdu.'),
(47, 22, 26, 509, 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', 'Fهل ʿasaytum in tawallaytum an tufsidū fī l-ʾarḍi wa tuqaṭṭiʿū ʾarḥāmakum', 'Eğer (yönetimden) yüz çevirirseniz, yeryüzünde bozgunculuk çıkarmanız ve akrabalık bağlarınızı kesmeniz umulur sizden.'),
(47, 23, 26, 509, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَٰرَهُمْ', 'ʾūlāʾika l-ladhīna laʿanahumu ʾllāhu fa-ʾaṣammahum wa-ʾaʿmā ʾabṣārahum', 'İşte onlardır Allah''ın lanetlediği, sonra da onları sağırlaştıran ve gözlerini kör eden kimseler.'),
(47, 24, 26, 509, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', 'ʾafalā yatadabbarūna l-qurʾāna ʾam ʿalā qulūbin ʾaqfāluha', 'Onlar Kur''an''ı düşünmüyorlar mı? Yoksa kalplerinin üzerinde kilitleri mi var?'),
(47, 25, 26, 509, 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ٱلشَّيْطَٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', 'ʾinna lladhīna rteddū ʿalā ʾadbārihim mim baʿdi mā tabayyana lahumu l-hudā a sh-shayṭānu sawwala lahum wa ʾamlā lahum', 'Kendilerine hidayet (doğru yol) belli olduktan sonra gerisin geri dönenler var ya, şeytan onların (bu işlerini) onlara süslemiş ve onları uzun emellere düşürmüştür.'),
(47, 26, 26, 509, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', 'dhālika bi-ʾannahum qālū li-lladhīna karihū mā nazzala ʾllāhu sanuṭīʿukum fī baʿḍi l-ʾamri wa-llāhu yaʿlamu ʾisrārahum', 'Onların bu halleri, Allah''ın indirdiğini (Kur''an''ı) hoş karşılamayanlara: "Biz size bazı işlerde itaat edeceğiz" demelerinden dolayıdır. Oysa Allah onların gizlediklerini de bilmektedir.'),
(47, 27, 26, 509, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ', 'fakayfa iḏā tawaffathumu l-malāʾikatu yaḍribūna wujūhahum wa-ʾadbārahum', 'Peki, canlarını almak üzere meleklere geldiklerinde, yüzlerine ve arkalarına vuracakları zaman halleri nasıl olacak?'),
(47, 28, 26, 509, 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'dhālika bi-ʾannahumu-ttabaʿū mā ʾaskhaṭa-llāha wa-karihū riḍwānahū fa-ʾaḥbaṭa ʾaʿmālahum', 'Bu böyledir, çünkü onlar Allah''ı gazaplandıran şeylere uydular ve O''nun rızasından hoşlanmadılar da O da amellerini boşa çıkardı.'),
(47, 29, 26, 509, 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَٰنَهُمْ', 'ʾam ḥasiba lladhīna fī qulūbihim maraḍun ʾanna lan yukhrija l-lāhu ʾaḍghānahum', 'Kalplerinde hastalık bulunanlar, Allah''ın kendilerinin gizli kinlerini asla ortaya çıkarmayacağını mı sandılar?'),
(47, 30, 26, 510, 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَٰهُمْ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ وَٱللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ', 'wa-law nashāʾu la-araynākahum fa-la-ʿaraftahum bi-sīmāhum wa-la-taʿrifannahum fī laḥni l-qawli wa-llāhu yaʿlamu aʿmālakum', 'Eğer dilemiş olsaydık, onları sana gösterirdik de elbette onları simalarından tanırdın. Andolsun ki sen onları, sözlerin (veya konuşma tarzının) inceliğinden de tanırsın. Allah bütün yaptıklarınızı bilir.'),
(47, 31, 26, 510, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', 'Ve le nebluvennekum hattâ na''leme-l-mucâhidîne minkum ve-ssâbirîn ve nebluve ahbârakum', 'Andolsun ki, içinizden mücahit olanları ve sabredenleri bilinceye kadar sizi imtihan edeceğiz; haberlerinizi de deneyeceğiz.'),
(47, 32, 26, 510, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَٰلَهُمْ', 'ʾinna lladhīna kafarū wa ṣaddū ʿan sabīli l-lāhi wa shāqqū r-rasūla min baʿdi mā tabayyana lahumu l-hudā lan yaḍurrū l-lāha shayʾan wa sayuḥbiṭu ʾaʿmālahum', 'Şüphesiz inkâr edenler, Allah''ın yolundan alıkoyanlar ve kendilerine doğru yol belli olduktan sonra Peygamber''e düşmanlık edenler, Allah''a hiçbir zarar veremezler. Allah onların amellerini boşa çıkaracaktır.'),
(47, 33, 26, 510, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَٰلَكُمْ', 'yā ayyuhā alladhīna āmānū aṭīʿū allāh wa aṭīʿū ar-rasūl wa lā tubṭilū aʿmālakum', 'Ey iman edenler! Allah''a itaat edin, Peygamber''e itaat edin ve amellerinizi boşa çıkarmayın.'),
(47, 34, 26, 510, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', 'ʾinna lladhīna kafarū wa ṣaddū ʿan sabīli llāhi thumma mātū wa hum kuffārun falan yaghfira llāhu lahum', 'Şüphesiz inkâr edenler ve Allah''ın yolundan alıkoyanlar, sonra da inkârcı olarak ölenler; işte Allah onları asla bağışlamayacaktır.'),
(47, 35, 26, 510, 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَٰلَكُمْ', 'falā tahinū watadʿū ilā s-salmi wa antumu l-aʿlawna wa llāhu maʿakum walani yatirakum aʿmālakum', 'O halde gevşemeyin ve üstünken barışa çağırmayın; Allah sizinle beraberdir ve O amellerinizi asla eksiltmeyecektir.'),
(47, 36, 26, 510, 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', 'innamā l-ḥayātu d-dunyā laʿibun wa-lahwun wa-in tuʾminū wa-tattaqū yuʾtikum ʾujūrakum wa-lā yasʾalukum ʾamwālakum', 'Dünya hayatı ancak bir oyun ve eğlencedir. Eğer iman eder ve takva sahibi olursanız, Allah size ecirlerinizi verir ve sizden mallarınızı istemez.'),
(47, 37, 26, 510, 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَٰنَكُمْ', 'in yas''alukumūhā feyuḥfikum tabkhalū wayukhriju aḍgānakum', 'Eğer onları isterse ve sizi zorlarsa, cimrilik edersiniz ve kinlerinizi ortaya çıkarırsınız.'),
(47, 38, 26, 510, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَٰلَكُم', 'hā''antum hā''ulā''i tudʿawna litunfiqū fī sabīli llāhi famin kum man yabkhalu wa man yabkhal fa''innamā yabkhalu ʿan nafsihi wa llāhu l-ġaniyyu wa antumu l-fuqarā''u wa in tatawallaw yastabdil qawman ġayrakum thumma lā yakūnū amthālakum', 'İşte sizler, Allah yolunda harcamaya davet olunanlarsınız. İçinizden cimrilik edenler vardır. Kim cimrilik ederse, ancak kendi nefsine cimrilik etmiş olur. Allah zengindir, siz fakirlersiniz. Eğer siz (O''ndan) yüz çevirirseniz, yerinize sizden başka bir kavim getirir ve onlar sizin gibi olmazlar.'),
(48, 1, 26, 511, 'إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا', 'ʾinnā fataḥnā laka fatḥan mubīnā', 'Şüphesiz biz sana apaçık bir fetih (fetihlerin en büyüğü olan Mekke''nin fethini) verdik.'),
(48, 2, 26, 511, 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًا مُّسْتَقِيمًا', 'li-yaghfira laka-llāhu mā taqaddama min-dhanbika wa-mā taʾakhkhara wa-yutimma niʿmatahū ʿalayka wa-yahdiyaka ṣirāṭan mustaqīman', 'Böylece Allah, senin geçmiş ve gelecek kusurlarını bağışlar, sana olan nimetini tamamlar ve seni dosdoğru yola iletir.'),
(48, 3, 26, 511, 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', 'wa yanṣuraka allāhu naṣran ʿazīzan', 'Ve Allah, sana (düşmanlarına karşı) çok güçlü bir zaferle yardım edecektir.'),
(48, 4, 26, 511, 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَٰنًا مَّعَ إِيمَٰنِهِمْ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'huwa lladhī ʾanzala s-sakīnata fī qulūbi l-muʾminīn li-yazdādū ʾīmānan maʿa ʾīmānihim wa-li-llāhi junūdu s-samāwāti wa-l-ʾarḍi wa-kāna llāhu ʿalīman ḥakīman', 'O, iman edenlerin kalplerine o eşsiz huzuru indiren, böylece imanlarına imanlarını artırsınlar diye (indirmiş) olan odur. Göklerin ve yerin orduları Allah''ındır. Allah, her şeyi bilen, hikmet sahibi olandır.'),
(48, 5, 26, 511, 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًا', 'li-yudkhila l-muʾminīna wa-l-muʾmināti jannātin tajrī min taḥtihā l-anhāru khālidīna fīhā wa-yukaffira ʿanhum sayyiʾātihim wa-kāna dhālika ʿinda llāhi fawzan ʿaẓīman', 'Böylece Allah, iman eden erkekleri ve iman eden kadınları, altlarından ırmaklar akan, içinde ebedî kalacakları cennetlere soksun ve onların günahlarını örtsün. İşte bu, Allah katında büyük bir kurtuluştur.'),
(48, 6, 26, 511, 'وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', 'wa yu''aḏḏiba l-munāfiqīna wa-l-munāfiqāti wa-l-mušrikīna wa-l-mušrikāti ẓ-ẓānnīna bi-llāhi ẓanna s-sawʾi ʿalayhim dāʾiratu s-sawʾi wa ġaḍiba llāhu ʿalayhim wa laʿanahum wa aʿadda lahum ǧahannama wa sāʾat maṣīran', 'Ve yine Allah, münafık erkeklere ve münafık kadınlara, müşrik erkeklere ve müşrik kadınlara, Allah hakkında zann-ı sû (kötü zanda bulunanlar) azap etsin! Kötülük onların başlarına insin! Allah onlara gazap etmiş, onları lanetlemiş ve cehennemi hazırlamıştır. Ne kötü bir dönüş yeridir!'),
(48, 7, 26, 511, 'وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'wa lil-lāhi junūdu s-samāwāti wal-arḍi wa kāna l-lāhu ʿazīzan ḥakīman', 'Göklerin ve yerin orduları Allah''ındır. Allah, Azîz’dir (mutlak galiptir), Hakîm’dir (hikmet sahibidir).'),
(48, 8, 26, 511, 'إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', 'innā arsalnāka shāhidan wa mubashshiran wa nadhīran', 'Şüphesiz biz seni şahit, müjdeleyici ve uyarıcı olarak gönderdik.'),
(48, 9, 26, 511, 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', 'li-tuʾminū bi-llāhi wa-rasūlihī wa-tuʿazzirūhū wa-tuwaqqirūhū wa-tusabbiḥūhū bukrataw-wa-ʾaṣīlā', 'Böylece Allah''a ve Resûlü''ne iman edesiniz, O''na (dininize) yardımda bulunasınız, O''nu tâzim edesiniz ve O''nu sabah akşam tesbih edesiniz diye (böyle emrettik).'),
(48, 10, 26, 512, 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ وَمَنْ أَوْفَىٰ بِمَا عَٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا', 'ʾinna lladhīna yubāyiʿūnaka ʾinnamā yubāyiʿūna llāha yadū llāhi fawqa ʾaydīhim faman nakatha fa-ʾinnamā yankuṯu ʿalā nafsihi waman ʾawfā bimā ʿāhada ʿalayhi llāha fa-sayuʾtīhi ʾajran ʿaẓīman', 'Şüphesiz sana biat edenler, ancak Allah''a biat etmiş olurlar. Allah''ın eli onların ellerinin üzerindedir. Kim ahdini bozarsa, kendi aleyhine bozmuş olur. Kim de Allah ile olan ahdine vefa gösterirse, Allah ona büyük bir ecir verecektir.'),
(48, 11, 26, 512, 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', 'sayuqūlu laka l-mukhallafūna mina l-aʿrābi shaghalatnā amwālunā wa-ahlūnā fastaghfir lanā yaqūlūna bi-alsinatihim mā laysa fī qulūbihim qul faman yamliku lakum mina llāhi shayʾan in arāda bikum ḍarran aw arāda bikum nafʿan bal kāna llāhu bimā taʿmalūna khabīran', 'Savaştan (seferden) geri bırakılan bedeviler sana diyecekler ki: "Mallarımız ve ailelerimiz bizi alıkoydu. Allah''tan bizim için mağfiret dile. Onlar, kalplerinde olmayanı dilleriyle söylerler. De ki: "Eğer Allah size bir zarar veya bir fayda dileyecek olursa, sizin için O''na karşı kimin bir şeyi olabilir? Hayır, Allah yaptıklarınızdan haberdardır."'),
(48, 12, 26, 512, 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًا', 'bal ẓanantum an lan yanqaliba r-rasūlu wa-l-muʾminūna ʾilā ʾahlihim ʾabadan wa zuyyina dhālika fī qulūbikum wa ẓanantum ẓanna s-sawʾi wa kuntum qawman būran', 'Hayır! Siz, Peygamberin ve müminlerin ailelerine bir daha dönmeyeceklerini sanmıştınız. Bu, kalplerinize güzel gösterildi ve siz kötü bir zanda bulundunuz. Siz, helaki hak etmiş bir topluluk idiniz.'),
(48, 13, 26, 512, 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَعِيرًا', 'wa-man lam yuʾmin bi-llāhi wa-rasūlihi fa-ʾinnā ʾaʿtadnā lil-kāfirīna saʿīrā', 'Kim Allah''a ve Resûlü''ne inanmazsa, şüphesiz biz kâfirler için çılgın bir ateş hazırlamışızdır.'),
(48, 14, 26, 512, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'wa lillāhi mulku s-samāwāti wa l-arḍi yaghfiru liman yashāʾu wa yuʿadhdhibu man yashāʾu wa kāna -llāhu ghafūran rahīmā', 'Göklerin ve yerin mülkiyeti/hükümranlığı Allah''a aittir. Dilediğini bağışlar, dilediğini azaplandırır. Allah, Gafûr''dur (çok bağışlayıcıdır), Rahîm''dir (çok merhametlidir).'),
(48, 15, 26, 512, 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَٰمَ ٱللَّهِ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًا', 'sayuqūlu l-mukhallafūna iḏā nṭalaqtum ilā magāni-ma li-taʾkhuḏūhā ḏarūnā nattabiʿkum yurīdūna an yubaddilū kalāma llāh qul lan tattabiʿūnā kaḏālikum qāla llāhu min qablu fasayaqūlūna bal taḥsudūnanā bal kānū lā yafqahūna illā qalīlan', 'Siz ganimetleri almak üzere (hayber''e) doğru yola çıktığınızda, geride kalanlar şöyle diyeceklerdir: "Bırakın bizi de size tâbi olalım." Onlar, Allah''ın (bu konudaki) hükmünü değiştirmek istiyorlar. De ki: "Siz bize asla tâbi olamazsınız. Allah, daha önce böyle buyurmuştur." Onlar şöyle diyeceklerdir: "Hayır, siz bizi kıskanıyorsunuz." Halbuki onlar, (bu hükmün hikmetini) pek az anlarlar.'),
(48, 16, 26, 513, 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍ شَدِيدٍ تُقَٰتِلُونَهُمْ أَوْ يُسْلِمُونَ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًا وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا', 'qul lilmukhallafīna minal-aʿrābi satudʿawna ilā qawmin ʾūlī baʾsin shadīdin tuqātilūnahum ʾaw yuslimūna fa-ʾin tuṭīʿū yuʾtikumu ʾallāhu ʾajran ḥasanan wa-ʾin tatawallaw kamā tawallaytum min qablu yuʿaḏḏibkum ʿaḏāban ʾalīman', 'Bedevilerden (cihad için) geri bırakılmış olanlara de ki: "Siz yakında çok kuvvetli bir kavme (savaşa) çağrılacaksınız. Onlarla savaşacaksınız ya da (onlar) Müslüman olacaklardır. Eğer itaat ederseniz, Allah size güzel bir ecir verir. Eğer daha önce yüz çevirdiğiniz gibi yine yüz çevirirseniz, sizi acı bir azap ile cezalandırır."'),
(48, 17, 26, 513, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًا', 'laysa ʿalā l-ʾaʿmā ḥaracun walā ʿalā l-ʾaʿraji ḥaracun walā ʿalā l-marīḍi ḥaracun waman yuṭiʿi l-lāha warasūlahū yudkhilhu jannātin tajrī min taḥtihā l-ʾanhāru waman yatawallā yuʿadždhibhu ʿad͟hāban ʾalīman', 'Kör üzerine bir zorluk yoktur, topal üzerine de bir zorluk yoktur, hasta üzerine de bir zorluk yoktur. Ve kim Allah''a ve Resûlü''ne itaat ederse, O (Allah) onu, altından ırmaklar akan cennetlere sokar. Ve kim yüz çevirirse, O (Allah) onu acı bir azap ile azaplandırır.'),
(48, 18, 26, 513, 'لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحًا قَرِيبًا', 'laqad raḍiya ʾallāhu ʿani l-muʾminīna ʾiḏ yubāyiʿūnakat taḥta š-šajarati fʿalimama fī qulūbihim faʾanzala s-sakīnata ʿalayhim waʾaṯābahum fatḥan qarīban', 'Andarolsun ki Allah, o ağacın altında sana bey''at (biat) ederlerken mü''minlerden razı olmuştur. Onların kalplerinde olanı bildi de üzerlerine o (manevi) huzuru indirdi ve onları (bu sebeple) yakın bir fetihle mükafatlandırdı.'),
(48, 19, 26, 513, 'وَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 've magānim-a keśīratan yeʾhuẕūnehā ve kāne-llāhu ʿazīzan ḥakīmā', 'Onları alacakları birçok ganimetler de (vardır). Allah Azîz''dir, Hakîm''dir.'),
(48, 20, 26, 513, 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًا مُّسْتَقِيمًا', 'Waʿadakumullāhu maghāni-ma kathīratan taʾkhudhūnahā Faʿajjala lakum hādhihī Wa kaffa aydiya n-nāsi ʿankum Wa litakūna āyatan lil-muʾminīn Wa yahd-iyakum ṣirāṭan mustaqīmā', 'Allah, size bol ganimetler vaad etmiştir. Onları alacaksınız. Bu ganimeti size hemen verdi ve insanların ellerini sizden çekti ki bu, müminler için bir ayet (mucize) olsun ve sizi doğru yola iletsin.'),
(48, 21, 26, 513, 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', 'wa ʾuḫrā lam taqdirū ʿalayhā qad ʾaḥāṭa llāhu bihā wa kāna llāhu ʿalā kulli šayʾin qadīrā', 'Hem de sizin henüz gücünüzün yetmediği, ama Allah''ın kuşattığı diğer ganimetler de vardır. Allah her şeye hakkıyla gücü yetendir.'),
(48, 22, 26, 513, 'وَلَوْ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', 'wa-law qātalakumul-ladhīna kafarū lawallul-adbāra thumma lā yajidūna waliyyan walā naṣīrā', 'Onları inkâr edenler sizinle savaşmış olsalardı, mutlaka arkalarını dönüp kaçarlardı. Sonra da ne bir dost ne de bir yardımcı bulamazlardı.'),
(48, 23, 26, 513, 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', 'sunnata Allāhi llatī qad ḵalat min qablu wa-lan tajida li-sunnati Allāhi tabdīlan', 'Bunlar, Allah''ın (insanlar hakkında) geçmiş olan kanunudur (sünnetidir). Allah''ın kanununda asla bir değişiklik bulamazsın.'),
(48, 24, 26, 514, 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 'wa-huwa alladhī kaffa aydiyahum ʿankum wa-aydiyaakum ʿanhum bibaṭni makkata min baʿdi an aẓfarakum ʿalayhim wa-kāna allāhu bimā taʿmalūna baṣīran', 'Yine O, Mekke''nin içinde iken, onlara karşı size zafer verdikten sonra, onların ellerini sizden, sizin ellerinizi de onlardan çekendir. Allah, yaptıklarınızı hakkıyla görmektedir.'),
(48, 25, 26, 514, 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَٰتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', 'humu lladhīna kafarū wa ṣaddūkum ʿani l-masjidi l-ḥarāmi wa l-hadyā maʿkūfan an yablugha maḥillahuۥ wa lawlā rijālun muʾminūna wa nisāʾun muʾminātun lam taʿlamūhum an taṭāʾūhum fa-tuṣībakum minhum maʿarratun bi-ghayri ʿilmin li-yudkhila l-lāhu fī raḥmatihī man yashāʾu law tazayyalū la-ʿadhdhabnā lladhīna kafarū minhum ʿadhāban alīman', 'Onlar, inkar edenler ve sizi Mescid-i Haram''dan (alıkoyanlar) ve (Kurbanlarınızın) yerlerine ulaşmaktan alıkoyanlardır. Eğer (Mekke''de) henüz bilmediğiniz inanmış erkekler ve inanmış kadınlar olmasaydı, onlara dokunmanız sonucu bilmeden size bir sıkıntı (veya ceza) isabet etmesi olmasaydı (onları hemen cezalandırırdık). Allah, dilediğini rahmetine sokar. Eğer onlar (Müslümanlar ve kâfirler) ayrılmış olsalardı, onlardan inkâr edenleri elbette elem dolu bir azapla cezalandırırdık.'),
(48, 26, 26, 514, 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', 'idh jaʿala alladhīna kafarū fī qulūbihimu l-ḥamiyyata ḥamiyyata l-jāhiliyyati fa-anzala llāhu sakīnatahū ʿalā rasūlihī wa-ʿalā l-muʾminīna wa-alzama hum kalimata t-taqwā wa-kānū ʾaḥaqqa bihā wa-ʾahalahā wa-kāna llāhu bikulli shayin ʿalīman', 'Hani o kâfirler, kalplerine taassubu (cahiliye taassubunu) yerleştirmişlerdi. Allah da elçisine ve müminlere huzur ve sükûnetini indirdi, onları takva (Allah korkusu ve saygısı) kelimesine sarılmaya mecbur etti. Zaten onlar buna herkesten daha lâyık ve ehil idiler. Allah her şeyi hakkıyla bilendir.'),
(48, 27, 26, 514, 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا', 'leḳad ṣadeḳa Allâhu rasûlehu-rruʾyâ bilḥaḳḳi letedḫulunne-lmescide-lḥarâme in şâe-llâhu âminîne muḥalliḳîne ruʾûsekum vemuḳaṣṣirîne lâ teḫâfûn fe`alime mâ lem ta`lemû fece`ale min dûni żâlike fetḥan ḳarîbâ', 'Andolsun ki Allah, Resûlü''nün rüyasını hak olarak tasdik etmiştir. Allah dilerse, güven içinde, başlarınızı tıraş etmiş ve kısaltmış olarak, korkmaksızın Mescid-i Haram''a muhakkak gireceksiniz. Sizin bilmediğiniz şeyleri bildi de, bundan önce yakın bir fetih nasip etti.'),
(48, 28, 26, 514, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'huwa alladhī arsala rasūlahū bil-hudā wa dīni l-ḥaqqi li yuẓhirahu ʿalā d-dīni kullihī wa kafā bil-lāhi shahīdan', 'O, Resûlü''nü hidayetle ve hak din ile gönderen O''dur ki, O''nu bütün dinlere üstün kılacaktır. Şahit olarak Allah yeter.'),
(48, 29, 26, 515, 'مُّحَمَّدٌ رَّسُولُ ٱللَّهِ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ تَرَىٰهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًۢا', 'Muḥammadun rasūlu Allāh Wa-lladhīna maʿahu ʾashiddāʾu ʿalā l-kuffāri ruḥamāʾu baynahum Tarāhum rukkāʿan sujjadan yabtaghūna faḍlan mina Allāhi wa-riḍwānan Sīmāhum fī wujūhihim min ʾathari s-sujūd Dhālika mathaluhum fī t-Tawrāti wa-mathaluhum fī l-ʾInjīl Ka-zarʿin ʾakhraja shaṭʾahu fa-ʾāzarahu fa-staghlaẓa fa-stawā ʿalā sūqihi yuʿjibu z-zurrāʿa Li-yaghīẓa bihimu l-kuffār Waʿada Allāhu lladhīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti minhum maghfiratan wa-ʾajran ʿaẓīman', 'Muhammed, Allah’ın elçisidir. Onunla birlikte olanlar da kâfirlere karşı çetin, kendi aralarında merhametlidir. Onları, Allah’tan bir lütuf ve rıza isteyerek eğilmiş ve secde ederken görürsün. Onların alametleri yüzlerindedir. Secde eserinden dolayıdır. İşte bu, Tevrat’ta onların misalidir. İncil’de ise onların misali, filizini çıkarmış, onu güçlendirmiş, derken kalınlaşarak kendi kamına dayanmış, ziraatçıların hoşuna giden bir ekin gibidir. Allah, onlarla kâfirleri öfkelendirmek için böyle yapmıştır. Allah, inanıp iyi işler yapanlara onlardan bir bağışlanma ve büyük bir ecir vaad etmiştir.'),
(49, 1, 26, 515, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'yā ayyuhā alladhīna āmanū lā tuqaddimū bayna yadayi llāhi wa rasūlihi wa-ttaqū llāha ʾinna llāha samīʿun ʿalīmun', 'Ey iman edenler! Allah''ın ve Resûlü''nün önüne geçmeyin. Allah''tan korkun. Şüphesiz Allah, işiten ve bilendir.'),
(49, 2, 26, 515, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', 'yā ayyuhā alladhīna āmanū lā tarfaʿū aṣwātukum fawqa ṣawti n-nabiyyi wa lā tajharū lahū bil-qawli kajahri baʿḍikum libaʿḍin an taḥbaṭa aʿmālukum wa antum lā tashʿurūna', 'Ey iman edenler! Seslerinizi peygamberin sesinin üstüne yükseltmeyin ve birbirinize yüksek sesle konuştuğunuz gibi ona (karşı öyle) yüksek sesle konuşmayın; yoksa siz farkında olmadan amelleriniz boşa gider.'),
(49, 3, 26, 515, 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', 'ʾinna lladhīna yaghuḍḍūna ʾaṣwātahum ʿinda rasūli llāhi ʾulāʾika lladhīna ʾimtaḥana llāhu qulūbahum li-t-taqwā lahum maghfiratun wa-ʾajrun ʿaẓīmun', 'Şüphesiz Allah''ın Resûlü nezdinde seslerini kıranlar, işte onlar, Allah''ın kalplerini takva için imtihan ettiği kimselerdir. Onlar için bir mağfiret ve büyük bir ecir vardır.'),
(49, 4, 26, 515, 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'ʾinna lladhīna yunādūna-ka min warāʾi l-ḥujurāti ʾaktharuhum lā yaʿqilūn', 'Şüphesiz ki seni odaların arkasından bağıranlar, onların çoğu aklı ermeyenlerdir.'),
(49, 5, 26, 516, 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'wa law annahum ṣabarū ḥattā taḫruja ilayhim lakāna khayran lahum wallāhu ghafūrun raḥīm', 'Eğer onlar, sen kendilerine çıkıncaya kadar sabretmiş olsalardı, elbette kendileri için daha hayırlı olurdu. Allah Gafûr''dur, Rahîm''dir.'),
(49, 6, 26, 516, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ', 'yā ayyuhā alladhīna āmanū in jāʾakum fāsiqūm binabaʾin fatabayyanū an tuṣībū qawman bijahālatin fatuṣbiḥū ʿalā mā faʿaltum nādimīn', 'Ey iman edenler! Fasık (kâfir veya fâsık) bir kimse size bir haber getirirse, onu iyice araştırın (yoksa) bilmeden bir kavme kötülük edip de sonra yaptığınızdan pişmanlık duyanlardan olursunuz.'),
(49, 7, 26, 516, 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ لَوْ يُطِيعُكُمْ فِى كَثِيرٍ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ أُو۟لَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', 'wa-ʿlamū ʾanna fīkum rasūla ʾllāhi law yuṭīʿukum fī kathīrin mina l-ʾamri la-ʿanittum wa-lākinna ʾllāha ḥabbaba ʾilaykumu l-ʾīmāna wa-zayyanahū fī qulūbikum wa-karraha ʾilaykumu l-kufra wa-l-fusūqa wa-l-ʿiṣyāna ʾulāʾika humu r-rāshidūna', 'Ve şunu bilin ki, içinizde Allah''ın Resûlü vardır. Eğer o, birçok işlerde size uysaydı, herhalde sıkıntıya düşerdiniz. Fakat Allah size iman sevgisi verdi ve onu kalplerinize güzel gösterdi; küfrü, fasıklığı ve isyanı da size çirkin gösterdi. İşte bunlar doğru yolu bulanlardır.'),
(49, 8, 26, 516, 'فَضْلًا مِّنَ ٱللَّهِ وَنِعْمَةً وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'faḍlan minallāhi wa niʿmah wallāhu ʿalīmun ḥakīm', 'Bunlar Allah''tan bir lütuf ve nimet idi. Allah her şeyi bilen, hikmet sahibidir.'),
(49, 9, 26, 516, 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'wa ʾin ṭāʾifatāni mina l-muʾminīna ʾiqtatalū fa-ʾaṣliḥū baynahumā fa-ʾin bagat ʾiḥdāhumā ʿalā l-ʾuḵrā fa-qātilū llatī tabgī ḥattā tafīʾa ʾilā ʾamri llāhi fa-ʾin fāʾat fa-ʾaṣliḥū baynahumā bil-ʿadli wa-ʾaqsiṭū ʾinna llāha yuḥibbu l-muqsiṭīna', 'Müminlerden iki topluluk birbirleriyle savaşırlarsa, aralarını bulun. Eğer ikisinden biri diğerine karşı aşırı davranırsa, Allah''ın buyruğuna dönünceye kadar, aşırı davranan tarafla savaşın. Eğer Allah''ın buyruğuna dönerse, ikisi arasında adaletle barışı sağlayın ve adil davranın. Şüphesiz Allah, adil davrananları sever.'),
(49, 10, 26, 516, 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'innamā l-muʾminūna ʾikhwah faʾaṣliḥū bayna ʾakhawaykum wa-ttaqū l-lāh laʿallakum turḥamūn', 'Mü''minler ancak kardeştirler. Öyleyse kardeşlerinizin arasını bulun ve Allah''tan korkup sakının ki O''nun rahmetini umabilesiniz.'),
(49, 11, 26, 516, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَٰنِ وَمَن لَّمْ يَتُبْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'yā ayyuhā alladhīna āmānū lā yaskhar qawmun min qawmin ʿasā an yakūnū khayran minhum wa lā nisāʾun min nisāʾin ʿasā an yakunna khayran minhunna wa lā talmizū anfusakum wa lā tanābazū bil-ʾalqābi biʾsa l-ismu l-fusūqu baʿda l-ʾīmāni wa man lam yatub fa-ʾulāʾika humu ẓ-ẓālimūna', 'Ey iman edenler! Bir topluluk diğer bir topluluğu alaya almasın; belki onlar, kendilerinden daha hayırlı olabilirler. Kadınlar da kadınları alaya almasınlar; belki onlar, kendilerinden daha hayırlı olabilirler. Kendi kendinizi ayıplamayın ve birbirinize kötü lakaplarla takılmayın. İmandan sonra fısk (yoldan çıkmak) ne kötü bir isimdir! Kim tevbe etmezse, işte onlar zalimlerdir.'),
(49, 12, 26, 517, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ تَوَّابٌ رَّحِيمٌ', 'yā ayyuhā lladhīna āmānū ijtanibū kathīran mina ẓ-ẓanni inna baʿḍa ẓ-ẓanni ithmun wa lā tajasasū wa lā yaghtab baʿḍukum baʿḍan ayuḥibbu aḥadukum an yaʾkula laḥma akhīhi mayyitan fakarihtumūhu wa ttaqū llāha inna llāha tawwābun raḥīmun', 'Ey iman edenler! Zannın çoğundan kaçının. Çünkü zannın bir kısmı günahtır. Tecessüs yapmayın (birbirinizin kusurlarını araştırmayın). Biriniz, ölü kardeşinin etini yemeyi sever mi? İşte bundan tiksindiniz. Allah''a karşı gelmekten sakının. Şüphesiz Allah, tevbeleri kabul edendir, çok merhamet edendir.'),
(49, 13, 26, 517, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ', 'yā ayyuhā n-nāsu innā khalaqnākum min dhakarin wa unthā wa jaʿalnākum shuʿūban wa qabāʾila litaʿārafū inna akramakum ʿinda llāhi atqākum inna llāha ʿalīmun khabīrun', 'Ey insanlar! Şüphesiz biz sizi bir erkek ve bir dişiden yarattık. Ve sizi ve''târif olmanız için (çeşitli) kavimler ve kabileler kıldık. Şüphesiz Allah katında sizin en kerim (mükerrem) olanınız, takvâca en ziyade olanınızdır. Şüphesiz Allah, bilendir, haberdâr olandır.'),
(49, 14, 26, 517, 'قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا قُل لَّمْ تُؤْمِنُوا۟ وَلَٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَٰنُ فِى قُلُوبِكُمْ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَٰلِكُمْ شَيْـًٔا إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'qālati l-aʿrābu ʾāmannā qul lam tuʾminū walākin qūlū ʾaslamnā walammā yadkhuli l-ʾimānu fī qulūbikum waʾin tuṭīʿū ʾllāha warasūlahū lā yalutkum min ʾaʿmālikum shayʾan ʾinna ʾllāha ġafūrun raḥīmun', 'Bedeviler "İman ettik" dediler. De ki: "Siz iman etmediniz, ancak ''teslim olduk'' deyin. Henüz iman kalplerinize girmedi. Eğer Allah''a ve Resûlü''ne itaat ederseniz, O sizin amellerinizden hiçbir şeyi eksiltmez. Şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir."'),
(49, 15, 26, 517, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 'innamā l-muʾminūna l-ladhīna ʾāmanū bi-llāhi wa-rasūlihi thumma lam yartābū wa-jāhadū bi-ʾamwālihim wa-ʾanfusihim fī sabīli llāhi ʾulāʾika humu ṣ-ṣādiqūna', 'Mü''minler ancak Allah''a ve Resûlü''ne inanmış, sonra hiçbir şüpheye düşmemiş ve mallarıyla, canlarıyla Allah yolunda cihad etmiş olanlardır. İşte onlar, doğru söyleyenlerin ta kendileridir.'),
(49, 16, 26, 517, 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'qul atuʿallimūna llāha bidīnikum wa llāhu yaʿlamu mā fī s-samāwāti wa mā fī l-arḍi wa llāhu bikulli shayin ʿalīmun', 'De ki: "Din(iniz) ile bize Allah''ı mı öğretiyorsunuz? Oysa Allah, göklerde olanı da yerde olanı da bilir. Allah, her şeyi hakkıyla bilendir."'),
(49, 17, 26, 517, 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَٰمَكُم بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَٰنِ إِن كُنتُمْ صَٰدِقِينَ', 'yamunnūna ʿalayka an aslamū qul lā tamunnū ʿalayya islāmakum balillāhu yamunnu ʿalaykum an hadākum lil-īmāni in kuntum ṣādiqīn', 'Onlar, Müslüman olmalarıyla sana minnet ediyorlar. De ki: "Müslümanlığınızla bana minnet etmeyin; hayır, sizi imana muvaffak etmekle Allah size minnet etmektedir, eğer siz doğru sözlüler iseniz."'),
(49, 18, 26, 517, 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', 'ʾinna llāha yaʿlamu ġayba s-samāwāti wa-l-ʾarḍi wa-llāhu baṣīrun bimā taʿmalūna', 'Şüphesiz Allah, göklerin ve yerin gaybını bilir. Allah, yaptıklarınızı hakkıyla görmektedir.'),
(50, 1, 26, 518, 'قٓ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', 'Kāf. Ve''l-kur''āni''l-mecīd', 'Kâf. Yemin olsun o şerefli Kur''an''a.'),
(50, 2, 26, 518, 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ فَقَالَ ٱلْكَٰفِرُونَ هَٰذَا شَىْءٌ عَجِيبٌ', 'bal ʿajibū ʾen jāʾehum munḏirun minhum feqāla lkāfirūne hāḏā šayʾun ʿajībun', 'Onlar, kendilerinden bir uyarıcının gelmesine şaştılar da, kâfirler şöyle dediler: "Bu, acayip bir şeydir."'),
(50, 3, 26, 518, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا ذَٰلِكَ رَجْعٌۢ بَعِيدٌ', 'ʾaʾiḏā mitnā wa-kunnā turāban ḏālika rajʿun baʿīd', 'Onlar: "Biz kemik olup unufak olduğumuzda mı, biz mi yeni bir yaratılışla tekrar diriltileceğiz?" dediler.'),
(50, 4, 26, 518, 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ وَعِندَنَا كِتَٰبٌ حَفِيظٌۢ', 'qad ʿalimnā mā tanquṣu l-arḍu minhum wa ʿindanā kitābun ḥafīẓun', 'Yeri onların noksanlaştırdığını (ne alıp götürdüğünü) bilmişizdir. Yanımızda ise her şeyi saklayan bir kitap vardır.'),
(50, 5, 26, 518, 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍ مَّرِيجٍ', 'bal kadhdhabū bil-ḥaqqi lammā jāʾahum fahum fī amrin marīj', 'Hayır, onlara hak geldiğinde onu yalanladılar. Bu yüzden onlar şaşkınlık içinde bir haldedirler.'),
(50, 6, 26, 518, 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٍ', 'ʾAfelem yenẓurū ʾilā s-samāʾi fawqahum kayfa banaynāhā wa zayyannāhā wa mā lahā min furūjin', 'Onlar, tepelerindeki göğe bakmadılar mı? Onu nasıl bina ettik ve onu nasıl süsledik ve onda hiçbir çatlak ve yarık bulunmamaktadır?'),
(50, 7, 26, 518, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'wa-l-arḍa madadnāhā wa-alqaynā fīhā rawāsīa wa-anbatnā fīhā min kulli zawjin bahījin', 'Yeri de (sizin için) bir döşek yaptık ve orada sarsılmaz dağlar yarattık ve orada her güzel (bitki)den çiftler bitirdik.'),
(50, 8, 26, 518, 'تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُّنِيبٍ', 'tabṣiratan wa dhikrá li-kulli ʿabdin munīb', 'Bunlar, basiret ve öğüt olmak üzere, her gönül dönen kul içindir.'),
(50, 9, 26, 518, 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءً مُّبَٰرَكًا فَأَنۢبَتْنَا بِهِۦ جَنَّٰتٍ وَحَبَّ ٱلْحَصِيدِ', 'wa-nazalna mina s-samāʾi māʾan mubārakā fa-ʾanbatnā bihi ǧannātin wa-ḥabba l-ḥaṣīd', 'Gökten bereketli bir su indirdik, onunla bahçeler ve biçilecek ekinler bitirdik.'),
(50, 10, 26, 518, 'وَٱلنَّخْلَ بَاسِقَٰتٍ لَّهَا طَلْعٌ نَّضِيدٌ', 'wa-n-nakhla bāsiqātin lahā ṭalʿun naḍīd', 'Ve uzanmış hurma ağaçları; onların başaklarında küme küme tomurcuklar vardır.'),
(50, 11, 26, 518, 'رِّزْقًا لِّلْعِبَادِ وَأَحْيَيْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ ٱلْخُرُوجُ', 'rizqan lil-ʿibād waʾaḥyaynā bihi baldatan maytatan kadhālika l-khurūj', 'Kullar için bir rızık olarak ve ölü bir beldeyi onunla dirilttik. İşte çıkış da böyledir.'),
(50, 12, 26, 518, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَٰبُ ٱلرَّسِّ وَثَمُودُ', 'kaḏḏabat qablahum qawmu nūḥin waʾaṣḥābu r-rassi waṯamūd', 'Onlardan önce Nuh''un kavmi, Ashab-ı Ress ve Semûd da yalanlamıştı.'),
(50, 13, 26, 518, 'وَعَادٌ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍ', 'wa ʿāduw wa firʿawnu wa ʾikhwānu lūṭin', 'Ve Âd''ı, Firavun''u ve Lût''un kardeşlerini de (yok ettik).'),
(50, 14, 26, 518, 'وَأَصْحَٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍ كُلٌّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', 'wa-aṣḥābu l-ʾaykati wa-qawmu tubbaʿin kullun kaḏḏaba r-rusula fa-ḥaqqa waʿīdī', 'Eyke halkı ve Tubba'' kavmi de! Hepsi peygamberleri yalanladılar da, tehdidim (azabım) gerçekleşti.'),
(50, 15, 26, 518, 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ بَلْ هُمْ فِى لَبْسٍ مِّنْ خَلْقٍ جَدِيدٍ', 'a faʿeyīnā bil-khalqi l-awwali bal hum fī labsٍ min khalqin jadīdin', 'Oysa biz, ilk yaratma ile yorulmadık. Hayır, onlar yeni bir yaratma hususunda bir şüphe içindedirler.'),
(50, 16, 26, 519, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 'Ve lekad halaknâ el-insâne ve na’lemu mâ tuvesvisu bihî nefsuhu ve nahnu akrabu ileyhi min habli el-verîdi', 'Andolsun ki insanı Biz yarattık ve nefsinin ona ne fısıldadığını biliriz. Biz ona şahdamarından daha yakınız.'),
(50, 17, 26, 519, 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌ', 'idh yatalqqā al-mutalaqqiyāni ʿani al-yamīni wa ʿani al-shimāli qāʿīdun', 'İki alıcı (melek) sağından ve solundan oturmuş (onları) alırken...'),
(50, 18, 26, 519, 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ', 'mā yalfitu min qawlin illā ladayhi raqībun ʿatīd', 'Ağzından bir söz çıkmaz ki, yanında onu gözetleyen ve kaydeden bir melek olmasın.'),
(50, 19, 26, 519, 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', 'wa jāʾat sakratu l-mawti bi-l-ḥaqqi dhālika mā kunta minhu taḥīdu', 'Ve ölüm sarhoşluğu, hak olarak geldi. İşte bu, kendisinden kaçmakta olduğun şeydir.'),
(50, 20, 26, 519, 'وَنُفِخَ فِى ٱلصُّورِ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', 'wa nufikha fī ṣ-ṣūri dhālika yawmu l-waʿīdi', 'Sur''a üflenir. İşte bu, tehdit (ve uyarı) günüdür.'),
(50, 21, 26, 519, 'وَجَآءَتْ كُلُّ نَفْسٍ مَّعَهَا سَآئِقٌ وَشَهِيدٌ', 'wa jāʾat kullu nafsin maʿahā sāʾiqun wa shahīd', 'Her nefis, beraberinde bir sevk eden (sürücü) ve bir şahit ile birlikte gelmiştir.'),
(50, 22, 26, 519, 'لَّقَدْ كُنتَ فِى غَفْلَةٍ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌ', 'Lekad kunte fî gafletin min hâzâ fekeshefnâ anke gıtâʾeke febasaruke-lyevme hadîdün', 'Andolsun ki sen bundan gaflet içindeydin. Biz de senden perdeni kaldırdık. Artık bugün gözün keskindir.'),
(50, 23, 26, 519, 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَىَّ عَتِيدٌ', 'wa qāla qarīnuhu hādhā mā ladayya ʿatīd', 'Onun arkadaşı (olan şeytan) dedi ki: İşte bu, yanımda hazır bulunan şeydir.'),
(50, 24, 26, 519, 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ', 'ʾalqiyā fī jahannama kulla kaffārin ʿanīd', 'Her inatçı kâfiri cehenneme atın!'),
(50, 25, 26, 519, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ', 'mannāʿin lil-khayri muʿtadin murīb', 'Hayrı önleyen, haddi aşan, şüpheye düşen.'),
(50, 26, 26, 519, 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', 'alladhī jaʿala maʿa -llāhi ilāhan ʾākhar fa-ʾalqiyāhu fī -l-ʿadhābi -š-šadīd', 'Allah ile beraber başka bir ilâh edineni, hemen onu en şiddetli azaba atıverin!'),
(50, 27, 26, 519, 'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِى ضَلَٰلٍۭ بَعِيدٍ', 'qāla qarīnuhu rabbanā mā aṭgaytuhu walākin kāna fī ḍalālin baʿīd', 'Onun arkadaşı (olan şeytan) dedi ki: "Rabbimiz! Ben onu azdırmadım, fakat kendisi derin bir sapıklık içinde idi."'),
(50, 28, 26, 519, 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', 'qāla lā taḫtaṣimū ladayya wa qad qaddamtū ilaykum bil-waʿīd', 'Allah şöyle buyurur: "Benim katımda çekişmeyin! Nitekim ben size daha önce uyarıda bulunmuştum."'),
(50, 29, 26, 519, 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'mā yubaddalu l-qawlu ladayya wa mā anā biẓallāmin lil-ʿabīd', 'Katımda söz (hüküm) değiştirilmez ve ben kullara zulmedici değilim.'),
(50, 30, 26, 519, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ', 'yawma naqūlu li-jahannama hal-im-talaʾti wa-taqūlu hal-min-mazīd', 'O gün cehenneme, ''Doldun mu?'' deriz. O da, ''Daha fazlası var mı?'' der.'),
(50, 31, 26, 519, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', 'wa-uzlifati l-jannatu li-l-muttaqīna ghayra baʿīd', 'Cennet, takva sahiplerine yaklaştırıldı; (onlardan) uzakta değil.'),
(50, 32, 26, 519, 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ', 'hādhā mā tūʿadūna likulli ʾawwābin ḥafīẓin', 'İşte bu, (vazifelerini yerine getirip) Allah''a yönelen ve (O''nun emirlerini) koruyan kimselere vaadedilen şeydir.'),
(50, 33, 26, 519, 'مَّنْ خَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍ مُّنِيبٍ', 'man hashiya ar-raḥmāna bil-ghaybi wa jāʾa bi-qalbin munībi', 'Rahmân''dan gıyaben korkan ve (O''na) yönelmiş bir kalple gelen kimse.'),
(50, 34, 26, 519, 'ٱدْخُلُوهَا بِسَلَٰمٍ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', 'udkhulūhā bisalāmin dhālika yawmūl-khulūd', 'Oraya selametle girin. İşte bu, ebedilik günüdür.'),
(50, 35, 26, 519, 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ', 'lahum mā yashāʾūna fīhā weladaynā mazīdun', 'Onlar için orada diledikleri her şey vardır. Katımızda ise daha fazlası da vardır.'),
(50, 36, 26, 520, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًا فَنَقَّبُوا۟ فِى ٱلْبِلَٰدِ هَلْ مِن مَّحِيصٍ', 'wa-kam ahlaqnā qablahum min qarnin hum ashadd minhum batshan fanaqqabū fī al-bilādi hal min maḥīṣin', 'Onlardan önce nice nesilleri helak ettik ki, onlar bunlardan daha kuvvetli idiler. Nihayet şehirlerde (evleri) delip geçtiler. Kurtulacak bir yer var mıydı?'),
(50, 37, 26, 520, 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌ', 'ʾinna fī ḏālika laḏikrā li-man kāna lahu qalbun ʾaw ʾalqā s-samʿa wa-huwa šahīd', 'Şüphesiz bunda, kalbi olan veya (söz) dinlerken hazır bulunan kimse için elbette bir öğüt vardır.'),
(50, 38, 26, 520, 'وَلَقَدْ خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ', 'Ve lekad halaknâs semâvâti vel arda ve mâ beynehumâ fî sitteti eyyâmîn Ve mâ messenâ min lugûbîn', 'Andolsun ki gökleri, yeri ve ikisi arasındakileri altı günde yarattık ve bize hiçbir yorgunluk dokunmadı.'),
(50, 39, 26, 520, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', 'faṣbir ʿalā mā yaqūlūn wa-sabbiḥ bi-ḥamdi rabbika qabla ṭulūʿi sh-shamsi wa-qabla l-ghurūbi', 'Onların dediklerine sabret. Güneşin doğuşundan önce ve batışından önce Rabbini hamd ile tesbih et.'),
(50, 40, 26, 520, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَأَدْبَٰرَ ٱلسُّجُودِ', 'wa-mina l-layli fa-sabbih''hu wa-adbāra s-sujūd', 'Ve geceden de O''nu tesbih et ve secdelerin ardından da.'),
(50, 41, 26, 520, 'وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍ قَرِيبٍ', 'wastamiʿ yawma yunādi l-munādi min makānin qarībin', 'O gün, çağırıcı yakın bir yerden seslendiği zaman dinle.'),
(50, 42, 26, 520, 'يَوْمَ يَسْمَعُونَ ٱلصَّيْحَةَ بِٱلْحَقِّ ذَٰلِكَ يَوْمُ ٱلْخُرُوجِ', 'yawma yasmaʿūna ṣ-ṣayḥata bi-l-ḥaqqi dhālika yawmu l-khurūji', 'Onların, hakkıyla o korkunç sayhayı (sûru) işitecekleri günü (hatırla). İşte o, kabirlerden çıkış günüdür.'),
(50, 43, 26, 520, 'إِنَّا نَحْنُ نُحْىِۦ وَنُمِيتُ وَإِلَيْنَا ٱلْمَصِيرُ', 'ʾinnā naḥnu nuḥyī wa numītu wa ʾilayna l-maṣīru', 'Şüphesiz biz hem diriltiriz hem de öldürürüz ve dönüş yalnız banadır.'),
(50, 44, 26, 520, 'يَوْمَ تَشَقَّقُ ٱلْأَرْضُ عَنْهُمْ سِرَاعًا ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌ', 'yawma tashaqqaqu l-arḍu ʿanhum sirāʿan dhālika ḥashrun ʿalaynā yasīrun', 'O gün yer onlardan yarılıp çıkacaklar; bu, bize göre toplanması kolay bir haşirdir.'),
(50, 45, 26, 520, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ وَمَآ أَنتَ عَلَيْهِم بِجَبَّارٍ فَذَكِّرْ بِٱلْقُرْءَانِ مَن يَخَافُ وَعِيدِ', 'Naḥnu aʿlamu bimā yaqūlūn Wa mā anta ʿalayhim bijabbār Fadhakkir bil-Qurʾāni man yakhāfu waʿīd', 'Onların ne söylediklerini biz daha iyi biliriz. Sen onlara karşı zorlayıcı değilsin. Korkana Kur''an ile öğüt ver.'),
(51, 1, 26, 520, 'وَٱلذَّٰرِيَٰتِ ذَرْوًا', 'wa-l-dhāriyāti dharwan', 'Tozuyanlara (rüzgârlara) yemin olsun!'),
(51, 2, 26, 520, 'فَٱلْحَٰمِلَٰتِ وِقْرًا', 'fa-l-ḥāmilāti wiqran', 'Yük taşıyanlara (da)'),
(51, 3, 26, 520, 'فَٱلْجَٰرِيَٰتِ يُسْرًا', 'fa-l-jāriyāti yusran', 'Yemin ederim o (rüzgârlara) ki, (gemileri) kolaylıkla yürütenlere.'),
(51, 4, 26, 520, 'فَٱلْمُقَسِّمَٰتِ أَمْرًا', 'fa-l-muqassimāti amran', 'İşte bunlarla görevlendirilenlere yemin ederim ki,'),
(51, 5, 26, 520, 'إِنَّمَا تُوعَدُونَ لَصَادِقٌ', 'innamā tūʿadūna laṣādiq', 'Şüphesiz, size vaadedilen (olan) elbette doğrudur.'),
(51, 6, 26, 520, 'وَإِنَّ ٱلدِّينَ لَوَٰقِعٌ', 'waʾinna d-dīna lawāqiʿun', 'Şüphesiz, din (hesap günü) mutlaka gerçekleşecektir.'),
(51, 7, 26, 521, 'وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ', 'wa-s-samāʾi ḏāti l-ḥubuki', 'Kasem olsun o (birbirine) uyumlu, düzgün yapılı göğe ki,'),
(51, 8, 26, 521, 'إِنَّكُمْ لَفِى قَوْلٍ مُّخْتَلِفٍ', 'ʾinnakum lafī qawlin muḫtalif', 'Şüphesiz siz, ihtilaflı bir söz içindesiniz.'),
(51, 9, 26, 521, 'يُؤْفَكُ عَنْهُ مَنْ أُفِكَ', 'yuʾfaku ʿanhu man ʾufika', 'Ondan ancak perdelenmiş olanlar perdelenir.'),
(51, 10, 26, 521, 'قُتِلَ ٱلْخَرَّٰصُونَ', 'qutila l-kharraṣūn', 'Kahrolası yalancılar!'),
(51, 11, 26, 521, 'ٱلَّذِينَ هُمْ فِى غَمْرَةٍ سَاهُونَ', 'alladhīna hum fī ghamratin sāhūn', 'Onlar ki, gaflet içinde dalmışlardır.'),
(51, 12, 26, 521, 'يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ', 'yas''alūna ayyāna yawmu d-dīn', 'Din Günü''nün ne zaman olduğunu sorarlar.'),
(51, 13, 26, 521, 'يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ', 'yawma hum ʿalā n-nāri yuftunūn', 'Onların ateşte sınanacakları gün.'),
(51, 14, 26, 521, 'ذُوقُوا۟ فِتْنَتَكُمْ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'dhūqū fitnetakum hādhā alladhī kuntum bihī tastaʿcilūn', 'Fitnenizi tadın! İşte bu, acele istediğiniz şeydir.'),
(51, 15, 26, 521, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَعُيُونٍ', 'ʾinna l-muttaqīna fī jannātin wa-ʿuyūnin', 'Şüphesiz takva sahipleri cennetlerde ve pınar başlarındadır.'),
(51, 16, 26, 521, 'ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ', 'ākhidhīna mā ʾātāhum rabbuhum ʾinnahum kānū qabla dhālika muḥsinīna', 'Rablerinin kendilerine verdikleriyle zevk ve sefa sürerler. Çünkü onlar, bundan önce dünyada güzel davrananlardı.'),
(51, 17, 26, 521, 'كَانُوا۟ قَلِيلًا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ', 'kānū qelīlen mine-l-ley''li mā yehjacūn', 'Onlar geceleri az uyurlardı.'),
(51, 18, 26, 521, 'وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ', 'wa bil-ʾasḥāri hum yastaghfirūn', 'Onlar, seher vakitlerinde de bağışlanma dilerlerdi.'),
(51, 19, 26, 521, 'وَفِىٓ أَمْوَٰلِهِمْ حَقٌّ لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'wa-fī ʾamwālihim ḥaqqun lil-sāʾili wa-l-maḥrūmi', 'Onların mallarında (yardım) isteyen ve (mahrum kalıp) mahrum kalanlar için bir hak vardı.'),
(51, 20, 26, 521, 'وَفِى ٱلْأَرْضِ ءَايَٰتٌ لِّلْمُوقِنِينَ', 'wa-fī l-arḍi ʾāyātun lil-mūqinīn', 'Yeryüzünde kesin bilgi sahibi olanlar için de nice deliller vardır.'),
(51, 21, 26, 521, 'وَفِىٓ أَنفُسِكُمْ أَفَلَا تُبْصِرُونَ', 'wa-fī ʾanfusikum ʾafalā tubṣirūn', 'Nefislerinizde de ayetler vardır. Hâlâ basiret edemez misiniz?'),
(51, 22, 26, 521, 'وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', 'wa-fī s-samāʾi rizqukum wa-mā tūʿadūn', 'Gök de sizin rızkınız ve size vaad olunan şeyler de (orada)dır.'),
(51, 23, 26, 521, 'فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ', 'fa-wa-rabb-i as-samāʾ-i wa-al-ʾarḍ-i ʾinna-hū la-ḥaqq-un mithla mā ʾanna-kum tanṭiqūn-i', 'Gök ve yerin Rabbine yemin olsun ki, sizin konuşmanız gibi, bu (vaad olunan azap) elbette haktır.'),
(51, 24, 26, 521, 'هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ', 'hal atāka ḥadīthu ḍayfi ibrāhīma l-mukramīn', 'İbrahim''in ağırlanan konuklarının haberi sana geldi mi?'),
(51, 25, 26, 521, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ قَوْمٌ مُّنكَرُونَ', 'idh dakhallū ʿalayhi faqālū salāman qāla salāmun qawmun munkarūn', 'Onu ziyarete gelenler (melekler) yanına girdiklerinde, ''Selam!'' dediler. O da, ''Selam! Siz tanınmayan bir topluluksunuz!'' dedi.'),
(51, 26, 26, 521, 'فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍ سَمِينٍ', 'farāġa ʾilā ʾahlihī fagāʾa biʿijlin semīn', 'Bunun üzerine ailesinin yanına gizlice gidip semiz bir buzağı getirdi.'),
(51, 27, 26, 521, 'فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ', 'faqarrahū ʾilayhim qāla ʾalā taʾkulūn', 'Derken (İbrahim) onlara (ikramı) yaklaştırdı. (Onların yemediklerini görünce) şöyle dedi: "Yemez misiniz?"'),
(51, 28, 26, 521, 'فَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍ', 'faʾawjasa minhum xīfatan qālū lā taḫaf wa-baššarūhu bi-ḡulāmin ʿalīmin', 'Bunun üzerine onlardan bir korku sezdi. Dediler ki: "Korkma!" Ve ona bilgili bir oğlan müjdelediler.'),
(51, 29, 26, 521, 'فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌ', 'faʾaqbalati mraʾatuhu fī ṣarrah faṣakkat wajhahā waqālat ʿajūzun ʿaqīm', 'Bunun üzerine hanımı, (bir çığlık içinde) koşarak geldi, yüzüne vurdu ve "Ben yaşlı ve kısır bir kadınım!" dedi.'),
(51, 30, 26, 521, 'قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'qālū kadhāliki qāla rabbuki ʾinnahu huwa l-ḥakīmu l-ʿalīmu', 'Dediler ki: "Rabbimiz buyurdu ki: Şüphesiz O, Hikmet Sahibi''dir, Alim''dir."'),
(51, 31, 27, 522, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 'qāla famā khaṭbukum ayyuhā l-mursalūn', 'Dedi ki: "Ey elçiler! Sizin işiniz nedir?"'),
(51, 32, 27, 522, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ', 'qālū ʾinnā ʾursilnā ʾilā qawmin mujrimīn', 'Dediler ki: "Doğrusu biz, suçlu bir kavme gönderildik."'),
(51, 33, 27, 522, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةً مِّن طِينٍ', 'li-nur-sila ʿalay-him ḥi-jā-ra-tan min ṭīn', 'Üzerlerine balçıktan taşlar göndermek için'),
(51, 34, 27, 522, 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ', 'musawwamatan ʿinda rabbika lil-musrifīn', 'Onlar, Rabbinin katında, haddi aşanlar için işaretlenmiş (taşlar)dır.'),
(51, 35, 27, 522, 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ', 'faʾakhrajnā man kāna fīhā mina l-muʾminīn', 'Onun içinde bulunan müminleri çıkardık.'),
(51, 36, 27, 522, 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍ مِّنَ ٱلْمُسْلِمِينَ', 'fe-mā vecednā fīhā ġayra beytin mine-l-muslimīn', 'Nihayet orada Müslümanlardan bir evden başkasını bulmadık.'),
(51, 37, 27, 522, 'وَتَرَكْنَا فِيهَآ ءَايَةً لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ', 'wa taraknā fīhā āyatan lilladhīna yakhāfūna l-ʿadhāba l-ʾalīm', 'Onun içinde, acı azaptan korkan bir kavim için bir ibret de bıraktık.'),
(51, 38, 27, 522, 'وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنٍ مُّبِينٍ', 'wa-fī Mūsā ʾiḏ ʾarsalnāhu ʾilā Firʿawna bisulṭānin mubīnin', 'Musa''da da (ibretler vardır). Hani biz onu apaçık bir delille Firavun''a göndermiştik.'),
(51, 39, 27, 522, 'فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ أَوْ مَجْنُونٌ', 'fa-tawallā bi-ruknihi wa-qāla sāḥirun aw majnūnun', 'Böylece kendi gücüne güvenerek yüz çevirdi ve (halkına şöyle dedi): ''Bir sihirbaz ya da bir mecnundur.'''),
(51, 40, 27, 522, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌ', 'faʾakhaḏnāhu wa-junūda-hū fa-nabadhnāhum fī l-yamm wa-huwa mulīm', 'Böylece onu ve ordularını yakalayıp denize attık. Zaten o, kınanmış bir kimseydi.'),
(51, 41, 27, 522, 'وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ', 'wa-fī ʿādin ʾid ʾarsalnā ʿalayhimu r-rīḥa l-ʿaqīma', 'Ad kavminin de (helakini hatırla). Hani onlara o kısır rüzgarı göndermiştik.'),
(51, 42, 27, 522, 'مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ', 'mā tadhara min shayin atat ʿalayhi illā jaʿalathū ka-r-ramīm', 'O, uğradığı her şeyi kül edip savuruyordu.'),
(51, 43, 27, 522, 'وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍ', 'wa-fī th-amūda ʾidh qīla lahum tamattaʿū ḥattā ḥīnin', 'Semûd''a gelince: Onlara, ''Bir zamana kadar zevklenin'' denilmişti.'),
(51, 44, 27, 522, 'فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ وَهُمْ يَنظُرُونَ', 'faʿataw ʿan amri rabbihim faʾaḵaḏathumu ṣ-ṣāʿiqatu wa-hum yanẓurūn', 'Böylece Rablerinin emrinden yüz çevirdiler. Bu yüzden, kendileri bakıp dururken onları yıldırım (sayha) yakalayıverdi.'),
(51, 45, 27, 522, 'فَمَا ٱسْتَطَٰعُوا۟ مِن قِيَامٍ وَمَا كَانُوا۟ مُنتَصِرِينَ', 'fe-mā-staṭāʿū min qiyāmin ve-mā kānū muntasirīn', 'Ne kalkmaya güçleri yetti, ne de yardıma mazhar oldular.'),
(51, 46, 27, 522, 'وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', 'wa-qawma nūḥin min qablu ʾinnahum kānū qawman fāsiqīn', 'Ve daha önce Nuh kavmini de (helak ettik). Çünkü onlar fasık bir kavim idiler.'),
(51, 47, 27, 522, 'وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍ وَإِنَّا لَمُوسِعُونَ', 'wa-ssamāʾa banaynāhā bi-ʾaydin wa-ʾinnā la-mūsiʿūn', 'Göğü kudretimizle biz bina ettik ve şüphesiz biz (onu) genişletmekteyiz.'),
(51, 48, 27, 522, 'وَٱلْأَرْضَ فَرَشْنَٰهَا فَنِعْمَ ٱلْمَٰهِدُونَ', 'wa-l-arḍa farašnāhā fa-niʿma l-māhidūn', 'Yeri de biz döşedik. Ne güzel döşeyenleriz!'),
(51, 49, 27, 522, 'وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', 'wa min kulli shay’in khalaqnā zawjayni laʿallakum tadhakkarūn', 'Her şeyden de çift çift yarattık ki, düşünüp öğüt alasınız.'),
(51, 50, 27, 522, 'فَفِرُّوٓا۟ إِلَى ٱللَّهِ إِنِّى لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', 'fa-firruu ilallahi innii lakum minhu nadhiirum mubiin', 'Haydi Allah''a sığının. Ben sizi O''nun tarafından açıkça uyaran bir peygamberim.'),
(51, 51, 27, 522, 'وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ إِنِّى لَكُم مِّنْهُ نَذِيرٌ مُّبِينٌ', 'wa lā tajʿalū maʿa ʾllāhi ʾilāhan ʾākhara ʾinnī lakum minhu naẓīrun mubīnun', 'Allah ile beraber başka bir ilah edinmeyin. Ben sizin için O''nun tarafından (gönderilmiş) apaçık bir uyarıcıyım.'),
(51, 52, 27, 523, 'كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ', 'kadhalika ma atā alladhīna min qablihim min rasūlin illā qālū sāḥirun aw majnūn', 'İşte böyle! Onlardan öncekilere de hiçbir peygamber gelmemişti ki, ona "Büyücü" veya "Deli" dememiş olsunlar.'),
(51, 53, 27, 523, 'أَتَوَاصَوْا۟ بِهِۦ بَلْ هُمْ قَوْمٌ طَاغُونَ', 'etavāsav bihi bal hum qavmun ṭāġūn', 'Bunu birbirlerine vasiyet mi etmişlerdi? Hayır, onlar azgın bir kavimdir.'),
(51, 54, 27, 523, 'فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍ', 'fa tawalla ʿanhum fa mā anta bimalūm', 'Onlardan yüz çevir; çünkü sen kınanacak değilsin.'),
(51, 55, 27, 523, 'وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ', 'wa dhakkir fa-inna adh-dhikra tanfa''u al-mu''minīn', 'Ve öğüt ver; çünkü öğüt, mü''minlere fayda verir.'),
(51, 56, 27, 523, 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', 've ma halaktu l-cinne ve l-inse illa li ya''budun', 'Ben cinleri ve insanları, ancak bana kulluk etsinler diye yarattım.'),
(51, 57, 27, 523, 'مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍ وَمَآ أُرِيدُ أَن يُطْعِمُونِ', 'Mā urīdu minhum mir rizqin wa mā urīdu an yuṭʿimūni', 'Onlardan bir rızık istemiyorum ve beni yedirmelerini de istemiyorum.'),
(51, 58, 27, 523, 'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ', 'ʾinna ʾallāha huwa ʾar-razzāqu ḏū ʾl-quwwati ʾl-matīn', 'Şüphesiz Allah, rızık verenlerin en iyisi, mutlak güç sahibi ve kesindir.'),
(51, 59, 27, 523, 'فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًا مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ', 'faʾinna lilladhīna ẓalamū dhunūban mithla dhunūbi ʾaṣḥābihim falā yastaʿjilūn', 'Şüphesiz haksızlık edenler için, atalarının uğradığı azap gibi bir azap vardır. Şimdi (azabın gelmesini) acele istemesinler.'),
(51, 60, 27, 523, 'فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ', 'fa-waylun lilladhīna kafarū min yawmihimu lladhī yūʿadūn', 'O günleri kendilerine vaad olunanlar, o kâfirlerin vay haline!'),
(52, 1, 27, 523, 'وَٱلطُّورِ', 'wa-ṭ-ṭūri', 'Tûr''a ve...'),
(52, 2, 27, 523, 'وَكِتَٰبٍ مَّسْطُورٍ', 'wa kitābin masṭūr', 'Yemin ederim o yazılmış kitaba.'),
(52, 3, 27, 523, 'فِى رَقٍّ مَّنشُورٍ', 'fī raqqin manshūr', 'Açılmış ince bir deri içinde.'),
(52, 4, 27, 523, 'وَٱلْبَيْتِ ٱلْمَعْمُورِ', 'wa-l-bayti l-maʿmūr', 'Ve imar edilmiş Beyt''e (Kâbe''ye)'),
(52, 5, 27, 523, 'وَٱلسَّقْفِ ٱلْمَرْفُوعِ', 'wa-s-saqfi l-marfūʿi', 'Ve tavanı yükseltilmiş göğe.'),
(52, 6, 27, 523, 'وَٱلْبَحْرِ ٱلْمَسْجُورِ', 'wa-l-baḥri l-masjūr', 'Ve doldurulmuş denize yemin ederim.'),
(52, 7, 27, 523, 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٌ', 'ʾinna ʿaḏāba rabbika la-wāqiʿun', 'Şüphesiz Rabbinin azabı mutlaka gerçekleşecektir.'),
(52, 8, 27, 523, 'مَّا لَهُۥ مِن دَافِعٍ', 'mā lahū min dāfiʿin', 'Onu savacak hiçbir kimse yoktur.'),
(52, 9, 27, 523, 'يَوْمَ تَمُورُ ٱلسَّمَآءُ مَوْرًا', 'yawma tamūru s-samāʾu mawran', 'O gün gök, çalkalanıp sallandıkça sallanır.'),
(52, 10, 27, 523, 'وَتَسِيرُ ٱلْجِبَالُ سَيْرًا', 'wa tasīru l-jibālu sayran', 'Ve dağlar yürütüldükçe...'),
(52, 11, 27, 523, 'فَوَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'fa-waylun yawmaʾiḏin lil-mukaḏḏibīn', 'İşte o gün, yalanlayanların vay haline!'),
(52, 12, 27, 523, 'ٱلَّذِينَ هُمْ فِى خَوْضٍ يَلْعَبُونَ', 'alladhīna hum fī khawḍin yalʿabūn', 'Onlar ki, dalmışlardır, oynarlar.'),
(52, 13, 27, 523, 'يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا', 'yawma yudaʿʿūna ʾilā nāri jahannama daʿʿan', 'O gün ateşe, ateşe kovulup itileceklerdir.'),
(52, 14, 27, 523, 'هَٰذِهِ ٱلنَّارُ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'hāḏihi n-nāru l-latī kuntum bihā tukaḏḏibūn', 'İşte bu, yalanlamakta olduğunuz ateştir!'),
(52, 15, 27, 524, 'أَفَسِحْرٌ هَٰذَآ أَمْ أَنتُمْ لَا تُبْصِرُونَ', 'Afa siḥrun hādhā am antum lā tubṣirūn', 'Şimdi bu bir sihir midir, yoksa siz mi görmüyorsunuz?'),
(52, 16, 27, 524, 'ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'iṣlawhā faṣbirū aw lā taṣbirū sawāʾun ʿalaykum ʾinnamā tujzawna mā kuntum taʿmalūn', 'Ateşe girin! İster dayanın, ister dayanmayın, sizin için birdir. Siz ancak yaptıklarınızın karşılığını alacaksınız.'),
(52, 17, 27, 524, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَنَعِيمٍ', 'ʾinna l-muttaqīna fī jannātin wa-naʿīmin', 'Şüphesiz takva sahipleri cennetlerde ve nimet içindedir.'),
(52, 18, 27, 524, 'فَٰكِهِينَ بِمَآ ءَاتَىٰهُمْ رَبُّهُمْ وَوَقَىٰهُمْ رَبُّهُمْ عَذَابَ ٱلْجَحِيمِ', 'fākihīna bimā ātāhum rabbuhum wa waqāhum rabbuhum ʿadhāba l-jaḥīmi', 'Rablerinin onlara verdikleriyle sevinirlerken, Rableri de onları Cehennem azabından korumuştur.'),
(52, 19, 27, 524, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 'kulū wa-shrūbū hanīʾan bimā kuntum taʿmalūn', 'Yaptıklarınıza karşılık olarak afiyetle yiyin için.'),
(52, 20, 27, 524, 'مُتَّكِـِٔينَ عَلَىٰ سُرُرٍ مَّصْفُوفَةٍ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍ', 'muttakiʾīna ʿalā sururim maṣfūfah wa zawwajnāhum biḥūrin ʿīn', 'Karşılıklı sıralanmış tahtlar üzerinde yaslanırlar. Ve Biz onları iri gözlü hûrilerle evlendirmişizdir.'),
(52, 21, 27, 524, 'وَٱلَّذِينَ ءَامَنُوا۟ وَٱتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَٰهُم مِّنْ عَمَلِهِم مِّن شَىْءٍ كُلُّ ٱمْرِئٍۭ بِمَا كَسَبَ رَهِينٌ', 'wa-lladhīna ʾāmanū wa-ttabaʿathum dhurriyyatuhum bi-ʾīmānin ʾalḥaqnā bihim dhurriyyatahum wa-mā ʾalatnāhum min ʿamalihim min shayin kullu mriʾin bimā kasaba rahīnun', 'İman edip de soyları imanla kendilerine uyanlar... İşte biz onların soylarını da kendilerine katmışızdır ve onların amellerinden hiçbir şeyi eksiltmemişizdir. Herkes kendi kazandığıyla rehindir.'),
(52, 22, 27, 524, 'وَأَمْدَدْنَٰهُم بِفَٰكِهَةٍ وَلَحْمٍ مِّمَّا يَشْتَهُونَ', 'wa amdadnāhum bifākihah-w-walḥam-mim-mā yashtahūn', 'Onlara canlarının çektiği meyvelerden ve etten bol bol verdik.'),
(52, 23, 27, 524, 'يَتَنَٰزَعُونَ فِيهَا كَأْسًا لَّا لَغْوٌ فِيهَا وَلَا تَأْثِيمٌ', 'yatanāzaʿūna fīhā kaʾsan lā laghwun fīhā wa lā taʾthīmun', 'Orada ne boş bir söz ne de günaha sokacak bir şey vardır.'),
(52, 24, 27, 524, 'وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَّكْنُونٌ', 'wa yaṭūfu ʿalayhim ġilmānun lahum kaʾannahum luʾluʾun maknūn', 'Onların etraflarında, saklı inciler gibi genç hizmetçiler dolaşır.'),
(52, 25, 27, 524, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ', 'wa-ʾaqbala baʿḍuhum ʿalā baʿḍin yatasāʾalūn', 'Ve onlardan bir kısmı, diğerlerine dönerek birbirlerine sorarlar.'),
(52, 26, 27, 524, 'قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ', 'qālū ʾinnā kunnā qablu fī ʾahlinā mušfiqīn', 'Dediler ki: "Doğrusu biz bundan önce ailemiz içinde (azaptan) korkardık."'),
(52, 27, 27, 524, 'فَمَنَّ ٱللَّهُ عَلَيْنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ', 'fe menna llāhu ʿalaynā wa waqānā ʿadhāba s-samūmi', 'Böylece Allah bize lütufta bulundu ve bizi (vücutları) eriten ateşin azabından korudu.'),
(52, 28, 27, 524, 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ', 'innā kunnā min qablu nadʿūhu innahu huwa al-barru ar-raḥīmu', 'Şüphesiz biz bundan önce de O''na dua ederdik. Şüphesiz O, iyilik ve merhamet sahibi olandır.'),
(52, 29, 27, 524, 'فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍ', 'faḏakkir famā anta biniʿmati rabbika bikāhinin walā majnūnin', 'Sen öğüt verip hatırlat. Çünkü sen, Rabbinin nimetiyle bir kahin ve bir mecnun değilsin.'),
(52, 30, 27, 524, 'أَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِۦ رَيْبَ ٱلْمَنُونِ', 'ʾam yaqūlūna shāʿirun natarabbaṣu bihi ràyba l-manūni', 'Yoksa "O, bir şairdir; biz onu bir belanın gelip çatmasını gözetleriz" mü diyorlar?'),
(52, 31, 27, 524, 'قُلْ تَرَبَّصُوا۟ فَإِنِّى مَعَكُم مِّنَ ٱلْمُتَرَبِّصِينَ', 'qul tarabbaṣū faʾinnī maʿakum mina l-mutarabbaṣīn', 'De ki: Bekleyin! Şüphesiz ben de sizinle birlikte bekleyenlerdenim.'),
(52, 32, 27, 525, 'أَمْ تَأْمُرُهُمْ أَحْلَٰمُهُم بِهَٰذَآ أَمْ هُمْ قَوْمٌ طَاغُونَ', 'am taʾmuruhum aḥlāmuhum bihāḏā am hum qawmun ṭāġūn', 'Yoksa onlara, akılları mı bunu emrediyor, yoksa onlar azgın bir topluluk mu?'),
(52, 33, 27, 525, 'أَمْ يَقُولُونَ تَقَوَّلَهُۥ بَل لَّا يُؤْمِنُونَ', 'ʾam yaqūlūna taqawwalahū bal lā yuʾminūna', 'Yoksa "Onu kendiliğinden uydurdu" mu diyorlar? Hayır, onlar iman etmiyorlar.'),
(52, 34, 27, 525, 'فَلْيَأْتُوا۟ بِحَدِيثٍ مِّثْلِهِۦٓ إِن كَانُوا۟ صَٰدِقِينَ', 'falya''tū biḥadīthin mithlihī in kānū ṣādiqīn', 'Eğer doğru sözlülerse, haydi onun gibi bir söz getirsinler.'),
(52, 35, 27, 525, 'أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ', 'am ḫuliqū min ġayri šayʾin am humu l-ḫāliqūn', 'Yoksa onlar, hiçbir şeyden mi yaratıldılar? Yoksa yaratıcılar kendileri midirler?'),
(52, 36, 27, 525, 'أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بَل لَّا يُوقِنُونَ', 'am ḫalaqū s-samāwāti wa-l-arḍa bal lā yūqinūn', 'Yoksa gökleri ve yeri onlar mı yarattı? Hayır, onlar inanmazlar.'),
(52, 37, 27, 525, 'أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ٱلْمُصَۣيْطِرُونَ', 'ʾam ʿindaham ḫazāʾinu rabbika ʾam humu l-muṣṭayṭirūn', 'Yoksa Rabbinin hazineleri onların yanında mı? Yoksa her şeyin üzerinde egemenlik onlara mı ait?'),
(52, 38, 27, 525, 'أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَٰنٍ مُّبِينٍ', 'ʾam lahum sullamun yastamiʿūna fīhi falyʾati mustamiʿuhum bisulṭānin mubīnin', 'Yoksa onlara (göğe çıkan) bir merdiven mi var da orada dinliyorlar? Öyleyse onlardan dinleyen kimse apaçık bir delil getirsin.'),
(52, 39, 27, 525, 'أَمْ لَهُ ٱلْبَنَٰتُ وَلَكُمُ ٱلْبَنُونَ', 'ʾam lahu l-banātu wa lakumu l-banūna', 'Yoksa kızlar O''nun da, oğullar sizin mi?'),
(52, 40, 27, 525, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', 'am tas''aluhum ajran fe hum min magramin muthqalun', 'Yoksa onlardan bir ücret mi istiyorsun da onlar bu yüzden ağır bir borç yükü altında eziliyorlar?'),
(52, 41, 27, 525, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'ʾam ʿindahumu l-ḡaybu fa-hum yaktubūn', 'Yoksa gayb (gizli şeyler) onların yanındadır da onlar mı yazıyorlar?'),
(52, 42, 27, 525, 'أَمْ يُرِيدُونَ كَيْدًا فَٱلَّذِينَ كَفَرُوا۟ هُمُ ٱلْمَكِيدُونَ', 'ʾam yurīdūna kaydan fa-llaḏīna kafarū humu l-makīdūna', 'Yoksa bir tuzak mı kurmak istiyorlar? Hayır, tuzak kurmak isteyenler kendileridir.'),
(52, 43, 27, 525, 'أَمْ لَهُمْ إِلَٰهٌ غَيْرُ ٱللَّهِ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 'ʾam lahum ʾilāhun ġayru ʾllāhi subḥāna ʾllāhi ʿammā yušrikūn', 'Yoksa onlara Allah''tan başka ilâh mı var? Allah, onların ortak koştukları şeylerden münezzehtir.'),
(52, 44, 27, 525, 'وَإِن يَرَوْا۟ كِسْفًا مِّنَ ٱلسَّمَآءِ سَاقِطًا يَقُولُوا۟ سَحَابٌ مَّرْكُومٌ', 'wa-ʾin yaraw ḵisfan mina s-samāʾi sāqiṭan yaqūlū saḥābun marrūmun', 'Onlar, gökten bir parçanın düşmekte olduğunu görseler bile, ''Üst üste yığılmış bir buluttur'' derler.'),
(52, 45, 27, 525, 'فَذَرْهُمْ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ', 'feḏerhum ḥattā yu lāqū yawmahumu lladhī fīhi yuṣʿaqūn', 'Onları, çarpılacakları o günlerine kavuşuncaya kadar kendi hallerine bırak.'),
(52, 46, 27, 525, 'يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًٔا وَلَا هُمْ يُنصَرُونَ', 'yawma lā yughnī ʿanhum kayduhum shayʾan wa lā hum yunṣarūn', 'O gün, onların hileleri kendilerine hiçbir fayda sağlamaz ve onlara yardım da edilmez.'),
(52, 47, 27, 525, 'وَإِنَّ لِلَّذِينَ ظَلَمُوا۟ عَذَابًا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'waʾinna lilladhīna ẓalamū ʿadhāban dūna dhālika walākinna ʾaktharahum lā yaʿlamūn', 'Şüphesiz ki o zalimler için bundan başka da bir azap vardır. Fakat çokları bilmezler.'),
(52, 48, 27, 525, 'وَٱصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ', 'wa-ṣbir li-ḥukmi rabbika fa-ʾinnaka bi-ʾaʿyuninā wa-sabbih bi-ḥamdi rabbika ḥīna taqūmu', 'Rabbinin hükmüne sabret. Çünkü sen, gözlerimizin önündesin. Ve kalkarken de Rabbini hamd ile tesbih et.'),
(52, 49, 27, 525, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَإِدْبَٰرَ ٱلنُّجُومِ', 'wa-mina l-layli fa-sabbih-hu wa-idbāra n-nujūmi', 'Gecenin bir kısmında ve yıldızların batışından sonra da O''nu tesbih et.'),
(53, 1, 27, 526, 'وَٱلنَّجْمِ إِذَا هَوَىٰ', 'wa-n-najmi ʾidhā hawā', 'Yıldızlar battığı zaman.'),
(53, 2, 27, 526, 'مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ', 'mā ḍalla ṣāḥibukum wa mā ġawā', 'Arkadaşınız (Muhammed) sapmadı ve azmadı.'),
(53, 3, 27, 526, 'وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ', 'wa mā yanṭiqu ʿani l-hawā', 'O, kendi isteğiyle konuşmaz.'),
(53, 4, 27, 526, 'إِنْ هُوَ إِلَّا وَحْىٌ يُوحَىٰ', 'ʾin huwa ʾillā waḥyun yūḥā', 'O, yalnızca vahyolunan bir vahiydir.'),
(53, 5, 27, 526, 'عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ', 'ʿallamahū ʿšadīdu l-quwā', 'Onu, çetin kuvvet sahibi olan öğretti.'),
(53, 6, 27, 526, 'ذُو مِرَّةٍ فَٱسْتَوَىٰ', 'ḏū mirratin fa-stawā', 'O, çetin kuvvet sahibi idi de tam bir şekilde doğruldu.'),
(53, 7, 27, 526, 'وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ', 'wa-huwa bi-l-ʾufūqi l-ʾaʿlā', 'Ve O, en yüce ufukta idi.'),
(53, 8, 27, 526, 'ثُمَّ دَنَا فَتَدَلَّىٰ', 'thumma danā fatadal-lā', 'Sonra yaklaştı, derken sarktı.'),
(53, 9, 27, 526, 'فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ', 'fa-kāna qāba qavsayni aw adnā', 'Böylece ona (görülme) mesafesi kadar, hatta daha yakın oldu.'),
(53, 10, 27, 526, 'فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ', 'faʾawḥā ʾilā ʿabdihi mā ʾawḥā', 'Böylece kuluna vahyettiğini vahyetti.'),
(53, 11, 27, 526, 'مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ', 'mā kadhaba l-fuʾādu mā raʾā', 'Gördüğü kalbi yalanlamadı.'),
(53, 12, 27, 526, 'أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ', 'ʾafatumārūnahū ʿalā mā yarā', 'Şimdi siz, gördüğü şey hakkında onunla tartışacak mısınız?'),
(53, 13, 27, 526, 'وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ', 've lekad raʾāhu nezleten uḫrā', 'Andolsun ki onu bir başka inişinde de görmüştü.'),
(53, 14, 27, 526, 'عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ', 'ʿinda sidrati l-muntahā', 'Son ağacın yanında.'),
(53, 15, 27, 526, 'عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ', 'ʿindelahā jannatu l-maʾwā', 'Onun yanında Meva cenneti vardır.'),
(53, 16, 27, 526, 'إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ', 'idh yaghshā as-sidrata mā yaghshā', 'O zaman sidreye o şeyi kaplayan şey bürüyordu.'),
(53, 17, 27, 526, 'مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ', 'mā zāġa l-baṣaru wa mā ṭaġā', 'Göz [onun] ne döndü, ne de azdı.'),
(53, 18, 27, 526, 'لَقَدْ رَأَىٰ مِنْ ءَايَٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ', 'leḳad raʾā min ʾāyāti rabbihil-kubrā', 'Andolsun ki o, Rabbinin en büyük ayetlerinden (mucizelerinden) bazılarını görmüştür.'),
(53, 19, 27, 526, 'أَفَرَءَيْتُمُ ٱللَّٰتَ وَٱلْعُزَّىٰ', 'ʾaferaʾaytumul-lāta wal-ʿuzzā', 'Gördünüz mü Lât''ı ve Uzzâ''yı?'),
(53, 20, 27, 526, 'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ', 'wa manāta th-thālithata l-ʾukhrā', 'Ve Menât, diğer üçüncü (put)'),
(53, 21, 27, 526, 'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ', 'ʾal-ʿal-kum-u ʾaḏ-ḏakaru wa-lahu ʾal-ʾunṯā', 'Erkek olan size mi, dişi olan da O''na mı?'),
(53, 22, 27, 526, 'تِلْكَ إِذًا قِسْمَةٌ ضِيزَىٰٓ', 'tilka idhan qismatun ḍīzā', 'Öyleyse bu, (ne kadar) adaletsiz bir paylaştırmadır!'),
(53, 23, 27, 526, 'إِنْ هِىَ إِلَّآ أَسْمَآءٌ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ', 'in hiye illā esmāʾun semmeytumūhā entum ve ābāʾukum mā enzela llāhu bihā min sulṭānin in yettebiʿūne illā ẓ-ẓanne ve mā tehve l-enfusu ve leqad jāʾehum min rabbihimu l-hudā', 'Onlar, Allah''ın kendileriyle hiçbir delil indirmediği, yalnızca sizin ve atalarınızın uydurduğu birtakım isimlerden başkası değildir. Onlar, ancak zanna ve nefislerin arzu ettiğine uyarlar. Oysa onlara Rableri tarafından yol gösterici gelmiştir.'),
(53, 24, 27, 526, 'أَمْ لِلْإِنسَٰنِ مَا تَمَنَّىٰ', 'am lil-ʾinsāni mā tamanā', 'Yoksa insana dilediği her şey mi vardır?'),
(53, 25, 27, 526, 'فَلِلَّهِ ٱلْءَاخِرَةُ وَٱلْأُولَىٰ', 'falillāhi l-ākhiratu wa-l-ūlā', 'Son da ilk de Allah''ındır.'),
(53, 26, 27, 526, 'وَكَم مِّن مَّلَكٍ فِى ٱلسَّمَٰوَٰتِ لَا تُغْنِى شَفَٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ', 'wa-kam min malakin fī as-samāwāti lā tuġnī šafāʿatuhum šayʾan illā min baʿdi an yaʾḏana ʾallāhu li-man yašāʾu wa-yarḍā', 'Göklerde nice melekler vardır ki, onların şefaatleri hiçbir fayda vermez; ancak Allah''ın dilediği ve razı olduğu kimseler için izin vermesinden sonra başka.'),
(53, 27, 27, 527, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', 'inna alladhīna lā yuʾminūna bil-ʾākhirati layusammūna l-malāʾikata tasmiyata l-ʾunthā', 'Şüphesiz ahirete inanmayanlar meleklere dişilik ismiyle isim verirler.'),
(53, 28, 27, 527, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا', 've mā lehum bihi min ʿilmin in yettebiʿūne illāẓ-ẓanna ve inneẓ-ẓanne lā yuğnī mine l-ḥaqqi šeyʾan', 'Onların buna dair hiçbir bilgisi yoktur. Onlar ancak zanna uyar ve zannın hakka hiçbir faydası olmaz.'),
(53, 29, 27, 527, 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'faʾaʿriḍ ʿan man tawallā ʿan dhikrinā wa-lam yurid illā al-ḥayāta ad-dunyā', 'Bize (Kur''an''a) sırt dönen ve dünya hayatından başkasını istemeyen kimselerden yüz çevir.'),
(53, 30, 27, 527, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', 'dhālika mablaghuhum mina l-ʿilmi ʾinna rabbaka huwa ʾaʿlamu biman ḍalla ʿan sabīlihī wa-huwa ʾaʿlamu biman i-htadā', 'İşte onların ilimden yana erebildikleri son nokta budur. Şüphesiz Rabbin, kendi yolundan sapanı da, doğru yolu bulanı da en iyi bilendir.'),
(53, 31, 27, 527, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', 'wa lil-lāhi mā fī s-samāwāti wa mā fī l-arḍi li-yajziya l-ladhīna asāʾū bi-mā ʿamilū wa yajziya l-ladhīna aḥsanū bi-l-ḥusnā', 'Göklerde ve yerde ne varsa hepsi Allah''ındır. Kötülük yapanları yaptıklarından dolayı cezalandırması ve iyilik yapanları da yaptıklarıyla mükâfatlandırması için (böyle yapmıştır).'),
(53, 32, 27, 527, 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَٰتِكُمْ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', 'alladhīna yajtaniibūna kabaa''ira l-ithmi wa-l-fawaaḥisha illaa l-lamama inna rabbaka waasiʿu l-maghfirah huwa aʿlamu bikum idh ansha''akum mina l-arḍi wa-idh antum ajinnatun fii buṭūni ummahaatikum falaa tuzakkuu anfusakum huwa aʿlamu biman ittaqaa', 'Onlar, günahın büyüklerinden ve hayasızlıklardan kaçınırlar; küçük kusurlar (lelem) hariç. Şüphesiz Rabbin, mağfireti çok geniş olandır. O, sizi topraktan yarattığı ve siz annelerinizin karınlarında cenin(halde) iken sizi (en iyi) bilendir. Öyleyse kendinizi temize çıkarmayın. O, kimin takva sahibi olduğunu en iyi bilendir.'),
(53, 33, 27, 527, 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', 'Afara''ayta alladhī tawallā', 'Dönüp arkasını döneni gördün mü?'),
(53, 34, 27, 527, 'وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ', 'wa ʾaʿṭā qalīlan wa ʾakdā', 'Oysa o, az bir şey vermiş, sonra da kesmişti.'),
(53, 35, 27, 527, 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', 'ʾaʿindahu ʿilmu l-ġaybi fa-huwa yarā', 'Yoksa gaybın ilmi onun yanında da onun için mi görünüyor?'),
(53, 36, 27, 527, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', 'ʾam lam yunabbaʾ bimā fī ṣuḥufi Mūsā', 'Yoksa Musa''nın sahifelerinde olanlar ona bildirilmedi mi?'),
(53, 37, 27, 527, 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', 'wa-ʾibrāhīma l-ladhī waffā', 'Ve ahdini yerine getiren İbrahim''i (de).'),
(53, 38, 27, 527, 'أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ', 'ʾallā taziru wāziratun wizra ʾuḵrā', 'Hiçbir günahkar, başka bir günahkarın günahını yüklenmez.'),
(53, 39, 27, 527, 'وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ', 'wa-ʾanna laysa lil-ʾinsāni ʾillā mā saʿā', 'Ve insan için ancak çalıştığı şey vardır.'),
(53, 40, 27, 527, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', 'wa anna saʿyahu sawfa yurā', 'Ve yine, onun gayretinin (veya amellerinin) de ileride mutlaka görüleceği.'),
(53, 41, 27, 527, 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', 'thumma yujzāhu l-jazāʾa l-ʾawfā', 'Sonra ona eksiksiz karşılığı verilir.'),
(53, 42, 27, 527, 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', 'waʾanna ʾilā rabbika l-muntaḥā', 'Ve nihayet varılacak yer, ancak Rabbinin katıdır.'),
(53, 43, 27, 527, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', 'wa ʾannahu huwa ʾaḍḥaka wa ʾabkā', 'Ve yine O, güldürdü ve ağlattı.'),
(53, 44, 27, 527, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', 'wa ʾannahu huwa ʾamāta wa ʾaḥyā', 'Ve yine O, hem öldüren hem de diriltendir.'),
(53, 45, 27, 528, 'وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ', 'wa annahu khalaqa z-zawjayni dh-dhakara wa-l-unthā', 'Ve O''nun, erkek ve dişi olmak üzere iki çifti yarattığına (da şahitlik ederiz).'),
(53, 46, 27, 528, 'مِن نُّطْفَةٍ إِذَا تُمْنَىٰ', 'min nuṭfatin iḏā tumnā', 'Döllenip-akıtılmış bir nutfeden.'),
(53, 47, 27, 528, 'وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ', 'wa ʾanna ʿalayhi ʾn-nashʾata ʾl-ʾukhrā', 'Ve yine O''nun, diğer yaratmayı da gerçekleştireceği muhakkaktır.'),
(53, 48, 27, 528, 'وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ', 'wa annahu huwa aghnā wa aqnā', 'Ve O''dur zenginleştiren ve yeterli kılan.'),
(53, 49, 27, 528, 'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ', 'wa ʾannahu huwa rabb-u-š-šiʿrā', 'Ve O''nun, Şi''râ yıldızının Rabbi olduğu (gerçeği).'),
(53, 50, 27, 528, 'وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ', 'wa annahu ahlāka ʿādan al-ūlā', 'Ve yine O, öncekiler (olan) Âd kavmini helak etti.'),
(53, 51, 27, 528, 'وَثَمُودَا۟ فَمَآ أَبْقَىٰ', 'wa-thamūda famā abqā', 'Semud''a gelince, (onları da) bırakmadı.'),
(53, 52, 27, 528, 'وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ', 'wa qawma nūḥin min qablu innahum kānū hum aẓlama wa aṭghā', 'Daha önce Nuh kavmini de (helak ettik). Çünkü onlar daha zalim ve daha azgındılar.'),
(53, 53, 27, 528, 'وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ', 'wa-l-muʾtafikata ahwā', 'Altüst olan şehirleri de (yıkıp) yerle bir etti.'),
(53, 54, 27, 528, 'فَغَشَّىٰهَا مَا غَشَّىٰ', 'faġaššāhā mā ġaššā', 'Onu (o azabı) örttü ne örttüyse.'),
(53, 55, 27, 528, 'فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ', 'fa-bi-ʾayyi ʾālāʾi rabbika tatamārā', 'Şimdi Rabb''inin hangi nimetlerini yalan sayabilirsin?'),
(53, 56, 27, 528, 'هَٰذَا نَذِيرٌ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ', 'hādhā nadhīrun min an-nudhūri al-ūlā', 'Bu, (daha önce geçen) ilk uyarılardan bir uyarıcıdır.'),
(53, 57, 27, 528, 'أَزِفَتِ ٱلْءَازِفَةُ', 'ʾazifatil-ʾāzifah', 'Yaklaşan (o büyük hadise) yaklaştı.'),
(53, 58, 27, 528, 'لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ', 'laysa lahā min dūni llāhi kāshifatun', 'Onu Allah''tan başka açığa çıkaracak yoktur.'),
(53, 59, 27, 528, 'أَفَمِنْ هَٰذَا ٱلْحَدِيثِ تَعْجَبُونَ', 'ʾafamin hāḏā ʾlḥadīṯi taʿǧabūn', 'Şimdi siz bu söze mi şaşıyorsunuz?'),
(53, 60, 27, 528, 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', 'wa taḍḥakūna wa lā tabkūna', 'Siz gülüyorsunuz, ağlamıyorsunuz.'),
(53, 61, 27, 528, 'وَأَنتُمْ سَٰمِدُونَ', 'wa ʾantum sāmidoon', 'Siz ise kayıtsızca eğlenirsiniz.'),
(53, 62, 27, 528, 'فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟', 'fasjudū lillāhi waʿbudū', 'Artık Allah''a secde edin ve (O''na) kulluk edin.'),
(54, 1, 27, 528, 'ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ', 'iqtarabati s-saʿatu wa-nshaqqa l-qamaru', 'Saat (kıyamet) yaklaştı ve Ay yarıldı.'),
(54, 2, 27, 528, 'وَإِن يَرَوْا۟ ءَايَةً يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌ مُّسْتَمِرٌّ', 'wa-ʾin yaraw ʾāyatan yuʿriḍū wa-yaqūlū siḥrun mustamirr', 'Onlar bir mucize görseler, yüz çevirirler ve ''Bu, sürekliliği olan bir sihirdir'' derler.'),
(54, 3, 27, 528, 'وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ وَكُلُّ أَمْرٍ مُّسْتَقِرٌّ', 'wa kaḏḏabū wa-ttabaʿū ahwāʾahum wa-kullu amrin mustaqirrun', 'Onlar yalanladılar ve kendi hevalarına uydular. Halbuki her işin kararlaşacağı bir vakit vardır.'),
(54, 4, 27, 528, 'وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ', 'Ve lekad câe-hum mine-l-enbâi mâ fîhi muzdecerun', 'Andolsun ki onlara, içinde caydırıcı bir öğüt bulunan haberler gelmiştir.'),
(54, 5, 27, 528, 'حِكْمَةٌۢ بَٰلِغَةٌ فَمَا تُغْنِ ٱلنُّذُرُ', 'ḥikmetun bāliġah femā tuġni n-nuẕuru', 'Hikmetli, (her şeyi) kuşatan (bir vahiy). Fakat uyarılar (onlara) fayda vermez.'),
(54, 6, 27, 528, 'فَتَوَلَّ عَنْهُمْ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍ نُّكُرٍ', 'fa tawalla ʿanhum yawma yadʿu d-dāʿi ilā shayʾin nukurin', 'Artık onlardan yüz çevir. O gün davetçi, korkunç bir şeye çağıracaktır.'),
(54, 7, 27, 529, 'خُشَّعًا أَبْصَٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ', 'khushshaʿan abṣāruhum yakhrujūna mina l-ajdāthi kaʾannahum jarādun muntashirun', 'Gözleri dalgınlaşmış bir halde, sanki o (kabirlerinden) yayılmış çekirgeler gibi çıkarlar.'),
(54, 8, 27, 529, 'مُّهْطِعِينَ إِلَى ٱلدَّاعِ يَقُولُ ٱلْكَٰفِرُونَ هَٰذَا يَوْمٌ عَسِرٌ', 'muhtieen ila ad-da''i yaqulu l-kafirun hadha yawmun ''asir', 'Davetçiye doğru koşuşurlarken, kâfirler: "Bu, çetin bir gün!" derler.'),
(54, 9, 27, 529, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌ وَٱزْدُجِرَ', 'kadhdhabat qablahum qawmu nūḥin fakadhdhabū ʿabdanā waqālū majnūnun wazdajara', 'Onlardan önce Nuh''un kavmi de yalanlamıştı. Onlar da kulumuzu yalanlayıp: "Deli!" dediler ve (onu) şiddetle engellediler.'),
(54, 10, 27, 529, 'فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌ فَٱنتَصِرْ', 'fadʿā rabbahū annī maghlūbun fantaṣir', 'Bunun üzerine Rabbi''ne, "Ben yenik düştüm, bana yardım et!" diye dua etti.'),
(54, 11, 27, 529, 'فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍ مُّنْهَمِرٍ', 'fafataḥnā abwāba as-samāʾi bimāʾin munhamirin', 'Bunun üzerine göğün kapılarını, coşkun akan bir su ile açtık.'),
(54, 12, 27, 529, 'وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍ قَدْ قُدِرَ', 'wa-fajjarnā l-arḍa ʿuyūnan fa-ltaqā l-māʾu ʿalā ʾamrin qad qudira', 'Yeri kaynaklar fışkırarak akıttık. Derken su, takdir edilmiş bir iş için birleşti.'),
(54, 13, 27, 529, 'وَحَمَلْنَٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍ وَدُسُرٍ', 'wa ḥamalnāhu ʿalā dhāti alwāḥin wa dusurin', 'Onu (Nuh''u ve iman edenleri) tahtalar ve çivilerle (yapılmış gemi) üzerine taşıdık.'),
(54, 14, 27, 529, 'تَجْرِى بِأَعْيُنِنَا جَزَآءً لِّمَن كَانَ كُفِرَ', 'tajrī bi-ʾaʿyuninā jazāʾan liman kāna kufira', 'Gözlerimizin önünde (gözetimimizde) akıp gidiyordu. Bu, inkâr edilmiş olan kimseye bir mükâfattı.'),
(54, 15, 27, 529, 'وَلَقَد تَّرَكْنَٰهَآ ءَايَةً فَهَلْ مِن مُّدَّكِرٍ', 'Ve lekad teraknâhâ âyeten Fe hel min muddekirin', 'Andolsun ki Biz onu bir ibret olarak bıraktık. Var mı ibret alan?'),
(54, 16, 27, 529, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'fakayfa kāna ʿaḏābī wa nuḏuri', 'Azabım ve uyarılarım nasılmış (bir görseydiniz)!'),
(54, 17, 27, 529, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'Ve lekad yessernâ el-kurʾâne li-z-zikri Fe hel min muddekirin', 'Andolsun ki Kur''an''ı öğüt alınsın diye kolaylaştırdık. O halde öğüt alan yok mudur?'),
(54, 18, 27, 529, 'كَذَّبَتْ عَادٌ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'kadhdhabat ʿādun fakayfa kāna ʿadhābī wa nudhur', 'Ad kavmi de yalanladı. (Bak) azabım ve uyarılarım nasıl oldu!'),
(54, 19, 27, 529, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِى يَوْمِ نَحْسٍ مُّسْتَمِرٍّ', 'innā arsalnā ʿalayhim rīḥan ṣarṣaran fī yawmi naḥsin mustamirrin', 'Onların üzerine, uğursuz/devamlı bir günde dondurucu, buz gibi bir kasırga gönderdik.'),
(54, 20, 27, 529, 'تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ', 'Tanzʿu n-nāsa Kaʾannahum ʾaʿjāzu nakhline munqaʿir', 'İnsanları, sanki onlar kökünden sökülmüş hurma kütükleri gibi çekip alıyordu.'),
(54, 21, 27, 529, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'fakayfa kāna ʿaḏābī wa nuḏuri', 'Azabım ve uyarılarım nasılmış (gördüler)!'),
(54, 22, 27, 529, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'Ve lekad yessernâ el-kurʾâne liż-żikri Fe hel min muddekirin', 'Andolsun ki Kur''an''ı öğüt almak için kolaylaştırdık. Öğüt alan yok mudur?'),
(54, 23, 27, 529, 'كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ', 'kaḏḏabat ṯamūdu bi-n-nuḏur', 'Semûd (kavmi) de uyarıları yalanladı.'),
(54, 24, 27, 529, 'فَقَالُوٓا۟ أَبَشَرًا مِّنَّا وَٰحِدًا نَّتَّبِعُهُۥٓ إِنَّآ إِذًا لَّفِى ضَلَٰلٍ وَسُعُرٍ', 'faqālū ʾabasharan minnā wāḥidan nattabiʿuhu ʾinnanā ʾidhan lafī ḍalālin wa suʿurin', 'Bunun üzerine şöyle dediler: "Aramızdan bir tek insana mı uyacağız? O takdirde biz apaçık bir sapıklık ve çılgınlık içinde oluruz."'),
(54, 25, 27, 529, 'أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ', 'ʾaʾulqiya dh-dhikru ʿalayhi min-bayninā bal huwa kadhdhābun ʾashirun', 'İçimizden ona mı indirilmişti (bu vahiy)? Hayır, o, küstah bir yalancıdır!'),
(54, 26, 27, 529, 'سَيَعْلَمُونَ غَدًا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ', 'sa yaʿlamūna ġadan man al-kaḏḏābu l-ʾaširu', 'Yarın kimin yalancı, kimin şımarık olduğunu bilecekler.'),
(54, 27, 27, 529, 'إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةً لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ', 'innā mursilū n-nāqati fitnatan lahum fa-rtaqibhum wa-ṣṭabir', 'Şüphesiz biz onlara bir imtihan olmak üzere dişi deveyi göndereceğiz. Artık onları gözetle ve sabret.'),
(54, 28, 27, 530, 'وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ كُلُّ شِرْبٍ مُّحْتَضَرٌ', 'wa-nabbihum anna l-māʾa qismatun baynahum kullu shırbin muḥtaḍarun', 'Onlara, suyun aralarında taksim edilmiş olduğunu, her bir içme sırasının (kendisine) hazır olacağını haber ver.'),
(54, 29, 27, 530, 'فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ', 'fanādaw ṣāḥibahum fataʿāṭā faʿaqara', 'Bunun üzerine arkadaşlarına seslendiler de o (deveyle) ilişki kurdu ve onu kesti.'),
(54, 30, 27, 530, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 'fakayfa kāna ʿaḏābī wa nuḏuri', 'Azabım ve uyarılarım nasılmış!'),
(54, 31, 27, 530, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَٰحِدَةً فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ', 'ʾinnā ʾarsalnā ʿalayhim ṣayḥatan wāḥidatan fakānū ka-hašīmi l-muḥtaẓir', 'Biz de onların üzerine o korkunç sayhadan (bir tek çığlıktan) başka bir şey göndermedik de neticede derleyip toparlayanın kuruyup bir araya yığdığı çerçöpü haline getirdik.'),
(54, 32, 27, 530, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'Ve lekad yessernâ elkur''âne liẕẕikr(i) Fehel min muddekir(in)', 'Andolsun ki Kur''an''ı öğüt alınsın diye kolaylaştırdık. O halde öğüt alan yok mudur?'),
(54, 33, 27, 530, 'كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ', 'kadhdhabat qawmu lūṭin bi-n-nuḏur', 'Lût kavmi de uyarıcıları yalanladı.'),
(54, 34, 27, 530, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍ نَّجَّيْنَٰهُم بِسَحَرٍ', 'ʾinnā ʾarsalnā ʿalayhim ḥāṣibā ʾillā ʾāla Lūṭin najjaynāhum bisḥarin', 'Biz de onların üzerine taş yağdıran bir kasırga gönderdik; yalnız Lut''un ailesi müstesna. Onları seher vakti kurtardık.'),
(54, 35, 27, 530, 'نِّعْمَةً مِّنْ عِندِنَا كَذَٰلِكَ نَجْزِى مَن شَكَرَ', 'niʿmeten min ʿindinā kaḏālika najzî men šekara', 'Katımızdan bir nimet olarak. İşte biz, şükredeni böyle mükafatlandırırız.'),
(54, 36, 27, 530, 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ', 'Ve lekad enzerahum batşetenâ fe temârav bin nuzuri', 'Andolsun ki Bizim şiddetli yakalamamızla onları uyarmıştı da onlar uyarıları şüpheyle karşılamışlardı.'),
(54, 37, 27, 530, 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 'Ve lekad rāvedūhu ʿan ḍayfihī feṭamesnā aʿyunahum feẕūqū ʿaẕābī ve nuẕurī', 'Andolsun ki onlar, onun misafirleri hakkında kendisiyle mücadele ettiler. Bunun üzerine biz de onların gözlerini kör ettik. "Şimdi azabımı ve uyarılarımı tadın!" (dedik).'),
(54, 38, 27, 530, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ', 'Ve lekad sabbahahum bukraten azâbun mustekirrun', 'Andolsun ki, sabah erkenden üzerlerine sürekli bir azap gelmişti.'),
(54, 39, 27, 530, 'فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 'faḏūqū ʿaḏābī wanuḏurī', 'Tadın azabımı ve uyarılarımı!'),
(54, 40, 27, 530, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ', 'Ve lekad yessernâ el-kur''âne li''z-zikri Fehel min muddekirin', 'Andolsun ki Kur''an''ı öğüt almak için kolaylaştırdık. O halde öğüt alan yok mudur?'),
(54, 41, 27, 530, 'وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ', 'Ve lekad câe âle Fir''avne en-nuzuru', 'Andolsun ki Firavun ailesine de uyarılar gelmişti.'),
(54, 42, 27, 530, 'كَذَّبُوا۟ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذْنَٰهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ', 'kaḏḏabū bi-ʾāyātinā kullihā fa-ʾaḵaḏnāhum ʾaḵḏa ʿazīzin muqtadirin', 'Tüm ayetlerimizi yalanladılar. Biz de onları, mutlak güç sahibi, dilediğini yapan bir aziz (mutlak galipli) ile yakaladık.'),
(54, 43, 27, 530, 'أَكُفَّارُكُمْ خَيْرٌ مِّنْ أُو۟لَٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌ فِى ٱلزُّبُرِ', 'ʾakuffārukum ḫayrum min ʾūlāʾikum ʾam lakum barāʾatun fī ẓ-zuburi', 'Onların kâfirleri bunlardan daha mı hayırlıdır? Yoksa sizin için (ilahi) kitaplarda bir beraat (kurtuluş yazısı) mı vardır?'),
(54, 44, 27, 530, 'أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ', 'ʾam yaqūlūn naḥnu jamīʿum muntasir', 'Yoksa onlar, "Biz dağınık bir topluluğuz, (birbirimize) yardım ederiz" mü diyorlar?'),
(54, 45, 27, 530, 'سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ', 'sayuhzamu l-jamʿu wa-yuwallūna d-dubura', 'O topluluk yenilgiye uğrayacak ve gerisin geri (yüzüstü) döneceklerdir.'),
(54, 46, 27, 530, 'بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ', 'balis-sāʿatu mawʿiduhum was-sāʿatu ad-hā wa-amarr', 'Hayır, asıl onlara vaad olunan o saatir; ve o saat daha dehşetli ve daha acıdır.'),
(54, 47, 27, 530, 'إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَٰلٍ وَسُعُرٍ', 'ʾinna l-mujrimīna fī ḍalālin wa-suʿurin', 'Şüphesiz suçlular sapıklık ve çılgınlık içindedirler.'),
(54, 48, 27, 530, 'يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ', 'yawma yusḥabūna fī n-nāri ʿalā wujūhihim dhūqū mass saqara', 'O gün yüzüstü ateşte sürüklenecekler: "Tadın bakalım cehennemin dokunuşunu!"'),
(54, 49, 27, 530, 'إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍ', 'innā kulla shayin khalaqnāhu biqudirin', 'Doğrusu biz her şeyi bir ölçüye göre yarattık.'),
(54, 50, 27, 531, 'وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌ كَلَمْحٍۭ بِٱلْبَصَرِ', 'wa mā ʾamrunā ʾillā wāḥidatun kalambi bil-baṣar', 'Bizim emrimiz, göz kırpması gibi, yalnızca bir tek (ol)dur.'),
(54, 51, 27, 531, 'وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍ', 'Ve lekad ehleknâ eşyâ''akum Fe hel min muddekirin', 'Andolsun, biz sizin benzerlerinizi helak ettik. Hiç düşünen var mı?'),
(54, 52, 27, 531, 'وَكُلُّ شَىْءٍ فَعَلُوهُ فِى ٱلزُّبُرِ', 'wa kullu shayʾin faʿalūhu fī ẓ-zuburi', 'Yaptıkları her şey ise yazılıdır.'),
(54, 53, 27, 531, 'وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُّسْتَطَرٌ', 'wa kullun ṣagīrin wa kabīrin mustaṭarun', 'Her küçük ve büyük (her şey) satır satır yazılmıştır.'),
(54, 54, 27, 531, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَنَهَرٍ', 'ʾinna l-muttaqīna fī jannātin wa-nahar', 'Şüphesiz takva sahipleri, Rablerinin nezdinde, (cennetlerde) ve (bol) nehirlerin (kenarlarında)dır.'),
(54, 55, 27, 531, 'فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍۭ', 'fī maqʿadi ṣidqin ʿinda malīkin muqtadirin', 'Onlar, (sadakat ve doğruluk) makamında, O''nun katında, kudretli melikin (huzurunda)dırlar.'),
(55, 1, 27, 531, 'ٱلرَّحْمَٰنُ', 'Ar-Raḥmânu', 'Rahmân'),
(55, 2, 27, 531, 'عَلَّمَ ٱلْقُرْءَانَ', 'ʿallema l-qurʾāna', 'O, Kur''an''ı öğretti.'),
(55, 3, 27, 531, 'خَلَقَ ٱلْإِنسَٰنَ', 'ḫalaqa l-ʾinsāna', 'İnsanı yarattı'),
(55, 4, 27, 531, 'عَلَّمَهُ ٱلْبَيَانَ', 'ʿallamahu l-bayān', 'Ona beyanı (açıklama ve konuşma yeteneğini) öğretti.'),
(55, 5, 27, 531, 'ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍ', 'ash-shamsu wal-qamaru biḥusbān', 'Güneş ve Ay bir hesap iledir.'),
(55, 6, 27, 531, 'وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ', 'wa-n-najmu wa-sh-shajaru yasjudāni', 'Ve (yıldızlar ve ağaçlar) secde ederler.'),
(55, 7, 27, 531, 'وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ', 'wa-s-samāʾa rafaʿahā wa-waḍaʿa l-mīzāna', 'Gökleri O yükseltti ve dengeyi O koydu.'),
(55, 8, 27, 531, 'أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ', 'allā taṭġaw fīl-mīzān', 'Sakın olçüde/tartıda taşkınlık yapmayın.'),
(55, 9, 27, 531, 'وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ', 'wa-aqīmū al-wazna bil-qisṭi wa-lā tukhsi rū al-mīzāna', 'Ölçüyü adaletle tutun ve tartıda eksiklik yapmayın.'),
(55, 10, 27, 531, 'وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ', 'wa-l-arḍa waḍaʿahā lil-anām', 'Yeri de canlılar için yaratıp döşedi.'),
(55, 11, 27, 531, 'فِيهَا فَٰكِهَةٌ وَٱلنَّخْلُ ذَاتُ ٱلْأَكْمَامِ', 'fīhā fākihah(tun) wa-n-nakhlu dhātu l-ʾakmām(i)', 'Onun içinde meyveler ve tomurcukları çıkmış hurma ağaçları vardır.'),
(55, 12, 27, 531, 'وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ', 'wa-l-ḥabbu ḏū l-ʿaṣfi wa-r-rayḥānu', 'Ve taneler ve hoş kokulu bitkiler de O''nun (içindir).'),
(55, 13, 27, 531, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse, Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 14, 27, 531, 'خَلَقَ ٱلْإِنسَٰنَ مِن صَلْصَٰلٍ كَٱلْفَخَّارِ', 'ḫalaqa l-ʾinsāna min ṣalṣālin ka-l-faḫḫār', 'İnsanı, (çamurdan) pişmiş toprağa benzeyen bir balçıktan yarattı.'),
(55, 15, 27, 531, 'وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍ مِّن نَّارٍ', 'wa ḫalaqa l-ǧānna min māriǧin min nār', 'O, cinleri de, (dumansız) ateşten/alevden saf bir özden yarattı.'),
(55, 16, 27, 531, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaẓẓibān', 'Öyleyse Rabbinizin hangi ni''metlerini yalan sayarsınız?'),
(55, 17, 27, 532, 'رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ', 'rabbul meşrikayni ve rabbul mağribeyn', 'Doğu''nun da Rabbi, Batı''nın da Rabbi O''dur.'),
(55, 18, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin! Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 19, 27, 532, 'مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ', 'maraca l-baḥrayni yaltaqiyān', 'İki denizi birbirine salıverdi; ikisi de buluşurlar.'),
(55, 20, 27, 532, 'بَيْنَهُمَا بَرْزَخٌ لَّا يَبْغِيَانِ', 'baynahumā barzakhun lā yabghiyāni', 'İki deniz arasında bir engel vardır; birbirlerine karışmazlar.'),
(55, 21, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 22, 27, 532, 'يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ', 'yakhruju min-huma al-luʾluʾu wa-al-marjānu', 'Onlardan inci ve mercan çıkar.'),
(55, 23, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 24, 27, 532, 'وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 'wa-lahu l-jawāri l-munsha''ātu fī l-baḥri ka-l-aʿlāmi', 'Denizde dağlar gibi (yüzen) gemiler de O''na aittir.'),
(55, 25, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin! Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 26, 27, 532, 'كُلُّ مَنْ عَلَيْهَا فَانٍ', 'kullu men ʿalayhā fānin', 'Orada bulunan her şey yok olacaktır.'),
(55, 27, 27, 532, 'وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 'wa yabqā wajhu rabbika dhū al-jalāli wa al-ʾikrām', 'Rabbinin vech''i (zatı) bâki kalacaktır. O, celâl ve ikram sahibi olan Rabbindir.'),
(55, 28, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Şimdi Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 29, 27, 532, 'يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍ', 'yas''aluhu man fi as-samāwāti wa al-arḍi kulla yawmin huwa fī sha''nin', 'Göklerde ve yerde kim varsa hep O''ndan ister. O, her gün (bir) iştedir.'),
(55, 30, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse (ey insanlar ve cinler) Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 31, 27, 532, 'سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ', 'sanefruġu lakum ayyuha ṯ-ṯaqalān', 'Ey insan ve cin toplulukları! Yakında sizin için de hesaba çekilme vakti olacaktır.'),
(55, 32, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse (insan ve cin topluluğu) Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 33, 27, 532, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍ', 'yā maʿšara l-jinni wa-l-ʾinsi ʾini staṭaʿtum ʾan tanfudū min ʾaqṭāri s-samāwāti wa-l-ʾarḍi fa-nfuḏū lā tanfuḏūna ʾillā bi-sulṭānin', 'Ey cin ve insan topluluğu! Göklerin ve yerin (sınırlarından) taraflarından geçip gitmeye gücünüz yeterse, geçip gidin. (Fakat) O''nun otoritesi (ve gücü) olmadan geçip gidemezsiniz.'),
(55, 34, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin topluluğu! Rabb''inizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 35, 27, 532, 'يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ', 'yursalu ʿalaykumā shuwaẓun min an-nāri wa-nuḥāsun falā tantaṣirāni', 'Üzerinize ateşten bir kıvılcım ve erimiş maden gönderilir de kurtulamazsınız.'),
(55, 36, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaẓẓibān', 'Öyleyse Rabbinizin hangi nimetlerini yalanlıyorsunuz?'),
(55, 37, 27, 532, 'فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتْ وَرْدَةً كَٱلدِّهَانِ', 'fa-ʾiḏā nšaqaḳḳati s-samāʾu fa-kānat wardatan ka-d-dihān', 'Gök yarıldığı zaman, artık o gün, erimiş bir yağ (renginde) bir gül gibi olur.'),
(55, 38, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaẓẓibān', 'Ey ins ve cin! Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 39, 27, 532, 'فَيَوْمَئِذٍ لَّا يُسْـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٌ وَلَا جَآنٌّ', 'fa-yawmaʾiḏin lā yusʾalu ʿan ḏambihī ʾinsun walā jānnun', 'İşte o gün, ins ve cin''den hiç kimse günahından sorulmaz.'),
(55, 40, 27, 532, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'Fa bi-ayyi ālāʾi rabbikumā tukażżibān', 'Rabbinizin hangi nimetlerini yalanlıyorsunuz?'),
(55, 41, 27, 533, 'يُعْرَفُ ٱلْمُجْرِمُونَ بِسِيمَٰهُمْ فَيُؤْخَذُ بِٱلنَّوَٰصِى وَٱلْأَقْدَامِ', 'yuʿrafu l-mujrimūna bisīmāhum fayuʾkhadhu bi-n-nawāṣī wa-l-aqdām', 'Suçlular simalarından tanınır, böylece alınlarından ve ayaklarından yakalanır.'),
(55, 42, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin! Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 43, 27, 533, 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى يُكَذِّبُ بِهَا ٱلْمُجْرِمُونَ', 'hāḏihi jahanamul-latī yuḵaḏḏibu bihāl-mujrimūn', 'İşte bu, suçluların yalanladığı cehennemdir.'),
(55, 44, 27, 533, 'يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ءَانٍ', 'yaṭūfūna baynahā wa-bayna ḥamīmin ʾānin', 'Onlar, hem onun (ateşin) hem de kaynar suyun arasında dolaşırlar.'),
(55, 45, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin! Öyleyse Rabbinizin hangi ni''metlerini yalan sayarsınız?'),
(55, 46, 27, 533, 'وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ', 'wa liman khafa maqāma rabbihī jannatān', 'Rabbi makamından korkan kimse için iki cennet vardır.'),
(55, 47, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fabieyyi ālāʾi rabbikumā tukażżibān', 'Öyleyse (insan ve cin topluluğu), Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 48, 27, 533, 'ذَوَاتَآ أَفْنَانٍ', 'dhawātā ʾafnān', 'Her ikisi de çeşit çeşit meyve veren ağaçlardır.'),
(55, 49, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fabieyyi ālāʾi rabbikumā tukażżibān', 'Şimdi, Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 50, 27, 533, 'فِيهِمَا عَيْنَانِ تَجْرِيَانِ', 'fīhimā ʿaynāni tajriyāni', 'Onlarda akan iki pınar vardır.'),
(55, 51, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fe biʾayyi ʾālāʾi rabbikumā tukażżibān', 'Ey ins ve cin topluluğu! Şimdi Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 52, 27, 533, 'فِيهِمَا مِن كُلِّ فَٰكِهَةٍ زَوْجَانِ', 'fīhimā min kulli fākihah zevcān', 'Onlarda her iki türden meyvelerden ikişer tane vardır.'),
(55, 53, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin topluluğu! Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 54, 27, 533, 'مُتَّكِـِٔينَ عَلَىٰ فُرُشٍۭ بَطَآئِنُهَا مِنْ إِسْتَبْرَقٍ وَجَنَى ٱلْجَنَّتَيْنِ دَانٍ', 'muttakiʾīna ʿalā furushin baṭāʾinuhā min istabraq wa janā al-jannatayni dān', 'Onlar, içleri ipekten olan döşeklere yaslanırlar. İki cennetin de devşirilebilecek meyvesi yakındır.'),
(55, 55, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin! Rabbinizin hangi ni''metlerini yalan sayarsınız?'),
(55, 56, 27, 533, 'فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', 'fīhinna qāṣirātu ṭ-ṭarfi lam yaṭmithhunna insun qablahum wa-lā jānnun', 'Onlarda, bakışlarını yalnız eşlerine çevirmiş, kendilerinden önce cinlerden ve insanlardan hiçbir kimsenin dokunmadığı eşler vardır.'),
(55, 57, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Artık Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 58, 27, 533, 'كَأَنَّهُنَّ ٱلْيَاقُوتُ وَٱلْمَرْجَانُ', 'kaʾannahunna l-yāqūtu wa-l-marjānu', 'Onlar, yakut ve mercan gibidirler.'),
(55, 59, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 60, 27, 533, 'هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ', 'hal jazāʾu l-ʾiḥsāni ʾillā l-ʾiḥsān', 'İyiliğin karşılığı iyilikten başka mıdır?'),
(55, 61, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin! O halde Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 62, 27, 533, 'وَمِن دُونِهِمَا جَنَّتَانِ', 'wa-min dūnihimā jannatāni', 'Onların ikisinin altında da iki cennet vardır.'),
(55, 63, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaẓẓibān', 'Şimdi, Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 64, 27, 533, 'مُدْهَآمَّتَانِ', 'mud''hāmmatāni', 'Onlar, ikisi de simsiyah.'),
(55, 65, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Ey ins ve cin topluluğu! Öyleyse Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 66, 27, 533, 'فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ', 'fīhimā ʿaynāni naḍḍāḫatāni', 'On ikisinde de fışkıran kaynaklar vardır.'),
(55, 67, 27, 533, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Şimdi, Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 68, 27, 534, 'فِيهِمَا فَٰكِهَةٌ وَنَخْلٌ وَرُمَّانٌ', 'fīhimā fākihatun wa nakhluw wa rummān', 'Onlarda hem meyve, hem hurma ve nar vardır.'),
(55, 69, 27, 534, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 70, 27, 534, 'فِيهِنَّ خَيْرَٰتٌ حِسَانٌ', 'fīhinna khayrātun ḥisānun', 'Onlarda, hem iyi huylu hem de güzel (kadınlar) vardır.'),
(55, 71, 27, 534, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 72, 27, 534, 'حُورٌ مَّقْصُورَٰتٌ فِى ٱلْخِيَامِ', 'ḥūrun maqṣūratun fī l-khiyāmi', 'Onlar, çadırlarda kalmış hurilerdir.'),
(55, 73, 27, 534, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ayyi ālāʾi rabbikumā tukażżibān', 'Şimdi Rabbim''in hangi nimetlerini yalan sayarsınız?'),
(55, 74, 27, 534, 'لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', 'lam yaṭmithunna insun qablahum walā jānnun', 'Daha önce onlara ne bir insan ne de bir cin dokunmuştur.'),
(55, 75, 27, 534, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse Rabbinizin hangi nimetlerini yalan sayarsınız?'),
(55, 76, 27, 534, 'مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍ وَعَبْقَرِىٍّ حِسَانٍ', 'muttaki''īna ''alā rafrafin khuḍrin wa''abqariyyin ḥisānin', 'Onlar, yeşil yastıklara ve harika işlemeli örtülere yaslanırlar.'),
(55, 77, 27, 534, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 'fa-bi-ʾayyi ʾālāʾi rabbikumā tukaḏḏibān', 'Öyleyse, Rabbinizin hangi nimetlerini yalan sayabilirsiniz?'),
(55, 78, 27, 534, 'تَبَٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 'tabāraka-smu rabbika dhī-l-jalāli wa-l-ikrām', 'Rabbinin, celâl ve ikram sahibi olan ismi mübarektir.'),
(56, 1, 27, 534, 'إِذَا وَقَعَتِ ٱلْوَاقِعَةُ', 'iḏā waqaʿati l-wāqiʿah', 'Vakıa (yani, kıyamet) vuku bulduğu zaman,'),
(56, 2, 27, 534, 'لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ', 'laysa li-waqʿatihā kādhibatun', 'Onun vuku bulacağı an yalan değildir.'),
(56, 3, 27, 534, 'خَافِضَةٌ رَّافِعَةٌ', 'khāfiḍatun rāfiʿah', 'O, (insanları) alçaltıcı, (insanları) yükseltici.'),
(56, 4, 27, 534, 'إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّا', 'iḏā ruǧǧati l-arḍu raǧǧan', 'Yer, sarsıldıkça sarsıldığında,'),
(56, 5, 27, 534, 'وَبُسَّتِ ٱلْجِبَالُ بَسًّا', 'wa bussati l-jibālu bassan', 'Ve dağlar ufalanıp toz duman olunca,'),
(56, 6, 27, 534, 'فَكَانَتْ هَبَآءً مُّنۢبَثًّا', 'fa-kānat habāʾan munbaththā', 'İşte o zaman (o şeyler) saçılmış zerreler haline gelmiş olur.'),
(56, 7, 27, 534, 'وَكُنتُمْ أَزْوَٰجًا ثَلَٰثَةً', 'wa kuntum azwājan thalāthah', 'Sizler de üçe ayrılmış gruplar olursunuz.'),
(56, 8, 27, 534, 'فَأَصْحَٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَٰبُ ٱلْمَيْمَنَةِ', 'faʾaṣḥābu l-maymanati mā ʾaṣḥābu l-maymanati', 'Sağ taraf ashâbı (insanlar) nedir bilir misiniz? Sağ taraf ashâbı nedir?'),
(56, 9, 27, 534, 'وَأَصْحَٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ', 'wa-aṣḥābu l-mashʾamati mā aṣḥābu l-mashʾamati', 'Ashab-ı meş''eme (sol baştakiler) nedir, Ashab-ı meş''eme (sol baştakiler) nedir?'),
(56, 10, 27, 534, 'وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ', 'wa-s-sābiqūna s-sābiqūn', 'Ve (hayırda) öne geçenler, (cennette de) öne geçenlerdir.'),
(56, 11, 27, 534, 'أُو۟لَٰٓئِكَ ٱلْمُقَرَّبُونَ', 'ʾūlāʾika l-muqarrabūn', 'İşte onlar, (Allah''a) en yakın olanlardır.'),
(56, 12, 27, 534, 'فِى جَنَّٰتِ ٱلنَّعِيمِ', 'fī jannāti n-naʿīmi', 'Onlar, Naîm cennetlerindedirler.'),
(56, 13, 27, 534, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', 'thullatun min al-awwalīn', 'Onlardan birçoğu öncekilerdendir.'),
(56, 14, 27, 534, 'وَقَلِيلٌ مِّنَ ٱلْءَاخِرِينَ', 'wa qalīlun mina l-ʾākhirīn', 'Ve sonrakilerden az bir kısmı.'),
(56, 15, 27, 534, 'عَلَىٰ سُرُرٍ مَّوْضُونَةٍ', 'ʿalā sururin mawḍūnatin', 'İşlenmiş (altın işlemeli) tahtlar üzerindedirler.'),
(56, 16, 27, 534, 'مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَٰبِلِينَ', 'muttaʾkīna ʿalayhā mutaqābilīn', 'Onların üzerine yaslanmış, karşılıklı (otururlar).'),
(56, 17, 27, 535, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ', 'yaṭūfu ʿalayhim wildānum mukhalla-dūn', 'Onların etrafında (ölümsüz) gençler dolaşır.'),
(56, 18, 27, 535, 'بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِّن مَّعِينٍ', 'bi-ʾakwābin wa-ʾabārīqa wa-kaʾsin min maʿīnin', 'Onlara (doldurulmuş) kupalar, sürahiler ve (doldurulup) getirilen kadehler (sunulur).'),
(56, 19, 27, 535, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ', 'lā yuṣaddaʿūna ʿanhā wa lā yunzafūn', 'Onlardan ne baş ağrısı tutar ne de aklı başından gider.'),
(56, 20, 27, 535, 'وَفَٰكِهَةٍ مِّمَّا يَتَخَيَّرُونَ', 'wa-fākihatin mimmā yatakhayyarūn', 'Ve seçtikleri meyvelerden.'),
(56, 21, 27, 535, 'وَلَحْمِ طَيْرٍ مِّمَّا يَشْتَهُونَ', 'wa laḥmi ṭayrin mimmā yashtahūn', 'Ve canlarının çektiği kuş etleri.')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(56, 22, 27, 535, 'وَحُورٌ عِينٌ', 'wa ḥūrun ʿīn', 'Ve iri gözlü huriler.'),
(56, 23, 27, 535, 'كَأَمْثَٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ', 'kaʾamthāli l-luʾluʾi l-maknūn', 'Saklı inciler gibi.'),
(56, 24, 27, 535, 'جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 'jazāʾam bimā kānū yaʿmalūn', 'Onların yapmakta olduklarına bir karşılıktır.'),
(56, 25, 27, 535, 'لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا', 'lā yasmaʿūna fīhā laghwan walā taʾthīman', 'Onlar orada ne boş bir söz işitirler ne de günaha sokacak bir şey.'),
(56, 26, 27, 535, 'إِلَّا قِيلًا سَلَٰمًا سَلَٰمًا', 'illa qīlan salāman salāman', 'Ancak "Selam! Selam!" sözünü (işitirler).'),
(56, 27, 27, 535, 'وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ', 'wa-aṣḥābu l-yamīni mā aṣḥābu l-yamīni', 'Sağcılar ise, ne o sağcılardır!'),
(56, 28, 27, 535, 'فِى سِدْرٍ مَّخْضُودٍ', 'fī sidrin makhḍūd', 'Dikenleri budanmış sidr ağaçları (arasında)dır.'),
(56, 29, 27, 535, 'وَطَلْحٍ مَّنضُودٍ', 'wa ṭalḥin manḍūd', 'Ve salkım salkım muz.'),
(56, 30, 27, 535, 'وَظِلٍّ مَّمْدُودٍ', 'wa ẓillin mamdūdin', 'Ve uzatılmış bir gölgeye.'),
(56, 31, 27, 535, 'وَمَآءٍ مَّسْكُوبٍ', 'wa māʾim masqūbin', 'Ve akan bir su!'),
(56, 32, 27, 535, 'وَفَٰكِهَةٍ كَثِيرَةٍ', 'wa-fākiḥatin kathīrah', 'Ve bol miktarda meyve.'),
(56, 33, 27, 535, 'لَّا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍ', 'lā maqṭūʿatin walā mamnūʿatin', 'Ne kesintiye uğrar ne de yasaklanır.'),
(56, 34, 27, 535, 'وَفُرُشٍ مَّرْفُوعَةٍ', 'wa furushin marfūʿah', 'Ve yükseltilmiş eşler.'),
(56, 35, 27, 535, 'إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءً', 'ʾinnā ʾanšaʾnāhunna ʾinšāʾan', 'Doğrusu biz onları (o hurileri) bir daha oluşmayacak şekilde yaratmışızdır.'),
(56, 36, 27, 535, 'فَجَعَلْنَٰهُنَّ أَبْكَارًا', 'fa jaʿalnāhunna abkāran', 'Onları bâkireler kıldık.'),
(56, 37, 27, 535, 'عُرُبًا أَتْرَابًا', 'ʿuruban atrāban', 'Eş, yaşta, (ve) dillerini bilenler.'),
(56, 38, 27, 535, 'لِّأَصْحَٰبِ ٱلْيَمِينِ', 'li-aṣḥābi l-yamīnِ', 'Sağ ashabı için.'),
(56, 39, 27, 535, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', 'Thullatun min al-awwalīn', 'Onlardan birçoğu öncekilerdendir.'),
(56, 40, 27, 535, 'وَثُلَّةٌ مِّنَ ٱلْءَاخِرِينَ', 'wa thullatun mina l-ākhirīn', 'Ve sonrakilerden birçoğu.'),
(56, 41, 27, 535, 'وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ', 'wa-aṣḥābu sh-shimāli mā aṣḥābu sh-shimāli', 'Ashab-ı şimal! Ne (kötüdür) ashab-ı şimal!'),
(56, 42, 27, 535, 'فِى سَمُومٍ وَحَمِيمٍ', 'fī samūmin waḥamīmin', 'Alevli ateşin ve kaynar suyun içinde.'),
(56, 43, 27, 535, 'وَظِلٍّ مِّن يَحْمُومٍ', 'wa ẓillin min yaḥmūm', 'Ve kara dumandan bir gölge...'),
(56, 44, 27, 535, 'لَّا بَارِدٍ وَلَا كَرِيمٍ', 'lā bāridin wa lā karīm', 'Ne serin ne de hoş olur.'),
(56, 45, 27, 535, 'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ', 'innahum kānū qabla dhālika mutrafīn', 'Şüphesiz onlar, bundan önce (dünyada) refah içinde idiler.'),
(56, 46, 27, 535, 'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ', 'wa kānū yuṣirruna ʿalā al-ḥinṯi al-ʿaẓīm', 'Onlar, büyük günahda ısrar ediyorlardı.'),
(56, 47, 27, 535, 'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 'wa kānū yaqūlūn aʾiḏā mitnā wa kunnā turāban wa ʿiẓāman aʾinnanā lamabʿūṯūn', 'Ve diyorlardı ki: ''Biz kemikler olup toprak haline geldiğimizde mi, gerçekten biz mi (yeni bir) yaratılışla diriltilecekmişiz?'''),
(56, 48, 27, 535, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 'ʾawe ʾābāʾunā ʾel-ʾewwelūn', 'Yoksa atalarımız ilktekiler mi?'),
(56, 49, 27, 535, 'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْءَاخِرِينَ', 'qul inna l-ʾawwalīna wal-ʾākhirīn', 'De ki: "(Yaptıklarınızdan) öncekiler de, sonrakiler de...'),
(56, 50, 27, 535, 'لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍ مَّعْلُومٍ', 'lamajmūʿūna ʾilā mīqāti yawmin maʿlūm', 'Hepsi, belirlenmiş bir günün belli bir vakti için toplanmışlardır.'),
(56, 51, 27, 536, 'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ', 'thumma innakum ayyuhā aḍ-ḍāllūna l-mukaḏḏibūn', 'Sonra siz, ey (hakikati) yalanlayan o sapkınlar!'),
(56, 52, 27, 536, 'لَءَاكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ', 'la''ākilūna min shajarin min zaqqūm', 'Gerçekten zakkum ağacından yiyenler!'),
(56, 53, 27, 536, 'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 'famaliʾūna minhā al-buṭūn', 'O halde, karınlarınız tıka basa onunla dolacak.'),
(56, 54, 27, 536, 'فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ', 'fašārribūna ʿalayhi mina l-ḥamīm', 'Üzerine kaynar su içicilerdir.'),
(56, 55, 27, 536, 'فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ', 'fašāribūna šurba l-hīm', 'Onlar, (susuzluktan deve gibi) hastalıklı bir içişle içerler.'),
(56, 56, 27, 536, 'هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ', 'hādhā nuzuluhum yawma ʾd-dīni', 'İşte bu, onların din günü ziyafetidir.'),
(56, 57, 27, 536, 'نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ', 'naḥnu xalaqnākum falawlā tuṣaddiqūn', 'Sizi biz yarattık; buna neden inanmıyorsunuz?'),
(56, 58, 27, 536, 'أَفَرَءَيْتُم مَّا تُمْنُونَ', 'aferaʾaytum mā tumnūn', 'Sizden olan meniyi (sperm) görüyor musunuz?'),
(56, 59, 27, 536, 'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ', 'ʾaʾantum taḫluqūnahū ʾam naḥnu l-ḫāliqūn', 'Onu siz mi yaratıyorsunuz, yoksa yaratan Biz miyiz?'),
(56, 60, 27, 536, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'naḥnu qaddarnā baynakumu l-mawta wa-innā lamusbūqīn', 'Sizi (birbirinize) benzeyen topluluklar haline getirdik; sizi yok olmaktan kurtarıp yeniden var etmeye kadiriz.'),
(56, 61, 27, 536, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ', 'ʿalā ʾan nubaddila ʾamthālakum wa-nunshiʾakum fī mā lā taʿlamūn', 'Sizi başka benzerlerinizle değiştirmeye ve sizi bilmediğiniz bir şekilde yeniden yaratmaya (gücümüz yeter).'),
(56, 62, 27, 536, 'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', 'Ve lekad ''alimtumun-neş''etel-ūlā Felevlā teẕekkerūn', 'Andolsun, ilk yaratılışı bildiniz. Öyleyse düşünüp ibret almanız gerekmez mi?'),
(56, 63, 27, 536, 'أَفَرَءَيْتُم مَّا تَحْرُثُونَ', 'ʾaferʾaytum mā taḥrūthūn', 'Ektiğiniz (tohumlar) hakkında ne dersiniz?'),
(56, 64, 27, 536, 'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ', 'ʾaʾantum tazraʿūnahū ʾam naḥnu z-zāriʿūn', 'Onu siz mi bitiriyorsunuz, yoksa biz mi bitirenleriz?'),
(56, 65, 27, 536, 'لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًا فَظَلْتُمْ تَفَكَّهُونَ', 'law nasha2u laja3alnahu ḥuṭāman faẓaltum tafakkahūn', 'Eğer dilemiş olsaydık, onu kuru bir ot ve döküntü yapardık da siz (bunu) hayretle karşılardınız.'),
(56, 66, 27, 536, 'إِنَّا لَمُغْرَمُونَ', 'ʾinnā lamaġramūn', 'Şüphesiz biz, ziyana uğramışızdır.'),
(56, 67, 27, 536, 'بَلْ نَحْنُ مَحْرُومُونَ', 'bal naḥnu maḥrūmūn', 'Hayır, biz mahrum olanlarız.'),
(56, 68, 27, 536, 'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ', 'Afera''aytumul-mā''alladhī tashrabūn', 'İçtiğiniz suyu hiç düşündünüz mü?'),
(56, 69, 27, 536, 'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ', 'ʾaʾantum ʾanzaltumūhu mina l-muzni ʾam naḥnu l-munzilūn', 'Onu (bu suyu) buluttan siz mi indirdiniz, yoksa biz mi indiriniz?'),
(56, 70, 27, 536, 'لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ', 'law nashāʾu jaʿalnāhu ʾujājan falawlā tashkurūn', 'Eğer dilemiş olsaydık, onu tuzlu, acı bir su yapardık. Şükretmeniz gerekmez mi?'),
(56, 71, 27, 536, 'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ', 'Afare''aytumun-nāral-latī tūrūn', 'Gördünüz mü o tutuşturduğunuz ateşi?'),
(56, 72, 27, 536, 'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ', 'ʾaʾantum ʾanshaʾtum shajaratahā ʾam naḥnu l-munshiʾūn', 'Onu (o ağacı) siz mi meydana getirdiniz, yoksa onu meydana getiren Biz miyiz?'),
(56, 73, 27, 536, 'نَحْنُ جَعَلْنَٰهَا تَذْكِرَةً وَمَتَٰعًا لِّلْمُقْوِينَ', 'naḥnu jaʿalnāhā taḏkiratan wa matāʿan lilmuqween', 'Onu (bu Kur''an''ı) hem bir hatırlatıcı ve hem de (dünya nimetlerinden) faydalananlar için bir meta kıldık.'),
(56, 74, 27, 536, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'fa-sabbih bi-ismi rabbika l-ʿaẓīm', 'Öyleyse büyük Rabbinin adını tesbih et!'),
(56, 75, 27, 536, 'فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ', 'falā uqsimu bimawāqiʿi n-nujūmi', 'Yıldızların yerlerine yemin ederim ki!'),
(56, 76, 27, 536, 'وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ', 'wa innahu laqasamun law taʿlamūna ʿaẓīmun', 'Yemin olsun ki, eğer bilirseniz bu, pek büyük bir yemindir.'),
(56, 77, 27, 537, 'إِنَّهُۥ لَقُرْءَانٌ كَرِيمٌ', 'ʾinnahu la-qurʾānun karīmun', 'Şüphesiz ki o, değerli bir Kur''an''dır.'),
(56, 78, 27, 537, 'فِى كِتَٰبٍ مَّكْنُونٍ', 'fī kitābin maknūnin', 'O, korunmuş bir kitaptadır.'),
(56, 79, 27, 537, 'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ', 'lā yamassuhu ʾillā l-muṭahharūn', 'Ona ancak tertemiz olanlar dokunabilir.'),
(56, 80, 27, 537, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'tanzīlun min rabbil-ʿālamīn', 'O, âlemlerin Rabbi tarafından indirilmiştir.'),
(56, 81, 27, 537, 'أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ', 'ʾafabehāḏā ʾl-ḥadīṯi ʾantum mudʾinūn', 'Şimdi siz bu söze (Kur''an''a) mı yalan mı diyorsunuz?'),
(56, 82, 27, 537, 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', 'wa-tajʿalūna rizqakum annakum tukadhibūn', 'Siz de Kur''an''ı yalan saymanızla (onun) nasibinizi mi kılıyorsunuz?'),
(56, 83, 27, 537, 'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ', 'falawlā iḏā balagati l-ḥulqūma', 'Nihayet (can) boğaza dayandığı zaman,'),
(56, 84, 27, 537, 'وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ', 'wa ʾantum ḥīnaʾiḏin tanẓurūn', 'O zaman siz (sadece) bakıp durursunuz.'),
(56, 85, 27, 537, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', 'wa naḥnu ʾaqrabu ʾilayhi minkum walākin lā tubṣirūn', 'Oysa biz onu sizden daha yakınız, ama siz göremezsiniz.'),
(56, 86, 27, 537, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 'falawlā in kuntum ghayra madīniyyīn', 'Eğer (söylediklerinizde) doğru kimseler değilseniz, (söyleyin) neden geri döndürmüyorsunuz?'),
(56, 87, 27, 537, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ', 'tarjiʿūnahā in kuntum ṣādiqīn', 'Eğer (sözünüzde) doğru kimseler iseniz, onu (ruhları) geri getirin.'),
(56, 88, 27, 537, 'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ', 'fa-ammā in kāna mina l-muqarrabīn', 'Artık o, yakınlaştırılmışlardan ise,'),
(56, 89, 27, 537, 'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ', 'fa-rawḥun wa-rayḥānun wa-jannatu naʿīmin', 'Artık ona bir rahatlık, bir esenlik ve naim cenneti vardır.'),
(56, 90, 27, 537, 'وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 'wa ʾammā ʾin kāna min ʾaṣḥābi l-yamīn', 'Amma (gelince), eğer sağın ashâbından ise...'),
(56, 91, 27, 537, 'فَسَلَٰمٌ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 'Feselāmun leke min aṣḥābil-yemīn(i)', 'İşte o zaman (senin için)standen sağ tarafta olanlardan bir selâm vardır.'),
(56, 92, 27, 537, 'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ', 'wa-ammā in kāna mina l-mukadhibīna ḍ-ḍāllīn', 'Eğer yalanlayanlardan, sapmışlardan ise,'),
(56, 93, 27, 537, 'فَنُزُلٌ مِّنْ حَمِيمٍ', 'fanuzulun min hamim', 'İşte bu, kaynar sudan bir ziyafettir.'),
(56, 94, 27, 537, 'وَتَصْلِيَةُ جَحِيمٍ', 'wa taṣliyatu jaḥīm', 'Ve cehennem azabı çektirecektir.'),
(56, 95, 27, 537, 'إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ', 'ʾinna hāḏā lahuwa ḥaqqu l-yaqīn', 'Şüphesiz ki bu, kesin olan bir gerçektir.'),
(56, 96, 27, 537, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'fa-sabbih bi-ismi rabbika l-ʿaẓīm', 'Öyleyse, büyük Rabbinin adını tesbih et!'),
(57, 1, 27, 537, 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'sabbaha lillahi ma fi s-samawati wa-l-ardi wa huwa l-ʿazizu l-ḥakimu', 'Göklerde ve yerde ne varsa hepsi Allah''ı tesbih eder. O, Azîz''dir, Hakîm''dir.'),
(57, 2, 27, 537, 'لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'lahū mulku s-samāwāti wa-l-arḍi yuḥyī wa-yumītu wa-huwa ʿalā kulli shayʾin qadīrun', 'Göklerin ve yerin mülkiyeti O''nundur. O, hayat verir ve hayat alır. O, her şeye hakkıyla gücü yetendir.'),
(57, 3, 27, 537, 'هُوَ ٱلْأَوَّلُ وَٱلْءَاخِرُ وَٱلظَّٰهِرُ وَٱلْبَاطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'huwa l-ʾawwalu wal-ʾākhiru waẓ-ẓāhiru wal-bāṭinu wa huwa bikulli shayʾin ʿalīmun', 'O, ilktir, sondur, zahirdir ve batındır. O, her şeyi bilendir.'),
(57, 4, 27, 538, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'huve-lleẕī ḫalaḳa-s-semāvāti ve-l-arḍa fī sitteti eyyāmin ẗummestaẗvâ ʿalâ-l-ʿarşi yaʿlemu mā yeliču fī-l-arḍi ve-mā yaḫrucu minhā ve-mā yenzilu mine-s-semāʾi ve-mā yaʿrucu fīhā ve-huve meʿakum eyne-mā kuntum ve-llāhu bimā taʿmeleūne baṣīrun', 'O, gökleri ve yeri altı günde yaratan, sonra Arş''a istivâ eden (kurulan)dır. O, yere gireni ve yerden çıkanı, gökten ineni ve göğe yükseleni bilir. Nerede olursanız olun O sizinle beraberdir. Allah yaptıklarınızı hakkıyla görmektedir.'),
(57, 5, 27, 538, 'لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'lahu mulku as-samawati wal-ard wa ila Allahi turja''u al-umuru', 'Göklerin ve yerin mülkiyeti/hükümranlığı O''na aittir. Bütün işler de dönüp dolaşıp Allah''a varır.'),
(57, 6, 27, 538, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'yūliju l-layla fī n-nahāri wa yūliju n-nahāra fī l-layli wa huwa ʿalīmun bi-dhāti ṣ-ṣudūri', 'Geceyi gündüze sokar, gündüzü de geceye sokar. O, göğüslerin özünü bilendir.'),
(57, 7, 27, 538, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ', 'āminū billāhi wa rasūlihī wa anfiqū mimmā jaʿalakum mustahlafinīna fīhi fa-lladhīna āmanū minkum wa anfaqū lahum ajrun kabīrun', 'Allah''a ve Resûlü''ne iman edin; O''nun sizi halife kıldığı mallardan harcayın. Sizden iman edip harcayanlar için büyük bir ecir vardır.'),
(57, 8, 27, 538, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'Ve mâ lekum lâ tuʾminûne billâhi Ve''r-resûlu yed''ûkum li tuʾminû bi rabbikum Ve kad ehaze mîsâkakum in kuntum muʾminîn', 'Size ne oluyor da Allah''a inanmıyorsunuz? Oysa Peygamber sizi Rabbinize inanmaya çağırmaktadır ve sizden kesin bir söz de almıştır. Eğer inanacak olsaydınız.'),
(57, 9, 27, 538, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتٍۭ بَيِّنَٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ', 'huwa lladhī yunazzilu ʿalā ʿabdihi ʾāyātin bayyinātin liyuḫricakum mina ẓ-ẓulumāti ʾilā n-nūr wa ʾinna llāha bikum laraʾūfun raḥīmun', 'O, sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık ayetler indirendir. Şüphesiz Allah, size karşı çok şefkatli, çok merhametlidir.'),
(57, 10, 27, 538, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَٰتَلَ أُو۟لَٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَٰتَلُوا۟ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'wa mā lakum allā tunfiqū fī sabīli llāhi wa li llāhi mīrāthu s-samāwāti wa l-arḍi lā yastawī minkum man anfaqa min qabli l-fatḥi wa qātala ulāʾika aʿẓamu darajatan mina l-ladhīna anfaqū min baʿdu wa qātalū wa kullan waʿada llāhu l-ḥusnā wa llāhu bimā taʿmalūna khabīr', 'Allah yolunda harcama yapmayacağınız ne var size? Oysa göklerin ve yerin mirası Allah''ındır. İçinizden, fetihten önce harcayıp savaşanlar (diğerleri) ile bir olmaz. Onlar, dereca­t itibariyle, ondan sonra harcayıp savaşanlardan daha büyüktür. Allah, hepiniz için en güzeli vaat etmiştir. Allah, yapmakta olduklarınızdan haberdardır.'),
(57, 11, 27, 538, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ', 'man dhā alladhī yuqriḍu Allāha qarḍan ḥasanan fayuḍāʿifahu lahū wa lahū ajrun karīmun', 'Kimdir o ki Allah''a güzel bir borç versin de, O da ona kat kat ödesin? Ve ona cömertçe verilmiş bir ecir vardır.'),
(57, 12, 27, 539, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'yawma tarā al-muʾminīna wa-l-muʾmināti yasʿā nūruhum bayna ʾaydīhim wa-bi-ʾaymānihim bushrākum al-yawma jannātun tajrī min taḥtihā al-ʾanhāru khālidīna fīhā dhālika huwa al-fawzu al-ʿaẓīm', 'O gün, mü''min erkekleri ve mü''min kadınları, önlerinde ve sağlarında (ellerinde) nurları koşarken görürsün. "Bugün size müjde! Altlarından ırmaklar akan, içinde ebedi kalacağınız cennetler (var). İşte bu, büyük kurtuluştur."'),
(57, 13, 27, 539, 'يَوْمَ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', 'yawma yaqūlu l-munāfiqūna wa-l-munāfiqātu lilladhīna āmanū nẓurūnā naqtabis min nūrikum qīla rjiʿū warāʾakum fa-ltamisū nūran fa-ḍuriba baynahum bi-sūrin lahu bābun bāṭinuhu fīhi r-raḥmatu wa-ẓāhiruhu min qibalihi l-ʿadhābu', 'O gün münafık erkekler ve münafık kadınlar, iman edenlere şöyle derler: "Bize bakın da sizin nurunuzdan bir parça alalım." Onlara, "Arkanıza dönün de nur arayın!" denilir. Derken aralarına kapısı olan bir sur çekilir. Onun iç tarafında rahmet, dış tarafında ise azap vardır.'),
(57, 14, 27, 539, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ قَالُوا۟ بَلَىٰ وَلَٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'yunādūnahum ʾalam nakun maʿakum qālū balā walākinnakum fatantum ʾanfusakum wataraabbaṣtum wartabtum wa ġarratkumul-ʾamāniyyu ḥattā jāʾa ʾamrullāhi wa ġarrrakaum billāhil-ġarūru', 'Onlar münafıklara şöyle seslenirler: "Biz sizinle beraber değil miydik?" Münafıklar derler ki: "Evet, ama siz kendinizi fitneye attınız, bekleyip durdunuz, şüpheye düştünüz. Allah''ın emri gelinceye kadar sizi kuruntular aldattı. Ve o çok aldatıcı (şeytan) da sizi Allah ile aldattı."'),
(57, 15, 27, 539, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ مَأْوَىٰكُمُ ٱلنَّارُ هِىَ مَوْلَىٰكُمْ وَبِئْسَ ٱلْمَصِيرُ', 'Fa-l-yawma lā yuʾkhadhu minkum fidya Wa lā mina lladhīna kafarū Maʾwākumu n-nār Hiya mawlākum Wa biʾsa l-maṣīr', 'Artık bugün sizden ne fidye alınır ne de inkâr edenlerden. Sığınma yeriniz ateştir. Orası sizin dostunuzdur ve ne kötü bir dönüş yeridir!'),
(57, 16, 27, 539, 'أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'ʾelem yaʾni li-lleḏīna ʾāmanū ʾen taḫšaʿa qulūbuhum li-ḏikri llāhi wa-mā nazala mina l-ḥaqqi wa-lā yakūnū ka-lleḏīna ʾūtū l-kitāba min qablu fa-ṭāla ʿalayhimu l-ʾamadu fa-qasat qulūbuhum wa-kaṯīrun minhum fāsiqūna', 'İman edenlerin, Allah''ı anma ve O''ndan inen hak karşısında kalplerinin saygıyla dolması zamanı daha gelmedi mi? Daha önce kendilerine kitap verilenler gibi olmasınlar; uzun zaman geçtiği halde kalpleri katılaştı. Onlardan birçoğu yoldan çıkmışlardır.'),
(57, 17, 27, 539, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 'iʿlamūʾ anna ʾallāha yuḥyī l-ʾarḍa baʿda mawtihā qad bayyannā lakumu l-ʾāyāti laʿallakum taʿqilūna', 'Şunu iyi bilin ki Allah, yeryüzünü ölümünden sonra diriltir. Akıl erdiresiniz diye size ayetleri açıkladık.'),
(57, 18, 27, 539, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ', 'ʾinna l-muṣṣaddiqīna wa-l-muṣṣaddiqāti wa-ʾaqraḍū llāha qarḍan ḥasanan yuḍāʿafu lahum wa-lahum ʾajrun karīmun', 'Şüphesiz ki sadaka veren erkekler ve sadaka veren kadınlar ve Allah''a güzel bir borç verenler; onlar için kat kat artırılır ve onlara cömertçe verilmiş bir ecir vardır.'),
(57, 19, 27, 540, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'wa-lladhīna āmanū bi-llāhi wa-rusulihi ulāʾika humu ṣ-ṣiddīqūna wa-sh-shuhadāʾu ʿinda rabbihim lahum ajruhum wa-nūruhum wa-lladhīna kafarū wa-kadhadhabū bi-ʾāyātinā ulāʾika ʾaṣḥābu l-jaḥīmi', 'Allah''a ve Resûlü''ne iman edenler var ya, işte onlar Rableri katında sıddîklar ve şehitlerdir. Onların mükâfatları ve nûrları vardır. İnkâr edip âyetlerimizi yalanlayanlara gelince, işte onlar cehennemliktir.'),
(57, 20, 27, 540, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَٰمًا وَفِى ٱلْءَاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 'iʿlamū anna-mā l-ḥayātu d-dunyā laʿibun wa-lahwun wa-zīnatun wa-tafākhurun baynakum wa-takāthurun fī l-ʾamwāli wa-l-ʾawlādi ka-maṯali ġayṯin ʾaʿjaba l-kuffāra nabātuhū ṯumma yahīju fa-tarāhu muṣfarran ṯumma yakūnu ḥuṭāman wa-fī l-ʾākhirati ʿaḏābun šadīdun wa-maġfiratun mina llāhi wa-riḍwānun wa-mā l-ḥayātu d-dunyā ʾillā matāʿu l-ġurūri', 'Bilin ki, dünya hayatı ancak bir oyun, bir eğlence, bir süs, aranızda karşılıklı bir övünme, çok mal ve evlat sahibi olma isteğinden ibarettir. (Bu durum,) Tıpkı bir yağmurun bitirdiği ve (sonra) çiftçilerin (o bitkiyi görünce) hoşlandığı, ardından kuruyup sarardığı, sonra da çerçöp olduğu bir bitki gibidir. Ahirette ise (insanlar için) çetin bir azap ve Allah''tan bir bağışlanma ve hoşnutluk vardır. Dünya hayatı ise sadece aldatıcı bir zevkten ibarettir.'),
(57, 21, 27, 540, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'sābiqū ilā maghfiratin min rabbikum wa jannatin ʿarḍuhā ka-ʿarḍi s-samāʾi wa-l-arḍi uʿiddat li-lladhīna āmanū bi-llāhi wa rusulihī dhālika faḍlu llāhi yuʾtīhi man yashāʾu wa-llāhu dhū l-faḍli l-ʿaẓīmi', 'Rabbinizden bir bağışlanmaya ve genişliği göklerle yer kadar olan, Allah''a ve peygamberlerine iman edenler için hazırlanmış bir cennete doğru yarışın. İşte bu, Allah''ın dilediğine verdiği fazlıdır. Allah, büyük fazl sahibidir.'),
(57, 22, 27, 540, 'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'Mā aṣāba min muṣībatin fī l-arḍi walā fī ʾanfusikum ʾillā fī kitābin min qabli ʾan nabraʾahā ʾInna dhālika ʿalā Llāhi yasīrun', 'Yeryüzünde ve kendi nefislerinizde meydana gelen hiçbir musibet yoktur ki, biz onu yaratmadan önce bir kitapta (yazılı) olmasın. Şüphesiz bu, Allah için pek kolaydır.'),
(57, 23, 27, 540, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', 'likaylā taʾsaw ʿalā mā fātakum walā tafraḥū bimā ʾātakum wallāhu lā yuḥibbu kulla mukhtālin fakhūr', 'Böylece elinizden çıkana üzülmeyesiniz ve Allah''ın size verdiği nimetlerle de şımarmayasınız. Allah, kendini beğenip övünen hiç kimseyi sevmez.'),
(57, 24, 27, 540, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'alladhīna yabkhalūna wa yaʾmurūna n-nāsa bil-bukhl wa man yatawalla faʾinna llāha huwa l-ghanīyyu l-ḥamīd', 'Onlar ki cimrilik ederler ve insanlara da cimriliği emrederler. Kim yüz çevirirse, şüphesiz Allah zengin olan, hamd edilendir.'),
(57, 25, 27, 541, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', 'leḳad erselnâ rusulenâ bilbeyyinât ve enzelnâ meʿahümü-lkitâbe velmîzân liyeḳûme-nnâsü bilḳisṭ ve enzelne-lḥadîd fîhi beʾsün şedîdün vemenâfiʿu linnâs veliyaʿleme-llâhü men yenṣuruhû verusulehû bilgayb inne-llâhe ḳaviyyün ʿazîz', 'Andolsun ki biz, elçilerimizi apaçık delillerle gönderdik ve onlarla birlikte Kitab''ı ve mizanı indirdik ki insanlar adaletle ayakta dursunlar. Ve içinde çetin bir güç ve insanlar için faydalar bulunan demiri indirdik. Bir de Allah, gaybda kendisine ve elçilerine kimin yardım edeceğini bilsin diye (böyle yaptık). Şüphesiz Allah, çok kuvvetlidir, çok yücedir.'),
(57, 26, 27, 541, 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'Ve lekad erselnâ Nûhan ve İbrâhîme ve ce''alnâ fî zurriyyetihimâ en-nubuvvete ve el-kitâbe Fe minhum muhtedîn ve kesîrun minhum fâsikûn', 'Andolsun ki Nûh''u ve İbrâhîm''i gönderdik ve onların zürriyetlerine peygamberliği ve kitabı verdik. Onlardan kimisi doğru yola erişmiştir, onlardan çoğu ise fasıklardır.'),
(57, 27, 27, 541, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'thumma qaffaynā ʿalā ʾāthārihim birusulinā waqaffaynā biʿīsā ʾibni maryama wa ʾāttaynāhu l-ʾinjīla wa jaʿalnā fī qulūbi lladhīna ʾittabaʿūhu raʾfatan wa raḥmah wa rahbāniyyatan ʾibtadaʿūhā mā katabnāhā ʿalayhim ʾillā ʾibtiġāʾa riḍwāni l-llāhi famā raʿawhā ḥaqqa riʿāyatihā fa ʾāttaynā lladhīna ʾāmanū minhum ʾajrahum wa kathīrun minhum fāsiqūn', 'Sonra onların peşinden peygamberlerimizi gönderdik ve Meryem oğlu İsa''yı da arkalarından gönderdik; ona İncil''i verdik ve ona uyanların kalplerine şefkat ve merhamet koyduk. Onların uydurdukları ruhbanlığa gelince, biz onu onlara farz kılmamıştık. Ancak Allah''ın rızasını kazanmak için (kendiliklerinden) yaptılar. Ama ona da gereği gibi uymadılar. İçlerinden iman edenlere mükâfatlarını verdik. Onlardan ise çoğu yoldan çıkmışlardır.'),
(57, 28, 27, 541, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'yā ayyuhā lladhīna āmanū ttaqū l-lāha wa āminū bi-rasūlihi yuʾtikum kiflayni min raḥmatihi wa yajʿal lakum nūran tamshūna bihi wa yaghfir lakum wa-llāhu ghafūrun raḥīmun', 'Ey iman edenler! Allah''tan korkun ve O''nun Resûlü''ne iman edin ki size rahmetinden iki kat versin, size kendisiyle yürüyeceğiniz bir nur kılsın ve günahlarınızı bağışlasın. Allah çok bağışlayıcı, çok merhamet edicidir.'),
(57, 29, 27, 541, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'li''allā yaʿlama ʾahlu l-kitābi ʾallā yaqdirūna ʿalā šayʾin min faḍli llāhi wa-ʾanna l-faḍla bi-yadi llāhi yuʾtīhi man yašāʾu wa-llāhu ḏū l-faḍli l-ʿaẓīmi', 'Kitap ehlinin, Allah''ın fazlından hiçbir şeye güç yetiremeyeceklerini ve fazlın Allah''ın elinde olduğunu, dilediğine verdiğini bilmeleri için (böyle buyurdu). Allah, büyük fazl sahibidir.'),
(58, 1, 28, 542, 'قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'kad semiʿa l-lahu kawla allatī tujādiluka fī zawjihā wataštakī ilā l-lahi wa-l-lahu yasmaʿu taḥāwurakumā inna l-laha samīʿun baṣīrun', 'Allah, kocası hakkında seninle tartışan ve şikayetini Allah''a arz eden kadının sözünü işitmiştir. Allah, ikinizin konuşmasını işitir. Şüphesiz Allah, hakkıyla işiten, hakkıyla görendir.'),
(58, 2, 28, 542, 'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمْ إِنْ أُمَّهَٰتُهُمْ إِلَّا ٱلَّٰٓـِٔى وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', 'alladhīna yuẓāhirūna minkum min nisāʾihim mā hunna ummahātihim in ummahātuhum illā allāʾī waladnahum waʾinnahum layaqūlūna munkaran mina l-qawli wazūrā waʾinna ʾllāha laʿafūwun ghafūr', 'İçinizden kadınlarına zihar yapanlar (onları anneleri yerine koyanlar), onların anneleri değildir. Onların anneleri, sadece kendilerini doğuranlardır. Şüphesiz onlar, çirkin bir söz ve yalan söylemektedirler. Şüphesiz Allah, affedendir, bağışlayandır.'),
(58, 3, 28, 542, 'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ذَٰلِكُمْ تُوعَظُونَ بِهِۦ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'wa-lladhīna yuẓāhirūna min nisāʾihim thumma yaʿūdūna limā qālū fataḥrīru raqabatin min qabli an yatamāssā dhālikum tūʿaẓūna bihī wa-llāhu bimā taʿmalūna khabīr', 'Onlar, kadınlarından zihar yapıp sonra dediklerine dönenler, birbirleriyle temas etmeden önce bir köle azat etmelidirler. İşte bu, size yapılan bir öğüttür. Allah, yaptıklarınızdan haberdardır.'),
(58, 4, 28, 542, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتِلْكَ حُدُودُ ٱللَّهِ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', 'fe-men lem yecid fe-ṣiyāmu šahrayni mutetābiʿayni min qabli en yetemāssā fe-men lem yestaṭiʿ fa-ʾiṭʿāmu sittīna miskīnan ḏālika li-tuʾminū bi-llāhi wa-rasūlihī wa-tilka ḥudūdu llāh wa-li-l-kāfirīna ʿaḏābun ʾalīmun', 'Kim (bunu) bulamazsa, (kadınla) temas etmeden önce art arda iki ay oruç tutması gerekir. Kim de buna gücü yetmezse, altmış yoksulu doyurması gerekir. Bu, Allah''a ve Resûlü''ne iman etmeniz içindir. Bunlar Allah''ın sınırlarıdır. Kâfirler için ise elem dolu bir azap vardır.'),
(58, 5, 28, 542, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ وَقَدْ أَنزَلْنَآ ءَايَٰتٍۭ بَيِّنَٰتٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'ʾinna lladhīna yuḥāddūna llāha wa rasūlahū kubitū kamā kubita lladhīna min qablihim waqad ʾanzalnā ʾāyātin bayyinātin wa lilkāfirīna ʿadhābun muhīnun', 'Şüphesiz Allah''a ve Resûlü''ne düşmanlık edenler, kendilerinden öncekiler alçaltıldığı gibi alçaltılacaklardır. Oysa biz apaçık âyetler indirmişizdir. Kâfirler için de alçaltıcı bir azap vardır.'),
(58, 6, 28, 542, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'yawma yabʿathuhumu ʾllāhu jamīʿan fayunabbiʾuhum bimā ʿamilū ʾaḥṣāhu ʾllāhu wa nasūhu wa ʾllāhu ʿalā kulli shayʾin shahīd', 'Allah''ın, onları hep birden haşredeceği, sonra da yaptıkları her şeyi kendilerine bildireceği günü (hatırla). Allah, onları tek tek saymış, onlar ise unutmuşlardır. Allah, her şeye hakkıyla şahittir.'),
(58, 7, 28, 543, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'ʾalam tara ʾanna ʾallāha yaʿlamu mā fī s-samāwāti wa mā fī l-ʾarḍi mā yakūnu min najwā thalāthatin ʾillā huwa rābiʿuhum wa lā khamsatin ʾillā huwa sādisuhum wa lā ʾadnā min dhālika wa lā ʾakthara ʾillā huwa maʿahum ʾayna mā kānū thumma yunabbiʾuhum bimā ʿamilū yawma l-qiyāmati ʾinna ʾallāha bikulli shayin ʿalīmun', 'Görmedin mi ki, Allah göklerde olanı da, yerde olanı da bilmektedir. Üç kişinin gizli konuşmasında dördüncüleri mutlaka O''dur. Beş kişinin gizli konuşmasında altıncıları mutlaka O''dur. Bundan ne az ne de çok olursa olsun, onlar nerede olurlarsa olsunlar O mutlaka onlarla beraberdir. Sonra kıyamet günü onlara yaptıklarını haber verecektir. Şüphesiz Allah her şeyi bilendir.'),
(58, 8, 28, 543, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا فَبِئْسَ ٱلْمَصِيرُ', 'ʾalam tara ʾilā alladhīna nūhū ʿani n-najwā thumma yaʿūdūna limā nūhū ʿanhu wa yatanājawna bil-ʾithmi wal-ʿudwāni wa maʿṣiyati r-rasūli wa ʾidhā jāʾūka ḥayyawk bima lam yuḥayyika bihi llāhu wa yaqūlūna fī ʾanfusihim lawlā yuʿadhdhibunā llāhu bimā naqūlu ḥasbuhum jahannamu yaṣlawnahā fabiʾsa l-maṣīru', 'Onların gizli konuşmalarından men edildikleri halde sonra yine o yasaklandıkları şeye dönüp birbirleriyle günah, düşmanlık ve Peygamber''e isyan hususunda gizli konuşmaya devam ettiklerini görmedin mi? Ve sana geldiklerinde, Allah''ın selamlamadığı bir tarzda selam verirler. Ve kendi nefislerinde: "Bu dediğimiz yüzünden Allah bize azap etmeli değil miydi?" derler. Onlara cehennem yeter. Oraya gireceklerdir. Ne kötü bir dönüş yeridir o!'),
(58, 9, 28, 543, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'yā ʾayyuhā llaḏīna ʾāmanū iḏā tanājaytum falā tanājaw bil-ʾiṯmi wal-ʿudwāni wa-maʿṣiyati r-rasūli wa-tanājaw bil-birri wat-taqwā wat-taqū llāha llaḏī ʾilayhi tuḥšarūna', 'Ey iman edenler! Birbiriyle gizli konuşacağınız zaman, günah, düşmanlık ve peygambere isyan konularında gizli konuşmayın. İyilik ve takva (Allah''a karşı gelmekten sakınma) konularında gizli konuşun. Huzuruna toplanacağınız Allah''a karşı gelmekten sakının.'),
(58, 10, 28, 543, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'ʾinnama ʾn-najwā min ʾš-šayṭāni liyaḥzuna ʾlladhīna ʾāmanū wa laysa biḍārr পদার্থেরim šayʾan ʾilla biʾidhni ʾllāhi wa ʿalā ʾllāhi falyatawakkali ʾl-muʾminūna', 'Gizli konuşmalar ancak şeytandandır; bu, iman edenleri üzmek içindir. Oysa Allah''ın izni olmadıkça müminlere hiçbir zarar verecek değildir. Müminler yalnız Allah''a güvenip dayansınlar.'),
(58, 11, 28, 543, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'yā ayyuhā l-ladhīna āmanū idhā qīla lakum tafassaḥū fī l-majālisi fāfsaḥū yafsaḥi l-lāhu lakum wa idhā qīla nshuzū fa-nshuzū yarfaʿi l-lāhu l-ladhīna āmanū minkum wa-lladhīna ūtū l-ʿilma darajātin wa-llāhu bimā taʿmalūna khabīrun', 'Ey iman edenler! Size meclislerde ''yer açın'' denildiği zaman, yer açın. Allah da size genişlik versin. Ve ''kalkın'' denildiği zaman da kalkın. Allah içinizden iman edenleri ve kendilerine ilim verilenleri derecelerle yükseltsin. Allah yaptıklarınızdan haberdardır.'),
(58, 12, 28, 544, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'yā ayyuhā alladhīna āmanū idhā nājaytumū ar-rasūla faqaddimū bayna yaday najwākum ṣadaqatan dhālika khayrun lakum wa aṭharu fa in lam tajidū fa inna Allāha ghafūrun raḥīmun', 'Ey iman edenler! Resûlle gizli konuşacağınız zaman, gizli konuşmanızdan önce bir sadaka verin. Bu sizin için daha hayırlı ve daha temizdir. Şayet (sadaka verecek bir şey) bulamazsanız, o zaman şüphe yok ki Allah çok bağışlayıcı, çok merhamet edicidir.'),
(58, 13, 28, 544, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَٰتٍ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ʾaʾašfaqtum ʾan tuqaddimū bayna yaday najwākum ṣadaqātin faʾiḏ lam tafʿalū watāba ʾallāhu ʿalaykum faʾaqīmū aṣ-ṣalāta waʾātū az-zakāta waʾaṭīʿū ʾallāha wa-rasūlahū wa-ʾallāhu ḫabīrum bimā taʿmalūna', 'Gizli konuşmalarınızdan önce sadakalar vermenizden çekindiniz mi? Mademki böyle yaptınız ve Allah da sizin tevbenizi kabul etti, artık namazı dosdoğru kılın, zekâtı verin, Allah''a ve Resûlü''ne itaat edin. Allah, yaptıklarınızdan haberdardır.'),
(58, 14, 28, 544, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', 'ʾalam tara ʾilā alladhīna tawallaw qawman ghaḍiba allāhu ʿalayhim mā hum minkum walā minhum wayaḥlifūna ʿalā l-kadhibi wahum yaʿlamūn', 'Allah''ın kendilerine gazap ettiği bir topluluğu dost edinenleri görmedin mi? Onlar ne sizdendirler ne de onlardan. Bile bile yalan yere yemin ediyorlar.'),
(58, 15, 28, 544, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'aʿadda ʾallāhu lahum ʿadhāban shadīdan ʾinnahum sāʾa mā kānū yaʿmalūn', 'Allah onlara şiddetli bir azap hazırlamıştır. Gerçekten onlar yapmakta oldukları şey ne kötüdür!'),
(58, 16, 28, 544, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ', 'ittakhadhū ʾaymānahum junnatan faṣaddū ʿan sabīli ʾllāhi falahum ʿadhābun muhīnun', 'Onlar, yeminlerini kalkan edinindiler de Allah''ın yolundan alıkoydular. Artık onlar için alçaltıcı bir azap vardır.'),
(58, 17, 28, 544, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'lan tuğniye ''anhum emvâluhum ve lâ evlâduhum minallâhi şey''â ulâ''ike ashâbu-nnâri hum fîhâ hâlidûn(e)', 'Onların malları ve evlatları, Allah''a karşı kendilerine hiçbir fayda sağlamaz. İşte onlar cehennem ehlidirler; onlar orada ebedî kalırlar.'),
(58, 18, 28, 544, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ أَلَآ إِنَّهُمْ هُمُ ٱلْكَٰذِبُونَ', 'yawma yabʿathuhumu ʾllāhu jamīʿan fayaḥlifūna la-hū kamā yaḥlifūna lakum wa-yaḥsabūna ʾannahum ʿalā shayʾin ʾalā ʾinnahum humu l-kādhibūna', 'Allah''ın hepsini yeniden dirilteceği o gün, size yemin ettikleri gibi O''na da yemin edecekler ve kendilerinin bir şey (doğru bir yol) üzere olduklarını sanacaklardır. Haberiniz olsun ki, onlar yalancının ta kendileridir.'),
(58, 19, 28, 544, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ أُو۟لَٰٓئِكَ حِزْبُ ٱلشَّيْطَٰنِ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَٰنِ هُمُ ٱلْخَٰسِرُونَ', 'istaḥvaḏa ʿalayhimu ʾš-šayṭānu faʾansāhum ḏikra ʾllāhi ʾulāʾika ḥizbu ʾš-šayṭāni ʾalā ʾinna ḥizba ʾš-šayṭāni humu ʾl-ḥāsirūna', 'Onlara şeytan galebe çaldı da Allah''ı anmayı unutturdu. İşte onlar şeytanın hizbi (taraftarları)dır. Uyanın! Şeytanın hizbi olanlar elbette ziyana uğrayanlardır.'),
(58, 20, 28, 544, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ فِى ٱلْأَذَلِّينَ', 'ʾinna lladhīna yuḥāddūna llāha wa rasūlahū ʾulāʾika fī l-ʾadhallīna', 'Şüphesiz Allah''a ve Resûlüne düşmanlık edenler var ya, işte onlar en aşağı kimseler arasındadır.'),
(58, 21, 28, 544, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', 'kataba ʾallāhu laʾaḡlibanna ʾanā wa rusulī ʾinna ʾallāha qawiyyun ʿazīzun', 'Allah, ''Ben ve elçilerim mutlaka galip geleceğiz'' diye yazmıştır. Şüphesiz Allah, çok güçlüdür, mutlak güç sahibidir.'),
(58, 22, 28, 545, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', 'lā tajidu qawman yuʾminūna bi-llāhi wa-l-yawmi l-ʾākhiri yuwāddūna man ḥādda llāha wa-rasūlahū wa-law kānū ʾābāʾahum ʾaw ʾabnāʾahum ʾaw ʾikhwānahum ʾaw ʿashīratahum ʾulāʾika kataba fī qulūbihimu l-ʾīmāna wa-ʾayyada-hum bi-rūḥin minhu wa-yudkhilu-hum jannātin tajrī min taḥtihā l-ʾanhāru khālidīna fīhā raḍiya llāhu ʿanhum wa-raḍū ʿanhu ʾulāʾika ḥizbu llāhi ʾalā ʾinna ḥizba llāhi humu l-mufliḥūna', 'Allah''a ve ahiret gününe iman eden bir kavmin, Allah''a ve Resûlü''ne düşman olan kimselere sevgi beslediklerini bulamazsın. Onlar, babaları, oğulları, kardeşleri veya akrabaları olsalar bile. İşte onların kalplerine Allah, iman yazmış ve onları kendi tarafından bir ruh ile desteklemiştir. Onları, altlarından ırmaklar akan, içinde ebedi kalacakları cennetlere sokacaktır. Allah onlardan razı olmuş, onlar da O''ndan razı olmuşlardır. İşte onlar, Allah''ın taraftarlarıdır. İyi bilin ki, en iyi kurtuluşa erenler de Allah''ın taraftarlarıdır.'),
(59, 1, 28, 545, 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'sabbaha lillahi ma fi s-samawati wa ma fi l-ardi wa huwa l-ʿazizu l-ḥakimu', 'Göklerde ve yerde ne varsa Allah''ı tesbih eder. O, Azîz''dir, Hakîm''dir.'),
(59, 2, 28, 545, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ مِن دِيَٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَٰٓأُو۟لِى ٱلْأَبْصَٰرِ', 'huwa alladhī ʾakhraja alladhīna kafarū min ʾahli lkitābi min diyārihim liʾawwali lḥashri mā ẓanantumu ʾan yakhrujū waẓannū ʾannahum māniʿatuhum ḥuṣūnuhum mina llāhi faʾatāhumu llāhu min ḥaythu lam yaḥtasibū waqaḏafa fī qulūbihimu rruʿba yukhribūna buyūtahum biʾaydīhim waʾaydī lmuʾminīna faʿtabirū yāʾūlī lʾabṣāri', 'Kitap ehlinden inkâr edenleri, ilk sürgünde yurtlarından çıkaran O''dur. Sizin, çıkacaklarını hiç sanmadığınızı, onların da kalelerinin kendilerini Allah''tan koruyacağını sandıklarını sanmıştınız. Oysa Allah, onların hiç beklemediği yerden geldi ve kalplerine korku saldı. Kendi elleriyle ve müminlerin elleriyle evlerini yıkıyorlardı. Ey basiret sahipleri, ibret alın!'),
(59, 3, 28, 545, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابُ ٱلنَّارِ', 'wa-lawlā an kataba ʾallāhu ʿalayhimu l-jalāʾa la-ʿaḏḏabahum fī d-dunyā wa-lahum fī l-ʾākhirati ʿaḏābu n-nār', 'Allah, üzerlerine sürgünü yazmamış olsaydı, onları dünyada (başka türlü) azaplandıracaktı ve onlar için ahirette de ateş azabı vardır.'),
(59, 4, 28, 546, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'dhālika bi-ʾannahum shāqqū ʾllāha wa-rasūlahū wa-man yushāqqi ʾllāha fa-ʾinna ʾllāha shadīdu ʾl-ʿiqābi', 'Bu böyledir, çünkü onlar Allah''a ve Resûlü''ne karşı geldiler. Kim Allah''a karşı gelirse, şüphesiz Allah''ın azabı çetindir.'),
(59, 5, 28, 546, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ', 'mā qaṭaʿtum min līnatin aw taraktumūhā qāʾimatan ʿalā ʾuṣūlihā fabiʾiḏni ḷḷāhi walīyuḵziya l-fāsiqīn', 'Onların üzerine indirdiğin herhangi bir hurma ağacını kesmeniz veya onu gövdesi üzerinde bıraktığınız haliniz, ancak Allah''ın izniyle (oldu) ve Allah''ın fasıkları perişan etmesi içindir.'),
(59, 6, 28, 546, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 've mā afāʾa llāhu ʿalā rasūlihi minhum femā awjaftum ʿalayhi min khaylin walā rikābin walākinna llāha yusalliṭu rusulahu ʿalā man yashāʾu wallāhu ʿalā kulli shayʾin qadīrun', 'Onlardan Allah''ın Resûlü''ne (ganimet olarak) verdikleri ise, sizin (o zaman) at sürmekle ve yaya gitmekle (elde edemeyeceğiniz şeylerdir); lâkin Allah, peygamberlerini dilediği kimselerin üzerine musallat kılar. Allah, her şeye hakkıyla gücü yetendir.'),
(59, 7, 28, 546, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'mā afāʾa llāhu ʿalā rasūlihi min ʾahli l-qurā falilāhi war-rasūli walidhī l-qurbā wal-yatāmā wal-masākīni wabni s-sabīli kay lā yakūna dawlatan bayna l-ʾaghnīʾi minkum wamā ʾātākumu r-rasūlu fakhudhūhu wamā nahākum ʿanhu fāntahū wattaqū llāha ʾinna llāha shadīdu l-ʿiqābi', 'Allah''ın, (fethedilmiş) kasabalar halkından Peygamberine (ganimet olarak) verdikleri, Allah''ın, Peygamberin, yakınlarının, yetimlerin, yoksulların ve yolda kalmışların olmak üzere, Allah''a, Peygambere, (Peygamberin) yakınlarına, yetimlere, yoksullara ve (parası bitip yolda kalmış) yolcuya aittir. Böylece mallar, içinizdeki zenginler arasında dönüp dolaşan bir devlet olmaz. Peygamber size ne verirse onu alın, sizi neden sakındırırsa ondan vazgeçin. Allah''a karşı gelmekten sakının. Şüphesiz Allah''ın azabı çetindir.'),
(59, 8, 28, 546, 'لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 'lil-fuqarāʾi l-muhājirīna l-ladhīna ukhrijū min diyārihim wa-amwālihim yabtaghūna faḍlan mina l-lāhi wa-riḍwānan wa-yanṣurūna l-lāha wa-rasūlahū ulāʾika humu ṣ-ṣādiqūna', 'Onlar, mallarından ve yurtlarından sürülmüş olup Allah''tan bir lütuf ve hoşnutluk isteyerek ve Allah''a ve Resûlü''ne yardım ederek yurtlarından çıkarılmış olan muhacir fakirlere de (verilir). İşte bunlar, doğru olanlardır.'),
(59, 9, 28, 546, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'wa-lladhīna tabawwaʾū ʾad-dāra wa-l-ʾīmāna min qablihim yuḥibbūna man hājara ʾilayhim wa-lā yajidūna fī ṣudūrihim ḥājatan mimmā ʾūtū wa-yuʾthirūna ʿalā ʾanfusihim wa-law kāna bihim khaṣāṣah wa-man yūqa ʾuḥḥa nafsihi fa-ʾulāʾika humu ʾl-mufliḥūn', 'Onlardan önce o yurda (Medine''ye) yerleşmiş ve iman etmiş olanlar (ise), kendilerine göç edip gelenleri severler. Onların göğüslerinde hiçbir ihtiyaç (haset, kıskançlık) bulamazlar. Kendileri ihtiyaç içinde olsalar bile, onları (göç edenleri) kendi nefislerine tercih ederler. Kim nefsindeki cimrilikten korunursa, işte onlar kurtuluşa erenlerdir.'),
(59, 10, 28, 547, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ', 'wa-lladhīna jāʾū min baʿdihim yaqūlūna rabbanā ʾighfir lanā wa-li-ʾikhwāninā alladhīna sabaqūnā bi-l-ʾīmāni wa-lā tajʿal fī qulūbinā ghillan li-lladhīna ʾāmanū rabbanā ʾinnaka raʾūfun raḥīmun', 'Onlardan sonra gelenler şöyle derler: Rabbimiz! Bizi ve bizden önce iman etmiş olan kardeşlerimizi bağışla. Kalplerimizde, iman edenlere karşı bir kin (veya düşmanlık) tutuşturma. Rabbimiz! Şüphesiz sen çok şefkatli, çok merhametlisin.'),
(59, 11, 28, 547, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 'ʾalam tara ʾilā alladhīna nāfaqū yaqūlūna li-ʾikhwānihimu alladhīna kafarū min ʾahli l-kitābi la-ʾin ʾukhrictum la-nakhrujanna maʿakum wa-lā nuṭīʿu fīkum ʾaḥadan ʾabadan wa-ʾin qūtiltum la-nanṣurannakum wa-llāhu yashhadu ʾinnahum la-kādhibūna', 'Onlar, kitap ehlinden küfreden kardeşlerine, "Andolsun, eğer siz çıkarılırsanız, biz de sizinle birlikte çıkarız ve sizin hakkınızda kimseye asla boyun eğmeyiz; eğer sizinle savaşılırsa, biz de size yardım ederiz" diyen münafıklara bakmadın mı? Allah, onların yalancı olduklarına şahitlik eder.'),
(59, 12, 28, 547, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَٰرَ ثُمَّ لَا يُنصَرُونَ', 'laʾin ʾuḫrijū lā yaḫrūjūna maʿahum wa laʾin qūtilū lā yanṣurūnahum wa laʾin naṣarūhum layuwallunna l-ʾadbāra ṯumma lā yunṣarūna', 'Eğer (münafıklar) çıkarılırsa, onlarla birlikte çıkmazlar. Eğer onlarla savaşılırsa, onlara yardım etmezler. Yardım etseler bile, arkalarını dönüp kaçarlar. Sonra onlara yardım da edilmez.'),
(59, 13, 28, 547, 'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'la''antum ''ashaddu rahbatan fee sudoorihim minallahi dhalika bi''annahum qawmun la yafqahoon', 'Sizin kalplerinizde duydukları korku, Allah''tan duydukları korkudan daha şiddetlidir. Bu böyledir, çünkü onlar akıl etmeyen bir kavimdir.'),
(59, 14, 28, 547, 'لَا يُقَٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', 'La yuqātilūnakum jamīʿan illā fī quran mutaḥaṣṣanatin aw min warāʾi judurin Baʾsuhum baynahum shadīdun Taḥsabuhum jamīʿan waqulūbuhum shattā Dhālika biʾannahum qawmun lā yaʿqilūna', 'Onlar, toplu halde sizinle savaşamazlar; ancak (savaşsalar bile) sıkılaştırılmış şehirlerde veya duvarlar arkasından (savaşırlar). Kendi aralarındaki çekişmeleri şiddetlidir. Sen onları derli toplu sanırsın, oysa kalpleri paramparçadır. Böyledir, çünkü onlar aklını kullanmayan bir topluluktur.'),
(59, 15, 28, 547, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'kamaṯali lläḏīna min qablihim qarīban ḏāqū wabāla amrihim wa lahum ʿaḏābun alīmun', 'Onlardan az önce, işlerinin kötü sonucunu tadanların durumu gibidir. Onlar için elem dolu bir azap da vardır.'),
(59, 16, 28, 547, 'كَمَثَلِ ٱلشَّيْطَٰنِ إِذْ قَالَ لِلْإِنسَٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'kamaṯali š-šayṭāni iḏ qāla lil-ʾinsāni ukfur falammā kafara qāla ʾinnī barīʾun minka ʾinnī ʾaḵāfu ʾllāha rabba l-ʿālamīna', 'Şeytanın durumu gibidir; insana, ''İnkâr et'' dediği zaman, inkâr etti. O zaman şeytan, ''Ben senden uzağım, ben âlemlerin Rabbi olan Allah''tan korkarım'' dedi.'),
(59, 17, 28, 548, 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَٰلِدَيْنِ فِيهَا وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 'fa-kāna ʿāqibatahumā annahumā fī n-nāri khālidīna fīhā wa-dhālika jazāʾu ẓ-ẓālimīn', 'Sonuç olarak ikisinin de akıbeti, içinde ebedî kalacakları ateş oldu. İşte bu, zalimlerin cezasıdır.'),
(59, 18, 28, 548, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'yāʾayyuhā lladhīna ʾāmanū ttaqū llāha waltanẓur nafsum mā qaddamat lighadin wa-ttaqū llāha ʾinna llāha khabīrum bimā taʿmalūna', 'Ey iman edenler! Allah’a karşı gelmekten sakının. Her nefis, yarın için ne hazırladığına bir bakmalı. Allah’a karşı gelmekten sakının. Şüphesiz Allah, yaptıklarınızdan haberdardır.'),
(59, 19, 28, 548, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ أُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'walā takūnū kālladhīna nasū llāha fa ansāhum anfusahum ulā''ika humu l-fāsiqūn', 'Allah''ı unutup da Allah''ın da kendilerine kendi nefislerini unutturduğu kimseler gibi olmayın. İşte onlar fasıkların ta kendileridir.'),
(59, 20, 28, 548, 'لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 'lā yastawī ʾaṣḥābu n-nāri wa ʾaṣḥābu l-jannati ʾaṣḥābu l-jannati humu l-fāʾizūna', 'Ateş ehli ile cennet ehli bir olmaz. Cennet ehli, işte onlar kurtuluşa erenlerdir.'),
(59, 21, 28, 548, 'لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', 'law anzalnā hādhā l-qurʾāna ʿalā jabalin larayta''hu khāshiʿan mutaṣaddiʿan min khashyati llāhi wa tilka l-ʾamthālu naḍribuhā lil-nāsi laʿallahum yatafakkarūna', 'Eğer biz bu Kur''an''ı bir dağa indirseydik, Allah korkusuyla onu baş eğmiş, çatlamış görürdün. İşte biz bu örnekleri insanlar için veriyoruz ki, düşünüp anlasınlar.'),
(59, 22, 28, 548, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 'huwa allāhu alladhī lā ilāha illā huwa ʿālimu l-ghaybi wa-sh-shahādati huwa r-raḥmānu r-raḥīmu', 'O, kendisinden başka hiçbir ilah olmayan Allah''tır. Gaybı da, şehadeti de bilen odur. O, Rahmân''dır, Rahîm''dir.'),
(59, 23, 28, 548, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 'huwa llāhu llaḏī lā ʾilāha ʾillā huwa l-maliku l-quddūsu s-salāmu l-muʾminu l-muhayminu l-ʿazīzu l-jabbāru l-mutakabbiru subḥāna llāhi ʿammā yušrikūn', 'O, kendisinden başka hiçbir ilah olmayan Allah''tır. O, mülkün gerçek sahibi, her türlü kusurdan uzak, esenlik veren, güvenlik veren, her şeyi gözeten, mutlak güç sahibi, zorlayıcı ve mütekebbirdir. Allah, onların ortak koştukları şeylerden münezzehtir.'),
(59, 24, 28, 548, 'هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'Huwa Allāhu al-Khāliqu al-Bāriʾu al-Muṣawwiru lahu al-asmāʾu al-ḥusnā yusabbiḥu lahu mā fī al-samāwāti wa-al-arḍi wa-huwa al-ʿazīzu al-ḥakīmu', 'O, yaratan, yoktan var eden, şekil veren Allah''tır. En güzel isimler O''nundur. Göklerde ve yerde olan her şey O''nu tesbih eder. O, mutlak güç sahibi, hüküm ve hikmet sahibidir.'),
(60, 1, 28, 549, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'yā ayyuhā alladhīna āmanū lā tattakhidhū ʿaduwwī wa ʿaduwwakum awliyāʾa tulqūna ilayhim bil-mawaddati wa qad kafarū bimā jāʾakum mina l-ḥaqqi yukhrijūna r-rasūla wa iyyākum an tuʾminū billāhi rabbikum in kuntum kharajtum jihādan fī sabīlī wa-btighāʾa marḍātī tusirrūna ilayhim bil-mawaddati wa anā aʿlamu bimā akhfaytum wa mā aʿlantum wa man yafʿalhu minkum fa qad ḍalla sawāʾa s-sabīli', 'Ey iman edenler! Benim de düşmanım sizin de düşmanınız olanları veliler edinmeyin. Onlara sevgiyle yaklaşırsınız, oysa onlar size gelmiş olan hakka küfretmişlerdir. Rabbiniz olan Allah''a inandığınız için Peygamberi ve sizi (yurtlarından) çıkarıyorlar. Eğer siz (sizden yana) benim yolumda cihad etmek ve rızamı kazanmak için (onlara karşı) çıkmışsanız (onları veli edinmeyin). Onlara gizlice sevgiyle yaklaşırsınız, oysa ben sizin gizlediğinizi de açıkladığınızı da bilirim. Kim bunu yaparsa, gerçekten yolun doğrusunu sapıtmış olur.'),
(60, 2, 28, 549, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', 'in yets̱aqafūkum yakūnū lakum aʿdāʾan wa yabsūṭū ilaykum aydiyahum wa alsinaʾatahum bi-s-sūʾi wa waddū law takfurūn', 'Eğer size (karşı) üstünlük sağlarlarsa, size düşman olurlar ve size ellerini ve dillerini kötülükle uzatırlar. Zaten sizin küfr etmenizi istemektedirler.'),
(60, 3, 28, 549, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ يَوْمَ ٱلْقِيَٰمَةِ يَفْصِلُ بَيْنَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'lan tanfaʿakum arḥāmunkuṃ wa lā ʾawlādukuṃ yawma l-qiyāmati yafṣilu baynakum wa-llāhu bimā taʿmalūna baṣīrun', 'Onlar, Kıyamet günü size hiçbir fayda sağlamazlar ne akrabalarınız ne de evlatlarınız. Allah, yaptıklarınızı görür.'),
(60, 4, 28, 549, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'kad kānet lakum uswatun ḥasanatun fī ibrāhīma wa alladhīna maʿahū idh qālū liqawmihim innā buraʾāʾu minkum wa mimmā taʿbudūna min dūni allāhi kafarnā bikum wa badā baynanā wa baynakumu al-ʿadāwatu wa al-baghḍāʾu abadan ḥattā tuʾminū bi allāhi waḥdahū illā qawla ibrāhīma liʾabīhi laʾastaghfiranna laka wa mā amliku laka mina allāhi min shayʾin rabbanā ʿalayka tawakkalnā wa ilayka anabnā wa ilayka al-maṣīru', 'İbrahim''de ve onunla beraber olanlarda sizin için güzel bir örnek vardır. Hani onlar kavimlerine şöyle demişlerdi: "Biz sizden ve Allah''tan başka taptıklarınızdan uzağız. Sizi inkâr ettik. Bizimle sizin aranızda, siz bir tek Allah''a iman edinceye kadar ebediyen düşmanlık ve nefret belirmiştir." Ancak İbrahim''in babasına söylediği şu söz hariç: "Senin için bağışlama dileyeceğim, ama Allah''tan sana gelecek hiçbir şeyi engellemeye gücüm yetmez." (Onlar şöyle dua etmişlerdi:) "Rabbimiz! Ancak Sana tevekkül ettik, Sana yöneldik ve dönüş ancak Sanadır."'),
(60, 5, 28, 549, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'Rabbana la tec''alna fitneten lillezine keferu Wağfir lena Rabbena Innaka ente''l-''Azizu''l-Hakim', 'Ey Rabbimiz! Bizi kâfirler için bir fitne (deneme, işkence, alay konusu) kılma. Bizi bağışla ey Rabbimiz! Şüphesiz Sen, Azîz (mutlak güç sahibi) ve Hakîm (hüküm ve hikmet sahibi) olan Sensin.'),
(60, 6, 28, 550, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'leḳad kâne leküm fîhim üsvetün ḥasenetün limen kâne yercüva-llâhe vel-yevme-l-âḫir vemen yetevellâ feʾinne-llâhe hüve-l-ġaniyyü-l-ḥamîd', 'Andolsun ki, Allah''ı ve ahiret gününü umanlar için onlarda güzel bir örnek vardır. Kim yüz çevirirse, şüphesiz Allah, evet O, Ganî (hiçbir şeye muhtaç olmayan) ve Hamîd''dir (övülmeye layık olandır).'),
(60, 7, 28, 550, 'عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً وَٱللَّهُ قَدِيرٌ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'ʿasā llāhu an yajʿala baynakum wa-bayna lladhīna ʿādoytum minhum mawaddatan wa-llāhu qadīrun wa-llāhu ghafūrun raḥīmun', 'Umulur ki Allah, sizinle onlardan düşman olduklarınız arasına bir sevgi koyar. Allah kadirdir ve Allah Gafur''dur, Rahîm''dir.'),
(60, 8, 28, 550, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'lā yan-hā-kumullāhu ʿanil-laḏīna lam yuqātilūkum fid-dīni wa lam yuḫrijūkum min diyāri-kum an tabarrūhum wa tuqsiṭū ilaihim ʾinna-llāha yuḥibbul-muqsiṭīn', 'Allah, din hususunda sizinle savaşmamış ve sizi yurtlarınızdan çıkarmamış olanlara iyilik etmenizi ve onlara adil davranmanızı yasaklamaz. Şüphesiz Allah, adil davrananları sever.'),
(60, 9, 28, 550, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَٰرِكُمْ وَظَٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ وَمَن يَتَوَلَّهُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'ʾinnemā yenhākumu ʾllāhu ʿani lladhīna qātalūkum fī d-dīni wa ʾakhrajūkum min diyārikum wa ẓāharū ʿalā ʾikhrājikum ʾan tawallūhum wa man yatawallahum fa ʾulāʾika humu ẓ-ẓālimūna', 'Allah sizi ancak, din konusunda sizinle savaşmış, sizi yurtlarınızdan çıkarmış ve çıkarılmanız için (başkalarına) arka çıkmış kimselere dostluk (velayet) etmekten men eder. Kim onlara dost olursa, işte onlar zalimlerdir.'),
(60, 10, 28, 550, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَٰتُ مُهَٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ وَءَاتُوهُم مَّآ أَنفَقُوا۟ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ذَٰلِكُمْ حُكْمُ ٱللَّهِ يَحْكُمُ بَيْنَكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'yā ayyuhā lladhīna āmānū idhā jāʾakumul muʾminātu muhājirātin fāmtahihūnna Allāhu aʿlamu biʾīmānihinna fa-in ʿalimtumūhunna muʾminātin falā tarjiʿūhunna ilā l-kuffāri lā hunna ḥillun lahum walā hum yaḥillūna lahunna wa ātūhum mā anfaqū walā junāḥa ʿalaykum an tankiḥūhunna idhā ātaytumūhunna ʾujūrahunna walā tumsikū biʿiṣami l-kawāfiri wasʾalū mā anfaqtum wal-yasʾalū mā anfaqū dhālikum ḥukmu llāhi yaḥkumu baynakum wallāhu ʿalīmun ḥakīmun', 'Ey iman edenler! İman etmiş kadınlar hicret ederek size geldiklerinde, onları imtihan edin. Allah onların imanlarını daha iyi bilir. Eğer onların iman etmiş olduklarını öğrenirseniz, artık onları kâfirlere döndürmeyin. Bu kadınlar onlara helâl değildir, onlar da bu kadınlara helâl değildir. Harcadıklarını kendilerine verin. Hanım düşürme durumunda, ücretlerini (mehirlerini) verdiğiniz takdirde onlarla evlenmenizde size bir günah yoktur. Kâfir kadınları nikâhınızda tutmayın. Harcadığınızı isteyin. Onlar da harcadıklarını istesinler. Bu, Allah’ın hükmüdür. Sizin aranızda O hükmeder. Allah, bilendir, hikmet sahibidir.'),
(60, 11, 28, 550, 'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 'wa-in fātakum shay''un min azwājikum ilā l-kuffāri fa-ʿāqabtum fa-ʾātū l-ladhīna dhahabat azwājuhum mithla mā ʾanfaqū wa-ttaqū l-laha lladhī ʾantum bihi muʾminūna', 'Eğer hanımlarınızdan bir kısmı size gelmeyip (o sırada) kâfirlere katılmış olursa, (sonradan) harp ganimeti elde ederseniz, hanımları gitmiş olanlara, harcadıkları kadar (onların kâfirlere verdiklerinin bedelini) ödeyin. Ve iman ettiğiniz Allah’tan korkun.'),
(60, 12, 28, 551, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'yā ayyuhā n-nabiyyu iḏā jāʾaka l-muʾminātu yubāyiʿnaka ʿalā ʾan lā yušrikna bi-llāhi šayʾan wa lā yasriqna wa lā yaznīna wa lā yaqtulna ʾawlādahunna wa lā ʾatyīna bi-buhtānin yaftarīnahū bayna ʾaydīhinna wa ʾarjulihinna wa lā yaʿṣīyanka fī maʿrūfin fabāyiʿhunna wa-stafgir lahunna llāha ʾinna llāha ġafūrun raḥīmun', 'Ey Peygamber! İman etmiş kadınlar sana gelip, Allah’a hiçbir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, elleriyle ayakları arasında bir bühtan uydurup getirmemek, hiçbir iyi işte sana isyan etmemek üzere bey''at (biat) ettiklerinde, onlarla bey''atleş. Onlar için Allah’tan mağfiret dile. Şüphesiz Allah, çok bağışlayıcıdır, çok merhamet edicidir.'),
(60, 13, 28, 551, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْءَاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَٰبِ ٱلْقُبُورِ', 'yā ayyuhā alladhīna āmanū lā tatawallaw qawman ghaḍiba allāhu ʿalayhim qad yaʾisū mina l-ʾākhirati kamā yaʾisa l-kuffāru min aṣḥābi l-qubūri', 'Ey iman edenler! Allah''ın kendilerine gazap ettiği bir topluluğa dostluk etmeyin. Onlar, ahiretten tıpkı kâfirlerin kabir halkından umut kestikleri gibi umut kesmişlerdir.'),
(61, 1, 28, 551, 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'sabbaha lillahi ma fis-semavati wa ma fil-ard wa huwal-''azizul-hakim', 'Göklerde ve yerde ne varsa hepsi Allah''ı tesbih eder. O, Azîz''dir, Hakîm''dir.'),
(61, 2, 28, 551, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 'yā ayyuhā alladhīna āmanū lima taqūlūna mā lā tafʿalūna', 'Ey iman edenler! Yapmayacağınız şeyleri neden söylüyorsunuz?'),
(61, 3, 28, 551, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 'kabura maqtan ʿinda llāhi an taqūlū mā lā tafʿalūn', 'Ey iman edenler! Yapmayacağınız şeyleri söylemeniz Allah katında buğz (gerektiren en büyük çirkinlik) olarak(tur).'),
(61, 4, 28, 551, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَٰنٌ مَّرْصُوصٌ', 'ʾinna ʾallāha yuḥibbu l-ladhīna yuqātilūna fī sabīlihī ṣaffan kaʾannahum bunyānun marṣūṣun', 'Şüphesiz Allah, kendi yolunda, sanki birbirlerine kenetlenmiş bir duvar gibi saf tutarak savaşanları sever.'),
(61, 5, 28, 551, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'wa-ʾiḏ qāla mūsā li-qawmihi yā-qawmi lima tuʾḏūnani wa-qad taʿlamūna ʾannī rasūlu ʾallāhi ʾilaykum fa-lammā zāġū ʾazāġa ʾallāhu qulūbahum wa-ʾallāhu lā yahdī l-qawma l-fāsiqīn', 'Hani Mûsâ, kavmine demişti ki: "Ey kavmim! Neden bana eziyet ediyorsunuz? Oysa ben sizin Allah''ın elçisi olduğumu biliyorsunuz." Nihayet eğrilik yaptıklarında, Allah kalplerini (hak yoldan) eğriltti. Allah fasıklar topluluğunu doğru yola iletmez.'),
(61, 6, 28, 552, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَٰتِ قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ', 'wa-iḏ qāla ʿīsā bnu maryama yābanī isrāʾīla ʾinnī rasūlu ʾallāhi ʾilaykum muṣaddiqan limā bayna yadayya mina t-tawrāti wa-mubašširan birasūlin yaʾtī min baʿdī smuhu ʾaḥmadu falammā jāʾahum bil-bayyināti qālū hāḏā siḥrun mubīnun', 'Hani Meryem oğlu İsa da: "Ey İsrailoğulları! Ben, benden önce Tevrat''tan elinde olanı doğrulayıcı ve benden sonra gelecek ve adı Ahmed olacak bir peygamberi müjdeleyici olarak Allah''ın size (gönderdiği) elçisiyim" demişti. Sonra (İsa) onlara açık delillerle geldiğinde, dediler ki: "Bu, apaçık bir büyüdür."'),
(61, 7, 28, 552, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَٰمِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'Ve men azlemu mimmenifterâ alallâhil kezibe Ve huve yud''â ilel islâmi Vallâhu lâ yehdîl kavmez zâlimîn', 'İslâm''a davet edildiği halde Allah''a karşı yalan uydurandan daha zalim kim olabilir? Allah, zalimler topluluğunu hidayete erdirmez.'),
(61, 8, 28, 552, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'yurīdūna liyutfiʾū nūra ʾllāhi biʾafwāhihim wa-ʾllāhu mutimmu nūrihī wa-law kariha l-kāfirūna', 'Ağızlarıyla Allah''ın nurunu söndürmek istiyorlar. Halbuki Allah, kâfirler istemese de nurunu tamamlayacaktır.'),
(61, 9, 28, 552, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 'huwa lladhī arsala rasūlahū bil-hudā wa dīni l-ḥaqqi li yuẓhirahu ʿalā d-dīni kullahiī wa law kariha l-mušrikūna', 'O, Resûlü''nü hidayetle ve hak din ile, bütün dinlere üstün kılmak üzere gönderendir. Müşrikler istemese de.'),
(61, 10, 28, 552, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ', 'yā ayyuhā l-ladhīna āmanū hal adullukum ʿalā tijāratin tunjīkum min ʿadhābin alīmin', 'Ey iman edenler! Sizi elem dolu bir azaptan kurtaracak bir ticaret göstereyim mi?'),
(61, 11, 28, 552, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'tuʾminūna bi-llāhi wa-rasūlihī wa-tujāhidūna fī sabīli-llāhi bi-ʾamwālikum wa-ʾanfusikum ḏālikum ḫayrun lakum ʾin kuntum taʿlamūna', 'Allah''a ve Resûlü''ne inanır, mallarınızla ve canlarınızla Allah yolunda cihad edersiniz. Eğer bilirseniz, bu sizin için hayırlıdır.'),
(61, 12, 28, 552, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'yagfir lakum dhunubakum wa yudkhilukum jannatin tajri min tahtiha al-anharu wa masakina tayyibatan fi jannati ''adnin dhalika al-fawzu al-''adhimu', 'Rabbiniz için çalışıp çabalayınız ve O''nun mağfiretini umunuz. Şüphesiz Allah, çok bağışlayıcı, çok merhamet edicidir. Ve Rabbinizden bağışlanma dileyin, sonra O''na tövbe edin. Şüphesiz Rabbim çok merhametlidir, çok sevendir. Sonra size bir daha (böyle) bir toplulukla karşılaştığınızda, ayaklarınızın kaymaması için Allah''ı anın ve O''na dua edin! Kafirler ise ''Aldandık'' dediler. O, sizin günahlarınızı bağışlar ve sizi, altından ırmaklar akan cennetlere ve Adn cennetlerindeki güzel meskenlere koyar. İşte bu, en büyük kurtuluştur.'),
(61, 13, 28, 552, 'وَأُخْرَىٰ تُحِبُّونَهَا نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'wa ʾuḵrā tuḥibbūnahā naṣrun mina ʾllāhi wa fatḥun qarībun wa bašširi l-muʾminīna', 'Ve sevdiğiniz başka bir şey daha: Allah''tan bir yardım ve yakın bir fetih. (Ey Muhammed!) Müminlere müjde ver.'),
(61, 14, 28, 552, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّۦنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَٰهِرِينَ', 'yā ayyuhā l-ladhīna āmānū kūnū anṣāra llāhi kamā qāla ʿīsā bnu maryama lil-ḥawāriyyīna man anṣārī ilā llāhi qāla l-ḥawāriyyūna naḥnu anṣāru llāhi fa-āmanat ṭāʾifatun min banī isrāʾīla wa-kafarat ṭāʾifatun fa-ayyadnā lladhīna āmānū ʿalā ʿadūwwihim fa-aṣbaḥū ẓāhirīna', 'Ey iman edenler! Allah''a (yardımcı) olun! Tıpkı Meryem oğlu İsa''nın, "Allah''a (giden yolda) yardımcılarım kimlerdir?" dediği zaman, havarilerin, "Biz Allah''ın yardımcılarıyız!" dedikleri gibi. İsrailoğullarından bir taife iman etti, bir taife de inkar etti. Nihayet iman edenlere karşı düşmanlarına karşı yardım ettik, böylece üstün geldiler.'),
(62, 1, 28, 553, 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'yusabbihu lillahi ma fi as-samawati wa ma fi al-ardi al-maliki al-quddusi al-azizi al-hakim', 'Göklerde ve yerde ne varsa, mülk ve kudret sahibi, mukaddes, aziz ve hikmet sahibi olan Allah''ı tesbih eder.'),
(62, 2, 28, 553, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'huwa alladhī baʿatha fī l-ummiyyīna rasūlan minhum yatlū ʿalayhim ʾāyātihi wa-yuzakkīhim wa-yuʿallimuhumu l-kitāba wa-l-ḥikmata wa-ʾin kānū min qablu la-fī ḍalālin mubīnin', 'O, kendilerinden olan ve onlara ayetlerini okuyan, onları arındıran, onlara Kitap''ı ve hikmeti öğreten bir peygamberi ümmilere göndermiş olandır. Oysa onlar, daha önce apaçık bir sapıklık içinde idiler.'),
(62, 3, 28, 553, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'wa-ʾākhirīna minhum lammā yalḥaqū bihim wa-huwa l-ʿazīzu l-ḥakīmu', 'Ve onlardan henüz kendilerine katılmamış olanlara da (gönderilmiştir). O, mutlak güç sahibidir, hüküm ve hikmet sahibidir.'),
(62, 4, 28, 553, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'dhālika faḍlu llāhi yuʾtīhi man yashāʾu wa llāhu dhū l-faḍli l-ʿaẓīmi', 'İşte bu, Allah''ın lütfudur, dilediğine verir. Allah, büyük fazl sahibidir.'),
(62, 5, 28, 553, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'mathalu alladhīna ḥummilū al-tawrāta thumma lam yaḥmilūhā kamathali al-ḥimāri yaḥmilu asfāran biʾsa mathalu al-qawmi alladhīna kadhthabū bi-ʾāyāti Allāhi wa-Allāhu lā yahdī al-qawma al-ẓālimīna', 'Kendilerine Tevrat yükletilip de sonra onu (gereği gibi) taşımayanların durumu, ciltlerle kitap taşıyan merkep örneği gibidir. Allah''ın âyetlerini yalanlayan bir topluluğun örneği ne kötüdür! Allah, zalimler topluluğunu doğru yola iletmez.'),
(62, 6, 28, 553, 'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'Qul yā ayyuhā alladhīna hādū In zaʿamtum annakum awliyāʾu lillāhi min dūni an-nāsi Fa-tamannawu al-mawta In kuntum ṣādiqīna', 'De ki: "Ey Yahudi olanlar! Eğer (iddia ettiğiniz gibi) insanların değil de, Allah''ın dostları olduğunuzu sanıyorsanız, haydi ölümü temenni edin! (Bunu) eğer doğru sözlüler iseniz (yapın)."'),
(62, 7, 28, 553, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'wa-lā yatamannawnahu ʾabadan bimā qaddamat ʾaydīhim wa-llāhu ʿalīmun bi-ẓ-ẓālimīn', 'Onlar, kendi elleriyle hazırladıklarından dolayı ölümü asla dilemezler. Allah, zalimleri bilendir.'),
(62, 8, 28, 553, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'qul inna l-mawta lladhī tafirruna minhu faʾinnahu mulāqīkum thumma turaddūna ʾilā ʿālami l-ghaybi wa-sh-shahādati fayunabbiʾukum bimā kuntum taʿmalūna', 'De ki: "Kuşkusuz sizin kendisinden kaçtığınız ölüm, mutlaka sizinle buluşacaktır. Sonra da gizliyi ve aşikârı bilen (Allah''ın) huzuruna döndürüleceksiniz de O, size yapmakta olduklarınızı haber verecektir."'),
(62, 9, 28, 554, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'yā ayyuhā alladhīna āmanū idhā nūdiya lilṣṣalāti min yawmi l-jumuʿati fa-sʿaw ilā dhikri llāhi wa-dharū al-bayʿa dhālikum khayrun lakum in kuntum taʿlamūn', 'Ey iman edenler! Cuma günü namaz için çağrı yapıldığı zaman, hemen Allah''ı anmaya (cuma namazına) koşun ve alışverişi bırakın. Eğer bilirseniz, bu sizin için daha hayırlıdır.'),
(62, 10, 28, 554, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 'fa-iḏā quḍiyati ṣ-ṣalātu fa-ntashirū fī l-arḍi wa-btaghū min faḍli llāhi wa-ḏkurū llāha kaṯīran laʿallakum tufliḥūna', 'Namaz kılınıp bitince, yeryüzünde dağılıp Allah''ın lütfundan (nasibinizi) arayın. Allah''ı çok zikredin ki kurtuluşa eresiniz.'),
(62, 11, 28, 554, 'وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 'wa ʾiḏā raʾaw tiǧāratan ʾaw lahwan-infaddū ʾilayhā wa tarakūka qāʾiman qul mā ʿinda llāhi ḫayrun min al-lahwi wa min at-tiǧārah wa llāhu ḫayru r-rāziqīn', 'Onlar bir ticaret veya bir eğlence (oyun) gördükleri zaman, ona doğru dağılırlar ve seni ayakta bırakırlar. De ki: "Allah katında bulunan, eğlenceden de, ticaretten de daha hayırlıdır." Allah, rızık verenlerin en hayırlısıdır.'),
(63, 1, 28, 554, 'إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ', 'idhā jāʾaka l-munāfiqūna qālū nashhadu innaka la-rasūlu llāhi wa-llāhu yaʿlamu innaka la-rasūluhu wa-llāhu yashhadu inna l-munāfiqīna la-kādhibūna', 'Münafıklar sana geldiklerinde, ''Biz şehadet ederiz ki sen mutlaka Allah''ın Resûlü''sün'' derler. Allah senin kendi Resûlü olduğun bilmektedir. Ve Allah, münafıkların mutlaka yalancılar olduklarına şehadet eder.'),
(63, 2, 28, 554, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'ittakhadhū ʾaymānahum junnatan faṣaddū ʿan sabīli ʾllāhi ʾinnahum sāʾa mā kānū yaʿmalūn', 'Onlar, yeminlerini kalkan yaparak Allah''ın yolundan alıkoydular. Yaptıkları şey ne kötüdür!'),
(63, 3, 28, 554, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'dhālika bi-ʾannahum ʾāmanū thumma kafarū fa-ṭubiʿa ʿalā qulūbihim fa-hum lā yafqahūn', 'Bu, onların önce inanıp sonra inkâr etmeleri yüzündendir. Bu yüzden kalpleri mühürlenmiştir; artık onlar anlayamazlar.'),
(63, 4, 28, 554, 'وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', 'wa ʾiḏā raʾaytahum tuʿjibuka ʾajsāmuhum wa ʾin yaqūlū tasmeʿ liqawlihim kaʾannahum ḫušubun musannadatun yaḥsabūna kulla ṣayḥatin ʿalayhim humu l-ʿaduwwu fa-ḥḏarhum qātaluhumu ʾllāhu ʾannā yuʾfakūna', 'Onları gördüğünde, yapılarından/boylarından hoşlanırsın. Eğer konuşurlarsa, sözlerine kulak verirsin. Onlar sanki yaslanmış keresteler gibidirler. Her korkunç sesi kendi aleyhlerine sanırlar. Onlar düşmandırlar; Allah onları kahretsin! Nasıl da (haktan) çevriliyorlar!'),
(63, 5, 28, 555, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 'wa ʾiḏā qīla lahum taʿālaw yastaġfir lakum rasūlu ʾllāhi lawwaw ruʾūsahum waraʾaytahum yaṣudūna wahum mustakbirūna', 'Onlara: "Gelin, Allah Resûlü sizin için mağfiret dilesin" dendiği zaman, (alay ederek) başlarını çevirirler ve onların büyüklük taslayarak yüz çevirmekte olduklarını görürsün.'),
(63, 6, 28, 555, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'sawāʾun ʿalayhim ʾastagfarta lahum ʾam lam tastagfir lahum lan yagfira ʾllāhu lahum ʾinna ʾllāha lā yahdī l-qawma l-fāsiqīn', 'Onlara, bağışlanma dilesen de dilemesen de birdir. Allah, fasık kimseleri doğru yola iletmez.'),
(63, 7, 28, 555, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ', 'humu alladhīna yaqūlūna lā tunfiqū ʿalā man ʿinda rasūli Allāhi ḥattā yanfaḍḍū wa lillāhi khazāʾinu s-samāwāti wa l-arḍi wa lākinna l-munāfiqīna lā yafqahūna', 'Onlar, ''Allah''ın Resûlü yanındakilere hiçbir harcama yapmayın ki dağılıp gitsinler'' diyenlerdir. Oysa göklerin ve yerin hazineleri Allah''ındır, fakat münafıklar (bunu) anlamazlar.'),
(63, 8, 28, 555, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ', 'yaqūlūna laʾin rajaʿnā ʾilā l-madīnati layukhrijanna l-ʾaʿazzu minhā l-ʾaḏalla wa-li-llāhi l-ʿizzatu wa-li-rasūlihī wa-li-l-muʾminīna wa-lākinna l-munāfiqīna lā yaʿlamūna', 'Onlar, "Andolsun, Medine’ye dönecek olursak, içimizden güclü olan, zayıf olanı mutlaka oradan çıkaracaktır" derler. Oysa bütün güç ve izzet Allah’a, Resûlü’ne ve mü’minlere aittir. Ama münafıklar bunu bilmezler.'),
(63, 9, 28, 555, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'Yā ayyuhā alladhīna āmanū Lā tulhikum amwālukum walā awlādukum ʿan dhikri Allāh Wa man yafʿal dhālika fa-ʾulāʾika humu l-khāsirūn', 'Ey iman edenler! Mallarınız ve evlatlarınız sizi Allah''ı anmaktan alıkoymasın. Kim bunu yaparsa, işte onlar ziyana uğrayanların ta kendileridir.'),
(63, 10, 28, 555, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ', 'wa-ʾanfiqū min mā razaqnākum min qabli ʾan yaʾtiya ʾaḥadakumu l-mawtu fa-yaqūla rabbī lawlā ʾakhkhartanī ʾilā ʾajalin qarībin fa-ʾaṣṣaddaqa wa-ʾakun mina ṣ-ṣāliḥīn', 'Herhangi birinize ölüm gelip çatmadan ve "Rabbim! Beni yakın bir zamana kadar geciktirsen de tasaddukta bulunsam ve salihlerden olsam" demeden önce, sizi rızıklandırdığımız şeylerden (infak edip) harcayın.'),
(63, 11, 28, 555, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'wa-lan yu''akhkhira allāhu nafsan idhā jā''a ajaluhā wa-allāhu khabīrun bimā taʿmalūn', 'Allah, eceli geldiği zaman hiçbir kimseyi asla ertelemez. Allah, yapmakta olduklarınızdan haberdardır.'),
(64, 1, 28, 556, 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'yusabbihu lillahi ma fis-semavati ve ma fil-ardi lahul-mulku ve lahul-hamdu ve huve ''ala kulli sheyin kadirun', 'Göklerde ve yerde ne varsa hepsi Allah''ı tesbih eder. Mülk O''nundur, hamd O''na mahsustur. O her şeye hakkıyla kadirdir.'),
(64, 2, 28, 556, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'huwa alladhī khalaqakum faminkum kāfirun waminkum muʾminun wallāhu bimā taʿmalūna baṣīrun', 'O, sizi yaratan Allah''tır. Böyle iken kiminiz inanır, kiminiz inanmaz. Allah, yaptıklarınızı hakkıyla görmektedir.'),
(64, 3, 28, 556, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَإِلَيْهِ ٱلْمَصِيرُ', 'x̱alaqa s-samāwāti wa-l-arḍa bi-l-ḥaqqi wa ṣawwarakum fa-ʾaḥsana ṣuwarakum wa ʾilayhi l-maṣīru', 'Gökleri ve yeri hak ile yarattı. Size şekil verdi ve şeklinizi güzel kıldı. Dönüş O''nadır.'),
(64, 4, 28, 556, 'يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'yaʿlamu mā fī s-samāwāti wa-l-ʾarḍi wa yaʿlamu mā tusirrūna wa mā tuʿlinūna wa-llāhu ʿalīmun bi-ḏāti ṣ-ṣudūri', 'Göklerde ve yerde ne varsa bilir. Sizin gizlediklerinizi de, açığa vurduklarınızı da bilir. Allah, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir.'),
(64, 5, 28, 556, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ʾelem yaʾtikum nabʾu lladhīna kafarū min qablu fad hāqū wabāla ʾamrihim walahum ʿadhābun ʾalīmun', 'Daha önce inkâr edenlerin haberi size gelmedi mi? Onlar, işlerinin (kötü) sonucunu tattılar ve onlara elem dolu bir azap da vardır.'),
(64, 6, 28, 556, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ وَّٱسْتَغْنَى ٱللَّهُ وَٱللَّهُ غَنِىٌّ حَمِيدٌ', 'dhālika biʾannahu kānat taʾtīhim rusuluhum bil-bayyināti fāqālū ʾabašarun yahdūnanā fakafarū watawallaw wastaghnā ʾallāhu wʾallāhu ghaniyyun ḥamīd', 'Bu böyledir, çünkü onlara peygamberleri açık delillerle gelmişti de, ''İnsan mı bize yol gösterecek?'' demişlerdi. Bunun üzerine inkâr ettiler ve Allah da onlardan müstağni davrandı. Allah zengindir, övgüye lâyıktır.'),
(64, 7, 28, 556, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'zaʿama alladhīna kafarū ʾan lan yubʿathū qul balā wa rabbī latubʿathunna thumma latunabbaʾunna bimā ʿamiltum wa dhālika ʿalā allāhi yasīr', 'İnkâr edenler, asla diriltilmeyeceklerini iddia ettiler. De ki: ''Hayır! Rabbime yemin ederim ki, mutlaka diriltileceksiniz. Sonra da yaptıklarınız mutlaka size haber verilecektir. Bu, Allah''a göre kolaydır.'''),
(64, 8, 28, 556, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'faʾāminū billāhi wa rasūlihi wa n-nūri l-ladhī ʾanzalnā wa llāhu bimā taʿmalūna khabīr', 'Bunun için siz de Allah''a, Resûlü''ne ve indirdiğimiz nûr''a iman edin. Allah yaptıklarınızdan haberdardır.'),
(64, 9, 28, 556, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'yawma yajmaʿukum liyawmi l-jamʿi dhālika yawmu t-taghābuni wa man yuʾminu bi-llāhi wa yaʿmalu ṣāliḥan yukaffir ʿanhu sayyiʾātihi wa yudkhilhu jannātin tajrī min taḥtihā l-anhāru khālidīna fīhā abadan dhālika l-fawzu l-ʿaẓīmu', 'O gün (Allah) sizi toplayacaktır; bu, toplanma (veya aldanma) günüdür. Kim Allah''a inanır ve salih amel işlerse, Allah onun kötülüklerini örter ve onu, içinde ebediyen kalacakları, altlarından ırmaklar akan cennetlere sokar. İşte bu, büyük kurtuluştur.'),
(64, 10, 28, 557, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا وَبِئْسَ ٱلْمَصِيرُ', 'wa-lladhīna kafarū wa-kadhdhabū bi-ʾāyātinā ʾulāʾika ʾaṣḥābu n-nāri khālidīna fīhā wa-biʾsa l-maṣīru', 'İnkâr edip âyetlerimizi yalanlayanlara gelince; işte onlar, içinde ebedî kalacakları cehennem ehlidir. Orası ne kötü bir dönüş yeridir!'),
(64, 11, 28, 557, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'mā aṣāba min muṣībatin illā bi-ʾidhnillāh wa man yuʾmin billāhi yahdi qalbahu wallāhu bikulli shayin ʿalīm', 'Allah''ın izni olmadıkça hiçbir musibet isabet etmez. Kim Allah''a inanırsa, Allah onun kalbini doğru yola iletir. Allah her şeyi hakkıyla bilendir.'),
(64, 12, 28, 557, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'waʾaṭīʿū ʾllāha waʾaṭīʿū ʾr-rasūla faʾin tawallaytum faʾinnamā ʿalā rasūlinā ʾl-balāġu ʾl-mubīnu', 'Allah''a itaat edin, Peygamber''e de itaat edin. Eğer yüz çevirirseniz, bilin ki Elçimizin görevi apaçık tebliğden başka bir şey değildir.'),
(64, 13, 28, 557, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'Allāhu lā ilāha illā huw Wa ʿalā Allāhi falyatawakkali l-muʾminūn', 'Allah, O''ndan başka ilah yoktur. Ve müminler yalnızca Allah''a güvenip dayanmalıdır.'),
(64, 14, 28, 557, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'yā ayyuhā alladhīna āmanū inna min azwājikum wa awlādikum ʿaduwwan lakum fa-ḥdhārūhum wa in taʿfū wa taṣfaḥū wa taghfirū fa-inna Allāha ghafūrun raḥīm', 'Ey iman edenler! Şüphesiz eşlerinizden ve çocuklarınızdan kimileri size düşmandır. Öyleyse onlardan sakının. Eğer affeder, kusurlarını görmezden gelir ve bağışlarsanız, bilin ki Allah çok bağışlayandır, çok merhamet edendir.'),
(64, 15, 28, 557, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'ʾinnemā ʾamwālukum wa-ʾawlādukum fitnah wa-ʾllāhu ʿindahu ʾajrun ʿaẓīm', 'Mallarınız ve evlatlarınız ancak bir imtihandır. Allah ise, O''nun katında büyük mükâfat vardır.'),
(64, 16, 28, 557, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'fattaqūllāha māstaṭaʿtum wāsmʿū waʾaṭīʿū wanfiqu khayran liʾanfusikum waman yūqa shuḥḥa nafsihi faʾūlāʾika humul mufliḥūn', 'O halde gücünüz yettiğince Allah''tan korkup sakının, dinleyin, itaat edin ve kendi iyiliğiniz için harcayın. Kim nefsinin cimriliğinden korunursa, işte onlar kurtuluşa erenlerdir.'),
(64, 17, 28, 557, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ شَكُورٌ حَلِيمٌ', 'in tuḳriḍū allāha ḳarḍan ḥasanan yuḍāʿifhu lekum ve yagfir lekum ve allāhu şekūrun ḥalīmun', 'Eğer Allah''a güzel bir borç verirseniz, onu sizin için kat kat artırır ve günahlarınızı bağışlar. Allah çok mükâfat veren ve halimdir.'),
(64, 18, 28, 557, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ʿālimu l-ghaybi wa-sh-shahādati l-ʿazīzu l-ḥakīmu', 'O, gaybı da, şehadeti de bilen, mutlak güç sahibi, hüküm ve hikmet sahibi olandır.'),
(65, 1, 28, 558, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَتِلْكَ حُدُودُ ٱللَّهِ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا', 'yā ayyuhā n-nabiyyu iḏā ṭallaqtumu n-nisāʾa fa-ṭalliqūhunna li-ʿiddatihinna wa-aḥṣū l-ʿiddata wa-ttaqū llāha rabbakum lā tuḫrijūhunna min buyūtihinna wa-lā yaḫrujna illā an yaʾtīna bi-fāḥišatin mubayyinah wa-tilka ḥudūdu llāhi wa-man yataʿadda ḥudūda llāhi fa-qad ẓalama nafsahū lā tadrī laʿalla llāha yuḥdiṯu baʿda ḏālika amran', 'Ey Peygamber! Kadınları boşadığınız zaman, onları iddetlerine sayarak boşayın ve sayıyı tutun. Rabbiniz Allah''tan korkun. Onları evlerinden çıkarmayın, kendileri de çıkmasınlar. Ancak apaçık bir hayasızlık yapmaları hariç. Bunlar Allah''ın sınırlarıdır. Kim Allah''ın sınırlarını aşarsa, gerçekten kendi nefsine zulmetmiş olur. Bilemezsin, olur ki Allah bundan sonra bir durum (yeni bir emir) yaratır.'),
(65, 2, 28, 558, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا', 'faʾiḏā balagna ʾajalahunna faʾamsikūhunna bimaʿrūfin ʾaw fāriqūhunna bimaʿrūfin waʾašhidū ḏawāy ʿadlin minkum waʾaqīmū aššahādata lillāhi ḏālikum yūʿaẓu bihi man kāna yūʾminu billāhi wal-yawmi l-ʾāḫiri waman yattaqi l-lāha yajʿal lahu mahrājan', 'Onların bekleme süreleri sona erdiğinde, onları ya iyilikle tutun ya da iyilikle ayrılın. İçinizden iki adil şahit bulundurun ve şahitliği Allah için dosdoğru yapın. İşte bu, Allah''a ve ahiret gününe inananlara verilen öğüttür. Kim Allah''tan korkarsa, Allah ona bir çıkış yolu kılar.'),
(65, 3, 28, 558, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', 'wa yarzuqhu min ḥaythu lā yaḥtasibu wa man yatawakkal ʿalā Allāhi fa huwa ḥasbuhu ʾinna Allāha bāliġu ʾamrihī qad jaʿala Allāhu likulli šayʾin qadran', 'Ve onu beklemediği yerden rızıklandırır. Kim Allah''a tevekkül ederse, O ona yeter. Şüphesiz Allah, emrini yerine getirmeye kadirdir. Allah her şey için bir ölçü tayin etmiştir.'),
(65, 4, 28, 558, 'وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا', 'wa-allāʾī yaʾisna mina-l-maḥīḍi min nisāʾikum in irtabtum fa-ʿiddatuhunna thalāthatu ʾashhurin wa-allāʾī lam yaḥiḍna wa-ulātu-l-ʾaḥmāli ʾajaluhunna ʾan yaḍaʿna ḥamlahunna wa-man yattaqi-llāha yajʿal lahu min ʾamrihī yusran', 'Adet görmekten kesilmiş kadınlarınızın iddeti hususunda şüphe ederseniz, onların iddeti üç aydır. Hamile olanların ise, doğum yapıncaya kadar iddetleri devam eder. Kim Allah''tan korkarsa, Allah ona işinde bir kolaylık verir.'),
(65, 5, 28, 558, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 'dhālika amru llāhi anzalahū ʾilaykum wa man yattaqi llāha yukaffir ʿanhu sayyiʾātihi wa yuʿẓim lahu ʾajran', 'Bu, Allah''ın size indirdiği emridir. Kim Allah''a karşı takva sahibi olursa, Allah onun kabahatlerini örter ve ona büyük bir mükâfat verir.'),
(65, 6, 28, 559, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 'askınūhunna min ḥaythu sskantum min wujdikum wa lā tuḍārrūhunna li tuḍayyiqū ʿalayhinna wa in kunna ūlāti ḥamlin fa-anfiqū ʿalayhinna ḥattā yaḍaʿna ḥamlahunna fa-in arḍaʿna lakum fa-ātūhunna ucūrahunna wa-tmirū baynakum bi-maʿrūfin wa in taʿāsartum fa-sa-turḍiʿu lahu ʾukhrā', 'Onları, imkan ve genişliğinize göre, oturduğunuz yerin bir kısmında oturtun. Onları sıkıntıya sokmak için kendilerine zarar vermeye kalkışmayın. Eğer hamile iseler, doğum yapıncaya kadar nafakalarını verin. Eğer sizin için (çocuğu) emzirirlerse, onlara ücretlerini verin ve aranızda örfe uygun bir şekilde anlaşın. Eğer güçlük çıkarırsanız, başka bir kadın onun için emzirecektir.'),
(65, 7, 28, 559, 'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا', 'liyunfıq dhuu sa''atin min sa''atihii ve men qudira ''alayhi rizquhuu falyunfıq mimmaa aataahullahu laa yukallifullahuu nafsan illaa maa aataahaa sayaj''alullahuu ba''da ''usrin yusraa', 'Genislik imkanına sahip olan, genisligine gore nafaka versin. Rızkı daraltılan da Allah''ın kendisine verdigi kadar nafaka versin. Allah, bir kimseye ancak verdigi kadar yukler. Allah, guclukten sonra bir kolaylık yaratacaktır.'),
(65, 8, 28, 559, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَٰهَا عَذَابًا نُّكْرًا', 'wa kaʾayyin min qaryatin ʿatat ʿan ʾamri rabbihā wa rusulihī faḥāsabnāhā ḥisāban shadīdan wa ʿaḏḏabnāhā ʿaḏāban nukran', 'Ve nice kasabalar topluluğu Rablerinin ve O''nun elçilerinin emrinden dışarı çıktılar da Biz onları çetin bir hesaba çektik ve onlara acı bir azap ile azap ettik.'),
(65, 9, 28, 559, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا', 'faḏāqat wa bāla ʾamrihā wa kāna ʿāqibatu ʾamrihā ḫusran', 'Böylece işlerinin sonucunu tattu ve işlerinin sonu bir hüsran oldu.'),
(65, 10, 28, 559, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا', 'aʿadda ʾallāhu lahum ʿaḏāban šadīdan fāttaqū ʾallāha yā ʾūlī ʾalʾalbābi allaḏīna ʾāmanū qad ʾanzala ʾallāhu ʾilaykum ḏikran', 'Allah onlara şiddetli bir azap hazırlamıştır. Ey akıl sahipleri, Allah''tan korkun! Allah size bir zikir (Kur''an) indirmiştir.'),
(65, 11, 28, 559, 'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', 'rasūlan yatlū ʿalaykum ʾāyāti llāhi mubayyinātin liyuḫrija llaḏīna ʾāmanū wa-ʿamilū ṣ-ṣāliḥāti mina ẓ-ẓulumāti ʾilā n-nūri wa-man yuʾminu bi llāhi wa-yaʿmal ṣāliḥan yudḫilhu jannātin tajrī min taḥtihā l-ʾanhāru ḫālidīna fīhā ʾabadan qad ʾaḥsana llāhu lahu rızqan', 'Allah''ın size açıkça bildiren ayetlerini okuyan bir peygamberi (gönderdi); iman edip salih amel işleyenleri karanlıklardan aydınlığa çıkarmak için. Kim Allah''a inanır ve salih amel işlerse, Allah onu altından ırmaklar akan, içinde ebediyen kalacakları cennetlere sokar. Allah, gerçekten ona güzel bir rızık vermiştir.'),
(65, 12, 28, 559, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 'Allāhu alladhī khalaqa sabʿa samāwātin wa mina l-arḍi mithlahunna yatanazzalu l-amru baynahunna li-taʿlamū anna Allāha ʿalā kulli shayʾin qadīrun wa anna Allāha qad aḥāṭa bi-kulli shayʾin ʿilman', 'Allah, biri yedi gök olmak üzere yerin de benzerini yaratan, katman katman indirdiği emrin (göklerle yer) arasından inip çıkması için gökleri ve yeri yaratan, böylece sizin Allah''ın her şeye gücü yeten ve Allah''ın her şeyi ilmiyle kuşatmış olduğunu bilmeniz için (bütün bunları) yaratan Allah''tır.'),
(66, 1, 28, 560, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'yā ayyuhā an-nabiyyu lima tuḥarrimu mā aḥalla Allāhu laka tabtaġī marḍāta azwājika wa-Allāhu ġafūrun raḥīmun', 'Ey Peygamber! Hanımlarını hoşnut etmek istediğin halde, Allah''ın sana helâl kıldığı şeyi niçin kendine haram kılıyorsun? Allah Gafûr''dur, Rahîm''dir.'),
(66, 2, 28, 560, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ وَٱللَّهُ مَوْلَىٰكُمْ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'qad faraḍa allāhu lakum taḥillata aymānikum wa allāhu mawlākum wa huwa al-ʿalīmu al-ḥakīmu', 'Yeminlerinizin (yükümlülüğünü yerine getirme şeklini) Allah size farz kıldı. Allah sizin Mevlânızdır (dostunuz, yardımcınızdır). O, her şeyi bilen, hikmet sahibi olandır.'),
(66, 3, 28, 560, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', 'wa-ʾidh ʾasarra n-nabiyyu ʾilā baʿḍi ʾazwājihi ḥadīthan fa-lammā nabbaʾat bihi wa-ʾaẓharahu l-lāhu ʿalayhi ʿarrafa baʿḍahu wa-ʾaʿraḍa ʿan baʿḍin fa-lammā nabbaʾahā bihi qālat man ʾanbāʾaka hādhā qāla nabbaʾaniyya l-ʿalīmu l-khabīru', 'Hani Peygamber, hanımlarından birine gizlice bir söz söylemişti. Fakat o, bu sırrı başkasına açınca, Allah da bunu Peygamber’e bildirmişti. Peygamber, bu sırrın bir kısmını açığa vurdu, bir kısmından da yüz çevirdi. Peygamber durumu eşine bildirince, hanımı: “Bunu sana kim bildirdi?” dedi. Peygamber: “Bana her şeyi bilen, her şeyden haberdar olan Allah bildirdi” dedi.'),
(66, 4, 28, 560, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', 'in tatūbā ilā llāh faqad ṣaghat qulūbukumā we in taẓāharā ʿalayhi faʾinna llāha huwa mawlāhu we jibrīlu we ṣāliḥu l-muʾminīn we l-malāʾikatu baʿda dhālika ẓahīr', 'Eğer ikiniz de Allah''a tövbe ile dönerseniz, çünkü kalpleriniz (gerçeğe) eğilmiştir. Ve eğer ikiniz de ona karşı birbirinize arka çıkarsanız, bilin ki Allah onun Mevlâ''sıdır; Cebrail de, salih müminler de, ondan sonra melekler de yardımcıdır.'),
(66, 5, 28, 560, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَٰتٍ مُّؤْمِنَٰتٍ قَٰنِتَٰتٍ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍ سَٰٓئِحَٰتٍ ثَيِّبَٰتٍ وَأَبْكَارًا', 'ʿasā rabbuhū ʾin ṭallaqakunna ʾan yubdilahū ʾazwājan ḵayran minkunna muslimitin muʾminātin qānitātin tāʾibātin ʿābidātin sāʾiḥātin ṯayyibātin waʾabkāran', 'Olur ki, eğer o sizi boşamışsa, Rabbi ona sizden daha hayırlı, Müslümanlar, müminler, itaat edenler, tevbe edenler, ibadet edenler, oruç tutanlar, dul ve bâkir (olmak üzere) eşler ihsan eder.'),
(66, 6, 28, 560, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'yā ayyuhā alladhīna āmanū qū anfusakum wa ahliykum nāran wa qadūduhā an-nāsu wa al-ḥijāratu ʿalayhā malāʾikatun ghilāẓun shidādun lā yaʿṣūna Allāha mā amarahum wa yafʿalūna mā yuʾmarūna', 'Ey iman edenler! Kendinizi ve ailenizi, yakıtı insanlar ve taşlar olan ateşten koruyun. Ateşin başında, sert, kalın ağızlı melekler vardır. Onlar, Allah''ın kendilerine emrettiği hiçbir şeye karşı gelmezler ve emredildikleri şeyi yaparlar.'),
(66, 7, 28, 560, 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'yā ayyuhā alladhīna kafarū lā taʿtadhirū al-yawma innamā tujzawna mā kuntum taʿmalūna', 'Ey kâfirler! Bu gün özür dilemeyin. Siz ancak yaptıklarınızın karşılığını alacaksınız.'),
(66, 8, 28, 561, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'yā ayyuhā alladhīna āmanū tūbū ilā allāhi tawbatan naṣūḥan ʿasā rabbukum an yukaffira ʿankum sayyiʾātikum wa-yudkhilakum jannātin tajrī min taḥtihā al-anhāru yawma lā yukhzī allāhu an-nabiyya wa-alladhīna āmanū maʿahū nūruhum yasʿā bayna aydīhim wa-bi-aymānihim yaqūlūna rabbanā atminim lanā nūranā wa-ghfir lanā innaka ʿalā kulli shayʾin qadīrun', 'Ey iman edenler! Allâh’a samimi bir tevbe ile dönün. Umulur ki Rabbiniz sizin kötülüklerinizi örter ve sizi altlarından ırmaklar akan cennetlere sokar. O gün Allah, Peygamberi ve onunla birlikte iman edenleri utandırmayacaktır. Onların nuru önlerinde ve sağ yanlarında koşar. "Rabbimiz! Nurumuzu tamamla ve bizi bağışla! Şüphesiz Sen her şeye hakkıyla kadirsin" derler.'),
(66, 9, 28, 561, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'yā ayyuhā an-nabiyyu jāhid al-kuffāra wa-l-munāfiqīn wa-ghluẓ ʿalayhim wa maʾwāhum jahanam wa biʾsa al-maṣīr', 'Ey Peygamber! Kâfirlerle ve münafıklarla cihad et. Onlara karşı sert davran. Varacakları yer cehennemdir. Ne kötü bir varış yeridir o!'),
(66, 10, 28, 561, 'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', 'ḍaraba ʾllāhu maṯalan lillaḏīna kafarū ʾimraʾata nūḥin wa-ʾimraʾata lūṭin kānatā taḥta ʿabdayni min ʿibādinā ṣāliḥayni fakhānatāhumā falam yuğniyā ʿanhumā mina ʾllāhi šayʾan wa-qīla ʾdḵulā ʾn-nāra maʿa ʾd-dāḵilīna', 'Allah, inkâr edenlere Nuh''un ve Lût''un kadınlarını misal verdi. Onlar, kullarımızdan iki salih kulun (nikâhı) altında idiler. Onlara hıyanet ettiler. Bu yüzden (kocaları) onları Allah''tan (gelecek) hiçbir azaptan kurtaramadılar. Ve onlara: "Cehenneme girenlerle birlikte siz de girin!" denildi.'),
(66, 11, 28, 561, 'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'wa ḍaraba ʾallāhu maṯalan lillaḏīna ʾāmanū ʾimraʾata firʿawna ʾiḏ qālat rabbi ʾibni lī ʿindaka baytan fī l-jannati wa najjinī min firʿawna wa ʿamalihī wa najjinī mina l-qawmi ẓ-ẓālimīna', 'Ve Allah, iman edenler için Firavun''un karısını misal gösterdi. Hani o, ''Rabbim! Bana katında, cennette bir ev yap; ve beni Firavun''dan ve onun amellerinden kurtar ve beni o zalimler güruhundan kurtar!'' demişti.'),
(66, 12, 28, 561, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ', 'wa maryama-b-nata ʿimrāna-llatī ʾaḥṣanata farjahā fanafaknā fīhi min rūḥinā wa ṣaddaqat bi-kalimāti rabbihā wa-kutubihī wa kānat mina-l-qānitīn', 'Bir de İmran''ın kızı Meryem''i misal verir. O, ırzını korumuştu. Biz de ona ruhumuzdan üfledik. O, Rabbinin sözlerini ve kitaplarını tasdik etti ve gönülden itaat edenlerden oldu.'),
(67, 1, 29, 562, 'تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'tabāraka alladhī biyadihi almulku wahuwa ʿalā kulli shayʾin qadīrun', 'Mülk (hükümranlık) elinde bulunan yüceler yücesidir. O, her şeye hakkıyla kâdirdir.'),
(67, 2, 29, 562, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 'alladhī khalaqa l-mawta wa-l-ḥayāta liyabluwakum ayyukum aḥsanu ʿamalan wa-huwa l-ʿazīzu l-ġafūr', 'Ölümü ve hayatı, hangi davranış bakımından daha güzel olanınızı imtihan etmek için yaratan O''dur. O, mutlak güç sahibidir, çok bağışlayandır.'),
(67, 3, 29, 562, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ طِبَاقًا مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ', 'alladhī khalaqa sabʿa samāwātin ṭibāqan mā tarā fī khalqi r-raḥmāni min tafāwutin fa-rjiʿi l-baṣara hal tarā min fuṭūrin', 'O, birbiriyle ahenktar yedi göğü yaratmıştır. Rahman olan Allah''ın yarattığında hiçbir düzensizlik, uyumsuzluk görmezsin. Gözünü tekrar tekrar çevir bak! Hiçbir çatlak, kusur görüyor musun?'),
(67, 4, 29, 562, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ', 'thumma rjiʿi l-baṣara karratayni yanqalibi ilayka l-baṣaru khāsiʾan wa-huwa ḥasīrun', 'Sonra gözünü tekrar tekrar çevir de bak; (o) göz sana zelil ve bitkin bir halde dönüverir.'),
(67, 5, 29, 562, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًا لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', 'Ve lekad zeyyennâs semâed dunyâ bi mesâbîha ve cealnâhâ rucûmen liş şeyâtîn(liş şeyâtîni) ve a’tednâ lehum azâbes saîr(saîri)', 'Andolsun ki, en yakın göğü kandillerle süsledik ve onları şeytanlar için atış taneleri kıldık. Onlar için alevli ateş azabını hazırladık.'),
(67, 6, 29, 562, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ وَبِئْسَ ٱلْمَصِيرُ', 'wa-lilladhīna kafarū bi-rabbihim ʿadhābu jahannama wa-biʾsa l-maṣīru', 'Rablerini inkâr edenler için cehennem azabı vardır. Ne kötü bir varış yeridir o!'),
(67, 7, 29, 562, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ', 'iḏā ulqū fīhā samiʿū lahā šahīqan wa hiya tafūru', 'Onlar, cehenneme atıldıklarında, onun kaynamakta olduğunu işitirler.'),
(67, 8, 29, 562, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ', 'takādu tamayyazu mina l-ġayẓi kullamā ulqiya fīhā fawjun saʾalahum ḫazanatuhā ʾalam yaʾtikum naẓīrun', 'Neredeyse cehennem, öfkeden çatlayacak! Oraya her bir topluluk atıldıkça, oranın bekçileri onlara: "Size bir uyarıcı gelmedi mi?" diye sorarlar.'),
(67, 9, 29, 562, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ كَبِيرٍ', 'qālū balā qad jāʾanā nadhīrun fa-kadhabnā wa-qulnā mā nazzala ʾllāhu min šayʾin ʾin ʾantum ʾillā fī ḍalālin kabīrin', 'Onlar şöyle derler: "Evet, bize bir uyarıcı geldi, fakat biz yalanladık ve ''Allah hiçbir şey indirmemiştir. Siz ancak büyük bir sapıklık içindesiniz'' dedik."'),
(67, 10, 29, 562, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ', 'wa qālū law kunnā nasmaʿu aw naʿqilu mā kunnā fī ʾaṣḥābi s-saʿīri', 'Ve dediler ki: ''Eğer dinlemiş veya akıl etmiş olsaydık, şu çılgın ateşin yoldaşları arasında olmazdık.'''),
(67, 11, 29, 562, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَٰبِ ٱلسَّعِيرِ', 'faʿtarafū bidhanbihim fasuḥqan liʾaṣḥābi s-saʿīr', 'Böylece suçlarını itiraf ettiler. Cehennemlikler (Allah''ın rahmetinden) uzak olsun!'),
(67, 12, 29, 562, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'ʾinna lladhīna yakhshawna rabbahum bil-ghaybi lahum maghfiratun wa-ʾajrun kabīrun', 'Şüphesiz Rablerinden gayb ile (O''nu görmeden) korkanlar için bir bağışlanma ve büyük bir ecir vardır.'),
(67, 13, 29, 563, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'wa-ʾasirrū qawlakum ʾawi-jharū bihi ʾinnahu ʿalīmun bi-dhāti ṣ-ṣudūr', 'Sözlerinizi gizleyin veya açığa vurun, şüphesiz O, göğüslerde olanı bilendir.'),
(67, 14, 29, 563, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'ʾalā yaʿlamu man ḵalaqa wa-huwa l-laṭīfu l-ḵabīru', 'Yaratılışı O''nun bilmemesi olur mu? O, her şeyi en ince detayına kadar bilen, her şeyden haberdar olandır.'),
(67, 15, 29, 563, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ وَإِلَيْهِ ٱلنُّشُورُ', 'huwa lladhī jaʿala lakumu l-arḍa dhalūlan fa-mshū fī manākibihā wa-kulū min rizqihī wa-ilayhi n-nushūr', 'O, yeri sizin için ram (boyun eğen) kılan, onun üzerinde yürüyüp gezesiniz ve rızkından yiyesiniz diye orada (çeşitli) yollar var edendir. Sonunda hep O''nun huzuruna varacaksınız.'),
(67, 16, 29, 563, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 'ʾaʾamintum man fī s-samāʾi ʾan yakhsifa bikumu l-ʾarḍa faʾiḏā hiya tamūru', 'Göktekine güvendiniz de, yerin sizi yutmayacağını mı sandınız? Bir de baktınız ki, yer sallanıp duruyor.'),
(67, 17, 29, 563, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 'am amintum man fī s-samāʾi an yursila ʿalaykum ḥāṣibā fasataʿlamūna kayfa naḏīri', 'Yahut gökte olanın üzerinize taş yağdıran bir fırtına göndermeyeceğinden (emin mi) oldunuz? O zaman benim uyarıp korkutmammın nasıl olduğunu bileceksiniz.'),
(67, 18, 29, 563, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 'Ve lekad kezzebellezîne min kablihim Fe keyfe kâne nekîr', 'Andolsun ki onlardan öncekiler de yalanlamışlardı. Benim inkârım (azabım) nasıl oldu?'),
(67, 19, 29, 563, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍ وَيَقْبِضْنَ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', 'ʾawalam yaraw ʾilā ṭ-ṭayri fawqahum ṣāffātin wa yaqbiḍna mā yumsikuhunna ʾillā r-raḥmānu ʾinnahu bi-kulli shayʾin baṣīrun', 'Onlar, üstlerinde kanatlarını aça-kapaya (uçan) kuşları görmüyorlar mı? Onları ancak Rahman (olan Allah) tutuyor. Şüphesiz O, her şeyi hakkıyla bilendir.'),
(67, 20, 29, 563, 'أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ', 'amman hādhā alladhī huwa jundun lakum yansurukum min dūni r-raḥmāni ini l-kāfirūna illā fī ghurūrin', 'Yoksa, Rahman''dan başka size yardım edecek bir ordunuz mu var? Kafirler aldanmadan başka bir şey içinde değillerdir.'),
(67, 21, 29, 563, 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ', 'amman hādhā alladhī yarzuqukum in amsaka rizqahū bal lajjū fī ʿutuvvin wa-nufūr', 'Yahut rızkını kesiverirse, size kim o rızkı verebilir? Hayır, onlar azgınlık ve nefret içinde direnmektedirler.'),
(67, 22, 29, 563, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'Afemen yemşī mukibben ‘alā vechihi ehdā emmen yemşī seviy-yen ‘alā ṣirāṭin musteqīm', 'Yüzüstü kapanarak yürüyen mi daha doğru yoldadır, yoksa dosdoğru yürüyen mi?'),
(67, 23, 29, 563, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'Qul huwa alladhī ʾanshaʾakum wajaʿala lakumu s-samʿa wal-ʾabṣāra wal-ʾafʾidata qalīlan mā tashkurūna', 'De ki: "O, sizi yaratan ve size kulaklar, gözler ve kalpler verendir. Ne az şükrediyorsunuz!"'),
(67, 24, 29, 563, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'Qul huwa alladhī dharaʾakum fī l-arḍi wa-ilayhi tuḥsharūn', 'De ki: "O, sizi yeryüzünde yaratıp var eden ve hepinizi O''nun huzurunda toplayacak olandır."'),
(67, 25, 29, 563, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'wa yaqūlūna matā hādhā al-waʿdu in kuntum ṣādiqīn', 'Eğer doğru sözlüler iseniz, bu vaad ne zaman gerçekleşecek? derler.'),
(67, 26, 29, 563, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'Qul ʾinnamā l-ʿilmu ʿinda llāh wa-ʾinnamā ʾanā nadhīrun mubīn', 'De ki: "Onun ilmi ancak Allah katındadır. Ben ise sadece apaçık bir uyarıcıyım."'),
(67, 27, 29, 564, 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', 'fe-lemmā raʾawhu zulfeten sīʾet wujūhu lladhīne keferū ve qīle hādhā lladhī kuntum bihī taddaʿūn', 'Nihayet onu (azabı) yaklaşıp gördükleri zaman, kâfirlerin yüzleri kötüleşti. Ve (onlara): "İşte bu, sizin isteyip durduğunuz şeydir!" denildi.'),
(67, 28, 29, 564, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ', 'qul ʾaraʾaytum ʾin ʾahlakanīya llāhu waman maʿiya ʾaw raḥimanā faman yujīru lkāfirīna min ʿaḏābin ʾalīmin', 'De ki: ''Söyleyin bana, eğer Allah beni ve benimle birlikte olanları helak ederse veya bize merhamet ederse, peki, acı azaptan kâfirleri kim kurtarabilir?'''),
(67, 29, 29, 564, 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', 'Qul huwa ar-Raḥmānu Āmannā bihi Wa ʿalayhi tawakkalnā Fasataʿlamūna Man huwa fī ḍalālin mubīnin', 'De ki: "O, Rahmân''dır. O''na iman ettik ve O''na tevekkül ettik. Kimin apaçık bir sapıklık içinde olduğunu siz yakında bileceksiniz."'),
(67, 30, 29, 564, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَآءٍ مَّعِينٍۭ', 'qul ʾaraʾaytum ʾin ʾaṣbaḥa māʾukum ḡawran faman yaʾtīkum bimāʾin maʿīnin', 'De ki: «Eğer suyunuz çekilip yeraltına inse, o zaman söyleyin bakalım, kim size bir kaynak suyu getirebilir?»'),
(68, 1, 29, 564, 'نٓ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', 'Nūn. Vəl-qələmi vəmā yəsṭurūn', 'Nun. Kaleme ve onların yazdıklarına yemin olsun.'),
(68, 2, 29, 564, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ', 'Mā anta bi-niʿmati rabbika bi-majnūnin', 'Sen, Rabbinin nimetiyle bir mecnun (deli) değilsin.'),
(68, 3, 29, 564, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ', 'wa-inna laka la-ʾajran ġayra mamnūnin', 'Ve şüphesiz senin için kesintiye uğramayacak bir ecir vardır.'),
(68, 4, 29, 564, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ', 'wa-ʾinnaka la-ʿalā ḫuluqin ʿaẓīm', 'Şüphesiz sen yüce bir ahlâk üzeresin.'),
(68, 5, 29, 564, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 'fasatubṣiru wayubṣirūna', 'Siz de göreceksiniz, onlar da görecekler.'),
(68, 6, 29, 564, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', 'biʾayyikum al-maftūn', 'Hanginizde imiş o fitne!'),
(68, 7, 29, 564, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ʾinna rabbaka huwa ʾaʿlamu biman ḍalla ʿan sabīlihī wahuwa ʾaʿlamu bilmuhtadīn', 'Şüphesiz Rabbin, kendi yolundan sapanı en iyi bilendir ve O, doğru yolu bulanları da en iyi bilendir.'),
(68, 8, 29, 564, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', 'falā tuṭiʿi l-mukadhibīn', 'Yalanlayanlara itaat etme.'),
(68, 9, 29, 564, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', 'waddū law tud''hinu fayud''hinūn', 'Onlar, sen onların eğiliminde olsan, kendileri de sana eğilim göstereceklerdi.'),
(68, 10, 29, 564, 'وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِينٍ', 'wa lā tuṭiʿ kulla ḥallāfin mahīn', 'Yemin edip duran, hor görülen kimseye itaat etme!'),
(68, 11, 29, 564, 'هَمَّازٍ مَّشَّآءٍۭ بِنَمِيمٍ', 'hammazin mashsha''in binameem', 'O, (insanların) ardından çekiştiren, söz getirip götüren (veya koğuculuk eden) bir kimsedir.'),
(68, 12, 29, 564, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', 'mannāʿin lil-khayri muʿtadin ʾathīm', 'Hayra engel olan, haddi aşan, günaha dalan.'),
(68, 13, 29, 564, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', 'ʿutullin baʿda dhālika zanīmin', 'Ondan sonra da soyu sopu belirsiz, kaba saba birisi.'),
(68, 14, 29, 564, 'أَن كَانَ ذَا مَالٍ وَبَنِينَ', 'ʾan kāna ḏā mālٍ wa-banīna', 'Mal ve oğul sahibi olmasından dolayıdır.'),
(68, 15, 29, 564, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'idhā tutlā ʿalayhi ʾāyātunā qāla ʾasāṭīru l-ʾawwalīn', 'Aleyhine ayetlerimiz okunduğunda, ''Bunlar öncekilerin masallarıdır!'' der.'),
(68, 16, 29, 565, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', 'sanāsimuhu ʿalā l-khurṭūm', 'Onu hortumunun üzerine damgalayacağız.'),
(68, 17, 29, 565, 'إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 'innā balavnāhum kamā balavnā aṣḥāba l-jannati iż aqsamū layṣrimunnahā muṣbiḥīn', 'Biz onlara, bahçe sahiplerini denediğimiz gibi denedik. Hani onlar, sabahleyin bahçenin ürününü devşireceklerine yemin etmişlerdi.'),
(68, 18, 29, 565, 'وَلَا يَسْتَثْنُونَ', 'wa lā yastathnūna', 'Onlar şöyle derlerdi: ''Bizim ekinlerimize sabahleyin mutlaka uğrayın, eğer (meyvelerini) devşirecekseniz!'''),
(68, 19, 29, 565, 'فَطَافَ عَلَيْهَا طَآئِفٌ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 'faṭāfa ʿalayhā ṭāʾifun mir rabbika wa hum nāʾimūn', 'Derken, onlar uykuda iken, Rabbin tarafından onun üzerinde bir azap (dolaşıcı) dolaşıverdi.'),
(68, 20, 29, 565, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', 'faʾaṣbaḥat kaṣ-ṣarīmi', 'Böylece (bağları) simsiyah kesilmiş gibi oldu.'),
(68, 21, 29, 565, 'فَتَنَادَوْا۟ مُصْبِحِينَ', 'fa-tanādaw muṣbiḥīn', 'Derken sabahleyin birbirlerine şöyle seslendiler:'),
(68, 22, 29, 565, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَ', 'ʾani ʾighdū ʿalā ḥarṯikum ʾin kuntum ṣārimīn', 'Eğer (ürün) toplayacaksanız, şöyle derlerdi: Haydi, ürünlerinize gidin!'),
(68, 23, 29, 565, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَٰفَتُونَ', 'fa-nṭalaqū wa-hum yatakhafatūn', 'Bunun üzerine gizlice konuşarak yola koyuldular.'),
(68, 24, 29, 565, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌ', 'ʾan lā yدخulannahā l-yawma ʿalaykum miskīnun', 'Bugün sizin yanınıza hiçbir yoksul girmesin!'),
(68, 25, 29, 565, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍ قَٰدِرِينَ', 'wa ghadaw ʿalā ḥardin qādirīn', 'Ve (onlar) buna benzer bir karar üzere sabahladılar.'),
(68, 26, 29, 565, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', 'felemmā raʾavhā qālūʾ ʾinnā laḍāllūna', 'Onu gördükleri zaman: "Şüphesiz biz dosdoğru yolu kaybetmişiz" dediler.'),
(68, 27, 29, 565, 'بَلْ نَحْنُ مَحْرُومُونَ', 'bal naḥnu maḥrūmūn', 'Hayır, biz mahrum kaldık.'),
(68, 28, 29, 565, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', 'qāla awsathum alam aqul lakum lawlā tusabbiḥūn', 'İçlerinden en aklı başında olanı dedi ki: "Ben size (Allah''ı) tesbih etmiyor muydunuz dememiş miydim?"'),
(68, 29, 29, 565, 'قَالُوا۟ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'qālū subḥāna rabbina ʾinnā kunnāẓālimīn', 'Dediler ki: "Rabbimizi tesbih ederiz! Gerçekten biz zalim kimseler idik."'),
(68, 30, 29, 565, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَٰوَمُونَ', 'faʾaqbala baʿḍuhum ʿalā baʿḍin yatalāwamūn', 'Bunun üzerine birbirlerine dönüp suçlamaya başladılar.'),
(68, 31, 29, 565, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 'qālū yā waylanā innā kunnā ṭāḡīn', 'Dediler ki: "Eyvah bize! Gerçekten biz azgın kimseler idik."'),
(68, 32, 29, 565, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', 'ʿasā rabbunā ʾan yubdilanā khayran minhā ʾinnā ʾilā rabbina rāghibūna', 'Umarım Rabbimiz bunun yerine bize daha iyisini verir. Şüphesiz biz Rabbimize rağbet edenleriz.'),
(68, 33, 29, 565, 'كَذَٰلِكَ ٱلْعَذَابُ وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'kadhālika l-ʿadhābu wa laʿadhābu l-ʾākhirati ʾakbaru law kānū yaʿlamūna', 'İşte azap böyledir. Elbette ahiret azabı daha büyüktür, bir bilselerdi.'),
(68, 34, 29, 565, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ', 'ʾinna lilmuttaqīna ʿinda rabbihim jannāti n-naʿīmi', 'Şüphesiz takva sahipleri için Rablerinin katında, nimet cennetleri vardır.'),
(68, 35, 29, 565, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', 'ʾafanaǧʿalu l-muslimīna ka-l-muǧrimīn', 'Öyleyse müslümanları suçlular gibi mi tutacağız?'),
(68, 36, 29, 565, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'mā lakum kayfa taḥkumūn', 'Size ne oluyor? Nasıl hüküm veriyorsunuz?'),
(68, 37, 29, 565, 'أَمْ لَكُمْ كِتَٰبٌ فِيهِ تَدْرُسُونَ', 'ʾam lakum kitābun fīhi tadrusūn', 'Yoksa sizin, içinde (ders) okuduğunuz bir kitabınız mı var?'),
(68, 38, 29, 565, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', 'ʾinna lakum fīhi lamā tatakhayyarūn', 'Şüphesiz ki sizin için onda, seçtiğiniz ne varsa mutlaka vardır.'),
(68, 39, 29, 565, 'أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', 'am lakum aymānun ʿalaynā bāliġatun ʾilā yawmi l-qiyāmati ʾinna lakum lamā taḥkumūna', 'Yoksa size, kıyamete kadar sürecek, kesin olarak bildiğimiz yeminlerimiz mi var ki, ne karar verirseniz mutlaka sizin olacak?'),
(68, 40, 29, 565, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', 'salhum ayyuhum bidhalika za''im', 'Onlara sor: "Hanginiz bu konuda kefil?"'),
(68, 41, 29, 565, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَٰدِقِينَ', 'ʾam lahum shurakāʾu falyʾatū bi-shurakāʾihim ʾin kānū ṣādiqīna', 'Yoksa onların (Allah''a ortak koştuğunuz) ortakları mı var? Eğer doğru sözlülerse, haydi ortaklarını getirsinler!'),
(68, 42, 29, 565, 'يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', 'yawma yukshafu ʿan sāqin wa yudʿawna ʾilā s-sujūdi falā yastaṭīʿūna', 'O gün, (korkunç) bir sıkıntı ve dehşetle oneskini açığa çıkarılır ve (o müminler) secdeye davet edilirler, ama (o kâfirler) buna güç yetiremezler.'),
(68, 43, 29, 566, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَٰلِمُونَ', 'khāshiʿatan abṣāruhum tarhaquhum dhillah waqad kānū yudʿawna ilā s-sujūd wa hum sālimūn', 'Gözleri perdelenmiş bir halde, kendilerini bir zillet bürümüş olarak. Halbuki onlar (dünyada) sapasağlam iken secdeye davet olunuyorlardı.'),
(68, 44, 29, 566, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'Fa-dhar-nī wa-man yukadhibu bi-hādhā al-ḥadīth Sa-nastadrijuhum min ḥaythu lā yaʿlamūn', 'Şimdi beni ve bu sözü yalanlayanları bana bırak; onları, farkında olmadıkları bir yönden yavaş yavaş helaka sürükleyeceğiz.'),
(68, 45, 29, 566, 'وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ', 'wa-umlī lahum inna kaydī matīn', 'Onlara mühlet veririm. Şüphesiz benim tuzağım (aldatmam) çok sağlamdır.'),
(68, 46, 29, 566, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', 'ʾam tasʾaluhum ʾajran fahum mim mağramim muṯqalūn', 'Yoksa onlardan bir ücret mi istiyorsun da onlar bu yüzden ağır bir borç altına girmişlerdir?'),
(68, 47, 29, 566, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'ʾam ʿindahumu l-ghaybu fahum yaktubūn', 'Yoksa gayb (gizli şeyler) onların yanındadır da onlar mı yazıyorlar?'),
(68, 48, 29, 566, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ', 'faṣbir liḥukmi rabbika walā takun kaṣāḥibi l-ḥūti iḏ nāḏā wa huwa makẓūmun', 'Şimdi Rabbine sabret. Balık sahibi (Yunus) gibi olma. Hani o, gamla dolu olarak Rabbine yakarmıştı.'),
(68, 49, 29, 566, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌ', 'lawlā an tadārakahu niʿmatun min rabbihī lanubidha bil-ʿarāʾi wa huwa madhmūmun', 'Eğer Rabbinden (gelen) bir nimet olmasaydı, mutlaka o (peygamber) ayıplanacak bir halde çorak bir yere atılmış olurdu.'),
(68, 50, 29, 566, 'فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ', 'fa-jtabāhu rabbuhū fa-jaʿalahū mina ṣ-ṣāliḥīn', 'Böylece Rabbi onu seçti ve onu salihlerden kıldı.'),
(68, 51, 29, 566, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌ', 'wa-ʾinna ya-kādu l-ladhīna kafarū la-yuzliqunaka bi-ʾabṣārihim lammā samiʿū dh-dhikra wa-yaqūlūna ʾinnahu la-majnūn', 'O kâfirler, Kur''an''ı işittikleri zaman, neredeyse seni gözleriyle devireceklerdi. Hatta ''O, delidir!'' diyorlardı.'),
(68, 52, 29, 566, 'وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'wa mā huwa illā dhikrun lil-ʿālamīn', 'Oysa o (Kur''an), âlemler için bir öğütten başka bir şey değildir.'),
(69, 1, 29, 566, 'ٱلْحَآقَّةُ', 'al-ḥāqqah', 'O büyük hakikat!'),
(69, 2, 29, 566, 'مَا ٱلْحَآقَّةُ', 'Mā al-ḥāqqah', 'O Hakka (yani, o büyük hakikat) nedir?'),
(69, 3, 29, 566, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', 'Ve mā adrāka mā l-ḥaqqah', 'Onu (o hakikati) sana ne bildirdi?'),
(69, 4, 29, 566, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', 'kadhdhabat thamūdu wa ʿādun bil-qāriʿah', 'Semûd ve Âd kavimleri ise, o büyük felâket (Kâri''a) ile yalanladılar.'),
(69, 5, 29, 566, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', 'faʾammā thsmūd fāʾuhlikū biṭṭāġiyati', 'Semûd kavmi ise, azgın bir sesle helâk edildi.'),
(69, 6, 29, 566, 'وَأَمَّا عَادٌ فَأُهْلِكُوا۟ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ', 'waʾammā ʿādun faʾuhlikū birīḥin ṣarṣarin ʿātiyah', 'Ad topluluğuna gelince; onlara da uğurlayıcı, dondurucu bir rüzgârla son verilmişti.'),
(69, 7, 29, 566, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومًا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ', 'sakhkharahā ʿalayhim sabʿa layālin wa-thamāniyata ayyāmin ḥusūman fa-tarā l-qawma fīhā ṣarʿā ka-annahum aʿjāzu nakhlin khāwiyah', 'Onların üzerine yedi gece ve sekiz gün boyunca, aralıksız devam eden bir azap gönderdi. (Eğer orada olsaydın) o kavmi, içi boşalmış hurma kütükleri gibi devrilmiş halde görürdün.'),
(69, 8, 29, 566, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍ', 'fa hal tarā lahum min bāqiyah', 'Şimdi onlardan (hayatta) bir kalan görüyor musun?'),
(69, 9, 29, 567, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَٰتُ بِٱلْخَاطِئَةِ', 'wa jāʾa firʿawnu waman qablahū wal-muʾtafikātu bil-khāṭiʾah', 'Firavun da ondan öncekiler ve altı üstüne gelen şehirler de o günahkârlar gelmişti.'),
(69, 10, 29, 567, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً', 'faʿaṣaw rasūla rabbihim faʾaḵaḏahum ʾaḵḏatan rābiyatan', 'Böylece Rablerinin elçisine isyan ettiler. Bu yüzden onları şiddetli bir şekilde yakaladı.'),
(69, 11, 29, 567, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَٰكُمْ فِى ٱلْجَارِيَةِ', 'ʾinnā lammā ṭaghā l-māʾu ḥamalnākum fī l-jāriyati', 'Nihayet (Nuh''un kavmini helak eden) su taştığı zaman, sizi (gemide) taşımışızdır.'),
(69, 12, 29, 567, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ', 'li-najʿalahā lakum taẕkiratan wa-taʿiyahā ʾuḏunun wāʿiyatun', 'Onu, sizin için bir öğüt (ve ibret) kılalım ve kulak veren kulaklar (ona) vuku bulsun diye.'),
(69, 13, 29, 567, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌ وَٰحِدَةٌ', 'faʾiḏā nufiḵa fī ṣ-ṣūri nafḵatun wāḥidatun', 'Nihayet Sûr''a bir defa üflendiği zaman,'),
(69, 14, 29, 567, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةً وَٰحِدَةً', 'wa ḥumilat il-arḍu wal-jibālu fa-dukketā dakkatan wāḥidatan', 'Yeryüzü ve dağlar kaldırılıp birbirine çarpılarak tek bir toz haline getirildiği zaman...'),
(69, 15, 29, 567, 'فَيَوْمَئِذٍ وَقَعَتِ ٱلْوَاقِعَةُ', 'fa-yawmaʾiḏin waqaʿati l-wāqiʿah', 'İşte o gün, gerçekleşecek olan (o büyük felaket) gerçekleşir.'),
(69, 16, 29, 567, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ', 'we-nshaqqati-s-semāʾu fe-hiye yevmeʾiḏin wāhiyetun', 'Gök yarılmış ve o gün, zayıf düşmüştür.'),
(69, 17, 29, 567, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَٰنِيَةٌ', 've''l-meleku ''alā erçā''ihā ve yaḥmilu ''arşa rabbike fevquehum yevme''iẕin semāniyetun', 'Melekler de onun etrafındadır. Ve o gün, Rabbinin arşını onların da üstünde sekiz (melek) taşır.'),
(69, 18, 29, 567, 'يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌ', 'yawmaʾiḏin tuʿraḍūn lā taḫfā minkum ḫāfiyah', 'İşte o gün (hesap için) arz olunursunuz; hiçbir gizli haliniz gizli kalmaz.'),
(69, 19, 29, 567, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَٰبِيَهْ', 'faʾammā man ʾūtiya kitābahū biyemīnihi feyeqūlu hāʾumū iqraʾū kitābiyah', 'Kitabı sağ tarafından verilen kimse şöyle der: "Alın, kitabımı okuyun!"'),
(69, 20, 29, 567, 'إِنِّى ظَنَنتُ أَنِّى مُلَٰقٍ حِسَابِيَهْ', 'ʾinnī ẓanantu ʾannī mulāqin ḥisābiyeh', 'Ben, hesabıma kavuşacağımı muhakkak ki zannetmiştim.'),
(69, 21, 29, 567, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 'fa huwa fī ʿīsyatin rāḍiyah', 'Artık o, hoşnut bir hayat içindedir.'),
(69, 22, 29, 567, 'فِى جَنَّةٍ عَالِيَةٍ', 'fī jannatin ʿāliyah', 'Onların barınağı yüce bir cennettir.'),
(69, 23, 29, 567, 'قُطُوفُهَا دَانِيَةٌ', 'quṭūfuhā dāniyah', 'Meyveleri (ağaçların dalları) sarkmış, yakın.'),
(69, 24, 29, 567, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ', 'kulū wa-shrū hanīʾan bimā aslāftum fī l-ʾayyāmi l-khāliyah', 'Geçmiş günlerde (yapıp) takdim ettiğiniz şeyler yüzünden afiyetle yiyin, için.'),
(69, 25, 29, 567, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيْتَنِى لَمْ أُوتَ كِتَٰبِيَهْ', 'waʾammā man ʾūtiya kitābahū bišimālihī feyaqūlu yālaytanī lam ʾūta kitābiyah', 'Amma men utiye kitâbehu bişimâlihî feyekûlu yâleytenî lem utâ kitâbiyeh.'),
(69, 26, 29, 567, 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', 'wa lam adri mā ḥisābiyah', 'Hesabımın ne olduğunu da bilemedim.'),
(69, 27, 29, 567, 'يَٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ', 'yā-laytahā kānat-i l-qāḍiyah', 'Keşke o (ölüm) yeterli olsaydı!'),
(69, 28, 29, 567, 'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ', 'mā ʾaġnā ʿannī mālīyeh', 'Malım bana hiçbir fayda sağlamadı.'),
(69, 29, 29, 567, 'هَلَكَ عَنِّى سُلْطَٰنِيَهْ', 'halaka ʿannī sulṭāniyah', 'Benden saltanatım/gücüm yok olup gitti.'),
(69, 30, 29, 567, 'خُذُوهُ فَغُلُّوهُ', 'khudhūhu faghullūhu', 'Onu alın da hemen bağlayın!'),
(69, 31, 29, 567, 'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ', 'thumma l-jaḥīma ṣallūhu', 'Sonra onu cehenneme atın!'),
(69, 32, 29, 567, 'ثُمَّ فِى سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَٱسْلُكُوهُ', 'thumma fī silsilatin dharʿuhā sabʿūna dhirāʿan fa-slukūhu', 'Sonra onu, yetmiş arşınlık bir zincire vurup sürükleyin!'),
(69, 33, 29, 567, 'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ', 'ʾinnahu kāna lā yuʾminu bi-llāhi l-ʿaẓīm', 'Çünkü o, yüce Allah''a inanmıyordu.'),
(69, 34, 29, 567, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'wa lā yaḥuḍḍu ʿalā ṭaʿāmi l-miskīn', 'Ve yoksulu doyurmaya teşvik etmezdi.'),
(69, 35, 29, 568, 'فَلَيْسَ لَهُ ٱلْيَوْمَ هَٰهُنَا حَمِيمٌ', 'falaysa lahu al-yawma hāhunā ḥamīmun', 'Artık bugün burada ona bir dost yoktur.'),
(69, 36, 29, 568, 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ', 'wa-lā ṭaʿāmun ʾillā min ġislinin', 'Ve (oradan) bir yiyecek (yoktur) ancak irinden (veya kaynayan şeylerden) başka.'),
(69, 37, 29, 568, 'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ', 'lā yaʾkuluhu ʾillā l-khāṭiʾūn', 'Onu günahkârlardan başkası yiyemez.'),
(69, 38, 29, 568, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 'falā uqsimu bimā tubṣirūn', 'Gördüklerinize yemin ederim!'),
(69, 39, 29, 568, 'وَمَا لَا تُبْصِرُونَ', 'wa mā lā tubṣirūn', 'Ve görmekte olduklarınız ve görmekte olmadıklarınız.'),
(69, 40, 29, 568, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', 'ʾinnahu laqawlu rasūlin karīm', 'Şüphesiz ki o (Kur''an), kerim (değerli, şerefli) bir elçinin sözüdür.'),
(69, 41, 29, 568, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلًا مَّا تُؤْمِنُونَ', 'wa mā huwa bi-qawli shāʿirin qalīlan mā tuʾminūn', 'O, bir şair sözü değildir; ne az inanıyorsunuz!'),
(69, 42, 29, 568, 'وَلَا بِقَوْلِ كَاهِنٍ قَلِيلًا مَّا تَذَكَّرُونَ', 'wa lā bi-qawli kāhinin qalīlan mā tadkkarūna', 'Ne de bir kâhinin sözüyle. Ne az düşünüyorsunuz!'),
(69, 43, 29, 568, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'tanzīlun min rabbil-ʿālamīn', 'O, âlemlerin Rabbi tarafından indirilmiştir.'),
(69, 44, 29, 568, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', 'wa law taqawwala ʿalaynā baʿḍa l-ʾaqāwīli', 'Eğer o (Peygamber), bize karşı bazı sözler uydurmuş olsaydı,'),
(69, 45, 29, 568, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', 'leʾaḫaḏnā minhu bil-yamīni', 'Elbette onu sağ elinden yakalardık.'),
(69, 46, 29, 568, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', 'thumma laqaṭaʿnā minhu l-watīn', 'Sonra onun şah damarını elbette keserdik.'),
(69, 47, 29, 568, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَ', 'famā minkum min ʾaḥadin ʿanhu ḥājizīn', 'Onlardan hiçbir kimse onu (azabı) engelleyemezdi.'),
(69, 48, 29, 568, 'وَإِنَّهُۥ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ', 'wa innahu latadhkiratun lilmuttaqin', 'Şüphesiz o (Kur''an), takva sahipleri için bir öğüttür.'),
(69, 49, 29, 568, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', 'wa-ʾinnā lanāʿlamu ʾanna minkum m-mukaḏḏibīn', 'Şüphesiz biz, içinizden yalanlayanların olduğunu elbette biliyoruz.'),
(69, 50, 29, 568, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَٰفِرِينَ', 'waʾinnahu laḥasratun ʿalā lkāfirīn', 'Şüphesiz ki o (Kur''an), kâfirler için büyük bir hasret (üzüntü ve pişmanlık) olacaktır.'),
(69, 51, 29, 568, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', 'waʾinnahuu laḥaqqul-yaqīn', 'Şüphesiz ki o (Kur''an), hak ve kesin bir gerçektir.'),
(69, 52, 29, 568, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'fasabbiḥ bi-ismi rabbika l-ʿaẓīm', 'Öyleyse büyük Rabbinin adını tesbih et.'),
(70, 1, 29, 568, 'سَأَلَ سَآئِلٌۢ بِعَذَابٍ وَاقِعٍ', 'saʾala sāʾilum biʿaḏābin wāqiʿin', 'İsteyen, düşeceğinden emin olunan bir azap istemiştir.'),
(70, 2, 29, 568, 'لِّلْكَٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌ', 'lil-kāfirīna laysa la-hū dāfiʿun', 'Kafirler için, ondan savacak bir güç yoktur.'),
(70, 3, 29, 568, 'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ', 'minallāhi ḏī l-maʿāriji', 'O, (insanların) yükselme yollarına sahip olan Allah’tandır.'),
(70, 4, 29, 568, 'تَعْرُجُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍ', 'taʿruju l-malāʾikatu wa-r-rūḥu ilayhi fī yawmin kāna miqdāruhu khamsīna al''fa sanatin', 'Melekler ve Ruh, ona, o gün mi''râcı bin yıllık mesafeye denk olan elli bin sene kadar süren bir yükselişle çıkarlar.'),
(70, 5, 29, 568, 'فَٱصْبِرْ صَبْرًا جَمِيلًا', 'faṣbir ṣabran jamīlan', 'Şimdi güzel bir sabırla sabret.'),
(70, 6, 29, 568, 'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًا', 'ʾinnahum yarawnahū baʿīdā', 'Onlar, onu uzak görüyorlar.'),
(70, 7, 29, 568, 'وَنَرَىٰهُ قَرِيبًا', 'wa narāhu qarīban', 'Onu yakın görürüz.'),
(70, 8, 29, 568, 'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ', 'yawma takūnu s-samāʾu ka-l-muhli', 'O gün gök, erimiş maden gibi olur.'),
(70, 9, 29, 568, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ', 'wa takūnu l-jibālu ka-l-ʿihni', 'O gün dağlar (atılmış) yüne döner.'),
(70, 10, 29, 568, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًا', 'wa lā yasʾalu ḥamīmun ḥamīman', 'O gün, yakın dostun dostunu sormaz.'),
(70, 11, 29, 569, 'يُبَصَّرُونَهُمْ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ', 'yubassarūnahum yawaddu l-mujrimu law yaftadī min ʿadhābi yawmiʾiḏin bibanīhi', 'Onlar birbirlerini görürler. Suçlu, o günün azabından kurtulmak için (fakat) oğullarını feda etmek ister.'),
(70, 12, 29, 569, 'وَصَٰحِبَتِهِۦ وَأَخِيهِ', 'waṣāḥibatihi waʾakhīhi', 'Ve eşini ve kardeşini,'),
(70, 13, 29, 569, 'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ', 'wa faṣīlatihi llatī tuʾwīhi', 'Ve onu barındıran (yakın) akrabasını da.'),
(70, 14, 29, 569, 'وَمَن فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ يُنجِيهِ', 'wa-man fī l-arḍi jamīʿan thumma yunjeeh', 'Yeryüzündeki herkesi ve sonra onu kurtaracak olanı.'),
(70, 15, 29, 569, 'كَلَّآ إِنَّهَا لَظَىٰ', 'kallā, innahā laẓā', 'Hayır! Şüphesiz o, alevli bir ateştir.'),
(70, 16, 29, 569, 'نَزَّاعَةً لِّلشَّوَىٰ', 'nazzāʿatan lish-shawā', 'Deriyi soyup kavurur.'),
(70, 17, 29, 569, 'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ', 'tadʿū man adbara wa tawallā', 'Arkasına dönüp yüz çevireni çağırır.'),
(70, 18, 29, 569, 'وَجَمَعَ فَأَوْعَىٰٓ', 'wa jamaʿa fa-awʿā', 'O, (insanı) toplar ve (biriktirir).'),
(70, 19, 29, 569, 'إِنَّ ٱلْإِنسَٰنَ خُلِقَ هَلُوعًا', 'ʾinna l-ʾinsāna ḫuliqa halūʿan', 'Doğrusu insan, telaşlı (ve sabırsız) yaratılmıştır.'),
(70, 20, 29, 569, 'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًا', 'iḏā massahu ʾš-šarru jazūʿan', 'Kendisine fenalık dokunduğu zaman çok feryat edicidir.'),
(70, 21, 29, 569, 'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا', 'wa-ʾidhā massahu l-khayru manūʿan', 'Ancak ona hayır (iyilik, bolluk) dokunduğunda, (hayrı) engelleyici olur.'),
(70, 22, 29, 569, 'إِلَّا ٱلْمُصَلِّينَ', 'illa l-muṣallīn', 'Ancak namaz kılanlar müstesna'),
(70, 23, 29, 569, 'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ', 'alladhīna hum ʿalā ṣalātihim dāʾimūn', 'Onlar, namazlarına devam edenlerdir.'),
(70, 24, 29, 569, 'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّ مَّعْلُومٌ', 'wa-lladhīna fī ʾamwālihim ḥaqqun maʿlūmun', 'Onların mallarında, isteyen ve (isteyip de) mahrum kalanlar için belirli bir hak vardı.'),
(70, 25, 29, 569, 'لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'lis-sāʾili wal-maḥrūmi', 'Yardım dileyene ve mahrum kalana.'),
(70, 26, 29, 569, 'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ', 'wa-lladhīna yuṣaddiqūna bi-yawmi d-dīn', 'Ve onlar ki, din gününü tasdik ederler.'),
(70, 27, 29, 569, 'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 'wa-lladhīna hum min ʿadhābi rabbihim mushfiqūna', 'Ve onlar ki, Rablerinin azabından korkarlar.'),
(70, 28, 29, 569, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ', 'inna ʿaḏāba rabbihim ġayru maʾmūn', 'Onların Rablerinin azabı gerçekten güvenliğe çıkarıcı değildir.'),
(70, 29, 29, 569, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'wa-lladhīna hum li-furūjihim ḥāfiẓūn', 'Ve onlar ki, iffetlerini korurlar.'),
(70, 30, 29, 569, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'illa ʿalā ʾazwājihim ʾaw mā malakat ʾaymānuhum fa-ʾinnahum ġayru malūmīn', 'Ancak eşleri ve cariyeleri müstesna; çünkü onlar kınanmazlar.'),
(70, 31, 29, 569, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 'fe-meni-btagā warāʾa ḏālika fa-ʾulāʾika humu-l-ʿādūn', 'Bunun ötesine geçmek isteyenler ise, işte bunlar haddi aşanlardır.'),
(70, 32, 29, 569, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'wa-lladhīna hum li-ʾamānātihim wa-ʿahdihim rāʿūna', 'Onlar, emanetlerine ve ahidlerine riayet edenlerdir.'),
(70, 33, 29, 569, 'وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمْ قَآئِمُونَ', 'wa-lladhīna hum bi-sh-shahādātihim qāʾimūn', 'Ve onlar ki, şahitliklerinde dürüst ve vefalıdırlar.'),
(70, 34, 29, 569, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'wa-lladhīna hum ʿalā ṣalātihim yuḥāfiẓūna', 'Onlar, namazlarına devam edenlerdir.'),
(70, 35, 29, 569, 'أُو۟لَٰٓئِكَ فِى جَنَّٰتٍ مُّكْرَمُونَ', 'ʾulāʾika fī jannātin mukramūna', 'İşte onlar, cennetlerde ağırlanırlar.'),
(70, 36, 29, 569, 'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ', 'famāli alladhīna kafarū qibalaka muht̤iʿīna', 'Şimdi, inkâr edenlere ne oluyor da sana doğru koşuşuyorlar?'),
(70, 37, 29, 569, 'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ', 'ʿani l-yamīni wa ʿani sh-shimāli ʿizīn', 'Sağlarından ve sollarından bölük bölük.'),
(70, 38, 29, 569, 'أَيَطْمَعُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ', 'ʾayaṭmaʿu kullu mriʾin minhum ʾan yudkhala jannata naʿīm', 'Onlardan her biri, nimet cennetine sokulacağını mı umuyor?'),
(70, 39, 29, 569, 'كَلَّآ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ', 'kellā innā khalaqnāhum mimmā yaʿlamūn', 'Hayır! Onları bildiğimiz bir şeyden yarattık.'),
(70, 40, 29, 570, 'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَٰرِقِ وَٱلْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ', 'falā uqsimu birabbi l-maşāriqi wa-l-mağāribi ʾinnā laqādirūna', 'Hayır! Doğunun ve batının Rabbi hakkı için, biz elbette kadiriz.'),
(70, 41, 29, 570, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'ʿalā ʾan nubaddila ḵayran minhum wa mā naḥnu bimaspūqīn', 'Onların yerine başkalarını getirmeye ve (bu hususta) bizi aciz bırakmaya da (gücümüz yeter).'),
(70, 42, 29, 570, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'faḏarhum yaḥūḍū wa yalʿabū ḥattā yulāqū yawmahumu llaḏī yūʿadūn', 'Artık sen onları bırak, dalsınlar ve oynayadursunlar, kendilerine vaadedilen o güne kavuşuncaya kadar.'),
(70, 43, 29, 570, 'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ', 'yawma yakhrujūna mina l-ajdāthi sirāʿan ka-annahum ilā nuṣubin yūfiḍūna', 'O gün, kabirlerden (çıkmış) hızla koşarlar; sanki dikili bir şeye (puta) doğru koşuyor gibidirler.'),
(70, 44, 29, 570, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'khāshiʿatan abṣāruhum tarhaquhum dhillah dhālika l-yawmu lladhī kānū yūʿadūn', 'Gözleri horluktan yere batmış, kendilerini bir zillet kaplamış olarak (o güne çıkarlar). İşte bu, onlara va''dedilen gündür.'),
(71, 1, 29, 570, 'إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', 'ʾinnā ʾarsalnā nūḥan ʾilā qawmihī ʾan ʾanẓir qawmaka min qabli ʾan yaʾtiyahum ʿaḏābun ʾalīmun', 'Doğrusu biz Nuh''u kavmine, ''Kendilerine elem dolu bir azap gelmeden önce, kavmini uyar'' diye (peygamber olarak) gönderdik.'),
(71, 2, 29, 570, 'قَالَ يَٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 'qāla yā qawmi innī lakum nadīrun mubīn', 'Ey kavmim! dedi, ben size apaçık bir uyarıcıyım.'),
(71, 3, 29, 570, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', 'ʾani ʿbudū ʾllāha wa-ttaqūhu wa-ʾaṭīʿūni', 'Rabbinizin günahlarından mağfiret isteyin. Şüphesiz O, çok bağışlayandır.'),
(71, 4, 29, 570, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ لَوْ كُنتُمْ تَعْلَمُونَ', 'yagfir lakum min dhunubikum wa yu''akhkhirakum ila ajalim musamma inna ajallahi idha ja''a la yu''akhkhar law kuntum ta''lamun', 'O da size günahlarınızdan mağfiret eylesin ve sizi muayyen bir vakte kadar tehir eylesin. Şüphe yok ki Allah''ın tayin ettiği vakit gelince, artık tehir edilmez. Bir bilseydiniz!'),
(71, 5, 29, 570, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', 'qāla rabbi innī daʿawtu qawmī laylan wa nahāran', 'Nuh dedi ki: "Rabbim! Ben kavmimi gece ve gündüz davet ettim."'),
(71, 6, 29, 570, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', 'fe lem yezidhum duʿāʾī ʾillā firāran', 'Benim davetim onlara kaçmaktan başka bir fayda sağlamadı.'),
(71, 7, 29, 570, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', 'wa-ʾinnī kullamā daʿawtuhum litagfira lahum jaʿalū ʾaṣābiʿahum fī ʾādhānihim wa-staghshaw thiyābahum wa-ʾaṣarrū wa-stakbarū istikbāran', 'Ve onları bağışlaman için her ne zaman onları çağırdımsa, parmaklarını kulaklarına soktular, elbiselerine büründüler, direttiler ve kibirlendikçe kibirlendiler.'),
(71, 8, 29, 570, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', 'thumma innī daʿawtuhum jihāran', 'Sonra ben onlara, açığa vurarak davette bulundum.'),
(71, 9, 29, 570, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', 'thumma innī ʾaʿlantu lahum wa ʾasrar-tu lahum ʾisrārā', 'Sonra ben onlara hem açıktan davet ettim hem de onlara gizlice de davet ettim.'),
(71, 10, 29, 570, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا', 'fa-qultu-staghfirū rabbakum ʾinnahu kāna ġaffārā', 'Böylece dedim ki: Rabbinizden bağışlanma dileyin; çünkü O, çok bağışlayandır.'),
(71, 11, 29, 571, 'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا', 'yursili s-semāʾa ʿalaykum midrāran', 'Onun için Rabbinizden mağfiret dileyin, çünkü O, çok bağışlayandır. (10) (Mağfiret dilediğiniz takdirde) üzerinize gökten bol bol yağmur indirir.'),
(71, 12, 29, 571, 'وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتٍ وَيَجْعَل لَّكُمْ أَنْهَٰرًا', 'wa-yumdidkum bi-amwālin wa-banīna wa-yajʿal lakum jannātin wa-yajʿal lakum anhāran', 'Ve size mallar ve oğullar vererek, sizin için bahçeler ve sizin için ırmaklar yapacaktır.'),
(71, 13, 29, 571, 'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا', 'mā lakum lā tarjūna lillāhi waqāran', 'Size ne oluyor da Allah''a bir saygı ve azamet atfetmiyorsunuz?'),
(71, 14, 29, 571, 'وَقَدْ خَلَقَكُمْ أَطْوَارًا', 'waqad khalaqakum aṭwāran', 'Ve sizi evre evre O yaratmıştır.'),
(71, 15, 29, 571, 'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَٰوَٰتٍ طِبَاقًا', 'ʾalam taraw kayfa ḵalaqa ʾallāhu sabʿa samāwātin ṭibāqan', 'Görmediniz mi Allah, yedi göğü nasıl tabaka tabaka yaratmıştır?'),
(71, 16, 29, 571, 'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا', 'wa jaʿala l-qamara fīhinna nūran wa jaʿala sh-shamsa sirājan', 'Ve onları (gökleri) aydınlatacak bir ay ve kandil olarak güneşi var etti.'),
(71, 17, 29, 571, 'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا', 'wa-llāhu anbatakum mina l-arḍi nabātan', 'Allah sizi topraktan bir bitki (gibi) bitirmiştir.'),
(71, 18, 29, 571, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا', 'thumma yuʿīdukum fīhā wa yukhrijukum ikhrājan', 'Sonra sizi oraya (toprağa) döndürecek ve sizi (oradan) bir çıkarışla çıkaracaktır.'),
(71, 19, 29, 571, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', 'wa-llāhu jaʿala lakumu l-arḍa bisāṭan', 'Allah, yeryüzünü sizin için bir döşek yapmıştır.'),
(71, 20, 29, 571, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', 'li-taslukū minhā subulan fijājan', 'Onun içinden, geniş yollar tutabilesiniz diye.'),
(71, 21, 29, 571, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', 'qāla nūḥun rabbī ʾinnahum ʿaṣawnī wāttabaʿū man lam yazidhu māluhū waladuhū ʾillā khasāran', 'Nuh dedi ki: "Rabbim! Onlar bana isyan ettiler ve malı ve evlatları kendisini ancak ziyana uğratan kimselere uydular."'),
(71, 22, 29, 571, 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', 'wa makarū makran kabbārā', 'Ve onlar çok büyük bir tuzak kurdular.'),
(71, 23, 29, 571, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', 'wa qālū lā tadhara-nna ʾālihata-kum wa lā tadhara-nna Waddā wa lā Suwāʿā wa lā Yāġūṯa wa Yaʿūqa wa Naṣrā', 'Ve dediler ki: "Sakın ilahlarınızı bırakmayın; hele hele Vedd''i, Süva''ı, Yeğus''u, Ya''uk''u ve Nesra''yı asla bırakmayın!"'),
(71, 24, 29, 571, 'وَقَدْ أَضَلُّوا۟ كَثِيرًا وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلًا', 'wa qad aḍallū kathīran wa lā tazidi ẓ-ẓālimīna illā ḍalālan', 'Ve gerçekten de (onlar) çoğunu saptırdılar. Ve o zalimlere azgınlıktan başka bir şey artırma!'),
(71, 25, 29, 571, 'مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', 'mimmā khaṭīʾātihim ughriqū fa-udkhilū nāran fa-lam yajidū lahum min dunillāhi anṣārā', 'Onların hataları yüzünden helak edildiler ve ateşe atıldılar. O zaman kendilerine Allah''tan başka yardımcılar bulamadılar.'),
(71, 26, 29, 571, 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا', 'wa qāla nūḥun rabbī lā tadhar ʿalā l-arḍi mina l-kāfirīna dayyāran', 'Ve Nuh dedi: Rabbim! Yeryüzünde dolaşan hiçbir kâfiri bırakma!'),
(71, 27, 29, 571, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', 'ʾinnaka ʾin taḏarhum yuḍillū ʿibādaka walā yalidū ʾillā fājiran kaffāran', 'Eğer onları (yeryüzünde) bırakırsan, kullarını saptırırlar ve onlardan sadece günahkâr, kâfir evlatlar doğururlar.'),
(71, 28, 29, 571, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا', 'Rabbî ighfir lī wa liwālidayya wa liman dakhala baytiya muʾminan wa lilmuʾminīna walmuʾmināti wa lā tazidi ẓẓālimīna illā tabāran', 'Rabbim! Beni, annemi, babamı, evime mümin olarak gireni ve bütün mümin erkeklerle bütün mümin kadınları bağışla. Zalimlerin ise yalnızca helakini artır.'),
(72, 1, 29, 572, 'قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', 'Qul Ūḥiya ilayya Annahu istamaʿa nafarun min al-jinn Faqālū Innā samiʿnā qurʾānan ʿajabā', 'De ki: Bana, «Doğrusu biz Kur''an''ı dinledik de, hayran kaldık!» diyen bir cin topluluğunun vahyedildiğini dinledim.'),
(72, 2, 29, 572, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', 'yahdī ir-ruşdi fa''āmannā bihi wa lan nuşrika bi-rabbina ahadan', 'Bizi doğru yola iletti. Bu yüzden ona inandık. Rabbimize asla hiçbir şeyi ortak koşmayacağız.'),
(72, 3, 29, 572, 'وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةً وَلَا وَلَدًا', 'wa ʾannahuu taʿaalaa jadd rabbinaa maa-ttakhaḏa ṣāḥibatan wa-laa waladan', 'Ve yine (şunu anladık ki): Rabbimizin şanı yücedir; O, ne bir eş ne de bir çocuk edinmiştir.'),
(72, 4, 29, 572, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', 'waʾannahu kāna yaqūlu safīhunā ʿalā ʾllāhi ṣaṭaṭan', 'Ve yine o, aklı erenlerimizin Allah hakkında (gerçek dışı) şeyler söylemesine sebep olurdu.'),
(72, 5, 29, 572, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', 'wa annā ẓanannā an lan taqūla l-insu wa-l-jinnu ʿalā llāhi kaḏibā', 'Ve bizim, insanların ve cinlerin Allah hakkında yalan söylemeyeceğini sanmış olduğumuzu (söylemiştir).'),
(72, 6, 29, 572, 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', 'wa annahu kāna rijālun mina l-ʾinsi yaʿūdhūna birijālin mina l-jinni fazādūhum rahaqan', 'Ve yine o cinlerden bazı erkeklerin, insanlardan bazı erkeklere sığınmakta olduklarını, böylece cinlerin insanları daha da azgınlaştırdığını söylediler.'),
(72, 7, 29, 572, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', 'wa annahum ẓannū kamā ẓanantum an lan yabʿatha ʾallāhu ʾaḥadan', 'Ve sizin zannettiğiniz gibi, onların da Allah''ın hiç kimseyi tekrar diriltmeyeceğini zannettikleri (anlaşıldı).'),
(72, 8, 29, 572, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', 'wa annā lamasnā s-samāʾa fa-wajadnāhā muliʾat ḥarasan shadīdan wa-shuhuban', 'Ve gerçekten biz göğe dokunduk da, onun dolu olduğunu gördük; (orada) şiddetli bekçiler ve yakıcı yıldızlar bulduk.'),
(72, 9, 29, 572, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَن يَسْتَمِعِ ٱلْءَانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', 'wa annā kunnā naqʿudu minhā maqāʿida lis-samʿi fa-man yastamiʿi l-āna yajid lahu shihāban raṣadā', 'Ve biz, ondan (gökten haber dinlemek için) oturulacak yerlerde otururduk. Ama şimdi kim dinlemek isterse, onu gözetleyen bir ateş topu bulur.'),
(72, 10, 29, 572, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', 'wa-annā lā nadrī a-sharrun urīda bi-man fī l-arḍi am arāda bi-him rabbuhum rashadan', 'Yine biz, yeryüzündekilere fenalık mı murat edildi, yoksa Rableri onlara bir hayır mı murat etti, bilemeyiz.'),
(72, 11, 29, 572, 'وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ كُنَّا طَرَآئِقَ قِدَدًا', 'wa annā minnā ṣ-ṣāliḥūna wa minnā dūna dhālika kunnā ṭarāʾiqa qidada', 'Doğrusu biz, kimimiz salihler, kimimiz de başka türlüleriz. Biz çeşitli yollar tutmuşuz.'),
(72, 12, 29, 572, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', 'wa annā ẓanannā an lan nuʿjiza Allāha fī l-arḍi wa lan nuʿjizahu haraban', 'Ve bizim, yeryüzünde Allah’ı aciz bırakamayacağımızı ve O’nu kaçarak asla aciz bırakamayacağımızı sanmış olmamız (nedeniyle).'),
(72, 13, 29, 572, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', 'wa annā lammā samiʿnā l-hudā āmmanā bihi faman yuʾminu birabbihi falā yakhāfu bakhsan walā raheqan', 'Doğrusu biz, yol göstericiyi (Kur''an''ı) işittiğimizde ona inandık. Kim Rabbine inanırsa, artık ne (sevabının) eksiltileceğinden korkar, ne de (haksızlığa uğrayıp) zulmedileceğinden korkar.'),
(72, 14, 29, 573, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَٰسِطُونَ فَمَنْ أَسْلَمَ فَأُو۟لَٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', 'wa annā minnā l-muslimūna wa minnā l-qāsiṭūna faman aslama fa-ʾulāʾika taḥarraw rashadan', 'Doğrusu bizden Müslümanlar da var, bizden haktan sapanlar da var. Kim Müslüman olursa, işte onlar doğru yolu arayanlardır.'),
(72, 15, 29, 573, 'وَأَمَّا ٱلْقَٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', 'waʾammā l-qāsiṭūna fakānū li-jahannama ḥaṭaban', 'Ve zulmedenler, cehenneme odun olmuşlardır.'),
(72, 16, 29, 573, 'وَأَلَّوِ ٱسْتَقَٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقًا', 'wa-allaw istaqāmū ʿalā ṭ-ṭarīqati la-asqaynāhum māʾan ghadaqan', 'Eğer (insanlar ve cinler) dosdoğru yolda yürüselerdi, elbette onları bol su ile (bol rızıkla) imtihan ederdik.'),
(72, 17, 29, 573, 'لِّنَفْتِنَهُمْ فِيهِ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', 'li-naftinahum fīhi wa-man yuʿriḍ ʿan dhikri rabbihī yaslukhu ʿadhāban ṣaʿadan', 'Onları orada (dünya hayatında) imtihan etmek için (böyle yaptık). Kim de Rabbinin zikrinden yüz çevirirse, Rabbi onu zorlu bir azaba sokar.'),
(72, 18, 29, 573, 'وَأَنَّ ٱلْمَسَٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', 'wa ʾanna l-masājida li-llāhi fa-lā tadʿū mʿa ʾllāhi ʾaḥadan', 'Ve mescitler Allah''ındır. Öyleyse Allah ile birlikte hiç kimseye dua etmeyin.'),
(72, 19, 29, 573, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', 'wa ʾannahu lammā qāma ʿabdu llāhi yadʿūhu kādū yakūnūna ʿalayhi libadan', 'Yemin olsun ki, Allah''ın kulu O''na dua etmek üzere kalktığında, neredeyse onun üzerine (birbirlerine) bineceklerdi.'),
(72, 20, 29, 573, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', 'qul innamā adʿū rabbī walā usyriku bihi ʾaḥadan', 'De ki: Ben sadece Rabbime dua ederim ve O''na hiçbir şeyi ortak koşmam.'),
(72, 21, 29, 573, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', 'qul innī lā ʾamliku lakum ḍarraw walā rašadan', 'De ki: "Ben sizin için ne bir zarar ne de bir fayda vermeye malikim."'),
(72, 22, 29, 573, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 'qul innī lan yujīranī mina llāhi ʾaḥadun wa lan ʾajida min dūnihi multḥadan', 'De ki: "Doğrusu ben, Allah''tan başka hiç kimsenin beni koruyamayacağını ve O''ndan başka sığınacak bir yer de bulamayacağımı bilirim."'),
(72, 23, 29, 573, 'إِلَّا بَلَٰغًا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا', 'illa balāghan mina Allāhi wa-risālātihī wa-man yaʿṣi Allāha wa-rasūlahū fa-inna lahū nāra Jahannama khālidīna fīhā abadan', 'Ancak Allah''tan bir tebliğ ve O''nun mesajlarını iletmek (görevim vardır). Kim Allah''a ve Resûlü''ne isyan ederse, şüphesiz onun için, içinde ebedî kalacakları cehennem ateşi vardır.'),
(72, 24, 29, 573, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', 'ḥattā ʾiḏā raʾaw mā yūʿadūn fasayaʿlamūna man ʾaḍʿafu nāṣirā wa ʾaqallu ʿadadā', 'Nihayet kendilerine vaad olunanı gördükleri zaman, kimin daha zayıf yardımcıya ve kimin daha az kuvvete sahip olduğunu bileceklerdir.'),
(72, 25, 29, 573, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 'qul in adrī aqarībun mā tūʿadūna am yajʿalu lahū rabbī amadan', 'De ki: ''Size vaad olunan yakın mıdır, yoksa Rabbimin bir süre tanıması mıdır, bilemem.'''),
(72, 26, 29, 573, 'عَٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', 'ʿālimu l-ghaybi falā yuẓhiru ʿalā ghaybihi ʾaḥadan', 'O, gaybı bilendir. Gaybını kimseye açıp göstermez.'),
(72, 27, 29, 573, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', 'illa men-irtaḍā min rasūlin fa-innahū yasluku min bayni yadayhi wa-min khalfihī raṣadan', 'Ancak (Allah''ın) razı olduğu bir resul (yoktur ki, Allah onun önünden ve ardından gözetleyici (melekler) yollamasın).'),
(72, 28, 29, 573, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', 'liyaʿlama anna qad ablagū risālāti rabbihim wa-aḥāṭa bimā ladayhim wa-aḥṣā kulla shayʾin ʿadadan', 'Böylece (Allah), onların Rablerinin risaletlerini gerçekten tebliğ etmiş olduklarını bilmiş olur. (Allah) onların yanındakileri ilmiyle kuşatmış ve her şeyi sayıyla sayıp tesbit etmiştir.'),
(73, 1, 29, 574, 'يَٰٓأَيُّهَا ٱلْمُزَّمِّلُ', 'yā ʾayyuhā l-muzammil', 'Ey örtünüp bürünen!'),
(73, 2, 29, 574, 'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا', 'qumi l-layla illā qalīlā', 'Geceleyin kalk (namaz kıl), yarım saat veya biraz daha azı kadar.'),
(73, 3, 29, 574, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 'niṣfahū awi nquṣ minhu qalīlan', 'Gecenin yarısını, yahut yarısından biraz eksilt.'),
(73, 4, 29, 574, 'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا', 'aw zid ʿalayhi wa rattili l-qurʾāna tartīlan', 'Yahut ona ekle ve Kur''an''ı tertil ile oku.'),
(73, 5, 29, 574, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', 'ʾinnā sanulqī ʿalayka qawlan thaqīlan', 'Doğrusu biz sana ağır bir söz vahyedeceğiz.'),
(73, 6, 29, 574, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', 'ʾinna nāshiʾata l-layli hiya ʾashaddu waṭʾan wa-ʾaqwamu qīlan', 'Şüphesiz geceleyin kalkmak, (nefsi) terbiye etmek ve (duayı) sağlamlaştırmak bakımından daha etkili ve (okunanı) daha sağlam bir zamandır.'),
(73, 7, 29, 574, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', 'ʾinna laka fī ʾan-nahāri sabḥan ṭawīlan', 'Şüphesiz senin için gündüzün uzun bir meşguliyeti vardır.'),
(73, 8, 29, 574, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', 'wa-dh-kuri-sma-rabbika wa-tabattal-i-layhi-tabtīlan', 'Rabbinin adını zikret ve her şeyi bırakarak O''na yönel.'),
(73, 9, 29, 574, 'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا', 'rabbu l-maşriki wa-l-mağribi lā ilāha illā huwa fāttahiẓhu wakīlan', 'Doğu''nun ve Batı''nın Rabbi O''dur. O''ndan başka ilah yoktur. Öyleyse, (sana emredileni yaparken) O''nu vekil tut.'),
(73, 10, 29, 574, 'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا', 'waṣbir ʿalā mā yaqūlūn wahjurhum hajran jamīlan', 'Onların söylediklerine sabret ve onlardan güzel bir şekilde ayrıl.'),
(73, 11, 29, 574, 'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا', 'wa dharnī wa-l-mukaḏḏibīna ʾūlī ʾn-naʿmati wa mahhilhum qalīlan', 'Beni ve refah içinde yaşayan o inkârcıları bana bırak. Onlara biraz mühlet ver.'),
(73, 12, 29, 574, 'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا', 'ʾinna ladaynā ʾankālan wa-jaḥīmā', 'Şüphesiz ki, yanımızda (kullandığımız) ağırlaştırıcı zincirler ve çılgın bir ateş vardır.'),
(73, 13, 29, 574, 'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا', 'wa ṭaʿāman dhā ghuṣṣatin wa ʿadhāban alīman', 'Ve onu boğazı düğümlenir bir yemeğe ve elem dolu bir azaba mahkum ettik.'),
(73, 14, 29, 574, 'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا', 'yawma tarjufu l-arḍu wa-l-jibālu wa-kānat il-jibālu kathīban mahīlan', 'O gün yer ve dağlar sarsılır ve dağlar (dağılıp) kum yığını haline gelmiş olur.'),
(73, 15, 29, 574, 'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا', 'innā arsalnā ilaykum rasūlan shāhidan ʿalaykum kamā arsalnā ilā firʿawna rasūlan', 'Şüphesiz size, tıpkı Firavun''a bir elçi göndermiş olduğumuz gibi, size de bir elçi göndermiş bulunuyoruz. O elçi sizin de aleyhinize şahitlik edecektir.'),
(73, 16, 29, 574, 'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَٰهُ أَخْذًا وَبِيلًا', 'faʿaṣā firʿawnu r-rasūla faʾaḵaḏnāhu ʾaḵḏan wabīlan', 'Böylece Firavun o peygambere isyan etti. Biz de onu şiddetli bir şekilde yakaladık.'),
(73, 17, 29, 574, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا', 'fakayfa tattaqūna in kafartum yawman yajʿalu l-wildāna shībā', 'Eğer inkâr ederseniz, çocukları ak saçlı (ihtiyar) yapacak bir günden kendinizi nasıl koruyabilirsiniz?'),
(73, 18, 29, 574, 'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ كَانَ وَعْدُهُۥ مَفْعُولًا', 'as-semāʾu munfaṭirum bihī kāna waʿduhū mafʿūlan', 'Gök, onunla yarılıp-çatlamıştır. O''nun vaadi yerine getirilmiş bulunuyor.'),
(73, 19, 29, 574, 'إِنَّ هَٰذِهِۦ تَذْكِرَةٌ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'ʾinna hāḏihi tadhkirah faman šāʾa ʾittakhaḏa ʾilā rabbihī sabīlā', 'Şüphesiz bu bir öğüttür. Artık dileyen kimse Rabbine (giden) bir yol tutar.'),
(73, 20, 29, 575, 'إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ', 'ʾinna rabbaka yaʿlamu ʾannaka taqūmu ʾadnā min ṯuluṯay al-layli wa-niṣfahu wa-ṯuluṯahu wa-ṭāʾifatun min allaḏīna maʿaka wa-llāhu yuqaddiru al-layla wa-n-nahāra ʿalima ʾan lan tuḥṣūhu fa-tāba ʿalaykum fa-qraʾū mā tayassara mina al-qurʾāni ʿalima ʾan sayakūnu minkum marḍā wa-ʾāxarūna yaḍribūna fī al-ʾarḍi yabtaġūna min faḍli llāhi wa-ʾāxarūna yuqātilūna fī sabīli llāhi fa-qraʾū mā tayassara minhu wa-ʾaqīmū aṣ-ṣalāta wa-ʾātū az-zakāta wa-ʾaqriḍū llāha qarḍan ḥasanan wa-mā tuqaddimū li-ʾanfusikum min xayrin taǧidūhu ʿinda llāhi huwa xayran wa-ʾaʿẓama ʾajran wa-stafġirū llāha ʾinna llāha ġafūrun raḥīmun', 'Şüphesiz Rabbin, senin ve beraberindeki topluluktan bir kısmının geceleyin üçte ikisinden biraz eksik, yarısı, üçte biri kadar kalktığını biliyor. Geceyi ve gündüzü Allah takdir eder. Sizin sayamayacağınızı bildiği için tevbe etti. Artık Kur''an''dan kolay geleni okuyun. Sizden hastaların, yeryüzünde Allah''ın lütfunu arayanların ve Allah yolunda savaşanların olacağını bildi. Artık ondan kolay geleni okuyun, namazı dosdoğru kılın, zekatı verin ve Allah''a güzel bir borç verin. Kendiniz için önceden gönderdiğiniz her iyiliği Allah katında daha hayırlı ve daha büyük bir ecir olarak bulursunuz. Allah''tan mağfiret dileyin. Şüphesiz Allah, çok bağışlayıcı, çok merhamet edicidir.'),
(74, 1, 29, 575, 'يَٰٓأَيُّهَا ٱلْمُدَّثِّرُ', 'yāʾayyuhā l-muddaththir', 'Ey bürünüp sarınan!'),
(74, 2, 29, 575, 'قُمْ فَأَنذِرْ', 'qum fa-ʾanẓir', 'Kalk ve uyar!'),
(74, 3, 29, 575, 'وَرَبَّكَ فَكَبِّرْ', 'wa rabbaka fakabbir', 'Ve Rabbini büyük tanımaya devam et!'),
(74, 4, 29, 575, 'وَثِيَابَكَ فَطَهِّرْ', 'wa thiyābaka faṭahhir', 'Ve elbiseni de temizle!'),
(74, 5, 29, 575, 'وَٱلرُّجْزَ فَٱهْجُرْ', 'wa-r-rujza fa-hjur', 'Ve o pisliği terk et!')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(74, 6, 29, 575, 'وَلَا تَمْنُن تَسْتَكْثِرُ', 'wa lā tamnun tastaʾkthir', 'Ve iyilik edip de fazlasını isteme.'),
(74, 7, 29, 575, 'وَلِرَبِّكَ فَٱصْبِرْ', 'wa lirabbika faṣbir', 'Rabbin için sabret.'),
(74, 8, 29, 575, 'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ', 'fa-ʾidhā nuqira fī ʾn-nāqūr', 'Nitekim o sur''a üflendiği zaman,'),
(74, 9, 29, 575, 'فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ', 'faḏālika yawmaʾiḏin yawmun ʿasīrun', 'İşte o gün, zorlu bir gündür.'),
(74, 10, 29, 575, 'عَلَى ٱلْكَٰفِرِينَ غَيْرُ يَسِيرٍ', 'ʿalā l-kāfirīna ġayru yasīr', 'Kâfirler için hiç kolay değildir.'),
(74, 11, 29, 575, 'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا', 'dharnee wa man khalaqtu waḥeedan', 'Beni, yarattığım ve yalnız bıraktığım kimseyle baş başa bırak.'),
(74, 12, 29, 575, 'وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا', 'wa jaʿaltu lahu mālan mamdūdan', 'Ve ona yayılmış bir mal verdik.'),
(74, 13, 29, 575, 'وَبَنِينَ شُهُودًا', 'wa banīna shuhūdan', 'Ve kendisine şahitlik eden oğullar (verdiğimiz kimse).'),
(74, 14, 29, 575, 'وَمَهَّدتُّ لَهُۥ تَمْهِيدًا', 'wa mahhadtu lahuu tamhiidaa', 'Ve ona (bu nimetleri) hazırlayıp döşedim.'),
(74, 15, 29, 575, 'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ', 'thumma yaṭmaʿu an azīd', 'Sonra da artırmamı umar.'),
(74, 16, 29, 575, 'كَلَّآ إِنَّهُۥ كَانَ لِءَايَٰتِنَا عَنِيدًا', 'kallā, innahu kāna li-ʾāyātinā ʿanīdan', 'Hayır! Doğrusu o, bizim ayetlerimize karşı inatçı kesilmişti.'),
(74, 17, 29, 575, 'سَأُرْهِقُهُۥ صَعُودًا', 'saʾurhiquhū ṣaʿūdan', 'Onu sarp bir yokuşa saracağım.'),
(74, 18, 29, 576, 'إِنَّهُۥ فَكَّرَ وَقَدَّرَ', 'ʾinnahu fakkara wa qaddara', 'Çünkü o, (âyetlerimizi) düşündü ve ölçüp biçti.'),
(74, 19, 29, 576, 'فَقُتِلَ كَيْفَ قَدَّرَ', 'fa-qutila kayfa qaddara', 'Artık ona ölüm/lanet olsun! Nasıl da ölçtü/değerlendirdi?'),
(74, 20, 29, 576, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 'thumma qutila kayfa qaddara', 'Sonra onun nasıl takdir edildiği (ölümü) nasıl gerçekleşti, kahrolası!'),
(74, 21, 29, 576, 'ثُمَّ نَظَرَ', 'thumma naẓara', 'Sonra baktı.'),
(74, 22, 29, 576, 'ثُمَّ عَبَسَ وَبَسَرَ', 'thumma ʿabasa wa basara', 'Sonra yüzünü ekşitti ve kaşlarını çattı.'),
(74, 23, 29, 576, 'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ', 'thumma adbara wastakbara', 'Sonra arkasını döndü ve kibrine kibirlendi.'),
(74, 24, 29, 576, 'فَقَالَ إِنْ هَٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ', 'faqāla in hādhā illā siḥrun yuʾthar', 'Böylece şöyle dedi: "Bu, (eskilerden) öğrenilip aktarılan bir sihirden başka bir şey değildir."'),
(74, 25, 29, 576, 'إِنْ هَٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ', 'in hādhā illā qawlu l-bashari', 'Bu, beşerden başkasının sözü değildir.'),
(74, 26, 29, 576, 'سَأُصْلِيهِ سَقَرَ', 'saʾuṣlīhi saqara', 'Onu Sekar''a (cehenneme) sokacağız.'),
(74, 27, 29, 576, 'وَمَآ أَدْرَىٰكَ مَا سَقَرُ', 'wa mā adrāka mā saqar(u)', 'Ve onu ne bildirecek, nedir o Sakar?'),
(74, 28, 29, 576, 'لَا تُبْقِى وَلَا تَذَرُ', 'lā tubqī walā tadharu', 'Ne alıkoyar ne de bırakır.'),
(74, 29, 29, 576, 'لَوَّاحَةٌ لِّلْبَشَرِ', 'lawwāḥatun lil-bashar', 'O, deriyi kavurur.'),
(74, 30, 29, 576, 'عَلَيْهَا تِسْعَةَ عَشَرَ', 'ʿalayhā tisʿata ʿashara', 'Onun üzerinde on dokuz vardır.'),
(74, 31, 29, 576, 'وَمَا جَعَلْنَآ أَصْحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَٰنًا وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْمُؤْمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', 'wa mā jaʿalnā ʾaṣḥāba n-nāri ʾillā malāʾikatan wa mā jaʿalnā ʿiddatahum ʾillā fitnatan lilladhīna kafarū li-yastayqina lladhīna ʾūtū l-kitāba wa yazadāda lladhīna ʾāmanū ʾīmānan wa lā yartāba lladhīna ʾūtū l-kitāba wal-muʾminūna wa li-yaqūla lladhīna fī qulūbihim maraḍun wal-kāfirūna mādhā ʾarāda ʾllāhu bihādhā mathalan kadhālika yuḍillu ʾllāhu man yashāʾu wa yahdī man yashāʾu wa mā yaʿlamu junūda rabbika ʾillā huwa wa mā hiya ʾillā dhikrā lil-bashari', 'Biz cehennem ehli olanları ancak meleklerden kıldık. Onların sayısını da kâfirler için ancak bir imtihan (vesilesi) yaptık ki, kendilerine kitap verilenler kesin bir bilgiye ulaşsın, iman edenlerin de imanı artsın. Kendilerine kitap verilenler ve müminler şüphe etmesinler. Kalplerinde hastalık bulunanlar ile kâfirler de şöyle desinler: "Allah bu misalle ne murat etmiştir?" İşte Allah, dilediğini böyle saptırır, dilediğini de böyle doğru yola iletir. Rabbinin ordularını O''ndan başkası bilmez. Bu (Kur''an) ise beşer için ancak bir öğüttür.'),
(74, 32, 29, 576, 'كَلَّا وَٱلْقَمَرِ', 'kallā wa-l-qamar', 'Hayır! Ay''a yemin ederim ki,'),
(74, 33, 29, 576, 'وَٱلَّيْلِ إِذْ أَدْبَرَ', 'wa-l-layli idh adbara', 'Ve gece, arkasını döndüğünde'),
(74, 34, 29, 576, 'وَٱلصُّبْحِ إِذَآ أَسْفَرَ', 'waṣ-ṣubḥi idhā ʾasfara', 'Ve aydınlandığı zaman sabaha ki,'),
(74, 35, 29, 576, 'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ', 'ʾinnahā laʾiḥdā l-kubari', 'Şüphesiz o (Cehennem), elbette büyük felaketlerden biridir.'),
(74, 36, 29, 576, 'نَذِيرًا لِّلْبَشَرِ', 'naḏīran lil-baṣar', 'İnsanı uyaracak bir korkutucu olarak.'),
(74, 37, 29, 576, 'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', 'liman shāʾa minkum an yataqaddama aw yataʾakhkhara', 'İçinizden öne geçmek veya geri kalmak isteyene bir uyarıdır.'),
(74, 38, 29, 576, 'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ', 'kullu nafsibbimā kasabat rahīnetun', 'Her nefis, kazandığına karşılık bir rehindir.'),
(74, 39, 29, 576, 'إِلَّآ أَصْحَٰبَ ٱلْيَمِينِ', 'illa aṣḥāba l-yamīn', 'Ancak sağ ehli müstesna.'),
(74, 40, 29, 576, 'فِى جَنَّٰتٍ يَتَسَآءَلُونَ', 'fī jannātin yatasāʾalūn', 'Onlar, cennetlerde birbirlerine sorarlar.'),
(74, 41, 29, 576, 'عَنِ ٱلْمُجْرِمِينَ', 'ʿani l-muǧrimīn', 'Suçlulardan'),
(74, 42, 29, 576, 'مَا سَلَكَكُمْ فِى سَقَرَ', 'mā salakakum fī saqar', 'Sizi Sekar''a (Cehennem''e) sürükleyen nedir?'),
(74, 43, 29, 576, 'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ', 'qālū lam naku mina l-muṣallīn', 'Şöyle dediler: Namaz kılanlardan değildik.'),
(74, 44, 29, 576, 'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ', 'wa lam naku nuṭʿimu l-miskīna', 'Ve biz, düşkünleri doyurmuyorduk.'),
(74, 45, 29, 576, 'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ', 'wa-kunnā nakhūḍu maʿa l-khāʾiḍīn', 'Ve biz, dalanlarla birlikte dalıyorduk.'),
(74, 46, 29, 576, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ', 'wa kunnā nukadhibu bi-yawmi d-dīn', 'Ve din gününü yalanlıyorduk.'),
(74, 47, 29, 576, 'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ', 'ḥattā atānā l-yaqīn', 'Nihayet bize o kesin bilgi (ölüm) gelinceye kadar.'),
(74, 48, 29, 577, 'فَمَا تَنفَعُهُمْ شَفَٰعَةُ ٱلشَّٰفِعِينَ', 'famā tanfaʿuhum shafāʿatu sh-shāfiʿīn', 'Böylece onlara şefaatçilerin şefaati fayda vermez.'),
(74, 49, 29, 577, 'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ', 'famā lahum ʿani-t-tadhkirati muʿriḍīn', 'Onlara ne oluyor da öğütten yüz çeviriyorlar?'),
(74, 50, 29, 577, 'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ', 'kaʾannahum ḥumurun mustanfirah', 'Sanki onlar, ürkmüş (veya kaçışan) eşeklerdir.'),
(74, 51, 29, 577, 'فَرَّتْ مِن قَسْوَرَةٍۭ', 'farrat min qaswaratin', 'Aslanlar(dan) ürküp kaçmış.'),
(74, 52, 29, 577, 'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً', 'bal yurīdu kullu imriʾin minhum an yuʾtā ṣuḥufan munashsharatan', 'Hayır! Onlardan her bir kişi, kendisine açılmış sahifeler verilmesini ister.'),
(74, 53, 29, 577, 'كَلَّا بَل لَّا يَخَافُونَ ٱلْءَاخِرَةَ', 'kallā bal lā yakhāfūna l-ʾākhirah', 'Hayır! Onlar ahiretten korkmuyorlar.'),
(74, 54, 29, 577, 'كَلَّآ إِنَّهُۥ تَذْكِرَةٌ', 'kellā ʾinnahu tadhkiratun', 'Hayır! Şüphesiz ki o (Kur''an), bir öğüttür.'),
(74, 55, 29, 577, 'فَمَن شَآءَ ذَكَرَهُۥ', 'fe men şāʾa żakerahū', 'Artık dileyen ondan (Kur''an''dan) bir öğüt alır.'),
(74, 56, 29, 577, 'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ', 'wa mā yadhkurūna illā an yashāʾa allāhu huwa ʾahlu t-taqwā wa ʾahlu l-maghfirah', 'Ancak Allah dilerse hatırlayabilirler. O, takva (korkup sakınma) ehlidir ve mağfiret (bağışlama) ehlidir.'),
(75, 1, 29, 577, 'لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَٰمَةِ', 'lā uqsimu bi-yawmi l-qiyāmati', 'Hayır, kıyamet gününe yemin ederim.'),
(75, 2, 29, 577, 'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ', 'wa lā uqsimu bi-n-nafsi l-lawwāmati', 'Hayır, (kınayıp duran) nefse de yemin ederim.'),
(75, 3, 29, 577, 'أَيَحْسَبُ ٱلْإِنسَٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 'ʾayaḥsabu l-ʾinsānu ʾallannajmaʿa ʿiẓāmahū', 'İnsan, kendisinin kemiklerini bir araya toplayamayacağımızı mı sanır?'),
(75, 4, 29, 577, 'بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ', 'balā qādirīna ʿalā an nusawwiya banānahū', 'Hayır! Biz onun parmak uçlarını dahi (eski haline getirip) düzeltmeye kadiriz.'),
(75, 5, 29, 577, 'بَلْ يُرِيدُ ٱلْإِنسَٰنُ لِيَفْجُرَ أَمَامَهُۥ', 'bal yurīdu l-insānu liyafcura amāmahū', 'Hayır! İnsan, önündeki (kıyamet gününü) yalanlamak ister.'),
(75, 6, 29, 577, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَٰمَةِ', 'yas''alu ayyāna yawmu l-qiyāmah', 'Kıyamet günü ne zamanmış diye sorar.'),
(75, 7, 29, 577, 'فَإِذَا بَرِقَ ٱلْبَصَرُ', 'faʾiḏā bariqa l-baṣaru', 'Gözler kamaşıp (veya) perişan olduğu zaman'),
(75, 8, 29, 577, 'وَخَسَفَ ٱلْقَمَرُ', 'wa khasafa l-qamar', 'Ve Ay tutulmuştur.'),
(75, 9, 29, 577, 'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ', 'wa-jumiʿa sh-shamsu wa-l-qamaru', 'Ve güneş ve ay bir araya getirildiğinde.'),
(75, 10, 29, 577, 'يَقُولُ ٱلْإِنسَٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ', 'yaqūlu l-insānu yawmaʾiḏin ʾayna l-mafarru', 'İşte o gün insan: "Kaçış nereye?" der.'),
(75, 11, 29, 577, 'كَلَّا لَا وَزَرَ', 'kallā lā wazara', 'Hayır, sığınacak hiçbir yer yoktur!'),
(75, 12, 29, 577, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ', 'ilā rabbika yawmaʾiḏin al-mustaqarru', 'İşte o gün, varılacak yer (varıp karar kılacak) Rabbinedir.'),
(75, 13, 29, 577, 'يُنَبَّؤُا۟ ٱلْإِنسَٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ', 'yunab''bau l-insanu yawma''idim bima qaddama wa''akhkhara', 'O gün insan, önden gönderdiği ve geride bıraktığı şeylerle haberdar edilir.'),
(75, 14, 29, 577, 'بَلِ ٱلْإِنسَٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ', 'bal-i insānu ʿalā nafsihī baṣīrah', 'Hayır, insan kendi nefsi hakkında basiretlidir.'),
(75, 15, 29, 577, 'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ', 'Ve lev elkaa ma''aaziirehu', 'Velev elka ma''aaziirehu'),
(75, 16, 29, 577, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ', 'lā tuḥarrik bihī lisānaka litaʿjale bihī', 'Onunla (Kur''an''la), acele etmek için dilini kımıldatma!'),
(75, 17, 29, 577, 'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ', 'ʾinna ʿalaynā jamʿahū wa-qurʾānahū', 'Şüphesiz onu toplamak ve onu (okutmak) bize aittir.'),
(75, 18, 29, 577, 'فَإِذَا قَرَأْنَٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ', 'faʾiḏā qaraʾnāhu fāttabiʿ quriʾānahū', 'Onu okuduğumuz zaman sen de onun okunuşunu takip et.'),
(75, 19, 29, 577, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ', 'thumma inna ʿalaynā bayānahū', 'Sonra şüphe yok ki, onu beyan etmek de Bize aittir.'),
(75, 20, 29, 578, 'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ', 'kallā bal tuḥibbūna l-ʿājilah', 'Hayır! Siz acele olanı (dünyayı) seviyorsunuz.'),
(75, 21, 29, 578, 'وَتَذَرُونَ ٱلْءَاخِرَةَ', 'wa-tadharūna l-ʾākhirah', 'Ve ahireti bırakırsınız.'),
(75, 22, 29, 578, 'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ', 'wujūhun yawmaʾiḏin nāḍirah', 'Yüzler vardır o gün pırıl pırıl parlaktır.'),
(75, 23, 29, 578, 'إِلَىٰ رَبِّهَا نَاظِرَةٌ', 'ilā rabbihā nāẓirah', 'Rablerine bakmaktadırlar.'),
(75, 24, 29, 578, 'وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ', 'wa wujūhun yawmaʾiḏin bāsirah', 'Ve o gün nice yüzler de asık olacaktır.'),
(75, 25, 29, 578, 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ', 'taẓunnu an yufʿala bihā fāqirah', 'Onun hakkında, ''Onu ne yapıp çevirecekler?'' diye zanneder.'),
(75, 26, 29, 578, 'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ', 'kellā iḏā balagat at-tarāqiya', 'Hayır! Can köprücük kemiklerine dayandığı zaman,'),
(75, 27, 29, 578, 'وَقِيلَ مَنْ رَاقٍ', 'wa qīla man rāqin', 'Ve şöyle denir: "Tedavi edecek kimse var mı?"'),
(75, 28, 29, 578, 'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ', 'wa ẓanna annahu l-firāqu', 'Ve onun ayrılık olduğunu sanır.'),
(75, 29, 29, 578, 'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ', 'wa-ltāffati s-sāqu bi-s-sāqi', 'Ve bacak (veya baldır) bacağa (veya baldırına) dolandığı zaman.'),
(75, 30, 29, 578, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ', 'ilā rabbika yawmaʾiḏin al-masāq', 'İşte o gün, varılacak yer (varılacak) Rabbinedir.'),
(75, 31, 29, 578, 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', 'falā ṣaddeqa walā ṣallā', 'Artık inanmamış ve namaz da kılmamıştı.'),
(75, 32, 29, 578, 'وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ', 'wa lakin kadhdhaba wa tawalla', 'Hayır! O, yalanladı ve yüz çevirdi.'),
(75, 33, 29, 578, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ', 'thumma dhahaba ilā ahlihi yatamāṭā', 'Sonra da salına salına ailesine gitti.'),
(75, 34, 29, 578, 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', 'ʾawlā laka fa-ʾawlā', 'Yazıklar olsun sana, yine yazıklar olsun!'),
(75, 35, 29, 578, 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ', 'thumma ʾawlā laka fa-ʾawlā', 'Sonra, (o azap) sana daha layık, evet daha layık!'),
(75, 36, 29, 578, 'أَيَحْسَبُ ٱلْإِنسَٰنُ أَن يُتْرَكَ سُدًى', 'ʾayaḥsabual-ʾinsānu ʾan yutrakesudan', 'Yoksa insan, kendisinin başıboş bırakılacağını mı sanır?'),
(75, 37, 29, 578, 'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ', 'ʾelem yeku nuṭfatan mim-meniyyin yumnā', 'O, atılan bir damla sudan bir nutfe değil miydi?'),
(75, 38, 29, 578, 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ', 'thumma kāna ʿalaqatan fakhalqata fasawwā', 'Sonra o, bir pıhtı (alaka) olmuş, sonra Allah onu yaratmış ve en güzel şekilde biçimlendirmiştir.'),
(75, 39, 29, 578, 'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'fa jaʿala minhu z-zawjayni dh-dhakara wa-l-unthā', 'Böylece ondan erkeği ve dişiyi olmak üzere iki eşi var etti.'),
(75, 40, 29, 578, 'أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ', 'ʾalaysa dhālika biqādirin ʿalā ʾan yuḥyiya l-mawtā', 'Ölüleri diriltmeye gücü yeten bu (Allah) değil midir?'),
(76, 1, 29, 578, 'هَلْ أَتَىٰ عَلَى ٱلْإِنسَٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا', 'hal atā ʿalā l-ʾinsāni ḥīnun min-ad-dahri lam yakun šayʾan madhkūrā', 'İnsanın üzerinden, henüz anılır bir şey değilken, uzun bir zaman geçmedi mi?'),
(76, 2, 29, 578, 'إِنَّا خَلَقْنَا ٱلْإِنسَٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعًۢا بَصِيرًا', 'ʾinnā ḵalaqna-l-ʾinsāna min nuṭfatin ʾamšāǧin nabtalīhi fajaʿalnāhu samīʿan baṣīran', 'Doğrusu biz insanı, (rastgele) karışılmış bir nutfeden yarattık. Onu imtihan etmek için işiten ve gören (bir varlık) kıldık.'),
(76, 3, 29, 578, 'إِنَّا هَدَيْنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', 'ʾinnā hadaynāhu s-sabīla ʾimmā shākirān wa-ʾimmā kafūrā', 'Şüphesiz biz ona yolu gösterdik; (bu yolu) ya şükredici ya da nankör olarak (izleyebilir).'),
(76, 4, 29, 578, 'إِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَلَٰسِلَا۟ وَأَغْلَٰلًا وَسَعِيرًا', 'ʾinnā ʾaʿtadnā lil-kāfirīna salāsilā wa-ʾaḡlālā wa-saʿīrā', 'Şüphesiz biz kâfirlere zincirler, ateş ve çılgın alevli bir ateş hazırladık.'),
(76, 5, 29, 578, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 'inna l-ʾabrāra yašrabūna min kaʾsin kāna mizāǧuhā kāfūrā', 'Şüphesiz iyiler, içinde (mis kokulu) kâfûr karışımı olan bir kâseden içerler.'),
(76, 6, 29, 579, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 'ʿaynan yashrabu bihā ʿibādu llāhi yufecʿcirūnehā tefʿīrā', 'Allah''ın kulları, orayı bir pınar yaparak akıtırlar.'),
(76, 7, 29, 579, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', 'yūfūna bi-n-naḏri wa yaḫāfūna yawman kāna ḫarrruhuۥ musṭaṭīran', 'Onlar adaklarını yerine getirirler ve şerri yaygın olan bir günden korkarlar.'),
(76, 8, 29, 579, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', 'wa yuṭʿimūna ṭ-ṭaʿāma ʿalā ḥubbihī miskīnan wa yatīman wa ʾasīrā', 'Onlar, seve seve yiyeceği yoksula, yetime ve esire yedirirler.'),
(76, 9, 29, 579, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', 'innamā nuṭʿimukum liwajhi ʾllāhi lā nurīdu minkum jazāʾan walā shukūran', 'Biz sizi ancak Allah rızası için doyuruyoruz; sizden bir karşılık ve bir teşekkür beklemiyoruz.'),
(76, 10, 29, 579, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 'innā nakhāfu min rabbina yawman ʿabūsan ḳamṭarīrā', 'Şüphesiz biz, Rabbimizden (dolayı) o çetin ve belalı bir günde korkarız.'),
(76, 11, 29, 579, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', 'feveqāhumu llāhu şerra dhālika l-yawmi ve leqqāhumu naḍratan wa surūran', 'Böylece Allah onları o günün fenalığından korudu ve onlara bir güzellik ve sevinç verdi.'),
(76, 12, 29, 579, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', 'wa-jazāhum bimā ṣabarū jannatan wa-ḥarīran', 'Ve sabretmelerine karşılık onları cennete ve ipekli giysilere nail etti.'),
(76, 13, 29, 579, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', 'muttakiʾīna fīhā ʿalā al-ʾarāʾiki lā yarawna fīhā shamsan wa lā zamharīran', 'Onlar orada, koltuklara yaslanmışlardır. Orada ne yakıcı bir sıcaklık ne de dondurucu bir soğuk görürler.'),
(76, 14, 29, 579, 'وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', 'wa dāniyatan ʿalayhim ẓilāluhā wa ḏullilat quṭūfuhā ḏalīlan', 'Onların üzerlerine de gölgeleri sarkmış ve yemişleri (meyveleri) de bol bol (ve kolayca alınır) bir şekilde boyunlarını bükmüş olacaktır.'),
(76, 15, 29, 579, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', 'wa yuṭāfu ʿalayhim bi-ʾāniyatin min fiḍḍatin wa-ʾakwāba kānat qawārīrā', 'Onların etraflarında gümüş kaplar ve billur gibi kadehlerle dolaşılır.'),
(76, 16, 29, 579, 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 'qawārīrā min fiḍḍatin qaddarūhā taqdīrā', 'Gümüşten billur (kadehler)dir ki, onlar (hizmetçiler) tarafından saf bir şekilde ölçülüp hazırlanmıştır.'),
(76, 17, 29, 579, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', 'wa yusqawna fīhā kaʾsan kāna mizājuhā zanjabīlan', 'Onlara orada, zencefille karıştırılmış bir kâs (bardak) sunulur.'),
(76, 18, 29, 579, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', 'ʿaynan fīhā tusammā salsabīlā', 'Orada ''Salsabil'' diye adlandırılan bir pınardan (içerler).'),
(76, 19, 29, 579, 'وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', 'wa yaṭūfu ʿalayhim wildānu mukhallaḍūn iḏā raʾytahum ḥasibtahum luʾluʾan manṯūrā', 'Onların etrafında (hizmetleriyle) o ölümsüz genç hizmetçiler dolaşır. Onları gördüğünde, saçılmış inciler sanırsın.'),
(76, 20, 29, 579, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', 'wa ʾiḏā raʾayta ṯamma raʾayta naʿīman wa mulkan kabīran', 'Ve orada (o cennette) bir nimet ve büyük bir mülk görürsün.'),
(76, 21, 29, 579, 'عَٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', 'ʿāliyahum thiyābu sundusin khuḍrun wa-istabraqun wa-ḥullū ʾasāwira min fiḍḍatin wa-saqāhum rabbuhum sharāban ṭahūrā', 'Onların üzerlerinde yeşil ipekten ve işlemeli atlastan elbiseler vardır. Gümüş bileziklerle süslenmişlerdir ve Rableri onlara tertemiz bir içecek ikram etmiştir.'),
(76, 22, 29, 579, 'إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 'ʾinna hāḏā kāna lakum jazāʾan wa-kāna saʿyukum maškūrā', 'Şüphesiz bu, size bir mükâfat oldu; çalışmanız da karşılığını buldu.'),
(76, 23, 29, 579, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا', 'ʾinnā naḥnu nazzalnā ʿalayka l-qurʾāna tanzīlan', 'Şüphesiz o Kur''an''ı sana biz indirdik, hem de toim bir indirme.'),
(76, 24, 29, 579, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا', 'faṣbir liḥukmi rabbika walā tuṭiʿ minhum ʾāthiman ʾaw kafūrā', 'Şimdi Rabbinin hükmüne sabret. Onlardan günahkâr veya kâfir olana itaat etme.'),
(76, 25, 29, 579, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', 'wa-dh-kuri-sma-rabbika-bukrata-wa-aṣīlā', 'Sabah akşam Rabbinin adını an.'),
(76, 26, 29, 580, 'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا', 'wa-mina l-layli fa-sjud lahu wa- sabbihhu laylan tawīlan', 'Gecenin bir kısmında da O''na secde et ve geceleri uzun süre O''nu tesbih et.'),
(76, 27, 29, 580, 'إِنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا', 'ʾinna hāʾulāʾi yuḥibbūna l-ʿājilah wa yadharūna warāʾahum yawman thaqīlan', 'Şüphesiz bunlar, çarçabuk geçen dünyayı severler ve önlerindeki ağır bir günü (o ağır günün azabını) arkalarına bırakırlar.'),
(76, 28, 29, 580, 'نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَٰلَهُمْ تَبْدِيلًا', 'naḥnu ḵalaqnāhum wašadadnā ʾasrahum wa-iḏā šiʾnā baddalnā ʾamṯālahum tabdīlan', 'Onları biz yarattık ve iskeletlerini biz güçlendirdik. Dilediğimiz zaman da onların yerine benzerlerini getiririz.'),
(76, 29, 29, 580, 'إِنَّ هَٰذِهِۦ تَذْكِرَةٌ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 'ʾinna hāḏihi tadhkirah faman šāʾa ʾittaxaḏa ʾilā rabbihi sabīlā', 'Şüphesiz bu bir öğüttür. Artık dileyen kimse Rabbine (götüren) bir yol tutar.'),
(76, 30, 29, 580, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'Ve mâ teşâûne illâ en yeşâallâhu İnnallâhe kâne alîmen hakîmâ', 'Siz dilediğiniz gibi dileyemezsiniz; ancak Allah diler. Şüphesiz Allah, bilendir, hikmet sahibidir.'),
(76, 31, 29, 580, 'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا', 'yudkhilu man yashāʾu fī raḥmatihī wa-ẓ-ẓālimīna aʿadda lahum ʿadhāban alīman', 'Dilediğini rahmetine sokar. Zalimlere gelince, onlara da elem dolu bir azap hazırlamıştır.'),
(77, 1, 29, 580, 'وَٱلْمُرْسَلَٰتِ عُرْفًا', 'wa-l-murselāti ʿurfan', 'Ardarda gönderilenlere yemin olsun.'),
(77, 2, 29, 580, 'فَٱلْعَٰصِفَٰتِ عَصْفًا', 'fa-l-ʿāṣifāti ʿaṣfan', 'Kasırga gibi esenlere yemin olsun.'),
(77, 3, 29, 580, 'وَٱلنَّٰشِرَٰتِ نَشْرًا', 'wa-n-nāshirāti nashran', 'Yemin ederim gönderilip yayılanlara!'),
(77, 4, 29, 580, 'فَٱلْفَٰرِقَٰتِ فَرْقًا', 'fa-l-fāriqāti farqan', 'Ayıranlara yemin olsun ki, iyice ayırarak.'),
(77, 5, 29, 580, 'فَٱلْمُلْقِيَٰتِ ذِكْرًا', 'fa-l-mulqiyāti dhikran', 'Yemin ederim o meleklere ki, (vazifeleri gereği hakikati) telkin ederler.'),
(77, 6, 29, 580, 'عُذْرًا أَوْ نُذْرًا', 'ʿuḏran aw nuḏran', 'Özür dilemek veya uyarmak için.'),
(77, 7, 29, 580, 'إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ', 'ʾinnemā tūʿadūna lawāqiʿun', 'Şüphesiz size vaadedilen mutlaka gerçekleşecektir.'),
(77, 8, 29, 580, 'فَإِذَا ٱلنُّجُومُ طُمِسَتْ', 'faʾiḏā n-nujūmu ṭumiset', 'Yıldızlar ışığını kaybettiği zaman,'),
(77, 9, 29, 580, 'وَإِذَا ٱلسَّمَآءُ فُرِجَتْ', 'wa ʾiḏā s-samāʾu furijat', 'Gök yarıldığı zaman,'),
(77, 10, 29, 580, 'وَإِذَا ٱلْجِبَالُ نُسِفَتْ', 'wa-iḏā l-jibālu nusifat', 'Ve dağlar duman edildiği zaman,'),
(77, 11, 29, 580, 'وَإِذَا ٱلرُّسُلُ أُقِّتَتْ', 'wa ʾiḏā r-rusulu ʾuqqitat', 'Elçiler (o gün) vakti geldiğinde...'),
(77, 12, 29, 580, 'لِأَىِّ يَوْمٍ أُجِّلَتْ', 'li-ʾayyi yawmin ʾujjilat', 'Onun için, hangi güne ertelendi?'),
(77, 13, 29, 580, 'لِيَوْمِ ٱلْفَصْلِ', 'li-yawmi l-faṣli', 'O ayrım günü için.'),
(77, 14, 29, 580, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ', 'wa mā ʾadrāka mā yawmu l-faṣli', 'O hüküm günü nedir, sana ne bildirdi?'),
(77, 15, 29, 580, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawmaʾiḏin lilmukadḏibīn', 'İşte o gün, yalanlayanların vay haline!'),
(77, 16, 29, 580, 'أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ', 'ʾelem nuhlik-i l-ʾewwelīn', 'Onları helak etmedik mi?'),
(77, 17, 29, 580, 'ثُمَّ نُتْبِعُهُمُ ٱلْءَاخِرِينَ', 'thumma nutbiʿuhumu l-ʾākhirīn', 'Sonra, sonrakileri de peşlerine takarız.'),
(77, 18, 29, 580, 'كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 'kadhālika nafʿalu bil-mujrimīn', 'İşte biz, suçluları böyle cezalandırırız.'),
(77, 19, 29, 580, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawma''idhin lilmukadhdhibin', 'İşte o gün, yalanlayanların vay haline!'),
(77, 20, 29, 581, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ', 'ʾelem neḫlaḳkum mim māʾim mehīn', 'Sizi hakir bir sudan yaratmadık mı?'),
(77, 21, 29, 581, 'فَجَعَلْنَٰهُ فِى قَرَارٍ مَّكِينٍ', 'faǧaʿalnāhu fī qarārin makīn', 'Böylece onu sağlam bir yere yerleştirdik.'),
(77, 22, 29, 581, 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', 'ilā qaderin maʿlūmin', 'Bilinen bir zamana kadar.'),
(77, 23, 29, 581, 'فَقَدَرْنَا فَنِعْمَ ٱلْقَٰدِرُونَ', 'faqadarnā faniʿma l-qādirūn', 'Biz ölçtük, ne güzel ölçenleriz!'),
(77, 24, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawma''iḏin lilmuḵaḏibīn', 'O gün, yalanlayanların vay haline!'),
(77, 25, 29, 581, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا', 'ʾelem necaʿal-i l-ʾarḍa kifātan', 'Yeri bir toplayıcı kılmadık mı?'),
(77, 26, 29, 581, 'أَحْيَآءً وَأَمْوَٰتًا', 'aḥyāʾan wa-amwātan', 'Onları hem diri hem de ölü olarak (orada tutar).'),
(77, 27, 29, 581, 'وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَٰمِخَٰتٍ وَأَسْقَيْنَٰكُم مَّآءً فُرَاتًا', 'wa jaʿalnā fīhā rawāsīya shāmikhātin wa asqaynākum māʾan furātan', 'Ve orada sâbit, yüksek dağlar yarattık ve size tatlı su verdik.'),
(77, 28, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawmaʾiḏin lilmukadḏibīn', 'O gün, yalanlayanların vay haline!'),
(77, 29, 29, 581, 'ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', 'inṭaliqū ilā mā kuntum bihī tukedh''dhibūn', 'Yürüyün o yalanladığınız şeye!'),
(77, 30, 29, 581, 'ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَٰثِ شُعَبٍ', 'inṭaliqū ʾilā ẓillin dhī thalāthi shuʿabin', 'Haydi, üç dallı bir gölgeye gidin!'),
(77, 31, 29, 581, 'لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ', 'lā ẓalīlin wa lā yughnī mina l-lahabi', 'Ne gölge verir ne de ateşin alevinden korur.'),
(77, 32, 29, 581, 'إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ', 'ʾinnahā tarmī bišararin kalqaṣri', 'Şüphesiz o (cehennem), koca koca saraylar gibi kıvılcımlar saçar.'),
(77, 33, 29, 581, 'كَأَنَّهُۥ جِمَٰلَتٌ صُفْرٌ', 'kaʾannahu ǧimālatun ṣufru', 'Sanki o (ateş), sarı deve sürüsü gibidir.'),
(77, 34, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawmaʾiḏin lilmukadḏibīn', 'İşte o gün, yalanlayanların vay haline!'),
(77, 35, 29, 581, 'هَٰذَا يَوْمُ لَا يَنطِقُونَ', 'hādhā yawmu lā yanṭiqūna', 'Bu, konuşamayacakları bir gündür.'),
(77, 36, 29, 581, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', 'wa-lā yuʾḏanu lahum fa-yaʿtaḏirūn', 'Onlara (özür dilemeleri için) izin verilmez de (boşuna) özür beyan ederler.'),
(77, 37, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawma''idhin lilmukadhdhibin', 'İşte o gün, yalanlayanların vay haline!'),
(77, 38, 29, 581, 'هَٰذَا يَوْمُ ٱلْفَصْلِ جَمَعْنَٰكُمْ وَٱلْأَوَّلِينَ', 'hādhā yawmu l-faṣli jamaʿnākum wa-l-ʾawwalīna', 'Bu, hakkı batıldan ayırma günüdür; sizi ve öncekileri bir araya topladık.'),
(77, 39, 29, 581, 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', 'faʾin kāna lakum kaydun fakīdūni', 'Eğer bir hileli düzeniniz varsa, bana karşı uygulayın!'),
(77, 40, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawmaʾiḏin lil-mukaḏḏibīn', 'O gün, yalanlayanların vay haline!'),
(77, 41, 29, 581, 'إِنَّ ٱلْمُتَّقِينَ فِى ظِلَٰلٍ وَعُيُونٍ', 'inna l-muttaqīna fī ẓilālin wa-ʿuyūnin', 'Şüphesiz takva sahipleri, gölgeler ve pınarlar içindedir.'),
(77, 42, 29, 581, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ', 'wa fawākiham mimmā yashtahūn', 'Ve canlarının çektiği meyveler.'),
(77, 43, 29, 581, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 'kulū wa-shrū hanīʾan bimā kuntum taʿmalūn', 'Yiyin ve için, yaptıklarınıza karşılık afiyetle!'),
(77, 44, 29, 581, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 'ʾinnā kaḏālika naǧzī l-muḥsinīn', 'Şüphesiz biz, iyilik yapanları işte böyle mükafatlandırırız.'),
(77, 45, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawmaʾiḏin lil-mukaḏḏibīn', 'İşte o gün, yalanlayanların vay haline!'),
(77, 46, 29, 581, 'كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ', 'kulū wa tamattaʿū qalīlan ʾinnakum mujrimūn', 'Yiyin ve biraz geçinin. Şüphesiz siz suçlusunuz.'),
(77, 47, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawma''idhin lilmukadhdhibin', 'O gün, yalanlayanların vay haline!'),
(77, 48, 29, 581, 'وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ', 'wa-ʾiḏā qīla lahumu irkaʿū lā yarkaʿūna', 'Onlara, ''Rükû edin!'' dendiği zaman rükû etmezler.'),
(77, 49, 29, 581, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawmaʾiḏin lil-mukaḏḏibīn', 'O gün, yalanlayanların vay haline!'),
(77, 50, 29, 581, 'فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 'fa-bi-ʾayyi ḥadīthin baʿdahū yuʾminūn', 'Artık ondan sonra hangi söze inanırlar?'),
(78, 1, 30, 582, 'عَمَّ يَتَسَآءَلُونَ', 'ʿammā yatasaʾalūn', 'O büyük haberi soruyorlar?'),
(78, 2, 30, 582, 'عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ', 'ʿani n-nabai l-ʿaẓīm', 'O büyük haberden (dolayı).'),
(78, 3, 30, 582, 'ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ', 'alladhī hum fīhi mukhtalifūn', 'Onların hakkında anlaşmazlığa düştükleri şey.'),
(78, 4, 30, 582, 'كَلَّا سَيَعْلَمُونَ', 'kallā sayaʿlamūn', 'Hayır! Yakında bilecekler.'),
(78, 5, 30, 582, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', 'thumma kallā sayaʿlamūn', 'Sonra, hayır; (bu yaptıklarının sonucunu) yakında bilecekler.'),
(78, 6, 30, 582, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَٰدًا', 'ʾelem necali l-ʾarḍa mihādan', 'Yeri bir döşek yapmadık mı?'),
(78, 7, 30, 582, 'وَٱلْجِبَالَ أَوْتَادًا', 'wa-l-jibāla ʾawtādā', 'Ve dağları da birer kazık (temel) yapmadık mı?'),
(78, 8, 30, 582, 'وَخَلَقْنَٰكُمْ أَزْوَٰجًا', 'wa ḫalaqnākum azwāǧan', 'Ve sizi çiftler halinde yarattık.'),
(78, 9, 30, 582, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا', 'wa-jaʿalnā nawmakum subātan', 'Uykunuzu bir dinlenme (veya kesilme) kıldık.'),
(78, 10, 30, 582, 'وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا', 'wa jaʿalnā al-layla libāsan', 'Ve geceyi bir örtü yaptık.'),
(78, 11, 30, 582, 'وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا', 'wa-jaʿalnā an-nahāra maʿāshan', 'Ve gündüzü bir geçim (vakti) kıldık.'),
(78, 12, 30, 582, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا', 'wa banaynā fawqakum sabʿan shidādā', 'Ve sizin üstünüze yedi (kat) sağlam (gök) bina ettik.'),
(78, 13, 30, 582, 'وَجَعَلْنَا سِرَاجًا وَهَّاجًا', 'wa jaʿalnā sirājan wahhājan', 'Ve (orayı) bir lamba (veya ışık kaynağı) ve parıldayan bir kandil yaptık.'),
(78, 14, 30, 582, 'وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا', 'waʾanzalnā mina l-muʿṣirāti māʾan thajjājan', 'Ve biz, (bulutlardan) bol bol akan bir su indirdik.'),
(78, 15, 30, 582, 'لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا', 'li-nukhrija bi-hi habban wa-nabātā', 'Onunla taneler ve bitkiler çıkaralım diye.'),
(78, 16, 30, 582, 'وَجَنَّٰتٍ أَلْفَافًا', 'wa-jannātin ʾalfāfan', 'Ve sarmaşıklarla dolu bahçeler.'),
(78, 17, 30, 582, 'إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَٰتًا', 'ʾinna yawma l-faṣli kāna mīqātā', 'Şüphesiz ki fasıl (hak ile batılın ayrılacağı) günü belirlenmiş bir vakittir.'),
(78, 18, 30, 582, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا', 'yawma yunfakhu fīṣ-ṣūri fataʾtūna ʾafwājan', 'Sur''a üflendiği gün sizi bölük bölük getireceğiz.'),
(78, 19, 30, 582, 'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا', 'wa futiḥati s-samāʾu fa kānat abwāban', 'Gök yarılmış ve kapı kapı olmuştur.'),
(78, 20, 30, 582, 'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا', 'wa suyyerat-i l-jibālu fa kānat sarāban', 'Dağlar da yürütülür ve bir serap haline gelir.'),
(78, 21, 30, 582, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', 'ʾinna Jahannama kānat mirṣādā', 'Şüphesiz cehennem bir gözetleme yeridir.'),
(78, 22, 30, 582, 'لِّلطَّٰغِينَ مَـَٔابًا', 'liṭ-ṭāġīna maʾāban', 'Onlar için azgınların dönüş yeri orasıdır.'),
(78, 23, 30, 582, 'لَّٰبِثِينَ فِيهَآ أَحْقَابًا', 'lābiṯīna fīhā ʾaḥqābā', 'Orada çağlar boyunca kalacaklardır.'),
(78, 24, 30, 582, 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', 'lā yaḏūqūna fīhā bardan walā šarābā', 'Orada ne serinlik tadarlar ne de bir içecek.'),
(78, 25, 30, 582, 'إِلَّا حَمِيمًا وَغَسَّاقًا', 'ʾillā ḥamīman wa-ghassāqan', 'Ancak bir kaynar su ve irin (vardır).'),
(78, 26, 30, 582, 'جَزَآءً وِفَاقًا', 'jazāʾan wifāqan', 'Onların yaptıklarına karşılık bir mükafat (veya ceza) olarak.'),
(78, 27, 30, 582, 'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا', 'innahum kānū lā yarjūna ḥisābā', 'Çünkü onlar hesaba çekilmeyi ummazlardı.'),
(78, 28, 30, 582, 'وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًا', 'wa kadhthabū bi-āyātinā kidhābā', 'Ve âyetlerimizi yalanladılar, tam bir yalanlama.'),
(78, 29, 30, 582, 'وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًا', 'wa kulla shay''in aḥṣaynāhu kitāban', 'Ve her şeyi sayıp tespit ettik, bir kitapta.'),
(78, 30, 30, 582, 'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', 'faḏūqū falan nazīdakum illā ʿaḏāban', 'Artık tadın! Biz de size azaptan başka bir şey artırmayacağız.'),
(78, 31, 30, 583, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', 'ʾinna lilmuttaqīna mafāzan', 'Şüphesiz takva sahipleri için bir kurtuluş ve mutluluk yeri vardır.'),
(78, 32, 30, 583, 'حَدَآئِقَ وَأَعْنَٰبًا', 'ḥadāʾiqa wa-aʿnāban', 'Bahçeler ve üzümler.'),
(78, 33, 30, 583, 'وَكَوَاعِبَ أَتْرَابًا', 'wa kawāʿiba atrābā', 'Ve göğüsleri tomurcuklanmış, yaşları bir olanlar.'),
(78, 34, 30, 583, 'وَكَأْسًا دِهَاقًا', 'wa kaʾsan dihāqan', 'Ve dolu dolu kadehler.'),
(78, 35, 30, 583, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا', 'lā yasmaʿūna fīhā laghwan walā kidhābā', 'Orada ne boş bir söz işitirler ne de yalan.'),
(78, 36, 30, 583, 'جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا', 'jazāʾan mimm rabbika ʿaṭāʾan ḥisābā', 'Bunlar, Rabbinden birer mükâfat, (yapılanların) kâfi bir ihsanıdır.'),
(78, 37, 30, 583, 'رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ لَا يَمْلِكُونَ مِنْهُ خِطَابًا', 'rabbis-semāwāti wal-arḍi wa mā baynahumā r-raḥmān lā yamlikūna minhu khiṭābā', 'Göklerin, yerin ve ikisi arasında bulunanların Rabbi, (O) Rahman''dır. Onlar O''ndan bir söz (söz söyleme) hakkına sahip olamazlar.'),
(78, 38, 30, 583, 'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّا لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًا', 'yawma yaqūmu ar-rūḥu wal-malāʾikatu ṣaffan lā yatakallamūna ʾillā man ʾadhina lahu ar-raḥmānu waqāla ṣawāban', 'Ruh ve melekler saf saf durduğu o gün, Rahman''ın izin verdiği ve doğruyu söylediği kimseler dışında hiç kimse konuşamaz.'),
(78, 39, 30, 583, 'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا', 'dhālika l-yawmu l-ḥaqqu faman shāʾa t-takhadha ilā rabbihī maʾāban', 'İşte o gün, hak olan gündür. Artık kim dilerse Rabbine bir dönüş yolu tutar.'),
(78, 40, 30, 583, 'إِنَّآ أَنذَرْنَٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا', 'ʾinnā ʾanḏarnākum ʿaḏāban qarīban yawma yanẓuru l-marʾu mā qaddamat yadāhu wa-yaqūlu l-kāfiru yā-laytanī kuntu turāban', 'Şüphesiz biz sizi, (o) yakın bir günde olacak azaptan uyardık. O gün kişi, elleriyle neyi öne sürdüğüne bakacak ve o kâfir: "Keşke ben bir toprak olsaydım!" diyecektir.'),
(79, 1, 30, 583, 'وَٱلنَّٰزِعَٰتِ غَرْقًا', 'wa-n-nāziʿāti ġarqan', 'Yemin olsun o (ruhları) çekip çıkaranlara!'),
(79, 2, 30, 583, 'وَٱلنَّٰشِطَٰتِ نَشْطًا', 'wa-n-nāshiṭāti nashṭan', 'Yemin ederim o (ruhları) çekip çıkaranlara, bir de (kalplerinden) çekip alanlara!'),
(79, 3, 30, 583, 'وَٱلسَّٰبِحَٰتِ سَبْحًا', 'wa-s-sābiḥāti sabḥan', 'Yemin ederim o (ruhları) çekip çıkaranlara.'),
(79, 4, 30, 583, 'فَٱلسَّٰبِقَٰتِ سَبْقًا', 'fa-s-sābiqāti sabqan', 'İşte (emirleri) öne geçenlere yemin ederim.'),
(79, 5, 30, 583, 'فَٱلْمُدَبِّرَٰتِ أَمْرًا', 'fa-l-mudabbirāti amran', 'İşleri yönetenlere (yemin ederim ki)'),
(79, 6, 30, 583, 'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ', 'yawma tarjufu ʾar-rājifatu', 'O gün, o sarsıcı olan sarsar.'),
(79, 7, 30, 583, 'تَتْبَعُهَا ٱلرَّادِفَةُ', 'tatbaʿuhā r-rādifatu', 'Onun peşinden (ikinci olarak) Râdife gelir.'),
(79, 8, 30, 583, 'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ', 'qulūbun yawmaʾiḏin wājiifatun', 'O gün kalpler endişeyle çarpar.'),
(79, 9, 30, 583, 'أَبْصَٰرُهَا خَٰشِعَةٌ', 'abṣāruhā khāshiʿah', 'Gözleri dehşetten derinleşmiş olacaktır.'),
(79, 10, 30, 583, 'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ', 'yaqūlūna ʾa-ʾinnanā la-mardūdūna fī l-ḥāfirah', 'Onlar şöyle derler: "Gerçekten biz, (ölüp) geriye dönenler miyiz?"'),
(79, 11, 30, 583, 'أَءِذَا كُنَّا عِظَٰمًا نَّخِرَةً', 'ʾaʾiḏā kunnā ʿiẓāman nakhiratan', 'Biz kemikler haline geldikten sonra!'),
(79, 12, 30, 583, 'قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ', 'qālū tilka iḏan karratun ḫāsiratun', 'Onlar, "O halde bu, bize zararlı bir dönüştür!" dediler.'),
(79, 13, 30, 583, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ', 'fa-ʾinnama hiya zajratun wāḥidatun', 'O halde, (onları yerden kaldıracak olan) tek bir sayha (kıyamet suru)dır.'),
(79, 14, 30, 583, 'فَإِذَا هُم بِٱلسَّاهِرَةِ', 'fa-ʾiḏā hum bi-s-sāhirah', 'Bir de bakarsın ki onlar, mahşer yerinde uyanmışlardır.'),
(79, 15, 30, 583, 'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'hal atāka ḥadīthu mūsā', 'Musa''nın haberi sana geldi mi?'),
(79, 16, 30, 584, 'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 'iḏ nādāhu rabbuhuۥ bil-wādi l-muqaddasi ṭuvā', 'Hani Rabbi ona mukaddes vadi Tuvâ''da şöyle nida etmişti:'),
(79, 17, 30, 584, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 'idhhab ilā Fir''awn innahuu ṭaghā', 'Firavun''a git! Çünkü o azdı.'),
(79, 18, 30, 584, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ', 'faqul hal laka ilā an tazakkā', 'Şimdi de ki: ''Sana, arınmaya bir yol var mı?'''),
(79, 19, 30, 584, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ', 'wa-ʾahdiyaka ʾilā rabbika fataḵšā', 'Ve seni Rabbine ulaştırıp da O''ndan (gereğince) korkmanı sağlayacağım.'),
(79, 20, 30, 584, 'فَأَرَىٰهُ ٱلْءَايَةَ ٱلْكُبْرَىٰ', 'faʾarāhu l-ʾāyata l-kubrā', 'Böylece ona en büyük delili gösterdi.'),
(79, 21, 30, 584, 'فَكَذَّبَ وَعَصَىٰ', 'fa-kaḏḏaba wa-ʿaṣā', 'Böylece yalanladı ve isyan etti.'),
(79, 22, 30, 584, 'ثُمَّ أَدْبَرَ يَسْعَىٰ', 'thumma adbara yasʿā', 'Sonra arkasını dönüp koştu.'),
(79, 23, 30, 584, 'فَحَشَرَ فَنَادَىٰ', 'faḥašara fanādā', 'Böylece (insanları) topladı da seslendi.'),
(79, 24, 30, 584, 'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ', 'faqāla ʾanā rabbukumū l-ʾaʿlā', 'Böylece dedi ki: Ben sizin en yüce Rabbinizim!'),
(79, 25, 30, 584, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْءَاخِرَةِ وَٱلْأُولَىٰٓ', 'faʾakhaḏahu ʾallāhu nakāla ʾal-ʾāḵirati wa-l-ʾūlā', 'Bunun üzerine Allah onu hem önceki hem de sonraki azapla yakaladı.'),
(79, 26, 30, 584, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ', 'ʾinna fī ḏālika la-ʿibratan li-man yaḫšā', 'Şüphesiz bunda, (Allah''tan) korkan kimseler için elbette bir ibret vardır.'),
(79, 27, 30, 584, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ بَنَىٰهَا', 'ʾa ʾantum ʾašaddu ḫalqan ʾam as-samāʾu banāhā', 'Sizi yaratmak mı daha zordur, yoksa göğü yaratmak mı? (Onu) Allah bina etmiştir.'),
(79, 28, 30, 584, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', 'rafaʿa samkahā fasawwāhā', 'Onun tavanını yükseltti ve onu düzene soktu.'),
(79, 29, 30, 584, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', 'waʾaġṭaša laylahā waʾaḫraja ḍuḥāhā', 'Gecesini kararttı ve gündüzünü (açığa çıkarıp) ortaya çıkardı.'),
(79, 30, 30, 584, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', 'wa-l-arḍa baʿda dhālika daḥāhā', 'Yeri de bundan sonra uzatıp yaydı.'),
(79, 31, 30, 584, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', 'ʾakhraja minhā māʾahā wa-marʿāhā', 'O, ondan suyunu ve otlağını çıkardı.'),
(79, 32, 30, 584, 'وَٱلْجِبَالَ أَرْسَىٰهَا', 'wa-l-jibāla arsāhā', 'Dağları da yerleştirdi.'),
(79, 33, 30, 584, 'مَتَٰعًا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 'matāʿan lakum wa li-ʾanʿāmikum', 'Size ve hayvanlarınıza bir yarar (veya geçimlik) olmak üzere.'),
(79, 34, 30, 584, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', 'fa-iḏā ǧāʾat aṭ-ṭāmmatu l-kubrā', 'Nihayet o büyük felâket (kıyamet) geldiği zaman,'),
(79, 35, 30, 584, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ', 'yawma yatadhakkaru l-insānu mā saʿā', 'O gün insan yaptıklarını hatırlar.'),
(79, 36, 30, 584, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', 'wa burrizati l-jaḥīmu li-man yarā', 'Ve cehennem, görenler için açıkça ortaya konmuştur.'),
(79, 37, 30, 584, 'فَأَمَّا مَن طَغَىٰ', 'faʾammā man ṭaḡā', 'Artık kim azgınlık etmişse,'),
(79, 38, 30, 584, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'wa-āthara al-ḥayāta ad-dunyā', 'Ve dünya hayatını tercih edene.'),
(79, 39, 30, 584, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', 'fa-inna l-ǧaḥīma hiya l-maʾwā', 'Cehennem, (onların) varacağı yerdir.'),
(79, 40, 30, 584, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', 'waʾammā man ḵāfa maqāma rabbihī wanahā n-nafsa ʿani l-hawā', 'Rabbinin makamından korkan ve nefisini heveslerden men eden kimse ise...'),
(79, 41, 30, 584, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', 'fa-inna l-jannata hiya l-maʾwā', 'Şüphesiz ki barınak olan cennettir.'),
(79, 42, 30, 584, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', 'yas''alūnak ''ani s-sā''ati ayyāna mursāhā', 'Sana o saati soruyorlar: "Onun demir atma (vuku bulma) vakti ne zamandır?"'),
(79, 43, 30, 584, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', 'fīmā anta min dhikrāhā', 'Onu (kıyameti) anmaktan sen ne (halde-sin)?'),
(79, 44, 30, 584, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', 'ilā rabbika muntahāhā', 'Onların sonu Rabbinedir.'),
(79, 45, 30, 584, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', 'innamā anta mundhiru man yakhshāhā', 'Onu ancak ondan korkan kimseleri uyarabilirsin.'),
(79, 46, 30, 584, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', 'kaʾannahum yawma yarawnahā lam yalbaşū ʾillā ʿashiyyatan ʾaw ḍuḥāhā', 'Onlar, o azabı gördükleri gün, (sanki dünyada) sadece bir akşam veya kuşluk vakti kadar kalmışlardır.'),
(80, 1, 30, 585, 'عَبَسَ وَتَوَلَّىٰٓ', 'ʿabasa wa-tawallā', 'Yüzünü ekşitti ve döndü.'),
(80, 2, 30, 585, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', 'ʾan jāʾahu l-ʾaʿmā', 'O, kendisine kör geldiği için yüzünü ekşitti ve döndü.'),
(80, 3, 30, 585, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', 'wa mā yudrīka laʿallahu yazzakkā', 'Oysa onun temizlenip arınacağını nereden bilebilirsin?'),
(80, 4, 30, 585, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', 'ʾaw yataḏḏakkaru fatanfaʿahu ḏ-ḏikrā', 'Yahut öğüt alıp da bu öğüdün kendisine fayda vereceği bir zamanı.'),
(80, 5, 30, 585, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', 'ʾammā man-istaghnā', 'Hayır! Doğrusu bu (Kur''an) bir öğüttür.'),
(80, 6, 30, 585, 'فَأَنتَ لَهُۥ تَصَدَّىٰ', 'fa-ʾanta lahu taṣaddā', 'Sen ise ona yöneliyorsun.'),
(80, 7, 30, 585, 'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ', 'wa mā ʿalayka allā yazzakkā', 'Onların temizlenmemeleri sana ne (zarar verir)?'),
(80, 8, 30, 585, 'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ', 'waʾammā man jāʾaka yasʿā', 'Ancak sana koşarak gelene gelince,'),
(80, 9, 30, 585, 'وَهُوَ يَخْشَىٰ', 'wa huwa yakhshā', 'Ve o, kendisi saygı duyuyor.'),
(80, 10, 30, 585, 'فَأَنتَ عَنْهُ تَلَهَّىٰ', 'fa-anta ʿanhu talahhā', 'Sen ise ondan yüz çeviriyorsun.'),
(80, 11, 30, 585, 'كَلَّآ إِنَّهَا تَذْكِرَةٌ', 'kallā innahā taẕkirah', 'Hayır! O (Kur''an) bir öğüttür.'),
(80, 12, 30, 585, 'فَمَن شَآءَ ذَكَرَهُۥ', 'fe-men shāʾa dhakarahū', 'Artık kim dilerse onu hatırlar.'),
(80, 13, 30, 585, 'فِى صُحُفٍ مُّكَرَّمَةٍ', 'fī ṣuḥufim mukarramah', 'Onlar, değerli sahifelerdedir.'),
(80, 14, 30, 585, 'مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ', 'marfūʿatin muṭahharatin', 'Yüceltilmiş, temizlenmiş olarak.'),
(80, 15, 30, 585, 'بِأَيْدِى سَفَرَةٍ', 'bi-ʾaydī safareti', 'Ellerde, (yüksek) derecelerde bulunan, (Allah''ın emirlerini yerine getiren) yazıcı melekler tarafından.'),
(80, 16, 30, 585, 'كِرَامٍۭ بَرَرَةٍ', 'kirāmin bararah', 'Kerim ve berer olanlar.'),
(80, 17, 30, 585, 'قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ', 'qutila l-insānu mā akfarahu', 'İnsan kahrolası! Ne kadar da nankör!'),
(80, 18, 30, 585, 'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ', 'min ayyi shayʾin khalaqahū', 'Onu hangi şeyden yarattı?'),
(80, 19, 30, 585, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', 'min nuṭfatin ḫalaqahū faqaddarahū', 'Bir nutfeden onu yarattı, ona (vücut ve şekil) verdi.'),
(80, 20, 30, 585, 'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ', 'thumma s-sabīla yassarahū', 'Sonra ona yolu kolaylaştırdı.'),
(80, 21, 30, 585, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ', 'thumma amātahu faʾaqbarahu', 'Sonra onu öldürdü ve kabre koydurdu.'),
(80, 22, 30, 585, 'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ', 'thumma idhā shāʾa ansharahu', 'Sonra, dilediği zaman onu tekrar diriltecektir.'),
(80, 23, 30, 585, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ', 'kallā lammā yaqḍi mā ʾamarahū', 'Hayır! O, emredileni henüz yerine getirmedi.'),
(80, 24, 30, 585, 'فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ', 'fal-yanẓuri l-insānu ʾilā ṭaʿāmihī', 'İnsan kendi yiyeceğine bir bakıversin!'),
(80, 25, 30, 585, 'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا', 'annā ṣababnā l-māʾa ṣabbā', 'Doğrusu biz, bol bol yağmur yağdırmışızdır.'),
(80, 26, 30, 585, 'ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّا', 'thumma shaqqanā l-arḍa shaqqan', 'Sonra toprağı, ondan bitkiler bitirmek üzere yardık.'),
(80, 27, 30, 585, 'فَأَنۢبَتْنَا فِيهَا حَبًّا', 'faʾanbatnā fīhā ḥabbā', 'Onunla taneler bitirdik.'),
(80, 28, 30, 585, 'وَعِنَبًا وَقَضْبًا', 'wa ʿinaban wa qaḍbā', 'Ve üzüm ve yeşillikler.'),
(80, 29, 30, 585, 'وَزَيْتُونًا وَنَخْلًا', 'wa-zaytūnan wa-nakhlan', 'Ve zeytin ve hurma.'),
(80, 30, 30, 585, 'وَحَدَآئِقَ غُلْبًا', 'wa ḥadāʾiqa ḡulban', 'Ve bağlar, ağaçlarla dolu.'),
(80, 31, 30, 585, 'وَفَٰكِهَةً وَأَبًّا', 'wa fākihah-tan wa abban', 'Hem meyve hem de ot (bitki örtüsü) olarak.'),
(80, 32, 30, 585, 'مَّتَٰعًا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 'matāʿan lakum wa-li-anʿāmikum', 'Sizin ve hayvanlarınızın yararlanması için.'),
(80, 33, 30, 585, 'فَإِذَا جَآءَتِ ٱلصَّآخَّةُ', 'faʾiḏā ǧāʾati ṣ-ṣāḫḫah', 'Derken, kulakları sağır eden o büyük felaket geldiğinde!'),
(80, 34, 30, 585, 'يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ', 'yawma yafirru l-marʾu min ʾakhīhi', 'O gün insan, kardeşinden kaçar.'),
(80, 35, 30, 585, 'وَأُمِّهِۦ وَأَبِيهِ', 'wa-ummihi wa-abiihi', 'Ve annesine ve babasına.'),
(80, 36, 30, 585, 'وَصَٰحِبَتِهِۦ وَبَنِيهِ', 'wa ṣāḥibatihi wa banīhi', 'Ve eşini ve çocuklarını.'),
(80, 37, 30, 585, 'لِكُلِّ ٱمْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ', 'likulli-mri''im minhum yawma''idhin sha''nun yughnīhi', 'Her birine o gün, kendi başından aşkın bir iş vardır.'),
(80, 38, 30, 585, 'وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ', 'wujūhun yawmaʾiḏin musfirah', 'O gün, birtakım yüzler de parıl parıl güler.'),
(80, 39, 30, 585, 'ضَاحِكَةٌ مُّسْتَبْشِرَةٌ', 'ḍāḥikatun mustabshiratun', 'Gülüşmekte ve sevinmektedirler.'),
(80, 40, 30, 585, 'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ', 'wa wujūhun yawmaʾiḏin ʿalayhā ḡabaratun', 'Ve o gün öyle yüzler de vardır ki, üzerlerini bir toz (toz toprak) bürümüş olur.'),
(80, 41, 30, 585, 'تَرْهَقُهَا قَتَرَةٌ', 'tarhahuhā qatarah', 'Onları bir karanlık kaplar.'),
(80, 42, 30, 585, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ', 'ʾulāʾika humu l-kafarat u l-fajarah', 'İşte bunlardır kâfirler, günahkârlar.'),
(81, 1, 30, 586, 'إِذَا ٱلشَّمْسُ كُوِّرَتْ', 'iḏā š-šamsu kuwwirat', 'Güneş dürüldüğü zaman,'),
(81, 2, 30, 586, 'وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ', 'wa-idhā n-nujūmu nkadarat', 'Ve yıldızlar döküldüğü zaman,'),
(81, 3, 30, 586, 'وَإِذَا ٱلْجِبَالُ سُيِّرَتْ', 'wa-idhā l-jibālu suyyirat', 'Ve dağlar yürütüldüğünde,'),
(81, 4, 30, 586, 'وَإِذَا ٱلْعِشَارُ عُطِّلَتْ', 'wa ʾiḏā l-ʿišāru ʿuṭṭilat', 'Ve develer (sahiplerinden) boş bırakıldığı zaman,'),
(81, 5, 30, 586, 'وَإِذَا ٱلْوُحُوشُ حُشِرَتْ', 'wa-ʾiḏā l-wuḥūshu ḥuširat', 'Vahşi hayvanlar toplandığı zaman,'),
(81, 6, 30, 586, 'وَإِذَا ٱلْبِحَارُ سُجِّرَتْ', 'wa ʾiḏā l-biḥāru sujjiṟat', 'Ve denizler kaynatıldığı zaman,'),
(81, 7, 30, 586, 'وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ', 'wa ʾiḏā n-nufūsu zuwwijat', 'Ve nefisler (insanlar) eşleştirildiği zaman,'),
(81, 8, 30, 586, 'وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ', 'wa ʾiḏā l-mawʾūdatu suʾilat', 'Ve diri diri gömülen kız çocuğuna sorulduğu zaman,'),
(81, 9, 30, 586, 'بِأَىِّ ذَنۢبٍ قُتِلَتْ', 'bi-ʾayyi ḏambin qutilat', 'Hangi günah sebebiyle öldürüldü?'),
(81, 10, 30, 586, 'وَإِذَا ٱلصُّحُفُ نُشِرَتْ', 'wa ʾiḏā ṣ-ṣuḥufu nuširat', 'Ve (o) sahifeler yayıldığı zaman,'),
(81, 11, 30, 586, 'وَإِذَا ٱلسَّمَآءُ كُشِطَتْ', 'wa-idhā s-samāʾu kushṭat', 'Gök, sıyrılarak soyulduğu zaman,'),
(81, 12, 30, 586, 'وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ', 'waʾiḏā l-ǧaḥīmu suʿʿirat', 'Ve cehennem alevlendirildiği zaman,'),
(81, 13, 30, 586, 'وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ', 'waʾiḏā l-jannatu ʾuzlifat', 'Ve cennet (o gün) yaklaştırıldığı zaman.'),
(81, 14, 30, 586, 'عَلِمَتْ نَفْسٌ مَّآ أَحْضَرَتْ', 'ʿalimatu nafsun mā ʾaḥḍarat', 'Her nefis, ne hazırladığını öğrenmiştir.'),
(81, 15, 30, 586, 'فَلَآ أُقْسِمُ بِٱلْخُنَّسِ', 'falā uqsimu bil-khunansi', 'Hayır, (yıldızların geri çekilmesi gibi) geri dönenlere, gizlenenlere yemin ederim.'),
(81, 16, 30, 586, 'ٱلْجَوَارِ ٱلْكُنَّسِ', 'al-jawāri al-kunnaṣi', 'Geri çekilip gizlenenlere, (yörüngelerinde) gizlice seyredenlere yemin ederim ki,'),
(81, 17, 30, 586, 'وَٱلَّيْلِ إِذَا عَسْعَسَ', 'wa-l-layli iḏā ʿasʿasa', 'Karanlığı çöküp örtmeye başladığı zaman geceye yemin ederim ki,'),
(81, 18, 30, 586, 'وَٱلصُّبْحِ إِذَا تَنَفَّسَ', 'waṣ-ṣubḥi iḏā tanaffasa', 'Nefes aldığı zaman sabaha ki,'),
(81, 19, 30, 586, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', 'ʾinnahu laqawlu rasūlin karīm', 'Şüphesiz ki o (Kur''an), kerim (değerli, şerefli) bir resulün sözüdür.'),
(81, 20, 30, 586, 'ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍ', 'dhī quwwatin ʿinda dhī l-ʿarshi makīn', 'Arşın sahibi katında, güçlü, yüksek makam sahibi olan.'),
(81, 21, 30, 586, 'مُّطَاعٍ ثَمَّ أَمِينٍ', 'muṭāʿin thamma ʾamīnin', 'O, (göğe yükseltilip) itaat edilen, sonra da güvenilen biridir.'),
(81, 22, 30, 586, 'وَمَا صَاحِبُكُم بِمَجْنُونٍ', 'wa mā ṣāḥibukum bimajnūn', 'Ve sizin arkadaşınız (Peygamber) mecnun (deli) değildir.'),
(81, 23, 30, 586, 'وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ', 'Ve lekad raʾâhu bi''l-ufuki''l-mubîn(i)', 'Andolsun ki onu apaçık ufukta gördü.'),
(81, 24, 30, 586, 'وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍ', 've-mā hüve ʿalā l-ġaybi bi-ḍanīn', 'O, gayb (bilgisi) konusunda kıskanç değildir.'),
(81, 25, 30, 586, 'وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍ رَّجِيمٍ', 'wa mā huwa bi-qawli shayṭānin rajīm', 'O, (bu Kur''an) taşlanmış bir şeytanın sözü değildir.'),
(81, 26, 30, 586, 'فَأَيْنَ تَذْهَبُونَ', 'fa-ʾayna taḏ-habūn', 'O halde nereye gidiyorsunuz?'),
(81, 27, 30, 586, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'ʾin huwa ʾillā dhikrun lil-ʿālamīn', 'O (Kur''an), âlemler için bir öğütten başka bir şey değildir.'),
(81, 28, 30, 586, 'لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ', 'liman shāʾa minkum an yastaqīm', 'Sizden dosdoğru olmak isteyene.'),
(81, 29, 30, 586, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'wa mā tašāʾūna ʾillā ʾan yašāʾa ʾllāhu rabbu l-ʿālamīna', 'Siz dilediğinizden başkasını dileyemezsiniz; âlemlerin Rabbi olan Allah dilemedikçe.'),
(82, 1, 30, 587, 'إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ', 'iḏā s-samāʾu nfaṭarat', 'Gök yarıldığı zaman,'),
(82, 2, 30, 587, 'وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ', 'wa ʾiḏā l-kawākibu ʾintaṯarat', 'Ve yıldızlar döküldüğü zaman,'),
(82, 3, 30, 587, 'وَإِذَا ٱلْبِحَارُ فُجِّرَتْ', 'wa-idhā l-biḥāru fujjirat', 'Ve denizler (birbirine katılıp) fışkırtıldığında,'),
(82, 4, 30, 587, 'وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ', 'wa-idhā l-qubūru buʿthirat', 'Ve kabirler dağılıp saçıldığında,'),
(82, 5, 30, 587, 'عَلِمَتْ نَفْسٌ مَّا قَدَّمَتْ وَأَخَّرَتْ', 'ʿalimatu nafsun mā qaddamat waʾakhkharat', 'Her nefis, ne hazırlayıp ne geride bıraktığını öğrenmiştir.'),
(82, 6, 30, 587, 'يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ', 'yāʾayyuhā l-ʾinsānu mā ġarrəka birabbika l-karīmi', 'Ey insan! Hangi şey seni, kerem sahibi Rabbine karşı aldattı?'),
(82, 7, 30, 587, 'ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ', 'alladhī khalaqaka fasawwāka faʿadalaka', 'Seni yaratan, şekillendiren ve sana denge veren O''dur.'),
(82, 8, 30, 587, 'فِىٓ أَىِّ صُورَةٍ مَّا شَآءَ رَكَّبَكَ', 'fī ʾayyi ṣūratin mā šāʾa rakkabak', 'Sizi dilediği bir surette tertip etmiştir.'),
(82, 9, 30, 587, 'كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ', 'kallā bal tukadhdhibūna bid-dīn', 'Hayır! Doğrusu siz, din gününü yalanlıyorsunuz.'),
(82, 10, 30, 587, 'وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ', 'wa-ʾinna ʿalaykum la-ḥāfiẓīn', 'Oysa üzerinizde koruyucular vardır.'),
(82, 11, 30, 587, 'كِرَامًا كَٰتِبِينَ', 'kirāman kātibīn', 'Oysa üzerinizde koruyucular, değerli yazıcılar vardır.'),
(82, 12, 30, 587, 'يَعْلَمُونَ مَا تَفْعَلُونَ', 'yaʿlamūna mā tafʿalūn', 'Onlar yaptıklarınızı bilirler.'),
(82, 13, 30, 587, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'ʾinna l-ʾabrāra lafī naʿīm', 'Şüphesiz iyiler (doğru ve dürüst kimseler) nimet içindedir.'),
(82, 14, 30, 587, 'وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍ', 'wa-inna l-fujjāra la-fī jaḥīm', 'Şüphe yok ki, günahkarlar da cehennemdedir.'),
(82, 15, 30, 587, 'يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ', 'yaṣlawnahā yawma d-dīn', 'Onlar, o gün cehenneme gireceklerdir.'),
(82, 16, 30, 587, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ', 've-mā hum ʿanhā bi-ġāʾibīn', 'Onlar oradan uzakta değillerdir.'),
(82, 17, 30, 587, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 'wa mā adrāka mā yawm ad-dīn', 'Din gününün ne olduğunu sana ne bildirdi?'),
(82, 18, 30, 587, 'ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 'thumma mā adrāka mā yawmu d-dīn', 'Sonra o din gününün ne olduğunu sana ne bildirdi?'),
(82, 19, 30, 587, 'يَوْمَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْـًٔا وَٱلْأَمْرُ يَوْمَئِذٍ لِّلَّهِ', 'yawma lā tamliku nafsun li-nafsin shayʾan wa-l-amru yawmaʾidhin lillāhi', 'O gün kimse kimseye hiçbir fayda sağlayamaz. O gün hüküm ve yetki tamamen Allah''a aittir.'),
(83, 1, 30, 587, 'وَيْلٌ لِّلْمُطَفِّفِينَ', 'waylun lil-muṭaffifīn', 'Ölçüde ve tartıda hile yapanların vay haline!'),
(83, 2, 30, 587, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', 'alladhīna idhā ktalū ʿalā n-nāsi yastawfūn', 'Onlar, kendi haklarını alırken, ölçüp tarttıklarında tam alanlardır.'),
(83, 3, 30, 587, 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', 'wa ʾidhā kālūhum ʾaw wazānūhum yakhsirūn', 'Onları ölçtükleri veya tarttıkları zaman, eksik ölçer ve tartanlar.'),
(83, 4, 30, 587, 'أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 'ʾalā yaẓunnu ʾulāʾika ʾannahum mabʿūthūn', 'Şüphesiz onlar, tekrar diriltileceklerini sanmazlar.'),
(83, 5, 30, 587, 'لِيَوْمٍ عَظِيمٍ', 'li-yawmin ʿaẓīm', 'Büyük bir gün için.'),
(83, 6, 30, 587, 'يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ', 'yawma yaqūmu n-nāsu li-rabb-i l-ʿālamīn', 'O gün insanlar, âlemlerin Rabbi''nin (huzurunda) duracaklardır.'),
(83, 7, 30, 588, 'كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍ', 'kallā inna kitāba l-fujjāri lafī sijjin', 'Hayır! Şüphesiz, günahkârların yazısı ''siccin''dedir.'),
(83, 8, 30, 588, 'وَمَآ أَدْرَىٰكَ مَا سِجِّينٌ', 'wa mā ʾadraka mā sijjin', 'Oysa ne bildirdi sana Secccin nedir?'),
(83, 9, 30, 588, 'كِتَٰبٌ مَّرْقُومٌ', 'kitābun marqūmun', 'Mühürlenmiş bir kitaptır.'),
(83, 10, 30, 588, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'waylun yawma''iḏin lilmuḵaḏibīn', 'İşte o gün, yalanlayanların vay haline!'),
(83, 11, 30, 588, 'ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ', 'alladhīna yukadhdhibūna bi-yawmi d-dīn', 'Onlar, din gününü yalanlayanlardır.'),
(83, 12, 30, 588, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ', 'wa mā yukadždžibu bihi ʾillā kullu muʿtadin ʾaṯīmin', 'Onu ancak her azgın günahkâr yalanlar.'),
(83, 13, 30, 588, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'iḏā tutlā ʿalayhi ʾāyātunā qāla ʾasāṭīru l-ʾawwalīn', 'Onun üzerine ayetlerimiz okunduğunda, "(Bunlar) öncekilerin masallarıdır" der.'),
(83, 14, 30, 588, 'كَلَّا بَلْ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ', 'kallā bal rāna ʿalā qulūbihim mā kānū yaksibūn', 'Hayır! Onların yapmakta oldukları, kalplerini paslandırmıştır.'),
(83, 15, 30, 588, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ', 'kallā innahum ʿan rabbihim yawmaʾiḏin lamahjūbūn', 'Hayır! Şüphesiz onlar, o gün Rablerinden mahrum kalacaklardır.'),
(83, 16, 30, 588, 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', 'thumma innahum laṣālū al-jaḥīm', 'Sonra onlar mutlaka cehenneme gireceklerdir.'),
(83, 17, 30, 588, 'ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'thumma yuqālu hādhā alladhī kuntum bihī tukadhdhibūn', 'Sonra onlara şöyle denir: İşte bu, sizin yalanlamakta olduğunuz şeydir!'),
(83, 18, 30, 588, 'كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 'kallā. inna kitāba l-ʾabrāri lafī ʿilliyyīn', 'Hayır! İyilerin defteri, yüce illerdedir.'),
(83, 19, 30, 588, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 'wa mā adrāka mā ʿilliyyūn', 'Oysa ne bildirdi sana nice nice ''illiyyûn!'),
(83, 20, 30, 588, 'كِتَٰبٌ مَّرْقُومٌ', 'kitābun marqūm', 'Mühürlenmiş bir kitaptır.'),
(83, 21, 30, 588, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 'yashhaduhu l-muqarrabūn', 'Ona yakın olanlar tanıklık eder.'),
(83, 22, 30, 588, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'ʾinna l-ʾabrāra lafī naʿīm', 'Şüphesiz iyiler (o zaman) bir nimet içindedirler.'),
(83, 23, 30, 588, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'ʿalā l-ʾarāʾiki yanẓurūn', 'Onlar koltuklara kurulmuş, (her şeyi) seyrederler.'),
(83, 24, 30, 588, 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', 'taʿrifu fī wujūhihim naḍrata n-naʿīm', 'Onların yüzlerinde nimetin parlaklığını tanırsın.'),
(83, 25, 30, 588, 'يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ', 'yusqawna min raḥīqin makhtūm', 'Onlara mühürlenmiş (saf) bir içkiden ikram edilir.'),
(83, 26, 30, 588, 'خِتَٰمُهُۥ مِسْكٌ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ', 'khitāmuhu misk wa fī dhālika fal yatanāfas il mutanāfisūn', 'Onun mührü misktir. İşte bu! Yarışmak isteyenler bunun için yarışsınlar.'),
(83, 27, 30, 588, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'wa-mizājuhu min tasnīm', 'Onun karışımı da tesnimden (bir kaynak)tır.'),
(83, 28, 30, 588, 'عَيْنًا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 'ʿaynan yašrabu bihā l-muqarrabūn', 'Oysa o, (Allah''a) yakın olanların içtiği bir pınardır.'),
(83, 29, 30, 588, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 'ʾinna lladhīna ʾajramū kānū mina lladhīna ʾāmanū yaḍḥakūn', 'Doğrusu, suçlular iman edenlere gülerlerdi.'),
(83, 30, 30, 588, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 'wa ʾiḏā marrū bihim yataġāmazūn', 'Onların yanından geçerken birbirlerine göz kırparlardı.'),
(83, 31, 30, 588, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 'wa-ʾiḏā nqalabū ʾilā ʾahlihimu nqalabū fakiḥīn', 'Onlar, ailelerine döndüklerinde keyiflenerek dönerlerdi.'),
(83, 32, 30, 588, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ', 'wa-ʾidhā raʾawhum qālū ʾinna hāʾulāʾi la-ḍāllūna', 'Onları gördükleri zaman, "Şüphesiz bunlar sapmışlardır" derlerdi.'),
(83, 33, 30, 588, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ', 'wa mā ursilū ʿalayhim ḥāfiẓīn', 'Oysa onlara bir koruyucu gönderilmemişti.'),
(83, 34, 30, 588, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 'fa-l-yawma alladhīna ʾāmanū mina l-kuffāri yaḍḥakūn', 'İşte o gün, iman edenler kâfirlerin kahkahalarla gülecekleri (durumda)dır.'),
(83, 35, 30, 589, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'ʿalā l-ʾarāʾiki yanẓurūn', 'Onlar koltuklar üzerinde seyrederler.'),
(83, 36, 30, 589, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 'hal thūwwiba l-kuffāru mā kānū yafʿalūn', 'Yoksa o kâfirler, yapmakta olduklarının cezasıyla mı karşılandılar?'),
(84, 1, 30, 589, 'إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 'idhā s-samāʾu nshaqqat', 'Gök yarıldığı zaman,'),
(84, 2, 30, 589, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'wa-adhinat lirabbihā wa-ḥuqqat', 'Rabbinin çağrısına kulak verip boyun eğdi ve nitekim öyle de olması gerekiyordu.'),
(84, 3, 30, 589, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 'waʾiḏā l-ʾarḍu muddat', 'Ve yer uzatıldığı zaman,'),
(84, 4, 30, 589, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'wa-alqati mā fīhā wa-takhallat', 'Ve içindekileri atıp boşaldığı zaman.'),
(84, 5, 30, 589, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'wa-ʾaḏinat lirabbihā wa-ḥuqqat', 'Rabbi için dinlemiş ve hakkı yerine getirmiştir.'),
(84, 6, 30, 589, 'يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَٰقِيهِ', 'yā ʾayyuhā l-ʾinsānu ʾinnaka kādiḥun ʾilā rabbika kadḥan famulāqīhi', 'Ey insan! Şüphesiz sen Rabbine doğru bir çaba ile (yola) çıkmışsındır. Artık O''na varacaksın.'),
(84, 7, 30, 589, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ', 'faʾammā man ʾūtiya kitābahū biyemīnihī', 'Kitabı sağ tarafından verilen kimse ise,'),
(84, 8, 30, 589, 'فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا', 'fasawfa yuḥāsabu ḥisāban yasīran', 'O, kolay bir hesapla hesaba çekilecektir.'),
(84, 9, 30, 589, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًا', 'wa yanqalibu ilā ahlihi masrūrā', 'Ve ailesine sevinçli olarak döner.'),
(84, 10, 30, 589, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'wa-ʾammā man ʾūtīya kitābahū waraʾa ẓahrihī', 'Amma kimin kitabı sırtının ardından verilirse'),
(84, 11, 30, 589, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًا', 'fasawfa yadʿū thubūran', 'O, "Vay helakime!" diye çağıracaktır.'),
(84, 12, 30, 589, 'وَيَصْلَىٰ سَعِيرًا', 'wa yaṣlā saʿīrā', 'Ve alevli ateşe yaslanacaktır.'),
(84, 13, 30, 589, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 'ʾinnahu kāna fī ʾahlihī masrūran', 'Çünkü o, ailesi içinde neşeli idi.'),
(84, 14, 30, 589, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 'ʾinnahuu ẓanna ʾan lan yaḥuur', 'Şüphesiz o, Rabbine asla dönmeyeceğini sanmıştı.'),
(84, 15, 30, 589, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًا', 'balā ʾinna rabbahū kāna bihī baṣīrā', 'Hayır! Şüphesiz Rabbi onu görüyordu.'),
(84, 16, 30, 589, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 'falā uqsimu bish-shafaqi', 'Hayır, (yemin ederim) şafağa.'),
(84, 17, 30, 589, 'وَٱلَّيْلِ وَمَا وَسَقَ', 'wa-l-layli wa-mā wasaqa', 'Geceye ve (onun) topladığı şeylere yemin ederim.'),
(84, 18, 30, 589, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 'wa-l-qamari ʾidhā ttasaqa', 'Ay''a ve dolunay halini aldığı zamana yemin ederim.'),
(84, 19, 30, 589, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', 'Letarkebunne tabakan an tabakin', 'Siz elbette halden hale geçeceksiniz.'),
(84, 20, 30, 589, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 'famā lahum lā yuʾminūn', 'Onlara ne oluyor ki iman etmiyorlar?'),
(84, 21, 30, 589, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ', 'wa ʾiḏā quriʾa ʿalayhimu l-qurʾānu lā yasjudūna', 'Onlara Kur''an okunduğu zaman secde etmezler.'),
(84, 22, 30, 589, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 'balil-ladhīna kafarū yukadhdhibūn', 'Hayır, inkâr edenler yalanlamaktadır.'),
(84, 23, 30, 589, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 'wa-llāhu ʾaʿlamu bimā yūʿūn', 'Oysa Allah, onların sinelerinde sakladıklarını daha iyi bilendir.'),
(84, 24, 30, 589, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'febeşşirhum biʿaḏābin ʾelīm', 'Onları acı veren bir azapla müjdele!'),
(84, 25, 30, 589, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 'illa alladhīna ʾāmanū waʿamilū aṣ-ṣāliḥāti lahum ʾajrun ghayru mamnūnin', 'Ancak iman edip salih amel işleyenler başka; onlara kesintisiz bir ecir vardır.'),
(85, 1, 30, 590, 'وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', 'Vessemāʾi ḏāti l-burūj', 'Yemin ederim o burçlara sahip göğe.'),
(85, 2, 30, 590, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', 'wa-l-yawmi l-mawʿūd(i)', 'Ve va''dedilen gün''e.'),
(85, 3, 30, 590, 'وَشَاهِدٍ وَمَشْهُودٍ', 'wa shāhidin wa mashhūdin', 'Ve şâhidin ve meşhûdin.'),
(85, 4, 30, 590, 'قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ', 'qutila ʾaṣḥābu l-ʾukhdūd', 'O hende kazıp ateş yakanlar kahrolsun!'),
(85, 5, 30, 590, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', 'an-nāri dhāti l-waqūd', 'Yakıtla beslenen ateş.'),
(85, 6, 30, 590, 'إِذْ هُمْ عَلَيْهَا قُعُودٌ', 'ʾidh hum ʿalayhā qʿūd', 'Onlar, o ateşin başında oturmuşlardı.'),
(85, 7, 30, 590, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ', 'wa hum ʿalā mā yafʿalūna bil-muʾminīna shuhūdun', 'Onlar, mü''minlere yaptıkları karşısında şahitlik ederler.'),
(85, 8, 30, 590, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 've mā naqamū minhum illā an yuʾminū billāhi l-ʿazīzi l-ḥamīd', 'Oysa onlardan intikam almalarının tek sebebi, Aziz ve Hamîd olan Allah''a inanmalarıydı.'),
(85, 9, 30, 590, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'alladhī lahu mulku s-samāwāti wa-l-arḍi wa-llāhu ʿalā kulli shayʾin shahīd', 'O, göklerin ve yerin mülkiyetinin/hükümranlığının kendisi olan Allah''tır. Allah her şeye şahittir.'),
(85, 10, 30, 590, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', 'İnne-lleẕîne fetenû-lmu''minîne velmu''minât(i) śümme lem yetûbû felehum ‘aẕâbu cehenneme velehum ‘aẕâbu-lḥarîḳ(i)', 'Şüphesiz ki mümin erkeklere ve mümin kadınlara işkence edip de sonra tevbe etmeyenlere cehennem azabı vardır ve onlar için yangın azabı vardır.'),
(85, 11, 30, 590, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ', 'ʾinna llaḏīna ʾāmanū wa ʿamilū ṣ-ṣāliḥāti lahum jannātun tajrī min taḥtihā l-ʾanhāru ḏālika l-fawzu l-kabīru', 'Şüphesiz iman edip salih amel işleyenler için, zira altlarından ırmaklar akan cennetler vardır. İşte bu, büyük kurtuluştur.'),
(85, 12, 30, 590, 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', 'ʾinna baṭśa rabbika la-shadīd', 'Şüphesiz Rabbinin yakalaması (ve cezalandırması) çok şiddetlidir.'),
(85, 13, 30, 590, 'إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ', 'ʾinnahu huwa yubdiʾu wa yuʿīdu', 'Şüphesiz O, yaratmaya başlayan ve (sonra) döndürendir.'),
(85, 14, 30, 590, 'وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ', 'wa huwa l-ghafūru l-wadūd', 'Ve O, Gafûr''dur, Vedûd''dur.'),
(85, 15, 30, 590, 'ذُو ٱلْعَرْشِ ٱلْمَجِيدُ', 'dhū l-ʿarshi l-majīd', 'Arş''ın sahibi, şanı yüce olan O''dur.'),
(85, 16, 30, 590, 'فَعَّالٌ لِّمَا يُرِيدُ', 'faʿʿālun limā yurīd', 'O, dilediğini mutlak olarak yapandır.'),
(85, 17, 30, 590, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ', 'hal atāka ḥadīthu l-junūd', 'Sana o orduların haberi geldi mi?'),
(85, 18, 30, 590, 'فِرْعَوْنَ وَثَمُودَ', 'firʿawna wa-ṯamūd', 'Firavun ve Semud (kavimleri).'),
(85, 19, 30, 590, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ', 'bal-illeżīne keferū fī tekżîb', 'Hayır, o kâfirler bir tekzip (yalanlama) içindedirler.'),
(85, 20, 30, 590, 'وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ', 'wa-llāhu min warāʾihim muḥīṭun', 'Halbuki Allah onları (her yönden) kuşatmıştır.'),
(85, 21, 30, 590, 'بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ', 'bal huwa qurʾānun majīd', 'Hayır, o, Kur''an''dır.'),
(85, 22, 30, 590, 'فِى لَوْحٍ مَّحْفُوظٍۭ', 'fī lawḥin maḥfūẓin', 'Saklanmış bir levha(da)dır.'),
(86, 1, 30, 591, 'وَٱلسَّمَآءِ وَٱلطَّارِقِ', 've''s-semâʾi ve''t-târiḳi', 'Göğe ve Târık''a (gece gelene) yemin olsun.'),
(86, 2, 30, 591, 'وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ', 'wa mā adrāka mā ṭ-ṭāriq', 'Ve o Târık''ın ne olduğunu sana ne bildirdi?'),
(86, 3, 30, 591, 'ٱلنَّجْمُ ٱلثَّاقِبُ', 'en-necmü-th-thâqib', 'O, (karanlığı) delen yıldızdır.'),
(86, 4, 30, 591, 'إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ', 'ʾinna kulla nafsin lammā ʿalayhā ḥāfiẓun', 'Hiçbir nefis yoktur ki üzerinde bir koruyucu bulunmasın.'),
(86, 5, 30, 591, 'فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ', 'fal-yanẓuri l-insānu mim-mā khuliqa', 'İnsan neden yaratıldığına bir bakıversin.'),
(86, 6, 30, 591, 'خُلِقَ مِن مَّآءٍ دَافِقٍ', 'khuliqa min māʾin dāfiq', 'O, fışkırtılan bir sudan yaratıldı.'),
(86, 7, 30, 591, 'يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ', 'yakhruju min bayni ṣ-ṣulbi wa-t-tarāʾib', 'O, bel (sırta) ile göğüs (kaburgalar) arasından çıkan bir sudan yaratılır.'),
(86, 8, 30, 591, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ', 'ʾinnahu ʿalā rajʿihi laqādirun', 'Şüphesiz O, onu (öldükten sonra) döndürmeye elbette kadirdir.'),
(86, 9, 30, 591, 'يَوْمَ تُبْلَى ٱلسَّرَآئِرُ', 'yawma tublā as-sarāʾir', 'O gün sırlar denenecektir.'),
(86, 10, 30, 591, 'فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ', 'famā lahu min quwwatin walā nāṣir', 'Onun için ne bir güç ne de bir yardımcı vardır.'),
(86, 11, 30, 591, 'وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ', 'Vessemāʾi zātir-recʿi', 'Yağmur sahipli göğe andolsun.'),
(86, 12, 30, 591, 'وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ', 'wa-l-arḍi dhāti ṣ-ṣadʿi', 'Yemin ederim o yere ve çatlayıp yarılana.'),
(86, 13, 30, 591, 'إِنَّهُۥ لَقَوْلٌ فَصْلٌ', 'ʾinnahu laqawlun faṣlun', 'Şüphesiz o, (hak ile batılı) ayıran bir sözdür.'),
(86, 14, 30, 591, 'وَمَا هُوَ بِٱلْهَزْلِ', 'wa mā huwa bil-hazli', 'O, asla bir eğlence/şaka değildir.'),
(86, 15, 30, 591, 'إِنَّهُمْ يَكِيدُونَ كَيْدًا', 'ʾinnahum yakīdūna kaydan', 'Şüphesiz onlar hileli bir plan kuruyorlar.'),
(86, 16, 30, 591, 'وَأَكِيدُ كَيْدًا', 'wa ʾakīdu kaydan', 'Ve ben de o zaman bir tuzak kuracağım.'),
(86, 17, 30, 591, 'فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا', 'fe-mehhili l-kāfirīne emhilhum ruwaydan', 'Şimdi kâfirlere mühlet ver, onlara biraz zaman tanı.'),
(87, 1, 30, 591, 'سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى', 'Sabbıḥi-sme rabbike-l-ʾaʿlā', 'En yüce Rabbinin adını tesbih et!'),
(87, 2, 30, 591, 'ٱلَّذِى خَلَقَ فَسَوَّىٰ', 'alladhī khalaqa fasawwā', 'O ki yaratmış, sonra da (biçim verip) düzeltmiştir.'),
(87, 3, 30, 591, 'وَٱلَّذِى قَدَّرَ فَهَدَىٰ', 'wa-lladhī qaddara fa-hadā', 'Ve O ki (her şeyi) ölçüyle yaratıp düzenlemiş, sonra da yol göstermiştir.'),
(87, 4, 30, 591, 'وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ', 'wa-lladhī ʾakhraja l-marʿā', 'O, (yeşil) bitki örtüsünü çıkaran da O''dur.'),
(87, 5, 30, 591, 'فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ', 'fa jaʿalahū ġuṯāʾan aḥwā', 'Böylece onu, kupkuru, siyah bir ot yığını haline getirdi.'),
(87, 6, 30, 591, 'سَنُقْرِئُكَ فَلَا تَنسَىٰٓ', 'sanukriʾuka falā tansā', 'Sana Kur''an''ı okutacağız da unutmayacaksın.'),
(87, 7, 30, 591, 'إِلَّا مَا شَآءَ ٱللَّهُ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ', 'illa mā shāʾa ʾllāhu ʾinnahuu yaʿlamu l-jahra wa mā yakhfaa', 'Allah''ın dilediği müstesna. Şüphesiz O, açığa vurulanı da, gizleneni de bilir.'),
(87, 8, 30, 591, 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', 'wa nuyassiruka lil-yusra', 'Ve onu en kolayı için muvaffak kılacağız.'),
(87, 9, 30, 591, 'فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ', 'faḏakkir in nafaʿati ḏ-ḏikrā', 'Öğüt ver; çünkü öğüt fayda verecektir.'),
(87, 10, 30, 591, 'سَيَذَّكَّرُ مَن يَخْشَىٰ', 'sa-yadhakkaru man yakhshā', 'Çok geçmeden o, çekinip korkan kimse öğüt alacaktır.'),
(87, 11, 30, 591, 'وَيَتَجَنَّبُهَا ٱلْأَشْقَى', 'wa yatajannabuhā l-ʾashqā', 'Ve onu en bedbaht olan kaçınır.'),
(87, 12, 30, 591, 'ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ', 'alladhī yaṣlā an-nāra al-kubrā', 'O, en büyük ateşe girecektir.'),
(87, 13, 30, 591, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'thumma lā yamūtu fīhā walā yaḥyā', 'Sonra orada ne ölür ne de yaşar.'),
(87, 14, 30, 591, 'قَدْ أَفْلَحَ مَن تَزَكَّىٰ', 'qad aflaḥa man tazakkā', 'Gerçekten de arınan kimse kurtuluşa ermiştir.'),
(87, 15, 30, 591, 'وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ', 'wa dhakara isma rabbihī faṣallā', 'Ve Rabbinin ismini zikredip namaz kıldı.'),
(87, 16, 30, 592, 'بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 'bal tuʾthirūna l-ḥayāta d-dunyā', 'Hayır, siz dünya hayatını tercih ediyorsunuz.'),
(87, 17, 30, 592, 'وَٱلْءَاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ', 'wa-l-ʾākhiratu khayrun wa-ʾabqā', 'Oysa dünya hayatı, ahiret hayatından daha hayırlı ve daha kalıcıdır.'),
(87, 18, 30, 592, 'إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'ʾinna hādhā lafī ṣ-ṣuḥufi l-ʾūlā', 'Şüphesiz bu, önceki sahifelerde de vardır.'),
(87, 19, 30, 592, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ', 'ṣuḥufi ibrāhīma wa-mūsā', 'İbrahim''in ve Musa''nın sahifelerinde olan.'),
(88, 1, 30, 592, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ', 'hal atāka ḥadīthu l-ghāshiyah', 'Sana o her şeyi örten (Kıyamet) haberi geldi mi?'),
(88, 2, 30, 592, 'وُجُوهٌ يَوْمَئِذٍ خَٰشِعَةٌ', 'wujūhun yawmaʾiḏin ḫāšiʿah', 'O gün birtakım yüzler de hor ve hakir.'),
(88, 3, 30, 592, 'عَامِلَةٌ نَّاصِبَةٌ', 'ʿāmilatun nāṣibah', 'Çalışıp yorulmuşlardır.'),
(88, 4, 30, 592, 'تَصْلَىٰ نَارًا حَامِيَةً', 'taṣlā nāran ḥāmiyatan', 'Onlar, (dunyada yaptiklari kotulukler yuzunden) kizgin bir atese gireceklerdir.'),
(88, 5, 30, 592, 'تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ', 'tusqā min ʿaynin ʾāniyah', 'Onlar, kaynar bir kaynaktan (bir pınardan) içirilirler.'),
(88, 6, 30, 592, 'لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ', 'laysa lahum ṭaʿāmun illā min ḍarīʿin', 'Onlara zakkum ağacından başka bir yiyecek yoktur.'),
(88, 7, 30, 592, 'لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ', 'lā yusminu walā yughnī min jūʿin', 'Ne semizletir ne de açlıktan bir fayda sağlar.'),
(88, 8, 30, 592, 'وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ', 'wujūhun yawmaʾiḏin nāʿimah', 'O gün, bir takım yüzler de vardır ki, (dünya nimetleri içinde) zevk ve refah içindedir.'),
(88, 9, 30, 592, 'لِّسَعْيِهَا رَاضِيَةٌ', 'li-saʿyihā rāḍiyah', 'Kendi çabasından razı olmuştur.'),
(88, 10, 30, 592, 'فِى جَنَّةٍ عَالِيَةٍ', 'fī jannatin ʿāliyah', 'Onlar, yüksek bir cennettedirler.'),
(88, 11, 30, 592, 'لَّا تَسْمَعُ فِيهَا لَٰغِيَةً', 'lā tasmʿu fīhā lāġiyatan', 'Orada boş bir söz işitmezsin.'),
(88, 12, 30, 592, 'فِيهَا عَيْنٌ جَارِيَةٌ', 'fīhā ʿaynun jāriyah', 'Onun içinde akan bir kaynak vardır.'),
(88, 13, 30, 592, 'فِيهَا سُرُرٌ مَّرْفُوعَةٌ', 'fīhā sururun marfūʿah', 'Onlarda (cennetlerde) yükseltilmiş tahtlar vardır.'),
(88, 14, 30, 592, 'وَأَكْوَابٌ مَّوْضُوعَةٌ', 'wa-akwābun mawḍūʿah', 'Ve konulmuş kupalar.'),
(88, 15, 30, 592, 'وَنَمَارِقُ مَصْفُوفَةٌ', 'wa namāriqu maṣfūfah', 'Ve dizilmiş koltuklar.'),
(88, 16, 30, 592, 'وَزَرَابِىُّ مَبْثُوثَةٌ', 'wa-zarābiyyu mabthūthah', 'Ve yayılmış halı(lar).'),
(88, 17, 30, 592, 'أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ', 'ʾaflā yanẓurūn ʾilā l-ʾibili kayfa ḵuliqat', 'Onlar, devenin nasıl yaratıldığına bakmazlar mı?'),
(88, 18, 30, 592, 'وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ', 'waʾilā s-samāʾi kayfa rufiʿat', 'Ve göğe bakmazlar mı, nasıl yükseltilmiş?'),
(88, 19, 30, 592, 'وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ', 'waʾilā l-jibāli kayfa nuṣibat', 'Ve dağlara bakmadılar mı, nasıl dikilmişler?'),
(88, 20, 30, 592, 'وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ', 'wa ilā l-arḍi kayfa suṭiḥat', 'Ve yeryüzüne bakmadılar mı, nasıl döşenmiş?'),
(88, 21, 30, 592, 'فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ', 'faḏakkir ʾinnamā ʾanta muḏakkirun', 'Artık sen öğüt ver; çünkü sen ancak bir öğüt vericisin.'),
(88, 22, 30, 592, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', 'lasta ʿalayhim bimuṣayṭir', 'Sen onların üzerinde bir zorba değilsin.'),
(88, 23, 30, 592, 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', 'illa men tevellâ ve kefer', 'Ancak arkanı dönüp gerçeği yalanlayanlar müstesna.'),
(88, 24, 30, 592, 'فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ', 'fa yuʿaḏḏibuhu ʾllāhu l-ʿaḏāba l-ʾakbara', 'Böylece Allah onu en büyük azapla azaplandırır.'),
(88, 25, 30, 592, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 'ʾinna ʾilayna ʾiyābahum', 'Şüphesiz ki onların dönüşü ancak bize olacaktır.'),
(88, 26, 30, 592, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', 'thumma inna ʿalaynā ḥisābahum', 'Sonra şüphesiz onların hesabı da bize aittir.'),
(89, 1, 30, 593, 'وَٱلْفَجْرِ', 'wa-l-fajri', 'Yemin olsun fecr''e.'),
(89, 2, 30, 593, 'وَلَيَالٍ عَشْرٍ', 'wa layālin ʿashr', 'Ve on geceye. (Yemin ederim)'),
(89, 3, 30, 593, 'وَٱلشَّفْعِ وَٱلْوَتْرِ', 'wa-sh-shafʿi wa-l-watri', 'Nizama konulmuş olanlara ve tek olanlara yemin ederim.'),
(89, 4, 30, 593, 'وَٱلَّيْلِ إِذَا يَسْرِ', 'wa-l-layli ʾidhā yasri', 'Ve gece, sükunete erdiğinde.'),
(89, 5, 30, 593, 'هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ', 'hal fī dhālika qasamun li-dhī ḥijrin', 'Şüphesiz bunlarda akıl sahibi için bir yemin (değeri) var mıdır?'),
(89, 6, 30, 593, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 'ʾelem tere keyfe feʿale rabbuke bi-ʿād', 'Rabbinin Âd (kavmin)e nasıl davrandığını görmedin mi?'),
(89, 7, 30, 593, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', 'Iram dhāt al-ʿimād', 'Direkler sahibi İrem''e (ne yaptığını görmedi mi?)')
INSERT INTO ayetler (sure_id, ayet_no, cuz_no, sayfa_no, metin_ar, transliterasyon_tr, meal_tr) VALUES
(89, 8, 30, 593, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ', 'allatī lam yukhalq mithluhā fī al-bilād', 'Hiç benzeri memleketlerde yaratılmamış olan.'),
(89, 9, 30, 593, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', 'wa-thamūda l-ladhīna jābū ṣ-ṣakhra bil-wādī', 'Ve vadideki kayaları yontan Semud''a da (yapmadılar mı?)'),
(89, 10, 30, 593, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', 'wa-firʿawna dhī l-ʾawtādi', 'Ve (onları) kazıklar sahibi Firavun''u (da helak ettik).'),
(89, 11, 30, 593, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ', 'alladhīna ṭaghaw fī l-bilādi', 'Onlar ki, ülkelerde azgınlık etmişlerdi.'),
(89, 12, 30, 593, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', 'faʾaktharū fīhā l-fasāda', 'Böylece orada fesadı (bozgunculuğu) çoğalttılar.'),
(89, 13, 30, 593, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 'faṣabba ʿalayhim rabbuka sawṭa ʿadhābin', 'Böylece Rabbin onlara azap kamçısı salıverdi.'),
(89, 14, 30, 593, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', 'ʾinna rabbaka labilmirṣād', 'Şüphesiz Rabbin (her an) gözetlemededir.'),
(89, 15, 30, 593, 'فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', 'faʾammā l-ʾinsānu ʾiḏā mā ʾibtalāhu rabbuhū faʾakramahū wanaʿʿamahū fayaqūlu rabbī ʾakramanī', 'İnsan ise, Rabbi onu imtihan edip de ikramda bulunursa, ona nimet verirse, ''Rabbim bana ikram etti'' der.'),
(89, 16, 30, 593, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ', 'wa-ammā idhā mā ibtalāhu fa-qadara ʿalayhi rizqahū fa-yaqūlu rabbī ahānanī', 'Ancak Rabb''i onu imtihan edip de rızkını daralttığında, "Rabbim bana değer vermedi (beni hor gördü)" der.'),
(89, 17, 30, 593, 'كَلَّا بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 'kallā bal lā tukrimūna l-yetīme', 'Hayır! Doğrusu siz yetime ikram etmiyorsunuz.'),
(89, 18, 30, 593, 'وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'wa lā taḥāḍḍūna ʿalā ṭaʿāmi l-miskīn', 'Ve miskini (yoksulu) doyurmaya birbirinizi teşvik etmezsiniz.'),
(89, 19, 30, 593, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا', 'wa taʾkulūna al-turātha aklan lammā', 'Ve mirası da bir horanta yiyorsunuz.'),
(89, 20, 30, 593, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا', 'wa tuḥibbūna l-māla ḥubban jammā', 'Ve malı çok seversiniz.'),
(89, 21, 30, 593, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', 'kallā ʾidhā dukkati l-ʾarḍu dakkān dakkā', 'Hayır! Yer, birbirine vurulup toz haline getirildiği zaman,'),
(89, 22, 30, 593, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا', 'wa jāʾa rabbuka wal-malaku ṣaffan ṣaffan', 'Ve Rabbin gelince ve melekler de saf saf'),
(89, 23, 30, 593, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 'wa-jīʾa yawmaʾiḏin bi-jahannama yawmaʾiḏin yataḏakkaru l-ʾinsānu wa-ʾannā lahu ḏ-ḏikrā', 'Ve o gün cehennem getirilir. O gün insan öğüt alıp düşünür. Ama o zaman düşünüp öğüt alması ona nasıl fayda verir?'),
(89, 24, 30, 594, 'يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 'yaqūlu yālaytanī qaddmtu liḥayātī', 'Keşke (dünya hayatım için) önceden (salih amel) takdim etseydim, der.'),
(89, 25, 30, 594, 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ', 'fa-yawmaʾiḏin lā yuʿaḏḏibu ʿaḏābahū ʾaḥadun', 'İşte o gün, O''nun azabı gibi azap edecek kimse yoktur.'),
(89, 26, 30, 594, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ', 'wa lā yūthiḳu wathāqahū ʾaḥadun', 'Ve O’nun (vazgeçilmez) bağlayışıyla bağladığını hiç kimse bağlayamaz.'),
(89, 27, 30, 594, 'يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 'yā ʾayyuhā n-nafsu l-muṭmaʾinnah', 'Ey mutmainne olmuş nefis!'),
(89, 28, 30, 594, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', 'irğī ilā rabbiki rāḍiyatan marḍiyyah', 'Rabbine, O''ndan razı olmuş ve razı olunmuş olarak dön!'),
(89, 29, 30, 594, 'فَٱدْخُلِى فِى عِبَٰدِى', 'fadkhulī fī ʿibādī', 'Artık kullarımın arasına katıl.'),
(89, 30, 30, 594, 'وَٱدْخُلِى جَنَّتِى', 'wa-dkhulī jannatī', 'Ve (ona şöyle denir): ''Rabbine (senin için) hazırlanmış olan cennete gir!'''),
(90, 1, 30, 594, 'لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ', 'Lā uqsimu bihādhā al-balad(i)', 'Bu şehir(Mekke) hakkı için yemin ederim ki,'),
(90, 2, 30, 594, 'وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ', 'wa ʾanta ḥillun bi-hāḏā l-balad', 'Ve sen, bu şehirde (bulunmaktasın).'),
(90, 3, 30, 594, 'وَوَالِدٍ وَمَا وَلَدَ', 'wa wālidin wa mā walada', 'Neye ve doğurana andolsun!'),
(90, 4, 30, 594, 'لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ', 'leḳad ḫalaḳnâ-l-insâne fî kebedin', 'Andolsun ki Biz insanı bir sıkıntı ve mücadele içinde yarattık.'),
(90, 5, 30, 594, 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', 'ʾayaḥsabu ʾan lan yaqdire ʿalayhi ʾaḥadun', 'Hiç kimsenin kendisine güç yetiremeyeceğini mi sanır?'),
(90, 6, 30, 594, 'يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا', 'yaqūlu ʾahlaktu mālān lubadan', 'Der ki: "Ben, (yığın yığın) mal harcadım!"'),
(90, 7, 30, 594, 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', 'ʾayaḥsabū ʾanna lam yarahu ʾaḥadun', 'O, kendisini kimsenin görmediğini mi sanır?'),
(90, 8, 30, 594, 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'ʾalam najʿal lahū ʿaynayni', 'Biz ona iki göz vermedik mi?'),
(90, 9, 30, 594, 'وَلِسَانًا وَشَفَتَيْنِ', 'wa li-sānan wa shafatayni', 'Ve ona iki dil ve iki dudak vermedik mi?'),
(90, 10, 30, 594, 'وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ', 'wa hadaynāhu an-najdayn', 'Ve biz ona iki yolu (doğru ve eğri yolu) göstermedik mi?'),
(90, 11, 30, 594, 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', 'falā iqtaḥama l-ʿaqabah', 'Ancak o yokuşu (o zorlu işi) aşmadı.'),
(90, 12, 30, 594, 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', 'wa mā adrāka mā l-ʿaqabah', 'O Akabe''nin ne olduğunu sana ne bildirdi?'),
(90, 13, 30, 594, 'فَكُّ رَقَبَةٍ', 'fukku raqabatin', 'O, sarp yokuşu aşmak (ibadet ve hayırla boynunu kurtarmak) değil midir?'),
(90, 14, 30, 594, 'أَوْ إِطْعَٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ', 'aw iṭʿāmun fī yawmin dhī masġabah', 'Yahut açlık günü'),
(90, 15, 30, 594, 'يَتِيمًا ذَا مَقْرَبَةٍ', 'yatīman ḏā maqrabatin', 'Yetim olan, yakın hısımlığı bulunan...'),
(90, 16, 30, 594, 'أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ', 'ʾaw miskīnan ḏā matraba', 'Yahut açlık ve yoksulluk içinde kalmış bir miskini.'),
(90, 17, 30, 594, 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', 'thumma kāna mina lladhīna ʾāmanū wa tawāṣaw biṣ-ṣabri wa tawāṣaw bi l-marḥamati', 'Sonra iman edenlerden ve birbirlerine sabır tavsiye edenlerden ve birbirlerine merhamet tavsiye edenlerden olanlardan oldu.'),
(90, 18, 30, 594, 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ', 'ʾulāʾika ʾaṣḥābu l-maymanati', 'İşte bunlar, Ashab-ı Yemin''dir.'),
(90, 19, 30, 594, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ', 'wa-lladhīna kafarū bi-ʾāyātinā hum ʾaṣḥābu l-mašʾamah', 'Ayetlerimizi inkâr edenlere gelince; işte onlar sol taraftakilerdir.'),
(90, 20, 30, 594, 'عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ', 'ʿalayhim nārun muʾṣadah', 'Onların üzerlerine (kapatılmış) bir ateş vardır.'),
(91, 1, 30, 595, 'وَٱلشَّمْسِ وَضُحَىٰهَا', 'wa-sh-shamsi wa-ḍuḥāhā', 'Güneşe ve onun kuşluk vaktine yemin olsun.'),
(91, 2, 30, 595, 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', 'wa-l-qamari itha talāhā', 'Ay''a, onu takip ettiğinde'),
(91, 3, 30, 595, 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', 'wa-n-nahāri idhā jallāhā', 'Gündüze ve onu açıp aydınlatana.'),
(91, 4, 30, 595, 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', 'wa-l-layli idhā yagshāhā', 'Örttüğü zaman geceye.'),
(91, 5, 30, 595, 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', 'wa-s-samāʾi wa-mā banāhā', 'Gök ve onu bina edene yemin ederim ki,'),
(91, 6, 30, 595, 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', 'wa-l-arḍi wa-mā ṭaḥāhā', 'Nefse ve onu fiziksel ve ruhsal olarak şekillendirene, sonra ona hem günahlarını hem de takvasını ilham edene yemin ederim ki;'),
(91, 7, 30, 595, 'وَنَفْسٍ وَمَا سَوَّىٰهَا', 'wa-nafs-in wa-mā sawwāhā', 'Nefse ve onu yaratıp şekillendirene yemin ederim ki,'),
(91, 8, 30, 595, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', 'faʾalhamahā fujūrahā wataqwāhā', 'Nefsine hem günahını hem de takvasını ilham edene yemin olsun ki,'),
(91, 9, 30, 595, 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', 'qad aflaḥa man zakkāhā', 'Nefsini temizleyip arıtan kimse şüphesiz kurtulmuştur.'),
(91, 10, 30, 595, 'وَقَدْ خَابَ مَن دَسَّىٰهَا', 'waqad khaba man dassāhā', 'Ve onu günahlarla örten kimse ziyana uğramıştır.'),
(91, 11, 30, 595, 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', 'kadhdhabat thamūdu biṭaghwāhā', 'Semûd (kavmi), azgınlıkları yüzünden yalanladı.'),
(91, 12, 30, 595, 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', 'iḏi nabaʿa ʾašqāhā', 'Onların en azgını harekete geçtiği zaman.'),
(91, 13, 30, 595, 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا', 'faqāla lahum rasūlu llāhi nāqata llāhi wasuqyāhā', 'Bunun üzerine Allah''ın elçisi onlara: "Allah''ın dişi devesine ve ona su verme hakkına dokunmayın!" dedi.'),
(91, 14, 30, 595, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', 'fe keẕẕebûhu fe ʿakarûhâ fe demdeme ʿaleyhim rabbuhum biẕenbihim fe sevvehâ', 'Böylece onu yalanladılar, deveyi kestiler. Bunun üzerine Rableri, günahları yüzünden onlara azap etti de hepsini (yerle bir edip) eşit kıldı.'),
(91, 15, 30, 595, 'وَلَا يَخَافُ عُقْبَٰهَا', 'wa-lā yakhāfu ʿuqbāhā', 'Onun sonucundan korkmaz.'),
(92, 1, 30, 595, 'وَٱلَّيْلِ إِذَا يَغْشَىٰ', 'wa-l-layli ʾidhā yaghshā', 'Örttüğü zaman geceye andolsun.'),
(92, 2, 30, 595, 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', 'wa-n-nahāri idhā tajallā', 'Ve gündüze, onun aydınlığına yemin ederim.'),
(92, 3, 30, 595, 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 've-mā ḫalaqa-ẕ-ẕekere ve-l-ʾunṯā', 'Erkeği ve dişiyi yaratana andolsun ki,'),
(92, 4, 30, 595, 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 'ʾinna saʿyakum la-shattā', 'Şüphesiz sizin çalışmalarınız/çabalarınız farklı farklıdır.'),
(92, 5, 30, 595, 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', 'faʾammā man ʾaʿṭā wa-ttaqā', 'Kim verir ve sakınırsa...'),
(92, 6, 30, 595, 'وَصَدَّقَ بِٱلْحُسْنَىٰ', 'wa ṣaddaqa bil-ḥusnā', 'Ve en güzel olanı tasdik edene.'),
(92, 7, 30, 595, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', 'fasayuyassiruhu lil-yusra', 'Kolay olana (cennete) ulaştıracağız.'),
(92, 8, 30, 595, 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', 'waʾammā man bakhila wastaghanā', 'Kim de cimrilik eder ve kendini müstağni sayarsa,'),
(92, 9, 30, 595, 'وَكَذَّبَ بِٱلْحُسْنَىٰ', 'wa kadhdhaba bil-ḥusnā', 'Ve en güzeli yalanladı.'),
(92, 10, 30, 595, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ', 'fasayuyassiruhu lilʿusrā', 'Biz de onu en zor olana kolaylaştıracağız.'),
(92, 11, 30, 595, 'وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ', 'Ve mā yuğnī ʿanhu māluhū iḏā taraddā', 'Onu malı, helak olduğu zaman hiçbir şeyden kurtaramaz.'),
(92, 12, 30, 595, 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', 'ʾinna ʿalaynā lal-hudā', 'Şüphesiz ki bize yol göstermek (hidayet vermek) elbette üzerimizdedir.'),
(92, 13, 30, 595, 'وَإِنَّ لَنَا لَلْءَاخِرَةَ وَٱلْأُولَىٰ', 'wa-inna lanā lal-ʾākhirata wal-ʾūlā', 'Şüphesiz ki hem ahiret hem de dünya bizimdir.'),
(92, 14, 30, 595, 'فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ', 'faʾanḏartukum nāran talaẓẓā', 'Böylece sizi alevli bir ateşe karşı uyardım.'),
(92, 15, 30, 596, 'لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى', 'lā yaṣlāhā ʾillā l-ʾašqā', 'Ancak en bedbaht olanı ona yaslanacaktır.'),
(92, 16, 30, 596, 'ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ', 'alladhī kadhdhaba watawallā', 'O kimse ki (peygamberi) yalanladı ve (imandan) yüz çevirdi.'),
(92, 17, 30, 596, 'وَسَيُجَنَّبُهَا ٱلْأَتْقَى', 'wa sayujannabuhā l-ʾatqā', 'Ve ondan (o ateşe) en çok takva sahibi olan uzak tutulacaktır.'),
(92, 18, 30, 596, 'ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ', 'alladhī yuʾtī māluhu yatazakkā', 'Malını hayra verip arınan kimse.'),
(92, 19, 30, 596, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ', 'wa mā li-ʾaḥadin ʿindahu min niʿmatin tujzā', 'Halbuki onun yanında, (başkalarına) karşı ödenmesi gereken bir nimet de yoktur.'),
(92, 20, 30, 596, 'إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ', 'illa-btiġāʾa wajhi rabbihī l-ʾaʿlā', 'Ancak Rabbinin yüce olan rızasını kazanmak için (bunu yaparlar).'),
(92, 21, 30, 596, 'وَلَسَوْفَ يَرْضَىٰ', 'wa-lasawfa yarḍā', 'Ve elbette yakında razı olacaktır.'),
(93, 1, 30, 596, 'وَٱلضُّحَىٰ', 'wa-ḍ-ḍuḥā', 'Kuşluk vaktine andolsun.'),
(93, 2, 30, 596, 'وَٱلَّيْلِ إِذَا سَجَىٰ', 'wa-l-layli ʾidhā sajā', 'Yemin ederim o karanlık gecelere ki, (sükûna erdiğinde)'),
(93, 3, 30, 596, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 'mā waddaʿaka rabbuka wa mā qalā', 'Rabbin seni terk etmedi ve sana darılmadı.'),
(93, 4, 30, 596, 'وَلَلْءَاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ', 'Ve le''l-âḫiratu ḫayrun leke mine''l-ûlâ', 'Şüphesiz ahiret senin için dünyadan daha hayırlıdır.'),
(93, 5, 30, 596, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 'Ve le savfe yuʿṭīke rabbuke fe terḍā', 'Rabbin sana elbette verecek ve sen de razı olacaksın.'),
(93, 6, 30, 596, 'أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ', 'ʾelem yecidke yetīmen feʾāwā', 'Seni yetim bulup da barındırmadı mı?'),
(93, 7, 30, 596, 'وَوَجَدَكَ ضَآلًّا فَهَدَىٰ', 'wa wajadaka ḍāllan fahadā', 'Seni bir yetim olarak bulup da barındırmadı mı? Seni sapmış (yolunu kaybetmiş) bulup da doğru yola iletmedi mi? Seni (mallarını çoğaltmak için) muhtaç bulup da zenginleştirmedi mi? İşte bu yüzden yetimi sakın ezme. İsteyeni de sakın azarlama. Rabbinin nimetine gelince, işte onu an (anlatıp şükret).'),
(93, 8, 30, 596, 'وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ', 'wa wajadaka ʿāʾilan fa-aġnā', 'Seni fakir bulup da zenginleştirmedi mi?'),
(93, 9, 30, 596, 'فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ', 'faʾammā l-yatīma falā taqhar', 'Artık yetimi sakın ezme.'),
(93, 10, 30, 596, 'وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ', 'waʾammā s-sāʾila falā tanhar', 'Yetime gelince, sakın horlama.'),
(93, 11, 30, 596, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', 'wa-ammā bi-niʿmati rabbika fa-ḥaddiṯ', 'Rabbinin nimetine gelince, (onu) anlat!'),
(94, 1, 30, 596, 'أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'ʾelem neşraḥ leke ṣadrek', 'Biz senin göğsünü açıp genişletmedik mi?'),
(94, 2, 30, 596, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'wa waḍaʿnā ʿanka wizraka', 'Ve senin yükünü alnından koyduk.'),
(94, 3, 30, 596, 'ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ', 'alladhī ʾanqaḍa ẓahraka', 'O, (yükü) sırtından ağırlaşan (o yükü) kaldıran.'),
(94, 4, 30, 596, 'وَرَفَعْنَا لَكَ ذِكْرَكَ', 'wa rafaʿnā laka dhikrak', 'Ve senin şânını yücelttik.'),
(94, 5, 30, 596, 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'fa-inna maʿa l-ʿusri yusran', 'Şüphesiz zorlukla beraber bir kolaylık vardır.'),
(94, 6, 30, 596, 'إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'ʾinna maʿa l-ʿusri yusran', 'Şüphesiz zorlukla beraber bir kolaylık vardır.'),
(94, 7, 30, 596, 'فَإِذَا فَرَغْتَ فَٱنصَبْ', 'fa-ʾidhā faraghta fa-nṣab', 'Ne zaman ki (bir işi bitirip) boş kaldın, hemen diğerine koş!'),
(94, 8, 30, 596, 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', 'waʾilā rabbika farghab', 'Öyleyse, umudunu yalnız Rabbine bağla.'),
(95, 1, 30, 597, 'وَٱلتِّينِ وَٱلزَّيْتُونِ', 'wa-t-tīni wa-z-zaytūn', 'İncire ve zeytine yemin olsun.'),
(95, 2, 30, 597, 'وَطُورِ سِينِينَ', 'wa ṭūri sīnīna', 'Ve Tûr-i Sînâ''ya (da)'),
(95, 3, 30, 597, 'وَهَٰذَا ٱلْبَلَدِ ٱلْأَمِينِ', 'wa hādhā al-baladi al-ʾamīn', 'Ve bu güvenli beldeye yemin olsun ki,'),
(95, 4, 30, 597, 'لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ', 'laqad khalaqnā l-insāna fī aḥsani taqwīmin', 'Andolsun ki Biz insanı en güzel biçimde yarattık.'),
(95, 5, 30, 597, 'ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ', 'thumma radadnāhu asfala sāfilīn', 'Sonra onu (insanı) aşağıların aşağısına indirdik.'),
(95, 6, 30, 597, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 'illa alladhīna ʾāmanū wa ʿamilū aṣ-ṣāliḥāti falalahum ʾajrun ghayru mamnūnin', 'Ancak iman edip salih amel işleyenler başka; onlara kesintisiz bir ecir vardır.'),
(95, 7, 30, 597, 'فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ', 'famā yukadhibuka baʿdu bi-d-dīn', 'Buna rağmen, din (hesap) günü hususunda seni hala kim yalanlayabilir?'),
(95, 8, 30, 597, 'أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَٰكِمِينَ', 'ʾalaysa ʾallāhu bi-ʾaḥkami l-ḥākimīn', 'Allah, hükmedenlerin en iyi hükmedeni değil midir?'),
(96, 1, 30, 597, 'ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 'iqraʾ bi-smi rabbika lladhī khalaqa', 'Yaratan Rabbinin adıyla oku!'),
(96, 2, 30, 597, 'خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ', 'x̱alaqa l-ʾinsāna min ʿalaq', 'İnsanı alak''tan yarattı.'),
(96, 3, 30, 597, 'ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ', 'iqraʾ wa rabbuka l-ʾakramu', 'Oku! Ve Rabbin en kerem sahibidir.'),
(96, 4, 30, 597, 'ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ', 'alladhī ʿallama bil-qalam', 'O, (insana) kalemle (yazmayı) öğreten.'),
(96, 5, 30, 597, 'عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ', 'ʿallama l-ʾinsāna mā lam yaʿlam', 'İnsana bilmediğini öğretti.'),
(96, 6, 30, 597, 'كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ', 'kallā. inna l-insāna le yaġġā.', 'Hayır! İnsan, kendini yeterli görüp azgınlaşır.'),
(96, 7, 30, 597, 'أَن رَّءَاهُ ٱسْتَغْنَىٰٓ', 'ʾan raʾāhu ʾistaghnā', 'Kendisini zengin sandığı için.'),
(96, 8, 30, 597, 'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ', 'ʾinna ʾilā rabbika ʾr-rujʿā', 'Şüphesiz dönüş Rabbinedir.'),
(96, 9, 30, 597, 'أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ', 'ʾaraʾayta lladhī yanhā', 'Gördün mü o (kötülüğü) yasaklayanı?'),
(96, 10, 30, 597, 'عَبْدًا إِذَا صَلَّىٰٓ', 'ʿabdan ʾiḏā ṣallā', 'Kulluk ettiği vakit.'),
(96, 11, 30, 597, 'أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ', 'araʾayta in kāna ʿalā l-hudā', 'Gördün mü, eğer o (kulluk eden) hidayet üzere ise'),
(96, 12, 30, 597, 'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ', 'aw amara bi-t-taqwā', 'Yoksa takvâyı emretmiş miydi?'),
(96, 13, 30, 597, 'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ', 'ʾaraʾayta ʾin kaḏḏaba wa tawallā', 'Gördün mü, eğer yalan sayıp yüz çevirirse?'),
(96, 14, 30, 597, 'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ', 'ʾalam yaʿlam biʾanna ʾallāha yarā', 'Bilmez mi ki, Allah yaptıklarını görmektedir.'),
(96, 15, 30, 597, 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ', 'kallā laʾin lam yantahi̇ lanəsfaʿan bi̇n-nāṣiyati', 'Hayır, eğer o (bu) vazgeçmezse, andolsun ki, alnından (perçeminden) yakalarız.'),
(96, 16, 30, 597, 'نَاصِيَةٍ كَٰذِبَةٍ خَاطِئَةٍ', 'nāṣiyatin kādhibatin khāṭiʾatin', 'Yalancı, günahkâr bir alın.'),
(96, 17, 30, 597, 'فَلْيَدْعُ نَادِيَهُۥ', 'fal-yadʿu nādiya-hū', 'Hayır, eğer o vazgeçmezse, mutlaka onu tepeden (perçeminden) yakalarız.'),
(96, 18, 30, 597, 'سَنَدْعُ ٱلزَّبَانِيَةَ', 'sanadʿu z-zabāniyah', 'Hayır, eğer o vazgeçmezse, mutlaka onu tepeden (perçeminden) yakalarız.'),
(96, 19, 30, 597, 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب', 'kellā lā tuṭiʿhu wasjud waqtari', 'Hayır, ona uyma! Secde et ve (Rabbin''e) yaklaş!'),
(97, 1, 30, 598, 'إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', 'ʾinnā ʾanzalnāhu fī laylati l-qadr', 'Şüphesiz biz onu (Kur''an''ı) Kadir gecesinde indirdik.'),
(97, 2, 30, 598, 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', 'wa mā adrāka mā laylatu l-qadr', 'Kadir gecesinin ne olduğunu sana ne bildirdi?'),
(97, 3, 30, 598, 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', 'laylatu l-qadri khayrun min alfı shahrin', 'Kadir gecesi bin aydan daha hayırlıdır.'),
(97, 4, 30, 598, 'تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ', 'tanazzalu l-malāʾikatu wa-r-rūḥu fīhā bi-iʾdhini rabbihim min kulli ʾamr', 'Melekler ve Ruh (Cebrail) o gecede, Rablerinin izniyle her bir iş için iner.'),
(97, 5, 30, 598, 'سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', 'salāmun hiya ḥattā maṭlaʿi l-fajr', 'O (gece) esenliktir; tan yeri ağarıncaya kadar.'),
(98, 1, 30, 598, 'لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', 'lem yekuni l-ladhīna kafarū min ahli l-kitābi wa-l-mushrikīna munfakkīna ḥattā taʾtiyahumu l-bayyinatu', 'Kitap ehlinden ve müşriklerden inkâr edenler, kendilerine apaçık delil (Beyyine) gelinceye kadar küfürlerinden ayrılacak değillerdi.'),
(98, 2, 30, 598, 'رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً', 'rasūlun mina llāhi yatlū ṣuḥufan muṭahharatan', 'Allah tarafından, tertemiz sahifeleri okuyan bir Resûl.'),
(98, 3, 30, 598, 'فِيهَا كُتُبٌ قَيِّمَةٌ', 'fīhā kutubun qayyimah', 'Onlarda dosdoğru (hükümler) bulunan yazılı kitaplar vardır.'),
(98, 4, 30, 598, 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', 'Ve mā teferraqa l-lezīne ūtū l-kitābe illā min baʿdi mā jāʾethumu l-bayyinah', 'Kendilerine apaçık delil (Kur''an) gelmesinden sonra, kitap ehli ayrılığa düştüler.'),
(98, 5, 30, 598, 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', 've mâ umirū illâ liyaʿbudūllâhe muḫliṣîne led-dîne ḥunefâʾe ve yuqīmūṣ-ṣalâte ve yuʾtūz-zekâte ve dhālika dīnul-qayyimeti', 'Halbu ki onlara, ancak dini Allah''a has kılarak, hakka yönelerek kulluk etmeleri, namazı dosdoğru kılmaları ve zekâtı vermeleri emredildi. İşte bu, dosdoğru dindir.'),
(98, 6, 30, 598, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 'ʾinna l-ladhīna kafarū min ʾahli l-kitābi wa-l-mušrikīna fī nāri jahannama khālidīna fīhā ʾulāʾika hum šarru l-barīyyah', 'Şüphesiz, Ehl-i kitaptan ve müşriklerden inkâr edenler, cehennem ateşindedirler; orada ebedî olarak kalırlar. İşte onlar, mahlûkatın en kötüsüdürler.'),
(98, 7, 30, 598, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 'ʾinna alladhīna ʾāmanū wa ʿamilū aṣ-ṣāliḥāti ʾulāʾika hum khayru l-barīyah', 'Şüphesiz iman edip salih amel işleyenler, işte onlar yaratılmışların en hayırlısıdır.'),
(98, 8, 30, 599, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 'jazāʾuhum ʿinda rabbihim jannātu ʿadnin tajrī min taḥtihā l-anhāru khālidīna fīhā abadan raḍiya llāhu ʿanhum wa raḍū ʿanhu dhālika liman khashiya rabbahū', 'Onların Rableri katındaki mükâfatları, altlarından ırmaklar akan, içinde ebediyen kalacakları Adn cennetleridir. Allah onlardan razı olmuş, onlar da Allah''tan razı olmuşlardır. İşte bu, Rabbinden (O''na duyulan) saygı korkusu taşıyan kimse içindir.'),
(99, 1, 30, 599, 'إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 'iḏā zulzilatil-arḍu zilzālahā', 'Yeryüzü o sarsıntısıyla sarsıldığı zaman,'),
(99, 2, 30, 599, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 'wa-akhrajati l-arḍu athqālahā', 'Ve yeryüzü ağırlıklarını çıkardığında.'),
(99, 3, 30, 599, 'وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا', 'waqāla l-insānu mā lahā', 'İnsan: "Bu ne oluyor?" der.'),
(99, 4, 30, 599, 'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا', 'yawmaʾiḏin tuḥaddiṯu ʾaxbārahā', 'O gün yer, kendi haberlerini anlatır.'),
(99, 5, 30, 599, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 'biʾanna rabbaka ʾawḥā lahā', 'Rabbin ona (vahiy ile) bildirmesiyle.'),
(99, 6, 30, 599, 'يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَٰلَهُمْ', 'yawmaʾiḏin yaṣduru ʾn-nāsu ʾaštātan liyuraw ʾaʿmālahum', 'O gün insanlar, amellerinin kendilerine gösterilmesi için bölük bölük (dağınık) olarak ortaya çıkarlar.'),
(99, 7, 30, 599, 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ', 'fe-men yaʿmal mithqāla dharratin khayran yarahū', 'Kim zerre kadar hayır işlerse onu görür.'),
(99, 8, 30, 599, 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ', 'wa man yaʿmal mithqāla dharratin sharran yarahu', 'Kim zerre kadar hayır işlerse onu görür.'),
(100, 1, 30, 599, 'وَٱلْعَٰدِيَٰتِ ضَبْحًا', 'wa-l-ʿādiyāti ḍabḥan', 'Savaşta (koşarken) soluk soluğa koşanlara yemin ederim.'),
(100, 2, 30, 599, 'فَٱلْمُورِيَٰتِ قَدْحًا', 'fa-l-mūriyāti qadḥan', 'Ateş çıkaranlara, kıvılcımlar saçanlara yemin ederim ki,'),
(100, 3, 30, 599, 'فَٱلْمُغِيرَٰتِ صُبْحًا', 'fa-l-mughīrāti ṣubḥan', 'Sabahleyin akın edenlere yemin ederim.'),
(100, 4, 30, 599, 'فَأَثَرْنَ بِهِۦ نَقْعًا', 'fa-ʾaṯarna bihi naqʿan', 'Böylece onunla toz ve toprağı birbirine katarlar.'),
(100, 5, 30, 599, 'فَوَسَطْنَ بِهِۦ جَمْعًا', 'fa-wasatna bihi jamʿan', 'Böylece onların ortasına dalmışlardı.'),
(100, 6, 30, 599, 'إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌ', 'inna al-insāna li-rabbihī la-kanūd', 'Şüphesiz insan, Rabbine karşı pek nankördür.'),
(100, 7, 30, 599, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ', 'wa-ʾinnahu ʿalā ḏālika lašahīd', 'Ve şüphesiz O, buna şahittir.'),
(100, 8, 30, 599, 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', 'waʾinnahu liḥubbi l-khayri lašadīd', 'Ve şüphesiz O, mal sevgisinde gerçekten çok ileri gitmiştir.'),
(100, 9, 30, 599, 'أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', 'ʾafalā yaʿlamu ʾidhā buʿthira mā fī l-qubūri', 'Mezarlardakiler (diriltilip) ortaya çıkarıldığında, artık o (insan) bilmeyecek mi?'),
(100, 10, 30, 600, 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', 'waḥuṣṣila mā fī ṣ-ṣudūri', 'Ve göğüslerde olanlar ortaya çıkarıldı.'),
(100, 11, 30, 600, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ', 'inna rabbahum bihim yawma''idhin lakhabirun', 'Şüphesiz Rableri o gün onlardan haberdardır.'),
(101, 1, 30, 600, 'ٱلْقَارِعَةُ', 'al-qāriʿah', 'Karia (kapı çalan, felaket)'),
(101, 2, 30, 600, 'مَا ٱلْقَارِعَةُ', 'Mā l-qāriʿah', 'Karia nedir?'),
(101, 3, 30, 600, 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', 'wa mā ʾadrāka mā l-qāriʿah', 'Kıyamet''in ne olduğunu sana ne bildirdi?'),
(101, 4, 30, 600, 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', 'yawma yakūnu n-nāsu kal-farāshi l-mabthūth', 'O gün insanlar, (her biri) yayılmış küçük birer kelebek gibi olur.'),
(101, 5, 30, 600, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 'wa takūnu l-jibālu ka-l-ʿihni l-manfūsh', 'Ve dağlar atılmış renkli yünler gibi olur.'),
(101, 6, 30, 600, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 'faʾammā man thaqulat mawāzīnuhū', 'Artık kimin tartıları ağır gelirse,'),
(101, 7, 30, 600, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 'fa-huwa fī ʿīshatin rāḍiyah', 'İşte o, razı olacağı bir hayat içindedir.'),
(101, 8, 30, 600, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 'waʾammā man khaffat mawāzīnuhū', 'Kıyamet Suresi 8. Ayet: Ve kimin tartıları hafif gelirse'),
(101, 9, 30, 600, 'فَأُمُّهُۥ هَاوِيَةٌ', 'faʾummuhu hāwiyah', 'Onun anası Hâviye''dir.'),
(101, 10, 30, 600, 'وَمَآ أَدْرَىٰكَ مَا هِيَهْ', 'wa mā adrāka mā hiyah', 'Ve seni ne bilgilendirir, nedir o?'),
(101, 11, 30, 600, 'نَارٌ حَامِيَةٌۢ', 'nārun ḥāmiyatun', 'O, (içine girip) kor olası bir ateştir.'),
(102, 1, 30, 600, 'أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', 'alhakumu t-takathur', 'Çoklukla övünmek, sizi oyaladı.'),
(102, 2, 30, 600, 'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ', 'ḥattā zurtumu l-maqābir', 'Nihayet siz (bu böbürlenmenizle) kabirleri ziyaret edinceye kadar.'),
(102, 3, 30, 600, 'كَلَّا سَوْفَ تَعْلَمُونَ', 'kallā sawfa taʿlamūn', 'Hayır, ileride bilecek-siniz!'),
(102, 4, 30, 600, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', 'thumma kallā sawfa taʿlamūn', 'Hayır! Yakında (gerçeği) bileceksiniz.'),
(102, 5, 30, 600, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ', 'kallā law taʿlamūna ʿilma l-yaqīn', 'Hayır! Keşke siz (şimdiyi) yakîni bir bilgiyle bilseydiniz!'),
(102, 6, 30, 600, 'لَتَرَوُنَّ ٱلْجَحِيمَ', 'Leteravunne el-cahîme', 'Andolsun, cehennemi mutlaka göreceksiniz.'),
(102, 7, 30, 600, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ', 'thumma latarawunnahā ʿayna l-yaqīn', 'Sonra, o gün, onu mutlaka gözünüzle göreceksiniz.'),
(102, 8, 30, 600, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', 'thumma latus''alunna yawma''idhin ''ani n-na''iim', 'Sonra o gün, nimetlerden elbette hesaba çekileceksiniz.'),
(103, 1, 30, 601, 'وَٱلْعَصْرِ', 'wa-l-ʿaṣri', 'Asr''a yemin olsun.'),
(103, 2, 30, 601, 'إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ', 'ʾinna l-ʾinsāna lafī khusr', 'Gerçekten insan ziyandadır.'),
(103, 3, 30, 601, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ', 'illa alladhīna ʾāmanū wa ʿamilū aṣ-ṣāliḥāti wa tawāṣaw bi-l-ḥaqqi wa tawāṣaw bi-ṣ-ṣabri', 'Ancak iman edip salih amel işleyenler, birbirlerine hakkı ve sabrı tavsiye edenler bunun dışındadır.'),
(104, 1, 30, 601, 'وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ', 'waylun likulli humazatin lumazatin', 'Arkadan çekiştirip duran, (herkesi) ayıplayıp alay edenlerin vay haline!'),
(104, 2, 30, 601, 'ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ', 'alladhī jamaʿa mālān wa ʿaddadahū', 'O, mal toplayıp onu sayan.'),
(104, 3, 30, 601, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 'yaḥsabu anna mālāhu ʾakhladahū', 'Malının kendisini ebedi kılacağını sanır.'),
(104, 4, 30, 601, 'كَلَّا لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ', 'kallā layunbaḏanna fī l-ḥuṭamah', 'Hayır! Andolsun ki o, (değerini) hiçe sayıp alaya aldığı kimse, Hutame''ye (Cehennem''deki ateşe) atılacaktır.'),
(104, 5, 30, 601, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ', 've mâ edrâke mâl-ḥuṭamah', 'Oysa ne bildirdi sana o Hutame nedir?'),
(104, 6, 30, 601, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ', 'nāru llāhi l-mūqadatu', 'Allah''ın tutuşturduğu ateş.'),
(104, 7, 30, 601, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ', 'allatī taṭṭaliʿu ʿalā l-ʾafʾidati', 'O (ateş) kalplere işler.'),
(104, 8, 30, 601, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ', 'ʾinnahā ʿalayhim muʾṣadah', 'Şüphesiz o ateş onların üzerine kapatılmıştır.'),
(104, 9, 30, 601, 'فِى عَمَدٍ مُّمَدَّدَةٍۭ', 'fī ʿamadin mumaddadah', 'Onların üzerine (azap) uzatılmış bir sütun (olarak)dır.'),
(105, 1, 30, 601, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ', 'ʾa-lam tara kayfa faʿala rabbuka bi-ʾaṣḥābi l-fīl', 'Rabbin fil sahiplerine ne yaptığını görmedin mi?'),
(105, 2, 30, 601, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ', 'ʾelem yecʿal kaydahum fī ḍalīl', 'Onların tuzaklarını boşuna çıkarmadı mı?'),
(105, 3, 30, 601, 'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ', 'waʾarsala ʿalayhim ṭayran ʾabābīla', 'Ve onların üzerine sürüler halinde kuşlar gönderdi.'),
(105, 4, 30, 601, 'تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ', 'tarmīhim biḥijāratin min sijill', 'Onları, taşlarla atan bir rüzgarla gönderdik.'),
(105, 5, 30, 601, 'فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ', 'fa jaʿalahum ka ʿaṣfim maʾkūlin', 'Böylece onları, (ağızlarda) çiğnenmiş ekin yaprağı haline getirdi.'),
(106, 1, 30, 602, 'لِإِيلَٰفِ قُرَيْشٍ', 'li-ʾīlāfi quraishin', 'Kureyş''in (yaz ve kış seferleriyle) ülfetini (sağladığı için).'),
(106, 2, 30, 602, 'إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ', 'ʾilāfihim riḥlata sh-shitāʾi wa-ṣ-ṣayf', 'Onların kış ve yaz sefer(ler)ine (alıştırdığına).'),
(106, 3, 30, 602, 'فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ', 'falyaʿbudū rabb hādhā l-bayti', 'Şu halde, Kâbe''nin Rabbi''ne kulluk etsinler.'),
(106, 4, 30, 602, 'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ', 'alladhī ʾaṭʿamahum min jūʿin wa ʾāmanahum min khawfin', 'O, kendilerini açlıktan doyuran ve kendilerini korkudan emin kılan.'),
(107, 1, 30, 602, 'أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ', 'araʾayta lladhī yukadhdhību bid-dīn', 'Dini yalanlayanı gördün mü?'),
(107, 2, 30, 602, 'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ', 'faḏālika lladhī yadʿʿu l-yatīma', 'İşte bu, yetimi itip kakandır.'),
(107, 3, 30, 602, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'wa lā yaḥuḍḍu ʿalā ṭaʿāmi l-miskīn', 'Ve yoksulu doyurmaya teşvik etmez.'),
(107, 4, 30, 602, 'فَوَيْلٌ لِّلْمُصَلِّينَ', 'fa waylun lilmuṣallīn', 'Demek, namaz kılanların vay haline!'),
(107, 5, 30, 602, 'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 'allaḏīna hum ʿan ṣalātihim sāhūn', 'Onlar ki, namazlarından gafildirler.'),
(107, 6, 30, 602, 'ٱلَّذِينَ هُمْ يُرَآءُونَ', 'alladhīna hum yurāʾūna', 'Onlar ki, gösteriş yaparlar.'),
(107, 7, 30, 602, 'وَيَمْنَعُونَ ٱلْمَاعُونَ', 'wa yamnaʿūna l-māʿūn', 'Ve onlar, yardımlaşmayı (iyiliği) engellerler.'),
(108, 1, 30, 602, 'إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ', 'ʾinnā ʾaʿṭaynāka l-kawṯara', 'Şüphesiz biz sana Kevser''i verdik.'),
(108, 2, 30, 602, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', 'faṣalli lirabbika wanḥar', 'Bunun için Rabbine namaz kıl, kurban kes.'),
(108, 3, 30, 602, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', 'ʾinna shāʾniʾaka huwa l-ʾabtaru', 'Şüphesiz sana buğzeden (veya senin soyunun devam etmeyeceğini söyleyen) kimse, soyu kesik olanın ta kendisidir.'),
(109, 1, 30, 603, 'قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ', 'Qul yāʾayyuha l-kāfirūn', 'De ki: "Ey kâfirler!"'),
(109, 2, 30, 603, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 'lā ʾaʿbudu mā taʿbudūn', 'Siz tapmakta olduğunuz şeylere ben tapmam.'),
(109, 3, 30, 603, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ', 'wa lā ʾantum ʿābidūna mā ʾaʿbudu', 'Siz de benim taptığıma tapacak değilsiniz.'),
(109, 4, 30, 603, 'وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ', 'wa lā ʾanā ʿābidum mā ʿabadtum', 'Sizin taptıklarınıza tapacak değilim.'),
(109, 5, 30, 603, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ', 'wa lā ʾantum ʿābidūna mā ʾaʿbudu', 'Siz de benim taptığıma tapacak değilsiniz.'),
(109, 6, 30, 603, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', 'lakum dīnukum wa liya dīni', 'Sizin dininiz size, benim dinim banadır.'),
(110, 1, 30, 603, 'إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', 'iḏā ǧāʾa naṣru ʾllāhi wa-l-fatḥu', 'Allah''ın yardımı ve zafer (fetih) geldiği zaman,'),
(110, 2, 30, 603, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا', 'wa raʾayta n-nāsa yadkhulūna fī dīni llāhi ʾafwājan', 'Ve insanları Allah''ın dinine bölük bölük girerken gördün.'),
(110, 3, 30, 603, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ إِنَّهُۥ كَانَ تَوَّابًۢا', 'fasabbih biḥamdi rabbika wastaghfirhu ʾinnahu kāna tawwāban', 'Rabbini hamd ile tesbih et ve O''ndan mağfiret dile. Şüphesiz O, tevbeleri kabul edendir.'),
(111, 1, 30, 603, 'تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ', 'tabbat yadā abī lahabin wa tabb', 'Ebu Leheb''in elleri kurudu! Kurudu da!'),
(111, 2, 30, 603, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', 'Mā aġnā ʿanhu māluhū wa mā kasab', 'Malı ona hiçbir fayda sağlamadı ve kazandığı da.'),
(111, 3, 30, 603, 'سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ', 'Sayasla narān dhāta lahabin', 'Alevli bir ateşe girecektir.'),
(111, 4, 30, 603, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', 'wa-mraʾatuhu ḥammālata l-ḥaṭab', 'Ve onun karısı da, odun taşıyıcı (olan da)'),
(111, 5, 30, 603, 'فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ', 'fī jīdihā ḥablun min masad', 'Onun boynunda bükülmüş bir ip vardır.'),
(112, 1, 30, 604, 'قُلْ هُوَ ٱللَّهُ أَحَدٌ', 'Qul huwa Allāhu Aḥad', 'De ki: O, Allah''tır; birdir.'),
(112, 2, 30, 604, 'ٱللَّهُ ٱلصَّمَدُ', 'Allāhuṣ-ṣamad', 'Allah Samed''dir.'),
(112, 3, 30, 604, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 'lem yelid ve lem yūlad', 'O, doğurmadı ve doğurulmadı.'),
(112, 4, 30, 604, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 'wa lam yakul lahu kufuwan ahadun', 'Ve O''na hiçbir denk de yoktur.'),
(113, 1, 30, 604, 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 'qul ʾaʿūḏu birabbi l-falaq', 'De ki: "Ben, ağartmakta olan Felek''in Rabbine sığınırım."'),
(113, 2, 30, 604, 'مِن شَرِّ مَا خَلَقَ', 'min şerri mā halaq', 'Yarattığı şeylerin kötülüğünden.'),
(113, 3, 30, 604, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 've min şerri ġāsıqin iẕā vaḳab', 'Karanlığı çöktürmeye başladığı zaman gecenin şerrinden de.'),
(113, 4, 30, 604, 'وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ', 'wa min sharri an-naffāthāti fī al-ʿuqadi', 'Ve düğümlere üfleyenlerin şerrinden.'),
(113, 5, 30, 604, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'wa min sharri ḥāsidin ʾidhā ḥasada', 'Ve hasedici olduğu zaman hasedicinin şerrinden.'),
(114, 1, 30, 604, 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 'qul ʾaʿūḏu birabbi n-nāsi', 'De ki: İnsanların Rabbine sığınırım.'),
(114, 2, 30, 604, 'مَلِكِ ٱلنَّاسِ', 'maliki n-nās', 'İnsanların Meliki.'),
(114, 3, 30, 604, 'إِلَٰهِ ٱلنَّاسِ', 'ilāhi n-nāsi', 'İnsanların ilahı'),
(114, 4, 30, 604, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 'min sharri l-waswāsi l-khannāsi', 'O sinsi vesvesecinin şerrinden.'),
(114, 5, 30, 604, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 'alladhī yuwaswisu fī ṣudūri n-nās', 'O, insanların göğüslerine vesvese veren.'),
(114, 6, 30, 604, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 'mina l-jinnati wa-n-nāsi', 'Cinlerden ve insanlardan.')
